def color_graph(adj: list[list[int]]) -> list[int]:
    # Mock candidate: simple greedy first-fit
    n = len(adj)
    colors = [-1] * n
    for v in range(n):
        used = {colors[u] for u in adj[v] if colors[u] >= 0}
        c = 0
        while c in used:
            c += 1
        colors[v] = c
    return colors

