def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Vertex graph coloring using a greedy Welsh‑Powell ordering followed by
    iterative elimination of the highest colour class via direct reassignment
    and bounded Kempe‑chain swaps.
    Returns a list of colours (0‑based) for each vertex.
    """
    # ---------- 0. Trivial cases ----------
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

