        for row in adj:
            if len(row) != n:
                all_bin = False
                break
            for val in row:
                if val not in (0, 1):
                    all_bin = False
                    break
            if not all_bin:
                break
        if all_bin:
            is_matrix = True

    # ---------- 2. Build neighbour sets ----------
    if is_matrix:
        neigh = [set(j for j, v in enumerate(row) if v) for row in adj]
    else:
        # adjacency list (may contain duplicates; we make a set)
        neigh = [set(lst) for lst in adj]

    # ---------- 3. Initial greedy colouring (Welsh‑Powell) ----------
    degree = [len(nei) for nei in neigh]
    order = sorted(range(n), key=lambda v: (-degree[v], v))  # descending degree
    colour = [-1] * n
    for v in order:
        used = {colour[u] for u in neigh[v] if colour[u] != -1}
        c = 0
        while c in used:
            c += 1
        colour[v] = c

    # ---------- 4. Helper: try to eliminate highest colour ----------
    def eliminate_highest(colour):
        """Attempt to reduce the number of colours by recolouring the
        current highest colour class. Returns True if a change was made."""
        maxc = max(colour)
        if maxc < 0:
            return False

        # vertices currently having the highest colour
        high_vertices = [v for v, c in enumerate(colour) if c == maxc]
        random.shuffle(high_vertices)  # random tie‑break helps escape local minima

        for v in high_vertices:
            # ----- direct reassignment to a lower colour -----
            neighbour_cols = {colour[u] for u in neigh[v]}
            for c in range(maxc):          # only lower colours
                if c not in neighbour_cols:
                    colour[v] = c
                    return True

            # ----- Kempe‑chain swaps (a = maxc, b = lower colour) -----
            a = colour[v]
            for b in range(maxc):
                # BFS/DFS to get the (a,b)-Kempe component containing v
                stack = [v]
                comp = set()
                while stack:
                    x = stack.pop()
                    if x in comp:
                        continue
                    comp.add(x)
                    for y in neigh[x]:
                        if colour[y] == a or colour[y] == b and y not in comp:
                            stack.append(y)

                # Check whether swapping a<->b in this component would cause a conflict
                conflict = False
                for y in neigh[v]:
                    if colour[y] == b and y in comp:
                        conflict = True
                        break
                if not conflict:
                    # perform the swap
                    for x in comp:
                        if colour[x] == a:
                            colour[x] = b
                        elif colour[x] == b:
                            colour[x] = a
                    return True
        return False

    # ---------- 5. Iteratively try to drop colours ----------
    # Limit iterations to avoid infinite loops; each successful drop reduces max colour.
    while eliminate_highest(colour):
        pass

    # ---------- 6. Ensure colours are dense 0..k-1 (they already are) ----------
    # No further action needed.

    return colour

