def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build neighbor bitmasks and adjacency list
    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)
                neighbors[i].append(j)

    # Helper to compute degree in a subgraph defined by a bitmask
    def degree_in_subgraph(v: int, mask: int) -> int:
        return (bit_adj[v] & mask).bit_count()

    # Helper to compute saturation degree of v given current colors
    def saturation_degree(v: int, colors: list[int]) -> int:
        mask = 0
        for u in neighbors[v]:
            if colors[u] != -1:
                mask |= (1 << colors[u])
        return mask.bit_count()

    # Helper to check if coloring is valid
    def is_valid_coloring(colors: list[int]) -> bool:
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper to compact colors to 0..k-1
    def compact_colors(colors: list[int]) -> list[int]:
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR algorithm
    def dsatur() -> list[int]:
        colors = [-1] * n
        # Order by degree descending for initial tie-breaking
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        for _ in range(n):
            # Select uncolored vertex with max saturation degree
            max_sat = -1
            candidates = []
            for v in order:
                if colors[v] == -1:
                    sat = saturation_degree(v, colors)
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
            # Tie-break by degree in uncolored subgraph
            uncolored_mask = 0
            for v in range(n):
                if colors[v] == -1:
                    uncolored_mask |= (1 << v)
            best_v = -1
            max_deg = -1
            for v in candidates:
                deg = degree_in_subgraph(v, uncolored_mask)
                if deg > max_deg:
                    max_deg = deg
                    best_v = v
                elif deg == max_deg and v < best_v:
                    best_v = v
            # Assign smallest available color
            used = 0
            for u in neighbors[best_v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[best_v] = c
        return compact_colors(colors)

    # RLF algorithm
    def rlf() -> list[int]:
        colors = [-1] * n
        uncolored_mask = (1 << n) - 1
        color = 0
        while uncolored_mask:
            # Build independent set for this color
            S_mask = 0
            # Choose vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            temp_mask = uncolored_mask
            while temp_mask:
                u = (temp_mask & -temp_mask).bit_length() - 1
                deg = degree_in_subgraph(u, uncolored_mask)
                if deg > max_deg:
                    max_deg = deg
                    v = u
                temp_mask &= temp_mask - 1
            if v == -1:
                break  # Should not happen
            S_mask |= (1 << v)
            # U: vertices not adjacent to S, W: vertices adjacent to S
            U_mask = uncolored_mask & ~S_mask & ~bit_adj[v]
            W_mask = uncolored_mask & bit_adj[v]
            while U_mask:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                temp = U_mask
                while temp:
                    u = (temp & -temp).bit_length() - 1
                    w_neighbors = degree_in_subgraph(u, W_mask)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break by min degree in G[U]
                        deg_u = degree_in_subgraph(u, U_mask)
                        deg_best = degree_in_subgraph(best_u, U_mask) if best_u != -1 else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                    temp &= temp - 1
                if best_u == -1:
                    break  # Should not happen
                S_mask |= (1 << best_u)
                # Move best_u from U to W, and move its neighbors in U to W
                U_mask &= ~(1 << best_u)
                newly_w = bit_adj[best_u] & U_mask
                W_mask |= newly_w
                U_mask &= ~newly_w
            # Assign color to all in S
            mask = S_mask
            while mask:
                u = (mask & -mask).bit_length() - 1
                colors[u] = color
                mask &= mask - 1
            uncolored_mask &= ~S_mask
            color += 1
        return compact_colors(colors)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last() -> list[int]:
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # We'll simulate removal
        while remaining:
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda x: degree[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    degree[u] -= 1
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def reduce_colors_kempe(colors: list[int]) -> list[int]:
        if not is_valid_coloring(colors):
            return colors  # Should not happen if input is valid
        k = max(colors) + 1 if colors else 0
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest down
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            verts = [i for i, c in enumerate(colors) if c == target_color]
            if not verts:
                continue
            made_progress = True
            while made_progress and verts:
                made_progress = False
                # Try to recolor each vertex in this class
                new_verts = []
                for v in verts:
                    if colors[v] != target_color:  # Might have been recolored
                        continue
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in neighbors[v]:
                        if colors[u] != -1:
                            used |= (1 << colors[u])
                    found = False
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            colors[v] = c
                            found = True
                            made_progress = True
                            break
                    if found:
                        continue
                    # Try Kempe chain swap with each lower color
                    for c in range(target_color):
                        # Check if v can be swapped via (target_color, c) Kempe chain
                        # We'll do BFS to find the component of v in the subgraph of colors {target_color, c}
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for u in neighbors[node]:
                                if not visited[u] and (colors[u] == target_color or colors[u] == c):
                                    visited[u] = True
                                    queue.append(u)
                        # Check if any neighbor of the component has color c (would cause conflict if swapped)
                        has_conflict = False
                        for node in component:
                            for u in neighbors[node]:
                                if colors[u] == c and u not in component:
                                    has_conflict = True
                                    break
                            if has_conflict:
                                break
                        if not has_conflict:
                            # Perform swap: target_color <-> c in component
                            for node in component:
                                if colors[node] == target_color:
                                    colors[node] = c
                                else:
                                    colors[node] = target_color
                            made_progress = True
                            break  # Break color loop after successful swap
                    if colors[v] == target_color:
                        new_verts.append(v)
                verts = new_verts
            # After trying to recolor, check if target_color is still used
            if any(c == target_color for c in colors):
                # Cannot eliminate this color, break as higher colors are harder to eliminate
                break
        return compact_colors(colors)

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        colors = [-1] * n
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(compact_colors(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: max(x) + 1 if x else 0)
    # Apply Kempe reduction to try to improve
    best = reduce_colors_kempe(best)
    # Final validation (should be valid)
    if not is_valid_coloring(best):
        # Ultimate fallback: greedy
        colors = [-1] * n
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best = compact_colors(colors)
    return best

