def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build neighbor list and bitmask adjacency
    neighbors = []
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            nbrs = []
            mask = 0
            for v in range(n):
                if adj[u][v]:
                    nbrs.append(v)
                    mask |= (1 << v)
            neighbors.append(nbrs)
            bit_adj[u] = mask
    else:
        for u in range(n):
            nbrs = adj[u]
            mask = 0
            for v in nbrs:
                mask |= (1 << v)
            neighbors.append(nbrs)
            bit_adj[u] = mask

    # Helper: compute number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            cu = colors[u]
            for v in neighbors[u]:
                if cu == colors[v]:
                    return False
        return True

    # Helper: greedy coloring given an order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = colors[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[u]) for u in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, then max uncolored degree, then min index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u].bit_count()
                deg_u = uncolored_deg[u]
                if sat_u > max_sat or (sat_u == max_sat and (deg_u > max_deg or (deg_u == max_deg and u < v))):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return colors

    # RLF: Recursive Largest First (maximal independent set extraction)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # induced subgraph degrees
            deg = {}
            for u in uncolored:
                cnt = 0
                for v in neighbors[u]:
                    if v in uncolored:
                        cnt += 1
                deg[u] = cnt
            # pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to S
            U = {u for u in uncolored if all(u not in neighbors[w] for w in S)}
            # W: vertices adjacent to S
            W = uncolored - U
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = None
                for u in U:
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # tie-break: min degree in G[U]
                    deg_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and (deg_U < best_deg_U or best_deg_U is None)):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for u in S:
                colors[u] = color
            color += 1
            uncolored = W  # next iteration
        return colors

    # Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # core decomposition to get removal order
        degree = [len(neighbors[u]) for u in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]  # degree buckets
        for u in range(n):
            d = degree[u]
            if d < n:
                buckets[d].append(u)
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr < n and not buckets[ptr]:
                ptr += 1
            if ptr >= n:
                break  # should not happen
            u = buckets[ptr].pop()
            while removed[u]:
                if not buckets[ptr]:
                    while ptr < n and not buckets[ptr]:
                        ptr += 1
                    if ptr >= n:
                        break
                    u = buckets[ptr].pop()
                else:
                    u = buckets[ptr].pop()
            removed[u] = True
            order.append(u)
            for v in neighbors[u]:
                if not removed[v]:
                    d = degree[v]
                    if d > 0:
                        degree[v] -= 1
                        buckets[d].remove(v)
                        buckets[d-1].append(v)
        # color in reverse removal order
        return greedy_color(order[::-1])

    # Kempe chain swap for colors a and b, starting from vertex v, returns new coloring if swap performed
    def kempe_swap(colors, v, a, b):
        if colors[v] not in (a, b):
            return colors  # should not happen
        # BFS to get the Kempe chain component
        from collections import deque
        comp = set()
        q = deque([v])
        comp.add(v)
        while q:
            u = q.popleft()
            for w in neighbors[u]:
                if w not in comp and colors[w] in (a, b):
                    comp.add(w)
                    q.append(w)
        # create new coloring by swapping a<->b in comp
        new_colors = colors[:]
        for u in comp:
            if new_colors[u] == a:
                new_colors[u] = b
            elif new_colors[u] == b:
                new_colors[u] = a
        return new_colors

    # Try to eliminate the last color via Kempe chains or reassignment
    def reduce_colors(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # try to eliminate color k-1
        target = k - 1
        vertices = [u for u in range(n) if colors[u] == target]
        # try direct reassignment first
        for v in vertices:
            used = 0
            for u in neighbors[v]:
                c = colors[u]
                if c != -1 and c < target:  # only consider colors < target
                    used |= (1 << c)
            for c in range(target):
                if not (used & (1 << c)):
                    # move v to color c
                    new_colors = colors[:]
                    new_colors[v] = c
                    # after moving, check if target color is still used
                    if target not in new_colors:
                        # renumber colors to be consecutive
                        mapping = {}
                        next_c = 0
                        for col in sorted(set(new_colors)):
                            mapping[col] = next_c
                            next_c += 1
                        final_colors = [mapping[c] for c in new_colors]
                        return final_colors
        # try Kempe chains: for each v in target color, for each c < target, try swap
        for v in vertices:
            for c in range(target):
                # try to swap colors target and c in the component containing v
                swapped = kempe_swap(colors, v, target, c)
                # after swap, check if v is now color c (meaning it was in the swapped component)
                if swapped[v] == c:
                    # check if target color is still used anywhere
                    if target not in swapped:
                        mapping = {}
                        next_c = 0
                        for col in sorted(set(swapped)):
                            mapping[col] = next_c
                            next_c += 1
                        final_colors = [mapping[col] for col in swapped]
                        return final_colors
        # cannot reduce
        return colors

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: greedy by original order
    try:
        c4 = greedy_color(list(range(n)))
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass

    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        k = num_colors(col)
        if k < best_k:
            best_k = k
            best = col
    if best is None:
        best = [0] * n  # should not happen

    # Iteratively apply color reduction
    current = best
    while True:
        reduced = reduce_colors(current)
        if num_colors(reduced) >= num_colors(current):
            break
        current = reduced

    # Ensure colors are consecutive starting from 0
    used_colors = sorted(set(current))
    mapping = {col: i for i, col in enumerate(used_colors)}
    final = [mapping[c] for c in current]
    return final

