    for i in range(n):
        c = best_color[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_color[i] = unique_colors[c]

    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for i in range(n):
            for j in range(n):
                val = adj[i][j]
                if val != 0 and val != 1:
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build adjacency list and bit masks
    if is_matrix:
        adj_list = []
        bit_adj = [0] * n
        for i in range(n):
            neighbors = []
            mask = 0
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
                    mask |= (1 << j)
            adj_list.append(neighbors)
            bit_adj[i] = mask
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for nb in adj_list[i]:
                mask |= (1 << nb)
            bit_adj[i] = mask

    # Helper: count bits in mask
    def popcount(x: int) -> int:
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(colors: list[int]) -> bool:
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors: list[int]) -> int:
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: greedy coloring with given order
    def greedy_color(order: list[int]) -> list[int]:
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Heuristic 1: DSATUR with bitmask optimization
    def dsatur() -> list[int]:
        colors = [-1] * n
        # saturation mask per vertex: bits of colors used by colored neighbors
        sat_mask = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation degree, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = popcount(sat_mask[v])
                # degree in uncolored subgraph
                deg = popcount(bit_adj[v] & sum((1 << u) for u in uncolored))
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # assign smallest available color
            used = sat_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update saturation masks of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat_mask[u] |= (1 << c)
        return colors

    # Heuristic 2: RLF (Recursive Largest First) independent set extraction
    def rlf() -> list[int]:
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: popcount(bit_adj[x] & sum((1 << u) for u in uncolored)))
            S.add(v)
            # partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any((bit_adj[u] & (1 << w)) for w in S):
                    U.remove(u)
                    W.add(u)
            # greedily add to S from U
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = popcount(bit_adj[u] & sum((1 << w) for w in W))
                    degU = popcount(bit_adj[u] & sum((1 << w) for w in U))
                    if score > best_score or (score == best_score and degU < best_degU):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in list(U):
                    if bit_adj[u] & (1 << w):
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                colors[v] = color
            uncolored -= S
            color += 1
        return colors

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [popcount(bit_adj[v]) for v in range(n)]
        # we need dynamic degrees in the induced subgraph
        # simple O(n^2) method: repeatedly remove min degree vertex
        temp_adj = [set(adj_list[v]) for v in range(n)]
        remaining_set = set(range(n))
        while remaining_set:
            # find vertex with min degree in remaining_set
            min_v = None
            min_deg = float('inf')
            for v in remaining_set:
                deg = len(temp_adj[v] & remaining_set)
                if deg < min_deg:
                    min_deg = deg
                    min_v = v
            order.append(min_v)
            remaining_set.remove(min_v)
            # remove min_v from neighbors' adjacency
            for u in temp_adj[min_v]:
                if u in remaining_set:
                    temp_adj[u].discard(min_v)
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except Exception:
        pass
    # Fallback: greedy by natural order
    try:
        c4 = greedy_color(list(range(n)))
        if is_valid_coloring(c4):
            candidates.append(c4)
    except Exception:
        pass

    if not candidates:
        # should not happen, but assign all zeros (invalid but safe)
        return [0] * n

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    best_k = num_colors(best)

    # Kempe chain color reduction
    def kempe_reduction(colors: list[int]) -> list[int]:
        nonlocal best_k
        changed = True
        while changed and best_k > 1:
            changed = False
            # identify color classes
            classes = [[] for _ in range(best_k)]
            for v in range(n):
                c = colors[v]
                if 0 <= c < best_k:
                    classes[c].append(v)
            # target the last color (best_k-1)
            target = best_k - 1
            if not classes[target]:
                # should not happen
                break
            # Try to recolor each vertex in target class
            for v in classes[target]:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    cu = colors[u]
                    if cu != -1:
                        used |= (1 << cu)
                for c in range(target):
                    if not (used & (1 << c)):
                        # move v to color c
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target):
                    # BFS to find the (v, c)-Kempe chain component containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y]:
                                cy = colors[y]
                                if cy == c or cy == target:
                                    visited[y] = True
                                    queue.append(y)
                    # Check if any neighbor of v in the component has color c? Actually, we need to see if swapping frees color c for v.
                    # After swap, v would get color c if it is in the component (which it is) and we swap c<->target.
                    # But we must ensure that no neighbor of v ends up with color c after swap (which would cause conflict).
                    # Actually, after swap, neighbors of v that are in the component and had color c will become target, and those with target become c.
                    # So if v has a neighbor u with color c that is in the component, after swap u becomes target, so v can become c without conflict.
                    # However, if v has a neighbor u with color c that is NOT in the component, then after swap u remains c, so v cannot become c.
                    # Therefore, we can move v to color c if and only if there is NO neighbor of v with color c that is outside the component.
                    # Equivalent: all neighbors of v with color c are in the component.
                    has_external_c = False
                    for u in adj_list[v]:
                        if colors[u] == c and not visited[u]:
                            has_external_c = True
                            break
                    if not has_external_c:
                        # perform swap: c <-> target in the component
                        for x in component:
                            if colors[x] == c:
                                colors[x] = target
                            elif colors[x] == target:
                                colors[x] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # compact colors: reindex to 0..new_k-1
                # but we know we removed one color class? Not necessarily, we might have moved vertices but target class may still be non-empty.
                # Instead, we attempt to eliminate the target color class entirely by repeating until empty.
                # For simplicity, we just try to reduce the number of colors by one if possible.
                # Recompute classes and see if target class is empty
                classes = [[] for _ in range(best_k)]
                for v in range(n):
                    c = colors[v]
                    if 0 <= c < best_k:
                        classes[c].append(v)
                if not classes[target]:
                    # successful elimination: compact colors
                    mapping = {}
                    new_color = 0
                    for old in range(best_k):
                        if classes[old]:
                            mapping[old] = new_color
                            new_color += 1
                    for v in range(n):
                        if colors[v] in mapping:
                            colors[v] = mapping[colors[v]]
                    best_k = new_color
                else:
                    # cannot eliminate this round, break to avoid infinite loop
                    break
        return colors

    # Apply Kempe reduction
    improved = kempe_reduction(best[:])
    if is_valid_coloring(improved):
        final_k = num_colors(improved)
        if final_k < best_k:
            best = improved
            best_k = final_k
    # Ensure colors are contiguous 0..best_k-1
    # (Kempe reduction should maintain this, but re-map to be safe)
    used_colors = set(best)
    mapping = {}
    new_color = 0
    for old in sorted(used_colors):
        mapping[old] = new_color
        new_color += 1
    final = [mapping[c] for c in best]
    return final

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True
    if is_matrix:
        neighbors = [ [j for j, val in enumerate(row) if val] for row in adj ]
    else:
        neighbors = adj
    # Convert to bit masks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: test if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # map existing colors to 0..k-1
        unique = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            coloring[i] = unique[c]
        return coloring

    # DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: list of sets of neighbor colors
        sat = [set() for _ in range(n)]
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[u]) for u in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = len(sat[v])
                d = uncolored_deg[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # find smallest color not used by neighbors
            used = sat[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and degrees for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u].add(c)
                    uncolored_deg[u] -= 1
        return compact_colors(color[:])

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # degree in uncolored subgraph
            deg = {}
            for v in uncolored:
                cnt = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        cnt += 1
                deg[v] = cnt
            # choose vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            while U:
                # select u in U with max neighbors in W
                best_u = -1
                best_score = -1
                best_degU = -1
                for u in U:
                    # score = |N(u) ∩ W|
                    score = 0
                    for w in W:
                        if (bit_adj[u] >> w) & 1:
                            score += 1
                    # degree in U
                    degU = 0
                    for w in U:
                        if u != w and (bit_adj[u] >> w) & 1:
                            degU += 1
                    if score > best_score or (score == best_score and degU < best_degU) or (score == best_score and degU == best_degU and random.random() < 0.5):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u in U to W
                for w in list(U):
                    if (bit_adj[u] >> w) & 1:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return compact_colors(color[:])

    # Smallest-Last ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        # copy of degrees
        deg = [len(neighbors[u]) for u in range(n)]
        # buckets for degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        pos = [0] * n
        for v in range(n):
            d = deg[v]
            buckets[d].append(v)
            pos[v] = len(buckets[d]) - 1
        # current min degree
        min_deg = 0
        order = []
        # we will remove vertices
        removed = [False] * n
        for _ in range(n):
            # find first non-empty bucket from min_deg upwards
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            pos[v] = -1  # mark removed
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = deg[u]
                    # remove u from bucket d
                    idx = pos[u]
                    last = buckets[d][-1]
                    buckets[d][idx] = last
                    pos[last] = idx
                    buckets[d].pop()
                    if not buckets[d]:
                        pass
                    deg[u] -= 1
                    d2 = deg[u]
                    buckets[d2].append(u)
                    pos[u] = len(buckets[d2]) - 1
                    if d2 < min_deg:
                        min_deg = d2
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return compact_colors(color[:])

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy we can modify
        color = coloring[:]
        # helper: get vertices of a color
        def color_class(c):
            return [v for v in range(n) if color[v] == c]
        # helper: check if moving v to color c is safe
        def can_move(v, c):
            for u in neighbors[v]:
                if color[u] == c:
                    return False
            return True
        # helper: Kempe chain (a,b) component containing v
        def kempe_component(v, a, b):
            if color[v] not in (a, b):
                return set()
            stack = [v]
            comp = set()
            while stack:
                u = stack.pop()
                if u in comp:
                    continue
                comp.add(u)
                for w in neighbors[u]:
                    if color[w] in (a, b) and w not in comp:
                        stack.append(w)
            return comp
        # main loop: try to eliminate color classes from highest down
        changed = True
        while changed:
            changed = False
            k = num_colors(color)
            # try to eliminate each color from k-1 down to 0
            for target in range(k-1, -1, -1):
                cls = color_class(target)
                if not cls:
                    continue
                # try to recolor each vertex in the class
                for v in cls:
                    # try direct move to a lower color
                    for c in range(target):
                        if can_move(v, c):
                            color[v] = c
                            changed = True
                            break
                    if color[v] != target:
                        # moved, break to restart scan
                        break
                    # try Kempe swaps
                    for c in range(target):
                        comp = kempe_component(v, target, c)
                        if not comp:
                            continue
                        # check if swapping frees color c for v
                        # after swap, v would get color c, so we need that no neighbor of v has color c after swap
                        # neighbors of v that are in comp will change from target to c or c to target
                        # we need that no neighbor of v has color c outside the comp (because inside comp they become target)
                        # Actually, we need that after swap, no neighbor of v has color c.
                        # For a neighbor u of v:
                        #   if u in comp: its color flips; if it was target -> becomes c, if it was c -> becomes target
                        #   if u not in comp: color unchanged
                        # So we need:
                        #   - no neighbor u of v with u not in comp and color[u] == c
                        #   - no neighbor u of v with u in comp and color[u] == target (because after swap becomes c)
                        conflict = False
                        for u in neighbors[v]:
                            if color[u] == c and u not in comp:
                                conflict = True
                                break
                            if color[u] == target and u in comp:
                                conflict = True
                                break
                        if not conflict:
                            # perform swap
                            for u in comp:
                                if color[u] == target:
                                    color[u] = c
                                else:
                                    color[u] = target
                            changed = True
                            break
                    if color[v] != target:
                        break
                if changed:
                    # after any change, break to restart from highest color
                    break
            # if we removed the highest color, compact
            if changed:
                # recompute k and compact if highest color class empty
                k = num_colors(color)
                if k > 0:
                    highest = k - 1
                    if not color_class(highest):
                        color = compact_colors(color)
        return color

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append(col_sl)
    except Exception:
        pass
    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        color = [0] * n
        for u in range(n):
            used = set()
            for v in neighbors[u]:
                if color[v] != -1:
                    used.add(color[v])
            c = 0
            while c in used:
                c += 1
            color[u] = c
        candidates.append(compact_colors(color))
    # Apply Kempe reduction to each candidate and pick best
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        try:
            col_reduced = kempe_reduce(col[:])
            if is_valid(col_reduced):
                k = num_colors(col_reduced)
                if k < best_k:
                    best_k = k
                    best_coloring = col_reduced
        except Exception:
            continue
    if best_coloring is None:
        best_coloring = candidates[0]
    return best_coloring

