                       (sat[u] == max_sat and degrees[u] == max_deg and random.random() < 0.5):
                        max_sat = sat[u]
                        max_deg = degrees[u]
                        v = u
            if v == -1:
                break  # should not happen

            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # update saturation and neighbor colors for neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:
                    # add color c to neighbor's neighbor colors if not present
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1

        return compact_colors(coloring)

    # RLF algorithm (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color = 0
        # set of uncolored vertices
        uncolored = set(range(n))

        while uncolored:
            # build maximal independent set for this color
            # start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # compute degrees in uncolored subgraph
            deg_in_uncolored = {}
            for u in uncolored:
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg_in_uncolored[u] = cnt
            # pick vertex with max degree
            v = max(uncolored, key=lambda x: deg_in_uncolored[x])
            independent_set = {v}
            # partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            for u in adj_list[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)

            # while U not empty, add vertex with max neighbors in W
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # tie-break by min degree in U
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and random.random() < 0.5):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break
                # add best_u to independent set
                independent_set.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in independent set
            for u in independent_set:
                coloring[u] = color
            color += 1
            # next round: uncolored becomes W (vertices adjacent to current independent set)
            uncolored = W

        return compact_colors(coloring)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # compute smallest-last ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # we'll simulate peeling
        temp_deg = degrees[:]
        # maintain list of vertices by degree? Since n<=100, we can scan
        for _ in range(n):
            # find vertex with min temp_deg in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if temp_deg[u] < min_deg:
                    min_deg = temp_deg[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # decrease temp_deg of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    temp_deg[u] -= 1
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return compact_colors(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy to work on
        current = coloring[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(current)
            if k <= 1:
                break
            # target the last color (k-1)
            target_color = k - 1
            # vertices with target color
            target_vertices = [i for i in range(n) if current[i] == target_color]
            if not target_vertices:
                # should not happen if k is correct
                break
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if current[u] != -1:
                        used_by_neighbors |= (1 << current[u])
                # find smallest color not used by neighbors
                c = 0
                while c < target_color and (used_by_neighbors & (1 << c)):
                    c += 1
                if c < target_color:
                    # can recolor directly
                    current[v] = c
                    changed = True
                    break  # restart after change
                else:
                    # try Kempe chains with each lower color
                    for c in range(target_color):
                        # if neighbor already has color c, swapping won't help (would cause conflict)
                        has_c_neighbor = False
                        for u in adj_list[v]:
                            if current[u] == c:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            continue
                        # build Kempe chain for colors (target_color, c) starting from v
                        # we want to see if we can swap in the component of v to free target_color
                        # Actually, we want to swap v's color (target_color) to c via Kempe chain
                        # Standard: consider subgraph induced by colors target_color and c
                        # Find connected component of v in that subgraph
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if current[node] == target_color or current[node] == c:
                                component.add(node)
                                for nb in adj_list[node]:
                                    if nb not in visited and (current[nb] == target_color or current[nb] == c):
                                        stack.append(nb)
                        # Check if any neighbor of v in the component has color c? 
                        # Actually, if we swap colors in the component, v will become c.
                        # We need to ensure that no neighbor of v (outside the component) has color c,
                        # because after swap, v becomes c and would conflict.
                        # But note: neighbors of v that are in the component and have color c will become target_color, so no conflict.
                        # The only potential conflict is with neighbors of v that are not in the component but have color c.
                        safe = True
                        for u in adj_list[v]:
                            if u not in component and current[u] == c:
                                safe = False
                                break
                        if safe:
                            # perform swap: target_color <-> c in the component
                            for node in component:
                                if current[node] == target_color:
                                    current[node] = c
                                else:  # must be c
                                    current[node] = target_color
                            changed = True
                            break  # break from color loop
                    if changed:
                        break  # break from vertex loop
            # if we didn't change anything in this iteration, try to see if we can eliminate the color class entirely
            # by checking if all target vertices can be recolored (but we already tried one by one)
            # If no change, break
        # compact colors after reduction
        return compact_colors(current)

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    # DSATUR
    c1 = dsatur()
    if is_valid_coloring(c1):
        k1 = num_colors(c1)
        if k1 < best_k:
            best_k = k1
            best_coloring = c1

    # RLF
    c2 = rlf()
    if is_valid_coloring(c2):
        k2 = num_colors(c2)
        if k2 < best_k:
            best_k = k2
            best_coloring = c2

    # Smallest-Last
    c3 = smallest_last()
    if is_valid_coloring(c3):
        k3 = num_colors(c3)
        if k3 < best_k:
            best_k = k3
            best_coloring = c3

    # Apply Kempe reduction to the best so far
    if best_coloring is not None:
        c4 = kempe_reduce(best_coloring[:])
        if is_valid_coloring(c4):
            k4 = num_colors(c4)
            if k4 < best_k:
                best_k = k4
                best_coloring = c4

    # Fallback: if somehow no coloring, use greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = compact_colors(coloring)

    # Final validation and compact
    if not is_valid_coloring(best_coloring):
        # as a last resort, use trivial coloring (each vertex unique)
        best_coloring = list(range(n))
    best_coloring = compact_colors(best_coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj
    # Build bitmask adjacency
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= 1 << v
        bit_adj[u] = mask
    # Helper: degree in induced subgraph
    def degree_in_set(u, set_mask):
        return (bit_adj[u] & set_mask).bit_count()
    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False
        return True
    # Helper: number of colors used
    def num_colors_used(colors):
        if not colors:
            return 0
        return max(colors) + 1
    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]
    # DSATUR
    def dsatur():
        colors = [-1] * n
        colored_mask = 0
        sat = [0] * n
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree in uncolored, then index
            v = -1
            max_sat = -1
            max_deg = -1
            uncolored_mask = ((1 << n) - 1) & ~colored_mask
            for u in range(n):
                if colors[u] == -1:
                    sat_u = (bit_adj[u] & colored_mask).bit_count()
                    deg_u = degree_in_set(u, uncolored_mask)
                    if sat_u > max_sat or (sat_u == max_sat and (deg_u > max_deg or (deg_u == max_deg and u > v))):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen
            # find smallest color not used by neighbors
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= 1 << colors[u]
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
            colored_mask |= 1 << v
            # update saturation of neighbors
            for u in adj_list[v]:
                if colors[u] == -1:
                    sat[u] += 1
        return compact_colors(colors)
    # RLF
    def rlf():
        colors = [-1] * n
        uncolored_mask = (1 << n) - 1
        color = 0
        while uncolored_mask:
            # independent set for this color
            S_mask = 0
            # choose vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            temp = uncolored_mask
            while temp:
                u = (temp & -temp).bit_length() - 1
                deg_u = degree_in_set(u, uncolored_mask)
                if deg_u > max_deg or (deg_u == max_deg and u > v):
                    max_deg = deg_u
                    v = u
                temp &= temp - 1
            if v == -1:
                break
            S_mask |= 1 << v
            # partition: U = uncolored and not adjacent to S, W = uncolored and adjacent to S
            U_mask = uncolored_mask & ~bit_adj[v]
            W_mask = uncolored_mask & bit_adj[v]
            # grow independent set
            while U_mask:
                # select u in U with max neighbors in W, tie-break by min degree in U, then index
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                temp = U_mask
                while temp:
                    u = (temp & -temp).bit_length() - 1
                    w_neighbors = degree_in_set(u, W_mask)
                    deg_u = degree_in_set(u, U_mask)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and (deg_u < min_deg_u or (deg_u == min_deg_u and u > best_u))):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                    temp &= temp - 1
                if best_u == -1:
                    break
                S_mask |= 1 << best_u
                # move best_u from U to S, and its neighbors in U to W
                U_mask &= ~(1 << best_u)
                neighbors_in_U = bit_adj[best_u] & U_mask
                U_mask &= ~neighbors_in_U
                W_mask |= neighbors_in_U
            # assign color to all in S
            temp = S_mask
            while temp:
                u = (temp & -temp).bit_length() - 1
                colors[u] = color
                temp &= temp - 1
            uncolored_mask &= ~S_mask
            color += 1
        return compact_colors(colors)
    # Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[u]) for u in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            u = buckets[ptr].pop()
            order.append(u)
            remaining.remove(u)
            for v in adj_list[u]:
                if v in remaining:
                    d = degree[v]
                    if d > 0:
                        buckets[d].remove(v)
                        degree[v] -= 1
                        buckets[degree[v]].append(v)
                        if degree[v] < ptr:
                            ptr = degree[v]
        # color in reverse order
        colors = [-1] * n
        for u in reversed(order):
            neighbor_colors = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    neighbor_colors |= 1 << colors[v]
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[u] = c
        return compact_colors(colors)
    # Kempe chain swap for colors a and b, returns new coloring if swap performed, else None
    def kempe_swap(colors, a, b):
        n_local = len(colors)
        visited = [False] * n_local
        for start in range(n_local):
            if colors[start] == a or colors[start] == b:
                if not visited[start]:
                    # BFS to get component
                    stack = [start]
                    visited[start] = True
                    component = []
                    has_a = False
                    has_b = False
                    while stack:
                        u = stack.pop()
                        component.append(u)
                        if colors[u] == a:
                            has_a = True
                        elif colors[u] == b:
                            has_b = True
                        for v in adj_list[u]:
                            if not visited[v] and (colors[v] == a or colors[v] == b):
                                visited[v] = True
                                stack.append(v)
                    # if component does not contain both colors, swapping is safe
                    if not (has_a and has_b):
                        new_colors = colors[:]
                        for u in component:
                            if new_colors[u] == a:
                                new_colors[u] = b
                            elif new_colors[u] == b:
                                new_colors[u] = a
                        return new_colors
        return None
    # Try to eliminate a color using Kempe chains
    def reduce_colors_kempe(colors):
        k = num_colors_used(colors)
        if k <= 1:
            return colors
        # try to eliminate highest color
        target_color = k - 1
        # get vertices with target color
        target_vertices = [u for u in range(n) if colors[u] == target_color]
        # try to recolor each target vertex
        for v in target_vertices:
            # try direct reassignment to a lower color
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= 1 << colors[u]
            for c in range(target_color):
                if not (neighbor_colors & (1 << c)):
                    # can recolor directly
                    colors[v] = c
                    break
            else:
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    new_colors = kempe_swap(colors, target_color, c)
                    if new_colors is not None:
                        # check if the swap removed the target color from v
                        if new_colors[v] != target_color:
                            colors = new_colors
                            break
                else:
                    continue
                break
        # compact and check if we reduced
        colors = compact_colors(colors)
        new_k = num_colors_used(colors)
        if new_k < k:
            # recurse
            return reduce_colors_kempe(colors)
        return colors
    # Run all heuristics
    best_colors = None
    best_k = float('inf')
    for heuristic in [dsatur, rlf, smallest_last]:
        try:
            cols = heuristic()
            if is_valid_coloring(cols):
                k = num_colors_used(cols)
                if k < best_k:
                    best_k = k
                    best_colors = cols
        except Exception:
            continue
    # fallback: greedy by degree order
    if best_colors is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for u in order:
            neighbor_colors = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    neighbor_colors |= 1 << colors[v]
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[u] = c
        best_colors = compact_colors(colors)
    # apply Kempe reduction
    best_colors = reduce_colors_kempe(best_colors)
    # final validation and compact
    if not is_valid_coloring(best_colors):
        # last resort: greedy
        order = list(range(n))
        colors = [-1] * n
        for u in order:
            neighbor_colors = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    neighbor_colors |= 1 << colors[v]
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[u] = c
        best_colors = compact_colors(colors)
    return best_colors

