import time

def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Colors a graph using a hybrid heuristic approach combining DSATUR, RLF, 
    and smallest-last ordering, followed by Kempe chain-based color reduction.
    Designed to run within 50ms for N <= 100.
    """
    start_time = time.time()

    # Helper to check time budget
    def time_up():
        return time.time() - start_time > 0.045  # Leave buffer for overhead

    # Handle trivial cases
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format and convert to adjacency list
    if len(adj) > 0 and len(adj[0]) == n and all(
        isinstance(x, int) and x in (0, 1) for row in adj for x in row
    ):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Adjacency list
        adj_list = adj
        # Ensure symmetry (undirected graph)
        for u in range(n):
            for v in adj_list[u]:
                if u not in adj_list[v]:
                    adj_list[v].append(u)

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize_colors(coloring):
        if not coloring:
            return coloring
        # Map used colors to 0..k-1
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        if time_up():
            return None
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor_colors[v] = bitmask of colors used by neighbors
        neighbor_colors = [0] * n

        # Degree for tie-breaking
        degrees = [len(adj_list[u]) for u in range(n)]

        # Select first vertex: max degree
        v = max(range(n), key=lambda u: degrees[u])
        coloring[v] = 0
        # Update neighbors
        for u in adj_list[v]:
            neighbor_colors[u] |= (1 << 0)
            saturation[u] = neighbor_colors[u].bit_count()

        colored_count = 1
        while colored_count < n:
            if time_up():
                return None
            # Find uncolored vertex with max saturation
            candidates = []
            max_sat = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat = saturation[u]
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [u]
                    elif sat == max_sat:
                        candidates.append(u)

            if not candidates:
                break  # Should not happen

            # Tie-break: max degree in uncolored subgraph
            def uncolored_degree(u):
                return sum(1 for v in adj_list[u] if coloring[v] == -1)

            v = max(candidates, key=lambda u: (uncolored_degree(u), degrees[u], -u))

            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # Update neighbors
            for u in adj_list[v]:
                if not (neighbor_colors[u] & (1 << c)):
                    neighbor_colors[u] |= (1 << c)
                    saturation[u] = neighbor_colors[u].bit_count()

            colored_count += 1

        return normalize_colors(coloring)

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        if time_up():
            return None
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            if time_up():
                return None
            # Build independent set for this color
            S = []
            # Step 1: pick vertex with max degree in G[uncolored]
            def deg_in_uncolored(u):
                return sum(1 for v in adj_list[u] if v in uncolored)

            v = max(uncolored, key=deg_in_uncolored)
            S.append(v)
            uncolored.remove(v)

            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if all((u not in adj_list[s]) for s in S)}
            W = uncolored - U

            while U:
                if time_up():
                    return None
                # Select u in U with max |N(u) ∩ W|
                def weight(u):
                    return sum(1 for v in adj_list[u] if v in W)

                # Tie-break: min degree in G[U]
                def deg_in_U(u):
                    return sum(1 for v in adj_list[u] if v in U)

                u = max(U, key=lambda x: (weight(x), -deg_in_U(x), -x))
                S.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_in_U = {v for v in adj_list[u] if v in U}
                U -= nbrs_in_U
                W |= nbrs_in_U

            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1

        return normalize_colors(coloring)

    # Strategy 3: Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        if time_up():
            return None
        # Peeling order: remove min degree vertex repeatedly
        remaining = set(range(n))
        degree = [len(adj_list[u]) for u in range(n)]
        order = []  # will be peeled order (min degree first)

        # Current degrees in remaining graph
        curr_degree = degree[:]
        # For efficiency, we'll recompute when needed (n <= 100)

        while remaining:
            if time_up():
                return None
            # Find vertex with minimum current degree
            v = min(remaining, key=lambda u: (curr_degree[u], u))
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    curr_degree[u] -= 1

        # Color in reverse order (last peeled first)
        coloring = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by colored neighbors
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return normalize_colors(coloring)

    # Run all strategies and pick best
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last)
    ]

    best_coloring = None
    best_k = float('inf')

    for name, strategy in strategies:
        if time_up():
            break
        coloring = strategy()
        if coloring is None:
            continue
        if not is_valid_coloring(coloring):
            continue
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring

    # Fallback: greedy by degree if all failed
    if best_coloring is None:
        # Simple greedy: order by degree descending
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize_colors(coloring)
        if not is_valid_coloring(best_coloring):
            # Last resort: assign each vertex unique color
            best_coloring = list(range(n))

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        if time_up():
            return coloring
        # Make a copy to work on
        current = coloring[:]
        k = num_colors(current)

        # Try to eliminate color classes from highest downward
        for target_color in range(k-1, 0, -1):
            if time_up():
                break
            # Get vertices with target_color
            verts = [v for v in range(n) if current[v] == target_color]
            if not verts:
                continue  # already eliminated

            eliminated = True
            new_coloring = current[:]  # work on copy

            for v in verts:
                if time_up():
                    break
                # Try to recolor v to a lower color
                # First, try direct reassignment
                neighbor_colors = 0
                for u in adj_list[v]:
                    if new_coloring[u] != -1:
                        neighbor_colors |= (1 << new_coloring[u])

                found = False
                for c in range(target_color):  # only try colors < target_color
                    if not (neighbor_colors & (1 << c)):
                        new_coloring[v] = c
                        found = True
                        break

                if found:
                    continue

                # Try Kempe chains with each lower color
                kempe_found = False
                for c in range(target_color):
                    if time_up():
                        break
                    # Skip if v already has color c (shouldn't happen)
                    if new_coloring[v] == c:
                        continue

                    # Find the Kempe chain component containing v for colors (target_color, c)
                    # We'll do BFS/DFS on the subgraph induced by vertices with color target_color or c
                    from collections import deque
                    visited = [False] * n
                    component = []
                    queue = deque([v])
                    visited[v] = True

                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and new_coloring[nb] in (target_color, c):
                                visited[nb] = True
                                queue.append(nb)

                    # Check if swapping this component is safe:
                    # After swap, no neighbor of any node in component should have the new color
                    # For nodes currently target_color -> become c: check no neighbor has c
                    # For nodes currently c -> become target_color: check no neighbor has target_color
                    safe = True
                    for node in component:
                        col = new_coloring[node]
                        new_col = target_color if col == c else c
                        for nb in adj_list[node]:
                            nb_col = new_coloring[nb]
                            if nb_col == new_col:
                                safe = False
                                break
                        if not safe:
                            break

                    if safe:
                        # Perform the swap
                        for node in component:
                            if new_coloring[node] == target_color:
                                new_coloring[node] = c
                            else:
                                new_coloring[node] = target_color
                        kempe_found = True
                        break  # break from color loop

                if not kempe_found:
                    eliminated = False
                    break  # break from vertex loop

            if eliminated:
                # Successfully eliminated target_color: compact colors
                # Map: colors < target_color stay same; colors > target_color shift down by 1
                # But note: we may have introduced new use of target_color via Kempe? 
                # Actually, we removed all target_color, so we can shift down
                mapping = {}
                for col in range(k):
                    if col < target_color:
                        mapping[col] = col
                    elif col > target_color:
                        mapping[col] = col - 1
                # target_color is removed
                current = [mapping[c] for c in new_coloring]
                k = num_colors(current)
                # Restart reduction from scratch with new k
                return kempe_reduce(current)

        return current

    # Apply Kempe reduction if we have time
    if not time_up():
        reduced = kempe_reduce(best_coloring)
        if is_valid_coloring(reduced):
            best_coloring = reduced

    # Final normalization and validation
    best_coloring = normalize_colors(best_coloring)
    if not is_valid_coloring(best_coloring):
        # Ultimate fallback
        best_coloring = list(range(n))

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []

    # Determine if input is adjacency matrix or adjacency list
    if n > 0 and len(adj[0]) == n and all(x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Adjacency list
        adj_list = adj

    # Precompute bitmasks for adjacency
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            # Compute neighbor colors mask
            neighbor_mask = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_mask |= (1 << color[u])
            # Find smallest color not in neighbor_mask
            c = 0
            while neighbor_mask & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # Uncolored set as list for efficiency
        uncolored = set(range(n))
        # Degrees for tie-breaking
        deg = [len(adj_list[i]) for i in range(n)]

        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], deg[x], random.random()))
            # Assign smallest available color
            neighbor_mask = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_mask |= (1 << color[u])
            c = 0
            while neighbor_mask & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build independent set for current_color
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
                independent_set.add(v)
                uncolored.remove(v)
                # Partition: U = vertices not adjacent to any in independent_set, W = adjacent
                U = {u for u in uncolored if not any((1 << u) & bit_adj[w] for w in independent_set)}
                W = uncolored - U

                while U:
                    # Select u in U with max neighbors in W, tie-break by min degree in U
                    u = max(U, key=lambda x: (sum(1 for y in adj_list[x] if y in W), -sum(1 for y in adj_list[x] if y in U), random.random()))
                    independent_set.add(u)
                    U.remove(u)
                    # Move neighbors of u from U to W
                    neighbors_in_U = {y for y in adj_list[u] if y in U}
                    U -= neighbors_in_U
                    W |= neighbors_in_U
            # Assign color to independent_set
            for v in independent_set:
                color[v] = current_color
            current_color += 1
        return color

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        deg = [len(adj_list[i]) for i in range(n)]
        # Buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        order = []
        # Copy of degrees for modification
        curr_deg = deg[:]
        # For each vertex to remove
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # Should not happen
            v = buckets[ptr].pop()
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if curr_deg[u] > ptr:  # Only if u not yet removed
                    # Remove u from its current bucket
                    old_deg = curr_deg[u]
                    buckets[old_deg].remove(u)
                    curr_deg[u] -= 1
                    new_deg = curr_deg[u]
                    buckets[new_deg].append(u)
                    if new_deg < ptr:
                        ptr = new_deg
        # Reverse to get coloring order
        order.reverse()
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except:
        pass
    # Fallback: simple greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        c4 = greedy_color(order)
        candidates.append(c4)
    except:
        pass

    # Select best candidate (fewest colors)
    if not candidates:
        # Ultimate fallback: assign all to color 0 (may be invalid, but we'll fix)
        best_color = [0] * n
    else:
        best_color = min(candidates, key=lambda col: len(set(col)))

    # Validate and fix if necessary (should not happen, but safe)
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    if not is_valid(best_color):
        # Recolor greedily in vertex order
        best_color = greedy_color(list(range(n)))

    # Compact colors to 0..k-1
    unique_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    compacted = [mapping[c] for c in best_color]

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # Try to reduce number of colors iteratively
        while True:
            k = max(coloring) + 1 if n > 0 else 0
            if k <= 1:
                break
            # Find smallest color class (highest index color)
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[coloring[v]].append(v)
            # Start from highest color and try to eliminate
            eliminated = False
            for c in range(k-1, 0, -1):
                if not color_classes[c]:
                    continue  # Already empty
                # Try to recolor each vertex in color c
                moved = [False] * len(color_classes[c])
                # Try direct reassignment to lower colors
                for idx, v in enumerate(color_classes[c]):
                    # Check if v can take any color < c
                    neighbor_mask = 0
                    for u in adj_list[v]:
                        if coloring[u] < c:
                            neighbor_mask |= (1 << coloring[u])
                    for new_c in range(c):
                        if not (neighbor_mask & (1 << new_c)):
                            # Move v to new_c
                            coloring[v] = new_c
                            color_classes[c].remove(v)
                            color_classes[new_c].append(v)
                            moved[idx] = True
                            break
                    if moved[idx]:
                        eliminated = True
                        break  # Restart scan after move
                if eliminated:
                    break
                # Try Kempe chain swaps for each vertex in color c
                for idx, v in enumerate(color_classes[c]):
                    if moved[idx]:
                        continue
                    # Try each lower color
                    for new_c in range(c):
                        # Check if v and any vertex of color new_c are in same Kempe chain
                        # We'll try to swap along Kempe chain (c, new_c) starting from v
                        # Build the Kempe chain component containing v in colors {c, new_c}
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        component = set()
                        while queue:
                            node = queue.popleft()
                            component.add(node)
                            for nb in adj_list[node]:
                                if coloring[nb] == c or coloring[nb] == new_c:
                                    if nb not in visited:
                                        visited.add(nb)
                                        queue.append(nb)
                        # Check if any vertex of color new_c is in this component
                        has_new_c = any(coloring[node] == new_c for node in component)
                        if not has_new_c:
                            # Swap colors c and new_c in component
                            for node in component:
                                if coloring[node] == c:
                                    coloring[node] = new_c
                                elif coloring[node] == new_c:
                                    coloring[node] = c
                            # Update color classes
                            color_classes[c] = [node for node in color_classes[c] if node not in component]
                            color_classes[new_c] = [node for node in color_classes[new_c] if node not in component]
                            color_classes[c].extend([node for node in component if coloring[node] == c])
                            color_classes[new_c].extend([node for node in component if coloring[node] == new_c])
                            eliminated = True
                            break
                    if eliminated:
                        break
                if eliminated:
                    break
            if not eliminated:
                break  # No more reductions possible
        return coloring

    # Apply Kempe reduction
    try:
        best_color = kempe_reduction(best_color[:])  # Work on a copy
    except:
        pass  # If reduction fails, keep current

    # Final validation and compaction
    if not is_valid(best_color):
        best_color = greedy_color(list(range(n)))
    unique_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best_color = [mapping[c] for c in best_color]

    return best_color

