def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list and bitmask
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    neighbors[u].append(v)
                    bit_adj[u] |= (1 << v)
    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True
    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # Helper: convert to consecutive colors
    def normalize(coloring):
        mapping = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            coloring[i] = mapping[c]
        return coloring
    # DSATUR
    def dsatur():
        coloring = [-1] * n
        # saturation: list of sets of neighbor colors
        saturation = [set() for _ in range(n)]
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[u]) for u in range(n)]
        uncolored_count = n
        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat_u = len(saturation[u])
                    deg_u = uncolored_deg[u]
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                       (sat_u == max_sat and deg_u == max_deg and random.random() < 0.5):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen
            # find smallest color not used by neighbors
            used = [False] * (n + 1)
            for nb in neighbors[v]:
                c = coloring[nb]
                if c != -1:
                    used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[v] = c
            # update saturation of uncolored neighbors
            for nb in neighbors[v]:
                if coloring[nb] == -1:
                    saturation[nb].add(c)
                    uncolored_deg[nb] -= 1
            uncolored_count -= 1
        return normalize(coloring)
    # RLF
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: sum(1 for nb in neighbors[u] if nb in uncolored))
            S.add(v)
            # partition U and W
            U = uncolored - {v}
            W = set()
            for nb in neighbors[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                u_star = -1
                max_w_neighbors = -1
                min_u_degree = n + 1
                for u in U:
                    w_neighbors = sum(1 for nb in neighbors[u] if nb in W)
                    u_degree = sum(1 for nb in neighbors[u] if nb in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and u_degree < min_u_degree) or \
                       (w_neighbors == max_w_neighbors and u_degree == min_u_degree and random.random() < 0.5):
                        max_w_neighbors = w_neighbors
                        min_u_degree = u_degree
                        u_star = u
                if u_star == -1:
                    break
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star from U to W
                for nb in neighbors[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to S
            for u in S:
                coloring[u] = color
            uncolored -= S
            color += 1
        return normalize(coloring)
    # Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # compute degeneracy ordering via min-degree removal
        degree = [len(neighbors[u]) for u in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]  # degree buckets
        for u in range(n):
            d = degree[u]
            if d < n:
                buckets[d].append(u)
        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg < n and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break
            u = buckets[min_deg].pop()
            if removed[u]:
                continue
            removed[u] = True
            order.append(u)
            for v in neighbors[u]:
                if not removed[v]:
                    d = degree[v]
                    if d < n:
                        # remove v from its bucket
                        if v in buckets[d]:
                            buckets[d].remove(v)
                        degree[v] -= 1
                        dnew = degree[v]
                        if dnew < n:
                            buckets[dnew].append(v)
        # color in reverse order
        coloring = [-1] * n
        for u in reversed(order):
            used = [False] * (n + 1)
            for v in neighbors[u]:
                c = coloring[v]
                if c != -1:
                    used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[u] = c
        return normalize(coloring)
    # Kempe chain swap for colors a and b, starting from vertex v, returns new coloring if swap performed
    def kempe_swap(coloring, a, b, v):
        # find the Kempe chain component containing v for colors a and b
        stack = [v]
        visited = set()
        component = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            cu = coloring[u]
            if cu == a or cu == b:
                component.add(u)
                for w in neighbors[u]:
                    if w not in visited and (coloring[w] == a or coloring[w] == b):
                        stack.append(w)
        # check if swapping is valid: no neighbor outside component has color a or b that would conflict
        # Actually, swapping colors in a Kempe chain always preserves validity
        # Perform swap
        new_coloring = coloring[:]
        for u in component:
            if new_coloring[u] == a:
                new_coloring[u] = b
            else:
                new_coloring[u] = a
        return new_coloring
    # Try to eliminate the last color via Kempe chains or direct reassignment
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color k-1
        target_color = k - 1
        vertices = [u for u in range(n) if coloring[u] == target_color]
        # try direct reassignment first
        for v in vertices:
            used = [False] * (k)  # we only need to check colors < k
            for nb in neighbors[v]:
                c = coloring[nb]
                if c < k:
                    used[c] = True
            for c in range(k):
                if not used[c]:
                    # move v to color c
                    new_coloring = coloring[:]
                    new_coloring[v] = c
                    # if we moved v, check if target color is now unused
                    # but we need to reassign all vertices of target color? We'll do one by one and repeat
                    # Instead, we will attempt to recolor each vertex and if successful, restart reduction
                    # For simplicity, we try to recolor one vertex and if we can, we remove that vertex from target color
                    # and continue until no more vertices in target color or no progress
                    # We'll implement a loop that tries to recolor any vertex in target color
                    # This function will be called iteratively from outside
                    return new_coloring
        # if no direct reassignment, try Kempe chains with each lower color
        for v in vertices:
            for c in range(target_color):
                # try to swap colors target_color and c in the Kempe chain of v
                # if after swap, v is not color target_color, then we have reduced the count
                new_coloring = kempe_swap(coloring, target_color, c, v)
                if new_coloring[v] != target_color:
                    return new_coloring
        return coloring  # cannot reduce
    # Iterative Kempe reduction
    def kempe_reduce(coloring):
        current = coloring[:]
        while True:
            k = num_colors(current)
            if k <= 1:
                break
            new_coloring = reduce_colors(current)
            if num_colors(new_coloring) < k:
                current = new_coloring
            else:
                break
        return normalize(current)
    # Run all heuristics
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')
    # DSATUR
    c1 = dsatur()
    k1 = num_colors(c1)
    if k1 < best_k:
        best_k = k1
        best_coloring = c1
    # RLF
    c2 = rlf()
    k2 = num_colors(c2)
    if k2 < best_k:
        best_k = k2
        best_coloring = c2
    # Smallest-Last
    c3 = smallest_last()
    k3 = num_colors(c3)
    if k3 < best_k:
        best_k = k3
        best_coloring = c3
    # Apply Kempe reduction to the best
    c4 = kempe_reduce(best_coloring[:])
    k4 = num_colors(c4)
    if k4 < best_k:
        best_k = k4
        best_coloring = c4
    # Final validation and normalization
    if not is_valid(best_coloring):
        # fallback to greedy Welsh-Powell
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        coloring = [-1] * n
        for u in order:
            used = [False] * (n + 1)
            for v in neighbors[u]:
                c = coloring[v]
                if c != -1:
                    used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[u] = c
        best_coloring = normalize(coloring)
    # Ensure consecutive colors
    best_coloring = normalize(best_coloring)
    return best_coloring

import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list
    if is_matrix:
        graph = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    graph[u].append(v)
    else:
        graph = [list(neigh) for neigh in adj]

    # Bitmask representation for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in graph[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: get neighbor colors as bitmask
    def neighbor_color_mask(u, coloring):
        mask = 0
        for v in graph[u]:
            mask |= 1 << coloring[v]
        return mask

    # Helper: first fit color (mex)
    def first_fit(mask):
        c = 0
        while mask & (1 << c):
            c += 1
        return c

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(graph[u]) for u in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = bit_count(sat[u])
                d = uncolored_deg[u]
                if s > max_sat or (s == max_sat and (d > max_deg or (d == max_deg and random.random() < 0.5))):
                    max_sat = s
                    max_deg = d
                    v = u
            # assign smallest available color
            avail = first_fit(sat[v])
            coloring[v] = avail
            uncolored.remove(v)
            # update neighbors
            for nb in graph[v]:
                if nb in uncolored:
                    sat[nb] |= 1 << avail
                    uncolored_deg[nb] -= 1
        return coloring

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # build maximal independent set for this color
            # degrees in uncolored subgraph
            deg = {u: 0 for u in uncolored}
            for u in uncolored:
                for v in graph[u]:
                    if v in uncolored:
                        deg[u] += 1
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda u: (deg[u], random.random()))
            # independent set S
            S = {v}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v} - set(graph[v])
            W = set(graph[v]) & uncolored
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for nb in graph[u] if nb in W)
                    deg_u = sum(1 for nb in graph[u] if nb in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_u < min_deg_u):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in graph[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to all in S
            for u in S:
                coloring[u] = color
            uncolored -= S
            color += 1
        return coloring

    # Strategy 3: Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # compute degeneracy ordering
        order = []
        degrees = [len(graph[u]) for u in range(n)]
        # buckets for degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degrees[u]].append(u)
        # pointer to current non-empty bucket
        ptr = 0
        # copy of degrees
        deg = degrees[:]
        # removed flag
        removed = [False] * n
        for _ in range(n):
            # find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # remove vertex from bucket
            u = buckets[ptr].pop()
            while removed[u]:
                if not buckets[ptr]:
                    break
                u = buckets[ptr].pop()
            if removed[u]:
                continue
            removed[u] = True
            order.append(u)
            # update neighbors
            for v in graph[u]:
                if not removed[v]:
                    d = deg[v]
                    if d > 0:
                        deg[v] -= 1
                        buckets[d].remove(v)
                        buckets[d-1].append(v)
        # color in reverse order
        coloring = [-1] * n
        for u in reversed(order):
            # neighbor colors
            mask = 0
            for v in graph[u]:
                if coloring[v] != -1:
                    mask |= 1 << coloring[v]
            coloring[u] = first_fit(mask)
        return coloring

    # Run all strategies and pick best
    candidates = []
    for strat in (dsatur, rlf, smallest_last):
        try:
            col = strat()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    if not candidates:
        # fallback: greedy random order
        order = list(range(n))
        random.shuffle(order)
        coloring = [-1] * n
        for u in order:
            mask = 0
            for v in graph[u]:
                if coloring[v] != -1:
                    mask |= 1 << coloring[v]
            coloring[u] = first_fit(mask)
        candidates.append(coloring)

    # select candidate with fewest colors
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # vertices with target color
        verts = [u for u in range(n) if coloring[u] == target_color]
        if not verts:
            return coloring, True  # already eliminated
        # try to recolor each vertex
        for v in verts:
            # try direct reassignment to lower color
            for c in range(target_color):
                conflict = False
                for nb in graph[v]:
                    if coloring[nb] == c:
                        conflict = True
                        break
                if not conflict:
                    coloring[v] = c
                    break
            else:
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # BFS to find Kempe chain of colors c and target_color containing v
                    from collections import deque
                    visited = [False] * n
                    q = deque([v])
                    visited[v] = True
                    component = []
                    while q:
                        u = q.popleft()
                        component.append(u)
                        for nb in graph[u]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                q.append(nb)
                    # check if swapping c and target_color in component is valid
                    # after swap, no adjacent same color
                    valid_swap = True
                    for u in component:
                        new_color = c if coloring[u] == target_color else target_color
                        for nb in graph[u]:
                            if coloring[nb] == new_color:
                                valid_swap = False
                                break
                        if not valid_swap:
                            break
                    if valid_swap:
                        # perform swap
                        for u in component:
                            if coloring[u] == c:
                                coloring[u] = target_color
                            else:
                                coloring[u] = c
                        # now v has color c
                        break
                else:
                    # could not recolor v
                    return coloring, False
        # all vertices recolored, eliminate target color
        # remap colors > target_color down by 1
        for u in range(n):
            if coloring[u] > target_color:
                coloring[u] -= 1
        return coloring, True

    # iteratively try to eliminate highest color class
    improved = True
    while improved and k > 0:
        improved = False
        # try to eliminate color k-1
        new_coloring, success = eliminate_color_class(best[:], k-1)
        if success:
            best = new_coloring
            k = num_colors(best)
            improved = True

    # final validation and compact colors
    # ensure colors are 0..k-1
    color_map = {}
    next_color = 0
    for u in range(n):
        c = best[u]
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        best[u] = color_map[c]
    return best

