    def greedy_coloring(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in graph[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

