    best_k = float('inf')

    # 1. DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        sat = [0] * n
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for u in uncolored:
                # saturation degree = number of distinct colors in neighbors
                sat_deg = sat[u].bit_count()
                if sat_deg > max_sat:
                    max_sat = sat_deg
                    candidates = [u]
                elif sat_deg == max_sat:
                    candidates.append(u)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_u = candidates[0]
                for u in candidates:
                    # count uncolored neighbors
                    deg = 0
                    for v in graph[u]:
                        if v in uncolored:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        best_u = u
                u = best_u
            else:
                u = candidates[0]

            # Assign smallest available color
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c

            # Update saturation of uncolored neighbors
            for v in graph[u]:
                if color[v] == -1:  # v is uncolored
                    sat[v] |= (1 << c)

            uncolored.remove(u)
        return color

    # 2. RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v0 = None
            for u in uncolored:
                deg = 0
                for v in graph[u]:
                    if v in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = u
            if v0 is None:
                break  # should not happen
            S.add(v0)
            # U: vertices not adjacent to S (eligible), W: adjacent to S (ineligible)
            U = uncolored - {v0}
            W = set()
            for v in graph[v0]:
                if v in U:
                    U.remove(v)
                    W.add(v)
            # While there are eligible vertices
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_count = 0
                    for v in graph[u]:
                        if v in W:
                            w_count += 1
                    # tie-break: min degree in U
                    deg_in_U = 0
                    for v in graph[u]:
                        if v in U:
                            deg_in_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                # Add best_u to S, move its U-neighbors to W
                S.add(best_u)
                U.remove(best_u)
                for v in graph[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color c to all in S
            for u in S:
                color[u] = c
            # Remove S from uncolored
            uncolored -= S
            c += 1
        return color

