        current = best_coloring
    # Ensure colors are consecutive
    mapping = {}
    next_c = 0
    for i in range(n):
        c = current[i]
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
        current[i] = mapping[c]

    return current

