            # W: vertices adjacent to S (ineligible)
            U = set(uncolored - {v0}) - neighbors[v0]
            W = set(uncolored) - U - S
            while U:
                # Select u in U with max |N(u) ∩ W|
                max_score = -1
                best_u = -1
                for u in U:
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    if score > max_score:
                        max_score = score
                        best_u = u
                    elif score == max_score:
                        # Tie-break: min degree in G[U]
                        deg_u = 0
                        for w in neighbors[u]:
                            if w in U:
                                deg_u += 1
                        deg_best = 0
                        for w in neighbors[best_u]:
                            if w in U:
                                deg_best += 1
                        if deg_u < deg_best:
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
