def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    if is_matrix:
        bit_adj = [0] * n
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    bit_adj[u] |= (1 << v)
    else:
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    bit_adj[u] |= (1 << v)

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in range(u + 1, n):
                if ((bit_adj[u] >> v) & 1) and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [0] * n
        for u in range(n):
            uncolored_deg[u] = bit_adj[u].bit_count()
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, then max uncolored degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_count = saturation[u].bit_count()
                if sat_count > max_sat or (sat_count == max_sat and uncolored_deg[u] > max_deg):
                    max_sat = sat_count
                    max_deg = uncolored_deg[u]
                    v = u
                elif sat_count == max_sat and uncolored_deg[u] == max_deg and u < v:
                    v = u
            if v == -1:
                break  # should not happen

            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)

            # update neighbors
            neighbors = bit_adj[v]
            u = 0
            while neighbors:
                if neighbors & 1:
                    if u in uncolored:
                        saturation[u] |= (1 << c)
                        uncolored_deg[u] -= 1
                neighbors >>= 1
                u += 1
        return normalize(color)

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (bit_adj[x] & sum(1 << u for u in uncolored)).bit_count())
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            adj_to_S = 0
            for u in S:
                adj_to_S |= bit_adj[u]
            U = {u for u in uncolored if u not in S and not (adj_to_S >> u & 1)}
            W = {u for u in uncolored if u not in S and (adj_to_S >> u & 1)}

            while U:
                # select u in U with max neighbors in W
                u_star = -1
                max_w_neighbors = -1
                min_u_deg = float('inf')
                for u in U:
                    w_neighbors = (bit_adj[u] & sum(1 << w for w in W)).bit_count()
                    u_deg = (bit_adj[u] & sum(1 << x for x in U)).bit_count()
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and u_deg < min_u_deg):
                        max_w_neighbors = w_neighbors
                        min_u_deg = u_deg
                        u_star = u
                    elif w_neighbors == max_w_neighbors and u_deg == min_u_deg and u < u_star:
                        u_star = u
                if u_star == -1:
                    break
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                nbrs = bit_adj[u_star]
                v = 0
                while nbrs:
                    if nbrs & 1:
                        if v in U:
                            U.remove(v)
                            W.add(v)
                    nbrs >>= 1
                    v += 1
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return normalize(color)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        deg = [0] * n
        for u in range(n):
            deg[u] = bit_adj[u].bit_count()
        # use buckets for efficiency
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[deg[u]].append(u)
        # track current degree and position
        pos = [0] * n
        for d in range(max_deg + 1):
            for i, u in enumerate(buckets[d]):
                pos[u] = i
        ordering = []
        current_deg = deg[:]
        min_nonempty = 0
        for _ in range(n):
            # find first non-empty bucket
            while min_nonempty <= max_deg and not buckets[min_nonempty]:
                min_nonempty += 1
            if min_nonempty > max_deg:
                break
            u = buckets[min_nonempty].pop()
            pos[u] = len(buckets[min_nonempty])  # not really needed
            ordering.append(u)
            # update neighbors
            nbrs = bit_adj[u]
            v = 0
            while nbrs:
                if nbrs & 1:
                    if current_deg[v] > 0:  # v not removed yet
                        d = current_deg[v]
                        # remove v from bucket d
                        i = pos[v]
                        last = buckets[d][-1]
                        buckets[d][i] = last
                        pos[last] = i
                        buckets[d].pop()
                        # add to bucket d-1
                        current_deg[v] -= 1
                        dnew = current_deg[v]
                        buckets[dnew].append(v)
                        pos[v] = len(buckets[dnew]) - 1
                nbrs >>= 1
                v += 1
        # color in reverse order
        return greedy_color(ordering[::-1])

    # Kempe chain elimination for color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        # make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            k = max(col) + 1 if col else 0
            if k <= 1:
                break
            # target smallest color class: color k-1
            target_color = k - 1
            target_vertices = [v for v in range(n) if col[v] == target_color]
            if not target_vertices:
                # should not happen, but skip
                break
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                neighbor_colors = 0
                for u in range(n):
                    if ((bit_adj[v] >> u) & 1) and col[u] != -1:
                        neighbor_colors |= (1 << col[u])
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        # can move v to color c
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already not in target_color due to prior change, skip
                    if col[v] != target_color:
                        break
                    # BFS to find (target_color, c) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in range(n):
                            if ((bit_adj[x] >> y) & 1) and not visited[y]:
                                if col[y] == target_color or col[y] == c:
                                    visited[y] = True
                                    queue.append(y)
                    # check if we can swap: after swap, no vertex in component becomes target_color?
                    # Actually, swapping will change target_color to c and c to target_color in component.
                    # We want to eliminate target_color: after swap, we want no vertex to have target_color.
                    # That means: in the component, there should be no vertex colored c that would become target_color?
                    # Let's think: currently, component has vertices of target_color and c.
                    # After swap: target_color -> c, c -> target_color.
                    # So vertices that were c become target_color -> bad, we don't want that.
                    # We want that after swap, no vertex is target_color.
                    # That means: in the component, there should be no vertex colored c (because they would become target_color).
                    # But if there is a vertex colored c in the component, swapping would make it target_color.
                    # So we can only swap if the component contains no vertex of color c.
                    has_c = any(col[y] == c for y in component)
                    if not has_c:
                        # safe to swap: all target_color in component become c, and no c becomes target_color
                        for y in component:
                            if col[y] == target_color:
                                col[y] = c
                        changed = True
                        break
            if not changed:
                # cannot reduce further
                break
        # compact colors: ensure 0..k-1
        return normalize(col)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to simple greedy
    if not candidates:
        order = list(range(n))
        c_fallback = greedy_color(order)
        if is_valid(c_fallback):
            candidates.append(c_fallback)

    # Select best (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        k = count_colors(col)
        if k < best_k:
            best_k = k
            best = col
        elif k == best_k:
            # tie-break: prefer lexicographically smaller or more skewed distribution
            # compute sum of squares of color class sizes (larger skew -> smaller sum of squares?)
            # Actually, we want asymmetric: one big class, rest small -> minimize sum of squares?
            # For fixed sum, sum of squares is minimized when sizes are equal, maximized when skewed.
            # We want skewed -> maximize sum of squares.
            sizes = [0] * (best_k if best else 1)
            for c in col:
                if c < len(sizes):
                    sizes[c] += 1
                else:
                    # extend if needed
                    while len(sizes) <= c:
                        sizes.append(0)
                    sizes[c] += 1
            ss = sum(s * s for s in sizes)
            sizes_best = [0] * best_k
            for c in best:
                if c < len(sizes_best):
                    sizes_best[c] += 1
                else:
                    while len(sizes_best) <= c:
                        sizes_best.append(0)
                    sizes_best[c] += 1
            ss_best = sum(s * s for s in sizes_best)
            if ss > ss_best:
                best = col
                best_k = k

    # Apply Kempe reduction to try to improve
    if best is not None:
        reduced = kempe_reduce(best)
        if is_valid(reduced):
            k_red = count_colors(reduced)
            if k_red < best_k:
                best = reduced

    # Final validation and normalization
    if best is None:
        # ultimate fallback
        best = [0] * n
    best = normalize(best)
    if not is_valid(best):
        # last resort: greedy in random order
        for _ in range(10):
            order = list(range(n))
            random.shuffle(order)
            col = greedy_color(order)
            if is_valid(col):
                best = normalize(col)
                break
        else:
            # if still not valid, assign distinct colors (always works)
            best = list(range(n))
    return best

