            while buckets[d]:
                v = buckets[d].pop()
                if visited[v]:
                    continue
                visited[v] = True
                order.append(v)
                for u in graph[v]:
                    if not visited[u]:
                        degrees[u] -= 1
                        if degrees[u] < n:
                            buckets[degrees[u]].append(u)
        return order[::-1]  # reverse for coloring order

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        saturated = [set() for _ in range(n)]
        # degree in the full graph for tie-breaking
        degrees = [len(graph[i]) for i in range(n)]
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat = len(saturated[u])
                    if sat > max_sat or (sat == max_sat and degrees[u] > max_deg):
                        max_sat = sat
                        max_deg = degrees[u]
                        v = u
            if v == -1:
                break  # should not happen
            # find smallest available color
            used = [False] * n
            for u in graph[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
            # update saturation of neighbors
            for u in graph[v]:
                if coloring[u] == -1:
                    saturated[u].add(c)
        return coloring

    # Helper: RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # induced subgraph on uncolored
            # find vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            # independent set for this color
            independent_set = {v}
            # partition: U = not adjacent to any in S, W = adjacent to at least one in S
            U = {u for u in uncolored if u != v and all(u not in graph[w] for w in independent_set)}
            W = {u for u in uncolored if u != v and any(u in graph[w] for w in independent_set)}
            while U:
                # select u in U with max neighbors in W
                u_star = max(U, key=lambda x: sum(1 for y in graph[x] if y in W))
                # tie-break: min degree in G[U]
                min_deg_U = min((sum(1 for y in graph[x] if y in U) for x in U), default=-1)
                candidates = [x for x in U if sum(1 for y in graph[x] if y in U) == min_deg_U]
                u_star = random.choice(candidates) if candidates else u_star
                independent_set.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for nb in graph[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to independent_set
            for node in independent_set:
                coloring[node] = color
                uncolored.remove(node)
            color += 1
        return coloring

    # Generate candidate colorings
    candidates = []

    # 1. Welsh-Powell
    try:
        c1 = greedy_color(welsh_powell_order())
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass

    # 2. Smallest-Last
    try:
        c2 = greedy_color(smallest_last_order())
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass

    # 3. DSATUR
    try:
        c3 = dsatur()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # 4. RLF
    try:
        c4 = rlf()
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass

    # If no candidate (should not happen), fallback to trivial
    if not candidates:
        candidates.append([0] * n)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Iterative Kempe chain color reduction
    improved = True
    while improved and k > 1:
        improved = False
        # target smallest color class (k-1)
        target_color = k - 1
        target_vertices = [v for v in range(n) if best[v] == target_color]
        if not target_vertices:
            # already compacted?
            k -= 1
            continue
        # Try to recolor each target vertex
        for v in target_vertices[:]:  # copy list as we may modify
            # Try direct reassignment to a lower color
            used = [False] * k
            for u in graph[v]:
                if best[u] < k:
                    used[best[u]] = True
            for c in range(target_color):
                if not used[c]:
                    # move v to color c
                    best[v] = c
                    improved = True
                    break
            if improved:
                # after moving one vertex, break to recompute target class
                break
            # Try Kempe chains with each lower color
            for c in range(target_color):
                # Find the (v, c)-Kempe chain containing v
                # Only consider vertices with color target_color or c
                stack = [v]
                visited = set()
                component = set()
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    if best[node] == target_color or best[node] == c:
                        component.add(node)
                        for nb in graph[node]:
                            if nb not in visited and (best[nb] == target_color or best[nb] == c):
                                stack.append(nb)
                # Check if swapping this component would free color c for v
                # After swap, v would get color c, and all target_color in component become c
                # We need to ensure no neighbor of v gets color c from the swap (except possibly v itself)
                conflict = False
                for node in component:
                    if best[node] == target_color:
                        # after swap, this node becomes c
                        for nb in graph[node]:
                            if nb != v and best[nb] == c:  # v will become c, so ignore v
                                conflict = True
                                break
                    if conflict:
                        break
                if not conflict:
                    # perform swap
                    for node in component:
                        if best[node] == target_color:
                            best[node] = c
                        else:  # best[node] == c
                            best[node] = target_color
                    improved = True
                    break
            if improved:
                break
        # After attempting to eliminate target color, compact if possible
        used_colors = set(best)
        if len(used_colors) < k:
            # remap colors to 0..k'-1
            mapping = {old: new for new, old in enumerate(sorted(used_colors))]
            best = [mapping[c] for c in best]
            k = len(used_colors)
            improved = True  # continue trying to reduce

    # Final validation and return
    if not is_valid(best):
        # last resort: greedy in random order
        order = list(range(n))
        random.shuffle(order)
        best = greedy_color(order)
    return best

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0]) if n > 0 else 0
    if n == 1:
        return [0]
    if m == 0:
        return list(range(n))
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for fast access
    proc = [times[i][:] for i in range(n)]

    # Helper: makespan of a permutation using iterative DP (O(N*M))
    def makespan(perm):
        if not perm:
            return 0
        dp = [0] * m
        for job in perm:
            pj = proc[job]
            dp[0] += pj[0]
            for j in range(1, m):
                dp[j] = max(dp[j-1], dp[j]) + pj[j]
        return dp[-1]

    # Helper: compute forward completion matrix for a prefix of length k
    def compute_forward(prefix, k):
        e = [[0] * m for _ in range(k)]
        if k == 0:
            return e
        p0 = proc[prefix[0]]
        e[0][0] = p0[0]
        for j in range(1, m):
            e[0][j] = e[0][j-1] + p0[j]
        for i in range(1, k):
            pi = proc[prefix[i]]
            e[i][0] = e[i-1][0] + pi[0]
            for j in range(1, m):
                e[i][j] = max(e[i-1][j], e[i][j-1]) + pi[j]
        return e

    # Helper: compute backward tail matrix for a prefix of length k
    def compute_backward(prefix, k):
        q = [[0] * m for _ in range(k+1)]
        if k == 0:
            return q
        for j in range(m):
            q[k][j] = 0
        for i in range(k-1, -1, -1):
            pi = proc[prefix[i]]
            q[i][m-1] = q[i+1][m-1] + pi[m-1]
            for j in range(m-2, -1, -1):
                q[i][j] = max(q[i+1][j], q[i][j+1]) + pi[j]
        return q

    # Helper: evaluate makespan for inserting job x at position i in prefix of length k
    def evaluate_insertion(prefix, k, x, e, q):
        if k == 0:
            f = [proc[x][j] for j in range(m)]
            return max(f[j] + q[0][j] for j in range(m))
        f = [0] * m
        pj = proc[x]
        prev_e = e[-1] if k-1 >= 0 else [0]*m
        if k-1 >= 0:
            f[0] = prev_e[0] + pj[0]
            for j in range(1, m):
                f[j] = max(f[j-1], prev_e[j]) + pj[j]
        else:
            f[0] = pj[0]
            for j in range(1, m):
                f[j] = f[j-1] + pj[j]
        best = float('inf')
        for j in range(m):
            val = f[j] + q[k][j]
            if val < best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    total_proc = [sum(proc[i]) for i in range(n)]
    order = sorted(range(n), key=lambda i: total_proc[i], reverse=True)

    if n == 0:
        return []
    perm = [order[0]]
    if n == 1:
        return perm

    # Try both orders for first two jobs
    seq1 = [order[0], order[1]]
    seq2 = [order[1], order[0]]
    if makespan(seq1) <= makespan(seq2):
        perm = seq1
    else:
        perm = seq2

    # Insert remaining jobs
    for k in range(2, n):
        job = order[k]
        e = compute_forward(perm, k)
        q = compute_backward(perm, k)
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            mk = evaluate_insertion(perm, k, job, e, q)
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        perm.insert(best_pos, job)

    # Iterated Greedy refinement
    current = perm[:]
    current_mk = makespan(current)
    best_perm = current[:]
    best_mk = current_mk

    total_processing = sum(total_proc)
    T_param = 0.5
    T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
    d = 3 if n >= 3 else n
    max_iter = 60
    if n > 60:
        max_iter = 40
    if n > 100:
        max_iter = 30

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d == 0:
            destroyed = current[:]
            R = []
        else:
            indices = random.sample(range(n), d)
            indices.sort(reverse=True)
            R = [current[i] for i in indices]
            destroyed = [current[i] for i in range(n) if i not in set(indices)]

        # Reconstruction: reinsert jobs in R using NEH insertion with Taillard
        for job in R:
            k = len(destroyed)
            if k == 0:
                destroyed = [job]
                continue
            e = compute_forward(destroyed, k)
            q = compute_backward(destroyed, k)
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                mk = evaluate_insertion(destroyed, k, job, e, q)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            destroyed.insert(best_pos, job)

        new_perm = destroyed
        new_mk = makespan(new_perm)

        # Acceptance criterion
        if new_mk < current_mk:
            current = new_perm
            current_mk = new_mk
            if new_mk < best_mk:
                best_perm = new_perm[:]
                best_mk = new_mk
        else:
            if random.random() < math.exp(-(new_mk - current_mk) / T):
                current = new_perm
                current_mk = new_mk

    return best_perm

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: total_processing[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_times[m]
        return t[-1]

    def makespan_with_insertion(seq, job, pos):
        if not seq:
            return times[job][0] if M == 1 else _makespan_single_job(job)
        if pos == 0:
            prefix = []
            suffix = seq
        elif pos == len(seq):
            prefix = seq
            suffix = []
        else:
            prefix = seq[:pos]
            suffix = seq[pos:]
        return makespan(prefix + [job] + suffix)

    def _makespan_single_job(job):
        t = 0
        for m in range(M):
            t += times[job][m]
        return t

    def taillard_makespan(seq):
        if not seq:
            return 0
        e = [0] * M
        for job in seq:
            job_t = times[job]
            e[0] += job_t[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + job_t[m]
        return e[-1]

    def taillard_insertion_cost(seq, job, pos):
        k = len(seq)
        if k == 0:
            return taillard_makespan([job])
        e = [0] * M
        for idx in range(pos):
            job_t = times[seq[idx]]
            e[0] += job_t[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + job_t[m]
        f = [0] * M
        job_t = times[job]
        if pos == 0:
            f[0] = job_t[0]
            for m in range(1, M):
                f[m] = max(f[m-1], 0) + job_t[m]
        else:
            f[0] = e[0] + job_t[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[m]) + job_t[m]
        q = [0] * M
        for idx in range(k-1, pos-1, -1):
            job_t = times[seq[idx]]
            q[M-1] += job_t[M-1]
            for m in range(M-2, -1, -1):
                q[m] = max(q[m], q[m+1]) + job_t[m]
        max_val = 0
        for m in range(M):
            val = f[m] + q[m]
            if val > max_val:
                max_val = val
        return max_val

    best_seq = [order[0], order[1]] if makespan([order[0], order[1]]) <= makespan([order[1], order[0]]) else [order[1], order[0]]
    for k in range(2, N):
        job = order[k]
        best_pos = 0
        best_cost = taillard_insertion_cost(best_seq, job, 0)
        for pos in range(1, k+1):
            cost = taillard_insertion_cost(best_seq, job, pos)
            if cost < best_cost:
                best_cost = cost
                best_pos = pos
        best_seq.insert(best_pos, job)

    current_seq = best_seq[:]
    best_seq_ever = current_seq[:]
    best_makespan_ever = taillard_makespan(best_seq_ever)
    LB = 0
    for m in range(M):
        min_pre = min(sum(times[i][:m]) for i in range(N)) if m > 0 else 0
        min_suf = min(sum(times[i][m+1:]) for i in range(N)) if m < M-1 else 0
        machine_sum = sum(times[i][m] for i in range(N))
        LB = max(LB, min_pre + machine_sum + min_suf)
    if best_makespan_ever == LB:
        return best_seq_ever

    T_param = 0.5
    avg_p = sum(total_processing) / (N * M)
    T = T_param * avg_p / (10 * N * M) * N * M
    T = max(T, 1e-6)
    d = 3 if N > 20 else 2
    max_iter = 60
    for _ in range(max_iter):
        if len(current_seq) <= d:
            destroyed = []
            R = current_seq[:]
            random.shuffle(R)
        else:
            indices = random.sample(range(len(current_seq)), d)
            indices.sort(reverse=True)
            R = [current_seq.pop(i) for i in indices]
            destroyed = current_seq
        random.shuffle(R)
        for job in R:
            best_pos = 0
            best_cost = taillard_insertion_cost(destroyed, job, 0)
            for pos in range(1, len(destroyed)+1):
                cost = taillard_insertion_cost(destroyed, job, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            destroyed.insert(best_pos, job)
        current_seq = destroyed
        current_makespan = taillard_makespan(current_seq)
        if current_makespan < best_makespan_ever:
            best_makespan_ever = current_makespan
            best_seq_ever = current_seq[:]
        if current_makespan < taillard_makespan(best_seq):
            best_seq = current_seq[:]
        elif random.random() < math.exp(-(current_makespan - taillard_makespan(best_seq)) / T):
            best_seq = current_seq[:]
    return best_seq_ever

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for NEH ordering
    total_times = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N)]
    f = [0] * M

    def makespan_from_perm(perm):
        if not perm:
            return 0
        # Initialize first job
        e[0][0] = times[perm[0]][0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + times[perm[0]][m]
        # Forward pass for remaining jobs
        for i in range(1, len(perm)):
            job_idx = perm[i]
            e[i][0] = e[i-1][0] + times[job_idx][0]
            for m in range(1, M):
                e[i][m] = max(e[i-1][m], e[i][m-1]) + times[job_idx][m]
        return e[len(perm)-1][M-1]

    def makespan_with_insertion(perm, pos, job_idx):
        k = len(perm)
        # Compute forward vector f for insertion at position pos
        if pos == 0:
            f[0] = times[job_idx][0]
            for m in range(1, M):
                f[m] = f[m-1] + times[job_idx][m]
        else:
            f[0] = e[pos-1][0] + times[job_idx][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + times[job_idx][m]
        # Compute makespan using forward vector f and backward tail q
        makespan = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan:
                makespan = val
        return makespan

    def neh_construct(start_idx=0):
        # Reset e and q for new construction
        for i in range(N):
            for m in range(M):
                e[i][m] = 0
                q[i][m] = 0
        perm = []
        # Build permutation incrementally
        for idx in range(start_idx, N):
            job_idx = order[idx]
            k = len(perm)
            if k == 0:
                perm.append(job_idx)
                # Update e for first job
                e[0][0] = times[job_idx][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + times[job_idx][m]
                # Update q for first job (only one job)
                for m in range(M):
                    q[0][m] = times[job_idx][m]
                continue
            # Evaluate all k+1 insertion positions
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(k+1):
                # Compute forward vector f for job_idx at position pos
                if pos == 0:
                    f[0] = times[job_idx][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + times[job_idx][m]
                else:
                    f[0] = e[pos-1][0] + times[job_idx][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[pos-1][m]) + times[job_idx][m]
                # Compute makespan for this insertion
                ms = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > ms:
                        ms = val
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            # Insert job at best_pos
            perm.insert(best_pos, job_idx)
            # Recompute e and q for the new permutation of length k+1
            new_len = k+1
            # Forward pass
            for i in range(new_len):
                job_i = perm[i]
                if i == 0:
                    e[0][0] = times[job_i][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + times[job_i][m]
                else:
                    e[i][0] = e[i-1][0] + times[job_i][0]
                    for m in range(1, M):
                        e[i][m] = max(e[i-1][m], e[i][m-1]) + times[job_i][m]
            # Backward pass
            for m in range(M):
                q[new_len][m] = 0
            for i in range(new_len-1, -1, -1):
                job_i = perm[i]
                if i == new_len-1:
                    q[i][M-1] = times[job_i][M-1]
                    for m in range(M-2, -1, -1):
                        q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job_i][m]
                else:
                    q[i][M-1] = q[i+1][M-1] + times[job_i][M-1]
                    for m in range(M-2, -1, -1):
                        q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job_i][m]
        return perm

    # Compute lower bound for early termination (Taillard's LB)
    LB = 0
    for m in range(M):
        min_before = min(times[i][:m] for i in range(N)) if m > 0 else [0]*N
        min_after = min(times[i][m+1:] for i in range(N)) if m < M-1 else [0]*N
        sum_m = sum(times[i][m] for i in range(N))
        lb_m = min(sum(row[:m]) for row in times) + sum_m + min(sum(row[m+1:]) for row in times) if m > 0 and m < M-1 else \
               (sum_m + min(sum(row[m+1:]) for row in times)) if m == 0 else \
               (min(sum(row[:m]) for row in times) + sum_m) if m == M-1 else 0
        if lb_m > LB:
            LB = lb_m

    # Initial solution via NEH
    current_perm = neh_construct(0)
    best_perm = current_perm[:]
    best_makespan = makespan_from_perm(best_perm)
    if best_makespan == LB:
        return best_perm

    # Iterated Greedy parameters
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 60
    iter_count = 0

    while iter_count < max_iter:
        # Destruction: remove d random jobs
        indices = list(range(N))
        random.shuffle(indices)
        removed_indices = indices[:d]
        removed_jobs = [current_perm[i] for i in removed_indices]
        # Build destroyed permutation
        destroyed_perm = [current_perm[i] for i in indices[d:]]

        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed_jobs)
        for job_idx in removed_jobs:
            k = len(destroyed_perm)
            if k == 0:
                destroyed_perm.append(job_idx)
                # Update e and q for single job
                e[0][0] = times[job_idx][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + times[job_idx][m]
                for m in range(M):
                    q[0][m] = times[job_idx][m]
                continue
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(k+1):
                # Compute forward vector f for job_idx at position pos
                if pos == 0:
                    f[0] = times[job_idx][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + times[job_idx][m]
                else:
                    f[0] = e[pos-1][0] + times[job_idx][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[pos-1][m]) + times[job_idx][m]
                # Compute makespan for this insertion
                ms = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > ms:
                        ms = val
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            # Insert job at best_pos
            destroyed_perm.insert(best_pos, job_idx)
            # Recompute e and q for the new permutation
            new_len = k+1
            # Forward pass
            for i in range(new_len):
                job_i = destroyed_perm[i]
                if i == 0:
                    e[0][0] = times[job_i][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + times[job_i][m]
                else:
                    e[i][0] = e[i-1][0] + times[job_i][0]
                    for m in range(1, M):
                        e[i][m] = max(e[i-1][m], e[i][m-1]) + times[job_i][m]
            # Backward pass
            for m in range(M):
                q[new_len][m] = 0
            for i in range(new_len-1, -1, -1):
                job_i = destroyed_perm[i]
                if i == new_len-1:
                    q[i][M-1] = times[job_i][M-1]
                    for m in range(M-2, -1, -1):
                        q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job_i][m]
                else:
                    q[i][M-1] = q[i+1][M-1] + times[job_i][M-1]
                    for m in range(M-2, -1, -1):
                        q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job_i][m]

        # Compute makespan of new solution
        new_makespan = makespan_from_perm(destroyed_perm)

        # Acceptance criterion
        if new_makespan < makespan_from_perm(current_perm):
            current_perm = destroyed_perm[:]
            if new_makespan < best_makespan:
                best_perm = destroyed_perm[:]
                best_makespan = new_makespan
                if best_makespan == LB:
                    break
        else:
            delta = new_makespan - makespan_from_perm(current_perm)
            if random.random() < math.exp(-delta / T):
                current_perm = destroyed_perm[:]

        iter_count += 1

    return best_perm

