def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten times for faster access
    flat_times = [times[i][j] for i in range(N) for j in range(M)]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            base = job * M
            t[0] += flat_times[base]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + flat_times[base + m]
        return t[-1]

    # Initial solution: sort by total processing time descending
    total_times = [sum(times[i]) for i in range(N)]
    seq = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    current_makespan = makespan(seq)
    best_seq = seq[:]
    best_makespan = current_makespan

    # Iterated improvement with adjacent swaps (bubble-sort style descent)
    max_iter = 200
    for _ in range(max_iter):
        improved = False
        for i in range(N - 1):
            # Swap adjacent jobs at i and i+1
            seq[i], seq[i+1] = seq[i+1], seq[i]
            new_makespan = makespan(seq)
            if new_makespan < current_makespan:
                current_makespan = new_makespan
                improved = True
                if new_makespan < best_makespan:
                    best_makespan = new_makespan
                    best_seq = seq[:]
            else:
                # Revert swap if not improving
                seq[i], seq[i+1] = seq[i+1], seq[i]
        if not improved:
            break

    return best_seq

