            f[0] = prev_e[0] + job_t[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev_e[m]) + job_t[m]
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
