                        best_v = v
                v = best_v
            else:
                v = candidates[0]
            # Assign smallest available color
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
