def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: validate coloring and compute number of colors
    def validate_and_count(colors):
        if len(colors) != n:
            return False, 0
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False, 0
        return True, max(colors) + 1 if n > 0 else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        # Precompute degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]
        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                if sat > best_sat or (sat == best_sat and (
                    degrees[v] > best_deg or (degrees[v] == best_deg and v < best_v)
                )):
                    best_sat = sat
                    best_deg = degrees[v]
                    best_v = v
            v = best_v
            # Find smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u] |= (1 << c)
        return colors

    # RLF: Recursive Largest First
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            # Compute degrees in uncolored subgraph
            deg_in_uncolored = [0] * n
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_in_uncolored[v] += 1
            # Find vertex with max degree in uncolored
            start = max(uncolored, key=lambda v: (deg_in_uncolored[v], v))
            independent_set = {start}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {start}
            W = set()
            for u in adj_list[start]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # While U not empty, add vertex with max neighbors in W
            while U:
                best_u = -1
                best_w_neighbors = -1
                best_deg_U = -1
                for u in U:
                    # Count neighbors in W
                    w_neighbors = 0
                    for v in adj_list[u]:
                        if v in W:
                            w_neighbors += 1
                    # Tie-break: min degree in U-induced subgraph
                    deg_U = 0
                    for v in adj_list[u]:
                        if v in U:
                            deg_U += 1
                    if (w_neighbors > best_w_neighbors or
                        (w_neighbors == best_w_neighbors and deg_U < best_deg_U) or
                        (w_neighbors == best_w_neighbors and deg_U == best_deg_U and u < best_u)):
                        best_w_neighbors = w_neighbors
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for v in adj_list[u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color to independent set
            for v in independent_set:
                colors[v] = color
            uncolored -= independent_set
            color += 1
        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degree = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            # Find unremoved vertex with min degree
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and degree[i] < min_deg:
                    min_deg = degree[i]
                    v = i
            if v == -1:
                break  # should not happen
            order.append(v)
            removed[v] = True
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    degree[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain color reduction
    def kempe_reduce(colors):
        # Make sure colors are compact
        def compact(cols):
            mapping = {}
            next_color = 0
            for c in cols:
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
            return [mapping[c] for c in cols]

        colors = compact(colors)
        k = max(colors) + 1 if n > 0 else 0
        # Try to reduce colors from k-1 down
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                k -= 1
                colors = compact(colors)
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if colors[u] < target_color:
                        neighbor_colors.add(colors[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Direct move possible
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swaps
                for c in range(target_color):
                    # Check if v can be swapped with color c via Kempe chain
                    # We'll try to find a Kempe chain (target_color, c) starting from v
                    # that does not include any other target_color vertex (to avoid pulling them in)
                    # Actually, we allow the chain to include other target_color vertices, but we want to free color c for v
                    # Standard Kempe: swap colors in the component of v in the subgraph induced by colors {target_color, c}
                    # After swap, v will have color c, and we need to ensure no conflict
                    # Since we only swap within the component, it remains valid.
                    # However, if the component contains another vertex w of target_color, after swap w becomes c,
                    # which might cause conflict if w has a neighbor of color c outside the component.
                    # But the swap is still valid globally because we only swap within the component.
                    # The issue is that we might not reduce the number of target_color vertices.
                    # To reduce the count, we need the component to contain exactly one target_color vertex (v).
                    # So we check if the Kempe chain component of v in colors {target_color, c} contains any other target_color vertex.
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    is_safe = True  # True if no other target_color in component
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        if colors[x] == target_color and x != v:
                            is_safe = False  # Found another target_color in component
                        for y in adj_list[x]:
                            if not visited[y] and (colors[y] == target_color or colors[y] == c):
                                visited[y] = True
                                queue.append(y)
                    if is_safe:
                        # Swap colors in component
                        for x in component:
                            if colors[x] == target_color:
                                colors[x] = c
                            else:  # must be c
                                colors[x] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                k = max(colors) + 1
                colors = compact(colors)
            else:
                # Cannot reduce further
                break
        return colors

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        valid, _ = validate_and_count(c1)
        if valid:
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        valid, _ = validate_and_count(c2)
        if valid:
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        valid, _ = validate_and_count(c3)
        if valid:
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy by index
    if not candidates:
        colors = greedy_color(list(range(n)))
        candidates.append(colors)

    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        _, k = validate_and_count(col)
        if k < best_k:
            best_k = k
            best = col

    # Apply Kempe reduction to best candidate
    best = kempe_reduce(best)
    # Final validation and compaction
    valid, _ = validate_and_count(best)
    if not valid:
        # Last resort: greedy by index
        best = greedy_color(list(range(n)))
    best = kempe_reduce(best)  # Try again
    # Ensure compact
    def compact_final(cols):
        mapping = {}
        next_color = 0
        for c in cols:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in cols]
    best = compact_final(best)
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list
    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = [list(neighbors) for neighbors in adj]
    # Precompute neighbor bitmasks
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in graph[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        used_masks = [0] * n  # bitmask of colors used by neighbors
        for v in order:
            cmask = used_masks[v]
            c = 0
            while cmask & (1 << c):
                c += 1
            color[v] = c
            for u in graph[v]:
                used_masks[u] |= 1 << c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    best_coloring = None
    best_k = float('inf')

    # DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors in neighborhood
        sat_mask = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(graph[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = sat_mask[u].bit_count()
                deg = uncolored_deg[u]
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and random.random() < 0.5):
                    max_sat = sat
                    max_deg = deg
                    v = u
            # assign smallest available color
            cmask = sat_mask[v]
            c = 0
            while cmask & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in graph[v]:
                if u in uncolored:
                    sat_mask[u] |= 1 << c
                    uncolored_deg[u] -= 1
        return color

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in induced subgraph of uncolored
            deg = {}
            for u in uncolored:
                cnt = 0
                for v in graph[u]:
                    if v in uncolored:
                        cnt += 1
                deg[u] = cnt
            # pick vertex with max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and all(w not in graph[u] for w in S)}
            # W: vertices adjacent to at least one in S
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = float('inf')
                for u in U:
                    score = sum(1 for w in graph[u] if w in W)
                    # deg in U
                    degU = sum(1 for w in graph[u] if w in U)
                    if score > best_score or (score == best_score and degU < best_degU) or (score == best_score and degU == best_degU and random.random() < 0.5):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in graph[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(graph[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # buckets by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = deg[v]
        # process
        for _ in range(n):
            # find non-empty bucket with smallest index
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in graph[v]:
                if u in remaining:
                    du = pos[u]
                    # remove u from bucket du
                    if u in buckets[du]:
                        buckets[du].remove(u)
                    pos[u] -= 1
                    buckets[pos[u]].append(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    for func in (dsatur, rlf, smallest_last):
        try:
            col = func()
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col
        except Exception:
            continue

    # If no candidate, fallback to greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # color classes
        classes = [[] for _ in range(k)]
        for v, c in enumerate(coloring):
            classes[c].append(v)
        # try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target = k - 1
            if not classes[target]:
                # should not happen, but compact
                for c in range(target, k-1):
                    classes[c] = classes[c+1]
                classes.pop()
                k -= 1
                # rebuild coloring
                new_coloring = [-1] * n
                for c, lst in enumerate(classes):
                    for v in lst:
                        new_coloring[v] = c
                coloring = new_coloring
                changed = True
                continue
            # try to recolor each vertex in target class
            for v in classes[target][:]:
                # try direct reassignment to lower color
                neighbor_colors = set()
                for u in graph[v]:
                    if coloring[u] < target:
                        neighbor_colors.add(coloring[u])
                for c in range(target):
                    if c not in neighbor_colors:
                        # move v to color c
                        coloring[v] = c
                        classes[target].remove(v)
                        classes[c].append(v)
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                if changed:
                    break
                for c in range(target):
                    # BFS to get Kempe chain of colors c and target containing v
                    from collections import deque
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    while stack:
                        x = stack.pop()
                        for y in graph[x]:
                            if y not in visited and (coloring[y] == c or coloring[y] == target):
                                visited.add(y)
                                stack.append(y)
                    # check if swapping colors c and target in this component is safe
                    # i.e., no neighbor of any vertex in component has color c or target outside component
                    safe = True
                    for x in visited:
                        for y in graph[x]:
                            if y not in visited and (coloring[y] == c or coloring[y] == target):
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # perform swap
                        for x in visited:
                            if coloring[x] == c:
                                coloring[x] = target
                            else:
                                coloring[x] = c
                        # update classes
                        classes[c].clear()
                        classes[target].clear()
                        for idx, col_val in enumerate(coloring):
                            classes[col_val].append(idx)
                        changed = True
                        break
            if not changed:
                # cannot eliminate this color class, break
                break
        # compact colors
        # map colors to 0..k'-1
        unique_colors = {}
        next_color = 0
        for v in range(n):
            c = coloring[v]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[v] = unique_colors[c]
        return coloring

    best_coloring = kempe_reduce(best_coloring)
    # Final validation (optional, but ensure correctness)
    # for u in range(n):
    #     for v in graph[u]:
    #         if best_coloring[u] == best_coloring[v]:
    #             # fallback to greedy if invalid (should not happen)
    #             return greedy_color(list(range(n)))
    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    # ---------- Input handling ----------
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = (len(adj[0]) == n and 
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    # Build neighbor sets and bit adjacency
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    for u in range(n):
        if is_matrix:
            row = adj[u]
            for v in range(n):
                if row[v]:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)
        else:
            for v in adj[u]:
                if v != u:  # ignore self-loops
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)

    # Ensure symmetry (undirected graph)
    for u in range(n):
        for v in neighbors[u]:
            if u not in neighbors[v]:
                neighbors[v].add(u)
                bit_adj[v] |= (1 << u)

    # ---------- Helper functions ----------
    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    def normalize_colors(coloring):
        # Map colors to 0..k-1 consecutively
        mapping = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            coloring[i] = mapping[c]
        return coloring

    def count_colors(coloring):
        return max(coloring) + 1 if n > 0 else 0

    # ---------- DSATUR ----------
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighborhood
        saturation = [0] * n
        # neighbor color masks for fast saturation update
        neighbor_color_mask = [0] * n

        # initial vertex: highest degree
        degrees = [len(neighbors[i]) for i in range(n)]
        vertex = max(range(n), key=lambda i: (degrees[i], i))
        coloring[vertex] = 0
        # update neighbors of vertex
        for v in neighbors[vertex]:
            neighbor_color_mask[v] |= (1 << 0)
            saturation[v] = 1  # only color 0 so far

        for _ in range(1, n):
            # select uncolored vertex with max saturation, tie-break by degree
            candidate = -1
            max_sat = -1
            max_deg = -1
            for v in range(n):
                if coloring[v] == -1:
                    sat = saturation[v]
                    deg = len(neighbors[v])
                    if sat > max_sat or (sat == max_sat and deg > max_deg) or \
                       (sat == max_sat and deg == max_deg and v > candidate):
                        max_sat = sat
                        max_deg = deg
                        candidate = v
            v = candidate

            # find smallest available color
            used = neighbor_color_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # update neighbors
            for u in neighbors[v]:
                if not (neighbor_color_mask[u] & (1 << c)):
                    neighbor_color_mask[u] |= (1 << c)
                    saturation[u] += 1

        return normalize_colors(coloring)

    # ---------- RLF ----------
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # build maximal independent set for this color
            # start with vertex of max degree in uncolored subgraph
            def degree_in_uncolored(v):
                return sum(1 for u in neighbors[v] if u in uncolored)

            v = max(uncolored, key=lambda x: (degree_in_uncolored(x), x))
            independent_set = {v}
            to_check = set(uncolored) - {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            W = set()
            for u in to_check:
                if any(w in neighbors[u] for w in independent_set):
                    W.add(u)
            U = to_check - W

            while U:
                # select u in U with max |N(u) ∩ W|
                def weight(u):
                    return sum(1 for w in neighbors[u] if w in W)
                # tie-break: min degree in G[U]
                def deg_in_U(u):
                    return sum(1 for w in neighbors[u] if w in U)
                u = max(U, key=lambda x: (weight(x), -deg_in_U(x), x))
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # assign color to independent_set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return normalize_colors(coloring)

    # ---------- Smallest-Last (Degeneracy ordering) ----------
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].add(v)

        for _ in range(n):
            # find first non-empty bucket
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
            if i > max_deg:
                break  # should not happen
            v = buckets[i].pop()
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # remove u from current bucket
                    buckets[degree[u]].remove(u)
                    degree[u] -= 1
                    if degree[u] >= 0:
                        buckets[degree[u]].add(u)
            remaining.remove(v)

        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return normalize_colors(coloring)

    # ---------- Kempe chain color reduction ----------
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # make a copy to work on
        current = coloring[:]
        improved = True
        while improved:
            improved = False
            k = count_colors(current)
            if k <= 1:
                break
            # target smallest color class (highest index)
            target_color = k - 1
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # should not happen, but compact anyway
                return normalize_colors(current)

            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in neighbors[v]:
                    cu = current[u]
                    if cu < target_color:  # only consider colors we might reassign to
                        used_by_neighbors |= (1 << cu)
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # can recolor v to c
                        current[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart scan after change

                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c after direct reassignment attempt, skip
                    if current[v] == c:
                        continue
                    # find the (c, target_color) Kempe chain containing v
                    # BFS/DFS over vertices colored c or target_color
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        cn = current[node]
                        if cn == c or cn == target_color:
                            component.add(node)
                            for w in neighbors[node]:
                                if w not in visited:
                                    stack.append(w)
                    # check if any neighbor of v in the component has color c
                    # actually, we need to see if we can swap: after swap, v would become c
                    # and we must ensure no neighbor of v becomes target_color (which would conflict if they are adjacent to v?)
                    # But note: after swap, neighbors of v that are in the component and had color c become target_color.
                    # If any such neighbor is adjacent to v, then after swap it would be target_color and adjacent to v (which is now c) -> ok.
                    # The only issue is if there is a neighbor of v not in the component that is color c? 
                    # Actually, the swap is safe if and only if no neighbor of v is colored c and not in the component? 
                    # Standard condition: we can swap the component if it does not contain a neighbor of v that is colored c? 
                    # Let's think: we want to recolor v to c. Currently v is target_color.
                    # After swapping the component, v becomes c (if v in component, which it is).
                    # A neighbor u of v:
                    #   - If u not in component: its color unchanged.
                    #   - If u in component: 
                    #         if it was c -> becomes target_color
                    #         if it was target_color -> becomes c
                    # For the coloring to remain valid:
                    #   - If u not in component: we need current[u] != c (since v becomes c)
                    #   - If u in component and was c: after swap becomes target_color, need target_color != current[u] (which was c) -> true, and also need target_color != current[v] (which becomes c) -> true as long as c != target_color.
                    #   - If u in component and was target_color: after swap becomes c, then we need c != current[u] (which becomes c) -> conflict! 
                    # Actually, wait: after swap, v becomes c, and if a neighbor u in component was target_color and becomes c, then both v and u are c -> conflict.
                    # Therefore, we can only perform the swap if the component does NOT contain any neighbor of v that is colored target_color.
                    # Equivalent: in the component, v is the only vertex colored target_color? 
                    # More precisely, we require that no neighbor of v in the component has color target_color (because after swap they would become c and conflict with v's new color c).
                    # But note: v itself is in the component and is target_color, but we don't consider v as its own neighbor.
                    has_target_color_neighbor = False
                    for u in component:
                        if u != v and current[u] == target_color and u in neighbors[v]:
                            has_target_color_neighbor = True
                            break
                    if not has_target_color_neighbor:
                        # perform swap
                        for node in component:
                            if current[node] == c:
                                current[node] = target_color
                            else:  # must be target_color
                                current[node] = c
                        improved = True
                        break
                if improved:
                    break
            # if we made a change, we might have emptied the target color class; compact colors
            if improved:
                current = normalize_colors(current)
        return current

    # ---------- Main heuristic selection ----------
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # List of heuristics to try
    heuristics = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last)
    ]

    for name, heuristic in heuristics:
        if time.time() - start_time > 0.04:  # leave time for Kempe
            break
        coloring = heuristic()
        if not is_valid_coloring(coloring):
            continue
        k = count_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]

    # If no heuristic produced a valid coloring (should not happen), fallback to greedy
    if best_coloring is None:
        # simple greedy ordering by degree
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize_colors(coloring)

    # Apply Kempe chain reduction if time permits
    if time.time() - start_time < 0.045:
        best_coloring = kempe_reduce(best_coloring)
        # final validation and normalization
        if not is_valid_coloring(best_coloring):
            # fallback should not happen, but just in case
            best_coloring = [0] * n
        else:
            best_coloring = normalize_colors(best_coloring)

    return best_coloring

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Determine input type: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute bit masks
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Precompute bit masks for adjacency (undirected graph assumed)
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize_coloring(coloring):
        if not coloring:
            return coloring
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        normalized = [0] * n
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            normalized[i] = unique_colors[c]
        return normalized

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return [0] * n
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # degree in the uncolored subgraph (initially full degree)
        degree_uncolored = [len(adj_list[i]) for i in range(n)]
        uncolored_count = n

        for _ in range(n):
            # Select uncolored vertex with max saturation, then max degree_uncolored
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    if saturation[u] > max_sat or (saturation[u] == max_sat and degree_uncolored[u] > max_deg):
                        max_sat = saturation[u]
                        max_deg = degree_uncolored[u]
                        v = u
                    elif saturation[u] == max_sat and degree_uncolored[u] == max_deg:
                        # Tie-break by vertex index (lower index preferred for determinism, but random is also ok)
                        if v == -1 or u < v:
                            v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color for v
            neighbor_colors = 0
            for w in adj_list[v]:
                if coloring[w] != -1:
                    neighbor_colors |= (1 << coloring[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation and degree_uncolored for neighbors
            for w in adj_list[v]:
                if coloring[w] == -1:
                    # Update saturation: if color c is new in w's neighbors
                    # We can't easily track distinct colors without a set, but we can approximate by checking if this is the first time color c appears?
