            v = max(uncolored, key=lambda x: (sat[x], sum(1 for nb in adj_list[x] if nb in uncolored)))
            # Compute used colors by neighbors
            used = 0
            for nb in adj_list[v]:
                c = color[nb]
                if c != -1:
                    used |= 1 << c
            # Find smallest available color
