def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        # Adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if coloring[u] == coloring[v]:
                        return False
        return True

    # Strategy 1: Welsh-Powell (degree descending)
    order_wp = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
    best_color = greedy_color(order_wp)
    best_k = count_colors(best_color)

    # Strategy 2: Smallest-Last ordering
    degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
    remaining = set(range(n))
    order_sl = []
    while remaining:
        min_deg = n + 1
        v_min = -1
        for v in remaining:
            deg_in_remaining = bin(bit_adj[v] & sum((1 << u) for u in remaining)).count('1')
            if deg_in_remaining < min_deg:
                min_deg = deg_in_remaining
                v_min = v
        order_sl.append(v_min)
        remaining.remove(v_min)
    order_sl.reverse()
    color_sl = greedy_color(order_sl)
    k_sl = count_colors(color_sl)
    if k_sl < best_k:
        best_k = k_sl
        best_color = color_sl[:]

    # Strategy 3: DSATUR with degree tie-breaking
    color_ds = [-1] * n
    sat = [0] * n
    uncolored = set(range(n))
    for _ in range(n):
        if not uncolored:
            break
        max_sat = -1
        candidates = []
        for v in uncolored:
            if sat[v] > max_sat:
                max_sat = sat[v]
                candidates = [v]
            elif sat[v] == max_sat:
                candidates.append(v)
        if max_sat == -1:
            v = next(iter(uncolored))
        else:
            # Tie-break by degree in uncolored subgraph
            max_deg = -1
            for v in candidates:
                deg_in_uncolored = bin(bit_adj[v] & sum((1 << u) for u in uncolored)).count('1')
                if deg_in_uncolored > max_deg:
                    max_deg = deg_in_uncolored
                    v = v
        # Assign smallest available color
        used = 0
        for u in range(n):
            if (bit_adj[v] >> u) & 1 and color_ds[u] != -1:
                used |= (1 << color_ds[u])
        c = 0
        while used & (1 << c):
            c += 1
        color_ds[v] = c
        uncolored.remove(v)
        # Update saturation of neighbors
        for u in range(n):
            if (bit_adj[v] >> u) & 1 and u in uncolored:
                sat[u] = bin(used & ((1 << (max(sat[u], c + 1)) - 1))).count('1') if used else 0
                # Simpler: just increment if new color
                if ((used >> color_ds[u]) & 1) == 0:  # This is not quite right, but we'll recalc properly below
                    pass
        # Recalculate saturation for all uncolored vertices (simple but safe)
        for u in uncolored:
            neighbor_colors = 0
            for w in range(n):
                if (bit_adj[u] >> w) & 1 and color_ds[w] != -1:
                    neighbor_colors |= (1 << color_ds[w])
            sat[u] = bin(neighbor_colors).count('1')
    k_ds = count_colors(color_ds)
    if k_ds < best_k and is_valid(color_ds):
        best_k = k_ds
        best_color = color_ds[:]

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        nonlocal best_k
        k = count_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, 0, -1):
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                continue
            made_progress = True
            while made_progress and vertices:
                made_progress = False
                v = vertices.pop()
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    conflict = False
                    for u in range(n):
                        if (bit_adj[v] >> u) & 1 and coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        made_progress = True
                        break
                if made_progress:
                    continue
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find the (target_color, c)-Kempe chain containing v
                    visited = [False] * n
                    stack = [v]
                    component = []
                    while stack:
                        node = stack.pop()
                        if visited[node]:
                            continue
                        if coloring[node] not in (target_color, c):
                            continue
                        visited[node] = True
                        component.append(node)
                        for w in range(n):
                            if (bit_adj[node] >> w) & 1 and not visited[w]:
                                stack.append(w)
                    # Check if inverting this component would free color c for v
                    # Actually, we want to see if after swap, v can take color c
                    # In the component, target_color <-> c are swapped
                    # After swap, v (originally target_color) becomes c
                    # We need to ensure no neighbor of v has color c after swap
                    # Neighbors of v that are in the component and were c become target_color -> safe
                    # Neighbors of v that are in the component and were target_color become c -> conflict if they are adjacent to v?
                    # Actually, after swap, we only care: does any neighbor of v have color c?
                    # Original neighbors with color c: if in component, they become target_color -> no longer c
                    # Original neighbors with color c: if not in component, they remain c -> conflict
                    # Original neighbors with color target_color: if in component, they become c -> conflict
                    # So we need: no neighbor of v that is not in the component has color c, and
                    # no neighbor of v that is in the component has color target_color (because they become c)
                    safe = True
                    for u in range(n):
                        if (bit_adj[v] >> u) & 1:
                            if coloring[u] == c and u not in component:
                                safe = False
                                break
                            if coloring[u] == target_color and u in component:
                                safe = False
                                break
                    if safe:
                        # Perform the swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        made_progress = True
                        break
                if made_progress:
                    # Rebuild vertices list for this target_color
                    vertices = [v for v in range(n) if coloring[v] == target_color]
            # After trying to eliminate target_color, check if it's gone
            if any(coloring[v] == target_color for v in range(n)):
                # Could not eliminate this color, move to next lower target
                continue
            else:
                # Eliminated target_color, compact colors above it
                max_color = max(coloring)
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                # Recurse with possibly lower k
                return kempe_reduce(coloring)
        return coloring

    # Apply Kempe reduction to the best coloring found
    final_coloring = kempe_reduce(best_color[:])

    # Ensure validity and compactness
    if not is_valid(final_coloring):
        # Fallback to best known valid coloring
        final_coloring = best_color
    # Compact colors to be 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = final_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        final_coloring[i] = unique_colors[c]

    return final_coloring

