    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Remove self-loops if any and deduplicate
    for i in range(n):
        if i in neighbors[i]:
            neighbors[i].remove(i)
            bit_adj[i] &= ~(1 << i)
        # Deduplicate neighbors list (though input should be clean)
        seen = set()
        unique_neighbors = []
        for nb in neighbors[i]:
            if nb not in seen:
                seen.add(nb)
                unique_neighbors.append(nb)
        neighbors[i] = unique_neighbors

    # Degeneracy ordering for initial upper bound
    def degeneracy_ordering():
        if n == 0:
            return []
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]  # max degree is n-1
        for i in range(n):
            if deg[i] < n:
                buckets[deg[i]].append(i)
        min_deg = 0
        for _ in range(n):
            while min_deg < n and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break  # should not happen
            v = buckets[min_deg].pop()
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    d = deg[u]
                    if d < n:
                        buckets[d].remove(u)
                    deg[u] -= 1
                    if deg[u] < n:
                        buckets[deg[u]].append(u)
                    if deg[u] < min_deg:
                        min_deg = deg[u]
        return order

    order = degeneracy_ordering()
    color = [-1] * n
    # Color in reverse degeneracy order
    for v in reversed(order):
        used = [False] * (n + 1)  # n+1 to be safe
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c <= n and used[c]:
            c += 1
        color[v] = c
