                    for neighbor in range(n):
                        if (bit_adj[node] >> neighbor) & 1 and not visited[neighbor]:
                            if best[neighbor] == c or best[neighbor] == k - 1:
                                visited[neighbor] = True
                                queue.append(neighbor)
                # Swap colors c and k-1 in this component
                for node in component:
                    if best[node] == c:
                        best[node] = k - 1
                    elif best[node] == k - 1:
                        best[node] = c
                # Check if v is no longer color k-1 (i.e., it was swapped to c)
                if best[v] != k - 1:
                    # Validate
                    if is_valid_coloring(best):
                        improved = True
                        break
                    else:
                        # Swap back
                        for node in component:
                            if best[node] == c:
                                best[node] = k - 1
                            elif best[node] == k - 1:
                                best[node] = c
                # If not improved, swap back and try next
                if not improved:
                    for node in component:
                        if best[node] == c:
                            best[node] = k - 1
                        elif best[node] == k - 1:
                            best[node] = c
            if improved:
                break
        if improved:
            # After successful recoloring, check if color k-1 is now empty
            if any(best[v] == k - 1 for v in range(n)):
                k = count_colors(best)  # Recompute k
            else:
                k -= 1
                # Reindex colors
                mapping = {}
                new_color = 0
                for old in sorted(set(best)):
                    mapping[old] = new_color
                    new_color += 1
                best = [mapping[c] for c in best]
        else:
            break

    # Final validation and reindexing to ensure consecutive colors
    if not is_valid_coloring(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
        if not is_valid_coloring(best):
            # Ultimate fallback: greedy on Welsh-Powell
            best = greedy_color(welsh_powell_order())
    # Reindex to consecutive
    unique_colors = sorted(set(best))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best = [mapping[c] for c in best]

    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect input type: adjacency matrix or adjacency list
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        adj_list = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        # Adjacency list
        adj_list = adj

    # Convert adjacency list to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree
        uncolored = set(range(n))
        # Initial: all uncolored, sat=0
        while uncolored:
            # Select vertex with max sat, tie-break by degree in uncolored subgraph, then random
            v = max(uncolored, key=lambda x: (sat[x], sum(1 for u in adj_list[x] if u in uncolored), random.random()))
            # Assign smallest available color
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in adj_list[x] if u in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v} - {u for u in adj_list[v] if u in uncolored}
            W = {u for u in adj_list[v] if u in uncolored}
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                u = max(U, key=lambda x: (sum(1 for w in adj_list[x] if w in W), -sum(1 for w in adj_list[x] if w in U), random.random()))
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Helper: Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # We'll use a list of sets for buckets by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].add(v)
        # Pointer to current min degree
        d = 0
        while remaining:
            # Find non-empty bucket with smallest d
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # move u from bucket[deg[u]] to bucket[deg[u]-1]
                    buckets[deg[u]].remove(u)
                    deg[u] -= 1
                    if deg[u] < len(buckets):
                        buckets[deg[u]].add(u)
                    else:
                        # should not happen as deg[u] decreases
                        pass
            # d might need to be adjusted, but we'll find it in next iteration
        # Color in reverse order
        return greedy_color(reversed(order))

    # Generate candidate colorings
    candidates = []
    try:
        candidates.append(dsatur())
    except:
        pass
    try:
        candidates.append(rlf())
    except:
        pass
    try:
        candidates.append(smallest_last())
    except:
        pass
    # Also try greedy by degree descending
    try:
        order_deg = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        candidates.append(greedy_color(order_deg))
    except:
        pass
    # And greedy by degree ascending
    try:
        order_deg_asc = sorted(range(n), key=lambda x: len(adj_list[x]))
        candidates.append(greedy_color(order_deg_asc))
    except:
        pass

    # Select the candidate with the fewest colors
    best_color = None
    best_k = float('inf')
    for col in candidates:
        if col is None:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col

    if best_color is None:
        # Fallback: trivial coloring
        best_color = list(range(n))
        best_k = n

    # Function to count color classes
    def color_class_sizes(coloring):
        if n == 0:
            return []
        max_col = max(coloring)
        sizes = [0] * (max_col + 1)
        for c in coloring:
            sizes[c] += 1
        return sizes

    # Kempe chain based color reduction
    def try_reduce_color(coloring):
        # Make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Determine current number of colors
            if n == 0:
                return col
            max_color = max(col)
            # Try to eliminate color classes from highest downward
            for target_color in range(max_color, 0, -1):
                # Build list of vertices with this color
                target_vertices = [v for v in range(n) if col[v] == target_color]
                if not target_vertices:
                    continue  # already empty, should not happen
                # Try to recolor each target vertex to a lower color
                made_progress = False
                for v in target_vertices:
                    used = 0
                    for u in adj_list[v]:
                        if col[u] != -1:
                            used |= (1 << col[u])
                    # Find smallest available color < target_color
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            # Direct reassignment possible
                            col[v] = c
                            changed = True
                            made_progress = True
                            break
                    if made_progress:
                        break  # restart scan as coloring changed
                if made_progress:
                    continue  # restart the color loop from high to low
                # If direct reassignment failed for all, try Kempe chains
                for v in target_vertices:
                    used = 0
                    for u in adj_list[v]:
                        if col[u] != -1:
                            used |= (1 << col[u])
                    # For each lower color c, try to swap via Kempe chain
                    for c in range(target_color):
                        if used & (1 << c):
                            # c is used by a neighbor, so we consider Kempe chain (c, target_color)
                            # Find the Kempe chain component containing v in colors c and target_color
                            # We'll do BFS/DFS over vertices colored c or target_color
                            stack = [v]
                            visited = set()
                            component = set()
                            while stack:
                                node = stack.pop()
                                if node in visited:
                                    continue
                                visited.add(node)
                                if col[node] == c or col[node] == target_color:
                                    component.add(node)
                                    for nb in adj_list[node]:
                                        if col[nb] == c or col[nb] == target_color:
                                            if nb not in visited:
                                                stack.append(nb)
                            # Check if any neighbor of v in the component has color c? Actually, we want to see if we can swap
                            # After swap, v would get color c. We need to ensure that no neighbor of v has color c after swap.
                            # Currently, neighbors of v have colors in 'used'. After swap, vertices in component that were c become target_color and vice versa.
                            # So for a neighbor u of v:
                            #   if u in component: its color flips (c<->target_color)
                            #   else: color unchanged
                            # We need that after swap, no neighbor of v has color c.
                            # Let's compute the set of colors on neighbors of v after swap.
                            conflict = False
                            for u in adj_list[v]:
                                if u in component:
                                    # color flips
                                    new_col = target_color if col[u] == c else c
                                else:
                                    new_col = col[u]
                                if new_col == c:
                                    conflict = True
                                    break
                            if not conflict:
                                # Perform the swap
                                for node in component:
                                    if col[node] == c:
                                        col[node] = target_color
                                    else:
                                        col[node] = c
                                changed = True
                                made_progress = True
                                break
                    if made_progress:
                        break
                if made_progress:
                    break  # restart the color loop
            # If we made any progress, we continue the while loop to try again
        return col

    # Apply color reduction
    best_color = try_reduce_color(best_color)

    # Compact colors to be 0..k-1
    if n == 0:
        return []
    # Map existing colors to consecutive integers
    unique_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best_color = [mapping[c] for c in best_color]

    # Final validation (optional, but ensures correctness)
    # for u in range(n):
    #     for v in adj_list[u]:
    #         if best_color[u] == best_color[v]:
    #             # In case of error, fallback to greedy
    #             return greedy_color(list(range(n)))

    return best_color

import math
