def color_graph(adj: list[list[int]]) -> list[int]:
    # Convert input to adjacency list
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]
    # Determine if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = [list(neighbors) for neighbors in adj]

    # Helper: check if coloring is valid
    def is_valid_coloring(col):
        for u in range(n):
            for v in graph[u]:
                if u < v and col[u] == col[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(col):
        if not col:
            return 0
        return max(col) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(col):
        if not col:
            return col
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]

    # DSATUR with bitmask optimization
    def dsatur():
        if n == 0:
            return []
        # Build bitmask adjacency
        bit_adj = [0] * n
        for u in range(n):
            mask = 0
            for v in graph[u]:
                mask |= (1 << v)
            bit_adj[u] = mask
        color = [-1] * n
        # saturation: bitmask of colors in neighbors
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                if s > best_sat:
                    best_sat = s
                    best_v = v
                    best_deg = sum(1 for u in graph[v] if u in uncolored)
                elif s == best_sat:
                    deg = sum(1 for u in graph[v] if u in uncolored)
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
                    elif deg == best_deg:
                        if random.random() < 0.5:
                            best_v = v
            v = best_v
            # compute available colors: smallest non-negative not in neighbor colors
            neighbor_colors = sat[v]
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in graph[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # RLF (Recursive Largest First) with bitmask optimization
    def rlf():
        if n == 0:
            return []
        # Build bitmask adjacency
        bit_adj = [0] * n
        for u in range(n):
            mask = 0
            for v in graph[u]:
                mask |= (1 << v)
            bit_adj[u] = mask
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0
        while uncolored:
            # Build independent set for current_color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            S.add(v)
            # Partition uncolored - {v} into U (not adjacent to S) and W (adjacent to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                # check if u is adjacent to any in S
                adj_to_S = False
                for w in S:
                    if u in graph[w]:
                        adj_to_S = True
                        break
                if adj_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # while U not empty, add vertices to S
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    # count neighbors in W
                    cnt = 0
                    for w in graph[u]:
                        if w in W:
                            cnt += 1
                    # tie-break: min degree in G[U]
                    deg_U = sum(1 for w in graph[u] if w in U)
                    if cnt > best_score:
                        best_score = cnt
                        best_u = u
                        best_deg_U = deg_U
                    elif cnt == best_score:
                        if deg_U < best_deg_U:
                            best_deg_U = deg_U
                            best_u = u
                        elif deg_U == best_deg_U:
                            if random.random() < 0.5:
                                best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u that are in U to W
                for w in graph[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for v in S:
                color[v] = current_color
            uncolored -= S
            current_color += 1
        return color

    # Smallest-Last ordering greedy
    def smallest_last():
        if n == 0:
            return []
        # Build adjacency as list of sets for fast removal
        adj_set = [set(graph[u]) for u in range(n)]
        # Compute degeneracy ordering (smallest-last)
        order = []
        remaining = set(range(n))
        degrees = [len(adj_set[u]) for u in range(n)]
        # Use bucket queue for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for u in range(n):
            d = degrees[u]
            buckets[d].add(u)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in adj_set[v]:
                if u in remaining:
                    d = degrees[u]
                    buckets[d].remove(u)
                    degrees[u] -= 1
                    d_new = degrees[u]
                    buckets[d_new].add(u)
            # adjust ptr if needed
            if ptr > degrees[v]:
                ptr = degrees[v]
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)  # enough space
            for u in graph[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
        return color

    # Kempe chain elimination to reduce colors
    def kempe_reduce(color_in):
        color = color_in[:]
        if n == 0:
            return color
        changed = True
        while changed:
            changed = False
            k = num_colors(color)
            if k <= 1:
                break
            # find smallest color class (by index, but we target highest color for removal)
            # target the highest color to try to eliminate
            target_color = k - 1
            vertices = [v for v in range(n) if color[v] == target_color]
            if not vertices:
                # should not happen, but safety
                break
            # Try to recolor each vertex in target_color
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in graph[v]:
                    if color[u] != -1:
                        neighbor_colors.add(color[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        color[v] = c
                        changed = True
                        break
                if changed:
                    # after recoloring v, we may have emptied target_color; break to recompute
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # BFS to find the (target_color, c)-Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in graph[x]:
                            if not visited[y] and (color[y] == target_color or color[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # Check if any vertex in component colored c has no neighbor in target_color outside component
                    # Actually, we can swap if the component does not contain all vertices of color c that are adjacent to target_color?
                    # Simpler: after swap, check if target_color is still used elsewhere; if not, we can reduce.
                    # We'll perform swap and see if target_color disappears from the coloring.
                    # Swap colors in component
                    for x in component:
                        if color[x] == target_color:
                            color[x] = c
                        elif color[x] == c:
                            color[x] = target_color
                    # Check if target_color is still used
                    if target_color not in color:
                        changed = True
                        break  # break out of color loop
                    else:
                        # swap back
                        for x in component:
                            if color[x] == target_color:
                                color[x] = c
                            elif color[x] == c:
                                color[x] = target_color
                if changed:
                    break
            if changed:
                # normalize colors to fill gaps
                color = normalize(color)
        return color

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(normalize(c1))
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(normalize(c2))
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(normalize(c3))
    except Exception:
        pass
    # If no candidates, fallback to trivial greedy
    if not candidates:
        color = [-1] * n
        for u in range(n):
            used = [False] * (n + 1)
            for v in graph[u]:
                if color[v] != -1:
                    used[color[v]] = True
            c = 0
            while used[c]:
                c += 1
            color[u] = c
        candidates.append(normalize(color))
    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and normalization
    if not is_valid_coloring(best):
        # fallback to DSATUR if something went wrong
        best = dsatur()
        best = normalize(best)
    return best

