                for u in adj_list[v]:
                    c_u = coloring[u]
                    if c_u < k:
                        neighbor_colors.add(c_u)
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Assign v to color c
                        coloring[v] = c
                        color_classes[target_color].remove(v)
                        color_classes[c].append(v)
                        moved[v] = True
                        break
                if moved[v]:
                    continue
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    if moved[v]:
                        break
                    # Build the (c, target_color) Kempe chain containing v
                    # Only consider vertices with color c or target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if swapping this component is safe: no neighbor of any node in component
                    # has color c (outside the component) that would cause conflict after swap
                    # Actually, after swap, nodes in component that were c become target_color and vice versa.
                    # We need to ensure that after swap, no adjacent nodes have same color.
                    # Since we only swap within the component, and the component is connected via alternating colors,
                    # the only potential conflict is if a node in the component has a neighbor outside
                    # the component that has the same color as what it will become after swap.
                    # For a node currently colored c: after swap becomes target_color. Its neighbors outside
                    # the component must not be target_color.
                    # For a node currently colored target_color: after swap becomes c. Its neighbors outside
                    # the component must not be c.
                    safe = True
                    for node in component:
                        col = coloring[node]
                        new_col = c if col == target_color else target_color
                        for nb in adj_list[node]:
                            if not visited[nb]:  # neighbor outside component
                                if coloring[nb] == new_col:
                                    safe = False
                                    break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            else:  # must be target_color
                                coloring[node] = c
                        # Update color_classes
                        # We'll rebuild color_classes for simplicity since k is small
                        # Rebuild color_classes from scratch
                        color_classes = [[] for _ in range(k)]
                        for ii in range(n):
                            c_i = coloring[ii]
                            if c_i < k:
                                color_classes[c_i].append(ii)
