                        moved[v] = True
                        break  # break from c loop, go to next v
            # If we managed to empty the target_color class, we can try to reduce k
            if not color_classes[target_color]:
                # Compact colors: shift down higher colors
                new_coloring = [-1] * n
                color_map = {}
                new_color = 0
                for old_color in range(k):
                    if color_classes[old_color]:
                        color_map[old_color] = new_color
                        new_color += 1
                for v in range(n):
                    if coloring[v] != -1:
                        new_coloring[v] = color_map[coloring[v]]
                # Recurse with new k
                return kempe_reduce(new_coloring, new_color)
        return coloring

    # Heuristic 1: DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: list of sets of neighbor colors for each vertex
        saturation = [set() for _ in range(n)]
        colored = [False] * n
        # Select first vertex: highest degree
        v = max(range(n), key=lambda x: degrees[x])
        coloring[v] = 0
        colored[v] = True
        # Update saturation of neighbors
        for nb in adj_list[v]:
            saturation[nb].add(0)
        # Color remaining n-1 vertices
        for _ in range(n-1):
            # Select uncolored vertex with max saturation degree, tie-break by degree, then random
            candidates = []
            max_sat = -1
            for v in range(n):
                if not colored[v]:
                    sat = len(saturation[v])
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
            if not candidates:
                break  # should not happen
            # Tie-break: max degree in uncolored subgraph
            # Compute degree in uncolored subgraph: number of uncolored neighbors
            def uncolored_degree(v):
                return sum(1 for nb in adj_list[v] if not colored[nb])
            v = max(candidates, key=lambda x: (uncolored_degree(x), degrees[x], random.random()))
            # Find smallest available color
            used_colors = set()
            for nb in adj_list[v]:
                if colored[nb]:
                    used_colors.add(coloring[nb])
            c = 0
            while c in used_colors:
                c += 1
            coloring[v] = c
            colored[v] = True
            # Update saturation of neighbors
            for nb in adj_list[v]:
                if not colored[nb]:
                    saturation[nb].add(c)
        return coloring

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        colored = [False] * n
        color = 0
        # While there are uncolored vertices
        while any(not c for c in colored):
            # Step 1: choose vertex with max degree in uncolored subgraph
            uncolored = [v for v in range(n) if not colored[v]]
            if not uncolored:
                break
            # degree in induced subgraph of uncolored
            def deg_in_uncolored(v):
                return sum(1 for nb in adj_list[v] if not colored[nb])
            v = max(uncolored, key=deg_in_uncolored)
            # Start independent set S with v
            S = [v]
            colored[v] = True
            # Partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(nb in S for nb in adj_list[u]):  # actually, since S has only v initially, check adj to v
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                def weight(u):
                    return sum(1 for nb in adj_list[u] if nb in W)
                # Tie-break: min degree in G[U]
                def deg_in_U(u):
                    return sum(1 for nb in adj_list[u] if nb in U)
                u_star = max(U, key=lambda x: (weight(x), -deg_in_U(x), random.random()))
                S.append(u_star)
                colored[u_star] = True
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for nb in adj_list[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
        return coloring

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        # We'll work on a copy of degrees and adjacency
        deg = degrees[:]  # current degrees
        # adj_list is static, but we need to know which vertices are removed
        removed = [False] * n
        order = []  # will store removal order (first removed first)
        # We need to update degrees when a vertex is removed
        # Use bucket sort for efficiency (since n <= 100, we can do O(n^2))
        for _ in range(n):
            # Find vertex with min degree among non-removed
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    deg[nb] -= 1
        # Color in reverse order
        coloring = [-1] * n
        # For each vertex in reverse removal order, assign smallest available color
        for v in reversed(order):
            used = set()
            for nb in adj_list[v]:
                if coloring[nb] != -1:  # already colored (since we go in reverse, neighbors colored later in removal are colored earlier in this loop)
                    used.add(coloring[nb])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        return coloring

    # Run heuristics
    start_time = time.time()
    time_limit = 0.04  # 40ms to leave room for Kempe and validation

    # DSATUR
    if time.time() - start_time < time_limit:
        col1 = dsatur()
        k1 = validate_and_get_k(col1)
        if k1 is not None and k1 < best_k:
            best_k = k1
            best_coloring = col1[:]

    # RLF
    if time.time() - start_time < time_limit:
        col2 = rlf()
        k2 = validate_and_get_k(col2)
        if k2 is not None and k2 < best_k:
            best_k = k2
            best_coloring = col2[:]

    # Smallest-Last
    if time.time() - start_time < time_limit:
        col3 = smallest_last()
        k3 = validate_and_get_k(col3)
        if k3 is not None and k3 < best_k:
            best_k = k3
            best_coloring = col3[:]

    # If no heuristic produced a valid coloring (should not happen), fallback to greedy
    if best_coloring is None:
        # Simple greedy in vertex order
        coloring = [-1] * n
        for v in range(n):
            used = set()
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used.add(coloring[nb])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best_coloring = coloring
        best_k = validate_and_get_k(best_coloring)

    # Apply Kempe chain reduction to try to reduce number of colors
    if best_k > 0 and time.time() - start_time < time_limit:
        # Make a copy to work on
        improved = kempe_reduce(best_coloring[:], best_k)
        k_improved = validate_and_get_k(improved)
        if k_improved is not None and k_improved < best_k:
            best_k = k_improved
            best_coloring = improved

    # Final validation and compact colors to 0..k-1
    if best_coloring is None:
        # Should not happen, but just in case
        best_coloring = list(range(n))

    # Compact colors: remap to consecutive integers starting from 0
    unique_colors = {}
    next_color = 0
    for v in range(n):
        c = best_coloring[v]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_coloring[v] = unique_colors[c]

    # Ensure we return list of ints
    return best_coloring

