import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build neighbor lists and bitmasks
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            neighbors[i] = set(adj[i])

    # Build bitmasks for fast operations
    bit_adj = [0] * n
    for i in range(n):
        for j in neighbors[i]:
            bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        uncolored = set(range(n))
        # degrees in uncolored subgraph
        deg_uncolored = [len(neighbors[i]) for i in range(n)]

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored, then random
            v = max(uncolored, key=lambda x: (sat[x].bit_count(), deg_uncolored[x], random.random()))
            # Find smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation and degrees for neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # degree in current uncolored subgraph
            deg = {v: len([u for u in neighbors[v] if u in uncolored]) for v in uncolored}
            S = set()
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: (deg[x], random.random()))
            S.add(v)
            # U: vertices not adjacent to S, W: vertices adjacent to S
            U = {u for u in uncolored if u not in S and not any(w in neighbors[u] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in U
                def score(u):
                    n_in_W = len([w for w in neighbors[u] if w in W])
                    deg_U = len([w for w in neighbors[u] if w in U])
                    return (n_in_W, -deg_U)
                u = max(U, key=score)
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].add(v)
        # peel min degree
        for _ in range(n):
            # find first non-empty bucket
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
            if i > max_deg:
                break
            v = buckets[i].pop()
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = deg[u]
                    deg[u] -= 1
                    buckets[old_deg].remove(u)
                    buckets[deg[u]].add(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-len(neighbors[x]), random.random()))
        return greedy_color(order)

    # Generate candidate colorings
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        coloring = func()
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]

    # If no coloring found (should not happen), fall back to Welsh-Powell
    if best_coloring is None:
        best_coloring = welsh_powell()
        best_k = num_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find color classes
            classes = {}
            for v in range(n):
                c = col[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            # Try to eliminate highest color classes first
            colors = sorted(classes.keys(), reverse=True)
            for target_color in colors:
                if target_color == 0:
                    continue
                # Try to recolor each vertex in target_color
                for v in classes[target_color]:
                    used_by_neighbors = 0
                    for u in neighbors[v]:
                        used_by_neighbors |= (1 << col[u])
                    # Try direct reassignment to a lower color
                    for c in range(target_color):
                        if not (used_by_neighbors & (1 << c)):
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chains with each lower color
                    for c in range(target_color):
                        # If v already has color c from direct reassignment above, skip
                        if col[v] == c:
                            continue
                        # Find the Kempe chain component of v for colors (target_color, c)
                        # BFS to get component
                        from collections import deque
                        comp = []
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        while queue:
                            node = queue.popleft()
                            comp.append(node)
                            for nb in neighbors[node]:
                                if not visited[nb] and (col[nb] == target_color or col[nb] == c):
                                    visited[nb] = True
                                    queue.append(nb)
                        # Check if we can swap: after swap, v would get color c
                        # We need to ensure no neighbor of v has color c after swap
                        # Actually, swapping the component means: target_color <-> c in comp
                        # So v (currently target_color) becomes c
                        # Check if any neighbor of v has color c and is NOT in comp (would become target_color and conflict)
                        can_swap = True
                        for nb in neighbors[v]:
                            if col[nb] == c and nb not in comp:
                                can_swap = False
                                break
                        if can_swap:
                            # Perform swap
                            for node in comp:
                                if col[node] == target_color:
                                    col[node] = c
                                else:  # must be c
                                    col[node] = target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # If changed, rebuild classes and continue; else break
            if not changed:
                break
        # Compact colors to 0..k-1
        # Map used colors to consecutive integers
        used_colors = sorted(set(col))
        mapping = {old: new for new, old in enumerate(used_colors)}
        col = [mapping[c] for c in col]
        return col

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)

    # Final validation (optional, but safe)
    # Ensure proper coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Fallback to greedy if invalid (should not happen)
                return welsh_powell()

    return best_coloring

