def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True
    # Build neighbor list and bitmask representation
    if is_matrix:
        neighbors = [[j for j in range(n) if adj[i][j]] for i in range(n)]
    else:
        neighbors = [list(lst) for lst in adj]
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= 1 << j
        bit_adj[i] = mask

    # DSATUR heuristic
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # Choose vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], sum(1 for nb in neighbors[x] if nb in uncolored)))
            # Determine available colors
            used = 0
            for nb in neighbors[v]:
                c = color[nb]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for nb in neighbors[v]:
                if nb in uncolored:
                    sat[nb] += 1
        return color

    # RLF heuristic
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            indep = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in neighbors[x] if nb in uncolored))
            indep.add(v)
            # Partition remaining uncolored into U (eligible) and W (ineligible)
            U = uncolored - {v}
            W = set()
            for nb in neighbors[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
            # Greedily add vertices from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (sum(1 for nb in neighbors[x] if nb in W), -sum(1 for nb in neighbors[x] if nb in U)))
                indep.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to independent set
            for v in indep:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering via repeated removal of min degree vertex
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # Use buckets for efficiency (max degree <= n-1)
        max_deg = n - 1
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            for nb in neighbors[v]:
                if not removed[nb]:
                    d = deg[nb]
                    if d > 0:
                        deg[nb] -= 1
                        buckets[d].remove(nb)
                        buckets[d-1].append(nb)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in neighbors[v]:
                c = color[nb]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate coloring
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col[:]
    if best_color is None:
        # Fallback: greedy by vertex index
        best_color = [0] * n
        for i in range(n):
            used = 0
            for nb in neighbors[i]:
                c = best_color[nb]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            best_color[i] = c
        best_k = max(best_color) + 1 if n > 0 else 0

    # Kempe chain color reduction
    def kempe_reduction(color):
        nonlocal n, neighbors, bit_adj
        # Helper: get vertices of a color
        def color_class(c):
            return [i for i in range(n) if color[i] == c]
        # Helper: check if moving v to color c is valid
        def can_move(v, c):
            for nb in neighbors[v]:
                if color[nb] == c:
                    return False
            return True
        # Helper: perform Kempe swap on component of v with colors c1 and c2
        def kempe_swap(v, c1, c2):
            if color[v] not in (c1, c2):
                return False
            stack = [v]
            visited = set()
            comp = []
            while stack:
                u = stack.pop()
                if u in visited:
                    continue
                visited.add(u)
                if color[u] in (c1, c2):
                    comp.append(u)
                    for nb in neighbors[u]:
                        if nb not in visited and color[nb] in (c1, c2):
                            stack.append(nb)
            # Invert colors in component
            for u in comp:
                color[u] = c1 if color[u] == c2 else c2
            return True

        k = max(color) + 1 if n > 0 else 0
        improved = True
        while improved and k > 0:
            improved = False
            # Target smallest color class (k-1)
            target = k - 1
            target_vertices = color_class(target)
            if not target_vertices:
                # Should not happen, but skip
                k -= 1
                continue
            # Try to recolor each target vertex
            for v in target_vertices[:]:  # iterate over copy
                # Try direct reassignment to a lower color
                for c in range(target):
                    if can_move(v, c):
                        color[v] = c
                        improved = True
                        break
                if improved:
                    # After moving v, check if target color class is empty
                    if not color_class(target):
                        k -= 1
                        improved = True
                        break
                    else:
                        # Reset for next iteration
                        improved = False
                else:
                    # Try Kempe chain swaps with each lower color
                    for c in range(target):
                        # Check if v is in a Kempe chain that can be swapped to free color c
                        # We need that in the component of v in colors {target, c}, there is no vertex of color c
                        # that would become target after swap and cause conflict? Actually, swap is safe.
                        # Perform swap and see if v can take color c
                        # Save current color
                        orig_color = color[v]
                        if kempe_swap(v, target, c):
                            # After swap, v now has color c (if it was target) or target (if it was c)
                            # We want v to be color c, so if it was target, it's now c; good.
                            # If it was c, it's now target, not what we want.
                            if color[v] == c:
                                improved = True
                                break
                            else:
                                # Swap didn't put v in c, revert
                                kempe_swap(v, target, c)  # revert
                        # else: swap not applicable (v not in {target,c}? but we checked)
                    if improved:
                        if not color_class(target):
                            k -= 1
                            improved = True
                            break
                        else:
                            improved = False
            # Compact colors if possible
            while k > 0 and not color_class(k-1):
                k -= 1
        # Ensure colors are consecutive
        remap = {}
        next_c = 0
        for i in range(n):
            c = color[i]
            if c not in remap:
                remap[c] = next_c
                next_c += 1
            color[i] = remap[c]
        return color

    best_color = kempe_reduction(best_color)
    return best_color

import math
