    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor colorsets as bitmask for fast saturation update
        neighbor_colors = [0] * n

        # degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # select uncolored vertex with max saturation, then max degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat_u = saturation[u]
                    deg_u = degrees[u]
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # update saturation and neighbor colors for uncolored neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:
                    # if this color is new in u's neighborhood
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return coloring

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            independent_set = []
            # candidate vertices that can be added to independent set
            # ineligible vertices (adjacent to independent set)
            ineligible = set()

            # start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
                independent_set.append(v)
                uncolored.remove(v)
                # add neighbors of v to ineligible
                for u in adj_list[v]:
                    if u in uncolored:
                        ineligible.add(u)

            # eligible vertices: uncolored and not ineligible
            eligible = uncolored - ineligible

            while eligible:
                # select u in eligible with max neighbors in ineligible
                # tie-break by min degree in eligible subgraph
                best_u = -1
                max_w_neighbors = -1
                min_deg_eligible = float('inf')
                for u in eligible:
                    # count neighbors in ineligible
                    w_count = 0
                    for w in adj_list[u]:
                        if w in ineligible:
                            w_count += 1
                    # degree in eligible subgraph
                    deg_eligible = 0
                    for w in adj_list[u]:
                        if w in eligible:
                            deg_eligible += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_eligible < min_deg_eligible):
                        max_w_neighbors = w_count
                        min_deg_eligible = deg_eligible
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                independent_set.append(best_u)
                uncolored.remove(best_u)
                # move best_u from eligible to ineligible? Actually, we remove it from uncolored
                # and add its uncolored neighbors to ineligible
                for u in adj_list[best_u]:
                    if u in uncolored:
                        ineligible.add(u)
                # update eligible: remove best_u and its neighbors that became ineligible
                eligible = uncolored - ineligible

            # assign color to independent set
            for v in independent_set:
                coloring[v] = color
            color += 1

        return coloring

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []  # will store removal order
        degrees = [len(adj_list[i]) for i in range(n)]
        # we need to update degrees as we remove vertices
        deg_copy = degrees[:]
        for _ in range(n):
            # find vertex with min degree in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if deg_copy[u] < min_deg:
                    min_deg = deg_copy[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    deg_copy[u] -= 1
