def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmasks
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for j in adj_list[i]:
                mask |= 1 << j
            bit_adj[i] = mask
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for j in adj_list[i]:
                mask |= 1 << j
            bit_adj[i] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = colors[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # Heuristic 1: DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturated[v]
                deg_v = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_v += 1
                if sat_v > best_sat or (sat_v == best_sat and deg_v > best_deg) or \
                   (sat_v == best_sat and deg_v == best_deg and v > best_v):
                    best_sat = sat_v
                    best_deg = deg_v
                    best_v = v

            v = best_v
            # Compute used colors by neighbors
            used = 0
            for u in adj_list[v]:
                c = colors[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u] += 1
            uncolored.remove(v)

        return compact_colors(colors)

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = {u for u in uncolored if u != v and not any(w in adj_list[u] for w in independent_set)}
            # W: vertices adjacent to at least one in independent_set
            W = {u for u in uncolored if u not in independent_set and u not in U}

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and u < best_u):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
            color_idx += 1
            uncolored -= independent_set

        return compact_colors(colors)

    # Heuristic 3: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering (smallest-last)
        degrees = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # We'll simulate removal
        temp_deg = degrees[:]
        for _ in range(n):
            # Find vertex with min temp_deg in remaining
            v = min(remaining, key=lambda x: temp_deg[x])
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    temp_deg[u] -= 1
        # Color in reverse order
        colors = greedy_color(order[::-1])
        return compact_colors(colors)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # Fallback: simple greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        c_fallback = greedy_color(order)
        if is_valid(c_fallback):
            candidates.append(compact_colors(c_fallback))
        else:
            # Last resort: assign each vertex a unique color
            candidates.append(list(range(n)))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)

    # Iterative Kempe chain color reduction
    def kempe_reduction(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                continue

            changed = True
            while changed and verts:
                changed = False
                # Try to recolor each vertex in this class
                new_verts = []
                for v in verts:
                    if colors[v] != target_color:  # might have been recolored
                        continue
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in adj_list[v]:
                        c = colors[u]
                        if c != -1:
                            used |= 1 << c
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            colors[v] = c
                            changed = True
                            break
                    if colors[v] == target_color:
                        new_verts.append(v)
                verts = new_verts

            # If still vertices in target_color, try Kempe chains
            if verts:
                for v in verts[:]:  # iterate over a copy
                    if colors[v] != target_color:
                        continue
                    # For each lower color, try Kempe chain swap
                    for c in range(target_color):
                        # Build the (target_color, c)-Kempe chain containing v
                        # Only if v is not already color c (it isn't, since it's target_color)
                        visited = set()
                        stack = [v]
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if colors[node] == target_color or colors[node] == c:
                                component.add(node)
                                for nb in adj_list[node]:
                                    if nb not in visited and (colors[nb] == target_color or colors[nb] == c):
                                        stack.append(nb)
                        # Check if swapping this component would free color c for v
                        # Actually, we want to see if after swap, v can be color c
                        # But note: v is in component and has color target_color, after swap it becomes c
                        # We need to ensure that no neighbor of v has color c after swap
                        # Neighbors of v that are in component: if they have color c, after swap they become target_color -> safe
                        # Neighbors of v that are not in component: their color doesn't change
                        # So we need to check: no neighbor of v has color c and is not in component
                        conflict = False
                        for nb in adj_list[v]:
                            if colors[nb] == c and nb not in component:
                                conflict = True
                                break
                        if not conflict:
                            # Perform swap
                            for node in component:
                                if colors[node] == target_color:
                                    colors[node] = c
                                else:  # must be c
                                    colors[node] = target_color
                            changed = True
                            break  # break color loop, go to next vertex
                    if colors[v] != target_color:
                        # Successfully recolored
                        pass
                # Recollect verts after Kempe attempts
                verts = [v for v in range(n) if colors[v] == target_color]

        # Compact colors again
        return compact_colors(colors)

    # Apply Kempe reduction
    best = kempe_reduction(best)

    # Final validation and compact
    if not is_valid(best):
        # Should not happen, but fallback to greedy
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best = greedy_color(order)
    best = compact_colors(best)

    return best

