    for heuristic in heuristics:
        # Check time
        if time.time() - start_time > 0.04:  # leave some margin
            break
        try:
            coloring = heuristic()
            if not is_valid_coloring(coloring):
                continue
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring
        except Exception:
            continue

    # If no heuristic produced valid coloring, fall back to DSATUR
    if best_coloring is None:
        best_coloring = dsatur()

    # Apply Kempe reduction if time permits
    if time.time() - start_time < 0.045:
        try:
            reduced = kempe_reduce(best_coloring)
            if is_valid_coloring(reduced):
                k_reduced = num_colors(reduced)
                if k_reduced < num_colors(best_coloring):
                    best_coloring = reduced
        except Exception:
            pass

    # Final validation and compacting
    if not is_valid_coloring(best_coloring):
        # Last resort: greedy by degree order
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        coloring = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best_coloring = compact_colors(coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Colors a graph using the smallest-last (degeneracy ordering) heuristic.
    This algorithm removes vertices in order of increasing degree (in the
    remaining subgraph), then colors them in reverse order using the
    smallest available color (First-Fit). The number of colors used is
    at most the degeneracy of the graph plus one.
    """
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for efficient access
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
    else:  # adjacency list
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    neighbors[u].add(v)

    # Handle isolated vertices: ensure neighbor sets are correct
    # (no self-loops assumed in input)
    for u in range(n):
        neighbors[u].discard(u)

    # Smallest-last ordering: repeatedly remove vertex of minimum degree
    remaining = set(range(n))
    order = []  # will store vertices in removal order (first removed first)
    degrees = [len(neighbors[u]) for u in range(n)]
    # Current degrees in the remaining subgraph
    curr_deg = degrees[:]

    # We will maintain the current degree of each vertex in the remaining graph
    # and update it as we remove vertices.
    # Since n <= 100, we can simply recompute or update naively.
    # Here we update: when a vertex is removed, decrease degree of its neighbors.
    for _ in range(n):
        # Find vertex in remaining with minimum current degree
        min_deg = math.inf
        v_min = -1
        for v in remaining:
            if curr_deg[v] < min_deg:
                min_deg = curr_deg[v]
                v_min = v
            # Tie-break: if same degree, choose the one with smaller index (arbitrary but deterministic)
            elif curr_deg[v] == min_deg and v < v_min:
                v_min = v
        if v_min == -1:
            # Should not happen if remaining is non-empty
            break
        # Remove v_min from remaining and add to order
        remaining.remove(v_min)
        order.append(v_min)
        # Update current degrees of its neighbors that are still remaining
        for nb in neighbors[v_min]:
            if nb in remaining:
                curr_deg[nb] -= 1

    # Now color in reverse order (last removed first)
    color = [-1] * n
    # For each vertex in reverse removal order
    for v in reversed(order):
        # Determine colors used by already colored neighbors
        used = [False] * (n + 1)  # +1 to safely index up to n
        for nb in neighbors[v]:
            c = color[nb]
            if c != -1:
                used[c] = True
        # Find the smallest non-negative color not used
        c = 0
        while c <= n and used[c]:
            c += 1
        color[v] = c

    # Ensure colors are consecutive starting from 0 (they should be by construction)
    # But we can compact if necessary (though FF on degeneracy ordering should already be compact)
    # However, to be safe, we remap.
    unique_colors = sorted(set(color))
    if unique_colors != list(range(len(unique_colors))):
        mapping = {old: new for new, old in enumerate(unique_colors)}
        color = [mapping[c] for c in color]

    return color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                adj_list[u].append(v)
                bit_adj[u] |= (1 << v)

    # Helper: count bits in integer
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid(coloring: list[int]) -> bool:
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring: list[int]) -> int:
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring: list[int]) -> list[int]:
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbor masks for fast saturation update
        neighbor_color_mask = [0] * n
        degree = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u]
                deg_u = degree[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
                elif sat_u == max_sat and deg_u == max_deg and u < v:
                    v = u
            # assign smallest available color
            used = neighbor_color_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # update saturation and neighbor masks for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if not (neighbor_color_mask[u] & (1 << c)):
                        neighbor_color_mask[u] |= (1 << c)
                        saturation[u] += 1
        return compact_colors(coloring)

    # RLF: Recursive Largest First (independent set extraction)
    def rlf() -> list[int]:
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        # precompute degrees in full graph
        degree = [len(adj_list[i]) for i in range(n)]

        while uncolored:
            # build independent set for this color
            independent_set = set()
            # choose vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                # degree in uncolored subgraph
                deg_sub = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        deg_sub += 1
                if deg_sub > max_deg:
                    max_deg = deg_sub
                    v = u
                elif deg_sub == max_deg and u < v:
                    v = u
            independent_set.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in independent_set for w in adj_list[u]):
                    W.add(u)
                    U.remove(u)
            # greedily add to independent set
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # degree in U
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if (w_neighbors > max_w_neighbors or
                        (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or
                        (w_neighbors == max_w_neighbors and deg_u == min_deg_u and u < best_u)):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                # add best_u to independent set
                independent_set.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to independent set
            for u in independent_set:
                coloring[u] = color
            color += 1
            # remove colored vertices from uncolored
            uncolored -= independent_set
        return compact_colors(coloring)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last() -> list[int]:
        # compute degeneracy ordering
        order = []
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            if degree[v] < len(buckets):
                buckets[degree[v]].add(v)
        # simulate peeling
        current_degree = degree[:]
        for _ in range(n):
            # find first non-empty bucket
            v = -1
            for d in range(len(buckets)):
                if buckets[d]:
                    v = buckets[d].pop()
                    break
            if v == -1:
                break  # should not happen
            order.append(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = current_degree[u]
                    if d < len(buckets) and u in buckets[d]:
                        buckets[d].remove(u)
                    current_degree[u] -= 1
                    d_new = current_degree[u]
                    if d_new < len(buckets):
                        buckets[d_new].add(u)
            remaining.remove(v)
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return compact_colors(coloring)

    # Kempe chain swap for colors a and b, returns new coloring if swap performed, else None
    def kempe_swap(coloring: list[int], a: int, b: int, v: int) -> list[int] | None:
        if coloring[v] != a:
            return None
        # BFS to get Kempe chain of v in colors a,b
        from collections import deque
        visited = [False] * n
        queue = deque([v])
        visited[v] = True
        component = []
        while queue:
            u = queue.popleft()
            component.append(u)
            for w in adj_list[u]:
                if not visited[w] and (coloring[w] == a or coloring[w] == b):
                    visited[w] = True
                    queue.append(w)
        # check if swapping introduces conflict: for each u in component,
        # after swap, color becomes b if was a, else a; check neighbors
        # Actually, swapping preserves validity, so no need to check
        # But we want to know if after swap, vertex v can take some other color? 
        # This function is for swapping to free a color for v? 
        # We'll use it in elimination: try to remove color k-1 by moving vertices via Kempe
        # For now, just return swapped coloring
        new_coloring = coloring[:]
        for u in component:
            if new_coloring[u] == a:
                new_coloring[u] = b
            else:
                new_coloring[u] = a
        return new_coloring

    # Try to eliminate the last color using direct reassignment and Kempe chains
    def reduce_colors(coloring: list[int]) -> list[int]:
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color k-1 iteratively
        improved = True
        while improved and k > 1:
            improved = False
            # vertices with color k-1
            verts_k = [v for v in range(n) if coloring[v] == k-1]
            if not verts_k:
                k -= 1
                continue
            # try direct reassignment first
            for v in verts_k:
                used = 0
                for u in adj_list[v]:
                    if coloring[u] != k-1:  # ignore same color class
                        used |= (1 << coloring[u])
                # find smallest color not used
                c = 0
                while c < k-1 and (used & (1 << c)):
                    c += 1
                if c < k-1:  # can reassign to c
                    coloring[v] = c
                    improved = True
                    break  # restart scan
            if improved:
                # compact and continue
                coloring = compact_colors(coloring)
                k = num_colors(coloring)
                continue
            # try Kempe chains: for each v in color k-1, try to swap with some color c < k-1
            for v in verts_k:
                for c in range(k-1):
                    # check if Kempe chain swap between k-1 and c can free color k-1 for v
                    # Actually, we want to know if after swapping the component of v in (k-1, c),
                    # the color k-1 is no longer used in the component? 
                    # We'll attempt the swap and see if v can then take color c? 
                    # But swapping changes colors: if v is k-1, after swap it becomes c.
                    # So we just perform the swap and see if it reduces the number of vertices in k-1.
                    new_coloring = kempe_swap(coloring, k-1, c, v)
                    if new_coloring is not None:
                        # count how many vertices still have color k-1 after swap
                        count_k1 = sum(1 for x in new_coloring if x == k-1)
                        if count_k1 < len(verts_k):
                            coloring = compact_colors(new_coloring)
                            improved = True
                            break
                if improved:
                    break
            if not improved:
                break
        return coloring

    # Generate candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # select best (fewest colors)
    best = min(candidates, key=num_colors)
    # apply Kempe reduction
    best = reduce_colors(best)
    # final validation (should be valid)
    if not is_valid(best):
        # fallback to DSATUR if something went wrong
        best = dsatur()
    return best

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle trivial cases
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for i in range(n):
