        # Ensure adjacency list is symmetric and clean
        adj_list = [list(set(neighbors)) for neighbors in adj]
        # Make sure it's undirected (though input should be)
        for i in range(n):
            for j in adj_list[i]:
                if i not in adj_list[j]:
                    adj_list[j].append(i)

