        return max(colors) + 1

    # Helper: convert to consecutive colors starting from 0
    def normalize_colors(colors):
        if not colors:
            return colors
        unique = sorted(set(colors))
        mapping = {old: new for new, old in enumerate(unique)}
        return [mapping[c] for c in colors]

    # Strategy 1: BFS-based bipartite extraction + conflict resolution
    def bfs_bipartite_base():
        color = [-1] * n
        # We'll try to 2-color as much as possible via BFS
        from collections import deque
        q = deque()
        # Start BFS from vertex 0
        for start in range(n):
            if color[start] == -1:
                color[start] = 0
                q.append(start)
                while q:
                    u = q.popleft()
                    for v in adj_list[u]:
                        if color[v] == -1:
                            color[v] = color[u] ^ 1
                            q.append(v)
                        elif color[v] == color[u]:
                            # Conflict: odd cycle detected, we'll leave both for now and resolve later
                            pass
        # Now, we have a 2-coloring where possible, but conflicts remain on odd cycles
        # Collect vertices involved in conflicts (same color on both ends of an edge)
        conflict_vertices = set()
        for u in range(n):
            for v in adj_list[u]:
                if u < v and color[u] == color[v]:
                    conflict_vertices.add(u)
                    conflict_vertices.add(v)

        # For conflict vertices, we need to assign additional colors
        # We'll try to color the subgraph induced by conflict_vertices with minimal colors
        # But first, try to reassign using available colors 0 and 1 if possible by swapping
        # Instead, we'll use a greedy approach on the conflict set with more colors
        # Create a list of vertices to color: first non-conflict (already 2-colored), then conflict
        # But non-conflict are already colored 0/1, we keep them and only recolor conflict set
        # However, recoloring a conflict vertex might cause conflict with its non-conflict neighbors
        # So we consider the whole graph but fix the non-conflict vertices as pre-colored with 0/1
        # We'll do greedy coloring on conflict vertices in some order, avoiding colors used by neighbors

        # Order conflict vertices by degree descending
        conflict_list = sorted(conflict_vertices, key=lambda x: (-degree[x], x))
        # We'll try colors 0,1,2,... but 0 and 1 might be used by neighbors
        for v in conflict_list:
            used = set()
            for nb in adj_list[v]:
                if color[nb] != -1:  # neighbor already colored (either pre-colored or processed)
                    used.add(color[nb])
            # Find smallest color not in used
            c = 0
            while c in used:
                c += 1
            color[v] = c

        # Normalize to ensure consecutive colors
        color = normalize_colors(color)
        return color

    # Strategy 2: DSATUR with bitmask optimization
    def dsatur():
        if n == 0:
            return []
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # For efficiency, we'll maintain a list of uncolored vertices
        uncolored = set(range(n))

