        # We'll recalc saturation for a vertex by examining its colored neighbors
        def compute_saturation(v):
            if color[v] != -1:
                return -1  # shouldn't be called for colored
            seen = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    seen |= (1 << color[nb])
            return seen.bit_count()

        # Main loop
        for _ in range(n):
            # Select uncolored vertex with max saturation, break ties by degree in uncolored subgraph, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = compute_saturation(u)
                # Degree in uncolored subgraph: number of uncolored neighbors
                deg_uncolored = 0
                for nb in adj_list[u]:
                    if nb in uncolored:
                        deg_uncolored += 1
                if sat > max_sat or (sat == max_sat and deg_uncolored > max_deg) or \
                   (sat == max_sat and deg_uncolored == max_deg and random.random() < 0.5):
                    max_sat = sat
                    max_deg = deg_uncolored
                    v = u
            if v == -1:
                break  # should not happen
            # Assign smallest available color
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
        return normalize_colors(color)

    # Strategy 3: RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        color = [-1] * n
        # We'll maintain set of uncolored vertices
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Step 1: choose vertex with max degree in G[uncolored]
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: (sum(1 for nb in adj_list[x] if nb in uncolored), x))
            independent_set = {v}
            # Partition remaining uncolored into U (not adj to any in S) and W (adj to at least one in S)
            # We'll maintain U and W as sets
            U = uncolored - {v}
            W = set()
            for nb in adj_list[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
            # While U not empty
            while U:
                # Select u in U that maximizes |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_count += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_in_U += 1
                    if w_count > max_w_neighbors or \
                       (w_count == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_count == max_w_neighbors and deg_in_U == min_deg_in_U and random.random() < 0.5):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                # Add best_u to independent set
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
