        neighbor_colors = [set() for _ in range(n)]
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    sat_u = saturation[u]
                    deg_u = sum(1 for w in neighbors[u] if not colored[w])
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                       (sat_u == max_sat and deg_u == max_deg and u > v):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen
