def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    is_matrix = (len(adj[0]) == n if n > 0 else False) and all(
        len(row) == n and all(x in (0, 1) for x in row) for row in adj
    )
    # Build neighbor list and bitmask adjacency
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    for i in range(n):
        if is_matrix:
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
        else:
            for j in adj[i]:
                neighbors[i].append(j)
                bit_adj[i] |= (1 << j)
    # Helper to count bits
    def bit_count(x: int) -> int:
        return x.bit_count()
    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Choose vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([u for u in neighbors[x] if u in uncolored])))
            # Compute used colors by neighbors
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            # Find smallest available color
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        return color
    # RLF (Recursive Largest First) independent set extraction
    def rlf() -> list[int]:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set S for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            S.add(v)
            # Partition remaining uncolored into U (eligible) and W (ineligible)
            U = uncolored - {v}
            W = set(u for u in U if any(w in neighbors[u] for w in S))
            U -= W
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([w for w in neighbors[x] if w in W]), -len([w for w in neighbors[x] if w in U])))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color
    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last() -> list[int]:
        if n == 0:
            return []
        # Compute degeneracy ordering via min-degree peeling
        degree = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for v in range(n):
            if degree[v] < n:
                buckets[degree[v]].append(v)
        for d in range(n):
            while buckets[d]:
                v = buckets[d].pop()
                if removed[v]:
                    continue
                if degree[v] != d:
                    buckets[degree[v]].append(v)
                    continue
                removed[v] = True
                order.append(v)
                for u in neighbors[v]:
                    if not removed[u]:
                        degree[u] -= 1
                        if degree[u] < n:
                            buckets[degree[u]].append(u)
        # Color in reverse order using first-fit
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    # Select best candidate (fewest colors)
    best_color = min(candidates, key=lambda col: max(col) + 1 if col else 0)
    # Kempe chain color reduction
    def kempe_reduction(coloring: list[int]) -> list[int]:
        color = coloring[:]
        k = max(color) + 1 if n > 0 else 0
        improved = True
        while improved and k > 1:
            improved = False
            # Find smallest color class (highest index)
            for target in range(k-1, -1, -1):
                vertices = [v for v in range(n) if color[v] == target]
                if not vertices:
                    continue
                # Try to recolor each vertex in this class
                for v in vertices:
                    used_by_neighbors = 0
                    for u in neighbors[v]:
                        used_by_neighbors |= (1 << color[u])
                    # Try direct reassignment to a lower color
                    for c in range(target):
                        if not (used_by_neighbors & (1 << c)):
                            color[v] = c
                            improved = True
                            break
                    if improved:
                        break
                    # Try Kempe chain swap with each lower color
                    for c in range(target):
                        # BFS to find (target, c)-Kempe chain containing v
                        stack = [v]
                        visited = [False] * n
                        visited[v] = True
                        component = []
                        while stack:
                            node = stack.pop()
                            component.append(node)
                            for u in neighbors[node]:
                                if not visited[u] and (color[u] == target or color[u] == c):
                                    visited[u] = True
                                    stack.append(u)
                        # Check if any neighbor of component has color c (would cause conflict if swapped)
                        has_c_neighbor = False
                        for node in component:
                            for u in neighbors[node]:
                                if color[u] == c and u not in component:
                                    has_c_neighbor = True
                                    break
                            if has_c_neighbor:
                                break
                        if not has_c_neighbor:
                            # Perform swap: target <-> c in component
                            for node in component:
                                if color[node] == target:
                                    color[node] = c
                                else:
                                    color[node] = target
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                # Compact colors: remap to 0..k-2
                mapping = {}
                next_c = 0
                for v in range(n):
                    if color[v] not in mapping:
                        mapping[color[v]] = next_c
                        next_c += 1
                color = [mapping[color[v]] for v in range(n)]
                k = next_c
        return color
    # Apply Kempe reduction to best candidate
    best_color = kempe_reduction(best_color)
    # Validate coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and color[u] == color[v]:
                # Fallback to DSATUR if invalid (should not happen)
                return dsatur()
    # Ensure colors are consecutive starting from 0
    if n > 0:
        unique_colors = sorted(set(best_color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_color = [mapping[c] for c in best_color]
    return best_color

