def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert adjacency to list of neighbor sets for fast lookup
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        # Adjacency list
        neighbors = [set(row) for row in adj]

    best_coloring = None
    best_k = float('inf')

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Helper: count number of colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: 1-opt local improvement
    def local_improve(coloring):
        improved = True
        while improved:
            improved = False
            for v in range(n):
                used = set()
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        used.add(coloring[u])
                # Try to find a better color for v
                for c in range(count_colors(coloring) + 1):
                    if c not in used:
                        if c < coloring[v]:
                            coloring[v] = c
                            improved = True
                        break
        return coloring

    # Run multiple randomized greedy passes
    for _ in range(30):  # 30 passes for good coverage within time
        # Random vertex order
        order = list(range(n))
        random.shuffle(order)
        coloring = greedy_color(order)
        coloring = local_improve(coloring)
        k = count_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]
            # Early exit if we hit the clique lower bound
            if best_k == max(len(neighbors[v]) for v in range(n)) + 1:
                break

    # Fallback: if no coloring found (should not happen), use trivial
    if best_coloring is None:
        order = list(range(n))
        random.shuffle(order)
        best_coloring = greedy_color(order)

    # Ensure colors are compact (0..k-1)
    if best_coloring:
        unique_colors = sorted(set(best_coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

