def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix (0/1)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bit masks
    adj_list = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        for i in range(n):
            adj_list[i] = list(adj[i])

    # Build bit masks for fast neighborhood operations
    bit_adj = [0] * n
    for i in range(n):
        for j in adj_list[i]:
            bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # Strategy 1: DSATUR with bitmask optimization
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighborhood
        saturation = [0] * n
        # neighbor color sets as bit masks for fast saturation update
        neighbor_colors = [0] * n

