            for v in range(n):
                if coloring[v] == -1:
                    if saturation[v] > max_sat:
                        max_sat = saturation[v]
                        candidates = [v]
                    elif saturation[v] == max_sat:
                        candidates.append(v)

            if not candidates:
                break  # should not happen

            # Tie-break: max degree in uncolored subgraph
            max_deg = -1
            selected = candidates[0]
            for v in candidates:
                # Count uncolored neighbors
                uncolored_deg = 0
                for nb in adj_list[v]:
                    if coloring[nb] == -1:
                        uncolored_deg += 1
                if uncolored_deg > max_deg:
                    max_deg = uncolored_deg
                    selected = v
                elif uncolored_deg == max_deg:
                    if random.random() < 0.5:  # random tie-break
                        selected = v

            v = selected
            # Find smallest available color (mex)
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation and neighbor colors for neighbors
            for nb in adj_list[v]:
                if coloring[nb] == -1:  # only update uncolored neighbors
                    # Add color c to neighbor's neighbor color set
                    if not (neighbor_colors[nb] & (1 << c)):
                        neighbor_colors[nb] |= (1 << c)
                        saturation[nb] += 1

        return normalize(coloring)

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for this color
            independent_set = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                # Find vertex in uncolored with max degree in uncolored subgraph
                max_deg = -1
                start = None
                for v in uncolored:
                    deg = 0
                    for nb in adj_list[v]:
                        if nb in uncolored:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        start = v
                if start is None:
                    start = next(iter(uncolored))
                independent_set.append(start)
                uncolored.remove(start)

            # Partition remaining uncolored into U (eligible) and W (ineligible)
            W = set()
            for v in independent_set:
                for nb in adj_list[v]:
                    if nb in uncolored:
                        W.add(nb)
            U = uncolored - W

            # Greedily add vertices from U to independent set
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_neighbors = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_neighbors += 1
                    # Tie-break: min degree in U
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_in_U += 1
                    if (w_neighbors > max_w_neighbors or 
                        (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U)):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u

                if best_u is None:
                    break

                independent_set.append(best_u)
                uncolored.remove(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
            color += 1

        return normalize(coloring)

