    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []  # will store removal order

        # Bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    d = degree[nb]
                    if d > 0:
                        buckets[d].remove(nb)
                        degree[nb] -= 1
                        buckets[degree[nb]].append(nb)

        # Color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by colored neighbors
            used = [False] * (n + 1)  # safe bound
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c

        return normalize(coloring)

    # Strategy 4: Jaccard-based heuristic for non-adjacent pairs
    def jaccard_heuristic():
        # Precompute Jaccard similarity for non-adjacent pairs
        # Only consider pairs with non-zero potential similarity
        pairs = []
        for i in range(n):
            for j in range(i+1, n):
                if j not in adj_list[i]:  # non-adjacent
                    # Compute Jaccard similarity: |N(i) ∩ N(j)| / |N(i) ∪ N(j)|
                    set_i = set(adj_list[i])
                    set_j = set(adj_list[j])
                    intersection = len(set_i & set_j)
                    union = len(set_i | set_j)
                    if union > 0:
                        similarity = intersection / union
                        if similarity > 0:  # only consider useful pairs
                            pairs.append((similarity, i, j))

        # Sort by similarity descending
        pairs.sort(key=lambda x: x[0], reverse=True)

        # Greedy assignment: try to assign same color to high-similarity non-adjacent pairs
        coloring = [-1] * n
        color = 0
        # We'll try to build color classes by merging compatible vertices
        # Process pairs in order of similarity
        for sim, i, j in pairs:
            if coloring[i] == -1 and coloring[j] == -1:
                # Both uncolored, try to assign same color
                # Check if they can share a color (they are non-adjacent by construction)
                # Find a color that doesn't conflict with their neighbors
                used_colors = set()
                for nb in adj_list[i]:
                    if coloring[nb] != -1:
                        used_colors.add(coloring[nb])
                for nb in adj_list[j]:
                    if coloring[nb] != -1:
                        used_colors.add(coloring[nb])
                # Find smallest available color
                c = 0
                while c in used_colors:
                    c += 1
                coloring[i] = c
                coloring[j] = c
            elif coloring[i] == -1 and coloring[j] != -1:
                # Only i uncolored, try to give it j's color if possible
                c = coloring[j]
                # Check if i can take color c (i.e., no neighbor has color c)
                conflict = False
                for nb in adj_list[i]:
                    if coloring[nb] == c:
                        conflict = True
                        break
                if not conflict:
                    coloring[i] = c
            elif coloring[i] != -1 and coloring[j] == -1:
                # Only j uncolored, try to give it i's color if possible
                c = coloring[i]
                conflict = False
                for nb in adj_list[j]:
                    if coloring[nb] == c:
                        conflict = True
                        break
                if not conflict:
                    coloring[j] = c

        # Color remaining uncolored vertices with first-fit
        for v in range(n):
            if coloring[v] == -1:
                used = [False] * (n + 1)
                for nb in adj_list[v]:
                    if coloring[nb] != -1:
                        used[coloring[nb]] = True
                c = 0
                while used[c]:
                    c += 1
                coloring[v] = c

        return normalize(coloring)

    # Run all strategies and collect results
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last),
        ("Jaccard", jaccard_heuristic)
    ]

    best_coloring = None
    best_num_colors = float('inf')

    for name, strategy in strategies:
        try:
            coloring = strategy()
            # Validate coloring
            if is_valid_coloring(coloring):
                num = num_colors(coloring)
                if num < best_num_colors:
                    best_num_colors = num
                    best_coloring = coloring[:]
            else:
                # Invalid coloring, skip
                pass
        except Exception:
            # In case of error, skip this strategy
            pass

    # Fallback: if all strategies failed, use simple greedy
    if best_coloring is None:
        coloring = [-1] * n
        for v in range(n):
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    # Final validation and normalization
    if not is_valid_coloring(best_coloring):
        # Last resort: assign each vertex a unique color
        best_coloring = list(range(n))

    return best_coloring

