                for v in adj_list[u]:
                    if v in uncolored:
                        deg_uncolored[u] += 1
            # Choose first vertex: max degree in uncolored
            v = max(uncolored, key=lambda u: deg_uncolored[u])
            S.append(v)
            # Partition U and W
            U = uncolored - {v}
            W = set()
            for u in adj_list[v]:
                if u in uncolored:
                    W.add(u)
            # U: not adjacent to any in S
            U = {u for u in U if not any((w in adj_list[u]) for w in S)}
            # While U not empty
            while U:
                # Select u in U with max neighbors in W
                u_star = -1
                max_neighbors_in_W = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    cnt = 0
                    for w in adj_list[u]:
                        if w in W:
                            cnt += 1
                    # Tie-break: min degree in U
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if cnt > max_neighbors_in_W or (cnt == max_neighbors_in_W and deg_u < min_deg_in_U):
                        max_neighbors_in_W = cnt
                        min_deg_in_U = deg_u
                        u_star = u
                if u_star == -1:
                    break  # Should not happen
                S.append(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
