            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = deg[u]
                    buckets[d].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].append(u)
