                        # Actually, we want to free target_color for v by swapping a component that contains v
                        # Standard: if the Kempe chain of v for colors (target_color, c) does not contain any vertex of color c that is adjacent to v? 
                        # Simpler: try to swap the component containing v; if after swap, v gets color c and no neighbor gets target_color (which would conflict), but since we swap, it should be safe.
                        # We'll do BFS for the Kempe chain
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
