            # If we eliminated the target_color class (no vertex has that color), we can compact colors
            # But we do that implicitly by trying to reassign; after Kempe, we might have gaps.
            # We'll compact at the end.
        # Compact colors: map to 0..k-1
        # Get unique colors used
        unique_colors = sorted(set(col))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        col = [mapping[c] for c in col]
        return col

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduce(best_coloring)
    except:
        pass  # If Kempe fails, keep the best we have

    # Final validation and compacting (ensure 0..k-1)
    if not is_valid(best_coloring):
        # Fallback to greedy by degree
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
