            candidates = []
            for v in range(n):
                if colors[v] == -1:
                    # Saturation degree: number of distinct colors in neighbors
                    sat_deg = sat[v].bit_count()
                    if sat_deg > max_sat:
                        max_sat = sat_deg
                        candidates = [v]
                    elif sat_deg == max_sat:
                        candidates.append(v)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                selected = candidates[0]
                for v in candidates:
                    # Count uncolored neighbors
                    deg_uncolored = 0
                    for u in adj_list[v]:
                        if colors[u] == -1:
                            deg_uncolored += 1
                    if deg_uncolored > max_deg:
                        max_deg = deg_uncolored
                        selected = v
                    elif deg_uncolored == max_deg and v < selected:
                        selected = v
                v = selected
            else:
                v = candidates[0]

            # Find smallest available color
            used_colors = sat[v]
            c = 0
            while used_colors & (1 << c):
                c += 1
            colors[v] = c
            # Update saturation of neighbors
            for u in adj_list[v]:
                if colors[u] == -1:
                    sat[u] |= (1 << c)
        return colors

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        color = 0
        # Set of uncolored vertices
        uncolored = set(range(n))
        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v0 = None
            for v in uncolored:
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
                elif deg == max_deg and v0 is not None and v < v0:
                    v0 = v
            if v0 is None:
                break  # should not happen
            independent_set = {v0}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = set(uncolored) - {v0}
            W = set()
            # Remove neighbors of v0 from U
            for u in adj_list[v0]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_count += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_in_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u is None:
