                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in independent_set
            for v in independent_set:
                colors[v] = color
            # Remove independent_set from uncolored
            uncolored -= independent_set
            color += 1
        return colors

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll maintain a list of vertices by current degree
        # Since n <= 100, we can do simple scan
        while remaining:
            # Find vertex with minimum degree in remaining
            min_deg = float('inf')
            v_min = None
            for v in remaining:
                if degree[v] < min_deg:
                    min_deg = degree[v]
                    v_min = v
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors
            for u in adj_list[v_min]:
                if u in remaining:
                    degree[u] -= 1
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Kempe chain based color reduction
    def kempe_reduce(colors_in):
        colors = colors_in[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(colors)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        used_by_neighbors |= (1 << colors[u])
                # Find smallest color not used by neighbors
                for c in range(target_color):  # only try colors < target_color
                    if not (used_by_neighbors & (1 << c)):
                        # Check if moving v to c would cause conflict (shouldn't by construction)
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart while loop after any change
                # If direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (target_color, c)
                    # Only if v is not adjacent to any vertex of color c (otherwise swap might not help)
                    has_c_neighbor = False
                    for u in adj_list[v]:
                        if colors[u] == c:
                            has_c_neighbor = True
                            break
                    if has_c_neighbor:
                        continue  # Kempe chain swap won't free color c for v if adjacent to c
                    # Find the Kempe chain component containing v in colors {target_color, c}
                    # We'll do BFS/DFS on the subgraph induced by vertices of these two colors
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if colors[node] == target_color or colors[node] == c:
                            component.add(node)
                            for nb in adj_list[node]:
                                if nb not in visited and (colors[nb] == target_color or colors[nb] == c):
                                    stack.append(nb)
                    # Check if any neighbor of v in the component has color c? Actually, we want to see
                    # if swapping the component would cause v to have a neighbor of color c after swap.
                    # After swap, v will become color c. We need to ensure no neighbor of v is color c after swap.
                    # Currently, neighbors of v that are in the component and have color c will become target_color.
                    # So we need to check: after swap, will any neighbor of v be color c?
                    # Neighbors of v that are color c and not in component remain c -> conflict.
                    # Neighbors of v that are color c and in component become target_color -> no conflict.
                    # Neighbors of v that are color target_color and in component become c -> conflict!
                    # Actually, we need to ensure that no neighbor of v is colored c after the swap.
                    # Let's compute: after swap, a neighbor u of v will have color:
                    #   if u in component: color flips (target_color <-> c)
                    #   else: same color
                    # So neighbor u of v will be color c after swap iff:
                    #   (u in component and colors[u] == target_color) OR (u not in component and colors[u] == c)
                    # We need this to be false for all u in adj_list[v].
                    conflict = False
                    for u in adj_list[v]:
                        if u in component:
                            if colors[u] == target_color:
                                conflict = True
                                break
                        else:
                            if colors[u] == c:
                                conflict = True
                                break
                    if not conflict:
                        # Perform the swap
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            else:  # must be c
                                colors[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            # After attempting to recolor all target vertices, if none changed, break
            if not changed:
                break
            # Normalize colors to fill gaps
            colors = normalize_colors(colors)
        return colors

    # Generate candidate colorings
    candidates = []
    start_time = time.time()
    # DSATUR
    c1 = dsatur()
    if is_valid_coloring(c1):
        candidates.append(c1)
    # RLF
    c2 = rlf()
    if is_valid_coloring(c2):
        candidates.append(c2)
    # Smallest-Last
    c3 = smallest_last()
    if is_valid_coloring(c3):
        candidates.append(c3)
    # If no candidates (shouldn't happen), fallback to greedy
    if not candidates:
        # Simple greedy in vertex order
        colors = [-1] * n
        for v in range(n):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(colors)
    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = normalize_colors(best)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    best = normalize_colors(best)
    # Final validation (should be valid)
    if not is_valid_coloring(best):
        # Fallback to DSATUR normalized
        best = normalize_colors(dsatur())
    return best

