            for v in uncolored:
                sat_v = saturation[v]
                deg_v = sum(1 for u in adj_list[v] if u in uncolored)
                if sat_v > best_sat or (sat_v == best_sat and deg_v > best_deg) or \
                   (sat_v == best_sat and deg_v == best_deg and (best_v == -1 or v < best_v)):
                    best_sat = sat_v
                    best_deg = deg_v
                    best_v = v
            v = best_v
            # assign smallest available color
            used = [False] * n
            for u in adj_list[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if c not in colored_neighbors[u]:
                        colored_neighbors[u].add(c)
                        saturation[u] += 1
        return colors

    # Helper: RLF
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # build maximal independent set for this color
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = {u for u in uncolored if u != v and all(u not in adj_list[w] for w in independent_set)}
            # W: vertices adjacent to at least one in independent_set
            W = {u for u in uncolored if u not in independent_set and u not in U}
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_u = float('inf')
                for u in U:
                    score = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or \
                       (score == best_score and deg_u == best_deg_u and (best_u == -1 or u < best_u)):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to independent_set
            for v in independent_set:
                colors[v] = color_idx
            uncolored -= independent_set
            color_idx += 1
        return colors

    # Helper: smallest-last ordering
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[v]) for v in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # maintain pointer to first non-empty bucket
        ptr = 0
        while remaining:
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # remove v
            remaining.remove(v)
            order.append(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # remove u from its current bucket
                    d = degree[u]
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)
                    if degree[u] < ptr:
                        ptr = degree[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(normalize(c1))
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(normalize(c2))
    except:
        pass
    # Smallest-last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(normalize(c3))
    except:
        pass
    # Fallback: greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid_coloring(c4):
            candidates.append(normalize(c4))
    except:
        pass
    # If no candidate, assign all zeros (invalid but safe for empty graph)
    if not candidates:
        return [0] * n

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        nonlocal n, adj_list
        changed = True
        while changed:
            changed = False
            # find smallest color class
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                if colors[v] < k:  # only consider current colors
                    color_classes[colors[v]].append(v)
            # find the last non-empty color class (highest index)
            target_color = -1
            for c in range(k-1, -1, -1):
                if color_classes[c]:
                    target_color = c
                    break
            if target_color == -1:
                break  # no colors
            # try to recolor each vertex in target_color
            for v in color_classes[target_color][:]:  # iterate over copy
                # try direct reassignment to a lower color
                used = [False] * k
                for u in adj_list[v]:
                    if colors[u] < k:
                        used[colors[u]] = True
                for c in range(target_color):
                    if not used[c]:
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    # restart after any change
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # BFS to find Kempe chain of colors (target_color, c) containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (colors[y] == target_color or colors[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # check if we can swap: after swap, v should become color c
                    # and no neighbor of v should become color c (except possibly through swap, but we check)
                    # actually, swapping is safe if no neighbor of v has color c (because they would become target_color)
                    # but after swap, neighbors in the component that were c become target_color, and vice versa.
                    # The only potential conflict is if a neighbor of v not in the component has color c.
                    # So: check that no neighbor of v has color c (outside the component, but since component includes all reachable via target_color/c,
                    # any neighbor with color c must be in the component if connected via alternating path)
                    # Actually, simpler: after swap, v becomes c. We need to ensure no neighbor of v is c after swap.
                    # Neighbors of v:
                    #   - if in component and was target_color -> becomes c -> conflict!
                    #   - if in component and was c -> becomes target_color -> no conflict
                    #   - if not in component -> color unchanged
                    # So, if any neighbor of v in the component had color target_color, after swap it becomes c -> conflict with v (which is now c).
                    # Therefore, we can only swap if v has no neighbor in the component that is colored target_color (except itself).
                    # But v is in the component and has color target_color, so we look at neighbors.
                    conflict = False
                    for x in adj_list[v]:
                        if visited[x] and colors[x] == target_color:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for x in component:
                            if colors[x] == target_color:
                                colors[x] = c
                            elif colors[x] == c:
                                colors[x] = target_color
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # renormalize colors to 0..k-1
                mapping = {}
                next_color = 0
                for v in range(n):
                    c = colors[v]
                    if c not in mapping:
                        mapping[c] = next_color
                        next_color += 1
                colors = [mapping[c] for c in colors]
                k = next_color
        return colors

    # Apply Kempe reduction
    best = kempe_reduce(best)
    k = num_colors(best)
    # Final normalization
    best = normalize(best)
    # Validate
    if not is_valid_coloring(best):
        # fallback to DSATUR if something went wrong
        best = normalize(dsatur())
    return best

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = [sum(row) for row in times]
    jobs_sorted = sorted(range(N), key=lambda i: total_processing[i], reverse=True)

    p = [row[:] for row in times]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    def compute_forward(partial):
        k = len(partial)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = p[partial[0]][m] if m == 0 else max(e[0][m-1], 0) + p[partial[0]][m]
        for r in range(1, k):
            job = partial[r]
            e[r][0] = e[r-1][0] + p[job][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job][m]
        return e

    def compute_backward(partial):
        k = len(partial)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            q[r][M-1] = q[r+1][M-1] + p[job][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]
        return q

    def makespan_insert(e_mat, q_mat, job, pos):
        k = len(e_mat)
        f = [0] * M
        if pos == 0:
            for m in range(M):
                f[m] = p[job][m] if m == 0 else max(f[m-1], 0) + p[job][m]
        else:
            prev = e_mat[pos-1]
            f[0] = prev[0] + p[job][0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev[m]) + p[job][m]
        best = 0
        for m in range(M):
            val = f[m] + q_mat[pos][m]
            if val > best:
                best = val
        return best

    def neh_construct():
        if not jobs_sorted:
            return []
        seq = [jobs_sorted[0]]
        if len(jobs_sorted) > 1:
            job1, job2 = jobs_sorted[0], jobs_sorted[1]
            seq1 = [job1, job2]
            seq2 = [job2, job1]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
            start_idx = 2
        else:
            start_idx = 1
        for idx in range(start_idx, len(jobs_sorted)):
            job = jobs_sorted[idx]
            e_mat = compute_forward(seq)
            q_mat = compute_backward(seq)
            best_pos = 0
            best_mk = makespan_insert(e_mat, q_mat, job, 0)
            for pos in range(1, len(seq)+1):
                mk = makespan_insert(e_mat, q_mat, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    current = neh_construct()
    best_seq = current[:]
    best_mk = makespan(current)

    avg_p = sum(total_processing) / (N * M)
    T0 = 0.5 * avg_p
    T_min = 1e-6
    alpha = 0.95
    d = 3 if N < 30 else 4
    max_iter = 60
    T = T0

    for _ in range(max_iter):
        if T < T_min:
            break
        destroyed = current[:]
        random.shuffle(destroyed)
        R = destroyed[:d]
        pi_D = destroyed[d:]
        for job in R:
            e_mat = compute_forward(pi_D)
            q_mat = compute_backward(pi_D)
            best_pos = 0
            best_mk = makespan_insert(e_mat, q_mat, job, 0)
            for pos in range(1, len(pi_D)+1):
                mk = makespan_insert(e_mat, q_mat, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            pi_D.insert(best_pos, job)
        current = pi_D
        mk = makespan(current)
        if mk < best_mk:
            best_mk = mk
            best_seq = current[:]
        if mk < makespan(current):
            current = pi_D
        else:
            delta = mk - makespan(current)
            if random.random() < math.exp(-delta / T):
                current = pi_D
        T *= alpha

    return best_seq

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for each job
    total_times = [sum(job) for job in times]
    # Sort jobs by total processing time descending (NEH priority)
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Initialize makespan matrix for current schedule
    makespan = [[0] * M for _ in range(N)]
    # Initialize schedule with first job
    schedule = [order[0]]
    # Compute makespan for first job
    for m in range(M):
        makespan[0][m] = (makespan[0][m-1] if m > 0 else 0) + times[order[0]][m]

    # NEH construction with Taillard acceleration
    for pos in range(1, N):
        job_idx = order[pos]
        job = times[job_idx]
        k = pos  # current schedule length

        # Forward matrix e[0..k-1][0..M-1]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = times[schedule[r]]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + job_r[m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + job_r[m]

        # Backward matrix q[0..k][0..M-1]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = times[schedule[r]]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + job_r[m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]

        best_makespan = float('inf')
        best_pos = 0
        # Try inserting job_idx at each position i in [0, k]
        for i in range(k+1):
            # Compute forward vector f for job_idx up to machine m
            f = [0] * M
            for m in range(M):
                if m == 0:
                    prev_e = e[i-1][m] if i > 0 else 0
                    f[m] = prev_e + job[m]
                else:
                    left = f[m-1]
                    up = e[i-1][m] if i > 0 else 0
                    f[m] = max(left, up) + job[m]
            # Compute makespan if job inserted at position i
            current_max = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > current_max:
                    current_max = val
            if current_max < best_makespan:
                best_makespan = current_max
                best_pos = i
        # Insert job at best_pos
        schedule.insert(best_pos, job_idx)
        # Recompute makespan matrix for the new schedule of length k+1
        for r in range(k+1):
            job_r = times[schedule[r]]
            for m in range(M):
                if m == 0:
                    makespan[r][m] = (makespan[r-1][m] if r > 0 else 0) + job_r[m]
                else:
                    makespan[r][m] = max(makespan[r-1][m] if r > 0 else 0, makespan[r][m-1]) + job_r[m]

    # Iterated Greedy refinement
    makespan_star = makespan[N-1][M-1]
    pi_star = schedule[:]
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N > 5 else 2
    max_iter = 50

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = list(range(N))
        random.shuffle(indices)
        removed_indices = indices[:d]
        removed_indices.sort(reverse=True)
        removed_jobs = [schedule.pop(idx) for idx in removed_indices]
        # Reconstruction: reinsert each removed job using NEH with Taillard
        for job_idx in removed_jobs:
            job = times[job_idx]
            k = len(schedule)
            if k == 0:
                schedule.append(job_idx)
                # Initialize makespan for single job
                makespan = [[0] * M for _ in range(1)]
                for m in range(M):
                    makespan[0][m] = (makespan[0][m-1] if m > 0 else 0) + job[m]
                continue
            # Forward matrix e[0..k-1][0..M-1]
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = times[schedule[r]]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + job_r[m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + job_r[m]
            # Backward matrix q[0..k][0..M-1]
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = times[schedule[r]]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + job_r[m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
            best_makespan = float('inf')
            best_pos = 0
            for i in range(k+1):
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev_e = e[i-1][m] if i > 0 else 0
                        f[m] = prev_e + job[m]
                    else:
                        left = f[m-1]
                        up = e[i-1][m] if i > 0 else 0
                        f[m] = max(left, up) + job[m]
                current_max = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > current_max:
                        current_max = val
                if current_max < best_makespan:
                    best_makespan = current_max
                    best_pos = i
            schedule.insert(best_pos, job_idx)
            # Recompute makespan matrix for current schedule
            for r in range(len(schedule)):
                job_r = times[schedule[r]]
                for m in range(M):
                    if m == 0:
                        makespan[r][m] = (makespan[r-1][m] if r > 0 else 0) + job_r[m]
                    else:
                        makespan[r][m] = max(makespan[r-1][m] if r > 0 else 0, makespan[r][m-1]) + job_r[m]
        # Acceptance criterion
        current_makespan = makespan[N-1][M-1]
        if current_makespan < makespan_star:
            makespan_star = current_makespan
            pi_star = schedule[:]
        if current_makespan < makespan_star:  # This condition is redundant but kept for clarity
            pass
        elif random.random() < math.exp(-(current_makespan - makespan_star) / T):
            # Accept worse solution
            pass
        else:
            # Revert to previous solution (pi_star is best, but we need to revert current to last accepted?)
            # For simplicity, we keep pi_star as best and continue with current schedule as is
            # In standard IG, we would set schedule to pi or pi_star based on acceptance
            # Here we accept the new schedule regardless (as per Metropolis) but only update pi_star if better
            # So we do nothing: schedule remains as the new one (accepted)
            pass

    return pi_star

