def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    P = [0] * N
    for i in range(N):
        row = times[i]
        s = 0
        for j in range(M):
            s += row[j]
        P[i] = s
        total_processing += s

    order = sorted(range(N), key=lambda i: P[i], reverse=True)

    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N + 1)]

    def makespan(seq):
        if not seq:
            return 0
        c_prev = [0] * M
        for job in seq:
            t = times[job]
            c_curr = [0] * M
            for m in range(M):
                if m == 0:
                    c_curr[m] = c_prev[m] + t[m]
                else:
                    c_curr[m] = max(c_prev[m], c_curr[m - 1]) + t[m]
            c_prev = c_curr
        return c_prev[M - 1]

    def compute_forward(partial):
        k = len(partial)
        if k == 0:
            for m in range(M):
                e[0][m] = 0
        else:
            for m in range(M):
                e[0][m] = times[partial[0]][m]
            for r in range(1, k):
                job = partial[r]
                t = times[job]
                for m in range(M):
                    if m == 0:
                        e[r][m] = e[r - 1][m] + t[m]
                    else:
                        e[r][m] = max(e[r - 1][m], e[r][m - 1]) + t[m]

    def compute_backward(partial):
        k = len(partial)
        for m in range(M):
            q[k][m] = 0
        for r in range(k - 1, -1, -1):
            job = partial[r]
            t = times[job]
            for m in range(M - 1, -1, -1):
                if m == M - 1:
                    q[r][m] = q[r + 1][m] + t[m]
                else:
                    q[r][m] = max(q[r + 1][m], q[r][m + 1]) + t[m]

    def makespan_insert(partial, job, pos):
        k = len(partial)
        if pos == 0:
            im1 = [-1]
        else:
            im1 = pos - 1
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev = e[im1][0] if im1 >= 0 else 0
                f[m] = prev + times[job][0]
            else:
                f[m] = max(f[m - 1], e[im1][m] if im1 >= 0 else 0) + times[job][m]
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
        return best

    def construct_neh():
        if N == 0:
            return []
        pi = [order[0]]
        if N == 1:
            return pi
        c0 = makespan([order[0], order[1]])
        c1 = makespan([order[1], order[0]])
        if c0 <= c1:
            pi = [order[0], order[1]]
        else:
            pi = [order[1], order[0]]
        for k in range(2, N):
            job = order[k]
            compute_forward(pi)
            compute_backward(pi)
            best_pos = 0
            best_cmax = makespan_insert(pi, job, 0)
            for pos in range(1, k + 1):
                cmax = makespan_insert(pi, job, pos)
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = pos
            pi.insert(best_pos, job)
        return pi

    pi = construct_neh()
    best_pi = pi[:]
    best_cmax = makespan(pi)

