    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_sum = 0
    P = [0] * N
    for i in range(N):
        s = 0
        row = times[i]
        for j in range(M):
            s += row[j]
        P[i] = s
        total_sum += s

    order = list(range(N))
    order.sort(key=lambda i: P[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            row = times[job]
            t[0] += row[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + row[m]
        return t[-1]

    def makespan_with_insertion(seq, job, pos):
        k = len(seq)
        if k == 0:
            return times[job][0] if M == 1 else _makespan_single_job(job)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = seq[r]
            row_r = times[job_r]
            if r == 0:
                e[0][0] = row_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + row_r[m]
            else:
                e[r][0] = e[r-1][0] + row_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + row_r[m]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = seq[r]
            row_r = times[job_r]
            q[r][M-1] = q[r+1][M-1] + row_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + row_r[m]
        f = [0] * M
        if pos == 0:
            for m in range(M):
                f[m] = times[job][m]
        else:
            prev_e = e[pos-1]
            row_job = times[job]
            f[0] = prev_e[0] + row_job[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev_e[m]) + row_job[m]
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
        return best

    def _makespan_single_job(job):
        t = 0
        for m in range(M):
            t += times[job][m]
        return t

    def makespan_neh_insert(seq, job):
        k = len(seq)
        if k == 0:
            return [job]
        best_pos = 0
        best_cmax = makespan_with_insertion(seq, job, 0)
        for pos in range(1, k+1):
            cmax = makespan_with_insertion(seq, job, pos)
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = pos
        return seq[:best_pos] + [job] + seq[best_pos:]

    pi = []
    for idx in order:
        pi = makespan_neh_insert(pi, idx)

    pi_best = pi[:]
    cmax_best = makespan(pi_best)
    T_param = 0.5
    T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 60
    d = 3

    for _ in range(max_iter):
        if cmax_best == 0:
            break
        indices = list(range(N))
        random.shuffle(indices)
        destroyed = indices[:d]
        remaining = [idx for idx in indices if idx not in destroyed]
        random.shuffle(destroyed)
        pi_current = remaining[:]
        for job in destroyed:
            pi_current = makespan_neh_insert(pi_current, job)
        cmax_current = makespan(pi_current)
        if cmax_current < cmax_best:
            pi_best = pi_current[:]
            cmax_best = cmax_current
            pi = pi_current[:]
        elif cmax_current < makespan(pi):
            pi = pi_current[:]
        else:
            delta = cmax_current - makespan(pi)
            if delta < 0 or random.random() < math.exp(-delta / T):
                pi = pi_current[:]
    return pi_best

