def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    P = [0] * N
    for i in range(N):
        s = 0
        row = times[i]
        for j in range(M):
            s += row[j]
        P[i] = s
        total_processing += s

    LB = [0] * M
    for m in range(M):
        min_prefix = float('inf')
        min_suffix = float('inf')
        for i in range(N):
            prefix = 0
            for j in range(m):
                prefix += times[i][j]
            if prefix < min_prefix:
                min_prefix = prefix
            suffix = 0
            for j in range(m + 1, M):
                suffix += times[i][j]
            if suffix < min_suffix:
                min_suffix = suffix
        sum_m = 0
        for i in range(N):
            sum_m += times[i][m]
        LB[m] = min_prefix + sum_m + min_suffix
    LB_val = max(LB)

    order = sorted(range(N), key=lambda i: P[i], reverse=True)

    makespan_cache = {}

    def makespan(perm):
        key = tuple(perm)
        if key in makespan_cache:
            return makespan_cache[key]
        if not perm:
            res = 0
        else:
            t = [0] * M
            for job in perm:
                row = times[job]
                t[0] += row[0]
                for m in range(1, M):
                    t[m] = max(t[m], t[m - 1]) + row[m]
            res = t[-1]
        makespan_cache[key] = res
        return res

    def forward_matrix(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        row0 = times[perm[0]]
        e[0][0] = row0[0]
        for m in range(1, M):
            e[0][m] = e[0][m - 1] + row0[m]
        for r in range(1, k):
            row = times[perm[r]]
            er = e[r]
            er_prev = e[r - 1]
            er[0] = er_prev[0] + row[0]
            for m in range(1, M):
                er[m] = max(er_prev[m], er[m - 1]) + row[m]
        return e

    def backward_matrix(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k + 1)]
        for r in range(k - 1, -1, -1):
            row = times[perm[r]]
            qr = q[r]
            qr_next = q[r + 1]
            qr[M - 1] = qr_next[M - 1] + row[M - 1]
            for m in range(M - 2, -1, -1):
                qr[m] = max(qr_next[m], qr[m + 1]) + row[m]
        return q

    def makespan_insert(e, q, job, pos):
        k = len(e)
        f = [0] * M
        if pos == 0:
            f[0] = job[0]
            for m in range(1, M):
                f[m] = f[m - 1] + job[m]
        else:
            e_prev = e[pos - 1]
            f[0] = e_prev[0] + job[0]
            for m in range(1, M):
                f[m] = max(f[m - 1], e_prev[m]) + job[m]
        q_pos = q[pos]
        max_val = 0
        for m in range(M):
            val = f[m] + q_pos[m]
            if val > max_val:
                max_val = val
        return max_val

    def makespan_insert_fast(perm, job, pos):
        k = len(perm)
        if k == 0:
            return sum(times[job])
        e = forward_matrix(perm)
        q = backward_matrix(perm)
        return makespan_insert(e, q, times[job], pos)

    def NEH():
        if len(order) == 0:
            return []
        perm = [order[0]]
        if len(order) == 1:
            return perm
        job1 = times[order[0]]
        job2 = times[order[1]]
        makespan1 = job1[0] + job2[0]
        for m in range(1, M):
            makespan1 = max(makespan1, makespan1 - job1[m - 1]) + job2[m]
        makespan2 = job2[0] + job1[0]
        for m in range(1, M):
            makespan2 = max(makespan2, makespan2 - job2[m - 1]) + job1[m]
        if makespan2 < makespan1:
            perm = [order[1], order[0]]
        else:
            perm = [order[0], order[1]]
        for idx in range(2, len(order)):
            job_idx = order[idx]
            job = times[job_idx]
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(perm) + 1):
                lb = 0
                if pos > 0:
                    lb = perm[pos - 1]
                if pos < len(perm):
                    lb = max(lb, perm[pos])
                if lb >= LB_val:
                    continue
                ms = makespan_insert_fast(perm, job, pos)
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            perm.insert(best_pos, job_idx)
        return perm

    pi = NEH()
    pi_star = pi[:]
    C_pi = makespan(pi)
    C_pi_star = C_pi
    if C_pi_star == LB_val:
        return pi_star

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-9:
        T = 1e-9

    max_iter = 60
    d = 3
    if N > 60:
        d = 4
    if N > 100:
        max_iter = 40

    for _ in range(max_iter):
        if C_pi == LB_val:
            break
        indices = list(range(N))
        random.shuffle(indices)
        removed = []
        remaining = pi[:]
        for idx in indices[:d]:
            job_val = remaining.pop(remaining.index(indices[idx]))
            removed.append(job_val)
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(remaining) + 1):
                lb = 0
                if pos > 0:
                    lb = remaining[pos - 1]
                if pos < len(remaining):
                    lb = max(lb, remaining[pos])
                if lb >= LB_val:
                    continue
                ms = makespan_insert_fast(remaining, job, pos)
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            remaining.insert(best_pos, job)
        pi = remaining
        C_pi_new = makespan(pi)
        if C_pi_new < C_pi:
            pi = pi[:]
            C_pi = C_pi_new
            if C_pi < C_pi_star:
                pi_star = pi[:]
                C_pi_star = C_pi
                if C_pi_star == LB_val:
                    break
        else:
            if random.random() < math.exp(-(C_pi_new - C_pi) / T):
                pi = pi[:]
                C_pi = C_pi_new
    return pi_star

