def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_times = [sum(job) for job in times]
    slope = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Helper: compute makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Helper: evaluate insertion of job x at position i in current partial schedule
    # using Taillard's acceleration (forward/backward matrices)
    def evaluate_insertion(partial, x, i, e, q):
        # Compute forward vector f for job x
        f = [0] * M
        if i == 0:
            f[0] = times[x][0]
            for m in range(1, M):
                f[m] = f[m-1] + times[x][m]
        else:
            f[0] = e[i-1][0] + times[x][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + times[x][m]
        # Compute makespan candidate: max_m (f[m] + q[i][m])
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    # Construct initial solution using NEH with Taillard acceleration and tie-breaking by slope
    order = sorted(range(N), key=lambda i: (-total_times[i], -slope[i]))
    if N >= 2:
        # Initial pair
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        perm = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        start_k = 2
    else:
        perm = [order[0]]
        start_k = 1

    # Iterative construction with Taillard acceleration
    for k in range(start_k, N):
        job = order[k]
        # Build forward matrix e for current perm (length k)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = perm[r]
            if r == 0:
                e[0][0] = times[job_r][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + times[job_r][m]
            else:
                e[r][0] = e[r-1][0] + times[job_r][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job_r][m]
        # Build backward matrix q for current perm (length k)
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already
        for r in range(k-1, -1, -1):
            job_r = perm[r]
            q[r][M-1] = q[r+1][M-1] + times[job_r][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
        # Evaluate all insertion positions
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            mk = evaluate_insertion(perm, job, i, e, q)
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        perm.insert(best_pos, job)

    # Iterated Greedy refinement
    random.seed(42)  # deterministic seed for reproducibility
    current = perm[:]
    best_perm = current[:]
    best_mk = makespan(current)
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
    max_iters = 60  # calibrated for <50ms

    for _ in range(max_iters):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del current[idx]
        # Reconstruction: reinsert removed jobs one by one using NEH with Taillard
        for job in removed:
            k = len(current)
            if k == 0:
                current.append(job)
                continue
            # Build forward matrix e for current (length k)
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = current[r]
                if r == 0:
                    e[0][0] = times[job_r][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + times[job_r][m]
                else:
                    e[r][0] = e[r-1][0] + times[job_r][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job_r][m]
            # Build backward matrix q for current (length k)
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = current[r]
                q[r][M-1] = q[r+1][M-1] + times[job_r][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
            # Evaluate insertion positions
            best_pos = 0
            best_mk_ins = float('inf')
            for i in range(k+1):
                mk_ins = evaluate_insertion(current, job, i, e, q)
                if mk_ins < best_mk_ins:
                    best_mk_ins = mk_ins
                    best_pos = i
            current.insert(best_pos, job)
        # Evaluate new solution
        mk = makespan(current)
        if mk < best_mk:
            best_mk = mk
            best_perm = current[:]
        # Metropolis acceptance
        if mk < makespan(perm) or random.random() < math.exp(-(mk - makespan(perm)) / T):
            perm = current[:]

    return best_perm

