def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_times = [sum(job) for job in times]
    slope_index = [
        sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)
    ]
    # Combined priority: total time descending, then slope descending
    jobs = sorted(range(N), key=lambda i: (-total_times[i], -slope_index[i]))

    # Makespan calculation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Taillard's accelerated insertion evaluation
    def evaluate_insertion(partial, job, e, q):
        k = len(partial)
        best_pos = 0
        best_mk = float('inf')
        for i in range(k + 1):
            # Forward pass for job at position i
            f = [0] * M
            if i == 0:
                f[0] = times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], 0) + times[job][m]
            else:
                f[0] = e[i-1][0] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + times[job][m]
            # Compute makespan candidate
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return best_pos, best_mk

    # NEH construction with Taillard acceleration
    def construct_neh(job_order):
        if not job_order:
            return []
        seq = [job_order[0]]
        if len(job_order) == 1:
            return seq
        # Initial pair
        seq1 = [job_order[0], job_order[1]]
        seq2 = [job_order[1], job_order[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        # Prepare e and q for current seq length
        for k in range(2, len(job_order)):
            job = job_order[k]
            # Build forward matrix e for current seq
            e = [[0] * M for _ in range(len(seq))]
            for r in range(len(seq)):
                job_r = seq[r]
                if r == 0:
                    e[0][0] = times[job_r][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + times[job_r][m]
                else:
                    e[r][0] = e[r-1][0] + times[job_r][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job_r][m]
            # Build backward matrix q for current seq
            q = [[0] * M for _ in range(len(seq) + 1)]
            for r in range(len(seq)-1, -1, -1):
                job_r = seq[r]
                q[r][M-1] = q[r+1][M-1] + times[job_r][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
            # Evaluate insertion positions
            pos, _ = evaluate_insertion(seq, job, e, q)
            seq.insert(pos, job)
        return seq

    # Iterated Greedy with destruction size 3
    def iterated_greedy(initial_seq, max_iter=50):
        current = initial_seq[:]
        best = current[:]
        best_mk = makespan(best)
        total_load = sum(total_times)
        T_param = 0.5
        T = T_param * total_load / (10 * N * M) if N * M > 0 else 1e-6
        for _ in range(max_iter):
            # Destruction: remove 3 random jobs
            if len(current) < 3:
                destroyed = current[:]
                remaining = []
            else:
                indices = random.sample(range(len(current)), 3)
                indices.sort(reverse=True)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(len(current)) if i not in indices]
            # Reconstruction: reinsert destroyed jobs one by one in random order
            random.shuffle(destroyed)
            seq = remaining[:]
            for job in destroyed:
                # Build e and q for current seq
                e = [[0] * M for _ in range(len(seq))]
                for r in range(len(seq)):
                    job_r = seq[r]
                    if r == 0:
                        e[0][0] = times[job_r][0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + times[job_r][m]
                    else:
                        e[r][0] = e[r-1][0] + times[job_r][0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job_r][m]
                q = [[0] * M for _ in range(len(seq) + 1)]
                for r in range(len(seq)-1, -1, -1):
                    job_r = seq[r]
                    q[r][M-1] = q[r+1][M-1] + times[job_r][M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
                pos, _ = evaluate_insertion(seq, job, e, q)
                seq.insert(pos, job)
            # Acceptance criterion
            mk = makespan(seq)
            if mk < best_mk:
                best_mk = mk
                best = seq[:]
                current = seq[:]
            elif mk < makespan(current):
                current = seq[:]
            else:
                if random.random() < math.exp(-(mk - makespan(current)) / T):
                    current = seq[:]
        return best

    # Build initial solution
    initial_seq = construct_neh(jobs)
    # Refine with iterated greedy
    refined_seq = iterated_greedy(initial_seq, max_iter=40)
    return refined_seq

