        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    def makespan_taillard(seq):
        if not seq:
            return 0
        e = [0] * M
        for job in seq:
            job_t = times[job]
            new_e = [0] * M
            new_e[0] = e[0] + job_t[0]
            for m in range(1, M):
                new_e[m] = max(e[m], new_e[m-1]) + job_t[m]
            e = new_e
        return e[-1]

    def compute_forward(seq):
        if not seq:
            return [0] * M
        e = [0] * M
        for job in seq:
            job_t = times[job]
            new_e = [0] * M
            new_e[0] = e[0] + job_t[0]
            for m in range(1, M):
                new_e[m] = max(e[m], new_e[m-1]) + job_t[m]
            e = new_e
        return e

    def compute_backward(seq):
        if not seq:
            return [0] * M
        q = [0] * M
        for job in reversed(seq):
            job_t = times[job]
            new_q = [0] * M
            new_q[M-1] = q[M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                new_q[m] = max(q[m], new_q[m+1]) + job_t[m]
            q = new_q
        return q

    def evaluate_insertion(forward_vec, backward_tail, job):
        job_t = times[job]
        f = [0] * M
        f[0] = forward_vec[0] + job_t[0]
        for m in range(1, M):
            f[m] = max(f[m-1], forward_vec[m]) + job_t[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + backward_tail[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def evaluate_pair_insertion(forward_vec, backward_tail, job_a, job_b):
        job_t_a = times[job_a]
        job_t_b = times[job_b]
        f1 = [0] * M
        f1[0] = forward_vec[0] + job_t_a[0]
        for m in range(1, M):
