        f2 = [0] * M
        f2[0] = f1[0] + job_t_b[0]
        for m in range(1, M):
            f2[m] = max(f2[m-1], f1[m]) + job_t_b[m]
        makespan_val = 0
        for m in range(M):
            val = f2[m] + backward_tail[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    pi = [order[0]]
    if N >= 2:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan_taillard(seq1) <= makespan_taillard(seq2):
