        else:
            pi = seq2

    for idx in range(2, N):
        job = order[idx]
        forward_vec = compute_forward(pi)
        backward_tail = compute_backward(pi)
        best_pos = 0
        best_makespan = float('inf')
        for pos in range(len(pi) + 1):
            if pos == 0:
                f_vec = [0] * M
            else:
                f_vec = compute_forward(pi[:pos])
            if pos == len(pi):
                b_tail = [0] * M
            else:
                b_tail = compute_backward(pi[pos:])
            m = evaluate_insertion(f_vec, b_tail, job)
            if m < best_makespan:
                best_makespan = m
                best_pos = pos
        pi.insert(best_pos, job)

    pi_star = pi[:]
    makespan_star = makespan_taillard(pi_star)
    total_sum = sum(total_processing)
