            R = pi[:]
            pi_D = []
        else:
            indices = random.sample(range(len(pi)), d)
            indices.sort(reverse=True)
            R = [pi.pop(i) for i in indices]
            pi_D = pi
        random.shuffle(R)
        pi_new = pi_D[:]
        for job in R:
            forward_vec = compute_forward(pi_new)
            backward_tail = compute_backward(pi_new)
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(pi_new) + 1):
                if pos == 0:
                    f_vec = [0] * M
                else:
                    f_vec = compute_forward(pi_new[:pos])
                if pos == len(pi_new):
                    b_tail = [0] * M
                else:
                    b_tail = compute_backward(pi_new[pos:])
                m = evaluate_insertion(f_vec, b_tail, job)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            pi_new.insert(best_pos, job)
        m_new = makespan_taillard(pi_new)
        if m_new < makespan_star:
            pi_star = pi_new[:]
            makespan_star = m_new
        if m_new < makespan_taillard(pi):
            pi = pi_new
        else:
            delta = m_new - makespan_taillard(pi)
            if delta < 0 or random.random() < math.exp(-delta / T):
                pi = pi_new
    return pi_star

