                best_cmax = cmax
                best_seq = list(seq)
        current = best_seq
        # Insert remaining jobs
        for idx in range(2, N):
            job = jobs_sorted[idx]
            k = len(current)
            # Forward matrix e: completion times of current partial schedule
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = current[r]
                for m in range(M):
                    if m == 0:
                        prev = e[r-1][0] if r > 0 else 0
                        e[r][m] = prev + times[job_r][m]
                    else:
                        left = e[r][m-1]
                        up = e[r-1][m] if r > 0 else 0
                        e[r][m] = max(left, up) + times[job_r][m]
            # Backward matrix q: tail times
            q = [[0] * M for _ in range(k+1)]  # q[k][*] = 0
            for r in range(k-1, -1, -1):
                job_r = current[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + times[job_r][m]
                    else:
                        down = q[r+1][m]
                        right = q[r][m+1]
                        q[r][m] = max(down, right) + times[job_r][m]
            # Evaluate insertion positions
            best_pos = 0
            best_cmax = float('inf')
            for i in range(k+1):
                # Forward pass for job up to machine m
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev = e[i-1][0] if i > 0 else 0
                        f[m] = prev + times[job][m]
                    else:
                        left = f[m-1]
                        up = e[i-1][m] if i > 0 else 0
                        f[m] = max(left, up) + times[job][m]
                # Compute makespan: max over m of f[m] + q[i][m]
                cmax = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax:
                        cmax = val
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = i
            current = current[:best_pos] + [job] + current[best_pos:]
        return current

    # Iterated Greedy with destruction size d=3
    def iterated_greedy(initial_seq, max_iter=50):
        current = initial_seq[:]
        best = current[:]
        best_cmax = makespan(best)
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build destroyed sequence by keeping non-removed jobs in order
            destroyed = [job for idx, job in enumerate(current) if idx not in indices]
            # Reconstruction: reinsert each removed job using NEH insertion (Taillard accelerated)
            for job in removed:
                k = len(destroyed)
                if k == 0:
                    destroyed = [job]
                    continue
                # Forward matrix e for destroyed
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    job_r = destroyed[r]
                    for m in range(M):
                        if m == 0:
                            prev = e[r-1][0] if r > 0 else 0
                            e[r][m] = prev + times[job_r][m]
                        else:
                            left = e[r][m-1]
                            up = e[r-1][m] if r > 0 else 0
                            e[r][m] = max(left, up) + times[job_r][m]
                # Backward matrix q
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = destroyed[r]
                    for m in range(M-1, -1, -1):
                        if m == M-1:
                            q[r][m] = q[r+1][m] + times[job_r][m]
                        else:
                            down = q[r+1][m]
                            right = q[r][m+1]
                            q[r][m] = max(down, right) + times[job_r][m]
                # Evaluate insertion positions
                best_pos = 0
                best_cmax_local = float('inf')
                for i in range(k+1):
                    f = [0] * M
                    for m in range(M):
