                            prev = e[i-1][0] if i > 0 else 0
                            f[m] = prev + times[job][m]
                        else:
                            left = f[m-1]
                            up = e[i-1][m] if i > 0 else 0
                            f[m] = max(left, up) + times[job][m]
                    cmax = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > cmax:
                            cmax = val
                    if cmax < best_cmax_local:
                        best_cmax_local = cmax
                        best_pos = i
                destroyed = destroyed[:best_pos] + [job] + destroyed[best_pos:]
            # Acceptance criterion
            new_cmax = makespan(destroyed)
            if new_cmax < makespan(current):
                current = destroyed[:]
                if new_cmax < best_cmax:
                    best = destroyed[:]
                    best_cmax = new_cmax
            else:
                if random.random() < math.exp(-(new_cmax - makespan(current)) / T):
                    current = destroyed[:]
        return best

    # Run NEH and then Iterated Greedy
    initial = neh_construct()
    return iterated_greedy(initial, max_iter=40)

