def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    P = [0] * N
    for i in range(N):
        s = 0
        row = times[i]
        for j in range(M):
            s += row[j]
        P[i] = s
        total_processing += s

    order = sorted(range(N), key=lambda i: P[i], reverse=True)

    def makespan(perm):
        t = [0] * M
        for job in perm:
            row = times[job]
            t[0] += row[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + row[m]
        return t[-1]

    def makespan_taillard(perm, e, q):
        t = [0] * M
        for job in perm:
            row = times[job]
            t[0] += row[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + row[m]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        e = [[0] * M for _ in range(k)]
        if k == 0:
            return e
        row0 = times[perm[0]]
        e[0][0] = row0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + row0[m]
        for r in range(1, k):
            row = times[perm[r]]
            er = e[r]
            er_prev = e[r-1]
            er[0] = er_prev[0] + row[0]
            for m in range(1, M):
                er[m] = max(er_prev[m], er[m-1]) + row[m]
        return e

    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        if k == 0:
            return q
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            row = times[perm[r]]
            qr = q[r]
            qr_next = q[r+1]
            qr[M-1] = qr_next[M-1] + row[M-1]
            for m in range(M-2, -1, -1):
                qr[m] = max(qr_next[m], qr[m+1]) + row[m]
        return q

    def makespan_insert(e, q, job, pos):
        f = [0] * M
        row = times[job]
        if pos == 0:
            f[0] = row[0]
        else:
            f[0] = e[pos-1][0] + row[0]
        for m in range(1, M):
            f[m] = max(f[m-1], e[pos-1][m]) + row[m]
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
        return best

    def neh_taillard(perm_order):
        if not perm_order:
            return []
        first = perm_order[0]
        if len(perm_order) == 1:
            return [first]
        second = perm_order[1]
        seq1 = [first, second]
        seq2 = [second, first]
        if makespan(seq1) <= makespan(seq2):
            current = seq1[:]
        else:
            current = seq2[:]
        for idx in range(2, len(perm_order)):
            job = perm_order[idx]
            e = compute_forward(current)
            q = compute_backward(current)
            best_pos = 0
            best_makespan = makespan_insert(e, q, job, 0)
            for pos in range(1, len(current)+1):
                mk = makespan_insert(e, q, job, pos)
                if mk < best_makespan:
                    best_makespan = mk
                    best_pos = pos
            current.insert(best_pos, job)
        return current

    pi = neh_taillard(order)
    pi_best = pi[:]
    best_makespan = makespan(pi)

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3
    max_iters = 60
    if N * M > 1000:
        max_iters = 40
    elif N * M < 200:
        max_iters = 80

    for _ in range(max_iters):
        if d > N:
            d_destroy = N
        else:
            d_destroy = d
        indices = random.sample(range(N), d_destroy)
        indices.sort(reverse=True)
        removed = []
        for idx in indices:
            removed.append(pi.pop(idx))
        random.shuffle(removed)
        for job in removed:
            e = compute_forward(pi)
            q = compute_backward(pi)
            best_pos = 0
            best_mk = makespan_insert(e, q, job, 0)
            for pos in range(1, len(pi)+1):
                mk = makespan_insert(e, q, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            pi.insert(best_pos, job)
        curr_mk = makespan(pi)
        if curr_mk < best_makespan:
            best_makespan = curr_mk
            pi_best = pi[:]
        if curr_mk < makespan(pi_best):
            pass
        if curr_mk < makespan(pi):
            pi = pi[:]
        else:
            if random.random() < math.exp(-(curr_mk - makespan(pi)) / T):
                pi = pi[:]
            else:
                # revert to previous pi before this iteration's destruction
                # we don't have it stored, so we keep the current pi as is (already accepted)
                pass

    return pi_best

