def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_data = [row[:] for row in times]
    total_time = [sum(row) for row in job_data]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            p = job_data[job]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[m]
        return t[-1]

    # NEH construction with Taillard acceleration
    def construct_initial():
        # Sort jobs by total processing time descending
        order = sorted(range(N), key=lambda i: total_time[i], reverse=True)
        if N == 0:
            return []
        perm = [order[0]]
        if N == 1:
            return perm
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        perm = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        # Greedy insertion for remaining jobs
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_mk = float('inf')
            # Forward matrix e: completion times of current perm
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                pj = job_data[perm[r]]
                if r == 0:
                    e[0][0] = pj[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + pj[m]
                else:
                    e[r][0] = e[r-1][0] + pj[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
            # Backward tail matrix q
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                pj = job_data[perm[r]]
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
            # Evaluate each insertion position
            for i in range(k+1):
                pj = job_data[job]
                # Forward vector f for job at position i
                if i == 0:
                    f0 = pj[0]
                    f = [f0]
                    for m in range(1, M):
                        f.append(f[-1] + pj[m])
                else:
                    f0 = e[i-1][0] + pj[0]
                    f = [f0]
                    for m in range(1, M):
                        f.append(max(f[-1], e[i-1][m]) + pj[m])
                # Compute makespan for this insertion
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with Metropolis acceptance
    def iterated_greedy(initial_perm):
        current = initial_perm[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing = sum(total_time)
        # Temperature parameter
        T = 0.5 * total_processing / (10 * N * M)
        if T < 1e-6:
            T = 1e-6
        d = 3 if N > 5 else N  # destruction size
        max_iter = 60  # calibrated for <50ms
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            removed_set = set(removed)
            # Build partial sequence without removed jobs
            partial = [job for job in current if job not in removed_set]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                best_pos = 0
                best_mk_local = float('inf')
                k = len(partial)
                # Forward matrix e for partial sequence
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    pj = job_data[partial[r]]
                    if r == 0:
                        e[0][0] = pj[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + pj[m]
                    else:
                        e[r][0] = e[r-1][0] + pj[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
                # Backward tail matrix q
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    pj = job_data[partial[r]]
                    q[r][M-1] = q[r+1][M-1] + pj[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
                # Try each insertion position
                for i in range(k+1):
                    pj = job_data[job]
                    if i == 0:
                        f0 = pj[0]
                        f = [f0]
                        for m in range(1, M):
                            f.append(f[-1] + pj[m])
                    else:
                        f0 = e[i-1][0] + pj[0]
                        f = [f0]
                        for m in range(1, M):
                            f.append(max(f[-1], e[i-1][m]) + pj[m])
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_local:
                        best_mk_local = mk
                        best_pos = i
                partial.insert(best_pos, job)
            # New candidate sequence
            candidate = partial
            mk_candidate = makespan(candidate)
            # Acceptance criterion
            if mk_candidate < makespan(current):
                current = candidate
                if mk_candidate < best_mk:
                    best = candidate
                    best_mk = mk_candidate
            else:
                delta = mk_candidate - makespan(current)
                if random.random() < math.exp(-delta / T):
                    current = candidate
        return best

    # Build initial solution and refine
    initial_perm = construct_initial()
    return iterated_greedy(initial_perm)

