def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for job ordering
    total_time = [sum(job) for job in times]
    # Sort jobs by total processing time descending (NEH priority)
    order = sorted(range(N), key=lambda i: total_time[i], reverse=True)

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]  # forward matrix
    q = [[0] * M for _ in range(N + 1)]  # backward matrix (extra row for boundary)
    f = [0] * M  # temporary forward vector for insertion

    def makespan(perm):
        """Compute makespan of a permutation using DP."""
        if not perm:
            return 0
        dp = [0] * M
        for job in perm:
            t = times[job]
            dp[0] += t[0]
            for m in range(1, M):
                dp[m] = max(dp[m - 1], dp[m]) + t[m]
        return dp[M - 1]

    def compute_forward(perm, length):
        """Compute forward completion matrix e[0..length-1][0..M-1] for perm[0:length]."""
        if length == 0:
            for m in range(M):
                e[-1][m] = 0  # handled via condition in loop
        for r in range(length):
            job = perm[r]
            t = times[job]
            if r == 0:
                e[0][0] = t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m - 1] + t[m]
            else:
                e[r][0] = e[r - 1][0] + t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r - 1][m], e[r][m - 1]) + t[m]

    def compute_backward(perm, length):
        """Compute backward tail matrix q[0..length][0..M-1] for perm[0:length]."""
        # Initialize boundary: q[length][m] = 0 for all m
        for m in range(M):
            q[length][m] = 0
        for r in range(length - 1, -1, -1):
            job = perm[r]
            t = times[job]
            q[r][M - 1] = q[r + 1][M - 1] + t[M - 1]
            for m in range(M - 2, -1, -1):
                q[r][m] = max(q[r + 1][m], q[r][m + 1]) + t[m]

    def insertion_cost(perm, length, pos, job):
        """Compute makespan if job is inserted at position pos in perm[0:length]."""
        # Compute forward vector f for job up to machine M-1
        t = times[job]
        if pos == 0:
            f[0] = t[0]
            for m in range(1, M):
                f[m] = f[m - 1] + t[m]
        else:
            f[0] = e[pos - 1][0] + t[0]
            for m in range(1, M):
                f[m] = max(f[m - 1], e[pos - 1][m]) + t[m]
        # Compute makespan as max over m of f[m] + q[pos][m]
        max_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > max_val:
                max_val = val
        return max_val

    # --- NEH Construction with Taillard Acceleration ---
    current = []
    best_perm = []
    best_cmax = float('inf')

    for idx in range(N):
        job = order[idx]
        k = len(current)
        # Update forward and backward matrices for current partial schedule
        compute_forward(current, k)
        compute_backward(current, k)
        best_pos = 0
        best_cost = float('inf')
        # Try inserting job at each position 0..k
        for pos in range(k + 1):
            cost = insertion_cost(current, k, pos, job)
            if cost < best_cost:
                best_cost = cost
                best_pos = pos
        current.insert(best_pos, job)
        if best_cmax > best_cost:
            best_cmax = best_cost
            best_perm = current[:]

    # --- Iterated Greedy Refinement ---
    # Parameters calibrated for <50ms on N<=120, M<=20
    T_param = 0.5
    total_processing = sum(total_time)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0
    d = 3 if N > 20 else 2  # destruction size
    max_iter = 60  # iteration count

    pi = best_perm[:]
    pi_star = pi[:]
    cmax_star = best_cmax

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            destroyed = [pi[i] for i in indices]
            remaining = [pi[i] for i in range(N) if i not in indices_set]
        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        for job in destroyed:
            k = len(remaining)
            compute_forward(remaining, k)
            compute_backward(remaining, k)
            best_pos = 0
            best_cost = float('inf')
            for pos in range(k + 1):
                cost = insertion_cost(remaining, k, pos, job)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            remaining.insert(best_pos, job)
        pi_new = remaining
        cmax_new = makespan(pi_new)
        # Acceptance criterion
        if cmax_new < cmax_star:
            pi_star = pi_new[:]
            cmax_star = cmax_new
        if cmax_new < makespan(pi):
            pi = pi_new[:]
        else:
            if random.random() < math.exp(-(cmax_new - makespan(pi)) / T):
                pi = pi_new[:]

    return pi_star

