    # Compute backward tail matrix q for suffix perm[r:k]
    def compute_backward(perm, k):
        q = [[0] * M for _ in range(k+1)]  # q[k][:] = 0
        for r in range(k-1, -1, -1):
            job = perm[r]
            pj = p[job]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    # Evaluate makespan for inserting job x at each position in perm (length k)
    # Returns best position and makespan
    def best_insert_position(perm, k, x):
        if k == 0:
            return 0, p[x][0] if M == 1 else _makespan_single_job(x)
        e = compute_forward(perm, k)
        q = compute_backward(perm, k)
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            # forward vector f for job x after prefix perm[0:i]
            f = [0] * M
            if i == 0:
                f[0] = p[x][0]
                for m in range(1, M):
                    f[m] = f[m-1] + p[x][m]
            else:
                f[0] = e[i-1][0] + p[x][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + p[x][m]
            # makespan = max_m (f[m] + q[i][m])
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return best_pos, best_mk

    # Helper for single job makespan (used when k=0)
    def _makespan_single_job(x):
        return sum(p[x])

    # NEH construction with Taillard acceleration
    def construct_neh():
        # Job priority: total processing time descending
        job_order = sorted(range(N), key=lambda i: sum(p[i]), reverse=True)
        perm = [job_order[0]]
        for k in range(1, N):
            pos, _ = best_insert_position(perm, k, job_order[k])
            perm.insert(pos, job_order[k])
        return perm

    # Iterated Greedy metaheuristic
    def iterated_greedy(init_perm, max_iter=60):
        current = init_perm[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing = sum(sum(row) for row in p)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        d = 3 if N > 20 else 2  # destruction size

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in sorted(indices, reverse=True)]
            for idx in sorted(indices, reverse=True):
                del current[idx]
            # Reconstruction: reinsert each removed job using NEH insertion
            for job in removed:
                pos, _ = best_insert_position(current, len(current), job)
                current.insert(pos, job)
            # Acceptance criterion
            curr_mk = makespan(current)
            if curr_mk < best_mk:
                best_mk = curr_mk
                best = current[:]
            if curr_mk < makespan(best):  # always true if improved, but keep for symmetry
                best = current[:]
                best_mk = curr_mk
            elif curr_mk == makespan(best):
                pass
            else:
                # Metropolis acceptance
                if random.random() < math.exp(-(curr_mk - makespan(best)) / T):
                    current = current[:]  # accept worse solution
                else:
                    # revert to previous current (not stored, so keep as is if not accepted)
                    # Actually, we only change current if accepted; so no revert needed
                    pass
            # Early exit if optimal (optional, requires LB which we skip for speed)
        return best

    # Build initial solution
    init_perm = construct_neh()
    # Refine with Iterated Greedy
    return iterated_greedy(init_perm, max_iter=50)

