def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slopes
    total = [sum(job) for job in times]
    slope = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Helper: makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Helper: compute forward completion matrix for a given permutation
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][m] = prev + times[job][m]
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + times[job][m]
        return e

    # Helper: compute backward tail matrix for a given permutation
    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    down = q[r+1][m]
                    right = q[r][m+1]
                    q[r][m] = max(down, right) + times[job][m]
        return q

    # Helper: evaluate makespan after inserting job x at position i in current perm
    def evaluate_insertion(perm, x, i, e, q):
        k = len(perm)
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev = e[i-1][0] if i-1 >= 0 else 0
                f[m] = prev + times[x][m]
            else:
                left = f[m-1]
                up = e[i-1][m] if i-1 >= 0 else 0
                f[m] = max(left, up) + times[x][m]
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    def neh_construction(order):
        if not order:
            return []
        perm = [order[0]]
        if len(order) > 1:
            seq1 = [order[0], order[1]]
            seq2 = [order[1], order[0]]
            if makespan(seq1) <= makespan(seq2):
                perm = seq1
            else:
                perm = seq2
        for idx in range(2, len(order)):
            job = order[idx]
            e = compute_forward(perm)
            q = compute_backward(perm)
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(perm) + 1):
                cmax = evaluate_insertion(perm, job, pos, e, q)
                if cmax < best_makespan:
                    best_makespan = cmax
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # Try multiple orderings: total time descending, slope descending
    order_total = sorted(range(N), key=lambda i: total[i], reverse=True)
    order_slope = sorted(range(N), key=lambda i: slope[i], reverse=True)

    best_perm = neh_construction(order_total)
    best_makespan = makespan(best_perm)
    perm2 = neh_construction(order_slope)
    m2 = makespan(perm2)
    if m2 < best_makespan:
        best_makespan = m2
        best_perm = perm2

    # Iterated Greedy refinement
    T_param = 0.5
    total_processing = sum(total)
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 50
    current = best_perm[:]

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        indices_set = set(indices)
        current_D = [current[i] for i in range(N) if i not in indices_set]

        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            e = compute_forward(current_D)
            q = compute_backward(current_D)
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(current_D) + 1):
                cmax = evaluate_insertion(current_D, job, pos, e, q)
                if cmax < best_makespan:
                    best_makespan = cmax
                    best_pos = pos
            current_D.insert(best_pos, job)

        # Acceptance criterion
        new_makespan = makespan(current_D)
        current_makespan = makespan(current)
        if new_makespan < current_makespan:
            current = current_D[:]
            if new_makespan < best_makespan:
                best_makespan = new_makespan
                best_perm = current_D[:]
        elif new_makespan < best_makespan:
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current = current_D[:]

    return best_perm

