def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(row) for row in times)
    makespan_lower_bound = 0
    for m in range(M):
        sum_m = sum(times[i][m] for i in range(N))
        min_before = min((sum(times[i][l] for l in range(m)) for i in range(N)), default=0)
        min_after = min((sum(times[i][l] for l in range(m+1, M)) for i in range(N)), default=0)
        lb_m = min_before + sum_m + min_after
        if lb_m > makespan_lower_bound:
            makespan_lower_bound = lb_m

    job_totals = [sum(times[i]) for i in range(N)]
    job_order = sorted(range(N), key=lambda i: (-job_totals[i], i))

    e = [0] * M
    q = [0] * M
    f = [0] * M

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for idx in perm:
            job = times[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def compute_forward(perm):
        if not perm:
            return [0] * M
        e[0] = times[perm[0]][0]
        for m in range(1, M):
            e[m] = e[m-1] + times[perm[0]][m]
        for r in range(1, len(perm)):
            job = times[perm[r]]
            e[0] += job[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + job[m]
        return e[:]

    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [0] * M
        q[M-1] = times[perm[k-1]][M-1]
        for m in range(M-2, -1, -1):
            q[m] = q[m+1] + times[perm[k-1]][m]
        for r in range(k-2, -1, -1):
            job = times[perm[r]]
            q[M-1] += job[M-1]
            for m in range(M-2, -1, -1):
                q[m] = max(q[m], q[m+1]) + job[m]
        return q[:]

    def insertion_cost(perm, job_idx, pos):
        job = times[job_idx]
        if pos == 0:
            f[0] = job[0]
            for m in range(1, M):
                f[m] = f[m-1] + job[m]
        else:
            f[0] = e[pos-1][0] + job[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + job[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_construct():
        if not job_order:
            return []
        perm = [job_order[0]]
        if N > 1:
            job1, job2 = job_order[0], job_order[1]
            cost1 = makespan([job1, job2])
            cost2 = makespan([job2, job1])
            perm = [job1, job2] if cost1 <= cost2 else [job2, job1]
            start_k = 2
        else:
            start_k = 1
        for k in range(start_k, N):
            job_idx = job_order[k]
            compute_forward(perm)
            compute_backward(perm)
            best_pos = 0
            best_cost = insertion_cost(perm, job_idx, 0)
            for pos in range(1, k+1):
                cost = insertion_cost(perm, job_idx, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            perm.insert(best_pos, job_idx)
        return perm

    def ig_improve(initial_perm, max_iters=60):
        if N <= 2:
            return initial_perm
        perm = initial_perm[:]
        best_perm = perm[:]
        best_cost = makespan(best_perm)
        if best_cost == makespan_lower_bound:
            return best_perm
        T_param = 0.5
        T = T_param * total_processing / (10.0 * N * M)
        d = 3 if N > 5 else 2
        for _ in range(max_iters):
            if makespan(perm) == makespan_lower_bound:
                break
            indices = list(range(N))
            random.shuffle(indices)
            removed = []
            remaining = []
            for idx in indices:
                if len(removed) < d:
                    removed.append(perm[idx])
                else:
                    remaining.append(perm[idx])
            perm = remaining[:]
            random.shuffle(removed)
            for job in removed:
                compute_forward(perm)
                compute_backward(perm)
                best_pos = 0
                best_cost = insertion_cost(perm, job, 0)
                for pos in range(1, len(perm)+1):
                    cost = insertion_cost(perm, job, pos)
                    if cost < best_cost:
                        best_cost = cost
                        best_pos = pos
                perm.insert(best_pos, job)
            current_cost = makespan(perm)
            if current_cost < best_cost:
                best_cost = current_cost
                best_perm = perm[:]
            if current_cost < makespan(perm):
                perm = perm[:]
            elif current_cost > makespan(perm):
                if random.random() < math.exp(-(current_cost - makespan(perm)) / T):
                    perm = perm[:]
                else:
                    perm = best_perm[:]
        return best_perm

    initial_perm = neh_construct()
    improved_perm = ig_improve(initial_perm)
    return improved_perm

