    seq = [0] * n
    jobs = list(range(n))
    while jobs:
        min_val = float('inf')
        min_job = -1
        min_side = ''
        for j in jobs:
            if p1[j] < min_val:
                min_val = p1[j]
                min_job = j
                min_side = 'left'
            if p2[j] < min_val:
                min_val = p2[j]
                min_job = j
                min_side = 'right'
        if min_side == 'left':
            seq[left] = min_job
            left += 1
        else:
            seq[right] = min_job
            right -= 1
        jobs.remove(min_job)
    return seq

def cds_variant(times):
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])
    best_seq = None
    best_mk = float('inf')
    for l in range(1, m):
        p1 = [sum(times[i][:l]) for i in range(n)]
        p2 = [sum(times[i][m-l:]) for i in range(n)]
        seq = johnson_rule(p1, p2)
        mk = makespan(seq, times)
        if mk < best_mk:
            best_mk = mk
            best_seq = seq
    return best_seq

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    return cds_variant(times)

