        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_data = [row[:] for row in times]
    total_processing = [sum(row) for row in job_data]
    total_sum = sum(total_processing)

    # Makespan evaluation using Taillard's forward pass
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            p = job_data[job]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[m]
        return t[M-1]

    # NEH construction with Taillard acceleration
    def neh_construction():
        order = sorted(range(N), key=lambda i: total_processing[i], reverse=True)
        if N == 1:
            return order
        # Initial pair
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        # Greedy insertion with Taillard acceleration
        for k in range(2, N):
            job = order[k]
            # Forward matrix e for current seq (length k)
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                pj = job_data[seq[r]]
                if r == 0:
                    e[0][0] = pj[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + pj[m]
                else:
                    e[r][0] = e[r-1][0] + pj[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
            # Backward matrix q for current seq (length k)
            q = [[0] * M for _ in range(k+1)]
            # q[k][m] = 0 already
            for r in range(k-1, -1, -1):
                pj = job_data[seq[r]]
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
            # Find best insertion position
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Forward vector f for job at position i
                f = [0] * M
                if i == 0:
                    f[0] = job_data[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + job_data[job][m]
                else:
                    f[0] = e[i-1][0] + job_data[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + job_data[job][m]
                # Compute makespan if inserted at i
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Metropolis acceptance
    def iterated_greedy(initial_seq):
        current_seq = initial_seq[:]
        current_mk = makespan(current_seq)
        best_seq = current_seq[:]
        best_mk = current_mk
        T_param = 0.5
        T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N >= 3 else N
        max_iter = 60
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current_seq[i] for i in indices]
            # Build partial sequence without removed indices
            marker = [False] * N
            for idx in indices:
                marker[idx] = True
            partial_seq = [current_seq[i] for i in range(N) if not marker[i]]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                # Rebuild forward matrix e for current partial_seq
                k = len(partial_seq)
                if k == 0:
                    e = []
                else:
                    e = [[0] * M for _ in range(k)]
                    for r in range(k):
                        pj = job_data[partial_seq[r]]
                        if r == 0:
                            e[0][0] = pj[0]
                            for m in range(1, M):
                                e[0][m] = e[0][m-1] + pj[m]
                        else:
                            e[r][0] = e[r-1][0] + pj[0]
                            for m in range(1, M):
                                e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
                # Rebuild backward matrix q for current partial_seq
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    pj = job_data[partial_seq[r]]
                    q[r][M-1] = q[r+1][M-1] + pj[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
                # Find best insertion position for job
                best_pos = 0
                best_mk = float('inf')
                for i in range(k+1):
                    # Forward vector f for job at position i
                    f = [0] * M
                    if i == 0:
                        f[0] = job_data[job][0]
                        for m in range(1, M):
                            f[m] = f[m-1] + job_data[job][m]
                    else:
                        f[0] = e[i-1][0] + job_data[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + job_data[job][m]
                    # Compute makespan if inserted at i
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk:
                        best_mk = mk
                        best_pos = i
                partial_seq.insert(best_pos, job)
            new_seq = partial_seq
            new_mk = makespan(new_seq)
            # Acceptance criterion
            if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
                current_seq = new_seq
                current_mk = new_mk
                if new_mk < best_mk:
                    best_seq = new_seq[:]
                    best_mk = new_mk
        return best_seq

    # Run the pipeline
    initial_seq = neh_construction()
    final_seq = iterated_greedy(initial_seq)
    return final_seq

