def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square, binary entries)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build bitmask for each vertex: bit_adj[u] has bit v set if (u,v) is an edge
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # Precompute degrees
        degrees = [len(adj_list[i]) for i in range(n)]
        # Track saturation sets as bitmasks
        saturation = [0] * n  # bitmask of colors used by neighbors
        colored = [False] * n
        # Order vertices by saturation degree, then degree, then index
        for _ in range(n):
            # Select uncolored vertex with max saturation, then max degree, then min index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                sat = saturation[u].bit_count()
                deg = degrees[u]
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and u < v):
                    max_sat = sat
                    max_deg = deg
                    v = u
            # Assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            # Update saturation of neighbors
            for nb in adj_list[v]:
                if not colored[nb]:
                    saturation[nb] |= (1 << c)
        return colors

    # RLF (Recursive Largest First) - maximal independent set extraction
    def rlf():
        colors = [-1] * n
        colored = [False] * n
        color = 0
        # Precompute degrees in the full graph (for initial selection)
        degrees = [len(adj_list[i]) for i in range(n)]
        while not all(colored):
            # Find uncolored vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                # Count uncolored neighbors
                deg = 0
                for nb in adj_list[u]:
                    if not colored[nb]:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
            if v == -1:  # should not happen
                break
            # Build independent set for this color
            S = [v]
            colored[v] = True
            # U: uncolored vertices not adjacent to any in S (eligible)
            # W: uncolored vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if colored[u]:
                    continue
                if u == v:
                    continue
                # Check if adjacent to any in S
                adj_to_S = False
                for s in S:
                    if u in adj_list[s]:
                        adj_to_S = True
                        break
                if adj_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # While there are eligible vertices
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_count += 1
                    # Degree in U
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_in_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                S.append(u)
                colored[u] = True
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for node in S:
                colors[node] = color
            color += 1
        return colors

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degrees = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order
        # We'll use a list of sets for degrees, but n<=100 so we can scan
        for _ in range(n):
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if removed[u]:
                    continue
                # current degree: count neighbors not removed
                deg = 0
                for nb in adj_list[u]:
                    if not removed[nb]:
                        deg += 1
                if deg < min_deg:
                    min_deg = deg
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # Update degrees of neighbors (implicitly by removed flag)
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Kempe chain color reduction
    def kempe_reduce(colors_in):
        colors = colors_in[:]
        changed = True
        while changed:
            changed = False
            # Build color classes
            max_color = max(colors) if colors else -1
            if max_color < 0:
                break
            color_classes = [[] for _ in range(max_color + 1)]
            for v in range(n):
                color_classes[colors[v]].append(v)
            # Try to eliminate the last color class (largest color index)
            target_color = max_color
            if not color_classes[target_color]:
                # Already empty, should not happen if max_color is correct
                break
            # Try to recolor each vertex in target_color
            for v in color_classes[target_color]:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for nb in adj_list[v]:
                    if colors[nb] != -1:
                        used_by_neighbors |= (1 << colors[nb])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart the while loop after a change
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # If v already has a neighbor with color c, swapping might not help directly
                    # We look for a Kempe chain (target_color, c) that does not contain any neighbor of v with color c
                    # Build the component containing v in the subgraph of colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (colors[nb] == target_color or colors[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any neighbor of v has color c and is in this component
                    conflict = False
                    for nb in adj_list[v]:
                        if colors[nb] == c and visited[nb]:
                            conflict = True
                            break
                    if not conflict:
                        # Swap colors in the component
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            else:  # must be c
                                colors[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            # If we eliminated the target color class, compact colors
            if not changed:
                # No change made in this iteration
                break
            # Compact colors: reassign to 0..k-1
            mapping = {}
            next_color = 0
            for v in range(n):
                c = colors[v]
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
                colors[v] = mapping[c]
        return colors

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        colors = [-1] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        candidates.append(colors)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = kempe_reduce(best)
    best = normalize_colors(best)
    # Final validation (should be valid)
    if not is_valid_coloring(best):
        # Last resort: greedy
        colors = [-1] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best = normalize_colors(colors)
    return best

