def color_graph(adj: list[list[int]]) -> list[int]:
    # ----- Helper: detect and convert to adjacency list -----
    def to_adj_list(adj):
        n = len(adj)
        if n == 0:
            return []
        if isinstance(adj[0], list) and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            # adjacency matrix
            return [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
        else:
            # adjacency list (ensure symmetric and no self-loops)
            graph = [[] for _ in range(n)]
            for u in range(n):
                for v in adj[u]:
                    if u != v:
                        graph[u].append(v)
            # make undirected
            for u in range(n):
                for v in graph[u]:
                    if u not in graph[v]:
                        graph[v].append(u)
            return graph

    graph = to_adj_list(adj)
    n = len(graph)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # ----- Helper: check if coloring is valid -----
    def is_valid_coloring(colors):
        for u in range(n):
            cu = colors[u]
            for v in graph[u]:
                if cu == colors[v]:
                    return False
        return True

    # ----- Helper: number of colors used -----
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # ----- Helper: convert to bitmask for fast ops -----
    def to_bitmask():
        bit_adj = [0] * n
        for u in range(n):
            mask = 0
            for v in graph[u]:
