        if uncolored:
            v = max(uncolored, key=lambda x: len(graph[x]))
            colors[v] = 0
            uncolored.remove(v)
            # update neighbors
            for u in graph[v]:
                if u in uncolored:
                    neighbor_color_mask[u] |= 1 << 0
                    saturation[u] = 1

        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            def saturation_and_degree(v):
                sat = saturation[v]
                deg = sum(1 for nb in graph[v] if nb in uncolored)
                return (sat, deg, random.random())
            v = max(uncolored, key=saturation_and_degree)
            # find smallest available color
            mask = neighbor_color_mask[v]
            c = 0
            while mask & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in graph[v]:
                if u in uncolored:
                    if not (neighbor_color_mask[u] & (1 << c)):
                        neighbor_color_mask[u] |= (1 << c)
                        saturation[u] += 1
        return colors

    # ----- RLF (Recursive Largest First) -----
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # build maximal independent set for color_idx
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in graph[x] if nb in uncolored))
            independent_set = {v}
            # partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u != v and v not in graph[u]}
            W = {u for u in uncolored if u != v and v in graph[u]}
            while U:
                # select u in U with max |N(u) ∩ W|
                def score(u):
                    # count neighbors in W
                    cnt = sum(1 for nb in graph[u] if nb in W)
                    # tie-break: min degree in U
                    degU = sum(1 for nb in graph[u] if nb in U)
                    return (cnt, -degU, random.random())
                u = max(U, key=score)
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in graph[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color
            for vertex in independent_set:
                colors[vertex] = color_idx
                uncolored.remove(vertex)
            color_idx += 1
        return colors

    # ----- Smallest-Last ( degeneracy ordering ) greedy -----
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(graph[u]) for u in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # pointer to current min non-empty bucket
        min_deg = 0
        while remaining:
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            # remove v
            remaining.remove(v)
            order.append(v)
            # update neighbors
            for u in graph[v]:
                if u in remaining:
                    # remove u from its bucket
                    old_deg = degree[u]
                    buckets[old_deg].remove(u)
                    degree[u] -= 1
                    new_deg = degree[u]
                    buckets[new_deg].append(u)
                    if new_deg < min_deg:
                        min_deg = new_deg
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)  # safe size
            for u in graph[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            c = 0
            while used[c]:
