        k = num_colors(colors)
        if k <= 1:
            return colors
        # make copy to work on
        col = colors[:]
        improved = True
        while improved and k > 1:
            improved = False
            # target smallest color class (color k-1)
            target_color = k - 1
            vertices = [v for v in range(n) if col[v] == target_color]
            if not vertices:
                # should not happen, but safety
                break
            # try to recolor each vertex in target class
            for v in vertices:
                # try direct reassignment to a lower color
                neighbor_colors = {col[u] for u in graph[v]}
                for c in range(target_color):
                    if c not in neighbor_colors:
                        col[v] = c
                        improved = True
                        break
                if improved:
                    # after moving v, check if target color class is empty
                    if not any(col[x] == target_color for x in range(n)):
                        # compact colors: shift down all colors > target_color by 1
                        for x in range(n):
                            if col[x] > target_color:
                                col[x] -= 1
                        k -= 1
                        target_color = k - 1
                        break  # restart while loop
                else:
                    # try Kempe chains with each lower color
                    for c in range(target_color):
                        if c in neighbor_colors:
                            continue  # adjacent, cannot swap directly
                        # find Kempe chain (c, target_color) containing v
                        # BFS/DFS over vertices colored c or target_color
