                            else:  # must be target_color
                                col[node] = c
                        improved = True
                        # after swap, check if target color class is empty
                        if not any(col[x] == target_color for x in range(n)):
                            for x in range(n):
                                if col[x] > target_color:
                                    col[x] -= 1
                            k -= 1
                            target_color = k - 1
                        break  # break color loop
                    if improved:
