        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits
    def popcount(x: int) -> int:
        return x.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(adj_list[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in adj_list[v]:
                if color[u] == -1:
                    sat[u] += 1
        while uncolored:
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                v = next(iter(uncolored))
            else:
                v = max(candidates, key=lambda x: len(adj_list[x]))
            # Find smallest available color
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in adj_list[v]:
                if color[u] == -1:
                    sat[u] += 1
        return color

    # RLF: Recursive Largest First independent set extraction
    def rlf() -> list[int]:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set S for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.add(v)
            # Partition: U = uncolored \ S not adjacent to S, W = adjacent to S
            U = set()
            W = set()
            for u in uncolored:
                if u in S:
                    continue
                if any((bit_adj[w] >> u) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in U
                        deg_u = len([y for y in adj_list[u] if y in U])
                        deg_best = len([y for y in adj_list[best_u] if y in U]) if best_u is not None else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last() -> list[int]:
        # Compute degeneracy ordering (smallest last)
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        remaining = set(range(n))
        # Bucket queue for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = buckets[degrees[v]].index(v) if v in buckets[degrees[v]] else -1
        # Simulate peeling
        for _ in range(n):
            # Find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    # Remove u from its bucket
                    du = degrees[u]
                    if pos[u] >= 0 and pos[u] < len(buckets[du]):
                        buckets[du].pop(pos[u])
                    degrees[u] -= 1
                    buckets[degrees[u]].append(u)
                    pos[u] = len(buckets[degrees[u]]) - 1
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring: list[int]) -> list[int]:
        color = coloring[:]
        k = max(color) + 1 if n > 0 else 0
        improved = True
        while improved and k > 0:
            improved = False
            # Find smallest color class (highest index)
            target = k - 1
            # Get vertices with target color
            targets = [v for v in range(n) if color[v] == target]
            if not targets:
                k -= 1
                continue
            # Try to recolor each target vertex
            for v in targets:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if color[u] != -1:
                        used |= (1 << color[u])
                for c in range(target):
                    if not (used & (1 << c)):
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swaps
                for c in range(target):
                    # Build (target, c)-Kempe chain component containing v
                    stack = [v]
                    visited = set()
                    comp = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if color[node] == target or color[node] == c:
                            comp.add(node)
                            for u in adj_list[node]:
                                if color[u] == target or color[u] == c:
                                    if u not in visited:
                                        stack.append(u)
                    # Check if we can swap: no neighbor of v in comp has color c (other than via chain)
                    # Actually, swapping is safe if the component does not contain a neighbor of v with color c
                    # that would cause conflict after swap? Standard: swapping a Kempe chain preserves validity.
                    # We can swap if after swap, v can take color c without conflict.
                    # After swap, v would have color c. Check neighbors: none should have color c.
                    conflict = False
                    for u in adj_list[v]:
                        if color[u] == c and u not in comp:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap on component
                        for node in comp:
                            if color[node] == target:
                                color[node] = c
                            else:
                                color[node] = target
                        improved = True
                        break
                if improved:
                    break
            # If we improved, recompute k and try again
            if improved:
                k = max(color) + 1
            else:
                # Cannot eliminate target color, break
                break
        # Compact colors to 0..k-1
        # Map existing colors to consecutive integers
        unique_colors = sorted(set(color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        color = [mapping[c] for c in color]
        return color

    # Generate candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        # Validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = len(set(col))
        if k < best_k:
            best_k = k
            best = col
    if best is None:
        best = dsatur()  # fallback

    # Apply Kempe reduction
    best = kempe_reduce(best)

    # Final validation (should always hold)
    for u in range(n):
        for v in adj_list[u]:
            if best[u] == best[v]:
                # In case of error, fallback to DSATUR
                return dsatur()
    return best

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    # ---------- Input handling ----------
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]
    # Detect adjacency matrix
    is_matrix = (
        len(adj) > 0 and
        len(adj[0]) == len(adj) and
        all(isinstance(x, int) and x in (0, 1) for row in adj for x in row)
    )
    if is_matrix:
        # Convert to adjacency list for uniform processing
        adj_list = []
        for u in range(n):
            neighbors = [v for v, val in enumerate(adj[u]) if val == 1]
            adj_list.append(neighbors)
    else:
        # Ensure adjacency list is clean
        adj_list = []
        for u in range(n):
            # Filter self-loops and ensure unique neighbors
            nbrs = set()
            for v in adj[u]:
                if v != u and 0 <= v < n:
                    nbrs.add(v)
            adj_list.append(list(nbrs))
    # ---------- Bitmask adjacency ----------
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # ---------- Helper functions ----------
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    def count_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # ---------- DSATUR ----------
    def dsatur():
        colors = [-1] * n
        # saturation: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets as bitmasks for fast saturation update
        neighbor_colors = [0] * n
        uncolored = set(range(n))
        # initial degree for tie-breaking
        degree = [len(adj_list[u]) for u in range(n)]
        while uncolored:
            # select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], degree[x], random.random()))
            # compute mex (minimum excluded color) from neighbor colors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update saturation and neighbor colors for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1
        return compact_colors(colors)

    # ---------- RLF ----------
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # build independent set for this color
            # degree in current uncolored subgraph
            deg_uncolored = [0] * n
            for u in uncolored:
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg_uncolored[u] = cnt
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: (deg_uncolored[x], random.random()))
            independent_set = {v}
            # candidates: uncolored and not adjacent to any in independent_set
            candidates = uncolored - {v}
            # remove neighbors of v from candidates
            for u in adj_list[v]:
                if u in candidates:
                    candidates.remove(u)
            # ineligible: neighbors of independent_set
            ineligible = set()
            for u in independent_set:
                for w in adj_list[u]:
                    if w in uncolored and w not in independent_set:
                        ineligible.add(w)
            # main loop
            while candidates:
                # select u in candidates with max neighbors in ineligible
                def score(u):
                    cnt = 0
                    for w in adj_list[u]:
                        if w in ineligible:
                            cnt += 1
                    return cnt
                # tie-break by min degree in candidates subgraph
                def degree_in_candidates(u):
                    cnt = 0
                    for w in adj_list[u]:
                        if w in candidates:
                            cnt += 1
                    return cnt
                u = max(candidates, key=lambda x: (score(x), -degree_in_candidates(x), random.random()))
                independent_set.add(u)
                candidates.remove(u)
                # move neighbors of u from candidates to ineligible
                for w in adj_list[u]:
                    if w in candidates:
                        candidates.remove(w)
                        ineligible.add(w)
            # assign color to independent_set
            for u in independent_set:
                colors[u] = color
            uncolored -= independent_set
            color += 1
        return compact_colors(colors)

    # ---------- Smallest-Last (Degeneracy ordering) ----------
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[u]) for u in range(n)]
        # bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degrees[u]].add(u)
        # pointer to current min degree
        min_deg = 0
        while remaining:
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degrees[u]
                    buckets[d].remove(u)
                    degrees[u] -= 1
                    buckets[degrees[u]].add(u)
        # color in reverse order using greedy
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= 1 << colors[u]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # ---------- Kempe chain color reduction ----------
    def kempe_reduce(colors):
        k = count_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, 0, -1):
            # vertices with target_color
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            made_change = False
            for v in verts:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        neighbor_colors |= 1 << colors[u]
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        colors[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    if colors[v] == c:
                        continue
                    # Find the (c, target_color) Kempe chain containing v
                    # BFS to get component
                    stack = [v]
                    visited = set()
                    comp_color_v = colors[v]
                    comp_color_c = c
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        for nb in adj_list[node]:
                            if nb in visited:
                                continue
                            col_nb = colors[nb]
                            if col_nb == comp_color_v or col_nb == comp_color_c:
                                stack.append(nb)
                    # Check if color c is absent in the component's neighborhood
                    # Actually, we can swap if the component does not contain a vertex of color c
                    # that is adjacent to a vertex outside the component that would cause conflict?
                    # Standard: swapping is always valid; we just need to see if it helps free target_color for v
                    # After swap, v will have color c. We want to know if this reduces the number of vertices in target_color.
                    # It will, because v leaves target_color.
                    # However, we must ensure we don't accidentally increase another class? Swapping preserves validity.
                    # So we can always swap and v will no longer be in target_color.
                    # Perform swap
                    for node in visited:
                        if colors[node] == comp_color_v:
                            colors[node] = comp_color_c
                        elif colors[node] == comp_color_c:
                            colors[node] = comp_color_v
                    made_change = True
                    break
                if made_change:
                    break
            if not made_change:
                # Could not eliminate this color class, move to next lower target color
                continue
            else:
                # After change, recompute and try again from highest color
                k = count_colors(colors)
                # restart reduction from current highest
                break
        # Compact colors
        return compact_colors(colors)

    # ---------- Main ----------
    start_time = time.time()
    # Generate candidate colorings
    candidates = []
    # DSATUR
    if time.time() - start_time < 0.04:  # leave some buffer
        col1 = dsatur()
        if is_valid_coloring(col1):
            candidates.append(col1)
    # RLF
    if time.time() - start_time < 0.04:
        col2 = rlf()
        if is_valid_coloring(col2):
            candidates.append(col2)
    # Smallest-Last
    if time.time() - start_time < 0.04:
        col3 = smallest_last()
        if is_valid_coloring(col3):
            candidates.append(col3)
    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        # simple greedy ordering by degree
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= 1 << colors[u]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(compact_colors(colors))
    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: (count_colors(x), x))
    # Apply Kempe reduction iteratively (with time check)
    improved = kempe_reduce(best)
    if is_valid_coloring(improved) and count_colors(improved) < count_colors(best):
        best = improved
    # Final validation and compact
    best = compact_colors(best)
    if not is_valid_coloring(best):
        # As a last resort, use DSATUR again (should be valid)
        best = dsatur()
        best = compact_colors(best)
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Convert to adjacency list and build bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # Degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = bit_count(saturation[u])
                deg_u = uncolored_deg[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            if v == -1:
                break  # Should not happen

            # Find smallest available color (mex)
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)

            # Update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # RLF: Recursive Largest First via independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = []
            # Degrees in current uncolored subgraph
            deg = {u: 0 for u in uncolored}
            for u in uncolored:
                for v in adj_list[u]:
                    if v in uncolored:
                        deg[u] += 1
            # Start with vertex of max degree
            v = max(uncolored, key=lambda u: deg[u])
            S.append(v)
            # Partition: U = not adj to S, W = adj to S
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in adj_list[u] for w in S):
                    U.remove(u)
                    W.add(u)
            # Extract independent set
            while U:
                # Select u in U with max neighbors in W, tie-break by min deg in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or \
                       (w_neighbors == max_w_neighbors and deg_u == min_deg_u and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                if best_u == -1:
                    break  # Should not happen
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= set(S)
            c += 1
        return color

    # Smallest-Last (SL) ordering greedy
    def smallest_last():
        # Build SL ordering: repeatedly remove min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # Use bucket sort for efficiency (max degree < n)
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].append(i)
        # Pointer to current min non-empty bucket
        min_ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while min_ptr <= max_deg and not buckets[min_ptr]:
                min_ptr += 1
            if min_ptr > max_deg:
                break  # Should not happen
            v = buckets[min_ptr].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    old_deg = deg[u]
                    deg[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].remove(u)  # O(n) but n <= 100
                    if deg[u] <= max_deg:
                        buckets[deg[u]].append(u)
                    if deg[u] < min_ptr:
                        min_ptr = deg[u]
        # Color in reverse order (last removed first)
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(color_in):
        color = color_in[:]  # work on a copy
        # Helper: get set of vertices by color
        def get_color_classes():
            classes = {}
            for v, c in enumerate(color):
                classes.setdefault(c, []).append(v)
            return classes

        # Helper: check if coloring is valid
        def is_valid():
            for u in range(n):
                for v in adj_list[u]:
                    if u < v and color[u] == color[v]:
                        return False
            return True

        # Helper: get (a,b)-Kempe component containing v
        def kempe_component(v, a, b):
            if color[v] not in (a, b):
                return set()
            comp = set()
            stack = [v]
            while stack:
                u = stack.pop()
                if u in comp:
                    continue
                comp.add(u)
                for w in adj_list[u]:
                    if w not in comp and color[w] in (a, b):
                        stack.append(w)
            return comp

        changed = True
        while changed:
            changed = False
            classes = get_color_classes()
            if not classes:
                break
            max_color = max(classes.keys())
            # Try to eliminate color classes from highest to lowest
            for target_color in sorted(classes.keys(), reverse=True):
                if target_color == 0:
                    continue  # cannot eliminate color 0
                vertices = classes[target_color]
                # Try to recolor each vertex in this class
                for v in vertices[:]:  # iterate over copy
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in adj_list[v]:
                        if color[u] != -1:
                            used |= (1 << color[u])
                    for c in range(target_color):  # only try lower colors
                        if not (used & (1 << c)):
                            color[v] = c
                            changed = True
                            break
                    if changed:
                        break  # restart after change
                    # Try Kempe chain swaps with each lower color
                    for c in range(target_color):
                        comp = kempe_component(v, target_color, c)
                        if not comp:
                            continue
                        # Check if swapping comp would cause conflict: 
                        # after swap, vertices in comp that were target_color become c, and vice versa.
                        # Conflict if any neighbor of a vertex in comp (not in comp) has color c (after swap) 
                        # or color target_color (after swap) -> but since we swap, we need:
                        # For any u in comp, any neighbor w not in comp: 
                        #   if color[w] == c, then after swap u becomes c -> conflict if u was target_color
                        #   if color[w] == target_color, then after swap u becomes target_color -> conflict if u was c
                        # Actually, after swap: 
                        #   u in comp: new_color = c if old was target_color, else target_color
                        # So conflict if:
                        #   exists u in comp, w not in comp, (u,w) edge, and 
                        #       (color[u] == target_color and color[w] == c) or 
                        #       (color[u] == c and color[w] == target_color)
                        safe = True
                        for u in comp:
                            for w in adj_list[u]:
                                if w not in comp:
                                    if (color[u] == target_color and color[w] == c) or \
                                       (color[u] == c and color[w] == target_color):
                                        safe = False
                                        break
                            if not safe:
                                break
                        if safe:
                            # Perform swap
                            for u in comp:
                                if color[u] == target_color:
                                    color[u] = c
                                else:
                                    color[u] = target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break  # restart while loop
            # If we eliminated the highest color, compact colors
            if changed:
                # Re-map colors to 0..k-1
                unique_colors = sorted(set(color))
                mapping = {old: new for new, old in enumerate(unique_colors)}
                color = [mapping[c] for c in color]
        # Final validation (should hold)
        if not is_valid():
            # Fallback: return original if something went wrong
            return color_in
        return color

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except Exception:
        pass

    # If no candidates, fallback to trivial greedy
    if not candidates:
        color = [0] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if color[j] != -1:  # but we assign in order, so only j < i?
                    used |= (1 << color[j])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        candidates.append(color)

    # Select candidate with fewest colors
    best_color = None
    best_k = float('inf')
    for col in candidates:
        k = len(set(col))
        if k < best_k:
            best_k = k
            best_color = col

    # Apply Kempe reduction to improve
    try:
        improved = kempe_reduce(best_color)
        k_improved = len(set(improved))
        if k_improved < best_k:
            best_color = improved
    except Exception:
        pass

    return best_color

