            if not removed:
                # cannot eliminate this color class
                break
            # recompact colors: rebuild mapping to 0..new_k-1
            # but we only removed color k-1, so just decrement higher colors? 
            # Actually, we might have swapped, so we need to recompute the set.
            # Simpler: rebuild color mapping
            unique = {}
            next_color = 0
            for v in range(n):
                if col[v] not in unique:
                    unique[col[v]] = next_color
                    next_color += 1
                col[v] = unique[col[v]]
            k = next_color
        return col

    # Apply Kempe reduction to the best candidate
    reduced = kempe_reduce(best_colors)
    k_reduced = count_colors(reduced)
    if k_reduced < best_k:
        best_k = k_reduced
        best_colors = reduced

    # Final validation and compacting (ensure 0..k-1)
    # Verify no conflicts
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_colors[u] == best_colors[v]:
                # Conflict found; fallback to greedy on original order
                best_colors = greedy_color(list(range(n)))
