        else:
            continue
        break
    # Compact colors
    mapping = {}
    next_c = 0
    for i in range(n):
        c = best_colors[i]
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
        best_colors[i] = mapping[c]

    return best_colors

