def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect input type: adjacency matrix if square and binary entries
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)

    # DSATUR heuristic
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (saturated[x], bin(bit_adj[x]).count('1') - bin(bit_adj[x] & sum(1 << u for u in uncolored if u != x)).count('1'), -x))
            # Find smallest available color
            used = 0
            for u in range(n):
                if colors[u] != -1 and (bit_adj[v] >> u) & 1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in range(n):
                if u in uncolored and (bit_adj[v] >> u) & 1:
                    saturated[u] += 1
        return colors

    # RLF heuristic
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for current color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: bin(bit_adj[x]).count('1') - bin(bit_adj[x] & sum(1 << u for u in uncolored)).count('1'))
            S.add(v)
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if not any((bit_adj[s] >> u) & 1 for s in S)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (bin(bit_adj[x] & sum(1 << w for w in W)).count('1'), -bin(bit_adj[x] & sum(1 << uu for uu in U)).count('1'), -x))
                S.add(u)
                U.remove(u)
                # Update U and W: move neighbors of u in U to W
                nbrs_u = {uu for uu in range(n) if (bit_adj[u] >> uu) & 1}
                to_move = U & nbrs_u
                U -= to_move
                W |= to_move
            # Assign color to S
            for v in S:
                colors[v] = color
            color += 1
        return colors

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        order = []
        remaining = set(range(n))
        # Use bucket sort for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current min degree
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # Remove v
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in range(n):
                if u in remaining and (bit_adj[v] >> u) & 1:
                    old_deg = degrees[u]
                    new_deg = old_deg - 1
                    degrees[u] = new_deg
                    if new_deg < len(buckets):
                        buckets[new_deg].append(u)
                    # If old degree bucket still has v? not needed
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in range(n):
                if colors[u] != -1 and (bit_adj[v] >> u) & 1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Kempe chain color reduction
    def kempe_reduce(colors):
        if n == 0:
            return colors
        # Map color to list of vertices
        color_classes = {}
        for v, c in enumerate(colors):
            color_classes.setdefault(c, []).append(v)
        max_color = max(color_classes.keys()) if color_classes else -1
        # Try to eliminate colors from highest downwards
        changed = True
        while changed and max_color >= 0:
            changed = False
            # Target smallest color class (by size)
            target_color = min(color_classes.keys(), key=lambda c: len(color_classes[c]))
            target_vertices = color_classes[target_color][:]
            # Try to recolor each vertex in target class
            for v in target_vertices:
                if colors[v] != target_color:  # May have been recolored
                    continue
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in range(n):
                    if (bit_adj[v] >> u) & 1 and colors[u] != -1:
                        neighbor_colors.add(colors[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Move v to color c
                        color_classes[target_color].remove(v)
                        colors[v] = c
                        color_classes.setdefault(c, []).append(v)
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Build (target_color, c)-Kempe chain containing v
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    while stack:
                        x = stack.pop()
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1 and y not in visited:
                                if colors[y] == target_color or colors[y] == c:
                                    visited.add(y)
                                    stack.append(y)
                    # Check if we can swap: no neighbor of v in the chain has color c? Actually, after swap, v becomes c.
                    # We need that no neighbor of v has color c after swap -> neighbors currently having color c must not be in the chain? 
                    # Standard: if the component does not contain a neighbor of v colored c, then swapping is safe.
                    safe = True
                    for y in range(n):
                        if (bit_adj[v] >> y) & 1 and colors[y] == c and y in visited:
                            safe = False
                            break
                    if safe:
                        # Perform swap
                        for y in visited:
                            if colors[y] == target_color:
                                colors[y] = c
                            elif colors[y] == c:
                                colors[y] = target_color
                        # Update color classes
                        for y in visited:
                            if colors[y] == target_color:
                                color_classes[target_color].append(y)
                                color_classes[c].remove(y)
                            elif colors[y] == c:
                                color_classes[c].append(y)
                                color_classes[target_color].remove(y)
                        changed = True
                        break
            # If target color class is empty, remove it and compact
            if target_color in color_classes and not color_classes[target_color]:
                del color_classes[target_color]
                # Reindex colors greater than target_color down by 1
                new_colors = {}
                for col, verts in color_classes.items():
                    new_col = col - 1 if col > target_color else col
                    new_colors[new_col] = verts
                color_classes = new_colors
                # Update colors list
                for v in range(n):
                    if colors[v] > target_color:
                        colors[v] -= 1
                max_color = max(color_classes.keys()) if color_classes else -1
        return colors

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        # Validate
        valid = True
        for u in range(n):
            for v in range(u+1, n):
                if ((bit_adj[u] >> v) & 1) and c1[u] == c1[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        valid = True
        for u in range(n):
            for v in range(u+1, n):
                if ((bit_adj[u] >> v) & 1) and c2[u] == c2[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        valid = True
        for u in range(n):
            for v in range(u+1, n):
                if ((bit_adj[u] >> v) & 1) and c3[u] == c3[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to trivial
    if not candidates:
        return list(range(n))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda col: len(set(col)))
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compacting
    # Ensure colors are consecutive starting from 0
    unique_colors = sorted(set(best))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best = [mapping[c] for c in best]
    return best

