def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree array
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = adj[i]
            nbrs = [j for j in range(n) if row[j] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = adj  # already adjacency list

    # Compute initial degrees
    deg = [len(neighbors[i]) for i in range(n)]

    # Smallest-Last ordering: repeatedly remove vertex with minimum degree
    order = []
    removed = [False] * n
    current_deg = deg[:]  # copy of degrees to update

    for _ in range(n):
        # Find unremoved vertex with minimum current degree
        min_deg = math.inf
        v = -1
        for i in range(n):
            if not removed[i] and current_deg[i] < min_deg:
                min_deg = current_deg[i]
                v = i
        if v == -1:  # should not happen for n>0
            break
        order.append(v)
        removed[v] = True
        # Decrease degree of all unremoved neighbors
        for u in neighbors[v]:
            if not removed[u]:
                current_deg[u] -= 1

    # Color in reverse order using First-Fit (greedy)
    color = [-1] * n
    for v in reversed(order):
        # Determine colors used by already colored neighbors
        used = [False] * n  # at most n colors needed
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        # Find smallest non-negative integer color not used
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c

    return color

