        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            max_sat = -1
            max_deg = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                deg = sum(1 for nb in adj_list[v] if nb in uncolored)
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and v > best_v):
                    max_sat = sat
                    max_deg = deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    saturated[nb] |= 1 << c
        return colors

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in adj_list[x] if nb in uncolored))
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and all(nb not in S for nb in adj_list[u])}
            W = {u for u in uncolored if u not in S and any(nb in S for nb in adj_list[u])}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for nb in adj_list[u] if nb in W)
                    deg_u = sum(1 for nb in adj_list[u] if nb in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or (w_neighbors == max_w_neighbors and deg_u == min_deg_u and u < best_u):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                colors[v] = color
            uncolored -= S
            color += 1
        return colors

    # Heuristic 3: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[v]) for v in range(n)]
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    d = degrees[nb]
                    # Remove nb from its bucket
                    if nb in buckets[d]:
                        buckets[d].remove(nb)
                    degrees[nb] -= 1
                    d_new = degrees[nb]
                    buckets[d_new].append(nb)
                    if d_new < ptr:
                        ptr = d_new
        # Color in reverse order
        return greedy_coloring(order[::-1])

    # Run all heuristics
    for heuristic in [dsatur, rlf, smallest_last]:
        coloring = heuristic()
        k = validate_and_count(coloring)
        if k is not None and k < best_k:
            best_k = k
            best_coloring = coloring[:]

    # Fallback: if no heuristic produced valid coloring (should not happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_coloring(list(range(n)))
        best_k = validate_and_count(best_coloring)

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # Try to eliminate color classes from highest to lowest
        changed = True
        while changed:
            changed = False
            # Determine current number of colors
            max_color = max(coloring) if coloring else -1
            if max_color < 0:
                return coloring
            # Try to eliminate each color class, starting from the largest color index
            for target_color in range(max_color, -1, -1):
                # Collect vertices with target_color
                targets = [v for v in range(n) if coloring[v] == target_color]
                if not targets:
                    continue
                # Try to recolor each target vertex
                for v in targets:
                    # Try direct reassignment to a lower color
                    neighbor_colors = set()
                    for nb in adj_list[v]:
                        c = coloring[nb]
                        if c != -1:
                            neighbor_colors.add(c)
                    for c in range(target_color):  # only try lower colors
                        if c not in neighbor_colors:
                            coloring[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chain swaps with each lower color
                    for c in range(target_color):
                        # Find the (target_color, c)-Kempe chain containing v
                        # BFS to get component
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            x = queue.popleft()
                            component.append(x)
                            for nb in adj_list[x]:
                                if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                    visited[nb] = True
                                    queue.append(nb)
                        # Check if swapping colors in component would cause conflict
                        # After swap: target_color -> c, c -> target_color
                        # For each node in component, check neighbors outside component
                        valid = True
                        for x in component:
                            new_color = c if coloring[x] == target_color else target_color
                            for nb in adj_list[x]:
                                if coloring[nb] != target_color and coloring[nb] != c:  # neighbor not in chain
                                    if coloring[nb] == new_color:
                                        valid = False
                                        break
                            if not valid:
                                break
                        if valid:
                            # Perform swap
                            for x in component:
                                if coloring[x] == target_color:
                                    coloring[x] = c
                                else:
                                    coloring[x] = target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # After attempting to eliminate a color, compact colors if possible
            if changed:
                # Relabel colors to be consecutive starting from 0
                unique_colors = {}
                next_color = 0
                for v in range(n):
                    c = coloring[v]
                    if c not in unique_colors:
                        unique_colors[c] = next_color
                        next_color += 1
                    coloring[v] = unique_colors[c]
        return coloring

    best_coloring = kempe_reduction(best_coloring)
    # Final validation and compaction
    unique_colors = {}
    next_color = 0
    for v in range(n):
        c = best_coloring[v]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_coloring[v] = unique_colors[c]
    return best_coloring

