def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    # Convert to adjacency list if needed
    if n > 0 and len(adj[0]) == n and all(x in (0, 1) for row in adj for x in row):
        graph = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    graph[u].append(v)
    else:
        graph = adj

    # Helper to check if a coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in graph[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper to get number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper to renumber colors to be consecutive starting from 0
    def renumber_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # Strategy 1: Bipartite extraction + greedy on odd cycles
    def bipartite_plus_greedy():
        color = [-1] * n
        # Try to 2-color using BFS
        for start in range(n):
            if color[start] == -1:
                color[start] = 0
                q = deque([start])
                while q:
                    u = q.popleft()
                    for v in graph[u]:
                        if color[v] == -1:
                            color[v] = color[u] ^ 1
                            q.append(v)
                        elif color[v] == color[u]:
                            # Conflict found, break and we'll handle later
                            pass
        # Now, for any uncolored (shouldn't happen in connected, but just in case)
        for i in range(n):
            if color[i] == -1:
                color[i] = 0
        # Now fix conflicts by greedy coloring on the conflict graph
        # We'll use the current 2-coloring as a starting point and resolve conflicts
        # by allowing a third color where needed
        # Actually, we'll do: keep the 2-coloring where possible, and for vertices
        # in conflict, try to assign a third color if necessary
        # But simpler: use the 2-coloring as initial assignment and then apply
        # greedy algorithm to fix it by allowing more colors
        # Reset and do greedy with ordering by degree
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        color = [-1] * n
        for u in order:
            used = [False] * (n + 1)  # n+1 is safe upper bound
            for v in graph[u]:
                if color[v] != -1:
                    used[color[v]] = True
            c = 0
            while c < n + 1 and used[c]:
                c += 1
            color[u] = c
        return renumber_colors(color)

    # Strategy 2: DSATUR
    def dsatur():
        if n == 0:
            return []
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbors mask for fast saturation update? we'll compute directly
        # but we can maintain neighbor colors sets
        # Since n <= 100, we can compute saturation on the fly
        # But to be efficient, we'll update as we go
        # We'll maintain for each vertex, a boolean list of which colors are present in neighbors
        # However, we don't know the number of colors in advance, so we use a list of sets
        neighbor_colors = [set() for _ in range(n)]
        # degree for tie-breaking
        degree = [len(graph[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            candidates = []
            max_sat = -1
            for u in range(n):
                if color[u] == -1:
                    sat = len(neighbor_colors[u])
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [u]
                    elif sat == max_sat:
                        candidates.append(u)
            # Tie-break by degree in the subgraph induced by uncolored vertices
            if len(candidates) > 1:
                max_deg = -1
                final_candidates = []
                for u in candidates:
                    # count uncolored neighbors
                    d = sum(1 for v in graph[u] if color[v] == -1)
                    if d > max_deg:
                        max_deg = d
                        final_candidates = [u]
                    elif d == max_deg:
                        final_candidates.append(u)
                candidates = final_candidates
            # Final tie-break randomly
            u = random.choice(candidates)
            # Find smallest color not used by neighbors
            used = [False] * (n + 1)
            for v in graph[u]:
                if color[v] != -1:
                    used[color[v]] = True
            c = 0
            while c < n + 1 and used[c]:
                c += 1
            color[u] = c
            # Update neighbor_colors for neighbors of u
            for v in graph[u]:
                neighbor_colors[v].add(c)
        return renumber_colors(color)

    # Strategy 3: RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        color = [-1] * n
        # We'll maintain a list of uncolored vertices
        # For efficiency, we use a list and mark colored
        uncolored = [True] * n
        current_color = 0

        # Precompute adjacency as sets for fast lookup
        adj_set = [set(neigh) for neigh in graph]

        while any(uncolored):
            # Build maximal independent set for current_color
            # Step 1: choose vertex with max degree in the uncolored subgraph
            # We'll compute degree in the uncolored subgraph on the fly
            max_deg = -1
            v1 = -1
            for u in range(n):
                if uncolored[u]:
                    # count uncolored neighbors
                    deg = 0
                    for v in graph[u]:
                        if uncolored[v]:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        v1 = u
            if v1 == -1:  # should not happen
                break
            # Start independent set with v1
            independent_set = [v1]
            uncolored[v1] = False
            # Partition remaining uncolored into U and W
            # U: not adjacent to any in independent_set
            # W: adjacent to at least one in independent_set
            U = set()
            W = set()
            for u in range(n):
                if uncolored[u]:
                    # check if adjacent to any in independent_set
                    adjacent = False
                    for v in independent_set:
                        if u in adj_set[v]:
                            adjacent = True
                            break
                    if adjacent:
                        W.add(u)
                    else:
                        U.add(u)
            # While U is not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                for u in U:
                    # count neighbors in W
                    w_neighbors = 0
                    for v in graph[u]:
                        if v in W:
                            w_neighbors += 1
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break by min degree in G[U]
                        deg_u = 0
                        for v in graph[u]:
                            if v in U:
                                deg_u += 1
                        if best_u == -1 or deg_u < min_deg_u:
                            min_deg_u = deg_u
                            best_u = u
                # If tie-breaking still needed, we can use random or index
                if best_u == -1:  # should not happen
                    best_u = next(iter(U))
                # Add best_u to independent set
                independent_set.append(best_u)
                uncolored[best_u] = False
                U.remove(best_u)
                # Move neighbors of best_u that are in U to W
                for v in graph[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign current_color to all in independent_set
            for u in independent_set:
                color[u] = current_color
            current_color += 1
        return renumber_colors(color)

    # Strategy 4: Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        # We'll compute the smallest-last ordering
        # Make a copy of degrees
        degree = [len(graph[i]) for i in range(n)]
        # We'll maintain a list of vertices
        remaining = set(range(n))
        order = []  # will be the removal order
        # We need to repeatedly remove the vertex of minimum degree
        # To do efficiently, we can use buckets, but n<=100 so we can scan
        while remaining:
            # Find vertex in remaining with minimum degree
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                if degree[v] < min_deg:
                    min_deg = degree[v]
                    v_min = v
            # Remove v_min
            remaining.remove(v_min)
            order.append(v_min)
            # Decrease degree of neighbors
            for v in graph[v_min]:
                if v in remaining:
                    degree[v] -= 1
        # Now color in reverse order
        color = [-1] * n
        for u in reversed(order):
            used = [False] * (n + 1)
            for v in graph[u]:
                if color[v] != -1:
                    used[color[v]] = True
            c = 0
            while c < n + 1 and used[c]:
                c += 1
            color[u] = c
        return renumber_colors(color)

    # Run all strategies and pick the best (fewest colors)
    strategies = [
        ("bipartite_plus_greedy", bipartite_plus_greedy),
        ("dsatur", dsatur),
        ("rlf", rlf),
        ("smallest_last", smallest_last)
    ]

    best_coloring = None
    best_num_colors = float('inf')

    for name, strategy in strategies:
        try:
            coloring = strategy()
            # Validate
            if is_valid_coloring(coloring):
                num = num_colors(coloring)
                if num < best_num_colors:
                    best_num_colors = num
                    best_coloring = coloring
            else:
                # If invalid, try to fix by greedy? but we assume our strategies are valid
                pass
        except Exception:
            # In case of error, skip
            continue

    # Fallback: if all failed, use greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        color = [-1] * n
        for u in order:
            used = [False] * (n + 1)
            for v in graph[u]:
                if color[v] != -1:
                    used[color[v]] = True
            c = 0
            while c < n + 1 and used[c]:
                c += 1
            color[u] = c
        best_coloring = renumber_colors(color)

    return best_coloring

