def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:  # safety check
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Remove duplicates in adjacency list (if any)
    for i in range(n):
        adj_list[i] = list(set(adj_list[i]))

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map used colors to consecutive integers
        used = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(used)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph (initially full degree)
        degree = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select uncolored vertex with max saturation, then max degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = bit_count(saturation[u])
                deg_u = degree[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
                elif sat_u == max_sat and deg_u == max_deg:
                    # tie-break by vertex index (lower index first for determinism, but we can randomize)
                    if v == -1 or u < v:
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color
            used_by_neighbors = saturation[v]
            c = 0
            while used_by_neighbors & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)

            # Update saturation and degree for neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # Add color c to saturation of u
                    saturation[u] |= (1 << c)
                    # Decrease degree of u (since v is now colored)
                    degree[u] -= 1
        return normalize(colors)

    # RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build maximal independent set for color_idx
            S = set()
            # Step 1: pick vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                # degree in uncolored subgraph
                deg = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
            if v == -1:
                break
            S.add(v)

            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = uncolored - {v}
            W = set()
            for u in list(U):
                # check if u is adjacent to any in S
                adj_to_S = False
                for s in S:
                    if u in adj_list[s]:
                        adj_to_S = True
                        break
                if adj_to_S:
                    U.remove(u)
                    W.add(u)

            # While U not empty, add vertices to S
            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = -1
                max_common = -1
                min_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    common = 0
                    for w in adj_list[u]:
                        if w in W:
                            common += 1
                    # degree in U
                    deg_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_U += 1
                    if common > max_common or (common == max_common and deg_U < min_deg_U):
                        max_common = common
                        min_deg_U = deg_U
                        u_star = u
                if u_star == -1:
                    break
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color_idx to all in S
            for u in S:
                colors[u] = color_idx
            uncolored -= S
            color_idx += 1

        return normalize(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # We'll compute the ordering by repeatedly removing min degree vertex
        # Works on uncolored subgraph
        deg = [len(adj_list[i]) for i in range(n)]
        # We need to update degrees as we remove vertices
        # Use a list of sets for efficient removal? Since n<=100, we can do O(n^2)
        removed = [False] * n
        order = []  # will store removal order (first removed first)

        for _ in range(n):
            # Find vertex with min degree among non-removed
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u]:
                    # current degree: count non-removed neighbors
                    d = 0
                    for w in adj_list[u]:
                        if not removed[w]:
                            d += 1
                    if d < min_deg:
                        min_deg = d
                        v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return normalize(colors)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Try to eliminate the highest color class
            k = num_colors(col)
            if k <= 1:
                break
            target_color = k - 1
            # Get vertices with target_color
            targets = [i for i in range(n) if col[i] == target_color]
            if not targets:
                # Already normalized, should not happen
                break

            # Try to recolor each target vertex
            for v in targets:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if col[u] != -1:
                        used_by_neighbors |= (1 << col[u])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Can recolor v to c
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart while loop after change

                # Try Kempe chain swaps for each lower color
                for c in range(target_color):
                    # Check if v can be recolored to c via Kempe chain (target_color, c)
                    # We'll do BFS/DFS for the Kempe chain starting from v
                    # Only consider vertices colored target_color or c
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    # We'll also check if we can swap: after swap, v would be c, and we need to ensure
                    # that no neighbor of v becomes c (which would cause conflict)
                    # Actually, in Kempe swap, we swap colors in the component: target_color <-> c
                    # After swap, v becomes c. We need to check that no neighbor of v is c after swap.
                    # But note: neighbors of v that are in the component and colored c will become target_color.
                    # So we need to check: for any neighbor u of v, if u is in the component and colored c, 
                    # after swap it becomes target_color -> safe because v becomes c (different).
                    # If u is in the component and colored target_color, after swap becomes c -> conflict if v becomes c? 
                    # Actually, if u is neighbor of v and in component and colored target_color, after swap u becomes c and v becomes c -> conflict.
                    # Therefore, we can only perform the swap if there is no neighbor of v in the component that is colored target_color.
                    # But wait: v is in the component and colored target_color. Its neighbors in the component that are colored target_color would become c -> conflict with v becoming c.
                    # So we must avoid having any neighbor of v in the component that is colored target_color (except v itself? but v is not neighbor of itself).
                    # Actually, we can rephrase: after swap, the color of v becomes c. We need that for every neighbor u of v, col[u] != c after swap.
                    # After swap:
                    #   if u in component: 
                    #       if original col[u] == target_color -> becomes c
                    #       if original col[u] == c -> becomes target_color
                    #   else: remains col[u]
                    # So we require: for every neighbor u of v:
                    #   if u in component: then original col[u] != target_color (because if it were, it becomes c and conflicts with v's new color c)
                    #   if u not in component: then original col[u] != c
                    #
                    # Alternatively, we can simulate: 
                    #   Let's collect the component and then check the condition.
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (col[y] == target_color or col[y] == c):
                                visited[y] = True
                                queue.append(y)

                    # Now check if we can swap: 
                    # Condition: for every neighbor u of v, 
                    #   if u in component: then col[u] must not be target_color (because after swap it becomes c, and v becomes c -> conflict)
                    #   if u not in component: then col[u] must not be c
                    valid_swap = True
                    for u in adj_list[v]:
                        if u in component:
                            if col[u] == target_color:
                                valid_swap = False
                                break
                        else:
                            if col[u] == c:
                                valid_swap = False
                                break
                    if valid_swap:
                        # Perform swap: in the component, swap target_color and c
                        for x in component:
                            if col[x] == target_color:
                                col[x] = c
                            elif col[x] == c:
                                col[x] = target_color
                        changed = True
                        break  # break from c loop
                if changed:
                    break  # break from targets loop
            # If we changed, we break and restart the while loop to possibly reduce further
            if changed:
                # Normalize after change? We'll do at the end of while loop
                pass
        return normalize(col)

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), use greedy
    if not candidates:
        # Simple greedy: order by index
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        candidates.append(normalize(colors))

    # Select candidate with fewest colors
    best = min(candidates, key=lambda x: num_colors(x))

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best)
        if is_valid(improved) and num_colors(improved) <= num_colors(best):
            best = improved
    except:
        pass

    # Final normalization and validation
    best = normalize(best)
    # Double-check validity (should be, but ensure)
    if not is_valid(best):
        # Fallback to greedy
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best = normalize(colors)

    return best

