def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True
    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = [list(lst) for lst in adj]  # copy to avoid mutation

    # Convert to bit masks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with bitmask
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree as bitmask of used neighbor colors
        uncolored = set(range(n))
        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << 0)
        while uncolored:
            # Select vertex with max saturation degree (number of colors in sat[v])
            v = max(uncolored, key=lambda x: (sat[x].bit_count(), len(neighbors[x]), -x))
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent = [v]
            uncolored.remove(v)
            # Partition: U = not adjacent to any in independent, W = adjacent to at least one
            U = {u for u in uncolored if all((bit_adj[u] & (1 << w)) == 0 for w in independent)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W
                u = max(U, key=lambda x: sum(1 for y in neighbors[x] if y in W), default=None)
                if u is None:
                    break
                # Tie-break: min degree in U subgraph
                candidates = [x for x in U if sum(1 for y in neighbors[x] if y in W) == sum(1 for y in neighbors[u] if y in W)]
                u = min(candidates, key=lambda x: sum(1 for y in neighbors[x] if y in U))
                independent.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to independent set
            for v in independent:
                color[v] = c
            c += 1
            uncolored = W  # next round
        return color

    # Helper: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering via peeling min degree
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[v]) for v in range(n)]
        # Current degree in remaining subgraph
        curr_deg = degrees[:]
        while remaining:
            # Find vertex of minimum current degree
            v = min(remaining, key=lambda x: curr_deg[x])
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    curr_deg[u] -= 1
        # Color in reverse order
        return greedy_color(reversed(order))

    # Helper: Kempe chain swap for (a,b)
    def kempe_swap(color, a, b, v):
        # Returns new color array after swapping a and b in the component of v, or None if invalid
        stack = [v]
        visited = set()
        comp_color_a = []
        comp_color_b = []
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if color[u] == a:
                comp_color_a.append(u)
            elif color[u] == b:
                comp_color_b.append(u)
            else:
                continue  # should not happen if called correctly
            for w in neighbors[u]:
                if w not in visited and (color[w] == a or color[w] == b):
                    stack.append(w)
        # Perform swap
        new_color = color[:]
        for u in comp_color_a:
            new_color[u] = b
        for u in comp_color_b:
            new_color[u] = a
        return new_color

    # Helper: validate coloring
    def is_valid(color):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and color[u] == color[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact(color):
        # Map colors to consecutive integers
        unique = {}
        next_color = 0
        for i in range(n):
            c = color[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            color[i] = unique[c]
        return color

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(compact(c1[:]))
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(compact(c2[:]))
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(compact(c3[:]))
    except:
        pass
    # Fallback: simple greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(compact(c4[:]))
    except:
        pass

    if not candidates:
        # Ultimate fallback: assign each vertex a unique color
        return list(range(n))

    # Select candidate with fewest colors
    best = min(candidates, key=lambda x: max(x) + 1 if x else 0)
    k = max(best) + 1 if best else 0

    # Iterative Kempe chain reduction
    improved = True
    while improved and k > 1:
        improved = False
        # Find smallest color class (by index, but we target highest color for removal)
        # We try to eliminate color k-1
        target_color = k - 1
        vertices = [v for v in range(n) if best[v] == target_color]
        if not vertices:
            # Already compacted?
            best = compact(best)
            k = max(best) + 1 if best else 0
            continue
        # Try to recolor each vertex in target color
        for v in vertices:
            # Try direct reassignment to a lower color
            used = 0
            for u in neighbors[v]:
                c = best[u]
                if c != -1:
                    used |= (1 << c)
            for c in range(target_color):  # only try colors < target_color
                if not (used & (1 << c)):
                    # Can recolor v to c
                    best[v] = c
                    improved = True
                    break
            if improved:
                break
            # Try Kempe chains with each lower color
            for c in range(target_color):
                # Check if v is in a Kempe chain of (target_color, c) that does not include any other vertex of target_color?
                # Actually, we can try to swap and see if it frees the target color for v
                # We simulate: swap colors target_color and c in the component of v
                new_color = kempe_swap(best, target_color, c, v)
                if new_color is None:
                    continue
                # After swap, check if v is no longer target_color (should be c now)
                if new_color[v] != target_color:
                    # Also, we need to ensure we didn't create conflict? Kempe swap preserves validity
                    if is_valid(new_color):
                        best = new_color
                        improved = True
                        break
            if improved:
                break
        if improved:
            best = compact(best)
            k = max(best) + 1 if best else 0
        else:
            # Cannot reduce further
            break

    return best

