        curr_deg = deg[:]
        # For each vertex to remove
        for _ in range(n):
            # Find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if curr_deg[u] > min_deg:  # u not yet removed
                    # Remove u from its current bucket
                    d = curr_deg[u]
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    curr_deg[u] -= 1
                    buckets[curr_deg[u]].append(u)
                    if curr_deg[u] < min_deg:
                        min_deg = curr_deg[u]
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
