        return color

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to greedy
    if not candidates:
        color = [-1] * n
        for v in range(n):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        candidates.append(color)

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for color in candidates:
        # Validate coloring
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if u < v and color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = len(set(color))
        if k < best_k:
            best_k = k
            best_color = color

    if best_color is None:
        # Fallback: should not happen
        best_color = candidates[0] if candidates else [0] * n

    # Apply Kempe chain reduction iteratively
    reduced = reduce_colors(best_color)
    # Validate reduced
    valid = True
    for u in range(n):
        for v in adj_list[u]:
            if u < v and reduced[u] == reduced[v]:
                valid = False
                break
        if not valid:
            break
    if valid:
        return reduced
    else:
        return best_color

