    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

