    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize colors to 0..k-1 consecutive
    def normalize_colors(coloring):
        if not coloring:
            return coloring
        # Map used colors to consecutive integers
        used = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(used)}
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # colored_neighbors[v] = bitmask of colored neighbors
        colored_neighbors = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree (uncolored neighbors)
            max_sat = -1
            candidates = []
            for v in range(n):
                if coloring[v] == -1:
                    sat_v = saturation[v]
                    if sat_v > max_sat:
                        max_sat = sat_v
                        candidates = [v]
                    elif sat_v == max_sat:
                        candidates.append(v)

            if not candidates:
                break  # should not happen

