            # Find smallest color not used by neighbors
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            coloring[v] = color

            # Update saturation and colored_neighbors for neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:  # only update uncolored neighbors
                    colored_neighbors[u] |= (1 << color)
                    # saturation[u] = number of distinct colors in colored_neighbors[u]
                    saturation[u] = colored_neighbors[u].bit_count()

