    # RLF algorithm (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for this color
            independent_set = set()
            # Step 1: pick vertex with max degree in G[uncolored]
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for u in adj_list[x] if u in uncolored))
                independent_set.add(v)
                uncolored.remove(v)
                # Partition: U = vertices not adjacent to any in independent_set, W = adjacent
                W = set()
                for u in uncolored:
                    if any(w in adj_list[u] for w in independent_set):
                        W.add(u)
                U = uncolored - W

                # Step 2: while U not empty
                while U:
                    # Select u in U with max |N(u) ∩ W|
                    best_u = None
                    max_w_neighbors = -1
                    for u in U:
