                neighbor_colors = 0
                for u in adj_list[v]:
                    if colored[u]:
                        neighbor_colors |= (1 << coloring[u])
                sat = bit_count(neighbor_colors)
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_v = candidates[0]
                for v in candidates:
