                # To signal that we made no progress for this target_color, we do nothing and the for loop continues.
                pass
            # end for target_color
            # if we made progress in any target_color, we continue the while loop to try again from highest color
            # if we made no progress in any target_color, we break
            # We already have 'changed' set to True if we made progress.
        return color
    # Apply Kempe reduction
    try:
        best_color = kempe_reduction(best_color)
    except Exception:
        pass
    # Final validation and compacting
    # Ensure valid
    def validate_and_compact(col):
        # make copy
        col = col[:]
        # validate
        for u in range(n):
            for v in neighbors[u]:
                if col[u] == col[v]:
                    # try to fix by reassigning? but should not happen
                    # fallback: greedy
                    return greedy_color(list(range(n)))
        # compact
        used = set(col)
        if used:
            mapping = {old: new for new, old in enumerate(sorted(used))]
            col = [mapping[c] for c in col]
        return col
    best_color = validate_and_compact(best_color)
    return best_color

