def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if it's a binary matrix
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Convert to adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for neighbor in adj_list[i]:
                bit_adj[i] |= (1 << neighbor)

    # Helper: count bits in integer (Python 3.8+ has bit_count, but use bin for compatibility if needed)
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bit masks for efficiency
        neighbor_colors = [0] * n

        # order by degree descending for tie-breaking in saturation
        degrees = [len(adj_list[i]) for i in range(n)]
        # vertices sorted by degree descending
        vertices_by_degree = sorted(range(n), key=lambda x: (-degrees[x], x))

        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree then index
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if colors[i] == -1:
                    if saturation[i] > max_sat or (saturation[i] == max_sat and (degrees[i] > max_deg or (degrees[i] == max_deg and i < v))):
                        max_sat = saturation[i]
                        max_deg = degrees[i]
                        v = i
            if v == -1:  # should not happen
                break

            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

            # update saturation and neighbor_colors for uncolored neighbors
            for u in adj_list[v]:
                if colors[u] == -1:
                    # if this color is new in u's neighborhood
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1

        return compact_colors(colors)

    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # build maximal independent set for this color
            independent_set = []
            # candidates: vertices not adjacent to any in independent_set
            # ineligible: vertices adjacent to at least one in independent_set
            # We'll maintain eligible and ineligible sets
            eligible = set(uncolored)  # initially all uncolored are eligible
            ineligible = set()

            # choose first vertex: max degree in uncolored subgraph
            if eligible:
                # compute degree in the subgraph induced by uncolored
                max_deg = -1
                v = -1
                for u in eligible:
                    # count neighbors that are also in uncolored
                    deg = 0
                    for w in adj_list[u]:
                        if w in uncolored:
                            deg += 1
                    if deg > max_deg or (deg == max_deg and u < v):
                        max_deg = deg
                        v = u
                independent_set.append(v)
                eligible.remove(v)
                # move neighbors of v from eligible to ineligible
                for w in adj_list[v]:
                    if w in eligible:
                        eligible.remove(w)
                        ineligible.add(w)

            # while there are eligible vertices
            while eligible:
                # select u in eligible with max neighbors in ineligible
                best_u = -1
                max_w = -1
                min_deg_eligible = float('inf')
                for u in eligible:
                    # count neighbors in ineligible
                    w_count = 0
                    for neighbor in adj_list[u]:
                        if neighbor in ineligible:
                            w_count += 1
                    # tie-break: min degree in the eligible subgraph
                    deg_eligible = 0
                    for neighbor in adj_list[u]:
                        if neighbor in eligible:
                            deg_eligible += 1
                    if w_count > max_w or (w_count == max_w and (deg_eligible < min_deg_eligible or (deg_eligible == min_deg_eligible and u < best_u))):
                        max_w = w_count
                        min_deg_eligible = deg_eligible
                        best_u = u
                u = best_u
                independent_set.append(u)
                eligible.remove(u)
                # move neighbors of u from eligible to ineligible
                for w in adj_list[u]:
                    if w in eligible:
                        eligible.remove(w)
                        ineligible.add(w)

            # assign color to all in independent_set
            for v in independent_set:
                colors[v] = color
                uncolored.remove(v)
            color += 1

        return compact_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # copy of degrees
        degrees = [len(adj_list[i]) for i in range(n)]
        # set of remaining vertices
        remaining = set(range(n))
        order = []  # will store removal order

        while remaining:
            # find vertex with minimum degree in remaining subgraph
            min_deg = float('inf')
            v = -1
            for u in remaining:
                # compute degree in the subgraph induced by remaining
                deg = 0
                for w in adj_list[u]:
                    if w in remaining:
                        deg += 1
                if deg < min_deg or (deg == min_deg and u < v):
                    min_deg = deg
                    v = u
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors (only for those still remaining)
            for w in adj_list[v]:
                if w in remaining:
                    degrees[w] -= 1

        # color in reverse order using first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        if n <= 1:
            return colors
        # make a copy to work on
        current = colors[:]
        k = num_colors(current)
        # try to reduce colors as much as possible
        improved = True
        while improved and k > 1:
            improved = False
            # target the smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # should not happen if k is correct
                k -= 1
                continue

            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if current[u] != -1:
                        used_by_neighbors |= (1 << current[u])
                # find smallest color < target_color not used by neighbors
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # can move v to color c
                        current[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart the while loop after any change

                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c from direct reassignment above, skip
                    if current[v] == c:
                        continue
                    # find the Kempe chain component of v in colors {target_color, c}
                    # We'll do BFS to find the component containing v
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for neighbor in adj_list[node]:
                            if neighbor not in visited and (current[neighbor] == target_color or current[neighbor] == c):
                                visited.add(neighbor)
                                queue.append(neighbor)
                    # Check if any neighbor of v with color c is NOT in this component
                    # If so, we can swap the component and free color c for v
                    has_external = False
                    for u in adj_list[v]:
                        if current[u] == c and u not in component:
                            has_external = True
                            break
                    if has_external:
                        # swap colors in the component: target_color <-> c
                        for node in component:
                            if current[node] == target_color:
                                current[node] = c
                            else:  # must be c
                                current[node] = target_color
                        improved = True
                        break  # break from color loop
                if improved:
                    break  # break from vertex loop
            if improved:
                # compact colors and update k
                current = compact_colors(current)
                k = num_colors(current)

        return current

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            k1 = num_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_colors = c1
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            k2 = num_colors(c2)
            if k2 < best_k:
                best_k = k2
                best_colors = c2
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            k3 = num_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_colors = c3
    except:
        pass

    # If none worked (shouldn't happen), fallback to greedy
    if best_colors is None:
        # simple greedy in order 0..n-1
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best_colors = compact_colors(colors)

    # Apply Kempe chain reduction to improve
    try:
        improved = kempe_reduce(best_colors)
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_colors = improved
    except:
        pass

    # Final validation and compacting
    if not is_valid_coloring(best_colors):
        # last resort: greedy
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best_colors = compact_colors(colors)

    return best_colors

