                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
                    neigh[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue  # skip invalid indices
                bit_adj[i] |= (1 << j)
                neigh[i].append(j)

    # Helper: count bits in integer
    def bit_count(x: int) -> int:
        return x.bit_count()

