    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neigh[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = bit_count(sat[u])
                d = uncolored_deg[u]
                if s > max_sat or (s == max_sat and d > max_deg) or (s == max_sat and d == max_deg and random.random() < 0.5):
                    max_sat = s
                    max_deg = d
                    v = u
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neigh[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # RLF (Recursive Largest First)
    def rlf() -> list[int]:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neigh[x] if y in uncolored))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # grow independent set
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_u_degree = float('inf')
                for u in U:
                    w_neighbors = sum(1 for y in neigh[u] if y in W)
                    u_degree = sum(1 for y in neigh[u] if y in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and u_degree < min_u_degree) or (w_neighbors == max_w_neighbors and u_degree == min_u_degree and random.random() < 0.5):
                        max_w_neighbors = w_neighbors
                        min_u_degree = u_degree
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for y in neigh[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Smallest-Last (Matula & Beck) greedy
    def smallest_last() -> list[int]:
        # degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(neigh[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # we need to update degrees as we remove vertices
        # use bucket sort for efficiency (n <= 100)
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].append(i)
        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in neigh[v]:
                if not removed[u]:
                    old_deg = deg[u]
                    deg[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].remove(u)  # O(n) but n small
                    if deg[u] >= 0:
                        buckets[deg[u]].append(u)
                    if deg[u] < min_deg:
                        min_deg = deg[u]
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neigh[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring: list[int]) -> list[int]:
        if not coloring:
            return coloring
        # make a copy to work on
        color = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (largest color index that is used)
            max_color = max(color) if color else -1
            if max_color < 0:
                break
            # try to eliminate color classes from highest down
            for target_color in range(max_color, -1, -1):
                # collect vertices with target_color
                targets = [i for i in range(n) if color[i] == target_color]
                if not targets:
                    continue
                # try to recolor each target vertex
                eliminated = True
                for v in targets:
                    # check if v can take any color < target_color
                    used_by_neighbors = 0
                    for u in neigh[v]:
                        c_u = color[u]
                        if c_u < target_color:
                            used_by_neighbors |= (1 << c_u)
                    # find smallest available color < target_color
                    free_color = -1
                    for c in range(target_color):
                        if not (used_by_neighbors & (1 << c)):
                            free_color = c
                            break
                    if free_color != -1:
                        color[v] = free_color
                        changed = True
                        continue  # v recolored, move to next target
                    # try Kempe chain swap with each color c < target_color
                    swapped = False
                    for c in range(target_color):
                        # if v has a neighbor of color c, then swapping might pull v back
                        has_c_neighbor = any(color[u] == c for u in neigh[v])
                        if has_c_neighbor:
                            continue
                        # build Kempe chain for colors (c, target_color) starting from v
                        # we want to swap in the component of v if it does NOT contain any vertex of color c
                        # Actually, we can swap any component; after swap, v will become color c if it was in the component
                        # So we need the component of v in the subgraph induced by colors c and target_color
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            x = queue.popleft()
                            component.append(x)
                            for y in neigh[x]:
                                if not visited[y] and (color[y] == c or color[y] == target_color):
                                    visited[y] = True
                                    queue.append(y)
                        # check if component contains any vertex of color c
                        has_c_in_component = any(color[x] == c for x in component)
                        if not has_c_in_component:
                            # safe to swap: no vertex of color c in component, so after swap, no vertex becomes target_color
                            for x in component:
                                if color[x] == c:
                                    color[x] = target_color
                                else:  # must be target_color
                                    color[x] = c
                            color[v] = c  # v was target_color, now becomes c
                            changed = True
                            swapped = True
                            break
                    if swapped:
                        break
                    # if we couldn't recolor v, then we cannot eliminate this color class yet
                    eliminated = False
                    break
                if eliminated and changed:
                    # we managed to recolor all vertices of target_color, so eliminate the color
                    # compact colors will be done later
                    break
                elif not eliminated:
                    # couldn't eliminate this color, try next lower
                    continue
        # compact colors to 0..k-1
        return compact_colors(color)

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if not is_valid_coloring(col):
                continue
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col
        except Exception:
            continue

    # Fallback: if no heuristic produced valid coloring, use greedy random order
    if best_coloring is None:
        order = list(range(n))
        random.shuffle(order)
        color = [-1] * n
        for v in order:
            used = 0
            for u in neigh[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = color

    # Apply Kempe reduction to improve
    try:
        improved = kempe_reduce(best_coloring)
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_coloring = improved
    except Exception:
        pass

    # Final validation and compaction
    if not is_valid_coloring(best_coloring):
        # last resort: greedy by degree order
        order = sorted(range(n), key=lambda x: len(neigh[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for u in neigh[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = color

    return compact_colors(best_coloring)

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix or list
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                v = max(uncolored, key=lambda x: bin(bit_adj[x]).count('1'))
            else:
                v = max(candidates, key=lambda x: bin(bit_adj[x] & sum((1 << u) for u in uncolored)).count('1'))
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] == -1:
                    sat[u] |= (1 << c)
        return color

    # Helper: RLF independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: bin(bit_adj[x] & sum((1 << u) for u in uncolored)).count('1'))
            S = {v}
            U = uncolored - {v}
            W = set()
            # Initial W: neighbors of v in U
            for u in U:
                if (bit_adj[v] >> u) & 1:
                    W.add(u)
            U -= W
            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = bin(bit_adj[u] & sum((1 << w) for w in W)).count('1')
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_u = bin(bit_adj[u] & sum((1 << uu) for uu in U)).count('1')
                        deg_best = bin(bit_adj[best_u] & sum((1 << uu) for uu in U)).count('1')
                        if deg_u < deg_best:
                            best_u = u
                if best_u == -1:
                    break
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u in U to W
                for uu in U:
                    if (bit_adj[best_u] >> uu) & 1:
                        W.add(uu)
                U -= {uu for uu in U if (bit_adj[best_u] >> uu) & 1}
            for vertex in S:
                color[vertex] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        order = []
        remaining = set(range(n))
        # We'll simulate removal by updating degrees
        curr_deg = degrees[:]
        for _ in range(n):
            v = min(remaining, key=lambda x: curr_deg[x])
            order.append(v)
            remaining.remove(v)
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    curr_deg[u] -= 1
        order.reverse()
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    try:
        candidates.append(dsatur())
    except:
        pass
    try:
        candidates.append(rlf())
    except:
        pass
    try:
        candidates.append(smallest_last())
    except:
        pass

    # Fallback: Welsh-Powell
    try:
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        candidates.append(greedy_color(order))
    except:
        pass

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        if all(0 <= c < n for c in col):
            k = max(col) + 1 if col else 0
            if k < best_k:
                best_k = k
                best_color = col[:]

    if best_color is None:
        best_color = [0] * n

    # Kempe chain color reduction
    def is_valid(col):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1 and col[u] == col[v]:
                    return False
        return True

    def kempe_reduce(col):
        if not is_valid(col):
            return col
        while True:
            color_classes = {}
            for v in range(n):
                c = col[v]
                if c not in color_classes:
                    color_classes[c] = []
                color_classes[c].append(v)
            if not color_classes:
                break
            max_color = max(color_classes.keys())
            if max_color == 0:
                break
            smallest_class = color_classes[max_color]
            # Try to eliminate color max_color
            eliminated = False
            for v in smallest_class:
                neighbor_colors = set()
                for u in range(n):
                    if (bit_adj[v] >> u) & 1:
                        neighbor_colors.add(col[u])
                for c in range(max_color):
                    if c not in neighbor_colors:
                        col[v] = c
                        eliminated = True
                        break
                if eliminated:
                    break
                # Try Kempe chains
                for c in range(max_color):
                    if c in neighbor_colors:
                        continue
                    # Check if v can be recolored to c via Kempe chain (v, max_color) <-> (c)
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    component = set()
                    while stack:
                        node = stack.pop()
                        component.add(node)
                        for u in range(n):
                            if (bit_adj[node] >> u) & 1:
                                if col[u] == max_color or col[u] == c:
                                    if u not in visited:
                                        visited.add(u)
                                        stack.append(u)
                    # Check if any neighbor of v in component has color c -> swapping would cause conflict
                    conflict = False
                    for node in component:
                        for u in range(n):
                            if (bit_adj[node] >> u) & 1 and col[u] == c and u not in component:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Swap colors in component
                        for node in component:
                            if col[node] == max_color:
                                col[node] = c
                            elif col[node] == c:
                                col[node] = max_color
                        eliminated = True
                        break
            if not eliminated:
                break
            # Compact colors: remap to 0..k-1
            unique_colors = sorted(set(col))
            mapping = {old: new for new, old in enumerate(unique_colors)}
            col = [mapping[c] for c in col]
        return col

    best_color = kempe_reduce(best_color[:])
    # Final validation and compacting
    if not is_valid(best_color):
        # Last resort: greedy
        order = list(range(n))
        best_color = greedy_color(order)
    unique_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best_color = [mapping[c] for c in best_color]
    return best_color

import math
