def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for i in range(n):
            if len(adj[i]) != n:
                all_binary = False
                break
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    if is_matrix:
        neighbors = []
        for i in range(n):
            nbrs = []
            row = adj[i]
            for j in range(n):
                if row[j] == 1:
                    nbrs.append(j)
            neighbors.append(nbrs)
    else:
        neighbors = adj

    # Convert to bitmask representation for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        # degree in the uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u].bit_count()
                deg_u = uncolored_deg[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or (sat_u == max_sat and deg_u == max_deg and (v == -1 or u < v)):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            # assign smallest available color
            used = 0
            for w in neighbors[v]:
                cw = color[w]
                if cw != -1:
                    used |= (1 << cw)
            cv = 0
            while used & (1 << cv):
                cv += 1
            color[v] = cv
            uncolored.remove(v)
            # update saturation and uncolored degree of neighbors
            for w in neighbors[v]:
                if w in uncolored:
                    saturation[w] |= (1 << cv)
                    uncolored_deg[w] -= 1
        return color

    # 2. RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # degree in induced subgraph of uncolored
            deg_uncolored = [0] * n
            for u in uncolored:
                cnt = 0
                for w in neighbors[u]:
                    if w in uncolored:
                        cnt += 1
                deg_uncolored[u] = cnt
            # choose vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                adjacent = False
                for w in S:
                    if u in neighbors[w]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # tie-break by min degree in G[U]
                    deg_in_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_in_U += 1
                    if score > best_score or (score == best_score and deg_in_U < best_deg_U) or (score == best_score and deg_in_U == best_deg_U and (best_u == -1 or u < best_u)):
                        best_score = score
                        best_deg_U = deg_in_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u that are in U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
            c += 1
        return color

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        degree = [len(neighbors[i]) for i in range(n)]
        # bin vertices by degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            bins[d].append(v)
        # pointer to current non-empty bin
        ptr = 0
        order = []
        # current degree array (will be updated)
        curr_deg = degree[:]
        removed = [False] * n
        for _ in range(n):
            # find non-empty bin
            while ptr <= max_deg and not bins[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = bins[ptr].pop()
            while removed[v]:
                if not bins[ptr]:
                    while ptr <= max_deg and not bins[ptr]:
                        ptr += 1
                    if ptr > max_deg:
                        break
                    v = bins[ptr].pop()
                else:
                    break
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # update neighbors
            for w in neighbors[v]:
                if not removed[w]:
                    d = curr_deg[w]
                    if d > 0:
                        curr_deg[w] -= 1
                        bins[d].append(w)
                        if d - 1 < len(bins):
                            bins[d - 1].append(w)
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except Exception:
        pass

    # Also try greedy by degree descending
    order_deg = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    candidates.append(greedy_color(order_deg))
    # greedy by degree ascending
