    if is_matrix:
        neighbors = []
        for i in range(n):
            row = adj[i]
            nbrs = [j for j in range(n) if row[j] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = adj

    # Compute degree for each vertex
    degree = [len(neighbors[i]) for i in range(n)]

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: convert coloring to use consecutive colors starting from 0
    def compact_colors(coloring):
        if not coloring:
            return coloring
