    bit_adj = [0] * n
    for i in range(n):
        for j in neighbors[i]:
            bit_adj[i] |= (1 << j)

    # Helper: count bits
    def bit_count(x):
        return x.bit_count()

    # Helper: get uncolored neighbor count
    def uncolored_degree(v, colored_mask):
        return bit_count(bit_adj[v] & ~colored_mask)

    # Helper: get saturation (distinct colors in neighbors)
    def saturation(v, color_of):
        mask = 0
        for u in neighbors[v]:
            c = color_of[u]
            if c != -1:
                mask |= (1 << c)
        return bit_count(mask)

    # DSATUR
    def dsatur():
        color_of = [-1] * n
        # Order by degree descending for initial tie-breaking
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        for v in order:
            if color_of[v] != -1:
                continue
            # Find saturation
            sat = saturation(v, color_of)
            # Try to assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = color_of[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color_of[v] = c
        return color_of

    # RLF (Recursive Largest First)
    def rlf():
        color_of = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: uncolored_degree(x, 0))  # 0 mask means all uncolored
            # Build independent set for this color
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            U = {u for u in uncolored if u != v and not (bit_adj[v] & (1 << u))}
            # W: vertices adjacent to S (ineligible)
            W = uncolored - S - U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = bit_count(bit_adj[u] & sum((1 << w) for w in W))
                    if score > best_score or (score == best_score and len(neighbors[u]) < len(neighbors[best_u]) if best_u is not None else False):
                        best_score = score
                        best_u = u
                if best_u is None:
                    break  # Should not happen
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                nbrs_in_U = bit_adj[u] & sum((1 << w) for w in U)
                # Convert bits to set for removal
                to_remove = set()
                temp = nbrs_in_U
                while temp:
                    lsb = temp & -temp
                    idx = (lsb.bit_length() - 1)
                    to_remove.add(idx)
                    temp -= lsb
                U -= to_remove
                W |= to_remove
            # Assign color to S
            for u in S:
                color_of[u] = color
