    if time.time() - start_time < 0.05:
        candidates.append(col_sl)

    # Select best candidate (fewest colors)
    best_coloring = None
    min_colors = float('inf')
    for col in candidates:
        if col is None:
            continue
        unique_colors = len(set(col))
        if unique_colors < min_colors:
            min_colors = unique_colors
            best_coloring = col

    # If no candidate (should not happen), fallback to greedy
    if best_coloring is None:
        best_coloring = [0] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                c = best_coloring[j]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            best_coloring[i] = c

    # Apply Kempe chain reduction iteratively (within time)
    improved = best_coloring[:]
    for _ in range(10):  # Limit iterations
        if time.time() - start_time > 0.045:  # Leave margin
            break
        new_improved = reduce_colors(improved)
        if new_improved == improved:
            break
        improved = new_improved

    # Final validation and consecution
    # Ensure valid coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and improved[u] == improved[v]:
                # Conflict fix: greedy recolor
                used = 0
                for w in neighbors[u]:
                    c = improved[w]
                    if c != -1:
                        used |= (1 << c)
                c = 0
                while used & (1 << c):
                    c += 1
                improved[u] = c

    # Compact colors
    unique_colors = sorted(set(improved))
    if unique_colors != list(range(len(unique_colors))):
        mapping = {old: new for new, old in enumerate(unique_colors)}
        improved = [mapping[c] for c in improved]

    return improved

