def color_graph(adj: list[list[int]]) -> list[int]:
    # Convert adjacency to bitmask and adjacency list
    n = len(adj)
    if n == 0:
        return []
    bit_adj = [0] * n
    adj_list = [[] for _ in range(n)]
    if n > 0 and len(adj[0]) == n and all(all(x in (0, 1) for x in row) for row in adj):
        # Adjacency matrix
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    bit_adj[u] |= 1 << v
                    adj_list[u].append(v)
    else:
        # Adjacency list
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    bit_adj[u] |= 1 << v
                    adj_list[u].append(v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = colors[v]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # Helper: DSATUR with bitmask
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph, then index
            best = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                deg = 0
                for w in adj_list[v]:
                    if w in uncolored:
                        deg += 1
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best):
                    best_sat = sat
                    best_deg = deg
                    best = v
            v = best
            # assign smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update saturation of neighbors
            for w in adj_list[v]:
                if w in uncolored:
                    saturated[w] |= 1 << c
        return colors

    # Helper: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # build independent set for this color
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for w in adj_list[x] if w in uncolored))
            independent = {v}
            # U: vertices not adjacent to any in independent set
            # W: vertices adjacent to at least one in independent set
            U = {w for w in uncolored if w != v and all(w not in adj_list[u] for u in independent)}
            W = {w for w in uncolored if w != v and any(w in adj_list[u] for u in independent)}
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg = float('inf')
                for u in U:
                    score = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if score > best_score or (score == best_score and deg_u < best_deg) or (score == best_score and deg_u == best_deg and u < best_u):
                        best_score = score
                        best_deg = deg_u
                        best_u = u
                u = best_u
                independent.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to independent set
            for v in independent:
                colors[v] = color
                uncolored.remove(v)
            color += 1
        return colors

    # Helper: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # compute degeneracy ordering by repeatedly removing min degree vertex
        degrees = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # pointer to current min degree
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for w in adj_list[v]:
                if w in remaining:
                    d = degrees[w]
                    buckets[d].remove(w)
                    degrees[w] -= 1
                    if degrees[w] < len(buckets):
                        buckets[degrees[w]].append(w)
                    else:
                        # should not happen as degree decreases
                        pass
            # update ptr if needed
            if ptr > degrees[v]:
                ptr = degrees[v]
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # DSATUR
    candidates.append(dsatur())
    # RLF
    candidates.append(rlf())
    # Smallest-Last
    candidates.append(smallest_last())
    # Welsh-Powell (degree descending)
    candidates.append(greedy_color(sorted(range(n), key=lambda x: (-len(adj_list[x]), x))))
    # Randomized greedy (a few trials)
    for _ in range(2):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    # Select best candidate (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        # validate and compact colors
        if any(c == -1 for c in col):
            continue
        # check validity
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        # compact colors to 0..k-1
        unique = {}
        next_color = 0
        compacted = [0] * n
        for i in range(n):
            c = col[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            compacted[i] = unique[c]
        k = next_color
        if k < best_k:
            best_k = k
            best_coloring = compacted

    # Fallback: if no valid candidate (should not happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        # compact
        unique = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            best_coloring[i] = unique[c]

    # Iterative Kempe chain color reduction
    def kempe_reduction(colors):
        # make a copy
        col = colors[:]
        changed = True
        while changed:
            changed = False
            # find color classes
            classes = {}
            for v in range(n):
                c = col[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            if not classes:
                break
            max_color = max(classes.keys())
            # try to eliminate color classes from highest down
            for target_color in range(max_color, 0, -1):
                if target_color not in classes or not classes[target_color]:
                    continue
                # try to recolor each vertex in this class
                eliminated = True
                for v in classes[target_color][:]:  # copy list as we may modify
                    # try direct reassignment to a lower color
                    neighbor_colors = set()
                    for w in adj_list[v]:
                        neighbor_colors.add(col[w])
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            col[v] = c
                            changed = True
                            # move v to class c
                            classes[target_color].remove(v)
                            if c not in classes:
                                classes[c] = []
                            classes[c].append(v)
                            break
                    else:
                        # direct reassignment failed, try Kempe chains
                        freed = False
                        for c in range(target_color):
                            # if v already has color c after possible direct reassignment above, skip
                            if col[v] == c:
                                freed = True
                                break
                            # check if v and any vertex of color c are in different Kempe chains
                            # we only need to check if there is no path between v and any vertex of color c
                            # using only colors c and target_color
                            # BFS from v in the subgraph of colors {c, target_color}
                            from collections import deque
                            visited = set()
                            queue = deque([v])
                            visited.add(v)
                            found = False
                            while queue:
                                x = queue.popleft()
                                if col[x] == c:
                                    found = True
                                    break
                                for y in adj_list[x]:
                                    if col[y] == c or col[y] == target_color:
                                        if y not in visited:
                                            visited.add(y)
                                            queue.append(y)
                            if not found:
                                # we can swap colors c and target_color in the component of v
                                # swap in the visited set
                                for x in visited:
                                    if col[x] == c:
                                        col[x] = target_color
                                    elif col[x] == target_color:
                                        col[x] = c
                                changed = True
                                freed = True
                                # update classes: swap colors c and target_color in visited
                                # we will rebuild classes later, so just break
                                break
                        if freed:
                            # after Kempe swap, v may have changed color, but we break to rebuild classes
                            break
                        else:
                            eliminated = False
                if not eliminated:
                    # could not eliminate this color class, try next lower
                    continue
                # if we eliminated all vertices of target_color, remove the color
                if target_color in classes and not classes[target_color]:
                    del classes[target_color]
                    # remap higher colors down by one
                    for v in range(n):
                        if col[v] > target_color:
                            col[v] -= 1
                    changed = True
                    break  # restart while changed loop
        return col

    best_coloring = kempe_reduction(best_coloring)
    # final validation and compaction
    # compact colors
    unique = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique:
            unique[c] = next_color
            next_color += 1
        best_coloring[i] = unique[c]
    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    start_time = time.time()
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
    else:
        # Adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in range(n):
                if (bit_adj[u] >> v) & 1 and color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg = [0] * n
        for i in range(n):
            deg[i] = bit_adj[i].bit_count()
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # select vertex with max saturation, tie-break by degree in uncolored, then random
            v = max(uncolored, key=lambda x: (sat[x].bit_count(), deg[x], random.random()))
            # find smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            neighbors = bit_adj[v]
            u = 0
            while neighbors:
                if neighbors & 1:
                    if color[u] == -1:  # uncolored
                        sat[u] |= (1 << c)
                        deg[u] -= 1
                    else:
                        # neighbor colored, no need to update sat for uncolored? already done when neighbor colored
                        pass
                neighbors >>= 1
                u += 1
        return color

    # Strategy 2: Recursive Largest First (RLF)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # degree in uncolored subgraph
            deg = {}
            for u in uncolored:
                deg[u] = (bit_adj[u] & sum(1 << v for v in uncolored)).bit_count()
            # start with max degree vertex in uncolored
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = uncolored - {v} - (bit_adj[v] & sum(1 << u for u in uncolored))
            W = (bit_adj[v] & sum(1 << u for u in uncolored))
            # Convert U and W to sets of vertex indices
            U = {i for i in range(n) if (U >> i) & 1}
            W = {i for i in range(n) if (W >> i) & 1}
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = (bit_adj[u] & sum(1 << w for w in W)).bit_count()
                    if score > best_score or (score == best_score and (best_u is None or deg.get(u, 0) < deg.get(best_u, 0))):
                        best_score = score
                        best_u = u
                if best_u is None:
                    break  # should not happen
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u in U to W
                nbrs_U = bit_adj[u] & sum(1 << v for v in U)
                W.update({i for i in range(n) if (nbrs_U >> i) & 1})
                U -= {i for i in range(n) if (nbrs_U >> i) & 1}
            # assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # Core decomposition to get ordering
        deg = [bit_adj[i].bit_count() for i in range(n)]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].append(i)
        # track current degree and position
        pos = [0] * n
        for d in range(max_deg + 1):
            for i, v in enumerate(buckets[d]):
                pos[v] = i
        ordering = []
        # current min degree
        curr_deg = 0
        # copy of degrees
        deg_copy = deg[:]
        # linked list for each bucket? we'll simulate with lists and pointers
        # Instead, we use a simple O(n^2) method since n<=100
        remaining = set(range(n))
        for _ in range(n):
            # find vertex with min degree in remaining
            v = min(remaining, key=lambda x: deg_copy[x])
            ordering.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            neighbors = bit_adj[v]
            u = 0
            while neighbors:
                if neighbors & 1:
                    if u in remaining:
                        deg_copy[u] -= 1
                neighbors >>= 1
                u += 1
        # color in reverse order
        return greedy_color(list(reversed(ordering)))

    # Run all strategies within time budget
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last),
        ("Degree Order", lambda: greedy_color(sorted(range(n), key=lambda x: bit_adj[x].bit_count(), reverse=True))),
    ]

    for name, strat in strategies:
        if time.time() - start_time > 0.04:  # leave some margin
            break
        try:
            coloring = strat()
            # validate
            valid = True
            for u in range(n):
                for v in range(u + 1, n):
                    if (bit_adj[u] >> v) & 1:
                        if coloring[u] == coloring[v]:
                            valid = False
                            break
                if not valid:
                    break
            if valid:
                k = count_colors(coloring)
                if k < best_k:
                    best_k = k
                    best_coloring = coloring[:]
        except Exception:
            continue

    # If no strategy produced valid coloring (should not happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        nonlocal start_time
        # Make sure colors are compact
        def compact_colors(col):
            mapping = {}
            next_color = 0
            for c in col:
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
            return [mapping[c] for c in col]

        coloring = compact_colors(coloring)
        k = max(coloring) + 1 if n > 0 else 0
        improved = True
        while improved and k > 1 and (time.time() - start_time) < 0.045:
            improved = False
            # Find smallest color class
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[coloring[v]].append(v)
            # Try to eliminate color k-1
            target_color = k - 1
            target_vertices = color_classes[target_color][:]
            if not target_vertices:
                # already compacted?
                coloring = compact_colors(coloring)
                k = max(coloring) + 1 if n > 0 else 0
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                if time.time() - start_time > 0.045:
                    break
                used_by_neighbors = 0
                for u in range(n):
                    if (bit_adj[v] >> u) & 1:
                        used_by_neighbors |= (1 << coloring[u])
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    if time.time() - start_time > 0.045:
                        break
                    if used_by_neighbors & (1 << c):
                        # v is adjacent to color c, so Kempe chain might help
                        # Build (target_color, c)-Kempe chain containing v
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for nb in range(n):
                                if (bit_adj[node] >> nb) & 1 and not visited[nb]:
                                    if coloring[nb] == target_color or coloring[nb] == c:
                                        visited[nb] = True
                                        queue.append(nb)
                        # Check if we can swap: after swap, no neighbor of v will have color c?
                        # Actually, swapping in the component will change v's color to c
                        # We need to ensure that no neighbor of v that is NOT in the component has color c
                        # Because neighbors in the component will change from target_color to c or c to target_color
                        # So if a neighbor of v is in the component and has color c, after swap it becomes target_color -> ok
                        # If a neighbor of v is in the component and has color target_color, after swap it becomes c -> conflict if v becomes c? 
                        # Let's think: after swap, v (originally target_color) becomes c.
                        # For a neighbor u of v:
                        #   If u in component and color[u]==c -> becomes target_color (not c) -> ok
                        #   If u in component and color[u]==target_color -> becomes c -> conflict! because v becomes c and u becomes c.
                        #   If u not in component and color[u]==c -> remains c -> conflict.
                        #   If u not in component and color[u]==target_color -> remains target_color -> ok.
                        # So we can swap only if there is no neighbor of v with color c that is NOT in the component.
                        has_external_c = False
                        for u in range(n):
                            if (bit_adj[v] >> u) & 1 and not visited[u] and coloring[u] == c:
                                has_external_c = True
                                break
                        if not has_external_c:
                            # perform swap
                            for node in component:
                                if coloring[node] == target_color:
                                    coloring[node] = c
                                else:
                                    coloring[node] = target_color
                            improved = True
                            break
            if improved:
                # compact colors again
                coloring = compact_colors(coloring)
                k = max(coloring) + 1 if n > 0 else 0
            else:
                break
        return coloring

    # Apply Kempe reduction if time permits
    if time.time() - start_time < 0.045:
        best_coloring = kempe_reduction(best_coloring)

    # Final validation and compacting
    def compact_colors(col):
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]

    best_coloring = compact_colors(best_coloring)
    # Validate one last time
    for u in range(n):
        for v in range(u + 1, n):
            if (bit_adj[u] >> v) & 1:
                if best_coloring[u] == best_coloring[v]:
                    # Should not happen, but if so, fallback to greedy
                    return greedy_color(list(range(n)))
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Colors a graph using the smallest-last (degeneracy) ordering heuristic.
    The algorithm:
      1. Determines if input is adjacency matrix or list.
      2. Converts to adjacency list for uniform processing.
      3. Computes a smallest-last ordering by repeatedly removing the vertex
         of minimum degree in the remaining subgraph.
      4. Colors vertices in reverse order using First-Fit (smallest available color).
    This guarantees a coloring using at most d+1 colors, where d is the graph's degeneracy.
    """
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square, binary entries)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list
    if is_matrix:
        adj_list = []
        for u in range(n):
            neighbors = []
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors.append(v)
