    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        colors = [-1] * n
        # Build core ordering: repeatedly remove min degree vertex
        remaining = list(range(n))
        order = []
        deg = [len(adj_list[v]) for v in range(n)]
        # We'll simulate removal
        removed = [False] * n
        for _ in range(n):
            # Find vertex with min degree among non-removed
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u] and deg[u] < min_deg:
                    min_deg = deg[u]
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    deg[nb] -= 1
        # Color in reverse order
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Kempe chain swap: try to swap colors a and b in component containing v
    def kempe_swap(colors, v, a, b):
        if colors[v] not in (a, b):
            return False
        # BFS to get component
        from collections import deque
        q = deque([v])
        comp = set([v])
        target_a, target_b = a, b
        while q:
            u = q.popleft()
            for nb in adj_list[u]:
                if colors[nb] in (target_a, target_b) and nb not in comp:
                    comp.add(nb)
                    q.append(nb)
        # Try swapping: a->b, b->a
        for u in comp:
            if colors[u] == target_a:
                colors[u] = target_b
            else:
                colors[u] = target_a
        return True

    # Attempt to eliminate the last color using Kempe chains
    def reduce_colors(colors):
        k = max(colors) + 1 if n > 0 else 0
        if k <= 1:
            return colors
        # Try to eliminate color k-1
        target_color = k - 1
        vertices = [v for v in range(n) if colors[v] == target_color]
        # Try direct reassignment first
        for v in vertices:
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != target_color:  # only consider other colors
                    used |= (1 << colors[nb])
            for c in range(target_color):
                if not (used & (1 << c)):
                    colors[v] = c
                    vertices.remove(v)
                    break
        if not vertices:
            # Successfully eliminated target_color, remap higher colors
            new_colors = []
            for v in range(n):
                if colors[v] > target_color:
                    new_colors.append(colors[v] - 1)
                else:
                    new_colors.append(colors[v])
            return new_colors
        # Try Kempe chains for each vertex in target color
        made_progress = False
        for v in vertices[:]:  # copy
            for c in range(target_color):
                # Check if v can be moved to color c via Kempe chain (target_color, c)
                # We simulate swap on a copy
                colors_copy = colors[:]
                if kempe_swap(colors_copy, v, target_color, c):
                    # After swap, check if v is now color c and no conflict introduced
                    if colors_copy[v] == c:
                        # Validate: no neighbor has color c (should be true by Kempe)
                        conflict = False
                        for nb in adj_list[v]:
                            if colors_copy[nb] == c:
                                conflict = True
                                break
                        if not conflict:
                            colors = colors_copy
                            made_progress = True
                            vertices.remove(v)
                            break
            if made_progress:
                break
        if made_progress:
            return reduce_colors(colors)  # recurse
        return colors

    # Validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (shouldn't happen), fallback to greedy
    if not candidates:
        colors = [0] * n
        for v in range(n):
            used = 0
            for nb in adj_list[v]:
                used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(colors)

    # Select best (fewest colors)
    best = min(candidates, key=lambda x: max(x) + 1 if n > 0 else 0)
    # Apply Kempe reduction
    best = reduce_colors(best)
    # Ensure colors are consecutive starting from 0
    if n > 0:
        unique_colors = sorted(set(best))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best = [mapping[c] for c in best]
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle trivial cases
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Build bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper function to check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper function to get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper function to normalize colors to 0..k-1
    def normalize_colors(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # Greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for v in order:
            # Find colors used by neighbors
            neighbor_colors = 0
            for u in adj_list[v]:
                c = coloring[u]
                if c != -1:
                    neighbor_colors |= (1 << c)
            # Find smallest available color
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        return normalize_colors(coloring)

    # DSATUR heuristic
    def dsatur():
        coloring = [-1] * n
        # Track saturation degree: bitmask of colors used by neighbors
        neighbor_color_mask = [0] * n
        # Track number of uncolored neighbors for tie-breaking
        uncolored_degree = [len(adj_list[i]) for i in range(n)]
        colored = [False] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation degree
            max_sat = -1
            candidates = []
            for v in range(n):
                if not colored[v]:
                    sat = neighbor_color_mask[v].bit_count()
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)

            # Tie-break: max uncolored degree
            if len(candidates) > 1:
                max_deg = -1
                best_candidates = []
                for v in candidates:
                    deg = uncolored_degree[v]
                    if deg > max_deg:
                        max_deg = deg
                        best_candidates = [v]
                    elif deg == max_deg:
                        best_candidates.append(v)
                candidates = best_candidates

            # Final tie-break: random
            v = random.choice(candidates) if candidates else 0

            # Assign smallest available color
            c = 0
            while neighbor_color_mask[v] & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True

            # Update neighbors
            for u in adj_list[v]:
                if not colored[u]:
                    neighbor_color_mask[u] |= (1 << c)
                    uncolored_degree[u] -= 1

        return normalize_colors(coloring)

    # RLF heuristic (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            independent_set = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                # Find vertex with max degree in induced subgraph
                max_deg = -1
                v_start = None
                for v in uncolored:
                    # Count neighbors in uncolored set
                    deg = 0
                    for u in adj_list[v]:
                        if u in uncolored:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        v_start = v
                if v_start is not None:
                    independent_set.append(v_start)
                    uncolored.remove(v_start)

            # Partition remaining uncolored into U (eligible) and W (ineligible)
            W = set()
            for v in independent_set:
                for u in adj_list[v]:
                    if u in uncolored:
                        W.add(u)
            U = uncolored - W

            # Greedily add vertices from U to independent set
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_u_deg = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # Tie-break: min degree in U
                    u_deg = 0
                    for w in adj_list[u]:
                        if w in U:
                            u_deg += 1
                    if (w_neighbors > max_w_neighbors or 
                        (w_neighbors == max_w_neighbors and u_deg < min_u_deg)):
                        max_w_neighbors = w_neighbors
                        min_u_deg = u_deg
                        best_u = u

                if best_u is None:
                    break  # Should not happen

                independent_set.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return normalize_colors(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []

        # Repeatedly remove vertex of minimum degree
        for _ in range(n):
            # Find vertex with min degree in remaining graph
            min_deg = float('inf')
            v_min = None
            for v in remaining:
                if degree[v] < min_deg:
                    min_deg = degree[v]
                    v_min = v
            if v_min is None:
                break
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors
            for u in adj_list[v_min]:
                if u in remaining:
                    degree[u] -= 1

        # Color in reverse order
        return greedy_color(list(reversed(order)))

    # Kempe chain swap attempt
    def kempe_swap(coloring, v, c1, c2):
        # Try to swap colors c1 and c2 in the Kempe chain containing v
        # Only if v has color c1
        if coloring[v] != c1:
            return False

        # Find all vertices reachable from v via alternating c1-c2 paths
        visited = [False] * n
        stack = [v]
        visited[v] = True
        component = []

        while stack:
            u = stack.pop()
            component.append(u)
            for w in adj_list[u]:
                if not visited[w] and (coloring[w] == c1 or coloring[w] == c2):
                    visited[w] = True
                    stack.append(w)

        # Check if swapping is safe: no neighbor outside component has color c2
        # Actually, for Kempe chain swap to be valid, we need that after swap,
        # no adjacent vertices have same color. Since we only swap c1<->c2 in component,
        # it's valid if no vertex in component has a neighbor outside component with color c2
        # (because after swap, those would become c1 and conflict if neighbor has c2)
        # But standard Kempe chain swap is always valid for preserving proper coloring
        # because we only swap within the component and the component is maximal.
        # However, we want to free color c1 for v, so after swap v gets c2.
        # We need to ensure that v doesn't have any neighbor with color c2 outside the component.
        # Actually, by definition of the component, there is no edge from component to 
        # a vertex colored c2 outside the component (otherwise it would be in the component).
        # So the swap is always valid.

        # Perform the swap
        for u in component:
            if coloring[u] == c1:
                coloring[u] = c2
            else:  # must be c2
                coloring[u] = c1
        return True

    # Attempt to eliminate a color class using Kempe chains
    def eliminate_color(coloring, target_color):
        # Get vertices with target_color
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return True  # Already eliminated

        # Try to recolor each vertex
        for v in vertices:
            # Try direct reassignment to a lower color
            neighbor_colors = set()
            for u in adj_list[v]:
                c = coloring[u]
                if c < target_color:
                    neighbor_colors.add(c)
            for c in range(target_color):
                if c not in neighbor_colors:
                    # Direct reassignment possible
                    coloring[v] = c
                    return True

            # Try Kempe chain swaps with each lower color
            for c in range(target_color):
                # Check if v has a neighbor with color c (necessary for Kempe chain to be useful)
                has_neighbor_c = False
                for u in adj_list[v]:
                    if coloring[u] == c:
                        has_neighbor_c = True
                        break
                if not has_neighbor_c:
                    continue

                # Try to swap colors c and target_color in the Kempe chain of v
                # Make a copy to test
                test_coloring = coloring[:]
                if kempe_swap(test_coloring, v, target_color, c):
                    # After swap, v should have color c
                    if test_coloring[v] == c:
                        # Verify the coloring is still valid
                        if is_valid_coloring(test_coloring):
                            coloring[:] = test_coloring
                            return True

        return False

    # Main algorithm: generate initial colorings and try to improve
    best_coloring = None
    best_num_colors = float('inf')

    # Generate initial candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Evaluate initial candidates
    for coloring in candidates:
        if is_valid_coloring(coloring):
            k = num_colors(coloring)
            if k < best_num_colors:
                best_num_colors = k
                best_coloring = coloring[:]

    # If no valid coloring found (shouldn't happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_num_colors = num_colors(best_coloring)
        best_coloring = normalize_colors(best_coloring)

    # Try to reduce colors by eliminating highest color classes
    current_coloring = best_coloring[:]
    k = best_num_colors

    # Iteratively try to eliminate color k-1, then k-2, etc.
    for target_color in range(k-1, -1, -1):
        # Make a copy to work on
        test_coloring = current_coloring[:]
        # Try to eliminate this color
        if eliminate_color(test_coloring, target_color):
            # Success: compact colors
            test_coloring = normalize_colors(test_coloring)
            new_k = num_colors(test_coloring)
            if new_k < k and is_valid_coloring(test_coloring):
                current_coloring = test_coloring
                k = new_k
                # Restart from the new highest color
                target_color = k  # will be decremented to k-1 in next iteration
            else:
                # No improvement, try next lower target color
                continue
        else:
            # Could not eliminate this color, try next lower
            continue

    # Final validation and normalization
    if not is_valid_coloring(current_coloring):
        # Fallback to DSATUR if something went wrong
        current_coloring = dsatur()

    current_coloring = normalize_colors(current_coloring)
    return current_coloring

import math
