                deg_uncolored[v] = cnt
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and v not in neighbors[u]}
            # W: vertices adjacent to at least one in S
            W = {u for u in uncolored if u != v and v in neighbors[u]}
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = None
                for u in U:
                    # count neighbors in W
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # deg in U
                    degU = 0
                    for w in neighbors[u]:
                        if w in U:
                            degU += 1
                    if score > best_score or (score == best_score and degU < best_degU) or (score == best_score and degU == best_degU and random.random() < 0.5):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for vertex in S:
                colors[vertex] = color_idx
            uncolored -= S
            color_idx += 1
        return colors

    # Helper: Smallest-Last ordering
    def smallest_last():
        # core decomposition to get order
        deg = [len(neighbors[i]) for i in range(n)]
        # buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        pos = [0] * n
        for v in range(n):
            d = deg[v]
            buckets[d].append(v)
            pos[v] = len(buckets[d]) - 1
        # current min degree
        min_deg = 0
        order = []
        # copy of degrees
        curr_deg = deg[:]
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if curr_deg[u] > curr_deg[v]:  # u not yet removed
                    d = curr_deg[u]
                    # remove u from bucket d
                    buckets[d].pop(pos[u])
                    if buckets[d]:
                        pos[buckets[d][-1]] = len(buckets[d]) - 1
                    # add to bucket d-1
                    curr_deg[u] -= 1
                    d2 = curr_deg[u]
                    buckets[d2].append(u)
                    pos[u] = len(buckets[d2]) - 1
            curr_deg[v] = -1  # removed
        # reverse order for coloring
        order.reverse()
        return greedy_color(order)

    # Helper: Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(colors, a, b, v):
        n = len(colors)
        stack = [v]
        visited = [False] * n
        visited[v] = True
        component = []
        while stack:
            u = stack.pop()
            component.append(u)
            for w in neighbors[u]:
                if not visited[w] and (colors[w] == a or colors[w] == b):
                    visited[w] = True
                    stack.append(w)
        # swap colors a<->b in component
        for u in component:
            if colors[u] == a:
                colors[u] = b
            elif colors[u] == b:
                colors[u] = a
        return colors

    # Helper: try to eliminate a color class via Kempe or reassignment
    def reduce_colors(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # try from highest color down
        for target_color in range(k-1, 0, -1):
            # collect vertices with target_color
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                continue
            # try to reassign each vertex to a lower color
            changed = False
            for v in verts:
                used = 0
                for u in neighbors[v]:
                    c = colors[u]
                    if c != -1:
                        used |= (1 << c)
                # find smallest available color < target_color
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # reassign v to c
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # restart reduction from scratch
                return reduce_colors(colors)
            # try Kempe chains with each lower color
            for v in verts:
                for c in range(target_color):
                    # check if v can be swapped via Kempe chain (c, target_color)
                    # only if no neighbor of v has color c (so that after swap, v gets c and no conflict)
                    has_c_neighbor = False
                    for u in neighbors[v]:
                        if colors[u] == c:
                            has_c_neighbor = True
                            break
                    if not has_c_neighbor:
                        # perform Kempe swap on component of v for colors c and target_color
                        kempe_swap(colors, c, target_color, v)
                        # after swap, v should have color c
                        # verify
                        if colors[v] == c:
                            changed = True
                            break
                if changed:
                    break
            if changed:
                return reduce_colors(colors)
        # compact colors: remap to 0..k-1
        # but we already have zero-based? ensure consecutive
        used_colors = set()
        for c in colors:
            if c != -1:
                used_colors.add(c)
        mapping = {}
        sorted_colors = sorted(used_colors)
        for idx, col in enumerate(sorted_colors):
            mapping[col] = idx
        new_colors = [mapping[c] if c != -1 else 0 for c in colors]
        return new_colors

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: greedy by degree order
    try:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass
    # If no candidate, assign all zeros (invalid but safe)
    if not candidates:
        return [0] * n
    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply color reduction via Kempe chains
    best = reduce_colors(best)
    # Final validation (should be valid)
    if not is_valid(best):
        # fallback to DSATUR if something went wrong
        best = dsatur()
    return best

