            for w in adj_list[v]:
                if color[w] == -1:
                    sat[w] = bit_count(neighbor_colors & sum((1 << color[x]) for x in adj_list[w] if color[x] != -1))
                    # More efficient: maintain a set of neighbor colors per vertex
            # Recompute saturation efficiently: for each uncolored neighbor, count distinct colors in its colored neighbors
            for w in adj_list[v]:
                if color[w] == -1:
