    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [bit_count(bit_adj[u]) for u in range(n)]
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degrees[u]].append(u)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # Remove a vertex from bucket[ptr]
            while buckets[ptr] and (buckets[ptr][-1] not in remaining):
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for w in adj_list[v]:
                if w in remaining:
                    degrees[w] -= 1
                    if degrees[w] < ptr:
