                    deg[u] -= 1
                    buckets[old_deg].remove(u)
                    buckets[deg[u]].add(u)
            remaining.remove(v)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # If no candidate (should not happen), fallback to trivial
    if not candidates:
        color = [0] * n
        for i in range(1, n):
            color[i] = i
        return color

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        nonlocal k
        changed = True
        while changed and k > 1:
            changed = False
            # Find smallest color class (highest index, assuming compact)
            # We'll try to eliminate color k-1
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already compacted?
                k -= 1
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                used_by_neighbors = set()
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        used_by_neighbors.add(coloring[u])
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if c not in used_by_neighbors:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Skip if v already has color c (shouldn't happen)
                    if coloring[v] == c:
                        continue
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # Only if v has color target_color (it does)
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for u in neighbors[node]:
                                if u not in visited and (coloring[u] == target_color or coloring[u] == c):
                                    stack.append(u)
                    # Check if any neighbor of v in the component has color c? Actually, we want to see
                    # if we can swap without causing conflict. Swapping is safe if no neighbor of v
                    # outside the component has color c (because after swap, v would get c).
                    # More precisely: after swapping colors target_color and c in the component,
                    # v will get color c. This is valid if no neighbor of v has color c after swap.
                    # Neighbors of v: if in component, their color flips (so if they were target_color, become c; if c, become target_color).
                    # We need to ensure that no neighbor of v ends up with color c.
                    # Let's compute: after swap, a neighbor u of v will have:
                    #   - if u in component: color flips between target_color and c
                    #   - if u not in component: color unchanged
                    # So neighbor u has color c after swap iff:
                    #   (u in component and coloring[u] == target_color) OR (u not in component and coloring[u] == c)
                    # We want this to be false for all u in neighbors[v].
                    conflict = False
                    for u in neighbors[v]:
                        if (u in component and coloring[u] == target_color) or (u not in component and coloring[u] == c):
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:  # must be c
                                coloring[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            # If we made a change, check if target color class is now empty
            if changed:
                # Recompute k and compact if needed
                used_colors = set(coloring)
                if not used_colors:
                    k = 0
                else:
                    k = max(used_colors) + 1
                # Compact colors to 0..k-1
                mapping = {}
                next_c = 0
                for old in sorted(used_colors):
                    mapping[old] = next_c
                    next_c += 1
                for i in range(n):
                    coloring[i] = mapping[coloring[i]]
            else:
                # Could not reduce further
                break
        return coloring

    # Apply Kempe reduction
    best = kempe_reduce(best)
    # Final validation (should hold)
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build neighbor bitmasks
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= 1 << j
    else:
        for i in range(n):
            for nb in adj[i]:
                bit_adj[i] |= 1 << nb

    def bit_count(x: int) -> int:
        return x.bit_count()

    def neighbors_of(v: int) -> int:
        return bit_adj[v]

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and bit_count(neighbors_of(u) & sum(1 << w for w in uncolored)) > max_deg):
                    max_sat = sat[u]
                    max_deg = bit_count(neighbors_of(u) & sum(1 << w for w in uncolored))
                    v = u
            if v == -1:
                v = next(iter(uncolored))
            # find smallest color not used by neighbors
            used = 0
            nb = neighbors_of(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                c = color[w]
                if c >= 0:
                    used |= 1 << c
                nb &= nb - 1
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            nb = neighbors_of(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                if color[w] == -1:
                    sat[w] += 1
                nb &= nb - 1
        return color

    # RLF (Recursive Largest First)
    def rlf() -> list[int]:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in induced subgraph of uncolored
            deg = {}
            for v in uncolored:
                deg[v] = bit_count(neighbors_of(v) & sum(1 << w for w in uncolored))
            # pick vertex with max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to any in S
            # W: vertices adjacent to at least one in S
            U = set()
            W = set()
            for w in uncolored:
                if neighbors_of(w) & sum(1 << s for s in S):
                    W.add(w)
                else:
                    U.add(w)
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = None
                for u in U:
                    score = bit_count(neighbors_of(u) & sum(1 << w for w in W))
                    degU = bit_count(neighbors_of(u) & sum(1 << w for w in U))
                    if score > best_score or (score == best_score and degU < best_degU):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                nb = neighbors_of(u)
                while nb:
                    w = (nb & -nb).bit_length() - 1
                    if w in U:
                        U.remove(w)
                        W.add(w)
                    nb &= nb - 1
            # assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        # core decomposition to get order
        deg = [bit_count(neighbors_of(v)) for v in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = deg[v]
        # simulate removal
        for _ in range(n):
            # find min degree vertex in remaining
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # update neighbors
            nb = neighbors_of(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                if w in remaining:
                    # decrease degree of w
                    old_deg = pos[w]
                    buckets[old_deg].remove(w)
                    pos[w] -= 1
                    new_deg = pos[w]
                    buckets[new_deg].append(w)
                nb &= nb - 1
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            nb = neighbors_of(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                cw = color[w]
                if cw >= 0:
                    used |= 1 << cw
                nb &= nb - 1
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(color_init: list[int]) -> list[int]:
        color = color_init[:]
        # map color to vertices
        while True:
            # determine number of colors used
            max_color = max(color) if n > 0 else -1
            if max_color < 0:
                return color
            # build color classes
            classes = [[] for _ in range(max_color + 1)]
            for v in range(n):
                classes[color[v]].append(v)
            # find smallest non-empty color class (by index, but we target highest color for removal)
            # we try to eliminate the highest color class
            target = max_color
            if not classes[target]:
                # should not happen, but compact
                # remap colors to be consecutive
                mapping = {}
                new_color = [-1] * n
                next_c = 0
                for v in range(n):
                    if color[v] not in mapping:
                        mapping[color[v]] = next_c
                        next_c += 1
                    new_color[v] = mapping[color[v]]
                color = new_color
                continue
            # try to recolor each vertex in target class to a lower color
            moved = False
            for v in classes[target]:
                # try direct reassignment to a lower color
                used = 0
                nb = neighbors_of(v)
                while nb:
                    w = (nb & -nb).bit_length() - 1
                    cw = color[w]
                    if cw >= 0:
                        used |= 1 << cw
                    nb &= nb - 1
                for c in range(target):
                    if not (used & (1 << c)):
                        color[v] = c
                        moved = True
                        break
                if moved:
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # if v already has color c after possible direct move, skip
                    if color[v] == c:
                        continue
                    # check if there is a Kempe chain (v, target) <-> (c) that does not include any other target-colored vertex besides v
                    # we BFS from v in the subgraph of colors {target, c}
                    from collections import deque
                    visited = [False] * n
                    q = deque([v])
                    visited[v] = True
                    component = []
                    has_other_target = False
                    while q:
                        u = q.popleft()
                        component.append(u)
                        if color[u] == target and u != v:
                            has_other_target = True
                        # explore neighbors with color target or c
                        nb = neighbors_of(u)
                        while nb:
                            w = (nb & -nb).bit_length() - 1
                            if not visited[w] and (color[w] == target or color[w] == c):
                                visited[w] = True
                                q.append(w)
                            nb &= nb - 1
                    if not has_other_target:
                        # swap colors target and c in this component
                        for u in component:
                            if color[u] == target:
                                color[u] = c
                            elif color[u] == c:
                                color[u] = target
                        moved = True
                        break
                if moved:
                    break
            if not moved:
                # cannot reduce further
                break
        # compact colors to be 0..k-1
        mapping = {}
        next_c = 0
        for v in range(n):
            if color[v] not in mapping:
                mapping[color[v]] = next_c
                next_c += 1
            color[v] = mapping[color[v]]
        return color

    # Run all heuristics
    best_color = None
    best_k = float('inf')
    for func in (dsatur, rlf, smallest_last):
        try:
            col = func()
            col = kempe_reduce(col)
            # validate
            ok = True
            for u in range(n):
                nb = neighbors_of(u)
                while nb:
                    v = (nb & -nb).bit_length() - 1
                    if color[u] == color[v]:
                        ok = False
                        break
                    nb &= nb - 1
                if not ok:
                    break
            if not ok:
                continue
            k = len(set(col))
            if k < best_k:
                best_k = k
                best_color = col
        except Exception:
            continue
    if best_color is None:
        # fallback to greedy
        best_color = [0] * n
        for i in range(n):
            used = 0
            nb = neighbors_of(i)
            while nb:
                w = (nb & -nb).bit_length() - 1
                used |= 1 << best_color[w]
                nb &= nb - 1
            c = 0
            while used & (1 << c):
                c += 1
            best_color[i] = c
    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
    else:
        for u in range(n):
            if isinstance(adj[u], list):
                for v in adj[u]:
                    if 0 <= v < n:
                        neighbors[u].add(v)

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    best_coloring = None
    best_k = float('inf')

    # Helper: validate coloring and compute number of colors
    def validate_and_get_k(coloring):
        if len(coloring) != n:
            return float('inf')
        seen = set()
        for u in range(n):
            c = coloring[u]
            if c < 0:
                return float('inf')
            seen.add(c)
            # Check neighbors
            mask = bit_adj[u]
            v = 0
            while mask:
                if mask & 1:
                    if coloring[v] == c:
                        return float('inf')
                mask >>= 1
                v += 1
        return len(seen)

    # Helper: convert to consecutive colors starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return [0] * n
        colors = [-1] * n
        # Precompute degrees
        degrees = [len(neighbors[u]) for u in range(n)]
        # Saturation sets: track distinct neighbor colors per vertex
        saturation_sets = [set() for _ in range(n)]
        # Colored neighbor count not needed explicitly

        for _ in range(n):
            # Select uncolored vertex with max saturation degree, tie-break by degree, then random
            cand = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    sat = len(saturation_sets[u])
                    deg = degrees[u]
                    if sat > max_sat or (sat == max_sat and deg > max_deg) or \
                       (sat == max_sat and deg == max_deg and (cand == -1 or random.random() < 0.5)):
                        max_sat = sat
                        max_deg = deg
                        cand = u
            if cand == -1:
                break  # should not happen
            # Find smallest available color
            used = saturation_sets[cand]
            c = 0
            while c in used:
                c += 1
            colors[cand] = c
            # Update saturation sets of uncolored neighbors
            for v in neighbors[cand]:
                if colors[v] == -1:
                    saturation_sets[v].add(c)
        return colors

    # RLF: Recursive Largest First via independent set extraction
    def rlf():
        if n == 0:
            return [0] * n
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for this color
            S = set()
            # Step 1: pick vertex with max degree in G[uncolored]
            if uncolored:
                v = max(uncolored, key=lambda u: len(neighbors[u] & uncolored))
                S.add(v)
                uncolored.remove(v)
            # Partition remaining uncolored into U (eligible) and W (ineligible)
            W = set()
            for u in S:
                W.update(neighbors[u])
            U = uncolored - W

            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = len(neighbors[u] & W)
                    deg_in_U = len(neighbors[u] & U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for v in neighbors[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color to all in S
            for u in S:
                colors[u] = color
            color += 1
            # Next iteration: uncolored becomes W (vertices adjacent to S)
            uncolored = W
        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return [0] * n
        # Compute degeneracy ordering via min-degree peeling
        remaining = set(range(n))
        degree = [len(neighbors[u]) for u in range(n)]
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            # Find vertex with min degree in remaining
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                if degree[v] < min_deg:
                    min_deg = degree[v]
                    v_min = v
            if v_min == -1:
                break
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors
            for v in neighbors[v_min]:
                if v in remaining:
                    degree[v] -= 1
        # Color in reverse order using first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        changed = True
        while changed:
            changed = False
            # Get color classes
            color_classes = {}
            for v in range(n):
                c = current[v]
                color_classes.setdefault(c, []).append(v)
            if not color_classes:
                break
            max_color = max(color_classes.keys())
            # Try to eliminate color classes from highest down
            for target_color in range(max_color, -1, -1):
                if target_color not in color_classes or not color_classes[target_color]:
                    continue
                # Try to recolor each vertex in this class
                eliminated = True
                for v in color_classes[target_color][:]:  # iterate over copy
                    # Try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if current[u] != -1:
                            neighbor_colors.add(current[u])
                    for c in range(target_color):  # only try colors < target_color
                        if c not in neighbor_colors:
                            # Move v to color c
                            current[v] = c
                            changed = True
                            break
                    else:
                        # Direct reassignment not possible, try Kempe chains
                        found = False
                        for c in range(target_color):
                            # Skip if color c not present (optional optimization)
                            if c not in color_classes:
                                continue
                            # Check if v is adjacent to any vertex of color c
                            adj_to_c = False
                            for u in neighbors[v]:
                                if current[u] == c:
                                    adj_to_c = True
                                    break
                            if adj_to_c:
                                continue  # Kempe chain swap would not help directly
                            # Build (target_color, c)-Kempe chain containing v
                            stack = [v]
                            visited = set()
                            component = set()
                            while stack:
                                node = stack.pop()
                                if node in visited:
                                    continue
                                visited.add(node)
                                if current[node] == target_color or current[node] == c:
                                    component.add(node)
                                    for w in neighbors[node]:
                                        if w not in visited and (current[w] == target_color or current[w] == c):
                                            stack.append(w)
                            # Check if swapping this component is safe: 
                            # No vertex in component should have a neighbor of color c outside component (would cause conflict after swap)
                            safe = True
                            for node in component:
                                for w in neighbors[node]:
                                    if current[w] == c and w not in component:
                                        safe = False
                                        break
                                if not safe:
                                    break
                            if safe:
                                # Perform swap: target_color <-> c in component
                                for node in component:
                                    if current[node] == target_color:
                                        current[node] = c
                                    else:  # must be c
                                        current[node] = target_color
                                changed = True
                                found = True
                                break
                        if found:
                            # After successful Kempe swap, v might still be target_color? 
                            # Actually, if v was target_color and we swapped, it becomes c.
                            # So we break and restart the color class iteration
                            break
                # After processing all vertices in target_color, check if class is empty
                if target_color in color_classes and not color_classes[target_color]:
                    # Remove this color by shifting higher colors down
                    for v in range(n):
                        if current[v] > target_color:
                            current[v] -= 1
                    changed = True
                    break  # restart while loop as coloring changed
                elif not changed:
                    # Could not eliminate this color, try next lower
                    pass
        return current

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        k1 = validate_and_get_k(c1)
        if k1 < best_k:
            best_k = k1
            best_coloring = c1
        candidates.append(c1)
    except Exception:
        pass

    # RLF
    try:
        c2 = rlf()
        k2 = validate_and_get_k(c2)
        if k2 < best_k:
            best_k = k2
            best_coloring = c2
        candidates.append(c2)
    except Exception:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        k3 = validate_and_get_k(c3)
        if k3 < best_k:
            best_k = k3
            best_coloring = c3
        candidates.append(c3)
    except Exception:
        pass

    # Apply Kempe reduction to each candidate and keep the best
    for cand in candidates:
        try:
            reduced = kempe_reduce(cand)
            k_red = validate_and_get_k(reduced)
            if k_red < best_k:
                best_k = k_red
                best_coloring = reduced
        except Exception:
            pass

    # Fallback: if no candidate succeeded, use greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        best_coloring = colors

    # Normalize to ensure consecutive colors starting from 0
    best_coloring = normalize(best_coloring)
    # Final validation (should be valid by construction)
    # In case of any issue, return a valid but possibly non-optimal coloring
    final_k = validate_and_get_k(best_coloring)
    if final_k == float('inf'):
        # Last resort: assign each vertex a unique color
        best_coloring = list(range(n))

    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        # Check if binary matrix
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build neighbor bitmasks and adjacency list
    bit_adj = [0] * n
    neigh = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
                    neigh[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)
                    neigh[i].append(j)
    # Helper: test if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neigh[u]:
                if cu == coloring[v]:
                    return False
        return True
    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # Helper: convert coloring to consecutive 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map used colors to 0..k-1
        used = {}
        nxt = 0
        for i in range(n):
            c = coloring[i]
            if c not in used:
                used[c] = nxt
                nxt += 1
            coloring[i] = used[c]
        return coloring
    # DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets as bitmask for fast sat update
        neighbor_colors = [0] * n
        uncolored = set(range(n))
        # initial degree tie-breaker
        degree = [len(neigh[i]) for i in range(n)]
        while uncolored:
            # select vertex with max sat, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], degree[x], random.random()))
            # compute mex of neighbor colors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neigh[v]:
                if color[u] == -1:  # uncolored
                    # add color c to neighbor's palette
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1
        return color
    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # degree in current uncolored subgraph
            deg = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in neigh[v]:
                    if u in uncolored:
                        deg[v] += 1
            # start with max degree vertex
            v = max(uncolored, key=lambda x: (deg[x], random.random()))
            S = {v}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v} - set(neigh[v])
            W = set(neigh[v]) & uncolored
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                best_deg = math.inf
                for u in U:
                    # count neighbors in W
                    score = 0
                    for w in neigh[u]:
                        if w in W:
                            score += 1
                    # tie-break by min degree in U
                    deg_u = 0
                    for w in neigh[u]:
                        if w in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and deg_u < best_deg):
                        best_score = score
                        best_deg = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neigh[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color
    # Smallest-Last (Matula & Beck) greedy
    def smallest_last():
        # core decomposition to get ordering
        degree = [len(neigh[i]) for i in range(n)]
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            buckets[d].append(v)
        # track current degree and position
        curr_deg = degree[:]
        pos = [0] * n
        for d in range(max_deg + 1):
            for i, v in enumerate(buckets[d]):
                pos[v] = i
        # linked list for each bucket
        head = [-1] * (max_deg + 1)
        tail = [-1] * (max_deg + 1)
        nxt = [-1] * n
        prv = [-1] * n
        for d in range(max_deg + 1):
            if buckets[d]:
                head[d] = buckets[d][0]
                tail[d] = buckets[d][-1]
                for i in range(len(buckets[d]) - 1):
                    v = buckets[d][i]
                    nxt[v] = buckets[d][i + 1]
                    prv[nxt[v]] = v
        # array to mark removed
        removed = [False] * n
        order = []
        # current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and head[min_deg] == -1:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = head[min_deg]
            # remove v from bucket
            removed[v] = True
            order.append(v)
            # unlink v
            if prv[v] != -1:
                nxt[prv[v]] = nxt[v]
            else:
                head[min_deg] = nxt[v]
            if nxt[v] != -1:
                prv[nxt[v]] = prv[v]
            else:
                tail[min_deg] = prv[v]
            # update neighbors
            for u in neigh[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    # remove u from bucket d
                    if prv[u] != -1:
                        nxt[prv[u]] = nxt[u]
                    else:
                        head[d] = nxt[u]
                    if nxt[u] != -1:
                        prv[nxt[u]] = prv[u]
                    else:
                        tail[d] = prv[u]
                    # decrease degree
                    curr_deg[u] -= 1
                    d2 = curr_deg[u]
                    # add u to bucket d2
                    if head[d2] == -1:
                        head[d2] = tail[d2] = u
                        prv[u] = nxt[u] = -1
                    else:
                        nxt[u] = head[d2]
                        prv[head[d2]] = u
                        head[d2] = u
                    # update min_deg if needed
                    if d2 < min_deg:
                        min_deg = d2
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neigh[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Kempe chain elimination
    def kempe_reduce(coloring):
        # make copy
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (largest index)
            maxc = max(col) if col else -1
            if maxc < 0:
                break
            # try to eliminate color classes from high to low
            for target in range(maxc, -1, -1):
                # collect vertices with this color
                verts = [v for v in range(n) if col[v] == target]
                if not verts:
                    continue
                # try to recolor each vertex
                eliminated = True
                for v in verts:
                    # try direct reassignment to lower color
                    neighbor_colors = 0
                    for u in neigh[v]:
                        if col[u] != -1:
                            neighbor_colors |= (1 << col[u])
                    # find smallest available color < target
                    found = False
                    for c in range(target):
                        if not (neighbor_colors & (1 << c)):
                            col[v] = c
                            found = True
                            changed = True
                            break
                    if found:
                        continue
                    # try Kempe chain swap with each lower color
                    swapped = False
                    for c in range(target):
                        # if v already has color c after some swap, skip
                        if col[v] == c:
                            continue
                        # check if v is connected to color c via Kempe chain
                        # BFS/DFS over vertices colored c or target
                        from collections import deque
                        visited = [False] * n
                        q = deque()
                        # start from v only if it has color target (it does)
                        if col[v] == target:
                            q.append(v)
                            visited[v] = True
                        comp_target = 0
                        comp_c = 0
                        while q:
                            x = q.popleft()
                            if col[x] == target:
                                comp_target += 1
                            else:
                                comp_c += 1
                            for y in neigh[x]:
                                if not visited[y] and (col[y] == target or col[y] == c):
                                    visited[y] = True
                                    q.append(y)
                        # if the component does not contain any vertex of color c, we can swap
                        # Actually, we can always swap, but we want to free color target for v
                        # Swapping will change v's color to c if v is in the component
                        # We want to know if after swap, v can be color c (i.e., v is in the component)
                        # Since we started from v and it's color target, it's in the component.
                        # After swap, v becomes color c.
                        # But we must ensure that no neighbor of v becomes color c? 
                        # Actually, after swap, neighbors that were color c become target, and vice versa.
                        # Since we are only concerned about freeing color target for v, we note that
                        # after swap, v will be color c, so color target is no longer used by v.
                        # However, we need to make sure that we don't accidentally put another vertex
                        # into color target that wasn't before? Swapping only exchanges colors in the component.
                        # So the set of vertices with color target in the component becomes color c,
                        # and vice versa. So the total number of vertices of each color may change.
                        # We want to eliminate color target, so we need that after swapping, no vertex
                        # remains with color target. That is only possible if the component contains
                        # all vertices of color target. But we are processing one vertex at a time.
                        # Instead, the standard Kempe elimination: for a vertex v of color target,
                        # if there exists a color c such that v is not adjacent to any vertex of color c,
                        # we can recolor v to c (already tried). Otherwise, we look for a Kempe chain
                        # (v, c)-chain that does not contain a neighbor of v colored c? 
                        # Actually, the condition is: if in the (target, c)-Kempe chain of v, 
                        # there is no vertex colored c that is adjacent to v, then we can swap the chain
                        # and recolor v to c without conflict.
                        # Simpler: attempt to swap and check if valid.
                        # We'll do the swap and then check if coloring remains valid.
                        # Since n <= 100, we can afford to check.
                        # Swap colors target and c in the component
                        for x in range(n):
                            if visited[x]:
                                if col[x] == target:
                                    col[x] = c
                                else:
                                    col[x] = target
                        # check if still valid
                        ok = True
                        for x in range(n):
                            for y in neigh[x]:
                                if col[x] == col[y]:
                                    ok = False
                                    break
                            if not ok:
                                break
                        if ok:
                            swapped = True
                            changed = True
                            break  # break color loop
                        else:
                            # swap back
                            for x in range(n):
                                if visited[x]:
                                    if col[x] == target:
                                        col[x] = c
                                    else:
                                        col[x] = target
                    if swapped:
                        break  # break vertex loop
                if not eliminated:
                    # cannot eliminate this color class, break to try next lower? 
                    # Actually, if we couldn't eliminate this class, we break and try next target?
                    # But we are iterating from high to low, so if we can't eliminate target, 
                    # we break and try to eliminate a lower one? 
                    # However, eliminating a lower color class might be easier.
                    # We'll break the vertex loop and continue to next target.
                    # But we set eliminated=False if any vertex couldn't be recolored.
                    # We'll break and try next target.
                    break
                else:
                    # all vertices of target color recolored, so color target is eliminated
                    # compact colors later
                    break
            # if we eliminated a color, restart the while loop
            if changed:
                break
        # compact colors to 0..k-1
        return normalize(col)
    # Run all heuristics
    start = time.perf_counter()
    best_coloring = None
    best_k = math.inf
    # DSATUR
    if time.perf_counter() - start < 0.05:
        col = dsatur()
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]
    # RLF
    if time.perf_counter() - start < 0.05:
        col = rlf()
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]
    # Smallest-Last
    if time.perf_counter() - start < 0.05:
        col = smallest_last()
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]
    # If none worked (should not happen), fallback to greedy
    if best_coloring is None:
        # simple greedy in vertex order
        col = [-1] * n
        for v in range(n):
            used = 0
            for u in neigh[v]:
                if col[u] != -1:
                    used |= (1 << col[u])
            c = 0
            while used & (1 << c):
                c += 1
            col[v] = c
        best_coloring = col
    # Apply Kempe reduction
    if time.perf_counter() - start < 0.05:
        best_coloring = kempe_reduce(best_coloring)
    # Final validation and normalization
    if not is_valid(best_coloring):
        # emergency fix: greedy
        col = [-1] * n
        for v in range(n):
            used = 0
            for u in neigh[v]:
                if col[u] != -1:
                    used |= (1 << col[u])
            c = 0
            while used & (1 << c):
                c += 1
            col[v] = c
        best_coloring = col
    best_coloring = normalize(best_coloring)
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for u in range(n):
            for v in adj_list[u]:
                bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: convert to compact 0..k-1 colors
    def compact_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # Precompute neighbor bitmasks for saturation
        neighbor_mask = bit_adj[:]
        # Degree for tie-breaking
        degree = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                # Compute saturation: distinct colors in neighbors
                sat = 0
                seen = 0
                for u in adj_list[v]:
                    if colored[u]:
                        c = colors[u]
                        if not (seen >> c) & 1:
                            seen |= (1 << c)
                            sat += 1
                if sat > best_sat or (sat == best_sat and degree[v] > best_deg):
                    best_sat = sat
                    best_deg = degree[v]
                    best_v = v
                elif sat == best_sat and degree[v] == best_deg and v < best_v:
                    best_v = v  # deterministic tie-break by index

            v = best_v
            # Find smallest available color
            used = 0
            for u in adj_list[v]:
                if colored[u]:
                    c = colors[u]
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
        return compact_colors(colors)

    # RLF: Recursive Largest First (maximal independent set extraction)
    def rlf():
        colors = [-1] * n
        colored = [False] * n
        color = 0
        # Precompute degree in full graph for initial selection
        full_degree = [len(adj_list[i]) for i in range(n)]

        while not all(colored):
            # Find uncolored vertex with max degree in uncolored subgraph
            best_v = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                # Count uncolored neighbors
                deg = 0
                for u in adj_list[v]:
                    if not colored[u]:
                        deg += 1
                if deg > best_deg or (deg == best_deg and v < best_v):
                    best_deg = deg
                    best_v = v

            # Build independent set for this color
            S = [best_v]
            colored[best_v] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if colored[u]:
                    continue
                adjacent_to_S = False
                for v in S:
                    if u in adj_list[v]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    # Count neighbors in W
                    score = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            score += 1
                    # Tie-break: min degree in G[U]
                    deg_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or \
                       (score == best_score and deg_U == best_deg_U and u < best_u):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u

                u = best_u
                S.append(u)
                colored[u] = True
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1

        return compact_colors(colors)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Copy of degrees and adjacency for peeling
        degree = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []  # will hold vertices in removal order
        # We'll maintain a list of vertices for each degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if degree[v] < len(bins):
                bins[degree[v]].append(v)
        # Pointer to current min degree
        min_deg = 0

        for _ in range(n):
            # Find non-empty bin with smallest degree
            while min_deg < len(bins) and not bins[min_deg]:
                min_deg += 1
            if min_deg >= len(bins):
                break  # should not happen
            v = bins[min_deg].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    old_deg = degree[u]
                    degree[u] -= 1
                    if old_deg < len(bins):
                        bins[old_deg].remove(u)  # O(n) but n <= 100
                    if degree[u] < len(bins):
                        bins[degree[u]].append(u)
                    if degree[u] < min_deg:
                        min_deg = degree[u]

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
