                    # Since we don't track per neighbor color counts, we do a simple increment and hope it's close.
                    # For exactness in small n, we recalc sat for nb from scratch.
                    # Given n <= 100, we can recalc sat for all uncolored vertices each time, but that is O(n^2).
                    # Instead, we recalc sat only for neighbors of v.
                    # Recompute sat[nb] as number of distinct colors in its colored neighbors.
                    colored_nbs = [color[w] for w in neighbors[nb] if color[w] != -1]
                    sat[nb] = len(set(colored_nbs))
                    # update uncolored degree
                    uncolored_deg[nb] -= 1
        return color
    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = set()
            # step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S.add(v)
            # partition U and W
            U = uncolored - {v}
            W = set()
            # move neighbors of v from U to W
            for nb in list(U):
                if nb in neighbors[v]:
                    U.remove(nb)
                    W.add(nb)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = len([w for w in neighbors[u] if w in W])
                    deg_U = len([w for w in neighbors[u] if w in U])
                    if score > best_score or (score == best_score and deg_U < best_deg_U):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in list(U):
                    if nb in neighbors[u]:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for v in S:
                color[v] = c
            # next color class: uncolored becomes W
            uncolored = W
            c += 1
        return color
    # Smallest-Last ordering
    def smallest_last():
        # core decomposition to get removal order
        deg = [len(neighbors[i]) for i in range(n)]
        # bins for degree
        max_deg = max(deg) if n > 0 else 0
        bins = [set() for _ in range(max_deg + 1)]
        pos = [0] * n
        for i in range(n):
            d = deg[i]
            bins[d].add(i)
            pos[i] = d
        # current min degree
        min_deg = 0
        order = []
        # copy of degrees
        curr_deg = deg[:]
        # set of remaining vertices
        remaining = set(range(n))
        while remaining:
            # find non-empty bin with min degree
            while min_deg <= max_deg and not bins[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = bins[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for nb in neighbors[v]:
                if nb in remaining:
                    d = curr_deg[nb]
                    # remove from current bin
                    bins[d].remove(nb)
                    curr_deg[nb] -= 1
                    d_new = curr_deg[nb]
                    bins[d_new].add(nb)
                    pos[nb] = d_new
                    if d_new < min_deg:
                        min_deg = d_new
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in neighbors[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Kempe chain color reduction
    def kempe_reduce(color_in):
        color = color_in[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(color)
            if k <= 1:
                break
            # target smallest color class (color k-1)
            target = k - 1
            target_vertices = [v for v in range(n) if color[v] == target]
            if not target_vertices:
                # should not happen, but compact
                color = compact(color)
                continue
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used = 0
                for nb in neighbors[v]:
                    if color[nb] != -1:
                        used |= (1 << color[nb])
                for c in range(target):
                    if not (used & (1 << c)):
                        color[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # if v already recolored, break
                    if color[v] != target:
                        break
                    # BFS to find the (target, c)-Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for nb in neighbors[u]:
                            if not visited[nb] and (color[nb] == target or color[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # check if inverting the component would cause conflict
                    # inversion: target <-> c
                    # after inversion, vertices originally target become c, and vice versa
                    # we need to ensure that no neighbor of a vertex in component gets same color after inversion
                    valid = True
                    for u in component:
                        orig_color = color[u]
                        new_color = c if orig_color == target else target
                        for nb in neighbors[u]:
                            if color[nb] == new_color and (not (color[nb] == orig_color and orig_color in (target, c))):
                                # if neighbor has new_color and is not part of the swap (i.e., not in component or not changing to conflict)
                                # Actually, if neighbor is in component, it will also swap, so we need to check only neighbors not in component
                                if nb not in component:
                                    valid = False
                                    break
                        if not valid:
                            break
                    if valid:
                        # perform swap
                        for u in component:
                            if color[u] == target:
                                color[u] = c
                            elif color[u] == c:
                                color[u] = target
                        changed = True
                        break
            if changed:
                color = compact(color)
        return color
    # Generate candidates
    candidates = []
    # DSATUR
    try:
        col1 = dsatur()
        if is_valid(col1):
            candidates.append(col1)
    except Exception:
        pass
    # RLF
    try:
        col2 = rlf()
        if is_valid(col2):
            candidates.append(col2)
    except Exception:
        pass
    # Smallest-Last
    try:
        col3 = smallest_last()
        if is_valid(col3):
            candidates.append(col3)
    except Exception:
        pass
    # If no candidate, fallback to greedy
    if not candidates:
        color = [-1] * n
        for i in range(n):
            used = 0
            for nb in neighbors[i]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        candidates.append(color)
    # Apply Kempe reduction to each candidate and pick best
    best_color = None
    best_k = float('inf')
    for col in candidates:
        try:
            col_red = kempe_reduce(col)
            if is_valid(col_red):
                k = num_colors(col_red)
                if k < best_k:
                    best_k = k
                    best_color = col_red
        except Exception:
            continue
    if best_color is None:
        best_color = candidates[0]
    # Final validation and compaction
    if not is_valid(best_color):
        # last resort: greedy
        color = [-1] * n
        for i in range(n):
            used = 0
            for nb in neighbors[i]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        best_color = color
    best_color = compact(best_color)
    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build neighbor list and bitmask adjacency
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and len([w for w in neighbors[u] if w in uncolored]) > max_deg):
                    max_sat = sat[u]
                    max_deg = len([w for w in neighbors[u] if w in uncolored])
                    v = u
                elif sat[u] == max_sat and len([w for w in neighbors[u] if w in uncolored]) == max_deg:
                    if v == -1 or u < v:
                        v = u
            # assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        return color
    # RLF (Largest First Independent Set)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([w for w in neighbors[x] if w in uncolored]))
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            # W: vertices adjacent to at least one in S
            W = {u for u in uncolored if u != v and any(u in neighbors[w] for w in S)}
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                u_star = -1
                max_w_nei = -1
                min_u_deg = float('inf')
                for u in U:
                    w_nei = len([w for w in neighbors[u] if w in W])
                    u_deg = len([w for w in neighbors[u] if w in U])
                    if w_nei > max_w_nei or (w_nei == max_w_nei and u_deg < min_u_deg):
                        max_w_nei = w_nei
                        min_u_deg = u_deg
                        u_star = u
                    elif w_nei == max_w_nei and u_deg == min_u_deg:
                        if u_star == -1 or u < u_star:
                            u_star = u
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star from U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for vertex in S:
                color[vertex] = c
                uncolored.remove(vertex)
            c += 1
        return color
    # Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # compute degeneracy ordering via repeated removal of min degree
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # current degrees in remaining subgraph
        curr_deg = degrees[:]
        # bucket queue for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[curr_deg[i]].append(i)
        # pointer to current min non-empty bucket
        min_ptr = 0
        while remaining:
            # find next non-empty bucket
            while min_ptr <= max_deg and not buckets[min_ptr]:
                min_ptr += 1
            if min_ptr > max_deg:
                break
            v = buckets[min_ptr].pop()
            if v not in remaining:
                continue
            # remove v
            remaining.remove(v)
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # remove u from its current bucket
                    old_deg = curr_deg[u]
                    buckets[old_deg].remove(u)
                    curr_deg[u] -= 1
                    new_deg = curr_deg[u]
                    if new_deg >= len(buckets):
                        buckets.extend([[] for _ in range(new_deg - len(buckets) + 1)])
                    buckets[new_deg].append(u)
                    if new_deg < min_ptr:
                        min_ptr = new_deg
        # color in reverse order
        return greedy_color(order[::-1])
    # Kempe chain elimination
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        k = num_colors(coloring)
        # try to eliminate colors from highest down
        changed = True
        while changed and k > 0:
            changed = False
            # target smallest color class (highest index)
            target = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target]
            if not target_vertices:
                # already empty, compact
                for v in range(n):
                    if coloring[v] > target:
                        coloring[v] -= 1
                k -= 1
                changed = True
                continue
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # BFS to find Kempe chain of colors {target, c} containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target or coloring[node] == c:
                            component.add(node)
                            for nb in neighbors[node]:
                                if nb not in visited and (coloring[nb] == target or coloring[nb] == c):
                                    stack.append(nb)
                    # check if inverting this component would free color c for v
                    # after inversion, v would get color c (since it was target)
                    # we need to ensure no neighbor of v gets color c from inversion
                    conflict = False
                    for nb in neighbors[v]:
                        if nb in component:
                            # nb would flip from target to c or c to target
                            orig = coloring[nb]
                            newc = c if orig == target else target
                            if newc == c:
                                conflict = True
                                break
                        else:
                            if coloring[nb] == c:
                                conflict = True
                                break
                    if not conflict:
                        # perform swap
                        for node in component:
                            if coloring[node] == target:
                                coloring[node] = c
                            else:
                                coloring[node] = target
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # compact colors if needed
                # recompute k and reindex
                k = num_colors(coloring)
                # create mapping from old colors to new consecutive colors
                unique_colors = sorted(set(coloring))
                mapping = {old: new for new, old in enumerate(unique_colors)}
                for v in range(n):
                    coloring[v] = mapping[coloring[v]]
        return coloring
    # Generate candidates
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        candidates.append(col_sl)
    except Exception:
        pass
    # Fallback: greedy by natural order
    try:
        col_greedy = greedy_color(list(range(n)))
        candidates.append(col_greedy)
    except Exception:
        pass
    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        if col is None:
            continue
        k = num_colors(col)
        if k < best_k:
            best_k = k
            best = col
    if best is None:
        best = [0] * n
    # Apply Kempe reduction to best candidate
    best = kempe_reduce(best)
    # Final validation and compacting
    # Ensure proper coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best[u] == best[v]:
                # Should not happen, but fallback to greedy
                best = greedy_color(list(range(n)))
                break
        else:
            continue
        break
    # Compact colors
    if best:
        unique_colors = sorted(set(best))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        for v in range(n):
            best[v] = mapping[best[v]]
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs adjacency list
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        neighbors = [ [j for j, val in enumerate(row) if val] for row in adj ]
    else:
        # Adjacency list (ensure each element is a list)
        neighbors = [list(lst) for lst in adj]
    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to list if needed
    def ensure_list(coloring):
        return list(coloring)

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bitmask for fast distinct count
        neighbor_colors = [0] * n
        uncolored = set(range(n))
        # initial degrees for tie-breaking
        degrees = [len(neighbors[u]) for u in range(n)]
        while uncolored:
            # select vertex with max saturation, break ties by degree, then random
            v = max(uncolored, key=lambda x: (saturation[x], degrees[x], random.random()))
            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and neighbor colors for uncolored neighbors
            for u in neighbors[v]:
                if color[u] == -1:
                    # if this color is new in u's neighbor colors
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return color

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            # start with vertex of max degree in uncolored subgraph
            # compute degree in uncolored subgraph
            deg_in_uncolored = {}
            for v in uncolored:
                # count neighbors that are also uncolored
                cnt = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        cnt += 1
                deg_in_uncolored[v] = cnt
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: (deg_in_uncolored[x], random.random()))
            independent_set = {v}
            # eligible: vertices not adjacent to any in independent_set
            ineligible = set()
            for u in neighbors[v]:
                if u in uncolored:
                    ineligible.add(u)
            eligible = uncolored - {v} - ineligible
            # while there are eligible vertices
            while eligible:
                # select u in eligible with max neighbors in ineligible
                # tie-break by min degree in eligible subgraph
                best_u = None
                best_score = -1
                best_deg = None
                for u in eligible:
                    # score: number of neighbors in ineligible
                    score = 0
                    for w in neighbors[u]:
                        if w in ineligible:
                            score += 1
                    # degree in eligible subgraph
                    deg_eligible = 0
                    for w in neighbors[u]:
                        if w in eligible:
                            deg_eligible += 1
                    if score > best_score or (score == best_score and (best_deg is None or deg_eligible < best_deg)):
                        best_score = score
                        best_deg = deg_eligible
                        best_u = u
                u = best_u
                independent_set.add(u)
                eligible.remove(u)
                # move neighbors of u from eligible to ineligible
                for w in neighbors[u]:
                    if w in eligible:
                        eligible.remove(w)
                        ineligible.add(w)
            # assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
