    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring given an ordering
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    best_colors = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # saturation degree (distinct neighbor colors)
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = max(uncolored, key=lambda x: (saturated[x], len([y for y in adj_list[x] if y in uncolored]), random.random()))
            # Find smallest available color
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # Recompute saturation: count distinct colors in neighbors
                    mask = 0
                    for w in adj_list[u]:
                        if colors[w] != -1:
                            mask |= (1 << colors[w])
                    saturated[u] = mask.bit_count()
        return colors

    # 2. RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set S for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.add(v)
            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = {u for u in uncolored if u not in S and all(u not in adj_list[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([y for y in adj_list[x] if y in W]), -len([y for y in adj_list[x] if y in U]), random.random()))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to S
            for v in S:
                colors[v] = color
            uncolored -= S
            color += 1
        return colors

    # 3. Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len([y for y in adj_list[x] if y in remaining]) for x in range(n)]
        # Use bucket sort for efficiency
        max_deg = n - 1
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = len([y for y in adj_list[v] if y in remaining])
            buckets[d].append(v)
        # Pointer to current min degree
        min_d = 0
        while remaining:
            # Find non-empty bucket
            while min_d <= max_deg and not buckets[min_d]:
                min_d += 1
            if min_d > max_deg:
                break
            v = buckets[min_d].pop()
            if v not in remaining:
                continue
            remaining.remove(v)
            order.append(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    old_d = len([y for y in adj_list[u] if y in remaining])
                    new_d = old_d - 1
                    # Remove u from old bucket
                    if u in buckets[old_d]:
                        buckets[old_d].remove(u)
                    buckets[new_d].append(u)
                    # Update min_d if needed
                    if new_d < min_d:
                        min_d = new_d
        # Color in reverse order
        return greedy_color(reversed(order))

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if all(col[u] != col[v] for u in range(n) for v in adj_list[u]):
                candidates.append(col)
        except Exception:
            continue

    if not candidates:
        # Fallback: simple greedy by vertex index
        best_colors = greedy_color(list(range(n)))
    else:
        best_colors = min(candidates, key=num_colors)
        best_k = num_colors(best_colors)

    # 4. Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # Work on a copy
        cur_colors = colors[:]
        improved = True
        while improved and k > 1:
            improved = False
            # Target the smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if cur_colors[v] == target_color]
            if not target_vertices:
                # Already compacted
                k -= 1
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if cur_colors[u] != -1:
                        used |= (1 << cur_colors[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Move v to color c
                        cur_colors[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {c, target_color}
                    if cur_colors[v] != target_color:
                        continue
                    # BFS to get component
                    from collections import deque
                    comp = set()
                    queue = deque([v])
                    comp.add(v)
                    while queue:
                        x = queue.popleft()
                        for y in adj_list[x]:
                            if cur_colors[y] in (c, target_color) and y not in comp:
                                comp.add(y)
                                queue.append(y)
                    # Check if swapping c and target_color in comp is valid and frees target_color for v
                    # After swap, v would become c, so we need that no neighbor of v is c (outside comp) or becomes c via swap?
                    # Actually, we need that after swap, v's color c does not conflict.
                    # Since we only swap within comp, and neighbors of v either:
                    #   - not in {c, target_color}: unchanged
                    #   - in comp: will swap, so if neighbor u has color c, after swap it becomes target_color
                    #   - not in comp: unchanged
                    # So v will be c after swap. Conflict if any neighbor of v has color c after swap.
                    # Neighbors of v that are in comp and had color c become target_color -> safe
                    # Neighbors of v not in comp and had color c -> conflict
                    # Neighbors of v that had target_color become c -> if not in comp, they become c and are neighbor -> conflict
                    # Actually, simpler: after swap, for any neighbor u of v:
                    #   if u in comp: new color = c if old was target_color, else target_color if old was c
                    #   if u not in comp: color unchanged
                    # So v becomes c. We need that no neighbor u of v has color c after swap.
                    conflict = False
                    for u in adj_list[v]:
                        if u in comp:
                            # u's color flips
                            if cur_colors[u] == target_color:
                                # becomes c
                                conflict = True
                                break
                            # else was c, becomes target_color -> safe
                        else:
                            if cur_colors[u] == c:
                                conflict = True
                                break
                    if not conflict:
                        # Perform swap
                        for u in comp:
                            if cur_colors[u] == c:
                                cur_colors[u] = target_color
                            elif cur_colors[u] == target_color:
                                cur_colors[u] = c
                        improved = True
                        break
                if improved:
                    break
            # If we improved, check if target color class is now empty
            if improved:
                # Recompute k
                k = num_colors(cur_colors)
                # Compact colors if needed (not strictly necessary for validity, but for minimality)
                # We'll compact at the end
            else:
                # Could not eliminate target color, break
                break
        # Compact colors to 0..k-1
        unique_colors = sorted(set(cur_colors))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        compacted = [mapping[c] for c in cur_colors]
        return compacted

    # Apply Kempe reduction
    final_colors = kempe_reduce(best_colors)
    # Final validation (should always pass)
    for u in range(n):
        for v in adj_list[u]:
            if final_colors[u] == final_colors[v]:
                # Fallback to best_colors if something went wrong
                return best_colors
    return final_colors

