        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue  # Skip invalid indices
                adj_list[i].append(j)
                bit_adj[i] |= (1 << j)

    # Handle single vertex
    if n == 1:
        return [0]

