    # Current degrees and vertex status
    degree = [len(adj_list[i]) for i in range(n)]
    removed = [False] * n
    order = []  # Removal order (will color in reverse)

    # Use buckets for efficiency: degree -> list of vertices
    max_deg = max(degree) if n > 0 else 0
    buckets = [[] for _ in range(max_deg + 1)]
    for v in range(n):
        d = degree[v]
        if d <= max_deg:
            buckets[d].append(v)

    # Pointer to current minimum non-empty bucket
    min_deg = 0

    for _ in range(n):
        # Find next vertex to remove: min degree in current graph
        while min_deg <= max_deg and not buckets[min_deg]:
            min_deg += 1
        if min_deg > max_deg:
            break  # Should not happen if n>0
        v = buckets[min_deg].pop()
        while removed[v]:
            if not buckets[min_deg]:
                min_deg += 1
                while min_deg <= max_deg and not buckets[min_deg]:
                    min_deg += 1
                if min_deg > max_deg:
                    break
                v = buckets[min_deg].pop()
            else:
                v = buckets[min_deg].pop()
        if removed[v]:
            # This should not occur if logic is correct, but fallback
            for i in range(n):
                if not removed[i]:
                    v = i
                    break
        removed[v] = True
        order.append(v)
        # Update degrees of neighbors
        for u in adj_list[v]:
            if not removed[u]:
                d_u = degree[u]
                # Remove u from its current bucket
                if d_u < len(buckets) and u in buckets[d_u]:
                    buckets[d_u].remove(u)
                degree[u] -= 1
                d_new = degree[u]
                if d_new < len(buckets):
                    buckets[d_new].append(u)
                else:
                    # Extend buckets if necessary (should not happen as degree decreases)
                    while len(buckets) <= d_new:
                        buckets.append([])
                    buckets[d_new].append(u)
                # Update min_deg if needed
                if d_new < min_deg:
                    min_deg = d_new

    # Color in reverse removal order with First-Fit
    color = [-1] * n
    for v in reversed(order):
        # Determine colors used by already colored neighbors
        neighbor_colors = 0
        for u in adj_list[v]:
            c = color[u]
            if c != -1:
                neighbor_colors |= (1 << c)
        # Find smallest non-negative color not in neighbor_colors
        c = 0
        while neighbor_colors & (1 << c):
            c += 1
        color[v] = c

    # Compact colors to ensure consecutive 0..k-1
    # Map existing colors to a compact set
    unique_colors = sorted(set(color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    return color

