    is_matrix = False
    if len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neigh) for neigh in adj]

    # Build bitmask representation
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: k-core decomposition ordering (innermost to outermost)
    def k_core_order():
        deg = [len(adj_list[i]) for i in range(n)]
        order = []
        removed = [False] * n
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].append(i)
        # Process from smallest degree
        for d in range(max_deg + 1):
            while buckets[d]:
                v = buckets[d].pop()
                if removed[v]:
                    continue
                removed[v] = True
                order.append(v)
                for u in adj_list[v]:
                    if not removed[u]:
                        if deg[u] > d:
                            deg[u] -= 1
                            buckets[deg[u]].append(u)
        # Reverse to get inner to outer
        return order[::-1]

    # Strategy 2: DSATUR with bitmask
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree as bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                # saturation degree: number of distinct colors in neighbors
                sat_deg = sat[v].bit_count()
                # degree in uncolored subgraph
                deg_uncol = (bit_adj[v] & sum((1 << u) for u in uncolored)).bit_count()
                if sat_deg > best_sat or (sat_deg == best_sat and deg_uncol > best_deg) or \
                   (sat_deg == best_sat and deg_uncol == best_deg and v > best_v):
                    best_sat = sat_deg
                    best_deg = deg_uncol
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # Strategy 3: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # degree in uncolored subgraph
            deg_uncol = {}
            for v in uncolored:
                deg_uncol[v] = (bit_adj[v] & sum((1 << u) for u in uncolored)).bit_count()
            # start with vertex of max degree
            v = max(uncolored, key=lambda x: deg_uncol[x])
            independent_set = [v]
            to_remove = {v}
            # eligible: not adjacent to any in independent_set
            eligible = uncolored - {v} - set()
            for u in adj_list[v]:
                if u in eligible:
                    eligible.remove(u)
            # ineligible: adjacent to independent_set
            ineligible = set()
            for u in adj_list[v]:
                if u in uncolored and u not in independent_set:
                    ineligible.add(u)
            while eligible:
                # select u in eligible with max neighbors in ineligible
                best_u = -1
                best_score = -1
                best_deg_eligible = -1
                for u in eligible:
                    score = (bit_adj[u] & sum((1 << w) for w in ineligible)).bit_count()
                    deg_in_eligible = (bit_adj[u] & sum((1 << w) for w in eligible)).bit_count()
                    if score > best_score or (score == best_score and deg_in_eligible < best_deg_eligible) or \
                       (score == best_score and deg_in_eligible == best_deg_eligible and u > best_u):
                        best_score = score
                        best_deg_eligible = deg_in_eligible
                        best_u = u
                u = best_u
                independent_set.append(u)
                to_remove.add(u)
                eligible.remove(u)
                # move neighbors of u from eligible to ineligible
                for w in adj_list[u]:
                    if w in eligible:
                        eligible.remove(w)
                        ineligible.add(w)
            # assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Generate candidate colorings
    candidates = []

    # 1. k-core ordering
    order_core = k_core_order()
    color_core = greedy_color(order_core)
    if is_valid(color_core):
        candidates.append(color_core)

    # 2. DSATUR
    color_ds = dsatur()
    if is_valid(color_ds):
        candidates.append(color_ds)

    # 3. RLF
    color_rlf = rlf()
    if is_valid(color_rlf):
        candidates.append(color_rlf)

    # 4. Welsh-Powell (degree descending)
    order_wp = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
    color_wp = greedy_color(order_wp)
    if is_valid(color_wp):
        candidates.append(color_wp)

    # 5. Smallest-Last ordering (reverse of min-degree peeling)
    def smallest_last():
        deg = [len(adj_list[i]) for i in range(n)]
        order = []
        removed = [False] * n
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].append(i)
        for d in range(max_deg + 1):
            while buckets[d]:
                v = buckets[d].pop()
                if removed[v]:
                    continue
                removed[v] = True
                order.append(v)
                for u in adj_list[v]:
                    if not removed[u]:
                        if deg[u] > d:
                            deg[u] -= 1
                            buckets[deg[u]].append(u)
        return order  # peeling order, color in reverse
    order_sl = smallest_last()
    color_sl = greedy_color(order_sl[::-1])
    if is_valid(color_sl):
        candidates.append(color_sl)

    # Select best candidate (fewest colors)
    if not candidates:
        # fallback: greedy on natural order
        best_color = greedy_color(list(range(n)))
    else:
        best_color = min(candidates, key=num_colors)

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_color[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_color[i] = unique_colors[c]

    return best_color

