    is_matrix = len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row)

    # Build adjacency list and bitmask representation
    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = adj
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    def greedy_coloring(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    def dsatur():
        colors = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: (sat[x], len([u for u in neighbors[x] if u in uncolored]), -x))
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        return colors

    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            S = {v}
            U = {u for u in uncolored if u != v and v not in neighbors[u]}
            W = {u for u in uncolored if u != v and v in neighbors[u]}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = max(U, key=lambda x: (len([w for w in neighbors[x] if w in W]), -len([u2 for u2 in neighbors[x] if u2 in U]), -x))
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for vertex in S:
                colors[vertex] = color
                uncolored.remove(vertex)
            color += 1
        return colors

    def smallest_last():
        order = []
        remaining = set(range(n))
        degrees = [len(neighbors[i]) for i in range(n)]
        while remaining:
            v = min(remaining, key=lambda x: degrees[x])
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    degrees[u] -= 1
        return greedy_coloring(order[::-1])

    def kempe_reduce(colors):
        max_color = max(colors) if colors else -1
        if max_color < 0:
            return colors
        # Try to eliminate color classes from highest to lowest
        for target_color in range(max_color, -1, -1):
            vertices = [i for i, c in enumerate(colors) if c == target_color]
            if not vertices:
                continue
            eliminated = True
            new_colors = colors[:]
            for v in vertices:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    if new_colors[u] != -1:
                        used |= (1 << new_colors[u])
                found = False
                for c in range(target_color):
                    if not (used & (1 << c)):
                        new_colors[v] = c
                        found = True
                        break
                if found:
                    continue
                # Try Kempe chain swap with each lower color
                swapped = False
                for c in range(target_color):
                    # Find component of v in (target_color, c) subgraph
                    stack = [v]
                    comp = set()
                    while stack:
                        node = stack.pop()
                        if node in comp:
                            continue
                        comp.add(node)
                        for u in neighbors[node]:
                            if new_colors[u] in (target_color, c) and u not in comp:
                                stack.append(u)
                    # Check if any neighbor of v with color c is NOT in this component
                    has_external = False
                    for u in neighbors[v]:
                        if new_colors[u] == c and u not in comp:
                            has_external = True
                            break
                    if has_external:
                        # Swap colors in component
                        for node in comp:
                            if new_colors[node] == target_color:
                                new_colors[node] = c
                            elif new_colors[node] == c:
                                new_colors[node] = target_color
                        swapped = True
                        break
                if not swapped:
                    eliminated = False
                    break
            if eliminated:
                # Compact colors: remap to 0..k-1
                color_map = {}
                next_color = 0
                for i in range(n):
                    c = new_colors[i]
                    if c not in color_map:
                        color_map[c] = next_color
                        next_color += 1
                    new_colors[i] = color_map[c]
                colors = new_colors
                # Restart reduction from new max color
                return kempe_reduce(colors)
        return colors

    # Generate candidates
    candidates = []
    # DSATUR
    candidates.append(dsatur())
    # RLF
    candidates.append(rlf())
    # Smallest-Last
    candidates.append(smallest_last())
    # BFS-based bipartite attempt
    try:
        color_bfs = [-1] * n
        from collections import deque
        for i in range(n):
            if color_bfs[i] == -1:
                color_bfs[i] = 0
                q = deque([i])
                while q:
                    u = q.popleft()
                    for v in neighbors[u]:
                        if color_bfs[v] == -1:
                            color_bfs[v] = color_bfs[u] ^ 1
                            q.append(v)
                        elif color_bfs[v] == color_bfs[u]:
                            raise ValueError("Not bipartite")
        candidates.append(color_bfs)
    except:
        pass

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: len(set(x)))
    # Apply Kempe chain reduction
    best = kempe_reduce(best)
    # Final validation and compaction
    used_colors = set(best)
    color_map = {c: i for i, c in enumerate(sorted(used_colors))]
    best = [color_map[c] for c in best]
    return best

