            U = {u for u in uncolored if not any(u in neighbors[w] for w in S)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W
                u = max(U, key=lambda x: len([w for w in neighbors[x] if w in W]))
                # Tie-break: min degree in U
                u = min(U, key=lambda x: (len([w for w in neighbors[x] if w in W]), len([w for w in neighbors[x] if w in U])))
                color_class.append(u)
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in list(U):
                    if w in neighbors[u]:
                        U.remove(w)
                        W.add(w)
            order.extend(color_class)
            uncolored = W
        return order

    candidates.append(rlf_order())

    # 3. Smallest-Last (degeneracy ordering)
    def sl_order():
        # Copy of degrees
        degree = [len(neighbors[i]) for i in range(n)]
        # Set of unremoved vertices
        remaining = set(range(n))
        order = []
        # Buckets for vertices by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            if degree[v] < len(buckets):
                buckets[degree[v]].add(v)
        # Peeling process
        for _ in range(n):
            # Find non-empty bucket with smallest index
            i = 0
            while i < len(buckets) and not buckets[i]:
                i += 1
            if i >= len(buckets):
                break  # should not happen
            v = buckets[i].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = degree[u]
                    degree[u] -= 1
                    if old_deg < len(buckets):
                        buckets[old_deg].discard(u)
                    if degree[u] < len(buckets):
                        buckets[degree[u]].add(u)
        return order[::-1]  # reverse for coloring order

    candidates.append(sl_order())

    # 4. Welsh-Powell: sort by degree descending
    def wp_order():
        return sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)

    candidates.append(wp_order())

    # Evaluate all candidate orderings and pick best coloring
    best_coloring = None
    best_colors = float('inf')
    for order in candidates:
        coloring = greedy_color(order)
        num_colors = max(coloring) + 1 if n > 0 else 0
        if num_colors < best_colors:
            best_colors = num_colors
            best_coloring = coloring

    # If no coloring found (should not happen), use first-fit on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_colors = max(best_coloring) + 1 if n > 0 else 0

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        k = max(coloring) + 1 if n > 0 else 0
        # Try to eliminate colors from highest to lowest
        for target_color in range(k-1, -1, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            changed = True
            # Try to recolor these vertices
            while changed and verts:
                changed = False
                v = verts.pop()
                # Try direct reassignment to a lower color
                neighbor_colors = {coloring[u] for u in neighbors[v]}
                for c in range(target_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue  # Skip if color c is already used by neighbor (would cause conflict if swapped)
                    # Find the Kempe chain component of v for colors (target_color, c)
                    # We'll do BFS to find the component containing v in the subgraph of colors target_color and c
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    component = set()
                    while queue:
                        x = queue.popleft()
                        if x in visited:
                            continue
                        visited.add(x)
                        if coloring[x] == target_color or coloring[x] == c:
                            component.add(x)
                            for y in neighbors[x]:
                                if coloring[y] == target_color or coloring[y] == c:
                                    if y not in visited:
                                        queue.append(y)
                    # Check if swapping this component is safe: no neighbor of any vertex in component has color c (outside component)
                    safe = True
                    for x in component:
                        for y in neighbors[x]:
                            if y not in component and coloring[y] == c:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # Perform swap: target_color <-> c in component
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            elif coloring[x] == c:
                                coloring[x] = target_color
                        changed = True
                        # After swap, v is now color c, so we can remove it from consideration
                        break
                if changed:
                    # Restart the loop for this target_color since we modified coloring
                    verts = [v for v in range(n) if coloring[v] == target_color]
        # Compact colors: remap to 0..k'-1
        # Get unique colors used
        used_colors = set(coloring)
        if not used_colors:
            return coloring
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        return [mapping[coloring[v]] for v in range(n)]

    best_coloring = kempe_reduce(best_coloring)

    # Final validation (optional, but safe)
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Conflict found, fallback to greedy on natural order (should be rare)
                return greedy_color(list(range(n)))

    return best_coloring

