def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        # Validate binary entries
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    for i in range(n):
        if is_matrix:
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
        else:
            for j in adj[i]:
                neighbors[i].add(j)
                bit_adj[i] |= (1 << j)

    # Ensure symmetry
    for i in range(n):
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].add(i)
                bit_adj[j] |= (1 << i)

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len(neighbors[x] & uncolored), x))
            # Compute used colors by colored neighbors
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            # Find smallest available color
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            S = {v}
            # Partition uncolored - {v} into U (not adj to S) and W (adj to S)
            U = uncolored - {v} - neighbors[v]
            W = neighbors[v] & uncolored
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len(neighbors[x] & W), -len(neighbors[x] & U), x))
                S.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                nbrs_in_U = neighbors[u] & U
                U -= nbrs_in_U
                W |= nbrs_in_U
            # Assign color c to S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].add(i)
        # Peel min degree vertex
        for _ in range(n):
            # Find non-empty bucket with smallest index
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # Remove u from current degree bucket
                    buckets[deg[u]].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].add(u)
            remaining.remove(v)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain swap for (a,b)
    def kempe_swap(color, a, b, v):
        # Find the Kempe chain component containing v for colors a and b
        stack = [v]
        visited = set()
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            for u in neighbors[node]:
                if color[u] == a or color[u] == b:
                    if u not in visited:
                        stack.append(u)
        # Swap colors a and b in the component
        for node in visited:
            if color[node] == a:
                color[node] = b
            elif color[node] == b:
                color[node] = a
        return color

    # Try to eliminate the smallest color class via Kempe chains
    def reduce_colors(color):
        # Map color to list of vertices
        color_classes = {}
        for v in range(n):
            c = color[v]
            color_classes.setdefault(c, []).append(v)
        if not color_classes:
            return color
        max_color = max(color_classes.keys())
        # Try to eliminate colors from highest downwards
        for target in range(max_color, 0, -1):
            if target not in color_classes:
                continue
            verts = color_classes[target][:]
            # Try to recolor each vertex in this class
            for v in verts:
                if color[v] != target:  # might have been recolored
                    continue
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    if color[u] != -1:
                        used |= (1 << color[u])
                for c in range(target):
                    if not (used & (1 << c)):
                        color[v] = c
                        break
                else:
                    # Try Kempe chains with each lower color
                    for c in range(target):
                        # Check if v is isolated in the (c, target) subgraph
                        has_target_neighbor = any(color[u] == target for u in neighbors[v])
                        has_c_neighbor = any(color[u] == c for u in neighbors[v])
                        if not (has_target_neighbor and has_c_neighbor):
                            # No edge to same color or to c? Actually, we need to check if swapping is safe
                            # Instead, attempt swap and see if it frees target for v
                            # Save current color
                            orig_color_v = color[v]
                            # Perform Kempe swap on (c, target) component containing v
                            color = kempe_swap(color, c, target, v)
                            # After swap, check if v can take color c (should now be free if chain didn't pull c)
                            # Actually, after swap, v's color becomes c if it was target, or target if it was c
                            # We want v to be color c, so if it was target, after swap it's c -> success
                            if color[v] == c:
                                break
                            else:
                                # Revert swap if not helpful
                                color = kempe_swap(color, c, target, v)
                    else:
                        continue  # no break in inner loop
                    break  # break outer loop if Kempe succeeded
                else:
                    # Failed to recolor v, cannot eliminate target color
                    return None
            # After processing all vertices, check if target color is eliminated
            if target not in [color[v] for v in range(n)]:
                # Compact colors: remap higher colors down
                mapping = {}
                next_c = 0
                for orig in sorted(set(color.values())):
                    if orig < target:
                        mapping[orig] = orig
                    elif orig > target:
                        mapping[orig] = next_c
                        next_c += 1
                # target color is removed
                new_color = [mapping[color[v]] for v in range(n)]
                return reduce_colors(new_color)  # recurse
        return color

    # Generate candidate colorings
    candidates = []
    try:
        candidates.append(dsatur())
    except:
        pass
    try:
        candidates.append(rlf())
    except:
        pass
    try:
        candidates.append(smallest_last())
    except:
        pass

    # Select best candidate (fewest colors)
    best = None
    best_colors = float('inf')
    for col in candidates:
        if len(set(col)) < best_colors:
            best_colors = len(set(col))
            best = col

    if best is None:
        # Fallback: greedy by degree
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best = color

    # Apply Kempe chain reduction
    reduced = reduce_colors(best[:])
    if reduced is not None and len(set(reduced)) < len(set(best)):
        best = reduced

    # Validate and ensure consecutive colors
    # Verify proper coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best[u] == best[v]:
                # Conflict, apply greedy fix
                order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
                color = [-1] * n
                for v in order:
                    used = 0
                    for u in neighbors[v]:
                        if color[u] != -1:
                            used |= (1 << color[u])
                    c = 0
                    while used & (1 << c):
                        c += 1
                    color[v] = c
                best = color
                break
        else:
            continue
        break

    # Remap to consecutive colors
    unique_colors = sorted(set(best))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best = [mapping[c] for c in best]

    return best

