    def is_valid_coloring(colors):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: normalize colors to 0..k-1
    def normalize_colors(colors):
        if not colors:
            return colors
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = colors[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            colors[i] = unique_colors[c]
        return colors

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
