            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    if saturation[u] > max_sat or (saturation[u] == max_sat and degree[u] > max_deg) or \
                       (saturation[u] == max_sat and degree[u] == max_deg and (v == -1 or random.random() < 0.5)):
                        max_sat = saturation[u]
                        max_deg = degree[u]
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by neighbors
            neighbor_colors = 0
            for u in neighbors[v]:
                if colored[u]:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True

            # Update saturation and degree for neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    # Update saturation: if color c is new in u's neighbors
