            # Assign smallest available color
            used = [False] * n
            for u in graph[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in graph[v]:
                if u in uncolored:
                    saturated[u].add(c)
        return coloring

    # Helper: RLF
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            independent_set = {v}
            to_check = {u for u in graph[v] if u in uncolored}
            ineligible = set()

            while to_check:
                # Select u in to_check with max neighbors in ineligible, tie-break by min degree in to_check
                best_u = -1
                best_ineligible_neighbors = -1
                best_deg_in_to_check = float('inf')
                for u in to_check:
                    ineligible_neighbors = sum(1 for w in graph[u] if w in ineligible)
                    deg_in_to_check = sum(1 for w in graph[u] if w in to_check)
                    if ineligible_neighbors > best_ineligible_neighbors or \
                       (ineligible_neighbors == best_ineligible_neighbors and deg_in_to_check < best_deg_in_to_check) or \
                       (ineligible_neighbors == best_ineligible_neighbors and deg_in_to_check == best_deg_in_to_check and u < best_u):
                        best_ineligible_neighbors = ineligible_neighbors
                        best_deg_in_to_check = deg_in_to_check
                        best_u = u
                u = best_u
                independent_set.add(u)
                to_check.remove(u)
                # Move neighbors of u from to_check to ineligible if they are in to_check
                for w in graph[u]:
                    if w in to_check:
                        to_check.remove(w)
                        ineligible.add(w)
            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1
        return coloring

    # Helper: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        degrees = [len(graph[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            if degrees[v] < len(buckets):
                buckets[degrees[v]].add(v)
        # Peel vertices
        for _ in range(n):
            # Find first non-empty bucket
            i = 0
            while i < len(buckets) and not buckets[i]:
                i += 1
            if i >= len(buckets):
                break
            v = buckets[i].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in graph[v]:
                if u in remaining:
                    old_deg = degrees[u]
                    buckets[old_deg].remove(u)
                    degrees[u] -= 1
                    new_deg = degrees[u]
                    if new_deg < len(buckets):
                        buckets[new_deg].add(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=num_colors)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                continue
            # Try to recolor each target vertex
            changed = True
            while changed and target_vertices:
                changed = False
                v = target_vertices.pop()
                # Try direct reassignment to a lower color
                used = [False] * k
                for u in graph[v]:
                    if coloring[u] < k:
                        used[coloring[u]] = True
                for c in range(target_color):
                    if not used[c]:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find (c, target_color)-Kempe chain containing v
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in graph[node]:
                            if not visited[u] and (coloring[u] == c or coloring[u] == target_color):
                                visited[u] = True
                                stack.append(u)
                    # Check if we can swap: no neighbor of component has color c (outside component)
                    can_swap = True
                    for node in component:
                        for u in graph[node]:
                            if not visited[u] and coloring[u] == c:
                                can_swap = False
                                break
                        if not can_swap:
                            break
                    if can_swap:
                        # Swap colors c and target_color in component
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            else:
                                coloring[node] = c
                        changed = True
                        break
            # If we couldn't eliminate this color class, break
            if not changed:
                break
        # Compact colors
        color_map = {}
        next_color = 0
        for v in range(n):
            if coloring[v] not in color_map:
                color_map[coloring[v]] = next_color
                next_color += 1
            coloring[v] = color_map[coloring[v]]
        return coloring

    best_coloring = kempe_reduce(best_coloring)

    # Final validation (should always hold)
    if not is_valid(best_coloring):
        # Fallback to greedy on original order
        best_coloring = greedy_color(list(range(n)))

    return best_coloring

import math
