def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True
    # Convert to adjacency list and bitmask
    if is_matrix:
        adj_list = [[v for v in range(n) if adj[u][v] == 1] for u in range(n)]
    else:
        adj_list = [list(neigh) for neigh in adj]
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    best_coloring = None
    best_k = float('inf')

    # Helper: greedy coloring given an order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = colors[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # 1. DSATUR
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = saturated[u].bit_count()
                deg = sum(1 for w in adj_list[u] if w in uncolored)
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and u > v):
                    max_sat = sat
                    max_deg = deg
                    v = u
            # assign smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update saturation of neighbors
            for w in adj_list[v]:
                if w in uncolored:
                    saturated[w] |= (1 << c)
        return colors

    # 2. RLF
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: sum(1 for w in adj_list[u] if w in uncolored))
            S.add(v)
            # U: vertices not adjacent to S, W: adjacent to S
            U = uncolored - {v}
            W = set()
            for w in list(U):
                if any(w in adj_list[s] for s in S):
                    U.remove(w)
                    W.add(w)
            # grow independent set
            while U:
                # select u in U with max neighbors in W
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u) or (nw == max_nw and deg_u == min_deg_u and u < u_star):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for w in list(U):
                    if w in adj_list[u_star]:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for u in S:
                colors[u] = color_idx
            uncolored -= S
            color_idx += 1
        return colors

    # 3. Smallest-Last (Matula-Beck) ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(adj_list[u]) for u in range(n)]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[deg[u]].append(u)
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for w in adj_list[v]:
                if w in remaining:
                    d = deg[w]
                    if d > 0:
                        deg[w] -= 1
                        buckets[d].append(w)
                        if d - 1 < ptr:
                            ptr = d - 1
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for w in adj_list[v]:
                c = colors[w]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Generate candidates
    candidates = []
    for func in (dsatur, rlf, smallest_last):
        try:
            col = func()
            # validate
            ok = True
            for u in range(n):
                for v in adj_list[u]:
                    if col[u] == col[v]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                k = max(col) + 1 if n > 0 else 0
                if k < best_k:
                    best_k = k
                    best_coloring = col[:]
        except Exception:
            continue

    # Fallback: simple greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
        best_coloring = greedy_color(order)
        best_k = max(best_coloring) + 1 if n > 0 else 0

    # Kempe chain color reduction
    def kempe_reduce(colors):
        nonlocal best_k, best_coloring
        # make copy to work on
        col = colors[:]
        changed = True
        while changed and max(col) + 1 > 1:
            changed = False
            k = max(col) + 1
            # target smallest color class (highest index)
            target_color = k - 1
            vertices = [v for v in range(n) if col[v] == target_color]
            if not vertices:
                # should not happen
                break
            # try to recolor each vertex in target class
            for v in vertices:
                # try direct reassignment to a lower color
                used = 0
                for w in adj_list[v]:
                    c = col[w]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target_color):
                    if not (used & (1 << c)):
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c after possible direct reassignment, skip
                    if col[v] == c:
                        continue
                    # find Kempe chain component of colors {c, target_color} containing v
                    # BFS/DFS
                    stack = [v]
                    visited = set()
                    comp_color = {}
                    while stack:
                        u = stack.pop()
                        if u in visited:
                            continue
                        visited.add(u)
                        comp_color[u] = col[u]
                        for w in adj_list[u]:
                            if w not in visited and col[w] in (c, target_color):
                                stack.append(w)
                    # check if we can swap: after swap, no neighbor of v will have color c
                    conflict = False
                    for w in adj_list[v]:
                        if w in comp_color:
                            # after swap, color becomes c if it was target_color, else target_color
                            new_c = c if comp_color[w] == target_color else target_color
                            if new_c == c:
                                conflict = True
                                break
                    if not conflict:
                        # perform swap
                        for u in visited:
                            if col[u] == c:
                                col[u] = target_color
                            else:
                                col[u] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # compact colors: remap to 0..new_k-1
                # but we can just continue; at end we will compact
                pass
        # compact colors
        if n == 0:
            return []
        # map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = col[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            col[i] = unique_colors[c]
        return col

    best_coloring = kempe_reduce(best_coloring)
    # final validation and compact
    if n == 0:
        return []
    # verify
    for u in range(n):
        for v in adj_list[u]:
            if best_coloring[u] == best_coloring[v]:
                # fallback to greedy
                order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
                return greedy_color(order)
    # compact
    unique = {}
    nxt = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique:
            unique[c] = nxt
            nxt += 1
        best_coloring[i] = unique[c]
    return best_coloring

import math
