import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bit masks
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                adj_list[i].append(j)
                bit_adj[i] |= (1 << j)

    # Helper: validate coloring
    def is_valid_coloring(col):
        for u in range(n):
            for v in adj_list[u]:
                if col[u] == col[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(col):
        if not col:
            return 0
        return max(col) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(col):
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bit masks for fast distinct count
        neighbor_colors = [0] * n

        # initial vertex: highest degree
        degrees = [len(adj_list[i]) for i in range(n)]
        v = max(range(n), key=lambda i: degrees[i])
        color[v] = 0
        # update neighbors of v
        for u in adj_list[v]:
            neighbor_colors[u] |= (1 << 0)
            saturation[u] = neighbor_colors[u].bit_count()

        for _ in range(n - 1):
            # select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for i in range(n):
                if color[i] == -1:
                    sat = saturation[i]
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [i]
                    elif sat == max_sat:
                        candidates.append(i)
            # tie-break: degree in uncolored subgraph
            if len(candidates) > 1:
                # compute degree in uncolored subgraph
                uncolored_deg = [0] * n
                for i in candidates:
                    cnt = 0
                    for nb in adj_list[i]:
                        if color[nb] == -1:
                            cnt += 1
                    uncolored_deg[i] = cnt
                v = max(candidates, key=lambda i: uncolored_deg[i])
            else:
                v = candidates[0]

            # assign smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            # update neighbors
            for u in adj_list[v]:
                if color[u] == -1:  # only update uncolored neighbors
                    neighbor_colors[u] |= (1 << c)
                    saturation[u] = neighbor_colors[u].bit_count()
        return compact_colors(color)

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # build maximal independent set for current_color
            S = []
            # degree in current uncolored subgraph
            deg_uncolored = [0] * n
            for v in uncolored:
                cnt = 0
                for nb in adj_list[v]:
                    if nb in uncolored:
                        cnt += 1
                deg_uncolored[v] = cnt

            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S.append(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for nb in adj_list[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)

            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = None
                for u in U:
                    # count neighbors in W
                    score = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            score += 1
                    # tie-break: min degree in G[U]
                    deg_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to S
            for v in S:
                color[v] = current_color
            # remove S from uncolored
            uncolored -= set(S)
            current_color += 1
        return compact_colors(color)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        degree = [len(adj_list[i]) for i in range(n)]
        # bin vertices by degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            bins[d].append(v)
        # pointer to current non-empty bin
        pos = 0
        ordering = []
        # current degree copy
        curr_deg = degree[:]
        removed = [False] * n
        for _ in range(n):
            # find non-empty bin
            while pos <= max_deg and not bins[pos]:
                pos += 1
            if pos > max_deg:
                break  # should not happen
            v = bins[pos].pop()
            removed[v] = True
            ordering.append(v)
            # update neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    d = curr_deg[nb]
                    if d > 0:
                        # move nb from bin d to d-1
                        bins[d].remove(nb)
                        bins[d-1].append(nb)
                        curr_deg[nb] = d - 1
        # color in reverse order
        color = [-1] * n
        for v in reversed(ordering):
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return compact_colors(color)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # target the smallest color class (highest index)
            target_color = k - 1
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                # already compacted?
                coloring = compact_colors(coloring)
                k = num_colors(coloring)
                continue

            # Try to recolor each vertex in target class
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for nb in adj_list[v]:
                    if coloring[nb] != -1:
                        neighbor_colors.add(coloring[nb])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v can be recolored to c via Kempe chain (target_color, c)
                    # Build the Kempe chain component containing v in colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any neighbor of the component has color c (would cause conflict if swapped)
                    has_conflict = False
                    for node in component:
                        for nb in adj_list[node]:
                            if coloring[nb] == c and nb not in component:
                                has_conflict = True
                                break
                        if has_conflict:
                            break
                    if not has_conflict:
                        # swap colors in component
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:  # must be c
                                coloring[node] = target_color
                        improved = True
                        break
                if improved:
                    break

            if improved:
                # compact colors after potential elimination
                coloring = compact_colors(coloring)
                k = num_colors(coloring)

        return coloring

    # Run all heuristics with time budget
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # DSATUR
    if time.time() - start_time < 0.05:  # 50ms budget
        col = dsatur()
        if is_valid_coloring(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col

    # RLF
    if time.time() - start_time < 0.05:
        col = rlf()
        if is_valid_coloring(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col

    # Smallest-Last
    if time.time() - start_time < 0.05:
        col = smallest_last()
        if is_valid_coloring(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col

    # Fallback: greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = compact_colors(color)

    # Apply Kempe reduction if time permits
    if time.time() - start_time < 0.05 and best_coloring is not None:
        best_coloring = kempe_reduce(best_coloring)

    # Final validation and compact
    if not is_valid_coloring(best_coloring):
        # emergency fallback: greedy
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        color = [-1] * n
        for v in order:
