                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = compact_colors(color)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        # Adjacency list
        neighbors = [list(row) for row in adj]

    # Precompute bitmasks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    def is_valid_coloring(colors):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    def compact_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # degree for tie-breaking
        deg = [len(neighbors[i]) for i in range(n)]
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                # compute saturation: number of distinct colors in neighbors
                neighbor_colors = 0
                for w in neighbors[u]:
                    if colored[w]:
                        neighbor_colors |= (1 << colors[w])
                sat = neighbor_colors.bit_count()
                if sat > max_sat or (sat == max_sat and (deg[u] > max_deg or (deg[u] == max_deg and random.random() < 0.5))):
                    max_sat = sat
                    max_deg = deg[u]
                    v = u
            # assign smallest available color
            used = 0
            for w in neighbors[v]:
                if colored[w]:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
        return compact_colors(colors)

    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # build independent set for this color
            # step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda u: sum(1 for w in neighbors[u] if w in uncolored))
            independent_set = {v}
            # partition: U = not adj to any in S, W = adj to at least one in S
            U = {u for u in uncolored if u != v and all(w not in independent_set for w in neighbors[u])}
            W = {u for u in uncolored if u != v and u not in U}
            while U:
                # select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: sum(1 for w in neighbors[x] if w in W))
                # tie-break: min degree in G[U]
                u = min(U, key=lambda x: (sum(1 for w in neighbors[x] if w in U), random.random()))
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color
            for u in independent_set:
                colors[u] = color
                uncolored.remove(u)
            color += 1
        return compact_colors(colors)

    def smallest_last():
        # degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # we need dynamic degree updates
        deg = degrees[:]
        # bucket sort like
        buckets = [[] for _ in range(n)]
        for v in range(n):
            buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = buckets[deg[v]].index(v) if v in buckets[deg[v]] else -1
        min_deg = 0
        for _ in range(n):
            # find first non-empty bucket
            while min_deg < n and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break
            v = buckets[min_deg].pop()
            pos[v] = -1
            order.append(v)
            # update neighbors
            for w in neighbors[v]:
                if w not in remaining:
                    continue
                # remove w from its bucket
                d = deg[w]
                if pos[w] != -1 and pos[w] < len(buckets[d]):
                    buckets[d].pop(pos[w])
                deg[w] -= 1
                if deg[w] < 0:
                    deg[w] = 0
                buckets[deg[w]].append(w)
                pos[w] = len(buckets[deg[w]]) - 1
            remaining.remove(v)
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for w in neighbors[v]:
                if colors[w] != -1:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    def kempe_reduce(colors):
        if not colors:
            return colors
        # make sure colors are compact
        colors = compact_colors(colors)
        k = max(colors) + 1 if colors else 0
        improved = True
        while improved and k > 0:
            improved = False
            # find smallest color class
            classes = [[] for _ in range(k)]
            for v, c in enumerate(colors):
                classes[c].append(v)
            # find smallest non-empty class
            target = -1
            min_size = n + 1
            for c in range(k):
                if classes[c] and len(classes[c]) < min_size:
                    min_size = len(classes[c])
                    target = c
            if target == -1:
                break
            # try to recolor each vertex in target class
            for v in classes[target][:]:
                # try direct reassignment to a lower color
                neighbor_colors = 0
                for w in neighbors[v]:
                    if colors[w] != -1:
                        neighbor_colors |= (1 << colors[w])
                for c in range(target):
                    if not (neighbor_colors & (1 << c)):
                        # move v to color c
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    # re-compact and restart
                    colors = compact_colors(colors)
                    k = max(colors) + 1 if colors else 0
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # BFS to find Kempe chain of colors {target, c} containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in neighbors[u]:
                            if not visited[w] and (colors[w] == target or colors[w] == c):
                                visited[w] = True
                                queue.append(w)
                    # check if we can swap: after swap, no vertex in component gets color target from outside?
                    # Actually, swapping preserves validity. We want to free color target for v.
                    # After swap, v will have color c. We need to ensure that no neighbor of v has color c after swap?
                    # But swapping only changes colors within component: target<->c.
                    # So after swap, v has color c. Its neighbors: if neighbor has color c and is in component, it becomes target -> ok.
                    # If neighbor has color c and is not in component, then after swap it remains c -> conflict.
                    # So we need that no neighbor of v has color c and is outside the component.
                    conflict = False
                    for w in neighbors[v]:
                        if colors[w] == c and not visited[w]:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for u in component:
                            if colors[u] == target:
                                colors[u] = c
                            elif colors[u] == c:
                                colors[u] = target
                        colors = compact_colors(colors)
                        k = max(colors) + 1 if colors else 0
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # cannot eliminate target color, break
                break
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')
    for func in (dsatur, rlf, smallest_last):
        try:
            cols = func()
            if not is_valid_coloring(cols):
                continue
            k = max(cols) + 1 if cols else 0
            if k < best_k or (k == best_k and best_colors is None):
                best_k = k
                best_colors = cols
        except Exception:
            continue

    if best_colors is None:
        # fallback: greedy by degree order
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for w in neighbors[v]:
                if colors[w] != -1:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    # Apply Kempe reduction
    best_colors = kempe_reduce(best_colors)
    # Final validation and compact
    if not is_valid_coloring(best_colors):
        # last resort: greedy
        order = list(range(n))
        colors = [-1] * n
        for v in order:
            used = 0
            for w in neighbors[v]:
                if colors[w] != -1:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)
    return best_colors

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if adjacency matrix (square, binary entries)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        # Saturation: bitmask of colors used by colored neighbors
        sat = [0] * n
        # Degree in uncolored subgraph (initially full degree)
        deg_uncolored = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by deg_uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = deg_uncolored[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and v > best_v):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color

    # Helper: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = {u for u in uncolored if u != v and all(u not in adj_list[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in adj_list[w] for w in S)}
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_u = -1
                for u in U:
                    score = len([w for w in adj_list[u] if w in W])
                    deg_u = len([w for w in adj_list[u] if w in U])
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or (score == best_score and deg_u == best_deg_u and u < best_u):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last (Matula & Beck)
    def smallest_last():
        # Core decomposition to get ordering
        deg = [len(adj_list[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            d = deg[i]
            if d < len(buckets):
                buckets[d].append(i)
        # Pointer to current non-empty bucket
        pos = 0
        order = []
        # Copy of degrees for modification
        curr_deg = deg[:]
        removed = [False] * n
        for _ in range(n):
            # Find next non-empty bucket
            while pos < len(buckets) and not buckets[pos]:
                pos += 1
            if pos >= len(buckets):
                break
            v = buckets[pos].pop()
            while removed[v]:
                if not buckets[pos]:
                    break
                v = buckets[pos].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    if d < len(buckets):
                        buckets[d].remove(u)
                    curr_deg[u] -= 1
                    if curr_deg[u] < len(buckets):
                        buckets[curr_deg[u]].append(u)
                    if curr_deg[u] < pos:
                        pos = curr_deg[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        candidates.append(col_dsatur)
    except:
        pass
    # RLF
    try:
        col_rlf = rlf()
        candidates.append(col_rlf)
    except:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        candidates.append(col_sl)
    except:
        pass
    # Also try Welsh-Powell (degree descending)
    try:
        order_wp = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        col_wp = greedy_color(order_wp)
        candidates.append(col_wp)
    except:
        pass
    # Try random orders a few times
    for _ in range(5):
        try:
            order_rand = list(range(n))
            random.shuffle(order_rand)
            col_rand = greedy_color(order_rand)
            candidates.append(col_rand)
        except:
            pass

    # Select best candidate (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        # Validate coloring
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_coloring = col[:]

    # If no valid candidate (should not happen), fallback to greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = max(best_coloring) + 1 if n > 0 else 0

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find smallest color class (largest color index that is used)
            # We try to eliminate the highest color index present
            used_colors = set(col)
            if not used_colors:
                return col
            max_color = max(used_colors)
            # Try to eliminate color max_color
            # Get vertices with this color
            verts_max = [v for v in range(n) if col[v] == max_color]
            if not verts_max:
                # This color not used, should not happen
                return col
            # Try to recolor each vertex in verts_max to a lower color
            for v in verts_max:
                # Try direct reassignment to lowest possible color < max_color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if col[u] != -1:
                        used_by_neighbors |= (1 << col[u])
                # Try colors from 0 to max_color-1
                for c in range(max_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Can recolor v to c
                        col[v] = c
                        changed = True
                        break
                if changed:
                    # After recoloring, break to restart (color classes changed)
                    break
            if changed:
                continue
            # If no direct reassignment, try Kempe chains
            for v in verts_max:
                # For each lower color c
                for c in range(max_color):
                    # If v already has a neighbor of color c, swapping might not help directly
                    # But we check Kempe chain (c, max_color) starting from v
                    # Only consider if v is not adjacent to any vertex of color c? Actually, we can still try.
                    # Build the Kempe chain component containing v for colors (c, max_color)
                    from collections import deque
                    comp = set()
                    queue = deque([v])
                    comp.add(v)
                    while queue:
                        x = queue.popleft()
                        for y in adj_list[x]:
                            if col[y] == c or col[y] == max_color:
                                if y not in comp:
                                    comp.add(y)
                                    queue.append(y)
                    # Check if any neighbor of v in the component has color c? Actually, we want to see if we can swap
                    # After swap, v would get color c. We need to ensure no neighbor of v has color c after swap.
                    # Neighbors of v that are in the component and have color c will become max_color after swap.
                    # Neighbors of v that are in the component and have color max_color will become c after swap.
                    # So after swap, a neighbor of v will have color c if:
                    #   - it was in the component and had color max_color (becomes c) OR
                    #   - it was not in the component and had color c (remains c)
                    # To avoid conflict, we need that no neighbor of v ends up with color c.
                    # So we require:
                    #   - No neighbor of v outside the component has color c (they stay c)
                    #   - No neighbor of v inside the component has color max_color (they become c)
                    # Actually, simpler: after swap, for each neighbor u of v:
                    #   if col[u] == c: after swap, if u in comp -> becomes max_color; else remains c -> conflict if remains c
                    #   if col[u] == max_color: after swap, if u in comp -> becomes c; else remains max_color
                    # So conflict occurs if:
                    #   - exists neighbor u of v with col[u] == c and u not in comp (stays c)
                    #   - exists neighbor u of v with col[u] == max_color and u in comp (becomes c)
                    conflict = False
                    for u in adj_list[v]:
                        if col[u] == c and u not in comp:
                            conflict = True
                            break
                        if col[u] == max_color and u in comp:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: flip colors c <-> max_color in component
                        for x in comp:
                            if col[x] == c:
                                col[x] = max_color
                            elif col[x] == max_color:
                                col[x] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                continue
            # If we couldn't recolor any vertex of max_color, break
            break
        # Compact colors: map to 0..k-1
        # But we already use small colors, just renumber to be consecutive
        used = sorted(set(col))
        mapping = {old: new for new, old in enumerate(used)}
        col = [mapping[c] for c in col]
        return col

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduce(best_coloring)
    except:
        pass

    # Final validation and compacting (ensure 0..k-1)
    used = sorted(set(best_coloring))
    mapping = {old: new for new, old in enumerate(used)}
    best_coloring = [mapping[c] for c in best_coloring]

    # One last validation (should be valid)
    for u in range(n):
        for v in adj_list[u]:
            if best_coloring[u] == best_coloring[v]:
                # In case of error, fallback to greedy on natural order
                return greedy_color(list(range(n)))

    return best_coloring

