            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and degrees for neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
