                    if score > best_score or (score == best_score and deg_u < best_deg_u) or (score == best_score and deg_u == best_deg_u and u < best_u):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[v]) for v in range(n)]
        # we need updated degrees as we remove vertices
        deg = degrees[:]
        for _ in range(n):
            # find vertex with minimum degree in remaining
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            for nb in neighbors[v]:
                if nb in remaining:
                    deg[nb] -= 1
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Also try Welsh-Powell (sort by degree descending)
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    candidates.append(greedy_color(order_wp))

    # Try random orders a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    # Select the coloring with the fewest colors
    best_color = None
    best_k = float('inf')
    for col in candidates:
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_color = col

    # If no valid found (should not happen), fallback to greedy
    if best_color is None:
        best_color = greedy_color(list(range(n)))
        best_k = num_colors(best_color)

    # Kempe chain based color reduction
    def eliminate_color_class(col, target_color):
        """Try to eliminate target_color by recoloring its vertices.
        Returns new coloring if successful, else None."""
        # vertices with target_color
        verts = [v for v in range(n) if col[v] == target_color]
        if not verts:
            return col  # already empty
        # Try direct reassignment
        for v in verts:
            used = 0
            for nb in neighbors[v]:
                if col[nb] != target_color:  # only consider colors < target_color? but we allow any
                    used |= (1 << col[nb])
            # find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            if c != target_color:
                # recolor v to c
                new_col = col[:]
                new_col[v] = c
                # after recoloring, we may have duplicated colors, but we will compact later
                return new_col
        # Try Kempe chains for each pair (target_color, c) with c < target_color
        for c in range(target_color):
            # Try to swap along Kempe chains to free target_color for some vertex
            # We'll attempt to find a vertex v in target_color that can be swapped with c
            # via a Kempe chain that does not pull other target_color vertices into c
            # Build components of the subgraph induced by colors target_color and c
            visited = [False] * n
            for v in verts:
                if not visited[v]:
                    # BFS to get component
                        stack = [v]
                        visited[v] = True
                        comp = []
                        has_c = False
                        while stack:
                            node = stack.pop()
                            comp.append(node)
                            if col[node] == c:
                                has_c = True
                            for nb in neighbors[node]:
                                if not visited[nb] and (col[nb] == target_color or col[nb] == c):
                                    visited[nb] = True
                                    stack.append(nb)
                        # If component does not contain color c, we can swap
                        if not has_c:
                            new_col = col[:]
                            for node in comp:
                                if new_col[node] == target_color:
                                    new_col[node] = c
                                else:
                                    new_col[node] = target_color
                            return new_col
        return None

    # Iteratively try to reduce colors
    current = best_color[:]
    changed = True
    while changed:
        changed = False
        k = num_colors(current)
        # try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            new_col = eliminate_color_class(current, target_color)
            if new_col is not None:
                # compact colors: remap to 0..k'-1
                mapping = {}
                next_color = 0
                for v in range(n):
                    col_val = new_col[v]
                    if col_val not in mapping:
                        mapping[col_val] = next_color
                        next_color += 1
                current = [mapping[col_val] for col_val in new_col]
                changed = True
                break  # restart from highest color after a successful elimination
        # loop continues if changed

    # Final validation and ensure consecutive colors
    if not is_valid(current):
        # fallback to greedy
        current = greedy_color(list(range(n)))
    # remap to consecutive
    mapping = {}
    next_color = 0
    for v in range(n):
        col_val = current[v]
        if col_val not in mapping:
            mapping[col_val] = next_color
            next_color += 1
    current = [mapping[col_val] for col_val in current]

    return current

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if entries are 0/1 integers
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor bitmasks and neighbor lists
    bit_adj = [0] * n
    neighbors = [None] * n
    if is_matrix:
        for u in range(n):
            mask = 0
            for v in range(n):
                if adj[u][v]:
                    mask |= (1 << v)
            bit_adj[u] = mask
            neighbors[u] = [v for v in range(n) if adj[u][v]]
    else:
        for u in range(n):
            mask = 0
            for v in adj[u]:
                mask |= (1 << v)
            bit_adj[u] = mask
            neighbors[u] = adj[u][:]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[u]) for u in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, then max degree, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                d = uncolored_deg[u]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best = u
            u = best
            uncolored.remove(u)
            # assign smallest available color
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
            # update neighbors
            for v in neighbors[u]:
                if v in uncolored:
                    sat[v] |= (1 << c)
                    uncolored_deg[v] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # degree in uncolored subgraph
            deg_in_uncolored = {u: 0 for u in uncolored}
            for u in uncolored:
                for v in neighbors[u]:
                    if v in uncolored:
                        deg_in_uncolored[u] += 1
            # start with vertex of max degree
            v = max(uncolored, key=lambda u: deg_in_uncolored[u])
            S = {v}
            # U: vertices not adjacent to S
            U = {u for u in uncolored if u != v and v not in neighbors[u]}
            # W: vertices adjacent to S
            W = {u for u in uncolored if u != v and v in neighbors[u]}
            while U:
                # select u in U with max neighbors in W, then min degree in U
                best_u = -1
                best_score = -1
                best_deg = -1
                for u in U:
                    # count neighbors in W
                    w_count = 0
                    for w in neighbors[u]:
                        if w in W:
                            w_count += 1
                    # degree in U
                    u_deg = 0
                    for w in neighbors[u]:
                        if w in U:
                            u_deg += 1
                    if w_count > best_score or (w_count == best_score and u_deg < best_deg) or (w_count == best_score and u_deg == best_deg and random.random() < 0.5):
                        best_score = w_count
                        best_deg = u_deg
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(neighbors[u]) for u in range(n)]
        # buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            d = deg[u]
            if d <= max_deg:
                buckets[d].append(u)
        # pointer to current min degree
        min_deg = 0
        order = []
        # copy of degrees for updating
        curr_deg = deg[:]
        removed = [False] * n
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            u = buckets[min_deg].pop()
            removed[u] = True
            order.append(u)
            for v in neighbors[u]:
                if not removed[v]:
                    d = curr_deg[v]
                    if d <= max_deg:
                        # remove v from bucket d
                        if v in buckets[d]:
                            buckets[d].remove(v)
                    curr_deg[v] -= 1
                    d_new = curr_deg[v]
                    if d_new <= max_deg:
                        buckets[d_new].append(v)
                    if d_new < min_deg:
                        min_deg = d_new
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    start = time.time()
    # DSATUR
    if time.time() - start < 0.04:  # leave buffer
        col = dsatur()
        if is_valid(col):
            candidates.append(col)
    # RLF
    if time.time() - start < 0.04:
        col = rlf()
        if is_valid(col):
            candidates.append(col)
    # Smallest-Last
    if time.time() - start < 0.04:
        col = smallest_last()
        if is_valid(col):
            candidates.append(col)

    # If no candidate (should not happen), fallback to greedy by index
    if not candidates:
        col = greedy_color(list(range(n)))
        if is_valid(col):
            candidates.append(col)

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=count_colors)
    k = count_colors(best_coloring)

    # Iterative Kempe chain color reduction
    improved = True
    while improved and k > 1 and time.time() - start < 0.045:
        improved = False
        # Build color classes
        classes = [[] for _ in range(k)]
        for u in range(n):
            classes[best_coloring[u]].append(u)
        # Target smallest color class (last color)
        target = k - 1
        if not classes[target]:
            # should not happen, but skip
            break
        # Try to recolor each vertex in target class
        for v in classes[target][:]:
            # Try direct reassignment to a lower color
            used_by_neighbors = 0
            for u in neighbors[v]:
                c = best_coloring[u]
                if c != -1:
                    used_by_neighbors |= (1 << c)
            for c in range(target):
                if not (used_by_neighbors & (1 << c)):
                    # move v to color c
                    best_coloring[v] = c
                    classes[target].remove(v)
                    classes[c].append(v)
                    improved = True
                    break
            if improved:
                break
            # Try Kempe chains with each lower color
            for c in range(target):
                # BFS to find Kempe chain of colors c and target starting from v
                from collections import deque
                visited = [False] * n
                queue = deque([v])
                visited[v] = True
                component = []
                while queue:
                    u = queue.popleft()
                    component.append(u)
                    for w in neighbors[u]:
                        if not visited[w]:
                            col_w = best_coloring[w]
                            if col_w == c or col_w == target:
                                visited[w] = True
                                queue.append(w)
                # Check if any neighbor of v in the component has color c? Actually, we want to see if we can swap
                # After swap, v would get color c. Check if any neighbor of v has color c (which would cause conflict)
                conflict = False
                for w in neighbors[v]:
                    if best_coloring[w] == c:
                        # after swap, w would become target, so check if w is in component
                        if w in component:
                            conflict = True
                            break
                if not conflict:
                    # perform swap: c <-> target in component
                    for u in component:
                        if best_coloring[u] == c:
                            best_coloring[u] = target
                        elif best_coloring[u] == target:
                            best_coloring[u] = c
                    # update classes
                    classes[target].remove(v)
                    classes[c].append(v)
                    improved = True
                    break
            if improved:
                break
        if improved:
            # compact colors: reindex to 0..k-1
            # but we may have holes; rebuild mapping
            used_colors = set(best_coloring)
            mapping = {old: new for new, old in enumerate(sorted(used_colors))]
            best_coloring = [mapping[c] for c in best_coloring]
            k = len(used_colors)
        else:
            break

    # Final validation and compacting
    if not is_valid(best_coloring):
        # fallback to greedy
        best_coloring = greedy_color(list(range(n)))
    # ensure colors are 0..k-1 consecutive
    used = set(best_coloring)
    mapping = {old: new for new, old in enumerate(sorted(used))]
    best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = (len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for x in adj[0]))
    for i in range(n):
        if is_matrix:
            if len(adj[i]) != n or not all(isinstance(x, int) and x in (0, 1) for x in adj[i]):
                is_matrix = False
                break
        else:
            if not isinstance(adj[i], list):
                is_matrix = False
                break
            for v in adj[i]:
                if not isinstance(v, int) or v < 0 or v >= n:
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build bitmask adjacency and neighbor lists
    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)
                neighbors[i].append(j)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to compact 0..k-1
    def compact_coloring(coloring):
        if not coloring:
            return coloring
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighborhood
        saturation = [0] * n
        # colored neighbor masks for fast saturation update
        colored_mask = [0] * n
        # degree in uncolored subgraph (initially full degree)
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, then max uncolored degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v]
                deg = uncolored_deg[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # compute available colors: smallest not in neighborhood
            neighbor_colors = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # update saturation and uncolored degree for neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    # update saturation: if color c is new in neighborhood
                    if not (colored_mask[u] & (1 << c)):
                        colored_mask[u] |= (1 << c)
                        saturation[u] += 1
                    uncolored_deg[u] -= 1
        return coloring

    # RLF: Recursive Largest First (independent set extraction)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and not any((1 << u) & bit_adj[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    deg_U = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and deg_U < best_uncolored_deg):
                        best_score = score
                        best_uncolored_deg = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
        return coloring

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        ordering = []
        # copy of degrees
        deg = [len(neighbors[i]) for i in range(n)]
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current min non-empty bucket
        min_deg = 0
        for _ in range(n):
            # find min degree vertex in remaining
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            while v not in remaining:
                if not buckets[min_deg]:
                    min_deg += 1
                    while min_deg <= max_deg and not buckets[min_deg]:
                        min_deg += 1
                    if min_deg > max_deg:
                        break
                    v = buckets[min_deg].pop()
                else:
                    v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            ordering.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    # move u from bucket d to d-1
                    if d <= max_deg:
                        buckets[d].remove(u)  # O(n) but n <= 100, acceptable
                    if deg[u] >= 0:
                        if deg[u] >= len(buckets):
                            buckets.extend([[] for _ in range(deg[u] - len(buckets) + 1)])
                        buckets[deg[u]].append(u)
        # color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(ordering):
            neighbor_colors = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make coloring compact first
        coloring = compact_coloring(coloring[:])
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest down
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # already compacted?
                coloring = compact_coloring(coloring)
                k = num_colors(coloring)
                continue
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                neighbor_colors = 0
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        neighbor_colors |= (1 << coloring[u])
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        # move v to color c
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c from direct reassignment above, skip
                    if coloring[v] == c:
                        continue
                    # find the Kempe chain component of v in colors {c, target_color}
                    # BFS/DFS to get component
                    stack = [v]
                    visited = set()
                    comp_color = coloring[v]  # should be target_color
                    other_color = c
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == comp_color or coloring[node] == other_color:
                            component.add(node)
                            for nb in neighbors[node]:
                                if nb not in visited and (coloring[nb] == comp_color or coloring[nb] == other_color):
                                    stack.append(nb)
                    # check if any neighbor of component has color other_color
                    # if not, we can swap colors in component
                    has_other_color_neighbor = False
                    for node in component:
                        for nb in neighbors[node]:
                            if coloring[nb] == other_color and nb not in component:
                                has_other_color_neighbor = True
                                break
                        if has_other_color_neighbor:
                            break
                    if not has_other_color_neighbor:
                        # swap colors in component
                        for node in component:
                            if coloring[node] == comp_color:
                                coloring[node] = other_color
                            else:
                                coloring[node] = comp_color
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # compact colors
                coloring = compact_coloring(coloring)
                k = num_colors(coloring)
        return coloring

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                if coloring[j] != -1:
                    used |= (1 << coloring[j])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[i] = c
        candidates.append(coloring)

    # Apply Kempe reduction to each candidate and pick best
    best_coloring = None
    best_k = float('inf')
    for cand in candidates:
        reduced = kempe_reduce(cand[:])
        if not is_valid(reduced):
            # fallback: ensure validity by greedy repair
            reduced = [-1] * n
            for i in range(n):
                used = 0
                for j in neighbors[i]:
                    if reduced[j] != -1:
                        used |= (1 << reduced[j])
                c = 0
                while used & (1 << c):
                    c += 1
                reduced[i] = c
        reduced = compact_coloring(reduced)
        k = num_colors(reduced)
        if k < best_k or (k == best_k and best_coloring is None):
            best_k = k
            best_coloring = reduced

    return best_coloring

