def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True

    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Precompute bitmask adjacency and degrees
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    deg = [len(adj_list[u]) for u in range(n)]

    # Helper: count bits
    def popcount(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: normalize colors to 0..k-1
    def normalize_colors(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bitmask for efficiency
        neighbor_colors = [0] * n

        # Order by degree descending for initial tie-breaking in saturation
        order = list(range(n))
        order.sort(key=lambda x: (-deg[x], x))

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in order:
                if coloring[u] == -1:
                    sat_u = saturation[u]
                    deg_u = deg[u]
                    if sat_u > max_sat or (sat_u == max_sat and (deg_u > max_deg or (deg_u == max_deg and u < v))):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation and neighbor colors for uncolored neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:
                    # If this color is new in u's neighborhood
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1

        return normalize_colors(coloring)

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        colored = [False] * n
        color = 0

        while True:
            # Find uncolored vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    # count uncolored neighbors
                    d = 0
                    for w in adj_list[u]:
                        if not colored[w]:
                            d += 1
                    if d > max_deg:
                        max_deg = d
                        v = u
            if v == -1:
                break  # all colored

            # Build independent set for this color
            S = [v]
            colored[v] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if not colored[u]:
                    if v == u or (bit_adj[v] >> u) & 1:
                        W.add(u)
                    else:
                        U.add(u)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # tie-break: min degree in G[U]
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen

                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to all in S
            for u in S:
                coloring[u] = color
            color += 1

        return normalize_colors(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []  # removal order
        deg_copy = deg[:]  # current degree in remaining graph

        # Use bucket sort for efficiency
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg_copy[v]
            if d < len(buckets):
                buckets[d].append(v)
            else:
                # extend buckets if needed (should not happen as deg_copy <= max_deg)
                while len(buckets) <= d:
                    buckets.append([])
                buckets[d].append(v)

        # Pointer to current min non-empty bucket
        min_bucket = 0

        for _ in range(n):
            # Find first non-empty bucket
            while min_bucket < len(buckets) and not buckets[min_bucket]:
                min_bucket += 1
            if min_bucket >= len(buckets):
                break  # should not happen
            v = buckets[min_bucket].pop()
            if v not in remaining:
                # already removed, skip
                continue
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    old_d = deg_copy[u]
                    new_d = old_d - 1
                    deg_copy[u] = new_d
                    # remove u from old bucket
                    if old_d < len(buckets) and u in buckets[old_d]:
                        buckets[old_d].remove(u)
                    # add to new bucket
                    if new_d < len(buckets):
                        buckets[new_d].append(u)
                    else:
                        while len(buckets) <= new_d:
                            buckets.append([])
                        buckets[new_d].append(u)
                    # update min_bucket if needed
                    if new_d < min_bucket:
                        min_bucket = new_d

        # Color in reverse order using First-Fit
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return normalize_colors(coloring)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        improved = True
        # We'll try to reduce colors iteratively
        while improved:
            improved = False
            # Find the current number of colors
            max_color = max(current) if current else -1
            if max_color < 0:
                return current
            # Try to eliminate color classes from highest down
            for target_color in range(max_color, 0, -1):
                # Collect vertices with target_color
                vertices_target = [v for v in range(n) if current[v] == target_color]
                if not vertices_target:
                    # This color already eliminated, continue
                    continue
                # Try to recolor each vertex in this class
                eliminated = True
                for v in vertices_target:
                    # Try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in adj_list[v]:
                        if current[u] != -1:
                            neighbor_colors.add(current[u])
                    found = False
                    for c in range(target_color):  # only try lower colors
                        if c not in neighbor_colors:
                            # Direct reassignment possible
                            current[v] = c
                            found = True
                            break
                    if found:
                        continue
                    # Try Kempe chain swap with each lower color
                    swapped = False
                    for c in range(target_color):
                        # Skip if v already has color c (shouldn't happen as we checked direct)
                        if current[v] == c:
                            continue
                        # Check if v and any u of color c are in same Kempe chain
                        # We'll do BFS for (target_color, c) chain containing v
                        # But note: v has target_color, we want to see if we can swap a component
                        # that does NOT include any vertex of color c that is adjacent to v? 
                        # Standard: consider the Kempe chain of v in colors {target_color, c}
                        # If the chain does not contain any neighbor of v that has color c, then swapping
                        # will free color c for v.
                        # Actually: after swap, v becomes c. We need that no neighbor of v is c after swap.
                        # Before swap, neighbors of v that are c remain c, neighbors that are target_color become c.
                        # So we need that no neighbor of v is currently c (because they stay c) and 
                        # no neighbor of v that is target_color becomes c and conflicts? 
                        # Let's think: after swap, a neighbor u of v:
                        # - if current[u] == c: stays c -> conflict if v becomes c
                        # - if current[u] == target_color: becomes c -> conflict
                        # - else: unchanged
                        # So we need that no neighbor of v has color c OR target_color? 
                        # Actually, we need that no neighbor of v has color c (because they remain c) 
                        # and no neighbor of v has color target_color (because they become c).
                        # But wait: if a neighbor has color target_color, after swap it becomes c -> conflict.
                        # So we need that v has no neighbor with color c or target_color? 
                        # That can't be right because then we could have reassigned directly.
                        # Correct condition: In the Kempe chain (target_color, c) containing v, 
                        # if there is no vertex in the chain that is adjacent to v and has color c, 
                        # then swapping the chain will not introduce a conflict? 
                        # Actually, standard condition: we can swap the chain if it does not contain 
                        # any neighbor of v that has color c. Because after swap, those neighbors 
                        # would remain c (if they were c) or become c (if they were target_color) -> conflict.
                        # So we need that the chain does NOT contain any vertex that is a neighbor of v 
                        # and has color c. But note: v itself is in the chain and has target_color, not c.
                        # So we do BFS from v on the subgraph induced by vertices of color target_color or c.
                        # If we encounter a vertex u that is a neighbor of v and has color c, then we cannot swap.
                        # Otherwise, we can swap the entire chain.
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        safe = True
                        while queue:
                            x = queue.popleft()
                            # If x is a neighbor of v and has color c, then unsafe
                            if x != v and (bit_adj[v] >> x) & 1 and current[x] == c:
                                safe = False
                                break
                            for y in adj_list[x]:
                                if y not in visited and (current[y] == target_color or current[y] == c):
                                    visited.add(y)
                                    queue.append(y)
                        if safe:
                            # Perform swap: target_color <-> c in the component
                            for x in visited:
                                if current[x] == target_color:
                                    current[x] = c
                                elif current[x] == c:
                                    current[x] = target_color
                            swapped = True
                            break
                    if swapped:
                        continue
                    # If we couldn't recolor v, then we cannot eliminate this color class
                    eliminated = False
                    break
                if eliminated:
                    # Successfully eliminated target_color: remap colors > target_color down by 1
                    for v in range(n):
                        if current[v] > target_color:
                            current[v] -= 1
                    improved = True
                    break  # restart from highest color
            if not improved:
                # No color could be eliminated in this pass
                break
        return normalize_colors(current)

    # Run all heuristics
    start_time = time.time()
    best_coloring = None
    best_colors = float('inf')

    # DSATUR
    c1 = dsatur()
    if time.time() - start_time < 0.05:  # 50 ms budget
        k1 = len(set(c1))
        if k1 < best_colors:
            best_colors = k1
            best_coloring = c1

    # RLF
    c2 = rlf()
    if time.time() - start_time < 0.05:
        k2 = len(set(c2))
        if k2 < best_colors:
            best_colors = k2
            best_coloring = c2

    # Smallest-Last
    c3 = smallest_last()
    if time.time() - start_time < 0.05:
        k3 = len(set(c3))
        if k3 < best_colors:
            best_colors = k3
            best_coloring = c3

    # Apply Kempe reduction to the best so far
    if best_coloring is not None and time.time() - start_time < 0.05:
        c4 = kempe_reduce(best_coloring)
        if time.time() - start_time < 0.05:
            k4 = len(set(c4))
            if k4 < best_colors:
                best_colors = k4
                best_coloring = c4

    # Fallback: if nothing worked, use greedy by degree
    if best_coloring is None:
        order = list(range(n))
        order.sort(key=lambda x: (-deg[x], x))
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize_colors(coloring)

    # Final validation (should be valid, but ensure)
    if not is_valid_coloring(best_coloring):
        # Emergency fallback: assign each vertex a unique color
        best_coloring = list(range(n))

    return best_coloring

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build bitmask for each vertex: bitmask[u] has bit v set if (u,v) is an edge
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize_coloring(coloring):
        if not coloring:
            return coloring
        # Map used colors to 0,1,2,...
        used_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(used_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur():
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # For each color, we could track but we compute saturation on the fly
        # We'll maintain a list of uncolored vertices
        uncolored = set(range(n))

        # Precompute degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]

        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                # Compute saturation: distinct colors in neighbors
                neighbor_colors = set()
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        neighbor_colors.add(coloring[u])
                sat = len(neighbor_colors)
                if sat > best_sat or (sat == best_sat and (degrees[v] > best_deg or (degrees[v] == best_deg and v < best_v))):
                    best_sat = sat
                    best_deg = degrees[v]
                    best_v = v
            v = best_v
            # Find smallest color not used by neighbors
            used = [False] * (n + 1)  # n+1 to be safe
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # Recompute saturation for u: we could increment if c is new, but simpler to recompute
                    neighbor_colors = set()
                    for w in adj_list[u]:
                        if coloring[w] != -1:
                            neighbor_colors.add(coloring[w])
                    saturation[u] = len(neighbor_colors)
        return normalize_coloring(coloring)

    # RLF algorithm (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        # Precompute degrees in the full graph for initial selection
        degrees = [len(adj_list[i]) for i in range(n)]

        while uncolored:
            # Build the subgraph induced by uncolored: we need degrees in this subgraph
            # We'll compute degree in uncolored subgraph on the fly
            # Step 1: choose vertex with max degree in G[uncolored]
            # If multiple, choose the one with max degree (we already have full degree, but we need in subgraph)
            # We'll compute degree in uncolored subgraph for each vertex
            max_deg = -1
            candidates = []
            for v in uncolored:
                # degree in uncolored subgraph: count neighbors that are also uncolored
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    candidates = [v]
                elif deg == max_deg:
                    candidates.append(v)
            # Tie-break: choose the one with max full degree (or min index)
            v = max(candidates, key=lambda x: (degrees[x], -x))  # max degree, then min index? Actually we want max degree, then we can use min index to be deterministic but we'll use max degree then min index? 
            # Actually, the paper says: choose the vertex of maximum degree in G[R]. If tie, any. We'll use max degree then min index.
            # But we already selected by max deg in subgraph, now tie-break by full degree then min index.
            # However, we have candidates with same subgraph degree, so we break by full degree (descending) then min index.
            v = min(candidates, key=lambda x: (-degrees[x], x))  # Actually, we want max full degree, then min index? Let's do: sort by full degree descending, then index ascending.
            # Better: 
            v = None
            best_full_deg = -1
            for cand in candidates:
