            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                # Check if u is adjacent to any in S
                adjacent = False
                for s in S:
                    if u in adj_list[s] or s in adj_list[u]:  # since undirected, we can check one way
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty
            while U:
                # Select u in U that maximizes |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_in_U = -1  # for tie-break: min degree in G[U]
                for u in U:
                    # score = number of neighbors in W
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    # degree in G[U]: neighbors that are in U
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if score > best_score or (score == best_score and deg_in_U < best_deg_in_U):
                        best_score = score
                        best_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                # Add u to S
                S.add(u)
                U.remove(u)
                # Move neighbors of u that are in U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for vertex in S:
                coloring[vertex] = color
                uncolored.remove(vertex)
            color += 1
        return normalize_coloring(coloring)

    # Smallest-Last ordering (Matula & Beck) greedy
    def smallest_last():
        # Build ordering by repeatedly removing vertex of min degree
        # We'll work on a copy of the graph
        # degrees in current graph
        deg = [len(adj_list[i]) for i in range(n)]
        # We need to know the current adjacency as we remove vertices
        # We'll maintain a list of removed vertices and update degrees
        removed = [False] * n
        order = []  # will be the removal order (first removed first in list)
        # We'll use a list of sets for current neighbors? Instead, we can simulate.
        # For each vertex, we maintain its current degree and update when neighbors are removed.
        # We'll use a bucket queue for efficiency, but n<=100 so we can do linear scan.
        for _ in range(n):
            # Find vertex with min degree among non-removed
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break  # should not happen
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    deg[u] -= 1
        # Now color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if coloring[u] != -1:
