    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # If no candidate (should not happen), fall back to simple greedy
    if not candidates:
        col = greedy_color(list(range(n)))
        if is_valid(col):
            candidates.append(col)
        else:
            # Ultimate fallback: assign each vertex a unique color
            return list(range(n))

    # Select the candidate with the fewest colors
    best = min(candidates, key=count_colors)

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # Get vertices with target_color
        verts = [v for v in range(n) if coloring[v] == target_color]
        if not verts:
            return coloring, False  # already empty
        # Try to recolor each vertex
        for v in verts:
            # Try direct reassignment to a lower color
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            for c in range(target_color):  # only try colors < target_color
                if not (used & (1 << c)):
                    # Move v to color c
                    coloring[v] = c
                    break
            else:
                # Direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    # Check if v can be swapped via (target_color, c) Kempe chain
                    # We'll do BFS to find the Kempe chain component of v in colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (coloring[y] == target_color or coloring[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of the component has color c (would cause conflict if swapped)
                    has_conflict = False
                    for x in component:
                        for y in neighbors[x]:
                            if coloring[y] == c and y not in component:
                                has_conflict = True
                                break
                        if has_conflict:
                            break
                    if not has_conflict:
                        # Perform swap: target_color <-> c in the component
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            else:  # must be c
                                coloring[x] = target_color
                        break
                else:
                    # Kempe chain didn't work for any c, leave v as is for now
                    pass
        # After attempting to recolor all vertices of target_color, check if color class is empty
        new_verts = [v for v in range(n) if coloring[v] == target_color]
        if not new_verts:
            # Compact colors: shift down all colors > target_color by 1
            for v in range(n):
                if coloring[v] > target_color:
                    coloring[v] -= 1
            return coloring, True
        return coloring, False

    # Iteratively try to reduce the number of colors
    current = best[:]
    k = count_colors(current)
    improved = True
    # Limit iterations to avoid infinite loops; in practice, few iterations suffice
    for _ in range(k):  # at most k attempts
        if not improved:
            break
        improved = False
        # Try to eliminate the highest color class (k-1) first, as it's likely smallest
        for target in range(k-1, -1, -1):
            new_col, eliminated = eliminate_color_class(current[:], target)  # work on a copy
            if eliminated:
