    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # DSATUR with dynamic tie-breaking: sum of degrees of uncolored neighbors
    def dsatur():
        color = [-1] * n
        # Precompute static degrees for tie-breaking
        deg = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by sum of degrees of uncolored neighbors
            best_v = -1
            best_sat = -1
            best_tie = -1  # sum of degrees of uncolored neighbors

            for v in range(n):
                if color[v] != -1:
                    continue
                # Compute saturation: distinct colors in neighbors
                neighbor_colors = 0
                for u in adj_list[v]:
                    if color[u] != -1:
                        neighbor_colors |= (1 << color[u])
                sat = neighbor_colors.bit_count()

                # Tie-breaker: sum of degrees of uncolored neighbors
                tie_breaker = 0
                for u in adj_list[v]:
                    if color[u] == -1:
                        tie_breaker += deg[u]

                if sat > best_sat or (sat == best_sat and tie_breaker > best_tie):
                    best_sat = sat
                    best_tie = tie_breaker
                    best_v = v
                elif sat == best_sat and tie_breaker == best_tie and v < best_v:
                    best_v = v

            v = best_v
            # Find smallest available color (mex)
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

        return color

    # Welsh-Powell ordering (largest degree first) with greedy coloring
    def welsh_powell():
        # Order by degree descending
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        deg = [len(adj_list[i]) for i in range(n)]
        # Current degree in remaining graph
        curr_deg = deg[:]
        # Remaining vertices
        remaining = [True] * n
        order = []
        # Buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            if curr_deg[i] < len(buckets):
                buckets[curr_deg[i]].append(i)

        # Pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # Find non-empty bucket
            while min_deg < len(buckets) and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= len(buckets):
