            else:
                v = buckets[min_deg].pop()
                while not remaining[v]:
                    if not buckets[min_deg]:
                        break
                    v = buckets[min_deg].pop()
            order.append(v)
            remaining[v] = False
            # Update neighbors
            for u in adj_list[v]:
                if remaining[u]:
                    old_deg = curr_deg[u]
                    curr_deg[u] -= 1
                    if old_deg < len(buckets):
                        buckets[old_deg].remove(u)  # O(n) but n<=100
                    if curr_deg[u] < len(buckets):
                        buckets[curr_deg[u]].append(u)
                    if curr_deg[u] < min_deg:
                        min_deg = curr_deg[u]

        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
