                    if deg[u] < min_deg:
                        min_deg = deg[u]
        # Color in reverse order
        return greedy_order(order[::-1])

    # Welsh-Powell ordering (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_order(order)

    # Kempe chain swap for colors a and b
    def kempe_swap(colors, a, b):
        # Build mapping of color to vertices
        color_verts = [[] for _ in range(max(colors) + 1 if colors else 0)]
        for v in range(n):
            c = colors[v]
            if c < len(color_verts):
                color_verts[c].append(v)
        # Ensure a and b are within bounds
        if a >= len(color_verts) or b >= len(color_verts):
            return False, colors
        # For each vertex of color a, try to swap its Kempe chain with color b
        for v in color_verts[a]:
            visited = [False] * n
            stack = [v]
            visited[v] = True
            component = []
            while stack:
                u = stack.pop()
                component.append(u)
                for w in neighbors[u]:
                    if not visited[w] and (colors[w] == a or colors[w] == b):
                        visited[w] = True
                        stack.append(w)
            # Check if component has no neighbor of color b outside the component
            # Actually, swapping is always valid as long as we stay within a,b subgraph
            # But we want to free color a for v? Actually, we want to eliminate color a by moving v to b
            # After swap, v will have color b, so we need to ensure no neighbor of v has color b after swap
            # However, in the component, neighbors with color b will become a, and vice versa.
            # So after swap, v (originally a) becomes b. Its neighbors in the component that were b become a.
            # Neighbors outside the component: if they are b, they remain b -> conflict if v becomes b.
            # So we need that no neighbor of v outside the component has color b.
            conflict = False
            for u in component:
                for w in neighbors[u]:
                    if not visited[w] and colors[w] == b:
                        conflict = True
                        break
                if conflict:
                    break
            if not conflict:
                # Perform swap: a<->b in component
                for u in component:
                    if colors[u] == a:
                        colors[u] = b
                    else:  # must be b
                        colors[u] = a
                return True, colors
        return False, colors

    # Try to eliminate the smallest color class using Kempe chains
    def reduce_colors(colors):
        if not colors:
            return colors
        k = max(colors) + 1
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex to a lower color
            changed = False
            for v in verts:
                used = 0
                for u in neighbors[v]:
                    c = colors[u]
                    if c != -1:
                        used |= (1 << c)
                # Find smallest available color
                for c in range(target_color):  # only try lower colors
                    if not (used & (1 << c)):
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # After change, we may have unused colors, but we'll compact later
                break
            # Try Kempe chains with each lower color
            for c in range(target_color):
                success, new_colors = kempe_swap(colors[:], target_color, c)
                if success:
                    colors = new_colors
                    changed = True
                    break
            if changed:
                break
        # Compact colors: remap to 0..k'-1
        if changed or True:  # always compact to ensure consecutive
            # Find used colors
            used_colors = set()
            for c in colors:
                if c != -1:
                    used_colors.add(c)
            if not used_colors:
                return [0] * n
            mapping = {}
            sorted_used = sorted(used_colors)
            for new_c, old_c in enumerate(sorted_used):
                mapping[old_c] = new_c
            colors = [mapping[c] for c in colors]
        return colors

    # Generate multiple random greedy orderings
    def random_greedy_passes(num_pass=10):
        best_colors = None
        best_k = float('inf')
        for _ in range(num_pass):
            # Random permutation
            order = list(range(n))
            random.shuffle(order)
            colors = greedy_order(order)
            k = num_colors(colors)
            if k < best_k:
                best_k = k
                best_colors = colors[:]
        return best_colors

    # Main: try multiple heuristics
    candidates = []

    # 1. DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append((num_colors(c1), c1))
    except:
        pass

    # 2. RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append((num_colors(c2), c2))
    except:
        pass

    # 3. Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append((num_colors(c3), c3))
    except:
        pass

    # 4. Welsh-Powell
    try:
        c4 = welsh_powell()
        if is_valid(c4):
            candidates.append((num_colors(c4), c4))
    except:
        pass

    # 5. Random greedy passes
    try:
        c5 = random_greedy_passes(10)
        if c5 is not None and is_valid(c5):
            candidates.append((num_colors(c5), c5))
    except:
        pass

    # Select best candidate
    if not candidates:
        # Fallback: trivial coloring (may not be valid, but we fix)
        colors = list(range(n))
        # Validate and fix conflicts
        changed = True
        while changed:
            changed = False
            for u in range(n):
                for v in neighbors[u]:
                    if u < v and colors[u] == colors[v]:
                        # increment one of them
                        colors[v] += 1
                        changed = True
        # Compact
        used = set(colors)
        mapping = {old: new for new, old in enumerate(sorted(used))}
        colors = [mapping[c] for c in colors]
        return colors

    best_k, best_colors = min(candidates, key=lambda x: x[0])

    # Apply Kempe chain reduction iteratively
    for _ in range(10):  # limit iterations
        new_colors = reduce_colors(best_colors[:])
        new_k = num_colors(new_colors)
        if new_k < best_k:
            best_k = new_k
            best_colors = new_colors
        else:
            # No improvement, break early
            break

    # Final validation and compaction
    if not is_valid(best_colors):
        # Should not happen, but fallback to greedy
        best_colors = greedy_order(list(range(n)))
    # Ensure consecutive colors
    used = set(best_colors)
    if used:
        mapping = {old: new for new, old in enumerate(sorted(used))]
        best_colors = [mapping[c] for c in best_colors]

    return best_colors

