def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = coloring[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring

    # DSATUR
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            max_sat = -1
            max_deg = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if sat > max_sat or (sat == max_sat and deg > max_deg):
                    max_sat = sat
                    max_deg = deg
                    best_v = v
                elif sat == max_sat and deg == max_deg and v < best_v:
                    best_v = v
            v = best_v
            # Find smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u] |= (1 << c)
        return coloring

    # RLF
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build maximal independent set for this color
            S = []
            # Choose vertex with max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
                S.append(v)
                uncolored.remove(v)
                # Partition remaining uncolored into U and W
                U = set()
                W = set()
                for u in uncolored:
                    if any((bit_adj[u] >> w) & 1 for w in S):
                        W.add(u)
                    else:
                        U.add(u)
                # Greedily add to S from U
                while U:
                    # Select u in U with max |N(u) ∩ W|
                    best_u = -1
                    max_w_neighbors = -1
                    min_deg_U = float('inf')
                    for u in U:
                        w_neighbors = 0
                        for w in adj_list[u]:
                            if w in W:
                                w_neighbors += 1
                        deg_U = 0
                        for w in adj_list[u]:
                            if w in U:
                                deg_U += 1
                        if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_U < min_deg_U):
                            max_w_neighbors = w_neighbors
                            min_deg_U = deg_U
                            best_u = u
                        elif w_neighbors == max_w_neighbors and deg_U == min_deg_U and u < best_u:
                            best_u = u
                    u = best_u
                    S.append(u)
                    U.remove(u)
                    # Move neighbors of u from U to W
                    for w in adj_list[u]:
                        if w in U:
                            U.remove(w)
                            W.add(w)
            # Assign color to S
            for v in S:
                coloring[v] = color
            color += 1
        return coloring

    # Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        degrees = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degrees[u]
                    buckets[d].remove(u)
                    degrees[u] -= 1
                    buckets[degrees[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, a, b, v):
        if coloring[v] not in (a, b):
            return False
        stack = [v]
        visited = set()
        comp_color = coloring[v]
        target_color = a if comp_color == b else b
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            # Swap color
            coloring[u] = target_color if coloring[u] == comp_color else comp_color
            for w in adj_list[u]:
                if w not in visited and coloring[w] in (a, b):
                    stack.append(w)
        return True

    # Try to eliminate the last color using Kempe chains
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target = k - 1
        vertices = [v for v in range(n) if coloring[v] == target]
        # Try direct reassignment first
        for v in vertices:
            used = 0
            for u in adj_list[v]:
                c = coloring[u]
                if c != -1:
                    used |= (1 << c)
            for c in range(target):
                if not (used & (1 << c)):
                    coloring[v] = c
                    vertices.remove(v)
                    break
        if not vertices:
            # Successfully removed target color, compact
            new_coloring = [c if c < target else c - 1 for c in coloring]
            return reduce_colors(new_coloring)
        # Try Kempe chains
        made_progress = True
        while made_progress and vertices:
            made_progress = False
            v = vertices[0]
            for c in range(target):
                if kempe_swap(coloring, target, c, v):
                    # After swap, check if v changed color
                    if coloring[v] != target:
                        vertices.remove(v)
                        made_progress = True
                        break
                    else:
                        # Swap didn't change v's color, revert
                        kempe_swap(coloring, target, c, v)
            # If no progress, try next vertex
            if not made_progress:
                vertices = vertices[1:] if len(vertices) > 1 else []
        if not vertices:
            new_coloring = [c if c < target else c - 1 for c in coloring]
            return reduce_colors(new_coloring)
        return coloring

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Also try Welsh-Powell (degree ordering)
    degree_order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
    candidates.append(greedy_color(degree_order))

    # Try random orders a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    # Select best valid coloring (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        if is_valid(col):
            k = num_colors(col)
            if k < best_k or (k == best_k and best is None):
                best_k = k
                best = col

    # Fallback: if no valid found (shouldn't happen), use DSATUR
    if best is None:
        best = dsatur()

    # Apply Kempe chain reduction to try to get better
    best = reduce_colors(best[:])

    # Final validation and compacting
    if not is_valid(best):
        # Last resort: greedy on DSATUR order
        order = list(range(n))
        order.sort(key=lambda x: -len(adj_list[x]))
        best = greedy_color(order)
    # Ensure colors are compact
    if best:
        mapping = {}
        next_color = 0
        for c in best:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        best = [mapping[c] for c in best]

    return best

