    n = len(adj)
    # Determine if input is adjacency matrix or adjacency list
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Convert adjacency matrix to adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj
        # Ensure adjacency list is valid (no self-loops, symmetric not required but assumed)
        for i in range(n):
            graph[i] = [v for v in graph[i] if v != i and 0 <= v < n]

