    def greedy_coloring(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in graph[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        uncolored = set(range(n))
        # degree in the uncolored subgraph
        deg_uncolored = [len(graph[u]) for u in range(n)]

        while uncolored:
            # Select vertex with max saturation, tie-break by max deg_uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                if sat > best_sat or (sat == best_sat and deg_uncolored[v] > best_deg) or \
                   (sat == best_sat and deg_uncolored[v] == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg_uncolored[v]
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = 0
            for u in graph[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation and deg_uncolored for neighbors
            for u in graph[v]:
                if color[u] == -1:  # u is uncolored
                    saturation[u] |= (1 << c)
                    deg_uncolored[u] -= 1
