            if not uncolored:
                break
            v = max(uncolored, key=lambda u: sum(1 for w in graph[u] if w in uncolored))
            S.add(v)
            # Partition uncolored \ {v} into U (not adjacent to S) and W (adjacent to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(w in graph[u] for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add vertices from U to S
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                best_nw = -1
                best_deg_u = -1
                for u in U:
                    nw = sum(1 for w in graph[u] if w in W)
                    deg_u = sum(1 for w in graph[u] if w in U)
                    if nw > best_nw or (nw == best_nw and deg_u < best_deg_u) or \
                       (nw == best_nw and deg_u == best_deg_u and random.random() < 0.5):
                        best_nw = nw
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
