        bucket_pos = [0] * n
        for u in range(n):
            bucket_pos[u] = len(buckets[rem_deg[u]])
            buckets[rem_deg[u]].append(u)

        # Simplified: repeated removal of min degree vertex
        # We'll use a simpler O(n^2) method since n <= 100
        remaining = set(range(n))
        removal_order = []
        while remaining:
            # Find vertex with minimum degree in the remaining subgraph
            min_v = None
            min_deg = float('inf')
            for v in remaining:
                deg = sum(1 for u in graph[v] if u in remaining)
                if deg < min_deg:
                    min_deg = deg
                    min_v = v
            removal_order.append(min_v)
            remaining.remove(min_v)
        # Color in reverse removal order
        return greedy_coloring(removal_order[::-1])

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Ensure coloring uses colors 0..k-1
        max_color = max(coloring) if n > 0 else -1
        if max_color < 0:
            return coloring
        # Compact colors if necessary
        while True:
            # Map colors to 0..k-1
            unique_colors = sorted(set(coloring))
            if list(range(len(unique_colors))) == unique_colors:
                break
            mapping = {old: new for new, old in enumerate(unique_colors)}
            coloring = [mapping[c] for c in coloring]
            max_color = len(unique_colors) - 1

        k = max_color + 1
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            # Get vertices with target_color
            targets = [v for v in range(n) if coloring[v] == target_color]
            if not targets:
                continue
            # Try to recolor each target vertex
            removed = False
            for v in targets:
                # Try direct reassignment to a lower color
                used = 0
                for u in graph[v]:
                    if coloring[u] != -1:
                        used |= (1 << coloring[u])
                for c in range(target_color):  # only try colors < target_color
                    if not (used & (1 << c)):
                        coloring[v] = c
                        removed = True
                        break
                if removed:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # BFS to get component
                    from collections import deque
                    comp = set()
                    q = deque([v])
                    comp.add(v)
                    while q:
                        x = q.popleft()
                        for y in graph[x]:
                            if coloring[y] == target_color or coloring[y] == c:
                                if y not in comp:
                                    comp.add(y)
                                    q.append(y)
                    # Check if swapping colors in comp would cause conflict
                    # Specifically, after swap, no neighbor outside comp should have the new color
                    valid = True
                    for x in comp:
                        new_color = c if coloring[x] == target_color else target_color
                        for y in graph[x]:
                            if y not in comp and coloring[y] == new_color:
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        # Perform swap
                        for x in comp:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            else:
                                coloring[x] = target_color
                        removed = True
                        break
                if removed:
                    break
            if not removed:
                # Cannot eliminate this color, move to next lower color
                continue
            else:
                # Successfully removed at least one vertex from target_color
                # Recompact and restart from highest color
                # Compact colors
                unique_colors = sorted(set(coloring))
                mapping = {old: new for new, old in enumerate(unique_colors)}
                coloring = [mapping[c] for c in coloring]
                # Restart from the new highest color
                return kempe_reduce(coloring)
        return coloring

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col1 = dsatur()
        candidates.append(col1)
    except:
        pass
    # RLF
    try:
        col2 = rlf()
        candidates.append(col2)
    except:
        pass
    # Smallest-Last
    try:
        col3 = smallest_last()
        candidates.append(col3)
    except:
        pass

    # If no candidates, fallback to greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda u: len(graph[u]), reverse=True)
        candidates.append(greedy_coloring(order))

    # Select candidate with minimal number of colors
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        # Validate coloring
        valid = True
        for u in range(n):
            for v in graph[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = len(set(col))
        if k < best_k:
            best_k = k
            best_coloring = col

    # Apply Kempe reduction to the best candidate
    if best_coloring is not None:
        best_coloring = kempe_reduce(best_coloring[:])  # work on a copy
        # Final validation
        for u in range(n):
            for v in graph[u]:
                if best_coloring[u] == best_coloring[v]:
                    # Fallback: return DSATUR if Kempe produced invalid
                    return dsatur()
        return best_coloring
    else:
        # Ultimate fallback
        return dsatur()

