def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: validate coloring and compute number of colors
    def validate_and_count(colors):
        if len(colors) != n:
            return False, 0
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False, 0
        max_color = max(colors) if n > 0 else -1
        return True, max_color + 1

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # Precompute degrees
        degrees = [len(adj_list[i]) for i in range(n)]
        # Maintain saturation sets as bitmasks
        saturation = [0] * n  # bitmask of colors used by neighbors
        colored = [False] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then index
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                sat = saturation[v].bit_count()
                if sat > best_sat or (sat == best_sat and degrees[v] > best_deg) or \
                   (sat == best_sat and degrees[v] == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = degrees[v]
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            # Update saturation of neighbors
            for u in adj_list[v]:
                if not colored[u]:
                    saturation[u] |= (1 << c)
        return colors

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # Build independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
                S.add(v)
                uncolored.remove(v)
            # Partition remaining uncolored into U (eligible) and W (ineligible)
            W = set()
            for u in list(uncolored):
                if any(w in adj_list[u] for w in S):
                    W.add(u)
            U = uncolored - W
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = len([w for w in adj_list[u] if w in W])
                    deg_u = len([y for y in adj_list[u] if y in U])
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and u < best_u):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to S
            for v in S:
                colors[v] = color_idx
            color_idx += 1
            # Next round: uncolored becomes W (vertices adjacent to S)
            uncolored = W
        return colors

    # Helper: Smallest-Last ordering (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll simulate removal
        current_degree = degree[:]
        removed = [False] * n
        for _ in range(n):
            # Find vertex with min current degree in remaining
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                if current_degree[v] < min_deg:
                    min_deg = current_degree[v]
                    v_min = v
            v = v_min
            order.append(v)
            removed[v] = True
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    current_degree[u] -= 1
        # Color in reverse order
        return greedy_color(list(reversed(order)))

    # Helper: Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(colors, a, b, v):
        n = len(colors)
        if colors[v] not in (a, b):
            return False  # Should not happen
        target = b if colors[v] == a else a
        stack = [v]
        visited = set()
        component = []
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            if colors[node] == a or colors[node] == b:
                component.append(node)
                for nb in adj_list[node]:
                    if nb not in visited and (colors[nb] == a or colors[nb] == b):
                        stack.append(nb)
        # Check if we can swap: after swap, no neighbor of any node in component gets color conflict?
        # Actually, swapping a<->b in a Kempe chain preserves validity, so we can always swap.
        # But we want to free color a for v? We'll swap the component.
        for node in component:
            if colors[node] == a:
                colors[node] = b
            else:
                colors[node] = a
        return True

    # Helper: try to eliminate the smallest color class using Kempe chains
    def reduce_colors(colors):
        # Make a copy to work on
        cur_colors = colors[:]
        changed = True
        while changed:
            changed = False
            # Find color classes
            classes = [[] for _ in range(n)]  # up to n colors
            max_color = -1
            for v in range(n):
                c = cur_colors[v]
                classes[c].append(v)
                if c > max_color:
                    max_color = c
            # Try to eliminate from highest color down? Actually target smallest non-empty class
            # But literature says target smallest color class (often highest index if we use first-fit)
            # We'll target the largest color index that is non-empty, as it's likely smallest class in DSATUR/RLF
            # Find non-empty classes from high to low
            for color in range(max_color, -1, -1):
                if not classes[color]:
                    continue
                # Try to recolor each vertex in this class to a lower color
                eliminated = True
                for v in classes[color]:
                    # Check if v can take any color < color without conflict
                    found = False
                    for c in range(color):
                        conflict = False
                        for u in adj_list[v]:
                            if cur_colors[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            cur_colors[v] = c
                            found = True
                            break
                    if found:
                        continue
                    # Try Kempe chain with each lower color
                    kempe_found = False
                    for c in range(color):
                        # Try to swap along (color, c) Kempe chain starting at v
                        # Make a copy to test
                        test_colors = cur_colors[:]
                        if kempe_swap(test_colors, color, c, v):
                            # After swap, check if v now has color c (which it should if it was color)
                            # Actually, we want to see if after swap, v is no longer color 'color'
                            if test_colors[v] != color:
                                # Accept the swap
                                cur_colors = test_colors
                                kempe_found = True
                                break
                    if kempe_found:
                        continue
                    # If we couldn't recolor v, we cannot eliminate this color class yet
                    eliminated = False
                    break
                if eliminated:
                    # Successfully eliminated color class: remap colors above down by one
                    for v in range(n):
                        if cur_colors[v] > color:
                            cur_colors[v] -= 1
                    changed = True
                    break  # restart from scratch after change
        return cur_colors

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        valid, k1 = validate_and_count(c1)
        if valid:
            candidates.append((k1, c1))
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        valid, k2 = validate_and_count(c2)
        if valid:
            candidates.append((k2, c2))
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        valid, k3 = validate_and_count(c3)
        if valid:
            candidates.append((k3, c3))
    except Exception:
        pass
    # Fallback: greedy by degree order
    try:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        c4 = greedy_color(order)
        valid, k4 = validate_and_count(c4)
        if valid:
            candidates.append((k4, c4))
    except Exception:
        pass

    if not candidates:
        # Ultimate fallback: assign each vertex a unique color
        return list(range(n))

    # Select candidate with minimal colors
    best_k, best_colors = min(candidates, key=lambda x: x[0])
    # Apply Kempe chain reduction to try to improve
    try:
        reduced = reduce_colors(best_colors)
        valid, k_red = validate_and_count(reduced)
        if valid and k_red < best_k:
            best_colors = reduced
            best_k = k_red
    except Exception:
        pass

    # Ensure colors are compact (0..k-1)
    # Remap colors to consecutive indices
    color_map = {}
    next_color = 0
    for v in range(n):
        c = best_colors[v]
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        best_colors[v] = color_map[c]
    return best_colors

