                break
        if all_binary:
            is_matrix = True
    # Build neighbor list and bitmask adjacency
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    # Ensure symmetry (undirected graph)
    for i in range(n):
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].append(i)
                bit_adj[j] |= (1 << i)
    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            # Find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Helper: count distinct colors
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True
    # Heuristic 1: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = uncolored_deg[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and v > best_v):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color
    # Heuristic 2: RLF (Largest First Independent Set)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent_set = {v}
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = uncolored - {v} - set(neighbors[v])
            W = set(neighbors[v]) & uncolored
            # Greedily add vertices from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_in_U = float('inf')
                for u in U:
                    score = sum(1 for y in neighbors[u] if y in W)
                    deg_in_U = sum(1 for y in neighbors[u] if y in U)
                    if score > best_score or (score == best_score and deg_in_U < best_deg_in_U) or (score == best_score and deg_in_U == best_deg_in_U and u < best_u):
                        best_score = score
                        best_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color to independent set
            for v in independent_set:
                color[v] = color_idx
            uncolored -= independent_set
            color_idx += 1
        return color
    # Heuristic 3: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current min degree
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])
    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: simple greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass
    # If no candidate (should not happen), assign distinct colors
    if not candidates:
        return list(range(n))
    # Select candidate with minimal colors
    best = min(candidates, key=count_colors)
    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # Get vertices with target_color
        verts = [v for v in range(n) if coloring[v] == target_color]
        if not verts:
            return coloring, True  # already eliminated
        # Try to recolor each vertex
        for v in verts:
            # Try direct reassignment to a lower color
            used = 0
            for u in neighbors[v]:
                c = coloring[u]
                if c != -1 and c < target_color:
                    used |= (1 << c)
            for c in range(target_color):
                if not (used & (1 << c)):
                    # Move v to color c
                    coloring[v] = c
                    # Remove v from target color class
                    verts.remove(v)
                    break
            else:
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Build (c, target_color) Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == c or coloring[node] == target_color:
                            component.add(node)
                            for nb in neighbors[node]:
                                if nb not in visited and (coloring[nb] == c or coloring[nb] == target_color):
                                    stack.append(nb)
                    # Check if any neighbor of v in component has color c? Actually, we need to see if swapping removes conflict
                    # After swap, v would become c if it was target_color, but we need to ensure no neighbor of v is c after swap
                    # Actually, we check: if no neighbor of v is colored c in the current coloring, then after swap v becomes c and it's safe
                    # But if there is a neighbor u of v with color c, then after swap v becomes c and conflict with u.
                    # However, if that neighbor u is in the component, then after swap u becomes target_color, so no conflict.
                    # So condition: all neighbors of v that are colored c must be in the component.
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c and u not in component:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        # v is now color c
                        coloring[v] = c
                        verts.remove(v)
                        break
                else:
                    # Could not recolor v
                    return coloring, False
        # All vertices recolored, target color eliminated
        return coloring, True
    # Iteratively try to eliminate highest color
    k = count_colors(best)
    changed = True
    while changed and k > 0:
        changed = False
        target = k - 1
        new_coloring, eliminated = eliminate_color_class(best[:], target)  # work on copy
        if eliminated:
            # Remap colors to be consecutive
            mapping = {}
            next_color = 0
            for i in range(n):
                c = new_coloring[i]
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
                new_coloring[i] = mapping[c]
            best = new_coloring
            k = count_colors(best)
            changed = True
    # Final validation and remap to ensure consecutive
    if not is_valid(best):
        # Should not happen, but fallback to greedy
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        best = greedy_color(order)
    # Ensure colors are 0..k-1
    mapping = {}
    next_color = 0
    for i in range(n):
        c = best[i]
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
        best[i] = mapping[c]
    return best

