    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= 1 << j
    else:
        # adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    bit_adj[u] |= 1 << v

    if n == 0:
        return []
    if n == 1:
        return [0]

