        deg_uncolored = [bin(bit_adj[i]).count('1') for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = bin(sat[u]).count('1')
                d = deg_uncolored[u]
                if s > max_sat or (s == max_sat and d > max_deg) or (s == max_sat and d == max_deg and random.random() < 0.5):
                    max_sat = s
                    max_deg = d
                    v = u
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1:
                    if color[u] == -1:
                        sat[u] |= 1 << c
                        deg_uncolored[u] -= 1
                    else:
                        # neighbor already colored, no need to update sat for colored? Actually sat only for uncolored neighbors
                        pass
        return color

    col_dsatur = dsatur()
    k_dsatur = count_colors(col_dsatur)
    if k_dsatur < best_k:
        best_k = k_dsatur
        best_color = col_dsatur[:]

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = set()
            # vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: bin(bit_adj[x] & sum(1 << u for u in uncolored)).count('1'))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - S
            W = set()
            for u in U:
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
            U -= W
            while U:
                # select u in U with max neighbors in W
                u_star = -1
                max_nw = -1
                min_deg_U = float('inf')
                for u in U:
                    nw = bin(bit_adj[u] & sum(1 << w for w in W)).count('1')
                    deg_U = bin(bit_adj[u] & sum(1 << w for w in U)).count('1')
                    if nw > max_nw or (nw == max_nw and deg_U < min_deg_U) or (nw == max_nw and deg_U == min_deg_U and random.random() < 0.5):
                        max_nw = nw
                        min_deg_U = deg_U
                        u_star = u
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for w in list(U):
                    if (bit_adj[u_star] >> w) & 1:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    col_rlf = rlf()
    k_rlf = count_colors(col_rlf)
    if k_rlf < best_k:
        best_k = k_rlf
        best_color = col_rlf[:]

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        deg = [bin(bit_adj[i]).count('1') for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current min degree
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    buckets[d].remove(u)
                    buckets[deg[u]].append(u)
                    if deg[u] < ptr:
                        ptr = deg[u]
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    col_sl = smallest_last()
    k_sl = count_colors(col_sl)
    if k_sl < best_k:
        best_k = k_sl
        best_color = col_sl[:]

    # Kempe chain color reduction
    def kempe_reduction(color):
        # make color indices consecutive
        def renormalize(col):
            mapping = {}
            next_c = 0
            for v in range(n):
                if col[v] not in mapping:
                    mapping[col[v]] = next_c
                    next_c += 1
                col[v] = mapping[col[v]]
            return col

        color = renormalize(color[:])
        k = count_colors(color)
        improved = True
        while improved and k > 1:
            improved = False
            # target smallest color class (color k-1)
            target_color = k - 1
            vertices = [v for v in range(n) if color[v] == target_color]
            if not vertices:
                # should not happen
                break
            # try to recolor each vertex in target class
            for v in vertices:
                # try direct reassignment to a lower color
                used = 0
                for u in range(n):
                    if (bit_adj[v] >> u) & 1:
                        used |= 1 << color[u]
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # move v to color c
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # BFS to find Kempe chain of colors {target_color, c} containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in range(n):
                            if (bit_adj[u] >> w) & 1 and not visited[w]:
                                if color[w] == target_color or color[w] == c:
                                    visited[w] = True
                                    queue.append(w)
                    # check if swapping colors in component frees color c for v
                    # after swap, v would get color c, so we need that no neighbor of v has color c after swap
                    # neighbors of v that are in component and have color c will become target_color
                    # neighbors of v not in component with color c remain c
                    conflict = False
                    for u in range(n):
                        if (bit_adj[v] >> u) & 1:
                            if color[u] == c and u not in component:
                                conflict = True
                                break
                    if not conflict:
                        # perform swap
                        for u in component:
                            if color[u] == target_color:
                                color[u] = c
                            elif color[u] == c:
                                color[u] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # renormalize and update k
                color = renormalize(color)
                k = count_colors(color)
            else:
                # cannot eliminate target color
                break
        return color

    # Apply Kempe reduction to the best candidate
    best_color = kempe_reduction(best_color)
    # Final validation and renormalize
    def validate_and_renorm(col):
        # validate
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if col[u] == col[v]:
                        # invalid, but should not happen; fallback to greedy
                        return greedy_color(list(range(n)))
        # renormalize
        mapping = {}
        next_c = 0
        for i in range(n):
            if col[i] not in mapping:
                mapping[col[i]] = next_c
                next_c += 1
            col[i] = mapping[col[i]]
        return col

    best_color = validate_and_renorm(best_color)
    return best_color

