    except Exception:
        pass

    # Final validation and compacting
    def validate_and_compact(coloring):
        # Check validity
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    # Invalid, but we try to fix by greedy re-color
                    return greedy_color(list(range(n)))
        # Compact colors
        mapping = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            coloring[i] = mapping[c]
        return coloring

    best_coloring = validate_and_compact(best_coloring)
    return best_coloring

