            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if len(candidates) > 1:
                # Tie-break by degree in uncolored subgraph
                max_deg = -1
                deg_candidates = []
                for v in candidates:
                    deg = sum(1 for u in neighbors[v] if u in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        deg_candidates = [v]
                    elif deg == max_deg:
                        deg_candidates.append(v)
                candidates = deg_candidates
            v = random.choice(candidates)
            # Find smallest available color
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        return color

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set S for color c
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # Partition U and W
            U = uncolored - {v}
            W = set(neighbors[v]) & uncolored
            U -= W
            while U:
                # Select u in U with max |N(u) ∩ W|
                max_w_neighbors = -1
                best_u = None
                for u in U:
                    w_count = sum(1 for y in neighbors[u] if y in W)
                    if w_count > max_w_neighbors:
                        max_w_neighbors = w_count
                        best_u = u
                    elif w_count == max_w_neighbors:
                        # Tie-break: min degree in U
                        deg_u = sum(1 for y in neighbors[u] if y in U)
                        deg_best = sum(1 for y in neighbors[best_u] if y in U) if best_u is not None else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

