    def smallest_last():
        # Compute degeneracy ordering
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for v in range(n):
            if deg[v] < n:
                buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = v
        # Simplified: use list of sets for buckets
        bucket_sets = [set() for _ in range(n)]
        for v in range(n):
            if deg[v] < n:
                bucket_sets[deg[v]].add(v)
        min_deg = 0
        for _ in range(n):
            # Find non-empty bucket
            while min_deg < n and not bucket_sets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break
            v = bucket_sets[min_deg].pop()
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    d = deg[u]
                    if d < n and u in bucket_sets[d]:
                        bucket_sets[d].remove(u)
                        deg[u] -= 1
                        if deg[u] >= 0:
                            bucket_sets[deg[u]].add(u)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
