    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            # Validate
            valid = True
            for u in range(n):
                for v in neighbors[u]:
                    if color[u] == color[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                k = max(col) + 1 if col else 0
                candidates.append((k, col))
        except Exception:
            continue

    if not candidates:
        # Fallback: greedy by original order
        color = [0] * n
        for i in range(n):
            used = 0
            for u in neighbors[i]:
                if u < i:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        candidates.append((max(color) + 1, color))

    # Select best candidate (min colors)
    best_k, best_coloring = min(candidates, key=lambda x: x[0])

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal n, bit_adj
        while True:
            # Find smallest non-empty color class
            color_classes = [[] for _ in range(max(coloring) + 1)] if coloring else [[]]
            for v, c in enumerate(coloring):
                color_classes[c].append(v)
            # Find the last color (highest index) that is non-empty; we try to eliminate it
            target_color = -1
            for c in range(len(color_classes) - 1, -1, -1):
                if color_classes[c]:
                    target_color = c
                    break
            if target_color == 0:
                break  # Cannot reduce further
            # Try to recolor each vertex in target_color
            removed = False
            for v in color_classes[target_color][:]:  # copy list
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target_color):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        removed = True
                        break
                if removed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # If v already has color c due to prior swap, skip
                    if coloring[v] == c:
                        removed = True
                        break
                    # Find Kempe chain (c, target_color) containing v
                    # BFS to get component
                    from collections import deque
                    queue = deque([v])
                    visited = set([v])
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for u in neighbors[node]:
                            if coloring[u] == c or coloring[u] == target_color:
                                if u not in visited:
                                    visited.add(u)
                                    queue.append(u)
                    # Check if swapping is safe: no neighbor of component has color c (would conflict after swap)
                    safe = True
                    for node in component:
                        for u in neighbors[node]:
                            if coloring[u] == c and u not in component:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        removed = True
                        break
                if removed:
                    break
            if not removed:
                break
            # Compact colors: reindex to 0..k-1
            # But we already try to remove highest color, so just re-run the loop
        return coloring

    best_coloring = kempe_reduce(best_coloring[:])
    # Validate and ensure consecutive colors
    # Re-index colors to be consecutive
    used_colors = set(best_coloring)
    mapping = {old: new for new, old in enumerate(sorted(used_colors))]
    best_coloring = [mapping[c] for c in best_coloring]
    # Final validation (should be valid)
    for u in range(n):
        for v in neighbors[u]:
            if best_coloring[u] == best_coloring[v]:
                # In case of error, fallback to greedy
                color = [0] * n
                for i in range(n):
                    used = 0
                    for u in neighbors[i]:
                        if u < i:
                            used |= (1 << color[u])
                    c = 0
                    while used & (1 << c):
                        c += 1
                    color[i] = c
                return color
    return best_coloring

