def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build neighbor list and bitmask adjacency
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if v < n:
                    neighbors[u].append(v)
                    bit_adj[u] |= (1 << v)

    # Helper: greedy coloring given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree: bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and len([w for w in neighbors[u] if w in uncolored]) > max_deg):
                    max_sat = s
                    max_deg = len([w for w in neighbors[u] if w in uncolored])
                    v = u
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([w for w in neighbors[x] if w in uncolored]))
            S.add(v)
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if not any(w in S for w in neighbors[u])}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = len([w for w in neighbors[u] if w in W])
                    deg_u = len([w for w in neighbors[u] if w in U])
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
            uncolored = W  # Next round colors vertices in W
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Decrease degree of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    if d < len(buckets):
                        buckets[d].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Welsh-Powell: sort by degree descending
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                k = count_colors(col)
                if k < best_k:
                    best_k = k
                    best_coloring = col[:]
        except Exception:
            continue

    # If no candidate found (should not happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal best_k
        changed = True
        while changed and best_k > 1:
            changed = False
            # Find smallest color class (largest index, assuming compact)
            # We'll try to eliminate color classes from high to low
            for target_color in range(best_k - 1, 0, -1):
                # Get vertices with target_color
                target_vertices = [v for v in range(n) if coloring[v] == target_color]
                if not target_vertices:
                    continue
                # Try to recolor each vertex in target_vertices
                eliminated = True
                for v in target_vertices:
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in neighbors[v]:
                        if coloring[u] != -1:
                            used |= (1 << coloring[u])
                    moved = False
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            # Move v to color c
                            coloring[v] = c
                            moved = True
                            break
                    if moved:
                        continue
                    # Try Kempe chain swap with each lower color
                    swapped = False
                    for c in range(target_color):
                        # Skip if no vertex of color c in neighbors (no chain possible)
                        if not any(coloring[u] == c for u in neighbors[v]):
                            continue
                        # Build (target_color, c)-Kempe chain containing v
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if coloring[node] == target_color or coloring[node] == c:
                                component.add(node)
                                for u in neighbors[node]:
                                    if coloring[u] == target_color or coloring[u] == c:
                                        if u not in visited:
                                            stack.append(u)
                        # Check if swapping this component would free color c for v
                        # After swap, v would get color c (since it was target_color)
                        # We need to ensure no neighbor of v gets color c from the swap
                        conflict = False
                        for u in neighbors[v]:
                            if u in component and coloring[u] == c:
                                # After swap, u becomes target_color, so no conflict
                                continue
                            if u not in component and coloring[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            # Perform swap
                            for node in component:
                                if coloring[node] == target_color:
                                    coloring[node] = c
                                else:
                                    coloring[node] = target_color
                            swapped = True
                            break
                    if swapped:
                        continue
                    # If we couldn't move v, we cannot eliminate target_color yet
                    eliminated = False
                    break
                if eliminated:
                    # Successfully eliminated target_color: remap colors > target_color down by 1
                    for v in range(n):
                        if coloring[v] > target_color:
                            coloring[v] -= 1
                    best_k -= 1
                    changed = True
                    break  # Restart from highest color
        return coloring

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)

    # Final validation and compacting
    if not is_valid(best_coloring):
        # Fallback to greedy if something went wrong
        best_coloring = greedy_color(list(range(n)))
    # Ensure colors are compact
    max_color = max(best_coloring) if best_coloring else 0
    if max_color + 1 < len(set(best_coloring)):
        # Remap to 0..k-1
        unique_colors = {}
        next_color = 0
        for v in range(n):
            c = best_coloring[v]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_coloring[v] = unique_colors[c]

    return best_coloring

