def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Colors a graph using the smallest-last ordering (degeneracy ordering) with First-Fit greedy coloring.
    This guarantees a coloring using at most d+1 colors, where d is the graph's degeneracy.
    """
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree array
    if is_matrix:
        neighbors = []
        for u in range(n):
            nbrs = [v for v in range(n) if adj[u][v] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = adj  # already adjacency list

    degree = [len(neighbors[u]) for u in range(n)]

    # Smallest-last ordering: repeatedly remove min-degree vertex
    removed = [False] * n
    order = []  # removal order (first removed to last removed)
    current_degree = degree[:]  # mutable copy

    for _ in range(n):
        # Find unremoved vertex with minimum current degree
        min_deg = math.inf
        v_min = -1
        for u in range(n):
            if not removed[u] and current_degree[u] < min_deg:
                min_deg = current_degree[u]
                v_min = u
        if v_min == -1:  # should not happen for connected graphs, but safe
            break
        removed[v_min] = True
        order.append(v_min)
        # Decrease degree of neighbors
        for w in neighbors[v_min]:
            if not removed[w]:
                current_degree[w] -= 1

    # Color in reverse removal order using First-Fit
    color = [-1] * n
    for v in reversed(order):
        # Determine colors used by already colored neighbors
        used = [False] * n  # n is safe upper bound on colors needed
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        # Find smallest non-negative integer color not used
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c

    return color

