def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect input type: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj
        # Ensure symmetric (undirected) and no self-loops
        for i in range(n):
            adj_list[i] = [j for j in adj_list[i] if j != i and 0 <= j < n]

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # colored neighbor masks for fast saturation update
        colored_mask = [0] * n
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                if sat[v] > best_sat or (sat[v] == best_sat and len([u for u in adj_list[v] if u in uncolored]) > best_deg):
                    best_sat = sat[v]
                    best_deg = len([u for u in adj_list[v] if u in uncolored])
                    best_v = v
                elif sat[v] == best_sat and len([u for u in adj_list[v] if u in uncolored]) == best_deg:
                    if best_v == -1 or v < best_v:
                        best_v = v
            v = best_v
            # Find smallest color not used by neighbors
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if not (colored_mask[u] & (1 << c)):
                        colored_mask[u] |= (1 << c)
                        sat[u] += 1
        return normalize(colors)

    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # Build independent set for this color
            S = []  # independent set
            # Step 1: pick vertex with max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.append(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = set(uncolored)  # candidates
            W = set()           # blocked
            # Remove v from U
            U.remove(v)
            # Move neighbors of v in U to W
            for u in adj_list[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # While U not empty
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U-induced subgraph
                best_u = -1
                best_w_neighbors = -1
                best_deg_U = -1
                for u in U:
                    w_neighbors = len([w for w in adj_list[u] if w in W])
                    deg_U = len([x for x in adj_list[u] if x in U])
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and deg_U < best_deg_U):
                        best_w_neighbors = w_neighbors
                        best_deg_U = deg_U
                        best_u = u
                    elif w_neighbors == best_w_neighbors and deg_U == best_deg_U:
                        if best_u == -1 or u < best_u:
                            best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # Move neighbors of u in U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to S
            for v in S:
                colors[v] = color_idx
            color_idx += 1
            # Next round: uncolored becomes W
            uncolored = W
        return normalize(colors)

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        # We'll use a list of sets for buckets, but n <= 100 so we can do simple scan
        order = []
        remaining = set(range(n))
        # current degrees in the remaining graph
        curr_deg = deg[:]
        for _ in range(n):
            # find vertex with minimum curr_deg in remaining
            v = min(remaining, key=lambda x: curr_deg[x])
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    curr_deg[u] -= 1
        # Color in reverse order using greedy
        colors = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        return normalize(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                # already empty, compact
                mapping = {c: c for c in range(k) if c != target_color}
                # shift down colors above target
                for c in range(target_color + 1, k):
                    mapping[c] = c - 1
                colors = [mapping[c] for c in colors]
                k -= 1
                changed = True
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        neighbor_colors |= (1 << colors[u])
                for c in range(target_color):  # try colors 0..target_color-1
                    if not (neighbor_colors & (1 << c)):
                        # direct move possible
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart from highest color after change
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # We consider swapping colors target_color and c
                    # Build the Kempe chain component containing v in the subgraph of colors {c, target_color}
                    # Only if v is colored target_color
                    if colors[v] != target_color:
                        continue
                    # BFS to get the component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (colors[nb] == c or colors[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if swapping this component is safe: 
                    # After swap, no neighbor of any node in component should have the new color
                    # For each node in component, if it was color c, it becomes target_color; if target_color, becomes c.
                    # We need to ensure that for every node in component:
                    #   - if it becomes c, none of its neighbors are c (after swap, but note neighbors not in component keep their color)
                    #   - if it becomes target_color, none of its neighbors are target_color (after swap)
                    # However, note: neighbors in the component will also swap, so we only need to check neighbors outside the component.
                    safe = True
                    for node in component:
                        orig_color = colors[node]
                        new_color = c if orig_color == target_color else target_color
                        for nb in adj_list[node]:
                            if not visited[nb]:  # neighbor outside component
                                if colors[nb] == new_color:
                                    safe = False
                                    break
                        if not safe:
                            break
                    if safe:
                        # perform swap
                        for node in component:
                            if colors[node] == c:
                                colors[node] = target_color
                            else:  # must be target_color
                                colors[node] = c
                        changed = True
                        break
                if changed:
                    break
            # After attempting to recolor target vertices, if target color class is empty, compact
            if not any(colors[v] == target_color for v in range(n)):
                mapping = {c: c for c in range(k) if c != target_color}
                for c in range(target_color + 1, k):
                    mapping[c] = c - 1
                colors = [mapping[c] for c in colors]
                k -= 1
                changed = True
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            cols = func()
            if is_valid_coloring(cols):
                k = num_colors(cols)
                if k < best_k:
                    best_k = k
                    best_colors = cols
        except Exception:
            continue

    # Fallback: if no heuristic produced valid coloring, use greedy by node order
    if best_colors is None:
        colors = [-1] * n
        for v in range(n):
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        best_colors = normalize(colors)

    # Apply Kempe chain reduction to try to improve
    try:
        improved = kempe_reduce(best_colors[:])
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < num_colors(best_colors):
                best_colors = improved
    except Exception:
        pass

    # Final validation and normalization
    if not is_valid_coloring(best_colors):
        # Last resort: greedy
        colors = [-1] * n
        for v in range(n):
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        best_colors = normalize(colors)

    return best_colors

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets
    if is_matrix:
        neighbors = [set(j for j in range(n) if adj[i][j] == 1) for i in range(n)]
    else:
        neighbors = [set(adj[i]) for i in range(n)]
        # Ensure symmetry (undirected graph)
        for i in range(n):
            for j in neighbors[i]:
                if i not in neighbors[j]:
                    neighbors[j].add(i)

    # Convert to bitmasks for fast operations
    bit_adj = [0] * n
    for i in range(n):
        for j in neighbors[i]:
            bit_adj[i] |= (1 << j)

    # Helper: count bits in integer
    def popcount(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur():
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbor colorsets (as bitmask for fast distinct count)
        neighbor_colors = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat_u = saturation[u]
                    deg_u = popcount(bit_adj[u])
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
                    elif sat_u == max_sat and deg_u == max_deg:
                        if random.random() < 0.5:  # random tie-break
                            v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # Update neighbors
            for u in neighbors[v]:
                if coloring[u] == -1:
                    # Add color c to neighbor's used colors
                    neighbor_colors[u] |= (1 << c)
                    # Update saturation: count distinct colors in neighbor_colors[u]
                    saturation[u] = popcount(neighbor_colors[u])

        return compact_colors(coloring)

    # RLF algorithm
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for this color
            # S: independent set, U: candidates, W: vertices adjacent to S
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: popcount(bit_adj[u] & sum((1 << w) for w in uncolored)))
            S.add(v)
            uncolored.remove(v)

            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible for this color)
            W = set()
            for u in S:
                W.update(neighbors[u])
            U = uncolored - W

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = popcount(bit_adj[u] & sum((1 << w) for w in W))
                    deg_in_U = popcount(bit_adj[u] & sum((1 << w) for w in U))
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen

                S.add(best_u)
                uncolored.remove(best_u)
                # Move best_u from U to S, update W and U
                U.remove(best_u)
                # Add neighbors of best_u that are in U to W
                new_W = neighbors[best_u] & U
                W.update(new_W)
                U -= new_W

            # Assign color to all in S
            for u in S:
                coloring[u] = color
            color += 1

        return compact_colors(coloring)

    # Smallest-Last (SL) ordering greedy
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [popcount(bit_adj[u]) for u in range(n)]
        order = []
        # We'll maintain current degrees in the remaining subgraph
        curr_degree = degree[:]

        for _ in range(n):
            # Find vertex with minimum degree in remaining
            v = min(remaining, key=lambda u: curr_degree[u])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    curr_degree[u] -= 1

        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return compact_colors(coloring)

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, a, b, v):
        if coloring[v] not in (a, b):
            return False  # should not happen
        target = b if coloring[v] == a else a
        stack = [v]
        visited = set()
        component = []
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if coloring[u] == a or coloring[u] == b:
                component.append(u)
                for w in neighbors[u]:
                    if coloring[w] in (a, b) and w not in visited:
                        stack.append(w)
        # Check if swapping is safe: no neighbor outside component has target color
        for u in component:
            for w in neighbors[u]:
                if w not in component and coloring[w] == target:
                    return False  # would create conflict
        # Perform swap
        for u in component:
            if coloring[u] == a:
                coloring[u] = b
            else:
                coloring[u] = a
        return True

    # Try to eliminate a color class using Kempe chains
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try from highest color down
        for c in range(k-1, 0, -1):
            # Get vertices with color c
            verts_c = [v for v in range(n) if coloring[v] == c]
            if not verts_c:
                continue
            # Try to recolor each vertex in color c
            made_change = False
            for v in verts_c[:]:  # iterate over copy
                # Try direct reassignment to a lower color
                for new_c in range(c):
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == new_c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = new_c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chains with each lower color
                for new_c in range(c):
                    if kempe_swap(coloring, c, new_c, v):
                        made_change = True
                        break
                if made_change:
                    break
            if made_change:
                # Recompact and try again from top
                coloring = compact_colors(coloring)
                return reduce_colors(coloring)  # recurse
        return coloring

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to simple greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        candidates.append(compact_colors(coloring))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = reduce_colors(best)

    # Final validation and compaction
    if not is_valid_coloring(best):
        # Ultimate fallback: greedy ordering by degree
        order = sorted(range(n), key=lambda u: popcount(bit_adj[u]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best = compact_colors(coloring)

    # Ensure zero-based consecutive colors
    best = compact_colors(best)

    return best

