            U = uncolored - {v} - set(adj_list[v])
            W = set(adj_list[v]) & uncolored
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min deg in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_neighbors += 1
                    deg_u = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_u += 1
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or \
                       (w_neighbors == max_w_neighbors and deg_u == min_deg_u and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(adj_list[i]) for i in range(n)]
        # bucket sort by degree
        buckets = [[] for _ in range(n)]
        for v in range(n):
            if deg[v] < n:
                buckets[deg[v]].append(v)
        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg < n and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = deg[u]
                    buckets[d].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].append(u)
                    if deg[u] < min_deg:
                        min_deg = deg[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col
        except Exception:
            continue

    # If no candidate, fallback to greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (largest color index)
            max_color = max(col) if col else -1
            if max_color < 0:
                return col
            # count frequency
            freq = [0] * (max_color + 1)
            for c in col:
                if c != -1:
                    freq[c] += 1
            # find the smallest non-empty color class (prioritize high color indices for removal)
            target_color = -1
            for c in range(max_color, -1, -1):
                if freq[c] > 0:
                    target_color = c
                    break
            if target_color == 0:
                break  # cannot reduce further
            # try to recolor each vertex of target_color
            for v in range(n):
                if col[v] != target_color:
                    continue
                # try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if col[u] != -1:
                        neighbor_colors.add(col[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        col[v] = c
                        freq[target_color] -= 1
                        freq[c] += 1
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # if v already recolored, break
                    if col[v] != target_color:
                        break
                    # BFS to find (target_color, c) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (col[y] == target_color or col[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # check if swapping is safe: no neighbor of component has color c outside component
                    safe = True
                    for x in component:
                        for y in adj_list[x]:
                            if not visited[y] and col[y] == c:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # perform swap
                        for x in component:
                            if col[x] == target_color:
                                col[x] = c
                            elif col[x] == c:
                                col[x] = target_color
                        changed = True
                        break
            if changed:
                # compact colors: remap to 0..k-1
                # but we already try to keep colors small, so just return
                # actually, we should remap to ensure consecutive
                mapping = {}
                next_color = 0
                for i in range(n):
                    if col[i] not in mapping:
                        mapping[col[i]] = next_color
                        next_color += 1
                for i in range(n):
                    col[i] = mapping[col[i]]
        return col

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduction(best_coloring)
    except Exception:
        pass

    # Final validation and compacting
    # Ensure valid coloring
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # conflict, apply greedy fallback
                best_coloring = greedy_color(list(range(n)))
                break
        else:
            continue
        break

    # Compact colors to 0..k-1
    if best_coloring:
        mapping = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        for i in range(n):
            best_coloring[i] = mapping[best_coloring[i]]

    return best_coloring

