        final_col = best_coloring
    # Ensure consecutive colors
    mapping = {}
    next_color = 0
    for v in range(n):
        c = final_col[v]
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
        final_col[v] = mapping[c]
    return final_col

