    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fall back to greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            used = set()
            for w in adj_list[i]:
                if coloring[w] != -1:
                    used.add(coloring[w])
            c = 0
            while c in used:
                c += 1
            coloring[i] = c
        candidates.append(coloring)

    # Choose the candidate with fewest colors
    best = min(candidates, key=num_colors)
    best = compact_colors(best)

    # Apply Kempe chain reduction to try to improve
    best = reduce_colors_kempe(best)
    best = compact_colors(best)

    # Final validation (should be valid)
    if not is_valid(best):
        # As a last resort, return a greedy coloring
        coloring = [-1] * n
        for i in range(n):
            used = set()
            for w in adj_list[i]:
                if coloring[w] != -1:
                    used.add(coloring[w])
            c = 0
            while c in used:
                c += 1
            coloring[i] = c
        return compact_colors(coloring)

    return best

