        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = sat_mask[u].bit_count()
                deg = uncolored_deg[u]
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and random.random() < 0.5):
                    max_sat = sat
                    max_deg = deg
                    v = u
            # assign smallest available color
            used = sat_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat_mask[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in current uncolored subgraph
            deg_uncolored = {}
            for u in uncolored:
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg_uncolored[u] = cnt
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to S, W: adjacent to S
            U = set()
            W = set()
            for u in uncolored:
                adjacent = False
                for w in S:
                    if u in adj_list[w]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # grow independent set S
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = float('inf')
                for u in U:
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    # tie-break: min degree in G[U]
                    degU = 0
                    for w in adj_list[u]:
                        if w in U:
                            degU += 1
                    if score > best_score or (score == best_score and degU < best_degU):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
