        # compact colors: remap to 0..k-1
        # but we already use lower colors, so just reindex
        # collect used colors
        used_colors = set(col)
        if not used_colors:
            return [0]*n
        mapping = {}
        for i, c in enumerate(sorted(used_colors)):
