def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighborhood
        sat = [0] * n
        # neighbor color masks for fast saturation update
        neighbor_color_mask = [0] * n
        uncolored = set(range(n))
        # initial degree for tie-breaking
        degree = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # select uncolored vertex with max saturation, then max degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and degree[u] > max_deg):
                    max_sat = sat[u]
                    max_deg = degree[u]
                    v = u
                elif sat[u] == max_sat and degree[u] == max_deg and v == -1:
                    v = u  # fallback to first found
            if v == -1:
                v = next(iter(uncolored))

            # find smallest available color
            used = neighbor_color_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)

            # update saturation and neighbor color masks for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if not (neighbor_color_mask[u] & (1 << c)):
                        neighbor_color_mask[u] |= (1 << c)
                        sat[u] += 1
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # find vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                deg = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
            if v == -1:
                v = next(iter(uncolored))

            # build independent set S for color c
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent = False
                for w in S:
                    if u in adj_list[w]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)

            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = math.inf
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # tie-break: min degree in U
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if (w_neighbors > max_w_neighbors or
                        (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U)):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    best_u = next(iter(U))

                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        color = [-1] * n
        # copy of degrees for peeling
        degree = [len(adj_list[i]) for i in range(n)]
        # unpeeled set
        unpeeled = set(range(n))
        order = []  # will store peeled vertices in order

        for _ in range(n):
            # find vertex with minimum degree in unpeeled
            v = -1
            min_deg = math.inf
            for u in unpeeled:
                if degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                v = next(iter(unpeeled))
            order.append(v)
            unpeeled.remove(v)
            # decrease degree of neighbors
            for u in adj_list[v]:
                if u in unpeeled:
                    degree[u] -= 1

        # color in reverse peeling order
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_color = None
    min_colors = math.inf
    for col in candidates:
        # validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if u < v and color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        unique_colors = len(set(col))
        if unique_colors < min_colors:
            min_colors = unique_colors
            best_color = col

    # Fallback: if none valid (should not happen), use DSATUR
    if best_color is None:
        best_color = dsatur()

    # Compact colors to 0..k-1
    unique_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    compacted = [mapping[c] for c in best_color]

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        n_local = len(coloring)
        # adjacency as list of sets for fast lookup
        adj_set = [set(adj_list[i]) for i in range(n_local)]
        # continue until no improvement
        improved = True
        while improved:
            improved = False
            # color classes
            classes = [[] for _ in range(n_local)]  # upper bound
            for v in range(n_local):
                classes[coloring[v]].append(v)
            # find highest color used
            max_color = max(coloring) if n_local > 0 else -1
            # try to eliminate color classes from high to low
            for c in range(max_color, 0, -1):
                if not classes[c]:
                    continue
                # try to recolor each vertex in class c
                for v in classes[c]:
                    # try direct reassignment to lower color
                    for c2 in range(c):
                        conflict = False
                        for u in adj_set[v]:
                            if coloring[u] == c2:
                                conflict = True
                                break
                        if not conflict:
                            # move v to c2
                            coloring[v] = c2
                            classes[c].remove(v)
                            classes[c2].append(v)
                            improved = True
                            break
                    if improved:
                        break
                    # try Kempe chains with each lower color
                    for c2 in range(c):
                        # BFS to find (c, c2)-Kempe chain containing v
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        component = set()
                        while queue:
                            node = queue.popleft()
                            component.add(node)
                            for nb in adj_set[node]:
                                if nb not in visited and (coloring[nb] == c or coloring[nb] == c2):
                                    visited.add(nb)
                                    queue.append(nb)
                        # check if swapping this component would free color c2 for v
                        # actually, we want to see if after swap, v can take c2 without conflict
                        # but simpler: if the component does not contain any neighbor of v with color c2,
                        # then swapping will put v to c2 and not create conflict
                        has_c2_neighbor = False
                        for u in adj_set[v]:
                            if u in component and coloring[u] == c2:
                                has_c2_neighbor = True
                                break
                        if not has_c2_neighbor:
                            # perform swap: c <-> c2 in component
                            for node in component:
                                if coloring[node] == c:
                                    coloring[node] = c2
                                else:
                                    coloring[node] = c
                            # update classes
                            for node in component:
                                old_c = coloring[node]
                                if old_c == c2:
                                    classes[c].append(node)
                                    classes[c2].remove(node)
                                else:
                                    classes[c].remove(node)
                                    classes[c2].append(node)
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            # compact colors after each improvement pass
            if improved:
                unique_colors = sorted(set(coloring))
                mapping = {old: new for new, old in enumerate(unique_colors)}
                coloring = [mapping[c] for c in coloring]
        return coloring

    # Apply Kempe reduction
    best_color = kempe_reduction(best_color)

    # Final validation and compacting
    unique_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    final_color = [mapping[c] for c in best_color]

    # Double-check validity
    for u in range(n):
        for v in adj_list[u]:
            if u < v and final_color[u] == final_color[v]:
                # Should not happen, but fallback to greedy
                return dsatur()
    return final_color

import math
