def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    if is_matrix:
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        neighbors = [set(lst) for lst in adj]
    # Ensure symmetry
    for u in range(n):
        for v in neighbors[u]:
            neighbors[v].add(u)
    # Trivial cases
    if n == 1:
        return [0]
    # Check if edgeless
    has_edge = any(neighbors[u] for u in range(n))
    if not has_edge:
        return [0] * n
    # Check if complete
    is_complete = True
    for u in range(n):
        if len(neighbors[u]) != n - 1:
            is_complete = False
            break
    if is_complete:
        return list(range(n))
    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color
    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0
    # Helper: Welsh-Powell ordering (descending degree)
    def wp_order():
        return sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    # Helper: Smallest-Last (degeneracy) ordering
    def sl_order():
        if n == 0:
            return []
        deg = [len(neighbors[v]) for v in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for v in range(n):
            d = deg[v]
            if d < n:
                buckets[d].append(v)
        min_deg = 0
        for _ in range(n):
            while min_deg < n and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break
            v = buckets[min_deg].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    d = deg[u]
                    if d > 0:
                        deg[u] -= 1
                        buckets[deg[u]].append(u)
        return order[::-1]
    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if len(candidates) == 1:
                v = candidates[0]
            else:
                # Tie-break: max degree in uncolored subgraph
                v = max(candidates, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            # Assign smallest available color
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored and color[u] == -1:
                    # Check if this color is new for u's neighborhood
                    new = True
                    for w in neighbors[u]:
                        if color[w] == c and w != v:
                            new = False
                            break
                    if new:
                        sat[u] += 1
        return color
    # Helper: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set(uncolored - {v})
            W = set()
            for u in list(U):
                if any(w in S for w in neighbors[u]):
                    W.add(u)
                    U.remove(u)
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = None
                best_score = -1
                best_deg = None
                for u in U:
                    score = len([w for w in neighbors[u] if w in W])
                    deg_u = len([w for w in neighbors[u] if w in U])
                    if score > best_score or (score == best_score and (best_deg is None or deg_u < best_deg)):
                        best_score = score
                        best_deg = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in list(U):
                    if w in neighbors[u]:
                        W.add(w)
                        U.remove(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color
    # Generate candidate colorings
    candidates = []
    candidates.append(greedy_color(wp_order()))
    candidates.append(greedy_color(sl_order()))
    candidates.append(dsatur())
    candidates.append(rlf())
    # Choose the one with minimal number of colors
    best_coloring = min(candidates, key=num_colors)
    k = num_colors(best_coloring)
    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal k
        changed = True
        while changed and k > 1:
            changed = False
            # Target smallest color class (color k-1)
            target = k - 1
            # Find vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target]
            if not target_vertices:
                # Should not happen, but safety
                break
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = set()
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        used.add(coloring[u])
                for c in range(target):
                    if c not in used:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    # After moving v, check if target color class is empty
                    if not any(coloring[u] == target for u in range(n)):
                        # Compact colors: shift down all colors > target
                        for u in range(n):
                            if coloring[u] > target:
                                coloring[u] -= 1
                        k -= 1
                        break
                else:
                    # Try Kempe chain swap with each lower color
                    for c in range(target):
                        # Build (target, c)-Kempe chain containing v
                        # BFS/DFS over vertices colored target or c
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if coloring[node] == target or coloring[node] == c:
                                component.add(node)
                                for nb in neighbors[node]:
                                    if nb not in visited and (coloring[nb] == target or coloring[nb] == c):
                                        stack.append(nb)
                        # Check if swapping this component would free color c for v
                        # After swap, v would get color c (since v is in component and currently target)
                        # We need to ensure that no neighbor of v gets color c from the swap
                        # Actually, swapping means: target->c, c->target in the component.
                        # So neighbors of v that are in the component and colored c would become target.
                        # We need to check that after swap, no neighbor of v has color c.
                        # Neighbors of v that are in component and colored c become target -> safe.
                        # Neighbors of v not in component: if they are colored c, they stay c -> conflict.
                        # So we need that no neighbor of v outside the component is colored c.
                        conflict = False
                        for u in neighbors[v]:
                            if u not in component and coloring[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            # Perform swap
                            for node in component:
                                if coloring[node] == target:
                                    coloring[node] = c
                                else:  # must be c
                                    coloring[node] = target
                            changed = True
                            # After swap, check if target color class is empty
                            if not any(coloring[u] == target for u in range(n)):
                                for u in range(n):
                                    if coloring[u] > target:
                                        coloring[u] -= 1
                                k -= 1
                            break
                    if changed:
                        break
            # End for each target vertex
        return coloring
    best_coloring = kempe_reduce(best_coloring)
    # Validate coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Fallback: greedy on Welsh-Powell (should be valid)
                best_coloring = greedy_color(wp_order())
                break
        else:
            continue
        break
    # Ensure colors are consecutive starting from 0
    used_colors = set(best_coloring)
    if used_colors:
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        best_coloring = [mapping[c] for c in best_coloring]
    return best_coloring

