def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input type and convert to adjacency list
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # adjacency matrix
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        # adjacency list
        adj_list = [list(nei) for nei in adj]

    # Convert adjacency list to bitmask for fast operations
    bit_adj = [0] * n
    for i in range(n):
        for j in adj_list[i]:
            bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # Strategy 1: DSATUR
    def dsatur():
        color = [-1] * n
        saturation = [0] * n  # saturation degree
        # degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]

        # start with vertex of highest degree
        v = max(range(n), key=lambda i: degrees[i])
        color[v] = 0
        # update saturation of neighbors
        neighbors_v = adj_list[v]
        for u in neighbors_v:
            saturation[u] = 1  # neighbor of colored vertex with color 0

        for _ in range(1, n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            candidates = [-1]
            max_sat = -1
            for i in range(n):
                if color[i] == -1:
                    if saturation[i] > max_sat:
                        max_sat = saturation[i]
                        candidates = [i]
                    elif saturation[i] == max_sat:
                        candidates.append(i)
            # tie-break by degree in the uncolored subgraph
            if len(candidates) > 1:
                # degree in uncolored subgraph
                uncolored_deg = [0] * n
                for i in range(n):
                    if color[i] == -1:
                        cnt = 0
                        for u in adj_list[i]:
                            if color[u] == -1:
                                cnt += 1
                        uncolored_deg[i] = cnt
                v = max(candidates, key=lambda i: (uncolored_deg[i], i))
            else:
                v = candidates[0]
            # assign smallest available color
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            # update saturation of uncolored neighbors
            for u in adj_list[v]:
                if color[u] == -1:
                    # compute new saturation: number of distinct colors in neighbors
                    neighbor_colors = 0
                    for w in adj_list[u]:
                        if color[w] != -1:
                            neighbor_colors |= (1 << color[w])
                    saturation[u] = neighbor_colors.bit_count()
        return normalize(color)

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        current_color = 0
        uncolored = set(range(n))

        while uncolored:
            # Step 1: pick vertex with max degree in G[uncolored]
            max_deg = -1
            v0 = -1
            for v in uncolored:
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
            S = [v0]
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for v in uncolored:
                if v == v0:
                    continue
                adjacent = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(v)
                else:
                    U.add(v)

            # Step 2: while U not empty, select vertex with max neighbors in W
            while U:
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # tie-break: min degree in G[U]
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if (w_neighbors > max_w_neighbors or
                        (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U)):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                # add best_u to S
                S.append(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                color[v] = current_color
            uncolored -= set(S)
            current_color += 1
        return normalize(color)

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # we will remove min degree vertex each time
        for _ in range(n):
            # find vertex with min degree in remaining
            v = min(remaining, key=lambda x: degree[x])
            order.append(v)
            remaining.remove(v)
            # update degree of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    degree[u] -= 1
        # color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Run all strategies and pick the best
    strategies = [dsatur, rlf, smallest_last, welsh_powell]
    best_coloring = None
    best_k = float('inf')
    for strat in strategies:
        try:
            coloring = strat()
            if not is_valid(coloring):
                continue
            k = count_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring
        except Exception:
            continue

    # Fallback: if no strategy succeeded, use Welsh-Powell (should not happen)
    if best_coloring is None:
        best_coloring = welsh_powell()
        if not is_valid(best_coloring):
            # last resort: assign each vertex a unique color
            best_coloring = list(range(n))

    # Ensure colors are normalized and valid
    best_coloring = normalize(best_coloring)
    if not is_valid(best_coloring):
        # debug fallback
        best_coloring = list(range(n))
    return best_coloring

