            v = max(uncolored, key=lambda x: deg_uncolored[x])
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = {u for u in uncolored if u != v and not any(w in graph[u] for w in independent_set)}
            W = {u for u in uncolored if u not in independent_set and u not in U}
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = sum(1 for w in graph[u] if w in W)
                    if score > best_score or (score == best_score and (best_u is None or len([x for x in graph[u] if x in U]) < len([x for x in graph[best_u] if x in U]))):
                        best_score = score
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in graph[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        degrees = [len(graph[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointers to current non-empty bucket
        ptr = 0
        # Copy of degrees for modification
        deg = degrees[:]
        for _ in range(n):
            # Find first non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            # Update neighbors
            for u in graph[v]:
                if deg[u] > ptr:  # only if u not yet removed
                    # Move u from bucket deg[u] to deg[u]-1
                    if u in buckets[deg[u]]:
                        buckets[deg[u]].remove(u)
                    deg[u] -= 1
                    if deg[u] <= max_deg:
                        buckets[deg[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidates
    start_time = time.time()
    candidates = []
    # DSATUR
    if time.time() - start_time < 0.04:  # leave some buffer
        col = dsatur()
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]
    # RLF
    if time.time() - start_time < 0.04:
        col = rlf()
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]
    # Smallest-Last
    if time.time() - start_time < 0.04:
        col = smallest_last()
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]

    # If no candidate (should not happen), fallback to greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # 4. Kempe chain color reduction
    def kempe_reduction(coloring):
        nonlocal best_k, best_coloring
        # Try to reduce colors iteratively
        improved = True
        while improved and best_k > 1:
            improved = False
            # Find smallest color class (highest color index that is used)
            # We try to eliminate the highest color first
            max_color = max(coloring)
            # Try to eliminate colors from max_color down to 1
            for target_color in range(max_color, 0, -1):
                # Get vertices with target_color
                verts = [v for v in range(n) if coloring[v] == target_color]
                if not verts:
                    continue
                # Try to recolor each vertex in this class
                made_progress = False
                for v in verts:
                    # Try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in graph[v]:
                        if coloring[u] != -1:
                            neighbor_colors.add(coloring[u])
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            # Move v to color c
                            coloring[v] = c
                            made_progress = True
                            break
                    if made_progress:
                        break
                    # Try Kempe chains with each lower color
                    for c in range(target_color):
                        if c in neighbor_colors:
                            continue  # Skip if direct neighbor has color c (would cause conflict after swap)
                        # Build (target_color, c)-Kempe chain containing v
                        # We'll do BFS to get the component
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for u in graph[node]:
                                if not visited[u] and (coloring[u] == target_color or coloring[u] == c):
                                    visited[u] = True
                                    queue.append(u)
                        # Check if swapping colors in component is safe:
                        # After swap, no adjacent vertices should have same color
                        # Since we only swap target_color and c, and we know v has no neighbor with color c,
                        # the only potential issue is if a vertex in component has a neighbor outside
                        # the component with color c (which would become target_color after swap) or
                        # a vertex outside has color target_color and adjacent to component (would become c)
                        # But by definition of Kempe chain, we only include vertices connected via alternating colors,
                        # so any edge from component to outside must have both endpoints same color? Not exactly.
                        # Actually, the condition for a safe swap is that there is no edge between the component
                        # and a vertex colored with the other color that would cause conflict.
                        # However, in the standard Kempe chain argument for planar graphs, swapping a component
                        # always preserves validity. Let's verify:
                        # For any edge (x,y):
                        # - If both in component: colors swap, so if they were different, still different.
                        # - If both out: unchanged.
                        # - If one in (x) and one out (y):
                        #   * If coloring[x] == target_color, then after swap it becomes c.
                        #     For validity, we need coloring[y] != c.
                        #     But if coloring[y] == c, then y would have been included in the component (since x is target_color and y is c, and edge exists).
                        #     Contradiction. So coloring[y] != c.
                        #   * Similarly, if coloring[x] == c, after swap becomes target_color, and coloring[y] != target_color (otherwise y would be in component).
                        # Therefore, the swap is always safe.
                        # Perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        made_progress = True
                        break
                    if made_progress:
                        break
                if made_progress:
                    improved = True
                    # Compact colors: relabel to 0..k-1
                    # But we break to restart the while loop to recompute color classes
                    break
            # After attempting to eliminate a color, if we made progress, we break to restart
            if improved:
                # Recompute max color and continue
                pass
        # Final compacting: ensure colors are 0..k-1
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for v in range(n):
            c = coloring[v]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[v] = unique_colors[c]
        return coloring

    # Apply Kempe reduction
    if time.time() - start_time < 0.045:
        best_coloring = kempe_reduction(best_coloring[:])
        best_k = num_colors(best_coloring)

    # Final validation and compacting (ensure 0-indexed consecutive)
    if best_coloring is not None:
        # Compact colors
        unique_colors = {}
        next_color = 0
        for v in range(n):
            c = best_coloring[v]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_coloring[v] = unique_colors[c]
        # Validate
        if not is_valid(best_coloring):
            # Fallback to greedy
            best_coloring = greedy_color(list(range(n)))
            unique_colors = {}
            next_color = 0
            for v in range(n):
                c = best_coloring[v]
                if c not in unique_colors:
                    unique_colors[c] = next_color
                    next_color += 1
                best_coloring[v] = unique_colors[c]

    return best_coloring

