def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Convert to adjacency list if needed
    if isinstance(adj[0], list) and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for x in adj[0]):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Adjacency list
        adj_list = adj
        # Ensure it's a list of lists and symmetric (undirected)
        for i in range(n):
            adj_list[i] = [j for j in adj_list[i] if 0 <= j < n and j != i]

    # Handle trivial cases
    if n == 1:
        return [0]

    # Compute degrees
    degrees = [len(adj_list[i]) for i in range(n)]
    if max(degrees) == 0:
        return [0] * n

    # k-core decomposition
    core = [0] * n
    deg = degrees[:]
    order = []
    # Use bucket sort for efficiency
    max_deg = max(deg) if deg else 0
    buckets = [[] for _ in range(max_deg + 1)]
    for v in range(n):
        if deg[v] < len(buckets):
            buckets[deg[v]].append(v)
        else:
            # Extend buckets if necessary (should not happen with max_deg)
            buckets.extend([[] for _ in range(deg[v] - len(buckets) + 1)])
            buckets[deg[v]].append(v)

    pos = [0] * n
    for v in range(n):
        pos[v] = len(buckets[deg[v]]) - 1 - buckets[deg[v]][::-1].index(v) if v in buckets[deg[v]] else 0

    # Main peeling loop
    for _ in range(n):
        # Find min degree vertex
        d = 0
        while d < len(buckets) and not buckets[d]:
            d += 1
        if d >= len(buckets):
            break
        # Get a vertex from bucket[d]
        while buckets[d] and pos[buckets[d][-1]] != len(buckets[d]) - 1:
            buckets[d].pop()
        if not buckets[d]:
            d += 1
            while d < len(buckets) and not buckets[d]:
                d += 1
            if d >= len(buckets):
                break
        v = buckets[d].pop()
        pos[v] = len(buckets[d])  # invalidate position
        order.append(v)
        core[v] = d
        # Update neighbors
        for u in adj_list[v]:
            if core[u] == 0:  # not yet removed
                # Remove u from its current bucket
                old_deg = deg[u]
                if pos[u] < len(buckets[old_deg]):
                    buckets[old_deg][pos[u]] = buckets[old_deg][-1]
                    if buckets[old_deg]:
                        pos[buckets[old_deg][-1]] = pos[u]
                buckets[old_deg].pop()
                # Decrease degree
                deg[u] -= 1
                if deg[u] < 0:
                    deg[u] = 0
                # Add to new bucket
                if deg[u] < len(buckets):
                    buckets[deg[u]].append(u)
                    pos[u] = len(buckets[deg[u]]) - 1
                else:
                    buckets.extend([[] for _ in range(deg[u] - len(buckets) + 1)])
                    buckets[deg[u]].append(u)
                    pos[u] = len(buckets[deg[u]]) - 1

    # If any vertex not processed (should not happen), assign core 0
    for i in range(n):
        if core[i] == 0:
            core[i] = 0

    # Order vertices by increasing core number (outer to inner)
    vertices_by_core = list(range(n))
    vertices_by_core.sort(key=lambda v: (core[v], degrees[v], v))

    # Greedy coloring in this order
    color = [-1] * n
    for v in vertices_by_core:
        # Find colors used by neighbors
        neighbor_colors = set()
        for u in adj_list[v]:
            if color[u] != -1:
                neighbor_colors.add(color[u])
        # Assign smallest available color
        c = 0
        while c in neighbor_colors:
            c += 1
        color[v] = c

    # Compact colors (ensure 0..k-1)
    unique_colors = sorted(set(color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    return color

