        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Convert adjacency list to bit masks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if graph is bipartite and return 2-coloring if possible
    def is_bipartite():
        color_arr = [-1] * n
        for start in range(n):
            if color_arr[start] != -1:
                continue
            queue = [start]
            color_arr[start] = 0
            while queue:
                u = queue.pop(0)
                for v in adj_list[u]:
                    if color_arr[v] == -1:
                        color_arr[v] = color_arr[u] ^ 1
                        queue.append(v)
                    elif color_arr[v] == color_arr[u]:
                        return False, None
        return True, color_arr

    bip_ok, bip_color = is_bipartite()
    if bip_ok:
        return bip_color

    # DSATUR implementation with bit masks
    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph (for tie-breaking)
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, then max degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                if s > best_sat or (s == best_sat and uncolored_deg[v] > best_deg) or \
                   (s == best_sat and uncolored_deg[v] == best_deg and (best_v == -1 or v < best_v)):
                    best_sat = s
                    best_deg = uncolored_deg[v]
                    best_v = v
            v = best_v
            # find smallest color not used by neighbors
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return colors

    # RLF implementation
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # build maximal independent set for color_idx
            # start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u != v and v not in adj_list[u]}
            W = {u for u in uncolored if u != v and v in adj_list[u]}

            while U:
                # select u in U with max neighbors in W, then min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    u_deg = sum(1 for x in adj_list[u] if x in U)
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or \
                       (w_neighbors == best_w_neighbors and u_deg == best_u_deg and (best_u == -1 or u < best_u)):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color
            for vertex in independent_set:
                colors[vertex] = color_idx
                uncolored.remove(vertex)
            color_idx += 1
        return colors

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)

        for _ in range(n):
            # find first non-empty bucket
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
            if i > max_deg:
                break
            v = buckets[i].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Kempe chain swap for (a,b)
    def kempe_swap(colors, a, b, vertex):
        # returns new colors if we swap the component containing vertex, else None
        stack = [vertex]
        visited = set()
        comp_a = set()
        comp_b = set()
        target_color = colors[vertex]
        other_color = a if target_color == b else b
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if colors[u] == target_color:
                comp_a.add(u)
            elif colors[u] == other_color:
                comp_b.add(u)
            else:
                continue
            for w in adj_list[u]:
                if w not in visited and (colors[w] == target_color or colors[w] == other_color):
                    stack.append(w)
        # Check if swapping is safe: no neighbor outside comp has color other_color for vertices in comp_a
        # Actually, swapping preserves validity always for Kempe chain
        new_colors = colors[:]
        for u in comp_a:
            new_colors[u] = other_color
        for u in comp_b:
            new_colors[u] = target_color
        return new_colors

    # Try to eliminate a color class using Kempe chains
    def reduce_colors(colors):
        # make colors consecutive
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        colors = [mapping[c] for c in colors]
        max_color = max(colors) if colors else -1

        changed = True
        while changed and max_color > 0:
            changed = False
            # find smallest color class
            class_size = [0] * (max_color + 1)
            for c in colors:
                class_size[c] += 1
            # find smallest non-empty class
            target_color = -1
            min_size = float('inf')
            for c in range(max_color + 1):
                if 0 < class_size[c] < min_size:
                    min_size = class_size[c]
                    target_color = c
            if target_color == -1:
                break
            # try to recolor each vertex in target_color
            vertices = [i for i, c in enumerate(colors) if c == target_color]
            for v in vertices:
                # try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # direct move possible
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    new_colors = kempe_swap(colors, target_color, c, v)
                    if new_colors is not None:
                        # check if the swap removed the target color from v (it should)
                        if new_colors[v] != target_color:
                            colors = new_colors
                            changed = True
                            break
                if changed:
                    break
            if changed:
                # remap colors to be consecutive
                mapping = {}
                next_color = 0
                for c in colors:
                    if c not in mapping:
                        mapping[c] = next_color
                        next_color += 1
                colors = [mapping[c] for c in colors]
                max_color = max(colors) if colors else -1
        return colors

    # Run multiple heuristics
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # select best candidate (fewest colors)
    best = None
    best_colors = float('inf')
    for col in candidates:
        # validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if u < v and col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        num_colors = len(set(col))
        if num_colors < best_colors:
            best_colors = num_colors
            best = col

    if best is None:
        # fallback to greedy
        best = [0] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if best[j] != -1:
                    used |= (1 << best[j])
            c = 0
            while used & (1 << c):
                c += 1
            best[i] = c

    # apply Kempe reduction
    best = reduce_colors(best)

    # final validation and remapping
    # ensure consecutive colors
    mapping = {}
    next_color = 0
    for c in best:
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
    best = [mapping[c] for c in best]

    return best

