def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = (len(adj) > 0 and len(adj[0]) == len(adj) and
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    # Bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_coloring(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Candidate 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        uncolored = set(range(n))
        # Initial degree for tie-breaking
        degrees = [len(adj_list[u]) for u in range(n)]

        while uncolored:
            # Select vertex with max saturation, break ties by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                deg = degrees[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                   (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
        return color

    # Candidate 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = []
            # Degree in current uncolored subgraph
            deg_in_uncolored = [0] * n
            for v in uncolored:
                cnt = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        cnt += 1
                deg_in_uncolored[v] = cnt

            # Start with vertex of max degree in uncolored
            v = max(uncolored, key=lambda x: deg_in_uncolored[x])
            S.append(v)
            uncolored.remove(v)
            # U: vertices not adjacent to S (eligible), W: adjacent to S (ineligible)
            U = set(uncolored)  # copy
            W = set()
            for u in adj_list[v]:
                if u in uncolored:
                    W.add(u)
                    if u in U:
                        U.remove(u)

            while U:
                # Select u in U with max neighbors in W, break ties by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                uncolored.remove(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in uncolored and w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

    # Candidate 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Core decomposition to get removal order
        degree = [len(adj_list[u]) for u in range(n)]
        # Bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d < len(buckets):
                buckets[d].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        order = []
        # Current degree (will be updated)
        curr_degree = degree[:]
        removed = [False] * n

        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            while removed[v]:
                if not buckets[ptr]:
                    ptr += 1
                    while ptr <= max_deg and not buckets[ptr]:
                        ptr += 1
                    if ptr > max_deg:
                        break
                    v = buckets[ptr].pop()
                else:
                    break
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = curr_degree[u]
                    if d < len(buckets):
                        buckets[d].remove(u)
                    curr_degree[u] -= 1
                    d_new = curr_degree[u]
                    if d_new < len(buckets):
                        buckets[d_new].append(u)
                    # Update ptr if necessary
                    if d_new < ptr:
                        ptr = d_new
        # Color in reverse removal order
        return greedy_coloring(order[::-1])

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except:
        pass

    # Select best candidate (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        k = count_colors(col)
        if k < best_k:
            best_k = k
            best_coloring = col

    # If no candidate succeeded, fall back to simple greedy
    if best_coloring is None:
        best_coloring = greedy_coloring(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduction(coloring):
        # Ensure colors are consecutive
        def renormalize(col):
            mapping = {}
            next_color = 0
            for c in col:
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
            return [mapping[c] for c in col]

        coloring = renormalize(coloring)
        n = len(coloring)
        # Try to eliminate color classes from highest downward
        improved = True
        while improved:
            improved = False
            # Find current max color
            max_color = max(coloring) if n > 0 else -1
            for target_color in range(max_color, -1, -1):
                # Collect vertices with target_color
                verts = [v for v in range(n) if coloring[v] == target_color]
                if not verts:
                    continue
                # Try to recolor each vertex in this class
                for v in verts:
                    # Try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in adj_list[v]:
                        c = coloring[u]
                        if c != -1:
                            neighbor_colors.add(c)
                    for c in range(target_color):  # only try lower colors
                        if c not in neighbor_colors:
                            # Move v to color c
                            coloring[v] = c
                            improved = True
                            break
                    if improved:
                        break  # restart scan after change
                    # Try Kempe chain swap with each lower color
                    for c in range(target_color):
                        if c in neighbor_colors:
                            continue  # skip if color already used by neighbor (would conflict after swap)
                        # Find the Kempe chain component of v in colors {target_color, c}
                        # We'll do BFS/DFS to get the component containing v
                        stack = [v]
                        visited = set([v])
                        component = set()
                        while stack:
                            node = stack.pop()
                            component.add(node)
                            for u in adj_list[node]:
                                if coloring[u] == target_color or coloring[u] == c:
                                    if u not in visited:
                                        visited.add(u)
                                        stack.append(u)
                        # Check if swapping this component is safe: 
                        # After swap, no two adjacent vertices should have same color.
                        # Since we only swap target_color<->c, and the component is connected via these colors,
                        # the only potential conflict is if a vertex in the component has a neighbor
                        # outside the component with color equal to the swapped color.
                        # Specifically:
                        #   - If a vertex in component colored target_color has a neighbor outside with color c -> after swap, that neighbor is c and vertex becomes c -> conflict.
                        #   - Similarly, if a vertex in component colored c has a neighbor outside with color target_color -> conflict.
                        # So we need to ensure:
                        #   For all vertices in component:
                        #       if colored target_color, no neighbor outside has color c
                        #       if colored c, no neighbor outside has color target_color
                        safe = True
                        for node in component:
                            col_node = coloring[node]
                            for u in adj_list[node]:
                                if u not in component:
                                    col_u = coloring[u]
                                    if col_node == target_color and col_u == c:
                                        safe = False
                                        break
                                    if col_node == c and col_u == target_color:
                                        safe = False
                                        break
                            if not safe:
                                break
                        if safe:
                            # Perform the swap
                            for node in component:
                                if coloring[node] == target_color:
                                    coloring[node] = c
                                else:  # must be c
                                    coloring[node] = target_color
                            improved = True
                            break  # break from color c loop
                    if improved:
                        break  # break from vertex loop
                if improved:
                    break  # break from target_color loop
            if improved:
                # Renormalize to keep colors consecutive
                coloring = renormalize(coloring)
        return coloring

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduction(best_coloring)
    except:
        pass  # fallback to current best if reduction fails

    # Final validation and renormalization
    def renormalize(col):
        if not col:
            return col
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]

    best_coloring = renormalize(best_coloring)

    # Validate coloring (debugging aid, can be removed for speed)
