def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = (len(adj) > 0 and len(adj[0]) == n and
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    # Build adjacency list and bitmask
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # Heuristic 1: DSATUR with bitmask
    def dsatur():
        coloring = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                # count distinct colors in sat[u]
                # since we use bitmask, count bits
                s = sat[u].bit_count()
                d = uncolored_deg[u]
                if s > max_sat or (s == max_sat and d > max_deg) or (s == max_sat and d == max_deg and random.random() < 0.5):
                    max_sat = s
                    max_deg = d
                    v = u
            if v == -1:
                v = next(iter(uncolored))

            # find smallest color not in neighbors
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # update neighbors
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1

        return normalize(coloring)

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # build maximal independent set for this color
            S = []  # independent set
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set(uncolored)
            W = set()

            # start with vertex of max degree in uncolored subgraph
            if U:
                v = max(U, key=lambda x: sum(1 for y in adj_list[x] if y in U))
                S.append(v)
                U.remove(v)
                # move neighbors of v from U to W
                for y in adj_list[v]:
                    if y in U:
                        U.remove(y)
                        W.add(y)

