                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_count = sum(1 for y in adj_list[u] if y in W)
                    # degree in U
                    deg_in_U = sum(1 for y in adj_list[u] if y in U)
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    best_u = next(iter(U))

                S.append(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for y in adj_list[best_u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)

            # assign color to all in S
            for v in S:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return normalize(coloring)

    # Heuristic 3: Smallest-Last ordering
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []

        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)

        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    buckets[d].remove(u)
                    buckets[d-1].append(u)
                    if d-1 < min_deg:
                        min_deg = d-1

        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return normalize(coloring)

    # Heuristic 4: Jaccard-based heuristic for non-adjacent pairs
    def jaccard_heuristic():
        # Precompute Jaccard similarity for non-adjacent pairs
        # Only consider pairs (i, j) where i < j and not adjacent
        similarities = []
        for i in range(n):
            for j in range(i+1, n):
                # check if adjacent
                if j in adj_list[i]:  # adjacency list check
                    continue
                # compute Jaccard similarity: |N(i) ∩ N(j)| / |N(i) ∪ N(j)|
                set_i = set(adj_list[i])
                set_j = set(adj_list[j])
                intersection = len(set_i & set_j)
                union = len(set_i | set_j)
                if union == 0:
                    sim = 0.0
                else:
                    sim = intersection / union
                similarities.append((sim, i, j))

        # sort by similarity descending
        similarities.sort(key=lambda x: x[0], reverse=True)

        # greedy coloring: try to assign same color to high-similarity non-adjacent pairs
        coloring = [-1] * n
        # we'll process pairs and try to merge color classes
        # but simpler: use DSATUR but with initial ordering by similarity
        # Create vertex ordering: vertices involved in high-similarity pairs first
        vertex_score = [0.0] * n
        for sim, i, j in similarities:
            vertex_score[i] += sim
            vertex_score[j] += sim

        # order by score descending, then degree
        order = sorted(range(n), key=lambda v: (vertex_score[v], len(adj_list[v])), reverse=True)

        # greedy coloring in this order
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return normalize(coloring)

    # Run all heuristics and collect candidates
    candidates = []
    start_time = time.time()

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # Jaccard heuristic
    try:
        c4 = jaccard_heuristic()
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass

    # Fallback: greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda v: len(adj_list[v]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        candidates.append(normalize(coloring))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)

    # Try to reduce colors using Kempe chain swaps
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # get vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue

            # Try to recolor each vertex to a lower color
            changed = True
            while changed and verts:
                changed = False
                new_verts = []
                for v in verts:
                    # try direct reassignment to lower colors
                    recolored = False
                    for c in range(target_color):
                        # check if color c is available
                        conflict = False
                        for u in adj_list[v]:
                            if coloring[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            # check if moving v to c would cause any vertex of color c to become recolorable to target_color?
                            # Actually, we just move it; we'll handle chains later
                            coloring[v] = c
                            recolored = True
                            changed = True
                            break
                    if not recolored:
                        new_verts.append(v)
                verts = new_verts

            # if all vertices of target_color are recolored, we can drop this color
            if not any(v for v in range(n) if coloring[v] == target_color):
                # remap colors: shift down all colors > target_color
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                # recursively try to reduce further
                return reduce_colors(coloring)

        return coloring

    # Apply color reduction
    best = reduce_colors(best)
    # Ensure normalized
    best = normalize(best)

    # Final validation (should always hold)
    if not is_valid(best):
        # last resort: DSATUR
        best = dsatur()

    return best

import math
