import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # Helper: count number of colors used
    def count_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: normalize colors to 0..k-1
    def normalize(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        # Precompute degrees
        degrees = [len(adj_list[u]) for u in range(n)]

        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            candidates = []
            max_sat = -1
            for u in uncolored:
                sat = saturated[u]
                if sat > max_sat:
                    max_sat = sat
                    candidates = [u]
                elif sat == max_sat:
                    candidates.append(u)
            # Tie-break by degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                final_candidates = []
                for u in candidates:
                    deg = sum(1 for v in adj_list[u] if v in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        final_candidates = [u]
                    elif deg == max_deg:
                        final_candidates.append(u)
                u = random.choice(final_candidates)
            else:
                u = candidates[0]

            # Assign smallest available color
            used = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
            uncolored.remove(u)

            # Update saturation of uncolored neighbors
            for v in adj_list[u]:
                if v in uncolored:
                    # Recompute saturation: number of distinct colors in neighbors
                    neighbor_colors = set()
                    for w in adj_list[v]:
                        if colors[w] != -1:
                            neighbor_colors.add(colors[w])
                    saturated[v] = len(neighbor_colors)
        return colors

    # RLF: Recursive Largest First
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # Find vertex with max degree in G[uncolored]
            max_deg = -1
            start = None
            for u in uncolored:
                deg = sum(1 for v in adj_list[u] if v in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    start = u
            S = {start}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for v in uncolored:
                if v == start:
                    continue
                if any((bit_adj[u] >> v) & 1 for u in S):
                    W.add(v)
                else:
                    U.add(v)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = 0
                    for v in adj_list[u]:
                        if v in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break: min degree in G[U]
                        deg_u = sum(1 for v in adj_list[u] if v in U)
                        deg_best = sum(1 for v in adj_list[best_u] if v in U) if best_u is not None else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for v in adj_list[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color to all in S
            for u in S:
                colors[u] = color
                uncolored.remove(u)
            color += 1
        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Peel vertices of minimum degree
        order = []
        remaining = set(range(n))
        deg = [len(adj_list[u]) for u in range(n)]
        # We'll simulate peeling
        while remaining:
            # Find vertex with minimum degree in remaining subgraph
            min_deg = float('inf')
            v_min = None
            for u in remaining:
                # current degree in remaining subgraph
                d = sum(1 for v in adj_list[u] if v in remaining)
                if d < min_deg:
                    min_deg = d
                    v_min = u
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors (optional, but we recompute each time)
        # Color in reverse peeling order
        return greedy_color(list(reversed(order)))

    # Welsh-Powell: sort by degree descending
    def welsh_powell():
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    start_time = time.time()
    # DSATUR
    if time.time() - start_time < 0.04:  # 40ms budget for heuristics
        col = dsatur()
        if is_valid(col):
            candidates.append((count_colors(col), col))
    # RLF
    if time.time() - start_time < 0.04:
        col = rlf()
        if is_valid(col):
            candidates.append((count_colors(col), col))
    # Smallest-Last
    if time.time() - start_time < 0.04:
        col = smallest_last()
        if is_valid(col):
            candidates.append((count_colors(col), col))
    # Welsh-Powell
    if time.time() - start_time < 0.04:
        col = welsh_powell()
        if is_valid(col):
            candidates.append((count_colors(col), col))

    if not candidates:
        # Fallback: trivial coloring (each vertex unique color)
        col = list(range(n))
        candidates.append((n, col))

    # Select best candidate (fewest colors)
    best_count, best_coloring = min(candidates, key=lambda x: x[0])
    best_coloring = normalize(best_coloring)  # ensure 0..k-1

    # Try to reduce colors via Kempe chain swaps (target smallest color class)
    k = best_count
    if k <= 1:
        return best_coloring

    # We'll attempt to eliminate color k-1, then k-2, etc.
    # But limit attempts to avoid timeout
    max_reduction_steps = 10
    reduction_step = 0
    while reduction_step < max_reduction_steps and k > 1:
        target_color = k - 1
        # Get vertices with target_color
        target_vertices = [u for u in range(n) if best_coloring[u] == target_color]
        if not target_vertices:
            # Already empty, compact
            k -= 1
            # Remap colors: all colors > target_color shift down
            for u in range(n):
                if best_coloring[u] > target_color:
                    best_coloring[u] -= 1
            continue

        # Try to recolor each target vertex to a lower color
        made_progress = False
        random.shuffle(target_vertices)  # randomize order
        for v in target_vertices:
            # Try direct reassignment to any color < target_color
            used_colors = set()
            for u in adj_list[v]:
                if best_coloring[u] < target_color:
                    used_colors.add(best_coloring[u])
            for c in range(target_color):
                if c not in used_colors:
                    # Check if moving v to c causes any conflict (shouldn't by construction)
                    # But verify: neighbors of v should not have color c
                    conflict = False
                    for u in adj_list[v]:
                        if best_coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        best_coloring[v] = c
                        made_progress = True
                        break
            if made_progress:
                break

            # Try Kempe chain swap with each lower color
            for c in range(target_color):
                # We'll try to swap colors c and target_color in the component containing v
                # Only if v is not adjacent to any vertex of color c (otherwise swap invalid?)
                # Actually, we can still try: we need to check if the Kempe chain component
                # does not contain any neighbor of v that is colored c (to avoid creating conflict)
                # Standard approach: build the (c, target_color)-Kempe chain of v
                # If no neighbor of v in the chain has color c, then swapping is safe
                from collections import deque
                visited = [False] * n
                queue = deque([v])
                visited[v] = True
                component = []
                has_c_neighbor = False  # does component have a vertex of color c adjacent to v?
                while queue:
                    u = queue.popleft()
                    component.append(u)
                    for w in adj_list[u]:
                        if not visited[w] and (best_coloring[w] == c or best_coloring[w] == target_color):
                            visited[w] = True
                            queue.append(w)
                # Check if any neighbor of v in the component has color c
                for u in component:
                    if u == v:
                        continue
                    if best_coloring[u] == c:
                        # Check if u is adjacent to v? Actually, we need to see if swapping would cause v to conflict
                        # After swap, v gets color c. We need to ensure no neighbor of v has color c.
                        # If u is in the component and has color c, and u is adjacent to v, then conflict.
                        if v in adj_list[u]:  # or u in adj_list[v]
                            has_c_neighbor = True
                            break
                if not has_c_neighbor:
                    # Perform swap: swap colors c and target_color in component
                    for u in component:
                        if best_coloring[u] == c:
                            best_coloring[u] = target_color
                        elif best_coloring[u] == target_color:
                            best_coloring[u] = c
                    made_progress = True
                    break
            if made_progress:
                break

        if not made_progress:
            # Could not reduce this color, break
            break
        else:
            # After recoloring, check if target_color class is empty
            if any(best_coloring[u] == target_color for u in range(n)):
                # Still some vertices have target_color, try again in next iteration?
                # For safety, we break to avoid infinite loop
                break
            else:
                # Successfully eliminated target_color
                k -= 1
                # Remap colors: all colors > target_color shift down
                for u in range(n):
                    if best_coloring[u] > target_color:
                        best_coloring[u] -= 1
        reduction_step += 1

    # Final validation and normalization
    if not is_valid(best_coloring):
        # Fallback to best candidate if something went wrong
        best_coloring = normalize(best_coloring)
    else:
        best_coloring = normalize(best_coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
