    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper function to validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper function to compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR algorithm
    def dsatur():
        colors = [-1] * n
        # Precompute degrees
        degrees = [len(adj_list[i]) for i in range(n)]
        # Track saturation sets as bitmasks
        saturation = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = sum(1 for u in adj_list[v] if u in uncolored)
                elif sat == best_sat:
                    deg = sum(1 for u in adj_list[v] if u in uncolored)
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
                    elif deg == best_deg:
                        if random.random() < 0.5:
                            best_v = v
            v = best_v
            # Find smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
        return compact_colors(colors)

    # RLF algorithm
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build maximal independent set for this color
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S.add(v)
            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = uncolored - S
            W = set()
            for u in list(U):
                if any(w in S for w in adj_list[u]):
                    W.add(u)
                    U.remove(u)

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U subgraph
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = -1
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    if w_neighbors > best_w_neighbors:
                        best_w_neighbors = w_neighbors
                        best_u = u
                        best_deg_u = sum(1 for x in adj_list[u] if x in U)
                    elif w_neighbors == best_w_neighbors:
                        deg_u = sum(1 for x in adj_list[u] if x in U)
                        if deg_u < best_deg_u:
                            best_deg_u = deg_u
                            best_u = u
                        elif deg_u == best_deg_u:
                            if random.random() < 0.5:
                                best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                colors[v] = color_idx
            uncolored -= S
            color_idx += 1

        return compact_colors(colors)

    # Smallest-Last greedy (Matula-Beck ordering)
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering (smallest-last)
        degrees = [len(adj_list[i]) for i in range(n)]
        # We'll use a list of sets for each degree
        max_deg = max(degrees) if n > 0 else 0
        bins = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degrees[v]
            if d <= max_deg:
                bins[d].add(v)
        # Track current degree and position
        curr_deg = degrees[:]
        order = []
        # For each vertex to remove
        for _ in range(n):
            # Find first non-empty bin
            d = 0
            while d <= max_deg and not bins[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            v = bins[d].pop()
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if curr_deg[u] > d:  # only if u not yet removed
                    # remove u from its current bin
                    old_deg = curr_deg[u]
                    if old_deg <= max_deg and u in bins[old_deg]:
                        bins[old_deg].remove(u)
                    curr_deg[u] -= 1
                    new_deg = curr_deg[u]
                    if new_deg <= max_deg:
                        bins[new_deg].add(u)
        # Color in reverse order using greedy
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        if not is_valid_coloring(colors):
            return colors  # should not happen if input is valid
        k = max(colors) + 1 if n > 0 else 0
        # Try to reduce colors from k down to 1
        improved = True
        while improved and k > 1:
            improved = False
            # Find smallest color class (highest color index)
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[colors[v]].append(v)
            # Start from highest color and go down
            for c in range(k-1, -1, -1):
                if not color_classes[c]:
                    continue
                # Try to eliminate color c
                # For each vertex in color c, try to recolor to a lower color
                eliminated = True
                for v in color_classes[c][:]:  # iterate over copy
                    # Try direct reassignment to a lower color
