                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue
                neighbors[i].add(j)
                bit_adj[i] |= (1 << j)

