    is_matrix = (len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for x in adj[0]))
    if is_matrix:
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
