                        can_swap = True
                        for x in component:
                            for y in range(n):
                                if (bit_adj[x] >> y) & 1 and color[y] == c2 and y not in component:
                                    can_swap = False
                                    break
                            if not can_swap:
                                break
                        if can_swap:
                            # Swap colors c and c2 in component
                            for x in component:
                                if color[x] == c:
                                    color[x] = c2
                                elif color[x] == c2:
                                    color[x] = c
                            changed = True
                            # Update classes
                            classes[c] = [x for x in classes[c] if x not in component]
                            classes[c2] = [x for x in classes[c2] if x not in component]
                            for x in component:
                                if color[x] == c:
                                    classes[c].append(x)
                                elif color[x] == c2:
                                    classes[c2].append(x)
                            break
                    if changed:
                        break
                if changed:
