def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix or list
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Convert adjacency matrix to adjacency list
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        adj = adj_list
    else:
        # Ensure adjacency list format (make a copy to avoid side effects)
        adj = [list(neighbors) for neighbors in adj]

    # Precompute neighbor bitmasks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj[u]:
            bit_adj[u] |= (1 << v)

    # Helper: compute number of colors used in a coloring
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in adj[u]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor colors as bitmask for fast saturation update
        neighbor_colors = [0] * n
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, break ties by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > best_sat:
                    best_sat = sat_v
                    best_v = v
                    best_deg = sum(1 for u in adj[v] if u in uncolored)
                elif sat_v == best_sat:
                    deg_v = sum(1 for u in adj[v] if u in uncolored)
                    if deg_v > best_deg:
                        best_deg = deg_v
                        best_v = v
                    elif deg_v == best_deg:
                        if random.random() < 0.5:  # random tie-break
                            best_v = v
            v = best_v
            uncolored.remove(v)

            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation and neighbor colors for uncolored neighbors
            for u in adj[v]:
                if u in uncolored:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return coloring

    # Helper: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj[x] if y in uncolored))
            independent_set = {v}
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if not any(w in adj[u] for w in independent_set)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = sum(1 for w in adj[u] if w in W)
                    deg_U = sum(1 for w in adj[u] if w in U)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        best_deg_U = deg_U
                    elif score == best_score:
                        if deg_U < best_deg_U:
                            best_deg_U = deg_U
                            best_u = u
                        elif deg_U == best_deg_U:
                            if random.random() < 0.5:
                                best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in independent set
            for v in independent_set:
                coloring[v] = color
            color += 1
            uncolored = W  # next round
        return coloring

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degrees = [len(adj[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # We'll simulate removal
        temp_adj = [set(neighbors) for neighbors in adj]
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda x: len(temp_adj[x] & remaining))
            order.append(v)
            remaining.remove(v)
            # Remove v from neighbors' adjacency
            for u in temp_adj[v]:
                if u in remaining:
                    temp_adj[u].discard(v)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: simple greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(adj[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass
    # If no candidate (should not happen), assign all zeros (invalid but safe)
    if not candidates:
        return [0] * n

    # Select candidate with minimal number of colors
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Iterative color reduction via Kempe chains and direct reassignment
    improved = True
    while improved and k > 1:
        improved = False
        # Target the last color (k-1)
        target_color = k - 1
        # Vertices with target color
        target_vertices = [v for v in range(n) if best[v] == target_color]
        if not target_vertices:
            # Should not happen, but skip
            break
        # Try to recolor each target vertex
        for v in target_vertices:
            # Try direct reassignment to a lower color
            used_by_neighbors = 0
            for u in adj[v]:
                if best[u] < target_color:
                    used_by_neighbors |= (1 << best[u])
            for c in range(target_color):
                if not (used_by_neighbors & (1 << c)):
                    # Move v to color c
                    best[v] = c
                    improved = True
                    break
            if improved:
                # Recoloring succeeded, break to restart
                break
            # Try Kempe chain swap with each lower color
            for c in range(target_color):
                # Skip if v already has a neighbor with color c (direct move not possible, but Kempe might still work)
                # We'll attempt swap regardless
                # Find the Kempe chain component of v in colors {target_color, c}
                # BFS/DFS to get component
                stack = [v]
                visited = set()
                component = set()
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    if best[node] == target_color or best[node] == c:
                        component.add(node)
                        for nb in adj[node]:
                            if nb not in visited and (best[nb] == target_color or best[nb] == c):
                                stack.append(nb)
                # Check if any neighbor of v in the component has color c? Actually, we need to see if swapping
                # the component would cause a conflict: after swap, v would get color c, so we need that
                # no neighbor of v has color c after swap.
                # After swap, neighbors in component that were color c become target_color, and vice versa.
                # So, for a neighbor u of v:
                #   if u in component:
                #       if best[u] == c -> becomes target_color
                #       if best[u] == target_color -> becomes c
                #   else: color unchanged
                # We need that after swap, no neighbor of v has color c.
                # Currently, neighbors of v that are color c: if they are in component, they become target_color (safe)
                #   if not in component, they remain color c (conflict if v becomes c)
                # So, we need that no neighbor of v with color c is outside the component.
                conflict = False
                for u in adj[v]:
                    if best[u] == c and u not in component:
                        conflict = True
                        break
                if not conflict:
                    # Perform swap: invert colors in component
                    for node in component:
                        if best[node] == target_color:
                            best[node] = c
                        else:  # must be c
                            best[node] = target_color
                    improved = True
                    break
            if improved:
                break
        # After attempting to recolor target vertices, if we improved, we may have reduced k
        if improved:
            # Compact colors: reindex to 0..k'-1
            # But first, check if target color class is empty
            if not any(v == target_color for v in best):
                k -= 1
                # Reindex colors to be consecutive
                mapping = {}
                new_color = 0
                for old_color in sorted(set(best)):
                    mapping[old_color] = new_color
                    new_color += 1
                best = [mapping[c] for c in best]
            else:
                # Even if we didn't empty the class, we might have reduced max color via Kempe?
                # Recompute k
                new_k = num_colors(best)
                if new_k < k:
                    k = new_k
                # else, no improvement in k, but we might have improved coloring quality; continue to try again
        else:
            # No improvement in this round
            break

    # Final validation and compacting (ensure colors are 0..k-1)
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
    # Compact colors
    unique_colors = sorted(set(best))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best = [mapping[c] for c in best]

    return best

