            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Initial vertex: max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if len(candidates) == 1:
                v = candidates[0]
            else:
                # Tie-break: max degree in uncolored subgraph
                v = max(candidates, key=lambda x: len(neighbors[x] & uncolored))
            # Assign smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    # Check if color c is new for u's neighbors
                    new_sat = sat[u]
                    for w in neighbors[u]:
                        if color[w] == c:
                            new_sat += 1
                            break
                    # Actually, we need to count distinct colors in neighbors
                    # Recompute saturation for u from scratch (since n small)
                    distinct = set()
                    for w in neighbors[u]:
                        if color[w] != -1:
                            distinct.add(color[w])
                    sat[u] = len(distinct)
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = uncolored - {v} - (neighbors[v] & uncolored)
            W = neighbors[v] & uncolored
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = len(neighbors[u] & W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in G[U]
                        deg_u = len(neighbors[u] & U)
                        if best_u is None or deg_u < len(neighbors[best_u] & U):
                            best_u = u
                if best_u is None:
                    break  # should not happen
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                nbrs = neighbors[best_u] & U
                U -= nbrs
                W |= nbrs
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[v]) for v in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)
                    if degree[u] < ptr:
                        ptr = degree[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, v, a, b):
        if coloring[v] not in (a, b):
            return False, coloring
        stack = [v]
        visited = set()
        comp_color_a = set()
        comp_color_b = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            col = coloring[u]
            if col == a:
                comp_color_a.add(u)
            elif col == b:
                comp_color_b.add(u)
            for w in neighbors[u]:
                if w not in visited and coloring[w] in (a, b):
                    stack.append(w)
        # Check if we can swap: after swap, no conflict introduced?
        # Actually, swapping a component preserves validity.
        # We just perform the swap.
        new_coloring = coloring[:]
        for u in comp_color_a:
            new_coloring[u] = b
        for u in comp_color_b:
            new_coloring[u] = a
        return True, new_coloring

    # Try to eliminate the last color via Kempe chains or direct reassignment
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target = k - 1
        vertices = [v for v in range(n) if coloring[v] == target]
        # Try direct reassignment first
        for v in vertices:
            used = [False] * n
            for u in neighbors[v]:
                c = coloring[u]
                if c != -1:
                    used[c] = True
            for c in range(target):  # try colors 0..target-1
                if not used[c]:
                    # Recolor v to c
                    new_coloring = coloring[:]
                    new_coloring[v] = c
                    if is_valid(new_coloring):
                        return reduce_colors(new_coloring)  # recurse
        # Try Kempe chains: for each vertex in target color, try to swap with a lower color
        for v in vertices:
            for c in range(target):
                success, new_coloring = kempe_swap(coloring, v, target, c)
                if success and is_valid(new_coloring):
                    # After swap, check if target color class is reduced
                    # Actually, we just need to see if we can eliminate the color
                    # Recurse on the new coloring
                    reduced = reduce_colors(new_coloring)
                    if num_colors(reduced) < k:
                        return reduced
        return coloring  # cannot reduce

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except:
        pass
    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append(col_sl)
    except:
        pass

    # If no candidates, fallback to greedy by index
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = reduce_colors(best)
    # Ensure colors are compact
    # Remap colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best[i] = unique_colors[c]
    return best

