    is_matrix = (len(adj) > 0 and len(adj[0]) == n and 
                 all(isinstance(row, list) and len(row) == n and 
                     all(isinstance(x, int) and x in (0, 1) for x in row) 
                     for row in adj))

    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and 
                                        (bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1') > max_deg)):
                    max_sat = sat[u]
                    max_deg = bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1')
                    v = u
                elif sat[u] == max_sat:
                    deg_u = bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1')
                    if deg_u > max_deg:
                        max_deg = deg_u
                        v = u
            if v == -1:  # fallback
                v = next(iter(uncolored))

            # Assign smallest available color
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)

            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] = bin(bit_adj[u] & sum((1 << w) for w in uncolored if color[w] != -1)).count('1')
        return color

    # RLF: Recursive Largest First (independent set extraction)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0

        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in G[uncolored]
            v = max(uncolored, key=lambda u: bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1'))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v} - {w for w in adj_list[v] if w in uncolored}
            W = {w for w in adj_list[v] if w in uncolored}

            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = bin(bit_adj[u] & sum((1 << w) for w in W)).count('1')
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and 
                                                         bin(bit_adj[u] & sum((1 << w) for w in U)).count('1') < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = bin(bit_adj[u] & sum((1 << w) for w in U)).count('1')
                        u_star = u
                    elif w_neighbors == max_w_neighbors:
                        deg_u = bin(bit_adj[u] & sum((1 << w) for w in U)).count('1')
                        if deg_u < min_deg_in_U:
                            min_deg_in_U = deg_u
                            u_star = u
                if u_star == -1:
                    u_star = next(iter(U))

                independent_set.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degrees = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # We'll simulate removal
        temp_adj = [set(adj_list[i]) for i in range(n)]
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda u: len(temp_adj[u] & remaining))
            order.append(v)
            remaining.remove(v)
            # Remove v from neighbors' adjacency
            for u in temp_adj[v]:
                if u in remaining:
                    temp_adj[u].discard(v)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap for (a,b)
    def kempe_swap(coloring, a, b, vertex):
        # Returns new coloring after swapping a and b in the Kempe chain containing vertex
        # Only if vertex has color a or b
        if coloring[vertex] not in (a, b):
            return coloring
        # BFS to get the component
        from collections import deque
        q = deque([vertex])
        visited = set([vertex])
        comp_color_a = []
        comp_color_b = []
        while q:
            u = q.popleft()
            if coloring[u] == a:
                comp_color_a.append(u)
            elif coloring[u] == b:
                comp_color_b.append(u)
            for w in adj_list[u]:
                if w not in visited and coloring[w] in (a, b):
                    visited.add(w)
                    q.append(w)
        # Swap colors in the component
        new_coloring = coloring[:]
        for u in comp_color_a:
            new_coloring[u] = b
        for u in comp_color_b:
            new_coloring[u] = a
        return new_coloring

    # Try to eliminate the last color using Kempe chains or direct reassignment
    def reduce_colors(coloring):
        k = count_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target_color = k - 1
        vertices_target = [i for i in range(n) if coloring[i] == target_color]
        # Try direct reassignment first
        for v in vertices_target:
            used = 0
            for u in adj_list[v]:
