        saturation = [0] * n
        # Track neighbor colors as bitmask for fast saturation update
        neighbor_colors = [0] * n  # bitmask of colors used by neighbors

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    sat = saturation[u]
                    deg = degrees[u]
                    if sat > max_sat or (sat == max_sat and deg > max_deg) or \
                       (sat == max_sat and deg == max_deg and random.random() < 0.5):
                        max_sat = sat
                        max_deg = deg
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by neighbors
            used_by_neighbors = neighbor_colors[v]
            c = 0
            while used_by_neighbors & (1 << c):
                c += 1
            colors[v] = c

            # Update saturation and neighbor_colors for uncolored neighbors
            for u in adj_list[v]:
                if colors[u] == -1:
                    # Add color c to u's neighbor colors
                    neighbor_colors[u] |= (1 << c)
                    # Update saturation: count bits in neighbor_colors[u]
                    saturation[u] = neighbor_colors[u].bit_count()
        return normalize(colors)

    # Recursive Largest First (RLF) style independent set extraction
    def rlf():
