            color[v] = c
        candidates.append(color)

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=lambda x: max(x) + 1 if x else 0)

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # Make copy to work on
        color = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find color classes
            classes = {}
            for v in range(n):
                c = color[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)

            # Sort colors by class size
            sorted_colors = sorted(classes.keys(), key=lambda c: len(classes[c]))

            # Try to eliminate smallest color classes
            for c in sorted_colors:
                if c not in classes or len(classes[c]) == 0:
                    continue
                # Try to recolor each vertex in class c
                for v in classes[c][:]:  # copy list as we may modify
                    # Try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in adj_list[v]:
                        if color[u] != -1:
                            neighbor_colors.add(color[u])
                    for c_new in range(c):  # only try lower colors
                        if c_new not in neighbor_colors:
                            color[v] = c_new
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chains with each lower color
                    for c_new in range(c):
                        # Find (c, c_new)-Kempe chain containing v
                        visited = set()
                        stack = [v]
                        visited.add(v)
                        component = set()
                        while stack:
                            x = stack.pop()
                            component.add(x)
                            for y in adj_list[x]:
                                if color[y] == c or color[y] == c_new:
                                    if y not in visited:
                                        visited.add(y)
                                        stack.append(y)
                        # Check if we can swap: no neighbor of v has color c_new outside component
                        # Actually, swapping is always valid as it preserves coloring
                        # But we want to free color c for v, so after swap v will have c_new
                        # We need to ensure that after swap, v is not the only one that might cause issue? 
                        # Kempe swap is always valid, so we can do it and see if it reduces the need for color c
                        # Perform swap: in component, swap c and c_new
                        for x in component:
                            if color[x] == c:
                                color[x] = c_new
                            elif color[x] == c_new:
                                color[x] = c
                        changed = True
                        break
                    if changed:
                        break
                if changed:
                    break
            # Compact colors if possible
            if changed:
                # Remap colors to 0..k-1
                used_colors = set(color)
                mapping = {}
                for i, c in enumerate(sorted(used_colors)):
                    mapping[c] = i
                for i in range(n):
                    color[i] = mapping[color[i]]
        return color

    # Apply Kempe reduction
    try:
        improved = kempe_reduction(best_coloring)
        # Validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if u < v and improved[u] == improved[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            # Count colors in improved
            k_improved = max(improved) + 1 if improved else 0
            k_best = max(best_coloring) + 1 if best_coloring else 0
            if k_improved < k_best:
                best_coloring = improved
    except:
        pass

    # Final validation and compacting
    # Ensure valid
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Fallback to greedy
                order = sorted(range(n), key=lambda x: (-degree[x], x))
                color = [-1] * n
                for v in order:
                    used = [False] * n
                    for u in adj_list[v]:
                        if color[u] != -1:
                            used[color[u]] = True
                    c = 0
                    while c < n and used[c]:
                        c += 1
                    color[v] = c
                best_coloring = color
                break

    # Compact colors to 0..k-1
    used_colors = set(best_coloring)
    if used_colors:
        mapping = {c: i for i, c in enumerate(sorted(used_colors))]
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

