                v = next(i for i in range(n) if coloring[i] == -1)

            # assign smallest available color
            used = neighbor_colors[v].copy()
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
            # update neighbors
            for u in adj_list[v]:
                if c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    sat[u] = len(neighbor_colors[u])

