    # RLF implementation (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # independent set for this color
            independent_set = set()
            # start with vertex of max degree in uncolored subgraph
            if uncolored:
                # compute degrees in uncolored subgraph
                deg_uncolored = {}
                for u in uncolored:
                    cnt = 0
                    for w in adj_list[u]:
                        if w in uncolored:
                            cnt += 1
                    deg_uncolored[u] = cnt
                v = max(uncolored, key=lambda x: deg_uncolored[x])
                independent_set.add(v)
                # partition: U = not adjacent to S, W = adjacent to S
                U = uncolored - {v}
                W = set()
                for u in list(U):
                    if any(w in independent_set for w in adj_list[u]):
                        W.add(u)
                        U.remove(u)
                # while U not empty
                while U:
                    # select u in U with max neighbors in W
                    best_u = None
                    max_w_neighbors = -1
                    min_deg_in_U = float('inf')
                    for u in U:
                        w_neighbors = sum(1 for w in adj_list[u] if w in W)
                        # tie-break by min degree in U
                        deg_in_U = sum(1 for w in adj_list[u] if w in U)
                        if w_neighbors > max_w_neighbors or \
                           (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                            max_w_neighbors = w_neighbors
                            min_deg_in_U = deg_in_U
                            best_u = u
                    if best_u is None:
                        break  # should not happen
                    independent_set.add(best_u)
                    U.remove(best_u)
                    # move neighbors of best_u from U to W
                    for w in adj_list[best_u]:
                        if w in U:
                            U.remove(w)
                            W.add(w)
            # assign color to independent set
            for v in independent_set:
                coloring[v] = color
            color += 1
            # next uncolored set is W (vertices adjacent to current independent set)
            uncolored = W

        return coloring

    # Smallest-Last ordering greedy
    def smallest_last():
        if n == 0:
            return []
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # we'll simulate removal
        deg_copy = degrees[:]
        for _ in range(n):
            # find vertex with min degree in remaining
            min_deg = float('inf')
            min_v = -1
            for v in remaining:
                if deg_copy[v] < min_deg:
                    min_deg = deg_copy[v]
                    min_v = v
            if min_v == -1:
                break
