    best_k = num_colors(best_coloring)

    # If already optimal (lower bound from clique or degree), we could stop, but we try to reduce
    # Kempe chain based color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color to free the color
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return coloring  # already empty

        # Try direct reassignment first
        new_coloring = coloring[:]
        moved = [False] * n
        for v in vertices:
            used = set()
            for u in adj_list[v]:
                if new_coloring[u] != target_color:  # ignore same color class
                    used.add(new_coloring[u])
            c = 0
            while c in used:
                c += 1
            if c < target_color:  # can move to a lower color
                new_coloring[v] = c
                moved[v] = True

        # Check if we eliminated the color class
        if target_color not in set(new_coloring):
            # compact colors: remap to 0..k-1
            color_map = {}
            next_color = 0
            for i in range(n):
                col = new_coloring[i]
                if col not in color_map:
                    color_map[col] = next_color
                    next_color += 1
                new_coloring[i] = color_map[col]
            return new_coloring

        # If not eliminated, try Kempe chains for each vertex
        for v in vertices:
            if moved[v]:
                continue
            # Try to swap with each lower color
            for c in range(target_color):
                # Check if v can be recolored to c via Kempe chain (target_color, c)
                # Build the Kempe chain component containing v in colors {target_color, c}
                from collections import deque
                component = set()
                queue = deque([v])
                component.add(v)
                while queue:
                    node = queue.popleft()
                    for neighbor in adj_list[node]:
                        if neighbor not in component:
                            col_n = new_coloring[neighbor]
                            if col_n == target_color or col_n == c:
                                component.add(neighbor)
                                queue.append(neighbor)
                # Check if any neighbor of v in the component has color c? 
                # Actually, we want to see if we can swap: after swap, v becomes c, and no conflict
                # The swap is safe if no neighbor of v has color c after swap? 
                # After swap, vertices in component: target_color <-> c
                # So v becomes c. We need that no neighbor of v has color c after swap.
                # Neighbors of v: if they are in component and had color c, they become target_color -> ok
                # If they are in component and had target_color, they become c -> conflict if adjacent to v? 
                # Actually, after swap, a neighbor u of v:
                #   if u in component and had color c -> becomes target_color (not c)
                #   if u in component and had target_color -> becomes c
                #   if u not in component -> color unchanged
                # So conflict occurs if there exists a neighbor u of v such that:
                #   (u in component and original color target_color) OR (u not in component and original color c)
                # Because after swap, u would have color c in first case, or keep color c in second.
                conflict = False
                for u in adj_list[v]:
                    col_u = new_coloring[u]
                    if (u in component and col_u == target_color) or (u not in component and col_u == c):
                        conflict = True
                        break
                if not conflict:
                    # perform swap
                    for node in component:
                        if new_coloring[node] == target_color:
                            new_coloring[node] = c
                        elif new_coloring[node] == c:
                            new_coloring[node] = target_color
                    # after swap, check if v's color changed to c (it should)
                    # Now check if target_color class is reduced
                    # We break and will check after processing all vertices? 
                    # For simplicity, we break and try to eliminate after this swap
                    break  # break from color loop
            else:
                continue  # only if inner loop didn't break
            break  # break from vertex loop if we did a swap

        # After potential swap, check if target_color is eliminated
        if target_color not in set(new_coloring):
            color_map = {}
            next_color = 0
            for i in range(n):
                col = new_coloring[i]
                if col not in color_map:
                    color_map[col] = next_color
                    next_color += 1
                new_coloring[i] = color_map[col]
            return new_coloring

        # If still not eliminated, return original (should not happen often)
        return coloring

    # Iterative color reduction
    current = best_coloring[:]
    max_steps = 50  # Tabu search steps as per directive
    tabu_tenure = 5
    tabu_list = []  # list of (vertex, color_from, color_to) or just vertex moves?

    # We'll use a simple Tabu search to resolve conflicts if any, but our colorings should be valid
    # Instead, we try to reduce color count
    for _ in range(max_steps):
        k = num_colors(current)
        if k <= 1:
            break
        target_color = k - 1  # try to eliminate the highest color
        new_current = eliminate_color_class(current, target_color)
        if num_colors(new_current) < k:
            current = new_current
            # reset tabu? or continue
        else:
            # couldn't reduce, try to resolve conflicts via Tabu if any (but should be valid)
            # For now, break if no improvement
            break

    # Final validation and compacting
    if not is_valid_coloring(current):
        # fallback to best initial
        current = best_coloring

    # Ensure colors are consecutive starting from 0
    if current:
        color_map = {}
        next_color = 0
        for i in range(n):
            col = current[i]
            if col not in color_map:
                color_map[col] = next_color
                next_color += 1
            current[i] = color_map[col]

    return current

