def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets and bitmask adjacency
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if i != j:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        # Initial selection: max degree vertex
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] += 1  # color 0 is now used by neighbor
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = saturated[v]
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)
            if max_sat == -1:  # all saturated 0
                v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            else:
                v = max(candidates, key=lambda x: len(neighbors[x] & uncolored))
            # Assign smallest available color
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    # Check if color c is new to u's neighborhood
                    new_sat = saturated[u]
                    for w in neighbors[u]:
                        if color[w] == c:
                            new_sat += 1
                            break
                    # Actually, we can do: if no neighbor has color c, then increment
                    has_c = False
                    for w in neighbors[u]:
                        if color[w] == c:
                            has_c = True
                            break
                    if not has_c:
                        saturated[u] += 1
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v} - (neighbors[v] & uncolored)
            W = neighbors[v] & uncolored
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                tie_break_deg = float('inf')
                for u in U:
                    score = len(neighbors[u] & W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        tie_break_deg = len(neighbors[u] & U)
                    elif score == best_score:
                        deg_u = len(neighbors[u] & U)
                        if deg_u < tie_break_deg:
                            tie_break_deg = deg_u
                            best_u = u
                if best_u == -1:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                nbrs = neighbors[best_u] & U
                U -= nbrs
                W |= nbrs
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[v]) for v in range(n)]
        # We'll simulate removal
        temp_adj = [set(neighbors[v]) for v in range(n)]
        for _ in range(n):
            # find vertex with min degree in remaining
            v = min(remaining, key=lambda x: len(temp_adj[x] & remaining))
            order.append(v)
            remaining.remove(v)
            # remove v from temp_adj of neighbors
            for u in temp_adj[v]:
                if u in remaining:
                    temp_adj[u].discard(v)
        # Color in reverse order
        return greedy_color(reversed(order))

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen
        # Make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find smallest color class (highest index) that is non-empty
            # We try to eliminate the largest color index first
            max_color = max(col) if col else -1
            for target in range(max_color, 0, -1):  # from high to 1
                # Get vertices with color target
                verts = [v for v in range(n) if col[v] == target]
                if not verts:
                    continue
                # Try to recolor each vertex in this class
                removed_all = True
                for v in verts:
