                    for c in range(target):  # try colors 0..target-1
                        if not (used & (1 << c)):
                            # Check if color c is available (no neighbor has it)
                            col[v] = c
                            if is_valid(col):
                                found = True
                                changed = True
                                break
                            else:
                                col[v] = target  # revert
                    if found:
                        continue
                    # Try Kempe chain swap with each lower color
                    swapped = False
                    for c in range(target):
                        # Consider (c, target) Kempe chain
                        # If v is not in a component that can be swapped to free target?
                        # Actually, we want to swap a component containing v to change v's color to c
                        # Build the component of v in the subgraph induced by colors c and target
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
