    # If no candidates (should not happen), fallback to greedy by index
    if not candidates:
        col_greedy = greedy_color(list(range(n)))
        candidates.append(col_greedy)

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    best = compact_colors(best)  # ensure compact

    # Apply Kempe reduction to try to improve
    improved = kempe_reduce(best)
    if is_valid(improved) and num_colors(improved) < num_colors(best):
        best = improved

    # Final validation and compaction
    if not is_valid(best):
        # Ultimate fallback: greedy with random order until valid
        for _ in range(10):
            order = list(range(n))
            random.shuffle(order)
            col = greedy_color(order)
            if is_valid(col):
                best = compact_colors(col)
                break
        else:
            # Last resort: assign each vertex a unique color
            best = list(range(n))

    return compact_colors(best)

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: compute degree
    degree = [len(adj_list[i]) for i in range(n)]

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        used = [False] * n  # temporary for MEX
        for v in order:
            # Mark colors used by neighbors
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            # Find smallest free color
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            # Reset used
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = False
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bitmasks for fast saturation update
        neighbor_colors = [0] * n
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, break ties by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > best_sat:
                    best_sat = sat_v
                    best_v = v
                    best_deg = sum(1 for u in adj_list[v] if u in uncolored)
                elif sat_v == best_sat:
                    deg_v = sum(1 for u in adj_list[v] if u in uncolored)
                    if deg_v > best_deg:
                        best_deg = deg_v
                        best_v = v
                    elif deg_v == best_deg:
                        if random.random() < 0.5:
                            best_v = v
                            best_deg = deg_v
            v = best_v
            uncolored.remove(v)

            # Find smallest free color for v
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

            # Update saturation and neighbor colors for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # If color c is new in u's neighbor colors
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build maximal independent set for current_color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = {u for u in uncolored if u != v and v not in adj_list[u]}
            W = {u for u in uncolored if u != v and v in adj_list[u]}

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    score = sum(1 for w in adj_list[u] if w in W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        best_deg_U = sum(1 for x in adj_list[u] if x in U)
                    elif score == best_score:
                        deg_u = sum(1 for x in adj_list[u] if x in U)
                        if deg_u < best_deg_U:
                            best_deg_U = deg_u
                            best_u = u
                        elif deg_u == best_deg_U:
                            if random.random() < 0.5:
                                best_u = u
                                best_deg_U = deg_u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent_set
            for v in independent_set:
                color[v] = current_color
            uncolored -= independent_set
            current_color += 1
        return color

    # Helper: Smallest-Last ordering greedy
    def smallest_last():
        # Compute degeneracy ordering (smallest-last)
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        # Current degrees (will be updated)
        curr_deg = degrees[:]
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # remove u from its current bucket
                    d = curr_deg[u]
                    buckets[d].remove(u)
                    curr_deg[u] -= 1
                    buckets[curr_deg[u]].append(u)
        # Reverse to get coloring order
        order.reverse()
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Also try Welsh-Powell (degree descending)
    wp_order = sorted(range(n), key=lambda x: degree[x], reverse=True)
    candidates.append(greedy_color(wp_order))

    # Select best candidate (fewest colors)
    best_coloring = None
    best_num_colors = float('inf')
    for col in candidates:
        if is_valid(col):
            num_colors = max(col) + 1 if n > 0 else 0
            if num_colors < best_num_colors:
                best_num_colors = num_colors
                best_coloring = col[:]
    if best_coloring is None:
        # fallback to trivial greedy
        best_coloring = greedy_color(list(range(n)))
        best_num_colors = max(best_coloring) + 1 if n > 0 else 0

    # Kempe chain color reduction
    def eliminate_color_class(coloring, k):
        """Try to eliminate color k-1, return new coloring with max color < k-1 if possible, else None"""
        # Get vertices with color k-1
        color_class = [v for v in range(n) if coloring[v] == k-1]
        if not color_class:
            return coloring  # already eliminated

        # Try to recolor each vertex in color_class
        for v in color_class:
            # Try direct reassignment to a lower color
            neighbor_colors = set()
            for u in adj_list[v]:
                if coloring[u] < k-1:
                    neighbor_colors.add(coloring[u])
            for c in range(k-1):
                if c not in neighbor_colors:
                    # Move v to color c
                    coloring[v] = c
                    # Re-check: if any vertex still has color k-1?
                    if not any(coloring[x] == k-1 for x in range(n)):
                        return coloring
                    # Otherwise, revert and try next
                    coloring[v] = k-1
                    break  # no need to try other c for this v since we found one but didn't eliminate class

        # Try Kempe chains for each vertex in color_class
        for v in color_class:
            for c in range(k-1):
                # Build (c, k-1)-Kempe chain containing v
                # Only if v is not adjacent to any c-colored vertex? Actually, we can always build chain.
                visited = [False] * n
                stack = [v]
                visited[v] = True
                component = []
                while stack:
                    node = stack.pop()
                    component.append(node)
                    for nb in adj_list[node]:
                        if not visited[nb] and (coloring[nb] == c or coloring[nb] == k-1):
                            visited[nb] = True
                            stack.append(nb)
                # Check if swapping colors in component would cause conflict
                # After swap, v would become color c. Check if any neighbor of v is color c (outside component)
                conflict = False
                for nb in adj_list[v]:
                    if nb not in component and coloring[nb] == c:
                        conflict = True
                        break
                if not conflict:
                    # Perform swap
                    for node in component:
                        if coloring[node] == c:
                            coloring[node] = k-1
                        else:  # must be k-1
                            coloring[node] = c
                    # Check if color k-1 is eliminated
                    if not any(coloring[x] == k-1 for x in range(n)):
                        return coloring
                    # Otherwise, revert swap and try next
                    for node in component:
                        if coloring[node] == c:
                            coloring[node] = k-1
                        else:
                            coloring[node] = c
        return None  # could not eliminate

    # Iteratively try to reduce colors
    k = best_num_colors
    improved = True
    while improved and k > 1:
        improved = False
        new_coloring = eliminate_color_class(best_coloring[:], k)
        if new_coloring is not None:
            best_coloring = new_coloring
            k -= 1
            improved = True

    # Compact colors to 0..k-1
    # Map colors to consecutive integers
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_coloring[i] = unique_colors[c]

    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        # Validate binary entries
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bit masks
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for v in adj[i]:
                neighbors[i].add(v)

    # Ensure undirected (symmetric)
    for i in range(n):
        for j in list(neighbors[i]):
            neighbors[j].add(i)

    # Convert to bit masks for fast operations
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    # Helper: count bits in mask
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: get degree in subgraph induced by uncolored set
    def degree_in_uncolored(v: int, uncolored_mask: int) -> int:
        return bit_count(bit_adj[v] & uncolored_mask)

    # Helper: saturation degree (number of distinct colors in colored neighbors)
    def saturation_degree(v: int, colors: list[int]) -> int:
        mask = 0
        nb_mask = bit_adj[v]
        u = 0
        while nb_mask:
            if nb_mask & 1:
                if colors[u] != -1:
                    mask |= (1 << colors[u])
            nb_mask >>= 1
            u += 1
        return bit_count(mask)

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        colors = [-1] * n
        uncolored_mask = (1 << n) - 1

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1

            vmask = uncolored_mask
            while vmask:
                v = (vmask & -vmask).bit_length() - 1
                vmask &= vmask - 1

                sat = saturation_degree(v, colors)
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = degree_in_uncolored(v, uncolored_mask)
                elif sat == best_sat:
                    deg = degree_in_uncolored(v, uncolored_mask)
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
                    elif deg == best_deg:
                        if random.random() < 0.5:
                            best_v = v
                            best_deg = deg

            v = best_v
            # Find smallest available color
            used = 0
            nb_mask = bit_adj[v]
            u = 0
            while nb_mask:
                if nb_mask & 1:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
                nb_mask >>= 1
                u += 1
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored_mask &= ~(1 << v)

        return colors

    # RLF: Recursive Largest First (independent set extraction)
    def rlf() -> list[int]:
        colors = [-1] * n
        uncolored_mask = (1 << n) - 1
        color = 0

        while uncolored_mask:
            # Find vertex with max degree in uncolored subgraph
            vmask = uncolored_mask
            best_v = -1
            best_deg = -1
            while vmask:
                v = (vmask & -vmask).bit_length() - 1
                vmask &= vmask - 1
                deg = degree_in_uncolored(v, uncolored_mask)
                if deg > best_deg:
                    best_deg = deg
                    best_v = v

            # Build independent set for this color
            independent_set = 0
            independent_set |= (1 << best_v)
            # W: vertices adjacent to independent set (cannot take this color)
            W = bit_adj[best_v] & uncolored_mask
            # U: vertices not adjacent to independent set (can take this color)
            U = uncolored_mask & ~W & ~(1 << best_v)

            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_u = -1
                umask = U
                while umask:
                    u = (umask & -umask).bit_length() - 1
                    umask &= umask - 1
                    # Score: number of neighbors in W
                    score = bit_count(bit_adj[u] & W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        best_deg_u = degree_in_uncolored(u, U)
                    elif score == best_score:
                        deg_u = degree_in_uncolored(u, U)
                        if deg_u < best_deg_u:
                            best_deg_u = deg_u
                            best_u = u
                        elif deg_u == best_deg_u:
                            if random.random() < 0.5:
                                best_u = u
                                best_deg_u = deg_u

                u = best_u
                independent_set |= (1 << u)
                # Move u from U to independent set, update W and U
                U &= ~(1 << u)
                # Add neighbors of u that are in U to W
                W |= (bit_adj[u] & U)
                # Remove from U any vertices now adjacent to independent set (i.e., in W)
                U &= ~W

            # Assign color to all in independent set
            imask = independent_set
            while imask:
                v = (imask & -imask).bit_length() - 1
                imask &= imask - 1
                colors[v] = color

            uncolored_mask &= ~independent_set
            color += 1

        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        # Build core numbers via smallest-last ordering
        remaining = list(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        bucket = [[] for _ in range(n)]
        pos = [0] * n

        for v in range(n):
            d = degree[v]
            bucket[d].append(v)
            pos[v] = len(bucket[d]) - 1

        for d in range(n):
            while bucket[d]:
                # Find non-empty bucket
                while d < n and not bucket[d]:
                    d += 1
                if d >= n:
                    break
                v = bucket[d].pop()
                pos[v] = -1  # removed
                order.append(v)
                # Update neighbors
                for u in neighbors[v]:
                    if pos[u] >= 0:  # still in remaining
                        du = degree[u]
                        # remove u from bucket[du]
                        idx = pos[u]
                        last = bucket[du][-1]
                        bucket[du][idx] = last
                        pos[last] = idx
                        bucket[du].pop()
                        if pos[last] < len(bucket[du]):
                            pos[last] = pos[last]  # unchanged
                        degree[u] -= 1
                        dnew = degree[u]
                        bucket[dnew].append(u)
                        pos[u] = len(bucket[dnew]) - 1

        # Color in reverse order (largest last first)
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

        return colors

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(colors: list[int], a: int, b: int, v: int) -> list[int]:
        new_colors = colors[:]
        stack = [v]
        visited = [False] * n
        visited[v] = True
        # We will swap a<->b in the component containing v
        while stack:
            node = stack.pop()
            if new_colors[node] == a:
                new_colors[node] = b
            elif new_colors[node] == b:
                new_colors[node] = a
            for u in neighbors[node]:
                if not visited[u] and (new_colors[u] == a or new_colors[u] == b):
                    visited[u] = True
                    stack.append(u)
        return new_colors

    # Try to eliminate the smallest color class using Kempe chains
    def reduce_colors(colors: list[int]) -> list[int]:
        if max(colors) < 0:
            return colors
        k = max(colors) + 1
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            # Collect vertices with target_color
            targets = [v for v in range(n) if colors[v] == target_color]
            if not targets:
                continue
            # Try to recolor each target vertex
            made_progress = False
            for v in targets:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Found a free color, reassign
                        colors[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v is isolated in the (c, target_color) Kempe subgraph
                    # i.e., no neighbor of v has color c
                    has_c_neighbor = False
                    for u in neighbors[v]:
                        if colors[u] == c:
                            has_c_neighbor = True
                            break
                    if not has_c_neighbor:
                        # Swap the component: since v has no c neighbor, swapping will move v to c
                        colors = kempe_swap(colors, c, target_color, v)
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                # Cannot eliminate this color class, move to next lower
                continue
            else:
                # Made progress, restart from highest color
                return reduce_colors(colors)
        # No progress made, return as is
        return colors

    # Validate coloring
    def is_valid(colors: list[int]) -> bool:
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Compact colors to 0..k-1
    def compact_colors(colors: list[int]) -> list[int]:
        if max(colors) < 0:
            return colors
        # Map existing colors to 0..k-1
        unique = {}
        next_color = 0
        for c in colors:
            if c not in unique:
                unique[c] = next_color
                next_color += 1
        return [unique[c] for c in colors]

    # Run multiple heuristics and pick best
    start_time = time.time()
    best_colors = None
    best_k = float('inf')

    # DSATUR
    if time.time() - start_time < 0.04:  # 40ms budget for heuristics
        c1 = dsatur()
        c1 = compact_colors(c1)
        if is_valid(c1):
            k1 = max(c1) + 1 if c1 else 0
            if k1 < best_k:
                best_k = k1
                best_colors = c1

    # RLF
    if time.time() - start_time < 0.04:
        c2 = rlf()
        c2 = compact_colors(c2)
        if is_valid(c2):
            k2 = max(c2) + 1 if c2 else 0
            if k2 < best_k:
                best_k = k2
                best_colors = c2

    # Smallest-Last
    if time.time() - start_time < 0.04:
        c3 = smallest_last()
        c3 = compact_colors(c3)
        if is_valid(c3):
            k3 = max(c3) + 1 if c3 else 0
            if k3 < best_k:
                best_k = k3
                best_colors = c3

    # If no valid coloring found (should not happen), fallback to greedy
    if best_colors is None:
        # Simple greedy by degree order
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    # Apply Kempe chain reduction to try to improve
    if time.time() - start_time < 0.045:  # Leave 5ms for reduction
        improved = reduce_colors(best_colors[:])
        improved = compact_colors(improved)
        if is_valid(improved):
            k_imp = max(improved) + 1 if improved else 0
            if k_imp < best_k:
                best_colors = improved

    # Final validation and compact
    if not is_valid(best_colors):
        # Last resort: greedy coloring
        order = list(range(n))
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    return best_colors

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input type
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmasks
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: convert adjacency list to bitmask for a set of vertices
    def mask_from_vertices(vertices):
        mask = 0
        for v in vertices:
            mask |= (1 << v)
        return mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # DSATUR
    def dsatur():
        color = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for u in uncolored:
                sat = saturated[u]
                if sat > max_sat:
                    max_sat = sat
                    candidates = [u]
                elif sat == max_sat:
                    candidates.append(u)
            # Tie-break: degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                selected = candidates[0]
                for u in candidates:
                    deg = 0
                    for v in adj_list[u]:
                        if v in uncolored:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        selected = u
                u = selected
            else:
                u = candidates[0]
            # Assign smallest available color
            used = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
            uncolored.remove(u)
            # Update saturation of uncolored neighbors
            for v in adj_list[u]:
                if v in uncolored:
                    # Recompute saturation for v: number of distinct colors in its colored neighbors
                    neighbor_colors = 0
                    for w in adj_list[v]:
                        if color[w] != -1:
                            neighbor_colors |= (1 << color[w])
                    saturated[v] = neighbor_colors.bit_count()
        return color

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # Choose vertex with max degree in uncolored subgraph
            max_deg = -1
            v1 = None
            for v in uncolored:
                deg = 0
                for w in adj_list[v]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v1 = v
            if v1 is None:
                break  # should not happen
            S.append(v1)
            # Partition: U = vertices not adjacent to any in S, W = adjacent to S
            U = set()
            W = set()
            for v in uncolored:
                if v == v1:
                    continue
                adjacent = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(v)
                else:
                    U.add(v)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break: min degree in G[U]
                        deg_u = 0
                        for w in adj_list[u]:
                            if w in U:
                                deg_u += 1
                        deg_best = 0
                        for w in adj_list[best_u]:
                            if w in U:
                                deg_best += 1
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        while remaining:
            # Find vertex with minimum degree in remaining subgraph
            min_deg = float('inf')
            v_min = None
            for v in remaining:
                # Compute current degree in remaining subgraph
                deg = 0
                for w in adj_list[v]:
                    if w in remaining:
                        deg += 1
                if deg < min_deg:
                    min_deg = deg
                    v_min = v
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors (optional, but we recompute each time)
        # Color in reverse order
        return greedy_color(list(reversed(order)))

    # Kempe chain swap attempt to free a color
    def kempe_swap(coloring, target_color):
        # Try to recolor vertices of target_color to free the color
        vertices = [i for i in range(n) if coloring[i] == target_color]
        if not vertices:
            return True  # already free
        # Try direct reassignment first
        for v in vertices:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            for c in range(target_color):  # only try colors < target_color
                if not (used & (1 << c)):
                    coloring[v] = c
                    vertices.remove(v)
                    break
        if not vertices:
            return True
        # Try Kempe chains for each remaining vertex
        for v in vertices[:]:  # copy as we may modify
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            for c in range(target_color):
                if used & (1 << c):
                    continue  # color c is present in neighbors, cannot assign directly
                # Try to swap along (c, target_color) Kempe chain
                # Find component of v in subgraph induced by colors c and target_color
                from collections import deque
                visited = set()
                queue = deque([v])
                visited.add(v)
                component = set()
                while queue:
                    x = queue.popleft()
                    component.add(x)
                    for y in adj_list[x]:
                        if y not in visited and (coloring[y] == c or coloring[y] == target_color):
                            visited.add(y)
                            queue.append(y)
                # Check if any neighbor of the component has color c (would cause conflict if swapped)
                conflict = False
                for x in component:
                    for y in adj_list[x]:
                        if y not in component and coloring[y] == c:
                            conflict = True
                            break
                    if conflict:
                        break
                if not conflict:
                    # Perform swap: c <-> target_color in component
                    for x in component:
                        if coloring[x] == c:
                            coloring[x] = target_color
                        elif coloring[x] == target_color:
                            coloring[x] = c
                    # Now v should be color c (since it was target_color)
                    coloring[v] = c
                    vertices.remove(v)
                    break
            if not vertices:
                break
        return len(vertices) == 0

    # Try multiple heuristics
    for heuristic_name, heuristic in [('DSATUR', dsatur), ('RLF', rlf), ('Smallest-Last', smallest_last)]:
        try:
            coloring = heuristic()
            if is_valid(coloring):
                k = count_colors(coloring)
                if k < best_k:
                    best_k = k
                    best_coloring = coloring[:]
        except Exception:
            continue

    # Fallback: greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best_coloring = greedy_color(order)
        best_k = count_colors(best_coloring)

    # Ensure colors are compact (0..k-1)
    # Relabel colors to be consecutive
    if best_coloring:
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_coloring[i] = unique_colors[c]

    # Iterative Kempe chain reduction
    current_k = count_colors(best_coloring)
    improved = True
    while improved and current_k > 1:
        improved = False
        # Try to eliminate color classes from highest to lowest
        for target_color in range(current_k - 1, -1, -1):
            # Make a copy to try on
            trial = best_coloring[:]
            if kempe_swap(trial, target_color):
                # Success: color class eliminated, compact colors
                # Relabel
                used_colors = set(trial)
                mapping = {}
                next_c = 0
                for c in sorted(used_colors):
                    mapping[c] = next_c
                    next_c += 1
                for i in range(n):
                    trial[i] = mapping[trial[i]]
                new_k = count_colors(trial)
                if new_k < current_k:
                    best_coloring = trial
                    current_k = new_k
                    improved = True
                    break  # restart from highest color
        # If no improvement, break

    # Final validation (should always hold)
    if not is_valid(best_coloring):
        # Ultimate fallback: greedy sequential
        best_coloring = greedy_color(list(range(n)))
        # Compact
        used = set(best_coloring)
        mapping = {c: i for i, c in enumerate(sorted(used))]
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

import math
