    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and bitmask representation
    if is_matrix:
        neighbors = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
    else:
        neighbors = adj

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper functions
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    def get_unique_colors(coloring):
        return len(set(coloring)) if coloring else 0

    def compact_colors(coloring):
        if not coloring:
            return coloring
        unique = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        saturated = [0] * n
        uncolored = set(range(n))

        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            colors[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] += 1

        while uncolored:
            # Find vertex with max saturation, break ties by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = saturated[v]
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)

            if len(candidates) == 1:
                v = candidates[0]
            else:
                # Tie-break by degree in uncolored subgraph
                v = max(candidates, key=lambda x: sum(1 for u in neighbors[x] if u in uncolored))

            # Find smallest available color
            neighbor_colors = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)

            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] += 1

        return compact_colors(colors)

    # RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build independent set for current color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in neighbors[x] if u in uncolored))
            independent_set = {v}
            # Partition remaining uncolored into U (eligible) and W (ineligible)
            U = uncolored - {v}
            W = set()
            for u in U:
                if u in neighbors[v]:
                    W.add(u)
                else:
                    # u remains in U (eligible)
                    pass

            # While there are eligible vertices
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_count = sum(1 for w in neighbors[u] if w in W)
                    if w_count > max_w_neighbors:
                        max_w_neighbors = w_count
                        best_u = u
                    elif w_count == max_w_neighbors:
                        # Tie-break: min degree in U
                        deg_u = sum(1 for w in neighbors[u] if w in U)
                        deg_best = sum(1 for w in neighbors[best_u] if w in U) if best_u is not None else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                            max_w_neighbors = w_count
                if best_u is None:
                    break  # Should not happen if U not empty

                # Add best_u to independent set
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
                uncolored.remove(v)
            color_idx += 1

        return compact_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering (smallest-last)
        degrees = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # Buckets for degree frequencies
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            d = degrees[i]
            if d <= max_deg:
                buckets[d].append(i)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # Should not happen
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = degrees[u]
                    if d <= max_deg and u in buckets[d]:
                        buckets[d].remove(u)
                        degrees[u] -= 1
                        d_new = degrees[u]
                        if d_new <= max_deg:
                            buckets[d_new].append(u)

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c

        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        best = coloring[:]
        improved = True
        # Limit iterations to avoid timeout
        for _ in range(10):  # Max 10 reduction attempts
            if not improved:
                break
            improved = False
            k = get_unique_colors(best)
            if k <= 1:
                break
            # Find smallest color class (highest index)
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                c = best[v]
                if c < k:
                    color_classes[c].append(v)
            # Target the last color (k-1)
            target_color = k - 1
            target_vertices = color_classes[target_color]
            if not target_vertices:
                # Should not happen, but compact just in case
                best = compact_colors(best)
                continue

            # Try to recolor each target vertex
            removed_all = True
            new_coloring = best[:]
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in neighbors[v]:
                    if new_coloring[u] != -1:
                        neighbor_colors |= (1 << new_coloring[u])
                reassigned = False
                for c in range(target_color):  # Try colors 0 to k-2
                    if not (neighbor_colors & (1 << c)):
                        new_coloring[v] = c
                        reassigned = True
                        break
                if reassigned:
                    continue

                # Try Kempe chains with each lower color
                kempe_success = False
                for c in range(target_color):
                    # If v already has color c (shouldn't happen as we checked direct reassignment)
                    if new_coloring[v] == c:
                        kempe_success = True
                        break
                    # Build Kempe chain for colors (target_color, c) starting from v
                    # We want to swap in the component of v if it doesn't contain any vertex of color c
                    stack = [v]
                    visited = set()
                    component = set()
                    has_color_c = False
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        col = new_coloring[node]
                        if col == target_color or col == c:
                            component.add(node)
                            if col == c:
                                has_color_c = True
                            # Explore neighbors with colors target_color or c
                            for nb in neighbors[node]:
                                if nb not in visited:
                                    nb_col = new_coloring[nb]
                                    if nb_col == target_color or nb_col == c:
                                        stack.append(nb)
                    # If the component does not contain color c, we can swap
                    if not has_color_c:
                        kempe_success = True
                        for node in component:
                            if new_coloring[node] == target_color:
                                new_coloring[node] = c
                            else:  # must be c
                                new_coloring[node] = target_color
                        break
                if kempe_success:
                    continue
                # If we couldn't recolor v, we fail to remove the color class
                removed_all = False
                break

            if removed_all:
                # Successfully removed target color
                best = compact_colors(new_coloring)
                improved = True
            # else: try next iteration with same coloring (though unlikely to improve without change)

        return best

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        greedy = [0] * n
        for i in range(n):
            if i == 0:
                greedy[i] = 0
            else:
                neighbor_colors = 0
                for j in neighbors[i]:
                    if j < i:  # only colored neighbors
                        neighbor_colors |= (1 << greedy[j])
                c = 0
                while neighbor_colors & (1 << c):
                    c += 1
                greedy[i] = c
        candidates.append(greedy)

    # Select best candidate (fewest colors)
    best_candidate = min(candidates, key=get_unique_colors)
    best_candidate = compact_colors(best_candidate)

    # Apply Kempe reduction to improve
    try:
        improved = kempe_reduce(best_candidate)
        if is_valid_coloring(improved) and get_unique_colors(improved) < get_unique_colors(best_candidate):
            best_candidate = improved
    except:
        pass

    # Final validation and compact
    if not is_valid_coloring(best_candidate):
        # Fallback to greedy if invalid
        greedy = [0] * n
        for i in range(n):
            neighbor_colors = 0
            for j in neighbors[i]:
                if j < i:
                    neighbor_colors |= (1 << greedy[j])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            greedy[i] = c
        best_candidate = compact_colors(greedy)

    return best_candidate

