                for nb in adj_list[v]:
                    if color[nb] != -1:
                        used_by_neighbors |= (1 << color[nb])
                found = False
                for c in range(target_color):  # try colors 0 to target_color-1
                    if not (used_by_neighbors & (1 << c)):
                        # can assign color c directly
                        color[v] = c
                        changed = True
                        found = True
                        break
                if found:
                    continue
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # if v already has color c after possible direct reassignment, skip (but we know it doesn't)
                    # build Kempe chain for colors c and target_color starting from v
                    # we want to swap in the component of v if it does not contain any vertex of color c that is fixed?
                    # Actually, we can try to swap the component containing v in the (c, target_color) subgraph
                    # If after swap, v gets color c and we don't introduce conflict, it's good.
                    # But we must ensure that swapping doesn't cause two adjacent same color.
                    # Since we are swapping only two colors, it remains valid if we swap a connected component.
                    # However, we want to free target_color for v? Actually, we want to recolor v to c.
                    # After swap, v will have color c if it was target_color and we swap its component.
                    # But we need to check that in the component, swapping doesn't cause conflict? It won't because it's a proper 2-coloring.
                    # However, we must check that no neighbor of v that is not in the component has color c? Actually, after swap:
                    #   - vertices in component: c <-> target_color
                    #   - vertices outside: unchanged
                    # So for v, after swap it becomes c.
                    # Its neighbors: 
                    #   - if neighbor in component: was target_color -> becomes c -> conflict? 
                    #     But wait: if neighbor is in component and adjacent to v, then before swap: v is target_color, neighbor is c (since they are adjacent and must be different in the 2-coloring). 
                    #     After swap: v becomes c, neighbor becomes target_color -> still different.
                    #   - if neighbor not in component: unchanged color. 
                    #     If neighbor color is c, then after swap v becomes c -> conflict.
                    #     If neighbor color is target_color, after swap v becomes c -> no conflict (since target_color != c).
                    # Therefore, we can swap the component containing v if and only if no neighbor of v has color c and is not in the component.
                    # Equivalent: all neighbors of v that have color c must be in the component (so they get swapped to target_color).
                    # But easier: we can attempt the swap and then check if coloring remains valid? Since n is small, we can do that.
                    # Let's copy color, perform swap on the component, and check validity.
                    # Find connected component of v in the subgraph induced by vertices with color c or target_color
                    from collections import deque
                    comp_color_c = c
                    comp_color_t = target_color
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for nb in adj_list[x]:
                            if not visited[nb] and (color[nb] == comp_color_c or color[nb] == comp_color_t):
                                visited[nb] = True
                                queue.append(nb)
                    # swap colors in component
                    color_copy = color[:]
                    for x in component:
                        if color_copy[x] == comp_color_c:
                            color_copy[x] = comp_color_t
                        elif color_copy[x] == comp_color_t:
                            color_copy[x] = comp_color_c
                    # check if valid
                    if is_valid_coloring(color_copy):
                        # accept the swap
                        color = color_copy
                        changed = True
                        break  # break out of color c loop, go to next target vertex (but note: we changed color, so break inner loops)
                if changed:
                    break  # break out of target vertex loop to restart while changed
            # if we couldn't recolor any target vertex, break
            if not changed:
                break
        return compact_colors(color)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        color = [-1] * n
        for v in range(n):
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        candidates.append(compact_colors(color))

    # Apply Kempe reduction to each candidate and pick best
    best_coloring = None
    best_k = float('inf')
    for cand in candidates:
        reduced = kempe_reduce(cand)
        if not is_valid_coloring(reduced):
            # fallback to original if reduction broke validity
            reduced = cand
        k = num_colors(reduced)
        if k < best_k:
            best_k = k
            best_coloring = reduced
        elif k == best_k:
            # tie-break by lexicographical order or random? keep first
            pass

    # Final validation and compact
    if best_coloring is None:
        best_coloring = [0] * n
    best_coloring = compact_colors(best_coloring)
    if not is_valid_coloring(best_coloring):
        # last resort: greedy
        color = [-1] * n
        for v in range(n):
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = compact_colors(color)
    return best_coloring

