def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Colors a graph using a DSATUR-based heuristic with tie-breaking by sum of degrees of uncolored neighbors.
    Includes iterative Kempe chain refinement to minimize the number of colors.
    """
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for efficient access
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for nb in adj[i]:
                if 0 <= nb < n:
                    neighbors[i].add(nb)

    # Precompute degrees
    degrees = [len(neighbors[i]) for i in range(n)]

    # Helper: compute sum of degrees of uncolored neighbors for a vertex
    def sum_uncolored_degrees(v, colored_set):
        s = 0
        for nb in neighbors[v]:
            if nb not in colored_set:
                s += degrees[nb]
        return s

    # DSATUR with custom tie-breaking
    def dsatur():
        color = [-1] * n
        colored_set = set()
        # saturation[v] = number of distinct colors in neighborhood
        saturation = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by sum of degrees of uncolored neighbors, then degree, then index
            v = -1
            max_sat = -1
            max_sum_deg = -1
            max_deg = -1
            for u in range(n):
                if color[u] == -1:
                    sat_u = saturation[u]
                    if sat_u > max_sat:
                        max_sat = sat_u
                        max_sum_deg = sum_uncolored_degrees(u, colored_set)
                        max_deg = degrees[u]
                        v = u
                    elif sat_u == max_sat:
                        sum_deg_u = sum_uncolored_degrees(u, colored_set)
                        deg_u = degrees[u]
                        if sum_deg_u > max_sum_deg:
                            max_sum_deg = sum_deg_u
                            max_deg = deg_u
                            v = u
                        elif sum_deg_u == max_sum_deg:
                            if deg_u > max_deg:
                                max_deg = deg_u
                                v = u
                            elif deg_u == max_deg and u < v:
                                v = u
            # Assign smallest available color
            used = [False] * (n + 1)  # n colors suffice
            for nb in neighbors[v]:
                c = color[nb]
                if c != -1:
                    used[c] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            color[v] = c
            colored_set.add(v)
            # Update saturation of uncolored neighbors
            for nb in neighbors[v]:
                if color[nb] == -1:
                    # Recompute saturation: count distinct colors in neighborhood
                    neighbor_colors = set()
                    for nb2 in neighbors[nb]:
                        if color[nb2] != -1:
                            neighbor_colors.add(color[nb2])
                    saturation[nb] = len(neighbor_colors)
        return color

    # Kempe chain swap for colors a and b, starting from vertex v, returns new coloring if swap performed, else None
    def kempe_swap(color, v, a, b):
        n = len(color)
        if color[v] not in (a, b):
            return None
        # Find the Kempe chain containing v for colors a and b
        stack = [v]
        visited = [False] * n
        component = []
        while stack:
            u = stack.pop()
            if visited[u]:
                continue
            visited[u] = True
            if color[u] in (a, b):
                component.append(u)
                for nb in neighbors[u]:
                    if not visited[nb] and color[nb] in (a, b):
                        stack.append(nb)
        # Check if swapping is safe: no neighbor outside component has color a or b that would conflict
        # Actually, swapping within a component is always safe for Kempe chains
        new_color = color[:]
        for u in component:
            new_color[u] = a if new_color[u] == b else b
        return new_color

    # Try to eliminate the last color using Kempe chains and direct reassignment
    def reduce_colors(color):
        # Map color to list of vertices
        color_classes = [[] for _ in range(n)]  # n is safe upper bound
        for v in range(n):
            c = color[v]
            if c < n:
                color_classes[c].append(v)
        # Find the highest color used
        max_color = max(color) if n > 0 else -1
        if max_color < 0:
            return color
        # Try to eliminate colors from highest downwards
        for c in range(max_color, 0, -1):
            if not color_classes[c]:
                continue
            # Try to recolor each vertex in color class c
            changed = True
            while changed and color_classes[c]:
                changed = False
                v = color_classes[c].pop()  # take a vertex
                # Try direct reassignment to a lower color
                for new_c in range(c):
                    conflict = False
                    for nb in neighbors[v]:
                        if color[nb] == new_c:
                            conflict = True
                            break
                    if not conflict:
                        # Assign new color
                        color[v] = new_c
                        color_classes[new_c].append(v)
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chain swaps with each lower color
                for new_c in range(c):
                    swapped = kempe_swap(color, v, c, new_c)
                    if swapped is not None:
                        # Update color and color classes
                        old_c = color[v]
                        color[:] = swapped
                        # Rebuild color classes for efficiency (could be optimized, but n <= 100)
                        color_classes = [[] for _ in range(n)]
                        for u in range(n):
                            cu = color[u]
                            if cu < n:
                                color_classes[cu].append(u)
                        changed = True
                        break
                if not changed:
                    # Could not recolor v, put it back
                    color_classes[c].append(v)
            # If color class c is empty, we can compact colors
            if not color_classes[c]:
                # Shift down all colors > c
                for v in range(n):
                    if color[v] > c:
                        color[v] -= 1
                # Rebuild color classes after shifting
                color_classes = [[] for _ in range(n)]
                for v in range(n):
                    cv = color[v]
                    if cv < n:
                        color_classes[cv].append(v)
        return color

    # Generate initial coloring with DSATUR
    best_color = dsatur()
    best_k = max(best_color) + 1 if n > 0 else 0

    # Try to reduce colors using Kempe chains
    reduced_color = reduce_colors(best_color[:])
    reduced_k = max(reduced_color) + 1 if n > 0 else 0
    if reduced_k < best_k:
        best_color = reduced_color
        best_k = reduced_k

    # Validate and ensure consecutive colors
    # Verify no adjacent same color
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_color[u] == best_color[v]:
                # Fallback: greedy by degree order
                order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
                color = [-1] * n
                for v in order:
                    used = [False] * (n + 1)
                    for nb in neighbors[v]:
                        c = color[nb]
                        if c != -1:
                            used[c] = True
                    c = 0
                    while c <= n and used[c]:
                        c += 1
                    color[v] = c
                best_color = color
                break

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_color[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_color[i] = unique_colors[c]

    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: count distinct colors
    def count_colors(colors):
        return len(set(colors)) if colors else 0

    # Helper: convert to consecutive colors starting from 0
    def normalize_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets as bit masks for fast distinct count
        neighbor_colors = [0] * n
        uncolored = set(range(n))

        # initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(adj_list[x]))
            color[v] = 0
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if color[u] == -1:
                    neighbor_colors[u] |= (1 << 0)
                    sat[u] = neighbor_colors[u].bit_count()

        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([n for n in adj_list[x] if n in uncolored])))
            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in adj_list[v]:
                if color[u] == -1:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] = neighbor_colors[u].bit_count()
        return color

    # Recursive Largest First (RLF)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            S = []
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([n for n in adj_list[x] if n in uncolored]))
            S.append(v)
            # partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in adj_list[u] for w in S):
                    W.add(u)
                    U.remove(u)
            # greedily add to S from U
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U-induced subgraph
                u_star = None
                max_neighbors_in_W = -1
                min_deg_in_U = float('inf')
                for u in U:
                    neighbors_in_W = len([w for w in adj_list[u] if w in W])
                    deg_in_U = len([w for w in adj_list[u] if w in U])
                    if (neighbors_in_W > max_neighbors_in_W or
                        (neighbors_in_W == max_neighbors_in_W and deg_in_U < min_deg_in_U)):
                        max_neighbors_in_W = neighbors_in_W
                        min_deg_in_U = deg_in_U
                        u_star = u
                if u_star is None:
                    break  # should not happen
                S.append(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Smallest-Last (Matula-Beck) ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            if degree[v] < len(buckets):
                buckets[degree[v]].add(v)
        # peel min degree vertex
        for _ in range(n):
            # find non-empty bucket with smallest index
            i = 0
            while i < len(buckets) and not buckets[i]:
                i += 1
            if i >= len(buckets):
                break  # should not happen
            v = buckets[i].pop()
            order.append(v)
            # update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # remove u from current degree bucket
                    if degree[u] < len(buckets):
                        buckets[degree[u]].discard(u)
                    degree[u] -= 1
                    if degree[u] < len(buckets):
                        buckets[degree[u]].add(u)
            remaining.remove(v)
        # color in reverse order using first-fit
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring
        k = count_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # try to recolor each vertex in this class
            removed = True
            while verts and removed:
                removed = False
                v = verts.pop()
                # try direct reassignment to a lower color
                neighbor_colors = 0
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        neighbor_colors |= (1 << coloring[u])
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        # move v to color c
                        coloring[v] = c
                        removed = True
                        break
                if removed:
                    continue
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # if v already has a neighbor of color c, swapping may not help
                    has_neighbor_c = any(coloring[u] == c for u in adj_list[v])
                    if has_neighbor_c:
                        continue
                    # build Kempe chain of colors {c, target_color} containing v
                    # we consider swapping only if v is not adjacent to color c (to avoid immediate conflict)
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == c or coloring[node] == target_color:
                            component.add(node)
                            for nb in adj_list[node]:
                                if nb not in visited and (coloring[nb] == c or coloring[nb] == target_color):
                                    stack.append(nb)
                    # check if any neighbor of v in the component has color c? Actually, we want to see if swapping frees color c for v
                    # After swap, v would get color c if it was target_color and in the component.
                    # We need to ensure that no neighbor of v gets color target_color after swap (which would conflict if v becomes c)
                    # But actually, we are going to swap colors in the component: c->target_color, target_color->c.
                    # For v to be recolored to c, it must be in the component and currently target_color.
                    # After swap, its neighbors that are in the component and were color c become target_color.
                    # So if v has a neighbor in the component that is color c, after swap that neighbor becomes target_color, same as v's original color -> no conflict.
                    # The only potential conflict is if v has a neighbor outside the component that is color target_color? 
                    # But if such neighbor existed, it would be in the component (since it's target_color and adjacent to v which is target_color? 
                    # Wait: v is target_color, neighbor is target_color -> edge between same color -> invalid coloring. So cannot happen.
                    # Similarly, neighbor outside component that is color c: after swap, v becomes c, neighbor remains c -> conflict.
                    # So we must check: after swap, does v have any neighbor with color c (outside component)?
                    # Actually, neighbors with color c outside component would remain c, and v becomes c -> conflict.
                    # So we need that v has no neighbor with color c outside the Kempe component.
                    safe = True
                    for nb in adj_list[v]:
                        if coloring[nb] == c and nb not in component:
                            safe = False
                            break
                    if safe:
                        # perform swap
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        removed = True
                        break
                if removed:
                    # restart the while loop for this target_color since coloring changed
                    verts = [v for v in range(n) if coloring[v] == target_color]
                    break
            # if we eliminated the color class, break and try again from high color
            if not any(coloring[v] == target_color for v in range(n)):
                # compact colors: remap to 0..k-2
                mapping = {}
                new_color = 0
                for col in range(k):
                    if col == target_color:
                        continue
                    mapping[col] = new_color
                    new_color += 1
                for v in range(n):
                    if coloring[v] != -1:
                        coloring[v] = mapping[coloring[v]]
                # restart reduction from scratch with new coloring
                return kempe_reduce(coloring)
        return coloring

    # Generate candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best = None
    best_colors = float('inf')
    for cand in candidates:
        if not is_valid_coloring(cand):
            # fix by greedy reassign if needed (should not happen)
            # but just in case, apply first-fit in vertex order
            fixed = [-1] * n
            for v in range(n):
                used = 0
                for u in adj_list[v]:
                    if fixed[u] != -1:
                        used |= (1 << fixed[u])
                c = 0
                while used & (1 << c):
                    c += 1
                fixed[v] = c
            cand = fixed
        cand = normalize_colors(cand)
        if not is_valid_coloring(cand):
            continue
        num_colors = count_colors(cand)
