                sat = saturation[v].bit_count()
                deg = uncolored_deg[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                   (sat == best_sat and deg == best_deg and (best_v == -1 or random.random() < 0.5)):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v

            # Find smallest available color (not in saturation mask)
            used_colors = saturation[v]
            c = 0
            while used_colors & (1 << c):
                c += 1
            colors[v] = c

            # Update neighbors
            for u in graph[v]:
                if colors[u] == -1:  # if neighbor uncolored
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
            uncolored_count -= 1

        return normalize(colors)

    # RLF (Recursive Largest First) with bitmask
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build independent set for this color
            independent_set = []
            # Candidates: vertices not adjacent to any in independent_set
            # We'll maintain eligible set U and ineligible set W
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # Find vertex in uncolored with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            independent_set.append(v)
            # U: vertices in uncolored not adjacent to v
            # W: vertices in uncolored adjacent to v
            U = uncolored - {v} - set(graph[v])
            W = set(graph[v]) & uncolored

            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = -1  # degree in U for tie-break
                for u in U:
                    # Count neighbors of u in W
                    w_neighbors = 0
                    for y in graph[u]:
                        if y in W:
                            w_neighbors += 1
                    # Degree in U
                    u_deg = 0
                    for y in graph[u]:
                        if y in U:
                            u_deg += 1
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or \
                       (w_neighbors == best_w_neighbors and u_deg == best_u_deg and (best_u == -1 or random.random() < 0.5)):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                independent_set.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in graph[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
            # Remove independent set from uncolored
            uncolored -= set(independent_set)
            color_idx += 1

        return normalize(colors)

    # Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(graph[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order
        # We'll use bucket sort for efficiency (since n <= 100)
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].append(i)

        # Pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # Find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in graph[v]:
                if not removed[u]:
                    d = deg[u]
                    buckets[d].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].append(u)
                    if deg[u] < min_deg:
                        min_deg = deg[u]

        # Color in reverse order (last removed first)
        colors = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by neighbors
            used = [False] * (n + 1)  # safe upper bound
            for u in graph[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            c = 0
            while used[c]:
                c += 1
            colors[v] = c

        return normalize(colors)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (shouldn't happen), fall back to greedy
    if not candidates:
        colors = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for j in graph[i]:
                if colors[j] != -1:
                    used[colors[j]] = True
            c = 0
            while used[c]:
                c += 1
            colors[i] = c
        candidates.append(normalize(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: count_colors(x))

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        k = count_colors(coloring)
        # Try to eliminate color classes from highest downward
        for target_color in range(k-1, -1, -1):
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                continue
            # Try to recolor each target vertex
            made_change = False
            for v in target_vertices[:]:  # work on copy
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in graph[v]:
                    if coloring[u] < target_color:  # only consider colors we might reassign to
                        neighbor_colors.add(coloring[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Found a free color, reassign
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    # After reassigning v, we might have emptied target_color class
                    # But continue to try to empty the whole class
                    continue
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # We'll try to swap colors c and target_color in the component containing v
                    # Only if v is not adjacent to any vertex of color c (otherwise swap would cause conflict)
                    has_c_neighbor = any(coloring[u] == c for u in graph[v])
                    if has_c_neighbor:
                        continue  # swapping would put two c's together
                    # Build the Kempe chain: connected component of v in subgraph of colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    valid = True
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in graph[node]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any node in component has a neighbor with color c (outside component) that would cause conflict if swapped
                    # Actually, after swap, nodes originally color c become target_color and vice versa.
                    # Conflict would occur if a node in component (originally c) has a neighbor outside component that is target_color,
                    # or a node in component (originally target_color) has a neighbor outside component that is c.
                    # But we already know v has no c neighbor (has_c_neighbor false). Need to check others.
                    conflict = False
                    for node in component:
                        orig_color = coloring[node]
                        for nb in graph[node]:
                            if not visited[nb]:  # neighbor outside component
                                if orig_color == c and coloring[nb] == target_color:
                                    conflict = True
                                    break
                                if orig_color == target_color and coloring[nb] == c:
                                    conflict = True
                                    break
                        if conflict:
                            break
                    if not conflict:
                        # Perform swap
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            else:  # must be target_color
                                coloring[node] = c
                        made_change = True
                        break  # break from color loop, go to next vertex
                if made_change:
                    # After changing v, break to restart the target_color class scan (since composition changed)
                    break
            if not made_change:
                # Could not recolor any vertex in this class, move to next color
                continue
            else:
                # We made a change, so restart the reduction from the highest color again
                # because the color count may have reduced
                return kempe_reduce(coloring)
        # If we made it through all colors without change, return
        return normalize(coloring)

    # Apply Kempe reduction to the best candidate
    try:
        improved = kempe_reduce(best[:])  # work on a copy
        if is_valid(improved) and count_colors(improved) < count_colors(best):
            best = improved
    except:
        pass  # if kempe fails, keep original

    # Final normalization and validation
    best = normalize(best)
    if not is_valid(best):
        # Fallback to greedy if something went wrong
        colors = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for j in graph[i]:
                if colors[j] != -1:
                    used[colors[j]] = True
            c = 0
            while used[c]:
                c += 1
            colors[i] = c
        best = normalize(colors)

    return best

