                        # Build component of v in subgraph of colors c and target_color
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            x = queue.popleft()
                            component.append(x)
                            for y in range(n):
                                if y != x and ((bit_adj[x] >> y) & 1) and not visited[y]:
                                    if best[y] == c or best[y] == target_color:
                                        visited[y] = True
                                        queue.append(y)
                        # Check if any neighbor of v with color c is NOT in this component
                        # If so, we can swap colors in the component to free color c for v
                        has_external = False
                        for y in range(n):
                            if y != v and ((bit_adj[v] >> y) & 1) and best[y] == c and not visited[y]:
                                has_external = True
                                break
                        if has_external:
                            # Swap colors c and target_color in component
                            for x in component:
                                if best[x] == c:
                                    best[x] = target_color
                                elif best[x] == target_color:
                                    best[x] = c
                            improved = True
                            # After swap, v now has color c (since it was target_color and swapped)
                            # Check if target_color is still used
                            if target_color not in best:
                                best_k -= 1
                                mapping = {}
                                next_c = 0
                                for i in range(n):
                                    if best[i] not in mapping:
                                        mapping[best[i]] = next_c
                                        next_c += 1
                                for i in range(n):
                                    best[i] = mapping[best[i]]
                            break
                if improved:
                    break

    # Final validation and compacting (ensure 0..k-1)
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
    # Compact colors
    mapping = {}
    next_c = 0
    for i in range(n):
        if best[i] not in mapping:
            mapping[best[i]] = next_c
            next_c += 1
    for i in range(n):
        best[i] = mapping[best[i]]

    return best

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

