    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute bitmask representation
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Precompute neighbor bitmasks and degrees
    neighbor_mask = [0] * n
    degrees = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        neighbor_mask[u] = mask
        degrees[u] = len(adj_list[u])

    # Helper: test if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize_colors(colors):
        if not colors:
            return colors
        # Map used colors to 0..k-1
        used = sorted(set(colors))
        mapping = {old: new for new, old in enumerate(used)}
        return [mapping[c] for c in colors]

    # Heuristic 1: DSATUR with bitmask optimization
    def dsatur():
        colors = [-1] * n
        # Track saturation: for each vertex, bitmask of colors used by neighbors
        neighbor_colors = [0] * n  # bitmask: bit i set if color i is used by a neighbor

        # Precompute neighbor lists for quick access
        # We'll use neighbor_mask for bit operations

        # Order of coloring
        for _ in range(n):
            # Select uncolored vertex with max saturation degree
            # Saturation degree = number of distinct colors in neighbors = bit_count(neighbor_colors[v])
            max_sat = -1
            candidates = []
            for v in range(n):
                if colors[v] == -1:
                    sat = neighbor_colors[v].bit_count()
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)

            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                selected = candidates[0]
                for v in candidates:
                    # Count uncolored neighbors
                    deg_uncolored = 0
                    for u in adj_list[v]:
                        if colors[u] == -1:
                            deg_uncolored += 1
                    if deg_uncolored > max_deg:
                        max_deg = deg_uncolored
                        selected = v
                v = selected
            else:
