            for v in neighbors[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, then max uncolored degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u].bit_count()
                deg_u = uncolored_deg[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and u > v):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            # Assign smallest available color
            c = 0
            while saturation[v] & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = uncolored - {v} - (neighbors[v] & uncolored)
            # W: vertices adjacent to at least one in independent_set
            W = (neighbors[v] & uncolored)
            while U:
                # Select u in U with max neighbors in W, then min degree in U-induced subgraph
                u = -1
                max_w_neighbors = -1
                min_u_degree = float('inf')
                for candidate in U:
                    w_neighbors = len(neighbors[candidate] & W)
                    u_degree = len(neighbors[candidate] & U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and u_degree < min_u_degree) or \
                       (w_neighbors == max_w_neighbors and u_degree == min_u_degree and candidate < u):
                        max_w_neighbors = w_neighbors
                        min_u_degree = u_degree
                        u = candidate
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbors[u] & U
                U -= nbrs_u
                W |= nbrs_u
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].add(v)

        for _ in range(n):
            # Find vertex with min degree
            v = -1
            for d in range(max_deg + 1):
                if buckets[d]:
                    v = buckets[d].pop()
                    break
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = deg[u]
                    deg[u] -= 1
                    buckets[old_deg].remove(u)
                    buckets[deg[u]].add(u)
            remaining.remove(v)
        # Color in reverse order
        return greedy_color(reversed(order))

    # Strategy 4: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except:
            continue

    # Select best candidate
    for col in candidates:
        k = count_colors(col)
        if k < best_k:
            best_k = k
            best_coloring = col

    # If no candidate found (should not happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return True  # already empty

        # Try direct reassignment first
        for v in vertices:
            used = 0
            for u in neighbors[v]:
                used |= (1 << coloring[u])
            for c in range(target_color):  # only try colors < target_color
                if not (used & (1 << c)):
                    coloring[v] = c
                    return True  # success, color class reduced

        # Try Kempe chains for each vertex
        for v in vertices:
            for c in range(target_color):
                # Check if v can be swapped via (target_color, c) Kempe chain
                # Build component of v in subgraph of colors target_color and c
                from collections import deque
                visited = set()
                queue = deque([v])
                visited.add(v)
                component = set()
                while queue:
                    x = queue.popleft()
                    component.add(x)
                    for y in neighbors[x]:
                        if coloring[y] in (target_color, c) and y not in visited:
                            visited.add(y)
                            queue.append(y)
                # Check if any neighbor of v has color c (would cause conflict if swapped)
                conflict = False
                for x in component:
                    for y in neighbors[x]:
                        if coloring[y] == c and y not in component:
                            conflict = True
                            break
                    if conflict:
                        break
                if not conflict:
                    # Perform swap
                    for x in component:
                        if coloring[x] == target_color:
                            coloring[x] = c
                        else:
                            coloring[x] = target_color
                    return True
        return False

    # Iteratively try to reduce colors
    changed = True
    while changed and best_k > 0:
        changed = False
        target = best_k - 1
        if eliminate_color_class(best_coloring, target):
            # Compact colors: remap to 0..best_k-2
            mapping = {}
            next_color = 0
            for v in range(n):
                if best_coloring[v] not in mapping:
                    mapping[best_coloring[v]] = next_color
                    next_color += 1
                best_coloring[v] = mapping[best_coloring[v]]
            best_k -= 1
            changed = True

    return best_coloring

