def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Convert to adjacency list if needed
    if len(adj[0]) == n and all(all(x in (0, 1) for x in row) for row in adj):
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    graph[i].append(j)
    else:
        graph = adj

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in graph[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert coloring to consecutive 0..k-1
    def normalize_coloring(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR with bitmask optimization
    def dsatur():
        if n == 0:
            return []
        # Build bitmask adjacency
        bit_adj = [0] * n
        for u in range(n):
            for v in graph[u]:
                bit_adj[u] |= (1 << v)
