        colors = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color masks for fast saturation update
        neighbor_color_mask = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    sat_u = saturation[u]
                    deg_u = bit_adj[u].bit_count()
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
                    elif sat_u == max_sat and deg_u == max_deg and v == -1:
                        v = u  # first encountered
            if v == -1:
                break  # should not happen
            # Find smallest available color
            used = neighbor_color_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            # Update saturation and neighbor masks for neighbors
            for u in graph[v]:
                if not colored[u]:
                    # If this color is new in u's neighborhood, increase saturation
                    if not (neighbor_color_mask[u] & (1 << c)):
                        saturation[u] += 1
                        neighbor_color_mask[u] |= (1 << c)
        return normalize_coloring(colors)

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        if n == 0:
            return []
        colored = [False] * n
        colors = [-1] * n
        color_idx = 0
        # Precompute degree in full graph for initial selection
        full_deg = [len(graph[u]) for u in range(n)]

        while not all(colored):
            # Find uncolored vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    # degree in uncolored subgraph
                    deg = 0
                    for w in graph[u]:
                        if not colored[w]:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        v = u
                    elif deg == max_deg and v == -1:
                        v = u
            if v == -1:
                break
            # Build independent set S for this color
            S = [v]
            colored[v] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if not colored[u]:
                    if u == v or v not in graph[u]:
                        U.add(u)
                    else:
                        W.add(u)
            # Expand S
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for w in graph[u]:
                        if w in W:
                            w_count += 1
                    # Degree in U
                    deg_in_U = 0
                    for w in graph[u]:
                        if w in U:
                            deg_in_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in graph[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for u in S:
                colors[u] = color_idx
            color_idx += 1
        return normalize_coloring(colors)

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        remaining = set(range(n))
        deg = [len(graph[u]) for u in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in graph[v]:
                if u in remaining:
                    deg[u] -= 1
                    if deg[u] < len(buckets):
                        buckets[deg[u]].append(u)
                    else:
                        # Should not happen if buckets sized to max_deg
                        pass
        # Color in reverse order using First-Fit
        colors = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)  # n colors enough
            for u in graph[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            c = 0
            while used[c]:
                c += 1
            colors[v] = c
        return normalize_coloring(colors)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring
        # Make coloring consecutive
        coloring = normalize_coloring(coloring)
        k = max(coloring) + 1 if n > 0 else 0
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest downward
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                k -= 1
                improved = True
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = [False] * k
                for u in graph[v]:
                    if coloring[u] != -1:
                        used[coloring[u]] = True
                for c in range(target_color):
                    if not used[c]:
                        # Check if moving v to c is valid (no neighbor has c)
                        conflict = False
                        for u in graph[v]:
                            if coloring[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            coloring[v] = c
                            improved = True
                            break
                if improved:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # (target_color, c)-Kempe chain containing v
                    # We'll try to swap if it doesn't pull any vertex into target_color
                    from collections import deque
                    visited = [False] * n
                    q = deque([v])
                    visited[v] = True
                    component = []
                    while q:
                        node = q.popleft()
                        component.append(node)
                        for nb in graph[node]:
                            if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                visited[nb] = True
                                q.append(nb)
                    # Check if swapping would cause any vertex in component to get target_color
                    # After swap: target_color -> c, c -> target_color
                    # So vertices originally colored c will become target_color
                    # We need to ensure no neighbor of any vertex in component (outside) has target_color
                    # because after swap, they would conflict
                    valid_swap = True
                    for node in component:
                        if coloring[node] == c:  # will become target_color
                            for nb in graph[node]:
                                if not visited[nb] and coloring[nb] == target_color:
                                    valid_swap = False
                                    break
                            if not valid_swap:
                                break
                    if valid_swap:
                        # Perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                coloring = normalize_coloring(coloring)
                k = max(coloring) + 1 if n > 0 else 0
            else:
                break
        return coloring

    # Run all heuristics
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best (fewest colors)
    best = None
    best_k = float('inf')
    for coloring in candidates:
        if not is_valid_coloring(coloring):
            continue
        k = len(set(coloring))
        if k < best_k:
            best_k = k
            best = coloring
    if best is None:
        # Fallback: greedy
        best = [0] * n
        for i in range(n):
            used = [False] * (n + 1)
            for nb in graph[i]:
                if best[nb] != -1:
                    used[best[nb]] = True
            c = 0
            while used[c]:
                c += 1
            best[i] = c
        best = normalize_coloring(best)

    # Apply Kempe reduction
    best = kempe_reduce(best)
    # Final validation and normalization
    if not is_valid_coloring(best):
        # Last resort: greedy
        best = [0] * n
        for i in range(n):
            used = [False] * (n + 1)
            for nb in graph[i]:
                if best[nb] != -1:
                    used[best[nb]] = True
            c = 0
            while used[c]:
                c += 1
            best[i] = c
    best = normalize_coloring(best)
    return best

