                                for x in component:
                                    old = target if colors[x] == c else c
                                    new = colors[x]
                                    color_classes[old].remove(x)
                                    if not color_classes[old]:
                                        del color_classes[old]
                                    color_classes.setdefault(new, []).append(x)
                                # update target class and verts
                                if v in color_classes.get(target, []):
                                    verts.append(v)  # should not happen, but safe
                                else:
                                    if v in verts:
                                        verts.remove(v)
                                changed = True
                                break
                        if changed:
                            break
            # if target color class eliminated, break to restart from new max
            if target not in color_classes:
                break
        # compact colors to 0..k-1
        # map current colors to consecutive integers
        unique_colors = sorted(set(colors))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        colors = [mapping[c] for c in colors]
        return colors

    best = kempe_reduce(best)
    # final validation (optional, but safe)
    for u in range(n):
        for v in graph[u]:
            if u < v and colors[u] == colors[v]:
                # should not happen, but if so, fallback to DSATUR
                return dsatur()
    return best

