    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        # degree in uncolored subgraph (initially full degree)
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                deg = uncolored_deg[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update saturation and uncolored degree of neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return colors

    # RLF: Recursive Largest First independent set extraction
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S.add(v)
            # partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(w in neighbors[u] for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # while U not empty, add vertex with max neighbors in W, tie-break by min degree in U
            while U:
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = float('inf')
                for u in U:
                    w_neighbors = len([w for w in neighbors[u] if w in W])
                    u_deg = len([w for w in neighbors[u] if w in U])
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or (w_neighbors == best_w_neighbors and u_deg == best_u_deg and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
            uncolored = W  # next iteration only considers vertices adjacent to S
        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get removal order
        deg = [len(neighbors[i]) for i in range(n)]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # track position of each vertex in its bucket for O(1) removal
        pos = [0] * n
        for d in range(max_deg + 1):
            for i, v in enumerate(buckets[d]):
                pos[v] = i
        order = []
        current_deg = 0
        for _ in range(n):
            # find first non-empty bucket
            while current_deg <= max_deg and not buckets[current_deg]:
                current_deg += 1
            if current_deg > max_deg:
                break  # should not happen
            v = buckets[current_deg].pop()
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if deg[u] > current_deg:  # u not yet removed
                    d = deg[u]
                    # remove u from bucket d
                    i = pos[u]
                    last = buckets[d][-1]
                    buckets[d][i] = last
                    pos[last] = i
                    buckets[d].pop()
                    # decrease degree
                    deg[u] -= 1
                    dnew = deg[u]
                    buckets[dnew].append(u)
                    pos[u] = len(buckets[dnew]) - 1
        # color in reverse removal order
        return greedy_color(order[::-1])

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # make a copy we can modify
        col = colors[:]
        improved = True
        while improved and k > 1:
            improved = False
            # target the last color (k-1)
            target_color = k - 1
            # vertices with target color
            targets = [v for v in range(n) if col[v] == target_color]
            if not targets:
                # should not happen, but safety
                k -= 1
                continue
            # try to recolor each target vertex
            for v in targets:
                # try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = col[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target_color):  # only try colors < target_color
                    if not (used & (1 << c)):
                        col[v] = c
                        improved = True
                        break
                if improved:
                    # after recoloring v, check if target color class is empty
                    if any(col[x] == target_color for x in range(n)):
                        # not empty yet, continue to next vertex
                        pass
                    else:
                        # target color eliminated, compact colors
                        k -= 1
                        # remap colors > target_color down by one
                        for x in range(n):
                            if col[x] > target_color:
                                col[x] -= 1
                        break  # break for-loop, restart while-loop with new k
                # if direct reassignment failed, try Kempe chains
                if not improved:
                    for c in range(target_color):
                        # if v has a neighbor with color c, Kempe chain might help
                        has_neighbor_c = any(col[u] == c for u in neighbors[v])
                        if not has_neighbor_c:
                            continue
                        # build Kempe chain of colors c and target_color containing v
                        # BFS/DFS over vertices with color c or target_color
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            x = stack.pop()
                            if x in visited:
                                continue
                            visited.add(x)
                            if col[x] == c or col[x] == target_color:
                                component.add(x)
                                for u in neighbors[x]:
                                    if col[u] == c or col[u] == target_color:
                                        if u not in visited:
                                            stack.append(u)
                        # check if any neighbor of v with color c is NOT in this component
                        # i.e., exists neighbor u of v with col[u]==c and u not in component
                        neighbor_c_outside = False
                        for u in neighbors[v]:
                            if col[u] == c and u not in component:
                                neighbor_c_outside = True
                                break
                        if neighbor_c_outside:
                            # swap colors c and target_color in component
                            for x in component:
                                if col[x] == c:
                                    col[x] = target_color
                                elif col[x] == target_color:
                                    col[x] = c
                            improved = True
                            # after swap, v should now have color c (since it was target_color and in component)
                            # check if target color class is empty
                            if not any(col[x] == target_color for x in range(n)):
                                k -= 1
                                for x in range(n):
                                    if col[x] > target_color:
                                        col[x] -= 1
                            break  # break color loop
                    if improved:
                        break  # break vertex loop
            # end for vertices
        # end while
        # ensure colors are compact
        if k < num_colors(col):
            # remap to 0..k-1
            mapping = {}
            next_c = 0
            for v in range(n):
                c = col[v]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                col[v] = mapping[c]
            k = next_c
        return col

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass
    # Fallback: simple greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(c4)
        else:
            # last resort: assign each vertex a unique color
            candidates.append(list(range(n)))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    try:
        best_kempe = kempe_reduce(best)
        if is_valid(best_kempe) and num_colors(best_kempe) < num_colors(best):
            best = best_kempe
    except Exception:
        pass

    # Final validation and compacting
    if not is_valid(best):
        # Should not happen, but ensure validity by greedy re-color
        order = list(range(n))
        best = greedy_color(order)
    # Ensure colors are consecutive starting from 0
    mapping = {}
    next_c = 0
    for v in range(n):
        c = best[v]
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
        best[v] = mapping[c]
    return best

