        all_binary = True
        for i in range(n):
            if len(adj[i]) != n:
                all_binary = False
                break
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
