    def dsatur():
        color = [-1] * n
        saturation = [0] * n  # number of distinct colors in neighborhood
        neighbor_colors = [0] * n  # bitmask of colors used by neighbors

        # Order by degree descending for tie-breaking
        order = list(range(n))
        order.sort(key=lambda x: len(adj_list[x]), reverse=True)

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then order
            v = -1
            max_sat = -1
            max_deg = -1
            for u in order:
                if color[u] != -1:
