    # RLF heuristic (Largest First Independent Set)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S.append(v)
            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in adj_list[u] for w in S):
                    U.remove(u)
                    W.add(u)
            # Grow independent set
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for y in adj_list[u] if y in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or (w_neighbors == max_w_neighbors and deg_u == min_deg_u and u < best_u):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for y in adj_list[best_u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering (smallest last)
        deg = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # We'll use bucket sort for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    deg[u] -= 1
