            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain swap for color elimination
    def kempe_swap(color, target_color, swap_color):
        # Find vertices with target_color
        targets = [i for i in range(n) if color[i] == target_color]
        if not targets:
            return color, True  # already empty

        # Try to recolor each target vertex
        for v in targets:
            # Check if v can take swap_color directly
            conflict = False
            for u in adj_list[v]:
                if color[u] == swap_color:
                    conflict = True
                    break
            if not conflict:
                color[v] = swap_color
                continue

            # Build (target_color, swap_color) Kempe chain containing v
            # We'll do BFS to get the component
            from collections import deque
            visited = [False] * n
            queue = deque([v])
            visited[v] = True
            component = []
            while queue:
                node = queue.popleft()
                component.append(node)
                for nb in adj_list[node]:
                    if not visited[nb] and (color[nb] == target_color or color[nb] == swap_color):
                        visited[nb] = True
                        queue.append(nb)

            # Check if swapping this component is safe: no neighbor of component has swap_color outside
            safe = True
            for node in component:
                for nb in adj_list[node]:
                    if color[nb] == swap_color and not visited[nb]:
                        safe = False
                        break
                if not safe:
                    break

            if safe:
                # Perform swap: target_color <-> swap_color in component
                for node in component:
                    if color[node] == target_color:
                        color[node] = swap_color
                    else:
                        color[node] = target_color
                # After swap, v now has swap_color
                return color, True

        # Could not eliminate target_color via Kempe swaps
        return color, False

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select candidate with fewest colors
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate and compact colors
        if not col or len(col) != n:
            continue
        # Check validity
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        # Compact colors to 0..k-1
        unique_colors = set(col)
        mapping = {c: i for i, c in enumerate(sorted(unique_colors))]
        compacted = [mapping[c] for c in col]
        k = len(unique_colors)
        if k < best_k:
            best_k = k
            best_color = compacted

    # If no valid candidate, fallback to greedy (should not happen)
    if best_color is None:
        best_color = [0] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                used |= (1 << best_color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            best_color[i] = c
        # Compact
        unique_colors = set(best_color)
        mapping = {c: i for i, c in enumerate(sorted(unique_colors))]
        best_color = [mapping[c] for c in best_color]

    # Iterative Kempe chain color reduction
    max_iter = 10  # safety bound
    for _ in range(max_iter):
        # Find smallest color class
        color_classes = [[] for _ in range(best_k)]
        for v in range(n):
            color_classes[best_color[v]].append(v)
        # Find non-empty color classes from high to low
        target_color = -1
        for c in range(best_k-1, -1, -1):
            if color_classes[c]:
                target_color = c
                break
        if target_color == -1 or target_color == 0:
            break  # no more colors to eliminate or only color 0 left

        # Try to eliminate target_color by moving to lower colors
        eliminated = False
        # Try each lower color
        for swap_color in range(target_color):
            new_color, success = kempe_swap(best_color[:], target_color, swap_color)
            if success:
                # Validate and compact
                valid = True
                for u in range(n):
                    for v in adj_list[u]:
                        if new_color[u] == new_color[v]:
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    unique_colors = set(new_color)
                    mapping = {c: i for i, c in enumerate(sorted(unique_colors))]
                    compacted = [mapping[c] for c in new_color]
                    best_color = compacted
                    best_k = len(unique_colors)
                    eliminated = True
                    break
        if not eliminated:
            break  # cannot reduce further

    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    deg = [len(neighbors[i]) for i in range(n)]

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        unique = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            coloring[i] = unique[c]
        return coloring

    # DSATUR
    def dsatur():
        coloring = [-1] * n
        # saturation: list of sets of neighbor colors
        sat_sets = [set() for _ in range(n)]
        # degree in uncolored subgraph
        uncolored_deg = deg[:]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = len(sat_sets[u])
                if sat > max_sat or (sat == max_sat and (uncolored_deg[u] > max_deg or (uncolored_deg[u] == max_deg and random.random() < 0.5))):
                    max_sat = sat
                    max_deg = uncolored_deg[u]
                    v = u
            # assign smallest available color
            used = sat_sets[v]
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat_sets[u].add(c)
                    uncolored_deg[u] -= 1
        return compact_colors(coloring)

    # RLF
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # partition: U (eligible), W (ineligible)
            W = set(neighbors[v]) & uncolored
            U = uncolored - {v} - W
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                u = -1
                max_w_neighbors = -1
                min_u_deg = float('inf')
                for cand in U:
                    w_neighbors = sum(1 for y in neighbors[cand] if y in W)
                    u_deg = sum(1 for y in neighbors[cand] if y in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and u_deg < min_u_deg):
                        max_w_neighbors = w_neighbors
                        min_u_deg = u_deg
                        u = cand
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # assign color to S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
        return compact_colors(coloring)

    # Smallest-Last ordering greedy
    def smallest_last():
        # degeneracy ordering: repeatedly remove min degree vertex
        order = []
        degrees = deg[:]
        remaining = set(range(n))
        # bucket sort for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in remaining:
            buckets[degrees[v]].append(v)
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = degrees[u]
                    buckets[old_deg].remove(u)
                    degrees[u] -= 1
                    new_deg = degrees[u]
                    if new_deg < len(buckets):
                        buckets[new_deg].append(u)
                    else:
                        # should not happen as degree decreases
                        pass
            if ptr > degrees[v] if v in remaining else 0:
                ptr = min(degrees[u] for u in remaining) if remaining else 0
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = {coloring[u] for u in neighbors[v] if coloring[u] != -1}
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        return compact_colors(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex
            removed = True
            while verts and removed:
                removed = False
                v = verts.pop()
                # Try direct reassignment to a lower color
                neighbor_colors = {coloring[u] for u in neighbors[v]}
                for c in range(target_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        removed = True
                        break
                if removed:
                    continue
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue
                    # Build (target_color, c)-Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for nb in neighbors[node]:
                                if nb not in visited and (coloring[nb] == target_color or coloring[nb] == c):
                                    stack.append(nb)
                    # Check if swapping this component would free target_color for v
                    # After swap, v would become c, so we need that no neighbor of v is c after swap
                    # Neighbors of v that are in component and colored c will become target_color
                    # So we need that no neighbor of v is colored c and not in component (they stay c)
                    # and no neighbor of v is in component and colored c (they become target_color, safe)
                    # Actually, after swap: 
                    #   - nodes in component: target_color <-> c
                    #   - v is target_color -> becomes c
                    #   - a neighbor u of v:
                    #       if u in component and coloring[u]==c -> becomes target_color (not c)
                    #       if u in component and coloring[u]==target_color -> becomes c (conflict!)
                    #       if u not in component: color unchanged
                    # So conflict if exists neighbor u of v such that:
                    #   (u not in component and coloring[u]==c) OR (u in component and coloring[u]==target_color)
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c:
                            if u not in component:
                                conflict = True
                                break
                        elif coloring[u] == target_color:
                            if u in component:
                                conflict = True
                                break
                    if not conflict:
                        # perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        removed = True
                        break
                if not removed:
                    verts.append(v)  # put back for next round
            # If all vertices of target_color are recolored, we can reduce k
            if not any(coloring[v] == target_color for v in range(n)):
                # remap colors > target_color down by 1
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                break  # restart from new highest color
        return compact_colors(coloring)

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            used = {coloring[u] for u in neighbors[v] if coloring[u] != -1}
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        candidates.append(compact_colors(coloring))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid(best):
        # last resort: greedy
        coloring = [-1] * n
        for v in range(n):
            used = {coloring[u] for u in neighbors[v] if coloring[u] != -1}
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best = compact_colors(coloring)
    else:
        best = compact_colors(best)
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            if not all(x in (0, 1) for x in row):
                is_matrix = False
                break

    # Build bitmask adjacency
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            mask = 0
            for v in range(n):
                if adj[u][v]:
                    mask |= (1 << v)
            bit_adj[u] = mask
    else:
        for u in range(n):
            mask = 0
            for v in adj[u]:
                if 0 <= v < n:
                    mask |= (1 << v)
            bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            nbrs = bit_adj[u]
            v = nbrs
            while v:
                lb = v & -v
                idx = (lb.bit_length() - 1)
                if color[idx] != -1:
                    used |= (1 << color[idx])
                v ^= lb
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            c_u = coloring[u]
            nbrs = bit_adj[u]
            v = nbrs
            while v:
                lb = v & -v
                idx = (lb.bit_length() - 1)
                if coloring[idx] == c_u:
                    return False
                v ^= lb
        return True

    # DSATUR with degree tie-breaking
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        saturation = [0] * n
        degree = [bin(bit_adj[i]).count('1') for i in range(n)]
        while uncolored:
            # Find vertex with max saturation, tie-break by degree, then random
            candidates = []
            max_sat = -1
            for v in uncolored:
                if saturation[v] > max_sat:
                    max_sat = saturation[v]
                    candidates = [v]
                elif saturation[v] == max_sat:
                    candidates.append(v)
            # Tie-break by degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                final_candidates = []
                for v in candidates:
                    deg = bin(bit_adj[v] & sum((1 << u) for u in uncolored)).count('1')
                    if deg > max_deg:
                        max_deg = deg
                        final_candidates = [v]
                    elif deg == max_deg:
                        final_candidates.append(v)
                candidates = final_candidates
            v = random.choice(candidates) if candidates else next(iter(uncolored))
            uncolored.remove(v)
            # Compute used colors from neighbors
            used = 0
            nbrs = bit_adj[v]
            w = nbrs
            while w:
                lb = w & -w
                idx = (lb.bit_length() - 1)
                if color[idx] != -1:
                    used |= (1 << color[idx])
                w ^= lb
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            # Update saturation of uncolored neighbors
            nbrs = bit_adj[v]
            w = nbrs
            while w:
                lb = w & -w
                idx = (lb.bit_length() - 1)
                if idx in uncolored:
                    saturation[idx] += 1
                w ^= lb
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            S = []
            # Compute degrees in uncolored subgraph
            deg_uncolored = {}
            for v in uncolored:
                deg = bin(bit_adj[v] & sum((1 << u) for u in uncolored)).count('1')
                deg_uncolored[v] = deg
            v1 = max(uncolored, key=lambda x: deg_uncolored[x])
            S.append(v1)
            # U: vertices not adjacent to any in S
            # W: vertices adjacent to at least one in S
            adj_S = 0
            for u in S:
                adj_S |= bit_adj[u]
            U = uncolored - {v1} - set([i for i in range(n) if (adj_S >> i) & 1])
            W = uncolored - U - {v1}
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_U = math.inf
                for u in U:
                    nbrs_u = bit_adj[u]
                    w_count = bin(nbrs_u & sum((1 << w) for w in W)).count('1')
                    if w_count > max_w_neighbors:
                        max_w_neighbors = w_count
                        min_deg_U = bin(nbrs_u & sum((1 << x) for x in U)).count('1')
                        best_u = u
                    elif w_count == max_w_neighbors:
                        deg_u = bin(nbrs_u & sum((1 << x) for x in U)).count('1')
                        if deg_u < min_deg_U:
                            min_deg_U = deg_u
                            best_u = u
                if best_u is None:
                    break  # should not happen
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                nbrs_best = bit_adj[best_u]
                w = nbrs_best
                while w:
                    lb = w & -w
                    idx = (lb.bit_length() - 1)
                    if idx in U:
                        U.remove(idx)
                        W.add(idx)
                    w ^= lb
            # Assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute core ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        # We'll simulate removal
        current_degrees = degrees[:]
        removed = [False] * n
        for _ in range(n):
            # Find vertex with minimum current degree
            min_deg = math.inf
            min_v = -1
            for v in remaining:
                if current_degrees[v] < min_deg:
                    min_deg = current_degrees[v]
                    min_v = v
            if min_v == -1:
                break
            order.append(min_v)
            removed[min_v] = True
            remaining.remove(min_v)
            # Update degrees of neighbors
            nbrs = bit_adj[min_v]
            w = nbrs
            while w:
                lb = w & -w
                idx = (lb.bit_length() - 1)
                if not removed[idx]:
                    current_degrees[idx] -= 1
                w ^= lb
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen if starting from valid
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already empty, compact
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                k -= 1
                changed = True
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                nbrs = bit_adj[v]
                w = nbrs
                while w:
                    lb = w & -w
                    idx = (lb.bit_length() - 1)
                    if coloring[idx] != -1:
                        used |= (1 << coloring[idx])
                    w ^= lb
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Direct move possible
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    # After moving one vertex, check if target color class is empty
                    target_vertices = [v for v in range(n) if coloring[v] == target_color]
                    if not target_vertices:
                        for v in range(n):
                            if coloring[v] > target_color:
                                coloring[v] -= 1
                        k -= 1
                    break  # restart outer while loop
            if changed:
                continue
            # Try Kempe chains for each target vertex
            for v in target_vertices:
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (v, target_color) <-> (some u, c)
                    # Only if there is no path from v to any vertex of color c using only colors target_color and c
                    # We do BFS on the subgraph induced by colors {target_color, c}
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    found_c = False
                    while queue:
                        u = queue.popleft()
                        if coloring[u] == c:
                            found_c = True
                            break
                        # Explore neighbors with color target_color or c
                        nbrs = bit_adj[u]
                        w = nbrs
                        while w:
                            lb = w & -w
                            idx = (lb.bit_length() - 1)
                            col_idx = coloring[idx]
                            if col_idx == target_color or col_idx == c:
                                if idx not in visited:
                                    visited.add(idx)
                                    queue.append(idx)
                            w ^= lb
                    if not found_c:
                        # Swap colors target_color and c in the component containing v
                        for u in visited:
                            if coloring[u] == target_color:
                                coloring[u] = c
                            elif coloring[u] == c:
                                coloring[u] = target_color
                        changed = True
                        break
                if changed:
                    # After swap, check if target color class is empty
                    target_vertices = [v for v in range(n) if coloring[v] == target_color]
                    if not target_vertices:
                        for v in range(n):
                            if coloring[v] > target_color:
                                coloring[v] -= 1
                        k -= 1
                    break  # restart outer while
        return coloring

    # Generate candidates
    candidates = []

    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except Exception:
        pass

    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except Exception:
        pass

    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append(col_sl)
    except Exception:
        pass

    # If no candidate, fallback to simple greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        col_greedy = greedy_color(order)
        if is_valid(col_greedy):
            candidates.append(col_greedy)
        else:
            # Ultimate fallback: assign distinct colors
            candidates.append(list(range(n)))

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best_coloring = kempe_reduce(best_coloring[:])  # work on a copy
    # Final validation and compacting
    if not is_valid(best_coloring):
        # Should not happen, but fallback
        best_coloring = list(range(n))
    # Ensure colors are consecutive starting from 0
    # Map colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_coloring[i] = unique_colors[c]
    return best_coloring

