        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: compute k-core numbers
    def core_numbers():
        deg = [len(neighbors[u]) for u in range(n)]
        order = sorted(range(n), key=lambda u: deg[u])
        bucket = [[] for _ in range(n)]
        pos = [0] * n
        for i, u in enumerate(order):
            pos[u] = i
        core = deg[:]
        for u in order:
            for v in neighbors[u]:
                if core[v] > core[u]:
                    # move v from bucket[core[v]] to bucket[core[v]-1]
                    cv = core[v]
                    bucket[cv].remove(v)
                    bucket[cv-1].append(v)
                    pos[v] = len(bucket[cv-1]) - 1
                    core[v] -= 1
        return core

    # Heuristic 1: DSATUR with bitmask
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree
            cand = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if color[u] == -1:
                    if sat[u] > max_sat or (sat[u] == max_sat and len(neighbors[u]) > max_deg):
                        max_sat = sat[u]
                        max_deg = len(neighbors[u])
                        cand = u
                    elif sat[u] == max_sat and len(neighbors[u]) == max_deg and u < cand:
                        cand = u
            if cand == -1:
                break
            # assign smallest available color
            used = 0
            for v in neighbors[cand]:
                c = color[v]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[cand] = c
            # update saturation of neighbors
            for v in neighbors[cand]:
                if color[v] == -1:
                    sat[v] += 1
        return color

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            # start with vertex of max degree in uncolored subgraph
            deg_sub = {u: 0 for u in uncolored}
            for u in uncolored:
                for v in neighbors[u]:
                    if v in uncolored:
                        deg_sub[u] += 1
            v = max(uncolored, key=lambda u: deg_sub[u])
            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to S, W: vertices adjacent to S
            U = {u for u in uncolored if all(v2 not in neighbors[u] for v2 in S)}
            W = uncolored - U
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w = -1
                min_deg_u = float('inf')
                for u in U:
                    w_count = sum(1 for v in neighbors[u] if v in W)
                    deg_u = sum(1 for v in neighbors[u] if v in U)
                    if w_count > max_w or (w_count == max_w and deg_u < min_deg_u) or \
                       (w_count == max_w and deg_u == min_deg_u and u < best_u):
                        max_w = w_count
                        min_deg_u = deg_u
                        best_u = u
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for v in neighbors[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
                uncolored.remove(best_u)
            for u in S:
                color[u] = c
            c += 1
        return color

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute removal order (smallest degree last)
        deg = [len(neighbors[u]) for u in range(n)]
        alive = [True] * n
        order = []
        for _ in range(n):
            # pick vertex with min degree
            u = -1
            min_deg = float('inf')
            for i in range(n):
                if alive[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    u = i
            order.append(u)
            alive[u] = False
            for v in neighbors[u]:
                if alive[v]:
                    deg[v] -= 1
        # color in reverse order
        return greedy_color(list(reversed(order)))

    # Heuristic 4: k-core decomposition ordering (outer to inner core)
    def core_order():
        core = core_numbers()
        # order by increasing core number (outer to inner)
        order = sorted(range(n), key=lambda u: core[u])
        return greedy_color(order)

    # Run all heuristics and pick best
    candidates = [
        dsatur(),
        rlf(),
        smallest_last(),
        core_order()
    ]
    # Also try Welsh-Powell (degree descending)
    wp_order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
    candidates.append(greedy_color(wp_order))

    best_color = None
    best_k = float('inf')
    for col in candidates:
        # validate
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if u < v and col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            k = max(col) + 1 if n > 0 else 0
            if k < best_k:
                best_k = k
                best_color = col[:]

    # Fallback: if none valid (should not happen), use greedy on natural order
    if best_color is None:
        best_color = greedy_color(list(range(n)))

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    compacted = [0] * n
    for i in range(n):
        c = best_color[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        compacted[i] = unique_colors[c]
    return compacted

