def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect if input is adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for i in range(n):
            if len(adj[i]) != n:
                all_binary = False
                break
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj
    # Build bitmask adjacency
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask
    # Helper: degree in uncolored subgraph
    def degree_in_uncolored(u, colored_mask):
        return (bit_adj[u] & ~colored_mask).bit_count()
    # Helper: saturation degree
    def saturation_degree(u, color_of):
        neighbor_colors = 0
        nbrs = bit_adj[u]
        while nbrs:
            v = (nbrs & -nbrs).bit_length() - 1
            nbrs &= nbrs - 1
            if color_of[v] != -1:
                neighbor_colors |= (1 << color_of[v])
        return neighbor_colors.bit_count()
    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True
    # DSATUR with degree tie-breaking
    def dsatur():
        color_of = [-1] * n
        colored_mask = 0
        for _ in range(n):
            best_v = -1
            best_sat = -1
            best_deg = -1
            for u in range(n):
                if color_of[u] != -1:
                    continue
                sat = saturation_degree(u, color_of)
                deg = degree_in_uncolored(u, colored_mask)
                if sat > best_sat or (sat == best_sat and deg > best_deg):
                    best_sat = sat
                    best_deg = deg
                    best_v = u
            if best_v == -1:
                break  # should not happen
            # Find smallest available color
            neighbor_colors = 0
            nbrs = bit_adj[best_v]
            while nbrs:
                v = (nbrs & -nbrs).bit_length() - 1
                nbrs &= nbrs - 1
                if color_of[v] != -1:
                    neighbor_colors |= (1 << color_of[v])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color_of[best_v] = c
            colored_mask |= (1 << best_v)
        return color_of
    # RLF: Recursive Largest First
    def rlf():
        color_of = [-1] * n
        color = 0
        uncolored_mask = (1 << n) - 1
        while uncolored_mask:
            # Build independent set S for this color
            S_mask = 0
            # Choose first vertex: max degree in uncolored subgraph
            best_v = -1
            best_deg = -1
            u = uncolored_mask
            while u:
                v = (u & -u).bit_length() - 1
                u &= u - 1
                deg = degree_in_uncolored(v, uncolored_mask)
                if deg > best_deg:
                    best_deg = deg
                    best_v = v
            if best_v == -1:
                break
            S_mask |= (1 << best_v)
            # Partition U and W
            U_mask = uncolored_mask & ~(1 << best_v)
            W_mask = bit_adj[best_v] & U_mask
            U_mask &= ~W_mask
            # Grow independent set
            while U_mask:
                best_u = -1
                best_score = -1
                best_deg_u = -1
                uu = U_mask
                while uu:
                    u_candidate = (uu & -uu).bit_length() - 1
                    uu &= uu - 1
                    # score: number of neighbors in W
                    nbrs_in_W = (bit_adj[u_candidate] & W_mask).bit_count()
                    deg_u = degree_in_uncolored(u_candidate, U_mask)  # degree in current U
                    if nbrs_in_W > best_score or (nbrs_in_W == best_score and deg_u < best_deg_u):
                        best_score = nbrs_in_W
                        best_deg_u = deg_u
                        best_u = u_candidate
                if best_u == -1:
                    break
                S_mask |= (1 << best_u)
                # move best_u from U to W
                U_mask &= ~(1 << best_u)
                # move neighbors of best_u that are in U to W
                nbrs_of_u = bit_adj[best_u] & U_mask
                W_mask |= nbrs_of_u
                U_mask &= ~nbrs_of_u
            # Assign color to all in S
            vmask = S_mask
            while vmask:
                v = (vmask & -vmask).bit_length() - 1
                vmask &= vmask - 1
                color_of[v] = color
            color += 1
            uncolored_mask &= ~S_mask
        return color_of
    # Smallest-Last ordering greedy
    def smallest_last():
        # Compute smallest-last ordering
        order = []
        remaining = set(range(n))
        deg = [len(adj_list[u]) for u in range(n)]
        # We'll simulate removal
        # For efficiency with n<=100, we can recompute min degree each time
        while remaining:
            # find vertex with min degree in remaining subgraph
            min_v = -1
            min_deg = float('inf')
            for v in remaining:
                # count neighbors in remaining
                d = 0
                for nb in adj_list[v]:
                    if nb in remaining:
                        d += 1
                if d < min_deg:
                    min_deg = d
                    min_v = v
            order.append(min_v)
            remaining.remove(min_v)
        # color in reverse order
        color_of = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for nb in adj_list[v]:
                if color_of[nb] != -1:
                    neighbor_colors |= (1 << color_of[nb])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color_of[v] = c
        return color_of
    # Kempe chain swap: swap colors a and b in the component containing v
    def kempe_swap(coloring, v, a, b):
        if coloring[v] not in (a, b):
            return False
        # BFS/DFS to get component
        from collections import deque
        q = deque([v])
        comp = set()
        target_a, target_b = a, b
        while q:
            u = q.popleft()
            if u in comp:
                continue
            comp.add(u)
            for w in adj_list[u]:
                if coloring[w] in (target_a, target_b) and w not in comp:
                    q.append(w)
        # swap colors in component
        for u in comp:
            if coloring[u] == target_a:
                coloring[u] = target_b
            else:
                coloring[u] = target_a
        return True
    # Attempt to eliminate a color class using Kempe chains
    def reduce_colors(coloring):
        # make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (largest index) that is non-empty
            # we try to remove the highest color index
            max_color = max(col) if col else -1
            for target in range(max_color, -1, -1):
                # collect vertices with this color
                verts = [v for v in range(n) if col[v] == target]
                if not verts:
                    continue
                # try to recolor each vertex in this class
                for v in verts:
                    # try direct reassignment to a lower color
                    neighbor_colors = 0
                    for nb in adj_list[v]:
                        if col[nb] != -1:
                            neighbor_colors |= (1 << col[nb])
                    for c in range(target):  # only try lower colors
                        if not (neighbor_colors & (1 << c)):
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # try Kempe chains with each lower color
                    for c in range(target):
                        # check if v is in a Kempe chain of colors target and c
                        # that does not include any other vertex of color target? Actually we can try swap
                        # We will attempt to swap colors target and c in the component of v
                        # But we need to ensure that after swap, we don't introduce conflict? Kempe swap preserves validity
                        # Make a copy to test
                        test_col = col[:]
                        if kempe_swap(test_col, v, target, c):
                            # after swap, check if v now has color c (it should)
                            if test_col[v] == c:
                                # Also, we want to see if this helps eliminate color target
                                # Count how many vertices of color target remain
                                # But we can just accept the swap and break
                                col = test_col
                                changed = True
                                break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break
        # compact colors: remap to 0..k-1
        # but first, ensure it's valid
        if not is_valid(col):
            return coloring  # fallback to original if invalid
        # remap
        unique_colors = {}
        next_color = 0
        for v in range(n):
            if col[v] not in unique_colors:
                unique_colors[col[v]] = next_color
                next_color += 1
        compacted = [unique_colors[col[v]] for v in range(n)]
        return compacted
    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # If no candidates, fallback to trivial
    if not candidates:
        # greedy by vertex order
        col = [-1] * n
        for v in range(n):
            neighbor_colors = 0
            for nb in adj_list[v]:
                if col[nb] != -1:
                    neighbor_colors |= (1 << col[nb])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            col[v] = c
        candidates.append(col)
    # Choose best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for cand in candidates:
        k = len(set(cand))
        if k < best_k:
            best_k = k
            best = cand
    # Apply Kempe reduction to best
    try:
        reduced = reduce_colors(best)
        if is_valid(reduced):
            k_red = len(set(reduced))
            if k_red < best_k:
                best = reduced
    except:
        pass
    # Final validation and compaction (should already be compact)
    if not is_valid(best):
        # last resort: greedy
        col = [-1] * n
        for v in range(n):
            neighbor_colors = 0
            for nb in adj_list[v]:
                if col[nb] != -1:
                    neighbor_colors |= (1 << col[nb])
            c = 0
            while neighbor_colors & (1 << c):
