            col[v] = c
        best = col
    # Ensure colors are 0..k-1 consecutive
    mapping = {}
    next_c = 0
    for v in range(n):
        if best[v] not in mapping:
            mapping[best[v]] = next_c
            next_c += 1
    best = [mapping[best[v]] for v in range(n)]
    return best

