    n = len(adj)
    if n == 0:
        return []

    # Convert adjacency representation to bitmask and neighbor list
    if len(adj) > 0 and len(adj[0]) == len(adj) and all(all(x in (0, 1) for x in row) for row in adj):
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
