        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)

    # Neighbor list for quick access
    neighbors = []
    for i in range(n):
        mask = bit_adj[i]
        nb = []
        while mask:
            lsb = mask & -mask
            j = (lsb.bit_length() - 1)
            nb.append(j)
            mask ^= lsb
        neighbors.append(nb)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR
    def dsatur():
        color = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = saturated[u].bit_count()
                deg = 0
                for w in neighbors[u]:
                    if w in uncolored:
                        deg += 1
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and u > v):
                    max_sat = sat
                    max_deg = deg
                    v = u
            # Assign smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for w in neighbors[v]:
                if w in uncolored:
                    saturated[w] |= (1 << c)
