    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                deg = 0
                for w in neighbors[u]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
            if v == -1:
                break
            S.append(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for u in list(U):
                for s in S:
                    if u in neighbors[s]:
                        W.add(u)
                        U.remove(u)
                        break
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_count = 0
                    for w in neighbors[u]:
