            if changed:
                # Relabel colors to be consecutive
                used = set(color)
                mapping = {}
                for i, c in enumerate(sorted(used)):
                    mapping[c] = i
                new_color = [mapping[c] for c in color]
                color = new_color
                # Update best if improved
                k = count_colors(color)
                if k < best_k and is_valid(color):
                    best_k = k
                    best_coloring = color[:]
