                for v in adj_list[u]:
                    if colors[v] == c:
                        conflict = True
                        break
                if not conflict:
                    colors[u] = c
                    break
            else:
                # Try Kempe chain swap with each lower color
                for c in range(target):
                    # Try to swap along (target, c) Kempe chain starting at u
                    # Make a copy to test
                    test_colors = colors[:]
                    if kempe_swap(test_colors, target, c, u):
                        # Check if u now has color c (it should after swap)
                        if test_colors[u] == c:
                            colors = test_colors
                            break
                else:
                    continue
                break
        else:
