            # Compact colors: remap higher colors down
            mapping = {}
            next_color = 0
            for i in range(max_color + 1):
                if i == target:
                    continue
                mapping[i] = next_color
                next_color += 1
            new_colors = [mapping[c] if c != target else -1 for c in colors]
            # Reassign the skipped ones (should be none if we broke correctly)
            for u in range(n):
                if new_colors[u] == -1:
                    # Should not happen if elimination worked
                    for c in range(next_color):
                        conflict = False
                        for v in adj_list[u]:
                            if new_colors[v] == c:
                                conflict = True
                                break
                        if not conflict:
                            new_colors[u] = c
                            break
