        neighbor_colors = [0] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation degree (number of distinct colors in neighbors)
            # Tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] != -1:
                    continue
                # saturation = number of distinct colors in neighbors
                sat = neighbor_colors[u].bit_count()
                if sat > max_sat or (sat == max_sat and (degrees[u] > max_deg or (degrees[u] == max_deg and random.random() < 0.5))):
                    max_sat = sat
                    max_deg = degrees[u]
                    v = u
            if v == -1:
                break  # should not happen
            # Assign smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            # Update neighbor colorsets
            for u in adj_list[v]:
                neighbor_colors[u] |= (1 << c)
        if is_valid(colors):
            k = num_colors(colors)
            if k < best_num:
                best_num = k
                best_colors = colors[:]

    # Pass 2: RLF (Recursive Largest First)
    if time.time() - start_time < time_limit:
        colors = [-1] * n
        color = 0
        remaining = set(range(n))
        while remaining:
            # Build maximal independent set for this color
            # Degree in remaining subgraph
            deg_remaining = {u: 0 for u in remaining}
            for u in remaining:
                for v in adj_list[u]:
                    if v in remaining:
                        deg_remaining[u] += 1
            # Start with vertex of max degree in remaining
            v = max(remaining, key=lambda u: deg_remaining[u])
            independent_set = {v}
            remaining.remove(v)
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            W = set()
            for u in independent_set:
                for w in adj_list[u]:
                    if w in remaining:
                        W.add(w)
            U = remaining - W
            while U:
                # Select u in U with max neighbors in W
                u = max(U, key=lambda x: sum(1 for y in adj_list[x] if y in W))
                # Tie-break: min degree in U
                independent_set.add(u)
                remaining.remove(u)
                # Update W and U: add neighbors of u that are in U to W
                for y in adj_list[u]:
                    if y in U:
                        W.add(y)
                        U.remove(y)
                U = remaining - W
            # Assign color to independent_set
            for u in independent_set:
                colors[u] = color
            color += 1
        if is_valid(colors):
            k = num_colors(colors)
            if k < best_num:
                best_num = k
                best_colors = colors[:]

    # Pass 3: Smallest-Last ordering (Matula & Beck)
    if time.time() - start_time < time_limit:
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # Bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)
                    if degree[u] < ptr:
                        ptr = degree[u]
        # Color in reverse order
        colors = greedy_color(order[::-1])
        if is_valid(colors):
            k = num_colors(colors)
            if k < best_num:
                best_num = k
                best_colors = colors[:]

    # Pass 4: Welsh-Powell (sort by degree descending)
    if time.time() - start_time < time_limit:
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        colors = greedy_color(order)
        if is_valid(colors):
            k = num_colors(colors)
            if k < best_num:
                best_num = k
                best_colors = colors[:]

    # Pass 5: Randomized greedy with shuffling
    if time.time() - start_time < time_limit:
        for _ in range(10):  # 10 random shuffles
            if time.time() - start_time >= time_limit:
                break
            order = vertices[:]
            random.shuffle(order)
            colors = greedy_color(order)
            if is_valid(colors):
                k = num_colors(colors)
                if k < best_num:
                    best_num = k
                    best_colors = colors[:]

    # If no valid coloring found (should not happen), fallback to trivial
    if best_colors is None:
        best_colors = list(range(n))  # worst case: each vertex its own color

    # Ensure colors are consecutive starting from 0
    # Remap colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_colors[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_colors[i] = unique_colors[c]

    # Iterative color reduction via Kempe chains
    changed = True
    while changed and num_colors(best_colors) > 1:
        changed = False
        # Try to eliminate the highest color class (or smallest, but highest is easier to compact)
        max_color = num_colors(best_colors) - 1
        # Count vertices in each color class
        color_count = [0] * (max_color + 1)
        for c in best_colors:
            color_count[c] += 1
        # Try to eliminate color classes from high to low
        for target in range(max_color, 0, -1):
            if color_count[target] == 0:
                continue
            new_colors, eliminated = eliminate_color(best_colors[:], target)
            if eliminated and is_valid(new_colors):
                # Compact again
                unique_colors = {}
                next_color = 0
                for i in range(n):
                    c = new_colors[i]
                    if c not in unique_colors:
                        unique_colors[c] = next_color
                        next_color += 1
                    new_colors[i] = unique_colors[c]
                best_colors = new_colors
                changed = True
                break  # restart from highest color
        # If no elimination succeeded, break
        if not changed:
            break

    return best_colors

