                if not removed[u]:
                    current_deg[u] -= 1
        # Now color in reverse order: last removed first colored
        coloring = [-1] * n
        # Process in reverse order
        for idx in range(n-1, -1, -1):
            v = order[idx]
            # Find smallest color not used by colored neighbors
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        col = coloring[:]
        changed = True
        # We'll try to reduce colors as long as we can remove a color class
        while changed:
            changed = False
            k = num_colors(col)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if col[v] == target_color]
            if not target_vertices:
                # Already normalized, so this should not happen unless gap
                # Renormalize and continue
                col = normalize(col)
                k = num_colors(col)
                target_color = k - 1
                target_vertices = [v for v in range(n) if col[v] == target_color]
                if not target_vertices:
                    break
            # Try to recolor each target vertex to a lower color
            # We'll attempt to move each vertex to a color < target_color if possible
            # Use Kempe chains
            success = [False] * len(target_vertices)
            # For each target vertex, try to find a color c < target_color that we can assign
            # either directly or via Kempe swap
            for idx, v in enumerate(target_vertices):
                # Try direct reassignment first
                neighbor_colors = 0
                for u in adj_list[v]:
                    if col[u] != -1:
                        neighbor_colors |= (1 << col[u])
                for c in range(target_color):  # try colors 0 to target_color-1
                    if not (neighbor_colors & (1 << c)):
                        # Directly assign color c to v
                        col[v] = c
                        success[idx] = True
                        break
                if success[idx]:
                    continue
                # Try Kempe chains for each color c < target_color
                for c in range(target_color):
                    # We consider swapping colors c and target_color in the component of v
                    # in the subgraph induced by vertices with color c or target_color
                    # If we can swap such that v becomes color c and no vertex becomes target_color (or we don't care as long as we can remove target_color later)
                    # Actually, we want to eliminate target_color: after swap, v should not be target_color, and we hope that no other vertex remains target_color? 
                    # But we are processing one vertex at a time. We will do the swap and then later try to remove the color class.
                    # Standard approach: if the Kempe chain of v for colors (c, target_color) does not contain any vertex of color c that is adjacent to a vertex of color target_color? 
                    # Simpler: we try to swap the component containing v in the (c, target_color) subgraph. After swap, v will have color c.
                    # We then check if this creates any conflict? It shouldn't because swapping colors in a Kempe chain preserves validity.
                    # So we can safely swap.
                    # However, we want to avoid increasing the number of vertices in target_color? Actually, after swap, some vertices that were c become target_color and vice versa.
                    # The number of target_color vertices may change. We want to reduce the count of target_color.
                    # We will do the swap and then later attempt to remove the color class again.
                    # For now, we just try to recolor v to c via Kempe chain, and if we can, we do it and break.
                    # Find the Kempe chain component of v in the subgraph of vertices with color c or target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (col[nb] == c or col[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if swapping is safe: it always is, but we want to know if after swap, v will not be target_color.
                    # After swap, v will become c (if it was target_color) or target_color (if it was c). Since v is target_color, it becomes c.
                    # So we can perform the swap.
                    # Perform swap: for each node in component, if col[node]==c set to target_color, else if col[node]==target_color set to c.
                    for node in component:
                        if col[node] == c:
                            col[node] = target_color
                        elif col[node] == target_color:
                            col[node] = c
                    # Now v has color c (since it was target_color and in component)
                    success[idx] = True
                    break  # break from color c loop
                if success[idx]:
                    break  # break from vertex loop, we will restart the while changed loop
            # If we succeeded in recoloring at least one target vertex, we set changed=True and will try to reduce again
            if any(success):
                changed = True
                # Renormalize to fill gaps
                col = normalize(col)
        return col

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            k1 = num_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_coloring = c1
    except Exception:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            k2 = num_colors(c2)
            if k2 < best_k:
                best_k = k2
                best_coloring = c2
    except Exception:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            k3 = num_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_coloring = c3
    except Exception:
        pass

    # If none worked (should not happen), use greedy as fallback
    if best_coloring is None:
        # Simple greedy: order by degree descending
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    # Apply Kempe chain reduction to try to improve
    try:
        improved = kempe_reduce(best_coloring)
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_coloring = improved
    except Exception:
        pass

    # Final validation and normalization
    if not is_valid_coloring(best_coloring):
        # Last resort: assign each vertex a unique color
        best_coloring = list(range(n))
    best_coloring = normalize(best_coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square, binary entries)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency bitmasks
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                bit_adj[u] |= (1 << v)

    # Helper: count bits in integer
    def popcount(x):
        return x.bit_count()

    # Helper: get degree (number of neighbors)
    def degree(u):
        return popcount(bit_adj[u])

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in range(n):
                if (bit_adj[u] >> v) & 1 and color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1 and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        mapping = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            coloring[i] = mapping[c]
        return coloring

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        # degrees in uncolored subgraph
        uncolored_deg = [degree(u) for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            candidates = []
            max_sat = -1
            for u in uncolored:
                sat = popcount(saturation[u])
                if sat > max_sat:
                    max_sat = sat
                    candidates = [u]
                elif sat == max_sat:
                    candidates.append(u)
            # tie-break by degree in uncolored subgraph
            max_deg = -1
            for u in candidates:
                d = uncolored_deg[u]
                if d > max_deg:
                    max_deg = d
                    best = u
                elif d == max_deg:
                    if random.random() < 0.5:  # random tie-break
                        best = u
            v = best
            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and uncolored degrees for neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1:
                    if color[u] == -1:  # u is uncolored
                        saturation[u] |= (1 << c)
                        uncolored_deg[u] -= 1
                    # if u is colored, no need to update saturation (already accounted)
        return color

    # 2. RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v0 = -1
            for u in uncolored:
                d = sum(1 for w in uncolored if (bit_adj[u] >> w) & 1)
                if d > max_deg:
                    max_deg = d
                    v0 = u
            S = [v0]
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v0:
                    continue
                adjacent = False
                for w in S:
                    if (bit_adj[u] >> w) & 1:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # expand S
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = 0
                    for w in W:
                        if (bit_adj[u] >> w) & 1:
                            w_neighbors += 1
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # tie-break by min degree in G[U]
                        deg_u = sum(1 for w in U if (bit_adj[u] >> w) & 1)
                        deg_best = sum(1 for w in U if (bit_adj[best_u] >> w) & 1)
                        if deg_u < deg_best:
                            best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in list(U):
                    if (bit_adj[u] >> w) & 1:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [degree(u) for u in range(n)]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[deg[u]].append(u)
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # find first non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    d = deg[u]
                    buckets[d].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].append(u)
                    if deg[u] < ptr:
                        ptr = deg[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if is_valid(col):
                col = normalize(col)
                k = num_colors(col)
                if k < best_k:
                    best_k = k
                    best_coloring = col[:]
        except Exception:
            continue

    # Fallback: if no candidate found, use greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda u: degree(u), reverse=True)
        best_coloring = greedy_color(order)
        best_coloring = normalize(best_coloring)
        best_k = num_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (largest color index)
            color_classes = [[] for _ in range(best_k)]  # we know current k
            for u in range(n):
                if col[u] < best_k:
                    color_classes[col[u]].append(u)
            # find the largest color index that is non-empty
            target_color = -1
            for c in range(best_k - 1, -1, -1):
                if color_classes[c]:
                    target_color = c
                    break
            if target_color == -1:
                break  # no colors
            # try to recolor each vertex in target_color
            for v in color_classes[target_color][:]:
                # try direct reassignment to a lower color
                for c in range(target_color):
                    conflict = False
                    for u in range(n):
                        if (bit_adj[v] >> u) & 1 and col[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart after change
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # find the Kempe chain component of v in colors {c, target_color}
                    # if v is not in that component, we can swap
                    # Actually, we check: if we can swap the component containing v
                    # such that v gets color c and no vertex gets target_color incorrectly
                    # Standard: if v is not connected to any vertex of color c via a chain,
                    # then we can swap the component of v in (c, target_color)
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        u = stack.pop()
                        component.append(u)
                        for w in range(n):
                            if (bit_adj[u] >> w) & 1 and not visited[w]:
                                if col[w] == c or col[w] == target_color:
                                    visited[w] = True
                                    stack.append(w)
                    # check if any neighbor of v has color c (outside component?)
                    # Actually, we can swap if no vertex in the component is adjacent to a vertex of color c outside?
                    # Correct condition: after swap, we want no conflict.
                    # Swapping colors c and target_color in the component is safe if
                    # no vertex in the component is adjacent to a vertex of color c outside the component
                    # (because after swap, that outside vertex would be color c and adjacent to a vertex now color c)
                    # Similarly for target_color.
                    # But since we are only swapping within the component, and the component is maximal,
                    # there should be no edge from component to outside with color c or target_color?
                    # Actually, by definition of Kempe chain, the component is connected and
                    # there are no edges from the component to vertices of color c or target_color outside.
                    # So swap is always safe.
                    # Perform swap: c <-> target_color in component
                    for u in component:
                        if col[u] == c:
                            col[u] = target_color
                        else:
                            col[u] = c
                    changed = True
                    break
                if changed:
                    break
            if changed:
                # recompute best_k and normalize
                col = normalize(col)
                best_k = num_colors(col)
        return col

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)
    # Final validation and normalization
    if not is_valid(best_coloring):
        # last resort: greedy by degree
        order = sorted(range(n), key=lambda u: degree(u), reverse=True)
        best_coloring = greedy_color(order)
    best_coloring = normalize(best_coloring)
    return best_coloring

