        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor list and bitmask adjacency
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    def get_color_count(coloring):
        return max(coloring) + 1 if coloring else 0

    def compact_colors(coloring):
        if not coloring:
            return coloring
        max_color = max(coloring)
        if max_color + 1 == len(set(coloring)):
            return coloring
        mapping = {}
        next_color = 0
        for c in range(max_color + 1):
            if c in set(coloring):
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        saturated = [0] * n
        # Initialize saturation: for each vertex, track neighbor colors via bitmask
        neighbor_colors_mask = [0] * n
        degree = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v]
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = sum(1 for u in neighbors[v] if u in uncolored)
                elif sat == best_sat:
                    deg = sum(1 for u in neighbors[v] if u in uncolored)
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
                    elif deg == best_deg:
                        if random.random() < 0.5:
                            best_v = v
            v = best_v
            # Find smallest available color
            used = neighbor_colors_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation and neighbor colors for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    if not (neighbor_colors_mask[u] & (1 << c)):
                        neighbor_colors_mask[u] |= (1 << c)
                        saturated[u] += 1
