    # RLF: Recursive Largest First via independent set extraction
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set S for this color
            S = set()
            # Choose vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # Partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_in_U = -1
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        best_deg_in_U = sum(1 for w in neighbors[u] if w in U)
                    elif score == best_score:
                        deg_in_U = sum(1 for w in neighbors[u] if w in U)
                        if deg_in_U < best_deg_in_U:
                            best_deg_in_U = deg_in_U
                            best_u = u
                        elif deg_in_U == best_deg_in_U:
                            if random.random() < 0.5:
                                best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
        return coloring

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering via min-degree peeling
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # Use buckets for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d <= max_deg:
                buckets[d].append(v)
        # Pointer to current min degree
        min_deg = 0
        while remaining:
            # Find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            # Find a vertex in bucket[min_deg] that is still in remaining
            v = None
            while buckets[min_deg]:
                candidate = buckets[min_deg].pop()
                if candidate in remaining:
                    v = candidate
                    break
            if v is None:
                min_deg += 1
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degree[u]
                    # Remove u from bucket[d]
                    if d <= max_deg and u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    if d_new <= max_deg:
                        buckets[d_new].append(u)
                    if d_new < min_deg:
                        min_deg = d_new
        # Color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
