    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring  # Should not happen if input is valid
        k = get_color_count(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest down
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already compacted? Recompact and continue
                coloring = compact_colors(coloring)
                k = get_color_count(coloring)
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        used |= (1 << coloring[u])
                for c in range(target_color):  # only lower colors
                    if not (used & (1 << c)):
                        # Move v to color c
                        coloring[v] = c
