def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format
    is_matrix = len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row)
    if is_matrix:
        neighbors = [set(j for j in range(n) if adj[i][j] == 1) for i in range(n)]
    else:
        neighbors = [set(row) for row in adj]

    # Bitmask representation for fast operations
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= 1 << j
        bit_adj[i] = mask

    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    def greedy_coloring(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= 1 << colors[u]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Heuristic 1: DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (saturated[x], len([u for u in neighbors[x] if u in uncolored]), x))
            # Compute forbidden colors from neighbors
            forbidden = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    forbidden |= 1 << colors[u]
            c = 0
            while forbidden & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] += 1
        return colors

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build independent set S for current color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - S - set().union(*[neighbors[s] for s in S]) if S else uncolored.copy()
            W = set().union(*[neighbors[s] for s in S]) & uncolored
            # Greedily add to S from U
            while U:
                # Select u in U maximizing |N(u) ∩ W|
                u = max(U, key=lambda x: (len([w for w in neighbors[x] if w in W]), -len([w for w in neighbors[x] if w in U]), x))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbors[u] & U
                W.update(nbrs_u)
                U -= nbrs_u
            # Assign color to S
            for v in S:
                colors[v] = color
            uncolored -= S
            color += 1
        return colors

    # Heuristic 3: Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        while remaining:
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    deg[u] -= 1
        # Color in reverse order
        return greedy_coloring(order[::-1])

    # Heuristic 4: Welsh-Powell (degree sorting)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_coloring(order)

    # Generate candidate colorings
    candidates = []
    for heuristic in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = heuristic()
            if is_valid_coloring(col):
                candidates.append(col)
        except Exception:
            continue

    # Fallback: simple greedy if no candidate valid (should not happen)
    if not candidates:
        candidates.append(greedy_coloring(list(range(n))))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda c: max(c) + 1 if any(x != -1 for x in c) else 0)
    k = max(best) + 1 if best else 0

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # Get vertices with target_color
        verts = [v for v in range(n) if coloring[v] == target_color]
        if not verts:
            return coloring, True  # already eliminated
        # Try to recolor each vertex
        for v in verts:
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= 1 << coloring[u]
            # Try direct reassignment to a lower color
            for c in range(target_color):
                if not (used & (1 << c)):
                    coloring[v] = c
                    break
            else:
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Build (c, target_color) Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == c or coloring[node] == target_color:
                            component.add(node)
                            for u in neighbors[node]:
                                if u not in visited and (coloring[u] == c or coloring[u] == target_color):
                                    stack.append(u)
                    # Check if any neighbor of v in component has color c (would cause conflict if swapped)
                    conflict = False
                    for node in component:
                        for u in neighbors[node]:
                            if u in component and coloring[u] == c and coloring[node] == target_color:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Swap colors c and target_color in component
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        coloring[v] = c  # Now v has color c
                        break
        # Re-check if target_color is still used
        if any(coloring[v] == target_color for v in range(n)):
            return coloring, False
        # Compact colors: shift down all colors > target_color
        for v in range(n):
            if coloring[v] > target_color:
                coloring[v] -= 1
        return coloring, True

    # Iteratively try to reduce color count
    current = best[:]
    changed = True
    while changed and max(current) + 1 > 1:
        changed = False
        target = max(current)  # highest color index
        # Try to eliminate the highest color class first (often easier)
        new_col, eliminated = eliminate_color_class(current[:], target)
        if eliminated:
            current = new_col
            changed = True
        else:
            # Try eliminating color classes from high to low
            for c in range(max(current), -1, -1):
                new_col, eliminated = eliminate_color_class(current[:], c)
                if eliminated:
                    current = new_col
                    changed = True
                    break

    # Final validation and compaction to zero-based
    if not is_valid_coloring(current):
        # Fallback to greedy on best ordering
        current = greedy_coloring(list(range(n)))
    # Ensure colors are consecutive starting from 0
    unique_colors = {}
    next_color = 0
    for i in range(n):
        if current[i] not in unique_colors:
            unique_colors[current[i]] = next_color
            next_color += 1
        current[i] = unique_colors[current[i]]
    return current

