    # Fallback: simple greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(col)
        else:
            # ultimate fallback: assign distinct colors
            col = list(range(n))
            candidates.append(col)

    # Select candidate with fewest colors
    best_col = min(candidates, key=num_colors)

    # Kempe chain color reduction
    def kempe_reduction(col):
        k = num_colors(col)
        if k <= 1:
            return col
        # work on a copy
        color = col[:]
        improved = True
        while improved and k > 1:
            improved = False
            # find smallest color class (by index, but we target highest color for removal)
            # Actually, we try to eliminate the highest color index
            target = k - 1
            vertices = [v for v in range(n) if color[v] == target]
            if not vertices:
                # should not happen, but safety
                k -= 1
                continue
            # Try to recolor each vertex in target class
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for w in adj_list[v]:
                    if color[w] < target:
                        neighbor_colors.add(color[w])
                for c in range(target):
                    if c not in neighbor_colors:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    # after moving v, check if target class is empty
                    if not any(color[u] == target for u in range(n)):
                        k -= 1
                        # compact colors: remap higher colors down
                        mapping = {}
                        new_c = 0
                        for orig in range(k + 1):  # up to old k
                            if any(color[u] == orig for u in range(n)):
                                mapping[orig] = new_c
                                new_c += 1
                        for u in range(n):
                            color[u] = mapping[color[u]]
                        break  # restart while loop with new k
                else:
                    # Try Kempe chains with each lower color
                    for c in range(target):
                        # Find the Kempe chain component of v in colors {c, target}
                        # BFS/DFS
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if color[node] == c or color[node] == target:
                                component.add(node)
                                for w in adj_list[node]:
                                    if w not in visited and (color[w] == c or color[w] == target):
                                        stack.append(w)
                        # Check if any neighbor of v with color c is NOT in this component
                        # If so, we can swap the component and free color c for v
                        has_external = False
                        for w in adj_list[v]:
                            if color[w] == c and w not in component:
                                has_external = True
                                break
                        if has_external:
                            # swap colors c and target in the component
                            for node in component:
                                if color[node] == c:
                                    color[node] = target
                                else:  # must be target
                                    color[node] = c
                            # now v has color c (since it was target and swapped)
                            improved = True
                            # check if target class is now empty
                            if not any(color[u] == target for u in range(n)):
                                k -= 1
                                mapping = {}
                                new_c = 0
                                for orig in range(k + 1):
                                    if any(color[u] == orig for u in range(n)):
                                        mapping[orig] = new_c
                                        new_c += 1
                                for u in range(n):
                                    color[u] = mapping[color[u]]
                            break  # break color loop
                    if improved:
                        break  # break vertex loop
            # end for vertices
        return color

    # Apply Kempe reduction
    try:
        improved_col = kempe_reduction(best_col)
        if is_valid(improved_col) and num_colors(improved_col) <= num_colors(best_col):
            best_col = improved_col
    except Exception:
        pass

    # Final validation and compacting
    if not is_valid(best_col):
        # last resort: greedy by DSATUR order
        best_col = dsatur()
        if not is_valid(best_col):
            best_col = list(range(n))

    # Ensure colors are consecutive starting from 0
    # Map used colors to 0..k-1
    used = sorted(set(best_col))
    mapping = {old: new for new, old in enumerate(used)}
    best_col = [mapping[c] for c in best_col]

    return best_col

