def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row)

    # Build adjacency list
    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = [ list(set(row)) for row in adj ]

    # Edge case: no edges
    if all(len(nei) == 0 for nei in neighbors):
        return [0] * n

    # Helper: greedy coloring given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: compute k-core numbers and degeneracy ordering
    def core_decomposition():
        degree = [len(neighbors[i]) for i in range(n)]
        bin_count = [0] * (n + 1)
        for d in degree:
            if d < n:
                bin_count[d] += 1
        start = [0] * (n + 1)
        for d in range(1, n + 1):
            start[d] = start[d-1] + bin_count[d-1]
        vertex_list = list(range(n))
        pos = [0] * n
        for v in range(n):
            d = degree[v]
            pos[v] = start[d]
            vertex_list[pos[v]] = v
            start[d] += 1
        # Adjust start back
        for d in range(n, 0, -1):
            start[d] = start[d-1]
        start[0] = 0
        core = [0] * n
        for i in range(n):
            v = vertex_list[i]
            for u in neighbors[v]:
                if degree[u] > degree[v]:
                    du = degree[u]
                    pu = pos[u]
                    pw = start[du]
                    uu = vertex_list[pw]
                    if uu != u:
                        pos[u] = pw
                        pos[uu] = pu
                        vertex_list[pu] = uu
                        vertex_list[pw] = u
                    degree[u] -= 1
                    start[du] += 1
                    bin_count[du] -= 1
                    bin_count[du-1] += 1
            core[v] = degree[v]
        ordering = vertex_list[:]  # removal order (smallest last)
        # degeneracy is max core
        degeneracy = max(core) if n > 0 else 0
        return core, ordering, degeneracy

    core, removal_order, degeneracy = core_decomposition()
    # Order vertices from low core to high core (outer to inner)
    order_by_core = sorted(range(n), key=lambda v: (core[v], v))
    # Also try reverse (high core to low core)
    order_by_core_rev = sorted(range(n), key=lambda v: (-core[v], v))
    # Also try degeneracy ordering (smallest last) and its reverse
    order_sl = removal_order
    order_sl_rev = list(reversed(removal_order))

    candidates = []
    for order in [order_by_core, order_by_core_rev, order_sl, order_sl_rev]:
        color = greedy_color(order)
        k = max(color) + 1 if n > 0 else 0
        # Compact colors
        mapping = {}
        next_color = 0
        for c in color:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        compact_color = [mapping[c] for c in color]
        candidates.append((compact_color, k))

    # Select best candidate (min colors, then lexicographically smallest for tie-breaking)
    best_color, best_k = min(candidates, key=lambda x: (x[1], x[0]))

    # Kempe chain reduction to try to lower color count
    def kempe_reduce(color):
        nonlocal neighbors, n
        # Get color classes
        classes = {}
        for v, c in enumerate(color):
            classes.setdefault(c, []).append(v)
        sorted_colors = sorted(classes.keys())
        # Try to eliminate highest color classes
        for c in sorted(sorted_colors, reverse=True):
            if c not in classes or not classes[c]:
                continue
            # Try to recolor each vertex in class c
            changed = True
            while changed and c in classes and classes[c]:
                changed = False
                v = classes[c][-1]  # pick a vertex
                # Try direct reassignment to lower color
                neighbor_colors = {color[u] for u in neighbors[v]}
                for target in range(c):
                    if target not in neighbor_colors:
                        # Recolor v to target
                        classes[c].remove(v)
                        if not classes[c]:
                            del classes[c]
                        classes.setdefault(target, []).append(v)
                        color[v] = target
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe swap with each lower color
                for target in range(c):
                    if target in neighbor_colors:
                        continue
                    # Find Kempe chain of (c, target) containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if color[node] == c or color[node] == target:
                            component.add(node)
                            for u in neighbors[node]:
                                if color[u] == c or color[u] == target:
                                    if u not in visited:
                                        stack.append(u)
                    # Check if any neighbor of v in target color is NOT in this component
                    has_external = False
                    for u in neighbors[v]:
                        if color[u] == target and u not in component:
                            has_external = True
                            break
                    if not has_external:
                        # Swap colors in component
                        for node in component:
                            if color[node] == c:
                                color[node] = target
                                classes[target].append(node)
                                if c in classes:
                                    classes[c].remove(node)
                                    if not classes[c]:
                                        del classes[c]
                            else:  # color[node] == target
                                color[node] = c
                                classes.setdefault(c, []).append(node)
                                classes[target].remove(node)
                                if not classes[target]:
                                    del classes[target]
                        changed = True
                        break
            # If class c is eliminated, break to restart from highest
            if c not in classes or not classes[c]:
                break
        # Compact colors again
        mapping = {}
        next_color = 0
        for v in range(n):
            c = color[v]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            color[v] = mapping[c]
        return color

    best_color = kempe_reduce(best_color[:])
    # Final validation (optional, but ensures correctness)
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_color[u] == best_color[v]:
                # Fallback to DSATUR if validation fails (should not happen)
                return dsatur_fallback(neighbors, n)
    return best_color

def dsatur_fallback(neighbors, n):
    # Simple DSATUR implementation as fallback
    color = [-1] * n
    # saturation: number of distinct colors in neighbors
    sat = [0] * n
    # neighbor colorsets for saturation update
    neighbor_colors = [set() for _ in range(n)]
    uncolored = set(range(n))
    # initial vertex: highest degree
    if n == 0:
        return []
    v = max(uncolored, key=lambda x: len(neighbors[x]))
    color[v] = 0
    uncolored.remove(v)
    for u in neighbors[v]:
        neighbor_colors[u].add(0)
        sat[u] = len(neighbor_colors[u])
    while uncolored:
        # select vertex with max sat, tie-break by degree
        v = max(uncolored, key=lambda x: (sat[x], len(neighbors[x]), -x))
        # find smallest available color
        used = [False] * n
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c
        uncolored.remove(v)
        # update saturation for uncolored neighbors
        for u in neighbors[v]:
            if u in uncolored:
                if c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    sat[u] = len(neighbor_colors[u])
    # compact colors
    mapping = {}
    next_color = 0
    for c in color:
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
    return [mapping[c] for c in color]

