def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Convert to adjacency list and adjacency matrix if needed
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Adjacency list
        adj_list = adj

    # Precompute degrees
    degrees = [len(adj_list[i]) for i in range(n)]

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    best_coloring = None
    best_k = float('inf')

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR with bitmask optimization
    def dsatur():
        coloring = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # colored neighbor count for tie-breaking
        colored_neighbors = [0] * n

        # Order vertices by degree descending for initial tie-breaking
        order = sorted(range(n), key=lambda x: (-degrees[x], x))
        # We'll maintain a list of uncolored vertices
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, then max degree in uncolored subgraph
            best_v = -1
            max_sat = -1
            max_deg_uncolored = -1

            for v in uncolored:
                sat_count = saturation[v].bit_count()
                if sat_count > max_sat:
                    max_sat = sat_count
                    max_deg_uncolored = sum(1 for u in adj_list[v] if u in uncolored)
                    best_v = v
                elif sat_count == max_sat:
                    deg_uncolored = sum(1 for u in adj_list[v] if u in uncolored)
                    if deg_uncolored > max_deg_uncolored:
                        max_deg_uncolored = deg_uncolored
                        best_v = v
                    elif deg_uncolored == max_deg_uncolored and v < best_v:
                        best_v = v

            v = best_v
            # Find smallest color not used by neighbors
            used_colors = saturation[v]
            color = 0
            while used_colors & (1 << color):
                color += 1
            coloring[v] = color
            uncolored.remove(v)

            # Update saturation and colored neighbors for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << color)
                    colored_neighbors[u] += 1

        return normalize(coloring)

    # RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            independent_set = []
            # Candidates: uncolored vertices not adjacent to any in independent_set
            # We'll maintain eligible and ineligible sets
            eligible = set(uncolored)
            ineligible = set()

            # Start with vertex of max degree in uncolored subgraph
            if eligible:
                v = max(eligible, key=lambda x: sum(1 for u in adj_list[x] if u in eligible))
                independent_set.append(v)
                eligible.remove(v)
                # Move neighbors of v from eligible to ineligible
                for u in adj_list[v]:
                    if u in eligible:
                        eligible.remove(u)
                        ineligible.add(u)

            # Greedily add to independent set
            while eligible:
                # Select u in eligible with max neighbors in ineligible
                best_u = -1
                max_neighbors_ineligible = -1
                min_deg_eligible = float('inf')

                for u in eligible:
                    neighbors_ineligible = sum(1 for w in adj_list[u] if w in ineligible)
                    if neighbors_ineligible > max_neighbors_ineligible:
                        max_neighbors_ineligible = neighbors_ineligible
                        min_deg_eligible = sum(1 for w in adj_list[u] if w in eligible)
                        best_u = u
                    elif neighbors_ineligible == max_neighbors_ineligible:
                        deg_eligible = sum(1 for w in adj_list[u] if w in eligible)
                        if deg_eligible < min_deg_eligible:
                            min_deg_eligible = deg_eligible
                            best_u = u
                        elif deg_eligible == min_deg_eligible and u < best_u:
                            best_u = u

                u = best_u
                independent_set.append(u)
                eligible.remove(u)
                # Move neighbors of u from eligible to ineligible
                for w in adj_list[u]:
                    if w in eligible:
                        eligible.remove(w)
                        ineligible.add(w)

            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return normalize(coloring)

    # Smallest-Last (Degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []

        # Bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)

        # Pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # Find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)
                    if degree[u] < min_deg:
                        min_deg = degree[u]

        # Color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)  # n+1 safe bound
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            color = 0
            while used[color]:
                color += 1
            coloring[v] = color

        return normalize(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring

        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = [False] * k
                for u in adj_list[v]:
                    c = coloring[u]
                    if c < k:  # only consider colors in range
                        used_by_neighbors[c] = True

                for c in range(k - 1):  # try colors 0 to k-2
                    if not used_by_neighbors[c]:
                        # Try to move v to color c
                        coloring[v] = c
                        if is_valid(coloring):
                            improved = True
                            break
                        else:
                            coloring[v] = target_color  # revert
                if improved:
                    break

                # Try Kempe chains with each lower color
                for c in range(k - 1):
                    # Build (c, target_color) Kempe chain containing v
                    # We'll do BFS to find the component
                    from collections import deque
                    queue = deque([v])
                    visited = set([v])
                    component = set()
                    # Only traverse vertices colored c or target_color
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in adj_list[x]:
                            if y not in visited and (coloring[y] == c or coloring[y] == target_color):
                                visited.add(y)
                                queue.append(y)

                    # Try swapping colors in the component
                    # Create new coloring by swapping c and target_color in component
                    new_coloring = coloring[:]
                    for x in component:
                        if new_coloring[x] == c:
                            new_coloring[x] = target_color
                        elif new_coloring[x] == target_color:
                            new_coloring[x] = c

                    # Check if this move reduces the number of vertices in target_color
                    # and doesn't increase conflicts
                    if is_valid(new_coloring):
                        # Count how many vertices would be in target_color after swap
                        count_target = sum(1 for x in component if new_coloring[x] == target_color)
                        if count_target < len([x for x in component if coloring[x] == target_color]):
                            # This swap reduces the target color count in this component
                            coloring = new_coloring
                            improved = True
                            break
                if improved:
                    break

            # If we improved, try to renormalize and reduce k
            if improved:
                coloring = normalize(coloring)
                k = num_colors(coloring)

        return coloring

    # Run all heuristics with time budgeting
    start_time = time.time()
    time_limit = 0.045  # 45ms to leave room for overhead

    # DSATUR
    if time.time() - start_time < time_limit:
        c1 = dsatur()
        if is_valid(c1):
            k1 = num_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_coloring = c1

    # RLF
    if time.time() - start_time < time_limit:
        c2 = rlf()
        if is_valid(c2):
            k2 = num_colors(c2)
            if k2 < best_k:
                best_k = k2
                best_coloring = c2

    # Smallest-Last
    if time.time() - start_time < time_limit:
        c3 = smallest_last()
        if is_valid(c3):
            k3 = num_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_coloring = c3

    # Apply Kempe reduction to the best found so far
    if best_coloring is not None and time.time() - start_time < time_limit:
        c4 = kempe_reduce(best_coloring[:])
        if is_valid(c4):
            k4 = num_colors(c4)
            if k4 < best_k:
                best_k = k4
                best_coloring = c4

    # Fallback: if nothing worked, use greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: (-degrees[x], x))
        coloring = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            color = 0
            while used[color]:
                color += 1
            coloring[v] = color
        best_coloring = normalize(coloring)

    return best_coloring

