import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets and adjacency bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Multiple randomized greedy passes with 1-opt local search
    random.seed(42)  # For reproducibility
    start_time = time.time()
    timeout = 0.045  # 45ms to leave room for overhead

    # Degree list for ordering
    degrees = [len(neighbors[i]) for i in range(n)]
    vertices = list(range(n))

    # Try multiple orderings: sorted by degree (desc/asc), random, and perturbed
    orderings = []
    # Degree descending
    orderings.append(sorted(vertices, key=lambda x: (-degrees[x], x)))
    # Degree ascending
    orderings.append(sorted(vertices, key=lambda x: (degrees[x], x)))
    # Random shuffles
    for _ in range(20):
        if time.time() - start_time > timeout:
            break
        order = vertices[:]
        random.shuffle(order)
        orderings.append(order)
    # Perturbed degree orderings
    for _ in range(10):
        if time.time() - start_time > timeout:
            break
        order = sorted(vertices, key=lambda x: (-degrees[x], random.random()))
        orderings.append(order)

    for order in orderings:
        if time.time() - start_time > timeout:
            break
        coloring = greedy_color(order)
        if not is_valid(coloring):
            continue
        k = count_colors(coloring)
        if k >= best_k:
            continue
        # Apply 1-opt local search: try to reduce color of each vertex
        improved = True
        while improved and k > 1:
            improved = False
            # Process vertices in random order to avoid cycles
            order_v = vertices[:]
            random.shuffle(order_v)
            for v in order_v:
                if time.time() - start_time > timeout:
                    break
                used = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                # Try to find a smaller color not used by neighbors
                for c in range(coloring[v]):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    # Recompute k after improvement
                    k = count_colors(coloring)
                    if k < best_k:
                        best_k = k
                        best_coloring = coloring[:]
                    break  # Restart scan after change
            if time.time() - start_time > timeout:
                break

        if not improved or k < best_k:
            best_k = k
            best_coloring = coloring[:]

    # Fallback: if no valid coloring found (should not happen), use greedy on degree order
    if best_coloring is None or not is_valid(best_coloring):
        coloring = greedy_color(sorted(vertices, key=lambda x: (-degrees[x], x)))
        if is_valid(coloring):
            best_coloring = coloring
            best_k = count_colors(coloring)
        else:
            # Last resort: assign each vertex a unique color
            best_coloring = list(range(n))
            best_k = n

    # Compact colors to 0..k-1
    if best_coloring:
        unique_colors = {}
        next_color = 0
        compacted = []
        for c in best_coloring:
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            compacted.append(unique_colors[c])
        best_coloring = compacted

    return best_coloring

