    if is_matrix:
        neighbors = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
    else:
        neighbors = [list(lst) for lst in adj]  # copy to avoid mutation

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # 1. Welsh-Powell (degree descending)
    order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    col_wp = greedy_color(order_wp)
    k_wp = num_colors(col_wp)
    if k_wp < best_k:
        best_k = k_wp
        best_coloring = col_wp[:]

    # 2. Smallest-Last ordering (degeneracy)
    remaining = set(range(n))
    order_sl = []
    deg = [len(neighbors[u]) for u in range(n)]
    for _ in range(n):
        # find vertex with min degree in remaining
        v = min(remaining, key=lambda x: deg[x])
        order_sl.append(v)
        remaining.remove(v)
        for w in neighbors[v]:
            if w in remaining:
                deg[w] -= 1
    order_sl.reverse()
    col_sl = greedy_color(order_sl)
    k_sl = num_colors(col_sl)
    if k_sl < best_k:
        best_k = k_sl
        best_coloring = col_sl[:]

    # 3. DSATUR with bitmask optimization
    color = [-1] * n
    sat = [0] * n  # saturation degree as bitmask of colors used in neighbors
    uncolored = set(range(n))
    for _ in range(n):
        if not uncolored:
            break
        # select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
        v = max(uncolored, key=lambda x: (sat[x].bit_count(),
                                           sum(1 for y in neighbors[x] if y in uncolored),
                                           random.random()))
        # compute used colors from neighbors
        used = 0
        for y in neighbors[v]:
            c = color[y]
            if c != -1:
                used |= (1 << c)
        # find smallest color not used
        c = 0
        while used & (1 << c):
            c += 1
        color[v] = c
        uncolored.remove(v)
        # update saturation of uncolored neighbors
        for y in neighbors[v]:
            if y in uncolored:
                sat[y] |= (1 << c)
    col_ds = color[:]
    k_ds = num_colors(col_ds)
    if k_ds < best_k:
        best_k = k_ds
        best_coloring = col_ds[:]

    # Kempe chain elimination to reduce colors
    def eliminate_color(col):
        nonlocal best_k, best_coloring
        k = num_colors(col)
        if k <= 1:
            return col
        # try to eliminate highest color class
        target = k - 1
        verts_target = [i for i in range(n) if col[i] == target]
        if not verts_target:
            # compact colors
            mapping = {}
            next_c = 0
            for i in range(n):
                c = col[i]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                col[i] = mapping[c]
            return eliminate_color(col)
        moved = False
        for v in verts_target:
            # try direct reassignment to a lower color
            used = 0
            for y in neighbors[v]:
                c = col[y]
                if c != -1:
                    used |= (1 << c)
            for c in range(target):
                if not (used & (1 << c)):
                    col[v] = c
                    moved = True
                    break
            if moved:
                break
            # try Kempe chain swap with each lower color
            for c in range(target):
                # BFS to find Kempe chain component of v in colors {c, target}
                from collections import deque
                comp = []
                seen = set()
                dq = deque([v])
                seen.add(v)
                while dq:
                    node = dq.popleft()
                    comp.append(node)
                    for nb in neighbors[node]:
                        if nb not in seen and col[nb] in (c, target):
                            seen.add(nb)
                            dq.append(nb)
                # check if any neighbor of component has color c (would cause conflict if swapped)
                conflict = False
                for node in comp:
                    for nb in neighbors[node]:
                        if col[nb] == c and nb not in comp:
                            conflict = True
                            break
                    if conflict:
                        break
                if not conflict:
                    # perform swap
                    for node in comp:
                        col[node] = c if col[node] == target else target
                    moved = True
                    break
            if moved:
                break
        if moved:
            # compact and recurse
            mapping = {}
            next_c = 0
            for i in range(n):
                c = col[i]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                col[i] = mapping[c]
            return eliminate_color(col)
        else:
            return col

    # Apply Kempe elimination on best coloring found
    final_col = eliminate_color(best_coloring[:])
    final_k = num_colors(final_col)
    if final_k < best_k:
        best_k = final_k
        best_coloring = final_col

    # Validate coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Fallback to Welsh-Powell if invalid (should not happen)
                col_wp = greedy_color(order_wp)
                return col_wp

    return best_coloring

