                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    if not is_matrix:
        # Convert adjacency list to matrix for uniform processing
        mat = [[0] * n for _ in range(n)]
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    mat[u][v] = 1
                    mat[v][u] = 1
        adj = mat

