    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in range(n):
                if adj[u][v] and colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # saturation degree
        remaining = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree, then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in remaining:
                sat_u = saturated[u]
                deg_u = degree[u]
                if sat_u > max_sat or (sat_u == max_sat and (deg_u > max_deg or (deg_u == max_deg and u > v))):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            # assign smallest available color
            used = 0
            for w in range(n):
