            # W: vertices adjacent to at least one in independent (ineligible)
            U = {w for w in uncolored if w != v and not adj[v][w]}
            W = {w for w in uncolored if w != v and adj[v][w]}
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = sum(1 for w in W if adj[u][w])
                    deg_u = sum(1 for w in U if adj[u][w])
                    if nw > max_nw or (nw == max_nw and (deg_u < min_deg_u or (deg_u == min_deg_u and u < u_star))):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                independent.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star from U to W
                for w in list(U):
                    if adj[u_star][w]:
