    k = next_color

    # Kempe chain color reduction
    def kempe_reduce(colors, k_cur):
        if k_cur <= 1:
            return colors, k_cur
        # try to eliminate color classes from highest down
        for target_color in range(k_cur-1, 0, -1):
            # collect vertices with target_color
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            changed = True
            while changed and verts:
                changed = False
                v = verts.pop()
