                for w in range(n):
                    if adj[v][w]:
                        neighbor_colors.add(colors[w])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    # rebuild verts list
                    verts = [w for w in range(n) if colors[w] == target_color]
                    continue
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # BFS to find (target_color, c)-Kempe chain containing v
                        from collections import deque
