                        changed = True
                        break
                if changed:
                    break
            if not changed:
                break
            # Compact colors if target class is empty
            classes = [[] for _ in range(k)]
            for v in range(n):
                classes[coloring[v]].append(v)
            if not classes[target]:
                # Recolor: map colors > target down by 1
                for v in range(n):
                    if coloring[v] > target:
                        coloring[v] -= 1
                k -= 1
                # Rebuild classes for next iteration
        return coloring

    # Apply Kempe reduction
    best = kempe_reduce(best[:])
    # Validate coloring
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best[u] == best[v]:
