        # Ensure colors are consecutive
        if best:
            unique_colors = set(best)
            if unique_colors != set(range(len(unique_colors))):
                mapping = {old: new for new, old in enumerate(sorted(unique_colors))]
                best = [mapping[c] for c in best]
    return best

