                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # degree in U-induced subgraph
                    degU = 0
                    for w in neighbors[u]:
                        if w in U:
                            degU += 1
                    if score > best_score or (score == best_score and (degU < best_degU or best_degU is None)):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
            c += 1
