        saturation = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] != -1:
                    continue
                sat = saturation[u].bit_count()
                deg = degrees[u]
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and random.random() < 0.5):
                    max_sat = sat
                    max_deg = deg
                    v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

            # Update saturation of neighbors
            for u in adj_list[v]:
                if colors[u] == -1:
                    saturation[u] |= (1 << c)

        return compact_colors(colors)

    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.add(v)
            # Partition uncolored \ {v} into U (not adjacent to S) and W (adjacent to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(w in adj_list[u] for w in S):
                    W.add(u)
                else:
                    U.add(u)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_common = -1
                min_deg_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    common = 0
                    for w in adj_list[u]:
                        if w in W:
                            common += 1
                    # Tie-break: min degree in G[U]
                    deg_U = len([w for w in adj_list[u] if w in U])
                    if common > max_common or (common == max_common and deg_U < min_deg_U) or (common == max_common and deg_U == min_deg_U and random.random() < 0.5):
                        max_common = common
                        min_deg_U = deg_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for u in S:
                colors[u] = color
            color += 1
            # Next uncolored set is W
            uncolored = W

        return compact_colors(colors)

