        min_deg = 0
        for _ in range(n):
            # Find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if temp_deg[u] > 0:  # only if u is still in remaining (we don't track remaining explicitly, but we decrease degree)
                    d_old = temp_deg[u]
                    temp_deg[u] -= 1
                    d_new = temp_deg[u]
                    if d_old <= max_deg:
                        # remove u from old bucket (we don't actually remove, but we will skip when popped if degree doesn't match)
                        # Instead, we rely on the fact that we only decrease degree and we will see it in lower bucket
                        pass
                    if d_new <= max_deg:
                        buckets[d_new].append(u)
            # Mark v as removed by setting degree to -1 (so we don't process again)
            temp_deg[v] = -1

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
