    # Kempe chain swap for colors a and b, starting from vertex v, returns new coloring if swap is performed, else None
    def kempe_swap(colors, a, b, v):
        n = len(colors)
        if a == b:
            return colors[:]
        # Find the Kempe chain containing v for colors a and b
        stack = [v]
        visited = [False] * n
        component = []
        while stack:
            u = stack.pop()
            if visited[u]:
                continue
            visited[u] = True
            if colors[u] == a or colors[u] == b:
                component.append(u)
                for w in adj_list[u]:
                    if not visited[w] and (colors[w] == a or colors[w] == b):
                        stack.append(w)
        # Check if we can swap: after swap, no conflict
        # Actually, swapping a Kempe chain always preserves validity
        # Perform swap
        new_colors = colors[:]
        for u in component:
            if new_colors[u] == a:
                new_colors[u] = b
            else:
                new_colors[u] = a
        return new_colors

    # Try to eliminate the last color using Kempe chains
    def reduce_colors(colors):
