    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to greedy
    if not candidates:
        colors = [-1] * n
        for v in range(n):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
