def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    # Build bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: get uncolored vertices
    def get_uncolored(coloring):
        return [i for i in range(n) if coloring[i] == -1]

    # Helper: saturation degree of a vertex
    def saturation_degree(v, coloring):
        neighbor_colors = set()
        for u in adj_list[v]:
            if coloring[u] != -1:
                neighbor_colors.add(coloring[u])
        return len(neighbor_colors)

    # Helper: degree in uncolored subgraph
    def uncolored_degree(v, coloring, uncolored_set):
        count = 0
        for u in adj_list[v]:
            if coloring[u] == -1:
                count += 1
        return count

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # Order by initial degree descending for tie-breaking in saturation
        vertices_by_degree = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        # Map vertex to its degree for tie-breaking
        degree = [len(adj_list[i]) for i in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation, break ties by degree, then index
            candidates = get_uncolored(coloring)
            if not candidates:
                break
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in candidates:
                sat = saturation_degree(v, coloring)
                deg = degree[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v < best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            # Assign smallest available color
            used = [False] * (n + 1)
            for u in adj_list[best_v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[best_v] = c
        return coloring

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored_set = set(range(n))
        while uncolored_set:
            # Step 1: pick vertex with max degree in G[R]
            R = list(uncolored_set)
            if not R:
                break
            # Find vertex in R with max degree in induced subgraph
            max_deg = -1
            v1 = -1
            for v in R:
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored_set:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v1 = v
            S = {v1}
            # Partition R \ {v1} into U and W
            U = set()
            W = set()
            for u in R:
                if u == v1:
                    continue
                if u in adj_list[v1]:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_u_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if score > best_score or (score == best_score and deg_in_U < best_u_deg_in_U):
                        best_score = score
                        best_u_deg_in_U = deg_in_U
                        best_u = u
                # Add best_u to S, move from U to W its neighbors in U
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u that are in U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            # Remove S from uncolored_set
            uncolored_set -= S
            color += 1
        return coloring

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # We'll simulate peeling
        temp_adj = [set(adj_list[i]) for i in range(n)]
        while remaining:
            # Find vertex with min degree in remaining
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                d = 0
                for u in temp_adj[v]:
                    if u in remaining:
                        d += 1
                if d < min_deg:
                    min_deg = d
                    v_min = v
            order.append(v_min)
            remaining.remove(v_min)
            # Remove v_min from neighbors' temp_adj
            for u in temp_adj[v_min]:
                if u in remaining:
                    temp_adj[u].discard(v_min)
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, v, a, b):
        if coloring[v] not in (a, b):
            return False
        target = b if coloring[v] == a else a
        stack = [v]
        visited = set()
        component = []
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if coloring[u] == a or coloring[u] == b:
                component.append(u)
                for w in adj_list[u]:
                    if w not in visited and (coloring[w] == a or coloring[w] == b):
                        stack.append(w)
        # Check if we can swap: no neighbor outside component has color target
        for u in component:
            for w in adj_list[u]:
                if w not in component and coloring[w] == target:
                    return False  # would cause conflict
        # Perform swap
        for u in component:
            if coloring[u] == a:
                coloring[u] = b
            else:
                coloring[u] = a
        return True

    # Try to eliminate the smallest color class using Kempe chains
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, 0, -1):
            # Get vertices with target_color
            vertices = [i for i in range(n) if coloring[i] == target_color]
            if not vertices:
                continue
            # Try to recolor each vertex
            made_progress = False
            for v in vertices:
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    conflict = False
                    for u in adj_list[v]:
                        if coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    if kempe_swap(coloring, v, target_color, c):
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                # Cannot eliminate this color, try next lower
                continue
            else:
                # Recoloring happened, restart from highest color
                return reduce_colors(coloring)
        # Compact colors: remap to 0..k'-1
        used_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(used_colors)}
        for i in range(n):
            coloring[i] = mapping[coloring[i]]
        return coloring

    # Generate candidate colorings
    start_time = time.time()
    candidates = []

    # Run DSATUR
    c1 = dsatur()
    if is_valid(c1):
        candidates.append(c1)
    # Run RLF
    c2 = rlf()
    if is_valid(c2):
        candidates.append(c2)
    # Run Smallest-Last
    c3 = smallest_last()
    if is_valid(c3):
        candidates.append(c3)

    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for coloring in candidates:
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best = coloring

    # If no candidate valid (should not happen), fallback to greedy
    if best is None:
        coloring = [-1] * n
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        for v in order:
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[v] = c
        best = coloring

    # Apply Kempe chain reduction to try to improve
    best = reduce_colors(best)

    # Final validation and compacting (ensure 0..k-1)
    if not is_valid(best):
        # As a last resort, use greedy ordering by degree
        coloring = [-1] * n
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        for v in order:
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[v] = c
        best = coloring

    # Compact colors
    used_colors = sorted(set(best))
    mapping = {old: new for new, old in enumerate(used_colors)}
    for i in range(n):
        best[i] = mapping[best[i]]

    return best

