                # Try Kempe chains with each lower color
                for c in range(target):
                    # Build (target, c) Kempe chain containing v
                    # BFS/DFS over vertices colored target or c
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target or coloring[node] == c:
                            component.add(node)
                            nbrs_node = adj[node] if not is_matrix else [i for i in range(n) if adj[node][i]]
                            for nb in nbrs_node:
                                if nb not in visited and (coloring[nb] == target or coloring[nb] == c):
                                    stack.append(nb)
                    # Check if any neighbor of v in component has color c? Actually, we want to see if we can swap
                    # After swapping, v would become c, which is free if no neighbor of v has color c post-swap.
                    # In the component, neighbors of v that are colored c will become target, and vice versa.
                    # So we need that no neighbor of v is colored c in the component? Actually, after swap,
                    # neighbors of v that were c become target, and neighbors that were target become c.
                    # So for v to be able to take color c after swap, we need that no neighbor of v is colored c
                    # in the current coloring? Wait, after swap, the neighbors that were c become target, so they are not c.
                    # The neighbors that were target become c. So if v has a neighbor u that is colored target and in the component,
                    # after swap u becomes c, causing conflict.
                    # Therefore, we can only perform the swap if v has no neighbor in the component that is colored target.
                    # Because those neighbors would become c and conflict with v's new color c.
                    # Actually, standard condition: we can swap the component if v is not adjacent to any vertex
                    # in the component that has color c (because after swap, those become target, still not c).
                    # Let's derive: we want to recolor v to c. Currently v is target.
                    # In the component, we swap target<->c.
                    # After swap, v becomes c.
                    # For any neighbor u of v:
                    #   - If u not in component: color unchanged.
                    #   - If u in component and was target: becomes c -> conflict if u adjacent to v.
                    #   - If u in component and was c: becomes target -> no conflict (since v is c, u is target).
                    # So conflict arises only if there exists a neighbor u of v that is in the component and colored target.
                    # Thus, we can swap if no neighbor of v in the component is colored target.
                    has_target_neighbor = False
                    nbrs_v = adj[v] if not is_matrix else [i for i in range(n) if adj[v][i]]
                    for u in nbrs_v:
                        if u in component and coloring[u] == target:
                            has_target_neighbor = True
                            break
                    if not has_target_neighbor:
                        # perform swap
                        for node in component:
                            if coloring[node] == target:
                                coloring[node] = c
                            else:  # must be c
                                coloring[node] = target
                        removed = True
                        break
                if removed:
                    break
            if not removed:
                # cannot eliminate target color, break
                break
            # compact again after removal
            coloring = validate_and_compact(coloring)
            if coloring is None:
                break
        return coloring
    # Apply Kempe reduction to the best candidate
    try:
        best = kempe_reduce(best)
    except Exception:
        pass
    # Final validation and compact
    best = validate_and_compact(best)
    if best is None:
        # ultimate fallback: greedy
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        coloring = [-1] * n
        for v in order:
            used = set()
            nbrs = adj[v] if not is_matrix else [i for i in range(n) if adj[v][i]]
            for u in nbrs:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best = validate_and_compact(coloring)
        if best is None:
            best = [0] * n
    return best

