import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle trivial cases
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if entries are binary (0 or 1)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:  # safety check
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert to consecutive colors starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur():
        color = [-1] * n
        # saturation: list of sets of neighbor colors for each vertex
        saturation = [set() for _ in range(n)]
        # degree in the uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by max uncolored degree, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = len(saturation[v])
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)

            if not candidates:
                break  # should not happen

            # Tie-break by uncolored degree
            max_deg = -1
            final_candidates = []
            for v in candidates:
                deg_v = uncolored_deg[v]
                if deg_v > max_deg:
                    max_deg = deg_v
                    final_candidates = [v]
                elif deg_v == max_deg:
                    final_candidates.append(v)

            v = random.choice(final_candidates) if len(final_candidates) > 1 else final_candidates[0]

            # Find smallest available color
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c

            # Remove v from uncolored and update neighbors
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    uncolored_deg[u] -= 1
                    saturation[u].add(c)

        return normalize(color)

    # RLF algorithm
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build independent set for current_color
            S = set()
            # Step 1: pick vertex with max degree in uncolored subgraph
            max_deg = -1
            v1 = None
            for v in uncolored:
                deg_v = sum(1 for u in adj_list[v] if u in uncolored)
                if deg_v > max_deg:
                    max_deg = deg_v
                    v1 = v
            if v1 is None:
                break  # should not happen
            S.add(v1)

            # Partition remaining uncolored into U (eligible) and W (ineligible)
            U = set()
            W = set()
            for v in uncolored:
                if v == v1:
                    continue
                adjacent_to_S = any(u in S for u in adj_list[v])
                if adjacent_to_S:
                    W.add(v)
                else:
                    U.add(v)

            # Step 4: while U not empty, select vertex with max neighbors in W
            while U:
                best_u = None
                max_w_neighbors = -1
                min_u_deg = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    u_deg = sum(1 for x in adj_list[u] if x in U)  # degree in U
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_u_deg = u_deg
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        if u_deg < min_u_deg:
                            min_u_deg = u_deg
                            best_u = u
                if best_u is None:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to all in S
            for v in S:
                color[v] = current_color
            uncolored -= S
            current_color += 1

        return normalize(color)

    # Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        order = []
        remaining = set(range(n))
        deg = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # Find vertex with min degree in remaining
            min_deg = float('inf')
            v_min = None
            for v in remaining:
                if deg[v] < min_deg:
                    min_deg = deg[v]
                    v_min = v
            if v_min is None:
                break
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors
            for u in adj_list[v_min]:
                if u in remaining:
                    deg[u] -= 1

        # Color in reverse order using greedy first-fit
        color = [-1] * n
        for v in reversed(order):
            used = set()
            for u in adj_list[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c

        return normalize(color)

    # Kempe chain color reduction
    def kempe_reduce(initial_coloring):
        color = initial_coloring[:]
        if not is_valid(color):
            return color  # should not happen if initial is valid

        k = num_colors(color)
        if k <= 1:
            return color

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if color[v] == target_color]
            if not verts:
                continue  # already empty

            eliminated = False
            # Try to recolor each vertex in this class
            for v in verts:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if color[u] < target_color:
                        neighbor_colors.add(color[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        color[v] = c
                        break
                else:
                    # Direct reassignment not possible, try Kempe chains
                    for c in range(target_color):
                        # Check if v can be swapped via Kempe chain (c, target_color)
                        # Only consider if v has no neighbor of color c (otherwise swap might not help)
                        has_c_neighbor = any(color[u] == c for u in adj_list[v])
                        if has_c_neighbor:
                            continue

                        # Build the Kempe chain component containing v for colors c and target_color
                        stack = [v]
                        visited = set([v])
                        component = set()
                        while stack:
                            node = stack.pop()
                            component.add(node)
                            for u in adj_list[node]:
                                if color[u] in (c, target_color) and u not in visited:
                                    visited.add(u)
                                    stack.append(u)

                        # Check if swapping is safe: no vertex in component has a neighbor of color c outside component
                        # Actually, for the swap to be valid, we need that after swap, no two adjacent have same color.
                        # Swapping colors c and target_color in component is safe if:
                        #   For every vertex in component, none of its neighbors outside component have color c (which will become target_color after swap) 
                        #   and none have color target_color (which will become c after swap).
                        # But since we are only considering vertices with colors c or target_color in the component,
                        # and we know that v has no neighbor of color c (by has_c_neighbor check), we need to ensure:
                        #   No vertex in component has a neighbor outside component with color c (which would become target_color and conflict with vertices in component that become target_color? 
                        # Actually, after swap:
                        #   Vertices in component that were color c become target_color.
                        #   Vertices in component that were target_color become c.
                        #   So, for a vertex x in component that was color c (now target_color), it must not have any neighbor outside component with color target_color.
                        #   For a vertex x in component that was target_color (now c), it must not have any neighbor outside component with color c.
                        safe = True
                        for node in component:
                            col_node = color[node]
                            for u in adj_list[node]:
                                if u not in component:
                                    col_u = color[u]
                                    if col_node == c and col_u == target_color:
                                        safe = False
                                        break
                                    if col_node == target_color and col_u == c:
                                        safe = False
                                        break
                            if not safe:
                                break
                        if safe:
                            # Perform the swap
                            for node in component:
                                if color[node] == c:
                                    color[node] = target_color
                                else:
                                    color[node] = c
                            eliminated = True
                            break  # break from c loop
                    if eliminated:
                        break  # break from v loop
                if eliminated:
                    break  # break from v loop

            if eliminated:
                # Recolor classes to be consecutive
                color = normalize(color)
                k = num_colors(color)
                # Restart reduction from the new highest color
                return kempe_reduce(color)

        return normalize(color)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidates, fall back to greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        candidates.append(normalize(color))

    # Select the candidate with the fewest colors
    best = min(candidates, key=lambda x: (num_colors(x), x))  # tie-break by lex order for determinism
    best = kempe_reduce(best)

    # Final validation and normalization
    if not is_valid(best):
        # Last resort: greedy coloring
        order = list(range(n))
        color = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        best = normalize(color)

    return best

