    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    neighbors[u].append(v)
                    bit_adj[u] |= (1 << v)

    # Helper: validate coloring
    def is_valid_coloring(col):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and col[u] == col[v]:
                    return False
        return True

    # Helper: normalize colors to 0..k-1
    def normalize(col):
        if not col:
            return col
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]

    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bit masks
        neighbor_colors = [0] * n
        uncolored = set(range(n))

        # Initial: pick vertex with max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            neighbor_colors[v] = 1 << 0
            uncolored.remove(v)
            # Update neighbors of v
            for u in neighbors[v]:
                if u in uncolored:
                    neighbor_colors[u] |= (1 << 0)
                    saturation[u] = neighbor_colors[u].bit_count()

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            def select_vertex():
                max_sat = -1
                candidates = []
                for v in uncolored:
                    sat = saturation[v]
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
                if len(candidates) == 1:
                    return candidates[0]
                # Tie-break: max degree in uncolored subgraph
                max_deg = -1
                deg_candidates = []
                for v in candidates:
                    deg = sum(1 for u in neighbors[v] if u in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        deg_candidates = [v]
                    elif deg == max_deg:
                        deg_candidates.append(v)
                if len(deg_candidates) == 1:
                    return deg_candidates[0]
                return random.choice(deg_candidates)

            v = select_vertex()
            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            # Update neighbor color info
            neighbor_colors[v] |= (1 << c)
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] = neighbor_colors[u].bit_count()
        return color

    # Helper: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build independent set for current_color
            # Step 1: pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent_set = {v}
            to_remove = {v}
            # Partition: U = vertices not adjacent to any in independent_set
            # W = vertices adjacent to at least one in independent_set
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
