            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for x in neighbors[u] if x in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = sum(1 for x in neighbors[u] if x in U)
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_in_U = sum(1 for x in neighbors[u] if x in U)
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = u
                if best_u is None:
                    break  # should not happen
                # Add best_u to independent set
                independent_set.add(best_u)
                to_remove.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for x in neighbors[best_u]:
                    if x in U:
                        U.remove(x)
                        W.add(x)
            # Assign color to independent_set
            for v in independent_set:
                color[v] = current_color
                uncolored.remove(v)
            current_color += 1
        return color

    # Helper: Smallest-Last (SL) ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[v]) for v in range(n)]
        order = []
        # We'll use bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if degree[v] < len(buckets):
                buckets[degree[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr < len(buckets) and not buckets[ptr]:
                ptr += 1
            if ptr >= len(buckets):
                break  # should not happen
            # Get a vertex from bucket[ptr]
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = degree[u]
                    degree[u] -= 1
                    if old_deg < len(buckets):
                        buckets[old_deg].remove(u)  # O(n) but n<=100
                    if degree[u] < len(buckets):
                        buckets[degree[u]].append(u)
                    # Update ptr if needed
                    if degree[u] < ptr:
                        ptr = degree[u]
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
