        for v in range(n):
            used = 0
            for u in neighbors[v]:
                used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        candidates.append(normalize(color))

    # Select best candidate (fewest colors)
    best_color = min(candidates, key=lambda x: max(x) + 1 if x else 0)
    k = max(best_color) + 1 if best_color else 0

