            for c in range(target_color):
                # Check if v is in a Kempe chain of (target_color, c) that does not include any other target_color vertex?
                # We want to swap a component that contains v but no other vertex of target_color (so that after swap, v becomes c and no vertex becomes target_color)
                # Actually, we can swap any component; after swap, the number of target_color vertices may change.
                # We'll do: find the Kempe chain component of v in colors {target_color, c}
                from collections import deque
                visited = set()
                queue = deque([v])
                visited.add(v)
                component = set()
                while queue:
                    x = queue.popleft()
                    component.add(x)
                    for y in neighbors[x]:
                        if y not in visited and (best_color[y] == target_color or best_color[y] == c):
                            visited.add(y)
                            queue.append(y)
                # Check if this component contains any vertex of color target_color other than v? 
                # Actually, we can swap regardless; after swap, v will become c, and any target_color in component becomes c, and any c becomes target_color.
                # So the number of target_color vertices after swap = (original target_color count) - (# of target_color in component) + (# of c in component)
                # We want this to be less than original target_color count.
                target_in_comp = sum(1 for x in component if best_color[x] == target_color)
                c_in_comp = sum(1 for x in component if best_color[x] == c)
                if target_in_comp > c_in_comp:
                    # Swapping reduces the number of target_color vertices
                    for x in component:
                        if best_color[x] == target_color:
                            best_color[x] = c
                        elif best_color[x] == c:
                            best_color[x] = target_color
                    improved = True
                    break
            if improved:
                break
        if improved:
            # Normalize and update k
            best_color = normalize(best_color)
            k = max(best_color) + 1 if best_color else 0
        else:
            # Could not eliminate target color
            break

    # Final normalization
    best_color = normalize(best_color)
    return best_color

