def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build neighbor bitmasks
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            mask = 0
            for v in adj[u]:
                mask |= (1 << v)
            bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(col):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if col[u] == col[v]:
                        return False
        return True

    # Helper: count distinct colors
    def color_count(col):
        return max(col) + 1 if col else 0

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # initial vertex: max degree
        if uncolored:
            v = max(uncolored, key=lambda x: bin(bit_adj[x]).count('1'))
            color[v] = 0
            uncolored.remove(v)
            # update saturation of neighbors
            nbrs = bit_adj[v]
            while nbrs:
                lsb = nbrs & -nbrs
                u = (lsb.bit_length() - 1)
                sat[u] += 1
                nbrs ^= lsb
        while uncolored:
            # find vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if len(candidates) == 1:
                v = candidates[0]
            else:
                # tie-break: max degree in uncolored subgraph
                max_deg = -1
                best_v = candidates[0]
                for v in candidates:
                    # count uncolored neighbors
                    deg = bin(bit_adj[v] & sum((1 << u) for u in uncolored)).count('1')
                    if deg > max_deg:
                        max_deg = deg
                        best_v = v
                v = best_v
            # find smallest available color
            used = 0
            nbrs = bit_adj[v]
            while nbrs:
                lsb = nbrs & -nbrs
                u = (lsb.bit_length() - 1)
                c = color[u]
                if c != -1:
                    used |= (1 << c)
                nbrs ^= lsb
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            nbrs = bit_adj[v]
            while nbrs:
                lsb = nbrs & -nbrs
                u = (lsb.bit_length() - 1)
                if u in uncolored:
                    sat[u] += 1
                nbrs ^= lsb
        return color

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: bin(bit_adj[x] & sum((1 << u) for u in uncolored)).count('1'))
            S.add(v)
            # partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if bit_adj[v] & (1 << u):
                    W.add(u)
                    U.remove(u)
            # while U not empty, add vertices with max neighbors in W
            while U:
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = None
                for u in U:
                    w_neighbors = bin(bit_adj[u] & sum((1 << w) for w in W)).count('1')
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = bin(bit_adj[u] & sum((1 << x) for x in U)).count('1')
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_u = bin(bit_adj[u] & sum((1 << x) for x in U)).count('1')
                        if deg_u < min_deg_in_U:
                            min_deg_in_U = deg_u
                            best_u = u
                if best_u is None:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                nbrs = bit_adj[best_u]
                while nbrs:
                    lsb = nbrs & -nbrs
                    w = (lsb.bit_length() - 1)
                    if w in U:
                        U.remove(w)
                        W.add(w)
                    nbrs ^= lsb
            # assign color c to all in S
            for v in S:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Smallest-Last ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [bin(bit_adj[v]).count('1') for v in range(n)]
        order = []
        # we will simulate removal
        # maintain current degrees in remaining subgraph
        curr_deg = degree[:]
        # bucket sort by degree
        max_deg = max(curr_deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[curr_deg[v]].append(v)
        # pointer to non-empty bucket
        ptr = 0
        while remaining:
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # get a vertex from bucket[ptr]
            while buckets[ptr] and buckets[ptr][-1] not in remaining:
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # update neighbors
            nbrs = bit_adj[v]
            while nbrs:
                lsb = nbrs & -nbrs
                u = (lsb.bit_length() - 1)
                if u in remaining:
                    # decrease degree of u
                    old_deg = curr_deg[u]
                    curr_deg[u] -= 1
                    buckets[old_deg].remove(u)
                    if curr_deg[u] < len(buckets):
                        buckets[curr_deg[u]].append(u)
                    else:
                        # extend buckets if needed (should not happen)
                        buckets.extend([[] for _ in range(curr_deg[u] - len(buckets) + 1)])
                        buckets[curr_deg[u]].append(u)
                nbrs ^= lsb
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            nbrs = bit_adj[v]
            while nbrs:
                lsb = nbrs & -nbrs
                u = (lsb.bit_length() - 1)
                c = color[u]
                if c != -1:
                    used |= (1 << c)
                nbrs ^= lsb
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(col):
        # make a copy
        col = col[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (largest color index)
            max_color = max(col) if col else -1
            if max_color < 0:
                break
            # collect vertices by color
            color_classes = [[] for _ in range(max_color + 1)]
            for v, c in enumerate(col):
                color_classes[c].append(v)
            # try to eliminate color classes from highest down
            for target_color in range(max_color, -1, -1):
                if not color_classes[target_color]:
                    continue
                # try to recolor each vertex in this class
                for v in color_classes[target_color][:]:
                    # try direct reassignment to a lower color
                    neighbor_colors = set()
                    nbrs = bit_adj[v]
                    while nbrs:
                        lsb = nbrs & -nbrs
                        u = (lsb.bit_length() - 1)
                        neighbor_colors.add(col[u])
                        nbrs ^= lsb
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            # move v to color c
                            col[v] = c
                            color_classes[target_color].remove(v)
                            color_classes[c].append(v)
                            changed = True
                            break
                    if changed:
                        break
                    # try Kempe chains with each lower color
                    for c in range(target_color):
                        if c in neighbor_colors:
                            continue
                        # check if v is connected to color c via Kempe chain (c, target_color)
                        # BFS/DFS over vertices colored c or target_color
                        stack = [v]
                        visited = set()
                        component = set()
                        found_c = False
                        found_target = False
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            node_col = col[node]
                            if node_col == c:
                                found_c = True
                            elif node_col == target_color:
                                found_target = True
                            else:
                                continue  # should not happen as we only traverse c/target_color
                            component.add(node)
                            # neighbors with color c or target_color
                            nbrs = bit_adj[node]
                            while nbrs:
                                lsb = nbrs & -nbrs
                                u = (lsb.bit_length() - 1)
                                nbr_col = col[u]
                                if nbr_col == c or nbr_col == target_color:
                                    if u not in visited:
                                        stack.append(u)
                                nbrs ^= lsb
                        # if we found a vertex of color c in the component, we can swap
                        if found_c:
                            # swap colors c and target_color in the component
                            for node in component:
                                if col[node] == c:
                                    col[node] = target_color
                                elif col[node] == target_color:
                                    col[node] = c
                            # update color classes
                            color_classes[c].clear()
                            color_classes[target_color].clear()
                            for node in range(n):
                                color_classes[col[node]].append(node)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # compact colors if any highest color class is empty
            while max_color >= 0 and not color_classes[max_color]:
                max_color -= 1
            if max_color < 0:
                break
            # reindex colors to be 0..max_color
            mapping = {}
            for old in range(max_color + 1):
                mapping[old] = old  # already compact if we removed empties at top
            # but there might be gaps in middle, so we need to compact fully
            # rebuild mapping from used colors
            used_colors = set(col)
            if not used_colors:
                break
            sorted_used = sorted(used_colors)
            mapping = {old: new for new, old in enumerate(sorted_used)}
            col = [mapping[c] for c in col]
            # rebuild color_classes
            max_color = max(col) if col else -1
            color_classes = [[] for _ in range(max_color + 1)]
            for v, c in enumerate(col):
                color_classes[c].append(v)
        return col

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass
    # If no candidates (should not happen), fallback to trivial greedy
    if not candidates:
        # greedy by vertex order
        col = [-1] * n
        for v in range(n):
            used = 0
            nbrs = bit_adj[v]
            while nbrs:
                lsb = nbrs & -nbrs
                u = (lsb.bit_length() - 1)
                if col[u] != -1:
                    used |= (1 << col[u])
                nbrs ^= lsb
            c = 0
            while used & (1 << c):
                c += 1
            col[v] = c
        candidates.append(col)
    # Choose best (fewest colors)
    best = min(candidates, key=color_count)
    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best)
        if is_valid(improved) and color_count(improved) < color_count(best):
            best = improved
    except Exception:
        pass
    # Ensure colors are consecutive starting from 0
    used = set(best)
    if used:
        mapping = {old: new for new, old in enumerate(sorted(used))]
        best = [mapping[c] for c in best]
    return best

