def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect input type: adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build neighbor list and bitmask adjacency
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if v < 0 or v >= n:
                    continue
                neighbors[u].append(v)
                bit_adj[u] |= (1 << v)
    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color
    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation degree: bitmask of colors used by neighbors
        sat = [0] * n
        uncolored = set(range(n))
        # degree in the uncolored subgraph
        deg_uncolored = [len(neighbors[u]) for u in range(n)]
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                d = deg_uncolored[u]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best = u
            u = best
            # assign smallest available color
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
            uncolored.remove(u)
            # update saturation and degrees for uncolored neighbors
            for v in neighbors[u]:
                if v in uncolored:
                    sat[v] |= (1 << c)
                    deg_uncolored[v] -= 1
        return color
    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in the uncolored subgraph
            deg_uncolored = {u: 0 for u in uncolored}
            for u in uncolored:
                for v in neighbors[u]:
                    if v in uncolored:
                        deg_uncolored[u] += 1
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda u: deg_uncolored[u])
            S = {v}
            uncolored.remove(v)
            # W: vertices adjacent to S
            W = set()
            for u in S:
                for w in neighbors[u]:
                    if w in uncolored:
                        W.add(w)
            # U: uncolored vertices not adjacent to S
            U = uncolored - W
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = None
                best_w_neighbors = -1
                best_deg_U = None
                for u in U:
                    w_neighbors = 0
                    for w in neighbors[u]:
                        if w in W:
                            w_neighbors += 1
                    deg_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_U += 1
                    if (w_neighbors > best_w_neighbors or
                        (w_neighbors == best_w_neighbors and deg_U < best_deg_U) or
                        (w_neighbors == best_w_neighbors and deg_U == best_deg_U and random.random() < 0.5)):
                        best_w_neighbors = w_neighbors
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
