    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get removal order
        degree = [len(neighbors[u]) for u in range(n)]
        # buckets for degrees
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            d = degree[u]
            buckets[d].append(u)
        # track current degree and position
        pos = [0] * n
        for d in range(max_deg + 1):
            for i, u in enumerate(buckets[d]):
                pos[u] = i
        # removal order
        order = []
        current_degree = degree[:]
        # pointer to non-empty bucket
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
