            for v in neighbors[u]:
                if current_degree[v] > ptr:  # v not yet removed
                    d = current_degree[v]
                    # remove v from bucket d
                    i = pos[v]
                    last = buckets[d][-1]
                    buckets[d][i] = last
                    pos[last] = i
                    buckets[d].pop()
                    # add to bucket d-1
                    current_degree[v] -= 1
                    d2 = current_degree[v]
                    buckets[d2].append(v)
                    pos[v] = len(buckets[d2]) - 1
