        return greedy_color(order[::-1])
    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        candidates.append(col_sl)
    except Exception:
        pass
    # Also try Welsh-Powell (degree ordering)
    try:
        order_wp = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        col_wp = greedy_color(order_wp)
        candidates.append(col_wp)
    except Exception:
        pass
    # Choose the candidate with the fewest colors
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_coloring = col
    if best_coloring is None:
        # fallback: greedy on natural order
        best_coloring = greedy_color(list(range(n)))
        best_k = max(best_coloring) + 1 if n > 0 else 0
    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # make a copy we can modify
        color = coloring[:]
        # helper: get vertices of a color
        def color_class(c):
            return [u for u in range(n) if color[u] == c]
        # helper: check if coloring is valid
