                        # check if there is a Kempe chain (v, c) that does not include any other target-colored vertex
                        # BFS to get the (v,c)-Kempe chain component containing v
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            u = queue.popleft()
                            component.append(u)
                            for w in neighbors[u]:
                                if not visited[w] and (color[w] == c or color[w] == target):
                                    visited[w] = True
                                    queue.append(w)
                        # check if any other target-colored vertex is in this component
                        has_other_target = any(color[u] == target and u != v for u in component)
                        if not has_other_target:
                            # swap colors c and target in the component
                            for u in component:
                                if color[u] == c:
                                    color[u] = target
                                elif color[u] == target:
                                    color[u] = c
                            # now v has color c
                            break
                    else:
