                        return False
            # after processing all target vertices, verify target class is empty
            return len(color_class(target)) == 0
        # iteratively try to eliminate the highest color class
        changed = True
        while changed and best_k > 0:
            changed = False
            target = best_k - 1
            if try_remove_target(target):
