        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = [list(neigh) for neigh in adj]
    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Helper: compute chromatic number from coloring
    def chromatic_number(colors):
        return max(colors) + 1 if colors else 0

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper: convert coloring to consecutive indices starting from 0
    def normalize(colors):
        if not colors:
            return colors
        unique = sorted(set(colors))
        mapping = {c: i for i, c in enumerate(unique)}
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # degrees in the whole graph
        degrees = [len(adj_list[u]) for u in range(n)]
        # saturation sets: colors used by colored neighbors
        saturation = [set() for _ in range(n)]
        # colored count
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    sat = len(saturation[u])
                    if sat > max_sat or (sat == max_sat and (degrees[u] > max_deg or (degrees[u] == max_deg and u > v))):
                        max_sat = sat
                        max_deg = degrees[u]
                        v = u
            if v == -1:
                break  # should not happen
            # find smallest color not used by neighbors
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c
            # update saturation of neighbors
            for nb in adj_list[v]:
                if colors[nb] == -1:
                    saturation[nb].add(c)
        return normalize(colors)

    # RLF: Recursive Largest First
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))
        # Precompute degrees in the whole graph for initial selection
        degrees = [len(adj_list[u]) for u in range(n)]
        while uncolored:
            # Build independent set for this color
            S = set()
            # Choose vertex with max degree in induced subgraph G[uncolored]
            v = max(uncolored, key=lambda u: sum(1 for nb in adj_list[u] if nb in uncolored))
            S.add(v)
            # Partition uncolored \ {v} into U (not adjacent to S) and W (adjacent to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(nb in S for nb in adj_list[u]):
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add vertices from U to S
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_nei = -1
                min_deg_u = math.inf
                for u in U:
                    # count neighbors in W
                    w_nei = sum(1 for nb in adj_list[u] if nb in W)
                    deg_u = sum(1 for nb in adj_list[u] if nb in U)  # degree in U
                    if w_nei > max_w_nei or (w_nei == max_w_nei and deg_u < min_deg_u):
                        max_w_nei = w_nei
                        min_deg_u = deg_u
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u that are in U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to all vertices in S
            for u in S:
                colors[u] = color
            color += 1
            # remove S from uncolored
