    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidate (should not happen), fallback to trivial greedy
    if not candidates:
        colors = [-1] * n
        for u in range(n):
            used = set()
            for nb in adj_list[u]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[u] = c
        candidates.append(normalize(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=chromatic_number)
    best_k = chromatic_number(best)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = chromatic_number(colors)
        if k <= 1:
            return colors
