            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                # current degree in uncolored subgraph
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v

            # Assign smallest available color
            used = saturation[v]
