            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)

            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)

        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0

        while uncolored:
            # Build maximal independent set for color c
            # degree in current uncolored subgraph
            deg_uncolored = [0] * n
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_uncolored[v] += 1

            # Start with vertex of max degree in uncolored subgraph
            S = set()
            if uncolored:
                v = max(uncolored, key=lambda x: deg_uncolored[x])
                S.add(v)
                uncolored.remove(v)
