                U = set(uncolored)  # copy
                W = set()
                # Move neighbors of v from U to W
                for u in adj_list[v]:
                    if u in U:
                        U.remove(u)
                        W.add(u)

                while U:
                    # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                    best_u = -1
                    best_score = -1
                    best_deg_u = -1
                    for u in U:
                        # score: number of neighbors in W
                        score = 0
                        for w in adj_list[u]:
                            if w in W:
                                score += 1
                        # degree in G[U]
                        deg_u = 0
                        for w in adj_list[u]:
                            if w in U:
                                deg_u += 1
                        if score > best_score or (score == best_score and deg_u < best_deg_u) or (score == best_score and deg_u == best_deg_u and u < best_u):
                            best_score = score
                            best_deg_u = deg_u
                            best_u = u
                    u = best_u
                    S.add(u)
                    U.remove(u)
