    candidates = []

    # DSATUR
    try:
        col1 = dsatur()
        if is_valid(col1):
            candidates.append(col1)
    except:
        pass

    # RLF
    try:
        col2 = rlf()
        if is_valid(col2):
            candidates.append(col2)
    except:
        pass

    # Smallest-Last
    try:
        col3 = smallest_last()
        if is_valid(col3):
            candidates.append(col3)
    except:
        pass

    # Fallback: simple greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(col)

    # Select best candidate (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        k = num_colors(col)
        if k < best_k:
            best_k = k
            best_coloring = col

    if best_coloring is None:
        # Ultimate fallback: assign all vertices distinct colors
        best_coloring = list(range(n))

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        """Try to eliminate target_color by recoloring its vertices."""
        n = len(coloring)
        # Get vertices with target_color
        targets = [v for v in range(n) if coloring[v] == target_color]
        if not targets:
            return coloring  # already eliminated

        # Try direct reassignment first
        new_coloring = coloring[:]
        eliminated = True
        for v in targets:
            used = 0
            for u in adj_list[v]:
                c = new_coloring[u]
                if c != -1:
                    used |= (1 << c)
            # Find smallest color not used by neighbors
            c = 0
            while used & (1 << c):
                c += 1
            if c == target_color:
                # Cannot recolor without using target_color (should not happen if we skip target)
                # Actually, we want to avoid target_color, so find c != target_color
                c = 0
                while c == target_color or (used & (1 << c)):
                    c += 1
                # If we exhausted colors, we cannot eliminate this way
                if c >= n:  # safe bound
                    eliminated = False
                    break
            new_coloring[v] = c

        if eliminated and is_valid(new_coloring):
            # Check if target_color is still used
            if target_color not in new_coloring:
                # Compact colors: remap to 0..k-1
                unique_colors = sorted(set(new_coloring))
                mapping = {old: new for new, old in enumerate(unique_colors)}
                compacted = [mapping[c] for c in new_coloring]
                return compacted

        # Try Kempe chains for each target vertex
        for v in targets:
            a = target_color
            # Try each color c < a
            for c in range(a):
                # Check if v can be recolored to c via Kempe chain (a,c)
                # Build the Kempe chain component containing v in colors {a,c}
                from collections import deque
                visited = [False] * n
                queue = deque([v])
                visited[v] = True
                component = []
                has_c = False  # whether component contains color c

                while queue:
                    node = queue.popleft()
                    component.append(node)
                    if coloring[node] == c:
                        has_c = True
                    for neighbor in adj_list[node]:
                        if not visited[neighbor]:
                            col_neighbor = coloring[neighbor]
                            if col_neighbor == a or col_neighbor == c:
                                visited[neighbor] = True
                                queue.append(neighbor)

                # If the component does not contain color c, we can swap
                if not has_c:
                    # Perform swap: a->c, c->a in component
                    new_coloring = coloring[:]
                    for node in component:
                        if new_coloring[node] == a:
                            new_coloring[node] = c
                        elif new_coloring[node] == c:
                            new_coloring[node] = a
                    # Check validity (should be valid by Kempe theorem)
                    if is_valid(new_coloring):
                        # Check if target_color is eliminated
                        if target_color not in new_coloring:
                            unique_colors = sorted(set(new_coloring))
                            mapping = {old: new for new, old in enumerate(unique_colors)}
                            compacted = [mapping[x] for x in new_coloring]
                            return compacted

        return None  # could not eliminate

    # Iteratively try to reduce colors
    current = best_coloring[:]
    changed = True
    # Limit iterations to avoid infinite loop
    for _ in range(10):  # max 10 reduction attempts
        k = num_colors(current)
        if k <= 1:
            break
        target_color = k - 1  # smallest color class (highest index)
        new_coloring = eliminate_color_class(current, target_color)
        if new_coloring is not None and is_valid(new_coloring):
            current = new_coloring
        else:
            break

    # Final validation and compaction
    if not is_valid(current):
        # Should not happen, but fallback to DSATUR
        current = dsatur()

    # Ensure colors are compacted
    unique_colors = sorted(set(current))
    if unique_colors != list(range(len(unique_colors))):
        mapping = {old: new for new, old in enumerate(unique_colors)}
        current = [mapping[c] for c in current]

    return current

