                    row.append(j)
                    mask |= (1 << j)
            neighbors.append(row)
            bit_adj[i] = mask
    else:
        for i in range(n):
            row = adj[i]
            mask = 0
            for v in row:
                if v < 0 or v >= n:
                    continue  # ignore invalid indices
                mask |= (1 << v)
            neighbors.append(row)
            bit_adj[i] = mask

