    curr_deg = degrees[:]
    for _ in range(n):
        # find vertex with minimum curr_deg in remaining
        min_v = -1
        min_deg = float('inf')
        for v in remaining:
            if curr_deg[v] < min_deg:
                min_deg = curr_deg[v]
                min_v = v
        if min_v == -1:
            break  # should not happen
        order_sl.append(min_v)
        remaining.remove(min_v)
        for u in neighbors[min_v]:
            if u in remaining:
                curr_deg[u] -= 1
    color_sl = greedy_color(order_sl)
    k_sl = num_colors(color_sl)
    if k_sl < best_k:
        best_k = k_sl
        best_coloring = color_sl[:]

