            max_sat = -1
            max_deg = -1
            for v in uncolored:
                sat_v = saturated[v]
                deg_v = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        deg_v += 1
                if sat_v > max_sat or (sat_v == max_sat and deg_v > max_deg) or (sat_v == max_sat and deg_v == max_deg and v > sel):
                    max_sat = sat_v
                    max_deg = deg_v
