                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_nei = -1
                min_deg_U = float('inf')
                for u in U:
                    w_nei = 0
                    for w in neighbors[u]:
                        if w in W:
                            w_nei += 1
                    deg_u_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_u_U += 1
                    if w_nei > max_w_nei or (w_nei == max_w_nei and deg_u_U < min_deg_U) or (w_nei == max_w_nei and deg_u_U == min_deg_U and u < best_u):
                        max_w_nei = w_nei
                        min_deg_U = deg_u_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
                uncolored.remove(u)
            # assign color c to all in S
            for v in S:
