    color_rlf = rlf()
    k_rlf = num_colors(color_rlf)
    if k_rlf < best_k:
        best_k = k_rlf
        best_coloring = color_rlf[:]

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make copy
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest non-empty color class
            color_classes = {}
            for v in range(n):
                c = col[v]
                color_classes.setdefault(c, []).append(v)
            if not color_classes:
                break
            max_color = max(color_classes.keys())
            # try to eliminate color classes from highest down
            for target_color in range(max_color, -1, -1):
                if target_color not in color_classes:
                    continue
                vertices = color_classes[target_color]
                # try to recolor each vertex in this class
                for v in vertices:
                    # try direct reassignment to a lower color
                    used = 0
                    for u in neighbors[v]:
                        cu = col[u]
                        if cu != -1:
                            used |= (1 << cu)
                    for c in range(target_color):  # only lower colors
                        if not (used & (1 << c)):
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # try Kempe chains with each lower color
                    for c in range(target_color):
                        # if v already not target_color, skip (should not happen)
                        if col[v] != target_color:
                            break
                        # BFS to get the (target_color, c) Kempe chain containing v
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        component = set()
                        while queue:
                            x = queue.popleft()
                            component.add(x)
                            for y in neighbors[x]:
                                if y not in visited and (col[y] == target_color or col[y] == c):
                                    visited.add(y)
                                    queue.append(y)
                        # check if swapping colors in component is safe: no neighbor outside component has color c
                        safe = True
                        for x in component:
