                                if y not in component and col[y] == c:
                                    safe = False
                                    break
                            if not safe:
                                break
                        if safe:
                            # perform swap
                            for x in component:
                                if col[x] == target_color:
                                    col[x] = c
                                else:
                                    col[x] = target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # compact colors if highest color class empty
            if changed:
                # reindex colors to be consecutive
                used_colors = set(col)
                mapping = {}
                next_c = 0
                for c in sorted(used_colors):
                    mapping[c] = next_c
                    next_c += 1
                for v in range(n):
                    col[v] = mapping[col[v]]
        return col

    # Apply Kempe reduction to the best coloring found
    final_coloring = kempe_reduce(best_coloring)
    # Validate
    for u in range(n):
        for v in neighbors[u]:
            if u < v and final_coloring[u] == final_coloring[v]:
                # Fallback: greedy Welsh-Powell (should be valid)
                order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
