            continue
        break
    # Ensure zero-based consecutive
    used_colors = set(final_coloring)
    if used_colors:
        mapping = {}
        next_c = 0
        for c in sorted(used_colors):
            mapping[c] = next_c
            next_c += 1
        final_coloring = [mapping[c] for c in final_coloring]
    return final_coloring

