            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent_to_S = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)

            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_count += 1
                    # Tie-break: min degree in U
                    deg_in_U = len([nb for nb in adj_list[u] if nb in U])
                    if w_count > max_w_neighbors or \
                       (w_count == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_count == max_w_neighbors and deg_in_U == min_deg_in_U and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen if U not empty
                # Add best_u to S
                S.add(best_u)
                U.remove(best_u)
