    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        changed = True
        # Try to reduce colors as long as we can eliminate a color class
        while changed:
            changed = False
            k = num_colors(current)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Vertices with target_color
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # Should not happen, but skip
                continue

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for nb in adj_list[v]:
                    if current[nb] < target_color:  # only colors < target_color
                        neighbor_colors.add(current[nb])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Can recolor v to c directly
                        current[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart the while loop after any change

                # Try Kempe chain swap with each lower color c
                for c in range(target_color):
                    # We want to swap colors in the (c, target_color) Kempe chain of v
                    # if it does not pull any vertex into target_color from outside
                    # Actually, we want a component that does NOT contain any vertex of color c that is adjacent to a target_color vertex? 
                    # Standard: if in the (c, target_color) Kempe chain of v, there is no vertex of color c that is adjacent to a vertex of color target_color (other than possibly v?), 
                    # but simpler: we can swap if the component of v in (c, target_color) does not contain any vertex u of color c such that u has a neighbor of color target_color (which would become target_color after swap and cause conflict?)
                    # Instead, we use: after swap, we only create a conflict if we put two adjacent vertices to target_color.
                    # So we can swap if in the Kempe chain of v (for colors c and target_color), there is no edge between a vertex colored c and a vertex colored target_color (other than those in the chain?).
                    # Actually, the condition is: the Kempe chain component of v must not contain any vertex of color c that is adjacent to a vertex of color target_color that is not in the component.
                    # But a simpler sufficient condition: if there is no vertex u of color c in the component such that u has a neighbor w of color target_color that is not in the component.
                    # However, we can also just check: after swapping the component, is the coloring still valid?
                    # Since we are only swapping two colors, we can check validity locally? But to be safe, we do:
                    # Build the Kempe chain component of v for colors {c, target_color}
                    from collections import deque
                    comp = set()
                    queue = deque([v])
                    comp.add(v)
                    while queue:
                        x = queue.popleft()
                        for nb in adj_list[x]:
                            if nb not in comp and (current[nb] == c or current[nb] == target_color):
                                comp.add(nb)
                                queue.append(nb)
                    # Now, check if swapping colors c and target_color in comp would cause a conflict
                    valid_swap = True
                    for x in comp:
                        new_color = c if current[x] == target_color else target_color
                        for nb in adj_list[x]:
                            if nb in comp:
                                nb_new = c if current[nb] == target_color else target_color
                                if new_color == nb_new:
                                    valid_swap = False
                                    break
                            else:
                                if new_color == current[nb]:
                                    valid_swap = False
                                    break
                        if not valid_swap:
                            break
                    if valid_swap:
                        # Perform the swap
                        for x in comp:
                            if current[x] == c:
                                current[x] = target_color
                            else:
                                current[x] = c
                        changed = True
                        break  # break from c loop
                if changed:
                    break  # break from v loop
            # If we changed, we need to re-normalize and repeat
            if changed:
                current = normalize_coloring(current)
        return current

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        # Simple greedy in vertex order
        colors = [-1] * n
        for u in range(n):
            neighbor_colors = 0
            for nb in adj_list[u]:
                if colors[nb] != -1:
                    neighbor_colors |= (1 << colors[nb])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[u] = c
        candidates.append(normalize_coloring(colors))

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    best = normalize_coloring(best)

    # Apply Kempe chain reduction to try to improve
    best = kempe_reduce(best)
    best = normalize_coloring(best)

    # Final validation (should be valid by construction)
    if not is_valid_coloring(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
        best = normalize_coloring(best)

    return best

