                    if score > best_score or (score == best_score and len(graph[u]) < len(graph[best_u]) if best_u is not None else False):
                        best_score = score
                        best_u = u
                if best_u is None:
                    break
                independent_set.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in graph[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        degrees = [len(graph[i]) for i in range(n)]
        # buckets for degrees
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # pointer to current min degree
        min_deg = 0
        while remaining:
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in graph[v]:
                if u in remaining:
                    d = degrees[u]
                    buckets[d].remove(u)
                    degrees[u] -= 1
                    buckets[degrees[u]].append(u)
                    if degrees[u] < min_deg:
                        min_deg = degrees[u]
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in graph[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except:
        pass

    # Also try Welsh-Powell (degree descending)
    try:
        order_wp = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        c4 = greedy_color(order_wp)
        candidates.append(c4)
    except:
        pass

    # Try random orders a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        c = greedy_color(order)
        candidates.append(c)

    # Select best candidate (fewest colors)
    for color in candidates:
        k = count_colors(color)
        if k < best_k:
            best_k = k
            best_coloring = color

    # If no candidate (shouldn't happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain color reduction
    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Ensure current coloring is valid
    if not is_valid(best_coloring):
        # Recolor greedily to fix
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Function to eliminate a color class using Kempe chains
    def eliminate_color(coloring, target_color):
        # Get vertices with target_color
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return coloring  # already eliminated

        # Try to recolor each vertex
        for v in vertices:
            # Try direct reassignment to a lower color
            used = 0
            for u in graph[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            for c in range(target_color):  # only try lower colors
                if not (used & (1 << c)):
                    # move v to color c
                    coloring[v] = c
                    # remove v from target_color class
                    # Note: we don't actually remove, but we will rebuild class later
                    # For simplicity, we break and rebuild after all moves
                    break
            else:
                # Could not assign directly, try Kempe chains
                for c in range(target_color):
                    # Build (target_color, c)-Kempe chain containing v
                    # We'll do BFS to get the component
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in graph[x]:
                            if y not in visited and (coloring[y] == target_color or coloring[y] == c):
                                visited.add(y)
                                queue.append(y)
                    # Check if inverting this component would cause conflict
                    # Specifically, check if any neighbor of a vertex in component
                    # that is not in component has color c (would become target_color after swap)
                    safe = True
                    for x in component:
                        for y in graph[x]:
                            if y not in component and coloring[y] == c:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # perform swap: target_color <-> c in component
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            elif coloring[x] == c:
                                coloring[x] = target_color
                        # after swap, v is now color c (since it was target_color)
                        break
                else:
                    # Could not recolor v with any Kempe chain
                    return None  # failure
        # After attempting to recolor all vertices, rebuild target_color class
        new_vertices = [v for v in range(n) if coloring[v] == target_color]
        if not new_vertices:
            # success: target_color eliminated
            # remap colors higher than target_color down by 1
            for v in range(n):
                if coloring[v] > target_color:
                    coloring[v] -= 1
            return coloring
        else:
            # failed to eliminate
            return None

    # Iteratively try to reduce colors
    current = best_coloring[:]
    k = best_k
    improved = True
    while improved and k > 1:
        improved = False
        # Try to eliminate color k-1 (the highest color)
        target = k - 1
        new_coloring = eliminate_color(current[:], target)  # work on a copy
        if new_coloring is not None and is_valid(new_coloring):
            current = new_coloring
            k = count_colors(current)
            improved = True
            best_coloring = current
            best_k = k
        else:
            # try eliminating lower color classes? Usually target the largest color
            # but for simplicity, break if can't eliminate the highest
            break

    # Final validation and compacting
    # Ensure colors are consecutive starting from 0
    if best_coloring:
        # Remap colors to be consecutive
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_coloring[i] = unique_colors[c]

    return best_coloring

