    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Build adjacency list from matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build complement graph adjacency list
    comp_adj = [set() for _ in range(n)]
    for i in range(n):
        neighbors = set(adj_list[i])
        for j in range(n):
            if i != j and j not in neighbors:
                comp_adj[i].add(j)

    # Degeneracy ordering of the complement graph
    remaining = set(range(n))
    deg = [len(comp_adj[i] & remaining) for i in range(n)]
    order = []
    buckets = [[] for _ in range(n)]
    for v in range(n):
        if deg[v] < n:
            buckets[deg[v]].append(v)

    for d in range(n):
        while buckets[d]:
            v = buckets[d].pop()
            if v not in remaining:
                continue
            if deg[v] != d:
                buckets[deg[v]].append(v)
                continue
            remaining.remove(v)
            order.append(v)
            for u in comp_adj[v]:
                if u in remaining:
                    deg[u] -= 1
                    if deg[u] < n:
                        buckets[deg[u]].append(u)

    # Greedy coloring on the complement graph using degeneracy order (reverse)
    color = [-1] * n
    for v in reversed(order):
        used = [False] * (n + 1)
        for u in comp_adj[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while used[c]:
            c += 1
        color[v] = c

    # In independent set of G, vertices have same color in complement coloring
    # So we assign the color from complement graph coloring as the color in G
    return color

