def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Precompute triangle counts for each vertex
    triangle_count = [0] * n
    for u in range(n):
        neighbors = adj_list[u]
        deg = len(neighbors)
        for i in range(deg):
            for j in range(i+1, deg):
                v = neighbors[i]
                w = neighbors[j]
                if (bit_adj[v] >> w) & 1:
                    triangle_count[u] += 1

    # Order vertices by triangle count (descending), then by degree (descending), then by index
    vertices = list(range(n))
    vertices.sort(key=lambda x: (-triangle_count[x], -len(adj_list[x]), x))

    # Greedy coloring in the determined order
    color = [-1] * n
    for u in vertices:
        # Find colors used by colored neighbors
        used = [False] * n  # n is safe upper bound for colors needed
        for v in adj_list[u]:
            if color[v] != -1:
                used[color[v]] = True
        # Find the smallest available color
        c = 0
        while c < n and used[c]:
            c += 1
        color[u] = c

    # Compact color indices to ensure they are consecutive from 0
    # Map existing colors to 0..k-1
    unique_colors = sorted(set(color))
    color_map = {old: new for new, old in enumerate(unique_colors)}
    color = [color_map[c] for c in color]

    return color

