    # Detect adjacency matrix
    if n > 0 and len(adj[0]) == n and all(all(x == 0 or x == 1 for x in row) for row in adj):
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= 1 << j
    else:
        # adjacency list
        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= 1 << j
                bit_adj[j] |= 1 << i  # ensure symmetry
    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], sum(1 for u in range(n) if (bit_adj[x] >> u) & 1 and u in uncolored)))
            # compute used colors by neighbors
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in uncolored:
                    sat[u] += 1
        return color
    # Helper: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in range(n) if (bit_adj[x] >> u) & 1 and u in uncolored))
            S = {v}
            uncolored.remove(v)
            # partition U and W
            U = {u for u in uncolored if not any((bit_adj[w] >> u) & 1 for w in S)}
            W = uncolored - U
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                u_star = max(U, key=lambda x: (sum(1 for w in range(n) if (bit_adj[x] >> w) & 1 and w in W), -sum(1 for w in range(n) if (bit_adj[x] >> w) & 1 and w in U)))
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for w in list(U):
                    if (bit_adj[u_star] >> w) & 1:
                        U.remove(w)
                        W.add(w)
            for vertex in S:
                color[vertex] = c
            c += 1
            uncolored = W
        return color
    # Helper: smallest-last ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [sum(1 for u in range(n) if (bit_adj[v] >> u) & 1) for v in range(n)]
        while remaining:
            v = min(remaining, key=lambda x: degrees[x])
            order.append(v)
            remaining.remove(v)
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    degrees[u] -= 1
        # color in reverse order
        return greedy_color(order[::-1])
    # Helper: Kempe chain swap attempt to remove color k
    def kempe_reduce(color):
        k = max(color) if color else -1
        if k < 0:
            return color, False
        # vertices with color k
        verts_k = [v for v in range(n) if color[v] == k]
        # try to recolor each vertex in verts_k
        for v in verts_k:
            # try direct reassignment to a lower color
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1:
                    used |= 1 << color[u]
            for c in range(k):
                if not (used & (1 << c)):
                    color[v] = c
                    # after moving v, check if color k is still used
                    if k not in color:
                        # compact colors
                        mapping = {}
                        next_c = 0
                        for col in sorted(set(color)):
                            mapping[col] = next_c
                            next_c += 1
                        for i in range(n):
                            color[i] = mapping[color[i]]
                        return color, True
                    break
            else:
                # try Kempe chains with each lower color
                for c in range(k):
                    # BFS to get Kempe chain of colors c and k containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1 and not visited[y] and (color[y] == c or color[y] == k):
                                visited[y] = True
                                queue.append(y)
                    # check if swapping c and k in component would cause conflict
                    conflict = False
                    for x in component:
                        new_color = c if color[x] == k else k
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1 and color[y] == new_color:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # perform swap
                        for x in component:
                            if color[x] == c:
                                color[x] = k
                            else:
                                color[x] = c
                        # after swap, check if color k is still used
                        if k not in color:
                            mapping = {}
                            next_c = 0
                            for col in sorted(set(color)):
                                mapping[col] = next_c
                                next_c += 1
                            for i in range(n):
                                color[i] = mapping[color[i]]
                            return color, True
        return color, False
    # Generate candidate colorings
    candidates = []
    # DSATUR
    candidates.append(dsatur())
    # RLF
    candidates.append(rlf())
    # Smallest-last
    candidates.append(smallest_last())
    # Welsh-Powell (degree order)
    candidates.append(greedy_color(sorted(range(n), key=lambda x: -sum(1 for u in range(n) if (bit_adj[x] >> u) & 1))))
    # Select best by number of colors
    best = min(candidates, key=lambda col: len(set(col)))
    # Iterative Kempe reduction
    improved = True
    while improved:
        best, improved = kempe_reduce(best)
    # Validate
    for u in range(n):
        for v in range(n):
            if (bit_adj[u] >> v) & 1 and best[u] == best[v]:
                # fallback to DSATUR if invalid (should not happen)
                return dsatur()
    # Ensure consecutive colors
    mapping = {}
    next_c = 0
    for col in sorted(set(best)):
        mapping[col] = next_c
        next_c += 1
    for i in range(n):
        best[i] = mapping[best[i]]
    return best

