            conflicts = []
            for u in range(n):
                for v in neighbors[u]:
                    if u < v and current[u] == current[v]:
                        conflicts.append(u)
                        conflicts.append(v)
                        break
                if conflicts:
                    break
            if not conflicts:
                # No conflicts, try to reduce colors by recoloring a vertex
                improved = False
                for u in range(n):
                    orig = current[u]
                    used = 0
                    for v in neighbors[u]:
                        if current[v] != -1:
                            used |= (1 << current[v])
                    for c in range(best_k + 1):
                        if c == orig:
