        colors = local_search(colors, max_iter=200)
        k = len(set(colors))
        if k < best_k:
            best_k = k
            best_colors = colors[:]
            if best_k == 1:  # optimal possible
                break

    # Fallback: if no valid coloring found, use DSATUR-like
    if best_colors is None or not is_valid_coloring(best_colors):
