    # Build similarity matrix for non-adjacent vertices
    non_adj_pairs = []
    for u in range(n):
        for v in range(u + 1, n):
            if v not in neighbors[u]:
                # Compute Jaccard similarity
                inter = len(neighbors[u] & neighbors[v])
                union = len(neighbors[u] | neighbors[v])
                sim = inter / union if union > 0 else 0.0
                non_adj_pairs.append((sim, u, v))

    # Sort by similarity descending
    non_adj_pairs.sort(key=lambda x: x[0], reverse=True)

    # Greedy matching: try to pair high-similarity non-adjacent vertices
    used = [False] * n
    pairs = []
    for sim, u, v in non_adj_pairs:
        if not used[u] and not used[v]:
            used[u] = used[v] = True
            pairs.append((u, v))

    # Build initial coloring: each pair gets a color, singles get unique
    coloring = [-1] * n
    color = 0
    for u, v in pairs:
        coloring[u] = color
        coloring[v] = color
        color += 1
    for u in range(n):
        if coloring[u] == -1:
            coloring[u] = color
            color += 1

    # Fix conflicts: if adjacent vertices got same color, reassign
    # We'll use a simple greedy fix per vertex
    for u in range(n):
        if coloring[u] == -1:
            continue
        used_colors = set()
        for v in neighbors[u]:
            if coloring[v] != -1 and coloring[v] == coloring[u]:
                # Conflict: try to recolor u
                neighbor_colors = set()
                for w in neighbors[u]:
                    if coloring[w] != -1:
                        neighbor_colors.add(coloring[w])
                c = 0
                while c in neighbor_colors:
                    c += 1
                coloring[u] = c
                break

    # Ensure validity by greedy re-color if needed
    if not is_valid(coloring):
        # Fallback to greedy with degree order
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        coloring = greedy_color(order)

    k = count_colors(coloring)
    if k < best_k:
        best_k = k
        best_coloring = coloring[:]

    # Strategy 2: DSATUR
    def dsatur():
        coloring = [-1] * n
        saturated = [set() for _ in range(n)]  # colors used by neighbors
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for u in uncolored:
                sat = len(saturated[u])
                if sat > max_sat:
                    max_sat = sat
                    candidates = [u]
                elif sat == max_sat:
                    candidates.append(u)

            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_u = candidates[0]
                for u in candidates:
                    deg_in_uncolored = sum(1 for v in neighbors[u] if v in uncolored)
                    if deg_in_uncolored > max_deg:
                        max_deg = deg_in_uncolored
                        best_u = u
                u = best_u
            else:
                u = candidates[0]

            # Assign smallest available color
            used = saturated[u]
            c = 0
            while c in used:
                c += 1
            coloring[u] = c
            uncolored.remove(u)

            # Update saturation of neighbors
            for v in neighbors[u]:
                if v in uncolored:
                    saturated[v].add(c)

        return coloring

    col2 = dsatur()
    if is_valid(col2):
        k2 = count_colors(col2)
        if k2 < best_k:
            best_k = k2
            best_coloring = col2[:]

    # Strategy 3: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # Find vertex with max degree in G[uncolored]
            max_deg = -1
            start = None
            for u in uncolored:
                deg_in_uncolored = sum(1 for v in neighbors[u] if v in uncolored)
                if deg_in_uncolored > max_deg:
                    max_deg = deg_in_uncolored
                    start = u
            if start is None:
                start = next(iter(uncolored))

            independent_set = {start}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = set()
            W = set()
            for v in uncolored:
                if v == start:
                    continue
                if not any(v in neighbors[u] for u in independent_set):
                    U.add(v)
                else:
                    W.add(v)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_score = -1
                for u in U:
                    score = sum(1 for v in neighbors[u] if v in W)
                    if score > max_score:
                        max_score = score
                        best_u = u
                    elif score == max_score:
                        # Tie-break: min degree in G[U]
                        deg_u = sum(1 for v in neighbors[u] if v in U)
                        deg_best = sum(1 for v in neighbors[best_u] if v in U) if best_u is not None else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break  # should not happen
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for v in neighbors[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)

            # Assign color to all in independent_set
            for u in independent_set:
                coloring[u] = color
            uncolored -= independent_set
            color += 1

        return coloring

    col3 = rlf()
    if is_valid(col3):
        k3 = count_colors(col3)
        if k3 < best_k:
            best_k = k3
            best_coloring = col3[:]

    # Strategy 4: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[u]) for u in range(n)]
        order = []
        # We'll simulate peeling
        # Use bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for u in range(n):
            d = degree[u]
            if d <= max_deg:
                buckets[d].add(u)

        for _ in range(n):
            # Find smallest non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            u = buckets[d].pop()
            order.append(u)
            # Update neighbors
            for v in neighbors[u]:
                if v in remaining:
                    # Remove v from its current bucket
                    old_deg = degree[v]
                    if old_deg <= max_deg and v in buckets[old_deg]:
                        buckets[old_deg].remove(v)
                    degree[v] -= 1
                    new_deg = degree[v]
                    if new_deg <= max_deg:
                        buckets[new_deg].add(v)
            remaining.remove(u)

        # Color in reverse order
        coloring = greedy_color(order[::-1])
        return coloring

    col4 = smallest_last()
    if is_valid(col4):
        k4 = count_colors(col4)
        if k4 < best_k:
            best_k = k4
            best_coloring = col4[:]

    # Ensure consecutive colors
    if best_coloring is not None:
        # Map colors to 0..k-1
        unique_colors = sorted(set(best_coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring if best_coloring is not None else [0] * n

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = adj

    # Convert to bit masks for fast operations
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    def is_valid_coloring(colors):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    def get_color_count(colors):
        return max(colors) + 1 if colors else 0

    def normalize_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with bitmask optimization
    def dsatur():
        colors = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color masks for fast saturation update
        neighbor_color_mask = [0] * n

        # initial ordering by degree
        uncolored = set(range(n))
        # initial vertex: highest degree
        v = max(uncolored, key=lambda x: len(neighbors[x]))
        colors[v] = 0
        uncolored.remove(v)

        # update saturation for neighbors of v
        for u in neighbors[v]:
            if u in uncolored:
                neighbor_color_mask[u] |= (1 << 0)
                saturation[u] = 1

        while uncolored:
            # select vertex with max saturation, break ties by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v]
                deg = sum(1 for u in neighbors[v] if u in uncolored)
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v

            # find smallest available color
            used = neighbor_color_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)

            # update saturation for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    if not (neighbor_color_mask[u] & (1 << c)):
                        neighbor_color_mask[u] |= (1 << c)
                        saturation[u] += 1

        return normalize_colors(colors)

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # build independent set for color_idx
            independent_set = set()
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent_set.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any((bit_adj[u] >> w) & 1 for w in independent_set):
                    W.add(u)
                    U.remove(u)

            while U:
                # select u in U with max neighbors in W
                best_u = -1
                best_w_neighbors = -1
                best_deg_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in W if (bit_adj[u] >> w) & 1)
                    deg_U = sum(1 for nb in neighbors[u] if nb in U)
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and deg_U < best_deg_U) or (w_neighbors == best_w_neighbors and deg_U == best_deg_U and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
                uncolored.remove(v)
            color_idx += 1

        return normalize_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]

        # bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)

        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degrees[u]
                    buckets[d].remove(u)
                    degrees[u] -= 1
                    buckets[degrees[u]].append(u)
                    if degrees[u] < min_deg:
                        min_deg = degrees[u]

        # color in reverse order using first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

        return normalize_colors(colors)

    # Kempe chain swap for (a,b)
    def kempe_swap(colors, a, b, vertex):
        # returns new colors after swapping a and b in the component containing vertex
        # only if vertex has color a or b
        if colors[vertex] not in (a, b):
            return colors
        stack = [vertex]
        visited = set()
        comp_color = colors[vertex]
        other_color = b if comp_color == a else a
        while stack:
            v = stack.pop()
            if v in visited:
                continue
            visited.add(v)
            # swap color
            colors[v] = other_color if colors[v] == comp_color else comp_color
            for u in neighbors[v]:
                if u not in visited and colors[u] in (a, b):
                    stack.append(u)
        return colors

    # Try to eliminate the last color using Kempe chains
    def reduce_colors(colors):
        k = get_color_count(colors)
        if k <= 1:
            return colors

        # Try to eliminate color k-1
        target_color = k - 1
        vertices_target = [i for i in range(n) if colors[i] == target_color]

        # First, try direct reassignment
        for v in vertices_target:
            used = 0
            for u in neighbors[v]:
                if colors[u] != target_color:  # only consider colors < target_color for moving
                    used |= (1 << colors[u])
            # find smallest color < target_color not used
            for c in range(target_color):
                if not (used & (1 << c)):
                    colors[v] = c
                    break
            else:
                continue  # could not move v directly
            # if we moved v, check if target color is now empty
            if target_color not in colors:
                return normalize_colors(colors)

        # If direct reassignment didn't work, try Kempe chains
        # We try to recolor vertices in target_color using swaps with lower colors
        made_progress = True
        while made_progress and target_color in colors:
            made_progress = False
            vertices_target = [i for i in range(n) if colors[i] == target_color]
            for v in vertices_target:
                if colors[v] != target_color:
                    continue
                for c in range(target_color):
                    # Try Kempe swap between target_color and c
                    new_colors = kempe_swap(colors[:], target_color, c, v)
                    if new_colors is not colors:  # swap happened
                        # check if v changed color
                        if new_colors[v] != target_color:
                            colors = new_colors
                            made_progress = True
                            break
                if made_progress:
                    break
            if target_color not in colors:
                return normalize_colors(colors)

        # If still not reduced, return original
        return colors

    # Tabu search for conflict resolution
    def tabu_search(initial_colors, max_steps=50, tabu_tenure=10):
        colors = initial_colors[:]
        n = len(colors)
        # current number of conflicts
        def count_conflicts(cols):
            conflicts = 0
            for u in range(n):
                for v in neighbors[u]:
                    if u < v and cols[u] == cols[v]:
                        conflicts += 1
            return conflicts

        current_conflicts = count_conflicts(colors)
        if current_conflicts == 0:
            return colors

        best_colors = colors[:]
        best_conflicts = current_conflicts

        # tabu list: (vertex, color) -> time when it becomes available
        tabu = {}

        for step in range(max_steps):
            # find a conflicting vertex
            conflicting_vertices = []
            for u in range(n):
                for v in neighbors[u]:
                    if u < v and colors[u] == colors[v]:
                        conflicting_vertices.append(u)
                        conflicting_vertices.append(v)
            if not conflicting_vertices:
                break
            v = random.choice(conflicting_vertices)

            # compute color costs: number of conflicts if we change to color c
            color_cost = [0] * n  # n is upper bound on colors needed
            used_by_neighbors = [0] * n
            for u in neighbors[v]:
                if colors[u] < n:
                    used_by_neighbors[colors[u]] = 1

            for c in range(n):
                if used_by_neighbors[c]:
                    color_cost[c] = n  # high cost if causes conflict
                else:
                    # count conflicts that would be resolved by changing to c
                    resolved = 0
                    for u in neighbors[v]:
                        if colors[u] == colors[v]:  # this edge is currently conflicting
                            resolved += 1
                    # also count new conflicts introduced
                    introduced = 0
                    for u in neighbors[v]:
                        if colors[u] == c:
                            introduced += 1
                    color_cost[c] = introduced - resolved  # we want to minimize this (more negative is better)

            # select best non-tabu color
            best_color = -1
            best_cost = float('inf')
            for c in range(n):
                if (v, c) in tabu and tabu[(v, c)] > step:
                    continue
                if color_cost[c] < best_cost:
                    best_cost = color_cost[c]
                    best_color = c

            if best_color == -1:  # all moves tabu, choose best anyway (aspiration)
                best_color = min(range(n), key=lambda c: color_cost[c])

            # make the move
            old_color = colors[v]
            colors[v] = best_color

            # update tabu
            tabu[(v, old_color)] = step + tabu_tenure

            # update conflicts
            current_conflicts = count_conflicts(colors)
            if current_conflicts < best_conflicts:
                best_conflicts = current_conflicts
                best_colors = colors[:]
                if best_conflicts == 0:
                    break

        return normalize_colors(best_colors)

    # Generate candidate colorings
    start_time = time.time()
    candidates = []

    # DSATUR
    c1 = dsatur()
    if is_valid_coloring(c1):
        candidates.append(c1)

    # RLF
    c2 = rlf()
    if is_valid_coloring(c2):
        candidates.append(c2)

    # Smallest-Last
    c3 = smallest_last()
    if is_valid_coloring(c3):
        candidates.append(c3)

    # Select best candidate (fewest colors)
    if not candidates:
        # fallback: greedy ordering by degree
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best = normalize_colors(colors)
    else:
        best = min(candidates, key=get_color_count)

    # Try to reduce colors via Kempe chains
    reduced = reduce_colors(best[:])
    if get_color_count(reduced) < get_color_count(best):
        best = reduced

    # Apply Tabu search to resolve any remaining conflicts (should be few if any)
    if not is_valid_coloring(best):
        best = tabu_search(best, max_steps=50, tabu_tenure=7)

    # Final validation and normalization
    if not is_valid_coloring(best):
        # last resort: greedy with random order
        order = list(range(n))
        random.shuffle(order)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best = normalize_colors(colors)

    # Ensure we use colors 0..k-1
    best = normalize_colors(best)

    return best

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Graph coloring algorithm using a hybrid approach:
    - Order vertices by initial degree (descending)
    - Dynamically adjust effective degree: discount neighbors that are already colored
    - Greedy coloring with smallest available color (first-fit)
    - Kempe chain swaps for color reduction
    """
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        # Validate binary entries
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                neighbors[i].append(j)
                bit_adj[i] |= (1 << j)

    # Initial degree-based ordering
    degrees = [len(neighbors[i]) for i in range(n)]
    order = sorted(range(n), key=lambda i: (-degrees[i], i))

    # Color array, -1 means uncolored
    color = [-1] * n

    # Greedy coloring with dynamic degree discount
    for v in order:
        # Compute used colors among neighbors
        used = 0
        for u in neighbors[v]:
            if color[u] != -1:
                used |= (1 << color[u])
        # Find smallest available color (mex)
        c = 0
        while used & (1 << c):
            c += 1
        color[v] = c

    # Kempe chain color reduction
    def kempe_swap_possible(a, b, v):
        """Check if swapping colors a and b in the Kempe chain of v frees color a for v"""
        if color[v] == b:
            return True
        # BFS to find the (a,b)-Kempe chain containing v
        visited = [False] * n
        stack = [v]
        visited[v] = True
        has_a = (color[v] == a)
        while stack:
            u = stack.pop()
            for w in neighbors[u]:
                if not visited[w] and (color[w] == a or color[w] == b):
                    visited[w] = True
                    stack.append(w)
                    if color[w] == a:
                        has_a = True
        # If the chain does not contain color a, we can swap
        return not has_a

    # Try to reduce colors iteratively
    improved = True
    while improved:
        improved = False
        max_color = max(color) if n > 0 else -1
        if max_color < 0:
            break

        # Try to eliminate the largest color class first (often more effective)
        for target_color in range(max_color, -1, -1):
            # Get vertices with this color
            verts = [i for i in range(n) if color[i] == target_color]
            if not verts:
                continue

            # Try to recolor each vertex
            for v in verts:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    if color[u] != -1:
                        used |= (1 << color[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break

                # Try Kempe swaps with lower colors
                for c in range(target_color):
                    if kempe_swap_possible(c, target_color, v):
                        # Perform the swap: BFS to find component and swap colors
                        visited = [False] * n
                        stack = [v]
                        visited[v] = True
                        while stack:
                            u = stack.pop()
                            if color[u] == target_color:
                                color[u] = c
                            elif color[u] == c:
                                color[u] = target_color
                            for w in neighbors[u]:
                                if not visited[w] and (color[w] == target_color or color[w] == c):
                                    visited[w] = True
                                    stack.append(w)
                        improved = True
                        break
