        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if colors[u] == colors[v]:
                        return False
        return True

    def compact_colors(colors):
        if not colors:
            return colors
        max_color = max(colors)
        mapping = {}
        next_color = 0
        for c in range(max_color + 1):
            if c in colors:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

