        neighbors = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if (bit_adj[u] >> v) & 1:
                    neighbors[u].append(v)

        while not all(colored):
            # Build independent set for current color
            S = []
            U = [i for i in range(n) if not colored[i]]
            W = set()
            if not U:
                break
            # Start with vertex of max degree in U
            deg_in_U = [0] * n
            for u in U:
                for v in neighbors[u]:
                    if not colored[v]:
                        deg_in_U[u] += 1
            v1 = max(U, key=lambda x: deg_in_U[x])
