                       (w_neighbors == best_w_neighbors and deg_u < best_deg_in_U):
                        best_w_neighbors = w_neighbors
                        best_deg_in_U = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # Move neighbors of u in U to W
                for v in neighbors[u]:
                    if not colored[v] and v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color to all in S
            for v in S:
                colors[v] = color
                colored[v] = True
            color += 1
        return compact_colors(colors)

    def smallest_last():
        colors = [-1] * n
        # Compute degeneracy ordering (smallest-last)
        deg = [0] * n
        for i in range(n):
            for j in range(n):
                if (bit_adj[i] >> j) & 1:
                    deg[i] += 1
        # Use buckets for efficiency
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].append(i)
        # Track current degree and position
        current_deg = deg[:]
        pos = list(range(n))
        # Ordering stack
        order = []
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            # Update neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and current_deg[u] > ptr:  # u not removed yet
                    # Remove u from its current bucket
                    if u in buckets[current_deg[u]]:
                        buckets[current_deg[u]].remove(u)
                    current_deg[u] -= 1
                    if current_deg[u] < len(buckets):
                        buckets[current_deg[u]].append(u)
