        for v in reversed(order):
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
