    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append((len(set(c2)), c2))
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append((len(set(c3)), c3))
    except:
        pass

    if not candidates:
        # Fallback: greedy by index
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in range(n):
                if (bit_adj[i] >> j) & 1 and colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best_colors = compact_colors(colors)
    else:
        best_colors = min(candidates, key=lambda x: x[0])[1]

    # Kempe chain-based color reduction
    def eliminate_color_class(colors, target_color):
        # Try to recolor all vertices of target_color to lower colors
        vertices = [i for i in range(n) if colors[i] == target_color]
        if not vertices:
            return True  # Already eliminated
        # Try direct reassignment first
        for v in vertices:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1:
                    used |= (1 << colors[u])
            for c in range(target_color):
                if not (used & (1 << c)):
                    colors[v] = c
                    return True  # Success: recolored one vertex, will retry
        # Try Kempe chains for each vertex
        for v in vertices:
            for c in range(target_color):
                # Check if v can be swapped via Kempe chain (v, target_color) <-> (u, c)
                # Build the Kempe chain component containing v for colors (target_color, c)
                from collections import deque
                visited = [False] * n
                queue = deque([v])
                visited[v] = True
                component = []
                while queue:
                    node = queue.popleft()
                    component.append(node)
                    for nb in range(n):
                        if (bit_adj[node] >> nb) & 1 and not visited[nb]:
                            if colors[nb] == target_color or colors[nb] == c:
                                visited[nb] = True
                                queue.append(nb)
                # Check if any neighbor of the component has color c (would cause conflict if swapped)
                has_conflict = False
                for node in component:
                    for nb in range(n):
                        if (bit_adj[node] >> nb) & 1:
                            if colors[nb] == c and nb not in component:
                                has_conflict = True
                                break
                    if has_conflict:
                        break
                if not has_conflict:
                    # Perform swap: target_color <-> c in component
                    for node in component:
                        if colors[node] == target_color:
                            colors[node] = c
                        elif colors[node] == c:
                            colors[node] = target_color
                    return True
        return False

    # Iteratively try to eliminate the highest color class
    changed = True
    while changed:
        changed = False
        max_color = max(colors) if colors else -1
        for target_color in range(max_color, -1, -1):
            if eliminate_color_class(best_colors, target_color):
                changed = True
                break  # Restart from highest after a change
        if changed:
            best_colors = compact_colors(best_colors)

    # Final validation and compacting
    if not is_valid_coloring(best_colors):
        # Last resort: greedy coloring
        colors = [-1] * n
        for i in range(n):
            used = 0
            for j in range(n):
                if (bit_adj[i] >> j) & 1 and colors[j] != -1:
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best_colors = compact_colors(colors)
    else:
        best_colors = compact_colors(best_colors)

    return best_colors

