def color_graph(adj: list[list[int]]) -> list[int]:
    # Helper: detect and convert to adjacency list
    def to_adj_list(adj):
        n = len(adj)
        if n == 0:
            return []
        if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            return [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
        else:
            return [list(set(nei)) for nei in adj]  # ensure unique neighbors

    adj_list = to_adj_list(adj)
    n = len(adj_list)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = [False] * n
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used[coloring[v]] = True
            for c in range(n):
                if not used[c]:
                    coloring[u] = c
                    break
        return coloring

    # Helper: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Helper: Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        degrees = [len(adj_list[i]) for i in range(n)]
        visited = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for i in range(n):
            if degrees[i] < n:
                buckets[degrees[i]].append(i)
        pos = 0
        for _ in range(n):
            while pos < n and not buckets[pos]:
                pos += 1
            if pos >= n:
                break
            v = buckets[pos].pop()
            if visited[v]:
                continue
            visited[v] = True
            order.append(v)
            for u in adj_list[v]:
                if not visited[u]:
                    d = degrees[u]
                    if d > 0:
                        buckets[d].remove(u)
                        degrees[u] -= 1
                        buckets[degrees[u]].append(u)
        order.reverse()
        return greedy_color(order)

    # Helper: DSATUR
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        saturated = [set() for _ in range(n)]
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored, then index
            cand = -1
            max_sat = -1
            max_deg = -1
            for v in uncolored:
                sat = len(saturated[v])
                deg = uncolored_deg[v]
                if sat > max_sat or (sat == max_sat and (deg > max_deg or (deg == max_deg and v < cand))):
                    max_sat = sat
                    max_deg = deg
                    cand = v
            v = cand
            # assign smallest available color
            used = [False] * n
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            for c in range(n):
                if not used[c]:
                    coloring[v] = c
                    break
            # update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u].add(c)
            uncolored.remove(v)
            # update uncolored degree
            for u in adj_list[v]:
                if u in uncolored:
                    uncolored_deg[u] -= 1
        return coloring

    # Helper: RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S = {v}
            # U: vertices not adjacent to S, W: adjacent to S
            U = {u for u in uncolored if u != v and all(u not in adj_list[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in adj_list[w] for w in S)}
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if nw > max_nw or (nw == max_nw and (deg_u < min_deg_u or (deg_u == min_deg_u and u < u_star))):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for u in S:
                coloring[u] = color
                uncolored.remove(u)
            color += 1
        return coloring

    # Generate candidate colorings
    candidates = []
    candidates.append(welsh_powell())
    candidates.append(smallest_last())
    candidates.append(dsatur())
    candidates.append(rlf())

    # Pick best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    if not is_valid_coloring(best):
        # fallback: simple greedy
        best = greedy_color(list(range(n)))

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest down
        for target_color in range(k-1, 0, -1):
            # get vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # try to recolor each vertex
            changed = True
            while changed and verts:
                changed = False
                v = verts.pop()
                # try direct reassignment to lower color
                for c in range(target_color):
                    if all(coloring[u] != c for u in adj_list[v]):
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # BFS to get Kempe chain of (target_color, c) containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (coloring[y] == target_color or coloring[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # check if swapping is safe: no neighbor of component has color c outside component
                    safe = True
                    for x in component:
                        for y in adj_list[x]:
                            if y not in component and coloring[y] == c:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # perform swap
                        for x in component:
                            coloring[x] = c if coloring[x] == target_color else target_color
                        changed = True
                        break
            # rebuild verts list after changes
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                # target color eliminated, remap colors
                mapping = {}
                new_color = 0
                for old_color in range(k):
                    if any(coloring[v] == old_color for v in range(n)):
                        mapping[old_color] = new_color
                        new_color += 1
                for v in range(n):
                    coloring[v] = mapping[coloring[v]]
                break  # restart reduction with new k
        return coloring

    best = kempe_reduce(best)
    # final validation and compacting
    if not is_valid_coloring(best):
        best = greedy_color(list(range(n)))
    # ensure colors are 0..k-1
    used_colors = set(best)
    mapping = {old: new for new, old in enumerate(sorted(used_colors))]
    best = [mapping[c] for c in best]
    return best

