            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        if not colors:
            return colors
        k = num_colors(colors)
        # try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            # get vertices with target_color
            vertices = [i for i, c in enumerate(colors) if c == target_color]
            if not vertices:
                continue
            changed = True
            # we'll try to recolor these vertices away from target_color
            while changed and vertices:
                changed = False
                new_vertices = []
                for v in vertices:
                    if colors[v] != target_color:  # might have been recolored already
                        continue
                    # try to find a color < target_color that we can assign to v
                    neighbor_colors = 0
                    for u in adj_list[v]:
                        if colors[u] != -1:
                            neighbor_colors |= (1 << colors[u])
