                    for c in range(target_color):
                        if not (neighbor_colors & (1 << c)):
                            colors[v] = c
                            changed = True
                            break
                    if colors[v] == target_color:  # not reassigned directly
                        # try Kempe chains with each color c < target_color
                        for c in range(target_color):
                            if neighbor_colors & (1 << c):
                                # both colors present in neighborhood, check Kempe chain
                                # find the Kempe chain component of v for colors (target_color, c)
                                # but note: v is currently target_color, we want to see if we can swap
                                # Actually, we want to see if in the component of v (color target_color) 
                                # in the subgraph of colors target_color and c, there is no vertex of color c
                                # that would conflict? Standard: if the component of v does not contain 
                                # any vertex of color c that is adjacent to a vertex of color target_color? 
                                # Simpler: if we can swap the component of v (which is color target_color) 
                                # to color c without conflict, i.e., no neighbor of any vertex in the component 
                                # has color c (except those in the component).
                                # We'll do BFS to get the component.
                                from collections import deque
                                comp = []
                                visited = [False] * n
                                q = deque([v])
                                visited[v] = True
                                while q:
                                    node = q.popleft()
                                    comp.append(node)
                                    for nb in adj_list[node]:
                                        if not visited[nb] and (colors[nb] == target_color or colors[nb] == c):
                                            visited[nb] = True
                                            q.append(nb)
                                # check if any vertex in comp has a neighbor with color c (outside comp) 
                                # that would become conflict if we swap? Actually, after swap, 
                                # vertices in comp become color c, so we need to ensure no neighbor 
                                # of any vertex in comp has color c (unless that neighbor is also in comp and will swap)
                                # But if neighbor is in comp, it will also swap to target_color, so no conflict.
