                                for node in comp:
                                    for nb in adj_list[node]:
                                        if not visited[nb] and colors[nb] == c:
                                            can_swap = False
                                            break
                                    if not can_swap:
                                        break
                                if can_swap:
                                    # perform swap
                                    for node in comp:
                                        colors[node] = c if colors[node] == target_color else target_color
                                    changed = True
                                    break  # break out of color loop for this v
                    if colors[v] == target_color:
                        new_vertices.append(v)
                vertices = new_vertices
            # after trying to recolor all vertices of target_color, if none left, we can drop the color
            if not any(colors[i] == target_color for i in range(n)):
                # compact colors above target_color down by one
                for i in range(n):
                    if colors[i] > target_color:
                        colors[i] -= 1
                # break out and restart from new highest color
                return kempe_reduce(colors)
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            k1 = num_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_colors = c1
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
