            if k2 < best_k:
                best_k = k2
                best_colors = c2
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            k3 = num_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_colors = c3
    except:
        pass

    # If none worked, fallback to greedy by degree order
    if best_colors is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    # Apply Kempe chain reduction to try to improve
    try:
        improved = kempe_reduce(best_colors[:])
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_colors = improved
    except:
        pass

    # Final validation and compact
    if not is_valid_coloring(best_colors):
        # last resort: greedy arbitrary order
        colors = [-1] * n
        for v in range(n):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    return best_colors

