                for c in range(target_color):
                    if not (used & (1 << c)):
                        # move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break

                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c due to prior swap, skip
                    if coloring[v] == c:
                        improved = True
                        break
                    # find Kempe chain of (target_color, c) containing v
                    # BFS/DFS over vertices colored target_color or c
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            neighbors = bit_adj[node]
                            w = 0
                            while neighbors:
                                if neighbors & 1:
                                    if w not in visited and (coloring[w] == target_color or coloring[w] == c):
                                        stack.append(w)
                                neighbors >>= 1
                                w += 1
                    # check if swapping this component is safe: no neighbor outside component has color c (for target_color->c) or target_color (for c->target_color)
                    # Actually, we want to swap colors in component: target_color <-> c
                    # After swap, we want no conflict. It is safe if for every node in component,
                    #   none of its neighbors outside component has the color we are switching to.
                    # For nodes currently target_color switching to c: check no neighbor outside has color c.
                    # For nodes currently c switching to target_color: check no neighbor outside has color target_color.
                    safe = True
                    for node in component:
                        neighbors = bit_adj[node]
                        w = 0
                        while neighbors:
                            if neighbors & 1:
                                if w not in component:
                                    if coloring[node] == target_color and coloring[w] == c:
                                        safe = False
                                        break
                                    if coloring[node] == c and coloring[w] == target_color:
                                        safe = False
                                        break
                            neighbors >>= 1
                            w += 1
                        if not safe:
                            break
                    if safe:
                        # perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        improved = True
                        break
                if improved:
                    break

            if improved:
                # compact colors
                mapping = {c: i for i, c in enumerate(sorted(set(coloring)))}
                coloring = [mapping[c] for c in coloring]
                k = num_colors(coloring)
            else:
                break

        return coloring

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    for heuristic in [dsatur, rlf, smallest_last]:
        try:
            coloring = heuristic()
            if not is_valid(coloring):
                continue
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring
        except Exception:
            continue

    # Fallback: greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count("1"), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            neighbors = bit_adj[v]
            u = 0
            while neighbors:
                if neighbors & 1:
                    if color[u] != -1:
                        used |= (1 << color[u])
                neighbors >>= 1
                u += 1
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = normalize(color)

    # Final Kempe reduction
    try:
        best_coloring = kempe_reduce(best_coloring)
        if not is_valid(best_coloring):
            # if Kempe broke it, fall back to best before Kempe
            pass
    except Exception:
        pass

    # Ensure zero-based consecutive
    best_coloring = normalize(best_coloring)

    return best_coloring

