def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)

    # Ensure symmetry for undirected graph (if not already)
    for u in range(n):
        for v in adj_list[u]:
            if u not in adj_list[v]:
                adj_list[v].append(u)
                bit_adj[v] |= (1 << u)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: count distinct colors
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: convert to zero-based consecutive colors
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR algorithm
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbor masks for fast saturation update
        colored_masks = [0] * n

        # order: list of uncolored vertices
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, break ties by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v]
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # compute forbidden colors from neighbors
            forbidden = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    forbidden |= (1 << coloring[u])
            # find smallest color not forbidden
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # update saturation and colored_masks for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    colored_masks[u] |= (1 << c)
                    # count bits in colored_masks[u] -> saturation[u]
                    saturation[u] = colored_masks[u].bit_count()
        return coloring

    # RLF algorithm
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S.add(v)
            # partition U and W
            U = uncolored - {v}
            W = set()
            for u in adj_list[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # while U not empty
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for y in adj_list[u] if y in W)
                    deg_u = sum(1 for y in adj_list[u] if y in U)
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or (w_neighbors == best_w_neighbors and deg_u == best_deg_u and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for y in adj_list[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # assign color to all in S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
        return coloring

    # Smallest-Last (Matula & Beck) greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # we will remove min degree vertex each time
        temp_degree = degree[:]
        remaining_set = set(range(n))
        for _ in range(n):
            # find vertex with min degree in remaining
            v = min(remaining_set, key=lambda x: temp_degree[x])
            order.append(v)
            remaining_set.remove(v)
            for u in adj_list[v]:
                if u in remaining_set:
                    temp_degree[u] -= 1
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            forbidden = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    forbidden |= (1 << coloring[u])
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain elimination to reduce colors
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            # fallback: should not happen if input coloring is valid
            return coloring
        k = count_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate colors from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # vertices with target_color
            targets = [i for i in range(n) if coloring[i] == target_color]
            if not targets:
                # already empty, compact
                for i in range(n):
                    if coloring[i] > target_color:
                        coloring[i] -= 1
                k -= 1
                changed = True
                continue
            # try to recolor each target vertex
            for v in targets:
                # try direct reassignment to a lower color
                forbidden = 0
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        forbidden |= (1 << coloring[u])
                for c in range(target_color):
                    if not (forbidden & (1 << c)):
                        # can recolor directly
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    # after recoloring v, check if target_color is now empty
                    if target_color not in coloring:
                        # compact colors
                        for i in range(n):
                            if coloring[i] > target_color:
                                coloring[i] -= 1
                        k -= 1
                    break  # restart outer while loop
                # try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # if v already has color c, skip (shouldn't happen)
                    if coloring[v] == c:
                        continue
                    # find Kempe chain for (target_color, c) containing v
                    # BFS/DFS over vertices with color target_color or c
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for nb in adj_list[node]:
                                if nb not in visited and (coloring[nb] == target_color or coloring[nb] == c):
                                    stack.append(nb)
                    # check if any neighbor of v in the component has color c? Actually, we want to see if we can swap
                    # After swap, v would get color c. We need to ensure no neighbor of v has color c after swap.
                    # But if we swap the component, neighbors of v that are in the component and had color c will become target_color.
                    # So we need that no neighbor of v outside the component has color c.
                    conflict = False
                    for nb in adj_list[v]:
                        if nb not in component and coloring[nb] == c:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap: target_color <-> c in component
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:  # must be c
                                coloring[node] = target_color
                        changed = True
                        # after swap, check if target_color is eliminated
                        if target_color not in coloring:
                            for i in range(n):
                                if coloring[i] > target_color:
                                    coloring[i] -= 1
                            k -= 1
                        break
                if changed:
                    break
        return coloring

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        coloring = func()
        if not is_valid(coloring):
            # repair: simple greedy fix
            coloring = [-1] * n
            for v in range(n):
                forbidden = 0
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        forbidden |= (1 << coloring[u])
                c = 0
                while forbidden & (1 << c):
                    c += 1
                coloring[v] = c
        coloring = normalize(coloring)
        k = count_colors(coloring)
        if k < best_k or (k == best_k and best_coloring is None):
            best_k = k
            best_coloring = coloring[:]

    # Apply Kempe reduction to best
    if best_coloring is not None:
        best_coloring = kempe_reduce(best_coloring[:])
        best_coloring = normalize(best_coloring)

    # Final validation (should be valid)
    if not is_valid(best_coloring):
        # last resort: greedy ordering by degree
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            forbidden = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    forbidden |= (1 << coloring[u])
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    return best_coloring

