    n = len(adj)
    # Detect adjacency matrix vs list
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
    else:
        # adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                bit_adj[u] |= (1 << v)

    def greedy_coloring(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Heuristic 1: DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], sum(1 for u in range(n) if (bit_adj[x] >> u) & 1 and u in uncolored)))
            # compute used colors from colored neighbors
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] == -1:
                    sat[u] += 1
        return color

    # Heuristic 2: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in range(n) if (bit_adj[x] >> u) & 1 and u in uncolored))
            S = {v}
            U = uncolored - {v}
            W = set()
            # initial partition
            for u in U:
                if any((bit_adj[w] >> u) & 1 for w in S):
                    W.add(u)
                else:
                    # u remains in U
                    pass
            # Actually, better to recompute U and W from scratch each iteration
            # Let's do it properly: U = vertices not adjacent to any in S
            # W = vertices adjacent to at least one in S
            while True:
                U = {u for u in uncolored if u not in S and not any((bit_adj[w] >> u) & 1 for w in S)}
                W = uncolored - S - U
                if not U:
                    break
                # select u in U with max |N(u) ∩ W|
                u_star = max(U, key=lambda x: sum(1 for w in range(n) if (bit_adj[x] >> w) & 1 and w in W))
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for w in range(n):
                    if (bit_adj[u_star] >> w) & 1 and w in U:
                        U.remove(w)
                        W.add(w)
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Heuristic 3: Smallest-Last (Matula & Beck) ordering + greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [0] * n
        for v in range(n):
            degrees[v] = sum(1 for u in range(n) if (bit_adj[v] >> u) & 1)
        while remaining:
            v = min(remaining, key=lambda x: degrees[x])
            order.append(v)
            remaining.remove(v)
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    degrees[u] -= 1
        # color in reverse order
        return greedy_coloring(order[::-1])

    # Heuristic 4: Welsh-Powell (degree descending) + greedy
    def welsh_powell():
        order = sorted(range(n), key=lambda x: sum(1 for u in range(n) if (bit_adj[x] >> u) & 1), reverse=True)
        return greedy_coloring(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            # validate
            valid = True
            for u in range(n):
                for v in range(u+1, n):
                    if (bit_adj[u] >> v) & 1 and col[u] == col[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                candidates.append(col)
        except Exception:
            pass

    if not candidates:
        # fallback: trivial coloring (each vertex unique)
        candidates.append(list(range(n)))

    # select candidate with minimal number of colors
    best = min(candidates, key=lambda c: max(c) + 1 if c else 0)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make consecutive colors
        def renorm(col):
            mapping = {}
            next_c = 0
            for v in range(n):
                if col[v] not in mapping:
                    mapping[col[v]] = next_c
                    next_c += 1
                col[v] = mapping[col[v]]
            return col

        coloring = renorm(coloring[:])
        k = max(coloring) + 1 if n > 0 else 0
        improved = True
        while improved and k > 1:
            improved = False
            # target smallest color class (color k-1)
            target_color = k - 1
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                k -= 1
                continue
            # try to recolor each vertex in target class
            for v in vertices:
                # try direct reassignment to a lower color
                neighbor_colors = set()
                for u in range(n):
                    if (bit_adj[v] >> u) & 1:
                        neighbor_colors.add(coloring[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already recolored, break
                    if coloring[v] != target_color:
                        break
                # Build components of colors {c, target_color}
                    visited = [False] * n
                    from collections import deque
                    for start in range(n):
                        if coloring[start] in (c, target_color) and not visited[start]:
                            comp = []
                            q = deque([start])
                            visited[start] = True
                            while q:
                                x = q.popleft()
                                comp.append(x)
                                for y in range(n):
                                    if (bit_adj[x] >> y) & 1 and not visited[y] and coloring[y] in (c, target_color):
                                        visited[y] = True
                                        q.append(y)
                            # check if v in this component
                            if v in comp:
                                # check if any vertex in comp colored c has a neighbor not in {c, target_color} that is colored target_color? 
                                # Actually, swapping is safe if no vertex in comp colored c is adjacent to a vertex colored target_color outside comp? 
                                # Standard Kempe swap: swapping colors in a component preserves validity.
                                # We want to free color target_color for v by swapping c and target_color in comp containing v.
                                # After swap, v will be colored c (if it was target_color) and we free target_color.
                                # But we must ensure that after swap, no two adjacent vertices have same color.
                                # Swapping within a component is always safe.
                                # So we can swap and break.
                                for x in comp:
                                    if coloring[x] == c:
                                        coloring[x] = target_color
                                    else:
                                        coloring[x] = c
                                improved = True
                                break
                    if improved:
                        break
            if improved:
                coloring = renorm(coloring)
                k = max(coloring) + 1
            else:
                # cannot reduce further
                break
        return coloring

    best = kempe_reduce(best)
    # final validation (should be valid)
    for u in range(n):
        for v in range(u+1, n):
            if (bit_adj[u] >> v) & 1 and best[u] == best[v]:
                # fallback to greedy on original order if something went wrong
                return greedy_coloring(list(range(n)))
    return best

