        # degrees in the uncolored subgraph (initially full degree)
        degree = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if colors[i] == -1:
                    sat = len(saturation[i])
                    if sat > max_sat or (sat == max_sat and degree[i] > max_deg) or \
                       (sat == max_sat and degree[i] == max_deg and (v == -1 or random.random() < 0.5)):
                        max_sat = sat
                        max_deg = degree[i]
                        v = i
            if v == -1:
                break  # should not happen

            # Find smallest available color
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c

            # Update saturation and degree for uncolored neighbors
            for u in adj_list[v]:
                if colors[u] == -1:
                    saturation[u].add(c)
                    degree[u] -= 1

        return normalize(colors)

    # RLF heuristic
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for this color
            # degree in the uncolored subgraph
            deg = {}
            for v in uncolored:
                deg[v] = sum(1 for u in adj_list[v] if u in uncolored)

            S = set()
            # Start with vertex of max degree in uncolored
            v = max(uncolored, key=lambda x: deg[x]) if uncolored else None
            if v is None:
                break
            S.add(v)
            uncolored.remove(v)

            # Partition: U (not adjacent to S), W (adjacent to S)
            U = {u for u in uncolored if not any(u in adj_list[w] for w in S)}
            W = uncolored - U

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = None
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if (w_neighbors > max_w_neighbors or 
                        (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or
                        (w_neighbors == max_w_neighbors and deg_u == min_deg_u and (best_u is None or random.random() < 0.5))):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                if best_u is None:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
            uncolored = W  # for next color, only consider vertices adjacent to current S

        return normalize(colors)

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # Core decomposition to get ordering
        deg = [len(adj_list[i]) for i in range(n)]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg[v]
            if d < len(buckets):
                buckets[d].append(v)
            else:
                # extend buckets if needed (should not happen with max_deg)
                while len(buckets) <= d:
                    buckets.append([])
                buckets[d].append(v)

        # pointer to current non-empty bucket
        ptr = 0
        order = []
        # copy of degrees for modification
        curr_deg = deg[:]
        # visited flag
        removed = [False] * n

        for _ in range(n):
            # find next non-empty bucket
            while ptr < len(buckets) and not buckets[ptr]:
                ptr += 1
            if ptr >= len(buckets):
                break  # should not happen
            v = buckets[ptr].pop()
            while removed[v]:
                if not buckets[ptr]:
                    ptr += 1
                    while ptr < len(buckets) and not buckets[ptr]:
                        ptr += 1
                    if ptr >= len(buckets):
                        break
                    v = buckets[ptr].pop()
                else:
                    break
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    # remove u from bucket d
                    if d < len(buckets) and u in buckets[d]:
                        buckets[d].remove(u)
                    curr_deg[u] -= 1
                    d_new = curr_deg[u]
                    if d_new < len(buckets):
                        buckets[d_new].append(u)
                    else:
                        while len(buckets) <= d_new:
                            buckets.append([])
                        buckets[d_new].append(u)

        # color in reverse order using first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c

        return normalize(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        if not colors:
            return colors
        k = count_colors(colors)
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            # Get vertices with target_color
            vertices = [v for v in range(n) if colors[v] == target_color]
            if not vertices:
                continue

            # Try to recolor each vertex in this class
            made_change = False
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if colors[u] != -1:
                        neighbor_colors.add(colors[u])
                for c in range(target_color):  # only try colors < target_color
                    if c not in neighbor_colors:
                        colors[v] = c
                        made_change = True
                        break
                if made_change:
                    break

                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue  # skip if neighbor already has color c (would cause conflict after swap?)
                    # We consider swapping colors target_color and c in the component containing v
                    # Only if v is not adjacent to any vertex of color c (to avoid immediate conflict)
                    # Actually, we can allow adjacency as long as after swap it's still valid? 
                    # Standard Kempe: swap in a component, v will get color c, so we need that no neighbor of v has color c after swap.
                    # Before swap, neighbors of v have colors: some target_color, some c, others.
                    # After swap: neighbors that were target_color become c, and neighbors that were c become target_color.
                    # So for v to be valid after swap: 
                    #   - neighbors that were target_color: become c -> but v becomes c, so conflict if any neighbor was target_color? 
                    #   Actually, after swap, v becomes c, and any neighbor that was target_color becomes c -> conflict.
                    # Therefore, we can only swap if v has no neighbor of color target_color? 
                    # But v is color target_color, and by validity, no neighbor has color target_color. 
                    # So neighbors of v cannot have color target_color. 
                    # After swap: 
                    #   v: target_color -> c
                    #   neighbors: 
                    #       if they were target_color -> become c -> but there are none (since v had no neighbor of target_color)
                    #       if they were c -> become target_color
                    #       others unchanged.
                    # So the only potential conflict is if a neighbor of v was color c and becomes target_color, and v becomes c -> no conflict (different colors).
                    # And if a neighbor was color c and becomes target_color, and v becomes c -> still different.
                    # However, if there is a neighbor u of v that is color c, and we swap the component, then u becomes target_color and v becomes c -> still valid.
                    # The issue is: if we swap a component that includes v and some other vertices, we must ensure that for every edge, the two endpoints have different colors after swap.
                    # The swap preserves validity of the coloring because it's a color permutation on a connected component of the subgraph induced by the two colors.
                    # Therefore, we can safely swap any Kempe chain (component) of colors {target_color, c}.
                    # But note: if we swap a component that does not contain v, it doesn't help v.
                    # So we want to swap the component of v in the graph induced by colors {target_color, c} to try to change v's color to c.
                    # After swap, v will have color c (if it was target_color) or target_color (if it was c). Since v is target_color, it becomes c.
                    # And the coloring remains valid.
                    # So we can proceed.

                    # Build the Kempe chain component containing v for colors {target_color, c}
                    # We'll do BFS/DFS over vertices that are either target_color or c and connected by edges.
                    from collections import deque
                    comp = set()
                    queue = deque([v])
                    comp.add(v)
                    while queue:
                        x = queue.popleft()
                        for y in adj_list[x]:
                            if y not in comp and (colors[y] == target_color or colors[y] == c):
                                comp.add(y)
                                queue.append(y)

                    # Perform swap: target_color <-> c in the component
                    made_change = True
                    for x in comp:
                        if colors[x] == target_color:
                            colors[x] = c
                        elif colors[x] == c:
                            colors[x] = target_color
                    break  # break from color loop after making a change
                if made_change:
                    break  # break from vertex loop after making a change
            if not made_change:
                # Could not recolor any vertex in this color class, move to next (lower) target color
                continue
            else:
                # Made a change, restart the reduction process from the highest color
                # because the number of colors might have reduced or the structure changed
                return kempe_reduce(colors)
        # If we couldn't eliminate any color class, return current coloring
        return normalize(colors)

    # Run all heuristics with time budgeting
    start_time = time.time()
    time_limit = 0.05  # 50 ms

    best_colors = None
    best_k = float('inf')

    # Helper to try a heuristic and update best
    def try_heuristic(heuristic_func, name):
        nonlocal best_colors, best_k
        if time.time() - start_time >= time_limit:
            return
        colors = heuristic_func()
        if not is_valid(colors):
            # Fallback: should not happen, but if so, try to fix by greedy
            colors = [-1] * n
            for v in range(n):
                used = set()
                for u in adj_list[v]:
                    if colors[u] != -1:
                        used.add(colors[u])
                c = 0
                while c in used:
                    c += 1
                colors[v] = c
            colors = normalize(colors)
        k = count_colors(colors)
        if k < best_k:
            best_k = k
            best_colors = colors[:]

    # Run heuristics in order
    try_heuristic(dsatur, "DSATUR")
    if time.time() - start_time < time_limit:
        try_heuristic(rlf, "RLF")
    if time.time() - start_time < time_limit:
        try_heuristic(smallest_last, "Smallest-Last")

    # Apply Kempe reduction if time permits
    if time.time() - start_time < time_limit and best_colors is not None:
        reduced = kempe_reduce(best_colors[:])
        if is_valid(reduced):
            k_reduced = count_colors(reduced)
            if k_reduced < best_k:
                best_k = k_reduced
                best_colors = reduced

    # Fallback: if no heuristic produced a coloring (should not happen), use greedy
    if best_colors is None:
        colors = [-1] * n
        for v in range(n):
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        best_colors = normalize(colors)

    return best_colors

