def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if binary matrix
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor list and bitmask adjacency
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)

    # Ensure undirected (symmetrize if needed)
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)
                bit_adj[j] |= (1 << i)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with bitmask
    def dsatur():
        color = [-1] * n
        colored = [False] * n
        saturation = [0] * n  # bitmask of colors used by neighbors
        deg = [len(neighbors[i]) for i in range(n)]
        uncolored_count = n

        for _ in range(n):
            # Select vertex: max saturation, then max degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                sat = saturation[v].bit_count()
                # degree in uncolored subgraph
                deg_uncolored = 0
                for u in neighbors[v]:
                    if not colored[u]:
                        deg_uncolored += 1
                if sat > best_sat or (sat == best_sat and deg_uncolored > best_deg) or \
                   (sat == best_sat and deg_uncolored == best_deg and (best_v == -1 or random.random() < 0.5)):
                    best_sat = sat
                    best_deg = deg_uncolored
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            colored[v] = True
            uncolored_count -= 1
            # Update saturation of neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    saturation[u] |= (1 << c)
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        colored = [False] * n
        current_color = 0
        uncolored_set = set(range(n))

        while uncolored_set:
            # Build maximal independent set for current_color
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored_set:
                break
            # Find vertex in uncolored_set with max degree in G[uncolored_set]
            v = max(uncolored_set, key=lambda x: sum(1 for u in neighbors[x] if u in uncolored_set))
            independent_set = {v}
            to_remove = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = {u for u in uncolored_set if u != v and v not in neighbors[u]}
            W = {u for u in uncolored_set if u != v and v in neighbors[u]}

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    deg_U = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or \
                       (score == best_score and deg_U == best_deg_U and (best_u == -1 or random.random() < 0.5)):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                independent_set.add(u)
                to_remove.add(u)
                # Move u from U to independent_set, and update U, W
                U.remove(u)
                # Neighbors of u that are in U move to W
                for w in list(U):  # iterate over copy
                    if w in neighbors[u]:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent_set
            for v in independent_set:
                color[v] = current_color
                colored[v] = True
                uncolored_set.remove(v)
            current_color += 1
        return color

    # Strategy 3: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            # Find unremoved vertex with minimum degree
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break  # should not happen
            order.append(v)
            removed[v] = True
            # Decrease degree of neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    deg[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Run all strategies and collect valid colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            coloring = func()
            if is_valid(coloring):
                candidates.append(coloring)
        except Exception:
            continue

    # If no candidate (should not happen), fall back to simple greedy
    if not candidates:
        coloring = greedy_color(list(range(n)))
        if is_valid(coloring):
            candidates.append(coloring)
        else:
            # Last resort: assign each vertex a unique color
            coloring = list(range(n))
            candidates.append(coloring)

    # Select candidate with fewest colors
    best = min(candidates, key=count_colors)
    k = count_colors(best)

    # Kempe chain-based color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color to lower colors
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return coloring, True  # already eliminated
        # We'll try to reassign each vertex
        new_coloring = coloring[:]
        # Try direct reassignment first
        for v in vertices:
            used = 0
            for u in neighbors[v]:
                c = new_coloring[u]
                if c != -1:
                    used |= (1 << c)
            # Try colors < target_color
            for c in range(target_color):
                if not (used & (1 << c)):
                    new_coloring[v] = c
                    break
            else:
                # Could not assign directly, try Kempe chains
                found = False
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (target_color, c)
                    # We'll try to find a Kempe chain starting from v that does not include
                    # any other vertex of target_color that would be pulled in
                    # Simple approach: BFS for (target_color, c) component containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in neighbors[node]:
                            if not visited[nb] and (new_coloring[nb] == target_color or new_coloring[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any other target_color vertex is in this component
                    has_other_target = any(new_coloring[node] == target_color and node != v for node in component)
                    if not has_other_target:
                        # Swap colors in component
                        for node in component:
                            if new_coloring[node] == target_color:
                                new_coloring[node] = c
                            elif new_coloring[node] == c:
                                new_coloring[node] = target_color
                        found = True
                        break
                if not found:
                    # Cannot eliminate this vertex, abort
                    return None, False
        return new_coloring, True

    # Iteratively try to reduce colors
    improved = True
    while improved and k > 0:
        improved = False
        # Try to eliminate the highest color class (k-1)
        target = k - 1
        new_coloring, success = eliminate_color_class(best, target)
        if success and is_valid(new_coloring):
            # Compact colors: remap to 0..new_k-1
            color_map = {}
            next_color = 0
            for v in range(n):
                c = new_coloring[v]
                if c not in color_map:
                    color_map[c] = next_color
                    next_color += 1
            compacted = [color_map[c] for c in new_coloring]
            if is_valid(compacted):
                best = compacted
                k = next_color
                improved = True
        # If not successful, break
        if not improved:
            break

    return best

