    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if it's a binary matrix (0/1)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Degeneracy ordering (smallest-last)
    current_deg = [len(adj_list[i]) for i in range(n)]
    removed = [False] * n
    order = []

    # Use a list of buckets for efficiency (degree <= n-1)
    max_deg = n - 1
    buckets = [[] for _ in range(max_deg + 1)]
    for i in range(n):
        d = current_deg[i]
        if d <= max_deg:
            buckets[d].append(i)

    # Pointer to current minimum non-empty bucket
    min_deg = 0
    for _ in range(n):
        # Find the next non-empty bucket
        while min_deg <= max_deg and not buckets[min_deg]:
            min_deg += 1
        if min_deg > max_deg:
            break  # Should not happen

        # Get a vertex from the bucket
        v = buckets[min_deg].pop()
        if removed[v]:
            continue  # Skip if already removed (can happen due to lazy updates)

        removed[v] = True
        order.append(v)

        # Update neighbors
        for u in adj_list[v]:
            if not removed[u]:
                d_u = current_deg[u]
                # Remove u from its current bucket
                if d_u <= max_deg:
                    # We'll add it to the new bucket later; for now, just mark for update
                    pass
                current_deg[u] = d_u - 1
                new_d = current_deg[u]
                if new_d <= max_deg:
                    buckets[new_d].append(u)

        # Adjust min_deg if necessary (the bucket we just used might be empty now)
        # But we will find it in the next iteration's while loop

    # Reverse the order for coloring
    order.reverse()

    # Greedy coloring in the computed order
    color = [-1] * n
    for v in order:
        # Find the smallest color not used by neighbors
        neighbor_colors = 0
        for u in adj_list[v]:
            c = color[u]
            if c != -1:
                neighbor_colors |= (1 << c)
        # Find the first zero bit in neighbor_colors
        c = 0
        while neighbor_colors & (1 << c):
            c += 1
        color[v] = c

    return color

