def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = (len(adj) > 0 and len(adj[0]) == n and
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    if is_matrix:
        # Convert matrix to adjacency list for uniform processing
        adj_list = []
        for i in range(n):
            neighbors = [j for j in range(n) if adj[i][j] == 1 and i != j]
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        used_colors = [0] * n  # Track used colors for each vertex
        max_color = 0
        for u in order:
            # Find forbidden colors from neighbors
            forbidden = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    forbidden |= (1 << color[v])
            # Find first free color
            c = 0
            while forbidden & (1 << c):
                c += 1
            color[u] = c
            if c > max_color:
                max_color = c
        return color[:max_color+1]  # Trim to actual used colors

    # Helper: count colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        # Precompute degrees
        degrees = [len(adj_list[u]) for u in range(n)]

        while uncolored:
            # Find vertex with max saturation degree
            max_sat = -1
            candidates = []
            for u in uncolored:
                # Compute saturation degree: distinct colors in neighbors
                neighbor_colors = set()
                for v in adj_list[u]:
                    if color[v] != -1:
                        neighbor_colors.add(color[v])
                sat = len(neighbor_colors)
                if sat > max_sat:
                    max_sat = sat
                    candidates = [u]
                elif sat == max_sat:
                    candidates.append(u)

            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_u = candidates[0]
                for u in candidates:
                    # Count uncolored neighbors
                    deg_uncolored = sum(1 for v in adj_list[u] if v in uncolored)
                    if deg_uncolored > max_deg:
                        max_deg = deg_uncolored
                        best_u = u
                    elif deg_uncolored == max_deg and u < best_u:
                        best_u = u
                u = best_u
            else:
                u = candidates[0]

            # Assign smallest available color
            neighbor_colors = set()
            for v in adj_list[u]:
                if color[v] != -1:
                    neighbor_colors.add(color[v])
            c = 0
            while c in neighbor_colors:
                c += 1
            color[u] = c
            uncolored.remove(u)

        return color

    # Strategy 2: Recursive Largest First (RLF) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build independent set for current color
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                max_deg = -1
                start_v = None
                for u in uncolored:
                    deg = sum(1 for v in adj_list[u] if v in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        start_v = u
                    elif deg == max_deg and u < start_v:
                        start_v = u
                independent_set.add(start_v)
                # Partition: U = vertices not adjacent to any in S, W = adjacent to S
                U = set(uncolored) - {start_v}
                W = set()
                for v in adj_list[start_v]:
                    if v in U:
                        W.add(v)
                        U.remove(v)

                # Greedily add to independent set
                while U:
                    # Select u in U with max neighbors in W
                    best_u = None
                    max_w_neighbors = -1
                    for u in U:
                        w_neighbors = sum(1 for v in adj_list[u] if v in W)
                        if w_neighbors > max_w_neighbors:
                            max_w_neighbors = w_neighbors
                            best_u = u
                        elif w_neighbors == max_w_neighbors:
                            # Tie-break: min degree in U
                            deg_u = sum(1 for v in adj_list[u] if v in U)
                            deg_best = sum(1 for v in adj_list[best_u] if v in U) if best_u is not None else float('inf')
                            if deg_u < deg_best or (deg_u == deg_best and u < best_u):
                                best_u = u
                    # Add best_u to independent set
                    independent_set.add(best_u)
                    U.remove(best_u)
                    # Move neighbors of best_u from U to W
                    for v in adj_list[best_u]:
                        if v in U:
                            W.add(v)
                            U.remove(v)

            # Assign color to independent set
            for u in independent_set:
                color[u] = current_color
                uncolored.remove(u)
            current_color += 1

        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        degrees = [len(adj_list[u]) for u in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degrees[u]].append(u)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # Should not happen
            u = buckets[ptr].pop()
            order.append(u)
            remaining.remove(u)
            # Decrease degree of neighbors
            for v in adj_list[u]:
                if v in remaining:
                    d = degrees[v]
                    buckets[d].remove(v)
                    degrees[v] -= 1
                    if degrees[v] >= 0:
                        buckets[degrees[v]].append(v)
                    else:
                        degrees[v] = 0  # Should not go negative

        # Color in reverse order (largest last first)
        return greedy_color(list(reversed(order)))

    # Strategy 4: Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
        return greedy_color(order)

    # Generate initial candidates
    candidates = []
    start_time = time.time()

    # Time budget: 45ms for algorithms, 5ms for Kempe
    time_budget = 0.045

    # DSATUR
    if time.time() - start_time < time_budget:
        col = dsatur()
        if is_valid(col):
