from collections import deque

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Handle single vertex
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list if needed
    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj

    # Ensure graph is undirected and no self-loops
    for u in range(n):
        # Remove self-loops
        graph[u] = [v for v in graph[u] if v != u]
        # Ensure symmetry (if not already)
        for v in graph[u]:
            if u not in graph[v]:
                graph[v].append(u)

    # Remove duplicate neighbors
    for u in range(n):
        graph[u] = list(set(graph[u]))

    # If no edges, all vertices can be color 0
    if all(len(graph[u]) == 0 for u in range(n)):
        return [0] * n

    # Step 1: Try to 2-color the graph using BFS (for bipartite components)
    color = [-1] * n
    is_bipartite = True
    components = []
    visited = [False] * n

    for i in range(n):
        if not visited[i]:
            # BFS for this component
            comp_vertices = []
            queue = deque([i])
            visited[i] = True
            color[i] = 0
            comp_vertices.append(i)
            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        color[v] = color[u] ^ 1
                        queue.append(v)
                        comp_vertices.append(v)
                    else:
                        if color[v] == color[u]:
                            is_bipartite = False
            components.append(comp_vertices)

    # If the graph is bipartite, we are done
    if is_bipartite:
        return color

    # Step 2: For non-bipartite graphs, we need more than 2 colors.
    # We will use DSATUR as a baseline, then try to improve.

    # Precompute adjacency as bit masks for efficiency (only if n <= 64, else use sets)
    use_bitmask = n <= 64
    if use_bitmask:
        bit_adj = [0] * n
        for u in range(n):
            mask = 0
            for v in graph[u]:
                mask |= (1 << v)
            bit_adj[u] = mask

    # Helper function to get neighbors as set or bitmask
    def get_neighbors(u):
        if use_bitmask:
            return bit_adj[u]
        else:
            return set(graph[u])

    # DSATUR implementation
    def dsatur():
        # Initialize
        colors = [-1] * n
        # saturation: list of sets of neighbor colors for each vertex
        saturation = [set() for _ in range(n)]
        # degrees in the uncolored subgraph (initially full degree)
        deg = [len(graph[u]) for u in range(n)]
        colored = [False] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation degree, tie-break by degree, then random
            max_sat = -1
            candidates = []
            for u in range(n):
                if not colored[u]:
                    sat = len(saturation[u])
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [u]
                    elif sat == max_sat:
                        candidates.append(u)

            # Tie-break by degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                deg_candidates = []
                for u in candidates:
                    if deg[u] > max_deg:
                        max_deg = deg[u]
                        deg_candidates = [u]
                    elif deg[u] == max_deg:
                        deg_candidates.append(u)
                candidates = deg_candidates

            # Final tie-break randomly
            u = random.choice(candidates) if candidates else 0

            # Find smallest available color
            used = saturation[u]
            c = 0
            while c in used:
                c += 1
            colors[u] = c
            colored[u] = True

            # Update saturation and degree for neighbors
            for v in graph[u]:
                if not colored[v]:
                    saturation[v].add(c)
                    deg[v] -= 1  # one less uncolored neighbor

        return colors

    # RLF implementation (Largest First Independent Set)
    def rlf():
        colors = [-1] * n
        colored = [False] * n
        color_idx = 0

        while not all(colored):
            # Step 1: Find uncolored vertex with max degree in uncolored subgraph
            max_deg = -1
            start = -1
            for u in range(n):
                if not colored[u]:
                    # Compute current degree in uncolored subgraph
                    d = 0
                    for v in graph[u]:
                        if not colored[v]:
                            d += 1
                    if d > max_deg:
                        max_deg = d
                        start = u
            if start == -1:  # should not happen
                break

            # Initialize independent set for this color
            S = [start]
            colored[start] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = []
            W = set()
            for v in range(n):
                if not colored[v] and v != start:
                    if start not in graph[v]:  # not adjacent to start
                        U.append(v)
                    else:
                        W.add(v)

            # While there are eligible vertices
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for v in graph[u]:
                        if v in W:
                            w_count += 1
                    # Tie-break by min degree in G[U]
                    deg_in_U = 0
                    for v in graph[u]:
                        if v in U:  # v is in U and uncolored (since colored vertices are not in U)
                            deg_in_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # no eligible? should not happen

                # Add best_u to S
                S.append(best_u)
                colored[best_u] = True
                # Remove best_u from U
                U.remove(best_u)
                # Move neighbors of best_u that are in U to W
                for v in graph[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)

            # Assign color idx to all in S
            for u in S:
                colors[u] = color_idx
            color_idx += 1

        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Copy of degrees
        degree = [len(graph[u]) for u in range(n)]
        # Set of unremoved vertices
        remaining = set(range(n))
        order = []  # will store removal order

        for _ in range(n):
            # Find vertex with min degree in remaining
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                if degree[v] < min_deg:
                    min_deg = degree[v]
                    v_min = v
            if v_min == -1:
                break
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors
            for v in graph[v_min]:
                if v in remaining:
                    degree[v] -= 1

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by colored neighbors
            used = set()
            for u in graph[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c

        return colors

    # Run multiple heuristics and pick the best (fewest colors)
    best_coloring = None
    best_num_colors = float('inf')

    for heuristic in [dsatur, rlf, smallest_last]:
        try:
            coloring = heuristic()
            num_colors = max(coloring) + 1 if coloring else 0
            # Validate coloring
            valid = True
            for u in range(n):
                for v in graph[u]:
                    if u < v and coloring[u] == coloring[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid and num_colors < best_num_colors:
                best_num_colors = num_colors
                best_coloring = coloring
        except Exception:
            continue

    if best_coloring is None:
        # Fallback: greedy by degree order
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        colors = [-1] * n
        for u in order:
