        best_num_colors = max(colors) + 1 if colors else 0

    # Step 3: Try to reduce number of colors using Kempe chain swaps
    def kempe_reduce(coloring):
        # Make a copy to work on
        col = coloring[:]
        k = max(col) + 1 if n > 0 else 0
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            verts = [u for u in range(n) if col[u] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            changed = True
            while changed and verts:
                changed = False
                # Try to recolor each vertex in the class
                for u in verts[:]:  # iterate over a copy
                    if col[u] != target_color:  # might have been recolored
                        continue
                    # Try direct reassignment to a lower color
                    for c in range(target_color):
                        # Check if color c is available (no neighbor has color c)
                        conflict = False
                        for v in graph[u]:
                            if col[v] == c:
                                conflict = True
                                break
                        if not conflict:
                            col[u] = c
                            changed = True
                            verts.remove(u)
                            break
                    if changed:
                        continue
                    # Try Kempe chain swap with each lower color
                    for c in range(target_color):
                        # We want to swap colors target_color and c in the component containing u
                        # Only if u is not adjacent to any vertex of color c (otherwise swap would cause conflict)
                        has_c_neighbor = False
                        for v in graph[u]:
                            if col[v] == c:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            continue
                        # Build the Kempe chain: connected component of u in the subgraph of colors {target_color, c}
                        # We'll do BFS
                        stack = [u]
                        visited_kempe = set([u])
                        component = set()
                        while stack:
                            x = stack.pop()
                            component.add(x)
                            for y in graph[x]:
                                if col[y] in (target_color, c) and y not in visited_kempe:
                                    visited_kempe.add(y)
                                    stack.append(y)
                        # Swap colors in the component
                        for x in component:
                            if col[x] == target_color:
                                col[x] = c
                            elif col[x] == c:
                                col[x] = target_color
