    for i in range(n):
        if bit_adj[i] & (1 << i):
            bit_adj[i] &= ~(1 << i)
        adj_list[i] = [j for j in adj_list[i] if j != i]

    # Helper: count bits
    def bit_count(x):
        return x.bit_count()

