    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor colorsets as bitmasks for fast saturation update
        neighbor_colors = [0] * n

        # degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # select uncolored vertex with max saturation, then max degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat_u = saturation[u]
                    deg_u = degrees[u]
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # update saturation and neighbor colors for neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:
                    # if this color is new in u's neighborhood
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return coloring

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # independent set for this color
            S = []
            # choose vertex with max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda u: len([w for w in adj_list[u] if w in uncolored]))
                S.append(v)
                uncolored.remove(v)

            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set(uncolored)
            W = set()
            for u in S:
                for w in adj_list[u]:
                    if w in uncolored:
                        W.add(w)
            U -= W

            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # tie-break: min degree in U
                    deg_in_U = len([w for w in adj_list[u] if w in U])
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.append(best_u)
                uncolored.remove(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
        return coloring

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # we'll update degrees as we remove vertices
        deg_copy = degrees[:]

        for _ in range(n):
            # find vertex with minimum degree in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if deg_copy[u] < min_deg:
                    min_deg = deg_copy[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    deg_copy[u] -= 1

