        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, v, a, b):
        if coloring[v] not in (a, b):
            return False
        target = b if coloring[v] == a else a
        stack = [v]
        visited = set()
        component = []
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if coloring[u] == a or coloring[u] == b:
                component.append(u)
                for w in adj_list[u]:
                    if w not in visited and (coloring[w] == a or coloring[w] == b):
                        stack.append(w)
        # check if swapping is safe: no neighbor outside component has color a or b that would conflict
        # Actually, Kempe swap always preserves validity, so we can just swap
        for u in component:
            if coloring[u] == a:
                coloring[u] = b
            else:
                coloring[u] = a
        return True

    # Attempt to eliminate the last color using Kempe chains
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color k-1
        target_color = k - 1
        vertices = [i for i in range(n) if coloring[i] == target_color]
        if not vertices:
            return compact_colors(coloring)

        changed = True
        while changed and vertices:
            changed = False
            # try direct reassignment first
            for v in vertices[:]:
                if coloring[v] != target_color:
                    continue
                used = 0
                for u in adj_list[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
