                c = 0
                while used & (1 << c):
                    c += 1
                if c < target_color:
                    coloring[v] = c
                    vertices.remove(v)
                    changed = True
            if not vertices:
                break
            # try Kempe chains with each lower color
            for v in vertices[:]:
                if coloring[v] != target_color:
                    continue
                for c in range(target_color):
                    # try to swap along (target_color, c) Kempe chain
                    # make a copy to test
                    test_coloring = coloring[:]
                    if kempe_swap(test_coloring, v, target_color, c):
                        # check if v now has color c (meaning it was swapped)
                        if test_coloring[v] == c:
                            # accept the swap
                            coloring = test_coloring
                            vertices.remove(v)
                            changed = True
                            break
                if changed:
                    break
            if not changed:
                break
        if not vertices:
            return compact_colors(coloring)
        return coloring

    # Spectral-inspired clustering via random walk (heat kernel approximation)
    def spectral_clustering_init():
        # Use a few steps of random walk to get a diffusion vector
        # Start with random vector, apply heat kernel: p(t) = exp(-t*L) * p0
        # Approximate via repeated averaging (like PageRank)
        p = [random.random() for _ in range(n)]
        # Normalize
        s = sum(p)
        if s == 0:
            p = [1.0 / n] * n
        else:
            p = [x / s for x in p]

        # Apply 10 steps of random walk (mixing)
        for _ in range(10):
            p_new = [0.0] * n
            for u in range(n):
                if adj_list[u]:
                    val = p[u] / len(adj_list[u])
                    for v in adj_list[u]:
                        p_new[v] += val
                else:
                    p_new[u] += p[u]  # isolated vertex
            p = p_new

        # Assign initial colors based on sign of (p[u] - median)
        median_p = sorted(p)[n // 2]
        coloring = [0 if p[u] < median_p else 1 for u in range(n)]
        # Ensure it's valid by fixing conflicts via greedy
        for u in range(n):
            used = 0
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(compact_colors(c1[:]))
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(compact_colors(c2[:]))
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
