    except:
        pass

    # Spectral clustering init
    try:
        c4 = spectral_clustering_init()
        if is_valid_coloring(c4):
            candidates.append(compact_colors(c4[:]))
    except:
        pass

    # If no candidates, fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for u in range(n):
            used = 0
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        candidates.append(compact_colors(coloring))

    # Choose best candidate (fewest colors)
    best = min(candidates, key=num_colors)

    # Apply Kempe chain reduction iteratively
    current = best[:]
    for _ in range(10):  # limit iterations
        reduced = reduce_colors(current[:])
        if num_colors(reduced) < num_colors(current):
            current = reduced
        else:
            break

    # Final validation and compacting
    if not is_valid_coloring(current):
        # last resort: greedy
        coloring = [-1] * n
        for u in range(n):
            used = 0
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        current = compact_colors(coloring)

    return current

