                    # Since n is small, we can do BFS for the component and simulate swap.
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for nb in adj_list[u]:
                            if not visited[nb] and (colors[nb] == c or colors[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Swap colors c and target_color in component
                    swapped_colors = colors[:]
                    for u in component:
                        if swapped_colors[u] == c:
                            swapped_colors[u] = target_color
                        elif swapped_colors[u] == target_color:
                            swapped_colors[u] = c
                    # Check if swapped coloring is valid
                    if is_valid_coloring(swapped_colors):
                        # Now check if target_color is still used anywhere
                        if target_color not in swapped_colors:
                            colors = swapped_colors
                            made_change = True
                            k = count_colors(colors)
                            break
                    # else, try next c
                if made_change:
                    break
            if made_change:
                improved = True
                # compact colors after change
                colors = compact_colors(colors)
                k = count_colors(colors)
            # if no change, break
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            cols = func()
            if not is_valid_coloring(cols):
                continue
            k = count_colors(cols)
            if k < best_k:
                best_k = k
                best_colors = cols
        except Exception:
            continue

    # Fallback: if all failed, use greedy by degree order
    if best_colors is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)

    # Apply Kempe reduction to try to improve
    best_colors = kempe_reduce(best_colors)
    # Final validation and compaction
    if not is_valid_coloring(best_colors):
        # last resort: greedy
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = compact_colors(colors)
    else:
        best_colors = compact_colors(best_colors)

    return best_colors

