def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = (len(adj[0]) == n and 
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    # Build adjacency list and bitmask representation
    if is_matrix:
        neighbors = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
    else:
        neighbors = [list(set(lst)) for lst in adj]  # deduplicate

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert to consecutive colors starting from 0
    def normalize(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # Heuristic 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg_uncolored = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = deg_uncolored[v]
                if s > best_sat or (s == best_sat and d > best_deg) or \
                   (s == best_sat and d == best_deg and (best == -1 or random.random() < 0.5)):
                    best_sat = s
                    best_deg = d
                    best = v
            v = best
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and not any(w in S for w in neighbors[u])}
            W = {u for u in uncolored if u not in S and u not in U}
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    deg_U = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or \
                       (score == best_score and deg_U == best_deg_U and (best_u == -1 or random.random() < 0.5)):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Core decomposition to get ordering
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    if d < len(buckets):
                        buckets[d].append(u)
                    if deg[u] < ptr:
                        ptr = deg[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    start_time = time.time()
    candidates = []

    # DSATUR
    if time.time() - start_time < 0.04:  # 40ms budget for heuristics
        col = dsatur()
        if is_valid(col):
            candidates.append((count_colors(col), col))

    # RLF
    if time.time() - start_time < 0.04:
        col = rlf()
        if is_valid(col):
            candidates.append((count_colors(col), col))

    # Smallest-Last
    if time.time() - start_time < 0.04:
        col = smallest_last()
        if is_valid(col):
            candidates.append((count_colors(col), col))

    # Fallback: simple greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        col = greedy_color(order)
        if is_valid(col):
            candidates.append((count_colors(col), col))

    # Select best candidate (fewest colors)
    if not candidates:
        # Ultimate fallback: assign all different colors
        col = list(range(n))
        candidates.append((n, col))

    best_color = min(candidates, key=lambda x: x[0])[1]
    best_color = normalize(best_color)

    # Kempe chain-based color reduction
    def eliminate_color_class(coloring, target_color):
        # Get vertices with target_color
        verts = [v for v in range(n) if coloring[v] == target_color]
        if not verts:
            return coloring, True  # already eliminated

        # Try to recolor each vertex in target_color class
        new_coloring = coloring[:]
        for v in verts:
            used = 0
            for u in neighbors[v]:
                if new_coloring[u] != -1:
                    used |= (1 << new_coloring[u])
            # Try direct reassignment to a lower color
            for c in range(target_color):
                if not (used & (1 << c)):
                    new_coloring[v] = c
                    break
            else:
                # Try Kempe chain swap with each lower color
                swapped = False
                for c in range(target_color):
                    # Build (c, target_color) Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if new_coloring[node] == c or new_coloring[node] == target_color:
                            component.add(node)
                            for nb in neighbors[node]:
                                if new_coloring[nb] == c or new_coloring[nb] == target_color:
                                    if nb not in visited:
                                        stack.append(nb)
                    # Check if we can swap: no neighbor of component has color c outside component
                    can_swap = True
                    for node in component:
                        for nb in neighbors[node]:
                            if nb not in component and new_coloring[nb] == c:
                                can_swap = False
                                break
                        if not can_swap:
                            break
                    if can_swap:
                        # Perform swap
                        for node in component:
                            if new_coloring[node] == c:
                                new_coloring[node] = target_color
                            elif new_coloring[node] == target_color:
                                new_coloring[node] = c
                        swapped = True
                        break
                if not swapped:
                    # Cannot recolor v, so elimination fails
                    return coloring, False
        return new_coloring, True

    # Iteratively try to reduce colors
    current = best_color[:]
    changed = True
    while changed and time.time() - start_time < 0.045:  # 45ms budget for reduction
        changed = False
        k = max(current) + 1 if current else 0
        # Try to eliminate color classes from highest to lowest
        for color in range(k-1, -1, -1):
            new_col, success = eliminate_color_class(current, color)
            if success:
                current = normalize(new_col)
                changed = True
                break  # restart from highest color after change

    # Final validation and normalization
    if not is_valid(current):
        # Last resort: greedy on original order
        current = greedy_color(list(range(n)))
        current = normalize(current)

    return current

