    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    if is_matrix:
        # Convert adjacency matrix to adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    graph[i].append(j)
    else:
        graph = adj

    # Precompute neighbor sets for fast lookup
    neighbor_sets = [set(neigh) for neigh in graph]

    # Compute Jaccard similarity for non-adjacent vertex pairs
    jaccard = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if j not in neighbor_sets[i]:
                set_i = neighbor_sets[i]
                set_j = neighbor_sets[j]
                inter = len(set_i & set_j)
                union = len(set_i | set_j)
                if union > 0:
                    jaccard[i][j] = jaccard[j][i] = inter / union
                else:
                    jaccard[i][j] = jaccard[j][i] = 0.0

    # Create list of non-adjacent pairs with Jaccard > 0
    pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            if j not in neighbor_sets[i] and jaccard[i][j] > 0:
                pairs.append((jaccard[i][j], i, j))
    # Sort by Jaccard similarity descending
    pairs.sort(key=lambda x: x[0], reverse=True)

    # Greedy coloring using Jaccard pairs
    colors = [-1] * n
    used_colors = set()

    for _, i, j in pairs:
        if colors[i] == -1 and colors[j] == -1:
            # Find smallest color not used by neighbors of i or j
            neighbor_colors = set()
            for nb in neighbor_sets[i]:
                if colors[nb] != -1:
                    neighbor_colors.add(colors[nb])
            for nb in neighbor_sets[j]:
                if colors[nb] != -1:
                    neighbor_colors.add(colors[nb])
            c = 0
            while c in neighbor_colors:
                c += 1
            colors[i] = c
            colors[j] = c
            used_colors.add(c)

    # Color remaining uncolored vertices with greedy first-fit
    for v in range(n):
        if colors[v] == -1:
            neighbor_colors = set()
            for nb in neighbor_sets[v]:
                if colors[nb] != -1:
                    neighbor_colors.add(colors[nb])
            c = 0
            while c in neighbor_colors:
                c += 1
            colors[v] = c
            used_colors.add(c)

    # Compact colors to 0..k-1
    color_map = {}
    next_color = 0
    for v in range(n):
        if colors[v] not in color_map:
            color_map[colors[v]] = next_color
            next_color += 1
        colors[v] = color_map[colors[v]]

    return colors

