    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:  # safety check
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: compute degree
    def degree(u):
        return len(adj_list[u])

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: convert to consecutive colors starting from 0
    def normalize_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor colorsets as bit masks for fast sat update
        neighbor_colors = [0] * n

        # order by degree descending for initial tie-breaking
        vertices = list(range(n))
        vertices.sort(key=lambda x: degree(x), reverse=True)

        for _ in range(n):
            # select uncolored vertex with max sat, tie-break by degree, then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in vertices:
                if colors[u] == -1:
                    if sat[u] > max_sat or (sat[u] == max_sat and (degree(u) > max_deg or (degree(u) == max_deg and u < v))):
                        max_sat = sat[u]
                        max_deg = degree(u)
                        v = u
            if v == -1:  # should not happen
                break

            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

            # update saturation and neighbor colors for uncolored neighbors
            for u in adj_list[v]:
                if colors[u] == -1:
                    # update neighbor color bitmask
                    neighbor_colors[u] |= (1 << c)
                    # update saturation degree: number of distinct colors in neighbor_colors[u]
                    sat[u] = bin(neighbor_colors[u]).count("1")
        return colors

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        color = 0
        # set of uncolored vertices
        uncolored = set(range(n))

        while uncolored:
            # independent set for this color
            independent_set = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set.add(v)
            # partition: U = vertices not adjacent to any in independent_set, W = adjacent
            U = {u for u in uncolored if u not in independent_set and not any(w in adj_list[u] for w in independent_set)}
            W = {u for u in uncolored if u not in independent_set and u not in U}

            while U:
                # select u in U with max neighbors in W
                u_star = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_in_U = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        u_star = u
                if u_star == -1:
                    break  # should not happen
                independent_set.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star from U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # assign color to all in independent_set
            for v in independent_set:
                colors[v] = color
            color += 1
            # next round: uncolored becomes W (vertices adjacent to current independent set)
            uncolored = W
