    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        colors = [-1] * n
        # copy of degrees for peeling
        deg = [degree(u) for u in range(n)]
        # adjacency sets for fast removal
        adj_set = [set(adj_list[u]) for u in range(n)]
