        for v in reversed(stack):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(colors, a, b, v):
        if colors[v] not in (a, b):
            return False
        # BFS to get the Kempe chain component
        stack = [v]
        visited = set()
        component = set()
        target_colors = {a, b}
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if colors[u] in target_colors:
                component.add(u)
                for w in adj_list[u]:
                    if w not in visited and colors[w] in target_colors:
                        stack.append(w)
        # swap colors a<->b in the component
        for u in component:
            if colors[u] == a:
                colors[u] = b
            else:
                colors[u] = a
        return True

    # Try to eliminate the smallest color class using direct reassignment and Kempe chains
    def reduce_colors(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # try to remove color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
