        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            k = count_colors(col)
            if k < best_k:
                best_k = k
                best_color = col[:]
        except Exception:
            continue

    # If no candidate, fallback to greedy on natural order
    if best_color is None:
        best_color = greedy_color(list(range(n)))
        best_k = count_colors(best_color)

    # Kempe chain color reduction
    def kempe_reduction(color):
        k = count_colors(color)
        if k <= 1:
            return color
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, 0, -1):
            # Vertices with target_color
            vertices = [u for u in range(n) if color[u] == target_color]
            if not vertices:
                continue
            changed = True
            while changed and vertices:
                changed = False
                # Try to recolor each vertex in this class
                for u in vertices[:]:  # copy list
                    if color[u] != target_color:
                        continue  # already recolored
                    # Try direct reassignment to a lower color
                    used = 0
                    for v in adj_list[u]:
                        if color[v] != -1:
                            used |= 1 << color[v]
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            # Move u to color c
                            color[u] = c
                            changed = True
                            vertices.remove(u)
                            break
                    if color[u] == target_color:
                        # Try Kempe chain swap with each lower color
                        for c in range(target_color):
                            # Build (target_color, c)-Kempe chain containing u
                            stack = [u]
                            visited = set()
                            component = set()
                            while stack:
                                v = stack.pop()
                                if v in visited:
                                    continue
                                visited.add(v)
                                if color[v] == target_color or color[v] == c:
                                    component.add(v)
                                    for w in adj_list[v]:
                                        if w not in visited and (color[w] == target_color or color[w] == c):
                                            stack.append(w)
                            # Check if swapping this component frees color c for u
                            # After swap, u would get color c (since it was target_color)
                            # We need to ensure no neighbor of u has color c after swap
                            conflict = False
                            for w in adj_list[u]:
                                if color[w] == c and w not in component:
                                    conflict = True
                                    break
                            if not conflict:
                                # Perform swap: target_color <-> c in component
                                for v in component:
                                    if color[v] == target_color:
                                        color[v] = c
                                    elif color[v] == c:
                                        color[v] = target_color
                                # u is now color c
                                color[u] = c
                                changed = True
                                if u in vertices:
                                    vertices.remove(u)
                                break
            # If no vertices left with target_color, we can reduce k
            if not any(color[u] == target_color for u in range(n)):
                # Compact colors: remap higher colors down
                mapping = {}
                new_color = 0
                for old in range(k):
                    if any(color[u] == old for u in range(n)):
                        mapping[old] = new_color
                        new_color += 1
                for u in range(n):
                    color[u] = mapping[color[u]]
                k = new_color
                break  # restart reduction with new k
        return color

    best_color = kempe_reduction(best_color)

    # Final validation and consecution
    # Ensure valid coloring
    for u in range(n):
        for v in adj_list[u]:
            if u < v and color[u] == color[v]:
                # Should not happen, but fix by assigning a new color if needed
                pass  # In practice, our algorithms should maintain validity
    # Ensure colors are consecutive from 0
    used_colors = set(color)
    if used_colors:
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        color = [mapping[c] for c in color]
    return color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        # Validate binary entries
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Saturation: bitmask of colors used by colored neighbors
        sat = [0] * n
        # Degree in the uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, then max degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = bit_count(sat[u])
                if s > max_sat or (s == max_sat and uncolored_deg[u] > max_deg):
                    max_sat = s
                    max_deg = uncolored_deg[u]
                    v = u
                elif s == max_sat and uncolored_deg[u] == max_deg:
                    if v == -1 or u < v:
                        v = u
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation and uncolored degree for neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Choose vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = {u for u in uncolored if u not in S and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: sum(1 for y in neighbors[x] if y in W))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering greedy
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    buckets[d].remove(u)
                    buckets[d-1].append(u)
                    if d-1 < ptr:
                        ptr = d-1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select candidate with fewest colors
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate coloring
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if u < v and col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col

    # If no valid candidate (should not happen), fallback to greedy
    if best_color is None:
        best_color = greedy_color(list(range(n)))
        best_k = max(best_color) + 1 if n > 0 else 0

    # Kempe chain color reduction
    def kempe_reduce(color):
        # Ensure colors are compact
        def compact(col):
            mapping = {}
            next_c = 0
            for c in col:
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
            return [mapping[c] for c in col]

        color = compact(color)
        changed = True
        while changed:
            changed = False
            # Find smallest color class (highest color index)
            classes = [[] for _ in range(best_k)]
            for v, c in enumerate(color):
                classes[c].append(v)
            # Try to eliminate highest color class
            for c in range(best_k-1, -1, -1):
                if not classes[c]:
                    continue
                # Try to recolor each vertex in class c
                for v in classes[c][:]:
                    # Try direct reassignment to a lower color
                    for c2 in range(c):
                        conflict = False
                        for u in neighbors[v]:
                            if color[u] == c2:
                                conflict = True
                                break
                        if not conflict:
                            # Recolor v to c2
                            color[v] = c2
                            classes[c].remove(v)
                            classes[c2].append(v)
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chain swap with each lower color
                    for c2 in range(c):
                        # BFS to find Kempe chain of colors c and c2 containing v
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            x = queue.popleft()
                            component.append(x)
                            for y in neighbors[x]:
                                if not visited[y] and (color[y] == c or color[y] == c2):
                                    visited[y] = True
                                    queue.append(y)
                        # Check if swapping this component frees color c2 for v
                        # After swap, v would have color c2; check if any neighbor has color c2
                        can_swap = True
                        for x in component:
                            for y in neighbors[x]:
                                if color[y] == c2 and (color[x] != c or y not in component):
                                    # Neighbor y has color c2 and x is not in the component or x has color c (so after swap x would not be c2)
                                    # Actually, we need: after swap, no two adjacent have same color.
                                    # Swapping means: in component, c->c2 and c2->c.
                                    # So for edge (x,y):
                                    #   if x in component and y in component: colors swap, still different.
                                    #   if x in component and y not in component: 
                                    #       if color[x]==c -> becomes c2; if color[y]==c2 -> conflict.
                                    #       if color[x]==c2 -> becomes c; if color[y]==c -> conflict.
                                    #   if x not in component and y in component: symmetric.
                                    # So we can check: for any edge (x,y) with x in component, y not in component:
                                    #   if (color[x]==c and color[y]==c2) or (color[x]==c2 and color[y]==c): conflict after swap.
                                    if (color[x] == c and color[y] == c2) or (color[x] == c2 and color[y] == c):
                                        can_swap = False
                                        break
                            if not can_swap:
                                break
                        if can_swap:
                            # Perform swap
                            for x in component:
                                if color[x] == c:
                                    color[x] = c2
                                else:
                                    color[x] = c
                            # Update classes
                            for x in component:
                                if color[x] == c2:
                                    classes[c2].append(x)
                                else:
                                    classes[c].append(x)
                            # Rebuild classes for simplicity (since we modified)
                            classes = [[] for _ in range(best_k)]
                            for v, colv in enumerate(color):
                                classes[colv].append(v)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # If we eliminated a color, compact and restart
            if changed:
                # Compact colors
                mapping = {}
                next_c = 0
                for c in range(best_k):
                    if classes[c]:
                        mapping[c] = next_c
                        next_c += 1
                new_color = [mapping[color[v]] for v in range(n)]
                color = new_color
                best_k = next_c
                # Rebuild classes
                classes = [[] for _ in range(best_k)]
                for v, c in enumerate(color):
                    classes[c].append(v)
        return color

    # Apply Kempe reduction
    final_color = kempe_reduce(best_color)
    # Final validation and compact
    def is_valid(col):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and col[u] == col[v]:
                    return False
        return True

    if not is_valid(final_color):
        # Fallback to DSATUR if Kempe broke validity
        final_color = dsatur()

    # Ensure compact
    mapping = {}
    next_c = 0
    for c in final_color:
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
    final_color = [mapping[c] for c in final_color]

    return final_color

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: count bits
    def bit_count(x):
        return x.bit_count()

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            cu = colors[u]
            for v in adj_list[u]:
                if cu == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # degrees in the whole graph
        degrees = [len(adj_list[i]) for i in range(n)]
        # saturation sets: bitmask of colors used by neighbors
        sat = [0] * n
        colored = [False] * n

        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if colored[i]:
                    continue
                si = bit_count(sat[i])
                if si > max_sat or (si == max_sat and (degrees[i] > max_deg or (degrees[i] == max_deg and random.random() < 0.5))):
                    max_sat = si
                    max_deg = degrees[i]
                    v = i
            if v == -1:
                break  # should not happen
            # find smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            # update saturation of neighbors
            for u in adj_list[v]:
                if not colored[u]:
                    sat[u] |= (1 << c)
        return compact_colors(colors)

    # RLF: Recursive Largest First
    def rlf():
        colors = [-1] * n
        colored = [False] * n
        color = 0

        while True:
            # find uncolored vertices
            R = [i for i in range(n) if not colored[i]]
            if not R:
                break
            # degree in the subgraph induced by R
            deg_in_R = [0] * n
            for i in R:
                for j in adj_list[i]:
                    if not colored[j]:
                        deg_in_R[i] += 1
            # choose vertex with max degree in R
            v1 = max(R, key=lambda x: deg_in_R[x])
            S = [v1]
            colored[v1] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = [i for i in R if i != v1 and not any(adj_list[i].count(s) > 0 for s in S)]  # inefficient but n small
            # Better: use adjacency
            U = []
            W = set()
            for i in R:
                if i == v1:
                    continue
                adjacent_to_S = False
                for s in S:
                    if i in adj_list[s]:  # or adj_list[s] contains i
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(i)
                else:
                    U.append(i)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    # degree in U: number of neighbors in U
                    deg_U = 0
                    for w in adj_list[u]:
                        if w in U:  # but U is list, make set for speed? n small
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                if best_u == -1:
                    break
                # add best_u to S
                S.append(best_u)
                colored[best_u] = True
                # remove from U
                U.remove(best_u)
                # move neighbors of best_u that are in U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
        return compact_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get order
        degrees = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # we will remove min degree vertex repeatedly
        # use bucket sort for efficiency, but n small
        while remaining:
            # find vertex with min degree in remaining subgraph
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                # compute degree in remaining
                deg = 0
                for nb in adj_list[v]:
                    if nb in remaining:
                        deg += 1
                if deg < min_deg:
                    min_deg = deg
                    v_min = v
            if v_min == -1:
                break
            order.append(v_min)
            remaining.remove(v_min)
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors_in):
        colors = colors_in[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(colors)
            if k <= 1:
                break
            # find smallest color class (last color)
            target_color = k - 1
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                # should not happen, but compact anyway
                return compact_colors(colors)
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used_by_neighbors = 0
                for nb in adj_list[v]:
                    if colors[nb] != -1:
                        used_by_neighbors |= (1 << colors[nb])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # can move to color c
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already not target_color, skip (but we are in loop for target_color)
                    if colors[v] != target_color:
                        break
                    # BFS to find Kempe chain of colors (target_color, c) containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (colors[nb] == target_color or colors[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # check if any neighbor of the component has color c (external)
                    has_external_c = False
                    for node in component:
                        for nb in adj_list[node]:
                            if colors[nb] == c and not visited[nb]:
                                has_external_c = True
                                break
                        if has_external_c:
                            break
                    if not has_external_c:
                        # we can swap colors in the component
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            else:
                                colors[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            if changed:
                colors = compact_colors(colors)
            else:
                break
        return colors

    # Time management: we have 50ms total, but we will run heuristics and then reduction
    start_time = time.time()
    time_limit = 0.05  # 50 ms

    best_colors = None
    best_k = float('inf')

    # Run DSATUR
    if time.time() - start_time < time_limit:
        c1 = dsatur()
        k1 = num_colors(c1)
        if k1 < best_k and is_valid_coloring(c1):
            best_k = k1
            best_colors = c1
    # Run RLF
    if time.time() - start_time < time_limit:
        c2 = rlf()
        k2 = num_colors(c2)
        if k2 < best_k and is_valid_coloring(c2):
            best_k = k2
            best_colors = c2
    # Run Smallest-Last
    if time.time() - start_time < time_limit:
        c3 = smallest_last()
        k3 = num_colors(c3)
        if k3 < best_k and is_valid_coloring(c3):
            best_k = k3
            best_colors = c3

    # If no valid coloring found (should not happen), fallback to greedy
    if best_colors is None:
        # simple greedy in order 0..n-1
        colors = [-1] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best_colors = compact_colors(colors)

    # Apply Kempe reduction to improve
    if time.time() - start_time < time_limit:
        improved = kempe_reduce(best_colors)
        if is_valid_coloring(improved):
            ki = num_colors(improved)
            if ki < best_k:
                best_colors = improved

    # Final validation and compact
    if not is_valid_coloring(best_colors):
        # last resort: greedy
        colors = [-1] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best_colors = compact_colors(colors)
    else:
        best_colors = compact_colors(best_colors)

    return best_colors

