def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute degrees
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Compute degree for each vertex
    degree = [len(adj_list[i]) for i in range(n)]

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize_coloring(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets for saturation update
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select uncolored vertex with max saturation, break ties by degree (uncolored degree), then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturation[v]
                deg_v = degree[v]  # static degree, but we can use uncolored degree for tie-breaking? 
                # Actually, we want degree in uncolored subgraph for tie-breaking
                # Compute uncolored degree: number of uncolored neighbors
                uncolored_deg = 0
                for nb in adj_list[v]:
                    if nb in uncolored:
                        uncolored_deg += 1
                if sat_v > best_sat or (sat_v == best_sat and uncolored_deg > best_deg) or \
                   (sat_v == best_sat and uncolored_deg == best_deg and v < best_v):
                    best_sat = sat_v
                    best_deg = uncolored_deg
                    best_v = v
            v = best_v
            # Find smallest color not used by neighbors
            used = [False] * (n + 1)  # n+1 to be safe
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used[colors[nb]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    if c not in neighbor_colors[nb]:
                        neighbor_colors[nb].add(c)
                        saturation[nb] += 1
        return colors

    # RLF algorithm
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # Build maximal independent set for color_idx
            # Step 1: choose vertex with max degree in G[uncolored]
            v = -1
            max_deg = -1
            for u in uncolored:
                # degree in uncolored subgraph
                deg = 0
                for nb in adj_list[u]:
                    if nb in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
                elif deg == max_deg and u < v:
                    v = u
            independent_set = [v]
            # Partition remaining uncolored into U (not adjacent to any in S) and W (adjacent to at least one in S)
            S = set(independent_set)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent_to_S = False
                for w in S:
                    if u in adj_list[w] or w in adj_list[u]:  # undirected, so either way
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1  # for tie-break: min degree in G[U]
                for u in U:
                    # count neighbors in W
                    score = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            score += 1
                    # degree in G[U]
                    deg_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or \
                       (score == best_score and deg_U == best_deg_U and u < best_u):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                independent_set.append(u)
                S.add(u)
                U.remove(u)
                # Move neighbors of u that are in U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color_idx to all in independent_set
            for node in independent_set:
                colors[node] = color_idx
                uncolored.remove(node)
            color_idx += 1
        return colors

    # Smallest-Last (SL) ordering greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        # We'll compute the order and then color in reverse
        remaining = set(range(n))
        degree_copy = degree[:]  # current degree in remaining graph
        order = []  # removal order
        # We'll maintain a list of vertices by degree for efficiency, but n<=100 so we can scan
        for _ in range(n):
            # Find vertex with min degree in remaining
            min_deg = float('inf')
            v = -1
            for u in remaining:
                if degree_copy[u] < min_deg:
                    min_deg = degree_copy[u]
                    v = u
                elif degree_copy[u] == min_deg and u < v:
                    v = u
            order.append(v)
            remaining.remove(v)
            # Update degree_copy of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    degree_copy[nb] -= 1
        # Now color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used[colors[nb]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
        return colors

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(normalize_coloring(c1))
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(normalize_coloring(c2))
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(normalize_coloring(c3))
    except:
        pass

    # If no candidates (shouldn't happen), fallback to greedy by index
    if not candidates:
        colors = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    used[colors[nb]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[i] = c
        candidates.append(normalize_coloring(c))

    # Select candidate with fewest colors
    best_coloring = min(candidates, key=lambda x: num_colors(x))

    # Kempe chain-based color reduction
    def kempe_reduction(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        changed = True
        # We'll try to reduce colors until no improvement
        while changed:
            changed = False
            k = num_colors(current)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # Should not happen, but skip
                break
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = [False] * (k)  # we only need up to k-1
                for nb in adj_list[v]:
                    if current[nb] < k:  # only colors in use
                        used[current[nb]] = True
                # Find smallest color not used by neighbors
                for c in range(k):
                    if not used[c]:
                        # Recolor v to c
                        current[v] = c
                        changed = True
                        break
                if changed:
                    # After recoloring, we may have emptied target_color, break to recompute k
                    break
                # If direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (target_color, c)
                    # We need to see if v is in a component of the (target_color, c) subgraph
                    # that does not contain any vertex of color c that is adjacent to v? 
                    # Actually, we can swap the component containing v if it doesn't force a conflict.
                    # Standard: if in the (a,b) Kempe chain containing v, there is no neighbor of v with color b,
                    # then we can swap a and b in the component and v becomes b.
                    a = target_color
                    b = c
                    # Find the connected component of v in the subgraph induced by colors a and b
                    comp = set()
                    stack = [v]
                    visited = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if current[node] == a or current[node] == b:
                            comp.add(node)
                            for nb in adj_list[node]:
                                if current[nb] == a or current[nb] == b:
                                    if nb not in visited:
                                        stack.append(nb)
                    # Check if any neighbor of v has color b and is in the component? 
                    # Actually, if we swap, v will become b. We need to ensure that no neighbor of v is b after swap.
                    # After swap, neighbors that were a become b, and neighbors that were b become a.
                    # So we need that no neighbor of v is currently b (because after swap they would become a, which is ok) 
                    # and no neighbor of v is currently a (because after swap they become b, and if v becomes b, conflict).
                    # Wait: after swapping a and b in the component:
                    #   - v was a, becomes b.
                    #   - A neighbor u of v:
                    #        if u in comp and was a -> becomes b -> conflict with v (now b)
                    #        if u in comp and was b -> becomes a -> no conflict
                    #        if u not in comp -> color unchanged.
                    # So to avoid conflict, we need that no neighbor of v that is in the component had color a.
                    # But v itself is in the component and was a, and we are changing it to b.
                    # Actually, we need that there is no neighbor of v in the component that is colored a (other than v? but v is changing).
                    # Let's reexamine: after swap, v becomes b. For any neighbor u:
                    #   - If u in comp:
                    #        if current[u] == a -> becomes b -> same as v -> conflict.
                    #        if current[u] == b -> becomes a -> different from v (b) -> ok.
                    #   - If u not in comp: color unchanged.
                    #        if current[u] == b -> then u is b, v becomes b -> conflict.
                    #        if current[u] == a -> u is a, v becomes b -> ok.
                    # So conflict if:
                    #   (exists neighbor u in comp with current[u] == a) OR (exists neighbor u not in comp with current[u] == b)
                    # But note: if u in comp and current[u]==a, then after swap u becomes b -> conflict.
                    # If u not in comp and current[u]==b -> remains b -> conflict.
                    # So we can swap if there is NO neighbor u of v such that:
                    #   (u in comp and current[u]==a) OR (u not in comp and current[u]==b)
                    # However, note that v itself is in comp and current[v]==a, but we are changing it, so we exclude v? 
                    # Actually, we are checking neighbors u of v, so u != v.
                    safe = True
                    for nb in adj_list[v]:
                        if current[nb] == a:
                            if nb in comp:
                                safe = False
                                break
                        elif current[nb] == b:
                            if nb not in comp:
                                safe = False
                                break
                    if safe:
                        # Perform swap: in component, swap a and b
                        for node in comp:
                            if current[node] == a:
                                current[node] = b
                            elif current[node] == b:
                                current[node] = a
                        changed = True
                        break
                if changed:
                    break
            # After attempting to recolor all target vertices, if we changed something, we break to recompute k and possibly empty target_color
            if changed:
                # Break out of the target_vertices loop to restart while loop
                break
        # Normalize the coloring to use consecutive colors
        return normalize_coloring(current)

    # Apply Kempe reduction
    try:
        improved = kempe_reduction(best_coloring)
        if is_valid_coloring(improved):
            best_coloring = improved
    except:
        pass

    # Final validation and normalization
    if not is_valid_coloring(best_coloring):
        # Fallback to greedy
        colors = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    used[colors[nb]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[i] = c
        best_coloring = normalize_coloring(colors)

    return best_coloring

import math
