def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect input type and build adjacency bitmasks
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
    else:
        bit_adj = [0] * n
        for i in range(n):
            for nb in adj[i]:
                bit_adj[i] |= (1 << nb)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if colors[u] != -1 and (bit_adj[v] >> u) & 1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: count distinct colors
    def count_colors(colors):
        return max(colors) + 1 if colors else 0

    best_colors = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    uncolored = set(range(n))
    sat = [0] * n
    colors_dsatur = [-1] * n
    while uncolored:
        # select vertex with max saturation, tie-break by degree in uncolored subgraph, then index
        v = max(uncolored, key=lambda x: (sat[x], sum(1 for u in uncolored if (bit_adj[x] >> u) & 1), -x))
        # compute used colors from colored neighbors
        used = 0
        for u in range(n):
            if colors_dsatur[u] != -1 and (bit_adj[v] >> u) & 1:
                used |= (1 << colors_dsatur[u])
        c = 0
        while used & (1 << c):
            c += 1
        colors_dsatur[v] = c
        uncolored.remove(v)
        # update saturation of uncolored neighbors
        for u in uncolored:
            if (bit_adj[v] >> u) & 1:
                sat[u] += 1
    k_dsatur = count_colors(colors_dsatur)
    if k_dsatur < best_k:
        best_k = k_dsatur
        best_colors = colors_dsatur[:]

    # 2. RLF (Recursive Largest First)
    uncolored = set(range(n))
    colors_rlf = [-1] * n
    color_idx = 0
    while uncolored:
        # degree in uncolored subgraph
        deg = {v: sum(1 for u in uncolored if (bit_adj[v] >> u) & 1) for v in uncolored}
        v = max(uncolored, key=lambda x: deg[x])
        S = {v}
        U = {u for u in uncolored if u != v and not ((bit_adj[v] >> u) & 1)}
        W = {u for u in uncolored if u != v and ((bit_adj[v] >> u) & 1)}
        while U:
            # select u in U with max neighbors in W, tie-break by min degree in U
            def score(u):
                w_count = sum(1 for w in W if (bit_adj[u] >> w) & 1)
                u_deg = sum(1 for x in U if x != u and (bit_adj[u] >> x) & 1)
                return (w_count, -u_deg)
            u = max(U, key=score)
            S.add(u)
            U.remove(u)
            # move neighbors of u from U to W
            for x in list(U):
                if (bit_adj[u] >> x) & 1:
                    U.remove(x)
                    W.add(x)
        for vertex in S:
            colors_rlf[vertex] = color_idx
        uncolored -= S
        color_idx += 1
    k_rlf = count_colors(colors_rlf)
    if k_rlf < best_k:
        best_k = k_rlf
        best_colors = colors_rlf[:]

    # 3. Smallest-Last ordering
    # compute degeneracy ordering
    remaining = set(range(n))
    order = []
    deg = [0] * n
    for i in range(n):
        deg[i] = sum(1 for j in range(n) if (bit_adj[i] >> j) & 1)
    while remaining:
        v = min(remaining, key=lambda x: deg[x])
        order.append(v)
        remaining.remove(v)
        for u in range(n):
            if (bit_adj[v] >> u) & 1 and u in remaining:
                deg[u] -= 1
    order.reverse()
    colors_sl = greedy_color(order)
    k_sl = count_colors(colors_sl)
    if k_sl < best_k:
        best_k = k_sl
        best_colors = colors_sl[:]

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = count_colors(colors)
        if k <= 1:
            return colors
        color_classes = [[] for _ in range(k)]
        for v in range(n):
            color_classes[colors[v]].append(v)
        # try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            if not color_classes[target_color]:
                continue
            changed = True
            while changed and color_classes[target_color]:
                changed = False
                v = color_classes[target_color][-1]
                # try direct reassignment to a lower color
                for c in range(target_color):
                    conflict = False
                    for u in range(n):
                        if colors[u] == c and (bit_adj[v] >> u) & 1:
                            conflict = True
                            break
                    if not conflict:
                        # move v to color c
                        color_classes[target_color].pop()
                        color_classes[c].append(v)
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # BFS to find Kempe chain of colors {c, target_color} containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in range(n):
                            if not visited[y] and (bit_adj[x] >> y) & 1:
                                if colors[y] == c or colors[y] == target_color:
                                    visited[y] = True
                                    queue.append(y)
                    # check if swapping this component frees color c for v (i.e., no neighbor of v in component has color c after swap)
                    # Actually, after swap, neighbors of v that were color c become target_color and vice versa.
                    # We need that after swap, v (which will become c) has no neighbor with color c.
                    # Currently, v has color target_color. Its neighbors with color c will become target_color after swap.
                    # Its neighbors with color target_color will become c after swap.
                    # So after swap, v will have color c, and its neighbors that were target_color become c -> conflict.
                    # Therefore, we can only swap if v has no neighbor in the component with color target_color? 
                    # Let's think: we are swapping colors c and target_color in the component.
                    # v is in the component and has color target_color -> after swap becomes c.
                    # For no conflict, none of v's neighbors should have color c after swap.
                    # Neighbors of v in the component: if they had color c -> become target_color (ok), if they had target_color -> become c (conflict).
                    # Neighbors of v not in the component: keep their color.
                    # So we require that v has no neighbor in the component with color target_color (other than itself? but v is target_color, and we are going to change it).
                    # Actually, we can allow neighbors with color target_color in the component because they will become c, same as v -> conflict.
                    # Therefore, we need that in the component, v has no neighbor (other than itself) with color target_color.
                    # But note: the component is connected via edges, and we only traverse edges to vertices of colors c or target_color.
                    # It is simpler: after swap, v becomes c. We need that no neighbor of v has color c after swap.
                    # For a neighbor u of v:
                    #   if u in component:
                    #       if color[u] == c -> becomes target_color (not c)
                    #       if color[u] == target_color -> becomes c (conflict)
                    #   if u not in component: color unchanged -> conflict if color[u] == c
                    # So condition: no neighbor u of v with (u in component and color[u]==target_color) or (u not in component and color[u]==c)
                    has_conflict = False
                    for u in range(n):
                        if (bit_adj[v] >> u) & 1:
                            in_comp = visited[u]
                            if in_comp:
                                if colors[u] == target_color:
                                    has_conflict = True
                                    break
                            else:
                                if colors[u] == c:
                                    has_conflict = True
                                    break
                    if not has_conflict:
                        # perform swap
                        for x in component:
                            if colors[x] == c:
                                colors[x] = target_color
                                color_classes[c].remove(x)
                                color_classes[target_color].append(x)
                            else:  # must be target_color
                                colors[x] = c
                                color_classes[target_color].remove(x)
                                color_classes[c].append(x)
                        changed = True
                        break
            # if color class not empty, break and keep current k
            if color_classes[target_color]:
                break
            # else, remove the empty color class by shifting down
            for c in range(target_color, k-1):
                color_classes[c] = color_classes[c+1]
                for v in color_classes[c]:
                    colors[v] = c
            color_classes.pop()
            k -= 1
            # rebuild color_classes for new k (already done by shifting)
        return colors

    # Apply Kempe reduction to the best coloring found
    best_colors = kempe_reduce(best_colors)

    # Final validation and compacting
    # Ensure colors are consecutive starting from 0
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_colors[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_colors[i] = unique_colors[c]

    # Verify proper coloring (optional, but safe)
    for u in range(n):
        for v in range(u+1, n):
            if (bit_adj[u] >> v) & 1:
                if best_colors[u] == best_colors[v]:
                    # In case of error, fallback to greedy on original order
                    return greedy_color(list(range(n)))

    return best_colors

