    if n == 1:
        return [0]

    # Detect input format
    is_matrix = (len(adj) > 0 and len(adj[0]) == n and
                 all(len(row) == n for row in adj) and
                 all(x in (0, 1) for row in adj for x in row))

    # Build adjacency list and bitmasks
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
    else:
        for i in range(n):
            neighbors[i] = list(adj[i])

    # Build bit adjacency masks
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    # Helper to validate coloring
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper to get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper to compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets as bit masks for fast saturation update
        neighbor_colors = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] != -1:
                    continue
                if sat[u] > max_sat or (sat[u] == max_sat and len([w for w in neighbors[u] if coloring[w] == -1]) > max_deg):
                    max_sat = sat[u]
                    max_deg = len([w for w in neighbors[u] if coloring[w] == -1])
                    v = u
                elif sat[u] == max_sat and len([w for w in neighbors[u] if coloring[w] == -1]) == max_deg:
                    if v == -1 or u < v:  # tie-break by index
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation and neighbor colors for uncolored neighbors
            for u in neighbors[v]:
                if coloring[u] == -1:
                    # Add color c to neighbor's neighbor color set
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1
        return compact_colors(coloring)

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for this color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([w for w in neighbors[x] if w in uncolored]))
            S.append(v)
            uncolored.remove(v)

            # Partition remaining uncolored into U (eligible) and W (ineligible)
            U = {u for u in uncolored if all(u not in neighbors[w] for w in S)}
            W = uncolored - U

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = None
                max_w_neighbors = -1
                min_u_degree = float('inf')
                for u in U:
                    w_neighbors = len([w for w in neighbors[u] if w in W])
                    u_degree = len([w for w in neighbors[u] if w in U])
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and u_degree < min_u_degree):
                        max_w_neighbors = w_neighbors
                        min_u_degree = u_degree
                        u_star = u
                    elif w_neighbors == max_w_neighbors and u_degree == min_u_degree:
                        if u_star is None or u < u_star:
                            u_star = u
                if u_star is None:
                    break  # safety
                S.append(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
                uncolored.remove(u_star)

            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1

        return compact_colors(coloring)

    # Smallest-Last (Matula & Beck) greedy ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering (smallest-last)
        degrees = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use buckets for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            # Find vertex with minimum degree in remaining graph
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u]:
                    # current degree: count neighbors not removed
                    deg = len([w for w in neighbors[u] if not removed[w]])
                    if deg < min_deg:
                        min_deg = deg
                        v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # No need to update degrees explicitly; we recompute each time

        # Color in reverse order using greedy first-fit
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return compact_colors(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen if input is valid
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                continue  # already empty, should not happen due to compacting

            # Try to recolor each vertex in this class
            made_progress = False
            for v in vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in neighbors[v]:
                    if coloring[u] < target_color:  # only consider lower colors for direct move
                        used_by_neighbors |= (1 << coloring[u])
                # Find smallest available color < target_color
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Move v to color c
                        coloring[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break  # restart scanning from highest color after any change

            if made_progress:
                # Restart the color reduction loop since coloring changed
                return kempe_reduce(coloring)

            # If no direct move, try Kempe chains with each lower color
            for v in vertices:
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (c, target_color)
                    # Only if v has no neighbor of color c (otherwise direct move would have worked)
                    has_c_neighbor = any(coloring[u] == c for u in neighbors[v])
                    if has_c_neighbor:
                        continue  # direct move not possible, but Kempe might still work if we swap a component

                    # Build the Kempe chain component containing v for colors (c, target_color)
                    # We'll do BFS/DFS over vertices colored c or target_color
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == c or coloring[node] == target_color:
                            component.add(node)
                            for u in neighbors[node]:
                                if coloring[u] == c or coloring[u] == target_color:
                                    if u not in visited:
                                        stack.append(u)

                    # Check if swapping this component would cause conflict:
                    # After swap, vertices in component colored c become target_color and vice versa.
                    # We need to ensure no neighbor outside component has the color they would become.
                    safe = True
                    for node in component:
                        new_color = c if coloring[node] == target_color else target_color
                        for u in neighbors[node]:
                            if u not in component and coloring[u] == new_color:
                                safe = False
                                break
                        if not safe:
                            break

                    if safe:
                        # Perform the swap
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            else:  # must be target_color
                                coloring[node] = c
                        made_progress = True
                        break  # break out of color loop
                if made_progress:
                    break  # break out of vertex loop
            if made_progress:
                # Restart reduction after any Kempe swap
                return kempe_reduce(coloring)

        # If we couldn't eliminate the highest color, return as is
        return compact_colors(coloring)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fall back to greedy
    if not candidates:
        coloring = [0] * n
        for i in range(1, n):
            used = 0
            for j in neighbors[i]:
                if j < i:  # only already colored neighbors
                    used |= (1 << coloring[j])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[i] = c
        candidates.append(compact_colors(coloring))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = compact_colors(best)

    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    best = compact_colors(best)

    # Final validation (should always hold)
    if not is_valid(best):
        # As a last resort, return a valid greedy coloring
        coloring = [-1] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                if coloring[j] != -1:
                    used |= (1 << coloring[j])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[i] = c
        return compact_colors(coloring)

    return best

