    if is_matrix:
        for i in range(n):
            mask = 0
            for j in range(n):
                if adj[i][j]:
                    mask |= 1 << j
            bit_adj[i] = mask
            neighbors[i] = [j for j in range(n) if adj[i][j]]
    else:
        for i in range(n):
            mask = 0
            for j in adj[i]:
                mask |= 1 << j
            bit_adj[i] = mask
            neighbors[i] = adj[i][:]

    # Helper: count bits
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        colored = 0
        # degree in original graph for tie-breaking
        deg = [bit_count(bit_adj[i]) for i in range(n)]
        while colored < n:
            # select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if color[i] != -1:
                    continue
                # compute saturation: distinct colors in neighbors
                sat_mask = 0
                for u in neighbors[i]:
                    c = color[u]
                    if c != -1:
                        sat_mask |= 1 << c
                sat = bit_count(sat_mask)
                if sat > max_sat or (sat == max_sat and (deg[i] > max_deg or (sat == max_sat and deg[i] == max_deg and random.random() < 0.5))):
                    max_sat = sat
                    max_deg = deg[i]
                    v = i
            if v == -1:  # should not happen
                break
            # assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            colored += 1
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = []
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: bit_count(bit_adj[x] & sum(1 << u for u in uncolored)))
            S.append(v)
            uncolored.remove(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible for this color)
            U = set()
            W = set()
            for u in uncolored:
                if bit_adj[u] & sum(1 << s for s in S):
                    W.add(u)
                else:
                    U.add(u)
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = bit_count(bit_adj[u] & sum(1 << w for w in W))
                    deg_in_U = bit_count(bit_adj[u] & sum(1 << x for x in U))
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                S.append(u)
                uncolored.remove(u)
                U.remove(u)
                # move neighbors of u from U to W
                nbrs_u = set()
                for w in U:
                    if bit_adj[u] & (1 << w):
                        nbrs_u.add(w)
                for w in nbrs_u:
                    U.remove(w)
                    W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

    # Helper: Smallest-Last ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [bit_count(bit_adj[i]) for i in range(n)]
        # current degrees in remaining subgraph
        curr_deg = degrees[:]
        while remaining:
            # vertex of min degree in remaining
            v = min(remaining, key=lambda x: curr_deg[x])
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    curr_deg[u] -= 1
        # color in reverse order
        return greedy_color(reversed(order))

    # Run all heuristics
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # pick best (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col

    # Kempe chain color reduction
    def kempe_reduction(color):
        # make color consecutive
        mapping = {}
        next_c = 0
        for c in color:
            if c not in mapping:
                mapping[c] = next_c
                next_c += 1
        color = [mapping[c] for c in color]
        k = next_c
        if k <= 1:
            return color
        improved = True
        while improved and k > 1:
            improved = False
            # target smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if color[v] == target_color]
            if not target_vertices:
                # should not happen, but compact anyway
                mapping = {}
                next_c = 0
                for c in color:
