            # try to recolor each target vertex
            for v in target_vertices:
                used = 0
                for u in neighbors[v]:
                    c = color[u]
                    if c != -1:
                        used |= 1 << c
                # find smallest available color < target_color
                for c in range(target_color):
                    if not (used & (1 << c)):
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chains with each color c < target_color
                for c in range(target_color):
                    # if v already has color c, skip (should not happen as v is target_color)
                    if color[v] == c:
                        continue
                    # BFS to get Kempe chain component of (target_color, c) containing v
                    from collections import deque
                    comp = set()
                    q = deque([v])
                    comp.add(v)
                    while q:
                        x = q.popleft()
                        for y in neighbors[x]:
                            if y in comp:
                                continue
                            if color[y] == target_color or color[y] == c:
                                comp.add(y)
                                q.append(y)
                    # check if we can swap: after swap, no neighbor of v will have color c?
                    # Actually, swapping will change v's color to c, so we need that no neighbor of v has color c after swap.
                    # But after swap, neighbors in comp that were target_color become c, and those that were c become target_color.
                    # So we need that no neighbor of v is in comp and has color c (because after swap they become target_color, not c)
                    # and no neighbor of v is in comp and has color target_color (because after swap they become c) -> wait, we are setting v to c, so we need no neighbor has c after swap.
                    # After swap:
                    #   - vertices in comp that were target_color become c
                    #   - vertices in comp that were c become target_color
                    # So a neighbor of v will have color c after swap if:
                    #   - it is in comp and was target_color (becomes c) OR
                    #   - it is not in comp and was c (stays c)
                    # We want no neighbor of v to have color c after swap.
                    conflict = False
                    for u in neighbors[v]:
                        if color[u] == c and u not in comp:
                            conflict = True
                            break
                        if color[u] == target_color and u in comp:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for x in comp:
                            if color[x] == target_color:
                                color[x] = c
                            elif color[x] == c:
