                        improved = True
                        break
                if improved:
                    break
            if not improved:
                break
            # compact colors
            mapping = {}
            next_c = 0
            for c in color:
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
            color = [mapping[c] for c in color]
            k = next_c
        return color

