    # Final validation and compacting
    # Ensure proper coloring
    for u in range(n):
        for v in neighbors[u]:
            if u < v and color[u] == color[v]:
                # fallback: greedy on original order
                return greedy_color(list(range(n)))
    # compact colors
    mapping = {}
    next_c = 0
    for c in best_color:
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
    best_color = [mapping[c] for c in best_color]

    return best_color

