                    if v in neighbors[u]:  # could use bitmask but S small
                        adjacent = True
                        break
                if adjacent:
                    W.append(v)
                else:
                    U.append(v)
            # Process U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = -1
                for u in U:
                    # count neighbors in W
                    w_nb = 0
                    for w in W:
                        if w in neighbors[u]:
                            w_nb += 1
                    # degree in U subgraph
                    deg_u = 0
                    for v2 in U:
                        if v2 != u and v2 in neighbors[u]:
                            deg_u += 1
                    if w_nb > best_w_neighbors or (w_nb == best_w_neighbors and deg_u < best_deg_u) or (w_nb == best_w_neighbors and deg_u == best_deg_u and u < best_u):
                        best_w_neighbors = w_nb
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                colored[u] = True
                # remove u from U
                U.remove(u)
                # move neighbors of u from U to W
                for v in neighbors[u]:
                    if v in U:
                        U.remove(v)
                        if v not in W:
                            W.append(v)
            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
        return normalize(colors)

    # Smallest-Last ordering greedy
    def smallest_last():
        # Build degeneracy ordering (smallest last)
        # Copy of degrees
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []  # will be removal order
        # Buckets for efficiency (n <= 100, simple O(n^2) fine)
        for _ in range(n):
            # find vertex with minimum degree among unremoved
            min_deg = n + 1
            v_min = -1
            for v in range(n):
                if not removed[v] and deg[v] < min_deg:
                    min_deg = deg[v]
                    v_min = v
            if v_min == -1:
                break
            removed[v_min] = True
            order.append(v_min)
            # decrease degree of neighbors
            for u in neighbors[v_min]:
                if not removed[u]:
                    deg[u] -= 1
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return normalize(colors)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass
    # Also try Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return normalize(colors)
    try:
        c4 = welsh_powell()
        if is_valid(c4):
            candidates.append(c4)
    except Exception:
        pass
    # If no candidate, fallback to trivial (should not happen)
    if not candidates:
        # assign each vertex a unique color
        return list(range(n))
    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda col: chromatic_number(col))
    # Kempe chain color reduction
    def kempe_reduce(colors):
        # Make a copy we can modify
        cur = colors[:]
        k = chromatic_number(cur)
        # Try to reduce from k downwards
        while k > 0:
            target_color = k - 1
            # Collect vertices with target color
            target_verts = [v for v in range(n) if cur[v] == target_color]
            if not target_verts:
                k -= 1
                continue
            # Try to recolor each target vertex
            made_progress = False
            for v in target_verts:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    if cur[u] != -1:
                        used |= (1 << cur[u])
                for c in range(target_color):  # only lower colors
                    if not (used & (1 << c)):
                        # can recolor v to c
                        cur[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # BFS/DFS
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (cur[y] == target_color or cur[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of v has color c (outside component)
                    # Actually, we can swap if no neighbor of v in the component has color c? 
                    # Standard: if the component does not contain a neighbor of v colored c, we can swap
                    # But simpler: after swap, we need to ensure no conflict.
                    # Swapping colors in component: target <-> c
                    # It is safe if no vertex in component adjacent to v has color c? Actually, after swap, v becomes c.
                    # Conflict if any neighbor of v is colored c after swap.
                    # Before swap, neighbors of v that are in component and colored c will become target_color.
                    # So we need to check: after swap, for each neighbor u of v:
                    #   if u in component: its new color is (target_color if old was c else c if old was target_color)
                    #   else: unchanged.
                    # We can compute: conflict if exists neighbor u of v such that:
                    #   (u in component and cur[u] == c) -> after swap becomes target_color, which is not c (since target_color != c) -> no conflict? 
                    #   Actually, we are setting v to c, so conflict if neighbor u ends up with color c.
                    #   For u in component:
                    #       if cur[u] == c -> after swap becomes target_color != c -> ok
                    #       if cur[u] == target_color -> after swap becomes c -> conflict if u is neighbor of v
                    #   For u not in component: color unchanged -> conflict if cur[u] == c
                    # So conflict if: (exists neighbor u of v with cur[u] == c and u not in component) OR (exists neighbor u of v in component with cur[u] == target_color)
                    # But note: v itself is in component and cur[v]==target_color, but we don't consider self.
                    conflict = False
                    for u in neighbors[v]:
                        if cur[u] == c:
                            if not visited[u]:  # u not in component
                                conflict = True
                                break
                            else:  # u in component and cur[u]==c -> after swap becomes target_color, not c -> no conflict from this u
                                pass
                        elif cur[u] == target_color:
                            if visited[u]:  # u in component and cur[u]==target_color -> after swap becomes c -> conflict
                                conflict = True
                                break
                    if not conflict:
                        # perform swap
                        for x in component:
                            if cur[x] == target_color:
                                cur[x] = c
                            elif cur[x] == c:
                                cur[x] = target_color
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                # cannot reduce further
                break
            # Recompute k and normalize
            cur = normalize(cur)
            k = chromatic_number(cur)
        return cur
    # Apply Kempe reduction to the best candidate
    best = kempe_reduce(best)
    # Final validation (should be valid)
    if not is_valid(best):
        # fallback to DSATUR if something went wrong
        best = dsatur()
    return best

