def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)

    # Helper: Check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: Get number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: Get degree in the subgraph induced by uncolored vertices
    def uncolored_degree(v, colored_mask):
        neighbors = bit_adj[v] & ~colored_mask
        return neighbors.bit_count()

    # Helper: Get saturation degree and sum of degrees of uncolored neighbors
    def saturation_and_sum(v, colored_mask, colors):
        neighbor_colors = 0
        sum_deg = 0
        neighbors = bit_adj[v] & ~colored_mask
        while neighbors:
            u = (neighbors & -neighbors).bit_length() - 1
            neighbors &= neighbors - 1
            c = colors[u]
            if c != -1:
                neighbor_colors |= (1 << c)
            else:
                sum_deg += uncolored_degree(u, colored_mask)
        return neighbor_colors.bit_count(), sum_deg

    # DSATUR with sum of degrees of uncolored neighbors as tie-breaker
    def dsatur():
        colors = [-1] * n
        colored_mask = 0
        for _ in range(n):
            best_v = -1
            best_rho = -1
            best_sum_deg = -1
            for v in range(n):
                if colors[v] == -1:
                    rho, sum_deg = saturation_and_sum(v, colored_mask, colors)
                    if rho > best_rho or (rho == best_rho and sum_deg > best_sum_deg):
                        best_rho = rho
                        best_sum_deg = sum_deg
                        best_v = v
            if best_v == -1:
                break  # Should not happen
            # Find smallest available color
            neighbor_colors = 0
            neighbors = bit_adj[best_v] & ~colored_mask
            while neighbors:
                u = (neighbors & -neighbors).bit_length() - 1
                neighbors &= neighbors - 1
                c = colors[u]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[best_v] = c
            colored_mask |= (1 << best_v)
        return colors

    # Run DSATUR
    best_coloring = dsatur()
    best_k = num_colors(best_coloring)

    # Try a few random tie-break variations to potentially improve
    for _ in range(10):
        colors = [-1] * n
        colored_mask = 0
        order = list(range(n))
        random.shuffle(order)  # Randomize vertex processing order slightly
        for _ in range(n):
            best_v = -1
            best_rho = -1
            best_sum_deg = -1
            for v in order:
                if colors[v] == -1:
                    rho, sum_deg = saturation_and_sum(v, colored_mask, colors)
                    if rho > best_rho or (rho == best_rho and sum_deg > best_sum_deg):
                        best_rho = rho
                        best_sum_deg = sum_deg
                        best_v = v
            if best_v == -1:
                break
            neighbor_colors = 0
            neighbors = bit_adj[best_v] & ~colored_mask
            while neighbors:
                u = (neighbors & -neighbors).bit_length() - 1
                neighbors &= neighbors - 1
                c = colors[u]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[best_v] = c
            colored_mask |= (1 << best_v)
        k = num_colors(colors)
        if k < best_k and is_valid(colors):
            best_k = k
            best_coloring = colors[:]

    # Ensure coloring is valid and compact
    if not is_valid(best_coloring):
        # Fallback: simple greedy by descending degree
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        best_coloring = colors

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_coloring[i] = unique_colors[c]

    return best_coloring

