def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = [list(neighbors) for neighbors in adj]
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1') > max_deg):
                    max_sat = sat[u]
                    max_deg = bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1')
                    v = u
            if v == -1:
                v = next(iter(uncolored))
            # Assign smallest available color
            used = 0
            for w in adj_list[v]:
                if color[w] != -1:
                    used |= (1 << color[w])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for w in adj_list[v]:
                if w in uncolored:
                    sat[w] = bin(bit_adj[w] & sum((1 << color[x]) for x in range(n) if color[x] != -1)).count('1')
        return color

    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set S for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1'))
            S.add(v)
            uncolored.remove(v)
            # Partition U and W
            U = {w for w in uncolored if not (bit_adj[v] & (1 << w))}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W
                u = max(U, key=lambda x: bin(bit_adj[x] & sum((1 << w) for w in W)).count('1'))
                # Tie-break: min degree in G[U]
                candidates = [x for x in U if bin(bit_adj[x] & sum((1 << w) for w in W)).count('1') == bin(bit_adj[u] & sum((1 << w) for w in W)).count('1')]
                u = min(candidates, key=lambda x: bin(bit_adj[x] & sum((1 << w) for w in U)).count('1'))
                S.add(u)
                uncolored.remove(u)
                # Update U and W: move neighbors of u in U to W
                nbrs_u = {w for w in adj_list[u] if w in U}
                U -= nbrs_u
                W |= nbrs_u
            # Assign color c to all in S
            for u in S:
                color[u] = c
            c += 1
        return color

    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[u]) for u in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # Peeling
        for _ in range(n):
            # Find non-empty bucket with smallest degree
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for w in adj_list[v]:
                if w in remaining:
                    degree[w] -= 1
                    if degree[w] < len(buckets):
                        buckets[degree[w]].append(w)
                    else:
                        # Extend buckets if needed (should not happen)
                        buckets.extend([[] for _ in range(degree[w] - len(buckets) + 1)])
                        buckets[degree[w]].append(w)
        # Color in reverse order
        return greedy_color(reversed(order))

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_color = None
    min_colors = float('inf')
    for col in candidates:
        if all(0 <= c < n for c in col):  # sanity check
            k = max(col) + 1 if col else 0
            if k < min_colors:
                min_colors = k
                best_color = col

    # Validate and fix if necessary
    def is_valid(color):
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    return False
        return True

    if not is_valid(best_color):
        # Fallback to greedy on degree order
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
        best_color = greedy_color(order)

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_color[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_color[i] = unique_colors[c]

    return best_color

