def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        # Validate binary entries (0 or 1) for matrix
        valid = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            is_matrix = False

    # Convert to adjacency list and compute degrees
    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
        degree = [len(graph[i]) for i in range(n)]
    else:
        graph = adj
        degree = [len(adj[i]) for i in range(n)]

    # Helper: DSATUR with bitmask optimization
    def dsatur():
        colored = [-1] * n
        saturation = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        color_count = 0

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_count = saturation[v].bit_count()
                if sat_count > best_sat:
                    best_sat = sat_count
                    best_v = v
                    best_deg = sum(1 for u in graph[v] if u in uncolored)
                elif sat_count == best_sat:
                    deg_uncolored = sum(1 for u in graph[v] if u in uncolored)
                    if deg_uncolored > best_deg:
                        best_deg = deg_uncolored
                        best_v = v
                    elif deg_uncolored == best_deg:
                        if random.random() < 0.5:
                            best_v = v
            v = best_v
            if v == -1:  # Should not happen
                break

            # Find smallest available color (mex)
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colored[v] = c
            if c >= color_count:
                color_count = c + 1

            # Update saturation of neighbors
            for u in graph[v]:
                if colored[u] == -1:
                    saturation[u] |= (1 << c)
            uncolored.remove(v)
        return colored

    # Helper: RLF (Recursive Largest First)
    def rlf():
        colored = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build independent set for this color
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            independent_set.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = set(uncolored) - {v}
            W = set()
            for u in list(U):
                if any(w in graph[u] for w in independent_set):
                    W.add(u)
                    U.remove(u)
            # Grow independent set
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = sum(1 for w in graph[u] if w in W)
                    deg_U = sum(1 for w in graph[u] if w in U)
                    if score > best_score or (score == best_score and deg_U < best_deg_U):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                if best_u == -1:
                    break  # Should not happen
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in graph[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent set
            for v in independent_set:
                colored[v] = color
            color += 1
            uncolored -= independent_set
        return colored

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering (smallest-last)
        degrees = degree[:]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # Should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in graph[v]:
                if u in remaining:
                    d = degrees[u]
                    buckets[d].remove(u)
                    degrees[u] -= 1
                    buckets[degrees[u]].append(u)
                    if degrees[u] < ptr:
                        ptr = degrees[u]
        # Color in reverse order (largest-last first)
        colored = [-1] * n
        for v in reversed(order):
            used = 0
            for u in graph[v]:
                if colored[u] != -1:
                    used |= (1 << colored[u])
            c = 0
            while used & (1 << c):
                c += 1
            colored[v] = c
        return colored

    # Helper: Kempe chain swap for (a,b)
    def kempe_swap(colored, a, b, v):
        # Returns new coloring after swapping a and b in the component of v, or None if invalid
        stack = [v]
        visited = set()
        component = set()
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            if colored[node] not in (a, b):
                return None  # Should not happen if called correctly
            component.add(node)
            for nb in graph[node]:
                if colored[nb] in (a, b) and nb not in visited:
                    stack.append(nb)
        # Check if swap is safe: no neighbor outside component has color a or b that would conflict
        # Actually, Kempe swap always preserves validity, so we can just swap
        new_colored = colored[:]
        for node in component:
            if new_colored[node] == a:
                new_colored[node] = b
            else:
                new_colored[node] = a
        return new_colored

    # Helper: Try to eliminate a color class using Kempe chains
    def eliminate_color(colored, k):
        # Try to eliminate color k-1
        if k <= 0:
            return colored, k
        # Vertices with color k-1
        color_class = [v for v in range(n) if colored[v] == k-1]
        if not color_class:
            return colored, k
        # Try to recolor each vertex in the class
        for v in color_class:
            cv = colored[v]
            # Try direct reassignment to a lower color
            for c in range(k-1):
                conflict = False
                for u in graph[v]:
                    if colored[u] == c:
                        conflict = True
                        break
                if not conflict:
                    # Move v to color c
                    colored[v] = c
                    break
            else:
                # Direct reassignment failed, try Kempe chains
                for c in range(k-1):
                    # Try Kempe swap between cv and c
                    new_colored = kempe_swap(colored, cv, c, v)
                    if new_colored is not None:
                        # Check if after swap, v has color c (it should)
                        if new_colored[v] == c:
                            colored = new_colored
                            break
                else:
                    continue  # Kempe swap didn't work for any c
                break  # Successfully recolored v
            # If we successfully recolored v, check if color k-1 is now empty
            if any(colored[u] == k-1 for u in range(n)):
                continue  # Still some vertices with color k-1
            else:
                # Color k-1 is eliminated, compact colors
                # Map colors: 0..k-2 stay, k-1 gone
                # Actually, we just need to return that we eliminated one color
                return colored, k-1
        # If we couldn't eliminate the color, return as is
        return colored, k

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        candidates.append(c2)
