    try:
        c3 = smallest_last()
        candidates.append(c3)
    except Exception:
        pass

    # If no candidates, fallback to simple greedy
    if not candidates:
        colored = [-1] * n
        for v in range(n):
            used = 0
            for u in graph[v]:
                if colored[u] != -1:
                    used |= (1 << colored[u])
            c = 0
            while used & (1 << c):
                c += 1
            colored[v] = c
        candidates.append(colored)

    # Select best candidate (fewest colors)
    best_colored = None
    best_k = float('inf')
    for col in candidates:
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_colored = col
    colored = best_colored[:]

    # Iterative color reduction using Kempe chains
    improved = True
    while improved and best_k > 0:
        improved = False
        new_colored, new_k = eliminate_color(colored, best_k)
        if new_k < best_k:
            colored = new_colored
            best_k = new_k
            improved = True

    # Validate and ensure consecutive colors
    # Verify proper coloring
    for u in range(n):
        for v in graph[u]:
            if u < v and colored[u] == colored[v]:
                # Conflict, should not happen, but fallback to DSATUR
                colored = dsatur()
                break
        else:
            continue
        break

    # Compact color indices to be consecutive starting from 0
    if n > 0:
        unique_colors = sorted(set(colored))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        colored = [mapping[c] for c in colored]

    return colored

