def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = (len(adj) > 0 and len(adj[0]) == len(adj) and
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    # Build neighbor list and bitmask adjacency
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper functions
    def get_degree(v, colored_mask):
        return (bit_adj[v] & ~colored_mask).bit_count()

    def get_saturation(v, color_mask):
        # color_mask: list of bitmasks for each color class
        sat = 0
        for mask in color_mask:
            if mask & bit_adj[v]:
                sat |= mask
        return sat.bit_count()

    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    def compact_colors(coloring):
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        colored_mask = 0  # bitmask of colored vertices
        # Precompute degrees for tie-breaking
        degrees = [len(neighbors[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if coloring[v] == -1:
                    sat = get_saturation(v, [0]*n)  # dummy, will compute properly below
                    # Recompute saturation properly
                    neighbor_colors = 0
                    for u in neighbors[v]:
                        if coloring[u] != -1:
                            neighbor_colors |= (1 << coloring[u])
                    sat = neighbor_colors.bit_count()
                    deg = get_degree(v, colored_mask)
                    if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                       (sat == best_sat and deg == best_deg and v > best_v):
                        best_sat = sat
                        best_deg = deg
                        best_v = v

            v = best_v
            # Find smallest available color
            neighbor_colors = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
            colored_mask |= (1 << v)

        return compact_colors(coloring)

    # Recursive Largest First (RLF)
    def rlf():
        coloring = [-1] * n
        uncolored_mask = (1 << n) - 1  # bitmask of uncolored vertices
        color = 0

        while uncolored_mask:
            # Build independent set for this color
            independent_set = 0
            # Choose vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            um = uncolored_mask
            while um:
                lsb = um & -um
                i = (lsb.bit_length() - 1)
                deg = get_degree(i, uncolored_mask)
                if deg > max_deg:
                    max_deg = deg
                    v = i
                um -= lsb

            if v == -1:  # should not happen
                break

            independent_set |= (1 << v)
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to independent_set (ineligible)
            U = uncolored_mask & ~(bit_adj[v]) & ~(1 << v)  # not adjacent to v and not v
            W = uncolored_mask & bit_adj[v]  # adjacent to v

            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                max_w_neighbors = -1
                min_u_deg = -1
                um = U
                while um:
                    lsb = um & -um
                    u = (lsb.bit_length() - 1)
                    w_neighbors = (bit_adj[u] & W).bit_count()
                    u_deg = get_degree(u, U)  # degree in U subgraph
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and u_deg < min_u_deg) or \
                       (w_neighbors == max_w_neighbors and u_deg == min_u_deg and u > best_u):
                        max_w_neighbors = w_neighbors
                        min_u_deg = u_deg
                        best_u = u
                    um -= lsb

                u = best_u
                independent_set |= (1 << u)
                # Move u from U to independent set, update U and W
                U &= ~(1 << u)
                # Add neighbors of u that are in U to W
                newly_in_W = bit_adj[u] & U
                W |= newly_in_W
                U &= ~newly_in_W  # remove those from U

            # Assign color to independent_set
            im = independent_set
            while im:
                lsb = im & -im
                v = (lsb.bit_length() - 1)
                coloring[v] = color
                im -= lsb

            # Next color: remaining uncolored are W
            uncolored_mask = W
            color += 1

        return compact_colors(coloring)

    # Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        # Build degeneracy ordering
        remaining = [(i, len(neighbors[i])) for i in range(n)]
        order = []
        # We'll simulate removal by maintaining current degrees
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n

        for _ in range(n):
            # Find vertex with minimum degree among non-removed
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    deg[u] -= 1

        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

        return compact_colors(coloring)

    # Kempe chain-based color reduction
    def reduce_colors_kempe(coloring):
        # Try to eliminate the highest color class
        max_color = max(coloring) if coloring else -1
        if max_color <= 0:
            return coloring

        # Try to remove colors from max_color down to 1
        for target_color in range(max_color, 0, -1):
            # Get vertices with target_color
            target_vertices = [i for i in range(n) if coloring[i] == target_color]
            if not target_vertices:
                continue

            # Try to recolor each target vertex
            made_change = False
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        neighbor_colors |= (1 << coloring[u])

                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        # Direct move possible
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v can be swapped in (target_color, c) Kempe chain
                    # We'll do BFS to find the Kempe chain component containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    # Only traverse vertices with color target_color or c
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in neighbors[node]:
                            if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                visited[nb] = True
                                queue.append(nb)

                    # Check if swapping colors in component is valid
                    # After swap, target_color becomes c and c becomes target_color
                    # We need to ensure no neighbor of any node in component has conflicting color
                    valid_swap = True
                    for node in component:
                        new_color = c if coloring[node] == target_color else target_color
                        for nb in neighbors[node]:
                            if coloring[nb] == new_color:
                                valid_swap = False
                                break
                        if not valid_swap:
                            break

                    if valid_swap:
                        # Perform the swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        made_change = True
                        break
                if made_change:
                    break

            if not made_change:
                # Could not eliminate this color, try next lower target color
                continue
            else:
                # Successfully changed something, restart from highest color
                # Compact and try again
                coloring = compact_colors(coloring)
                return reduce_colors_kempe(coloring)

        # If we couldn't eliminate any color, compact and return
        return compact_colors(coloring)

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            neighbor_colors = 0
            for u in neighbors[i]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[i] = c
        candidates.append(compact_colors(coloring))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: max(x) + 1 if x else 0)

    # Apply Kempe chain reduction to try to improve
    try:
        improved = reduce_colors_kempe(best[:])  # work on a copy
        if is_valid_coloring(improved) and (max(improved) + 1 < max(best) + 1):
            best = improved
    except:
        pass

    # Final validation and compacting
    best = compact_colors(best)
    if not is_valid_coloring(best):
        # Last resort: simple greedy
        coloring = [-1] * n
        for i in range(n):
            neighbor_colors = 0
            for u in neighbors[i]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[i] = c
        best = compact_colors(coloring)

    return best

