def color_graph(adj: list[list[int]]) -> list[int]:
    # ----- Input Normalization -----
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect format: adjacency matrix if square and binary
    is_matrix = (
        len(adj[0]) == n and
        all(isinstance(x, int) and x in (0, 1) for row in adj for x in row)
    )

    # Build adjacency list and bitmask representation
    if is_matrix:
        neighbors = [
            [v for v in range(n) if adj[u][v] == 1] for u in range(n)
        ]
    else:
        neighbors = [list(lst) for lst in adj]  # copy

    # Bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # ----- Helper: Coloring Validation -----
    def is_valid_coloring(colors):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # ----- Helper: Number of Colors Used -----
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # ----- Helper: First-Fit Greedy Coloring -----
    def greedy_coloring(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = colors[v]
                if c != -1:
                    used |= 1 << c
            # Find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # ----- Helper: DSATUR with Degree Tie-Breaking -----
    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[u]) for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            best = -1
            best_sat = -1
            best_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                d = uncolored_deg[u]
                if s > best_sat or (s == best_sat and d > best_deg) or \
                   (s == best_sat and d == best_deg and u > best):
                    best_sat = s
                    best_deg = d
                    best = u
            u = best
            uncolored.remove(u)

            # Assign smallest available color
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c

            # Update saturation and degrees of uncolored neighbors
            for v in neighbors[u]:
                if v in uncolored:
                    sat[v] |= 1 << c
                    uncolored_deg[v] -= 1
        return colors

    # ----- Helper: RLF (Recursive Largest First) -----
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda u: sum(1 for w in neighbors[u] if w in uncolored))
            independent_set = {v}
            # Candidates: uncolored and not adjacent to any in independent_set
            # Not eligible: adjacent to at least one in independent_set
            candidates = uncolored - {v} - set()
            for w in neighbors[v]:
                if w in uncolored:
                    candidates.discard(w)
            ineligible = set()
            for w in neighbors[v]:
                if w in uncolored:
                    ineligible.add(w)

            # Greedily add vertices to independent_set
            while candidates:
                # Select u in candidates maximizing |N(u) ∩ ineligible|
                best_u = -1
                best_score = -1
                best_deg_in_candidates = None
                for u in candidates:
                    # count neighbors in ineligible
                    score = 0
                    for w in neighbors[u]:
                        if w in ineligible:
                            score += 1
                    # tie-break: min degree in candidates subgraph
                    deg_in_cand = sum(1 for w in neighbors[u] if w in candidates)
                    if score > best_score or (score == best_score and deg_in_cand < best_deg_in_candidates) or \
                       (score == best_score and deg_in_cand == best_deg_in_candidates and u > best_u):
                        best_score = score
                        best_deg_in_candidates = deg_in_cand
                        best_u = u
                u = best_u
                independent_set.add(u)
                candidates.remove(u)
                # Move neighbors of u from candidates to ineligible
                for w in neighbors[u]:
                    if w in candidates:
                        candidates.remove(w)
                        ineligible.add(w)
            # Assign color to all in independent_set
            for u in independent_set:
                colors[u] = color
                uncolored.remove(u)
            color += 1
        return colors

    # ----- Helper: Smallest-Last Ordering (Degeneracy) -----
    def smallest_last():
        # Core decomposition: repeatedly remove min degree vertex
        deg = [len(neighbors[u]) for u in range(n)]
        removed = [False] * n
        order = []
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[deg[u]].append(u)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            u = buckets[ptr].pop()
            removed[u] = True
            order.append(u)
            # Decrease degree of neighbors
            for v in neighbors[u]:
                if not removed[v]:
                    d = deg[v]
                    deg[v] -= 1
                    if d < len(buckets):
                        buckets[d].append(v)
                    if deg[v] < ptr:
                        ptr = deg[v]
        # Color in reverse removal order
        return greedy_coloring(order[::-1])

    # ----- Helper: Kempe Chain Swap for Color Reduction -----
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Vertices with target_color
            verts = [u for u in range(n) if colors[u] == target_color]
            if not verts:
                continue

            changed = True
            while changed and verts:
                changed = False
                # Try to recolor each vertex in target_color
                for u in verts[:]:  # iterate over copy
                    if colors[u] != target_color:
                        continue  # already recolored
                    # Try direct reassignment to a lower color
                    neighbor_colors = set()
                    for v in neighbors[u]:
                        c = colors[v]
                        if c != -1:
                            neighbor_colors.add(c)
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            colors[u] = c
                            changed = True
                            verts.remove(u)
                            break
                    if changed:
                        continue
                    # Try Kempe chain swap with each lower color
                    for c in range(target_color):
                        # Skip if u already has color c (shouldn't happen)
                        if colors[u] == c:
                            continue
                        # Build (c, target_color)-Kempe chain containing u
                        # Only if u has color target_color
                        stack = [u]
                        visited = set()
                        component = set()
                        while stack:
                            x = stack.pop()
                            if x in visited:
                                continue
                            visited.add(x)
                            if colors[x] == c or colors[x] == target_color:
                                component.add(x)
                                for y in neighbors[x]:
                                    if colors[y] == c or colors[y] == target_color:
                                        if y not in visited:
                                            stack.append(y)
                        # Check if swapping this component frees color c for u
                        # After swap, u would get color c
                        # We need to ensure no neighbor of u has color c after swap
                        conflict = False
                        for v in neighbors[u]:
                            if v in component:
                                # v gets swapped: target_color -> c
                                new_color_v = c
                            else:
                                new_color_v = colors[v]
                            if new_color_v == c:
                                conflict = True
                                break
                        if not conflict:
                            # Perform swap: c <-> target_color in component
                            for x in component:
                                if colors[x] == c:
                                    colors[x] = target_color
                                elif colors[x] == target_color:
                                    colors[x] = c
                            changed = True
                            if u in verts:
                                verts.remove(u)
                            break  # break color loop after successful swap
            # If no vertices left with target_color, we can eliminate this color
            if not any(colors[u] == target_color for u in range(n)):
                # Remap colors > target_color down by 1
                for u in range(n):
                    if colors[u] > target_color:
                        colors[u] -= 1
                # Break out to restart from new highest color
                return kempe_reduce(colors)
        return colors

    # ----- Generate Candidate Colorings -----
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # Fallback: simple greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        c4 = greedy_coloring(order)
        if is_valid_coloring(c4):
            candidates.append(c4)

    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        k = num_colors(col)
        if k < best_k:
            best_k = k
            best = col

    if best is None:
        # Ultimate fallback: assign all distinct colors
        best = list(range(n))

    # ----- Apply Kempe Chain Reduction -----
    try:
        reduced = kempe_reduce(best[:])
        if is_valid_coloring(reduced):
            best = reduced
    except:
        pass

    # ----- Final Validation and Compaction -----
    # Ensure colors are consecutive starting from 0
    used = set(best)
    mapping = {old: new for new, old in enumerate(sorted(used)))
    compacted = [mapping[c] for c in best]

    # Double-check validity (should be valid by construction)
    if not is_valid_coloring(compacted):
        # Last resort: greedy by DSATUR order
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        compacted = greedy_coloring(order)
        used = set(compacted)
        mapping = {old: new for new, old in enumerate(sorted(used))]
        compacted = [mapping[c] for c in compacted]

    return compacted

