            coloring[v] = c
            # Update used_colors for neighbors
            for u in neighbors[v]:
                used_colors[u].add(c)

        k = max(coloring) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]

