            coloring[v] = c
            for u in neighbors[v]:
                used_colors[u].add(c)
        best_coloring = coloring
        best_k = max(coloring) + 1 if n > 0 else 0

    # Local 1-opt improvement: try to reduce color count by recoloring
    # Try to eliminate the highest color class
    changed = True
