                    else:
                        # Revert if conflict (should not happen)
                        best_coloring[v] = high_color
            if changed:
                # After moving v, check if high color class is empty
                if not any(best_coloring[v] == high_color for v in range(n)):
                    best_k -= 1
                    # Compact colors: not necessary since we reduce best_k and reindex later
                    break
                else:
                    # Revert and try next vertex
                    best_coloring[v] = high_color
                    changed = False
        # If we couldn't eliminate the high color, try to reduce via Kempe-like swaps (simplified)
        if not changed and best_k > 0:
            # Attempt to swap colors to free up a color
            for v in range(n):
                c_v = best_coloring[v]
                if c_v == high_color:
