    # Compact colors to 0..best_k-1
    color_map = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        best_coloring[i] = color_map[c]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    if is_matrix:
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid(colors):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if colors[u] == colors[v]:
                        return False
        return True

    # Helper: number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if colors[u] != -1 and ((bit_adj[v] >> u) & 1):
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        # Precompute neighbor lists for speed
        neighbors = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if (bit_adj[u] >> v) & 1:
                    neighbors[u].append(v)

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturated[u]
                deg_u = sum(1 for w in neighbors[u] if w in uncolored)
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
                elif sat_u == max_sat and deg_u == max_deg and u < v:
                    v = u  # tie-break by index
            # Assign smallest available color
            used = 0
            for w in neighbors[v]:
                if colors[w] != -1:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for w in neighbors[v]:
                if w in uncolored:
                    saturated[w] += 1
        return colors

    # RLF: Recursive Largest First (independent set extraction)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        # Precompute neighbor lists
        neighbors = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if (bit_adj[u] >> v) & 1:
                    neighbors[u].append(v)
        while uncolored:
            # Build independent set S for this color
            S = set()
            # Choose vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: sum(1 for w in neighbors[x] if w in uncolored))
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                    U.remove(u)
            # Grow S from U
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in neighbors[u] if w in W)
                    deg_U = sum(1 for w in neighbors[u] if w in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_U < min_deg_U):
                        max_w_neighbors = w_neighbors
                        min_deg_U = deg_U
                        best_u = u
                    elif w_neighbors == max_w_neighbors and deg_U == min_deg_U and u < best_u:
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to S
            for v in S:
                colors[v] = color
            uncolored -= S
            color += 1
        return colors

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering (smallest last)
        remaining = set(range(n))
        order = []
        degrees = [0] * n
        for u in range(n):
            degrees[u] = sum(1 for v in range(n) if (bit_adj[u] >> v) & 1)
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degrees[u]].append(u)
        # Peeling
        for _ in range(n):
            # Find first non-empty bucket from low to high
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Decrease degree of neighbors
            for w in range(n):
                if (bit_adj[v] >> w) & 1 and w in remaining:
                    buckets[degrees[w]].remove(w)
                    degrees[w] -= 1
                    buckets[degrees[w]].append(w)
        # Reverse for coloring order
        order.reverse()
        return greedy_color(order)

    # Generate initial colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    # Keep the best (fewest colors)
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Kempe chain-based color reduction
    def kempe_reduce(colors, target_k):
        # Try to eliminate color classes from highest down
        for color_to_remove in range(target_k - 1, -1, -1):
            # Get vertices with this color
            verts = [v for v in range(n) if colors[v] == color_to_remove]
            if not verts:
                continue  # already empty
            made_progress = False
            for v in verts:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in range(n):
                    if (bit_adj[v] >> u) & 1 and colors[u] != -1:
                        neighbor_colors.add(colors[u])
                for c in range(color_to_remove):
                    if c not in neighbor_colors:
                        colors[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chains with each lower color
                for c in range(color_to_remove):
                    # Find the (c, color_to_remove)-Kempe chain containing v
                    # BFS to get component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1 and not visited[y]:
                                if colors[y] == c or colors[y] == color_to_remove:
                                    visited[y] = True
                                    queue.append(y)
                    # Check if we can swap: no neighbor of component has color c (except via chain)
                    can_swap = True
                    for x in component:
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1:
                                if colors[y] == c and y not in component:
                                    can_swap = False
                                    break
                        if not can_swap:
                            break
                    if can_swap:
                        # Swap colors c and color_to_remove in component
                        for x in component:
                            if colors[x] == c:
                                colors[x] = color_to_remove
                            elif colors[x] == color_to_remove:
                                colors[x] = c
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                # Cannot eliminate this color, stop reduction
                break
            # Remove empty color and shift higher colors down
            max_color = max(colors)
            for v in range(n):
                if colors[v] > color_to_remove:
                    colors[v] -= 1
            # Re-index: now colors are in [0, max_color-1]
        return colors

    # Apply Kempe reduction
    improved = kempe_reduce(best[:], k)
    if num_colors(improved) < k and is_valid(improved):
        best = improved
        k = num_colors(best)

    # Final validation and cleanup
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
        k = num_colors(best)
    # Ensure colors are consecutive starting from 0
    # Remap colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for v in range(n):
        c = best[v]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best[v] = unique_colors[c]
    return best

