def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect if input is adjacency matrix
    is_matrix = False
    if len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build neighbor list and bitmask adjacency
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue
                neighbors[i].append(j)
                bit_adj[i] |= (1 << j)
    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0
    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, then max degree, then min index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and uncolored_deg[u] > max_deg) or (s == max_sat and uncolored_deg[u] == max_deg and u < v):
                    max_sat = s
                    max_deg = uncolored_deg[u]
                    v = u
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color
    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # degree in induced subgraph of uncolored
            deg = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in neighbors[v]:
                    if u in uncolored:
                        deg[v] += 1
            # start with vertex of max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            # W: vertices adjacent to at least one in S
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in neighbors[u] if w in W)
                    deg_u = sum(1 for w in neighbors[u] if w in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or (w_neighbors == max_w_neighbors and deg_u == min_deg_u and u < best_u):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
