            best_coloring = col
    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find color classes
            classes = {}
            for v in range(n):
                c = col[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            if not classes:
                break
            max_color = max(classes.keys())
            # try to eliminate color classes from highest down
            for target_color in range(max_color, 0, -1):
                if target_color not in classes or not classes[target_color]:
                    continue
                # try to recolor each vertex in this class
                for v in classes[target_color]:
                    # try direct reassignment to a lower color
                    used = 0
                    for u in neighbors[v]:
                        cu = col[u]
                        if cu != -1:
                            used |= (1 << cu)
                    for c in range(target_color):
