                        mapping[c] = next_c
                        next_c += 1
                    col[v] = mapping[c]
        return col
    best_coloring = kempe_reduce(best_coloring)
    # Final validation (optional, but ensure correctness)
    # Verify no adjacent same color
    for u in range(n):
        for v in neighbors[u]:
            if u < v and col[u] == col[v]:
                # fallback to greedy with DSATUR if something went wrong
                return dsatur()
    # Ensure colors are consecutive
    used_colors = set(best_coloring)
    if used_colors:
        min_c = min(used_colors)
        max_c = max(used_colors)
        if min_c != 0 or max_c != len(used_colors) - 1:
            # remap
            mapping = {}
            next_c = 0
            for c in sorted(used_colors):
                mapping[c] = next_c
                next_c += 1
            best_coloring = [mapping[c] for c in best_coloring]
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == n:
        if all(isinstance(row, list) and len(row) == n for row in adj):
            if all(all(x in (0, 1) for x in row) for row in adj):
                is_matrix = True

    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = [j for j in range(n) if adj[i][j] == 1]
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Convert adjacency list to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to list if needed
    def finalize(coloring):
        # Ensure colors are 0..k-1 consecutive
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbor masks for fast saturation update
        colored_masks = [0] * n
        uncolored = set(range(n))

        # initial vertex: highest degree
        start = max(range(n), key=lambda x: len(adj_list[x]))
        colors[start] = 0
        uncolored.remove(start)
        # update saturation of neighbors
        mask_start = 1 << start
        for v in adj_list[start]:
            if colors[v] == -1:
                colored_masks[v] |= mask_start
                saturation[v] = 1

        while uncolored:
            # select vertex with max saturation, break ties by degree in uncolored subgraph, then random
            def select_vertex():
                max_sat = -1
                candidates = []
                for v in uncolored:
                    sat_v = saturation[v]
                    if sat_v > max_sat:
                        max_sat = sat_v
                        candidates = [v]
                    elif sat_v == max_sat:
                        candidates.append(v)
                if len(candidates) == 1:
                    return candidates[0]
                # tie-break by degree in uncolored subgraph
                max_deg = -1
                deg_candidates = []
                for v in candidates:
                    # count uncolored neighbors
                    deg = 0
                    for nb in adj_list[v]:
                        if nb in uncolored:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        deg_candidates = [v]
                    elif deg == max_deg:
                        deg_candidates.append(v)
                if len(deg_candidates) == 1:
                    return deg_candidates[0]
                return random.choice(deg_candidates)

            v = select_vertex()
            # compute forbidden colors from neighbors
            forbidden = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    forbidden |= (1 << colors[nb])
            # find smallest non-forbidden color
            c = 0
            while forbidden & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update saturation for uncolored neighbors
            mask_v = 1 << v
            for nb in adj_list[v]:
                if colors[nb] == -1:
                    # if this color is new to nb's neighbors
                    if not (colored_masks[nb] & mask_v):
                        colored_masks[nb] |= mask_v
                        saturation[nb] += 1
        return finalize(colors)

    # RLF: Recursive Largest First
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            def degree_in_uncolored(v):
                return sum(1 for nb in adj_list[v] if nb in uncolored)

            v_start = max(uncolored, key=degree_in_uncolored)
            independent_set = {v_start}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = set(uncolored)
            U.remove(v_start)
            W = set()
            for nb in adj_list[v_start]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)

            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                def score(u):
                    # count neighbors in W
                    w_count = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_count += 1
                    # degree in U
                    u_deg = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            u_deg += 1
                    return (w_count, -u_deg)  # maximize w_count, minimize u_deg

                u_star = max(U, key=score)
                independent_set.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star from U to W
                for nb in adj_list[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # assign color to independent_set
            for v in independent_set:
                colors[v] = color_idx
                uncolored.remove(v)
            color_idx += 1

        return finalize(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degrees = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order
        # buckets for degrees
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # pointer to current min degree
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            # update neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    d = degrees[nb]
                    if d > 0:
                        buckets[d].remove(nb)
                        degrees[nb] -= 1
                        buckets[degrees[nb]].append(nb)
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            forbidden = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    forbidden |= (1 << colors[nb])
            c = 0
            while forbidden & (1 << c):
                c += 1
            colors[v] = c
        return finalize(colors)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        best = coloring[:]
        improved = True
        # limit iterations to avoid timeout
        for _it in range(10):  # at most 10 reduction attempts
            if not improved:
                break
            improved = False
            k = num_colors(best)
            if k <= 1:
                break
            # target smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if best[v] == target_color]
            if not target_vertices:
                # should not happen, but compact anyway
                mapping = {c: c for c in range(k)}
                new_colors = [mapping[c] for c in best]
                best = finalize(new_colors)
                continue

            # Try to recolor each target vertex
            made_change = False
            for v in target_vertices:
                # Try direct reassignment to a lower color
                forbidden = 0
                for nb in adj_list[v]:
                    if best[nb] != -1:
                        forbidden |= (1 << best[nb])
                for c in range(target_color):  # try colors 0..k-2
                    if not (forbidden & (1 << c)):
                        # move v to color c
                        best[v] = c
                        made_change = True
                        break
                if made_change:
                    break

                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Build (target_color, c)-Kempe chain containing v
                    # BFS/DFS over vertices colored target_color or c
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if best[node] == target_color or best[node] == c:
                            component.add(node)
                            for nb in adj_list[node]:
                                if nb not in visited and (best[nb] == target_color or best[nb] == c):
                                    stack.append(nb)
                    # Check if swapping this component would free color c for v
                    # After swap, v would get color c (if it was target_color) or target_color (if it was c)
                    # Since v is target_color, after swap it becomes c.
                    # We need to ensure that no neighbor of v gets color c from the swap (i.e., no neighbor in component colored c)
                    # Actually, we need that after swap, v's neighbors do not have color c.
                    # Currently, neighbors of v may have color c or target_color.
                    # After swap: neighbors in component that were c become target_color, and those that were target_color become c.
                    # So we need that no neighbor of v is in the component and colored c (because after swap it becomes target_color, which is not c)
                    # Wait: we want v to become c. So we need that no neighbor of v has color c after swap.
                    # A neighbor u of v:
                    #   - if u not in component: color unchanged.
                    #   - if u in component:
                    #        if best[u] == c -> becomes target_color
                    #        if best[u] == target_color -> becomes c
                    # So after swap, a neighbor u in component that was target_color becomes c -> conflict if u adjacent to v.
                    # Therefore, we can swap only if there is no neighbor u of v in the component such that best[u] == target_color.
                    # Because those would become c and conflict with v's new color c.
                    safe = True
                    for nb in adj_list[v]:
                        if nb in component and best[nb] == target_color:
                            safe = False
                            break
                    if safe:
                        # perform swap
                        for node in component:
                            if best[node] == target_color:
                                best[node] = c
                            else:  # best[node] == c
                                best[node] = target_color
                        made_change = True
                        break
                if made_change:
                    break
            if made_change:
                improved = True
                # compact colors after change
                best = finalize(best)
            else:
                # cannot reduce further
                break
        return best

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        greedy = [0] * n
        for i in range(n):
            forbidden = 0
            for nb in adj_list[i]:
                if greedy[nb] != -1:  # but we are assigning in order, so check if colored
                    # Actually, we assign in order 0..n-1
                    pass
        # simple greedy in order
        colors = [-1] * n
        for i in range(n):
            forbidden = 0
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    forbidden |= (1 << colors[nb])
            c = 0
            while forbidden & (1 << c):
                c += 1
            colors[i] = c
        candidates.append(finalize(colors))

    # Choose best candidate (fewest colors)
    best_coloring = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best_coloring = kempe_reduce(best_coloring)
    # Final validation (should be valid)
    if not is_valid(best_coloring):
        # last resort: greedy ordering by degree
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            forbidden = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    forbidden |= (1 << colors[nb])
            c = 0
            while forbidden & (1 << c):
                c += 1
            colors[v] = c
        best_coloring = finalize(colors)
    return best_coloring

