import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bit masks
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                adj_list[i].append(j)
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return len(set(coloring)) if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                d = uncolored_deg[u]
                if s > max_sat or (s == max_sat and d > max_deg) or (s == max_sat and d == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = s
                    max_deg = d
                    v = u
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # degree in uncolored subgraph
            deg = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg[v] += 1
            # start with vertex of max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to S, W: vertices adjacent to S
            U = uncolored - {v} - set(adj_list[v])
            W = set(adj_list[v]) & uncolored
            while U:
                # select u in U with max neighbors in W, tie-break by min deg in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for nb in adj_list[u] if nb in W)
                    deg_u = sum(1 for nb in adj_list[u] if nb in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or (w_neighbors == max_w_neighbors and deg_u == min_deg_u and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(adj_list[i]) for i in range(n)]
        # bins for degree
        max_deg = max(deg) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            bins[deg[v]].append(v)
        # vertex status: 0=unprocessed, 1=processed
        status = [0] * n
        order = []
        # current min degree
        d = 0
        for _ in range(n):
            # find non-empty bin
            while d <= max_deg and not bins[d]:
                d += 1
            if d > max_deg:
                break
            v = bins[d].pop()
            status[v] = 1
            order.append(v)
            # update neighbors
            for u in adj_list[v]:
                if status[u] == 0:
                    # move u from bin[deg[u]] to bin[deg[u]-1]
                    if deg[u] < len(bins):
                        bins[deg[u]].remove(u)
                    deg[u] -= 1
                    if deg[u] < len(bins):
                        bins[deg[u]].append(u)
                    if deg[u] < d:
                        d = deg[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate initial candidates
    candidates = []
    start = time.time()
    # DSATUR
    col1 = dsatur()
    if is_valid(col1):
        candidates.append(col1)
    # RLF
    col2 = rlf()
    if is_valid(col2):
        candidates.append(col2)
    # Smallest-Last
    col3 = smallest_last()
    if is_valid(col3):
        candidates.append(col3)

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=count_colors) if candidates else None
    if best_coloring is None:
        # fallback: greedy by natural order
        best_coloring = greedy_color(list(range(n)))

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # vertices with target_color
        verts = [v for v in range(n) if coloring[v] == target_color]
        if not verts:
            return coloring, True  # already eliminated
        # Try to recolor each vertex
        for v in verts:
            used_by_neighbors = 0
            for u in adj_list[v]:
                c = coloring[u]
                if c != -1:
                    used_by_neighbors |= (1 << c)
            # try direct reassignment to a lower color
            for c in range(target_color):
                if not (used_by_neighbors & (1 << c)):
                    coloring[v] = c
                    break
            else:
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # BFS to find (c, target_color) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # check if any neighbor of component has color c (would cause conflict if swapped)
                    has_c_neighbor = False
                    for x in component:
                        for y in adj_list[x]:
                            if coloring[y] == c and y not in component:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            break
                    if not has_c_neighbor:
                        # swap colors c and target_color in component
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target_color
                            elif coloring[x] == target_color:
                                coloring[x] = c
                        # after swap, v now has color c
                        break
                else:
                    # could not recolor v
                    return coloring, False
        return coloring, True

    # Iteratively try to reduce colors
    k = count_colors(best_coloring)
    improved = True
    while improved and k > 0:
        improved = False
        # try to eliminate highest color class first (often smallest)
        for target_color in range(k-1, -1, -1):
            new_col, eliminated = eliminate_color_class(best_coloring.copy(), target_color)
            if eliminated:
                # compact colors: remap to 0..new_k-1
                mapping = {}
                next_c = 0
                for v in range(n):
                    c = new_col[v]
                    if c not in mapping:
                        mapping[c] = next_c
                        next_c += 1
                    new_col[v] = mapping[c]
                best_coloring = new_col
                k = count_colors(best_coloring)
                improved = True
                break  # restart from highest color after compacting

    # Final validation and compacting (ensure 0..k-1)
    if not is_valid(best_coloring):
        # last resort: greedy by degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best_coloring = greedy_color(order)
    # compact colors
    mapping = {}
    next_c = 0
    for v in range(n):
        c = best_coloring[v]
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
        best_coloring[v] = mapping[c]

    return best_coloring

