def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True
    # Build neighbor list and bitmask adjacency
    neighbors = []
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            row_neighbors = []
            mask = 0
            for j, val in enumerate(adj[i]):
                if val == 1:
                    row_neighbors.append(j)
                    mask |= (1 << j)
            neighbors.append(row_neighbors)
            bit_adj[i] = mask
    else:
        for i in range(n):
            row_neighbors = adj[i]
            mask = 0
            for j in row_neighbors:
                mask |= (1 << j)
            neighbors.append(row_neighbors)
            bit_adj[i] = mask

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            cu = colors[u]
            for v in neighbors[u]:
                if cu == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # Precompute degrees
        deg = [len(neighbors[i]) for i in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                # compute saturation: distinct colors in neighbors
                neighbor_colors = set()
                for u in neighbors[v]:
                    if colored[u]:
                        neighbor_colors.add(colors[u])
                sat = len(neighbor_colors)
                if sat > best_sat or (sat == best_sat and (deg[v] > best_deg or (deg[v] == best_deg and random.random() < 0.5))):
                    best_sat = sat
                    best_deg = deg[v]
                    best_v = v
            v = best_v
            # find smallest available color
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if colored[u]:
                    c = colors[u]
                    if c <= n:
                        used[c] = True
            for c in range(n + 1):
                if not used[c]:
                    colors[v] = c
                    break
            colored[v] = True
        return normalize(colors)

    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
                S.add(v)
                uncolored.remove(v)
            # partition remaining uncolored into U (no neighbor in S) and W (has neighbor in S)
            U = set()
            W = set()
            for x in uncolored:
                if any(y in S for y in neighbors[x]):
                    W.add(x)
                else:
                    U.add(x)
            # greedy expansion of S
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = len([y for y in neighbors[u] if y in W])
                    deg_U = len([y for y in neighbors[u] if y in U])
                    if score > best_score or (score == best_score and deg_U < best_deg_U):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u that are in U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
            # next round: uncolored becomes W (vertices adjacent to S)
            uncolored = W
        return normalize(colors)

    # Smallest-Last ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # we will repeatedly remove min degree vertex
        # use bucket queue for efficiency (n <= 100)
        # but simple O(n^2) is fine
        temp_deg = degrees[:]
        remaining_set = set(range(n))
        while remaining_set:
            # find vertex with min temp_deg in remaining_set
            v = min(remaining_set, key=lambda x: temp_deg[x])
            order.append(v)
            remaining_set.remove(v)
            for u in neighbors[v]:
                if u in remaining_set:
                    temp_deg[u] -= 1
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if colors[u] != -1:
                    c = colors[u]
                    if c <= n:
                        used[c] = True
            for c in range(n + 1):
                if not used[c]:
                    colors[v] = c
                    break
        return normalize(colors)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except Exception:
        pass
    # If no candidate (should not happen), fallback to greedy by index
    if not candidates:
        colors = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for u in neighbors[i]:
                if colors[u] != -1:
                    c = colors[u]
                    if c <= n:
                        used[c] = True
            for c in range(n + 1):
                if not used[c]:
                    colors[i] = c
                    break
        candidates.append(normalize(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_colors = best[:]
    k = num_colors(best_colors)

    # Iterative Kempe chain color reduction
    improved = True
    # We'll attempt to reduce colors as long as we can eliminate a color class
    while improved and k > 1:
        improved = False
        # Try to eliminate each color class from highest to lowest
        for target_color in range(k - 1, -1, -1):
            # collect vertices with this color
            target_vertices = [v for v in range(n) if best_colors[v] == target_color]
            if not target_vertices:
                continue
            # Try to recolor each vertex in this class
            made_change = False
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in neighbors[v]:
                    neighbor_colors.add(best_colors[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # recolor v to c
                        best_colors[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # We consider swapping colors target_color and c in the component containing v
                    # Only if v is not adjacent to any vertex of color c (otherwise swap would cause conflict immediately?)
                    # Actually, we can still try: we need to check that in the component, swapping doesn't cause conflict.
                    # Standard: find the (target_color, c)-Kempe chain of v; if in that component, there is no neighbor of v with color c,
                    # then swapping is safe.
                    # Build component via BFS/DFS
                    stack = [v]
                    visited = set()
                    component = set()
                    has_neighbor_of_color_c = False
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        component.add(node)
                        col = best_colors[node]
                        if col == target_color or col == c:
                            for nb in neighbors[node]:
                                if best_colors[nb] == target_color or best_colors[nb] == c:
                                    if nb not in visited:
                                        stack.append(nb)
                        # check if this node has a neighbor of color c (in original coloring)
                        # Actually, we need to know if any vertex in the component is adjacent to a vertex of color c outside the component?
                        # The condition for Kempe swap to be safe is that in the component, there is no vertex adjacent to a vertex of color c
                        # (because after swap, that vertex would become color c and conflict with its neighbor of color c).
                        # Instead, we can check: for any vertex in component, if it has a neighbor with color c that is not in the component, then swapping would cause conflict.
                        # So we can break early if we find such.
                    # We'll do a separate check: after collecting component, verify no vertex in component has a neighbor with color c outside component.
                    safe = True
                    for node in component:
                        for nb in neighbors[node]:
                            if best_colors[nb] == c and nb not in component:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # perform swap
                        for node in component:
                            if best_colors[node] == target_color:
                                best_colors[node] = c
                            elif best_colors[node] == c:
                                best_colors[node] = target_color
                        made_change = True
                        break
                if made_change:
                    break
            if made_change:
                improved = True
                # after making a change, break to restart the color reduction loop from highest color
                break
        # after attempting to eliminate a color, recompute k and normalize
        k = num_colors(best_colors)
        best_colors = normalize(best_colors)

    # Final validation (should be valid)
    if not is_valid_coloring(best_colors):
        # fallback to best candidate
        best_colors = best
    return best_colors

