                        best_score = nbrs_in_W
                        best_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbor_mask(u)
                to_remove = []
                for x in U:
                    if nbrs_u & (1 << x):
                        to_remove.append(x)
                for x in to_remove:
                    U.remove(x)
                    W.add(x)
