                    if u in remaining:
                        degree[u] -= 1
                        d = degree[u]
                        # move u to bucket d
                        # We don't actually move, just rely on degree array and re-check later
                        # Instead, we will rely on scanning buckets later; this is inefficient but n<=100
                        # For simplicity, we do nothing here; we will re-scan buckets by checking degree
                        pass
                u += 1
