    # Kempe chain swap for colors a and b, returns new coloring if swap performed, else None
    def kempe_swap(color, a, b, v):
        n = len(color)
        # Build component of v in (a,b) subgraph
        from collections import deque
        comp = set()
        q = deque([v])
        comp.add(v)
        while q:
            u = q.popleft()
            for w in range(n):
