    def normalize(coloring):
        if not coloring:
            return coloring
        unique = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            coloring[i] = unique[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
