            # find vertex in uncolored with max degree in induced subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                # degree in uncolored subgraph
                deg = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
            # build independent set S for this color
            S = {v}
            uncolored.remove(v)
            # W: vertices adjacent to S (ineligible)
            W = set()
            for w in adj_list[v]:
                if w in uncolored:
                    W.add(w)
            # U: uncolored vertices not adjacent to S (eligible)
            U = uncolored - W
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in U
                best_u = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    # count neighbors in W
                    nw = 0
                    for w in adj_list[u]:
                        if w in W:
                            nw += 1
                    # degree in U
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u) or (nw == max_nw and deg_u == min_deg_u and u < best_u):
                        max_nw = nw
                        min_deg_u = deg_u
                        best_u = u
                # add best_u to S
                S.add(best_u)
                uncolored.remove(best_u)
                # move best_u from U to ... and update W and U
                U.remove(best_u)
                # neighbors of best_u that are in U become ineligible (move to W)
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for u in S:
                color[u] = current_color
            current_color += 1
        return normalize(color)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    # remove u from bucket d
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    if d_new < len(buckets):
                        buckets[d_new].append(u)
                    else:
                        # extend buckets if needed (should not happen as degree decreases)
                        while len(buckets) <= d_new:
                            buckets.append([])
                        buckets[d_new].append(u)
                    if d_new < min_deg:
                        min_deg = d_new
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return normalize(color)

    # Kempe chain elimination
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (largest color index)
            max_color = max(col) if col else -1
            if max_color < 0:
                break
            # collect vertices by color
            color_classes = [[] for _ in range(max_color + 1)]
            for v in range(n):
                color_classes[col[v]].append(v)
            # try to eliminate color classes from highest to lowest
            for c in range(max_color, -1, -1):
                if not color_classes[c]:
                    continue
                # try to recolor each vertex in class c
                eliminated = True
                new_color_classes = [lst[:] for lst in color_classes]  # deep copy
                for v in color_classes[c]:
                    # try direct reassignment to a lower color
                    moved = False
                    for target in range(c):
                        # check if target color is available
                        conflict = False
                        for u in adj_list[v]:
                            if col[u] == target:
                                conflict = True
                                break
                        if not conflict:
                            # move v to target
                            new_color_classes[c].remove(v)
                            new_color_classes[target].append(v)
                            col[v] = target
                            moved = True
                            break
                    if moved:
                        continue
                    # try Kempe chain swap with each lower color
                    swapped = False
                    for target in range(c):
                        # if v already has target color after some swap, skip
                        if col[v] == target:
                            swapped = True
                            break
                        # check if v and any target-colored vertex are in same Kempe chain
                        # we only need to see if there's a path from v to a target-colored vertex using only colors c and target
                        # BFS/DFS on the subgraph of colors c and target
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        has_target = False
                        while queue:
                            node = queue.popleft()
                            if col[node] == target:
                                has_target = True
                                break
                            for nb in adj_list[node]:
                                if not visited[nb] and (col[nb] == c or col[nb] == target):
                                    visited[nb] = True
                                    queue.append(nb)
                        if not has_target:
                            # we can swap the component containing v
                            # recolor all nodes in the component: c <-> target
                            for node in range(n):
                                if visited[node]:
                                    if col[node] == c:
                                        col[node] = target
                                    elif col[node] == target:
                                        col[node] = c
                            # update new_color_classes accordingly
                            # rebuild from col for simplicity
                            new_color_classes = [[] for _ in range(max_color + 1)]
                            for node in range(n):
                                new_color_classes[col[node]].append(node)
                            # check if v is now in target class
                            if col[v] == target:
                                swapped = True
                                break
                    if swapped:
                        break
                    # if we couldn't move or swap v, then we cannot eliminate color c
                    eliminated = False
                    break
                if eliminated:
                    # successfully eliminated color c
                    changed = True
                    # compact colors: shift down all colors > c
                    for v in range(n):
                        if col[v] > c:
                            col[v] -= 1
                    break  # restart while loop as colors changed
                # if not eliminated, try next lower color class
            # if we went through all colors and none eliminated, break
        return normalize(col)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass
    # Fallback: greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        candidates.append(normalize(color))

    # Select best candidate (fewest colors)
    best = None
    best_colors = float('inf')
    for cand in candidates:
        num_colors = chromatic_number(cand)
        if num_colors < best_colors:
            best_colors = num_colors
            best = cand
    if best is None:
        best = [0] * n  # should not happen

    # Apply Kempe reduction to best candidate
    try:
        improved = kempe_reduce(best[:])
        if is_valid(improved):
            chrom_improved = chromatic_number(improved)
            chrom_original = chromatic_number(best)
            if chrom_improved < chrom_original:
                best = improved
    except Exception:
        pass

    # Final validation and normalization
    if not is_valid(best):
        # last resort: greedy sequential
        color = [0] * n
        for i in range(1, n):
            used = 0
            for j in adj_list[i]:
                if j < i:
                    used |= (1 << color[j])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        best = normalize(color)
    return normalize(best)

