        return greedy_color(reversed(order))

    # Helper: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-deg[x], x))
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    candidates.append(welsh_powell())

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate
        valid = True
        for u in range(n):
            for v in range(u + 1, n):
                if ((bit_adj[u] >> v) & 1) and col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col[:]

    # If no valid candidate (should not happen), fallback to greedy
    if best_color is None:
        best_color = greedy_color(list(range(n)))
        best_k = max(best_color) + 1 if n > 0 else 0

    # Compact colors to 0..k-1
    # Map used colors to consecutive integers
    used_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(used_colors)}
    compacted = [mapping[c] for c in best_color]

    # Kempe chain color reduction
    def kempe_reduction(color):
        nonlocal n, bit_adj
        # Try to eliminate color classes from highest downward
        changed = True
        while changed:
            changed = False
            # Find current number of colors
            k = max(color) + 1 if n > 0 else 0
            # Try to remove each color class, starting from largest color
            for target_color in range(k - 1, -1, -1):
                # Collect vertices with target_color
                targets = [v for v in range(n) if color[v] == target_color]
                if not targets:
                    continue
                # Try to recolor each target vertex
                removed = True
                for v in targets:
                    # Check if v can take any color < target_color
                    used = 0
                    for u in range(n):
                        if (bit_adj[v] >> u) & 1:
                            used |= (1 << color[u])
                    free = False
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            # Direct reassignment possible
                            color[v] = c
                            free = True
                            break
                    if free:
                        changed = True
                        continue  # v recolored, check next
                    # Try Kempe chain swap with each color c < target_color
                    swapped = False
                    for c in range(target_color):
                        if used & (1 << c):
                            # Both colors present in neighborhood, try Kempe chain
                            # Build component of color target_color and c containing v
                            from collections import deque
                            comp = set()
                            queue = deque([v])
                            comp.add(v)
                            while queue:
                                x = queue.popleft()
                                for y in range(n):
                                    if (bit_adj[x] >> y) & 1 and color[y] in (target_color, c) and y not in comp:
                                        comp.add(y)
                                        queue.append(y)
                            # Check if any neighbor of v with color c is NOT in this component
                            # i.e., is there a neighbor u of v with color c such that u not in comp?
                            has_external = False
                            for u in range(n):
                                if (bit_adj[v] >> u) & 1 and color[u] == c and u not in comp:
                                    has_external = True
                                    break
                            if not has_external:
                                # Swap colors in component: target_color <-> c
                                for x in comp:
                                    if color[x] == target_color:
                                        color[x] = c
                                    else:
                                        color[x] = target_color
                                changed = True
                                swapped = True
                                break
                    if swapped:
                        changed = True
                        break  # break color loop, restart while
                # If we managed to recolor all vertices of target_color, the color class is empty
                if not any(color[v] == target_color for v in range(n)):
                    # Compact colors above target_color down by one
                    for v in range(n):
                        if color[v] > target_color:
                            color[v] -= 1
                    changed = True
                    break  # break target_color loop, restart while
        return color

    # Apply Kempe reduction
    try:
        best_color = kempe_reduction(best_color)
    except:
        pass  # If anything goes wrong, keep the coloring

    # Final validation and compaction
    # Validate
    for u in range(n):
        for v in range(u + 1, n):
            if ((bit_adj[u] >> v) & 1) and best_color[u] == best_color[v]:
                # Fallback to greedy if invalid
                best_color = greedy_color(list(range(n)))
                break

    # Compact one last time
    used_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(used_colors)}
    best_color = [mapping[c] for c in best_color]

    return best_color

