def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect if input is adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Precompute degree and bitmasks
    degree = [len(adj_list[i]) for i in range(n)]
    bit_adj = [0] * n
    for i in range(n):
        for j in adj_list[i]:
            bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        unique = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        # saturation: list of sets of neighbor colors
        saturation = [set() for _ in range(n)]
        # uncolored set
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = len(saturation[v])
                if sat > best_sat or (sat == best_sat and degree[v] > best_deg):
                    best_sat = sat
                    best_deg = degree[v]
                    best_v = v
                elif sat == best_sat and degree[v] == best_deg:
                    if best_v == -1 or v < best_v:
                        best_v = v
            v = best_v

            # find smallest available color
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
            uncolored.remove(v)

            # update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u].add(c)
        return coloring

    # RLF: Recursive Largest First
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in adj_list[u] for w in independent_set):
                    U.remove(u)
                    W.add(u)

            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U-induced subgraph
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = -1
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for y in adj_list[u] if y in U)
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and u < best_u):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to independent_set
            for v in independent_set:
                coloring[v] = color
            uncolored -= independent_set
            color += 1
        return coloring

    # Smallest-Last ordering greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering (smallest-last)
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # We'll simulate peeling
        for _ in range(n):
            # find vertex with min degree in remaining
            v = min(remaining, key=lambda x: degrees[x])
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    degrees[u] -= 1
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = set()
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain elimination
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        coloring = coloring[:]  # work on a copy
        changed = True
        while changed:
            changed = False
            k = num_colors(coloring)
            if k <= 1:
                break
            # target smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # already compacted?
                coloring = compact_colors(coloring)
                continue

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = set()
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        used.add(coloring[u])
                for c in range(target_color):
                    if c not in used:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart after change

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # BFS/DFS to get component
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for neighbor in adj_list[node]:
                                if neighbor not in visited and (coloring[neighbor] == target_color or coloring[neighbor] == c):
                                    stack.append(neighbor)
                    # Check if inverting this component would free color c for v
                    # After swap, v would get color c (since it was target_color)
                    # We need to ensure that no neighbor of v gets color c from the swap
                    # Actually, inverting the component: target_color <-> c
                    # So neighbors of v that are in the component and colored c will become target_color
                    # and neighbors colored target_color will become c.
                    # We need that after swap, no neighbor of v has color c.
                    # Currently, neighbors of v that are in the component and colored c will become target_color (safe)
                    # Neighbors of v that are in the component and colored target_color will become c (conflict if adjacent to v)
                    # So we need that no neighbor of v in the component is colored target_color (because they would become c)
                    conflict = False
                    for u in adj_list[v]:
                        if u in component and coloring[u] == target_color:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:  # must be c
                                coloring[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            if not changed:
                # could not eliminate target color, break
                break
        return compact_colors(coloring)

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (shouldn't happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            used = set()
            for u in adj_list[i]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[i] = c
        candidates.append(coloring)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid(best):
        # last resort: greedy
        coloring = [-1] * n
        for i in range(n):
            used = set()
            for u in adj_list[i]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[i] = c
        best = compact_colors(coloring)
    else:
        best = compact_colors(best)

    return best

