def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = adj
        # Ensure symmetric and no self-loops (defensive)
        for i in range(n):
            adj_list[i] = [j for j in adj_list[i] if j != i and 0 <= j < n]
            adj_list[i] = list(set(adj_list[i]))

    # Build bitmask adjacency
    bit_adj = [0] * n
    for i in range(n):
        for j in adj_list[i]:
            bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to consecutive indices starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        unique = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets as bitmask for fast sat update
        neighbor_colors = [0] * n
        # degrees for tie-breaking
        deg = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    if sat[u] > max_sat or (sat[u] == max_sat and deg[u] > max_deg):
                        max_sat = sat[u]
                        max_deg = deg[u]
                        v = u
            if v == -1:  # should not happen
                break

            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # update saturation and neighbor colors for neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:
                    # if this color is new in u's neighborhood
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1
        return normalize(coloring)

    # RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # independent set for this color
            S = set()
            # vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and all(u not in adj_list[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}

            while U:
                # select u in U with max neighbors in W
                u_star = None
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    w_neighbors = len([w for w in adj_list[u] if w in W])
                    deg_U = len([x for x in adj_list[u] if x in U])
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_U < min_deg_U):
                        max_w_neighbors = w_neighbors
                        min_deg_U = deg_U
                        u_star = u
                if u_star is None:
                    break  # safety
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for nb in adj_list[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
            uncolored -= S

        return normalize(coloring)

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # core decomposition to get ordering
        degree = [len(adj_list[i]) for i in range(n)]
        # buckets for degrees
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].append(i)
        # vertex status: 0 = unprocessed, 1 = processed
        removed = [False] * n
        order = []
        # current min degree
        d = 0
        for _ in range(n):
            # find next non-empty bucket
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    # move u from bucket[degree[u]] to bucket[degree[u]-1]
                    old_deg = degree[u]
                    degree[u] -= 1
                    if degree[u] < old_deg:
                        buckets[degree[u]].append(u)
        # color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # already empty, compact
                coloring = [c if c < target_color else c - 1 for c in coloring]
                k -= 1
                continue

            # Try to recolor each target vertex
            for v in target_vertices[:]:  # copy list as we may modify
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        used_by_neighbors |= (1 << coloring[u])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart from highest color

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # If v already has a neighbor with color c, swapping may not help directly
                    # but we check if we can free color c for v by inverting a component
                    # Build the (target_color, c) Kempe chain component containing v
                    if coloring[v] != target_color:
                        continue  # should not happen, but safety
                    # BFS to get component
                    comp = []
                    stack = [v]
                    visited = [False] * n
                    visited[v] = True
                    while stack:
                        node = stack.pop()
                        comp.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                visited[nb] = True
                                stack.append(nb)
                    # Check if inverting this component would cause conflict
                    # Specifically, after swap, no neighbor of any node in comp should have the new color
                    valid = True
                    for node in comp:
                        new_color = c if coloring[node] == target_color else target_color
                        for nb in adj_list[node]:
                            if coloring[nb] == new_color:
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        # perform swap
                        for node in comp:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        improved = True
                        break
                if improved:
                    break

            # If we couldn't recolor any vertex in target_color, we cannot reduce further
            if not improved:
                break

            # If target color class is now empty, compact and continue
            if not any(coloring[v] == target_color for v in range(n)):
                coloring = [c if c < target_color else c - 1 for c in coloring]
                k -= 1
                improved = True  # allow another round

        return normalize(coloring)

    # Run all heuristics with time budget
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # List of heuristics to run
    heuristics = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last)
    ]

    for name, heuristic in heuristics:
        if time.time() - start_time > 0.04:  # leave time for Kempe
            break
        coloring = heuristic()
        if not is_valid(coloring):
            # fallback: should not happen, but just in case
            continue
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring

    # If no heuristic succeeded (should not happen), use greedy
    if best_coloring is None:
        coloring = [-1] * n
        for i in range(n):
            used = 0
            for j in adj_list[i]:
                if coloring[j] != -1:
                    used |= (1 << coloring[j])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[i] = c
        best_coloring = normalize(coloring)

    # Apply Kempe chain reduction to try to improve
    if time.time() - start_time < 0.045:
        best_coloring = kempe_reduce(best_coloring)
        # Final validation
        if not is_valid(best_coloring):
            # fallback to DSATUR if Kempe broke validity
            best_coloring = dsatur()

    return best_coloring

