import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and bitmask
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count colors
    def count_colors(color):
        if not color:
            return 0
        return max(color) + 1

    # Helper: validate coloring
    def is_valid(color):
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(color):
        mapping = {}
        next_color = 0
        for c in color:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in color]

    best_color = None
    best_k = float('inf')
    start_time = time.time()

    # 1. DSATUR
    if time.time() - start_time < 0.05:
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max sat, tie-break by max uncolored_deg, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and uncolored_deg[u] > max_deg) or (s == max_sat and uncolored_deg[u] == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = s
                    max_deg = uncolored_deg[u]
                    v = u
            # assign smallest available color
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        color = compact_colors(color)
        if is_valid(color):
            k = count_colors(color)
            if k < best_k:
                best_k = k
                best_color = color[:]

    # 2. RLF
    if time.time() - start_time < 0.05:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored and time.time() - start_time < 0.05:
            # degree in uncolored subgraph
            deg = {}
            for u in uncolored:
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg[u] = cnt
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg[x])
            # independent set for color c
            S = {v}
            # U: vertices not adjacent to S
            U = {u for u in uncolored if u != v and all(w not in adj_list[u] for w in S)}
            # W: vertices adjacent to S
            W = {u for u in uncolored if u not in S and u not in U}
            while U and time.time() - start_time < 0.05:
                # select u in U with max neighbors in W
                best_u = -1
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_U = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_U < min_deg_U) or (w_neighbors == max_w_neighbors and deg_U == min_deg_U and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        color = compact_colors(color)
        if is_valid(color):
            k = count_colors(color)
            if k < best_k:
                best_k = k
                best_color = color[:]

    # 3. Smallest-Last (degeneracy ordering)
    if time.time() - start_time < 0.05:
        # compute smallest-last ordering
        degrees = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = degrees[v]
        # pointer to current min non-empty bucket
        min_deg = 0
        for _ in range(n):
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    d = pos[u]
                    buckets[d].remove(u)
                    d -= 1
                    pos[u] = d
                    buckets[d].append(u)
                    if d < min_deg:
                        min_deg = d
        # color in reverse order
        color = greedy_color(order[::-1])
        color = compact_colors(color)
        if is_valid(color):
            k = count_colors(color)
            if k < best_k:
                best_k = k
                best_color = color[:]

    # If no valid coloring found (should not happen), fallback to simple greedy
    if best_color is None:
        best_color = greedy_color(list(range(n)))
        best_color = compact_colors(best_color)

    # Kempe chain color reduction
    if time.time() - start_time < 0.05:
        improved = True
        while improved and time.time() - start_time < 0.05:
            improved = False
            k = count_colors(best_color)
            if k <= 1:
                break
            # target smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if best_color[v] == target_color]
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    c = best_color[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # move v to color c
                        best_color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already can take color c, skip (should have been caught above)
                    used = 0
                    for u in adj_list[v]:
                        if best_color[u] == c:
                            used |= (1 << c)
                    if not (used & (1 << c)):
                        continue
                    # BFS to find (v, c)-Kempe chain starting from v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (best_color[nb] == target_color or best_color[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # check if any neighbor of the component has color c (would cause conflict if swapped)
                    has_c_neighbor = False
                    for node in component:
                        for nb in adj_list[node]:
                            if best_color[nb] == c and nb not in component:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            break
                    if not has_c_neighbor:
                        # swap colors in component
                        for node in component:
                            if best_color[node] == target_color:
                                best_color[node] = c
                            elif best_color[node] == c:
                                best_color[node] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                best_color = compact_colors(best_color)

    # Final validation and compaction
    if not is_valid(best_color):
        # last resort: greedy
        best_color = greedy_color(list(range(n)))
    best_color = compact_colors(best_color)
    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:  # safety
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur():
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # colored_neighbors[v] = bitmask of colored neighbors
        colored_neighbors = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat_u = saturation[u]
                    # degree in uncolored subgraph: neighbors that are also uncolored
                    deg_u = 0
                    for w in adj_list[u]:
                        if coloring[w] == -1:
                            deg_u += 1
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                       (sat_u == max_sat and deg_u == max_deg and u > v):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color for v
            neighbor_colors = 0
            for w in adj_list[v]:
                if coloring[w] != -1:
                    neighbor_colors |= (1 << coloring[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation and colored_neighbors for neighbors
            for w in adj_list[v]:
                if coloring[w] == -1:  # only uncolored neighbors
                    # If this is the first time color c appears in w's neighborhood
                    if not (colored_neighbors[w] & (1 << c)):
                        colored_neighbors[w] |= (1 << c)
                        saturation[w] += 1
        return coloring

    # RLF algorithm (Largest First Independent Set)
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for this color
            S = []  # independent set
            # Start with vertex of max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                deg_u = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        deg_u += 1
                if deg_u > max_deg:
                    max_deg = deg_u
                    v = u
            if v == -1:
                break
            S.append(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = uncolored - {v}
            W = set()
            for w in adj_list[v]:
                if w in U:
                    U.remove(w)
                    W.add(w)

            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    # Count neighbors in W
                    nw = 0
                    for w in adj_list[u]:
                        if w in W:
                            nw += 1
                    # Tie-break: min degree in G[U]
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u) or \
                       (nw == max_nw and deg_u == min_deg_u and u < u_star):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                if u_star == -1:
                    break  # should not happen
                S.append(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to all in S
            for u in S:
                coloring[u] = color
            color += 1
            # Next uncolored set is W (vertices adjacent to S)
            uncolored = W

        return coloring

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        degree = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order
        # We'll use bucket sort for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u] and degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            for w in adj_list[v]:
                if not removed[w]:
                    degree[w] -= 1
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for w in adj_list[v]:
                if coloring[w] != -1:
                    neighbor_colors |= (1 << coloring[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, a, b, v):
        # Returns new coloring after swapping a<->b in the component of v, or None if invalid
        # We'll do BFS to find the component
        from collections import deque
        queue = deque([v])
        visited = set([v])
        component = []
        while queue:
            u = queue.popleft()
            component.append(u)
            for w in adj_list[u]:
                if w not in visited and coloring[w] in (a, b):
                    visited.add(w)
                    queue.append(w)
        # Create new coloring by swapping a and b in component
        new_coloring = coloring[:]
        for u in component:
            if new_coloring[u] == a:
                new_coloring[u] = b
            elif new_coloring[u] == b:
                new_coloring[u] = a
        # Validate (should be valid by Kempe's theorem, but check)
        if is_valid_coloring(new_coloring):
            return new_coloring
        return None

    # Try to eliminate the smallest color class using Kempe chains
    def reduce_colors(coloring):
        if not coloring:
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target_color = k - 1
        # Get vertices with target color
        target_vertices = [i for i in range(n) if coloring[i] == target_color]
        if not target_vertices:
            return compact_colors(coloring)  # already compact

        changed = True
        while changed and num_colors(coloring) > 0:
            changed = False
            k_curr = num_colors(coloring)
            target_color = k_curr - 1
            target_vertices = [i for i in range(n) if coloring[i] == target_color]
            if not target_vertices:
                coloring = compact_colors(coloring)
                continue

            # Try to recolor each target vertex
            for v in target_vertices[:]:  # iterate over copy
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for w in adj_list[v]:
                    if coloring[w] != -1:
                        neighbor_colors |= (1 << coloring[w])
                for c in range(target_color):  # try colors 0..target_color-1
                    if not (neighbor_colors & (1 << c)):
                        # Direct move possible
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart while loop after change

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Try swapping in the (c, target_color) Kempe chain of v
                    new_coloring = kempe_swap(coloring, c, target_color, v)
                    if new_coloring is not None:
                        # Check if this move reduces the number of vertices in target_color
                        # Count target_color in new coloring
                        count_target = sum(1 for i in range(n) if new_coloring[i] == target_color)
                        if count_target < len(target_vertices):
                            coloring = new_coloring
                            changed = True
                            break
                if changed:
                    break
            if changed:
                coloring = compact_colors(coloring)

        return compact_colors(coloring)

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to simple greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            neighbor_colors = 0
            for w in adj_list[v]:
                if coloring[w] != -1:
                    neighbor_colors |= (1 << coloring[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        candidates.append(coloring)

    # Select best candidate (fewest colors)
    best = None
    min_colors = float('inf')
    for cand in candidates:
        if not is_valid_coloring(cand):
            continue
        k = num_colors(cand)
        if k < min_colors:
            min_colors = k
            best = cand

    if best is None:
        # Last resort: assign all to color 0 (only valid for edgeless graph)
        best = [0] * n
        # If there are edges, this is invalid, but we have no choice
        # However, our fallback should have produced a valid coloring

    # Apply Kempe chain reduction to try to improve
    try:
        improved = reduce_colors(best[:])
        if is_valid_coloring(improved):
            k_orig = num_colors(best)
            k_imp = num_colors(improved)
            if k_imp < k_orig:
                best = improved
    except:
        pass

    # Final compact and validation
    best = compact_colors(best)
    # Ensure validity (should be, but double-check)
    if not is_valid_coloring(best):
        # As a last resort, use DSATUR again (should be valid)
        best = dsatur()
        best = compact_colors(best)

    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for i in range(n):
            if len(adj[i]) != n:
                all_binary = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].add(j)

    # Ensure symmetry (undirected graph)
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)

    # Trivial cases
    if n == 1:
        return [0]
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Precompute degrees
        deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        # Saturation sets: for each vertex, set of colors used by colored neighbors
        sat_sets = [set() for _ in range(n)]

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat = len(sat_sets[v])
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)

            if max_sat == -1:  # All uncolored have saturation 0
                # Choose vertex with max degree in uncolored subgraph
                max_deg = -1
                for v in uncolored:
                    d = len(neighbors[v] & uncolored)
                    if d > max_deg:
                        max_deg = d
                        candidates = [v]
                    elif d == max_deg:
                        candidates.append(v)
                # If still tie, choose random
                v = random.choice(candidates) if candidates else next(iter(uncolored))
            else:
                # Tie-break by degree in uncolored subgraph
                max_deg = -1
                for v in candidates:
                    d = len(neighbors[v] & uncolored)
                    if d > max_deg:
                        max_deg = d
                        best_v = v
                    elif d == max_deg:
                        # Random tie-break among those with same saturation and degree
                        if random.random() < 0.5:  # Simple random choice
                            best_v = v
                else:
                    # If loop didn't set best_v (should not happen), pick first
                    best_v = candidates[0]
                v = best_v

            # Assign smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)

            # Update saturation sets for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat_sets[u].add(c)

        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v} - neighbors[v]
            W = neighbors[v] & uncolored

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = len(neighbors[u] & W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in G[U]
                        deg_u = len(neighbors[u] & U)
                        deg_best = len(neighbors[best_u] & U) if best_u is not None else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break  # Should not happen if U non-empty
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u that are in U to W
                nbrs_in_U = neighbors[best_u] & U
                W.update(nbrs_in_U)
                U -= nbrs_in_U

            # Assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1

        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use a list of buckets for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            # Find unremoved vertex with min degree
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break  # Should not happen
            order.append(v)
            removed[v] = True
            # Decrease degree of neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    deg[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last),
        ("Welsh-Powell", welsh_powell)
    ]

    for name, func in strategies:
        try:
            coloring = func()
            if is_valid(coloring):
                k = num_colors(coloring)
                if k < best_k:
                    best_k = k
                    best_coloring = coloring[:]
        except Exception:
            continue

    # If no valid coloring found (should not happen), fall back to greedy with random order
    if best_coloring is None:
        order = list(range(n))
        random.shuffle(order)
        best_coloring = greedy_color(order)
        best_k = num_colors(best_coloring)
        # Ensure validity (should be by construction)
        if not is_valid(best_coloring):
            # Last resort: assign each vertex a unique color
            best_coloring = list(range(n))
            best_k = n

    # Compact colors: ensure colors are 0..k-1 without gaps
    if best_coloring:
        # Map colors to consecutive integers
        unique_colors = sorted(set(best_coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_coloring = [mapping[c] for c in best_coloring]

    # Final validation and return
    if not is_valid(best_coloring):
        # As a safety, return a valid coloring (may not be optimal)
        best_coloring = greedy_color(list(range(n)))
        # Compact again
        if best_coloring:
            unique_colors = sorted(set(best_coloring))
            mapping = {old: new for new, old in enumerate(unique_colors)}
            best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

