                S.add(best_u)
                U.remove(best_u)
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to S
            for v in S:
                color[v] = current_color
                uncolored.remove(v)
