    # 4. Kempe chain color reduction
    if time.time() - start_time < time_limit and best_coloring is not None:
        coloring = best_coloring[:]
        improved = True
        while improved and time.time() - start_time < time_limit:
            improved = False
            k = num_colors(coloring)
            if k <= 1:
                break
            # Target the smallest color class (highest index)
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Should not happen, but compact just in case
                coloring = compact_colors(coloring)
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_colors = set()
                for u in adj_list[v]:
                    used_colors.add(coloring[u])
                for c in range(target_color):
                    if c not in used_colors:
                        # Move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Skip if v already has color c (shouldn't happen)
                    if coloring[v] == c:
                        continue
                    # Find the (c, target_color) Kempe chain containing v
                    # We'll do BFS to get the component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if this component has no vertex of color c that is adjacent to a vertex outside the component with color target_color?
