                    # We want to free target_color for v? Actually, we want to move v from target_color to c.
                    # After swap, v will have color c. We need to ensure no conflict.
                    # Since we only swap within the component, and the component is induced by {c, target_color},
                    # after swap, it's still valid.
                    # However, we want to know if after swap, v is no longer target_color (it becomes c) and we don't introduce new target_color elsewhere?
                    # Actually, we are trying to eliminate target_color. We want to recolor v away from target_color.
                    # If we swap the component, v will become c (since it was target_color), and all c in component become target_color.
                    # So the number of target_color vertices may increase or decrease.
                    # We want to reduce the count of target_color.
                    # Instead, we can try: if the component does NOT contain any vertex of color c that is adjacent to a vertex of color target_color outside the component? 
                    # Actually, the standard way to eliminate a color is: for a vertex v of color k, if there exists a color c < k such that in the Kempe chain of (c,k) starting from v, 
                    # the component does not contain any vertex of color c that is adjacent to a vertex of color k outside the component? 
                    # This is getting complex.
                    # Simpler: attempt the swap and see if the number of target_color vertices decreases.
                    # But we must maintain validity.
                    # Since swapping a Kempe chain preserves validity, we can do it and then check if we reduced the target_color count.
                    # However, we want to do it greedily.
                    # Let's try: swap the component and see if the number of vertices with target_color in the component decreases.
                    # Original: in component, count_c = number of c, count_k = number of k (target_color)
                    # After swap: count_c becomes count_k, count_k becomes count_c.
                    # So the change in target_color count is (count_c - count_k) in the component.
                    # We want this to be negative (i.e., count_c < count_k) so that total target_color decreases.
                    count_c = 0
                    count_k = 0
                    for node in component:
                        if coloring[node] == c:
                            count_c += 1
                        elif coloring[node] == target_color:
                            count_k += 1
                    if count_c < count_k:
                        # Swapping reduces the number of target_color vertices
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # Compact colors after improvement
                coloring = compact_colors(coloring)
            else:
                # Could not reduce this round
                break
        # Final compact
        coloring = compact_colors(coloring)
        if is_valid(coloring):
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring[:]

    # Ensure validity and compactness
    if best_coloring is None or not is_valid(best_coloring):
        # Last resort: greedy by degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = greedy_color(order)
        best_coloring = compact_colors(coloring)
    else:
        best_coloring = compact_colors(best_coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Colors a graph using the smallest-last ordering (degeneracy ordering) heuristic.
    The algorithm iteratively removes the vertex of minimum degree from the remaining graph,
    then colors vertices in reverse removal order using the smallest available color (First-Fit).
    This guarantees a coloring using at most d+1 colors, where d is the graph's degeneracy.

    Args:
        adj: Graph representation as adjacency matrix (list of lists of 0/1) or adjacency list.

    Returns:
        A list of integers representing the color of each vertex (0-indexed, consecutive).
    """
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            if is_matrix:
                for val in row:
                    if val not in (0, 1):
                        is_matrix = False
                        break
            if not is_matrix:
                break

    # Build adjacency list and degree array
    if is_matrix:
        adj_list = []
        deg = [0] * n
        for u in range(n):
            neighbors = []
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors.append(v)
            adj_list.append(neighbors)
            deg[u] = len(neighbors)
    else:
        adj_list = adj
        deg = [len(neighbors) for neighbors in adj_list]

    # Handle edgeless graph
    if all(d == 0 for d in deg):
        return [0] * n

    # Smallest-last ordering: repeatedly remove min-degree vertex
    removed = [False] * n
    order = []  # removal order (first removed first in list)
    current_deg = deg[:]  # current degrees in remaining graph

    for _ in range(n):
        # Find unremoved vertex with minimum current degree
        min_deg = math.inf
        v = -1
        for u in range(n):
            if not removed[u] and current_deg[u] < min_deg:
                min_deg = current_deg[u]
                v = u
        if v == -1:  # Should not happen, but safety
            break
        removed[v] = True
        order.append(v)
        # Decrease degree of unremoved neighbors
        for u in adj_list[v]:
            if not removed[u]:
                current_deg[u] -= 1

    # Color in reverse removal order (last removed first)
    color = [-1] * n
    # Process vertices in reverse order: from last removed to first removed
    for v in reversed(order):
        # Find smallest color not used by colored neighbors
        used = [False] * (n + 1)  # n+1 is safe upper bound
        for u in adj_list[v]:
            if color[u] != -1:  # if neighbor is colored
                used[color[u]] = True
        c = 0
        while c <= n and used[c]:
            c += 1
        color[v] = c

    # Compact colors to 0..k-1 if necessary
    unique_colors = set(color)
    if unique_colors == set(range(len(unique_colors))):
        return color
    else:
        mapping = {}
        sorted_colors = sorted(unique_colors)
        for new_c, old_c in enumerate(sorted_colors):
            mapping[old_c] = new_c
        return [mapping[c] for c in color]

