def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect input type: adjacency matrix or adjacency list
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        # Adjacency list
        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)

    # Trivial cases
    if n == 1:
        return [0]
    if all(bit_adj[i] == 0 for i in range(n)):
        return [0] * n

    # Precompute degrees
    degree = [bit_adj[i].bit_count() for i in range(n)]

    # DSATUR with custom tie-breaking: sum of degrees of uncolored neighbors
    def dsatur():
        color = [-1] * n
        # Saturation: for each vertex, bitmask of colors used by its colored neighbors
        saturation = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by sum of degrees of uncolored neighbors
            best_v = -1
            best_sat = -1
            best_tie = -1
            for v in range(n):
                if color[v] != -1:
                    continue
                sat_v = saturation[v].bit_count()
                if sat_v > best_sat:
                    best_sat = sat_v
                    best_v = v
                    # Compute tie-breaker: sum of degrees of uncolored neighbors
                    tie_val = 0
                    neighbors = bit_adj[v]
                    u = 0
                    while neighbors:
                        if neighbors & 1:
                            if color[u] == -1:
                                tie_val += degree[u]
                        neighbors >>= 1
                        u += 1
                    best_tie = tie_val
                elif sat_v == best_sat:
                    # Compute tie-breaker: sum of degrees of uncolored neighbors
                    tie_val = 0
                    neighbors = bit_adj[v]
                    u = 0
                    while neighbors:
                        if neighbors & 1:
                            if color[u] == -1:
                                tie_val += degree[u]
                        neighbors >>= 1
                        u += 1
                    if tie_val > best_tie:
                        best_tie = tie_val
                        best_v = v
            v = best_v

            # Find smallest available color (mex)
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

            # Update saturation of uncolored neighbors
            neighbors = bit_adj[v]
            u = 0
            while neighbors:
                if neighbors & 1:
                    if color[u] == -1:
                        saturation[u] |= (1 << c)
                neighbors >>= 1
                u += 1

        return color

    # Run DSATUR
    best_coloring = dsatur()
    best_k = max(best_coloring) + 1 if best_coloring else 0

    # Try to improve via Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal best_k
        k = max(coloring) + 1 if coloring else 0
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            vertices = [i for i in range(n) if coloring[i] == target_color]
            if not vertices:
                continue

            # Try to recolor each vertex in this class
            made_change = False
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                neighbors = bit_adj[v]
                u = 0
                while neighbors:
                    if neighbors & 1:
                        if coloring[u] != -1:
                            neighbor_colors |= (1 << coloring[u])
                    neighbors >>= 1
                    u += 1
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        # Direct reassignment possible
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break

                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Check if v can be swapped via (target_color, c) Kempe chain
                    # We'll do BFS to find the Kempe chain component containing v in colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        neighbors = bit_adj[node]
                        u = 0
                        while neighbors:
                            if neighbors & 1:
                                if coloring[u] == target_color or coloring[u] == c:
                                    if not visited[u]:
                                        visited[u] = True
                                        queue.append(u)
                            neighbors >>= 1
                            u += 1
                    # Check if any neighbor of the component has color c (would cause conflict if we swap)
                    has_conflict = False
                    for node in component:
                        neighbors = bit_adj[node]
                        u = 0
                        while neighbors:
                            if neighbors & 1:
                                if coloring[u] == c and u not in component:
                                    has_conflict = True
                                    break
                            neighbors >>= 1
                            u += 1
                        if has_conflict:
                            break
                    if not has_conflict:
                        # Perform swap: target_color <-> c in the component
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        made_change = True
                        break
                if made_change:
                    break
            if made_change:
                # After a change, rebuild coloring and try again from highest color
                return kempe_reduce(coloring)

        # If we eliminated the highest color, compact
        if target_color == k-1 and not any(coloring[i] == k-1 for i in range(n)):
            # Relabel colors to be consecutive
            color_map = {}
            next_color = 0
            for i in range(n):
                if coloring[i] not in color_map:
                    color_map[coloring[i]] = next_color
                    next_color += 1
                coloring[i] = color_map[coloring[i]]
            return kempe_reduce(coloring)

        return coloring

    # Apply Kempe reduction
    improved = kempe_reduce(best_coloring[:])
    improved_k = max(improved) + 1 if improved else 0
    if improved_k < best_k:
        best_coloring = improved
        best_k = improved_k

    # Validate and ensure consecutive colors
    # Validation (can be skipped for speed, but included for correctness)
    for u in range(n):
        neighbors = bit_adj[u]
        v = 0
        while neighbors:
            if neighbors & 1:
                if best_coloring[u] == best_coloring[v]:
                    # In case of invalid coloring, fall back to greedy
                    break
            neighbors >>= 1
            v += 1

    # Compact colors to 0..k-1
    color_map = {}
    next_color = 0
    for i in range(n):
        if best_coloring[i] not in color_map:
            color_map[best_coloring[i]] = next_color
            next_color += 1
        best_coloring[i] = color_map[best_coloring[i]]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Convert input to adjacency list if needed
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n and all(x in (0, 1) for row in adj for x in row):
        graph = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        graph = [list(neigh) for neigh in adj]

    # Ensure no self-loops and symmetric (undirected)
    for i in range(n):
        if i in graph[i]:
            graph[i].remove(i)
        for j in graph[i]:
            if i not in graph[j]:
                graph[j].append(i)

    # Remove duplicates
    for i in range(n):
        graph[i] = list(set(graph[i]))

    if n == 1:
        return [0]

    # Precompute degree for tie-breaking
    degree = [len(graph[i]) for i in range(n)]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in graph[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor colors as bitmask for efficiency
        neighbor_colors = [0] * n
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex: max saturation, then max degree in uncolored subgraph, then random
            candidates = []
            max_sat = -1
            for v in uncolored:
                if saturation[v] > max_sat:
                    max_sat = saturation[v]
                    candidates = [v]
                elif saturation[v] == max_sat:
                    candidates.append(v)

            if max_sat == -1:  # all uncolored, pick max degree
                v = max(uncolored, key=lambda x: degree[x])
            else:
                # break tie by degree in uncolored subgraph
                v = max(candidates, key=lambda x: sum(1 for u in graph[x] if u in uncolored))

            # Assign smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

            # Update neighbors
            for u in graph[v]:
                if color[u] == -1:  # if neighbor uncolored
                    # update saturation and neighbor color bitmask
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
            uncolored.remove(v)
        return color

    # 2. RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0

        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in graph[x] if u in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v} - set(graph[v])
            W = set(graph[v]) & uncolored

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in G[U]
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for x in graph[u] if x in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = sum(1 for x in graph[u] if x in U)
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_in_U = sum(1 for x in graph[u] if x in U)
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u that are in U to W
                for nb in graph[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree_in_remaining = degree[:]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree_in_remaining[v]].append(v)

        for _ in range(n):
            # Find first non-empty bucket from low to high
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
            if i > max_deg:
                break  # should not happen
            v = buckets[i].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in graph[v]:
                if u in remaining:
                    d = degree_in_remaining[u]
                    buckets[d].remove(u)
                    degree_in_remaining[u] -= 1
                    buckets[degree_in_remaining[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if is_valid(col):
                k = count_colors(col)
                if k < best_k:
                    best_k = k
                    best_coloring = col[:]
        except Exception:
            continue

    # Fallback: greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        best_coloring = greedy_color(order)
        best_k = count_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Try to eliminate the last color class
        while True:
            k = max(coloring) + 1 if coloring else 0
            if k <= 1:
                break
            # Find vertices with color k-1
            last_color_vertices = [v for v in range(n) if coloring[v] == k-1]
            if not last_color_vertices:
                break

            # Try to recolor each vertex in last color class
            removed = False
            for v in last_color_vertices:
                # Check if v can take any color < k-1 directly
                neighbor_colors = set()
                for u in graph[v]:
                    if coloring[u] < k-1:
                        neighbor_colors.add(coloring[u])
                for c in range(k-1):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        removed = True
                        break
                if removed:
                    break

                # Try Kempe chains with each color < k-1
                for c in range(k-1):
                    # Find the Kempe chain component of v in colors {c, k-1}
                    # We'll try to swap if the component does not contain any vertex of color c that is adjacent to a vertex of color k-1 (other than possibly v)
                    # Standard approach: if the component of v in (c, k-1) does not contain a neighbor of v colored c, then we can swap
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in graph[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == k-1):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of v with color c is in the component
                    conflict = False
                    for u in graph[v]:
                        if coloring[u] == c and u in component:
                            conflict = True
                            break
                    if not conflict:
                        # Swap colors c and k-1 in the component
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = k-1
                            elif coloring[x] == k-1:
                                coloring[x] = c
                        removed = True
                        break
                if removed:
                    break

            if not removed:
                break  # cannot eliminate this color

            # Compact colors: reindex to 0..k-2
            # Build mapping from old colors to new
            used_colors = set(coloring)
            mapping = {}
            next_c = 0
            for col in sorted(used_colors):
                mapping[col] = next_c
                next_c += 1
            for i in range(n):
                coloring[i] = mapping[coloring[i]]

        return coloring

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring[:])

    # Final validation and compacting
    if not is_valid(best_coloring):
        # Last resort: greedy by degree
        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        best_coloring = greedy_color(order)

    # Ensure colors are consecutive starting from 0
    used = set(best_coloring)
    mapping = {old: new for new, old in enumerate(sorted(used))]
    best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

import math
import random
import time
from collections import deque

def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Solve the vertex graph coloring problem with a hybrid approach:
    1. Convert input to adjacency list and bitmask representation for efficiency.
    2. Apply multiple heuristics: DSATUR, RLF, Welsh-Powell, and a BFS-based bipartite layering heuristic.
    3. Use Kempe chain swaps to reduce the number of colors.
    4. Return the best valid coloring found within the time limit.
    """
    start_time = time.time()
    time_limit = 0.045  # 45 ms to leave room for overhead

    # Handle trivial cases
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            cu = colors[u]
            for v in adj_list[u]:
                if v > u:  # Check each edge once
                    if cu == colors[v]:
                        return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: convert to dense color indices (0..k-1)
    def compact_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # Heuristic 1: DSATUR with bitmask optimization
    def dsatur():
        colors = [-1] * n
        # Precompute degrees for tie-breaking
        degrees = [len(adj_list[u]) for u in range(n)]
        # Track saturation: for each vertex, bitmask of colors used by neighbors
        neighbor_colors = [0] * n
        # Set of uncolored vertices
        uncolored = set(range(n))

        for _ in range(n):
            if time.time() - start_time > time_limit:
                break
            # Select vertex with max saturation degree, break ties by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = neighbor_colors[v].bit_count()
                deg = degrees[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                   (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update neighbors' saturation
            for u in adj_list[v]:
                if u in uncolored:
                    neighbor_colors[u] |= (1 << c)
        return compact_colors(colors)

    # Heuristic 2: Recursive Largest First (RLF)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored and time.time() - start_time <= time_limit:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # Compute degrees in the uncolored subgraph
            deg_in_uncolored = {}
            for v in uncolored:
                cnt = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        cnt += 1
                deg_in_uncolored[v] = cnt
            # Pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: deg_in_uncolored[x])
            independent_set = {v}
            to_remove = {v}
            # Partition: U = vertices not adjacent to any in S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for u in adj_list[v]:
                if u in uncolored:
                    W.add(u)
            # U = uncolored - {v} - W
            U = U - W
            # While U not empty, add vertices that maximize |N(u) ∩ W|
            while U and time.time() - start_time <= time_limit:
                best_u = -1
                best_score = -1
                best_deg_u = float('inf')
                for u in U:
                    # Score: number of neighbors in W
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    # Tie-break: min degree in G[U]
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or \
                       (score == best_score and deg_u == best_deg_u and random.random() < 0.5):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                to_remove.add(u)
                # Move u from U to W, and move its neighbors from U to W
                U.remove(u)
                W.add(u)
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
            uncolored -= to_remove
            color_idx += 1
        return compact_colors(colors)

    # Heuristic 3: Welsh-Powell (largest degree first)
    def welsh_powell():
        # Order by degree descending
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            if time.time() - start_time > time_limit:
                break
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Heuristic 4: BFS-based bipartite layering (for bipartite subgraph)
    def bfs_bipartite_layering():
        colors = [-1] * n
        # We'll try to 2-color as much as possible using BFS, then color remaining with DSATUR
        uncolored = set(range(n))
        while uncolored and time.time() - start_time <= time_limit:
            start = next(iter(uncolored))
            # BFS to get connected component
            component = []
            q = deque([start])
            visited = set([start])
            while q:
                u = q.popleft()
                component.append(u)
                for v in adj_list[u]:
                    if v in uncolored and v not in visited:
                        visited.add(v)
                        q.append(v)
            # Try to 2-color this component
            color_comp = {}
            is_bipartite = True
            q = deque([start])
            color_comp[start] = 0
            while q and is_bipartite:
                u = q.popleft()
                for v in adj_list[u]:
                    if v in component:
                        if v not in color_comp:
                            color_comp[v] = 1 - color_comp[u]
                            q.append(v)
                        elif color_comp[v] == color_comp[u]:
                            is_bipartite = False
                            break
            if is_bipartite:
                # Assign colors 0 and 1 within this component
                for u in component:
                    colors[u] = color_comp[u]
                uncolored -= set(component)
            else:
                # If not bipartite, we'll color it later with another heuristic
                # For now, just remove it from uncolored to avoid infinite loop
                # But we need to color it, so we break and let other heuristics handle
                break
        # Color remaining uncolored vertices with DSATUR (limited to them)
        if uncolored and time.time() - start_time <= time_limit:
            # Create subgraph induced by uncolored
            sub_n = len(uncolored)
            if sub_n > 0:
                mapping = {v: i for i, v in enumerate(sorted(uncolored))}
                inv_mapping = {i: v for v, i in mapping.items()}
                sub_adj = [[] for _ in range(sub_n)]
                for v in uncolored:
                    i = mapping[v]
                    for u in adj_list[v]:
                        if u in uncolored:
                            j = mapping[u]
                            sub_adj[i].append(j)
                # Run DSATUR on subgraph
                sub_colors = dsatur_sub(sub_adj, time_limit - (time.time() - start_time), start_time)
                # Map back
                for i, c in enumerate(sub_colors):
                    orig_v = inv_mapping[i]
                    colors[orig_v] = c
        return compact_colors(colors)

    # Helper for DSATUR on subgraph (used in bfs_bipartite_layering)
    def dsatur_sub(sub_adj, local_time_limit, start_time):
        n_sub = len(sub_adj)
        if n_sub == 0:
            return []
        sub_bit_adj = [0] * n_sub
        for u in range(n_sub):
            for v in sub_adj[u]:
                sub_bit_adj[u] |= (1 << v)
        colors = [-1] * n_sub
        degrees = [len(sub_adj[u]) for u in range(n_sub)]
        neighbor_colors = [0] * n_sub
        uncolored = set(range(n_sub))
        for _ in range(n_sub):
            if time.time() - start_time > local_time_limit:
                break
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = neighbor_colors[v].bit_count()
                deg = degrees[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                   (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            for u in sub_adj[v]:
                if u in uncolored:
                    neighbor_colors[u] |= (1 << c)
        return compact_colors(colors)

    # Run all heuristics
    candidates = []
    for heuristic in [dsatur, rlf, welsh_powell, bfs_bipartite_layering]:
        if time.time() - start_time > time_limit:
            break
        try:
            col = heuristic()
            if is_valid_coloring(col):
                candidates.append(col)
        except Exception:
            continue

    # If no valid candidate, fall back to simple greedy
    if not candidates:
        order = list(range(n))
        colors = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        candidates.append(compact_colors(colors))

    # Select the candidate with the fewest colors
    best_coloring = min(candidates, key=num_colors)

    # Apply Kempe chain swaps to reduce colors
    def kempe_reduce(colors):
        if time.time() - start_time > time_limit:
            return colors
        # Make a copy to work on
        cur_colors = colors[:]
        k = num_colors(cur_colors)
        improved = True
        # Try to eliminate color classes from highest to lowest
        while improved and k > 0 and time.time() - start_time <= time_limit:
            improved = False
            # Target the highest color class (k-1)
            target_color = k - 1
            vertices = [v for v in range(n) if cur_colors[v] == target_color]
            if not vertices:
                # This color is already unused, compact and continue
                cur_colors = compact_colors(cur_colors)
                k = num_colors(cur_colors)
                continue
            # Try to recolor each vertex in the target color class
            for v in vertices:
                if time.time() - start_time > time_limit:
                    break
                # Try direct reassignment to a lower color
                used_by_neighbors = set()
                for u in adj_list[v]:
                    if cur_colors[u] != -1:
                        used_by_neighbors.add(cur_colors[u])
                for c in range(target_color):
                    if c not in used_by_neighbors:
                        # Move v to color c
                        cur_colors[v] = c
                        improved = True
                        break
                if improved:
                    # After moving one vertex, break to restart the scan
                    break
                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    if time.time() - start_time > time_limit:
                        break
                    # Check if v is in a Kempe chain of (target_color, c) that does not include any other vertex of target_color?
                    # We'll try to swap the component containing v in the subgraph of colors {target_color, c}
                    # Build the component
                    stack = [v]
                    visited = set([v])
                    component = set()
                    # We'll traverse only vertices with color target_color or c
                    while stack:
                        node = stack.pop()
                        component.add(node)
                        for nb in adj_list[node]:
                            if nb not in visited and (cur_colors[nb] == target_color or cur_colors[nb] == c):
                                visited.add(nb)
                                stack.append(nb)
                    # In this component, swap target_color <-> c
                    # After swap, check if any vertex in the component that was target_color becomes c, and vice versa.
                    # We want to know if after swap, the target_color class loses at least one vertex and does not gain any.
                    # Count how many vertices in component are currently target_color and c
                    count_target = sum(1 for node in component if cur_colors[node] == target_color)
                    count_c = sum(1 for node in component if cur_colors[node] == c)
                    # After swap, these counts exchange.
                    # The target_color class will lose count_target and gain count_c.
                    # So net change in target_color class: -count_target + count_c
                    # We want this to be negative (so we lose more than we gain) or at least not increase and we remove v.
                    # Actually, we want to eliminate the target_color class entirely, so we need to move all its vertices.
                    # But for now, we check if this swap reduces the number of vertices in target_color class.
                    if count_target > count_c:
                        # This swap reduces the number of vertices in target_color class
                        # Perform the swap
                        for node in component:
                            if cur_colors[node] == target_color:
                                cur_colors[node] = c
                            elif cur_colors[node] == c:
                                cur_colors[node] = target_color
                        improved = True
                        break
                if improved:
                    break
            # After attempting to recolor vertices of target_color, check if the class is empty
            if not any(cur_colors[v] == target_color for v in range(n)):
                # Remove this color by compacting
                cur_colors = compact_colors(cur_colors)
                k = num_colors(cur_colors)
                improved = True  # We reduced the number of colors
        return cur_colors

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)

    # Final validation and compacting
    if not is_valid_coloring(best_coloring):
        # Last resort: simple greedy
        order = list(range(n))
        colors = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        best_coloring = compact_colors(colors)
    else:
        best_coloring = compact_colors(best_coloring)

    return best_coloring

