def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input type
    is_matrix = len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row)
    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = adj

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: get uncolored neighbors mask
    def uncolored_neighbors_mask(u, colored_mask):
        return bit_adj[u] & ~colored_mask

    # Helper: saturation degree (number of distinct colors in neighbors)
    def saturation_degree(u, coloring):
        mask = 0
        for v in neighbors[u]:
            if coloring[v] != -1:
                mask |= 1 << coloring[v]
        return mask.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        colored_mask = 0
        degree = [len(neighbors[i]) for i in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            candidates = []
            max_sat = -1
            for v in range(n):
                if coloring[v] == -1:
                    sat = saturation_degree(v, coloring)
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
            # Tie-break by degree (uncolored degree)
            if len(candidates) > 1:
                max_deg = -1
                best_v = candidates[0]
                for v in candidates:
                    deg = uncolored_neighbors_mask(v, colored_mask).bit_count()
                    if deg > max_deg:
                        max_deg = deg
                        best_v = v
                    elif deg == max_deg and v < best_v:
                        best_v = v
                v = best_v
            else:
                v = candidates[0]
            # Assign smallest available color
            used = 0
            for nb in neighbors[v]:
                if coloring[nb] != -1:
                    used |= 1 << coloring[nb]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            colored_mask |= 1 << v
        return coloring

    # RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color = 0
        remaining = set(range(n))
        while remaining:
            # Build independent set for this color
            S = set()
            # Start with vertex of max degree in remaining subgraph
            if not remaining:
                break
            v = max(remaining, key=lambda x: len([nb for nb in neighbors[x] if nb in remaining]))
            S.add(v)
            remaining.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in remaining if not any(nb in S for nb in neighbors[u])}
            W = remaining - U
            while U:
                # Select u in U with max neighbors in W
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = sum(1 for nb in neighbors[u] if nb in W)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and len([nb for nb in neighbors[u] if nb in U]) < (len([nb for nb in neighbors[best_u] if nb in U]) if best_u else float('inf'))):
                        max_w_neighbors = w_neighbors
                        best_u = u
                if best_u is None:
                    break
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in neighbors[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
            remaining = W
        return coloring

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        coloring = [-1] * n
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # We'll use a bucket-like approach but simple for n<=100
        temp_rem = set(remaining)
        temp_deg = degrees[:]
        while temp_rem:
            # Find vertex of minimum degree in current subgraph
            min_v = min(temp_rem, key=lambda v: sum(1 for nb in neighbors[v] if nb in temp_rem))
            order.append(min_v)
            temp_rem.remove(min_v)
            # Update degrees of neighbors
            for nb in neighbors[min_v]:
                if nb in temp_rem:
                    temp_deg[nb] -= 1
        # Color in reverse order
        for v in reversed(order):
            used = 0
            for nb in neighbors[v]:
                if coloring[nb] != -1:
                    used |= 1 << coloring[nb]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for (a,b)
    def kempe_swap(coloring, a, b, v):
        # Returns new coloring after swapping a and b in the component of v, or None if invalid
        if coloring[v] not in (a, b):
            return coloring  # No change if v not in either color
        stack = [v]
        visited = set()
        comp_color = coloring[v]
        target_color = b if comp_color == a else a
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            # Swap color
            coloring[u] = target_color if coloring[u] == comp_color else comp_color
            for nb in neighbors[u]:
                if coloring[nb] == comp_color and nb not in visited:
                    stack.append(nb)
        return coloring

    # Try to eliminate a color class using Kempe chains
    def reduce_colors(coloring):
        k = count_colors(coloring)
        if k <= 1:
            return coloring
        # Try from highest color down
        for target_color in range(k-1, 0, -1):
            # Get vertices with this color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex to a lower color
            made_change = False
            for v in verts:
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    conflict = False
                    for nb in neighbors[v]:
                        if coloring[nb] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Try to swap (target_color, c) chain starting at v
                    # Only if v is in target_color (it is)
                    # We simulate swap on a copy
                    trial = coloring[:]
                    # Find component of v in (target_color, c)
                    stack = [v]
                    visited = set()
                    while stack:
                        u = stack.pop()
                        if u in visited:
                            continue
                        visited.add(u)
                        # Swap colors in trial
                        if trial[u] == target_color:
                            trial[u] = c
                        elif trial[u] == c:
                            trial[u] = target_color
                        for nb in neighbors[u]:
                            if trial[nb] in (target_color, c) and nb not in visited:
                                stack.append(nb)
                    # Check if v can now be colored c (should be, but verify no conflict)
                    ok = True
                    for nb in neighbors[v]:
                        if trial[nb] == c:
                            ok = False
                            break
                    if ok:
                        # Also need to ensure we didn't introduce conflict elsewhere? 
                        # Kempe swap preserves validity, so safe.
                        coloring[:] = trial
                        made_change = True
                        break
                if made_change:
                    break
            if made_change:
                # After change, recompute and try again from same target (may have shifted)
                # But to avoid infinite loop, break and restart reduction
                return reduce_colors(coloring)
            # If no vertex of target_color could be recolored, this color class is locked
        # Compact colors if any gaps
        # Map colors to 0..k'-1
        unique_colors = {}
        next_color = 0
        for v in range(n):
            c = coloring[v]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[v] = unique_colors[c]
        return coloring

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best (fewest colors)
    best = min(candidates, key=count_colors)
    best_colors = count_colors(best)

    # Apply Kempe reduction iteratively
    improved = reduce_colors(best[:])
    if count_colors(improved) < best_colors:
        best = improved

    # Final validation and compaction
    if not is_valid(best):
        # Fallback to greedy on degree order
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for nb in neighbors[v]:
                if coloring[nb] != -1:
                    used |= 1 << coloring[nb]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best = coloring

    # Ensure colors are 0..k-1 consecutive
    mapping = {}
    next_c = 0
    for v in range(n):
        c = best[v]
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
        best[v] = mapping[c]
    return best

