def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Convert to adjacency list if needed
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        neighbors = [ [j for j, val in enumerate(row) if val == 1] for row in adj ]
    else:
        neighbors = [list(row) for row in adj]

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if u < v and coloring[v] == cu:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # Greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # DSATUR heuristic
    def dsatur():
        coloring = [-1] * n
        saturated = [set() for _ in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = len(saturated[v])
                deg = sum(1 for u in neighbors[v] if u in uncolored)
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = saturated[v]
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u].add(c)
        return normalize(coloring)

    # RLF heuristic
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent_set.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - independent_set - set()
            for u in list(uncolored - independent_set):
                if any(nb in independent_set for nb in neighbors[u]):
                    U.discard(u)
                else:
                    U.add(u)
            W = uncolored - independent_set - U

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = float('inf')
                for u in U:
                    w_neighbors = sum(1 for nb in neighbors[u] if nb in W)
                    u_deg = sum(1 for nb in neighbors[u] if nb in U)
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or (w_neighbors == best_w_neighbors and u_deg == best_u_deg and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in neighbors[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
            uncolored -= independent_set
            color += 1
        return normalize(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        degrees = [len(neighbors[v]) for v in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].add(v)

        for _ in range(n):
            # Find first non-empty bucket
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
            if i > max_deg:
                break  # should not happen
            v = buckets[i].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = degrees[u]
                    buckets[old_deg].remove(u)
                    degrees[u] -= 1
                    new_deg = degrees[u]
                    buckets[new_deg].add(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, a, b, v):
        if coloring[v] not in (a, b):
            return coloring  # should not happen
        # BFS to get the Kempe chain component
        stack = [v]
        visited = set([v])
        comp_color = coloring[v]
        target_color = b if comp_color == a else a
        while stack:
            node = stack.pop()
            for nb in neighbors[node]:
                if nb not in visited and coloring[nb] in (a, b):
                    visited.add(nb)
                    stack.append(nb)
        # Swap colors in the component
        new_coloring = coloring[:]
        for node in visited:
            if new_coloring[node] == a:
                new_coloring[node] = b
            elif new_coloring[node] == b:
                new_coloring[node] = a
        return new_coloring

    # Try to eliminate the highest color class using Kempe chains
    def reduce_colors(coloring):
        if not coloring:
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target_color = k - 1
        vertices = [v for v in range(n) if coloring[v] == target_color]
        # Try to reassign each vertex in target color class
        for v in vertices:
            # Try direct reassignment to a lower color
            used = set()
            for u in neighbors[v]:
                if coloring[u] < target_color:
                    used.add(coloring[u])
            for c in range(target_color):
                if c not in used:
                    new_coloring = coloring[:]
                    new_coloring[v] = c
                    if is_valid(new_coloring):
                        return reduce_colors(new_coloring)  # recurse
            # Try Kempe chain swaps with each lower color
            for c in range(target_color):
                new_coloring = kempe_swap(coloring, target_color, c, v)
                if new_coloring != coloring:  # swap actually changed something
                    if is_valid(new_coloring):
                        return reduce_colors(new_coloring)
        # Could not eliminate target color
        return coloring

    # Generate initial colorings from multiple heuristics
    candidates = []
    # DSATUR
    candidates.append(dsatur())
    # RLF
    candidates.append(rlf())
    # Smallest-Last
    candidates.append(smallest_last())
    # Also try Welsh-Powell (degree ordering)
    degree_order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    candidates.append(greedy_color(degree_order))
    # Natural order
    candidates.append(greedy_color(list(range(n))))
    # Random orders (a few)
    for _ in range(3):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    # Select the best candidate (fewest colors)
    best = min(candidates, key=lambda c: (num_colors(c), c))
    best = normalize(best)

    # Iteratively try to reduce colors
    improved = True
    while improved:
        reduced = reduce_colors(best)
        if num_colors(reduced) < num_colors(best):
            best = reduced
        else:
            improved = False

    return best

