            return 0
        return max(colors) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
