                       (common == max_common and deg_in_U == min_deg_U and (best_u == -1 or random.random() < 0.5)):
                        max_common = common
                        min_deg_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # Should not happen
                # Add best_u to independent set
                independent_set.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
