        colors = colors_in[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(colors)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Vertices with target_color
            target_vertices = [i for i in range(n) if colors[i] == target_color]
            if not target_vertices:
                # Already compacted?
                return compact_colors(colors)
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        used_by_neighbors |= (1 << colors[u])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Can recolor v to c
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break  # Restart while loop after change
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # If v already has a neighbor with color c, swapping might not help directly
                    # But we check: can we swap along a Kempe chain (c, target_color) starting from v?
