    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        colors = [-1] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        candidates.append(compact_colors(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation (should be valid by construction)
    if not is_valid_coloring(best):
        # Fallback to simple greedy if something went wrong
        colors = [-1] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best = compact_colors(colors)
    return best

