                 all(all(x in (0, 1) for x in row) for row in adj))
    if is_matrix:
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        bit_adj = [0] * n
        for i in range(n):
            for nb in adj[i]:
                bit_adj[i] |= (1 << nb)

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            nb = bit_adj[v]
            while nb:
                u = (nb & -nb).bit_length() - 1
                c = color[u]
                if c != -1:
                    used |= (1 << c)
                nb &= nb - 1
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

