    def is_valid(coloring):
        for u in range(n):
            c_u = coloring[u]
            nb = bit_adj[u]
            while nb:
                v = (nb & -nb).bit_length() - 1
                if coloring[v] == c_u:
                    return False
                nb &= nb - 1
        return True

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Precompute degrees for tie-breaking
        degree = [bin(bit_adj[i]).count('1') for i in range(n)]
        uncolored = set(range(n))
        # Saturation: bitmask of colors used by neighbors
        sat = [0] * n
        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], degree[x], random.random()))
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            nb = bit_adj[v]
            while nb:
                u = (nb & -nb).bit_length() - 1
                if u in uncolored:
                    sat[u] |= (1 << c)
                nb &= nb - 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            deg_sub = {}
            for v in uncolored:
                cnt = 0
                nb = bit_adj[v]
                while nb:
                    u = (nb & -nb).bit_length() - 1
                    if u in uncolored:
