                        nb &= nb - 1
                    return (cnt_w, -deg_u)
                u = max(U, key=score)
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nb = bit_adj[u]
                while nb:
                    w = (nb & -nb).bit_length() - 1
                    if w in U:
                        U.remove(w)
                        W.add(w)
                    nb &= nb - 1
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

