        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current min degree
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # Update neighbors
            nb = bit_adj[v]
            while nb:
                u = (nb & -nb).bit_length() - 1
                if not removed[u]:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)
                nb &= nb - 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    for func in (dsatur, rlf, smallest_last):
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # If no candidate, fallback to simple greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        candidates.append(greedy_color(order))

    # Select best candidate (fewest colors)
    best = min(candidates, key=count_colors)
    k = count_colors(best)

    # Iterative Kempe chain color reduction
    improved = True
    while improved and k > 1:
        improved = False
        # Target the last color (k-1)
        target_color = k - 1
        vertices = [v for v in range(n) if best[v] == target_color]
        if not vertices:
            k -= 1
            continue
        # Try to recolor each vertex in target color class
        for v in vertices:
            # Try direct reassignment to a lower color
            used = 0
            nb = bit_adj[v]
            while nb:
                u = (nb & -nb).bit_length() - 1
                c = best[u]
                if c < target_color:
                    used |= (1 << c)
                nb &= nb - 1
