                    best[v] = c
                    improved = True
                    break
            if improved:
                break
            # Try Kempe chain swap with each lower color
            for c in range(target_color):
                # Find Kempe chain component of v in colors {c, target_color}
                if best[v] != target_color:
                    continue
                # BFS to get component
                comp = set()
                stack = [v]
                comp.add(v)
                while stack:
                    x = stack.pop()
                    nb = bit_adj[x]
                    while nb:
                        y = (nb & -nb).bit_length() - 1
                        if best[y] in (c, target_color) and y not in comp:
                            comp.add(y)
