                        nb &= nb - 1
                # Check if swapping colors in component is valid
                valid_swap = True
                for x in comp:
                    nb = bit_adj[x]
                    while nb:
                        y = (nb & -nb).bit_length() - 1
                        if y not in comp and best[y] == c:
                            valid_swap = False
                            break
                    if not valid_swap:
                        break
                    nb &= nb - 1
                if valid_swap:
                    # Perform swap: c <-> target_color in component
                    for x in comp:
                        if best[x] == c:
                            best[x] = target_color
                        else:
                            best[x] = c
                    improved = True
                    break
