        if not any(v == target_color for v in best):
            # Remap colors to 0..k-2
            mapping = {}
            new_c = 0
            for old_c in range(k):
                if any(v == old_c for v in best):
                    mapping[old_c] = new_c
                    new_c += 1
            best = [mapping[c] for c in best]
            k -= 1
            improved = True  # Continue trying to reduce further

