    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            independent_set = {v}
            to_remove = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            U = uncolored - {v} - neighbors[v]
            # W: vertices adjacent to at least one in independent_set (ineligible)
            W = uncolored - U - independent_set
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                def score(u):
                    w_neighbors = len([w for w in neighbors[u] if w in W])
                    u_deg_in_U = len([w for w in neighbors[u] if w in U])
                    return (w_neighbors, -u_deg_in_U)
                u = max(U, key=score)
                independent_set.add(u)
                to_remove.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in list(U):  # iterate over copy
                    if w in neighbors[u]:
                        U.remove(w)
                        W.add(w)
