                    safe = True
                    for y in neighbors[v]:
                        if y != v and visited[y] and colors[y] == target_color:
                            safe = False
                            break
                    if safe:
                        # perform swap
                        for x in component:
                            if colors[x] == c:
                                colors[x] = target_color
                            elif colors[x] == target_color:
                                colors[x] = c
                        changed = True
                        break  # break color loop, restart with same v? but we removed v from target_vertices
                # if not changed, v remains in target_color; we'll try next vertex
            # after processing all target_vertices, if none remain, color class eliminated
            if not any(v for v in range(n) if colors[v] == target_color):
                # compact colors: map colors > target_color down by 1
                color_map = {}
                for c in range(k):
                    if c < target_color:
                        color_map[c] = c
                    elif c > target_color:
                        color_map[c] = c - 1
                colors = [color_map[c] for c in colors]
                k -= 1
                # restart reduction with new k
                return kempe_reduction(colors)
        return colors

    best_coloring = kempe_reduction(best_coloring)
    # Final validation and compacting
    def validate_and_compact(colors):
        # Validate
        for u in range(n):
            for v in neighbors[u]:
                if colors[u] == colors[v]:
                    # Should not happen, but fallback to greedy
                    return greedy_coloring(list(range(n)))
        # Compact colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for c in colors:
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
        return [unique_colors[c] for c in colors]
    best_coloring = validate_and_compact(best_coloring)
    return best_coloring

