            # Build independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            S.add(v)
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            W = set()
            for u in list(uncolored):
                if any(w in neighbors[u] for w in S):
                    W.add(u)
            U = uncolored - W
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([w for w in neighbors[x] if w in W]), -len([w for w in neighbors[x] if w in U])))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in list(U):
                    if w in neighbors[u]:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
            uncolored = W  # Next iteration: only vertices adjacent to current independent set
        return color

