        for _ in range(n):
            # Find non-empty bucket with smallest index
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = degree[u]
                    degree[u] -= 1
                    buckets[old_deg].remove(u)
                    buckets[degree[u]].add(u)
