                if 0 < len(color_classes[c]) < min_size:
                    min_size = len(color_classes[c])
                    target_color = c
            if target_color == -1:
                break  # no color to eliminate
            # Try to recolor each vertex in target color
            for v in color_classes[target_color][:]:  # iterate over copy
                # Try direct reassignment to a lower color
                free = [False] * k
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        free[coloring[u]] = True
                for c in range(target_color):
                    if not free[c]:
                        # Move v to color c
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart after change
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Build (target_color, c)-Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for u in neighbors[node]:
                                if u not in visited and (coloring[u] == target_color or coloring[u] == c):
                                    stack.append(u)
                    # Check if swapping frees color c for v (i.e., v not in component or swapping doesn't put others in target_color)
