            # If we eliminated the target color class, compact colors
            if not changed:
                # Could not eliminate, break
                break
            # Rebuild coloring to remove gaps
            mapping = {}
            new_color = 0
            for c in range(k):
                if any(coloring[v] == c for v in range(n)):
                    mapping[c] = new_color
                    new_color += 1
            for v in range(n):
                if coloring[v] in mapping:
                    coloring[v] = mapping[coloring[v]]
