                                # After swap, node becomes c, neighbor is c -> conflict
                                can_swap = False
                                break
                            if color_local[u] == target_color and color_local[node] == c:
                                # After swap, node becomes target_color, neighbor is target_color -> conflict
                                can_swap = False
                                break
                    if not can_swap:
                        break
                if can_swap:
                    # Perform swap
                    for node in component:
                        if color_local[node] == target_color:
                            color_local[node] = c
                        elif color_local[node] == c:
                            color_local[node] = target_color
                    # After swap, v should now be color c (since it was target_color)
                    # Remove v from consideration if it's no longer target_color
                    if color_local[v] != target_color:
                        break  # success for this v
            else:
                continue  # tried all c, couldn't move v
            break  # moved v, break to restart outer loop
        else:
            # Could not eliminate any vertex of target_color
            return False, coloring
        # Recurse to eliminate target_color again (since we might have created more)
        return eliminate_color_class(color_local, target_color)

    # Iteratively try to reduce colors starting from highest
    current_coloring = best_coloring[:]
    k = best_k
    changed = True
    while changed and k > 0:
        changed = False
        # Try to eliminate color k-1
        success, new_coloring = eliminate_color_class(current_coloring, k - 1)
        if success:
            # Compact colors: remap to 0..k-2
            mapping = {}
            next_c = 0
            for old_c in range(k - 1):
                if any(v == old_c for v in new_coloring):
                    mapping[old_c] = next_c
                    next_c += 1
            # Also map any color that might have been introduced? Shouldn't happen
            compacted = [mapping.get(c, c) for c in new_coloring]
            # Verify compacted uses colors 0..next_c-1
            max_c = max(compacted) if compacted else -1
            if max_c == next_c - 1:
                current_coloring = compacted
                k = next_c
                changed = True
        # If no progress, break
        if not changed:
            break

    # Final validation and compacting to zero-based
    # Ensure coloring is valid
    for u in range(n):
        for v in range(u + 1, n):
            if ((bit_adj[u] >> v) & 1) and current_coloring[u] == current_coloring[v]:
                # Fallback to DSATUR if invalid
                current_coloring = dsatur()
                break
        else:
            continue
        break

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = current_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        current_coloring[i] = unique_colors[c]

    return current_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        # Validate binary entries (0/1)
        for i in range(n):
            for j in range(n):
                val = adj[i][j]
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    if is_matrix:
        # Convert to adjacency list
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        adj = adj_list
    else:
        # Ensure adjacency list format
        adj = [list(nei) for nei in adj]
    # Build bit adjacency masks
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color masks for fast saturation update
        neighbor_color_mask = [0] * n
        uncolored = set(range(n))
        # initial degree for tie-breaking
        deg = [len(adj[u]) for u in range(n)]
        while uncolored:
            # select vertex with max sat, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], deg[x], random.random()))
            # compute available colors: smallest not in neighbor_color_mask[v]
            used = neighbor_color_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and neighbor masks for uncolored neighbors
            for u in adj[v]:
                if u in uncolored:
                    # if this color is new in u's neighborhood
                    if not (neighbor_color_mask[u] & (1 << c)):
                        neighbor_color_mask[u] |= (1 << c)
                        sat[u] += 1
        return color

    # RLF: Recursive Largest First (maximal independent set extraction)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set S for color c
            S = []
            # degree in current uncolored subgraph
            deg_uncolored = [0] * n
            for u in uncolored:
                cnt = 0
                for v in adj[u]:
                    if v in uncolored:
                        cnt += 1
                deg_uncolored[u] = cnt
            # choose first vertex: max degree in G[uncolored]
            v = max(uncolored, key=lambda x: (deg_uncolored[x], random.random()))
            S.append(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = set(uncolored) - {v}
            W = set()
            for u in list(U):
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                    U.remove(u)
            # while U not empty, add vertex with max neighbors in W
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    # count neighbors in W
                    cnt = 0
                    for w in adj[u]:
                        if w in W:
                            cnt += 1
                    if cnt > best_score or (cnt == best_score and (best_u is None or deg_uncolored[u] < deg_uncolored[best_u])):
                        best_score = cnt
                        best_u = u
                if best_u is None:
                    # fallback: arbitrary
                    best_u = next(iter(U))
                S.append(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        return color

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # core decomposition to get order
        degree = [len(adj[u]) for u in range(n)]
        # bin vertices by degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            bins[d].append(v)
        # track position
        pos = [0] * n
        for d in range(max_deg + 1):
            for i, v in enumerate(bins[d]):
                pos[v] = i
        # current degree and deleted flag
        curr_deg = degree[:]
        deleted = [False] * n
        order = []  # removal order
        # sweep degrees
        for d in range(max_deg + 1):
            while bins[d]:
                # clean bin
                while bins[d] and (deleted[bins[d][-1]] or curr_deg[bins[d][-1]] != d):
                    bins[d].pop()
                if not bins[d]:
                    break
                v = bins[d].pop()
                if deleted[v] or curr_deg[v] != d:
                    continue
                deleted[v] = True
                order.append(v)
                # update neighbors
                for u in adj[v]:
                    if not deleted[u]:
                        d_u = curr_deg[u]
                        # remove u from its bin
                        bins[d_u].pop(pos[u])
                        # add to bin d_u-1
                        curr_deg[u] -= 1
                        bins[curr_deg[u]].append(u)
                        pos[u] = len(bins[curr_deg[u]]) - 1
        # now color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    # select best (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # validate
        valid = True
        for u in range(n):
            for v in adj[u]:
                if color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col
    # fallback: if none valid (should not happen), use greedy
    if best_color is None:
        best_color = [0] * n
        for u in range(n):
            used = 0
            for v in adj[u]:
                if best_color[v] != -1:
                    used |= (1 << best_color[v])
            c = 0
            while used & (1 << c):
                c += 1
            best_color[u] = c

    # Kempe chain color reduction
    def kempe_reduction(color_in):
        # work on a copy
        color = color_in[:]
        # helper: get vertices of a color
        def color_class(c):
            return [v for v in range(n) if color[v] == c]
        # helper: check if coloring valid
        def is_valid():
            for u in range(n):
                for v in adj[u]:
                    if color[u] == color[v]:
                        return False
            return True
        # helper: Kempe swap for colors a,b on component containing v
        def kempe_swap(v, a, b):
            # BFS to get component
            from collections import deque
            comp = []
            seen = [False] * n
            q = deque([v])
            seen[v] = True
            while q:
                x = q.popleft()
                comp.append(x)
                for y in adj[x]:
                    if not seen[y] and (color[y] == a or color[y] == b):
                        seen[y] = True
                        q.append(y)
            # swap colors in component
            for x in comp:
                if color[x] == a:
                    color[x] = b
                elif color[x] == b:
                    color[x] = a
            return comp
        # main reduction loop
        improved = True
        while improved:
            improved = False
            # find smallest color class
            if n == 0:
                break
            max_color = max(color)
            # count sizes
            size = [0] * (max_color + 1)
            for v in range(n):
                if color[v] != -1:
                    size[color[v]] += 1
            # find smallest non-empty color
            target = -1
            min_size = n + 1
            for c in range(max_color + 1):
                if size[c] > 0 and size[c] < min_size:
                    min_size = size[c]
                    target = c
            if target == -1:
                break
            # try to recolor each vertex in target class
            target_vertices = color_class(target)
            for v in target_vertices:
                # try direct reassignment to a lower color
                used = 0
                for u in adj[v]:
                    if color[u] != -1:
                        used |= (1 << color[u])
                for c in range(target):  # only lower colors
                    if not (used & (1 << c)):
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # if v already has color c after possible direct reassignment, skip
                    if color[v] == c:
                        improved = True
                        break
                    # check if v and any vertex of color c are in same Kempe chain
                    # only useful if they are not adjacent (otherwise swap would conflict)
                    # but we can try and validate after
                    # we attempt swap on the component of v in (target, c)
                    # make sure we don't pull other target-colored vertices into target color
                    # Actually, we want to free color c for v by swapping a component that
                    # contains v (color target) and does not contain any vertex of color c
                    # that would become target and cause conflict? Let's do standard:
                    # We consider the Kempe chain of v for colors (target, c). Swapping
                    # will change v's color to c. We need to ensure that after swap,
                    # no two adjacent vertices have same color.
                    # Instead, we can attempt swap and validate.
                    # Save current color
                    orig_color = color[:]
                    kempe_swap(v, target, c)
                    if is_valid():
                        improved = True
                        break
                    else:
                        # revert
                        color = orig_color[:]
                if improved:
                    break
            # if we eliminated target color (no vertex has it), compact colors
            if target not in color:
                # remap colors to be consecutive
                mapping = {}
                next_c = 0
                for v in range(n):
                    if color[v] not in mapping:
                        mapping[color[v]] = next_c
                        next_c += 1
                color = [mapping[color[v]] for v in range(n)]
                improved = True  # continue to try further reduction
        return color

    best_color = kempe_reduction(best_color)
    # final validation and compacting
    # ensure valid
    for u in range(n):
        for v in adj[u]:
            if best_color[u] == best_color[v]:
                # should not happen, but fix by greedy
                used = 0
                for w in adj[u]:
                    if best_color[w] != -1:
                        used |= (1 << best_color[w])
                c = 0
                while used & (1 << c):
                    c += 1
                best_color[u] = c
    # compact colors to 0..k-1
    if n > 0:
        mapping = {}
        next_c = 0
        for v in range(n):
            if best_color[v] not in mapping:
                mapping[best_color[v]] = next_c
                next_c += 1
        best_color = [mapping[best_color[v]] for v in range(n)]
    return best_color

