    def greedy_color(order):
        colors = [-1] * n
        used = [0] * n  # bitmask of colors used by neighbors
        for u in order:
            # Find smallest color not used by neighbors
            c = 0
            while used[u] & (1 << c):
                c += 1
            colors[u] = c
            # Update neighbors
            mask = bit_adj[u]
            v = 0
            while mask:
                if mask & 1:
                    used[v] |= (1 << c)
                mask >>= 1
                v += 1
        return colors

