        deg_uncolored = [len(adj_list[i]) for i in range(n_local)]
        uncolored = set(range(n_local))

        for _ in range(n_local):
            # Select vertex with max saturation, then max degree in uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = deg_uncolored[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # Find smallest color not used by neighbors
            c = 0
            while sat[v] & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update neighbors
            mask = bit_adj[v]
            u = 0
            while mask:
                if mask & 1:
                    if u in uncolored:
                        sat[u] |= (1 << c)
                        deg_uncolored[u] -= 1
                mask >>= 1
                u += 1
        return colors

    # 2. RLF (Recursive Largest First)
    def rlf():
        n_local = n
        colors = [-1] * n_local
        uncolored = set(range(n_local))
