        # fallback: greedy by index
        best_colors = greedy_color(list(range(n)))
        best_k = count_colors(best_colors)

    # Kempe chain color reduction
    def kempe_reduction(colors):
        n_local = n
        # Make sure colors are compact
        def compact(col):
            mapping = {}
            next_color = 0
            for c in col:
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
            return [mapping[c] for c in col]

        colors = compact(colors)
        changed = True
        while changed:
            changed = False
            # Find color classes
            classes = [[] for _ in range(best_k)]  # we'll use current max color
            max_color = max(colors) if colors else -1
            for v in range(n_local):
                c = colors[v]
                if c <= max_color:
                    classes[c].append(v)
            # Try to eliminate color classes from highest down
            for target_color in range(max_color, -1, -1):
