                        # After swap: 
                        #   - v becomes c
                        #   - nodes in component that were c become target_color
                        #   - nodes in component that were target_color become c
                        # So, for a neighbor u of v:
                        #   If u not in component: color unchanged -> if it was c, conflict; if target_color, becomes c? no, unchanged -> so if it was target_color, it remains target_color -> no conflict (since v becomes c)
                        #   If u in component: 
                        #       if u was c -> becomes target_color -> no conflict (v becomes c)
                        #       if u was target_color -> becomes c -> conflict! because v becomes c.
                        # Therefore, swap is safe only if no neighbor of v in the component has color target_color.
                        has_target_color_neighbor_in_component = False
                        for nb in adj_list[v]:
                            if visited[nb] and colors[nb] == target_color:
                                has_target_color_neighbor_in_component = True
