                                old_color = colors[node]  # after swap? we just swapped, so need to revert to get old
                            # Instead, we rebuild classes from scratch for simplicity (n is small)
                            changed = True
                            # move v is already handled above? we'll rebuild
                            break
                    if changed:
                        break
                if not classes[target_color]:
                    # color class eliminated, rebuild compact colors and break to restart
                    colors = compact(colors)
                    changed = True
                    break
            if changed:
                break
        return compact(colors)

    # Apply Kempe reduction
    try:
        best_colors = kempe_reduction(best_colors)
    except Exception:
        pass  # fallback to current best

    # Final validation and compacting
    def is_valid(col):
        for u in range(n):
