        return []
    if n == 1:
        return [0]

    # Determine input type: adjacency matrix or adjacency list
    is_matrix = (len(adj[0]) == n) and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row)

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[v for v in range(n) if adj[u][v] == 1] for u in range(n)]
    else:
        adj_list = [list(neigh) for neigh in adj]

    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    deg = [len(adj_list[u]) for u in range(n)]

    best_coloring = None
    best_k = float('inf')

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Find vertex with max saturation, break ties by degree in uncolored subgraph, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and deg[u] > max_deg) or \
                   (sat[u] == max_sat and deg[u] == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat[u]
                    max_deg = deg[u]
                    v = u
            # Assign smallest available color
            used = 0
            for w in adj_list[v]:
                if color[w] != -1:
                    used |= (1 << color[w])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for w in adj_list[v]:
                if w in uncolored:
                    sat[w] = sat[w] | (1 << c)  # bitwise OR to track used colors? Actually we need count.
                    # Correction: saturation is number of distinct colors, so we need to recompute or track differently.
                    # We'll recompute saturation for simplicity since n is small.
            # Recompute saturation for all uncolored vertices (inefficient but n<=100)
            for u in uncolored:
                used_colors = 0
                for w in adj_list[u]:
                    if color[w] != -1:
                        used_colors |= (1 << color[w])
                sat[u] = bin(used_colors).count("1")
        return color

    # 2. RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = {u for u in uncolored if u != v and all(w not in independent_set for w in adj_list[u])}
            W = {u for u in uncolored if u != v and any(w in independent_set for w in adj_list[u])}
            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_in_U = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and (u_star == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        u_star = u
                independent_set.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in independent_set
            for u in independent_set:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # 3. Smallest-Last (Matula & Beck) ordering + greedy
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [deg[u] for u in range(n)]  # current degree in remaining subgraph
        while remaining:
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda x: degrees[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for w in adj_list[v]:
                if w in remaining:
                    degrees[w] -= 1
        # Color in reverse order
        return greedy_color(list(reversed(order)))

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            # Validate coloring
            valid = True
            for u in range(n):
                for v in adj_list[u]:
                    if color[u] == color[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                k = num_colors(col)
                if k < best_k:
                    best_k = k
                    best_coloring = col[:]
        except Exception:
            continue

    # Fallback: if no candidate succeeded (should not happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduction(coloring):
        # Make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Try to eliminate the highest color class
            k = num_colors(col)
            if k <= 1:
                break
            target_color = k - 1
            # Get vertices with target_color
            targets = [u for u in range(n) if col[u] == target_color]
            # Try to recolor each target vertex
            for v in targets:
                # Try direct reassignment to a lower color
                used = 0
                for w in adj_list[v]:
                    if col[w] != -1:
                        used |= (1 << col[w])
                for c in range(target_color):  # try colors 0 to target_color-1
                    if not (used & (1 << c)):
                        col[v] = c
                        changed = True
                        break
                if changed:
                    # After moving v, check if target_color class is empty
                    if target_color not in col:
                        # Compact colors: remap so that colors are 0..k-2
                        mapping = {}
                        new_c = 0
                        for old_c in sorted(set(col)):
                            mapping[old_c] = new_c
                            new_c += 1
                        col = [mapping[c] for c in col]
                        break  # restart while loop with new coloring
                    else:
                        # Continue to next target vertex (since we changed coloring, restart target scan)
                        break
                # If direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain with color c
                    # Only consider if v has no neighbor of color c (otherwise swap might not help or cause conflict)
                    has_c_neighbor = any(col[w] == c for w in adj_list[v])
                    if has_c_neighbor:
                        continue  # swapping would put two adjacent same color if we just swap v? Actually need to check component.
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # We'll do BFS to find the component containing v
                    from collections import deque
                    comp = set()
                    queue = deque([v])
                    comp.add(v)
                    while queue:
                        u = queue.popleft()
                        for w in adj_list[u]:
                            if w not in comp and (col[w] == target_color or col[w] == c):
                                comp.add(w)
                                queue.append(w)
                    # Check if any neighbor of v in the component has color c? Actually, we want to see if swapping the component
                    # would cause v to take color c without conflict.
                    # After swap, v would have color c. We need to ensure no neighbor of v has color c after swap.
                    # Neighbors of v: if neighbor has color c, after swap it becomes target_color -> conflict only if neighbor also in comp and swapped?
                    # Actually, in the Kempe chain, neighbors of v in the component have either target_color or c.
                    # After swap: 
                    #   - if neighbor had target_color -> becomes c
                    #   - if neighbor had c -> becomes target_color
                    # So for v (which had target_color, becomes c), we need that no neighbor of v has color c after swap.
                    # A neighbor of v has color c after swap if:
                    #   - it was in the component and had target_color (then becomes c) OR
                    #   - it was not in the component and had c (remains c)
                    # But if it was in the component and had target_color, then after swap it becomes c -> conflict with v (which becomes c).
                    # So we require that no neighbor of v is in the component and had target_color.
                    conflict = False
                    for w in adj_list[v]:
                        if w in comp and col[w] == target_color:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: in component, swap target_color <-> c
                        for u in comp:
                            if col[u] == target_color:
                                col[u] = c
                            elif col[u] == c:
                                col[u] = target_color
                        changed = True
                        # Check if target_color class is now empty
                        if target_color not in col:
                            mapping = {}
                            new_c = 0
                            for old_c in sorted(set(col)):
                                mapping[old_c] = new_c
                                new_c += 1
                            col = [mapping[c] for c in col]
                        break  # break from color c loop
                    if changed:
                        break  # break from target vertex loop
                if changed:
                    break  # break from target vertex loop (since we changed coloring)
            # If we went through all targets and no change, break
        return col

    # Apply Kempe reduction to the best candidate
    try:
        improved = kempe_reduction(best_coloring)
        # Validate improved coloring
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if improved[u] == improved[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            k_improved = num_colors(improved)
            if k_improved < best_k:
                best_coloring = improved
                best_k = k_improved
    except Exception:
        pass  # fallback to best_coloring

    # Ensure colors are consecutive starting from 0
    if best_coloring:
        unique_colors = sorted(set(best_coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

