def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor masks and adjacency lists
    neighbor_mask = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbor_mask[i] |= (1 << j)
                    neighbors[i].append(j)
    else:
        for i in range(n):
            mask = 0
            for j in adj[i]:
                if 0 <= j < n:
                    mask |= (1 << j)
                    neighbors[i].append(j)
            neighbor_mask[i] = mask

    # Helper: count bits
    def popcount(x: int) -> int:
        return x.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and popcount(neighbor_mask[u] & sum((1 << w) for w in uncolored)) > max_deg):
                    max_sat = sat[u]
                    max_deg = popcount(neighbor_mask[u] & sum((1 << w) for w in uncolored))
                    v = u
                elif sat[u] == max_sat:
                    deg_u = popcount(neighbor_mask[u] & sum((1 << w) for w in uncolored))
                    if deg_u > max_deg:
                        max_deg = deg_u
                        v = u
            if v == -1:
                v = next(iter(uncolored))
            # Assign smallest available color
            used = 0
            for w in neighbors[v]:
                c = color[w]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for w in neighbors[v]:
                if color[w] == -1:
                    sat[w] += 1
        return color

    # RLF: Recursive Largest First via independent set extraction
    def rlf() -> list[int]:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set S for color c
            S = set()
            # Choose vertex with max degree in G[uncolored]
            v = -1
            max_deg = -1
            for u in uncolored:
                deg = popcount(neighbor_mask[u] & sum((1 << w) for w in uncolored))
                if deg > max_deg:
                    max_deg = deg
                    v = u
            if v == -1:
                v = next(iter(uncolored))
            S.add(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v}
            W = set()
            for u in U:
                if neighbor_mask[u] & (1 << v):
                    W.add(u)
                else:
                    # u is in U (eligible)
                    pass
            # Actually, recompute U and W properly
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if neighbor_mask[u] & (1 << v):
                    W.add(u)
                else:
                    U.add(u)
            # Now grow S
            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = popcount(neighbor_mask[u] & sum((1 << w) for w in W))
                    deg_in_U = popcount(neighbor_mask[u] & sum((1 << w) for w in U))
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        u_star = u
                if u_star == -1:
                    u_star = next(iter(U))
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [popcount(neighbor_mask[i]) for i in range(n)]
        # We'll use bucket sort for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            d = degrees[i]
            if d < len(buckets):
                buckets[d].append(i)
            else:
                # extend buckets if needed
                while len(buckets) <= d:
                    buckets.append([])
                buckets[d].append(i)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr < len(buckets) and not buckets[ptr]:
                ptr += 1
            if ptr >= len(buckets):
                break
            # Get a vertex from bucket[ptr]
            while buckets[ptr] and (buckets[ptr][-1] not in remaining):
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for w in neighbors[v]:
                if w in remaining:
                    d_w = degrees[w]
                    # remove w from its current bucket
                    if d_w < len(buckets) and w in buckets[d_w]:
                        buckets[d_w].remove(w)
                    degrees[w] -= 1
                    d_w_new = degrees[w]
                    # ensure bucket exists
                    while len(buckets) <= d_w_new:
                        buckets.append([])
                    buckets[d_w_new].append(w)
        # Color in reverse order using First-Fit
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for w in neighbors[v]:
                c = color[w]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(color_in: list[int]) -> list[int]:
        color = color_in[:]
        k = max(color) + 1 if n > 0 else 0
        improved = True
        while improved and k > 0:
            improved = False
            # Find smallest color class (by index, but we target highest color to reduce k)
            # Target color k-1
            target = k - 1
            vertices_target = [v for v in range(n) if color[v] == target]
            if not vertices_target:
                # Already compacted?
                k -= 1
                continue
            # Try to recolor each vertex in target class
            for v in vertices_target:
                # Try direct reassignment to a lower color
                used = 0
                for w in neighbors[v]:
                    c = color[w]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target):  # only lower colors
                    if not (used & (1 << c)):
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains with each lower color
                for c in range(target):
                    # Check if v can be swapped via (target, c) Kempe chain
                    # We'll do BFS to find the component of v in the subgraph induced by colors {target, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in neighbors[u]:
                            if not visited[w] and (color[w] == target or color[w] == c):
                                visited[w] = True
                                queue.append(w)
                    # Check if any neighbor of the component has color c -> would cause conflict if swapped
                    has_c_neighbor = False
                    for u in component:
                        for w in neighbors[u]:
                            if color[w] == c:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            break
                    if not has_c_neighbor:
                        # Swap colors target <-> c in component
                        for u in component:
                            if color[u] == target:
                                color[u] = c
                            elif color[u] == c:
                                color[u] = target
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # Could not reduce k
                break
            # Compact colors: reindex to 0..k-1
            # But we already reduced k by one if we emptied target class?
            # Actually, we need to check if target class is now empty
            if any(color[v] == target for v in range(n)):
                # target class not empty, cannot reduce k
                break
            else:
                k -= 1
                # Relabel colors > target down by one? Not necessary if we just reduce k and ignore higher colors
                # But we must ensure colors are in [0, k-1]
                max_color = max(color) if n > 0 else -1
                if max_color >= k:
                    # Shift down colors > target
                    for v in range(n):
                        if color[v] > target:
                            color[v] -= 1
        # Final compact: ensure colors are consecutive from 0
        # Map colors to 0..k-1 where k = number of used colors
        used_colors = set(color)
        mapping = {}
        for i, c in enumerate(sorted(used_colors)):
            mapping[c] = i
        color = [mapping[c] for c in color]
        return color

    # Run all heuristics
    best_color = None
    best_k = float('inf')
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            # Validate
            valid = True
            for u in range(n):
                for v in neighbors[u]:
                    if u < v and color[u] == color[v]:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue
            k = len(set(col))
            if k < best_k:
                best_k = k
                best_color = col
        except Exception:
            continue

    if best_color is None:
        # Fallback: greedy by node order
        best_color = [0] * n
        for i in range(n):
            used = 0
            for w in neighbors[i]:
                c = best_color[w]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            best_color[i] = c

    # Apply Kempe reduction to best solution
    best_color = kempe_reduce(best_color)
    # Final validation and compact
    used_colors = set(best_color)
    mapping = {}
    for i, c in enumerate(sorted(used_colors)):
        mapping[c] = i
    best_color = [mapping[c] for c in best_color]

    return best_color

