                    sat[u] |= (1 << c)
        return color

    # 2. RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = set()
            # pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: deg[x])  # deg is static, but we can use current degree in uncolored
            # Actually, we need degree in the induced subgraph of uncolored
            # Recompute degrees in uncolored subgraph for accuracy
            deg_uncolored = {u: 0 for u in uncolored}
            for u in uncolored:
                for w in neighbors[u]:
                    if w in uncolored:
                        deg_uncolored[u] += 1
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S.add(v)
            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in S for w in neighbors[u]):
                    W.add(u)
                    U.remove(u)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = float('inf')
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    degU = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and degU < best_degU) or (score == best_score and degU == best_degU and (best_u == -1 or random.random() < 0.5)):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg_copy = deg[:]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg_copy[v]].append(v)
        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    d = deg_copy[u]
                    if d > 0:
                        deg_copy[u] -= 1
                        buckets[d].remove(u)
                        buckets[d-1].append(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col
        except Exception:
            continue

    # Fallback: greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        best_coloring = greedy_color(order)
        best_k = num_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find color classes
            classes = {}
            for v in range(n):
                c = col[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            if not classes:
                break
            max_color = max(classes.keys())
            # try to eliminate color classes from highest down
            for target_color in range(max_color, 0, -1):
                if target_color not in classes:
                    continue
                vertices = classes[target_color][:]
                # try to recolor each vertex in this class
                for v in vertices:
                    if col[v] != target_color:  # might have been recolored already
                        continue
                    # try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if col[u] != -1:
                            neighbor_colors.add(col[u])
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # try Kempe chains with each lower color
                    for c in range(target_color):
                        if c in neighbor_colors:
                            continue
                        # We want to see if we can swap colors along a Kempe chain (target_color, c)
                        # starting from v to free target_color for v? Actually we want to remove v from target_color.
                        # Standard: if v cannot take color c directly, consider the (c, target_color) Kempe chain containing v.
                        # If in that chain, there is no vertex of color c that is adjacent to v? Actually we want to swap
                        # so that v becomes color c, freeing target_color.
                        # But we already tried direct reassignment and failed because c is in neighbor_colors.
                        # So we look for a Kempe chain that does NOT include any neighbor of v colored c? 
                        # Actually, we can swap in the component of v in the subgraph induced by colors c and target_color.
                        # After swap, v becomes c. We need to ensure that no neighbor of v becomes c (which would cause conflict).
                        # But if a neighbor of v is colored c, after swap it might become target_color, which is ok as long as it's not adjacent to another target_color?
                        # This is complex. Instead, we use the known method: 
                        # For each vertex v of color target_color, try to find a color c < target_color such that
                        # there is no path from v to any vertex of color c using only colors c and target_color that 
                        # would cause a conflict when swapped. 
                        # Simpler: attempt to swap the component containing v in the (c, target_color) subgraph.
                        # After swap, v becomes c. We must check that no neighbor of v is colored c after swap.
                        # But neighbors of v that are in the component and colored c will become target_color, which is safe.
                        # Neighbors of v that are colored c and NOT in the component remain c -> conflict if adjacent to v.
                        # So we require that no neighbor of v colored c is outside the component (i.e., all neighbors of v colored c are in the component).
                        # Actually, after swap, v becomes c. A neighbor u of v:
                        # - If u colored c and in component: becomes target_color -> no conflict (v is c, u is target_color)
                        # - If u colored c and not in component: remains c -> conflict (both c)
                        # - If u colored target_color and in component: becomes c -> conflict (both c)
                        # - If u colored target_color and not in component: remains target_color -> no conflict (v is c)
                        # So we need: no neighbor of v colored c is outside the component, and no neighbor of v colored target_color is inside the component.
                        # Equivalent: the component must contain all neighbors of v colored c and none of the neighbors colored target_color.
                        # Let's compute the component.
                        from collections import deque
                        comp = set()
                        q = deque([v])
                        comp.add(v)
                        while q:
                            x = q.popleft()
                            for y in neighbors[x]:
                                if col[y] == c or col[y] == target_color:
                                    if y not in comp:
                                        comp.add(y)
                                        q.append(y)
                        # Check conditions
                        ok = True
                        for u in neighbors[v]:
                            if col[u] == c and u not in comp:
                                ok = False
                                break
                            if col[u] == target_color and u in comp:
                                ok = False
                                break
                        if ok:
                            # perform swap
                            for x in comp:
                                if col[x] == c:
                                    col[x] = target_color
                                elif col[x] == target_color:
                                    col[x] = c
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break
        # compact colors: map to 0..k-1
        unique_colors = sorted(set(col))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        col = [mapping[c] for c in col]
        return col

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduction(best_coloring)
        best_k = num_colors(best_coloring)
    except Exception:
        pass

    # Final validation (optional, but ensure correctness)
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    if not is_valid(best_coloring):
        # fallback to greedy
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        best_coloring = greedy_color(order)

    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets and bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)

    # Helper: count bits
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets for saturation update
        neighbor_colors = [set() for _ in range(n)]
        # degrees for tie-breaking
        degrees = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, break ties by degree, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)
            # Tie-break by degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                deg_candidates = []
                for v in candidates:
                    # count uncolored neighbors
                    deg_v = sum(1 for u in neighbors[v] if u in uncolored)
                    if deg_v > max_deg:
                        max_deg = deg_v
                        deg_candidates = [v]
                    elif deg_v == max_deg:
                        deg_candidates.append(v)
                if deg_candidates:
                    v = random.choice(deg_candidates)
                else:
                    v = random.choice(candidates)
            else:
                v = candidates[0]

            # Find smallest color not used by neighbors
            used = [False] * (n + 1)  # n+1 to be safe
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[v] = c
            uncolored.remove(v)

            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1
        return coloring

    # RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v_start = -1
            for v in uncolored:
                deg_v = sum(1 for u in neighbors[v] if u in uncolored)
                if deg_v > max_deg:
                    max_deg = deg_v
                    v_start = v
            if v_start == -1:
                break  # should not happen
            S = {v_start}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for v in uncolored:
                if v == v_start:
                    continue
                adjacent_to_S = False
                for u in S:
                    if v in neighbors[u]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(v)
                else:
                    U.add(v)
            # While U not empty, add vertices to S
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = 0
                    for w in W:
                        if w in neighbors[u]:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break by min degree in G[U]
                        deg_u_U = sum(1 for x in neighbors[u] if x in U)
                        deg_best_U = sum(1 for x in neighbors[best_u] if x in U) if best_u != -1 else -1
                        if deg_u_U < deg_best_U:
                            best_u = u
                if best_u == -1:
                    break  # no more to add
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for v in list(U):  # iterate over copy
                    if v in neighbors[best_u]:
                        U.remove(v)
                        W.add(v)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
                uncolored.remove(v)
            color += 1
        return coloring

    # Smallest-Last (SL) ordering greedy
    def smallest_last():
        # Build degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []  # will be removal order
        deg = [len(neighbors[i]) for i in range(n)]
        # We'll simulate removal
        # For efficiency, we can use bucket sort but n<=100 so simple loop
        temp_remaining = set(range(n))
        temp_deg = deg[:]
        while temp_remaining:
            # find vertex with min degree in temp_remaining
            min_deg = n+1
            v_min = -1
            for v in temp_remaining:
                if temp_deg[v] < min_deg:
                    min_deg = temp_deg[v]
                    v_min = v
            if v_min == -1:
                break
            order.append(v_min)
            temp_remaining.remove(v_min)
            # update degrees of neighbors
            for u in neighbors[v_min]:
                if u in temp_remaining:
                    temp_deg[u] -= 1
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, a, b, v):
        # Returns new coloring if swap is performed, else None
        # We'll do BFS to find the Kempe chain component of v in colors a,b
        from collections import deque
        visited = [False] * n
        queue = deque([v])
        visited[v] = True
        component = []
        while queue:
            node = queue.popleft()
            component.append(node)
            for nb in neighbors[node]:
                if not visited[nb] and (coloring[nb] == a or coloring[nb] == b):
                    visited[nb] = True
                    queue.append(nb)
        # Swap colors a<->b in component
        new_coloring = coloring[:]  # copy
        for node in component:
            if new_coloring[node] == a:
                new_coloring[node] = b
            elif new_coloring[node] == b:
                new_coloring[node] = a
        return new_coloring

    # Try to eliminate the smallest color class using Kempe chains
    def reduce_colors(coloring):
        coloring = normalize(coloring)
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to remove color k-1 iteratively
        improved = True
        while improved and k > 1:
            improved = False
            # Get vertices with color k-1
            color_class = [v for v in range(n) if coloring[v] == k-1]
            if not color_class:
                k -= 1
                continue
            # Try to recolor each vertex in color_class
            for v in color_class:
                cv = coloring[v]
                # Try direct reassignment to a lower color
                for c in range(k-1):  # try colors 0..k-2
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains with each lower color
                for c in range(k-1):
                    # Try to swap along (c, cv) Kempe chain starting from v
                    # Only if v is not already color c (it isn't, since cv=k-1>c)
                    new_col = kempe_swap(coloring, c, cv, v)
                    # Check if after swap, v is no longer color cv (i.e., it became c)
                    if new_col is not None and new_col[v] != cv:
                        # Accept the swap
                        coloring = new_col
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # Could not eliminate color k-1, break
                break
            # Renormalize and update k
            coloring = normalize(coloring)
            k = num_colors(coloring)
        return coloring

    # Time budget check
    start_time = time.time()
    time_limit = 0.05  # 50 ms

    best_coloring = None
    best_k = float('inf')

    # Run DSATUR
    if time.time() - start_time < time_limit:
        c1 = dsatur()
        c1 = normalize(c1)
        k1 = num_colors(c1)
        if k1 < best_k:
            best_k = k1
            best_coloring = c1
    # Run RLF
    if time.time() - start_time < time_limit:
        c2 = rlf()
        c2 = normalize(c2)
        k2 = num_colors(c2)
        if k2 < best_k:
            best_k = k2
            best_coloring = c2
    # Run Smallest-Last
    if time.time() - start_time < time_limit:
        c3 = smallest_last()
        c3 = normalize(c3)
        k3 = num_colors(c3)
        if k3 < best_k:
            best_k = k3
            best_coloring = c3

    # If no coloring found (shouldn't happen), fallback to greedy
    if best_coloring is None:
        # Simple greedy in vertex order
        coloring = [-1] * n
        for v in range(n):
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)
        best_k = num_colors(best_coloring)

    # Apply Kempe chain reduction to improve
    if time.time() - start_time < time_limit:
        best_coloring = reduce_colors(best_coloring)
        best_coloring = normalize(best_coloring)
        best_k = num_colors(best_coloring)

    # Final validation (optional, but ensure correctness)
    # if not is_valid_coloring(best_coloring):
    #     # Fallback to DSATUR if something went wrong
    #     best_coloring = dsatur()
    #     best_coloring = normalize(best_coloring)

    return best_coloring

import math
