            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S = [v]
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set(uncolored)
            U.remove(v)
            W = set()
            for u in neighbors[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in G[U]
                u_star = None
                max_score = -1
                min_deg = float('inf')
                for u in U:
                    score = len([w for w in neighbors[u] if w in W])
                    deg_u = len([w for w in neighbors[u] if w in U])
                    if score > max_score or (score == max_score and deg_u < min_deg):
                        max_score = score
                        min_deg = deg_u
