                c += 1
            colors[v] = c
            colored += 1
            # Update saturation of neighbors
            for u in neighbors_from_bitmask(bit_adj[v]):
                if colors[u] == -1:
                    saturation[u] |= (1 << c)
        return compact_colors(colors)

    # RLF: Recursive Largest First
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        # Precompute degrees in full graph
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            # Compute degrees in induced subgraph
            deg_in_uncolored = {}
            for v in uncolored:
                # Count neighbors in uncolored
                nb_mask = bit_adj[v]
                # Count bits set in nb_mask that are in uncolored
                cnt = 0
                for u in neighbors_from_bitmask(nb_mask):
                    if u in uncolored:
                        cnt += 1
                deg_in_uncolored[v] = cnt

            # Start with max degree vertex
            v = max(deg_in_uncolored, key=lambda x: deg_in_uncolored[x])
            independent_set = {v}
            to_remove = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to independent_set (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if bit_adj[v] & (1 << u):
                    W.add(u)
                else:
                    U.add(u)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_u = float('inf')
                for u in U:
                    # Count neighbors in W
                    score = 0
                    for w in W:
                        if bit_adj[u] & (1 << w):
                            score += 1
                    # Tie-break: min degree in G[U]
                    deg_u = 0
                    for nb in neighbors_from_bitmask(bit_adj[u]):
                        if nb in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or \
                       (score == best_score and deg_u == best_deg_u and (best_u == -1 or random.random() < 0.5)):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                to_remove.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in neighbors_from_bitmask(bit_adj[u]):
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to independent_set
            for v in independent_set:
                colors[v] = color_idx
            uncolored -= to_remove
            color_idx += 1
        return compact_colors(colors)

    # Smallest-Last ordering greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        # Copy degrees
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        # List of sets for each degree
        max_deg = max(degrees) if n > 0 else 0
        bins = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degrees[v]
            if d <= max_deg:
                bins[d].add(v)
        # Vertex ordering stack
        order = []
        # Current degrees (will be updated)
        curr_deg = degrees[:]
        # Remaining vertices
        remaining = set(range(n))

        for _ in range(n):
            # Find vertex with minimum degree
            min_v = -1
            min_deg = float('inf')
            for v in remaining:
                if curr_deg[v] < min_deg:
                    min_deg = curr_deg[v]
                    min_v = v
            v = min_v
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors_from_bitmask(bit_adj[v]):
                if u in remaining:
                    curr_deg[u] -= 1
                    old_d = curr_deg[u] + 1
                    new_d = curr_deg[u]
                    if old_d <= max_deg and v in bins[old_d]:
                        bins[old_d].remove(v)
                    if new_d <= max_deg:
                        bins[new_d].add(u)
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors_from_bitmask(bit_adj[v]):
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduction(colors):
        if n <= 1:
            return colors
        # Make a copy to work on
        cur_colors = colors[:]
        k = num_colors(cur_colors)
        # Try to reduce colors as much as possible
        improved = True
        while improved and k > 1:
            improved = False
            # Target the last color (k-1)
            target_color = k - 1
            # Vertices with target color
            target_vertices = [v for v in range(n) if cur_colors[v] == target_color]
            if not target_vertices:
                # Already compacted?
                cur_colors = compact_colors(cur_colors)
                k = num_colors(cur_colors)
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in neighbors_from_bitmask(bit_adj[v]):
                    if cur_colors[u] != -1:
                        used_by_neighbors |= (1 << cur_colors[u])
                # Find smallest color not used by neighbors
                for c in range(target_color):  # only try colors < target_color
                    if not (used_by_neighbors & (1 << c)):
                        # Can recolor directly
                        cur_colors[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart from beginning as coloring changed
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (c, target_color)
                    # We need to see if v is not connected to any vertex of color c via a Kempe chain
                    # Actually, we can try to swap the component containing v in the (c, target_color) subgraph
                    # Build the Kempe chain component starting from v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in neighbors_from_bitmask(bit_adj[node]):
                            if not visited[nb] and (cur_colors[nb] == c or cur_colors[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any neighbor of v in the component has color c? Actually, we need to see
                    # if swapping colors in this component would cause conflict.
                    # After swap, v would get color c. We need to ensure no neighbor of v has color c after swap.
                    # Neighbors of v that are in the component: if they had color c, they become target_color, so no conflict.
                    # Neighbors of v that are not in the component: they keep their color.
                    # So we need to check: for any neighbor u of v, if u not in component, then cur_colors[u] != c
                    # (because if it were c and not in component, after swap it remains c -> conflict with v's new color c)
                    conflict = False
                    for u in neighbors_from_bitmask(bit_adj[v]):
                        if not visited[u] and cur_colors[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: c <-> target_color in component
                        for node in component:
                            if cur_colors[node] == c:
                                cur_colors[node] = target_color
                            elif cur_colors[node] == target_color:
                                cur_colors[node] = c
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # Compact colors after change
                cur_colors = compact_colors(cur_colors)
                k = num_colors(cur_colors)
        return cur_colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    # List of heuristic functions
    heuristics = [dsatur, rlf, smallest_last]

    for heuristic in heuristics:
        try:
            col = heuristic()
            if not is_valid_coloring(col):
                # Fallback: use greedy ordering by degree
                order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
                col = [-1] * n
                for v in order:
                    used = 0
                    for u in neighbors_from_bitmask(bit_adj[v]):
                        if col[u] != -1:
                            used |= (1 << col[u])
                    c = 0
                    while used & (1 << c):
                        c += 1
                    col[v] = c
                col = compact_colors(col)
            k = num_colors(col)
            if k < best_k or (k == best_k and best_colors is None):
                best_k = k
                best_colors = col[:]
        except Exception:
            continue

    # If none worked, fallback to simple greedy
    if best_colors is None or not is_valid_coloring(best_colors):
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        col = [-1] * n
        for v in order:
            used = 0
            for u in neighbors_from_bitmask(bit_adj[v]):
                if col[u] != -1:
                    used |= (1 << col[u])
            c = 0
            while used & (1 << c):
                c += 1
            col[v] = c
        best_colors = compact_colors(col)

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduction(best_colors)
        if is_valid_coloring(improved):
            k_orig = num_colors(best_colors)
            k_imp = num_colors(improved)
            if k_imp < k_orig:
                best_colors = improved
    except Exception:
        pass

    # Final validation and compacting
    if not is_valid_coloring(best_colors):
        # Last resort: assign each vertex a unique color
        best_colors = list(range(n))
    best_colors = compact_colors(best_colors)

    return best_colors

