def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True
    # Build adjacency list and bitmask representation
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = adj[i]
            nbrs = [j for j in range(n) if row[j] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = adj
    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            mask = bit_adj[u]
            v = 0
            while mask:
                if mask & 1:
                    if coloring[v] == cu:
                        return False
                mask >>= 1
                v += 1
        return True

    # Helper: convert coloring to consecutive colors starting from 0
    def normalize(coloring):
        mapping = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            coloring[i] = mapping[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        # Precompute degrees
        degrees = [len(neighbors[i]) for i in range(n)]
        colored_neighbors_mask = [0] * n  # bitmask of colored neighbors
        saturation = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then index
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > best_sat:
                    best_sat = sat_v
                    best_v = v
                    best_deg = sum(1 for u in neighbors[v] if u in uncolored)
                elif sat_v == best_sat:
                    deg_v = sum(1 for u in neighbors[v] if u in uncolored)
                    if deg_v > best_deg:
                        best_deg = deg_v
                        best_v = v
                    elif deg_v == best_deg and v < best_v:
                        best_v = v
            v = best_v
            # Determine forbidden colors from colored neighbors
            forbidden = 0
            mask = bit_adj[v]
            u = 0
            while mask:
                if mask & 1:
                    if coloring[u] != -1:
                        forbidden |= (1 << coloring[u])
                mask >>= 1
                u += 1
            # Find smallest non-negative color not in forbidden
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            mask = bit_adj[v]
            u = 0
            while mask:
                if mask & 1:
                    if coloring[u] == -1:  # only update uncolored
                        saturation[u] += 1
                mask >>= 1
                u += 1
        return coloring

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set S for this color
            S = set()
            # Choose vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in neighbors[u] for w in S):
                    W.add(u)
                    U.remove(u)
            # While U not empty, select vertex with max neighbors in W
            while U:
                best_u = -1
                best_w_neighbors = -1
                best_deg_U = -1
                for u in U:
                    w_nbrs = sum(1 for w in neighbors[u] if w in W)
                    if w_nbrs > best_w_neighbors:
                        best_w_neighbors = w_nbrs
                        best_u = u
                        best_deg_U = sum(1 for x in neighbors[u] if x in U)
                    elif w_nbrs == best_w_neighbors:
                        deg_u = sum(1 for x in neighbors[u] if x in U)
                        if deg_u < best_deg_U:
                            best_deg_U = deg_u
                            best_u = u
                        elif deg_u == best_deg_U and u < best_u:
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u that are in U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all vertices in S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
        return coloring

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering via smallest-last removal
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # We'll use bucket sort for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            # Find vertex with minimum degree in remaining
            min_deg = float('inf')
            v_min = -1
            for v in remaining:
                if degree[v] < min_deg:
                    min_deg = degree[v]
                    v_min = v
            order.append(v_min)
            remaining.remove(v_min)
            # Decrease degree of neighbors
            for u in neighbors[v_min]:
                if u in remaining:
                    degree[u] -= 1
        # Color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(order):
            forbidden = 0
            mask = bit_adj[v]
            u = 0
            while mask:
                if mask & 1:
                    if coloring[u] != -1:
                        forbidden |= (1 << coloring[u])
                mask >>= 1
                u += 1
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain elimination to reduce colors
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Normalize first to ensure consecutive colors
        coloring = normalize(coloring[:])
        max_color = max(coloring) if n > 0 else -1
        # Try to eliminate colors from highest downwards
        changed = True
        while changed and max_color >= 0:
            changed = False
            # Find smallest color class (by size) to target for elimination
            color_classes = [[] for _ in range(max_color + 1)]
            for v in range(n):
                c = coloring[v]
                color_classes[c].append(v)
            # Target the smallest non-empty color class
            target_color = -1
            min_size = float('inf')
            for c in range(max_color + 1):
                if color_classes[c] and len(color_classes[c]) < min_size:
                    min_size = len(color_classes[c])
                    target_color = c
            if target_color == -1:
                break
            # Try to recolor each vertex in target_color
            for v in color_classes[target_color][:]:  # iterate over copy
                # Try direct reassignment to a lower color
                forbidden = 0
                mask = bit_adj[v]
                u = 0
                while mask:
                    if mask & 1:
                        if coloring[u] != -1:
                            forbidden |= (1 << coloring[u])
                    mask >>= 1
                    u += 1
                for c in range(target_color):  # only try lower colors
                    if not (forbidden & (1 << c)):
                        # Move v to color c
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    # After moving one vertex, break to re-normalize and re-evaluate
                    break
            if changed:
                # Normalize and continue
                coloring = normalize(coloring)
                max_color = max(coloring) if n > 0 else -1
                continue
            # If no direct reassignment, try Kempe chain swaps
            for v in color_classes[target_color][:]:
                for c in range(target_color):
                    # Check if v is adjacent to any vertex of color c
                    adjacent_to_c = False
                    mask = bit_adj[v]
                    u = 0
                    while mask:
                        if mask & 1:
                            if coloring[u] == c:
                                adjacent_to_c = True
                                break
                        mask >>= 1
                        u += 1
                    if adjacent_to_c:
                        continue
                    # Build the (target_color, c)-Kempe chain containing v
                    # We'll do BFS to get the component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for w in neighbors[node]:
                            if not visited[w] and (coloring[w] == target_color or coloring[w] == c):
                                visited[w] = True
                                queue.append(w)
                    # Swap colors in the component: target_color <-> c
                    for node in component:
                        if coloring[node] == target_color:
                            coloring[node] = c
                        elif coloring[node] == c:
                            coloring[node] = target_color
                    # After swap, check if v is no longer target_color (should be c now)
                    if coloring[v] != target_color:
                        changed = True
                        break
                if changed:
                    break
            if changed:
                coloring = normalize(coloring)
                max_color = max(coloring) if n > 0 else -1
        return coloring

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass
    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        coloring = [0] * n
        for i in range(1, n):
            forbidden = 0
            mask = bit_adj[i]
            j = 0
            while mask:
                if mask & 1:
                    if coloring[j] != -1:
                        forbidden |= (1 << coloring[j])
                mask >>= 1
                j += 1
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[i] = c
        candidates.append(coloring)

    # Select the candidate with the fewest colors
    best_coloring = None
    best_num_colors = float('inf')
    for col in candidates:
        num_colors = len(set(col)) if n > 0 else 0
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_coloring = col
    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best_coloring[:])
        if is_valid(improved):
            num_colors_imp = len(set(improved)) if n > 0 else 0
            if num_colors_imp < best_num_colors:
                best_coloring = improved
    except Exception:
        pass
    # Final normalization and validation
    best_coloring = normalize(best_coloring)
    # Ensure validity (should be, but double-check)
    if not is_valid(best_coloring):
        # As a last resort, apply a simple greedy algorithm in random order
        ordering = list(range(n))
        random.shuffle(ordering)
        coloring = [-1] * n
        for v in ordering:
            forbidden = 0
            mask = bit_adj[v]
            u = 0
            while mask:
                if mask & 1:
                    if coloring[u] != -1:
                        forbidden |= (1 << coloring[u])
                mask >>= 1
                u += 1
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)
    return best_coloring

