    # Detect adjacency matrix (square with binary entries)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        # Validate binary entries (0 or 1) for safety
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

