    if is_matrix:
        neighbors = []
        for i in range(n):
            row = []
            for j in range(n):
                if adj[i][j] == 1:
                    row.append(j)
            neighbors.append(row)
    else:
        neighbors = adj  # Assume adjacency list

    deg = [len(neighbors[i]) for i in range(n)]

    # Smallest-last ordering (Matula & Beck, 1983)
    removed = [False] * n
    order = []  # Will store vertices in removal order (first removed first in list)
    current_deg = deg[:]  # Current degrees in the remaining graph

    # Use buckets for O(n) extraction of min degree vertex
    max_deg = max(deg) if n > 0 else 0
    buckets = [[] for _ in range(max_deg + 1)]
    for v in range(n):
        d = current_deg[v]
        buckets[d].append(v)

    min_deg = 0
    for _ in range(n):
        # Find the next non-empty bucket with min degree
        while min_deg <= max_deg and not buckets[min_deg]:
            min_deg += 1
        if min_deg > max_deg:
            break  # Should not happen for connected components, but safe
        v = buckets[min_deg].pop()
        if removed[v]:
            continue  # Skip if already removed (should not occur with proper bucket maintenance)
        removed[v] = True
        order.append(v)
        # Update neighbors: decrease current degree and move to appropriate bucket
        for u in neighbors[v]:
            if not removed[u]:
                old_deg = current_deg[u]
                new_deg = old_deg - 1
                current_deg[u] = new_deg
                # Remove u from old bucket (we don't remove explicitly, but we will skip removed ones later)
                # Instead, we add to new bucket and rely on min_deg adjustment
                if new_deg < len(buckets):
                    buckets[new_deg].append(u)
                else:
                    # Extend buckets if necessary (should not happen as degree decreases)
                    while len(buckets) <= new_deg:
                        buckets.append([])
                    buckets[new_deg].append(u)
                # If the new degree is less than current min_deg, update min_deg
                if new_deg < min_deg:
                    min_deg = new_deg

    # Color in reverse order (last removed first) with First-Fit
    color = [-1] * n
    max_color_used = -1
    for v in reversed(order):
        # Collect colors used by already colored neighbors
        used = [False] * (n + 1)  # n+1 is safe upper bound
        for u in neighbors[v]:
            c = color[u]
            if c != -1:
                used[c] = True
        # Find the smallest non-negative integer color not used
        c = 0
        while c <= n and used[c]:
            c += 1
        color[v] = c
        if c > max_color_used:
            max_color_used = c

    # Compact colors to 0..k-1 if necessary (though First-Fit in reverse SL order should already produce compact colors)
