def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix or adjacency list
    if len(adj) > 0 and len(adj[0]) == len(adj) and all(
        isinstance(x, int) and x in (0, 1) for row in adj for x in row
    ):
        # Convert adjacency matrix to adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        # Treat as adjacency list
        graph = [list(neigh) for neigh in adj]

    # Helper: check if a coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in graph[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize_coloring(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # Heuristic 1: DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        # Precompute neighbor sets for saturation
        neighbor_sets = [set(neigh) for neigh in graph]
        # Degrees for tie-breaking
        degrees = [len(neigh) for neigh in graph]
        # Track saturation degree (number of distinct colors in neighbors)
        saturation = [0] * n
        # Track colored neighbors' colors for each vertex
        neighbor_colors = [set() for _ in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    sat_u = saturation[u]
                    deg_u = degrees[u]
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                       (sat_u == max_sat and deg_u == max_deg and (v == -1 or random.random() < 0.5)):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # Should not happen

            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c

            # Update saturation and neighbor colors for uncolored neighbors
            for u in neighbor_sets[v]:
                if colors[u] == -1:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1
        return normalize_coloring(colors)

    # Heuristic 2: RLF (Recursive Largest First) independent set extraction
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        color_idx = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for current color
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len([y for y in graph[x] if y in uncolored]))
                independent_set.add(v)
                uncolored.remove(v)
            # Sets U (eligible) and W (ineligible) for current color class
            # U: uncolored and not adjacent to any in independent_set
            # W: uncolored and adjacent to at least one in independent_set
            U = {u for u in uncolored if not any(w in independent_set for w in graph[u])}
            W = uncolored - U

            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = len([y for y in graph[u] if y in W])
                    deg_in_U = len([y for y in graph[u] if y in U])
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # Should not happen if U not empty
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for y in graph[best_u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
            color_idx += 1
            # Next uncolored set is W (vertices adjacent to current independent set)
            uncolored = W
        return normalize_coloring(colors)

    # Heuristic 3: Smallest-Last (Matula & Beck) ordering + greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degrees = [len(neigh) for neigh in graph]
        removed = [False] * n
        order = []  # removal order
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            # Find unremoved vertex with minimum degree
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u]:
                    # Current degree in remaining graph: count neighbors not removed
                    deg = 0
                    for w in graph[u]:
                        if not removed[w]:
                            deg += 1
                    if deg < min_deg:
                        min_deg = deg
                        v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
        # Color in reverse removal order
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for u in graph[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return normalize_coloring(colors)

    # Run all heuristics and pick the best (fewest colors)
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    best_coloring = None
    min_colors = float('inf')
    for coloring in candidates:
        if not is_valid_coloring(coloring):
            continue  # Should not happen, but just in case
        num_colors = len(set(coloring))
        if num_colors < min_colors:
            min_colors = num_colors
            best_coloring = coloring

    # Fallback: if no heuristic produced valid coloring (unlikely), use greedy by index
    if best_coloring is None:
        colors = [-1] * n
        for i in range(n):
            used = set()
            for j in graph[i]:
                if colors[j] != -1:
                    used.add(colors[j])
            c = 0
            while c in used:
                c += 1
            colors[i] = c
        best_coloring = normalize_coloring(colors)

    # Iterative Kempe chain color reduction
    def kempe_reduction(coloring):
        if n == 0:
            return coloring
        # Make a copy we can modify
        current = coloring[:]
        changed = True
        # We'll try to reduce colors as long as we can eliminate a color class
        while changed:
            changed = False
            # Try to eliminate the highest color class first (or any, but highest is common)
            max_color = max(current) if current else -1
            if max_color < 0:
                break
            # Collect vertices with color max_color
            vertices_to_recolor = [i for i in range(n) if current[i] == max_color]
            if not vertices_to_recolor:
                # This color already gone, renumber and continue
                current = normalize_coloring(current)
                continue

            # Try to recolor each vertex in this class to a lower color
            for v in vertices_to_recolor:
                # Try direct reassignment to any lower color
                neighbor_colors = set()
                for u in graph[v]:
                    if current[u] != -1:
                        neighbor_colors.add(current[u])
                for c in range(max_color):  # try colors 0 to max_color-1
                    if c not in neighbor_colors:
                        # Found a direct move
                        current[v] = c
                        changed = True
                        break
                if changed:
                    # After moving one vertex, break to restart the color class check
                    break

                # If no direct move, try Kempe chains with each lower color
                for c in range(max_color):
                    if c in neighbor_colors:
                        continue  # skip if neighbor already has color c (would cause conflict if we just swap)
                    # We want to swap colors max_color and c in the component containing v
                    # Only if v is not connected via a Kempe chain to another vertex of color c that would block
                    # Actually, we can try to build the (v, max_color, c) Kempe chain
                    # We'll do BFS/DFS over vertices colored max_color or c
                    from collections import deque
                    visited = [False] * n
                    queue = deque()
                    # Start from v only if it has color max_color (it does)
                    if current[v] == max_color:
                        queue.append(v)
                        visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in graph[x]:
                            if not visited[y] and (current[y] == max_color or current[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of v has color c (outside the component?)
                    # Actually, if we swap, we need to ensure that no neighbor of v ends up with color c after swap
                    # But if a neighbor of v is in the component and has color c, after swap it becomes max_color -> still not c
                    # The only issue is if a neighbor of v has color c and is NOT in the component -> then after swap, v becomes c and neighbor remains c -> conflict
                    conflict = False
                    for y in graph[v]:
                        if current[y] == c and not visited[y]:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: max_color <-> c in the component
                        for x in component:
                            if current[x] == max_color:
                                current[x] = c
                            elif current[x] == c:
                                current[x] = max_color
                        changed = True
                        break  # break from color loop
                if changed:
                    break  # break from vertex loop
            if changed:
                # After a change, renumber to keep colors consecutive and try again
                current = normalize_coloring(current)
            else:
                # Could not recolor any vertex in this color class, try next lower color class?
                # For simplicity, break if we can't reduce the highest color
                break
        return current

    # Apply Kempe reduction to the best candidate
    try:
        improved = kempe_reduction(best_coloring)
        if is_valid_coloring(improved):
            best_coloring = improved
    except Exception:
        # If anything goes wrong, keep the original best_coloring
        pass

    return best_coloring

