    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # Strategy 1: BFS-based bipartite extraction + greedy for odd cycles
    def bfs_bipartite_greedy():
        color = [-1] * n
        # Try each component
        for start in range(n):
            if color[start] != -1:
                continue
            # BFS to 2-color the component
            q = deque([start])
            color[start] = 0
            while q:
                u = q.popleft()
                for v in neighbors[u]:
                    if color[v] == -1:
                        color[v] = color[u] ^ 1
                        q.append(v)
                    elif color[v] == color[u]:
                        # Conflict: odd cycle detected, we'll handle later
                        pass
        # Now resolve conflicts by reassigning colors greedily in BFS order
        # We'll use 2 initial colors, then introduce new colors as needed
        final_color = [-1] * n
        used_colors = set()
        # Process in BFS order again, but assign smallest available color
        order = []
        visited = [False] * n
        for start in range(n):
            if not visited[start]:
                q = deque([start])
                visited[start] = True
                while q:
                    u = q.popleft()
                    order.append(u)
                    for v in neighbors[u]:
                        if not visited[v]:
                            visited[v] = True
                            q.append(v)
        # Greedy coloring in this order
        for u in order:
            used = [False] * (n + 1)  # enough colors
            for v in neighbors[u]:
                if final_color[v] != -1:
                    used[final_color[v]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            final_color[u] = c
            used_colors.add(c)
        return normalize(final_color)

    # Strategy 2: DSATUR with bitmask optimization
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        # Precompute degrees
        degrees = [len(neighbors[i]) for i in range(n)]
        # Track saturation sets as bitmasks
        saturation = [0] * n  # bitmask of colors used by neighbors
        colored = [False] * n

