            # Select uncolored vertex with max saturation, tie-break by degree
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                sat = saturation[v].bit_count()
                if sat > best_sat or (sat == best_sat and degrees[v] > best_deg) or \
                   (sat == best_sat and degrees[v] == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = degrees[v]
                    best_v = v
            v = best_v
            # Find smallest available color
            avail = 0
            while saturation[v] & (1 << avail):
                avail += 1
            coloring[v] = avail
            colored[v] = True
            # Update saturation of neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    saturation[u] |= (1 << avail)
        return normalize(coloring)

    # Strategy 3: RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        color = 0
        # Set of uncolored vertices
        uncolored = set(range(n))
        # Precompute degrees in full graph
        degrees = [len(neighbors[i]) for i in range(n)]

        while uncolored:
            # Build maximal independent set for this color
            independent_set = []
            # Start with vertex of max degree in uncolored subgraph
            # Compute current degrees in uncolored subgraph
            curr_deg = {}
            for v in uncolored:
                cnt = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        cnt += 1
                curr_deg[v] = cnt
            # Pick v with max degree
            v = max(uncolored, key=lambda x: (curr_deg[x], x))
            independent_set.append(v)
            # Partition: U = not adjacent to any in S, W = adjacent to at least one in S
            S = set(independent_set)
            U = set()
            W = set()
            for u in uncolored:
                if u in S:
                    continue
                adjacent_to_S = False
                for w in S:
                    if w in neighbors[u]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty, add vertices that maximize |N(u) ∩ W|
            while U:
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    # Score: number of neighbors in W
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # Tie-break: min degree in G[U]
                    deg_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or \
                       (score == best_score and deg_U == best_deg_U and u < best_u):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                independent_set.append(u)
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in independent_set
            for v in independent_set:
                coloring[v] = color
            color += 1
            # Remove colored vertices from uncolored
            uncolored -= S
        return normalize(coloring)

    # Strategy 4: Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # We'll maintain current degrees in the remaining graph
        curr_degree = degree[:]
        # Bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if curr_degree[v] < len(buckets):
                buckets[curr_degree[v]].append(v)
        # Pointer to current min degree
        min_deg = 0
        while remaining:
            # Find non-empty bucket
            while min_deg < len(buckets) and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= len(buckets):
                break
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = curr_degree[u]
                    curr_degree[u] -= 1
                    # Move u to new bucket
                    if old_deg < len(buckets):
                        # Remove from old bucket (lazy, we'll skip if not in remaining)
                        pass
                    if curr_degree[u] < len(buckets):
                        buckets[curr_degree[u]].append(u)
                    if curr_degree[u] < min_deg:
                        min_deg = curr_degree[u]
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Strategy 5: Greedy by degree (Welsh-Powell)
    def greedy_degree():
        if n == 0:
            return []
        order = sorted(range(n), key=lambda x: (-len(neighbors[x]), x))
        coloring = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Run all strategies and collect candidates
    candidates = []
    for strategy in [bfs_bipartite_greedy, dsatur, rlf, smallest_last, greedy_degree]:
        try:
            col = strategy()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # If no valid candidate, fallback to simple greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for j in neighbors[i]:
                if coloring[j] != -1:
                    used[coloring[j]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            coloring[i] = c
        candidates.append(normalize(coloring))

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    return best

