        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, then max uncolored degree
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_count = saturation[v].bit_count()
                if sat_count > best_sat or (sat_count == best_sat and uncolored_deg[v] > best_deg):
                    best_sat = sat_count
                    best_deg = uncolored_deg[v]
                    best_v = v
                elif sat_count == best_sat and uncolored_deg[v] == best_deg:
                    if best_v == -1 or v < best_v:
                        best_v = v
            v = best_v
            # Assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = {u for u in uncolored if u != v and all(u not in adj_list[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in adj_list[w] for w in S)}
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, then min degree in U-induced subgraph
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = -1
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    u_deg = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and u_deg < best_u_deg):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                    elif w_neighbors == best_w_neighbors and u_deg == best_u_deg:
                        if best_u == -1 or u < best_u:
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        degree = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current min degree
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = degree[u]
                    degree[u] -= 1
                    buckets[d].remove(u)
                    buckets[d-1].append(u)
                    if d-1 < ptr:
                        ptr = d-1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Spectral-inspired clustering via random walk diffusion
    def spectral_cluster():
        # Use random walk to approximate eigenvector for partitioning
        # Perform a few steps of random walk from random start, use visit frequency
        if n == 0:
            return []
        # Random walk: 50 steps, restart probability 0.15 (like PageRank)
        visits = [0.0] * n
        current = random.randrange(n)
        steps = 50
        restart_prob = 0.15
        for _ in range(steps):
            visits[current] += 1.0
            if random.random() < restart_prob:
                current = random.randrange(n)
            else:
                neighbors = adj_list[current]
                if neighbors:
                    current = random.choice(neighbors)
                else:
                    current = random.randrange(n)  # teleport if isolated
        # Normalize visits
        total = sum(visits)
        if total > 0:
            visits = [v / total for v in visits]
        else:
            visits = [1.0 / n] * n
        # Sort vertices by visit frequency (descending) as proxy for eigenvector
        order = sorted(range(n), key=lambda x: visits[x], reverse=True)
        return greedy_color(order)

    # Run all strategies and collect candidates
    candidates = []
    for strategy in [dsatur, rlf, smallest_last, spectral_cluster]:
        try:
            coloring = strategy()
            if is_valid(coloring):
                candidates.append(coloring)
        except Exception:
            continue

    # If no valid candidate, fallback to simple greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = greedy_color(order)
        if is_valid(coloring):
            candidates.append(coloring)
        else:
            # Last resort: assign each vertex a unique color
            coloring = list(range(n))
            candidates.append(coloring)

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Compact colors to 0..k-1 if not already
    if k > 0:
        # Map colors to compact set
        unique_colors = sorted(set(best))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best = [mapping[c] for c in best]

    # Final validation (should always hold)
    assert is_valid(best), "Invalid coloring produced"
    return best

