def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper: count distinct colors
    def count_colors(colors):
        return len(set(colors)) if colors else 0

    # Helper: convert to zero-based consecutive colors
    def normalize_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        saturation = [0] * n
        degree = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            max_sat = -1
            candidates = []
            for v in range(n):
                if not colored[v]:
                    if saturation[v] > max_sat:
                        max_sat = saturation[v]
                        candidates = [v]
                    elif saturation[v] == max_sat:
                        candidates.append(v)
            if not candidates:
                break  # should not happen
            # Tie-break: max degree in uncolored subgraph
            v = max(candidates, key=lambda x: degree[x])
            # Assign smallest available color
            neighbor_colors = 0
            for u in adj_list[v]:
                if colored[u]:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if not colored[u]:
                    saturation[u] += 1
        return normalize_colors(colors)

    # RLF: Recursive Largest First
    def rlf():
        colors = [-1] * n
        colored = [False] * n
        color_idx = 0
        # Precompute degrees in full graph
        degree = [len(adj_list[i]) for i in range(n)]

        while not all(colored):
            # Step 1: pick uncolored vertex with max degree in uncolored subgraph
            max_deg = -1
            v_start = -1
            for v in range(n):
                if not colored[v]:
                    # current degree in uncolored subgraph
                    deg = 0
                    for u in adj_list[v]:
                        if not colored[u]:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        v_start = v
            if v_start == -1:
                break
            # Build independent set for this color
            S = [v_start]
            colored[v_start] = True
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if not colored[u] and u != v_start:
                    if v_start in adj_list[u]:
                        W.add(u)
                    else:
                        U.add(u)
            # Expand S
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break: min degree in G[U]
                        deg_u = 0
                        for w in adj_list[u]:
                            if w in U:
                                deg_u += 1
                        deg_best = 0
                        for w in adj_list[best_u]:
                            if w in U:
                                deg_best += 1
                        if deg_u < deg_best:
                            best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to S
            for v in S:
                colors[v] = color_idx
            color_idx += 1
        return normalize_colors(colors)

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        if n == 0:
            return []
        # Copy of degrees
        degree = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # Buckets for degrees 0..n-1
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d < len(buckets):
                buckets[d].append(v)
            else:
                # extend buckets if needed (should not happen)
                while len(buckets) <= d:
                    buckets.append([])
                buckets[d].append(v)
        # Pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # Find next non-empty bucket
            while min_deg < len(buckets) and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= len(buckets):
                break  # no more vertices
            v = buckets[min_deg].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = degree[u]
                    # remove u from bucket d
                    if d < len(buckets) and u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    # ensure bucket exists
                    while len(buckets) <= d_new:
                        buckets.append([])
                    buckets[d_new].append(u)
                    if d_new < min_deg:
                        min_deg = d_new
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        return normalize_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        if not colors:
            return colors
        k = count_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # Target highest color class (k-1)
            target_color = k - 1
            vertices = [v for v in range(n) if colors[v] == target_color]
            if not vertices:
                # already empty, compact
                mapping = {c: c for c in range(k) if c != target_color}
                # shift down colors > target_color
                for c in range(target_color + 1, k):
                    mapping[c] = c - 1
                colors = [mapping[c] for c in colors]
                k -= 1
                improved = True
                continue
            # Try to recolor each vertex in target class
            removed_all = True
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in adj_list[v]:
                    neighbor_colors |= (1 << colors[u])
                found = False
                for c in range(target_color):  # try colors 0..k-2
                    if not (neighbor_colors & (1 << c)):
                        colors[v] = c
                        found = True
                        break
                if found:
                    continue
                # Try Kempe chain swap with each lower color
                swapped = False
                for c in range(target_color):
                    # Check if v is in a Kempe chain of (target_color, c) that does not include any other vertex of target_color?
                    # We'll try to swap the component containing v if it frees color c for v
                    # Build the Kempe chain component of v for colors target_color and c
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    has_other_target = False  # other vertex with target_color in component?
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        if colors[x] == target_color and x != v:
                            has_other_target = True
                        for y in adj_list[x]:
                            if not visited[y] and (colors[y] == target_color or colors[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # If no other target_color vertex in component, we can swap
                    if not has_other_target:
                        # Swap colors target_color <-> c in component
                        for x in component:
                            if colors[x] == target_color:
                                colors[x] = c
                            elif colors[x] == c:
                                colors[x] = target_color
                        # Now v has color c
                        swapped = True
                        break
                if swapped:
                    continue
                # If neither direct nor Kempe worked, we cannot remove v from target color
                removed_all = False
            if removed_all:
                # All vertices recolored, compact
                mapping = {c: c for c in range(k) if c != target_color}
                for c in range(target_color + 1, k):
                    mapping[c] = c - 1
                colors = [mapping[c] for c in colors]
                k -= 1
                improved = True
            else:
                # Could not eliminate this color class, try next lower? but we break for now
                break
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            cols = func()
            if is_valid_coloring(cols):
                k = count_colors(cols)
                if k < best_k:
                    best_k = k
                    best_colors = cols
        except Exception:
            continue

    # Fallback: greedy by degree order
    if best_colors is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        best_colors = normalize_colors(colors)

    # Apply Kempe reduction
    best_colors = kempe_reduce(best_colors)
    # Final validation and normalization
    if not is_valid_coloring(best_colors):
        # Last resort: simple greedy
        order = list(range(n))
        colors = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        best_colors = normalize_colors(colors)

    return best_colors

