                    # try Kempe chains with each lower color
                    for d in range(c):
                        # BFS to find (c,d)-Kempe chain containing v
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        component = set()
                        while queue:
                            x = queue.popleft()
                            component.add(x)
                            for y in adj_list[x]:
                                if color[y] == c or color[y] == d:
                                    if y not in visited:
                                        visited.add(y)
                                        queue.append(y)
                        # check if we can swap: no neighbor of component has color d outside component
                        can_swap = True
                        for x in component:
                            for y in adj_list[x]:
                                if color[y] == d and y not in component:
                                    can_swap = False
                                    break
                            if not can_swap:
                                break
                        if can_swap:
                            # swap colors c and d in component
                            for x in component:
                                if color[x] == c:
                                    color[x] = d
                                elif color[x] == d:
                                    color[x] = c
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if not changed:
                break
        # compact colors
        # map old colors to new consecutive colors
        unique_colors = sorted(set(color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        color = [mapping[c] for c in color]
        return color

    # Generate candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_color = None
    min_colors = float('inf')
    for col in candidates:
        # validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = len(set(col))
        if k < min_colors:
            min_colors = k
            best_color = col

    # fallback: greedy by degree
    if best_color is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_color = color

    # apply Kempe reduction to best candidate
    best_color = kempe_reduce(best_color)

    # final validation and compaction
    unique_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best_color = [mapping[c] for c in best_color]

    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for i in range(n):
            if len(adj[i]) != n:
                all_binary = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build adjacency list and bit masks
    if is_matrix:
        neighbors = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        neighbors = [list(lst) for lst in adj]
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for j in neighbors[i]:
                mask |= (1 << j)
            bit_adj[i] = mask
    # Helper: test if coloring is valid
    def is_valid(col):
        for u in range(n):
            cu = col[u]
            mask = bit_adj[u]
            while mask:
                v = (mask & -mask).bit_length() - 1
                if col[v] == cu:
                    return False
                mask &= mask - 1
        return True
    # Helper: number of colors used
    def num_colors(col):
        if not col:
            return 0
        return max(col) + 1
    # Helper: convert to consecutive colors
    def normalize(col):
        mapping = {}
        next_color = 0
        for i in range(n):
            c = col[i]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            col[i] = mapping[c]
        return col
    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets as bit masks
        neighbor_colors = [0] * n
        uncolored = set(range(n))
        # initial degree for tie-breaking
        degree = [len(neighbors[i]) for i in range(n)]
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and degree[u] > max_deg) or \
                   (sat[u] == max_sat and degree[u] == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat[u]
                    max_deg = degree[u]
                    v = u
            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if color[u] == -1:
                    # add color c to neighbor's palette if not present
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1
        return color
    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0
        while uncolored:
            # build maximal independent set for current_color
            # degree in induced subgraph of uncolored
            deg_uncolored = [0] * n
            for u in uncolored:
                cnt = 0
                for v in neighbors[u]:
                    if v in uncolored:
                        cnt += 1
                deg_uncolored[u] = cnt
            # select vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            # U: vertices not adjacent to any in S
            # W: vertices adjacent to at least one in S
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent = False
                for w in S:
                    if u in neighbors[w]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = None
                for u in U:
                    # count neighbors in W
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # tie-break: min degree in U
                    deg_u = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and (best_deg_U is None or deg_u < best_deg_U)):
                        best_score = score
                        best_deg_U = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for u in S:
                color[u] = current_color
                uncolored.remove(u)
            current_color += 1
        return color
    # Smallest-Last ordering
    def smallest_last():
        # core decomposition ordering
        degree = [len(neighbors[i]) for i in range(n)]
        # bin vertices by degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            bins[d].append(v)
        # pointer to current non-empty bin
        pos = 0
        order = []
        # current degree array (will be updated)
        curr_deg = degree[:]
        removed = [False] * n
        for _ in range(n):
            # find non-empty bin
            while pos <= max_deg and not bins[pos]:
                pos += 1
            if pos > max_deg:
                break  # should not happen
            v = bins[pos].pop()
            while removed[v]:
                if not bins[pos]:
                    break
                v = bins[pos].pop()
            if removed[v]:
                # find another
                found = False
                for d in range(pos, max_deg + 1):
                    while bins[d]:
                        w = bins[d].pop()
                        if not removed[w]:
                            v = w
                            found = True
                            break
                    if found:
                        break
                if not found:
                    break
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    if d > 0:
                        curr_deg[u] -= 1
                        # move u to bin d-1
                        bins[d-1].append(u)
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Kempe chain swap for colors a and b, starting from vertex v, returns new coloring if swap performed
    def kempe_swap(color, a, b, v):
        # BFS to get component of v in (a,b) subgraph
        from collections import deque
        comp = set()
        q = deque([v])
        comp.add(v)
        while q:
            u = q.popleft()
            for w in neighbors[u]:
                if color[w] == a or color[w] == b:
                    if w not in comp:
                        comp.add(w)
                        q.append(w)
        # swap colors a<->b in comp
        new_color = color[:]
        for u in comp:
            if new_color[u] == a:
                new_color[u] = b
            elif new_color[u] == b:
                new_color[u] = a
        return new_color
    # Try to eliminate a color class using Kempe chains
    def reduce_colors(color):
        k = num_colors(color)
        if k <= 1:
            return color
        # try from highest color down
        for target in range(k-1, 0, -1):
            # collect vertices with color target
            verts = [v for v in range(n) if color[v] == target]
            if not verts:
                continue
            # try to recolor each vertex
            made_change = False
            for v in verts:
                # try direct reassignment to a lower color
                neighbor_colors = 0
                for u in neighbors[v]:
                    c = color[u]
                    if c < target:
                        neighbor_colors |= (1 << c)
                for c in range(target):
                    if not (neighbor_colors & (1 << c)):
                        # direct move possible
                        color[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # check if v is isolated in (c,target) subgraph? 
                    # Actually, we try to swap a component that does not contain any vertex of color c that is neighbor to v?
                    # Standard: if there is a (c,target)-Kempe chain starting at v that does not include any neighbor of v colored c, then swapping frees color c for v.
                    # We'll implement: find the component of v in (c,target) subgraph, check if any neighbor of v colored c is in that component.
                    comp = set()
                    stack = [v]
                    comp.add(v)
                    while stack:
                        u = stack.pop()
                        for w in neighbors[u]:
                            if color[w] == c or color[w] == target:
                                if w not in comp:
                                    comp.add(w)
                                    stack.append(w)
                    # check if any neighbor of v with color c is in comp
                    conflict = False
                    for u in neighbors[v]:
                        if color[u] == c and u in comp:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for u in comp:
                            if color[u] == c:
                                color[u] = target
                            elif color[u] == target:
                                color[u] = c
                        made_change = True
                        break
                if made_change:
                    break
            if not made_change:
                # cannot eliminate this color, try lower target
                continue
            else:
                # we made a change, need to rebuild color classes and try again from high
                # normalize to fill gaps
                color = normalize(color)
                k = num_colors(color)
                # restart reduction from new highest color
                return reduce_colors(color)
        # if we get here, no reduction possible
        return color
    # Main: run multiple heuristics and pick best
    random.seed(42)  # for deterministic tie-breaking
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # If no candidate, fallback to greedy
    if not candidates:
        color = [0] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                if color[j] != -1:
                    used |= (1 << color[j])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        candidates.append(color)
    # Pick candidate with fewest colors
    best = min(candidates, key=num_colors)
    best = normalize(best)
    # Apply Kempe chain reduction
    best = reduce_colors(best)
    best = normalize(best)
    # Final validation (should be valid)
    if not is_valid(best):
        # fallback to greedy
        color = [0] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                if color[j] != -1:
                    used |= (1 << color[j])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        color = normalize(color)
    return color

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list and bitmask
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        neighbors = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        neighbors = [list(set(lst)) for lst in adj]  # Deduplicate

    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= 1 << j
        bit_adj[i] = mask

    def is_valid_coloring(colors):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    def greedy_first_fit(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                if colors[v] != -1:
                    used |= 1 << colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    def dsatur():
        colors = [-1] * n
        saturated = [0] * n
        uncolored = set(range(n))
        # Initial: pick vertex with max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            colors[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] = 1  # neighbor has color 0
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat = saturated[v]
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                # All saturation 0, pick max degree in uncolored
                v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            else:
                # Tie-break by degree in uncolored subgraph
                v = max(candidates, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            # Assign smallest available color
            used = 0
            for y in neighbors[v]:
                if colors[y] != -1:
                    used |= 1 << colors[y]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for y in neighbors[v]:
                if y in uncolored:
                    # Check if color c is new to y's neighborhood
                    has_color = False
                    for z in neighbors[y]:
                        if colors[z] == c:
                            has_color = True
                            break
                    if not has_color:
                        saturated[y] += 1
        return colors

    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            independent_set = {v}
            uncolored.remove(v)
            # Partition: U = not adjacent to independent_set, W = adjacent
            W = set()
            for u in list(uncolored):
                if any(w in neighbors[u] for w in independent_set):
                    W.add(u)
            U = uncolored - W
            while U:
                # Select u in U with max neighbors in W
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = len([w for w in neighbors[u] if w in W])
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in U
                        deg_u = len([x for x in neighbors[u] if x in U])
                        if best_u is None or deg_u < len([x for x in neighbors[best_u] if x in U]):
                            best_u = u
                if best_u is None:
                    break  # Should not happen
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for y in neighbors[best_u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color to independent_set
            for v in independent_set:
                colors[v] = color
            color += 1
        return colors

    def smallest_last():
        # Compute degeneracy ordering (smallest-last)
        degrees = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current min non-empty bucket
        min_deg = 0
        while remaining:
            # Find next non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degrees[u]
                    # Remove u from bucket d
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    degrees[u] -= 1
                    buckets[degrees[u]].append(u)
                    if degrees[u] < min_deg:
                        min_deg = degrees[u]
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= 1 << colors[u]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    def kempe_reduce(colors):
        # Map color to set of vertices
        color_classes = {}
        for v, c in enumerate(colors):
            color_classes.setdefault(c, set()).add(v)
        max_color = max(color_classes.keys()) if color_classes else -1
        # Try to eliminate color classes from highest down
        changed = True
        while changed and max_color >= 0:
            changed = False
            # Try to eliminate the smallest color class (by size) to reduce max color
            # But we aim to reduce the number of colors, so target highest color
            target_color = max_color
            if target_color not in color_classes or not color_classes[target_color]:
                max_color -= 1
                continue
            # Try to recolor each vertex in target_color to a lower color
            for v in list(color_classes[target_color]):
                used_by_neighbors = 0
                for u in neighbors[v]:
                    c_u = colors[u]
                    if c_u != -1:
                        used_by_neighbors |= 1 << c_u
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Move v to color c
                        color_classes[target_color].remove(v)
                        color_classes.setdefault(c, set()).add(v)
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break  # Restart after change
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # If v already has a neighbor of color c, swapping might not help directly
                    # Build (c, target_color) Kempe chain containing v
                    # We'll do BFS to get the component
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in neighbors[x]:
                            if y not in visited and (colors[y] == c or colors[y] == target_color):
                                visited.add(y)
                                queue.append(y)
                    # Check if we can swap: after swap, v would be color c
                    # We need to ensure that no neighbor of v becomes color c after swap (which would cause conflict)
                    # Actually, swapping colors in component: c->target_color, target_color->c
                    # For v, after swap it becomes c.
                    # Check neighbors of v: if any neighbor has color c and is NOT in component, then after swap that neighbor remains c -> conflict.
                    # If neighbor has color c and is in component, after swap it becomes target_color -> no conflict.
                    # If neighbor has color target_color and is in component, after swap it becomes c -> but v becomes c -> conflict if adjacent.
                    # So we need: for all neighbors u of v:
                    #   if colors[u] == c and u not in component -> conflict after swap
                    #   if colors[u] == target_color and u in component -> conflict after swap (since both become c)
                    # Actually, simpler: after swap, the color of v is c.
                    # So we need that no neighbor of v has color c after swap.
                    # Neighbors of v after swap:
                    #   if u in component: color flips (c<->target_color)
                    #   if u not in component: color unchanged
                    # So neighbor u has color c after swap iff:
                    #   (u in component and original color == target_color) OR (u not in component and original color == c)
                    conflict = False
                    for u in neighbors[v]:
                        if u in component:
                            if colors[u] == target_color:
                                conflict = True
                                break
                        else:
                            if colors[u] == c:
                                conflict = True
                                break
                    if not conflict:
                        # Perform swap
                        for x in component:
                            if colors[x] == c:
                                colors[x] = target_color
                                color_classes[c].remove(x)
                                color_classes.setdefault(target_color, set()).add(x)
                            elif colors[x] == target_color:
                                colors[x] = c
                                color_classes[target_color].remove(x)
                                color_classes.setdefault(c, set()).add(x)
                        changed = True
                        break
                if changed:
                    break
            if not changed:
                # Could not eliminate target_color, try next lower
                max_color -= 1
        # Compact colors: remap to 0..k-1
        unique_colors = sorted(set(colors))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        colors = [mapping[c] for c in colors]
        return colors

    # Run multiple heuristics and keep the best
    best_colors = None
    best_num_colors = float('inf')
    start_time = time.time()
    heuristics = [
        ("greedy_degree", lambda: greedy_first_fit(sorted(range(n), key=lambda x: -len(neighbors[x])))),
        ("greedy_random", lambda: greedy_first_fit(list(random.sample(range(n), n)))),
        ("dsatur", dsatur),
        ("rlf", rlf),
        ("smallest_last", smallest_last),
    ]
    for name, heuristic in heuristics:
