    if is_matrix:
        neighbors = []
        for i in range(n):
            row = []
            for j in range(n):
                if adj[i][j] == 1:
                    row.append(j)
            neighbors.append(row)
    else:
        neighbors = adj

    # Compute degree for each vertex
    degree = [len(neighbors[i]) for i in range(n)]

    # Special cases
    if n == 1:
        return [0]

    max_deg = max(degree) if degree else 0
    if max_deg == 0:
        return [0] * n

    if max_deg == n - 1:
