    # Smallest-Last
    try:
        col3 = smallest_last()
        if is_valid_coloring(col3):
            candidates.append(col3)
    except:
        pass

    # If no candidates (shouldn't happen), fallback to greedy
    if not candidates:
        # Simple greedy by degree order
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        coloring = [-1] * n
        for v in order:
            used = set()
