    used = set(reduced)
    if used:
        mapping = {old: new for new, old in enumerate(sorted(used))]
        reduced = [mapping[c] for c in reduced]

    return reduced

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            if len(row) != len(adj):
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets and bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue
                neighbors[i].add(j)
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        uncolored = set(range(n))
        # Precompute degrees for tie-breaking
        degree = [len(neighbors[i]) for i in range(n)]
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat = saturation[v].bit_count()
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                # All uncolored have saturation 0, pick max degree in uncolored
                max_deg = -1
                for v in uncolored:
                    d = degree[v]
                    if d > max_deg:
                        max_deg = d
                        candidates = [v]
                    elif d == max_deg:
                        candidates.append(v)
            v = random.choice(candidates)
            # Assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
        return color

    # 2. RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v0 = -1
            for v in uncolored:
                # degree in uncolored subgraph
                deg = sum(1 for u in neighbors[v] if u in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
                elif deg == max_deg and v0 == -1:
                    v0 = v
            if v0 == -1:
                break  # should not happen
            S = {v0}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = uncolored - {v0} - neighbors[v0]
            W = neighbors[v0] & uncolored
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break: min degree in G[U]
                        deg_u = sum(1 for w in neighbors[u] if w in U)
                        deg_best = sum(1 for w in neighbors[best_u] if w in U) if best_u != -1 else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u == -1:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use buckets for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    deg[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # Also try Welsh-Powell (sort by degree descending)
    try:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(col)
    except Exception:
        pass

    # Select best candidate (min colors)
    for col in candidates:
        k = count_colors(col)
        if k < best_k:
            best_k = k
            best_coloring = col

    # If no candidate found (should not happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find color classes
            classes = {}
            for v in range(n):
                c = col[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            # Sort colors by class size (smallest first)
            sorted_colors = sorted(classes.keys(), key=lambda x: len(classes[x]))
            # Try to eliminate each color class from smallest to largest
            for c in sorted_colors:
                if c >= len(col):  # safety
                    continue
                if not classes[c]:  # already empty
                    continue
                # Try to recolor each vertex in class c
                for v in classes[c]:
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in neighbors[v]:
                        cu = col[u]
                        if cu != -1:
                            used |= (1 << cu)
                    for c_new in range(c):  # only try colors < c
                        if not (used & (1 << c_new)):
                            col[v] = c_new
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chains with each lower color
                    for c_new in range(c):
                        # Find the Kempe chain component containing v for colors (c, c_new)
                        # We'll do BFS to get the component
                        from collections import deque
                        comp = set()
                        queue = deque([v])
                        comp.add(v)
                        while queue:
                            node = queue.popleft()
                            for u in neighbors[node]:
                                if col[u] == c or col[u] == c_new:
                                    if u not in comp:
                                        comp.add(u)
                                        queue.append(u)
                        # Check if we can swap: after swap, no neighbor of v will have color c_new (except possibly via chain)
                        # Actually, swapping the component will change v's color to c_new, and we need to ensure
                        # that no neighbor of v has color c_new after swap (but note: neighbors in the component
                        # that had c_new will become c, and neighbors not in component remain same)
                        # So we need to check: for all neighbors u of v, if u is in the component, then after swap
                        # its color becomes the opposite; if not in component, color remains.
                        # We want that after swap, no neighbor has color c_new.
                        # For a neighbor u of v:
                        #   If u in comp: 
                        #       if col[u] == c -> becomes c_new -> conflict if we want v to be c_new? 
                        #       Actually, we are swapping to make v become c_new. So if a neighbor u in comp had color c,
                        #       after swap it becomes c_new -> then u and v both would be c_new -> conflict.
                        #   Therefore, we can only swap if there is no neighbor u of v in the component that has color c.
                        #   Because after swap, such u would become c_new and conflict with v (which becomes c_new).
                        #   Similarly, if a neighbor u of v in the component has color c_new, after swap it becomes c,
                        #   which is not c_new, so no conflict.
                        # So condition: no neighbor u of v in the component has color c.
                        conflict = False
                        for u in neighbors[v]:
                            if u in comp and col[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            # Perform the swap
                            for node in comp:
                                if col[node] == c:
                                    col[node] = c_new
                                elif col[node] == c_new:
                                    col[node] = c
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # If we made a change, rebuild classes and continue
            if changed:
                # Rebuild classes for next iteration
                classes = {}
                for v in range(n):
                    c = col[v]
                    if c not in classes:
                        classes[c] = []
                    classes[c].append(v)
            else:
                # No change in this pass, break
                break
        # Compact colors: map to 0..k-1
        unique_colors = sorted(set(col))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        col = [mapping[c] for c in col]
        return col

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)
    # Final validation (should be valid)
    if not is_valid(best_coloring):
        # Fallback to greedy on natural order
        best_coloring = greedy_color(list(range(n)))
        # Compact
        unique_colors = sorted(set(best_coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle trivial cases
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute bitmasks
    if is_matrix:
        neighbors = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        neighbors = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in neighbors[i]:
                bit_adj[i] |= (1 << j)

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            cu = colors[u]
            for v in neighbors[u]:
                if cu == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            # Find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: DSATUR
    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by max uncolored degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = uncolored_deg[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and (best_v == -1 or random.random() < 0.5)):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return colors

    # Helper: RLF
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in neighbors[u] if w in W)
                    u_deg = sum(1 for w in neighbors[u] if w in U)
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or (w_neighbors == best_w_neighbors and u_deg == best_u_deg and (best_u == -1 or random.random() < 0.5)):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to S
            for v in S:
                colors[v] = color_idx
            uncolored -= S
            color_idx += 1
        return colors

    # Helper: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(neighbors[i]) for i in range(n)]
        # We'll use a list of sets for buckets, but n <= 100, so simple scan is fine
        order = []
        remaining = set(range(n))
        # Current degree in remaining subgraph
        curr_deg = deg[:]
        for _ in range(n):
            # Find vertex with minimum current degree
            v = min(remaining, key=lambda x: curr_deg[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    curr_deg[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fall back to greedy by index
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_k = num_colors(best)

    # Kempe chain-based color reduction
    def eliminate_color_class(colors, k):
        # Try to eliminate color k-1
        target = k - 1
        # Get vertices with target color
        target_vertices = [v for v in range(n) if colors[v] == target]
        if not target_vertices:
            return colors, k - 1  # already eliminated

        # Try to reassign each target vertex to a lower color
        changed = True
        while changed and target_vertices:
            changed = False
            v = target_vertices.pop()
            # Check direct reassignment to any color < target
            for c in range(target):
                # Check if color c is available (no neighbor has color c)
                conflict = False
                for u in neighbors[v]:
                    if colors[u] == c:
                        conflict = True
                        break
                if not conflict:
                    colors[v] = c
                    changed = True
                    break
            if not changed:
                # Try Kempe chain swap with each color c < target
                for c in range(target):
                    # Build the (c, target) Kempe chain containing v
                    # We'll do BFS to get the component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (colors[y] == c or colors[y] == target):
                                visited[y] = True
                                queue.append(y)
                    # Check if swapping in this component is safe: 
                    # After swap, no two adjacent vertices will have same color.
                    # Since we only swap c and target, and the component is connected via edges
                    # where both endpoints are in {c, target}, after swap they remain in {c, target}
                    # and adjacent vertices originally had different colors (one c, one target) 
                    # so after swap they still have different colors.
                    # However, we must check vertices outside the component: 
                    # For a vertex x in component, its neighbors outside component must not 
                    # have the color that x will become after swap.
                    # Specifically, if x is in component and has color c, after swap it becomes target.
                    # We must ensure no neighbor of x outside component has color target.
                    # Similarly, if x has color target, after swap becomes c, so no neighbor outside has color c.
                    safe = True
                    for x in component:
                        cx = colors[x]
                        for y in neighbors[x]:
                            if not visited[y]:  # y outside component
                                cy = colors[y]
                                if cx == c and cy == target:
                                    safe = False
                                    break
                                if cx == target and cy == c:
                                    safe = False
                                    break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for x in component:
                            if colors[x] == c:
                                colors[x] = target
                            else:
                                colors[x] = c
                        changed = True
                        break
                if not changed:
                    # Could not reassign v, keep it in target_vertices for now
                    target_vertices.append(v)
        # After attempts, reassign any remaining target vertices to target color (should be few)
        # But we want to eliminate the color, so if any remain, we failed.
        remaining_target = [v for v in range(n) if colors[v] == target]
        if not remaining_target:
            # Successfully eliminated color target: compact colors
            # Map colors > target down by 1
            for v in range(n):
                if colors[v] > target:
                    colors[v] -= 1
            return colors, k - 1
        else:
            # Could not eliminate, return original
            return colors, k

    # Iteratively try to reduce colors
    current_colors = best[:]
    current_k = best_k
    improved = True
    # Limit iterations to avoid infinite loop
    for _ in range(current_k):  # at most k iterations
        if current_k <= 1:
            break
        new_colors, new_k = eliminate_color_class(current_colors[:], current_k)
        if new_k < current_k:
            current_colors = new_colors
            current_k = new_k
            improved = True
        else:
            # No improvement in this attempt
            break

    # Final validation and ensure consecutive colors
    if not is_valid_coloring(current_colors):
        # Fallback to best candidate if Kempe broke validity
        current_colors = best
        current_k = best_k

    # Compact colors to 0..k-1
    color_map = {}
    next_color = 0
    for v in range(n):
        c = current_colors[v]
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        current_colors[v] = color_map[c]

    return current_colors

