    # Ensure symmetry (undirected graph)
    for i in range(n):
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].add(i)
                bit_adj[j] |= (1 << i)
    # Helper: greedy coloring given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            # Find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Helper: count unique colors
    def count_colors(coloring):
        return len(set(coloring)) if coloring else 0
    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True
    # DSATUR with degree tie-breaking
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg_uncolored = [len(neighbors[i]) for i in range(n)]
        while uncolored:
            # select vertex with max sat, tie-break by deg_uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = deg_uncolored[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # assign smallest color not in sat[v]
            c = 0
            while sat[v] & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color
    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # degree in uncolored subgraph
            deg = {v: len([u for u in neighbors[v] if u in uncolored]) for v in uncolored}
            # start with vertex of max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and not (neighbors[u] & S)}
            # W: vertices adjacent to S
            W = {u for u in uncolored if u != v and (neighbors[u] & S)}
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_u = None
                for u in U:
                    score = len(neighbors[u] & W)
                    deg_u = len([x for x in neighbors[u] if x in U])  # degree in G[U]
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or (score == best_score and deg_u == best_deg_u and random.random() < 0.5):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in list(neighbors[u] & U):
                    U.remove(w)
                    W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
