    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    buckets[d].remove(u)
                    buckets[d-1].append(u)
                    if d-1 < min_deg:
                        min_deg = d-1
        # color in reverse order
        return greedy_color(order[::-1])
    # Welsh-Powell ordering (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)
    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring
        # map color to vertices
        color_classes = {}
        for v, c in enumerate(coloring):
            color_classes.setdefault(c, []).append(v)
        colors = sorted(color_classes.keys())
        # try to eliminate highest color classes
        changed = True
        while changed and len(color_classes) > 1:
            changed = False
            # target highest color
            max_color = max(color_classes.keys())
            vertices = color_classes[max_color][:]
            # try to recolor each vertex in this class
            for v in vertices:
                if coloring[v] != max_color:  # might have been recolored
                    continue
                # try direct reassignment to lower color
                neighbor_colors = set()
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        neighbor_colors.add(coloring[u])
                for c in range(max_color):  # try colors 0..max_color-1
                    if c not in neighbor_colors:
                        # recolor v to c
                        coloring[v] = c
                        color_classes[c].append(v)
                        color_classes[max_color].remove(v)
                        if not color_classes[max_color]:
                            del color_classes[max_color]
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(max_color):
                    if coloring[v] != max_color:
                        break
                    # if v already can take color c, skip (should have been caught)
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if coloring[u] != -1:
                            neighbor_colors.add(coloring[u])
                    if c not in neighbor_colors:
                        continue
                    # BFS for (c, max_color) Kempe chain starting at v
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in neighbors[x]:
                            if y not in visited and coloring[y] in (c, max_color):
                                visited.add(y)
                                queue.append(y)
                    # check if swapping colors in component frees color c for v
                    # after swap, v would have color c, so we need that no neighbor of v has color c after swap
                    # neighbors of v that are in component will change color: if they were c -> max_color, if max_color -> c
                    # so we need that no neighbor of v is in component and has color c (because after swap it becomes max_color, ok)
                    # and no neighbor of v has color max_color and is not in component (because after swap it stays max_color, conflict)
                    # Actually, simpler: after swap, for each neighbor u of v:
                    #   if u in component: new_color = c if coloring[u]==max_color else max_color
                    #   else: new_color = coloring[u]
                    # we need new_color != c for all u in neighbors[v]
                    conflict = False
                    for u in neighbors[v]:
                        col_u = coloring[u]
                        if u in component:
                            new_col = c if col_u == max_color else max_color
                        else:
                            new_col = col_u
                        if new_col == c:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = max_color
                                color_classes[max_color].append(x)
                                color_classes[c].remove(x)
                            elif coloring[x] == max_color:
                                coloring[x] = c
                                color_classes[c].append(x)
                                color_classes[max_color].remove(x)
                        # v is now color c
                        if not color_classes[max_color]:
                            del color_classes[max_color]
                        changed = True
                        break
            # if no change, break
            if not changed:
                break
            # rebuild color_classes and colors for next iteration
            color_classes = {}
            for v, c in enumerate(coloring):
                color_classes.setdefault(c, []).append(v)
            colors = sorted(color_classes.keys())
        # compact colors to 0..k-1
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]
    # Generate candidate colorings
    candidates = []
    start = time.time()
    # DSATUR
    col_dsatur = dsatur()
    if is_valid(col_dsatur):
        candidates.append(col_dsatur)
    # RLF
    col_rlf = rlf()
    if is_valid(col_rlf):
        candidates.append(col_rlf)
    # Smallest-Last
    col_sl = smallest_last()
    if is_valid(col_sl):
        candidates.append(col_sl)
    # Welsh-Powell
    col_wp = welsh_powell()
    if is_valid(col_wp):
        candidates.append(col_wp)
    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        col_greedy = greedy_color(list(range(n)))
        candidates.append(col_greedy)
    # Select best (fewest colors)
    best = min(candidates, key=count_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation (should hold)
    if not is_valid(best):
        # fallback to DSATUR if something went wrong
        best = dsatur()
    return best

