        return compact_colors(color)

    # RLF
    def rlf():
        color = [-1] * n
        colored = [False] * n
        c = 0
        while not all(colored):
            # R: uncolored vertices
            R = [v for v in range(n) if not colored[v]]
            if not R:
                break
            # S: independent set for color c
            S = []
            # pick vertex with max degree in G[R]
            max_deg = -1
            v1 = R[0]
            for v in R:
                deg = 0
                nbrs = bit_adj[v]
                while nbrs:
                    u = (nbrs & -nbrs).bit_length() - 1
                    if not colored[u]:
                        deg += 1
                    nbrs &= nbrs - 1
                if deg > max_deg:
                    max_deg = deg
                    v1 = v
            S.append(v1)
            # U: vertices not adjacent to S, W: adjacent to S
            U = set()
            W = set()
            for v in R:
                if v == v1:
                    continue
                adjacent = False
                nbrs = bit_adj[v]
                while nbrs:
                    u = (nbrs & -nbrs).bit_length() - 1
                    if u in S:
                        adjacent = True
                        break
                    nbrs &= nbrs - 1
                if adjacent:
                    W.add(v)
                else:
                    U.add(v)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_nbrs = 0
                    nbrs = bit_adj[u]
                    while nbrs:
                        w = (nbrs & -nbrs).bit_length() - 1
                        if w in W:
                            w_nbrs += 1
                        nbrs &= nbrs - 1
                    if w_nbrs > max_w_neighbors:
                        max_w_neighbors = w_nbrs
                        best_u = u
                    elif w_nbrs == max_w_neighbors:
                        # tie-break: min degree in G[U]
                        if best_u is None:
                            best_u = u
                            continue
                        deg_u = 0
                        nbrs_u = bit_adj[u]
                        while nbrs_u:
                            w = (nbrs_u & -nbrs_u).bit_length() - 1
                            if w in U:
                                deg_u += 1
                            nbrs_u &= nbrs_u - 1
                        deg_best = 0
                        nbrs_best = bit_adj[best_u]
                        while nbrs_best:
                            w = (nbrs_best & -nbrs_best).bit_length() - 1
                            if w in U:
                                deg_best += 1
                            nbrs_best &= nbrs_best - 1
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break  # should not happen
                S.append(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                nbrs = bit_adj[best_u]
                while nbrs:
                    w = (nbrs & -nbrs).bit_length() - 1
                    if w in U:
                        U.remove(w)
                        W.add(w)
                    nbrs &= nbrs - 1
            # assign color c to all in S
            for v in S:
                color[v] = c
                colored[v] = True
            c += 1
        return compact_colors(color)

    # Smallest-Last ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [0] * n
        for v in range(n):
            degree[v] = bin(bit_adj[v]).count('1')
        order = []
        # we will store the order in which vertices are removed (smallest last)
        # so we need to reverse it for coloring
        removal_order = []
        temp_deg = degree[:]
        current_set = set(range(n))
        for _ in range(n):
            # find vertex with min temp_deg in current_set
            min_v = None
            min_deg = float('inf')
            for v in current_set:
                if temp_deg[v] < min_deg:
                    min_deg = temp_deg[v]
                    min_v = v
            if min_v is None:
                break
            removal_order.append(min_v)
            current_set.remove(min_v)
            # update degrees of neighbors
            nbrs = bit_adj[min_v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                if u in current_set:
                    temp_deg[u] -= 1
                nbrs &= nbrs - 1
        # color in reverse removal order
        order = removal_order[::-1]
        return greedy_color(order)

    # Kempe chain swap for colors a and b, starting from vertex v, returns new coloring if swap performed, else None
    def kempe_swap(coloring, v, a, b):
        n = len(coloring)
        # BFS to get the Kempe chain component containing v for colors a and b
        from collections import deque
        visited = [False] * n
        queue = deque([v])
        visited[v] = True
        component = []
        while queue:
            u = queue.popleft()
            component.append(u)
            nbrs = bit_adj[u]
            while nbrs:
                w = (nbrs & -nbrs).bit_length() - 1
                if not visited[w] and (coloring[w] == a or coloring[w] == b):
                    visited[w] = True
                    queue.append(w)
                nbrs &= nbrs - 1
        # check if swapping is valid: no neighbor outside component has color a or b that would conflict
        # Actually, swapping within a component always preserves validity because:
        # - edges inside component: colors swapped, so if they were different, still different
        # - edges from component to outside: outside vertex has color not a or b (by maximality), so after swap,
        #   the component vertex color changes from a to b or b to a, but outside vertex color is neither, so still different.
        # So we can always swap.
        # Perform swap
        new_coloring = coloring[:]
        for u in component:
            if new_coloring[u] == a:
                new_coloring[u] = b
            elif new_coloring[u] == b:
                new_coloring[u] = a
        return new_coloring

    # Iterative color reduction using Kempe chains
    def reduce_colors(initial_coloring):
        coloring = compact_colors(initial_coloring)
        if not is_valid(coloring):
            return coloring  # should not happen
        changed = True
        while changed:
            changed = False
            k = num_colors(coloring)
            if k <= 1:
                break
            # target smallest color class (color k-1)
            target_color = k - 1
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                # already compacted?
                coloring = compact_colors(coloring)
                continue
            # Try to recolor each vertex in target class
            for v in vertices:
                # Try direct reassignment to a lower color
                used = 0
                nbrs = bit_adj[v]
                while nbrs:
                    u = (nbrs & -nbrs).bit_length() - 1
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                    nbrs &= nbrs - 1
                for c in range(target_color):  # try colors 0..k-2
                    if not (used & (1 << c)):
                        # can recolor v to c
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Try to swap along (target_color, c) Kempe chain starting from v
                    # Only if v is in the target_color class
                    if coloring[v] != target_color:
                        continue
                    new_col = kempe_swap(coloring, v, target_color, c)
                    if new_col is None:
                        continue
                    # Check if after swap, v is no longer target_color (i.e., we moved it)
                    if new_col[v] != target_color:
                        coloring = compact_colors(new_col)
                        changed = True
                        break
                    # Also check if we eliminated the target color class entirely
                    if target_color not in new_col:
                        coloring = compact_colors(new_col)
                        changed = True
                        break
                if changed:
                    break
            # After attempting to recolor, compact again
            coloring = compact_colors(coloring)
        return coloring

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidate, fallback to greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        candidates.append(greedy_color(order))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = reduce_colors(best)
    # Final validation and compaction
    if not is_valid(best):
        # ultimate fallback: greedy
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        best = greedy_color(order)
    best = compact_colors(best)
    return best

