            is_matrix = True
    # Build neighbor sets and bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)
    # Ensure symmetry
    for u in range(n):
        for v in neighbors[u]:
            if u not in neighbors[v]:
                neighbors[v].add(u)
                bit_adj[v] |= (1 << u)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

