    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([y for y in neighbors[x] if y in uncolored]), x))
            # Assign smallest available color
            used = 0
            for y in neighbors[v]:
                c = color[y]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for y in neighbors[v]:
                if y in uncolored:
                    sat[y] += 1
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S = {v}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v} - neighbors[v]
            W = set(neighbors[v]) & uncolored
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([y for y in neighbors[x] if y in W]), -len([y for y in neighbors[x] if y in U]), x))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[u]) for u in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # Remove a vertex of minimum degree
            while buckets[ptr] and buckets[ptr][-1] not in remaining:
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for y in neighbors[v]:
                if y in remaining:
                    d = degree[y]
                    degree[y] -= 1
                    if d < len(buckets):
                        buckets[d].append(y)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Welsh-Powell ordering (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
