    # Detect adjacency matrix or adjacency list
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Convert adjacency matrix to adjacency list
        adj_list = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
    else:
        adj_list = adj
    # Ensure adjacency list is symmetric (undirected graph)
    for u in range(n):
        for v in adj_list[u]:
            if u not in adj_list[v]:
                adj_list[v].append(u)
    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= 1 << v
        bit_adj[u] = mask
    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True
    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0
    # Helper: get neighbor colors as bitmask
    def neighbor_colors_mask(u, coloring):
        mask = 0
        for v in adj_list[u]:
            c = coloring[v]
            if c >= 0:  # only consider colored neighbors
                mask |= 1 << c
        return mask
    # Helper: smallest available color (mex) for vertex u
    def mex(mask):
        c = 0
        while mask & (1 << c):
            c += 1
        return c
    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighborhood
        saturation = [0] * n
