        colored_mask = [0] * n
        uncolored = set(range(n))
        # initial degree for tie-breaking
        degree = [len(adj_list[u]) for u in range(n)]
        while uncolored:
            # select vertex with max saturation, break ties by degree, then random
            v = max(uncolored, key=lambda x: (saturation[x], degree[x], random.random()))
            # assign smallest available color
            avail_mask = neighbor_colors_mask(v, coloring)
            c = mex(avail_mask)
            coloring[v] = c
            uncolored.remove(v)
            # update saturation and colored_mask for uncolored neighbors
