            U = uncolored - independent_set - {w for u in independent_set for w in adj_list[u]}
            W = {w for u in independent_set for w in adj_list[u] if w in uncolored}
            # greedy expansion of independent set
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
