            removed[v] = True
            # decrease degree of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    degrees[u] -= 1
        # color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(ordering):
            # compute neighbor colors mask
            mask = 0
            for u in adj_list[v]:
                c = coloring[u]
                if c >= 0:
                    mask |= 1 << c
            c = 0
            while mask & (1 << c):
                c += 1
            coloring[v] = c
