                        if current[u] == c:
                            has_neighbor_c = True
                            break
                    if has_neighbor_c:
                        # cannot swap directly because would create conflict
                        continue
                    # build Kempe chain of colors target_color and c starting from v
                    # we want to swap colors in the component of v in the subgraph induced by colors {target_color, c}
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if current[node] == target_color or current[node] == c:
                            component.add(node)
                            for w in adj_list[node]:
                                if w not in visited and (current[w] == target_color or current[w] == c):
                                    stack.append(w)
                    # after building component, check if swapping would cause any conflict
                    # swapping is safe if no vertex in component has a neighbor outside component with the swapped color
                    safe = True
                    # we will swap: target_color -> c, c -> target_color
                    for node in component:
                        new_color = c if current[node] == target_color else target_color
                        for w in adj_list[node]:
                            if w not in component and current[w] == new_color:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # perform swap
                        for node in component:
                            if current[node] == target_color:
                                current[node] = c
                            else:
                                current[node] = target_color
                        progress = True
                        break
                if progress:
                    break
            if not progress:
                # cannot reduce further
                break
            # recompute k and compact colors if needed
            # but we only removed one color class if target_color is now unused
            if target_color not in set(current):
                k -= 1
                # compact colors: remap to 0..k-1
                # but we already removed the highest color, so just shift down if there are gaps?
                # simpler: rebuild mapping
                unique_colors = sorted(set(current))
                mapping = {old: new for new, old in enumerate(unique_colors)}
                for i in range(n):
                    current[i] = mapping[current[i]]
                k = len(unique_colors)
        return current
    # Run all heuristics
    best_coloring = None
    best_k = math.inf
    for heuristic in [dsatur, rlf, smallest_last]:
        coloring = heuristic()
        if not is_valid(coloring):
            # fallback: should not happen, but if so, use greedy
            coloring = [-1] * n
            for u in range(n):
                mask = 0
                for v in adj_list[u]:
                    c = coloring[v]
                    if c >= 0:
                        mask |= 1 << c
                c = 0
                while mask & (1 << c):
                    c += 1
                coloring[u] = c
        k = num_colors(coloring)
        if k < best_k or (k == best_k and best_coloring is None):
            best_k = k
            best_coloring = coloring[:]
    # Apply Kempe reduction to improve
    improved = kempe_reduce(best_coloring)
    if is_valid(improved):
        k_improved = num_colors(improved)
        if k_improved < best_k:
            best_k = k_improved
            best_coloring = improved
    # Ensure colors are consecutive starting from 0
    # (Kempe reduction already does this, but do it again for safety)
    unique_colors = sorted(set(best_coloring))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    for i in range(n):
        best_coloring[i] = mapping[best_coloring[i]]
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True
    # Build neighbor bitmasks and neighbor lists
    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    bit_adj[u] |= 1 << v
                    neighbors[u].append(v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    bit_adj[u] |= 1 << v
                    neighbors[u].append(v)
    # Helper: greedy coloring given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color
    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0
    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Initial: pick vertex with max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if len(candidates) > 1:
                # Tie-break: max degree in uncolored subgraph
                max_deg = -1
                final_candidates = []
                for v in candidates:
                    deg = sum(1 for u in neighbors[v] if u in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        final_candidates = [v]
                    elif deg == max_deg:
                        final_candidates.append(v)
                if len(final_candidates) > 1:
                    v = random.choice(final_candidates)
                else:
                    v = final_candidates[0]
            else:
                v = candidates[0]
            # Assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= 1 << c
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        return color
    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set S
            S = set()
            # Pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            uncolored.remove(v)
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = set()
            W = set()
            for u in uncolored:
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = None
                best_w_neighbors = -1
                best_deg_u = None
                for u in U:
                    w_neighbors = sum(1 for w in neighbors[u] if w in W)
                    deg_u = sum(1 for w in neighbors[u] if w in U)
                    if (w_neighbors > best_w_neighbors or
                        (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or
                        (w_neighbors == best_w_neighbors and deg_u == best_deg_u and u < best_u)):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color
    # Smallest-Last ordering greedy
    def smallest_last():
        # Compute degeneracy ordering (smallest-last)
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # Remove vertices from bucket until we find one still in remaining
            while buckets[ptr]:
                v = buckets[ptr].pop()
                if v in remaining:
                    break
            else:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    deg[u] -= 1
                    if deg[u] < len(buckets):
                        buckets[deg[u]].append(u)
                    else:
                        # Should not happen if buckets sized to max_deg
                        pass
            # Adjust ptr if needed
            if ptr > deg[v]:
                ptr = deg[v]
        # Color in reverse order
        return greedy_color(order[::-1])
    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    # Also try Welsh-Powell (degree ordering)
    candidates.append(greedy_color(sorted(range(n), key=lambda x: -len(neighbors[x]))))
    # Choose the one with minimal colors
    best_coloring = min(candidates, key=num_colors)
    k = num_colors(best_coloring)
    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal n, neighbors, bit_adj
        # Helper: check if coloring is valid
        def is_valid(col):
            for u in range(n):
                cu = col[u]
                for v in neighbors[u]:
                    if cu == col[v]:
                        return False
            return True
        # Helper: get color class sizes
        def color_classes(col):
            if not col:
                return []
            maxc = max(col)
            classes = [[] for _ in range(maxc + 1)]
            for v, c in enumerate(col):
                classes[c].append(v)
            return classes
        # Helper: find Kempe chain component for colors a,b containing v
        def kempe_component(col, a, b, v):
            stack = [v]
            visited = set()
            comp = set()
            while stack:
                u = stack.pop()
                if u in visited:
                    continue
                visited.add(u)
                cu = col[u]
                if cu == a or cu == b:
                    comp.add(u)
                    for w in neighbors[u]:
                        if w not in visited:
                            cw = col[w]
                            if cw == a or cw == b:
                                stack.append(w)
            return comp
        # Helper: swap colors a,b in component
        def swap_in_component(col, comp, a, b):
            new_col = col[:]
            for v in comp:
                if new_col[v] == a:
                    new_col[v] = b
                elif new_col[v] == b:
                    new_col[v] = a
            return new_col
        # Main reduction loop
        improved = True
        while improved and k > 1:
            improved = False
            classes = color_classes(coloring)
            # Target smallest color class (highest index)
            for target_color in range(k-1, -1, -1):
                if not classes[target_color]:
                    continue
                # Try to recolor each vertex in this class
                for v in classes[target_color][:]:  # copy list
                    cv = coloring[v]
                    # Try direct reassignment to a lower color
                    for c in range(target_color):
                        conflict = False
                        for u in neighbors[v]:
                            if coloring[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            # Move v to color c
                            coloring[v] = c
                            improved = True
                            break
                    if improved:
                        break
                    # Try Kempe chain swaps with each lower color
                    for c in range(target_color):
                        comp = kempe_component(coloring, cv, c, v)
                        # Check if swapping frees color c for v (i.e., v not in comp or after swap v gets c)
                        # Actually, if v is in comp, after swap it will have color c
                        # We need to ensure that no vertex in comp that is adjacent to v and has color c will cause conflict?
                        # But since we only swap within the component, and v is in comp, after swap v becomes c.
                        # The only potential issue is if there is a neighbor of v outside the component with color c.
                        # However, if such neighbor exists, then v would have been adjacent to it and both would be in the Kempe component? 
                        # Actually, no: the Kempe component is maximal with respect to colors a,b. If a neighbor u of v has color c (which is one of a,b) and is adjacent to v, then u should be in the component.
                        # So if we swap the component, v becomes c, and all neighbors in the component that were c become a, so no conflict.
                        # Neighbors outside the component have color not a or b, so no conflict.
                        # Therefore, swap is always safe.
                        # Perform swap
                        coloring = swap_in_component(coloring, comp, cv, c)
                        improved = True
                        break
                    if improved:
                        break
                if improved:
                    break
                # If we managed to eliminate the target color class, break and restart
                if not any(coloring[v] == target_color for v in range(n)):
                    break
            # Compact colors if highest color class is empty
            while k > 0 and not any(coloring[v] == k-1 for v in range(n)):
                k -= 1
                # Reindex colors to be 0..k-1
                mapping = {}
                for c in range(k):
                    mapping[c] = c
                # Actually, we just need to shift down if there are gaps, but we ensure no gaps by construction
                # Rebuild coloring with compact colors
                max_c = max(coloring) if n > 0 else -1
                if max_c < k:
                    # Already compact
                    pass
                else:
                    # Should not happen if we only remove highest
                    pass
        return coloring
    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)
    # Final validation and compacting
    # Ensure colors are consecutive starting from 0
    used_colors = set(best_coloring)
    if used_colors:
        mapping = {c: i for i, c in enumerate(sorted(used_colors))]
        best_coloring = [mapping[c] for c in best_coloring]
    # Validate (should always hold)
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Fallback: greedy coloring by degree
                best_coloring = greedy_color(sorted(range(n), key=lambda x: -len(neighbors[x])))
                break
    return best_coloring

import math
