    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)
                neighbors[i].append(j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # --- Heuristic 1: DSATUR ---
    try:
        color = [-1] * n
        sat = [0] * n  # saturation degree: bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                # saturation degree: number of distinct colors in neighbors
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat):
                    # degree in uncolored subgraph
                    deg = 0
                    for w in neighbors[u]:
                        if w in uncolored:
                            deg += 1
                    if s > max_sat or (s == max_sat and deg > max_deg) or \
                       (s == max_sat and deg == max_deg and (v == -1 or u < v)):
                        max_sat = s
                        max_deg = deg
                        v = u
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]
    except Exception:
        pass

    # --- Heuristic 2: RLF (Recursive Largest First) ---
    try:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                deg = 0
                for w in neighbors[u]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg or (deg == max_deg and (v == -1 or u < v)):
                    max_deg = deg
                    v = u
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            U = set(uncolored)
            U.remove(v)
            # W: vertices adjacent to S (ineligible for this color)
            W = set()
            for u in neighbors[v]:
                if u in uncolored:
                    W.add(u)
            # Remove from U any vertex adjacent to S
            for u in list(U):
                if any(w in S for w in neighbors[u]):
                    U.remove(u)
                    W.add(u)
            # While U not empty, add vertex with max neighbors in W
            while U:
                u_best = -1
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_count = 0
                    for w in neighbors[u]:
                        if w in W:
                            w_count += 1
                    # degree in U-induced subgraph
                    deg_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_U += 1
                    if (w_count > max_w_neighbors or
                        (w_count == max_w_neighbors and deg_U < min_deg_U) or
                        (w_count == max_w_neighbors and deg_U == min_deg_U and (u_best == -1 or u < u_best))):
                        max_w_neighbors = w_count
                        min_deg_U = deg_U
                        u_best = u
                # Add u_best to S
                S.add(u_best)
                U.remove(u_best)
                # Move its neighbors from U to W
                for w in neighbors[u_best]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
