    # --- Heuristic 3: Smallest-Last (Matula & Beck) ---
    try:
        # Compute degeneracy ordering (smallest-last)
        degree = [len(neighbors[i]) for i in range(n)]
        # We'll use a bucket sort like approach for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].append(i)
        # Pointer to current non-empty bucket
        ptr = 0
        order = []
        # Current degrees (will be updated)
        curr_deg = degree[:]
        # Remaining vertices
        remaining = set(range(n))
        for _ in range(n):
            # Find vertex with minimum degree in remaining graph
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            # Find a vertex in bucket[ptr] that is still remaining
            v = -1
            while buckets[ptr]:
                candidate = buckets[ptr].pop()
                if candidate in remaining:
                    v = candidate
                    break
            if v == -1:
                # This should not happen if data structures are correct
                break
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # remove u from its current bucket
                    old_deg = curr_deg[u]
                    buckets[old_deg].remove(u)  # O(n) but n <= 100
                    curr_deg[u] -= 1
                    new_deg = curr_deg[u]
                    buckets[new_deg].append(u)
                    if new_deg < ptr:
                        ptr = new_deg
        # Reverse order for coloring
        order.reverse()
        color = greedy_color(order)
        if is_valid(color):
            k = num_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]
