        pass

    # If no heuristic succeeded (should not happen), fallback to greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # --- Kempe Chain Color Reduction ---
    def eliminate_color_class(coloring, target_color):
        """Attempt to eliminate target_color by recoloring its vertices.
        Returns new coloring if successful, else None."""
        # Vertices with target_color
        targets = [v for v in range(n) if coloring[v] == target_color]
        if not targets:
            return coloring  # already eliminated
        # Try to recolor each target vertex
        for v in targets:
            used_by_neighbors = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used_by_neighbors |= (1 << coloring[u])
            # Try direct reassignment to a smaller color
            for c in range(target_color):
                if not (used_by_neighbors & (1 << c)):
