                    # We'll BFS over the subgraph of colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (coloring[y] == target_color or coloring[y] == c):
                                visited[y] = True
