        target = k - 1
        new_coloring = eliminate_color_class(current_coloring[:], target)
        if new_coloring is not None and is_valid(new_coloring):
            # Compact colors: remap to 0..k-2
            mapping = {}
            next_c = 0
            for i in range(n):
                col = new_coloring[i]
                if col not in mapping:
                    mapping[col] = next_c
                    next_c += 1
                new_coloring[i] = mapping[col]
            current_coloring = new_coloring
            k = next_c
