            v = max(uncolored, key=lambda x: (deg_uncolored[x], random.random()))
            S.add(v)
            # partition: U = vertices not adjacent to any in S, W = adjacent to S
            U = uncolored - {v} - neighbors[v]
            W = (uncolored - {v}) & neighbors[v]
            # update deg_uncolored for vertices in U and W (remove v from consideration)
            for u in uncolored:
                if u != v:
                    if u in neighbors[v]:
                        deg_uncolored[u] -= 1
            # remove v from uncolored
            uncolored.remove(v)
            while U:
                # select u in U with max |N(u) ∩ W|
                def weight(u):
                    # count neighbors in W
                    cnt = 0
                    for w in neighbors[u]:
                        if w in W:
                            cnt += 1
                    return cnt
                # tie-break by min degree in G[U]
                u = max(U, key=lambda x: (weight(x), -len([nb for nb in neighbors[x] if nb in U]), random.random()))
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
                # update deg_uncolored for vertices in U (remove u)
                for w in uncolored:
                    if w != u and w in neighbors[u]:
                        deg_uncolored[w] -= 1
                uncolored.remove(u)
