    def kempe_reduce(colors_in):
        colors = colors_in[:]
        changed = True
        while changed:
            changed = False
            k = count_colors(colors)
            if k <= 1:
                break
            # find smallest color class (largest index after normalization?)
            # We'll target the highest color index present, as we normalize later
            # But we want to eliminate a color, so target any color class that is small
