                used = 0
                for u in neighbors[v]:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
                for c in range(target_color):  # only try lower colors
                    if not (used & (1 << c)):
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart after change
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c from direct reassignment attempt, skip
                    if colors[v] == c:
