import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # DSATUR with degree tie-breaking
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        sat = [0] * n
        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = sum(1 for u in neighbors[v] if u in uncolored)
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # RLF: Recursive Largest First independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set S for color c
            S = set()
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = uncolored - S
            W = set()
            for x in U:
                if any(y in S for y in neighbors[x]):
                    W.add(x)
            U -= W
            # greedily add vertices from U to S
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                best_score = -1
                best_degU = float('inf')
                for u in U:
                    score = sum(1 for y in neighbors[u] if y in W)
                    degU = sum(1 for y in neighbors[u] if y in U)
                    if score > best_score or (score == best_score and degU < best_degU) or (score == best_score and degU == best_degU and random.random() < 0.5):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (degeneracy ordering) greedy
    def smallest_last():
        # core decomposition to get removal order
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for v in range(n):
            d = deg[v]
            if d < n:
                buckets[d].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = buckets[deg[v]].index(v) if v in buckets[deg[v]] else -1
        # simulate removal
        for _ in range(n):
            # find min degree vertex not removed
            d = 0
            while d < n and not buckets[d]:
                d += 1
            while buckets[d] and removed[buckets[d][-1]]:
                buckets[d].pop()
            v = buckets[d].pop()
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    du = deg[u]
                    # remove u from bucket du
                    if pos[u] != -1 and pos[u] < len(buckets[du]) and buckets[du][pos[u]] == u:
                        buckets[du].pop(pos[u])
                    # decrement degree
                    deg[u] -= 1
                    # add to new bucket
                    if deg[u] < n:
                        buckets[deg[u]].append(u)
                        pos[u] = len(buckets[deg[u]]) - 1
                    else:
                        pos[u] = -1
        # color in reverse removal order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append(col_sl)
    except Exception:
        pass
    # Fallback: simple greedy by degree order
    try:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        col_greedy = greedy_color(order)
        if is_valid(col_greedy):
            candidates.append(col_greedy)
    except Exception:
        pass
    # If no candidate (should not happen), assign distinct colors
    if not candidates:
        return list(range(n))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_k = num_colors(best)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal best_k
        improved = True
        while improved and best_k > 1:
            improved = False
            # find smallest color class (max color index)
            classes = [[] for _ in range(best_k)]
            for v in range(n):
                c = coloring[v]
                if 0 <= c < best_k:
                    classes[c].append(v)
            # target the last color class (highest index)
            target = best_k - 1
            if not classes[target]:
                # should not happen, but skip
                break
            # Try to recolor each vertex in target class
            for v in classes[target][:]:  # iterate over copy
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if 0 <= c < best_k:
                        used |= (1 << c)
                for c in range(target):
                    if not (used & (1 << c)):
                        # move v to color c
                        coloring[v] = c
                        classes[target].remove(v)
                        classes[c].append(v)
                        improved = True
                        break
                if improved:
                    # after moving one vertex, restart reduction from scratch
                    break
                # Try Kempe chain swaps with each lower color
                for c in range(target):
                    # BFS to find Kempe chain of (target, c) containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y]:
                                coly = coloring[y]
                                if coly == target or coly == c:
                                    visited[y] = True
                                    queue.append(y)
                    # Check if swapping colors in component is safe: no neighbor outside component has color c or target?
                    # Actually, swapping preserves validity always for Kempe chain.
                    # But we want to free color target for v: after swap, v gets color c.
                    # We need to ensure that no neighbor of v has color c after swap.
                    # Neighbors of v: if neighbor has color c and is in component, after swap it becomes target -> ok.
                    # If neighbor has color c and not in component, after swap it remains c -> conflict.
                    # So we need that no neighbor of v has color c and is outside the component.
                    conflict = False
                    for y in neighbors[v]:
                        if coloring[y] == c and y not in component:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for x in component:
                            if coloring[x] == target:
                                coloring[x] = c
                            else:
                                coloring[x] = target
                        # update classes
                        for x in component:
                            old = target if coloring[x] == c else c
                            new = coloring[x]
                            if old in classes and new in classes:
                                if x in classes[old]:
                                    classes[old].remove(x)
                                classes[new].append(x)
                        improved = True
                        break
                if improved:
                    break
            # If we managed to empty the target color class, reduce best_k
            if not classes[target]:
                best_k -= 1
                # recompact colors: shift down higher colors
                # but we already removed target class, so just ignore it
                # rebuild coloring with consecutive colors
                mapping = {}
                new_c = 0
                for old_c in range(best_k + 1):  # old colors 0..best_k (inclusive)
                    if classes[old_c]:
                        mapping[old_c] = new_c
                        new_c += 1
                # rebuild coloring
                new_coloring = [0] * n
                for v in range(n):
                    oldc = coloring[v]
                    if oldc in mapping:
                        new_coloring[v] = mapping[oldc]
                    else:
                        # should not happen
                        new_coloring[v] = oldc
                coloring = new_coloring
                # rebuild classes for next iteration
                classes = [[] for _ in range(best_k)]
                for v in range(n):
                    c = coloring[v]
                    if 0 <= c < best_k:
                        classes[c].append(v)
        return coloring

    # Apply Kempe reduction
    try:
        best = kempe_reduce(best)
    except Exception:
        pass

    # Final validation and compacting
    if not is_valid(best):
        # fallback to greedy
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        best = greedy_color(order)
    # Ensure colors are consecutive starting from 0
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best[i] = unique_colors[c]
    return best

