        return compact_colors(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen if input is valid
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest downward
        for target_color in range(k - 1, 0, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue

            changed = True
            while changed and verts:
                changed = False
                # Try to recolor each vertex in target_color
                for v in verts[:]:  # iterate over copy
                    if coloring[v] != target_color:
                        continue  # already recolored
                    # Try direct reassignment to a lower color
                    for c in range(target_color):
                        conflict = False
                        for nb in adj_list[v]:
                            if coloring[nb] == c:
                                conflict = True
                                break
                        if not conflict:
                            coloring[v] = c
                            changed = True
                            verts.remove(v)
                            break
                    if changed:
                        continue
                    # Try Kempe chains with each lower color
                    for c in range(target_color):
                        # Find (target_color, c)-Kempe chain containing v
                        # BFS to get component
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            u = queue.popleft()
                            component.append(u)
                            for nb in adj_list[u]:
                                if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                    visited[nb] = True
                                    queue.append(nb)
                        # Check if swapping would free color c for v
                        # After swap, v would get color c; check if any neighbor has color c (they would become target_color)
                        # Actually, we need to ensure that no neighbor of v has color c after swap? 
                        # In the component, neighbors with color c become target_color, and vice versa.
                        # For v, after swap it gets color c. We need that no neighbor of v has color c after swap.
                        # But neighbors of v that are in the component and had color c will become target_color.
                        # Neighbors not in the component keep their color.
                        # So we need: no neighbor of v has color c and is not in the component? 
                        # Actually, if a neighbor has color c and is in the component, after swap it becomes target_color -> ok.
                        # If a neighbor has color c and is not in the component, it remains c -> conflict.
                        # So we need that all neighbors of v with color c are in the component.
                        safe = True
                        for nb in adj_list[v]:
                            if coloring[nb] == c and not visited[nb]:
                                safe = False
                                break
                        if safe:
                            # Perform swap
                            for u in component:
                                if coloring[u] == target_color:
                                    coloring[u] = c
                                else:  # must be c
                                    coloring[u] = target_color
                            changed = True
                            if v in verts:
                                verts.remove(v)
                            break
                    if changed:
                        break
                # End for v in verts
            # End while changed
            # If no vertices left with target_color, we can reduce k
            if not any(coloring[v] == target_color for v in range(n)):
                # Compact colors above target_color
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                # Recompute k and break to restart from new highest color
                k = num_colors(coloring)
                # Restart reduction from new highest color
                break
        return compact_colors(coloring)

    # Run all heuristics and keep the best
    best_coloring = None
    best_k = math.inf

    # Time budget check (soft)
    start_time = time.time()

    # DSATUR
    c1 = dsatur()
    if is_valid(c1):
        k1 = num_colors(c1)
        if k1 < best_k:
            best_k = k1
            best_coloring = c1

    # RLF
    c2 = rlf()
    if is_valid(c2):
        k2 = num_colors(c2)
        if k2 < best_k:
            best_k = k2
            best_coloring = c2

    # Smallest-Last
    c3 = smallest_last()
    if is_valid(c3):
        k3 = num_colors(c3)
        if k3 < best_k:
            best_k = k3
            best_coloring = c3

    # Apply Kempe reduction to the best so far
    if best_coloring is not None and time.time() - start_time < 0.04:  # leave some time
        c4 = kempe_reduce(best_coloring[:])
        if is_valid(c4):
            k4 = num_colors(c4)
            if k4 < best_k:
                best_k = k4
                best_coloring = c4

    # Fallback: if somehow no valid coloring, use greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda i: len(adj_list[i]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used |= 1 << coloring[nb]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = compact_colors(coloring)

    # Final validation and compact
    if not is_valid(best_coloring):
        # Last resort: greedy sequential
        coloring = list(range(n))  # worst case, but valid
        best_coloring = coloring
    return compact_colors(best_coloring)

