def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build neighbor sets
    if is_matrix:
        neighbors = [set(v for v, val in enumerate(row) if val) for row in adj]
    else:
        neighbors = [set(row) for row in adj]

    # Precompute bit masks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Helper: count bits in mask
    def popcount(x: int) -> int:
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid(coloring: list[int]) -> bool:
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring: list[int]) -> int:
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize(coloring: list[int]) -> list[int]:
        if not coloring:
            return coloring
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        coloring = [-1] * n
        colored = [False] * n
        # saturation: number of distinct colors in neighborhood
        saturation = [0] * n
        # neighbor color sets for saturation update
        neighbor_colors = [set() for _ in range(n)]

        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    sat_u = saturation[u]
                    deg_u = popcount(bit_adj[u] & ~sum(1 << i for i in range(n) if colored[i]))
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
                    elif sat_u == max_sat and deg_u == max_deg and v == -1:
                        v = u  # fallback to first found

            # assign smallest available color
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
            colored[v] = True

            # update saturation of uncolored neighbors
            for w in neighbors[v]:
                if not colored[w]:
                    if c not in neighbor_colors[w]:
                        neighbor_colors[w].add(c)
                        saturation[w] += 1
        return coloring

    # RLF: Recursive Largest First
    def rlf() -> list[int]:
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: popcount(bit_adj[u] & sum(1 << w for w in uncolored)))
            # independent set for this color
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v} - neighbors[v]
            W = set()
            # move neighbors of v in U to W
            for w in list(U):
                if w in neighbors[v]:
                    U.remove(w)
                    W.add(w)
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = popcount(bit_adj[u] & sum(1 << w for w in W))
                    deg_u = popcount(bit_adj[u] & sum(1 << w for w in U))
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_u < min_deg_u):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in list(U):
                    if w in neighbors[u]:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for u in S:
                coloring[u] = color
            uncolored -= S
            color += 1
        return coloring

    # Smallest-Last ordering greedy
    def smallest_last() -> list[int]:
        # degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [popcount(bit_adj[u]) for u in range(n)]
        # current degree in remaining subgraph
        curr_deg = degrees[:]
        for _ in range(n):
            # find vertex with min curr_deg in remaining
            v = min(remaining, key=lambda u: curr_deg[u])
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for w in neighbors[v]:
                if w in remaining:
                    curr_deg[w] -= 1
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = set()
            for w in neighbors[v]:
                if coloring[w] != -1:
                    used.add(coloring[w])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring: list[int], a: int, b: int, v: int) -> bool:
        # BFS to get the (a,b)-Kempe chain containing v
        from collections import deque
        if coloring[v] not in (a, b):
            return False
        visited = [False] * n
        queue = deque([v])
        visited[v] = True
        component = []
        while queue:
            u = queue.popleft()
            component.append(u)
            for w in neighbors[u]:
                if not visited[w] and coloring[w] in (a, b):
                    visited[w] = True
                    queue.append(w)
        # swap colors in component
        for u in component:
            if coloring[u] == a:
                coloring[u] = b
            else:
                coloring[u] = a
        return True

    # Try to eliminate the smallest color class using Kempe chains
    def reduce_colors(coloring: list[int]) -> list[int]:
        coloring = normalize(coloring[:])
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        improved = True
        while improved and k > 1:
            improved = False
            # target smallest color class (k-1)
            target_color = k - 1
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                # should not happen if normalized
                break
            # Try to recolor each vertex in target class
            for v in vertices:
                # Try direct reassignment to a lower color
                used = set()
                for w in neighbors[v]:
                    if coloring[w] < target_color:
                        used.add(coloring[w])
                for c in range(target_color):
                    if c not in used:
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # only consider if swapping could free color c for v
                    # i.e., if there is no neighbor of v with color c, or we can swap a component
                    has_c_neighbor = any(coloring[w] == c for w in neighbors[v])
                    if not has_c_neighbor:
                        # should have been caught by direct reassignment, but just in case
                        coloring[v] = c
                        improved = True
                        break
                    # check if v is in a component that does not include any neighbor of v with color c
                    # we try to swap the component of v in (c, target_color) if it doesn't pull a c-colored neighbor into target_color
                    # Actually, we can always try the swap and see if it removes v from target_color without conflict
                    # Make a copy to test
                    test_coloring = coloring[:]
                    if kempe_swap(test_coloring, c, target_color, v):
                        # after swap, v should have color c
                        if test_coloring[v] == c:
                            # check if valid
                            if is_valid(test_coloring):
                                coloring = test_coloring
                                improved = True
                                break
            if improved:
                coloring = normalize(coloring)
                k = num_colors(coloring)
            else:
                break
        return coloring

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for u in range(n):
            used = set()
            for w in neighbors[u]:
                if coloring[w] != -1:
                    used.add(coloring[w])
            c = 0
            while c in used:
                c += 1
            coloring[u] = c
        candidates.append(coloring)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = normalize(best)
    # Apply Kempe reduction
    best = reduce_colors(best)
    # Final validation and normalization
    if not is_valid(best):
        # last resort: greedy
        coloring = [-1] * n
        for u in range(n):
            used = set()
            for w in neighbors[u]:
                if coloring[w] != -1:
                    used.add(coloring[w])
            c = 0
            while c in used:
                c += 1
            coloring[u] = c
        best = normalize(coloring)
    return best

import math
