def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Colors the graph using the smallest-last ordering (degeneracy ordering) heuristic.
    The algorithm:
      1. Computes a degeneracy ordering by repeatedly removing the vertex of minimum degree.
      2. Colors the vertices in reverse order using the greedy First-Fit strategy.
    This guarantees a coloring using at most d+1 colors, where d is the graph's degeneracy.
    """
    n = len(adj)
    if n == 0:
        return []

    # Determine if the input is an adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list from the input
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # If there are no edges, we can color all vertices with color 0
    total_edges = sum(len(neighbors) for neighbors in adj_list) // 2
    if total_edges == 0:
        return [0] * n

    # Initialize data structures for degeneracy ordering
    current_deg = [len(adj_list[i]) for i in range(n)]
    removed = [False] * n
    order = []  # will hold vertices in removal order (first removed to last removed)

    # We will remove n vertices
    for _ in range(n):
        # Find the vertex with minimum current degree that is not removed
        min_deg = math.inf
        v = -1
        for i in range(n):
            if not removed[i] and current_deg[i] < min_deg:
                min_deg = current_deg[i]
                v = i
        if v == -1:
            break  # should not happen if there are vertices left

        removed[v] = True
        order.append(v)

        # Update the degrees of neighbors
        for u in adj_list[v]:
            if not removed[u]:
                current_deg[u] -= 1

    # Now color in reverse order (last removed first)
    color = [-1] * n
    # We'll process vertices in reverse of the removal order
    for v in reversed(order):
        # Collect colors used by already colored neighbors
        neighbor_colors = set()
        for u in adj_list[v]:
            if color[u] != -1:
                neighbor_colors.add(color[u])
        # Assign the smallest non-negative integer not in neighbor_colors
        c = 0
        while c in neighbor_colors:
            c += 1
        color[v] = c

    return color

