def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Convert to adjacency list if needed
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj

    # Ensure graph is undirected and remove self-loops
    for i in range(n):
        graph[i] = [j for j in graph[i] if j != i]
        for j in graph[i]:
            if i not in graph[j]:
                graph[j].append(i)

    # Compute k-core decomposition
    degree = [len(graph[i]) for i in range(n)]
    bin_count = [0] * (n + 1)
    for d in degree:
        if d < n:
            bin_count[d] += 1

    core = [0] * n
    pos = list(range(n))
    vertex_pos = list(range(n))
    start = [0] * (n + 1)
    start[0] = 0
    for i in range(1, n + 1):
        start[i] = start[i - 1] + bin_count[i - 1]

    for i in range(n):
        v = pos[i]
        core[v] = degree[v]
        for u in graph[v]:
            if degree[u] > degree[v]:
                # swap u and v in pos
                pu, pv = vertex_pos[u], vertex_pos[v]
                pos[pu], pos[pv] = pos[pv], pos[pu]
                vertex_pos[u], vertex_pos[v] = vertex_pos[v], vertex_pos[u]
                degree[u] -= 1
                degree[v] += 1
                # update start positions
                start[degree[u] + 1] -= 1
                start[degree[v]] += 1
                # adjust i to re-check the swapped vertex
                i = min(i, vertex_pos[u]) - 1
                break

    max_core = max(core) if n > 0 else 0

    # Bucket vertices by core level
    buckets = [[] for _ in range(max_core + 1)]
    for i in range(n):
        buckets[core[i]].append(i)

    # Order: from low core to high core (outer to inner)
    order = []
    for level in range(max_core + 1):
        order.extend(buckets[level])

    # Greedy coloring in this order
    color = [-1] * n
    for v in order:
        used = [False] * (max_core + 2)  # safe upper bound
        for u in graph[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c < len(used) and used[c]:
            c += 1
        color[v] = c

    # Compact colors
    unique_colors = sorted(set(color))
    mapping = {c: i for i, c in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    return color

