        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Precompute neighbor bit masks and degrees
    neighbor_mask = [0] * n
    degree = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        neighbor_mask[u] = mask
        degree[u] = len(adj_list[u])

    # DSATUR with sum of degrees of uncolored neighbors as tie-breaker
    color = [-1] * n
    colored_mask = 0  # bitmask of colored vertices
    # Precompute neighbor masks for saturation calculation
    # We'll compute saturation on the fly using bit operations

    for _ in range(n):
        # Select uncolored vertex with max saturation degree
        max_sat = -1
        candidates = []  # list of (vertex, sat_degree, tie_breaker)
        for v in range(n):
            if color[v] != -1:
                continue
            # Compute saturation degree: number of distinct colors in neighbors
            neighbor_colors = 0
            nb_mask = neighbor_mask[v]
            # Iterate through each colored neighbor to collect colors
            # Since we don't have color per neighbor in a compact form, we do:
            # We can't avoid iterating neighbors, but n is small
            # Alternative: maintain for each color the set of vertices? 
            # Instead, we compute by checking each neighbor
            # But we can use: for each neighbor u of v, if colored, add color[u] to a set
            # Since degree is small, we do:
            seen_colors = set()
            nb = adj_list[v]
            for u in nb:
                if color[u] != -1:
                    seen_colors.add(color[u])
            sat_degree = len(seen_colors)

            # Tie-breaker: sum of degrees of uncolored neighbors
            tie_breaker = 0
            for u in nb:
