            if sat_degree > max_sat:
                max_sat = sat_degree
                candidates = [(v, sat_degree, tie_breaker)]
            elif sat_degree == max_sat:
                candidates.append((v, sat_degree, tie_breaker))

        # Break ties: max tie_breaker, then random
        if not candidates:
