def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # saturation degree
        colored = [False] * n
        # Initialize degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            max_sat = -1
            candidates = []
            for u in range(n):
                if not colored[u]:
                    if saturated[u] > max_sat:
                        max_sat = saturated[u]
                        candidates = [u]
                    elif saturated[u] == max_sat:
                        candidates.append(u)
            if not candidates:
                break  # should not happen
            # Tie-break by degree (uncolored degree approximated by original degree)
            u = max(candidates, key=lambda x: degrees[x])
            # Find smallest available color
            used = 0
            for v in adj_list[u]:
                if colored[v]:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
            colored[u] = True
            # Update saturation of neighbors
            for v in adj_list[u]:
                if not colored[v]:
                    saturated[v] += 1
        return coloring

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build independent set for this color
            S = []  # independent set (color class)
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # Compute degrees in uncolored subgraph
            deg_uncolored = {}
            for u in uncolored:
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg_uncolored[u] = cnt
            u = max(uncolored, key=lambda x: deg_uncolored[x])
            S.append(u)
            # Partition uncolored \ {u} into U (eligible) and W (ineligible)
            W = set()
            for v in adj_list[u]:
                if v in uncolored:
                    W.add(v)
            U = uncolored - {u} - W
            # Greedily grow independent set
            while U:
                # Select u* in U with max neighbors in W
                best_u = None
                best_score = -1
                tie_breakers = []
                for uu in U:
                    # Count neighbors of uu in W
                    score = 0
                    for v in adj_list[uu]:
                        if v in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        tie_breakers = [uu]
                    elif score == best_score:
                        tie_breakers.append(uu)
                # Tie-break: min degree in G[U]
                if tie_breakers:
                    deg_in_U = {}
                    for uu in tie_breakers:
                        cnt = 0
                        for v in adj_list[uu]:
                            if v in U:
                                cnt += 1
                        deg_in_U[uu] = cnt
                    u_star = min(tie_breakers, key=lambda x: deg_in_U[x])
                else:
                    # Should not happen if U non-empty
                    u_star = next(iter(U))
                S.append(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for v in adj_list[u_star]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color to all in S
            for u in S:
                coloring[u] = color
            color += 1
            # Next round: uncolored becomes W (vertices adjacent to current color class)
            uncolored = W
        return coloring

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute core ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # We'll simulate removal
        current_degrees = degrees[:]
        removed = [False] * n
        for _ in range(n):
            # Find vertex with minimum current degree
            min_deg = float('inf')
            min_v = -1
            for v in remaining:
                if current_degrees[v] < min_deg:
                    min_deg = current_degrees[v]
                    min_v = v
            if min_v == -1:
                break
            order.append(min_v)
            removed[min_v] = True
            remaining.remove(min_v)
            # Update degrees of neighbors
            for v in adj_list[min_v]:
                if not removed[v]:
                    current_degrees[v] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # DSATUR
    candidates.append(dsatur())
    # RLF
    candidates.append(rlf())
    # Smallest-Last
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_k = num_colors(best)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal best_k
        changed = True
        while changed and num_colors(coloring) > 1:
            changed = False
            k = num_colors(coloring)
            # Target smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [u for u in range(n) if coloring[u] == target_color]
            if not target_vertices:
                # Should not happen, but skip
                break
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if coloring[u] < target_color:
                        used |= (1 << coloring[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Found a free color, reassign
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart after change
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Check if v is connected to color c via Kempe chain
                    # We'll BFS the (c, target_color) component containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    # Only traverse vertices of color c or target_color
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in adj_list[u]:
                            if not visited[w] and (coloring[w] == c or coloring[w] == target_color):
                                visited[w] = True
                                queue.append(w)
                    # Check if this component has no neighbor of color c outside? Actually, we can swap if
                    # after swap, no conflict. Swapping is safe if we invert colors in component.
                    # But we want to free color c for v? Actually, after swap, v will get color c.
                    # We need to ensure that no neighbor of v has color c after swap.
                    # Since we are swapping c and target_color in the component, neighbors of v that are
                    # in the component and had color c will become target_color, and vice versa.
                    # So after swap, v (originally target_color) becomes c.
                    # Its neighbors: if neighbor had color c and in component -> becomes target_color (ok)
                    # if neighbor had color c and not in component -> remains c (conflict!)
                    # Therefore, we can only swap if no neighbor of v has color c and is outside the component.
                    conflict = False
                    for w in adj_list[v]:
                        if coloring[w] == c and not visited[w]:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: invert c and target_color in component
                        for u in component:
                            if coloring[u] == c:
                                coloring[u] = target_color
                            elif coloring[u] == target_color:
                                coloring[u] = c
                        changed = True
                        break
                    if changed:
                        break
                if changed:
                    break
            # If we made a change, we might have emptied target_color; compact colors
            if changed:
                # Compact color indices
                mapping = {}
                next_color = 0
                for u in range(n):
                    c = coloring[u]
                    if c not in mapping:
                        mapping[c] = next_color
                        next_color += 1
                    coloring[u] = mapping[c]
        return coloring

    # Apply Kempe reduction to best candidate
    best = kempe_reduce(best)
    best_k = num_colors(best)

    # Final validation and fallback
    if not is_valid(best):
        # Fallback to greedy on degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best = greedy_color(order)
    # Ensure colors are consecutive starting from 0
    used_colors = set(best)
    if used_colors:
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        best = [mapping[c] for c in best]
    else:
        best = [0] * n

    return best

