def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and bitmask representation
    if is_matrix:
        adj_list = []
        bit_adj = [0] * n
        for i in range(n):
            neighbors = []
            mask = 0
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
                    mask |= (1 << j)
            adj_list.append(neighbors)
            bit_adj[i] = mask
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for j in adj_list[i]:
                mask |= (1 << j)
            bit_adj[i] = mask

    # Helper: test if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: normalize coloring to use consecutive colors starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # Strategy 1: BFS-based bipartite extraction + conflict resolution
    def bfs_bipartite_then_resolve():
        color = [-1] * n
        from collections import deque
        q = deque()

        # Process each connected component
        for start in range(n):
            if color[start] != -1:
                continue
            color[start] = 0
            q.append(start)
            while q:
                u = q.popleft()
                for v in adj_list[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        q.append(v)
                    elif color[v] == color[u]:
                        # Conflict: odd cycle detected, leave for now (will be handled later)
                        pass

        # Now resolve conflicts by trying to recolor with minimal extra colors
        # We'll use a simple greedy approach on the conflict graph
        # Build conflict graph: edges where same color
        conflict_adj = [[] for _ in range(n)]
        for u in range(n):
            for v in adj_list[u]:
                if u < v and color[u] == color[v]:
                    conflict_adj[u].append(v)
                    conflict_adj[v].append(u)

        # If no conflicts, we're done (2-colorable)
        has_conflict = any(len(conflict_adj[u]) > 0 for u in range(n))
        if not has_conflict:
            return normalize(color)

        # Otherwise, try to color the conflict graph with additional colors
        # We'll use DSATUR on the conflict graph, starting from color 2
        uncolored = [u for u in range(n) if len(conflict_adj[u]) > 0]
        if not uncolored:
            return normalize(color)

        # DSATUR on conflict graph
        sat = [0] * n  # saturation degree
        colored_conflict = [False] * n
        # Initialize: vertices in conflict graph get their current color (0 or 1) but we'll reassign
        # We'll treat it as uncolored for the conflict resolution phase
        # Actually, we keep the original 0/1 colors and try to assign new colors >=2 to resolve conflicts
        # But simpler: just color the conflict graph from scratch with greedy, using colors 2,3,...
        # Since conflict graph may be small, we can do simple greedy

        # Order by degree in conflict graph descending
        degrees = [len(conflict_adj[u]) for u in range(n)]
        order = sorted(uncolored, key=lambda x: (-degrees[x], x))

        # Try to assign smallest possible color >=2 that doesn't conflict in conflict graph
        for u in order:
            used = set()
            for v in conflict_adj[u]:
                if color[v] >= 2:  # already assigned a new color
                    used.add(color[v])
            # Find smallest color >=2 not in used
            c = 2
            while c in used:
                c += 1
            color[u] = c

        # Validate and normalize
        if is_valid(color):
            return normalize(color)
        # Fallback: should not happen, but if so, use greedy
        return None

    # Strategy 2: DSATUR
    def dsatur():
        if n == 0:
            return []
        color = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # degree for tie-breaking
        degree = [len(adj_list[i]) for i in range(n)]

        # Start with vertex of highest degree
        uncolored = set(range(n))
        # Pick first vertex: max degree
        v = max(uncolored, key=lambda x: (degree[x], -x))  # -x for tie-break by lower index? actually we want max degree, then maybe min index for determinism
        color[v] = 0
        uncolored.remove(v)
        # Update saturation of neighbors
        for u in adj_list[v]:
            if u in uncolored:
                sat[u] = 1  # because neighbor v has color 0

        while uncolored:
            # Select vertex with max saturation, break ties by degree, then by index
            v = max(uncolored, key=lambda x: (sat[x], degree[x], -x))
            # Find smallest color not used by neighbors
            neighbor_colors = set()
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            c = 0
            while c in neighbor_colors:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # Recompute saturation: number of distinct colors in colored neighbors
                    neighbor_color_set = set()
                    for w in adj_list[u]:
                        if color[w] != -1:
                            neighbor_color_set.add(color[w])
                    sat[u] = len(neighbor_color_set)

        return normalize(color)

    # Strategy 3: RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        color = [-1] * n
        current_color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for current_color
            # Start with vertex of max degree in uncolored subgraph
            # Compute degrees in uncolored subgraph
            deg_uncolored = [0] * n
            for u in uncolored:
                count = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        count += 1
                deg_uncolored[u] = count

            # Pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: (deg_uncolored[x], -x))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v}
            W = set()
            for neighbor in adj_list[v]:
                if neighbor in U:
                    U.remove(neighbor)
                    W.add(neighbor)

            # While U not empty
            while U:
                # For each u in U, compute |N(u) ∩ W|
                best_u = None
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if score > best_score or (score == best_score and deg_in_U < best_deg_U):
                        best_score = score
                        best_deg_U = deg_in_U
                        best_u = u

                if best_u is None:
                    break  # should not happen
                # Add best_u to independent set
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign current_color to all in independent_set
            for v in independent_set:
                color[v] = current_color
            uncolored -= independent_set
            current_color += 1

        return normalize(color)

    # Strategy 4: Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        # We'll use a list of sets for buckets, but n<=100 so we can do simple scan
        # Actually, we can use priority queue but n small
        remaining = set(range(n))
        order = []  # removal order
        # We'll store degrees and update
        deg_current = deg[:]
        # Bucket sort like: since max degree < n, we can use list of lists
        max_deg = n-1
        buckets = [[] for _ in range(max_deg+1)]
        for i in range(n):
            d = deg_current[i]
            if d <= max_deg:
                buckets[d].append(i)
        # Pointer to current min non-empty bucket
        min_bucket = 0

        while remaining:
            # Find non-empty bucket from min_bucket upwards
            while min_bucket <= max_deg and not buckets[min_bucket]:
                min_bucket += 1
            if min_bucket > max_deg:
                break  # should not happen
            # Get a vertex from this bucket
            v = buckets[min_bucket].pop()
            if v not in remaining:
                continue  # already removed, skip
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # Remove u from its current bucket
                    old_d = deg_current[u]
                    if old_d <= max_deg and u in buckets[old_d]:
                        buckets[old_d].remove(u)
                    deg_current[u] -= 1
                    new_d = deg_current[u]
                    if new_d <= max_deg:
                        buckets[new_d].append(u)
                    # Update min_bucket if needed
                    if new_d < min_bucket:
                        min_bucket = new_d

        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by colored neighbors
            neighbor_colors = set()
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            c = 0
            while c in neighbor_colors:
                c += 1
            color[v] = c

        return normalize(color)

    # Run all strategies and pick the best (fewest colors)
    best_coloring = None
    best_num_colors = float('inf')

    # List of strategies to try
    strategies = [
        ("bfs_bipartite", bfs_bipartite_then_resolve),
        ("dsatur", dsatur),
        ("rlf", rlf),
        ("smallest_last", smallest_last)
    ]

    for name, strategy in strategies:
        try:
            coloring = strategy()
            if coloring is None or len(coloring) != n:
                continue
            if not is_valid(coloring):
                continue
            num_c = num_colors(coloring)
            if num_c < best_num_colors:
                best_num_colors = num_c
                best_coloring = coloring
        except Exception:
            continue

    # If none worked, fall back to simple greedy
    if best_coloring is None:
        color = [-1] * n
        # Order by degree descending
        order = sorted(range(n), key=lambda x: (-len(adj_list[x]), x))
        for v in order:
            neighbor_colors = set()
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            c = 0
            while c in neighbor_colors:
                c += 1
            color[v] = c
        best_coloring = normalize(color)

    # Final validation and normalization
    if not is_valid(best_coloring):
        # Last resort: assign each vertex a unique color
        best_coloring = list(range(n))

    return normalize(best_coloring)

