            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            independent_set = {v}
            to_remove = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = uncolored - {v}
            W = set()
            for u in adj_list[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # while U not empty
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U-induced subgraph
                u_star = max(U, key=lambda x: (len([y for y in adj_list[x] if y in W]),
                                               -len([y for y in adj_list[x] if y in U])))
                independent_set.add(u_star)
                to_remove.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star from U to W
                for nb in adj_list[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= to_remove
            c += 1
        return normalize(color)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            if degree[v] < len(buckets):
                buckets[degree[v]].add(v)
        # peel
        for _ in range(n):
            # find first non-empty bucket
            i = 0
            while i < len(buckets) and not buckets[i]:
                i += 1
            if i >= len(buckets):
                break  # should not happen
            v = buckets[i].pop()
            order.append(v)
            # update neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    # move nb to lower bucket
                    d = degree[nb]
                    if nb in buckets[d]:
                        buckets[d].remove(nb)
                    degree[nb] -= 1
                    if degree[nb] >= 0:
                        buckets[degree[nb]].add(nb)
