                            if coloring[u] == target_color:
                                coloring[u] = c
                            else:  # must be c
                                coloring[u] = target_color
                        changed = True
                        break
                if changed:
                    break
            # if we eliminated the target color class, compact
            if not any(coloring[v] == target_color for v in range(n)):
                # remap colors: shift down all colors > target_color
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                k -= 1
                changed = True
        return coloring

    # Spectral-inspired clustering via random walk (approximate)
    def spectral_cluster_coloring():
        # Use random walk to get proximity, then cluster via connected components in thresholded graph
        # Build similarity matrix via short random walks
        if n > 64:  # limit to avoid too slow
            steps = 3
        else:
            steps = 5
