            for i in range(n):
                if deg[i] == 0:
                    new_prob[i][i] = prob[i][i]
                    continue
                for j in range(n):
                    if prob[i][j] != 0:
                        # spread to neighbors
                        for nb in adj_list[j]:
                            new_prob[i][nb] += prob[i][j] / deg[j]
