        epsilon = 1e-5
        # build undirected graph where edge exists if prob[i][j] > epsilon or prob[j][i] > epsilon
        # Actually, make symmetric
        sim = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if prob[i][j] > epsilon or prob[j][i] > epsilon:
