        # but we must respect edges between components.
        # Better: use the component partition to initialize a greedy coloring: process components in order, color each with smallest available.
        # However, edges between components may cause conflicts.
        # Alternative: treat each component as a super-node? Too coarse.
        # Instead, we use the component membership to break ties in DSATUR: vertices in same component get preference.
        # For simplicity, we just run DSATUR on the original graph but use component size as secondary tie-break.
        comp_id = [-1] * n
        for idx, comp in enumerate(components):
            for v in comp:
                comp_id[v] = idx
        # DSATUR with tie-break: saturation degree, then component size (larger first), then degree
        color = [-1] * n
        sat = [0] * n
        neighbor_colors = [0] * n
        uncolored = set(range(n))
        if uncolored:
            v = max(uncolored, key=lambda x: (len(adj_list[x]), -comp_id[x]))  # arbitrary start
            color[v] = 0
            neighbor_colors[v] = 1 << 0
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    neighbor_colors[u] |= (1 << 0)
                    sat[u] = 1
        while uncolored:
            v = max(uncolored, key=lambda x: (sat[x],
                                              len([y for y in adj_list[x] if y in uncolored]),
                                              -len([y for y in adj_list[x] if comp_id[y] == comp_id[x]])))
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1
        return normalize(color)

    # Run all heuristics
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    candidates.append(spectral_cluster_coloring())

    # Select best (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best[:])  # work on copy
    # Final validation and normalization
    if not is_valid(best):
        # fallback to DSATUR if something went wrong
        best = dsatur()
    return normalize(best)

