        parent = [-1] * n
        ap = [False] * n
        time = [0]

        def dfs(u):
            disc[u] = low[u] = time[0]
            time[0] += 1
            children = 0
            for v in adj_list[u]:
                if disc[v] == -1:
                    parent[v] = u
                    children += 1
                    dfs(v)
                    low[u] = min(low[u], low[v])
                    if parent[u] == -1 and children > 1:
                        ap[u] = True
                    if parent[u] != -1 and low[v] >= disc[u]:
                        ap[u] = True
                elif v != parent[u]:
                    low[u] = min(low[u], disc[v])

        for i in range(n):
            if disc[i] == -1:
                dfs(i)
        return [i for i in range(n) if ap[i]]

