        betweenness = [0.0] * n
        samples = min(50, n * (n - 1) // 2) if n > 1 else 0
        if samples == 0:
            return betweenness

        for _ in range(samples):
            s = random.randrange(n)
            # BFS from s
            dist = [-1] * n
            pred = [[] for _ in range(n)]
            sigma = [0.0] * n
            dist[s] = 0
            sigma[s] = 1.0
            q = deque([s])
            order = []
