        # Peel vertices
        for _ in range(n):
            # Find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # Remove u from current degree bucket
                    buckets[degree[u]].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].add(u)
            remaining.remove(v)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate initial candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best initial coloring (fewest colors)
    best_coloring = min(candidates, key=count_colors)
    if not is_valid(best_coloring):
        # Fallback to simple greedy if invalid (should not happen)
        best_coloring = greedy_color(list(range(n)))

    # Kempe chain based color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color to lower colors
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return coloring  # already eliminated
        # Try direct reassignment first
        new_coloring = coloring[:]
        for v in vertices:
            used = 0
            for u in adj_list[v]:
                if new_coloring[u] != -1:
                    used |= (1 << new_coloring[u])
            # Find smallest available color < target_color
            for c in range(target_color):
                if not (used & (1 << c)):
                    new_coloring[v] = c
                    break
            else:
                # Cannot assign directly, try Kempe chains
                found = False
                for c in range(target_color):
                    # Try to swap along (c, target_color) Kempe chain
                    # Build component of v in subgraph of colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of component has color c (would cause conflict if swapped)
                    conflict = False
                    for x in component:
                        for y in adj_list[x]:
                            if y not in component and coloring[y] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Perform swap: c <-> target_color in component
                        for x in component:
                            if new_coloring[x] == c:
                                new_coloring[x] = target_color
                            elif new_coloring[x] == target_color:
                                new_coloring[x] = c
                        found = True
                        break
                if not found:
                    return None  # cannot eliminate this vertex
        return new_coloring

    # Iteratively try to reduce colors
    k = count_colors(best_coloring)
    improved = True
    while improved and k > 0:
        improved = False
        # Try to eliminate highest color class first
        target = k - 1
        new_coloring = eliminate_color_class(best_coloring, target)
        if new_coloring is not None and is_valid(new_coloring):
            # Compact colors: remap to 0..k-2
            mapping = {}
            next_color = 0
            for v in range(n):
                c = new_coloring[v]
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
            compacted = [mapping[c] for c in new_coloring]
            if count_colors(compacted) < k:
                best_coloring = compacted
                k = count_colors(best_coloring)
                improved = True
        else:
            # Try lower color classes if highest fails
            for target in range(k - 2, -1, -1):
                new_coloring = eliminate_color_class(best_coloring, target)
                if new_coloring is not None and is_valid(new_coloring):
                    mapping = {}
                    next_color = 0
                    for v in range(n):
                        c = new_coloring[v]
                        if c not in mapping:
                            mapping[c] = next_color
                            next_color += 1
                    compacted = [mapping[c] for c in new_coloring]
                    if count_colors(compacted) < k:
                        best_coloring = compacted
                        k = count_colors(best_coloring)
                        improved = True
                        break
            if not improved:
                break

    # Final validation and compacting
    if not is_valid(best_coloring):
        # Last resort: greedy coloring
        best_coloring = greedy_color(list(range(n)))
    # Ensure colors are consecutive starting from 0
    mapping = {}
    next_color = 0
    for v in range(n):
        c = best_coloring[v]
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
    best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    start_time = time.time()
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Convert to adjacency list and bitmask for fast operations
    if is_matrix:
        neighbors = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        neighbors = adj
        bit_adj = [0] * n
        for u in range(n):
            for v in neighbors[u]:
                bit_adj[u] |= (1 << v)

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: check validity
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # Degree in uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, then max degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = uncolored_deg[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in neighbors[w] for w in S)}
            while U:
                # Select u in U with max |N(u) ∩ W|, then min degree in G[U]
                best_u = -1
                best_score = -1
                best_deg_in_U = float('inf')
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    deg_in_U = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and deg_in_U < best_deg_in_U):
                        best_score = score
                        best_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute core decomposition order (smallest last)
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degree[u]
                    if d > 0:
                        buckets[d].remove(u)
                        degree[u] -= 1
                        buckets[degree[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        if time.time() - start_time > 0.04:  # Leave time for refinement
            break
        col = func()
        if is_valid(col):
            candidates.append(col)

    # If no valid candidate (should not happen), fallback to greedy
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=count_colors)
    k = count_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        nonlocal start_time
        # Map color to list of vertices
        color_classes = [[] for _ in range(k)]
        for v in range(n):
            color_classes[coloring[v]].append(v)
        # Try to eliminate color classes from highest down
        changed = True
        while changed and k > 1 and time.time() - start_time < 0.045:
            changed = False
            # Try to eliminate the smallest color class (last one)
            target_color = k - 1
            if not color_classes[target_color]:
                # Should not happen, but skip
                break
            # For each vertex in target class, try to recolor
            for v in color_classes[target_color][:]:  # Copy list as we may modify
                if time.time() - start_time > 0.045:
                    break
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    if coloring[u] < target_color:
                        used |= (1 << coloring[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Recolor v to c
                        coloring[v] = c
                        color_classes[target_color].remove(v)
                        color_classes[c].append(v)
                        changed = True
                        break
                if changed:
                    break  # Restart scanning from beginning
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    if time.time() - start_time > 0.045:
                        break
                    # Build (target_color, c)-Kempe chain containing v
                    # BFS/DFS to get component
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for u in neighbors[node]:
                                if u not in visited and (coloring[u] == target_color or coloring[u] == c):
                                    stack.append(u)
                    # Check if we can swap: after swap, no vertex in component gets target_color from outside?
                    # Actually, swapping is always valid; we just need to see if it reduces target_color usage
                    # Count how many vertices in component are currently target_color
                    count_target_in_comp = sum(1 for node in component if coloring[node] == target_color)
                    count_c_in_comp = sum(1 for node in component if coloring[node] == c)
                    # After swap, target_color count in component becomes count_c_in_comp
                    # So net change in target_color count: count_c_in_comp - count_target_in_comp
                    # We want this to be negative (reduce target_color count)
                    if count_c_in_comp < count_target_in_comp:
                        # Perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        # Update color classes
                        for node in component:
                            if coloring[node] == target_color:
                                color_classes[target_color].append(node)
                                if node in color_classes[c]:
                                    color_classes[c].remove(node)
                            else:  # coloring[node] == c
                                color_classes[c].append(node)
                                if node in color_classes[target_color]:
                                    color_classes[target_color].remove(node)
                        changed = True
                        break  # Restart scanning
            # If we eliminated the target color class, compact colors
            if not color_classes[target_color]:
                # Remap colors: shift down all colors > target_color
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                k -= 1
                # Rebuild color_classes
                color_classes = [[] for _ in range(k)]
                for v in range(n):
                    color_classes[coloring[v]].append(v)
                changed = True  # Continue trying to reduce
        return coloring, k

    # Apply Kempe reduction if we have time
    if time.time() - start_time < 0.045:
        best_coloring, k = kempe_reduce(best_coloring[:])

    # Final validation and compacting (ensure 0..k-1)
    # Remap colors to consecutive integers
    color_map = {}
    next_color = 0
    for v in range(n):
        c = best_coloring[v]
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        best_coloring[v] = color_map[c]
    # Re-validate (should be valid)
    assert is_valid(best_coloring), "Invalid coloring produced"

    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        neighbors = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        neighbors = [list(lst) for lst in adj]  # Ensure mutable copy
        bit_adj = [0] * n
        for u in range(n):
            for v in neighbors[u]:
                bit_adj[u] |= (1 << v)

    # Helper: count bits in integer
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid(coloring: list[int]) -> bool:
        for u in range(n):
            cu = coloring[u]
            mask = bit_adj[u]
            while mask:
                v = (mask & -mask).bit_length() - 1
                if coloring[v] == cu:
                    return False
                mask &= mask - 1
        return True

    # Helper: get number of colors used
    def num_colors(coloring: list[int]) -> int:
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize(coloring: list[int]) -> list[int]:
        if not coloring:
            return coloring
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        coloring = [-1] * n
        colored = [False] * n
        # Precompute degrees
        deg = [len(neighbors[i]) for i in range(n)]
        # Saturation sets: for each vertex, bitmask of colors used by neighbors
        sat = [0] * n  # bitmask of colors present in neighbors

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                su = bit_count(sat[u])
                if su > max_sat or (su == max_sat and deg[u] > max_deg) or (su == max_sat and deg[u] == max_deg and u > v):
                    max_sat = su
                    max_deg = deg[u]
                    v = u
            if v == -1:
                break  # Should not happen

            # Find smallest color not in saturation set
            c = 0
            while sat[v] & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True
            # Update saturation of neighbors
            for nb in neighbors[v]:
                if not colored[nb]:
                    sat[nb] |= (1 << c)
        return normalize(coloring)

    # RLF: Recursive Largest First
    def rlf() -> list[int]:
        coloring = [-1] * n
        colored = [False] * n
        color = 0
        # Precompute degrees in full graph
        deg = [len(neighbors[i]) for i in range(n)]

        while not all(colored):
            # Step 1: pick uncolored vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                # current degree in uncolored subgraph
                d = 0
                for nb in neighbors[u]:
                    if not colored[nb]:
                        d += 1
                if d > max_deg:
                    max_deg = d
                    v = u
            if v == -1:
                break

            # Start independent set for this color
            S = [v]
            colored[v] = True
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if colored[u]:
                    continue
                adjacent = False
                for nb in neighbors[u]:
                    if not colored[nb] and nb in S:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)

            # Step 2: while U not empty, add vertex with max neighbors in W
            while U:
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_nb = 0
                    for nb in neighbors[u]:
                        if nb in W:
                            w_nb += 1
                    # degree in U
                    deg_u = 0
                    for nb in neighbors[u]:
                        if nb in U:
                            deg_u += 1
                    if w_nb > max_w_neighbors or (w_nb == max_w_neighbors and deg_u < min_deg_in_U) or (w_nb == max_w_neighbors and deg_u == min_deg_in_U and u < best_u):
                        max_w_neighbors = w_nb
                        min_deg_in_U = deg_u
                        best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in neighbors[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for u in S:
                coloring[u] = color
            color += 1

        return normalize(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        if n == 0:
            return []
        # Copy of degrees and vertex set
        deg = [len(neighbors[i]) for i in range(n)]
        remaining = set(range(n))
        order = []  # will store removal order
        # We'll remove min degree vertex each time
        for _ in range(n):
            # find vertex in remaining with min degree
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if deg[u] < min_deg:
                    min_deg = deg[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # decrease degree of neighbors
            for nb in neighbors[v]:
                if nb in remaining:
                    deg[nb] -= 1
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)  # n+1 safe bound
            for nb in neighbors[v]:
                c = coloring[nb]
                if c != -1:
                    used[c] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Kempe chain swap attempt to eliminate a color
    def kempe_reduce(coloring: list[int]) -> list[int]:
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target_color = k - 1
        # Get vertices with target color
        target_vertices = [i for i in range(n) if coloring[i] == target_color]
        if not target_vertices:
            return normalize(coloring)  # already normalized

        # Try direct reassignment first
        new_coloring = coloring[:]
        made_change = False
        for v in target_vertices:
            used = [False] * (k)  # colors 0..k-1
            for nb in neighbors[v]:
                c = coloring[nb]
                if c < k:
                    used[c] = True
            for c in range(k):
                if not used[c]:
                    new_coloring[v] = c
                    made_change = True
                    break
            if made_change:
                break  # reassign one and restart reduction
        if made_change:
            return kempe_reduce(normalize(new_coloring))

        # Try Kempe chains for each target vertex
        for v in target_vertices:
            for c in range(target_color):  # try swapping with each lower color
                # Find Kempe chain (v, target_color) <-> (c)
                # BFS/DFS to get component
                stack = [v]
                visited = [False] * n
                visited[v] = True
                component = []
                while stack:
                    node = stack.pop()
                    component.append(node)
                    for nb in neighbors[node]:
                        if not visited[nb]:
                            col_nb = coloring[nb]
                            if col_nb == target_color or col_nb == c:
                                visited[nb] = True
                                stack.append(nb)
                # Check if swapping would cause conflict: any neighbor of component has color c or target_color outside?
                # Actually, swapping is safe if no neighbor of the component has the target color we are swapping to
                # More precisely: after swap, nodes in component that were target_color become c, and vice versa.
                # Conflict arises if a node in component that becomes c has a neighbor outside component with color c.
                # But since we only include nodes with target_color or c, and we traverse only those, any neighbor outside
                # the component must have color != target_color and != c (otherwise it would be in component).
                # So swap is always safe? Not exactly: consider a node in component with color c: after swap it becomes target_color.
                # It might have a neighbor outside component with color target_color -> conflict.
                # Actually, the standard Kempe chain swap is safe because the component is maximal: any neighbor of a node in the component
                # that has color c or target_color must be in the component. Therefore, after swap, no conflict.
                # So we can swap.
                # Perform swap
                for node in component:
                    if coloring[node] == target_color:
                        new_coloring[node] = c
                    else:  # must be c
                        new_coloring[node] = target_color
                # Normalize and try to reduce further
                return kempe_reduce(normalize(new_coloring))
        # If no Kempe chain helps, return as is
        return normalize(coloring)

    # Main: run multiple heuristics and pick best
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # List of heuristic functions
    heuristics = [dsatur, rlf, smallest_last]

    for heuristic in heuristics:
        if time.time() - start_time > 0.04:  # leave time for Kempe
            break
        coloring = heuristic()
        if not is_valid(coloring):
            continue
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring

    # If no heuristic produced valid coloring (should not happen), fallback to greedy
    if best_coloring is None:
        # Simple greedy: order by degree descending
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for nb in neighbors[v]:
                c = coloring[nb]
                if c != -1:
                    used[c] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    # Apply Kempe chain reduction iteratively
    for _ in range(10):  # limit iterations
        if time.time() - start_time > 0.045:
            break
        new_coloring = kempe_reduce(best_coloring)
        if not is_valid(new_coloring):
            break
        new_k = num_colors(new_coloring)
        if new_k < best_k:
            best_k = new_k
            best_coloring = new_coloring
        else:
            break  # no improvement

    # Final validation and normalization
    if not is_valid(best_coloring):
        # Last resort: DSATUR
        best_coloring = dsatur()
    best_coloring = normalize(best_coloring)

    return best_coloring

