def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Convert adjacency matrix to list
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Precompute neighbor bitmasks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: get smallest available color (mex)
    def mex(colors_used):
        c = 0
        while c in colors_used:
            c += 1
        return c

    # DSATUR heuristic
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets for saturation update
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v]
                deg = sum(1 for nb in adj_list[v] if nb in uncolored)
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # compute mex of neighbor colors
            used = neighbor_colors[v]
            c = mex(used)
            coloring[v] = c
            uncolored.remove(v)
            # update saturation and neighbor colors for uncolored neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    if c not in neighbor_colors[nb]:
                        neighbor_colors[nb].add(c)
                        saturation[nb] += 1
        return coloring

    # RLF heuristic
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in adj_list[x] if nb in uncolored))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for nb in adj_list[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
            # grow independent set
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for nb in adj_list[u] if nb in W)
                    deg_u = sum(1 for nb in adj_list[u] if nb in U)
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or (w_neighbors == best_w_neighbors and deg_u == best_deg_u and u < best_u):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
        return coloring

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[v]) for v in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].add(v)
        # peel min degree vertex
        for _ in range(n):
            # find first non-empty bucket
            i = 0
            while i < len(buckets) and not buckets[i]:
                i += 1
            if i >= len(buckets):
                break
            v = buckets[i].pop()
            order.append(v)
            # update neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    d = degree[nb]
                    if d < len(buckets):
                        buckets[d].discard(nb)
                    degree[nb] -= 1
                    if degree[nb] >= 0:
                        if degree[nb] < len(buckets):
                            buckets[degree[nb]].add(nb)
            remaining.remove(v)
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = set()
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used.add(coloring[nb])
            coloring[v] = mex(used)
        return coloring

    # Generate initial colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best initial coloring (fewest colors)
    best_coloring = min(candidates, key=num_colors)
    best_k = num_colors(best_coloring)

    # If already optimal (lower bound: clique size or max degree +1), but we try to reduce
    # Kempe chain based color reduction
    def try_reduce_k(coloring, k_target):
        # Attempt to eliminate color k_target-1
        if k_target <= 0:
            return coloring
        # vertices with color k_target-1
        color_class = [v for v in range(n) if coloring[v] == k_target-1]
        if not color_class:
            return coloring  # already eliminated
        # Try to recolor each vertex in the class
        for v in color_class:
            used_by_neighbors = set()
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used_by_neighbors.add(coloring[nb])
            # Try direct reassignment to a lower color
            for c in range(k_target-1):
                if c not in used_by_neighbors:
                    coloring[v] = c
                    break
            else:
                # Try Kempe chains with each lower color
                for c in range(k_target-1):
                    # Build (c, k_target-1) Kempe chain component containing v
                    # BFS/DFS over vertices colored c or k_target-1
                    stack = [v]
                    visited = set()
                    comp_color_k1 = False  # whether we see color k_target-1 in component (should be true for v)
                    comp_color_c = False   # whether we see color c in component
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        col = coloring[node]
                        if col == c:
                            comp_color_c = True
                        elif col == k_target-1:
                            comp_color_k1 = True
                        # explore neighbors with colors c or k_target-1
                        for nb in adj_list[node]:
                            if nb not in visited and coloring[nb] in (c, k_target-1):
                                stack.append(nb)
                    # If component does not contain color c, we can swap
                    if not comp_color_c:
                        # swap colors c and k_target-1 in component
                        for node in visited:
                            if coloring[node] == c:
                                coloring[node] = k_target-1
                            elif coloring[node] == k_target-1:
                                coloring[node] = c
                        # now v is colored c
                        break
                else:
                    # successfully recolored via Kempe chain
                    break
            else:
                # failed to recolor v, cannot eliminate this color class
                return None
        # Successfully recolored all vertices of color k_target-1
        # Relabel colors to be consecutive
        # mapping from old color to new color
        used_colors = set(coloring)
        mapping = {}
        next_c = 0
        for col in sorted(used_colors):
            mapping[col] = next_c
            next_c += 1
        for i in range(n):
            coloring[i] = mapping[coloring[i]]
        return coloring

    # Iteratively try to reduce number of colors
    current = best_coloring[:]
    k = best_k
    improved = True
    # safety limit
    for _ in range(k):
        if k <= 1:
            break
        reduced = try_reduce_k(current[:], k)  # work on a copy
        if reduced is not None and is_valid(reduced):
            current = reduced
            k = num_colors(current)
        else:
            break

    # Final validation (should always hold)
    if not is_valid(current):
        # fallback to best initial
        current = best_coloring

    return current

