        for _ in range(n):
            if not remaining:
                break
            # Select vertex with max saturation, tie-break by degree in remaining subgraph
            v = max(remaining, key=lambda x: (saturated[x], len(neighbors[x] & remaining)))
            # Compute available colors
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            remaining.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v] & remaining:
                saturated[u] += 1
        if is_valid(color):
            k = count_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]
