    try:
        color = [-1] * n
        remaining = set(range(n))
        c = 0
        while remaining:
            # Build maximal independent set for color c
            # Start with vertex of max degree in remaining
            v = max(remaining, key=lambda x: len(neighbors[x] & remaining))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = remaining - {v} - (neighbors[v] & remaining)
            # W: vertices adjacent to independent_set
            W = (neighbors[v] & remaining)
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len(neighbors[x] & W), -len(neighbors[x] & U)))
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbors[u] & U
                U -= nbrs_u
                W |= nbrs_u
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
            remaining -= independent_set
            c += 1
        if is_valid(color):
            k = count_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]
    except Exception:
        pass

    # Strategy 3: Smallest-Last ordering
    try:
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        temp_remaining = remaining.copy()
        temp_degree = degree[:]
        for _ in range(n):
            # Find vertex with min degree in temp_remaining
            v = min(temp_remaining, key=lambda x: temp_degree[x])
            order.append(v)
            temp_remaining.remove(v)
            for u in neighbors[v] & temp_remaining:
                temp_degree[u] -= 1
        # Reverse for coloring order
        order.reverse()
        color = greedy_color(order)
        if is_valid(color):
            k = count_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]
    except Exception:
        pass

    # If no strategy worked, fallback to simple greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        if not is_valid(best_coloring):
            # Last resort: assign each vertex a unique color
            best_coloring = list(range(n))

    # Ensure consecutive colors starting from 0
    # Map colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_coloring[i] = unique_colors[c]

    # Final validation (should be valid by construction)
    if not is_valid(best_coloring):
        # Emergency fix: reassign to avoid conflicts
        color = [-1] * n
        for i in range(n):
            used = 0
            for j in neighbors[i]:
                if color[j] != -1:
                    used |= (1 << color[j])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        best_coloring = color

    return best_coloring

