def color_graph(adj: list[list[int]]) -> list[int]:
    # Helper: detect if input is adjacency matrix
    def is_adj_matrix(a):
        if not a or not isinstance(a, list) or len(a) == 0:
            return False
        n = len(a)
        if not all(isinstance(row, list) and len(row) == n for row in a):
            return False
        for i in range(n):
            for j in range(n):
                val = a[i][j]
                if val not in (0, 1):
                    return False
                if a[i][j] != a[j][i]:
                    return False
        return True

    # Convert to adjacency list
    if is_adj_matrix(adj):
        n = len(adj)
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj
        n = len(adj_list)

    if n == 0:
        return []
    if n == 1:
        return [0]

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Find connected components
    visited = [False] * n
    components = []
    for i in range(n):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            comp = []
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in adj_list[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(comp)

    # Find articulation points and biconnected components (blocks) using DFS
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    ap = [False] * n
    time = 0
    stack = []
    blocks = []  # each block is a set of edges (u, v) with u < v

    def dfs(u):
        nonlocal time
        children = 0
        disc[u] = low[u] = time
        time += 1
        for v in adj_list[u]:
            if disc[v] == -1:
                parent[v] = u
                children += 1
                stack.append((u, v))
                dfs(v)
                low[u] = min(low[u], low[v])
                if (parent[u] == -1 and children > 1) or (parent[u] != -1 and low[v] >= disc[u]):
                    ap[u] = True
                    block_edges = set()
                    while True:
                        e = stack.pop()
                        block_edges.add(e)
                        if e == (u, v) or e == (v, u):
                            break
                    blocks.append(block_edges)
            elif v != parent[u] and disc[v] < disc[u]:
                low[u] = min(low[u], disc[v])
                stack.append((u, v))
        if parent[u] == -1 and children == 0:
            # isolated vertex
            pass

    for i in range(n):
        if disc[i] == -1:
            dfs(i)
            if stack:
                block_edges = set()
                while stack:
                    block_edges.add(stack.pop())
                blocks.append(block_edges)

    # Convert edge sets to vertex sets for each block
    block_vertex_sets = []
    for edge_set in blocks:
        vertices = set()
        for u, v in edge_set:
            vertices.add(u)
            vertices.add(v)
        block_vertex_sets.append(vertices)

    # Handle isolated vertices (not in any block)
    assigned = [False] * n
    color = [-1] * n
    current_color = 0

    # Process each block
    for vertices in block_vertex_sets:
        # Extract subgraph induced by vertices
        sub_adj = {u: [] for u in vertices}
        for u in vertices:
            for v in adj_list[u]:
                if v in vertices:
                    sub_adj[u].append(v)
        # Convert to list for indexing
        verts = sorted(vertices)
        idx_map = {v: i for i, v in enumerate(verts)}
        n_sub = len(verts)
        if n_sub == 0:
            continue
        if n_sub == 1:
            u = verts[0]
            color[u] = 0
            assigned[u] = True
            continue
        # Build adjacency matrix for subgraph
        sub_adj_mat = [[0] * n_sub for _ in range(n_sub)]
        for i, u in enumerate(verts):
            for v in sub_adj[u]:
                j = idx_map[v]
                sub_adj_mat[i][j] = 1
        # Color the subgraph using DSATUR with bitmask
        sub_color = _dsatur_bitmask(sub_adj_mat)
        # Map back to original vertex indices
        for i, u in enumerate(verts):
            color[u] = sub_color[i]
            assigned[u] = True

    # Assign colors to any remaining unassigned vertices (isolated or not in any block)
    for u in range(n):
        if not assigned[u]:
            color[u] = 0
            assigned[u] = True

    # Ensure colors are consecutive starting from 0
    unique_colors = sorted(set(color))
    if unique_colors != list(range(len(unique_colors)):
        color_map = {old: new for new, old in enumerate(unique_colors)}
        color = [color_map[c] for c in color]

    return color

def _dsatur_bitmask(adj_mat):
    n = len(adj_mat)
    if n == 0:
        return []
    # Precompute neighbor bitmasks
    bit_adj = [0] * n
    for i in range(n):
        for j in range(n):
            if adj_mat[i][j]:
                bit_adj[i] |= (1 << j)
    color = [-1] * n
    # Saturation degree: number of distinct colors in neighbors
    saturation = [0] * n
    # Remaining uncolored vertices
    uncolored = set(range(n))
    # Order by degree descending for initial tie-break
    degree = [bin(bit_adj[i]).count('1') for i in range(n)]
    # Start with vertex of highest degree
    v = max(uncolored, key=lambda x: (degree[x], x))
    color[v] = 0
    uncolored.remove(v)
    # Update saturation of neighbors
    neighbors = bit_adj[v]
    while neighbors:
        w = (neighbors & -neighbors).bit_length() - 1
        neighbors &= neighbors - 1
        if color[w] == -1:
            saturation[w] += 1
    # Main loop
    while uncolored:
        # Select vertex with max saturation, break ties by degree, then index
        v = max(uncolored, key=lambda x: (saturation[x], degree[x], x))
        # Find smallest available color
        used = 0
        neighbors = bit_adj[v]
        while neighbors:
            w = (neighbors & -neighbors).bit_length() - 1
            neighbors &= neighbors - 1
            c = color[w]
            if c != -1:
                used |= (1 << c)
        c = 0
        while used & (1 << c):
            c += 1
        color[v] = c
        uncolored.remove(v)
        # Update saturation for uncolored neighbors
        neighbors = bit_adj[v]
        while neighbors:
            w = (neighbors & -neighbors).bit_length() - 1
            neighbors &= neighbors - 1
            if color[w] == -1:
                # Recompute saturation for w: number of distinct colors in its neighbors
                sat = 0
                nbrs = bit_adj[w]
                seen_colors = 0
                while nbrs:
                    x = (nbrs & -nbrs).bit_length() - 1
                    nbrs &= nbrs - 1
                    col = color[x]
                    if col != -1:
                        seen_colors |= (1 << col)
                saturation[w] = bin(seen_colors).count('1')
    return color

