        for u in order:
            used = 0
            for v in adj_list[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[u]) for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                d = uncolored_deg[u]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best = u
            u = best
            uncolored.remove(u)
            # assign smallest available color
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
            # update neighbors
            for v in adj_list[u]:
                if v in uncolored:
                    sat[v] |= (1 << c)
                    uncolored_deg[v] -= 1
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = set()
            # start with max degree vertex in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - S
            W = set()
            for u in list(U):
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                    U.remove(u)
            # grow independent set
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best = -1
                best_w = -1
                best_deg_u = float('inf')
                for u in U:
                    w_count = sum(1 for y in adj_list[u] if y in W)
                    deg_u = sum(1 for y in adj_list[u] if y in U)
                    if w_count > best_w or (w_count == best_w and deg_u < best_deg_u) or (w_count == best_w and deg_u == best_deg_u and random.random() < 0.5):
                        best_w = w_count
                        best_deg_u = deg_u
                        best = u
                u = best
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for y in adj_list[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(adj_list[u]) for u in range(n)]
        order = []
        # buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[deg[u]].append(u)
        # pointer to current non-empty bucket
        ptr = 0
        # copy of degrees for updating
        cur_deg = deg[:]
        removed = [False] * n
        for _ in range(n):
            # find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            u = buckets[ptr].pop()
            if removed[u]:
                continue
            removed[u] = True
            order.append(u)
            for v in adj_list[u]:
                if not removed[v]:
                    d = cur_deg[v]
                    if d > 0:
                        cur_deg[v] -= 1
                        buckets[d].remove(v)
                        buckets[d-1].append(v)
        # color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap for (a,b) component containing u
    def kempe_swap(color, a, b, u):
        # returns new coloring after swapping a<->b in component of u, or None if invalid
        stack = [u]
        visited = set()
        comp = set()
        while stack:
            v = stack.pop()
            if v in visited:
                continue
            visited.add(v)
            if color[v] == a or color[v] == b:
                comp.add(v)
                for w in adj_list[v]:
                    if color[w] == a or color[w] == b and w not in visited:
                        stack.append(w)
        # check if swap is valid (should always be, but ensure)
        for v in comp:
            for w in adj_list[v]:
                if w in comp:
                    continue
                if color[w] == a and v in comp and color[v] == b:
                    # after swap, v->a, w->a -> conflict
                    return None
                if color[w] == b and v in comp and color[v] == a:
                    return None
        # perform swap
        new_color = color[:]
        for v in comp:
            if new_color[v] == a:
                new_color[v] = b
            else:
                new_color[v] = a
        return new_color

    # Attempt to eliminate a color class via Kempe chains
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate highest color
        target = k - 1
        target_vertices = [u for u in range(n) if coloring[u] == target]
        if not target_vertices:
            # already eliminated, compact
            mapping = {}
            next_c = 0
            for u in range(n):
                c = coloring[u]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
            return [mapping[coloring[u]] for u in range(n)]
        changed = True
        # local search: try to recolor target vertices
        for _ in range(10):  # limited iterations
            if not any(coloring[u] == target for u in range(n)):
                break
            made_progress = False
            for u in target_vertices:
                if coloring[u] != target:
                    continue
                # try direct reassignment to lower color
                used = 0
                for v in adj_list[u]:
                    c = coloring[v]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target):
                    if not (used & (1 << c)):
                        coloring[u] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # try to swap (target, c) component containing u
                    new_col = kempe_swap(coloring, target, c, u)
                    if new_col is not None:
                        # check if this reduces the number of target-colored vertices
                        if num_colors(new_col) < k or sum(1 for x in new_col if x == target) < sum(1 for x in coloring if x == target):
                            coloring = new_col
                            made_progress = True
                            break
                if made_progress:
                    break
            if not made_progress:
                break
        # if target color still used, try to compact anyway
        if any(coloring[u] == target for u in range(n)):
            return coloring
        # compact colors
        mapping = {}
        next_c = 0
        for u in range(n):
            c = coloring[u]
            if c not in mapping:
                mapping[c] = next_c
                next_c += 1
        return [mapping[coloring[u]] for u in range(n)]

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except:
        pass

    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except:
        pass

    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append(col_sl)
    except:
        pass

    # If no candidates, fallback to trivial
    if not candidates:
        # greedy by vertex index
        candidates.append(greedy_color(list(range(n))))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_colors = num_colors(best)

    # Iterative color reduction
    for _ in range(10):  # limit rounds
        new_best = reduce_colors(best)
        new_colors = num_colors(new_best)
        if new_colors < best_colors:
            best = new_best
            best_colors = new_colors
        else:
            break

    # Final validation and compacting
    if not is_valid(best):
        # last resort: greedy
        best = greedy_color(list(range(n)))
    # ensure colors are consecutive
    mapping = {}
    next_c = 0
    for u in range(n):
        c = best[u]
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
    best = [mapping[best[u]] for u in range(n)]

    return best

