def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if entries are binary (0 or 1)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor bitmasks and degree list
    bit_adj = [0] * n
    deg = [0] * n
    if is_matrix:
        for u in range(n):
            mask = 0
            for v in range(n):
                if adj[u][v]:
                    mask |= (1 << v)
                    deg[u] += 1
            bit_adj[u] = mask
    else:
        for u in range(n):
            mask = 0
            for v in adj[u]:
                mask |= (1 << v)
                deg[u] += 1
            bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in range(n):
                if (bit_adj[u] >> v) & 1:
                    c = colors[v]
                    if c != -1:
                        used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # Helper: count distinct colors
    def count_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if colors[u] == colors[v]:
                        return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # Candidate 1: DSATUR
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                # compute degree in uncolored subgraph
                d = 0
                for u in uncolored:
                    if u != v and ((bit_adj[v] >> u) & 1):
                        d += 1
                if sat > best_sat or (sat == best_sat and (d > best_deg or (d == best_deg and v > best_v))):
                    best_sat = sat
                    best_deg = d
                    best_v = v
            v = best_v
            # Find smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and colors[u] == -1:
                    saturated[u] |= (1 << c)
        return colors

    # Candidate 2: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # Build maximal independent set for color_idx
            # Start with vertex of max degree in uncolored subgraph
            S = set()
            # Find vertex with max degree in G[uncolored]
            best_v = -1
            best_deg = -1
            for v in uncolored:
                d = 0
                for u in uncolored:
                    if u != v and ((bit_adj[v] >> u) & 1):
                        d += 1
                if d > best_deg:
                    best_deg = d
                    best_v = v
            v = best_v
            S.add(v)
            # Partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adj_to_S = False
                for w in S:
                    if (bit_adj[w] >> u) & 1:
                        adj_to_S = True
                        break
                if adj_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                best_score = -1
                best_deg_u = -1
                for u in U:
                    # count neighbors in W
                    score = 0
                    for w in W:
                        if (bit_adj[u] >> w) & 1:
                            score += 1
                    # degree in G[U]
                    deg_u = 0
                    for u2 in U:
                        if u2 != u and ((bit_adj[u] >> u2) & 1):
                            deg_u += 1
                    if score > best_score or (score == best_score and (deg_u < best_deg_u or (deg_u == best_deg_u and u < best_u))):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for u2 in list(U):
                    if (bit_adj[u] >> u2) & 1:
                        U.remove(u2)
                        W.add(u2)
            # Assign color_idx to all in S
            for v in S:
                colors[v] = color_idx
            uncolored -= S
            color_idx += 1
        return colors

    # Candidate 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = deg[:]  # current degree in remaining subgraph
        order = []
        # Use buckets for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d < len(buckets):
                buckets[d].append(v)
            else:
                # extend buckets if needed (should not happen)
                buckets.extend([[] for _ in range(d - len(buckets) + 1)])
                buckets[d].append(v)
        # Pointer to current min degree
        min_deg = 0
        while remaining:
            # Find non-empty bucket
            while min_deg < len(buckets) and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= len(buckets):
                break  # should not happen
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    d = degree[u]
                    # remove u from bucket d
                    if d < len(buckets) and u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    # add to bucket d_new
                    if d_new >= len(buckets):
                        buckets.extend([[] for _ in range(d_new - len(buckets) + 1)])
                    buckets[d_new].append(u)
        # Reverse order for coloring
        order.reverse()
        return greedy_color(order)

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: simple greedy by degree
    try:
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass
    # If no candidate, assign all color 0 (invalid but fallback)
    if not candidates:
        return [0] * n

    # Select best candidate (fewest colors)
    best = min(candidates, key=count_colors)
    best = compact_colors(best)

    # Iterative Kempe chain color reduction
    def kempe_reduce(colors):
        k = count_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, -1, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            made_change = False
            for v in verts:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in range(n):
                    if (bit_adj[v] >> u) & 1:
                        c = colors[u]
                        if c != -1:
                            neighbor_colors.add(c)
                for c in range(target_color):  # only try lower colors
                    if c not in neighbor_colors:
                        colors[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue  # skip if neighbor already has color c (would cause conflict if swapped?)
                    # We consider swapping colors target_color and c in the component containing v
                    # Build the Kempe chain component for colors {target_color, c} containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1 and not visited[y]:
                                if colors[y] == target_color or colors[y] == c:
                                    visited[y] = True
                                    queue.append(y)
                    # In this component, swap target_color <-> c
                    # Check if after swap, no vertex in component gets a color that conflicts with outside
                    # Actually, swapping within a Kempe chain preserves validity
                    # Perform swap
                    for x in component:
                        if colors[x] == target_color:
                            colors[x] = c
                        elif colors[x] == c:
                            colors[x] = target_color
                    made_change = True
                    break
                if made_change:
                    break
            if not made_change:
                # Could not eliminate this color class, move to next lower
                continue
            else:
                # After change, compact and restart reduction from scratch
                colors = compact_colors(colors)
                return kempe_reduce(colors)  # recurse with new coloring
        return colors

    # Apply Kempe reduction
    best = kempe_reduce(best)
    best = compact_colors(best)

    return best

