def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
    else:
        for i in range(n):
            neighbors[i] = list(adj[i])

    # Build bitmask for each vertex (only for vertices < 64, else use set fallback)
    use_bitmask = n <= 64
    bit_adj = [0] * n
    if use_bitmask:
        for i in range(n):
            mask = 0
            for j in neighbors[i]:
                mask |= (1 << j)
            bit_adj[i] = mask

    # Helper: get neighbors as set or bitmask
    def get_neighbors(v):
        if use_bitmask:
            return bit_adj[v]
        else:
            return set(neighbors[v])

    # Helper: count common neighbors between v and a set (or bitmask)
    def common_count(v, mask_or_set):
        if use_bitmask:
            return (bit_adj[v] & mask_or_set).bit_count()
        else:
            return len(neighbors[v] & mask_or_set)

