    def normalize_coloring(coloring):
        if not coloring:
            return coloring
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR algorithm
    def dsatur():
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbor colors tracking: for each vertex, a bitmask of colors used by neighbors
        neighbor_colors = [0] * n if use_bitmask else [set() for _ in range(n)]
        # degree in the uncolored subgraph (initially full degree)
        degree_uncolored = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree_uncolored, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u]
                deg_u = degree_uncolored[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and random.random() < 0.5):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by neighbors
            used = neighbor_colors[v] if use_bitmask else neighbor_colors[v]
            if use_bitmask:
                c = 0
                while used & (1 << c):
                    c += 1
            else:
                c = 0
                while c in used:
                    c += 1
            coloring[v] = c

            # Update uncolored set and degree_uncolored
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    degree_uncolored[u] -= 1
                    # Update saturation and neighbor_colors for u
                    if use_bitmask:
                        # Add color c to neighbor_colors[u]
                        neighbor_colors[u] |= (1 << c)
                        # saturation[u] = bit count of neighbor_colors[u]
                        saturation[u] = neighbor_colors[u].bit_count()
                    else:
                        neighbor_colors[u].add(c)
                        saturation[u] = len(neighbor_colors[u])

