                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
            if v == -1:
                break
            S = {v}
            # U: uncolored vertices not adjacent to v
            U = uncolored - {v} - set(neighbors[v])
            # W: uncolored vertices adjacent to v
            W = set(neighbors[v]) & uncolored
            # Remove v from uncolored
            uncolored.remove(v)

            while U:
                # Select u in U with max |N(u) ∩ W|
                u_best = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in neighbors[u]:
                        if w in W:
                            w_neighbors += 1
                    # Tie-break: min degree in G[U]
                    deg_u = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_u += 1
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or \
                       (w_neighbors == max_w_neighbors and deg_u == min_deg_u and random.random() < 0.5):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        u_best = u
                if u_best == -1:
                    break
                # Add u_best to S
                S.add(u_best)
                uncolored.remove(u_best)
                # Move u_best from U to ... and update W
                U.remove(u_best)
                # Neighbors of u_best that are in U move to W
                for w in neighbors[u_best]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for u in S:
                coloring[u] = color
            color += 1
        return normalize_coloring(coloring)

    # Smallest-Last (Matula-Beck) greedy
    def smallest_last():
        # Build ordering by repeatedly removing min degree vertex
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # We'll simulate removal
        for _ in range(n):
            # find vertex in remaining with min deg
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if deg[u] < min_deg:
                    min_deg = deg[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    deg[u] -= 1
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        return normalize_coloring(coloring)

    # Kempe chain based color reduction
    def reduce_colors(coloring):
        if not is_valid_coloring(coloring):
            return coloring  # should not happen, but safeguard
        k = num_colors(coloring)
        # Try to reduce from k down to 1
        # We'll attempt to eliminate the highest color class
        changed = True
        while changed and k > 1:
            changed = False
            # Target the highest color (k-1)
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [i for i in range(n) if coloring[i] == target_color]
            if not target_vertices:
                # already normalized, should not happen
                break
            # Try to recolor each target vertex to a lower color
            for v in target_vertices:
                # Try direct reassignment to a color < target_color
                used_by_neighbors = set()
                for u in neighbors[v]:
                    if coloring[u] < target_color:
                        used_by_neighbors.add(coloring[u])
                for c in range(target_color):
                    if c not in used_by_neighbors:
                        # Direct move possible
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart reduction from scratch after any change
                # If not, try Kempe chain swap with each color c < target_color
                for c in range(target_color):
                    # Check if v can be swapped with color c via Kempe chain
                    # We consider the subgraph induced by colors {c, target_color}
                    # Find the Kempe chain containing v in this subgraph
                    # If the chain does not contain any vertex of color c that is adjacent to a vertex of color target_color outside the chain? 
                    # Actually, we can swap if the component of v in (c, target_color) does not contain a neighbor of v with color c? 
                    # Standard: if in the (c, target_color) Kempe chain of v, there is no neighbor of v colored c, then we can swap.
                    # But simpler: we can swap the entire component if it doesn't cause conflict.
                    # We'll do: BFS to get the component of v in colors {c, target_color}
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for nb in neighbors[node]:
                            if nb not in visited and (coloring[nb] == c or coloring[nb] == target_color):
                                visited.add(nb)
                                queue.append(nb)
                    # Check if any neighbor of v with color c is in the component? 
                    # Actually, we can swap if no neighbor of v colored c is in the component? 
                    # Correct condition: after swapping, v becomes color c. We need that no neighbor of v is color c after swap.
                    # Currently, neighbors of v that are color c will become color target_color after swap, which is ok as long as they are not adjacent to v? 
                    # But they are adjacent to v, and after swap they become target_color, and v becomes c -> no conflict.
                    # However, if a neighbor of v is color c and is in the component, after swap it becomes target_color, and v becomes c -> still no conflict because they are different.
                    # The only issue is if there is a neighbor of v that is color c and is NOT in the component? Then after swap, that neighbor remains c and v becomes c -> conflict.
                    # So we can swap if and only if there is no neighbor of v colored c that is outside the component.
                    has_external_c = False
                    for nb in neighbors[v]:
                        if coloring[nb] == c and nb not in component:
                            has_external_c = True
                            break
                    if not has_external_c:
                        # Perform swap: swap colors c and target_color in the component
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            elif coloring[node] == target_color:
                                coloring[node] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # Re-normalize colors to be consecutive
                coloring = normalize_coloring(coloring)
                k = num_colors(coloring)
            else:
                break  # cannot reduce further
        return coloring

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            coloring = func()
            if not is_valid_coloring(coloring):
                continue
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring[:]
        except Exception:
            continue

    # Fallback: if none worked, use greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best_coloring = normalize_coloring(coloring)

    # Apply Kempe reduction to try to improve
    best_coloring = reduce_colors(best_coloring)
    # Final validation and normalization
    if not is_valid_coloring(best_coloring):
        # Last resort: greedy
        order = list(range(n))
        coloring = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best_coloring = normalize_coloring(coloring)
    else:
        best_coloring = normalize_coloring(best_coloring)

    return best_coloring

