def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True
    # Build adjacency list and bitmask
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        used_masks = [0] * n  # bitmask of colors used by neighbors
        for v in order:
            mask = used_masks[v]
            c = 0
            while mask & (1 << c):
                c += 1
            color[v] = c
            for u in neighbors[v]:
                used_masks[u] |= (1 << c)
        return color
    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        saturation = [0] * n  # number of distinct neighbor colors
        colored_neighbor_masks = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u]
                if sat_u > max_sat or (sat_u == max_sat and len([w for w in neighbors[u] if w in uncolored]) > max_deg):
                    max_sat = sat_u
                    max_deg = len([w for w in neighbors[u] if w in uncolored])
                    v = u
                elif sat_u == max_sat and len([w for w in neighbors[u] if w in uncolored]) == max_deg and u < v:
                    v = u
            # assign smallest available color
            mask = colored_neighbor_masks[v]
            c = 0
            while mask & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and colored neighbor masks for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    colored_neighbor_masks[u] |= (1 << c)
                    # recompute saturation for u: count bits in colored_neighbor_masks[u]
                    saturation[u] = colored_neighbor_masks[u].bit_count()
        return color
    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set S for color c
            S = set()
            # vertex in uncolored with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: len([w for w in neighbors[x] if w in uncolored]))
            S.add(v)
            # partition: U = vertices not adjacent to any in S, W = vertices adjacent to S
            U = {u for u in uncolored if u not in S and all(u not in neighbors[s] for s in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: len([w for w in neighbors[x] if w in W]))
                # tie-break: min degree in G[U]
                candidates = [x for x in U if len([w for w in neighbors[x] if w in W]) == len([w for w in neighbors[u] if w in W])]
                u = min(candidates, key=lambda x: len([w for w in neighbors[x] if w in U]))
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color
    # Helper: smallest-last ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # simulate peeling
        for _ in range(n):
            # find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    # decrease degree of u
                    old_deg = degree[u]
                    degree[u] -= 1
                    buckets[old_deg].remove(u)
                    buckets[degree[u]].append(u)
        # color in reverse order
        return greedy_color(order[::-1])
    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-last
    try:
        col_sl = smallest_last()
        candidates.append(col_sl)
    except Exception:
        pass
    # Also try greedy by degree descending
    try:
        order_deg = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        candidates.append(greedy_color(order_deg))
    except Exception:
        pass
    # Choose best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # validate
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if col else 0
        if k < best_k:
            best_k = k
            best_color = col
    if best_color is None:
        # fallback: greedy by index
        best_color = greedy_color(list(range(n)))
        best_k = max(best_color) + 1 if best_color else 0
    # Kempe chain color reduction
    def kempe_reduction(color):
        # make color indices consecutive
        def compact(col):
            mapping = {}
            next_c = 0
            for v in range(n):
                c = col[v]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                col[v] = mapping[c]
            return col
        color = compact(color[:])
        improved = True
        while improved:
            improved = False
            # find smallest color class
            color_classes = [[] for _ in range(best_k)]
            for v in range(n):
                color_classes[color[v]].append(v)
            # find smallest non-empty class
            target_c = -1
            min_size = n + 1
            for c in range(best_k):
                if 0 < len(color_classes[c]) < min_size:
                    min_size = len(color_classes[c])
                    target_c = c
            if target_c == -1 or min_size == 0:
                break
            # try to recolor each vertex in target class
            removed = False
            for v in color_classes[target_c][:]:
                # try direct reassignment to a lower color
                neighbor_colors = set(color[u] for u in neighbors[v])
                for c in range(target_c):
                    if c not in neighbor_colors:
                        color[v] = c
                        removed = True
                        improved = True
                        break
                if removed:
                    break
                # try Kempe chain swaps with each lower color
                for c in range(target_c):
                    # if v already can take c, skip (should have been caught)
                    if c not in set(color[u] for u in neighbors[v]):
                        continue
                    # build Kempe chain of colors {c, target_c} containing v
                    # BFS
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (color[y] == c or color[y] == target_c):
                                visited[y] = True
                                queue.append(y)
                    # check if swapping frees color c for v
                    # after swap, v would get color c if it was target_c
                    # we need that no neighbor of v has color c after swap
                    # neighbors currently with color c will become target_c, so they won't conflict
                    # neighbors with color target_c will become c, so we must ensure none of them are neighbors of v
                    conflict = False
                    for y in neighbors[v]:
                        if color[y] == target_c and y in component:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for x in component:
                            if color[x] == c:
                                color[x] = target_c
                            else:
                                color[x] = c
                        removed = True
                        improved = True
                        break
                if removed:
                    break
            if removed:
                # recompute best_k and compact
                color = compact(color)
                best_k = max(color) + 1 if color else 0
        return color
    best_color = kempe_reduction(best_color)
    # final validation and compact
    def compact(col):
        mapping = {}
        next_c = 0
        for v in range(n):
            c = col[v]
            if c not in mapping:
                mapping[c] = next_c
                next_c += 1
            col[v] = mapping[c]
        return col
    best_color = compact(best_color)
    # verify
    for u in range(n):
        for v in neighbors[u]:
            if best_color[u] == best_color[v]:
                # should not happen, but fallback to greedy
                return greedy_color(list(range(n)))
    return best_color

