    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            neighbors = adj[i]
            adj_list[i] = neighbors[:]
            mask = 0
            for j in neighbors:
                mask |= (1 << j)
            bit_adj[i] = mask

