            # select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    sat_u = saturation[u]
                    # degree in uncolored subgraph
                    deg_u = 0
                    for w in adj_list[u]:
                        if not colored[w]:
                            deg_u += 1
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
                    elif sat_u == max_sat and deg_u == max_deg:
                        if v == -1 or u < v:
                            v = u
            # assign smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            # update saturation and neighbor colors for neighbors
            for w in adj_list[v]:
                if not colored[w]:
                    # add color c to neighbor's palette if not present
                    if not (neighbor_colors[w] & (1 << c)):
                        neighbor_colors[w] |= (1 << c)
                        saturation[w] += 1
