        full_deg = [len(adj_list[i]) for i in range(n)]

        while True:
            # find uncolored vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    deg = 0
                    for w in adj_list[u]:
                        if not colored[w]:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        v = u
                    elif deg == max_deg and u < v:
                        v = u
