            # W: uncolored and adjacent to S
            U = set()
            W = set()
            for u in range(n):
                if not colored[u]:
                    if v in adj_list[u] or u == v:
                        W.add(u)
                    else:
                        U.add(u)
            # Note: v is now colored, so not in U or W
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # degree in U-induced subgraph
                    deg_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_U < min_deg_U):
                        max_w_neighbors = w_count
