                        best_u = u
                    elif w_count == max_w_neighbors and deg_U == min_deg_U:
                        if best_u == -1 or u < best_u:
                            best_u = u
                # add best_u to S
                S.append(best_u)
                colored[best_u] = True
                colors[best_u] = color_idx
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            color_idx += 1
