    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # remove v
            remaining.remove(v)
            order.append(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # remove u from its current bucket
                    old_deg = degree[u]
                    buckets[old_deg].remove(u)
                    degree[u] -= 1
                    new_deg = degree[u]
                    buckets[new_deg].append(u)
                    if new_deg < ptr:
                        ptr = new_deg
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        used_by_neighbors |= (1 << colors[u])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c after direct reassignment attempt, skip
                    if colors[v] == c:
                        continue
                    # find the Kempe chain component of v in colors {c, target_color}
                    # BFS/DFS to get component
                    stack = [v]
                    visited = set()
                    comp_target = set()  # vertices in component with color target_color
                    comp_c = set()       # vertices in component with color c
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        col = colors[node]
                        if col == target_color:
                            comp_target.add(node)
                        elif col == c:
                            comp_c.add(node)
                        else:
                            continue
                        for nb in adj_list[node]:
                            if nb not in visited and (colors[nb] == target_color or colors[nb] == c):
                                stack.append(nb)
                    # check if we can swap: after swap, no vertex in comp_c will have a neighbor with color target_color (outside comp)
                    # actually, swapping is always safe because it only exchanges two colors in the component
                    # but we want to free target_color for v, which requires that after swap, v gets color c
                    # and we want to know if color target_color is still used elsewhere? we just want to remove target_color if possible
                    # Instead, we check if after swap, the color target_color is not used by any vertex in the component originally colored c
                    # because those will become target_color. If any of them has a neighbor outside the component with color target_color, then conflict.
                    safe = True
                    for u in comp_c:
                        for nb in adj_list[u]:
                            if nb not in comp_target and colors[nb] == target_color:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # perform swap
                        for u in comp_target:
                            colors[u] = c
                        for u in comp_c:
                            colors[u] = target_color
                        changed = True
                        break
                if changed:
                    break
            if changed:
                colors = compact_colors(colors)
                k = num_colors(colors)
        return colors

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: greedy Welsh-Powell
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(compact_colors(colors))

    # Apply Kempe reduction to each candidate and pick best
    best_colors = None
    best_k = float('inf')
    for col in candidates:
        try:
            col_reduced = kempe_reduce(col[:])  # work on a copy
            if is_valid_coloring(col_reduced):
                k = num_colors(col_reduced)
                if k < best_k:
                    best_k = k
                    best_colors = col_reduced
        except:
            continue

    # Final validation and compact
    if best_colors is None:
        best_colors = candidates[0] if candidates else [0] * n
    best_colors = compact_colors(best_colors)
    if not is_valid_coloring(best_colors):
        # ultimate fallback: greedy on random order
        for _ in range(10):
            order = list(range(n))
            random.shuffle(order)
            colors = [-1] * n
            for v in order:
                used = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
                c = 0
                while used & (1 << c):
                    c += 1
                colors[v] = c
            if is_valid_coloring(colors):
                best_colors = compact_colors(colors)
                break
        else:
            # last resort: assign distinct colors
            best_colors = list(range(n))
    return best_colors

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if binary matrix
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Bitmask representation for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: compute degree in subgraph induced by vertices in set S
    def degree_in_set(u, in_set):
        if not in_set[u]:
            return 0
        # Count neighbors of u that are also in the set
        return (bit_adj[u] & in_set).bit_count()

    # Helper: compute saturation degree of vertex u w.r.t. current coloring
    def saturation_degree(u, color_of):
        if color_of[u] != -1:
            return -1  # already colored
        # Compute set of colors used by colored neighbors
        neighbor_colors = 0
        for v in adj_list[u]:
            c = color_of[v]
            if c != -1:
                neighbor_colors |= (1 << c)
        return neighbor_colors.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(color_of):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and color_of[u] == color_of[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(color_of):
        # Map used colors to 0..k-1
        used = set()
        for c in color_of:
            if c != -1:
                used.add(c)
        mapping = {}
        for i, c in enumerate(sorted(used)):
            mapping[c] = i
        return [mapping[c] if c != -1 else -1 for c in color_of]

    # DSATUR with degree tie-breaking
    def dsatur():
        color_of = [-1] * n
        # Order vertices by initial degree descending for tie-breaking in saturation
        degrees = [len(adj_list[i]) for i in range(n)]
        # We'll maintain a list of uncolored vertices
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation degree, break ties by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation_degree(v, color_of)
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = degree_in_set(v, [u in uncolored for u in range(n)])
                elif sat == best_sat:
                    deg = degree_in_set(v, [u in uncolored for u in range(n)])
                    if deg > best_deg or (deg == best_deg and random.random() < 0.5):
                        best_v = v
                        best_deg = deg
            v = best_v
            # Find smallest available color
            neighbor_colors = 0
            for u in adj_list[v]:
                c = color_of[u]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color_of[v] = c
            uncolored.remove(v)
        return color_of

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        color_of = [-1] * n
        uncolored = [True] * n  # True if uncolored
        color = 0
        while any(uncolored):
            # Build independent set for this color
            S = []  # vertices to color with current color
            # Step 1: pick vertex of max degree in uncolored subgraph
            max_deg = -1
            v1 = -1
            for u in range(n):
                if uncolored[u]:
                    deg = degree_in_set(u, uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        v1 = u
            if v1 == -1:  # no uncolored vertices
                break
            S.append(v1)
            uncolored[v1] = False
            # Partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = [True] * n  # eligible: not adjacent to any in S
            W = [False] * n  # ineligible: adjacent to S
            for u in range(n):
                if uncolored[u]:
                    # check if u is adjacent to any vertex in S
                    adj_to_S = False
                    for s in S:
                        if u in adj_list[s]:
                            adj_to_S = True
                            break
                    if adj_to_S:
                        W[u] = True
                    else:
                        U[u] = True
                else:
                    U[u] = False
                    W[u] = False
            # While U not empty, add vertices to S
            while any(U):
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in range(n):
                    if U[u]:
                        # Count neighbors in W
                        w_mask = 0
                        for w in range(n):
                            if W[w]:
                                w_mask |= (1 << w)
                        score = (bit_adj[u] & w_mask).bit_count()
                        if score > best_score:
                            best_score = score
                            best_u = u
                            best_deg_U = degree_in_set(u, U)
                        elif score == best_score:
                            deg_u = degree_in_set(u, U)
                            if deg_u < best_deg_U or (deg_u == best_deg_U and random.random() < 0.5):
                                best_u = u
                                best_deg_U = deg_u
                u = best_u
                if u == -1:
                    break  # should not happen if U not empty
                S.append(u)
                uncolored[u] = False
                U[u] = False
                # Move neighbors of u from U to W
                for v in adj_list[u]:
                    if U[v]:
                        U[v] = False
                        W[v] = True
            # Assign color to all in S
            for u in S:
                color_of[u] = color
            color += 1
        return color_of

    # Smallest-Last (Matula & Beck) ordering + greedy
    def smallest_last():
        # Build degeneracy ordering (smallest last)
        # We'll use bucket sort for efficiency
        if n == 0:
            return []
        degree = [len(adj_list[i]) for i in range(n)]
        # Initialize buckets
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].append(i)
        # Pointers
        pos = [0] * n  # position of vertex in its bucket
        for d in range(max_deg + 1):
            for i, v in enumerate(buckets[d]):
                pos[v] = i
        # Current min degree
        d = 0
        ordering = []  # will store vertices in order removed (smallest last first)
        # Arrays to track if vertex is removed
        removed = [False] * n
        # For each vertex, maintain current degree in remaining graph
        curr_degree = degree[:]
        for _ in range(n):
            # Find non-empty bucket with smallest d
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            # Remove a vertex from bucket d
            v = buckets[d].pop()
            removed[v] = True
            ordering.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    # Remove u from its current bucket
                    old_deg = curr_degree[u]
                    buckets[old_deg].remove(u)  # O(bucket size) but n <= 100
                    pos[u] = len(buckets[old_deg])  # update position? not needed if we remove by value
                    curr_degree[u] -= 1
                    new_deg = curr_degree[u]
                    if new_deg < len(buckets):
                        buckets[new_deg].append(u)
                    else:
                        # extend buckets if necessary (should not happen as degree decreases)
                        buckets.append([])
                        buckets[new_deg].append(u)
            # Note: we don't need to maintain pos if we remove by value, but removal is O(n)
            # Since n <= 100, it's acceptable.
        # Now color in reverse order (largest degree first in the ordering)
        color_of = [-1] * n
        for v in reversed(ordering):
            neighbor_colors = 0
            for u in adj_list[v]:
                c = color_of[u]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color_of[v] = c
        return color_of

    # Kempe chain color reduction
    def kempe_reduce(color_of):
        # Make a copy to work on
        best_color_of = color_of[:]
        improved = True
        while improved:
            improved = False
            # Find the largest color index used
            max_color = max(best_color_of) if best_color_of else -1
            if max_color < 0:
                break
            # Try to eliminate color classes from highest to lowest
            for target_color in range(max_color, -1, -1):
                # Collect vertices with this color
                target_vertices = [v for v in range(n) if best_color_of[v] == target_color]
                if not target_vertices:
                    continue
                # Try to recolor each vertex in target_vertices to a lower color
                made_change = False
                for v in target_vertices:
                    # Try direct reassignment to a lower color
                    neighbor_colors = 0
                    for u in adj_list[v]:
                        c = best_color_of[u]
                        if c != -1:
                            neighbor_colors |= (1 << c)
                    # Find smallest available color < target_color
                    for c in range(target_color):
                        if not (neighbor_colors & (1 << c)):
                            # Recolor v to c
                            best_color_of[v] = c
                            made_change = True
                            improved = True
                            break
                    if made_change:
                        break
                    # Try Kempe chain swaps with each lower color
                    for c in range(target_color):
                        # We'll try to swap colors c and target_color in the component containing v
                        # Only if v is not already color c (it isn't, since it's target_color)
                        # Build the Kempe chain for colors c and target_color starting from v
                        # We'll do BFS/DFS on the subgraph induced by vertices of color c or target_color
                        from collections import deque
                        visited = [False] * n
                        queue = deque()
                        # Only start if v is of target_color (it is)
                        if best_color_of[v] != target_color:
                            continue
                        visited[v] = True
                        queue.append(v)
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for nb in adj_list[node]:
                                if not visited[nb] and (best_color_of[nb] == c or best_color_of[nb] == target_color):
                                    visited[nb] = True
                                    queue.append(nb)
                        # Check if any neighbor of v in the component has color c? Actually, we want to see
                        # if swapping the component would free color c for v.
                        # After swap, v would become color c if it was target_color.
                        # We need to ensure that no neighbor of v is colored c after swap.
                        # Currently, neighbors of v that are in the component and colored c would become target_color.
                        # So we need to check: after swap, would any neighbor of v be color c?
                        # Neighbors of v that are colored c and NOT in the component remain c.
                        # Neighbors of v that are colored c and IN the component become target_color.
                        # Neighbors of v that are colored target_color and IN the component become c.
                        # So we need to check: are there any neighbors of v that are colored c and NOT in the component?
                        conflict = False
                        for nb in adj_list[v]:
                            if best_color_of[nb] == c and not visited[nb]:
                                conflict = True
                                break
                        if not conflict:
                            # Perform swap: swap colors c and target_color in the component
                            for node in component:
                                if best_color_of[node] == c:
                                    best_color_of[node] = target_color
                                else:  # must be target_color
                                    best_color_of[node] = c
                            made_change = True
                            improved = True
                            break
                    if made_change:
                        break
                if made_change:
                    # After recoloring some vertices, we may have vacated target_color entirely
                    # Check if target_color is still used
                    if target_color not in best_color_of:
                        # Compact colors down by one
                        # Map colors > target_color down by 1
                        for i in range(n):
                            if best_color_of[i] > target_color:
                                best_color_of[i] -= 1
                        break  # break out of target_color loop to restart while
            # If we made a change and compacted, we'll restart the while loop
        return best_color_of

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fall back to greedy
    if not candidates:
        color_of = [-1] * n
        for i in range(n):
            neighbor_colors = 0
            for u in adj_list[i]:
                c = color_of[u]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color_of[i] = c
        candidates.append(color_of)

    # Select best candidate (fewest colors)
    best = None
    best_num_colors = float('inf')
    for cand in candidates:
        num_colors = len(set(cand))
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best = cand
        elif num_colors == best_num_colors:
            # Tie-break by lexicographical order or random? We'll keep first.
            pass

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best)
        if is_valid_coloring(improved):
            num_colors_imp = len(set(improved))
            if num_colors_imp < best_num_colors:
                best = improved
                best_num_colors = num_colors_imp
    except:
        pass

    # Compact colors to 0..k-1
    best = compact_colors(best)
    # Final validation (should be valid by construction)
    if not is_valid_coloring(best):
        # Fallback to simple greedy
        color_of = [-1] * n
        for i in range(n):
            neighbor_colors = 0
            for u in adj_list[i]:
                c = color_of[u]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color_of[i] = c
        best = compact_colors(color_of)

    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Convert to adjacency list and compute degrees
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            row = adj[i]
            for j in range(n):
                if row[j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj
    degrees = [len(adj_list[i]) for i in range(n)]
    # Edge case: no edges
    if all(d == 0 for d in degrees):
        return [0] * n
    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color
    # Helper: count colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True
    # DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: list of sets of neighbor colors
        saturation = [set() for _ in range(n)]
        # uncolored set
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = len(saturation[v])
                # compute degree in uncolored subgraph
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # find smallest available color
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u].add(c)
        return color
    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set S for color c
            S = set()
            # choose vertex with max degree in uncolored subgraph
            best_v = -1
            best_deg = -1
            for v in uncolored:
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if deg > best_deg:
                    best_deg = deg
                    best_v = v
            v = best_v
            S.add(v)
            # partition U and W
            U = uncolored - {v}
            W = set()
            for u in list(U):
                for w in S:
                    if w in adj_list[u]:
                        W.add(u)
                        U.remove(u)
                        break
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in U subgraph
                best_u = -1
                best_score = -1
                best_deg_u = -1
                for u in U:
                    # score: neighbors in W
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    # degree in U subgraph
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or (score == best_score and deg_u == best_deg_u and u < best_u):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        W.add(w)
                        U.remove(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color
    # Smallest-Last ordering
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [degrees[i] for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            buckets[d].add(v)
        # peel
        for _ in range(n):
            # find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # remove u from its bucket
                    old_deg = degree[u]
                    buckets[old_deg].remove(u)
                    degree[u] -= 1
                    new_deg = degree[u]
                    buckets[new_deg].add(u)
            remaining.remove(v)
        # color in reverse order
        return greedy_color(order[::-1])
    # Generate candidates
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except:
        pass
    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append(col_sl)
    except:
        pass
    # Also try Welsh-Powell (degree descending)
    try:
        order_wp = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        col_wp = greedy_color(order_wp)
        if is_valid(col_wp):
            candidates.append(col_wp)
    except:
        pass
    # If no candidate (should not happen), fallback to greedy with natural order
    if not candidates:
        col_greedy = greedy_color(list(range(n)))
        if is_valid(col_greedy):
            candidates.append(col_greedy)
        else:
            # last resort: assign each vertex a unique color
            return list(range(n))
    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=count_colors)
    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make copy
        col = coloring[:]
        k = count_colors(col)
        if k <= 1:
            return col
        # iterate while we can reduce
        improved = True
        while improved and k > 1:
            improved = False
            # target smallest color class (color k-1)
            target_color = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if col[v] == target_color]
            if not target_vertices:
                # should not happen
                break
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = [False] * k
                for u in adj_list[v]:
                    if col[u] != -1:
                        used[col[u]] = True
                for c in range(target_color):
                    if not used[c]:
                        # move v to color c
                        col[v] = c
                        improved = True
                        break
                if improved:
                    # after moving v, check if target color class is empty
                    if target_color not in col:
                        # compact colors
                        mapping = {}
                        new_color = 0
                        for old in range(k):
                            if old in col:
                                mapping[old] = new_color
                                new_color += 1
                        for i in range(n):
                            col[i] = mapping[col[i]]
                        k = new_color
                        break  # restart while loop
                    else:
                        # still have target color, but we improved by moving one vertex
                        # continue to try other vertices
                        pass
                if improved:
                    break  # break for loop to restart while
            if improved:
                continue  # restart while loop with possibly new k
            # If no direct reassignment, try Kempe chains
            for v in target_vertices:
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (target_color, c)
                    # If v is not adjacent to any vertex of color c, we could recolor directly (already checked)
                    # So we assume there is at least one neighbor of color c
                    # Build Kempe chain component containing v in colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (col[nb] == target_color or col[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any neighbor of v in the component has color c? Actually, we want to see if
                    # swapping the component would cause a conflict: after swap, v becomes color c.
                    # It is safe if no neighbor of v (outside component) has color c.
                    # But note: neighbors inside component that are color c will become target_color, which is ok because v leaves target_color.
                    # So we only need to check neighbors not in component.
                    conflict = False
                    for node in component:
                        for nb in adj_list[node]:
                            if not visited[nb] and col[nb] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # perform swap
                        for node in component:
                            if col[node] == target_color:
                                col[node] = c
                            else:
                                col[node] = target_color
                        improved = True
                        # after swap, check if target color class is empty
                        if target_color not in col:
                            mapping = {}
                            new_color = 0
                            for old in range(k):
                                if old in col:
                                    mapping[old] = new_color
                                    new_color += 1
                            for i in range(n):
                                col[i] = mapping[col[i]]
                            k = new_color
                        break  # break c loop
                if improved:
                    break  # break v loop
            # end Kempe chain attempt
        # end while
        return col
    # Apply Kempe reduction
    try:
        reduced = kempe_reduce(best_coloring)
        if is_valid(reduced):
            best_coloring = reduced
    except:
        pass
    # Ensure colors are consecutive starting from 0
    # (Kempe reduction should have done this, but just in case)
    used_colors = set(best_coloring)
    if used_colors:
        mapping = {}
        sorted_colors = sorted(used_colors)
        for idx, col in enumerate(sorted_colors):
            mapping[col] = idx
        for i in range(n):
            best_coloring[i] = mapping[best_coloring[i]]
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Convert to adjacency list and bitmask
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = [list(neigh) for neigh in adj]
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # DSATUR with degree tie-breaking
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        sat = [0] * n
        deg = [len(adj_list[i]) for i in range(n)]
        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], deg[x], random.random()))
            # Find smallest available color
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    sat[nb] = 0
                    seen = set()
                    for nb2 in adj_list[nb]:
                        if color[nb2] != -1 and color[nb2] not in seen:
                            seen.add(color[nb2])
                            sat[nb] += 1
        return color

    # RLF: Recursive Largest First independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in adj_list[x] if nb in uncolored))
            S.add(v)
            # Partition remaining uncolored
            U = uncolored - {v}
            W = set()
            for nb in adj_list[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
            # Greedily add to S
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                def score(u):
                    w_neighbors = sum(1 for nb in adj_list[u] if nb in W)
                    u_deg = sum(1 for nb in adj_list[u] if nb in U)
                    return (w_neighbors, -u_deg)
                u = max(U, key=score)
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering (peel min degree)
        deg = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Use bucket sort for efficiency
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = v
        # Simulate peeling
        curr_deg = 0
        for _ in range(n):
            while curr_deg <= max_deg and not buckets[curr_deg]:
                curr_deg += 1
            if curr_deg > max_deg:
                break
            v = buckets[curr_deg].pop()
            order.append(v)
            remaining.remove(v)
            for nb in adj_list[v]:
                if nb in remaining:
                    d = deg[nb]
                    if d > 0:
                        deg[nb] -= 1
                        buckets[d].remove(nb)
                        buckets[d-1].append(nb)
        # Color in reverse peeling order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    # Also try Welsh-Powell (degree ordering)
    wp_order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
    candidates.append(greedy_color(wp_order))
    # Try random orders a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal k
        changed = True
        while changed and k > 1:
            changed = False
            # Find smallest color class (highest index)
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[coloring[v]].append(v)
            # Try to eliminate color k-1
            target = k - 1
            if not color_classes[target]:
                # Should not happen, but skip
                k -= 1
                continue
            # Try to recolor each vertex in target class
            for v in color_classes[target][:]:
                # Try direct reassignment to a lower color
                used = 0
                for nb in adj_list[v]:
                    if coloring[nb] != -1:
                        used |= (1 << coloring[nb])
                for c in range(target):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    # Rebuild classes and continue
                    color_classes = [[] for _ in range(k)]
                    for v2 in range(n):
                        color_classes[coloring[v2]].append(v2)
                    if not color_classes[target]:
                        k -= 1
                        break
                    continue
                # Try Kempe chains with each lower color
                for c in range(target):
                    # Find Kempe chain of (target, c) containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target or coloring[node] == c:
                            component.add(node)
                            for nb in adj_list[node]:
                                if nb not in visited and (coloring[nb] == target or coloring[nb] == c):
                                    stack.append(nb)
                    # Check if swapping this component is safe: no neighbor outside component has color c
                    safe = True
                    for node in component:
                        for nb in adj_list[node]:
                            if nb not in component and coloring[nb] == c:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for node in component:
                            if coloring[node] == target:
                                coloring[node] = c
                            else:
                                coloring[node] = target
                        changed = True
                        break
                if changed:
                    # Rebuild and check if target class empty
                    color_classes = [[] for _ in range(k)]
                    for v2 in range(n):
                        color_classes[coloring[v2]].append(v2)
                    if not color_classes[target]:
                        k -= 1
                        break
            # End for each vertex in target class
        # Compact colors to 0..k-1
        # Map used colors to consecutive
        used_colors = set(coloring)
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        coloring = [mapping[c] for c in coloring]
        return coloring

    best = kempe_reduce(best)
    # Final validation (should always hold)
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        # Adjacency list
        neighbors = [set(row) for row in adj]

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    def validate_and_compact(coloring):
        # Validate coloring
        for u in range(n):
            for v in neighbors[u]:
                if coloring[u] == coloring[v]:
                    return None  # Invalid
        # Compact colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for c in coloring:
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
        return [unique_colors[c] for c in coloring]

    # Heuristic 1: DSATUR
    def dsatur():
        coloring = [-1] * n
        saturation = [0] * n  # Number of distinct colors in neighborhood
        colored_neighbors_mask = [0] * n  # Bitmask of colored neighbors

        # Helper to update saturation of uncolored neighbors of v
        def update_saturation(v, color):
            mask = bit_adj[v]
            u = 0
            while mask:
                if mask & 1:
                    if coloring[u] == -1:  # uncolored
                        # Check if this color is new in u's neighborhood
                        if not (colored_neighbors_mask[u] & (1 << color)):
                            colored_neighbors_mask[u] |= (1 << color)
                            saturation[u] += 1
                mask >>= 1
                u += 1

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            candidates = []
            max_sat = -1
            for v in range(n):
                if coloring[v] == -1:
                    sat = saturation[v]
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
            if not candidates:
                break  # should not happen
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                deg_candidates = []
                for v in candidates:
                    # Count uncolored neighbors
                    uncolored_mask = bit_adj[v] & ~sum((1 << i) for i in range(n) if coloring[i] != -1)
                    deg = uncolored_mask.bit_count()
                    if deg > max_deg:
                        max_deg = deg
                        deg_candidates = [v]
                    elif deg == max_deg:
                        deg_candidates.append(v)
                candidates = deg_candidates
            v = random.choice(candidates) if len(candidates) > 1 else candidates[0]
            # Assign smallest available color
            used = colored_neighbors_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            update_saturation(v, c)
        return validate_and_compact(coloring)

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for this color
            S = set()
            # Step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: (bit_adj[x] & sum((1 << i) for i in uncolored)).bit_count())
            S.add(v)
            # Partition U and W
            U = uncolored - {v} - (set(i for i in range(n) if (bit_adj[v] >> i) & 1))
            W = set(i for i in range(n) if (bit_adj[v] >> i) & 1) & uncolored

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = math.inf
                for u in U:
                    w_neighbors = (bit_adj[u] & sum((1 << w) for w in W)).bit_count()
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = (bit_adj[u] & sum((1 << i) for i in U)).bit_count()
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_in_U = (bit_adj[u] & sum((1 << i) for i in U)).bit_count()
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = u
                if best_u is None:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u in U to W
                nbrs = set(i for i in range(n) if (bit_adj[best_u] >> i) & 1)
                to_move = U & nbrs
                U -= to_move
                W |= to_move
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
            uncolored -= S
        return validate_and_compact(coloring)

    # Heuristic 3: Smallest-Last (Degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering (smallest last)
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # We'll simulate peeling
        temp_adj = [set(neighbors[i]) for i in range(n)]
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda x: len(temp_adj[x] & remaining))
            order.append(v)
            remaining.remove(v)
            # Remove v from neighbors' temp_adj
            for u in temp_adj[v]:
                if u in temp_adj:
                    temp_adj[u].discard(v)
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return validate_and_compact(coloring)

    # Run all heuristics and pick best (fewest colors)
    candidates = []
    for heuristic in [dsatur, rlf, smallest_last]:
        try:
            col = heuristic()
            if col is not None:
                candidates.append(col)
        except Exception:
            continue  # In case of unexpected error, skip

    # Fallback: greedy Welsh-Powell if all heuristics failed
    if not candidates:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        candidates.append(validate_and_compact(coloring))

    # Select candidate with minimal number of colors
    best_coloring = min(candidates, key=lambda x: max(x) + 1 if x else 0)

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        if coloring is None:
            return None
        # Make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find smallest color class (largest color index that is used)
            max_color = max(col) if col else -1
            if max_color < 0:
                return col
            # Try to eliminate color classes from highest down
            for target_color in range(max_color, 0, -1):
                # Get vertices with this color
                target_vertices = [v for v in range(n) if col[v] == target_color]
                if not target_vertices:
                    continue  # already eliminated
                # Try to recolor each vertex in this class
                eliminated = True
                for v in target_vertices:
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in neighbors[v]:
                        if col[u] != -1:
                            used |= (1 << col[u])
                    # Try colors 0..target_color-1
                    found = False
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            col[v] = c
                            found = True
                            changed = True
                            break
                    if found:
                        continue
                    # Try Kempe chain swap with each lower color
                    for c in range(target_color):
                        # Check if v can be swapped with color c via Kempe chain
                        # We consider the subgraph induced by colors target_color and c
                        # Find the Kempe chain containing v in this subgraph
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for u in neighbors[node]:
                                if not visited[u] and (col[u] == target_color or col[u] == c):
                                    visited[u] = True
                                    queue.append(u)
                        # Check if any neighbor of v in the component has color c? Actually, we want to see
                        # if we can swap colors in this component without causing conflict.
                        # Swapping is safe if no neighbor of any node in the component (outside the component)
                        # has the color we are swapping to.
                        # More precisely: after swapping target_color<->c in the component,
                        # for each node in component, its new color should not conflict with neighbors.
                        # This is equivalent to: for each node in component, none of its neighbors
                        # (outside the component) has the color we are switching to.
                        can_swap = True
                        for node in component:
                            for u in neighbors[node]:
                                if not visited[u]:  # neighbor outside component
                                    if col[u] == c:  # would become target_color after swap, conflict if node becomes c
                                        can_swap = False
                                        break
                                    if col[u] == target_color:  # would become c after swap, conflict if node becomes target_color
                                        can_swap = False
                                        break
                            if not can_swap:
                                break
                        if can_swap:
                            # Perform swap
                            for node in component:
                                if col[node] == target_color:
                                    col[node] = c
                                elif col[node] == c:
                                    col[node] = target_color
                            changed = True
                            break  # break from color c loop, go to next vertex
                    # If we couldn't recolor v, we cannot eliminate this color class yet
                    if not changed:
                        eliminated = False
                        break
                if eliminated and changed:
                    # Successfully eliminated target_color, compact and break to restart
                    # Compact colors
                    mapping = {}
                    next_c = 0
                    for i in range(n):
                        if col[i] not in mapping:
                            mapping[col[i]] = next_c
                            next_c += 1
                    col = [mapping[c] for c in col]
                    break  # break from target_color loop to restart while
            # If we eliminated a color in this iteration, the outer while will restart
        return col

    # Apply Kempe reduction
    try:
        reduced = kempe_reduction(best_coloring)
        if reduced is not None:
            best_coloring = reduced
    except Exception:
        pass  # Keep original if reduction fails

    return best_coloring

