def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True
    # Convert to adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj
    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in the uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, then max degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                if sat > best_sat or (sat == best_sat and uncolored_deg[v] > best_deg) or \
                   (sat == best_sat and uncolored_deg[v] == best_deg and (best_v == -1 or v < best_v)):
                    best_sat = sat
                    best_deg = uncolored_deg[v]
                    best_v = v
            v = best_v
            # assign smallest available color
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # degree in current uncolored subgraph
            deg_uncolored = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_uncolored[v] += 1
            # choose vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S.append(v)
            # partition U and W
            U = uncolored - {v}
            W = set()
            for u in adj_list[v]:
                if u in uncolored:
                    W.add(u)
                    if u in U:
                        U.remove(u)
            # grow independent set
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_u = None
                for u in U:
                    # count neighbors in W
                    cnt = 0
                    for w in adj_list[u]:
                        if w in W:
                            cnt += 1
                    deg_u = deg_uncolored[u]  # degree in current uncolored
                    if cnt > best_score or (cnt == best_score and deg_u < best_deg_u) or \
                       (cnt == best_score and deg_u == best_deg_u and (best_u == -1 or u < best_u)):
                        best_score = cnt
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            # remove S from uncolored
            uncolored -= set(S)
            c += 1
        return color

    # Helper: smallest-last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get order
        degree = [len(adj_list[i]) for i in range(n)]
        # buckets for degrees
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # track position
        pos = list(range(n))
        # current min degree
        min_deg = 0
        order = []
        # copy of degree for updating
        curr_deg = degree[:]
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            # update neighbors
            for u in adj_list[v]:
                if curr_deg[u] > min_deg:  # only if u not yet removed
                    # remove u from its bucket
                    d = curr_deg[u]
                    buckets[d].remove(u)
                    curr_deg[u] -= 1
                    buckets[curr_deg[u]].append(u)
                    if curr_deg[u] < min_deg:
                        min_deg = curr_deg[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Helper: Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, a, b, v):
        # returns new coloring after swapping a and b in the component of v
        # only if v has color a or b
        if coloring[v] not in (a, b):
            return coloring
        # BFS to get component
        from collections import deque
        comp = []
        visited = [False] * n
        q = deque([v])
        visited[v] = True
        while q:
            u = q.popleft()
            comp.append(u)
            for w in adj_list[u]:
                if not visited[w] and coloring[w] in (a, b):
                    visited[w] = True
                    q.append(w)
        # swap colors in component
        new_coloring = coloring[:]
        for u in comp:
            if new_coloring[u] == a:
                new_coloring[u] = b
            else:
                new_coloring[u] = a
        return new_coloring

    # Helper: attempt to eliminate the last color using Kempe chains
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # target color class k-1
        target = k - 1
        vertices = [v for v in range(n) if coloring[v] == target]
        # try to recolor each vertex in target class
        for v in vertices:
            # try direct reassignment to a lower color
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            for c in range(target):
                if not (used & (1 << c)):
                    # move v to color c
                    coloring[v] = c
                    # after moving, check if target class is empty
                    if not any(coloring[u] == target for u in range(n)):
                        return coloring
                    # if not, revert and try Kempe
                    coloring[v] = target
            # try Kempe chains with each lower color
            for c in range(target):
                # check if v is in a Kempe chain that can be swapped to free color c
                # only if v is not adjacent to any vertex of color c
                adjacent_to_c = False
                for u in adj_list[v]:
                    if coloring[u] == c:
                        adjacent_to_c = True
                        break
                if not adjacent_to_c:
                    # swap colors target and c in the component of v
                    new_col = kempe_swap(coloring, target, c, v)
                    # after swap, check if target class is empty
                    if not any(new_col[u] == target for u in range(n)):
                        return new_col
                    # otherwise, revert (but we didn't store original, so we need to revert by swapping again?)
                    # Actually, we can just try the swap and if it doesn't eliminate, we move on.
                    # The coloring is not changed because we didn't assign; we used a copy.
                    # So no need to revert.
        # if we couldn't eliminate, return original
        return coloring

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass
    # Fallback: greedy by degree order
    try:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(c4)
    except Exception:
        pass
    # If no candidates (should not happen), assign all zeros
    if not candidates:
        return [0] * n
    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    # Iterative Kempe reduction
    start = time.time()
    while time.time() - start < 0.04:  # leave some margin
        new_best = reduce_colors(best)
        if num_colors(new_best) < num_colors(best):
            best = new_best
        else:
            break
    # Final validation and compact colors
    # Ensure colors are consecutive
    mapping = {}
    next_color = 0
    for v in range(n):
        c = best[v]
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
        best[v] = mapping[c]
    return best

