def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].add(j)

    # Handle isolated vertices and self-loops (though self-loops make coloring impossible, assume no self-loops)
    # Smallest-Last ordering (Matula & Beck)
    order = []
    remaining = set(range(n))
    deg = [len(neighbors[i]) for i in range(n)]
    # Current degree in the remaining subgraph
    curr_deg = deg[:]

    # We will repeatedly remove the vertex of minimum degree
    for _ in range(n):
        # Find vertex with minimum current degree
        min_deg = float('inf')
        v_min = -1
        for v in remaining:
            if curr_deg[v] < min_deg:
                min_deg = curr_deg[v]
                v_min = v
        # If tie, choose the smallest index (or random, but we choose smallest for determinism)
        # Actually, we break ties by vertex index (lowest) as per common practice
        # But we already pick the first min, so to be safe, we can re-scan for ties and pick min index
        # However, for simplicity and speed, we keep the first found. Since n<=100, we can do:
        candidates = [v for v in remaining if curr_deg[v] == min_deg]
        v_min = min(candidates)  # break ties by smallest vertex index

        order.append(v_min)
        remaining.remove(v_min)
        # Update current degrees of neighbors
        for u in neighbors[v_min]:
            if u in remaining:
                curr_deg[u] -= 1

    # Now color in reverse order (last removed first)
    color = [-1] * n
    # We'll color vertices in the reverse of the removal order
    for v in reversed(order):
        # Determine colors used by already colored neighbors
        used = [False] * n  # at most n colors needed
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        # Find the smallest color not used
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c

    # Compact colors: ensure they are 0..k-1 without gaps
    # But First-Fit in this order should already produce compact colors? Not necessarily, but we can remap.
    # However, the algorithm uses colors from 0 upward, so it should be compact.
    # But to be safe, we can remap.
    unique_colors = set(color)
    if not unique_colors:
        return [0] * n  # all isolated, but should have been colored 0
    mapping = {}
    sorted_colors = sorted(unique_colors)
    for idx, col in enumerate(sorted_colors):
        mapping[col] = idx
    color = [mapping[c] for c in color]

    return color

