                    neighbor_colors = set()
                    for u in adj_list[v]:
                        if colors[u] != -1:
                            neighbor_colors.add(colors[u])
                    sat = len(neighbor_colors)
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
            # Tie-break by degree in uncolored subgraph, then random
            if len(candidates) > 1:
                # Compute degree in uncolored subgraph
                uncolored_deg = [0] * n
                for v in candidates:
                    cnt = 0
                    for u in adj_list[v]:
                        if colors[u] == -1:
                            cnt += 1
                    uncolored_deg[v] = cnt
                max_deg = max(uncolored_deg[v] for v in candidates)
                final_candidates = [v for v in candidates if uncolored_deg[v] == max_deg]
                v = random.choice(final_candidates)
            else:
                v = candidates[0]
            # Assign smallest available color
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            for c in range(n + 1):
                if not used[c]:
