    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # Find vertex in uncolored with max degree in G[uncolored]
            max_deg = -1
            v0 = None
            for v in uncolored:
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
            S.add(v0)
