            U = uncolored - {v0}
            W = set()
            for u in U:
                if any(w in adj_list[u] for w in S):
                    W.add(u)
            U -= W
            # Greedily expand S
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_u_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_u_deg_in_U = sum(1 for x in adj_list[u] if x in U)
