            v = bins[ptr].pop()
            while removed[v]:
                if not bins[ptr]:
                    break
                v = bins[ptr].pop()
            if removed[v]:
                # Find any remaining vertex
                for i in range(n):
                    if not removed[i]:
                        v = i
                        break
            order.append(v)
            removed[v] = True
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    if d > 0:
                        curr_deg[u] -= 1
                        # Move u to bin d-1
                        if d-1 < len(bins):
                            bins[d-1].append(u)
                        else:
                            while len(bins) <= d-1:
                                bins.append([])
                            bins[d-1].append(u)
        # Color in reverse order (last removed first)
        colors = [-1] * n
        for v in reversed(order):
