                            if (node_color == target_color and nb_color == c) or \
                               (node_color == c and nb_color == target_color):
                                if nb not in comp:
                                    comp.add(nb)
                                    queue.append(nb)
                    # Check if swapping this component is safe: 
                    # After swap, no two adjacent vertices will have same color.
                    # Since we only swap target_color <-> c, and the component is bipartite in these two colors,
                    # it remains valid. However, we must ensure we don't accidentally create a conflict
                    # by introducing target_color where it wasn't before? Actually, swapping preserves validity.
                    # But we want to remove target_color from v, so after swap, v will have color c.
                    # We need to ensure that no neighbor of v has color c after swap? 
                    # Actually, after swap, v becomes c. We already know that in the current coloring, 
                    # v has no neighbor of color target_color (because it's that color itself and valid) 
                    # and we are checking for Kempe chain to free color c? 
                    # Standard Kempe: if we swap the component, v becomes c, and we need to check that 
                    # no neighbor of v is c after swap. 
                    # After swap, a neighbor of v that was in the component and had color c becomes target_color.
                    # So we need to check: after swap, for every neighbor u of v, new_colors[u] != c.
                    # Currently, neighbors of v have colors in neighbor_colors (which does not include target_color, 
                    # but may include c). 
                    # Let's simulate: 
                    # For a neighbor u of v:
                    #   If u in comp: 
                    #       if its color was c, becomes target_color
                    #       if its color was target_color, becomes c
                    #   Else: color unchanged.
                    # We want: after swap, color of u != c (which is v's new color).
                    # Case 1: u in comp and had color c -> becomes target_color -> not c (since target_color != c) -> OK.
                    # Case 2: u in comp and had color target_color -> becomes c -> conflict! (because v becomes c)
                    # Case 3: u not in comp -> color unchanged -> we require that it is not c.
                    # Therefore, the swap is safe only if no neighbor of v that is in the component had color target_color.
                    # But note: v itself is in comp and has target_color, and we are changing it to c.
                    # The condition is: there should be no neighbor u of v such that u is in the component and has color target_color.
                    # Because after swap, that u would become c and conflict with v.
                    safe = True
                    for u in adj_list[v]:
                        if u in comp and new_colors[u] == target_color:
                            safe = False
                            break
                    if safe:
                        # Perform the swap
                        for node in comp:
                            if new_colors[node] == target_color:
                                new_colors[node] = c
                            elif new_colors[node] == c:
                                new_colors[node] = target_color
                        swapped = True
                        break
                if swapped:
                    continue
                # If we couldn't recolor v, then we cannot eliminate this color class
                eliminated = False
                break
            if eliminated:
                # Successfully eliminated target_color: compact colors
                # Map colors: 
                #   Keep colors < target_color as is.
                #   Colors > target_color shift down by 1.
                #   target_color is removed.
                mapping = {}
                next_c = 0
                for col in range(k):
                    if col == target_color:
                        continue
                    mapping[col] = next_c
                    next_c += 1
                new_colors2 = [mapping[c] for c in new_colors]
                # Recurse
                return kempe_reduction(new_colors2)
        return colors

    # Apply Kempe reduction
    try:
        reduced = kempe_reduction(best_colors)
        if is_valid_coloring(reduced):
            final_colors = normalize_colors(reduced)
        else:
            final_colors = best_colors
    except:
        final_colors = best_colors

    return final_colors

