def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = (len(adj) > 0 and len(adj[0]) == n and
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    if is_matrix:
        # Convert matrix to adjacency list
        adj_list = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
    else:
        adj_list = adj

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: get neighbors as list
    def neighbors(u):
        return adj_list[u]

    # Helper: get degree in subgraph induced by vertices in set S
    def degree_in_set(u, S_set):
        if not S_set:
            return 0
        mask = 0
        for v in S_set:
            mask |= (1 << v)
        return (bit_adj[u] & mask).bit_count()

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # saturation degree
        # Initialize: pick vertex with max degree
        degrees = [len(neighbors(u)) for u in range(n)]
        v = max(range(n), key=lambda u: degrees[u])
        coloring[v] = 0
        # Update saturation of neighbors
        for u in neighbors(v):
            saturated[u] = 1
        # Color remaining vertices
        for _ in range(n - 1):
            # Select uncolored vertex with max saturation, tie-break by degree
            candidates = [u for u in range(n) if coloring[u] == -1]
            if not candidates:
                break
            max_sat = max(saturated[u] for u in candidates)
            max_candidates = [u for u in candidates if saturated[u] == max_sat]
            # Tie-break by degree in uncolored subgraph
            v = max(max_candidates, key=lambda u: degree_in_set(u, set(candidates)))
            # Assign smallest available color
            neighbor_colors = set()
            for u in neighbors(v):
                if coloring[u] != -1:
                    neighbor_colors.add(coloring[u])
            c = 0
            while c in neighbor_colors:
                c += 1
            coloring[v] = c
            # Update saturation for neighbors of v
            for u in neighbors(v):
                if coloring[u] == -1:
                    # Recompute saturation: distinct colors in neighbors
                    neighbor_colors_set = set()
                    for w in neighbors(u):
                        if coloring[w] != -1:
                            neighbor_colors_set.add(coloring[w])
                    saturated[u] = len(neighbor_colors_set)
        return coloring

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build maximal independent set for this color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: degree_in_set(u, uncolored))
            S.append(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                    U.remove(u)
            # Grow S from U
            while U:
                # Select u in U with max neighbors in W
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_count = 0
                    for w in W:
                        if (bit_adj[u] >> w) & 1:
                            w_count += 1
                    if w_count > max_w_neighbors:
                        max_w_neighbors = w_count
                        best_u = u
                    elif w_count == max_w_neighbors:
                        # Tie-break: min degree in U
                        deg_u = degree_in_set(u, U)
                        deg_best = degree_in_set(best_u, U) if best_u is not None else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break  # should not happen
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for u in list(U):
                    if (bit_adj[best_u] >> u) & 1:
                        W.add(u)
                        U.remove(u)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
            uncolored -= set(S)
        return coloring

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors(u)) for u in range(n)]
        # We'll update degrees as we remove vertices
        curr_degrees = degrees[:]
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda u: curr_degrees[u])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors(v):
                if u in remaining:
                    curr_degrees[u] -= 1
        # Color in reverse order using First-Fit
        coloring = [-1] * n
        for v in reversed(order):
            neighbor_colors = set()
            for u in neighbors(v):
                if coloring[u] != -1:
                    neighbor_colors.add(coloring[u])
            c = 0
            while c in neighbor_colors:
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, a, b, v):
        if coloring[v] not in (a, b):
            return False
        # BFS to get the Kempe chain component
        from collections import deque
        queue = deque([v])
        visited = set([v])
        component = set()
        target_color_a = a
        target_color_b = b
        while queue:
            u = queue.popleft()
            component.add(u)
            for w in neighbors(u):
                if w not in visited and coloring[w] in (target_color_a, target_color_b):
                    visited.add(w)
                    queue.append(w)
        # Swap colors in component
        for u in component:
            if coloring[u] == a:
                coloring[u] = b
            elif coloring[u] == b:
                coloring[u] = a
        return True

    # Try to eliminate the last color using Kempe chains or direct reassignment
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target_color = k - 1
        vertices = [v for v in range(n) if coloring[v] == target_color]
        # Try direct reassignment first
        for v in vertices:
            neighbor_colors = set()
            for u in neighbors(v):
                if coloring[u] != target_color:
                    neighbor_colors.add(coloring[u])
            for c in range(target_color):  # try colors 0..k-2
                if c not in neighbor_colors:
                    coloring[v] = c
                    break
        # Recheck if target color is still used
        if any(coloring[v] == target_color for v in range(n)):
            # Try Kempe chains for each vertex in target color
            vertices = [v for v in range(n) if coloring[v] == target_color]
            for v in vertices:
                for c in range(target_color):  # try swapping with each lower color
                    # Make a copy to test
                    test_coloring = coloring[:]
                    if kempe_swap(test_coloring, target_color, c, v):
                        # Check if after swap, v is no longer target_color
                        if test_coloring[v] != target_color:
                            # Accept the swap
                            coloring[:] = test_coloring
                            break
                else:
                    continue
                break
        # Recompact colors if necessary
        used = set(coloring)
        if len(used) < k:
            mapping = {old: new for new, old in enumerate(sorted(used))]
            coloring = [mapping[c] for c in coloring]
        return coloring

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate, fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for u in range(n):
            used = set()
            for v in neighbors(u):
                if coloring[v] != -1:
                    used.add(coloring[v])
            c = 0
            while c in used:
                c += 1
            coloring[u] = c
        candidates.append(coloring)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = reduce_colors(best)
    # Final validation and compaction
    if not is_valid(best):
        # Last resort: greedy
        coloring = [-1] * n
        for u in range(n):
            used = set()
            for v in neighbors(u):
                if coloring[v] != -1:
                    used.add(coloring[v])
            c = 0
            while c in used:
                c += 1
            coloring[u] = c
        best = coloring
    # Ensure colors are compact
    used = set(best)
    if used:
        mapping = {old: new for new, old in enumerate(sorted(used))]
        best = [mapping[c] for c in best]
    return best

