    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to use consecutive colors from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        unique = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique)}
        return [mapping[c] for c in coloring]

    # DSATUR with bitmask optimization
    def dsatur():
        coloring = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg_uncolored = [len(neighbors[u]) for u in range(n)]
        colored = [False] * n

        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            candidates = []
            max_sat = -1
            for u in range(n):
                if not colored[u]:
                    s = sat[u].bit_count()
                    if s > max_sat:
                        max_sat = s
                        candidates = [u]
                    elif s == max_sat:
                        candidates.append(u)
            if not candidates:
                break  # should not happen
            # tie-break by degree in uncolored subgraph
            max_deg = -1
            best_u = candidates[0]
            for u in candidates:
                if deg_uncolored[u] > max_deg:
                    max_deg = deg_uncolored[u]
                    best_u = u
                elif deg_uncolored[u] == max_deg:
                    if random.random() < 0.5:
                        best_u = u
