            # compute forbidden colors from neighbors
            forbidden = 0
            for v in neighbors[u]:
                if colored[v]:
                    forbidden |= (1 << coloring[v])
            # find smallest color not forbidden
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[u] = c
            colored[u] = True
            # update saturation and degree for neighbors
            for v in neighbors[u]:
                if not colored[v]:
                    sat[v] |= (1 << c)
                    deg_uncolored[v] -= 1
