                for u in U:
                    w_count = 0
                    for v in neighbors[u]:
                        if v in W:
                            w_count += 1
                    if w_count > max_w_neighbors:
                        max_w_neighbors = w_count
                        min_deg_U = sum(1 for v in neighbors[u] if v in U)
                        best_u = u
                    elif w_count == max_w_neighbors:
                        deg_u = sum(1 for v in neighbors[u] if v in U)
                        if deg_u < min_deg_U:
                            min_deg_U = deg_u
                            best_u = u
                if best_u is None:
                    break  # should not happen
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for v in neighbors[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # assign color to all in S
            for u in S:
                coloring[u] = color
            color += 1
        return normalize(coloring)

    # Smallest-Last (Matula & Beck) ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[u]) for u in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # pointer to current min degree
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            u = buckets[ptr].pop()
            order.append(u)
            remaining.remove(u)
            # update neighbors
            for v in neighbors[u]:
                if v in remaining:
                    d = degree[v]
                    degree[v] -= 1
                    buckets[d].remove(v)
                    buckets[d-1].append(v)
                    if d-1 < ptr:
                        ptr = d-1
        # color in reverse order
        coloring = [-1] * n
        for u in reversed(order):
            forbidden = 0
            for v in neighbors[u]:
                if coloring[v] != -1:
                    forbidden |= (1 << coloring[v])
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[u] = c
