        # try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # target highest color class
            target_color = k - 1
            vertices = [u for u in range(n) if coloring[u] == target_color]
            if not vertices:
                # already empty, compact
                mapping = {c: c for c in range(k)}
                new_coloring = [mapping[c] for c in coloring]
                k -= 1
                improved = True
                continue
            # try to recolor each vertex in target class
            for v in vertices:
