                for c in range(target_color):
                    # check if color c is available
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        improved = True
                        break
                if improved:
