def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect format and build adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = [list(lst) for lst in adj]  # copy

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= 1 << v
        bit_adj[u] = mask

    # Helper: greedy coloring given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                if color[v] != -1:
                    used |= 1 << color[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count colors used
    def count_colors(col):
        if not col:
            return 0
        return max(col) + 1

    # Helper: validate coloring
    def is_valid(col):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and col[u] == col[v]:
                    return False
        return True

    # Strategy 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg_uncolored = [len(neighbors[u]) for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                d = deg_uncolored[u]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and (best == -1 or random.random() < 0.5)):
                    best_sat = s
                    best_deg = d
                    best = u
            u = best
            # assign smallest available color
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
            uncolored.remove(u)
            # update saturation and degrees for neighbors
            for v in neighbors[u]:
                if v in uncolored:
                    sat[v] |= 1 << c
                    deg_uncolored[v] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # degree in current uncolored subgraph
            deg = {u: 0 for u in uncolored}
            for u in uncolored:
                for v in neighbors[u]:
                    if v in uncolored:
                        deg[u] += 1
            # start with max degree vertex
            S = set()
            if uncolored:
                v1 = max(uncolored, key=lambda u: deg[u])
                S.add(v1)
                # U: vertices not adjacent to any in S
                U = {u for u in uncolored if u not in S and all((bit_adj[u] & (1 << w)) == 0 for w in S)}
                W = uncolored - S - U
                while U:
                    # select u in U with max neighbors in W, tie-break by min degree in U
                    best_u = -1
                    best_score = -1
                    best_deg_u = None
                    for u in U:
                        # count neighbors in W
                        w_count = 0
                        for v in neighbors[u]:
                            if v in W:
                                w_count += 1
                        deg_u = len([v for v in neighbors[u] if v in U])
                        if w_count > best_score or (w_count == best_score and deg_u < best_deg_u) or (w_count == best_score and deg_u == best_deg_u and (best_u == -1 or random.random() < 0.5)):
                            best_score = w_count
                            best_deg_u = deg_u
                            best_u = u
                    u = best_u
                    S.add(u)
                    U.remove(u)
                    # move neighbors of u from U to W
                    for v in neighbors[u]:
                        if v in U:
                            U.remove(v)
                            W.add(v)
            # assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering
    def smallest_last():
        # core decomposition to get order
        deg = [len(neighbors[u]) for u in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[deg[u]].append(u)
        # maintain pointer to non-empty bucket
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            u = buckets[ptr].pop()
            order.append(u)
            remaining.remove(u)
            # update neighbors
            for v in neighbors[u]:
                if v in remaining:
                    d = deg[v]
                    buckets[d].remove(v)
                    deg[v] -= 1
                    buckets[deg[v]].append(v)
                    if deg[v] < ptr:
                        ptr = deg[v]
