    # Strategy 4: Articulation point based ordering (new per directive)
    def articulation_based():
        # Tarjan's algorithm for articulation points
        disc = [-1] * n
        low = [-1] * n
        parent = [-1] * n
        ap = [False] * n
        time = 0

        def dfs(u):
            nonlocal time
            children = 0
            disc[u] = low[u] = time
            time += 1
            for v in neighbors[u]:
                if disc[v] == -1:
                    parent[v] = u
                    children += 1
                    dfs(v)
                    low[u] = min(low[u], low[v])
                    if parent[u] == -1 and children > 1:
                        ap[u] = True
                    if parent[u] != -1 and low[v] >= disc[u]:
                        ap[u] = True
                elif v != parent[u]:
                    low[u] = min(low[u], disc[v])

        for i in range(n):
            if disc[i] == -1:
                dfs(i)

        # order: articulation points first (by degree descending), then others
        aps = [u for u in range(n) if ap[u]]
        non_aps = [u for u in range(n) if not ap[u]]
        aps.sort(key=lambda u: len(neighbors[u]), reverse=True)
        non_aps.sort(key=lambda u: len(neighbors[u]), reverse=True)
        order = aps + non_aps
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except: pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except: pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except: pass
    try:
        c4 = articulation_based()
        if is_valid(c4):
            candidates.append(c4)
    except: pass

    # If no candidates (shouldn't happen), fallback to greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda u: len(neighbors[u]), reverse=True)
        candidates.append(greedy_color(order))

    # Select best by number of colors
    best = min(candidates, key=count_colors)
    k = count_colors(best)

    # Kempe chain color reduction
    def kempe_reduce(col):
        nonlocal k
        changed = True
        while changed and k > 1:
            changed = False
            # find smallest color class
            classes = [[] for _ in range(k)]
            for u in range(n):
                classes[col[u]].append(u)
            # find smallest non-empty class
            target = -1
            min_size = n + 1
            for c in range(k):
                if classes[c] and len(classes[c]) < min_size:
                    min_size = len(classes[c])
                    target = c
            if target == -1 or min_size == 0:
                break
            # Try to recolor each vertex in target class
            for v in classes[target][:]:  # copy
                # try direct reassignment to a lower color
                free = 0
                for u in neighbors[v]:
                    if col[u] < k:  # only consider colors in use
                        free |= 1 << col[u]
                for c in range(target):
                    if not (free & (1 << c)):
                        # move v to color c
                        col[v] = c
                        changed = True
                        break
                if changed:
                    # rebuild classes and continue
                    classes = [[] for _ in range(k)]
                    for u in range(n):
                        classes[col[u]].append(u)
                    # update target class
                    if classes[target]:
                        target_class = classes[target]
                    else:
                        # target class eliminated, compact colors
                        mapping = {}
                        new_c = 0
                        for c in range(k):
                            if classes[c]:
                                mapping[c] = new_c
                                new_c += 1
                        for u in range(n):
                            col[u] = mapping[col[u]]
                        k = new_c
                        break
                    break  # restart while loop after any change
            if not changed:
                # try Kempe chains for each vertex in target class
                for v in classes[target][:]:
                    for c in range(target):
                        # check if v can be swapped via Kempe chain (target, c)
                        # only if v not adjacent to any vertex of color c
                        adjacent_to_c = False
                        for u in neighbors[v]:
                            if col[u] == c:
                                adjacent_to_c = True
                                break
                        if adjacent_to_c:
                            continue
                        # build Kempe chain component of v in colors {target, c}
                        stack = [v]
                        visited = set([v])
                        component = set()
                        while stack:
                            node = stack.pop()
                            component.add(node)
                            for nb in neighbors[node]:
                                if col[nb] == target or col[nb] == c:
                                    if nb not in visited:
