                        has_c_neighbor = False
                        for node in component:
                            for nb in neighbors[node]:
                                if col[nb] == c and nb not in component:
                                    has_c_neighbor = True
                                    break
                            if has_c_neighbor:
                                break
                        if not has_c_neighbor:
                            # swap colors target<->c in component
                            for node in component:
                                if col[node] == target:
                                    col[node] = c
                                else:
                                    col[node] = target
                            changed = True
                            # rebuild classes
                            classes = [[] for _ in range(k)]
                            for u in range(n):
                                classes[col[u]].append(u)
                            if not classes[target]:
                                # target class eliminated
                                mapping = {}
                                new_c = 0
                                for cc in range(k):
