        while c in used_colors:
            c += 1
        color[v] = c

    # Compact colors to ensure they are consecutive starting from 0
    # This step is actually not strictly necessary due to the greedy assignment above,
    # but we do it to guarantee the output format.
    unique_colors = sorted(set(color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    return color

