import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if binary
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build neighbor sets and bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    # Ensure symmetry (undirected)
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)
                bit_adj[j] |= (1 << i)
    # Helper: test coloring validity
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True
    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # Helper: convert coloring to list if needed
    # DSATUR
    def dsatur():
        coloring = [-1] * n
        # saturation: distinct neighbor colors
        saturation = [0] * n
        # neighbor color sets as bitmask for efficiency
        neighbor_colors = [0] * n
        # degrees for tie-breaking
        degrees = [len(neighbors[i]) for i in range(n)]
        # uncolored set
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v]
                deg = degrees[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            # update uncolored
            uncolored.remove(v)
            # update saturation and neighbor_colors for neighbors
            for u in neighbors[v]:
                if coloring[u] == -1:  # u uncolored
                    # if color c not yet in neighbor_colors[u], add it and increase saturation
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return coloring
    # RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # build maximal independent set for this color
            # degrees in induced subgraph of uncolored
            deg_uncolored = [0] * n
            for v in uncolored:
                cnt = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        cnt += 1
                deg_uncolored[v] = cnt
            # select vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            uncolored.remove(v)
            # partition: U = vertices not adjacent to S, W = adjacent to S
            U = set(uncolored)  # copy
            W = set()
            # move neighbors of v from U to W
            for u in list(U):
                if u in neighbors[v]:
                    U.remove(u)
                    W.add(u)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_u = -1
                for u in U:
                    # score = number of neighbors in W
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # tie-break: min degree in G[U]
                    deg_u = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or (score == best_score and deg_u == best_deg_u and random.random() < 0.5):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                # add u to S, remove from U, move its neighbors in U to W
                S.add(u)
                U.remove(u)
                for w in list(U):
                    if w in neighbors[u]:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
        return coloring
    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        # copy degrees
        deg = [len(neighbors[i]) for i in range(n)]
        # bin vertices by degree
        max_deg = max(deg) if n > 0 else 0
        bins = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg[v]
            if d < len(bins):
                bins[d].add(v)
            else:
                # extend bins if needed (should not happen)
                while len(bins) <= d:
                    bins.append(set())
                bins[d].add(v)
        # pointer to current min non-empty bin
        min_bin = 0
        order = []
        # we will remove vertices
        removed = [False] * n
        for _ in range(n):
            # find first non-empty bin
            while min_bin < len(bins) and not bins[min_bin]:
                min_bin += 1
            if min_bin >= len(bins):
                break  # should not happen
            v = bins[min_bin].pop()
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = deg[u]
                    # remove u from bin d
                    if d < len(bins) and u in bins[d]:
                        bins[d].remove(u)
                    deg[u] -= 1
                    dnew = deg[u]
                    # add to bin dnew
                    if dnew < len(bins):
                        bins[dnew].add(u)
                    else:
                        while len(bins) <= dnew:
                            bins.append(set())
                        bins[dnew].add(u)
                    # update min_bin if needed
                    if dnew < min_bin:
                        min_bin = dnew
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                c = coloring[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring
    # Kempe chain swap for colors a and b, starting from vertex v, returns new coloring if swap performed, else None
    def kempe_swap(coloring, v, a, b):
        if coloring[v] not in (a, b):
            return None  # should not happen
        # BFS to get component
        from collections import deque
        comp = []
        seen = set()
        q = deque([v])
        seen.add(v)
        while q:
            x = q.popleft()
            comp.append(x)
            for y in neighbors[x]:
                if y not in seen and coloring[y] in (a, b):
                    seen.add(y)
                    q.append(y)
        # swap colors in component
        new_coloring = coloring[:]  # copy
        for x in comp:
            if new_coloring[x] == a:
                new_coloring[x] = b
            else:
                new_coloring[x] = a
        return new_coloring
    # Try to eliminate a color class via Kempe or reassignment
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try from highest color down
        for target_color in range(k-1, 0, -1):
            # collect vertices with this color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            # try to recolor each target vertex
            made_change = False
            for v in target_vertices:
                # try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target_color):  # only lower colors
                    if not (used & (1 << c)):
                        # assign v to color c
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # attempt to swap (target_color, c) chain starting at v
                    new_col = kempe_swap(coloring, v, target_color, c)
                    if new_col is not None:
                        # check if after swap, v is no longer target_color (should be c)
                        if new_col[v] != target_color:
                            # accept swap
                            coloring[:] = new_col
                            made_change = True
                            break
                if made_change:
                    break
            if made_change:
                # after change, rebuild coloring and try again from same target_color (since we may have more)
                # but we break and restart outer loop to be safe
                break
        # if we made a change, recurse; else return
        if made_change:
            return reduce_colors(coloring)
        # compact colors: ensure colors are 0..k-1 without gaps
        # map existing colors to consecutive
        unique_colors = {}
        next_color = 0
        for v in range(n):
            c = coloring[v]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
        coloring = [unique_colors[c] for c in coloring]
        return coloring
    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass
    # Fallback: greedy Welsh-Powell (degree order)
    try:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = coloring[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        if is_valid(coloring):
            candidates.append(coloring)
    except Exception:
        pass
    # If no candidates, assign all zeros (invalid but fallback)
    if not candidates:
        coloring = [0] * n
        candidates.append(coloring)
    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: num_colors(x))
    # Apply Kempe reduction iteratively
    best = reduce_colors(best)
    # Final validation (should hold)
    if not is_valid(best):
        # as last resort, return DSATUR if valid else all zeros
        if is_valid(c1):
            return c1
        else:
            return [0] * n
    return best

import math
