def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build neighbor bitmasks and degree list
    bit_adj = [0] * n
    deg = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
                    deg[i] += 1
    else:
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)
                deg[i] += 1

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            nbrs = bit_adj[v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                if colors[u] != -1:
                    used |= (1 << colors[u])
                nbrs &= nbrs - 1
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: count colors used
    def count_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            c_u = colors[u]
            nbrs = bit_adj[u]
            while nbrs:
                v = (nbrs & -nbrs).bit_length() - 1
                if colors[v] == c_u:
                    return False
                nbrs &= nbrs - 1
        return True

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree
            cand = -1
            max_sat = -1
            max_deg = -1
            for v in uncolored:
                sat = saturated[v]
                if sat > max_sat or (sat == max_sat and deg[v] > max_deg):
                    max_sat = sat
                    max_deg = deg[v]
                    cand = v
                elif sat == max_sat and deg[v] == max_deg and v < cand:
                    cand = v
            v = cand
            # Assign smallest available color
            used = 0
            nbrs = bit_adj[v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                if colors[u] != -1:
                    used |= (1 << colors[u])
                nbrs &= nbrs - 1
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            nbrs = bit_adj[v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                if colors[u] == -1:
                    saturated[u] += 1
                nbrs &= nbrs - 1
        return colors

    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj[x] if y in uncolored) if not is_matrix else bin(bit_adj[x] & sum((1 << y) for y in uncolored)).count('1'))
            independent_set = {v}
            to_check = set(uncolored) - {v}
            # Partition: U (not adjacent to S), W (adjacent to S)
            W = set()
            for u in to_check:
                if is_matrix:
                    if bit_adj[u] & (1 << v):
                        W.add(u)
                else:
                    if v in adj[u]:
                        W.add(u)
            U = to_check - W
            # Greedily add from U
            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = 0
                    if is_matrix:
                        w_neighbors = bin(bit_adj[u] & sum((1 << w) for w in W)).count('1')
                    else:
                        w_neighbors = sum(1 for w in adj[u] if w in W)
                    deg_in_U = sum(1 for y in adj[u] if y in U) if not is_matrix else bin(bit_adj[u] & sum((1 << y) for y in U)).count('1')
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                    elif w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and u < best_u:
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = set()
                if is_matrix:
                    for y in range(n):
                        if bit_adj[u] & (1 << y):
                            nbrs_u.add(y)
                else:
                    nbrs_u = set(adj[u])
                for y in nbrs_u:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color to independent set
            for v in independent_set:
                colors[v] = color
                uncolored.remove(v)
            color += 1
        return colors

    # Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        deg_copy = deg[:]
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg_copy[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            nbrs = bit_adj[v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                if u in remaining:
                    d = deg_copy[u]
                    buckets[d].remove(u)
                    deg_copy[u] -= 1
                    buckets[deg_copy[u]].append(u)
                nbrs &= nbrs - 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best_colors = None
    best_k = float('inf')
    for col in candidates:
        if is_valid(col):
            k = count_colors(col)
            if k < best_k:
                best_k = k
                best_colors = col[:]

    # If no valid candidate (should not happen), fallback to greedy by degree
    if best_colors is None:
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        best_colors = greedy_color(order)
        best_k = count_colors(best_colors)

    # Try to reduce colors via Kempe chain swaps
    def kempe_reduce(colors, target_k):
        # Try to eliminate color target_k-1
        color_class = [v for v in range(n) if colors[v] == target_k - 1]
        if not color_class:
            return target_k - 1  # already eliminated
        # Try to recolor each vertex in the class
        for v in color_class:
            forbidden = 0
            nbrs = bit_adj[v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                if colors[u] != -1:
                    forbidden |= (1 << colors[u])
                nbrs &= nbrs - 1
            # Try direct reassignment to a lower color
            for c in range(target_k - 1):
                if not (forbidden & (1 << c)):
                    colors[v] = c
                    break
            else:
                # Try Kempe chain swap with each lower color
                for c in range(target_k - 1):
                    if forbidden & (1 << c):
                        continue  # adjacent to color c, swap may not help
                    # Build (c, target_k-1)-Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if colors[node] == c or colors[node] == target_k - 1:
                            component.add(node)
                            nbrs_node = bit_adj[node]
                            while nbrs_node:
                                nb = (nbrs_node & -nbrs_node).bit_length() - 1
                                if nb not in visited:
                                    stack.append(nb)
                                nbrs_node &= nbrs_node - 1
                    # Check if swapping this component frees color c for v
                    # After swap, v would get color c if it's in the component
                    if v in component:
                        # Perform swap: c <-> target_k-1 in component
                        for node in component:
                            if colors[node] == c:
                                colors[node] = target_k - 1
                            elif colors[node] == target_k - 1:
                                colors[node] = c
                        # Now v has color c
                        break
                else:
                    continue  # no break in Kempe loop
                break  # break from direct reassignment loop if we reassigned
            else:
                # Could not recolor v, continue to next vertex
                continue
            # If we reassigned v, check if color class is now empty
            new_color_class = [x for x in range(n) if colors[x] == target_k - 1]
            if not new_color_class:
                return target_k - 1
        # If we couldn't eliminate the color class, return current k
        return target_k

    # Apply iterative Kempe reduction
    k = best_k
    while k > 1:
        new_k = kempe_reduce(best_colors[:], k)  # work on a copy
        if new_k < k:
            k = new_k
            # Compact colors: remap to 0..k-1
            color_map = {}
            next_color = 0
            for v in range(n):
