                    #   For all neighbors u of v:
                    #       if u in comp: then original color[u] != c  (because after flip it becomes target_color, which is not c since c != target_color)
                    #       if u not in comp: then original color[u] != c
                    # But wait: if u in comp and original color[u] == c, after swap it becomes target_color -> not c, so ok.
                    # If u in comp and original color[u] == target_color, after swap it becomes c -> conflict because v is also c.
                    # Therefore, we must have: no neighbor u of v in the component has original color target_color.
                    # Equivalent: the component contains no neighbor of v that is colored target_color.
                    has_target_color_neighbor = False
                    for u in adj_list[v]:
                        if u in comp and colors[u] == target_color:
                            has_target_color_neighbor = True
                            break
                    if not has_target_color_neighbor:
                        # perform swap
                        for x in comp:
                            if colors[x] == c:
                                colors[x] = target_color
                            else:  # must be target_color
                                colors[x] = c
                        improved = True
                        break
                if improved:
