            if improved:
                # compact colors again
                colors = compact_colors(colors)
                k = max(colors) + 1 if n > 0 else 0
            else:
                break
        return colors

    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid_coloring(best):
        # Should not happen, but fallback
        best = list(range(n))
    best = compact_colors(best)
    return best

