    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute degrees
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    deg = [len(adj_list[i]) for i in range(n)]

    # Helper function to compute coloring using DSATUR heuristic
    def dsatur():
        color = [-1] * n
        # Saturation sets: track distinct colors in neighbors for each vertex
        sat_sets = [set() for _ in range(n)]
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation degree, tie-break by degree in uncolored subgraph, then random
            v = max(uncolored, key=lambda x: (len(sat_sets[x]), deg[x], random.random()))
            # Find smallest available color (mex)
            used = sat_sets[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation sets of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat_sets[u].add(c)
        return color

    # Helper function to compute coloring using RLF heuristic
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sum(1 for nb in adj_list[x] if nb in uncolored), random.random()))
            S.add(v)
            uncolored.remove(v)
            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = {u for u in uncolored if all(nb not in S for nb in adj_list[u])}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U subgraph
                u = max(U, key=lambda x: (sum(1 for nb in adj_list[x] if nb in W), -sum(1 for nb in adj_list[x] if nb in U), random.random()))
                S.add(u)
                U.remove(u)
                # Update U and W: move neighbors of u in U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to all vertices in S
            for v in S:
                color[v] = c
            c += 1
        return color

    # Helper function to compute coloring using Smallest-Last (degeneracy) ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering (smallest-last)
        deg_copy = deg[:]
        removed = [False] * n
        order = []  # removal order
        # Use buckets for efficiency (max degree <= n-1)
        max_deg = n - 1
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg_copy[v]
            if d <= max_deg:
                buckets[d].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = deg_copy[u]
                    if d <= max_deg:
                        # Remove u from bucket d
                        if u in buckets[d]:
                            buckets[d].remove(u)
                        d -= 1
                        deg_copy[u] = d
                        if d <= max_deg:
                            buckets[d].append(u)
        # Color in reverse removal order using greedy (first-fit)
        color = [-1] * n
        for v in reversed(order):
            used = set()
            for u in adj_list[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

