    best_color = None
    best_k = float('inf')
    for col in candidates:
        k = len(set(col)) if col else 0
        if k < best_k:
            best_k = k
            best_color = col

    # Kempe chain color reduction
    def kempe_reduction(color_in):
        # Work on a copy
        color = color_in[:]
        changed = True
        while changed:
            changed = False
            # Determine current color classes
            if not color:
                return color
            max_color = max(color)
            color_classes = [[] for _ in range(max_color + 1)]
            for v in range(n):
                color_classes[color[v]].append(v)
            # Try to eliminate the last color class (max_color) if it's the smallest
            target_color = max_color
            if not color_classes[target_color]:
                # Already empty, should not happen but skip
                return color
            # Check if we can recolor each vertex in target_color to a lower color
            for v in color_classes[target_color]:
                used_by_neighbors = set()
                for u in adj_list[v]:
                    if color[u] < target_color:
                        used_by_neighbors.add(color[u])
                # Find smallest available color < target_color
                c = 0
                while c < target_color:
                    if c not in used_by_neighbors:
                        break
                    c += 1
                if c < target_color:
                    # Direct reassignment possible
                    color[v] = c
                    changed = True
                    # Move v from target_color to c
                    color_classes[target_color].remove(v)
                    color_classes[c].append(v)
                    # If target_color becomes empty, break to restart
                    if not color_classes[target_color]:
                        break
                    else:
                        # Continue to next vertex in target_color (list may have changed, but we break and restart anyway)
                        break
            if not color_classes[target_color]:
                # Successfully emptied target_color, compact colors
                changed = True
                # Build mapping from old colors to new compacted colors
                mapping = {}
                new_c = 0
                for old_c in range(max_color + 1):
                    if color_classes[old_c]:
                        mapping[old_c] = new_c
                        new_c += 1
                # Recolor all vertices
                for v in range(n):
                    color[v] = mapping[color[v]]
                # Continue to see if we can reduce further
            else:
                # Try Kempe chains for each vertex in target_color
                for v in color_classes[target_color]:
                    found = False
                    # Try each color c < target_color
                    for c in range(target_color):
                        # Skip if color c is used by a neighbor of v (direct move not possible)
                        if any(color[u] == c for u in adj_list[v]):
                            continue
                        # Build the (c, target_color)-Kempe chain containing v
                        # We'll do BFS to find the component
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for nb in adj_list[node]:
                                if not visited[nb] and (color[nb] == c or color[nb] == target_color):
                                    visited[nb] = True
                                    queue.append(nb)
                        # Check if any neighbor of v has color c (should not, by above check, but double-check)
                        has_c_neighbor = any(color[nb] == c for nb in adj_list[v])
                        if not has_c_neighbor:
                            # Swap colors c and target_color in the component
                            for node in component:
                                if color[node] == c:
                                    color[node] = target_color
                                elif color[node] == target_color:
                                    color[node] = c
                            changed = True
                            found = True
                            # Update color_classes (we'll break and restart outer loop)
                            break
                    if found:
                        break
                # If we made a change, break to restart the while loop
                if changed:
                    break
        return color

    # Apply Kempe reduction to the best candidate
    best_color = kempe_reduction(best_color)

    # Final validation and compacting (ensure colors are 0..k-1)
    if not best_color:
        return best_color
    # Verify it's a proper coloring
    for u in range(n):
        for v in adj_list[u]:
            if best_color[u] == best_color[v]:
                # Fallback: if invalid, use DSATUR (should not happen)
                return dsatur()
    # Compact colors
    unique_colors = sorted(set(best_color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best_color = [mapping[c] for c in best_color]

    return best_color

