    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)
                neighbors[i].append(j)

