    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

