            for v in uncolored:
                if sat[v] > best_sat or (sat[v] == best_sat and len([u for u in nbrs[v] if u in uncolored]) > best_deg):
                    best_sat = sat[v]
                    best_deg = len([u for u in nbrs[v] if u in uncolored])
                    best_v = v
                elif sat[v] == best_sat and len([u for u in nbrs[v] if u in uncolored]) == best_deg:
                    if best_v == -1 or v < best_v:
                        best_v = v
            v = best_v
            # Assign smallest available color
            used = 0
            for u in nbrs[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            colored[v] = True
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in nbrs[v]:
                if not colored[u]:
                    # Check if color c is new in u's neighborhood
                    has = False
                    for w in nbrs[u]:
                        if color[w] == c:
                            has = True
                            break
                    if not has:
                        sat[u] += 1
