    # Candidate 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        nbrs = neighbors
        while uncolored:
            # Build maximal independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in nbrs[x] if y in uncolored]))
            S.add(v)
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = {u for u in uncolored if u not in S and all(w not in S for w in nbrs[u])}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg = -1
                for u in U:
                    score = len([w for w in nbrs[u] if w in W])
                    deg_u = len([w for w in nbrs[u] if w in U])
                    if score > best_score or (score == best_score and deg_u < best_deg):
                        best_score = score
                        best_deg = deg_u
                        best_u = u
                    elif score == best_score and deg_u == best_deg:
                        if best_u == -1 or u < best_u:
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in nbrs[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
