    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal k
        # Make coloring consecutive
        # Map colors to 0..k-1
        unique = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            coloring[i] = unique[c]
        k = next_color
        # Try to eliminate color classes from high to low
        improved = True
        while improved and k > 0:
            improved = False
            # Target smallest color class (highest index)
            target = k - 1
            # Count vertices in target class
            target_vertices = [v for v in range(n) if coloring[v] == target]
            if not target_vertices:
                # Already empty, compact
                for v in range(n):
                    if coloring[v] > target:
                        coloring[v] -= 1
                k -= 1
                improved = True
                continue
            # Try to recolor each vertex in target class
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
