                        coloring[v] = c
                        # Check if target class is now empty
                        if not any(coloring[u] == target for u in range(n)):
                            # Compact colors
                            for u in range(n):
                                if coloring[u] > target:
                                    coloring[u] -= 1
                            k -= 1
