                    conflict = False
                    for u in neighbors[v]:
                        if not visited[u] and coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target
                            else:
                                coloring[x] = c
                        # Now v has color c
                        # Check if target class is empty
                        if not any(coloring[u] == target for u in range(n)):
                            for u in range(n):
                                if coloring[u] > target:
                                    coloring[u] -= 1
                            k -= 1
                        improved = True
                        break
                if improved:
