    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([u for u in neighbors[x] if u in uncolored])))
            # Find smallest available color
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            S.add(v)
            # Partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = max(U, key=lambda x: sum(1 for w in neighbors[x] if w in W))
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering (smallest-last)
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # Use bucket sort for efficiency
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].add(v)
        # Pointer to current min degree
        d = 0
        while remaining:
            # Find non-empty bucket
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = deg[u]
                    deg[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].discard(u)
                    if deg[u] <= max_deg:
                        buckets[deg[u]].add(u)
                    if deg[u] < d:
                        d = deg[u]
        # Color in reverse order using first-fit
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(color):
        # Helper: get vertices of a given color
        def color_class(c):
            return [i for i in range(n) if color[i] == c]

        # Helper: check if coloring is valid
        def is_valid():
            for u in range(n):
                for v in neighbors[u]:
                    if u < v and color[u] == color[v]:
                        return False
            return True

        # Helper: get Kempe chain component for colors a,b starting from v
        def kempe_component(v, a, b):
            if color[v] not in (a, b):
                return set()
            stack = [v]
            comp = set()
            while stack:
                node = stack.pop()
                if node in comp:
                    continue
                if color[node] not in (a, b):
                    continue
                comp.add(node)
                for nb in neighbors[node]:
                    if nb not in comp and color[nb] in (a, b):
                        stack.append(nb)
            return comp

        changed = True
        while changed:
            changed = False
            # Find current number of colors
            max_color = max(color) if n > 0 else -1
            if max_color < 0:
                break
            # Try to eliminate color classes from highest to lowest
            for target_color in range(max_color, -1, -1):
                cls = color_class(target_color)
                if not cls:
                    continue
                # Try to recolor each vertex in the class
                for v in cls[:]:  # iterate over copy
                    # Try direct reassignment to a lower color
                    for c in range(target_color):
                        conflict = False
                        for u in neighbors[v]:
                            if color[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            color[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chain swap
                    for c in range(target_color):
                        comp = kempe_component(v, target_color, c)
                        # Check if swapping would not introduce conflict
                        safe = True
                        for node in comp:
                            for u in neighbors[node]:
                                if color[u] == c and node not in comp:
                                    safe = False
                                    break
                            if not safe:
                                break
                        if safe:
                            # Perform swap
                            for node in comp:
                                color[node] = c if color[node] == target_color else target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    # Compact colors if highest color class is empty
                    max_color = max(color) if n > 0 else -1
                    if max_color >= 0 and not color_class(max_color):
                        # Remap colors to 0..max_color-1
                        mapping = {}
                        for c in range(max_color + 1):
                            if color_class(c):
                                mapping[c] = len(mapping)
                        for i in range(n):
                            if color[i] in mapping:
                                color[i] = mapping[color[i]]
                    break
        return color

    # Generate candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best = None
    best_colors = float('inf')
    for col in candidates:
        # Validate
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if u < v and col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        unique_colors = len(set(col))
        if unique_colors < best_colors:
            best_colors = unique_colors
            best = col

    # Fallback: if no candidate valid, use DSATUR (should be valid)
    if best is None:
        best = dsatur()

    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)

    # Final validation and compact colors
    # Ensure colors are consecutive starting from 0
    mapping = {}
    next_color = 0
    for c in sorted(set(best)):
        mapping[c] = next_color
        next_color += 1
    for i in range(n):
        best[i] = mapping[best[i]]

    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue  # ignore invalid indices
                adj_list[i].append(j)
                bit_adj[i] |= (1 << j)

    # Helper: count bits
    def popcount(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            cu = colors[u]
            for v in adj_list[u]:
                if cu == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: normalize colors to 0..k-1
    def normalize(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # degrees in the whole graph
        degrees = [len(adj_list[i]) for i in range(n)]
        # saturation sets: bitmask of colors used by neighbors
        sat = [0] * n
        # colored neighbor count not needed directly
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] != -1:
                    continue
                sat_u = popcount(sat[u])
                deg_u = degrees[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            if v == -1:
                break  # should not happen
            # find smallest color not used by neighbors
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            # update saturation of neighbors
            for nb in adj_list[v]:
                if colors[nb] == -1:
                    sat[nb] |= (1 << c)
        return normalize(colors)

    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        # uncolored set as bitmask
        R = (1 << n) - 1
        while R:
            # build independent set S for this color
            S = 0
            # choose first vertex: max degree in G[R]
            v = -1
            max_deg = -1
            # iterate over vertices in R
            temp = R
            while temp:
                lsb = temp & -temp
                u = (lsb.bit_length() - 1)
                # degree in G[R]: neighbors that are in R
                deg_in_R = popcount(bit_adj[u] & R)
                if deg_in_R > max_deg:
                    max_deg = deg_in_R
                    v = u
                temp ^= lsb
            if v == -1:
                break  # no vertices left? should not happen
            S |= (1 << v)
            # U: vertices in R not adjacent to any in S (eligible)
            # W: vertices in R adjacent to S (ineligible)
            U = R & ~(bit_adj[v])  # not adjacent to v
            W = R & bit_adj[v]     # adjacent to v
            # remove v from R
            R &= ~(1 << v)
            # expand S
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_nw = -1
                min_deg_U = -1
                temp = U
                while temp:
                    lsb = temp & -temp
                    u = (lsb.bit_length() - 1)
                    nw = popcount(bit_adj[u] & W)
                    deg_in_U = popcount(bit_adj[u] & U)
                    if nw > max_nw or (nw == max_nw and deg_in_U < min_deg_U) or \
                       (nw == max_nw and deg_in_U == min_deg_U and (best_u == -1 or random.random() < 0.5)):
                        max_nw = nw
                        min_deg_U = deg_in_U
                        best_u = u
                    temp ^= lsb
                if best_u == -1:
                    break  # should not happen
                # add best_u to S
                S |= (1 << best_u)
                # move best_u from U to W? Actually remove from U, add its neighbors to W
                U &= ~(1 << best_u)
                # neighbors of best_u that are in U become ineligible (move to W)
                newly_W = bit_adj[best_u] & U
                W |= newly_W
                U &= ~newly_W
                # also remove best_u from R
                R &= ~(1 << best_u)
            # assign color to all in S
            temp = S
            while temp:
                lsb = temp & -temp
                u = (lsb.bit_length() - 1)
                colors[u] = color
                temp ^= lsb
            color += 1
        return normalize(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering: repeatedly remove min degree vertex
        # we work on a copy of degrees
        deg = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []  # will store removal order
        # bucket sort by degree for efficiency
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            while removed[v]:
                if not buckets[ptr]:
                    break
                v = buckets[ptr].pop()
            if removed[v]:
                # find another
                found = False
                for d in range(max_deg + 1):
                    while buckets[d]:
                        cand = buckets[d].pop()
                        if not removed[cand]:
                            v = cand
                            found = True
                            break
                    if found:
                        break
                if not found:
                    break
            removed[v] = True
            order.append(v)
            # update neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    d = deg[nb]
                    # remove from bucket
                    if deg[nb] < len(buckets):
                        buckets[deg[nb]].remove(nb)  # O(n) but n <= 100
                    deg[nb] -= 1
                    if deg[nb] >= 0:
                        buckets[deg[nb]].append(nb)
                    else:
                        deg[nb] = 0
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return normalize(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # make a copy we can modify
        cur = colors[:]
        improved = True
        # try to reduce from highest color down
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # vertices with target color
            targets = [v for v in range(n) if cur[v] == target_color]
            if not targets:
                k -= 1
                continue
            # try to recolor each target vertex
            for v in targets:
                # try direct reassignment to a lower color
                used = 0
                for nb in adj_list[v]:
                    if cur[nb] != -1:
                        used |= (1 << cur[nb])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # can recolor directly
                        cur[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already recolored, break
                    if cur[v] != target_color:
                        break
                # Actually, we need to check for each c separately
                # We'll do it in the loop
                for c in range(target_color):
                    if cur[v] != target_color:
                        break
                    # find the Kempe chain component of v in colors {c, target_color}
                    # BFS/DFS
                    from collections import deque
                    comp = []
                    visited = [False] * n
                    q = deque([v])
                    visited[v] = True
                    while q:
                        u = q.popleft()
                        comp.append(u)
                        for nb in adj_list[u]:
                            if not visited[nb] and (cur[nb] == c or cur[nb] == target_color):
                                visited[nb] = True
                                q.append(nb)
                    # check if any neighbor of the component has color c (which would cause conflict if we swap)
                    has_c_neighbor = False
                    for u in comp:
                        for nb in adj_list[u]:
                            if cur[nb] == c and nb not in comp:  # neighbor outside component with color c
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            break
                    if not has_c_neighbor:
                        # swap colors c and target_color in component
                        for u in comp:
                            if cur[u] == c:
                                cur[u] = target_color
                            elif cur[u] == target_color:
                                cur[u] = c
                        improved = True
                        break
            if not improved:
                # cannot reduce further
                break
            # recompute k and normalize if any color changed
            k = num_colors(cur)
            # compact colors if needed (though kempe should preserve set)
            # but we do it at the end
        return normalize(cur)

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            cols = func()
            if not is_valid_coloring(cols):
                continue
            k = num_colors(cols)
            if k < best_k:
                best_k = k
                best_colors = cols
        except Exception:
            continue

    # If none worked, fall back to greedy
    if best_colors is None:
        # simple greedy: order by degree descending
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = normalize(colors)

    # Apply Kempe reduction to try to improve
    try:
        reduced = kempe_reduce(best_colors)
        if is_valid_coloring(reduced):
            k_red = num_colors(reduced)
            if k_red < num_colors(best_colors):
                best_colors = reduced
    except Exception:
        pass

    return best_colors

