def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = True
    if len(adj) == 0 or len(adj[0]) != len(adj):
        is_matrix = False
    else:
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build neighbor bitmasks
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for nb in adj[i]:
                bit_adj[i] |= (1 << nb)
    # Helper functions
    def count_bits(x: int) -> int:
        return x.bit_count()
    def get_neighbors(v: int) -> int:
        return bit_adj[v]
    # DSATUR
    def dsatur() -> list[int]:
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Order by degree descending for tie-breaking
        degree = [count_bits(get_neighbors(v)) for v in range(n)]
        while uncolored:
            # Select vertex with max saturation, tie-break by degree then index
            v = max(uncolored, key=lambda x: (sat[x], degree[x], x))
            # Find smallest available color
            neighbor_colors = 0
            nb = get_neighbors(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                c = color[w]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            nb = get_neighbors(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                if color[w] == -1:
                    sat[w] += 1
        return color
    # RLF
    def rlf() -> list[int]:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: count_bits(get_neighbors(x) & sum((1 << u) for u in uncolored)))
            S.add(v)
            # Partition U and W
            U = uncolored - {v}
            W = set()
            # Remove neighbors of v from U
            nb = get_neighbors(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                if w in U:
                    U.remove(w)
                    W.add(w)
            while U:
                # Select u in U with max neighbors in W
                def score(u):
                    return count_bits(get_neighbors(u) & sum((1 << w) for w in W))
                # Tie-break by min degree in U
                u = max(U, key=lambda x: (score(x), -count_bits(get_neighbors(x) & sum((1 << y) for y in U)), x))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nb = get_neighbors(u)
                while nb:
                    w = (nb & -nb).bit_length() - 1
                    nb &= nb - 1
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to S
            for v in S:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color
    # Smallest-Last (degeneracy ordering)
    def smallest_last() -> list[int]:
        if n == 0:
            return []
        # Compute degeneracy ordering via min-degree removal
        degree = [count_bits(get_neighbors(v)) for v in range(n)]
        removed = [False] * n
        order = []
        # Use buckets for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            nb = get_neighbors(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                if not removed[w]:
                    d = degree[w]
                    if d > 0:
                        degree[w] = d - 1
                        buckets[d].remove(w)
                        buckets[d-1].append(w)
                        if d-1 < ptr:
                            ptr = d-1
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            nb = get_neighbors(v)
            while nb:
                w = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                c = color[w]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color[v] = c
        return color
    # Kempe chain swap
    def kempe_swap(color: list[int], a: int, b: int, v: int) -> bool:
        # Returns True if swap performed and color of v changed from a to b
        if color[v] != a:
            return False
        # BFS to get Kempe chain component of v for colors a,b
        from collections import deque
        comp = []
        seen = set()
        q = deque([v])
        seen.add(v)
        while q:
            u = q.popleft()
            comp.append(u)
            # Neighbors with color a or b
            nb = get_neighbors(u)
            while nb:
                w = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                if color[w] == a or color[w] == b:
                    if w not in seen:
                        seen.add(w)
                        q.append(w)
        # Check if any neighbor of component has color b (would cause conflict if swapped)
        conflict = False
        for u in comp:
            nb = get_neighbors(u)
            while nb:
                w = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                if color[w] == b and w not in comp:
                    conflict = True
                    break
            if conflict:
                break
        if conflict:
            return False
        # Perform swap
        for u in comp:
            if color[u] == a:
                color[u] = b
            else:
                color[u] = a
        return True
    # Color reduction via Kempe chains
    def reduce_colors(color: list[int]) -> list[int]:
        if n == 0:
            return color
        # Map colors to compact range
        unique_colors = sorted(set(color))
        if len(unique_colors) == 0:
            return color
        mapping = {c: i for i, c in enumerate(unique_colors)}
        color = [mapping[c] for c in color]
        k = len(unique_colors)
        improved = True
        while improved and k > 1:
            improved = False
            # Target smallest color class (color 0 after mapping)
            target = 0
            # Get vertices with target color
            target_vertices = [v for v in range(n) if color[v] == target]
            if not target_vertices:
                # Should not happen
                break
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color (none, since target is 0)
                # Try Kempe swap with each higher color
                for c in range(1, k):
                    if kempe_swap(color, target, c, v):
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # Recompact colors
                unique_colors = sorted(set(color))
                mapping = {c: i for i, c in enumerate(unique_colors)}
                color = [mapping[c] for c in color]
                k = len(unique_colors)
            else:
                break
        return color
    # Generate candidates
    start = time.perf_counter()
    candidates = []
    # DSATUR
    col_dsatur = dsatur()
    if time.perf_counter() - start < 0.05:
        candidates.append(col_dsatur)
    # RLF
    col_rlf = rlf()
    if time.perf_counter() - start < 0.05:
        candidates.append(col_rlf)
    # Smallest-Last
    col_sl = smallest_last()
    if time.perf_counter() - start < 0.05:
        candidates.append(col_sl)
    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate
        valid = True
        for u in range(n):
            nb = get_neighbors(u)
            while nb:
                v = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                if color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = len(set(col))
        if k < best_k:
            best_k = k
            best_color = col
    # Fallback: if no candidate valid, use DSATUR (should be valid)
    if best_color is None:
        best_color = col_dsatur
    # Apply Kempe reduction
    best_color = reduce_colors(best_color)
    # Ensure zero-based consecutive
    unique_colors = sorted(set(best_color))
    mapping = {c: i for i, c in enumerate(unique_colors)}
    best_color = [mapping[c] for c in best_color]
    return best_color

