def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list if needed
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in graph[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: Kempe chain swap for colors a and b starting from vertex v
    def kempe_swap(color, a, b, v):
        if color[v] not in (a, b):
            return False
        stack = [v]
        visited = [False] * n
        visited[v] = True
        component = []
        while stack:
            node = stack.pop()
            component.append(node)
            for nb in graph[node]:
                if not visited[nb] and color[nb] in (a, b):
                    visited[nb] = True
                    stack.append(nb)
        # Swap colors in component
        for node in component:
            if color[node] == a:
                color[node] = b
            else:
                color[node] = a
        return True

    # Helper: try to eliminate color 'target' using Kempe chains
    def eliminate_color(color, target):
        # Map colors to vertices
        color_classes = [[] for _ in range(max(color) + 1)]
        for v in range(n):
            color_classes[color[v]].append(v)
        if target >= len(color_classes) or not color_classes[target]:
            return color  # nothing to eliminate

        # Try to recolor each vertex in target class
        for v in color_classes[target][:]:
            if color[v] != target:  # might have been recolored already
                continue
            # Try direct reassignment to a lower color
            for c in range(target):
                conflict = False
                for u in graph[v]:
                    if color[u] == c:
                        conflict = True
                        break
                if not conflict:
                    color[v] = c
                    break
            else:
                # Try Kempe chain with each lower color
                for c in range(target):
                    # Temporarily swap along Kempe chain (c, target) from v
                    # We simulate by checking if v can reach a vertex not colored c via alternating path
                    # Actually, we do the swap and check if it helps
                    # Make a copy to test
                    color_copy = color[:]
                    if kempe_swap(color_copy, c, target, v):
                        # After swap, check if v is no longer target color
                        if color_copy[v] != target:
                            # Accept the swap
                            for i in range(n):
                                color[i] = color_copy[i]
                            break
                else:
                    continue  # no Kempe swap worked for this v
                break  # if we broke out of Kempe loop, we recolored v
            else:
                continue  # direct reassignment didn't work, try next v
            break  # if we recolored v, break to restart scanning
        else:
            # No vertex in target class could be recolored
            return color

        # Recurse to try eliminating the same target again (now possibly smaller)
        return eliminate_color(color, target)

    # Main: Independent Set Extraction (RLF-style)
    def rlf_coloring():
        color = [-1] * n
        current_color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build independent set S for current_color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for nb in graph[x] if nb in uncolored))
                S.append(v)
                uncolored.remove(v)
                # Set of vertices adjacent to S (cannot take this color)
                adj_S = set()
                for u in S:
                    for nb in graph[u]:
                        if nb in uncolored:
                            adj_S.add(nb)
                # Candidates: uncolored and not adjacent to S
                candidates = uncolored - adj_S
                while candidates:
                    # Select u in candidates with max neighbors in adj_S
                    u = max(candidates, key=lambda x: sum(1 for nb in graph[x] if nb in adj_S))
                    S.append(u)
                    uncolored.remove(u)
                    # Update adj_S and candidates
                    for nb in graph[u]:
                        if nb in uncolored:
                            adj_S.add(nb)
                    candidates = uncolored - adj_S
            # Assign color to all in S
            for v in S:
                color[v] = current_color
            current_color += 1
        return color

    # Generate candidates: RLF, DSATUR, and degree ordering
    candidates = []

    # 1. RLF
    try:
        col_rlf = rlf_coloring()
        candidates.append(col_rlf)
    except:
        pass

    # 2. DSATUR with bitmask-like optimization using sets
    def dsatur():
        color = [-1] * n
        # saturation sets: for each vertex, set of colors used by colored neighbors
        sat = [set() for _ in range(n)]
        # degree in uncolored subgraph
        deg = [len(graph[v]) for v in range(n)]
        uncolored = set(range(n))
        while uncolored:
            # select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (len(sat[x]), deg[x], random.random()))
            # find smallest available color
            used = sat[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in graph[v]:
                if u in uncolored:
                    sat[u].add(c)
                    deg[u] -= 1
        return color
    try:
        col_ds = dsatur()
        candidates.append(col_ds)
    except:
        pass

    # 3. Degree ordering (largest first)
    order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
    col_deg = greedy_color(order)
    candidates.append(col_deg)

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # validate
        valid = True
        for u in range(n):
            for v in graph[u]:
                if color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col[:]

    if best_color is None:
        # fallback to greedy
        best_color = greedy_color(list(range(n)))

    # Try to reduce colors by eliminating the largest color index
    changed = True
    while changed and best_color:
        k = max(best_color) + 1
        if k <= 1:
            break
        target = k - 1
        new_color = eliminate_color(best_color[:], target)
        # validate new_color
        valid = True
        for u in range(n):
            for v in graph[u]:
                if new_color[u] == new_color[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            # compact colors: remap to 0..k'-1
            mapping = {}
            next_c = 0
            for v in range(n):
                c = new_color[v]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                new_color[v] = mapping[c]
            best_color = new_color
            changed = True
        else:
            changed = False

    return best_color

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
