    # Strategy 1: BFS-based bipartite extraction + conflict resolution
    def bfs_bipartite_then_resolve():
        color = [-1] * n
        from collections import deque
        q = deque()
        # Start BFS from node 0
        color[0] = 0
        q.append(0)
        while q:
            u = q.popleft()
            for v in adj_list[u]:
                if color[v] == -1:
                    color[v] = color[u] ^ 1
                    q.append(v)
                elif color[v] == color[u]:
