        # Now, we have a 2-coloring where some edges are monochromatic (conflicts)
        # We will try to recolor to fix conflicts using additional colors
        # Collect all vertices involved in conflicts
        conflict_vertices = set()
        for u in range(n):
            for v in adj_list[u]:
                if u < v and color[u] == color[v]:
                    conflict_vertices.add(u)
                    conflict_vertices.add(v)
        # If no conflicts, we are done (bipartite)
        if not conflict_vertices:
            return color
        # Try to assign a third color to some vertices to break conflicts
        # We'll use a simple greedy approach on the conflict subgraph
        # Order conflict vertices by degree in the conflict subgraph
        conflict_list = list(conflict_vertices)
        # Build conflict subgraph adjacency
        conflict_adj = {u: [] for u in conflict_list}
        for u in conflict_list:
