            u = selected
            # Find smallest color not in saturation[u]
            c = 0
            while saturation[u] & (1 << c):
                c += 1
            colors[u] = c
            uncolored.remove(u)
            # Update neighbors
            for v in adj_list[u]:
                if v in uncolored:
                    saturation[v] |= (1 << c)
                    uncolored_deg[v] -= 1
