    # Strategy 3: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        while uncolored:
            # Build maximal independent set for this color
            # Step 1: pick vertex with max degree in G[uncolored]
            if not uncolored:
                break
            # Compute degrees in uncolored subgraph
            deg_in_uncolored = {}
            for u in uncolored:
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg_in_uncolored[u] = cnt
            # Select vertex with max degree
            max_deg = -1
            v0 = None
            for u in uncolored:
                if deg_in_uncolored[u] > max_deg:
                    max_deg = deg_in_uncolored[u]
                    v0 = u
            if v0 is None:
                v0 = next(iter(uncolored))
            S = {v0}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v0:
                    continue
                adjacent_to_S = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = 0
                    for v in adj_list[u]:
                        if v in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break by min degree in G[U]
                        deg_u = sum(1 for v in adj_list[u] if v in U)
                        deg_best = sum(1 for v in adj_list[best_u] if v in U) if best_u is not None else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u that are in U to W
                for v in adj_list[u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color idx to all in S
            for u in S:
                colors[u] = color_idx
                uncolored.remove(u)
