    # Strategy 4: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering (smallest last)
        # Copy of degrees
        degree = [len(adj_list[u]) for u in range(n)]
        # List of vertices
        vertices = list(range(n))
        # Buckets for degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            d = degree[u]
            buckets[d].append(u)
        # Pointer to current non-empty bucket
        ptr = 0
        ordering = []
        # We'll maintain a set of removed vertices for degree updates
        removed = [False] * n
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            u = buckets[ptr].pop()
            while removed[u]:
                if not buckets[ptr]:
                    break
                u = buckets[ptr].pop()
            if removed[u]:
                # find another
                found = False
                for d in range(ptr, max_deg + 1):
                    for v in buckets[d]:
                        if not removed[v]:
                            u = v
                            found = True
                            break
                    if found:
                        break
                if not found:
                    # take any unremoved
                    for v in range(n):
                        if not removed[v]:
                            u = v
                            break
            ordering.append(u)
            removed[u] = True
            # Update neighbors
            for v in adj_list[u]:
                if not removed[v]:
                    d = degree[v]
                    # remove v from bucket d
                    if v in buckets[d]:
                        buckets[d].remove(v)
                    degree[v] -= 1
                    dnew = degree[v]
                    if dnew <= max_deg:
                        buckets[dnew].append(v)
                    else:
                        # should not happen as degree decreases
                        pass
        # Now color in reverse order
        colors = [-1] * n
        for u in reversed(ordering):
            used = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # Generate candidate colorings
    candidates = []
    # 1. BFS bipartite then resolve
    try:
        col1 = bfs_bipartite_then_resolve()
        if is_valid_coloring(col1):
            candidates.append(col1)
    except:
        pass
    # 2. DSATUR
    try:
        col2 = dsatur()
        if is_valid_coloring(col2):
