def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = (len(adj) > 0 and len(adj[0]) == n and
                 all(all(x in (0, 1) for x in row) for row in adj))

    # Build neighbor sets and bitmasks
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            neighbors[i] = set(adj[i])

    # Build bitmask for fast operations
    bit_adj = [0] * n
    for i in range(n):
        for j in neighbors[i]:
            bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # saturation degree (distinct colors in neighbors)
        uncolored = set(range(n))

        # Precompute degrees for tie-breaking
        degrees = [len(neighbors[i]) for i in range(n)]

        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v]
                deg = degrees[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                   (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v

            # Assign smallest available color
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)

            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    # Check if color c is new in u's neighborhood
                    new_sat = saturated[u]
                    found = False
                    for w in neighbors[u]:
                        if coloring[w] == c:
                            found = True
                            break
                    if not found:
                        saturated[u] += 1
        return coloring

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for this color
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
                independent_set.add(v)
                # Partition: U = not adjacent to S, W = adjacent to S
                U = uncolored - {v} - (neighbors[v] & uncolored)
                W = (neighbors[v] & uncolored)
            else:
                U = set()
                W = set()

            # Greedily add to independent set
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = len(neighbors[u] & W)
                    deg_u = len(neighbors[u] & U)
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                newly_W = neighbors[u] & U
                U -= newly_W
                W |= newly_W

            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
            color += 1
            uncolored -= independent_set

        return coloring

    # Helper: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # Current degree in remaining subgraph
        curr_deg = degrees[:]

        while remaining:
            # Find vertex with minimum current degree
            v = min(remaining, key=lambda x: curr_deg[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    curr_deg[u] -= 1

        # Color in reverse order
        return greedy_color(list(reversed(order)))

    # Helper: Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, v, a, b):
        if coloring[v] not in (a, b):
            return False
        # BFS to get the Kempe chain component
        stack = [v]
        visited = set()
        target_color = a if coloring[v] == b else b
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            for u in neighbors[node]:
                if coloring[u] == target_color and u not in visited:
                    stack.append(u)
        # Swap colors in the component
        for node in visited:
            if coloring[node] == a:
                coloring[node] = b
            else:
                coloring[node] = a
        return True

    # Helper: try to eliminate the last color using Kempe chains
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        last_color = k - 1
        last_class = [v for v in range(n) if coloring[v] == last_color]
        if not last_class:
            # Already compacted
            return [c if c < last_color else c - 1 for c in coloring]

        # Try to recolor each vertex in last class
        for v in last_class[:]:  # iterate over copy as we may modify
            # Try direct reassignment to a lower color
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            for c in range(last_color):
                if not (used & (1 << c)):
                    coloring[v] = c
                    last_class.remove(v)
                    break
            else:
                # Try Kempe chain swaps with each lower color
                for c in range(last_color):
                    # Temporarily swap and see if v can take color c
                    # We simulate by checking if the Kempe chain of v and c does not include
                    # any vertex that would cause conflict after swap
                    # Instead, we attempt the swap and check validity locally
                    original = coloring[:]
                    if kempe_swap(coloring, v, last_color, c):
                        # After swap, check if v is now color c (it should be if it was in the chain)
                        if coloring[v] == c:
                            # Successfully moved v to color c via Kempe chain
                            last_class.remove(v)
                            break
                        else:
                            # Swap didn't move v, revert
                            coloring[:] = original
                    else:
                        coloring[:] = original
                else:
                    # Successfully moved via Kempe chain, break outer loop
                    break
                # If not broken, continue to next v

        # If last color class is empty, compact
        if not any(c == last_color for c in coloring):
            return [c if c < last_color else c - 1 for c in coloring]
        return coloring

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # Fallback: simple greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid_coloring(c4):
            candidates.append(c4)
    except:
        pass

    # If no candidates, assign all zeros (invalid but safe fallback)
    if not candidates:
        return [0] * n

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)

    # Iteratively try to reduce colors using Kempe chains
    current = best[:]
    for _ in range(10):  # limit iterations to stay within time
        prev_num = num_colors(current)
        reduced = reduce_colors(current)
        if num_colors(reduced) < prev_num:
            current = reduced
        else:
            break

    # Final validation and compaction
    if not is_valid_coloring(current):
        # Should not happen, but fallback to DSATUR
        current = dsatur()

    # Compact colors to 0..k-1
    color_map = {}
    next_color = 0
    for i in range(n):
        c = current[i]
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        current[i] = color_map[c]

    return current

