                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Build complement graph adjacency list
    comp_adj = [set() for _ in range(n)]
    for i in range(n):
        neighbors_set = set(adj_list[i])
        for j in range(n):
            if i != j and j not in neighbors_set:
                comp_adj[i].add(j)

    # Convert to list for consistent ordering
    comp_adj_list = [list(s) for s in comp_adj]

    # Greedy coloring on complement graph (finding cliques in G' = independent sets in G)
    uncolored = set(range(n))
    color = [-1] * n
    current_color = 0

    while uncolored:
        # Find vertex with max degree in the subgraph induced by uncolored in complement graph
        max_deg = -1
        v_start = -1
        for v in uncolored:
            deg = 0
            for nb in comp_adj_list[v]:
                if nb in uncolored:
                    deg += 1
            if deg > max_deg:
                max_deg = deg
                v_start = v

        if v_start == -1:
            # Should not happen, but fallback: pick any
            v_start = next(iter(uncolored))

        # Build clique (independent set in original) greedily
        clique = [v_start]
        uncolored.remove(v_start)
        # Candidates: neighbors of v_start in complement that are still uncolored
        candidates = set()
        for nb in comp_adj_list[v_start]:
            if nb in uncolored:
                candidates.add(nb)

        while candidates:
            # Select vertex with max number of connections to current clique in complement graph
            best_v = -1
            max_conn = -1
            for v in candidates:
                conn = 0
                for u in clique:
                    if v in comp_adj_list[u]:
                        conn += 1
                if conn > max_conn:
                    max_conn = conn
                    best_v = v
                elif conn == max_conn:
                    # Tie-break: higher degree in complement subgraph induced by uncolored
                    deg_v = sum(1 for nb in comp_adj_list[v] if nb in uncolored)
                    deg_best = sum(1 for nb in comp_adj_list[best_v] if nb in uncolored) if best_v != -1 else -1
                    if deg_v > deg_best:
                        best_v = v

            if best_v == -1:
                break

            clique.append(best_v)
            uncolored.remove(best_v)
            # Update candidates: remove best_v, add its neighbors that are uncolored and not in clique
            candidates.discard(best_v)
            for nb in comp_adj_list[best_v]:
                if nb in uncolored and nb not in clique:
                    candidates.add(nb)

        # Assign current color to all vertices in the clique (independent set in original)
        for v in clique:
            color[v] = current_color
        current_color += 1

    return color

