    def smallest_last():
        # Core decomposition to get ordering
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current min degree
        min_deg = 0
        while remaining:
            # Find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = deg[u]
                    deg[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].remove(u)
                    if deg[u] <= max_deg:
                        buckets[deg[u]].append(u)
                    if deg[u] < min_deg:
                        min_deg = deg[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap attempt to free a color for vertex v
    def kempe_swap(coloring, v, target_color, tabu_tenure=10):
        from collections import deque
        current_color = coloring[v]
        if current_color == target_color:
            return True
        # Check if target_color is directly available
        for u in neighbors[v]:
            if coloring[u] == target_color:
                break
        else:
            # No neighbor has target_color, can assign directly
            coloring[v] = target_color
            return True

        # Build (current_color, target_color) Kempe chain containing v
        visited = [False] * n
        queue = deque([v])
        visited[v] = True
        component = []
        while queue:
            node = queue.popleft()
            component.append(node)
            for u in neighbors[node]:
                if not visited[u] and (coloring[u] == current_color or coloring[u] == target_color):
                    visited[u] = True
                    queue.append(u)
        # Check if any neighbor of v in the component has target_color? Actually, we want to see if swapping frees target_color for v.
        # After swap, v will get target_color if it was current_color. But we need to ensure no neighbor gets current_color that conflicts.
        # Actually, swapping colors in the component is safe as long as we don't create conflict. It's always safe for 2-color swap.
        # However, we want to know if after swap, target_color becomes free for v (i.e., no neighbor has target_color after swap).
        # After swap, vertices in component that were target_color become current_color, and vice versa.
        # So for v (which is current_color), after swap it becomes target_color.
        # We need that no neighbor of v has target_color after swap.
        # Neighbors of v: if in component and were target_color -> become current_color (safe)
        #                if in component and were current_color -> become target_color (conflict if adjacent to v)
        #                if not in component -> unchanged.
        # So conflict arises if there is a neighbor u of v such that u is in component and coloring[u] == current_color (because after swap it becomes target_color).
        # But note: if u is neighbor of v and in component, and coloring[u] == current_color, then since v is current_color and adjacent, they would have same color -> but that's impossible because coloring is valid.
        # Therefore, in a valid coloring, no two adjacent vertices have the same color, so if u is neighbor of v and in component, coloring[u] cannot be current_color (same as v).
        # Hence, after swap, no neighbor of v will have target_color? Let's see:
        #   - If neighbor u in component: 
        #        if coloring[u] == target_color -> becomes current_color (not target_color)
        #        if coloring[u] == current_color -> impossible as above
        #   - If neighbor u not in component: coloring[u] unchanged -> if it was target_color, then still target_color -> conflict.
        # So we need that no neighbor of v outside the component has target_color.
        for u in neighbors[v]:
            if not visited[u] and coloring[u] == target_color:
                return False
        # Perform swap
        for node in component:
            if coloring[node] == current_color:
                coloring[node] = target_color
            else:
                coloring[node] = current_color
        return True

    # Attempt to eliminate the smallest color class using Kempe chains
    def reduce_colors(coloring):
        if not coloring:
            return coloring
        # Make a copy to work on
        coloring = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find smallest color class
            color_classes = {}
            for i, c in enumerate(coloring):
                color_classes.setdefault(c, []).append(i)
            if not color_classes:
                break
            min_color = min(color_classes.keys())
            max_color = max(color_classes.keys())
            # If only one color, nothing to reduce
            if min_color == max_color:
                break
            # Try to recolor each vertex in min_color class
            for v in color_classes[min_color][:]:  # iterate over copy
                # Try direct reassignment to a lower color
                for c in range(min_color):
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart after change
                # Try Kempe swaps with each lower color
                for c in range(min_color):
                    # Use a copy for swap attempt to avoid corrupting if fails
                    test_coloring = coloring[:]
                    if kempe_swap(test_coloring, v, c):
                        coloring = test_coloring
                        changed = True
                        break
                if changed:
                    break
            # If we made a change, compact and repeat
            if changed:
                coloring = compact_colors(coloring)
        return coloring

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(compact_colors(c1[:]))
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(compact_colors(c2[:]))
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(compact_colors(c3[:]))
    except:
        pass
    # Fallback: simple greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(compact_colors(c4[:]))

    # Select best candidate (fewest colors)
    best = None
    best_num = float('inf')
    for col in candidates:
        if is_valid(col):
            num = num_colors(col)
            if num < best_num:
                best_num = num
                best = col
    if best is None:
        # Ultimate fallback: assign all zeros (only valid for edgeless)
        best = [0] * n

    # Apply Kempe chain reduction to try to improve
    best = reduce_colors(best)
    best = compact_colors(best)

    # Final validation (should always hold)
    if not is_valid(best):
        # As a last resort, use DSATUR again (should be valid)
        best = dsatur()
        best = compact_colors(best)
        if not is_valid(best):
            # This should not happen, but assign distinct colors
            best = list(range(n))

    return best

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect if adj is adjacency matrix (binary, square)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if v < n:  # safety
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)

    # Ensure symmetry for undirected graph
    for u in range(n):
        for v in neighbors[u]:
            if u not in neighbors[v]:
                neighbors[v].add(u)
                bit_adj[v] |= (1 << u)

    # Helper: compute chromatic number from coloring
    def chromatic_number(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: normalize colors to 0..k-1 consecutive
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map used colors to 0..k-1
        used = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(used)}
        return [mapping[c] for c in coloring]

    best_coloring = None
    best_k = float('inf')

    # Heuristic 1: DSATUR with bitmask optimization
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bitmask for efficiency
        neighbor_colors = [0] * n

        # Precompute degrees for tie-breaking
        degrees = [len(neighbors[i]) for i in range(n)]

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat_u = saturation[u]
                    deg_u = degrees[u]
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                       (sat_u == max_sat and deg_u == max_deg and random.random() < 0.5):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color (mex)
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation and neighbor colors for neighbors
            for u in neighbors[v]:
                if coloring[u] == -1:  # only uncolored neighbors
                    # Add color c to neighbor's neighbor color set
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return normalize(coloring)

    # Heuristic 2: RLF (Recursive Largest First) with bitmask
    def rlf():
        coloring = [-1] * n
        color = 0
        # uncolored set as bitmask
        uncolored = (1 << n) - 1

        while uncolored:
            # Build independent set for this color
            independent_set = 0
            # eligible: vertices not adjacent to any in independent_set
            eligible = uncolored
            # ineligible: 0 initially
            ineligible = 0

            # Start with vertex of max degree in uncolored subgraph
            v = -1
            max_deg = -1
            # compute degree in uncolored subgraph
            temp = uncolored
            while temp:
                u = (temp & -temp).bit_length() - 1
                temp &= temp - 1
                # count neighbors in uncolored
                deg = (bit_adj[u] & uncolored).bit_count()
                if deg > max_deg:
                    max_deg = deg
                    v = u
            if v == -1:
                break

            # Add v to independent set
            independent_set |= (1 << v)
            eligible &= ~(1 << v)
            # Move neighbors of v from eligible to ineligible
            ineligible |= (bit_adj[v] & eligible)
            eligible &= ~(bit_adj[v] & eligible)

            # While there are eligible vertices
            while eligible:
                # Select u in eligible with max neighbors in ineligible, tie-break by min degree in eligible subgraph
                u = -1
                max_w = -1
                min_deg_eligible = float('inf')
                temp = eligible
                while temp:
                    x = (temp & -temp).bit_length() - 1
                    temp &= temp - 1
                    w_count = (bit_adj[x] & ineligible).bit_count()
                    # degree in eligible subgraph
                    deg_eligible = (bit_adj[x] & eligible).bit_count()
                    if w_count > max_w or (w_count == max_w and deg_eligible < min_deg_eligible) or \
                       (w_count == max_w and deg_eligible == min_deg_eligible and random.random() < 0.5):
                        max_w = w_count
                        min_deg_eligible = deg_eligible
                        u = x
                if u == -1:
                    break

                # Add u to independent set
                independent_set |= (1 << u)
                eligible &= ~(1 << u)
                # Move neighbors of u from eligible to ineligible
                ineligible |= (bit_adj[u] & eligible)
                eligible &= ~(bit_adj[u] & eligible)

            # Assign color to all vertices in independent_set
            temp = independent_set
            while temp:
                u = (temp & -temp).bit_length() - 1
                temp &= temp - 1
                coloring[u] = color

            # Update uncolored: remove independent_set, set uncolored to ineligible (vertices adjacent to independent_set)
            uncolored = ineligible
            color += 1

        return normalize(coloring)

    # Heuristic 3: Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # We'll use a bucket-like approach but n is small
        while remaining:
            # Find vertex with min degree in remaining subgraph
            v = -1
            min_deg = float('inf')
            for u in remaining:
                # count neighbors in remaining
                deg = sum(1 for w in neighbors[u] if w in remaining)
                if deg < min_deg:
                    min_deg = deg
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)

        # Color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return normalize(coloring)

    # Heuristic 4: Jaccard-based neighborhood overlap for non-adjacent pairs
    def jaccard_heuristic():
        # Precompute Jaccard similarity for non-adjacent pairs
        sim = [[0.0] * n for _ in range(n)]
        for u in range(n):
            for v in range(u+1, n):
                if v not in neighbors[u]:  # non-adjacent
                    inter = len(neighbors[u] & neighbors[v])
                    union = len(neighbors[u] | neighbors[v])
                    sim[u][v] = sim[v][u] = inter / union if union > 0 else 0.0

        # Greedy: sort pairs by similarity descending, try to assign same color
        pairs = []
        for u in range(n):
            for v in range(u+1, n):
                if v not in neighbors[u]:
                    pairs.append((sim[u][v], u, v))
        pairs.sort(key=lambda x: -x[0])

        coloring = [-1] * n
        # Process pairs, assign same color if possible
        for _, u, v in pairs:
            if coloring[u] == -1 and coloring[v] == -1:
                # Find smallest color not used by neighbors of u or v
                used_u = 0
                for w in neighbors[u]:
                    if coloring[w] != -1:
                        used_u |= (1 << coloring[w])
                used_v = 0
                for w in neighbors[v]:
                    if coloring[w] != -1:
                        used_v |= (1 << coloring[w])
                used = used_u | used_v
                c = 0
                while used & (1 << c):
                    c += 1
                coloring[u] = c
                coloring[v] = c

        # Color remaining uncolored vertices with first-fit
        for u in range(n):
            if coloring[u] == -1:
                used = 0
                for w in neighbors[u]:
                    if coloring[w] != -1:
                        used |= (1 << coloring[w])
                c = 0
                while used & (1 << c):
                    c += 1
                coloring[u] = c

        return normalize(coloring)

    # Run all heuristics
    start = time.time()
    heuristics = [dsatur, rlf, smallest_last, jaccard_heuristic]
    for heuristic in heuristics:
        if time.time() - start > 0.04:  # leave time for Kempe
            break
        try:
            coloring = heuristic()
            if is_valid(coloring):
                k = chromatic_number(coloring)
                if k < best_k:
                    best_k = k
                    best_coloring = coloring
        except:
            continue

    # If no heuristic succeeded (should not happen), use greedy
    if best_coloring is None:
        coloring = [-1] * n
        for u in range(n):
            used = 0
            for v in neighbors[u]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        best_coloring = normalize(coloring)

    # Iterative Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring
        n_local = n
        # Try to eliminate color classes from highest down
        changed = True
        while changed and time.time() - start < 0.045:
            changed = False
            # Get color classes
            classes = [[] for _ in range(best_k)]  # we don't know best_k yet, use current max
            max_color = max(coloring) if coloring else -1
            for i in range(max_color + 1):
                classes[i] = []
            for v in range(n_local):
                c = coloring[v]
                if c <= max_color:
                    classes[c].append(v)

            # Try to eliminate the smallest non-empty color class (by size)
            # We'll try from highest color down to potentially reduce max color
            for target_color in range(max_color, -1, -1):
                if not classes[target_color]:
                    continue
                # Try to recolor each vertex in this class
                eliminated = True
                new_coloring = coloring[:]  # copy
                for v in classes[target_color]:
                    # Try to find a color c < target_color that v can take
                    reassigned = False
                    for c in range(target_color):
                        # Check if color c is available (no neighbor has color c)
                        conflict = False
                        for u in neighbors[v]:
                            if new_coloring[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            new_coloring[v] = c
                            reassigned = True
                            break
                    if reassigned:
                        continue
                    # Try Kempe chains with each color c < target_color
                    kempe_success = False
                    for c in range(target_color):
                        # We'll try to swap colors in the (c, target_color) Kempe chain containing v
                        # Only if v is not in a chain that would pull another vertex into target_color
                        # Build the Kempe chain component for v in colors {c, target_color}
                        from collections import deque
                        visited = [False] * n_local
                        queue = deque()
                        component = []
                        # Only traverse vertices with color c or target_color
                        if new_coloring[v] != target_color:
                            continue  # should be target_color
                        queue.append(v)
                        visited[v] = True
                        while queue:
                            x = queue.popleft()
                            component.append(x)
                            for y in neighbors[x]:
                                if not visited[y] and (new_coloring[y] == c or new_coloring[y] == target_color):
                                    visited[y] = True
                                    queue.append(y)
                        # Check if swapping would cause any vertex in component to conflict
                        # After swap: c -> target_color, target_color -> c
                        # We need to ensure no neighbor outside component has color c (which would become target_color after swap)
                        # or neighbor outside has color target_color (which would become c)
                        # Actually, we only care about introducing conflict: after swap, 
                        # a vertex that was c becomes target_color: check if any neighbor has target_color (and is not in component)
                        # a vertex that was target_color becomes c: check if any neighbor has c (and not in component)
                        valid_swap = True
                        for x in component:
                            orig_color = new_coloring[x]
                            new_color = c if orig_color == target_color else target_color
                            for y in neighbors[x]:
                                if not visited[y]:  # y not in component
                                    if new_coloring[y] == new_color:
                                        valid_swap = False
                                        break
                            if not valid_swap:
                                break
                        if valid_swap:
                            # Perform swap
                            for x in component:
                                if new_coloring[x] == c:
                                    new_coloring[x] = target_color
                                else:
                                    new_coloring[x] = c
                            kempe_success = True
                            break
                    if kempe_success:
                        # Successfully moved v via Kempe chain
                        continue
                    else:
                        # Could not recolor v
                        eliminated = False
                        break
                if eliminated:
                    # Successfully eliminated target_color class
                    # Relabel colors to be consecutive
                    coloring = new_coloring[:]
                    # Pull down colors above target_color
                    for v in range(n_local):
                        if coloring[v] > target_color:
                            coloring[v] -= 1
                    changed = True
                    break  # restart while loop
                # else: try next target_color
        return normalize(coloring)

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduce(best_coloring)
    except:
        pass

    # Final validation and normalization
    if not is_valid(best_coloring):
        # Fallback to greedy
        coloring = [-1] * n
        for u in range(n):
            used = 0
            for v in neighbors[u]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        best_coloring = normalize(coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    if is_matrix:
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
        adj_list = [[j for j in range(n) if (bit_adj[i] >> j) & 1] for i in range(n)]
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: count bits
    def popcount(x):
        return x.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        saturation = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            v = max(uncolored, key=lambda x: (saturation[x], popcount(bit_adj[x] & sum((1 << u) for u in uncolored)), random.random()))
            # Find smallest available color
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if color[u] == -1:
                    saturation[u] += 1
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set S for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: popcount(bit_adj[x] & sum((1 << u) for u in uncolored)))
                S.add(v)
                uncolored.remove(v)
                # Partition: U = not adjacent to S, W = adjacent to S
                U = set()
                W = set()
                for u in uncolored:
                    if any((bit_adj[u] >> w) & 1 for w in S):
                        W.add(u)
                    else:
                        U.add(u)
                # Greedily add to S from U
                while U:
                    # Select u in U with max |N(u) ∩ W|
                    u_star = max(U, key=lambda x: (popcount(bit_adj[x] & sum((1 << w) for w in W)), -popcount(bit_adj[x] & sum((1 << uu) for uu in U)), random.random()))
                    S.add(u_star)
                    U.remove(u_star)
                    # Move neighbors of u_star in U to W
                    nbrs = {uu for uu in U if (bit_adj[u_star] >> uu) & 1}
                    U -= nbrs
                    W |= nbrs
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        color = [-1] * n
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [popcount(bit_adj[i]) for i in range(n)]
        # Current degrees in remaining subgraph
        curr_deg = degrees[:]
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for i in range(n):
            if curr_deg[i] <= max_deg:
                buckets[curr_deg[i]].add(i)
        # Peel min degree vertex
        for _ in range(n):
            # Find non-empty bucket with smallest index
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    old_deg = curr_deg[u]
                    curr_deg[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].discard(u)
                    if curr_deg[u] <= max_deg:
                        buckets[curr_deg[u]].add(u)
        # Color in reverse order
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(color_in):
        color = color_in[:]
        # Map color to list of vertices
        while True:
            # Find color classes
            classes = {}
            for v in range(n):
                c = color[v]
                classes.setdefault(c, []).append(v)
            if not classes:
                break
            max_color = max(classes.keys())
            # Try to eliminate color classes from highest down
            changed = False
            for c in range(max_color, -1, -1):
                if c not in classes:
                    continue
                verts = classes[c]
                # Try to recolor each vertex in this class
                for v in verts:
                    used = 0
                    for u in adj_list[v]:
                        if color[u] != -1:
                            used |= (1 << color[u])
                    # Try direct reassignment to lower color
                    for c_new in range(c):
                        if not (used & (1 << c_new)):
                            color[v] = c_new
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chains with each lower color
                    for c_new in range(c):
                        if color[v] == c_new:
                            continue
                        # Check if v is in a Kempe chain of (c, c_new) that does not include any other vertex of color c
                        # We'll try to swap the component containing v if it frees color c for v
                        # Build component of v in subgraph of colors c and c_new
                        stack = [v]
                        visited = set()
                        comp_c = set()  # vertices of color c in comp
                        comp_cnew = set()  # vertices of color c_new in comp
                        while stack:
                            x = stack.pop()
                            if x in visited:
                                continue
                            visited.add(x)
                            if color[x] == c:
                                comp_c.add(x)
                            elif color[x] == c_new:
                                comp_cnew.add(x)
                            for u in adj_list[x]:
                                if color[u] == c or color[u] == c_new:
                                    if u not in visited:
                                        stack.append(u)
                        # If the component contains no other vertex of color c besides v, we can swap
                        if len(comp_c) == 1 and v in comp_c:
                            # Swap colors c and c_new in the component
                            for x in comp_c:
                                color[x] = c_new
                            for x in comp_cnew:
                                color[x] = c
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if not changed:
                break
        # Compact colors
        # Map existing colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for v in range(n):
            c = color[v]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            color[v] = unique_colors[c]
        return color

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        # Validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = len(set(col))
        if k < best_k:
            best_k = k
            best = col

    # Fallback: if no valid candidate (should not happen), use greedy
    if best is None:
        color = [-1] * n
        for v in range(n):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best = color

    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)

    # Final validation and compacting (already compacted in kempe_reduce, but ensure)
    unique_colors = {}
    next_color = 0
    for v in range(n):
        c = best[v]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best[v] = unique_colors[c]

    return best

