def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    if is_matrix:
        neighbors = [set() for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1 and u != v:
                    neighbors[u].add(v)
    else:
        neighbors = [set() for _ in range(n)]
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n and u != v:
                    neighbors[u].add(v)
                    neighbors[v].add(u)  # ensure undirected

    # Helper: check valid coloring
    def is_valid(col):
        for u in range(n):
            for v in neighbors[u]:
                if col[u] == col[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(col):
        return max(col) + 1 if col else 0

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([nb for nb in neighbors[x] if nb in uncolored])))
            # Find smallest available color
            used = {color[nb] for nb in neighbors[v] if color[nb] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for nb in neighbors[v]:
                if nb in uncolored:
                    sat[nb] = len({color[n] for n in neighbors[nb] if color[n] != -1})
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([nb for nb in neighbors[x] if nb in uncolored]))
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and all(nb not in S for nb in neighbors[u])}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([nb for nb in neighbors[x] if nb in W]), -len([nb for nb in neighbors[x] if nb in U])))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in list(neighbors[u] & U):
                    U.remove(nb)
                    W.add(nb)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering greedy
    def smallest_last():
        # Compute degeneracy ordering
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Peel min degree vertex
        for _ in range(n):
            # Find non-empty bucket with smallest index
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
            if i > max_deg:
                break
            v = buckets[i].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for nb in neighbors[v]:
                if nb in remaining:
                    d = deg[nb]
                    if d > 0:
                        buckets[d].remove(nb)
                        deg[nb] -= 1
                        buckets[deg[nb]].append(nb)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = {color[nb] for nb in neighbors[v] if color[nb] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Generate initial candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except:
            continue

    # Fallback: greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = {color[nb] for nb in neighbors[v] if color[nb] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        candidates.append(color)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Try to reduce colors via Kempe chain swaps (target highest color)
    def kempe_reduce(col, max_steps=50):
        k_cur = num_colors(col)
        if k_cur <= 1:
            return col
        # Target the last color (k_cur-1)
        target_color = k_cur - 1
        vertices = [v for v in range(n) if col[v] == target_color]
        if not vertices:
            # Already reduced
            return [c if c < target_color else c-1 for c in col]

        # Tabu search to resolve conflicts by recoloring target_color vertices
        # We allow temporary conflicts but penalize them
        tabu_tenure = 5
        tabu = {}  # (vertex, color) -> step until which tabu
        current = col[:]
        steps = 0
        while steps < max_steps and any(c == target_color for c in current):
            # Find a vertex with target_color that has conflicts or is candidates for move
            v_candidates = [v for v in range(n) if current[v] == target_color]
            if not v_candidates:
                break
            v = random.choice(v_candidates)
            # Consider all possible colors (including target_color for staying)
            possible_colors = list(range(k_cur))  # we can try to use existing colors
            best_move = None
            best_score = float('inf')
            for c in possible_colors:
                if tabu.get((v, c), 0) > steps:
                    continue
                # Compute conflict change if we move v to c
                old_color = current[v]
                # Remove v from old_color, add to c
                # Conflicts: edges to same color
                loss = sum(1 for nb in neighbors[v] if current[nb] == old_color)
                gain = sum(1 for nb in neighbors[v] if current[nb] == c)
                delta = gain - loss  # we want to minimize increase in conflicts
                if delta < best_score:
                    best_score = delta
                    best_move = (v, c)
            if best_move is None:
                # All moves tabu, choose random
                v = random.choice(v_candidates)
                c = random.choice(possible_colors)
                best_move = (v, c)
            v, c = best_move
            # Perform move
            old_color = current[v]
            current[v] = c
            # Update tabu
            tabu[(v, old_color)] = steps + tabu_tenure
            steps += 1

        # After tabu search, if no vertex has target_color, we can reduce
        if not any(c == target_color for c in current):
            # Compact colors: map [0..k_cur-1] to [0..k_cur-2] if target_color removed
            mapping = {}
            new_c = 0
            for old_c in range(k_cur):
                if old_c == target_color:
                    continue
                mapping[old_c] = new_c
                new_c += 1
            return [mapping[c] for c in current]
        else:
            # Could not eliminate target_color, return original
            return col

    # Apply Kempe reduction iteratively
    current_best = best[:]
    while True:
        new_col = kempe_reduce(current_best, max_steps=30)
        if num_colors(new_col) < num_colors(current_best):
            current_best = new_col
        else:
            break

    # Final validation (should be valid by construction, but ensure)
    if not is_valid(current_best):
        # Fallback to best candidate if something went wrong
        current_best = best

    return current_best

