def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for u in range(n):
            for v in adj_list[u]:
                bit_adj[u] |= (1 << v)

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], sum(1 for y in adj_list[x] if y in uncolored)))
            # Assign smallest available color
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] += 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S.add(v)
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if not any(w in adj_list[u] for w in S)}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W
                u_star = max(U, key=lambda x: sum(1 for y in adj_list[x] if y in W))
                # Tie-break: min degree in G[U]
                U_without_u = U - {u_star}
                deg_in_U = lambda x: sum(1 for y in adj_list[x] if y in U_without_u)
                candidates = [x for x in U if sum(1 for y in adj_list[x] if y in W) == sum(1 for y in adj_list[u_star] if y in W)]
                u_star = min(candidates, key=deg_in_U)
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for y in adj_list[u_star]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
            uncolored = W  # Next round
        return color

    # Strategy 3: Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[v]) for v in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    buckets[d].remove(u)
                    buckets[d-1].append(u)
                    if d-1 < ptr:
                        ptr = d-1
        # Color in reverse order
        return greedy_color(reversed(order))

    # Strategy 4: Degree-based ordering with dynamic discount (as per directive)
    def dynamic_degree_discount():
        # Order vertices by initial degree descending
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        # But we will color in this order, and dynamically adjust effective degree
        # by subtracting already colored neighbors (as per directive: discount neighbors as colored)
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Generate candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last, dynamic_degree_discount]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except:
            continue

    # Also try greedy on random orders as fallback
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(col)

    # Select best candidate (fewest colors)
    if candidates:
        best_coloring = min(candidates, key=count_colors)
        best_k = count_colors(best_coloring)
    else:
        # Fallback: greedy on natural order
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        # Make coloring consecutive
        def renumber(col):
            mapping = {}
            next_color = 0
            for v in range(n):
                if col[v] not in mapping:
                    mapping[col[v]] = next_color
                    next_color += 1
                col[v] = mapping[col[v]]
            return col

        coloring = renumber(coloring[:])
        k = count_colors(coloring)
        improved = True
        while improved and k > 1:
            improved = False
            # Target smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already compacted
                coloring = renumber(coloring)
                k = count_colors(coloring)
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        used_by_neighbors |= (1 << coloring[u])
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Build (c, target_color)-Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # Check if swapping frees color c for v
                    # After swap, v would get color c if it was target_color
                    # We need to ensure no neighbor of v gets color c after swap (would cause conflict)
                    # Actually, we check: if we swap, does any neighbor of v end up with color c?
                    # Neighbors of v currently have colors != target_color (since v is target_color and coloring is valid)
                    # After swap, a neighbor u of v:
                    #   if u was in component and had color c -> becomes target_color
                    #   if u was in component and had target_color -> becomes c
                    #   if u not in component -> unchanged
                    # So, if any neighbor u of v is in the component and had color c, after swap it becomes target_color -> no conflict
                    # If any neighbor u of v is in the component and had target_color, after swap it becomes c -> conflict if v also becomes c
                    # But v is in the component and has target_color -> after swap becomes c
                    # So if any neighbor u of v is in the component and had target_color, then after swap both u and v would be c -> conflict
                    # Therefore, we can swap only if no neighbor of v in the component has target_color
                    has_target_color_neighbor_in_component = False
                    for u in adj_list[v]:
                        if visited[u] and coloring[u] == target_color:
                            has_target_color_neighbor_in_component = True
                            break
                    if not has_target_color_neighbor_in_component:
                        # Perform swap
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target_color
                            elif coloring[x] == target_color:
                                coloring[x] = c
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # Renumber and continue
                coloring = renumber(coloring)
                k = count_colors(coloring)
            else:
                # Could not eliminate target color
                break
        return coloring

    # Apply Kempe reduction
    final_coloring = kempe_reduce(best_coloring)
    # Final validation
    if not is_valid(final_coloring):
        # Fallback to best candidate if Kempe broke validity
        final_coloring = best_coloring

    return final_coloring

