def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert adjacency to list of lists if it's a matrix
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        graph = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        graph = adj

    # Find biconnected components (blocks) and cut vertices using DFS
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    is_cut = [False] * n
    time = 0
    stack = []
    blocks = []  # each block is a set of vertices

    def dfs(u):
        nonlocal time
        disc[u] = low[u] = time
        time += 1
        children = 0
        for v in graph[u]:
            if disc[v] == -1:
                parent[v] = u
                children += 1
                stack.append((u, v))
                dfs(v)
                low[u] = min(low[u], low[v])
                if (parent[u] == -1 and children > 1) or (parent[u] != -1 and low[v] >= disc[u]):
                    is_cut[u] = True
                    block = set()
                    while True:
                        e = stack.pop()
                        block.add(e[0])
                        block.add(e[1])
                        if e == (u, v):
                            break
                    blocks.append(block)
            elif v != parent[u] and disc[v] < disc[u]:
                low[u] = min(low[u], disc[v])
                stack.append((u, v))
        if parent[u] == -1 and children == 0:
            # isolated vertex
            blocks.append({u})

    for i in range(n):
        if disc[i] == -1:
            dfs(i)
            if stack:
                block = set()
                while stack:
                    e = stack.pop()
                    block.add(e[0])
                    block.add(e[1])
                blocks.append(block)

    # If no blocks (should not happen), fallback
    if not blocks:
        blocks = [set(range(n))]

    # Build block-cut tree: bipartite graph between blocks and cut vertices
    block_id_of_vertex = [[] for _ in range(n)]
    for bid, block in enumerate(blocks):
        for v in block:
            block_id_of_vertex[v].append(bid)

    # We'll assign colors to vertices, ensuring consistency at cut vertices
    color = [-1] * n
    used_colors_global = set()

    # Process each block; for cut vertices, we will try to reuse colors from already colored blocks
    # Order blocks by size (smallest first) to minimize conflicts
    block_order = sorted(range(len(blocks)), key=lambda b: len(blocks[b]))

    for bid in block_order:
        block = blocks[bid]
        # Determine which vertices in this block are already colored (cut vertices from previous blocks)
        precolored = {v: color[v] for v in block if color[v] != -1}
        uncolored = [v for v in block if color[v] == -1]

        # If all vertices are precolored, just check validity and update used colors
        if not uncolored:
            for v in block:
                used_colors_global.add(color[v])
            continue

        # Build subgraph induced by the block
        subgraph = {v: [] for v in block}
        for v in block:
            for nb in graph[v]:
                if nb in block:
                    subgraph[v].append(nb)

        # Try to color the uncolored vertices using DSATUR on the subgraph, respecting precolored ones
        # We'll map local colors to global, but we can permute colors freely as long as cut vertices match
        # Since we can permute colors in a block arbitrarily, we only need to ensure that the precolored
        # vertices keep their color, and we assign new colors to others, possibly reusing or introducing new ones.

        # We'll use a greedy DSATUR on the uncolored vertices, with fixed colors for precolored
        local_color = {}
        for v in precolored:
            local_color[v] = precolored[v]

        # Saturation degree: number of distinct colors in neighbors
        def saturation(v):
            return len({local_color.get(u) for u in subgraph[v] if u in local_color})

        # Degree in the subgraph (for tie-breaking)
        def degree(v):
            return len(subgraph[v])

        # Order uncolored vertices by DSATUR
        uncolored_sorted = sorted(uncolored, key=lambda v: (-saturation(v), -degree(v), v))

        # Available colors: we can use any color, but we prefer to reuse existing global colors to minimize total
        # However, we must avoid colors used by neighbors
        # We'll try to assign the smallest possible color (global) that is not used by any neighbor
        # This may introduce new colors, but we keep track of used ones globally
        for v in uncolored_sorted:
            neighbor_colors = {local_color.get(u) for u in subgraph[v] if u in local_color}
            c = 0
            while c in neighbor_colors:
                c += 1
            local_color[v] = c
            used_colors_global.add(c)

        # Assign the local colors to the global color array
        for v in block:
            color[v] = local_color[v]

    # Compact colors: remap to 0..k-1
    unique_colors = sorted(set(color))
    mapping = {c: i for i, c in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    # Final validation (optional, but safe)
    for u in range(n):
        for v in graph[u]:
            if u < v and color[u] == color[v]:
                # Conflict: should not happen, but if so, fallback to greedy
                return _greedy_coloring(graph)
    return color

def _greedy_coloring(graph):
    n = len(graph)
    if n == 0:
        return []
    # Order by degree descending
    order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
    color = [-1] * n
    for u in order:
        used = {color[v] for v in graph[u] if color[v] != -1}
        c = 0
        while c in used:
            c += 1
        color[u] = c
    # Compact
    unique = sorted(set(color))
    mapping = {c: i for i, c in enumerate(unique)}
    return [mapping[c] for c in color]

