def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = (len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for x in adj[0]))
    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = [list(lst) for lst in adj]

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        used_masks = [0] * n  # bitmask of colors used by neighbors
        for v in order:
            cmask = used_masks[v]
            c = 0
            while cmask & (1 << c):
                c += 1
            color[v] = c
            for u in neighbors[v]:
                used_masks[u] |= (1 << c)
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # --- DSATUR ---
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors in neighborhood
        sat = [0] * n
        # degree in uncolored subgraph
        deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x].bit_count(), deg[x], random.random()))
            # find smallest available color
            cmask = sat[v]
            c = 0
            while cmask & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg[u] -= 1
        return color

    # --- RLF ---
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in induced subgraph of uncolored
            deg_sub = [0] * n
            for v in uncolored:
                mask = bit_adj[v]
                # count neighbors in uncolored
                cnt = 0
                m = mask
                while m:
                    lsb = m & -m
                    u = (lsb.bit_length() - 1)
                    if u in uncolored:
                        cnt += 1
                    m ^= lsb
                deg_sub[v] = cnt
            # pick vertex with max degree in subgraph
            v = max(uncolored, key=lambda x: (deg_sub[x], random.random()))
            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to S, W: adjacent to S
            U = {u for u in uncolored if (bit_adj[v] & (1 << u)) == 0}
            W = uncolored - U
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    # count neighbors in W
                    score = 0
                    m = bit_adj[u]
                    while m:
                        lsb = m & -m
                        w = (lsb.bit_length() - 1)
                        if w in W:
                            score += 1
                        m ^= lsb
                    if score > best_score or (score == best_score and (best_u is None or len(neighbors[u]) < len(neighbors[best_u]))):
                        best_score = score
                        best_u = u
                if best_u is None:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                m = bit_adj[best_u]
                while m:
                    lsb = m & -m
                    w = (lsb.bit_length() - 1)
                    if w in U:
                        U.remove(w)
                        W.add(w)
                    m ^= lsb
            for v in S:
                color[v] = c
            c += 1
        return color

    # --- Smallest-Last (Matula & Beck) ---
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        pos = [0] * n
        for v in range(n):
            pos[v] = buckets[deg[v]].index(v) if v in buckets[deg[v]] else -1
        # simulate removal
        for _ in range(n):
            # find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # remove u from its bucket
                    old_deg = deg[u]
                    buckets[old_deg].remove(u)
                    deg[u] -= 1
                    new_deg = deg[u]
                    buckets[new_deg].append(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if all(0 <= col[i] < n for i in range(n)) and all(col[u] != col[v] for u in range(n) for v in neighbors[u]):
                candidates.append(col)
        except Exception:
            continue

    if not candidates:
        # fallback: greedy by original order
        candidates.append(greedy_color(list(range(n))))

    # Select best candidate
    for col in candidates:
        k = num_colors(col)
        if k < best_k:
            best_k = k
            best_coloring = col

    # --- Kempe Chain Color Reduction ---
    def eliminate_color_class(coloring, target_color):
        # vertices with target_color
        verts = [v for v in range(n) if coloring[v] == target_color]
        if not verts:
            return coloring, True  # already eliminated
        # Try to recolor each vertex
        for v in verts:
            used = set()
            for u in neighbors[v]:
                if coloring[u] < target_color:
                    used.add(coloring[u])
            # find smallest available color < target_color
            for c in range(target_color):
                if c not in used:
                    # direct reassignment
                    coloring[v] = c
                    verts.remove(v)
                    break
            else:
                # try Kempe chains
                for c in range(target_color):
                    if c in used:
                        continue
                    # BFS to get Kempe chain of (target_color, c) from v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        x = stack.pop()
                        if x in visited:
                            continue
                        visited.add(x)
                        if coloring[x] == target_color or coloring[x] == c:
                            component.add(x)
                            for u in neighbors[x]:
                                if coloring[u] == target_color or coloring[u] == c:
                                    if u not in visited:
                                        stack.append(u)
                    # check if any neighbor of v with color c is in this component
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c and u in component:
                            conflict = True
                            break
                    if not conflict:
                        # swap colors in component
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            elif coloring[x] == c:
                                coloring[x] = target_color
                        verts.remove(v)
                        break
                else:
                    # cannot recolor v
                    return coloring, False
        # all vertices recolored, eliminate target_color
        # compact colors > target_color
        for v in range(n):
            if coloring[v] > target_color:
                coloring[v] -= 1
        return coloring, True

    # Try to reduce colors from highest downward
    current = best_coloring[:]
    changed = True
    while changed and num_colors(current) > 1:
        changed = False
        k = num_colors(current)
        # try to eliminate color k-1
        new_col, success = eliminate_color_class(current[:], k-1)
        if success:
            current = new_col
            changed = True
            # verify
            if not all(0 <= current[i] < n for i in range(n)) or any(current[u] == current[v] for u in range(n) for v in neighbors[u]):
                # revert if invalid
                current = best_coloring[:]
                break
            best_coloring = current
        else:
            break

    # Ensure consecutive colors
    remap = {}
    next_color = 0
    for v in range(n):
        c = best_coloring[v]
        if c not in remap:
            remap[c] = next_color
            next_color += 1
        best_coloring[v] = remap[c]

    return best_coloring

