    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    uncolored = set(range(n))
    color = [-1] * n
    sat = [0] * n  # saturation degree: number of distinct colors in neighbors
    while uncolored:
        # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
        v = max(uncolored, key=lambda x: (sat[x], len([y for y in neighbors[x] if y in uncolored]), random.random()))
        # Assign smallest available color
        used = 0
        for u in neighbors[v]:
            c = color[u]
            if c != -1:
                used |= (1 << c)
        c = 0
        while used & (1 << c):
            c += 1
        color[v] = c
        uncolored.remove(v)
        # Update saturation of uncolored neighbors
        for u in neighbors[v]:
            if u in uncolored:
                sat[u] = len({color[w] for w in neighbors[u] if color[w] != -1})
    k = num_colors(color)
    if k < best_k:
        best_k = k
        best_coloring = color[:]

    # 2. RLF (Recursive Largest First) independent set extraction
    uncolored = set(range(n))
    color = [-1] * n
    c = 0
    while uncolored:
        # Build independent set for color c
        # Start with vertex of max degree in uncolored subgraph
        v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
        S = {v}
        # U: vertices not adjacent to any in S (eligible)
        # W: vertices adjacent to at least one in S (ineligible)
        U = {u for u in uncolored if u != v and v not in neighbors[u]}
        W = {u for u in uncolored if u != v and v in neighbors[u]}
        while U:
            # Select u in U with max neighbors in W, tie-break by min degree in U
            u = max(U, key=lambda x: (len([w for w in neighbors[x] if w in W]), -len([w for w in neighbors[x] if w in U]), random.random()))
            S.add(u)
            U.remove(u)
            # Move neighbors of u that are in U to W
            for w in neighbors[u]:
                if w in U:
                    U.remove(w)
                    W.add(w)
        # Assign color c to all in S
        for v in S:
            color[v] = c
        uncolored -= S
        c += 1
    k = num_colors(color)
    if k < best_k:
        best_k = k
        best_coloring = color[:]

    # 3. Smallest-Last ordering (Matula & Beck)
    # Compute degeneracy ordering by repeatedly removing min degree vertex
    remaining = set(range(n))
    order = []
    degrees = [len(neighbors[i]) for i in range(n)]
    # Current degree in remaining subgraph
    curr_deg = degrees[:]
    while remaining:
        # Find vertex with minimum current degree
        v = min(remaining, key=lambda x: curr_deg[x])
        order.append(v)
        remaining.remove(v)
        # Update degrees of neighbors
        for u in neighbors[v]:
            if u in remaining:
                curr_deg[u] -= 1
    # Color in reverse order
    color = greedy_color(order[::-1])
    k = num_colors(color)
    if k < best_k:
        best_k = k
        best_coloring = color[:]

    # 4. Kempe chain color reduction
    def kempe_reduce(coloring):
        # Try to eliminate the smallest color class iteratively
        while True:
            k = num_colors(coloring)
            if k <= 1:
                break
            target = k - 1  # highest color class
            # Get vertices with target color
            targets = [v for v in range(n) if coloring[v] == target]
            if not targets:
                break  # should not happen
            removed = False
            for v in targets:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        removed = True
                        break
                if removed:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target):
                    # Find the Kempe chain component of v in colors {c, target}
                    # BFS/DFS to get component
                    stack = [v]
                    comp = set()
                    visited = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == c or coloring[node] == target:
                            comp.add(node)
                            for u in neighbors[node]:
                                if coloring[u] == c or coloring[u] == target:
                                    stack.append(u)
                    # Check if any neighbor of v with color c is NOT in this component
                    # If so, swapping will free color c for v
                    safe = False
                    for u in neighbors[v]:
                        if coloring[u] == c and u not in comp:
                            safe = True
                            break
                    if safe:
                        # Swap colors c and target in the component
                        for node in comp:
                            if coloring[node] == c:
                                coloring[node] = target
                            else:
                                coloring[node] = c
                        removed = True
                        break
                if removed:
                    break
            if not removed:
                break  # cannot reduce further
            # Compact colors: reindex to 0..k-2
            mapping = {}
            next_c = 0
            for i in range(n):
                c = coloring[i]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                coloring[i] = mapping[c]
        return coloring

    # Apply Kempe reduction to the best coloring so far
    if best_coloring is not None:
        reduced = kempe_reduce(best_coloring[:])
        k = num_colors(reduced)
        if k < best_k:
            best_k = k
            best_coloring = reduced

    # Final validation and compacting (ensure 0..k-1)
    if best_coloring is None:
        best_coloring = [0] * n
    # Ensure proper coloring (should be, but verify)
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Conflict: fallback to greedy with random order
                order = list(range(n))
                random.shuffle(order)
                best_coloring = greedy_color(order)
                break
        else:
            continue
        break
    # Compact colors
    mapping = {}
    next_c = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
        best_coloring[i] = mapping[c]
    return best_coloring

