            # Find vertex in uncolored with max degree in G[uncolored]
            max_deg = -1
            start_v = None
            for v in uncolored:
                # Count neighbors in uncolored
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    start_v = v
            S = {start_v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for v in uncolored:
                if v == start_v:
                    continue
                adjacent_to_S = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(v)
                else:
                    U.add(v)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    # Tie-break: min degree in G[U]
                    deg_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or \
                       (score == best_score and deg_U == best_deg_U and u < best_u):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1

        return compact_colors(coloring)

    # Smallest-Last ( degeneracy ordering ) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []  # removal order
        # We'll use a bucket queue for efficiency, but n<=100 so simple scan is fine
        temp_degree = degree[:]
        remaining_set = set(range(n))
        for _ in range(n):
            # Find vertex with min temp_degree in remaining_set
            min_v = None
            min_deg = float('inf')
            for v in remaining_set:
                if temp_degree[v] < min_deg:
                    min_deg = temp_degree[v]
                    min_v = v
            if min_v is None:
                break
            order.append(min_v)
            remaining_set.remove(min_v)
            # Decrease temp_degree of neighbors
            for u in adj_list[min_v]:
                if u in remaining_set:
                    temp_degree[u] -= 1
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by colored neighbors
            neighbor_colors = set()
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors.add(coloring[u])
            color = 0
            while color in neighbor_colors:
                color += 1
            coloring[v] = color
        return compact_colors(coloring)

    # Kempe chain swap: swap colors a and b in the component containing v
    def kempe_swap(coloring, v, a, b):
        # a and b are colors
        # Find connected component of v in subgraph induced by colors a and b
        stack = [v]
        visited = set()
        comp_a = set()  # vertices in component with color a
        comp_b = set()  # vertices in component with color b
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            cu = coloring[u]
            if cu == a:
                comp_a.add(u)
            elif cu == b:
                comp_b.add(u)
            else:
                continue  # should not happen if called correctly
            for w in adj_list[u]:
                if w not in visited:
                    cw = coloring[w]
                    if cw == a or cw == b:
                        stack.append(w)
        # Swap colors a<->b in the component
        for u in comp_a:
            coloring[u] = b
        for u in comp_b:
            coloring[u] = a
        return coloring

    # Try to eliminate the last color using Kempe chains or direct reassignment
    def reduce_colors(coloring):
        if not coloring:
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target_color = k - 1
        # Get vertices with target color
        target_vertices = [v for v in range(n) if coloring[v] == target_color]
        # Try each vertex in target color
        for v in target_vertices:
            # Try direct reassignment to a lower color
            used_by_neighbors = set()
            for u in adj_list[v]:
                cu = coloring[u]
                if cu < target_color:
                    used_by_neighbors.add(cu)
            for c in range(target_color):
                if c not in used_by_neighbors:
                    # Direct move possible
                    coloring[v] = c
                    # After moving v, check if target color class is empty
                    if target_color not in coloring:
                        # Compact and recurse
                        new_coloring = compact_colors(coloring)
                        return reduce_colors(new_coloring)
                    break
            else:
                # Direct move not possible, try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v is in a Kempe chain that can be swapped to free color c
                    # Temporarily swap and see if we can move v to c
                    # We'll simulate: if in the (c, target_color) component of v,
                    # after swapping, v becomes color c, and we check if no neighbor of v has color c
                    # Actually, after swap, v will have color c if it was target_color, or target_color if it was c.
                    # Since v is target_color, after swap it becomes c.
                    # We need to ensure that after swap, no neighbor of v has color c.
                    # But note: neighbors that were color c become target_color, and neighbors that were target_color become c.
                    # So we need to check: after swap, for each neighbor u of v:
                    #   if coloring[u] was c -> becomes target_color
                    #   if coloring[u] was target_color -> becomes c
                    # So v's new color is c. We need that no neighbor has color c after swap.
                    # That is: no neighbor u has (coloring[u] == c and after swap becomes target_color? no) 
                    # Actually, after swap:
                    #   if neighbor u had color c -> becomes target_color
                    #   if neighbor u had color target_color -> becomes c
                    # So v's new color is c. Conflict if any neighbor u has color c after swap, i.e., if neighbor u had color target_color before swap.
                    # So we need: no neighbor u of v has color target_color before swap? 
                    # But wait: if neighbor u had color target_color, after swap it becomes c, which would conflict with v's new color c.
                    # Therefore, to avoid conflict, we require that v has no neighbor with color target_color.
                    # However, if v has a neighbor with color target_color, then after swap that neighbor becomes c and conflicts.
                    # So we need to check the component: actually, the Kempe chain swap might change multiple vertices.
                    # The safe way: perform the swap and then check if v can be recolored to c without conflict, but note after swap v is already c.
                    # Instead, we do: swap the component, then check if coloring is valid and if v's color is c (it will be) and no conflict.
                    # But we must ensure we don't introduce conflicts elsewhere.
                    # Let's do the swap on a copy and check.
                    coloring_copy = coloring[:]
                    kempe_swap(coloring_copy, v, c, target_color)
                    # After swap, v should be color c (since it was target_color)
                    if coloring_copy[v] != c:
                        continue  # something wrong
                    # Check if valid
                    if is_valid(coloring_copy):
                        # Success: now check if target_color is still used
                        if target_color not in coloring_copy:
                            new_coloring = compact_colors(coloring_copy)
                            return reduce_colors(new_coloring)
                        else:
                            # Accept this swap and continue trying to eliminate target_color from other vertices
                            coloring = coloring_copy
                            break  # break out of Kempe loop, go to next target vertex (but we modified coloring, so restart?)
                else:
                    # Kempe swap succeeded and we broke out, continue to next target vertex with updated coloring
                    continue
                # If we didn't break from Kempe loop, continue to next c
            # If we broke from direct reassignment, we already returned or broke to outer loop?
            # Actually, in direct reassignment we broke and then checked if target_color not in coloring -> returned
            # So if we are here, direct reassignment didn't succeed or didn't lead to elimination
            # We'll continue to next target vertex
        # If we couldn't eliminate target_color, return current coloring
        return coloring

    # Run multiple heuristics
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # Time budget per heuristic: we have 50ms total, allocate roughly
    # But we'll just run them and hope they're fast enough for n<=100
    heuristics = [dsatur, rlf, smallest_last]
    for heuristic in heuristics:
        if time.time() - start_time > 0.04:  # leave some time for reduction
            break
        coloring = heuristic()
        if is_valid(coloring):
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring

    # If no heuristic produced valid coloring (shouldn't happen), fallback to greedy
    if best_coloring is None:
        # Simple greedy: order by degree descending
        order = sorted(range(n), key=lambda x: (-len(adj_list[x]), x))
        coloring = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best_coloring = compact_colors(coloring)

    # Apply color reduction via Kempe chains
    if time.time() - start_time < 0.045:
        best_coloring = reduce_colors(best_coloring)

    # Final validation and compaction
    if not is_valid(best_coloring):
        # As a last resort, use greedy with DSATUR order
        order = sorted(range(n), key=lambda x: (-len(adj_list[x]), x))
        coloring = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best_coloring = compact_colors(coloring)

    return best_coloring

