def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix or list
    if len(adj) > 0 and len(adj[0]) == len(adj) and all(
        isinstance(x, int) and x in (0, 1) for row in adj for x in row
    ):
        # Convert adjacency matrix to adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        # Already adjacency list
        graph = adj
        # Ensure symmetry for undirected graph
        for u in range(n):
            for v in graph[u]:
                if u not in graph[v]:
                    graph[v].append(u)

    # Convert adjacency list to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in graph[u]:
            bit_adj[u] |= (1 << v)

    def is_valid_coloring(colors):
        for u in range(n):
            for v in graph[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # Precompute degrees
        degrees = [len(graph[i]) for i in range(n)]
        # Track saturation sets as bitmasks
        saturation = [0] * n  # bitmask of colors used by neighbors
        colored = [False] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                sat = saturation[v].bit_count()
                deg = degrees[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Find smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            # Update saturation of neighbors
            for nb in graph[v]:
                if not colored[nb]:
                    saturation[nb] |= (1 << c)
        return compact_colors(colors)

    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build maximal independent set for color_idx
            # Start with vertex of max degree in uncolored subgraph
            # Compute degrees in uncolored subgraph
            deg_in_uncolored = {}
            for v in uncolored:
                # Count neighbors in uncolored
                cnt = 0
                for nb in graph[v]:
                    if nb in uncolored:
                        cnt += 1
                deg_in_uncolored[v] = cnt

            # Start with max degree vertex
            v = max(deg_in_uncolored, key=deg_in_uncolored.get) if deg_in_uncolored else None
            if v is None:
                break
            independent_set = {v}
            # Partition remaining uncolored into U (not adj to any in S) and W (adj to at least one in S)
            U = uncolored - {v}
            W = set()
            for nb in graph[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)

            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                best_w_neighbors = -1
                best_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors of u in W
                    w_nb = 0
                    for nb in graph[u]:
                        if nb in W:
                            w_nb += 1
                    # Degree in U
                    deg_u = 0
                    for nb in graph[u]:
                        if nb in U:
                            deg_u += 1
                    if w_nb > best_w_neighbors or (w_nb == best_w_neighbors and deg_u < best_deg_in_U):
                        best_w_neighbors = w_nb
                        best_deg_in_U = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in graph[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to independent set
            for node in independent_set:
                colors[node] = color_idx
                uncolored.remove(node)
            color_idx += 1
        return compact_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degrees = [len(graph[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use a list of sets for bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degrees[v]
            if d < len(buckets):
                buckets[d].add(v)
            else:
                # Extend buckets if needed (shouldn't happen as max_deg is computed)
                while len(buckets) <= d:
                    buckets.append(set())
                buckets[d].add(v)

        # Pointer to current min non-empty bucket
        min_bucket = 0
        for _ in range(n):
            # Find next non-empty bucket
            while min_bucket < len(buckets) and not buckets[min_bucket]:
                min_bucket += 1
            if min_bucket >= len(buckets):
                break  # should not happen
            v = buckets[min_bucket].pop()
            order.append(v)
            removed[v] = True
            # Decrease degree of neighbors
            for nb in graph[v]:
                if not removed[nb]:
                    d = degrees[nb]
                    if nb in buckets[d]:
                        buckets[d].remove(nb)
                    degrees[nb] -= 1
                    d_new = degrees[nb]
                    if d_new < len(buckets):
                        buckets[d_new].add(nb)
                    else:
                        while len(buckets) <= d_new:
                            buckets.append(set())
                        buckets[d_new].add(nb)
                    if d_new < min_bucket:
                        min_bucket = d_new

        # Color in reverse order using first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in graph[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                # Already compacted?
                return compact_colors(colors)
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for nb in graph[v]:
                    if colors[nb] != -1:
                        used_by_neighbors |= (1 << colors[nb])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Direct move possible
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart from highest color
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v can be swapped via Kempe chain (v, target_color) <-> (c)
                    # We'll do BFS/DFS for the Kempe chain of colors {target_color, c} starting from v
                    # Only consider vertices with color target_color or c
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if colors[node] == target_color or colors[node] == c:
                            component.add(node)
                            for nb in graph[node]:
                                if nb not in visited and (colors[nb] == target_color or colors[nb] == c):
                                    stack.append(nb)
                    # Check if any neighbor of v in the component has color c? Actually, we need to see
                    # if swapping the component would free color c for v.
                    # After swap, v would get color c. We need to ensure no neighbor of v has color c after swap.
                    # Neighbors of v that are in the component: if they have color c, they become target_color -> conflict?
                    # Actually, in the component, colors are only target_color and c.
                    # After swap: target_color becomes c, and c becomes target_color.
                    # So for a neighbor u of v:
                    #   If u in component and color[u] == c -> after swap becomes target_color -> not c (since v becomes c, and u becomes target_color, different)
                    #   If u in component and color[u] == target_color -> after swap becomes c -> same as v's new color -> conflict!
                    # Therefore, we can only swap if no neighbor of v in the component has color target_color.
                    # Because those would become c and conflict with v's new color c.
                    conflict = False
                    for nb in graph[v]:
                        if nb in component and colors[nb] == target_color:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            else:  # must be c
                                colors[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # Compact colors after change
                colors = compact_colors(colors)
                k = num_colors(colors)
        return colors

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (shouldn't happen), fallback to greedy
    if not candidates:
        colors = [0] * n
        for i in range(n):
            used = 0
            for nb in graph[i]:
                if colors[nb] != 0:  # only color 0 used so far
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        candidates.append(compact_colors(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid_coloring(best):
        # Fallback to simple greedy
        colors = [0] * n
        for i in range(n):
            used = 0
            for nb in graph[i]:
                if colors[nb] != 0:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        best = compact_colors(colors)
    else:
        best = compact_colors(best)

    return best

