        independent_set = {v}
        # U: vertices not adjacent to any in independent_set
        U = {u for u in uncolored if u != v and not (neighbors[u] & independent_set)}
        W = uncolored - independent_set - U
        while U:
            # select u in U with max |N(u) ∩ W|
            best_u = None
            best_score = -1
            for u in U:
                score = sum(1 for w in neighbors[u] if w in W)
                if score > best_score or (score == best_score and 
                                          (best_u is None or sum(1 for y in neighbors[u] if y in U) < sum(1 for y in neighbors[best_u] if y in U))):
                    best_score = score
                    best_u = u
            if best_u is None:
                break
            independent_set.add(best_u)
            U.remove(best_u)
            # move neighbors of best_u from U to W
            for w in list(neighbors[best_u] & U):
                U.remove(w)
                W.add(w)
        # assign color c to independent_set
        for v in independent_set:
            color[v] = c
        uncolored -= independent_set
        c += 1
    if is_valid(color):
        k = num_colors(color)
        if k < best_k:
            best_k = k
            best_coloring = color[:]

    # 3. Smallest-Last ordering (Matula & Beck)
    # compute degeneracy ordering
    degrees = [len(neighbors[i]) for i in range(n)]
    order = []
    remaining = set(range(n))
    # bucket sort by degree
    max_deg = max(degrees) if n > 0 else 0
    buckets = [[] for _ in range(max_deg + 1)]
    for v in range(n):
        buckets[degrees[v]].append(v)
    # maintain current degree
    curr_deg = degrees[:]
    for _ in range(n):
        # find first non-empty bucket from low to high
        d = 0
        while d <= max_deg and not buckets[d]:
            d += 1
        if d > max_deg:
            break
        v = buckets[d].pop()
        # skip if degree outdated
        if curr_deg[v] != d:
            # reinsert into correct bucket
            if curr_deg[v] <= max_deg:
                buckets[curr_deg[v]].append(v)
            continue
        order.append(v)
        remaining.remove(v)
        # update neighbors
        for u in neighbors[v]:
            if u in remaining:
                d_u = curr_deg[u]
                curr_deg[u] -= 1
                if d_u <= max_deg:
                    # remove u from bucket d_u (inefficient but ok for n<=100)
                    if u in buckets[d_u]:
                        buckets[d_u].remove(u)
                    if curr_deg[u] <= max_deg:
                        buckets[curr_deg[u]].append(u)
    # color in reverse order
    color = greedy_color(order[::-1])
    if is_valid(color):
        k = num_colors(color)
        if k < best_k:
            best_k = k
            best_coloring = color[:]

    # If no valid coloring found (should not happen), fallback to greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # 4. Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal best_k, best_coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # vertices with target_color
            verts = [v for v in range(n) if coloring[v] == target_color]
            if not verts:
                continue
            # try to recolor each vertex
            made_change = False
            for v in verts:
                # try direct reassignment to a lower color
                neighbor_colors = set()
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        neighbor_colors.add(c)
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # direct move possible
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue  # direct move not possible, but maybe Kempe chain
                    # find (target_color, c) Kempe chain containing v
                    # BFS over vertices colored target_color or c
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in neighbors[x]:
                            if y not in visited and (coloring[y] == target_color or coloring[y] == c):
                                visited.add(y)
                                queue.append(y)
                    # check if any neighbor of v in component has color c? 
                    # Actually, we want to see if we can swap without causing conflict
                    # Swapping is safe if no neighbor of v in the component has color c after swap?
                    # Standard: swapping colors in a Kempe chain preserves validity.
                    # We can swap if after swap, v gets color c and no conflict.
                    # Since component only has target_color and c, swapping will give v color c.
                    # Check if any neighbor of v has color c (outside component) -> would conflict after swap.
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c and u not in component:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            else:
                                coloring[x] = target_color
                        made_change = True
                        break
                if made_change:
                    break
            if not made_change:
                # cannot eliminate this color class, break
                break
            # compact colors: reindex
            # build mapping from old colors to new consecutive colors
            used_colors = set(coloring)
            mapping = {old: new for new, old in enumerate(sorted(used_colors))]
            for i in range(n):
                coloring[i] = mapping[coloring[i]]
        return coloring

    # Apply Kempe reduction to the best coloring found
    improved = kempe_reduce(best_coloring[:])
    if is_valid(improved):
        k_improved = num_colors(improved)
        if k_improved < best_k:
            best_k = k_improved
            best_coloring = improved

    # Final validation and compacting
    if not is_valid(best_coloring):
        # last resort: greedy by degree order
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        best_coloring = greedy_color(order)
    # ensure colors are consecutive starting from 0
    used = set(best_coloring)
    if used:
        mapping = {old: new for new, old in enumerate(sorted(used))]
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

