def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or list
    if len(adj[0]) == n and all(all(x in (0, 1) for x in row) for row in adj):
        # Adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
    else:
        # Adjacency list
        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], sum(1 for u in range(n) if (bit_adj[x] >> u) & 1 and u in uncolored)))
            # Compute used colors from colored neighbors
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in uncolored:
                    sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in range(n) if (bit_adj[x] >> u) & 1 and u in uncolored))
            S.add(v)
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if not any((bit_adj[u] >> w) & 1 for w in S)}
            W = uncolored - U
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U
                u_star = max(U, key=lambda x: (sum(1 for w in range(n) if (bit_adj[x] >> w) & 1 and w in W), -sum(1 for uu in range(n) if (bit_adj[x] >> uu) & 1 and uu in U)))
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                nbrs = {uu for uu in range(n) if (bit_adj[u_star] >> uu) & 1 and uu in U}
                U -= nbrs
                W |= nbrs
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
            uncolored = W  # Next iteration colors the W set
        return color

    # Helper: Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [0] * n
        for i in range(n):
            degree[i] = bin(bit_adj[i]).count("1")
        order = []
        while remaining:
            v = min(remaining, key=lambda x: degree[x])
            order.append(v)
            remaining.remove(v)
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    degree[u] -= 1
        # Color in reverse order
        return greedy_color(reversed(order))

    # Helper: Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(color, a, b, v):
        # Find the Kempe chain component of v for colors a and b
        stack = [v]
        visited = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            for w in range(n):
                if (bit_adj[u] >> w) & 1 and color[w] in (a, b) and w not in visited:
                    stack.append(w)
        # Swap colors a and b in the component
        for u in visited:
            if color[u] == a:
                color[u] = b
            elif color[u] == b:
                color[u] = a
        return color

    # Helper: try to eliminate the smallest color class via Kempe or reassignment
    def reduce_colors(color):
        # Map colors to compact range if needed
        unique = sorted(set(color))
        if unique == list(range(len(unique))):
            mapping = {c: i for i, c in enumerate(unique)}
            color = [mapping[c] for c in color]
        else:
            # Already compact? ensure
            mapping = {c: i for i, c in enumerate(sorted(set(color)))}
            color = [mapping[c] for c in color]
        k = max(color) + 1 if n > 0 else 0
        if k <= 1:
            return color
        # Try to eliminate color k-1
        target = k - 1
        target_vertices = [v for v in range(n) if color[v] == target]
        # Try direct reassignment first
        for v in target_vertices:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1:
                    used |= (1 << color[u])
            for c in range(target):
                if not (used & (1 << c)):
                    color[v] = c
                    break
        # Recompute target vertices after direct moves
        target_vertices = [v for v in range(n) if color[v] == target]
        if not target_vertices:
            # Successfully eliminated target color, compact
            return [c if c < target else c - 1 for c in color]
        # Try Kempe chains for each target vertex
        for v in target_vertices:
            for c in range(target):
                # Check if v can be recolored to c via Kempe swap (a=target, b=c)
                # Only if swapping does not introduce conflict (i.e., no neighbor of v has color c after swap)
                # Actually, Kempe swap preserves validity; we just need to ensure that after swap, v gets color c
                # Simulate: after swap, v will have color c if it is in the a-b component and we swap
                # But we can just attempt swap and see if v ends up with color c
                # Copy color for trial
                color_trial = color[:]
                kempe_swap(color_trial, target, c, v)
                if color_trial[v] == c:
                    # Accept the swap
                    color = color_trial
                    break
            else:
                continue
            break
        else:
            # No Kempe swap worked for any vertex; cannot reduce
            return color
        # Recurse to try further reduction
        return reduce_colors(color)

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda c: max(c) + 1 if n > 0 else 0)

    # Apply Kempe chain reduction to try to improve
    best = reduce_colors(best)

    # Final validation and compacting
    unique = sorted(set(best))
    if unique != list(range(len(unique))):
        mapping = {c: i for i, c in enumerate(unique)}
        best = [mapping[c] for c in best]

    # Verify correctness (optional, can be removed for speed)
    # for u in range(n):
    #     for v in range(n):
    #         if (bit_adj[u] >> v) & 1 and best[u] == best[v]:
    #             raise ValueError(f"Invalid coloring: edge ({u},{v}) monochromatic")
    return best

