            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v} - set(adj_list[v])
            W = set(adj_list[v]) & uncolored
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                def score(u):
                    w_count = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_count += 1
                    # degree in U
                    u_deg = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            u_deg += 1
                    return (w_count, -u_deg, random.random())
                u = max(U, key=score)
                S.add(u)
                U.remove(u)
