        while uncolored:
            # Build independent set for current_color
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nbr in adj_list[x] if nbr in uncolored))
            independent_set.add(v)
            # Partition uncolored - {v} into U (not adj to any in S) and W (adj to at least one in S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(nbr in independent_set for nbr in adj_list[u]):
                    W.add(u)
                    U.remove(u)
            # While U not empty, add vertex with max neighbors in W, tie-break by min degree in U
            while U:
                # select u in U maximizing |N(u) ∩ W|, tie-break by min degree in U (then index)
                u = max(U, key=lambda x: (sum(1 for nbr in adj_list[x] if nbr in W), -sum(1 for nbr in adj_list[x] if nbr in U), -x))
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nbr in adj_list[u]:
                    if nbr in U:
                        U.remove(nbr)
                        W.add(nbr)
            # assign color to independent_set
            for v in independent_set:
                color[v] = current_color
            uncolored -= independent_set
            current_color += 1
        return color

    # ---------- Heuristic 3: Smallest-Last ordering (Matula-Beck) ----------
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []  # removal order
        # We'll use a list of sets for buckets by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            buckets[d].add(v)
        # Pointer to current min non-empty bucket
        min_deg = 0
        while remaining:
            # find min_deg with non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    buckets[d_new].add(u)
                    if d_new < min_deg:
                        min_deg = d_new
        # color in reverse removal order
        return greedy_color(order[::-1])

    # ---------- Kempe chain swap for two colors ----------
    def kempe_swap(color, a, b, v):
        """Attempt to swap colors a and b in the component containing v.
        Returns new color list if swap is valid and changes something, else None."""
        # BFS to get the (a,b)-Kempe component of v
        from collections import deque
        comp = set()
        queue = deque([v])
        while queue:
            node = queue.popleft()
            if node in comp:
                continue
            comp.add(node)
            for nbr in adj_list[node]:
                if nbr not in comp and color[nbr] in (a, b):
                    queue.append(nbr)
        # Check if swapping is valid: for any edge within comp, colors remain different
        # Since we only swap a and b, and edges within comp are between a and b, after swap they remain different.
        # For edges from comp to outside: if outside node has color a or b, after swap it might conflict.
        # Actually, we need to ensure that no neighbor outside comp has color that would conflict after swap.
        # But standard Kempe swap: swapping a and b in a component preserves validity because:
        #   - Inside comp: edges were a-b, become b-a -> still different.
        #   - Between comp and outside: if outside node has color c not in {a,b}, no change.
        #                                 if outside node has color a, then it cannot be adjacent to any node in comp colored b (because if it were, that node would be in comp), similarly for b.
        # So it is always valid. We can swap without checking.
        new_color = color[:]
        for node in comp:
            if new_color[node] == a:
                new_color[node] = b
            else:
                new_color[node] = a
        return new_color

    # ---------- Try to eliminate a color class using Kempe chains ----------
    def reduce_colors(color):
        # Make color indices consecutive
        unique_colors = sorted(set(color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        color = [mapping[c] for c in color]
        k = len(unique_colors)
        if k <= 1:
            return color

        # Try to remove the highest color class (k-1) iteratively
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # vertices with target color
            targets = [v for v in range(n) if color[v] == target_color]
            # Try each vertex in target color
            for v in targets:
                # Try direct reassignment to a lower color
                used = [False] * k
                for u in adj_list[v]:
                    c = color[u]
                    if c < k:
                        used[c] = True
                for c in range(k):
                    if not used[c]:
                        # reassign v to color c
                        color[v] = c
                        improved = True
                        break
                if improved:
                    # after reassignment, we may have gaps; reindex
                    unique_colors = sorted(set(color))
                    mapping = {old: new for new, old in enumerate(unique_colors)}
                    color = [mapping[c] for c in color]
                    k = len(unique_colors)
                    break
                # Try Kempe swaps with each lower color
                for c in range(target_color):
                    # Try to swap colors target_color and c in the component of v
                    # This will change v's color to c if v is in the target_color part of the component
                    swapped = kempe_swap(color, target_color, c, v)
                    if swapped is not None:
                        # Check if v's color changed to c (i.e., we effectively moved v to color c)
                        if swapped[v] == c:
                            color = swapped
                            improved = True
                            # reindex
                            unique_colors = sorted(set(color))
                            mapping = {old: new for new, old in enumerate(unique_colors)}
                            color = [mapping[c] for c in color]
                            k = len(unique_colors)
                            break
                if improved:
                    break
            # If we couldn't remove the whole class, break
        return color

    # ---------- Run all heuristics and pick best ----------
    best_color = None
    best_k = float('inf')

    for heuristic in [dsatur, rlf, smallest_last]:
        try:
            col = heuristic()
            # Validate
            valid = True
            for u in range(n):
                for v in adj_list[u]:
                    if u < v and color[u] == color[v]:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue
            # Make colors consecutive
            unique = sorted(set(col))
            mapping = {old: new for new, old in enumerate(unique)}
            col = [mapping[c] for c in col]
            k = len(unique)
            if k < best_k:
                best_k = k
                best_color = col
        except Exception:
            continue

    # Fallback: greedy by degree order
    if best_color is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best_color = greedy_color(order)
        unique = sorted(set(best_color))
        mapping = {old: new for new, old in enumerate(unique)}
        best_color = [mapping[c] for c in best_color]

    # Final reduction attempt
    best_color = reduce_colors(best_color)

    return best_color

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Colors a graph using a hybrid heuristic approach combining DSATUR, RLF, and Kempe chain refinement.
    Aims to find the minimum number of colors (chromatic number) within a strict time budget.
    """
    start_time = time.perf_counter()
    time_limit = 0.05  # 50 milliseconds

    # Helper to check if we are out of time
    def time_up():
        return (time.perf_counter() - start_time) >= time_limit

    # --- Input Processing and Graph Representation ---
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj[0]) == n:
        is_all_binary = True
        for row in adj:
            if len(row) != n:
                is_all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    is_all_binary = False
                    break
            if not is_all_binary:
                break
        if is_all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representations for efficiency
    adj_list = [[] for _ in range(n)]
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
    else:
        # Assume it's already an adjacency list
        for u in range(n):
            # Ensure no self-loops and deduplicate just in case
            neighbors = set()
            for v in adj[u]:
                if v != u:
                    neighbors.add(v)
            adj_list[u] = sorted(list(neighbors))

    # Precompute degree and neighbor bitmasks for fast operations
    degree = [len(adj_list[u]) for u in range(n)]
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper to get uncolored neighbors as a bitmask
    def uncolored_neighbors_mask(u, colored_mask):
        return bit_adj[u] & ~colored_mask

    # Helper to count bits (saturation degree, etc.)
    def bit_count(x):
        return x.bit_count()

    # --- Coloring Algorithms ---

    def dsatur():
        """DSATUR algorithm with degree tie-breaking."""
        if time_up():
            return None
        colors = [-1] * n
        colored_mask = 0  # Bitmask of colored vertices
        # Saturation: list of sets, saturation[v] = set of colors used by colored neighbors
        saturation = [set() for _ in range(n)]

        # Order vertices by initial degree for tie-breaking in saturation
        vertices_by_degree = sorted(range(n), key=lambda x: degree[x], reverse=True)

        for _ in range(n):
            if time_up():
                return None
            # Select uncolored vertex with max saturation, tie-break by degree
            candidates = []
            max_sat = -1
            for v in range(n):
                if colors[v] == -1:
                    sat_v = len(saturation[v])
                    if sat_v > max_sat:
                        max_sat = sat_v
                        candidates = [v]
                    elif sat_v == max_sat:
                        candidates.append(v)
            # Tie-break: max degree in the uncolored subgraph
            if not candidates:
                break  # Should not happen
            best_v = -1
            max_deg_uncolored = -1
            for v in candidates:
                # Count uncolored neighbors
                deg_uncolored = bit_count(uncolored_neighbors_mask(v, colored_mask))
                if deg_uncolored > max_deg_uncolored:
                    max_deg_uncolored = deg_uncolored
                    best_v = v
                elif deg_uncolored == max_deg_uncolored:
                    if degree[v] > degree[best_v]:  # Secondary tie-break by original degree
                        best_v = v
            v = best_v

            # Find smallest available color (Mex)
            used_colors = saturation[v]
            c = 0
            while c in used_colors:
                c += 1
            colors[v] = c
            colored_mask |= (1 << v)

            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if colors[u] == -1:
                    saturation[u].add(c)
        return colors

    def rlf():
        """Recursive Largest First (RLF) algorithm."""
        if time_up():
            return None
        colors = [-1] * n
        colored_mask = 0
        color_idx = 0

        while colored_mask != (1 << n) - 1:  # While there are uncolored vertices
            if time_up():
                return None
            # Step 1: Pick vertex with max degree in the uncolored subgraph
            uncolored_mask = ~colored_mask & ((1 << n) - 1)
            best_v = -1
            max_deg_uncolored = -1
            for v in range(n):
                if (uncolored_mask >> v) & 1:
                    deg_uncolored = bit_count(uncolored_neighbors_mask(v, colored_mask))
                    if deg_uncolored > max_deg_uncolored:
                        max_deg_uncolored = deg_uncolored
                        best_v = v
                    elif deg_uncolored == max_deg_uncolored:
                        if degree[v] > degree[best_v]:
                            best_v = v
            if best_v == -1:  # No uncolored vertices left (should be caught by while condition)
                break

            # Start new color class (independent set) with best_v
            independent_set = 1 << best_v
            # U: vertices not adjacent to any in S (eligible for this color)
            # W: vertices adjacent to at least one in S (ineligible for this color)
            S_mask = independent_set
            W_mask = bit_adj[best_v] & uncolored_mask
            U_mask = uncolored_mask & ~(S_mask | W_mask)

            # Step 4: While U is not empty, add vertices to S
            while U_mask != 0:
                if time_up():
                    return None
                # Select u* in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                u_mask = U_mask
                while u_mask:
                    u = (u_mask & -u_mask).bit_length() - 1
                    u_mask &= u_mask - 1  # Remove lowest set bit
                    w_neighbors = bit_count(bit_adj[u] & W_mask)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in G[U]
                        deg_u = bit_count(bit_adj[u] & U_mask)
                        deg_best = bit_count(bit_adj[best_u] & U_mask) if best_u != -1 else float('inf')
                        if deg_u < deg_best or (deg_u == deg_best and u < best_u):
                            best_u = u
                if best_u == -1:
                    break  # Should not happen if U_mask != 0

                # Add best_u to S, move its neighbors from U to W
                independent_set |= (1 << best_u)
                S_mask |= (1 << best_u)
                # Neighbors of best_u that are currently in U become part of W
                neighbors_in_U = bit_adj[best_u] & U_mask
                W_mask |= neighbors_in_U
                U_mask &= ~neighbors_in_U
                U_mask &= ~(1 << best_u)  # Remove best_u from U

            # Assign color to all vertices in the independent set
            mask = independent_set
            while mask:
                v = (mask & -mask).bit_length() - 1
                mask &= mask - 1
                colors[v] = color_idx
            colored_mask |= independent_set
            color_idx += 1

        return colors

    def smallest_last_greedy():
        """Greedy coloring using smallest-last ordering."""
        if time_up():
            return None
        # Step 1: Compute smallest-last ordering (peel min degree vertices)
        remaining = set(range(n))
        order = []  # Will store vertices in order of removal (first removed first)
        deg = degree[:]  # Current degrees in the remaining subgraph
        # Adjacency sets for efficient degree updates
        adj_set = [set(adj_list[u]) for u in range(n)]

        for _ in range(n):
            if time_up():
                return None
            # Find vertex with minimum degree in remaining
            min_v = -1
            min_deg = float('inf')
            for v in remaining:
                if deg[v] < min_deg:
                    min_deg = deg[v]
                    min_v = v
                elif deg[v] == min_deg and v < min_v:
                    min_v = v
            if min_v == -1:
                break  # No vertices left
            order.append(min_v)
            remaining.remove(min_v)
            # Update degrees of neighbors
            for u in adj_list[min_v]:
                if u in remaining:
                    deg[u] -= 1

        # Step 2: Color in reverse order (last removed first) using First-Fit
        colors = [-1] * n
        for v in reversed(order):
            if time_up():
                return None
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    # --- Run all heuristics and collect candidates ---
    candidates = []
    for algo in [dsatur, rlf, smallest_last_greedy]:
        if time_up():
            break
        res = algo()
        if res is not None:
            candidates.append(res)

    # Fallback: if no heuristic completed (unlikely but possible), use a simple greedy
    if not candidates:
        colors = [-1] * n
        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        for v in order:
            if time_up():
                break
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        candidates.append(colors)

    # Select the best candidate (fewest colors)
    best_colors = None
    best_num_colors = float('inf')
    for cols in candidates:
        if time_up():
            break
        num_colors = len(set(cols)) if cols else 0
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_colors = cols

    if best_colors is None:
        best_colors = candidates[0] if candidates else [0] * n

    # --- Kempe Chain Refinement to reduce color count ---
    def kempe_reduce(cols):
        """Attempt to reduce the number of colors using Kempe chain swaps."""
        if time_up():
            return cols
        # Work with a copy to avoid modifying original if we fail
        colors = cols[:]
        k = len(set(colors))
        if k <= 1:
            return colors

        # Precompute color classes for efficiency
        color_classes = [set() for _ in range(k)]
        for v in range(n):
            c = colors[v]
            color_classes[c].add(v)

        # Try to eliminate the last color (k-1) iteratively
        target_color = k - 1
        while target_color > 0 and not time_up():
            if not color_classes[target_color]:
                # This color is already empty, compact and try next
                # Remap colors: shift down all colors > target_color
                new_colors = [-1] * n
                for v in range(n):
                    c = colors[v]
                    if c > target_color:
                        new_colors[v] = c - 1
                    elif c == target_color:
                        # Should not happen if set is empty, but skip
                        pass
                    else:
                        new_colors[v] = c
                colors = new_colors
                k -= 1
                target_color = k - 1
                # Rebuild color classes
                color_classes = [set() for _ in range(k)]
                for v in range(n):
                    c = colors[v]
                    color_classes[c].add(v)
                continue

            made_progress = False
            # Try to recolor each vertex in the target color class
            for v in list(color_classes[target_color]):  # Iterate over a copy
                if time_up():
                    break
                # Step 1: Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if colors[u] != -1:
                        neighbor_colors.add(colors[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Found a free color, reassign v
                        color_classes[target_color].remove(v)
                        colors[v] = c
                        color_classes[c].add(v)
                        made_progress = True
                        break
                if made_progress:
                    continue  # Move to next vertex in target class

                # Step 2: Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    if time_up():
                        break
                    # Check if v is adjacent to any vertex of color c (would cause conflict if swapped directly)
                    has_neighbor_of_color_c = any(colors[u] == c for u in adj_list[v])
                    if has_neighbor_of_color_c:
                        continue  # Cannot swap directly; Kempe chain might still help

                    # Find the Kempe chain component of v in colors {target_color, c}
                    # We'll do BFS to find the component containing v
                    from collections import deque
                    queue = deque([v])
                    visited = {v}
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for nb in adj_list[node]:
                            if colors[nb] in (target_color, c) and nb not in visited:
                                visited.add(nb)
                                queue.append(nb)
                    # Check if swapping this component is safe:
                    # After swap, vertices in component that were target_color become c, and vice versa.
                    # We need to ensure no vertex in the component that becomes c is adjacent to a vertex
                    # outside the component that is already c (to avoid conflict).
                    safe = True
                    for node in component:
                        if colors[node] == target_color:  # Will become c
                            for nb in adj_list[node]:
                                if nb not in component and colors[nb] == c:
                                    safe = False
                                    break
                            if not safe:
                                break
                    if safe:
                        # Perform the swap: target_color <-> c in the component
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            else:  # must be c
                                colors[node] = target_color
                        # Update color classes
                        color_classes[target_color] -= component
                        color_classes[c] |= component
                        made_progress = True
                        break  # Break from color loop, restart vertex loop as classes changed
                if made_progress:
                    break  # Break from vertex loop to restart with updated classes

            if not made_progress:
                # Could not eliminate this color class, move to next lower target
                target_color -= 1

        # Compact colors to ensure they are 0..k-1 without gaps
        # Map existing colors to a dense set
        unique_colors = sorted(set(colors))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        final_colors = [mapping[c] for c in colors]
        return final_colors

    # Apply Kempe reduction to the best candidate
    if not time_up():
        best_colors = kempe_reduce(best_colors)

    # Final validation and cleanup (ensure 0-indexed and valid)
    # Verify it's a proper coloring
    is_valid = True
    for u in range(n):
        for v in adj_list[u]:
            if u < v and colors[u] == colors[v]:  # Check each edge once
                is_valid = False
                break
        if not is_valid:
            break

    # If invalid, fallback to a simple greedy (should not happen with our heuristics)
    if not is_valid:
        colors = [-1] * n
        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        for v in order:
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c

    # Ensure colors are renumbered to be consecutive from 0
    unique_colors = sorted(set(colors))
    if unique_colors != list(range(len(unique_colors))):
        mapping = {old: new for new, old in enumerate(unique_colors)}
        colors = [mapping[c] for c in colors]

    return colors

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build neighbor sets
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for v in adj[i]:
                if 0 <= v < n:
                    neighbors[i].add(v)
    # Ensure undirected (though input should be)
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)
    # Helper: compute degree in a set of vertices
    def degree_in_set(v, vertex_set):
        return len(neighbors[v] & vertex_set)
    # DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor colors as sets for fast update
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))
        # order by degree descending for tie-breaking
        degrees = [len(neighbors[i]) for i in range(n)]
        while uncolored:
            # select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (saturation[x], degrees[x], random.random()))
            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and neighbor colors for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1
        return color
    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: degree_in_set(x, uncolored))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v} - (neighbors[v] & uncolored)
            W = (neighbors[v] & uncolored)
