            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    if d < len(buckets):
                        buckets[d].append(u)
                    if deg[u] < ptr:
                        ptr = deg[u]
        # Color in reverse order
        return greedy_color(reversed(order))

