                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            # Sort colors by class size (smallest first)
            sorted_colors = sorted(classes.keys(), key=lambda x: len(classes[x]))
            # Try to eliminate each color class from smallest up
            for color_k in sorted_colors:
                if color_k >= max(col) + 1:  # skip if already beyond current max
                    continue
                if not classes.get(color_k):
                    continue
                # Try to recolor each vertex in this class
                for v in classes[color_k]:
