                            used |= (1 << col[u])
                    for c in range(color_k):  # only try colors < color_k
                        if not (used & (1 << c)):
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chains with each lower color
                    for c in range(color_k):
                        # Find the (color_k, c)-Kempe chain containing v
                        # BFS to get component
                        from collections import deque
                        comp = set()
