    def is_valid_coloring(color):
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(color):
        if not color:
            return 0
        return max(color) + 1

    # Helper: get saturation degree of a vertex given current coloring
    def saturation_degree(v, color):
        mask = 0
        for u in adj_list[v]:
            c = color[u]
            if c != -1:
                mask |= (1 << c)
        return mask.bit_count()

