    def uncolored_degree(v, color):
        deg = 0
        for u in adj_list[v]:
            if color[u] == -1:
                deg += 1
        return deg

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Order vertices by initial degree descending for tie-breaking in saturation
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        # We'll use a list to track uncolored vertices
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by max degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation_degree(v, color)
                deg = uncolored_degree(v, color)
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
