        while uncolored:
            # Build independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: uncolored_degree(x, color))
                S.append(v)
                uncolored.remove(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set(uncolored)  # copy
            W = set()
            # Initial partition: move neighbors of S from U to W
            for u in S:
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
