        best_color = dsatur()
        unique_colors = sorted(set(best_color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_color = [mapping[c] for c in best_color]

    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    if len(adj) > 0 and len(adj[0]) == len(adj) and all(all(x in (0, 1) for x in row) for row in adj):
        # Adjacency matrix
        neighbors = [ [j for j, val in enumerate(row) if val] for row in adj ]
    else:
        # Adjacency list
        neighbors = adj

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg = [bit_count(bit_adj[u]) for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for u in uncolored:
                s = bit_count(sat[u])
                d = deg[u]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best = u
                    best_sat = s
                    best_deg = d
            u = best
            uncolored.remove(u)

            # Find smallest available color
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c

            # Update saturation and degree for uncolored neighbors
            for v in neighbors[u]:
                if v in uncolored:
                    sat[v] |= (1 << c)
                    deg[v] -= 1
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            deg_uncolored = {}
            for u in uncolored:
                # count neighbors in uncolored
                mask = bit_adj[u] & sum((1 << v) for v in uncolored)
                deg_uncolored[u] = bit_count(mask)
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            independent_set = {v}
            to_remove = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to independent_set (ineligible)
            U = uncolored - {v}
            W = set()
            # Initial W: neighbors of v in uncolored
            for u in list(U):
                if bit_adj[v] & (1 << u):
                    W.add(u)
                    U.remove(u)

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    mask = 0
                    for w in W:
                        if bit_adj[u] & (1 << w):
                            mask |= (1 << w)
                    score = bit_count(mask)
                    # degree in U
                    deg_u = bit_count(bit_adj[u] & sum((1 << v) for v in U))
                    if score > best_score or (score == best_score and deg_u < best_deg_in_U) or (score == best_score and deg_u == best_deg_in_U and random.random() < 0.5):
                        best_u = u
                        best_score = score
                        best_deg_in_U = deg_u
                u = best_u
                independent_set.add(u)
                to_remove.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in list(U):
                    if bit_adj[u] & (1 << w):
                        W.add(w)
                        U.remove(w)
            # Assign color c to independent_set
            for u in independent_set:
                color[u] = c
            uncolored -= to_remove
            c += 1
        return color

    # Helper: Smallest-Last ordering ( degeneracy ordering )
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [bit_count(bit_adj[u]) for u in range(n)]
        order = []
        remaining = set(range(n))
        # We'll simulate removal
        current_deg = deg[:]
        for _ in range(n):
            # find vertex with min current degree
            v = min(remaining, key=lambda x: current_deg[x])
            order.append(v)
            remaining.remove(v)
            # decrease degree of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    current_deg[u] -= 1
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Also try Welsh-Powell (sort by degree descending)
    order_wp = sorted(range(n), key=lambda x: bit_count(bit_adj[x]), reverse=True)
    candidates.append(greedy_color(order_wp))

    # Try random orders a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=num_colors)

    # Kempe chain-based color reduction
    def try_reduce_color(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            verts = [u for u in range(n) if coloring[u] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            made_change = False
            for v in verts:
                used_by_neighbors = 0
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        used_by_neighbors |= (1 << coloring[u])
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Skip if neighbor already has color c (would cause conflict if we try to pull)
                    has_c_neighbor = any(coloring[u] == c for u in neighbors[v])
                    if has_c_neighbor:
                        continue
                    # Build Kempe chain for colors (target_color, c) starting from v
                    # We want to see if we can swap a component that doesn't pull v's color class members
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        u = stack.pop()
                        if u in visited:
                            continue
                        visited.add(u)
                        if coloring[u] == target_color or coloring[u] == c:
                            component.add(u)
                            for w in neighbors[u]:
                                if w not in visited and (coloring[w] == target_color or coloring[w] == c):
                                    stack.append(w)
                    # Check if any neighbor of v in the component has color c (would cause conflict if swapped)
                    conflict = False
                    for u in component:
                        for w in neighbors[u]:
                            if w in component and coloring[w] == c and u == v:  # only care about v getting color c
                                # Actually, we need to check if after swap, v would conflict
                                # After swap, v gets color c if it was target_color
                                if coloring[v] == target_color and coloring[w] == c:
                                    conflict = True
                                    break
                        if conflict:
                            break
                    if not conflict:
                        # Perform swap on the component
                        for u in component:
                            if coloring[u] == target_color:
                                coloring[u] = c
                            elif coloring[u] == c:
                                coloring[u] = target_color
                        made_change = True
                        break
                if made_change:
                    break
            if not made_change:
                # Could not eliminate this color class, try next lower
                continue
            else:
                # Successfully recolored at least one vertex, restart reduction from highest color
                return try_reduce_color(coloring)
        # Compact colors: remap to 0..k'-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # Apply reduction
    best_coloring = try_reduce_color(best_coloring[:])  # work on a copy

    # Final validation (should be valid by construction)
    if not is_valid(best_coloring):
        # Fallback to DSATUR if something went wrong
        best_coloring = dsatur()

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if adj is an adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Build bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Complement graph adjacency as bitmasks
    full_mask = (1 << n) - 1
    comp_adj = [0] * n
    for u in range(n):
        comp_adj[u] = full_mask ^ bit_adj[u] ^ (1 << u)  # exclude self

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR on original graph
    try:
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[u]) for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u].bit_count()
                deg_u = uncolored_deg[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        k = count_colors(color)
        if k < best_k:
            best_k = k
            best_coloring = color[:]
    except Exception:
        pass

    # Strategy 2: RLF (Recursive Largest First)
    try:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # degree in uncolored subgraph
            deg = {u: 0 for u in uncolored}
            for u in uncolored:
                for v in adj_list[u]:
                    if v in uncolored:
                        deg[u] += 1
            # start with vertex of max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to S, W: adjacent to S
            U = uncolored - {v} - set(adj_list[v])
            W = set(adj_list[v]) & uncolored
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    deg_u = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_u += 1
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or \
                       (w_neighbors == max_w_neighbors and deg_u == min_deg_u and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        k = count_colors(color)
        if k < best_k:
            best_k = k
            best_coloring = color[:]
    except Exception:
        pass

    # Strategy 3: Smallest-Last ordering
    try:
        # compute degeneracy ordering
        deg = [len(adj_list[u]) for u in range(n)]
        order = []
        remaining = set(range(n))
        for _ in range(n):
            # vertex with min degree
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            for nb in adj_list[v]:
                if nb in remaining:
                    deg[nb] -= 1
        # color in reverse order
        color = greedy_color(order[::-1])
        k = count_colors(color)
        if k < best_k:
            best_k = k
            best_coloring = color[:]
    except Exception:
        pass

    # Strategy 4: Greedy on complement (clique heuristic)
    try:
        # In complement graph, find maximal cliques greedily -> independent sets in original
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # start with vertex of max degree in complement (min degree in original)
            deg_comp = {u: 0 for u in uncolored}
            for u in uncolored:
                # neighbors in complement within uncolored
                mask = comp_adj[u]
                # count bits in mask that are in uncolored
                cnt = 0
                # iterate over uncolored set to avoid constructing large temp set
                for v in uncolored:
                    if mask & (1 << v):
                        cnt += 1
                deg_comp[u] = cnt
            v = max(uncolored, key=lambda x: deg_comp[x])
            # build clique greedily: start with v, add vertices adjacent to all in clique
            clique = {v}
            candidates = uncolored - {v}
            # filter candidates: must be adjacent to v in complement
            candidates = {u for u in candidates if comp_adj[v] & (1 << u)}
            while candidates:
                # select vertex that is adjacent to most in current clique (should be all if clique property)
                # but we maintain: a vertex u is added if it is adjacent to all vertices in clique
                # so we filter: u such that for all w in clique, (u,w) in complement
                # Since we built clique to be a clique, we just need u adjacent to all in clique
                # To be efficient, we maintain the common neighbors
                # Instead, we can recompute: u is candidate if it is adjacent to all in clique
                new_candidates = set()
                for u in candidates:
                    ok = True
                    for w in clique:
                        if not (comp_adj[u] & (1 << w)):
                            ok = False
                            break
                    if ok:
                        new_candidates.add(u)
                if not new_candidates:
                    break
                # choose u with max degree in complement among new_candidates
                u = max(new_candidates, key=lambda x: deg_comp[x])
                clique.add(u)
                candidates = new_candidates - {u}
            # assign color c to clique (independent set in original)
            for u in clique:
                color[u] = c
            uncolored -= clique
            c += 1
        k = count_colors(color)
        if k < best_k:
            best_k = k
            best_coloring = color[:]
    except Exception:
        pass

    # If no strategy succeeded, fallback to simple greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # try to remove the highest color class
            max_color = max(col) if col else -1
            if max_color <= 0:
                break
            # vertices with color max_color
            targets = [u for u in range(n) if col[u] == max_color]
            if not targets:
                # should not happen, but safety
                break
            # try to recolor each target to a lower color
            for v in targets:
                # try direct reassignment to lower color
                for c in range(max_color):
                    # check if color c is available
                    conflict = False
                    for u in adj_list[v]:
                        if col[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart scanning from highest color
                # try Kempe chains with each lower color
                for c in range(max_color):
                    # consider (c, max_color) Kempe chain
                    # if v is not in a component that can be swapped to free c for v
                    # We do BFS to find the Kempe component of v in colors {c, max_color}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in adj_list[u]:
                            if not visited[w] and (col[w] == c or col[w] == max_color):
                                visited[w] = True
                                queue.append(w)
                    # check if any neighbor of v has color c (in original coloring)
                    # if not, we can swap the component
                    has_c_neighbor = False
                    for u in adj_list[v]:
                        if col[u] == c:
                            has_c_neighbor = True
                            break
                    if not has_c_neighbor:
                        # swap colors c and max_color in component
                        for u in component:
                            if col[u] == c:
                                col[u] = max_color
                            elif col[u] == max_color:
                                col[u] = c
                        changed = True
                        break
                if changed:
                    break
            # if we made a change, restart the while loop to try again on possibly new max color
        # compact colors: remap to 0..k-1
        # but first, validate
        for u in range(n):
            for v in adj_list[u]:
                if col[u] == col[v]:
                    # invalid, return original
                    return coloring
        # remap
        unique_colors = {}
        next_color = 0
        for u in range(n):
            c = col[u]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            col[u] = unique_colors[c]
        return col

    best_coloring = kempe_reduction(best_coloring)

    # Final validation and compacting (should already be compact)
    # Validate
    for u in range(n):
        for v in adj_list[u]:
            if best_coloring[u] == best_coloring[v]:
                # Fallback to greedy if invalid
                best_coloring = greedy_color(list(range(n)))
                break
        else:
            continue
        break

    # Compact colors
    mapping = {}
    next_c = 0
    for i in range(n):
        c = best_coloring[i]
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
        best_coloring[i] = mapping[c]

    return best_coloring

