    # Determine if input is adjacency matrix or list
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= (1 << j)
    else:
        # Adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    bit_adj[u] |= (1 << v)

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree: number of distinct colors in neighbors
        neighbor_colors = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        # Precompute degrees for tie-breaking
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], degrees[x], random.random()))
            # Find smallest available color (mex)
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation and neighbor colors for uncolored neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in uncolored:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # Degrees in the subgraph induced by uncolored
            deg_uncolored = [0] * n
            for u in uncolored:
                deg_uncolored[u] = bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1')
            if not uncolored:
                break
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (deg_uncolored[x], random.random()))
            S.append(v)
            # Partition U (eligible) and W (ineligible)
            U = uncolored - {v}
            W = set()
            for u in U:
                if bit_adj[v] & (1 << u):
                    W.add(u)
                else:
                    # u is eligible
                    pass
            # Actually, U should be vertices not adjacent to any in S
            U = {u for u in uncolored if all((bit_adj[s] & (1 << u)) == 0 for s in S)}
            W = uncolored - U - set(S)
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U subgraph
                def score(u):
                    # neighbors in W
                    w_count = bin(bit_adj[u] & sum((1 << w) for w in W)).count('1')
                    # degree in U subgraph
                    u_deg = bin(bit_adj[u] & sum((1 << w) for w in U)).count('1')
                    return (w_count, -u_deg, random.random())  # max w_count, min deg in U
                u = max(U, key=score)
                S.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = {w for w in U if bit_adj[u] & (1 << w)}
                U -= nbrs_u
                W |= nbrs_u
            # Assign color c to all in S
            for v in S:
                color[v] = c
                uncolored.remove(v)
            c += 1
