    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except Exception:
        pass

    # Select the candidate with the fewest colors
    best_color = None
    best_k = float('inf')
    for col in candidates:
        k = len(set(col)) if col else 0
        if k < best_k:
            best_k = k
            best_color = col

    # Apply Kempe reduction to try to improve
    if best_color is not None:
        best_color = kempe_reduce(best_color)

    # Final validation and compacting (ensure 0..k-1)
    if best_color is not None and n > 0:
