def color_graph(adj: list[list[int]]) -> list[int]:
    # Convert adjacency matrix/list to adjacency list
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]
    # Detect adjacency matrix: square and binary entries (0 or 1)
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list
    graph = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        for i in range(n):
            graph[i] = list(adj[i])  # copy to avoid side effects

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = [False] * n  # n is safe upper bound
            for v in graph[u]:
                if coloring[v] != -1:
                    used[coloring[v]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[u] = c
        return coloring

    # Helper: 1-opt local search (try to reduce color of each vertex)
    def local_search_1opt(coloring):
        improved = True
        # We'll try to reduce the color of each vertex if possible
        while improved:
            improved = False
            for u in range(n):
                used = [False] * (num_colors(coloring) + 1)  # +1 for safety
                for v in graph[u]:
                    if coloring[v] != -1:
                        used[coloring[v]] = True
                # Try to find a smaller color not used by neighbors
                for c in range(coloring[u]):
                    if not used[c]:
                        coloring[u] = c
                        improved = True
                        break
                # If we changed color, break to restart (since neighbors' options may change)
                if improved:
                    break
        return coloring

    # Helper: randomized greedy with perturbation
    def randomized_greedy(seed):
        random.seed(seed)
        # Order by degree descending, with random tie-break
        order = list(range(n))
        random.shuffle(order)  # initial shuffle for tie-breaking
        order.sort(key=lambda x: len(graph[x]), reverse=True)
        coloring = greedy_color(order)
        coloring = local_search_1opt(coloring)
        return coloring

    # Run multiple randomized greedy passes
    best_coloring = None
    best_num_colors = float('inf')
    # Use different seeds for diversity; 10 passes should be fast
    for seed in range(10):
        coloring = randomized_greedy(seed)
        if not is_valid(coloring):
            # Fallback: should not happen, but if so, use simple greedy
            ordering = list(range(n))
            ordering.sort(key=lambda x: len(graph[x]), reverse=True)
            coloring = greedy_color(ordering)
            coloring = local_search_1opt(coloring)
        k = num_colors(coloring)
        if k < best_num_colors:
            best_num_colors = k
            best_coloring = coloring[:]
            # Early exit if we hit lower bound: clique size or max degree + 1?
            # We can't compute clique fast, but if k == 1, it's optimal.
            if k == 1:
                break

    # Ensure coloring uses consecutive colors
    if best_coloring is None:
        # Fallback: simple greedy
        ordering = list(range(n))
        ordering.sort(key=lambda x: len(graph[x]), reverse=True)
        best_coloring = greedy_color(ordering)
        best_coloring = local_search_1opt(best_coloring)
    # Compact colors
    unique_colors = {}
    next_color = 0
    compacted = [0] * n
    for i in range(n):
        c = best_coloring[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        compacted[i] = unique_colors[c]
    return compacted

