    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # bitmask of neighbor colors
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            c = 0
            while saturated[v] & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u] |= (1 << c)
        return colors

    # RLF
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and not any(w in S for w in adj_list[u])}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = float('inf')
                for u in U:
                    w_neighbors = sum(1 for y in adj_list[u] if y in W)
                    u_deg = sum(1 for y in adj_list[u] if y in U)
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or (w_neighbors == best_w_neighbors and u_deg == best_u_deg and u > best_u):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in adj_list[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color to S
            for v in S:
                colors[v] = color
            uncolored -= S
            color += 1
        return colors

