        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best_colors = greedy_color(order)
        best_k = count_colors(best_colors)

    # Kempe chain-based color reduction
    def kempe_reduce(colors, target_k):
        # Try to eliminate color target_k-1
        if target_k <= 1:
            return colors
        # Build color classes
        color_classes = [[] for _ in range(target_k)]
        for v in range(n):
            c = colors[v]
            if c < target_k:
                color_classes[c].append(v)
        # Target color to eliminate
        t = target_k - 1
        if not color_classes[t]:
            return colors  # already eliminated
        # Try to recolor each vertex in color t
        for v in color_classes[t][:]:  # iterate over copy
            # Try direct reassignment to a lower color
            used = 0
            for u in adj_list[v]:
                if colors[u] < target_k:  # only consider colors < target_k
                    used |= (1 << colors[u])
            for c in range(t):
                if not (used & (1 << c)):
                    colors[v] = c
                    color_classes[t].remove(v)
                    color_classes[c].append(v)
                    break
            else:
                # Try Kempe chains with each lower color
                for c in range(t):
                    # Find (t, c)-Kempe chain containing v
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (colors[nb] == t or colors[nb] == c):
                                visited[nb] = True
                                stack.append(nb)
                    # Check if any neighbor of v has color c (would cause conflict if swapped)
                    conflict = False
                    for node in component:
                        for nb in adj_list[node]:
                            if colors[nb] == c and nb not in component:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Swap colors t and c in component
                        for node in component:
                            if colors[node] == t:
                                colors[node] = c
                                color_classes[t].remove(node)
                                color_classes[c].append(node)
                            elif colors[node] == c:
                                colors[node] = t
                                color_classes[c].remove(node)
                                color_classes[t].append(node)
                        # After swap, v is no longer color t
                        if colors[v] != t:
