            mapping = {}
            new_c = 0
            for old_c in range(target_k):
                if old_c == t:
                    continue
                mapping[old_c] = new_c
                new_c += 1
            compacted = [mapping[new_colors[v]] for v in range(n)]
            return compacted
        else:
            return new_colors

    # Iterative reduction
    k = best_k
    current = best_colors[:]
    while k > 1:
        # Attempt to reduce to k-1
        reduced = kempe_reduce(current[:], k)
        if is_valid(reduced):
            new_k = count_colors(reduced)
            if new_k < k:
                current = reduced
