    # Ensure colors are consecutive starting from 0
    # Map colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = current[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        current[i] = unique_colors[c]

