                    d = deg[u]
                    buckets[d].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].append(u)
                    if deg[u] < ptr:
                        ptr = deg[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-degree[x], x))
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                k = num_colors(col)
                if k < best_k:
                    best_k = k
                    best_coloring = col[:]
        except:
            continue

    # If no valid coloring found (should not happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        # make copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # try to remove the highest color class
            k = num_colors(col)
            if k <= 1:
                break
            target_color = k - 1
            # vertices with target color
            targets = [v for v in range(n) if col[v] == target_color]
            # try to recolor each target vertex
            for v in targets:
                # try direct reassignment to a lower color
                used = [False] * k
                for u in graph[v]:
                    if col[u] != -1:
                        used[col[u]] = True
                for c in range(target_color):
                    if not used[c]:
                        col[v] = c
                        changed = True
                        break
                if changed:
                    # after change, check if target color class is empty
                    if not any(col[u] == target_color for u in range(n)):
                        # compact colors: remap so that colors are 0..k-2
                        mapping = {}
                        new_c = 0
                        for orig in range(k):
                            if orig == target_color:
                                continue
                            mapping[orig] = new_c
                            new_c += 1
                        for i in range(n):
                            if col[i] != target_color:
                                col[i] = mapping[col[i]]
                        break
                    else:
                        break
            if changed:
                continue
            # try Kempe chain swaps for each target vertex
            for v in targets:
                for c in range(target_color):
                    # if v already has a neighbor of color c, swapping may not help directly
                    # but we check if there is a Kempe chain that does not pull v's color back
                    # Build the (c, target_color) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in graph[u]:
                            if not visited[w] and (col[w] == c or col[w] == target_color):
                                visited[w] = True
                                queue.append(w)
                    # check if any neighbor of v in the component has color c? Actually, we want to see
                    # if swapping the component would cause a conflict: after swap, v would get color c.
                    # So we need that no neighbor of v has color c (outside the component, because inside
                    # they will become target_color after swap).
                    conflict = False
                    for u in graph[v]:
                        if col[u] == c and not visited[u]:  # neighbor with color c not in component
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for u in component:
                            if col[u] == c:
                                col[u] = target_color
                            elif col[u] == target_color:
                                col[u] = c
                        changed = True
                        # check if target color class is now empty
                        if not any(col[u] == target_color for u in range(n)):
                            mapping = {}
                            new_c = 0
                            for orig in range(k):
                                if orig == target_color:
                                    continue
                                mapping[orig] = new_c
                                new_c += 1
                            for i in range(n):
                                if col[i] != target_color:
                                    col[i] = mapping[col[i]]
                            break
                if changed:
                    break
        return col

    # Apply Kempe reduction
    try:
        reduced = kempe_reduce(best_coloring)
        if is_valid(reduced):
            k_red = num_colors(reduced)
            if k_red < best_k:
                best_k = k_red
                best_coloring = reduced
    except:
        pass

    # Final validation and compacting
    if not is_valid(best_coloring):
        # last resort: greedy
        best_coloring = greedy_color(list(range(n)))
    # ensure colors are compact
    unique_colors = sorted(set(best_coloring))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    else:
        is_matrix = False

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    # Ensure undirected
    for i in range(n):
        for j in adj_list[i]:
            if i not in adj_list[j]:
                adj_list[j].append(i)
                bit_adj[j] |= (1 << i)

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR with bitmask
    def dsatur():
        coloring = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        degree = [len(adj_list[i]) for i in range(n)]
        # uncolored set as bitmask
        uncolored = (1 << n) - 1
        for _ in range(n):
            # select vertex: max saturation, then max degree in uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            # iterate over uncolored vertices
            u = uncolored
            while u:
                v = (u & -u).bit_length() - 1
                u &= u - 1
                s = sat[v].bit_count()
                # degree in uncolored subgraph
                deg_uncolored = (bit_adj[v] & uncolored).bit_count()
                if s > best_sat or (s == best_sat and deg_uncolored > best_deg) or (s == best_sat and deg_uncolored == best_deg and v < best_v):
                    best_sat = s
                    best_deg = deg_uncolored
                    best_v = v
            v = best_v
            # find smallest color not in sat[v]
            c = 0
            while sat[v] & (1 << c):
                c += 1
            coloring[v] = c
            # remove v from uncolored
            uncolored &= ~(1 << v)
            # update saturation of neighbors
            nb = bit_adj[v] & uncolored
            while nb:
                u = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                sat[u] |= (1 << c)
        return compact_colors(coloring)

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # induced subgraph on uncolored
            # step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and not any(w in adj_list[u] for w in S)}
            # W: vertices adjacent to S
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = len([w for w in adj_list[u] if w in W])
                    deg_U = len([w for w in adj_list[u] if w in U])
                    if score > best_score or (score == best_score and deg_U < len([w for w in adj_list[best_u] if w in U]) if best_u != -1 else False) or (score == best_score and deg_U == len([w for w in adj_list[best_u] if w in U]) and u < best_u if best_u != -1 else True):
                        best_score = score
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
        return compact_colors(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # we'll use a bucket queue for efficiency, but n<=100 so simple scan
        while remaining:
            # find vertex of minimum degree in remaining
            v = min(remaining, key=lambda x: degrees[x])
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    degrees[u] -= 1
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)  # n+1 safe bound
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        return compact_colors(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # vertices with target color
            targets = [v for v in range(n) if coloring[v] == target_color]
            if not targets:
                k -= 1
                improved = True
                continue
            # try to recolor each target vertex
            for v in targets:
                # try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if coloring[u] < target_color:
                        neighbor_colors.add(coloring[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already recolored, break
                    if coloring[v] != target_color:
                        break
                        # build (target_color, c)-Kempe chain containing v
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    component = set()
                    while stack:
                        node = stack.pop()
                        component.add(node)
                        for nb in adj_list[node]:
                            if nb not in visited and (coloring[nb] == target_color or coloring[nb] == c):
                                visited.add(nb)
                                stack.append(nb)
                    # check if swapping component frees color c for v
                    # after swap, v would get color c
                    # we need to ensure no neighbor of v has color c after swap
                    conflict = False
                    for nb in adj_list[v]:
                        if nb in component:
                            # nb gets swapped: if it was target_color -> c, or c -> target_color
                            if coloring[nb] == target_color:
                                # after swap becomes c
                                if c == c:  # always true, but we check if it causes conflict
                                    # actually, we need to see if any neighbor of v (not in component) has color c
                                    pass
                            else:  # coloring[nb] == c
                                # after swap becomes target_color
                                pass
                        else:
                            if coloring[nb] == c:
                                conflict = True
                                break
                    if not conflict:
                        # perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        improved = True
                        break
            if improved:
                # compact colors
                coloring = compact_colors(coloring)
                k = num_colors(coloring)
            else:
                break
        return coloring

    # Run all heuristics
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    # choose best by number of colors
    best = min(candidates, key=lambda c: (num_colors(c), len(c)))
    # apply Kempe reduction
    best = kempe_reduce(best)
    # final validation and compact
    if not is_valid_coloring(best):
        # fallback to greedy by degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        best = compact_colors(coloring)
    assert is_valid_coloring(best), "Invalid coloring produced"
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask
    neighbors_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:
                    neighbors_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        saturated = [0] * n
        uncolored = set(range(n))
        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors_list[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors_list[v]:
                if color[u] == -1:
                    saturated[u] |= (1 << 0)
        while uncolored:
            # Select vertex with max saturation degree
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_count = saturated[v].bit_count()
                if sat_count > max_sat:
                    max_sat = sat_count
                    candidates = [v]
                elif sat_count == max_sat:
                    candidates.append(v)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                v = max(candidates, key=lambda x: sum(1 for u in neighbors_list[x] if u in uncolored))
            else:
                v = candidates[0]
            # Assign smallest available color
            used = 0
            for u in neighbors_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors_list[v]:
                if color[u] == -1:
                    saturated[u] |= (1 << c)
        return color

    # RLF: Recursive Largest First (independent set extraction)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in neighbors_list[x] if u in uncolored))
            S.append(v)
            # Partition U and W
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in neighbors_list[u] for w in S):
                    U.remove(u)
                    W.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W
                best_u = None
                best_score = -1
                for u in U:
                    score = sum(1 for w in neighbors_list[u] if w in W)
                    if score > best_score or (score == best_score and (best_u is None or len([x for x in neighbors_list[u] if x in U]) < len([x for x in neighbors_list[best_u] if x in U]))):
                        best_score = score
                        best_u = u
                if best_u is None:
                    break  # Should not happen
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for u in list(U):
                    if best_u in neighbors_list[u]:
                        U.remove(u)
                        W.add(u)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        return color

    # Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering (peel min degree)
        deg = [len(neighbors_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # Should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors_list[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    buckets[d].append(u)
                    if d < ptr:
                        ptr = d
        # Color in reverse order
        return greedy_color(reversed(order))

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    # Also try Welsh-Powell (degree descending)
    wp_order = sorted(range(n), key=lambda x: len(neighbors_list[x]), reverse=True)
    candidates.append(greedy_color(wp_order))
    # Try random orders a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    # Select best candidate (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]

    # If no valid found (should not happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Ensure coloring uses colors 0..k-1
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        k = next_color
        if k <= 1:
            return coloring

        improved = True
        while improved and k > 1:
            improved = False
            # Find smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already compacted
                # Remap colors
                unique_colors = {}
                next_color = 0
                for i in range(n):
                    c = coloring[i]
                    if c not in unique_colors:
                        unique_colors[c] = next_color
                        next_color += 1
                    coloring[i] = unique_colors[c]
                k = next_color
                continue

            # Try to recolor each vertex in target class
            removed = [False] * len(target_vertices)
            # Try direct reassignment first
            for idx, v in enumerate(target_vertices):
                used = 0
                for u in neighbors_list[v]:
                    if coloring[u] != target_color:  # only consider colors < target_color
                        used |= (1 << coloring[u])
                # Find smallest color < target_color not used
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Recolor v to c
                        coloring[v] = c
                        removed[idx] = True
                        improved = True
                        break
                if improved:
                    # After moving one vertex, break to restart
                    break

            if improved:
                # Continue to try to remove more from target color
                continue

            # Try Kempe chains for each vertex in target class
            for idx, v in enumerate(target_vertices):
                if removed[idx]:
                    continue
                # Try each color c < target_color
                for c in range(target_color):
                    # Check if v can be recolored to c via Kempe chain (target_color, c)
                    # Build the Kempe chain component containing v in colors {target_color, c}
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in neighbors_list[x]:
                            if coloring[y] == target_color or coloring[y] == c:
                                if y not in visited:
                                    visited.add(y)
                                    queue.append(y)
                    # Check if any neighbor of v in the component has color c? Actually, we need to see
                    # if swapping colors in component would cause conflict.
                    # Swap is safe if no neighbor of any vertex in component colored c is outside component?
                    # Actually, after swap, vertices in component that were target_color become c, and vice versa.
                    # Conflict arises if a vertex in component that becomes c has a neighbor outside component colored c.
                    # So we check: for all x in component, if coloring[x] == target_color (will become c),
                    # then all neighbors of x must not be colored c (unless they are also in component and will become target_color).
                    # Similarly, for x in component with coloring[x] == c (will become target_color),
                    # neighbors must not be colored target_color (unless in component).
                    safe = True
                    for x in component:
                        if coloring[x] == target_color:  # will become c
                            for y in neighbors_list[x]:
                                if coloring[y] == c and y not in component:
                                    safe = False
                                    break
                            if not safe:
                                break
                        else:  # coloring[x] == c, will become target_color
                            for y in neighbors_list[x]:
                                if coloring[y] == target_color and y not in component:
                                    safe = False
                                    break
                            if not safe:
                                break
                    if safe:
                        # Perform swap
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            else:
                                coloring[x] = target_color
                        removed[idx] = True
