            # Actually, we need to split U and W properly
            U = {u for u in uncolored if u not in S and not any((bit_adj[u] >> w) & 1 for w in S)}
            W = {u for u in uncolored if u not in S and any((bit_adj[u] >> w) & 1 for w in S)}
            # Now iteratively add to S from U
            while U:
                # select u in U with max |N(u) ∩ W|
                u_star = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = bit_count(bit_adj[u] & sum((1 << w) for w in W))
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
