    def smallest_last() -> list[int]:
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        degree = [bit_count(bit_adj[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u] and degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                break  # should not happen
            removed[v] = True
