def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Convert to adjacency list and compute degrees
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = [list(nei) for nei in adj]
    deg = [len(nei) for nei in adj_list]

    # Precompute bitmasks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    best_coloring = None
    best_k = float('inf')

    # Helper: greedy coloring given an order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = colors[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = saturated[u].bit_count()
                if sat > max_sat or (sat == max_sat and deg[u] > max_deg):
                    max_sat = sat
                    max_deg = deg[u]
                    v = u
                elif sat == max_sat and deg[u] == max_deg and u < v:
                    v = u
            # Assign smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    saturated[nb] |= (1 << c)
        return colors

    # 2. RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in adj_list[x] if nb in uncolored))
            independent = {v}
            to_check = {nb for nb in adj_list[v] if nb in uncolored}
            ineligible = set()
            while to_check:
                # Select u in to_check with max neighbors in ineligible, tie-break by min degree in to_check
                u = -1
                max_w = -1
                min_deg_u = float('inf')
                for cand in to_check:
                    w = sum(1 for nb in adj_list[cand] if nb in ineligible)
                    deg_in_to_check = sum(1 for nb in adj_list[cand] if nb in to_check)
                    if w > max_w or (w == max_w and deg_in_to_check < min_deg_u) or (w == max_w and deg_in_to_check == min_deg_u and cand < u):
                        max_w = w
                        min_deg_u = deg_in_to_check
                        u = cand
                independent.add(u)
                to_check.remove(u)
                # Move neighbors of u from to_check to ineligible if they are in to_check
                for nb in adj_list[u]:
                    if nb in to_check:
                        to_check.remove(nb)
                        ineligible.add(nb)
                # Also add neighbors of u that are in uncolored but not in independent or ineligible to to_check
                for nb in adj_list[u]:
                    if nb in uncolored and nb not in independent and nb not in ineligible:
                        to_check.add(nb)
            # Assign color to independent set
            for u in independent:
                colors[u] = color
                uncolored.remove(u)
            color += 1
        return colors

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        deg_copy = deg[:]
        order = []
        # Use bucket sort for efficiency
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            if deg_copy[v] < len(buckets):
                buckets[deg_copy[v]].add(v)
        min_deg = 0
        while remaining:
            # Find non-empty bucket with smallest index
            while min_deg < len(buckets) and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= len(buckets):
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            for nb in adj_list[v]:
                if nb in remaining:
                    old_deg = deg_copy[nb]
                    new_deg = old_deg - 1
                    if old_deg < len(buckets):
                        buckets[old_deg].discard(nb)
                    if new_deg < len(buckets):
                        buckets[new_deg].add(nb)
                    deg_copy[nb] = new_deg
                    if new_deg < min_deg:
                        min_deg = new_deg
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    for func in (dsatur, rlf, smallest_last):
        try:
            col = func()
            # Validate coloring
            valid = True
            for u in range(n):
                for v in adj_list[u]:
                    if u < v and col[u] == col[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                k = max(col) + 1 if n > 0 else 0
                candidates.append((k, col))
        except Exception:
            continue

    if not candidates:
        # Fallback to simple greedy by degree order
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        col = greedy_color(order)
        k = max(col) + 1 if n > 0 else 0
        best_coloring = col
        best_k = k
    else:
        best_k, best_coloring = min(candidates, key=lambda x: x[0])

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal best_k, best_coloring
        # Try to eliminate the smallest color class iteratively
        while True:
            color_classes = [[] for _ in range(best_k)]
            for v, c in enumerate(coloring):
                color_classes[c].append(v)
            # Find smallest non-empty color class
            target_color = -1
            min_size = float('inf')
            for c in range(best_k):
                if 0 < len(color_classes[c]) < min_size:
                    min_size = len(color_classes[c])
                    target_color = c
            if target_color == -1:
                break  # no colored vertices
            if min_size == 0:
                break  # should not happen
            # Try to recolor each vertex in target class
            removed = False
            for v in list(color_classes[target_color]):  # iterate over copy
                # Try direct reassignment to a lower color
                used = 0
                for nb in adj_list[v]:
                    nb_c = coloring[nb]
                    if nb_c != -1:
                        used |= (1 << nb_c)
                for c in range(target_color):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        removed = True
                        break
                if removed:
                    continue
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {c, target_color}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for nb in adj_list[u]:
                            if not visited[nb] and coloring[nb] in (c, target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if swapping colors in component is valid (should always be)
                    # Perform swap
                    for u in component:
                        coloring[u] = c if coloring[u] == target_color else target_color
                    removed = True
                    break
                if removed:
                    break
            if not removed:
                break  # cannot eliminate this color class
            # Compact colors: remove target_color and shift higher colors down
            new_coloring = [-1] * n
            for v in range(n):
                c = coloring[v]
                if c == -1:
                    continue
                if c > target_color:
                    new_coloring[v] = c - 1
                else:
                    new_coloring[v] = c
            coloring = new_coloring
            best_k -= 1
            # Update best if improved
            if best_k < len(set(coloring)):  # should hold
                best_coloring = coloring[:]
        return coloring

    # Apply Kempe reduction
    final_coloring = kempe_reduce(best_coloring[:])
    # Ensure colors are consecutive and zero-based
    used_colors = set(final_coloring)
    if used_colors:
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        final_coloring = [mapping[c] for c in final_coloring]
    return final_coloring

