    neighbors = []
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            row = []
            mask = 0
            for j in range(n):
                if adj[i][j] == 1:
                    row.append(j)
                    mask |= (1 << j)
            neighbors.append(row)
            bit_adj[i] = mask
    else:
        for i in range(n):
            row = adj[i]
            mask = 0
            for v in row:
                if v < 0 or v >= n:
                    continue  # ignore invalid indices
                mask |= (1 << v)
            neighbors.append(row)
            bit_adj[i] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        sat = [0] * n
        # degree in uncolored subgraph (initially full degree)
        deg_uncolored = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by max deg_uncolored, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and deg_uncolored[u] > max_deg):
                    max_sat = s
                    max_deg = deg_uncolored[u]
                    v = u
                elif s == max_sat and deg_uncolored[u] == max_deg:
                    if random.random() < 0.5:  # random tie-break
                        v = u
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and deg_uncolored for neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
