    # 2. RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # start with vertex of max degree in uncolored subgraph
            # compute degrees in uncolored subgraph
            deg = {}
            for u in uncolored:
                cnt = 0
                for v in neighbors[u]:
                    if v in uncolored:
                        cnt += 1
                deg[u] = cnt
            # pick vertex with max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                for w in S:
                    if w in neighbors[u]:
                        W.add(u)
                        U.remove(u)
                        break
            # while U not empty, add vertex with max neighbors in W, tie-break by min deg in U
            while U:
                # compute deg in U for each u in U
                degU = {}
                for u in U:
                    cnt = 0
                    for w in U:
                        if w != u and w in neighbors[u]:
                            cnt += 1
                    degU[u] = cnt
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = float('inf')
                for u in U:
                    score = 0
                    for w in W:
                        if w in neighbors[u]:
                            score += 1
                    if score > best_score or (score == best_score and degU[u] < best_degU):
                        best_score = score
                        best_degU = degU[u]
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u in U to W
                for w in list(U):
                    if w in neighbors[best_u]:
                        W.add(w)
                        U.remove(w)
