        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    try:
        candidates.append(dsatur())
    except Exception:
        pass
    try:
        candidates.append(rlf())
    except Exception:
        pass
    try:
        candidates.append(smallest_last())
    except Exception:
        pass
    # Also try Welsh-Powell (degree descending)
    try:
        order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        candidates.append(greedy_color(order_wp))
    except Exception:
        pass
    # Try random orders a few times
    for _ in range(10):
        try:
            order = list(range(n))
            random.shuffle(order)
            candidates.append(greedy_color(order))
        except Exception:
            pass

    # Evaluate candidates
    for coloring in candidates:
        # validate coloring
        valid = True
        for u in range(n):
