        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (largest color index that is used)
            # we try to eliminate the highest color index first
            max_color = max(col) if col else -1
            for target in range(max_color, -1, -1):
                # collect vertices with color target
                verts = [i for i in range(n) if col[i] == target]
                if not verts:
                    continue
                # try to recolor each vertex in this class
                for v in verts:
                    # try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        c = col[u]
                        if c != -1:
                            neighbor_colors.add(c)
                    for c in range(target):  # only lower colors
                        if c not in neighbor_colors:
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # try Kempe chains with each lower color
                    for c in range(target):
                        if c in neighbor_colors:
                            continue
                        # check if v is connected to any vertex of color c via a Kempe chain (c, target)
                        # we do BFS/DFS on the subgraph induced by colors c and target
                        from collections import deque
                        visited = [False] * n
                        queue = deque()
                        # start from v, we can traverse edges only if the neighbor has color c or target
                        # but we start with v (color target) and look for color c
                        visited[v] = True
                        queue.append(v)
                        found_c = False
                        while queue and not found_c:
                            x = queue.popleft()
                            for y in neighbors[x]:
                                if not visited[y] and (col[y] == c or col[y] == target):
                                    visited[y] = True
                                    if col[y] == c:
                                        found_c = True
                                        break
                                    queue.append(y)
                            if found_c:
                                break
                        if found_c:
                            # we found a Kempe chain that contains a vertex of color c
                            # but we need to check if swapping the component of v would not cause conflict
                            # Actually, swapping any Kempe chain preserves validity.
                            # However, we want to move v to color c, so we swap the component that contains v.
                            # But note: if the component contains both colors, swapping will change v's color to c.
                            # We'll swap the entire component.
                            for i in range(n):
                                if visited[i]:
                                    if col[i] == c:
                                        col[i] = target
                                    else:  # col[i] == target
                                        col[i] = c
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # after attempting to eliminate color target, check if target color class is empty
            if target < max_color and not any(col[i] == target for i in range(n)):
                # compact colors: rename all colors > target down by 1
                mapping = {}
                next_c = 0
                for i in range(max_color + 1):
                    if any(col[j] == i for j in range(n)):
                        mapping[i] = next_c
                        next_c += 1
                for i in range(n):
                    col[i] = mapping[col[i]]
                changed = True
                break  # restart while loop
        return col

    # Apply Kempe reduction
    try:
        reduced = kempe_reduce(best_coloring)
        # validate
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if u < v and reduced[u] == reduced[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            k_red = num_colors(reduced)
            if k_red < best_k:
                best_k = k_red
                best_coloring = reduced
    except Exception:
        pass

    # Ensure colors are consecutive starting from 0
    if best_coloring:
        # remap to consecutive
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_coloring[i] = unique_colors[c]
    return best_coloring

