    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to zero-based consecutive
    def normalize(coloring):
        if not coloring:
            return coloring
        unique = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            coloring[i] = unique[c]
        return coloring

    # Strategy 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg_uncolored = [len(adj_list[u]) for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = deg_uncolored[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # find smallest color not used by neighbors
            neighbor_colors = sat[v]
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and degrees for neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # degree in current uncolored subgraph
            deg = {}
            for v in uncolored:
                deg[v] = sum(1 for u in adj_list[v] if u in uncolored)
            # start with vertex of max degree
            v = max(uncolored, key=lambda x: deg[x])
            independent_set = {v}
            # partition: U = vertices not adjacent to any in S, W = adjacent to S
            U = uncolored - {v} - set(adj_list[v])
            W = set(adj_list[v]) & uncolored
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_nw = -1
                best_deg_u = float('inf')
                for u in U:
                    nw = sum(1 for w in adj_list[u] if w in W)
                    du = sum(1 for w in adj_list[u] if w in U)
                    if nw > best_nw or (nw == best_nw and du < best_deg_u) or (nw == best_nw and du == best_deg_u and random.random() < 0.5):
                        best_nw = nw
                        best_deg_u = du
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to independent set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

