    def smallest_last():
        # compute degeneracy ordering
        deg = [len(adj_list[u]) for u in range(n)]
        # buckets for degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg[v]
            if d <= max_deg:
                buckets[d].append(v)
        # track current degree and position
        curr_deg = deg[:]
        # pointer to non-empty bucket
        ptr = 0
        order = []
        # visited flag
        removed = [False] * n
        for _ in range(n):
            # find first non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            while removed[v]:
                if not buckets[ptr]:
                    ptr += 1
                    while ptr <= max_deg and not buckets[ptr]:
                        ptr += 1
                    if ptr > max_deg:
                        break
                    v = buckets[ptr].pop()
                else:
                    break
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    if d > 0:
                        curr_deg[u] -= 1
                        if curr_deg[u] < len(buckets):
                            buckets[curr_deg[u]].append(u)
