    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # Select best candidate (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for coloring in candidates:
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]
    if best_coloring is None:
        # fallback: greedy by degree
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        color = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_colors |= (1 << color[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            color[v] = c
        best_coloring = color

    # Normalize to zero-based consecutive
    best_coloring = normalize(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find color classes
            classes = {}
            for v in range(n):
                c = col[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            # process colors from highest to lowest
            colors_sorted = sorted(classes.keys(), reverse=True)
            for target_color in colors_sorted:
                if target_color == 0:
                    continue
                if target_color not in classes or not classes[target_color]:
                    continue
                # try to recolor each vertex in target_color
                for v in classes[target_color][:]:  # copy list
                    # try direct reassignment to a lower color
                    neighbor_colors = 0
                    for u in adj_list[v]:
                        if col[u] != -1:
                            neighbor_colors |= (1 << col[u])
                    for c in range(target_color):
                        if not (neighbor_colors & (1 << c)):
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        break  # restart scan
                    # try Kempe chains with each lower color
                    for c in range(target_color):
                        # if v already recolored, break
                        if col[v] != target_color:
                            break
                        # BFS to find (target_color, c) Kempe chain containing v
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        component = set()
                        while queue:
                            node = queue.popleft()
                            component.add(node)
                            for nb in adj_list[node]:
                                if nb not in visited and (col[nb] == target_color or col[nb] == c):
                                    visited.add(nb)
                                    queue.append(nb)
                        # check if we can swap: no neighbor of component has color c outside component
                        can_swap = True
                        for node in component:
                            for nb in adj_list[node]:
                                if nb not in component and col[nb] == c:
                                    can_swap = False
                                    break
                            if not can_swap:
                                break
                        if can_swap:
                            # perform swap
                            for node in component:
                                if col[node] == target_color:
                                    col[node] = c
                                else:
                                    col[node] = target_color
                            changed = True
                            break  # restart scan
                if changed:
                    break  # restart color scan
        return col

    # Apply Kempe reduction
    try:
        reduced = kempe_reduce(best_coloring)
        if is_valid_coloring(reduced):
            best_coloring = reduced
    except:
        pass

    # Final normalization
    best_coloring = normalize(best_coloring)

    return best_coloring

