                    nb_u = bit_adj[u]
                    vv = 0
                    while nb_u:
                        if nb_u & 1:
                            if vv in U:
                                deg_in_U += 1
                        nb_u >>= 1
                        vv += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # Should not happen if U non-empty
                # Add best_u to S
                S.add(best_u)
                uncolored.remove(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                nb_best = bit_adj[best_u]
                vv = 0
                while nb_best:
                    if nb_best & 1:
                        if vv in U:
                            U.remove(vv)
                            W.add(vv)
                            # Update current degree: neighbor lost an uncolored neighbor
                            if vv in uncolored:
                                curr_deg[vv] -= 1
                    nb_best >>= 1
                    vv += 1
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return to_color_list(color)

    def smallest_last():
        # Degeneracy ordering: smallest-last
        order = []
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        # List of sets for vertices of each degree
        max_deg = max(degrees) if n > 0 else 0
        bins = [set() for _ in range(max_deg + 1)]
        pos = [0] * n
        for i in range(n):
            d = degrees[i]
            bins[d].add(i)
            pos[i] = d
        # Current min degree
        for _ in range(n):
            # Find non-empty bin with smallest index
            d = 0
            while d <= max_deg and not bins[d]:
                d += 1
            if d > max_deg:
                break
            v = bins[d].pop()
            order.append(v)
            # Update neighbors
            nb = bit_adj[v]
            u = 0
            while nb:
                if nb & 1:
                    if u in order:  # already removed
                        nb >>= 1
                        u += 1
                        continue
                    d_u = degrees[u]
                    if d_u > 0:
                        bins[d_u].remove(u)
                        d_u -= 1
                        bins[d_u].add(u)
                        degrees[u] = d_u
                nb >>= 1
                u += 1
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            nb = bit_adj[v]
            u = 0
            while nb:
                if nb & 1:
                    if color[u] != -1:
                        used |= (1 << color[u])
                nb >>= 1
                u += 1
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return to_color_list(color)

    # Spectral-inspired clustering via random walk (heat kernel approximation)
    def spectral_clustering_based_coloring():
        # Use random walk to approximate similarity, then assign same color to weakly connected clusters
        # We'll compute a diffusion vector via a few steps of random walk from a random start
        # Then sort vertices by diffusion value and assign colors in blocks to disconnected parts
        try:
            start = random.randrange(n)
            # Probability distribution vector
            p = [0.0] * n
            p[start] = 1.0
            # Number of walk steps: O(log n) for mixing
            steps = max(10, int(math.log2(n)) + 5)
            deg = [bin(bit_adj[i]).count('1') for i in range(n)]
            for _ in range(steps):
                new_p = [0.0] * n
                for u in range(n):
                    if p[u] == 0.0:
                        continue
                    d = deg[u]
                    if d == 0:
                        new_p[u] += p[u]
                    else:
                        nb = bit_adj[u]
                        v = 0
                        while nb:
                            if nb & 1:
                                new_p[v] += p[u] / d
                            nb >>= 1
                            v += 1
                p = new_p
            # Sort vertices by p-value
            order = sorted(range(n), key=lambda x: p[x])
            # Greedy color in this order
            color = [-1] * n
            for v in order:
                used = 0
                nb = bit_adj[v]
                u = 0
                while nb:
                    if nb & 1:
                        if color[u] != -1:
                            used |= (1 << color[u])
                    nb >>= 1
                    u += 1
                c = 0
                while used & (1 << c):
                    c += 1
                color[v] = c
            return to_color_list(color)
        except:
            # Fallback to DSATUR if anything goes wrong
            return dsatur()

    # Run all heuristics
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    candidates.append(spectral_clustering_based_coloring())

    # Select the candidate with the fewest colors
    best_coloring = None
    min_colors = float('inf')
    for col in candidates:
        if not is_valid_coloring(col):
            continue
        unique_colors = len(set(col))
        if unique_colors < min_colors:
            min_colors = unique_colors
            best_coloring = col

    # Fallback: if none valid (should not happen), use DSATUR
    if best_coloring is None:
        best_coloring = dsatur()

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        # Make copy
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find color classes
            classes = {}
            for v in range(n):
                c = col[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            # Sort colors by class size (smallest first)
            sorted_colors = sorted(classes.keys(), key=lambda x: len(classes[x]))
            # Try to eliminate each color class from largest color downward
            for target_color in sorted(sorted_colors, reverse=True):
                if target_color not in classes:
                    continue
                vertices = classes[target_color]
                # Try to recolor each vertex in this class
                for v in vertices:
                    # Try direct reassignment to a lower color
                    neighbor_colors = set()
                    nb = bit_adj[v]
                    u = 0
                    while nb:
                        if nb & 1:
                            if col[u] != -1:
                                neighbor_colors.add(col[u])
                        nb >>= 1
                        u += 1
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            # Move v to color c
                            col[v] = c
                            changed = True
                            # Update class structures
                            classes[target_color].remove(v)
                            if not classes[target_color]:
                                del classes[target_color]
                            if c not in classes:
                                classes[c] = []
                            classes[c].append(v)
                            break
                    if changed:
                        break  # Restart search after change
                if changed:
                    break  # Restart outer loop
            # If no direct reassignment, try Kempe chains
            if not changed:
                for target_color in sorted(sorted_colors, reverse=True):
                    if target_color not in classes:
                        continue
                    vertices = classes[target_color]
                    for v in vertices:
                        # Try to swap with each lower color
                        for c in range(target_color):
                            # Check if v can be recolored to c via Kempe chain (c, target_color)
                            # Build the Kempe chain component containing v in colors {c, target_color}
                            from collections import deque
                            visited = set()
                            queue = deque([v])
                            visited.add(v)
                            # We'll traverse only vertices of color c or target_color
                            while queue:
                                x = queue.popleft()
                                nb = bit_adj[x]
                                y = 0
                                while nb:
                                    if nb & 1:
                                        if col[y] == c or col[y] == target_color:
                                            if y not in visited:
                                                visited.add(y)
                                                queue.append(y)
                                    nb >>= 1
                                    y += 1
                            # Now, check if any neighbor of v has color c (outside the component?)
                            # Actually, we want to see if we can swap: if no neighbor of v in the component has color c,
                            # then swapping the component will not cause conflict for v.
                            # More precisely: after swap, v will get color c. We need to ensure no neighbor of v has color c after swap.
                            # Neighbors of v that are in the component: if they had color c, they become target_color; if target_color, become c.
                            # Neighbors not in the component keep their color.
                            # So, we need that no neighbor of v has color c and is NOT in the component (because those would stay c and conflict).
                            # Equivalent: all neighbors of v that have color c must be in the component (so they flip to target_color).
                            has_conflict = False
                            nb = bit_adj[v]
                            y = 0
                            while nb:
                                if nb & 1:
                                    if col[y] == c:
                                        if y not in visited:
                                            has_conflict = True
                                            break
                                nb >>= 1
                                y += 1
                            if not has_conflict:
                                # Perform swap: flip colors in the component
                                for x in visited:
                                    if col[x] == c:
                                        col[x] = target_color
                                    elif col[x] == target_color:
                                        col[x] = c
                                changed = True
                                # Update classes
                                # Rebuild classes from scratch for simplicity (n <= 100)
                                classes = {}
                                for i in range(n):
                                    ci = col[i]
                                    if ci not in classes:
                                        classes[ci] = []
                                    classes[ci].append(i)
                                break
                        if changed:
                            break
                    if changed:
                        break
        # Compact colors: remap to 0..k-1
        unique_colors = sorted(set(col))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        col = [mapping[c] for c in col]
        return col

    best_coloring = kempe_reduce(best_coloring)
    # Final validation (should be valid)
    if not is_valid_coloring(best_coloring):
        # Last resort: greedy by degree order
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        col = [-1] * n
        for v in order:
            used = 0
            nb = bit_adj[v]
            u = 0
            while nb:
                if nb & 1:
                    if col[u] != -1:
                        used |= (1 << col[u])
                nb >>= 1
                u += 1
            c = 0
            while used & (1 << c):
                c += 1
            col[v] = c
        best_coloring = col

    return best_coloring

