def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: count distinct colors
    def count_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: convert to consecutive colors
    def compact_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by max degree in uncolored, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_count = saturation[v].bit_count()
                deg = uncolored_deg[v]
                if sat_count > best_sat or (sat_count == best_sat and deg > best_deg) or \
                   (sat_count == best_sat and deg == best_deg and (best_v == -1 or random.random() < 0.5)):
                    best_sat = sat_count
                    best_deg = deg
                    best_v = v
            v = best_v
            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return colors

    # Helper: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # build maximal independent set for this color
            S = []
            # degree in current uncolored subgraph
            deg_uncolored = [0] * n
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_uncolored[v] += 1
            # U: vertices not adjacent to S, W: vertices adjacent to S
            U = set(uncolored)
            W = set()
            # pick first vertex: max degree in uncolored
            if U:
                v1 = max(U, key=lambda x: deg_uncolored[x])
                S.append(v1)
                U.remove(v1)
                # move neighbors of v1 from U to W
                for u in adj_list[v1]:
                    if u in U:
                        U.remove(u)
                        W.add(u)
            # grow S
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in G[U]
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    deg_u = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_u += 1
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and (best_u == -1 or random.random() < 0.5)):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to S
            for v in S:
                colors[v] = color
            color += 1
            # next round: uncolored becomes W (vertices adjacent to S)
            uncolored = W
            # reset for next color class
            S.clear()
            W.clear()
            U = set(uncolored)
        return colors

    # Helper: smallest-last ordering
    def smallest_last():
        # core decomposition to get removal order
        deg = [len(adj_list[i]) for i in range(n)]
        # buckets for degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg[v]
            if d <= max_deg:
                buckets[d].append(v)
        # track current degree and position
        curr_deg = deg[:]
        pos = [0] * n
        for d in range(max_deg + 1):
            for v in buckets[d]:
                pos[v] = len(buckets[d])  # approximate, we'll adjust
        # actually, we simulate removal
        removed = [False] * n
        order = []
        # we maintain a list of vertices per degree
        # for efficiency, we use buckets and pointer
        # since n <= 100, we can do simple scan
        for _ in range(n):
            # find vertex with minimum degree among non-removed
            min_deg = float('inf')
            v_min = -1
            for v in range(n):
                if not removed[v] and curr_deg[v] < min_deg:
                    min_deg = curr_deg[v]
                    v_min = v
            if v_min == -1:
                break  # should not happen
            removed[v_min] = True
            order.append(v_min)
            # update neighbors
            for u in adj_list[v_min]:
                if not removed[u]:
                    curr_deg[u] -= 1
        # reverse order for coloring
        order.reverse()
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid_coloring(c4):
            candidates.append(c4)
    except:
        pass
    # Fallback: sequential
    try:
        c5 = greedy_color(list(range(n)))
        if is_valid_coloring(c5):
            candidates.append(c5)
    except:
        pass

    # Select best candidate (fewest colors)
    if not candidates:
        # emergency fallback: assign all distinct colors
        best = list(range(n))
    else:
        best = min(candidates, key=count_colors)

    # Iterative Kempe chain color reduction
    def kempe_reduction(colors):
        k = count_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # vertices with target_color
            vertices = [v for v in range(n) if colors[v] == target_color]
            if not vertices:
                continue
            # Try to recolor each vertex in this class
            made_progress = False
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if colors[u] != -1:
                        neighbor_colors.add(colors[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        colors[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break  # restart scan as colors changed
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue  # direct move not possible, but Kempe might help
                    # We'll try to swap along (target_color, c) Kempe chain
                    # Find the component of v in the subgraph induced by colors target_color and c
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (colors[nb] == target_color or colors[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any neighbor of the component has color c (would cause conflict if swapped)
                    has_c_neighbor = False
                    for node in component:
                        for nb in adj_list[node]:
                            if colors[nb] == c and nb not in component:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            break
                    if not has_c_neighbor:
                        # Safe to swap: invert target_color <-> c in component
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            elif colors[node] == c:
                                colors[node] = target_color
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                # Could not eliminate this color class, try next lower
                continue
            else:
                # Made progress, restart from highest color as k may have reduced
                return kempe_reduction(colors)
        # Compact colors
        return compact_colors(colors)

    # Apply Kempe reduction
    try:
        best = kempe_reduction(best)
    except:
        pass  # fallback to best if kempe fails

    # Final validation and compaction
    if not is_valid_coloring(best):
        # last resort: greedy by degree
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best = greedy_color(order)
    best = compact_colors(best)
    return best

