    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build maximal independent set for current_color
            # Degree in uncolored subgraph
            deg = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg[v] += 1

            # Start with vertex of max degree in uncolored
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: deg[x])
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = uncolored - independent_set - {u for u in adj_list[v] if u in uncolored}
            W = {u for u in adj_list[v] if u in uncolored}

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # Degree in U
                    deg_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_U += 1
                    if w_count > best_score or (w_count == best_score and deg_U < best_deg_U) or \
                       (w_count == best_score and deg_U == best_deg_U and (best_u == -1 or u < best_u)):
                        best_score = w_count
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent_set
            for v in independent_set:
                color[v] = current_color
            uncolored -= independent_set
            current_color += 1
        return color

    # Strategy 3: Smallest-Last ordering
    def smallest_last():
        # Core decomposition to get ordering
        degree = [len(adj_list[i]) for i in range(n)]
        # Bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d < len(buckets):
                buckets[d].append(v)
            else:
                # Should not happen, but extend if needed
                while len(buckets) <= d:
                    buckets.append([])
                buckets[d].append(v)

        # Pointers for non-empty buckets
        ptr = [0] * (max_deg + 1)
        order = []
        # Current degree of each vertex
        curr_deg = degree[:]
        # Removed flag
        removed = [False] * n

        for _ in range(n):
            # Find vertex with minimum degree
            min_deg = -1
            v = -1
            for d in range(max_deg + 1):
                while ptr[d] < len(buckets[d]) and removed[buckets[d][ptr[d]]]:
