                    if min_deg == -1 or curr_deg[candidate] < min_deg:
                        min_deg = curr_deg[candidate]
                        v = candidate
            if v == -1:
                # Fallback: any unremoved vertex
                for i in range(n):
                    if not removed[i]:
                        v = i
                        break
