    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # Fallback: simple greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        c_fallback = greedy_color(order)
        if is_valid(c_fallback):
            candidates.append(c_fallback)

    # Select best initial coloring (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        k = count_colors(col)
        if k < best_k:
            best_k = k
            best_coloring = col[:]

    if best_coloring is None:
        # Ultimate fallback: assign all to color 0 (may be invalid, but we'll try to fix)
        best_coloring = [0] * n
        best_k = 1

    # Compact colors
    best_coloring = compact_colors(best_coloring)
    k = count_colors(best_coloring)

    # Iterative color reduction: try to eliminate highest color class
    improved = True
    while improved and k > 1:
        improved = False
        target_color = k - 1
        # Get vertices with target color
        target_vertices = [v for v in range(n) if best_coloring[v] == target_color]
        # Try to reassign each target vertex to a lower color
        for v in target_vertices:
            # Try direct reassignment to any lower color
            used_by_neighbors = 0
            for u in adj_list[v]:
                c = best_coloring[u]
                if c != -1:
                    used_by_neighbors |= (1 << c)
            # Try colors from 0 to target_color-1
            for c in range(target_color):
                if not (used_by_neighbors & (1 << c)):
                    # Can assign color c directly
                    best_coloring[v] = c
                    improved = True
                    break
            if improved:
                # After reassignment, check if target color class is empty
                if any(best_coloring[v] == target_color for v in range(n)):
                    # Still some vertices with target color, continue trying
                    pass
                else:
                    # Target color eliminated, compact and restart
                    best_coloring = compact_colors(best_coloring)
                    k = count_colors(best_coloring)
                    improved = True  # to restart outer loop
                    break
        # If no direct reassignment worked, try Kempe chain swaps
        if not improved:
            for v in target_vertices:
                v_color = best_coloring[v]  # should be target_color
                # Try swapping with each lower color
                for c in range(target_color):
                    # Build Kempe chain for (v_color, c) starting from v
                    # We'll try to swap the component containing v if it doesn't pull any target_color vertex into v_color
                    visited = set()
                    stack = [v]
                    component = set()
                    # BFS/DFS to get the Kempe chain component
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        node_color = best_coloring[node]
                        if node_color == v_color or node_color == c:
                            component.add(node)
                            for neighbor in adj_list[node]:
                                if neighbor not in visited:
                                    stack.append(neighbor)
                    # Check if swapping this component is safe: 
                    # After swap, no two adjacent vertices will have same color.
                    # Equivalent to: for every edge (x,y) with x in component, y not in component,
                    # we must not have (best_coloring[x] == c and best_coloring[y] == c) or 
                    # (best_coloring[x] == v_color and best_coloring[y] == v_color) after swap.
                    # After swap: x in component: if was v_color -> c, if was c -> v_color.
                    # So condition: for edge (x,y) with x in comp, y not in comp:
                    #   original colors: (a,b) where a in {v_color,c}, b not in {v_color,c}? 
                    #   Actually, y could be any color, but after swap:
                    #   If x was v_color -> becomes c, so we need that y is not c.
                    #   If x was c -> becomes v_color, so we need that y is not v_color.
                    # So: for all y in adj_list[x] with x in component and y not in component:
                    #   if best_coloring[x] == v_color then best_coloring[y] != c
                    #   if best_coloring[x] == c then best_coloring[y] != v_color
                    safe = True
                    for x in component:
                        xc = best_coloring[x]
                        for y in adj_list[x]:
                            if y not in component:
                                yc = best_coloring[y]
                                if xc == v_color and yc == c:
                                    safe = False
                                    break
                                if xc == c and yc == v_color:
                                    safe = False
                                    break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for x in component:
                            if best_coloring[x] == v_color:
                                best_coloring[x] = c
                            else:  # must be c
                                best_coloring[x] = v_color
                        improved = True
                        # Check if target color class is now empty for v
                        # But we break to restart outer loop after any improvement
                        break
                if improved:
                    break
            if improved:
                # Compact and check if we can reduce k
                best_coloring = compact_colors(best_coloring)
                new_k = count_colors(best_coloring)
                if new_k < k:
                    k = new_k
                    improved = True  # to continue outer loop
                else:
                    improved = False
        # End of Kempe attempt

    # Final validation and compact
    if not is_valid(best_coloring):
        # Last resort: greedy by degree
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best_coloring = greedy_color(order)
    best_coloring = compact_colors(best_coloring)
    return best_coloring

