def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix (0/1)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:  # safety check
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper function to validate coloring
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper function to get number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper function to normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur():
        colors = [-1] * n
        # saturation[v] = bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in the uncolored subgraph (for tie-breaking)
        uncolored_degree = [len(neighbors[i]) for i in range(n)]
        uncolored_count = n

        for _ in range(n):
            # Select uncolored vertex with max saturation, then max uncolored degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    sat = saturation[u].bit_count()
                    if sat > max_sat or (sat == max_sat and uncolored_degree[u] > max_deg):
                        max_sat = sat
                        max_deg = uncolored_degree[u]
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color (not in saturation[v])
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

            # Update neighbors of v
            for u in neighbors[v]:
                if colors[u] == -1:  # only update uncolored neighbors
                    saturation[u] |= (1 << c)
                    uncolored_degree[u] -= 1
            uncolored_count -= 1

        return normalize(colors)

    # RLF algorithm (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for this color
            independent_set = []
            # Candidates: vertices not adjacent to any in independent_set
            candidates = set(uncolored)
            # Vertices adjacent to independent_set (blocked)
            blocked = set()

            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
                independent_set.append(v)
                candidates.remove(v)
                # Update candidates and blocked
                for u in neighbors[v]:
                    if u in candidates:
                        candidates.remove(u)
                        blocked.add(u)

            # Greedily add to independent set
            while candidates:
                # Select vertex in candidates with max neighbors in blocked
                v = -1
                max_blocked_neighbors = -1
                min_deg_in_candidates = float('inf')
                for u in candidates:
                    blocked_neighbors = len([w for w in neighbors[u] if w in blocked])
                    deg_in_candidates = len([w for w in neighbors[u] if w in candidates])
                    if (blocked_neighbors > max_blocked_neighbors or 
                        (blocked_neighbors == max_blocked_neighbors and deg_in_candidates < min_deg_in_candidates)):
                        max_blocked_neighbors = blocked_neighbors
                        min_deg_in_candidates = deg_in_candidates
                        v = u
                if v == -1:
                    break
                independent_set.append(v)
                candidates.remove(v)
                # Move neighbors of v from candidates to blocked
                for u in neighbors[v]:
                    if u in candidates:
                        candidates.remove(u)
                        blocked.add(u)

            # Assign color to independent set
            for v in independent_set:
                colors[v] = color
                uncolored.remove(v)
            color += 1

        return normalize(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []

        # Repeatedly remove vertex of minimum degree
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    degree[u] -= 1

        # Color in reverse order using first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

        return normalize(colors)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring  # should not happen if input is valid

        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        used_by_neighbors |= (1 << coloring[u])

                for c in range(target_color):  # try colors 0 to target_color-1
                    if not (used_by_neighbors & (1 << c)):
                        # Can move v to color c directly
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart with new coloring

                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Find the (v, c)-Kempe chain containing v
                    # Only consider vertices colored v_color or c
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for u in neighbors[node]:
                                if u not in visited and (coloring[u] == target_color or coloring[u] == c):
                                    stack.append(u)

                    # Check if swapping this component is safe:
                    # After swap, no neighbor of any node in component should have color c (if we swap target_color->c)
                    # or target_color (if we swap c->target_color). Actually, we want to free target_color for v.
                    # We are considering swapping colors in the component: target_color <-> c.
                    # After swap, v will have color c (if it was target_color).
                    # We need to ensure that no neighbor of v has color c after swap.
                    # But note: neighbors of v that are in the component and had color c will become target_color.
                    # So we need to check: for any node in component, its neighbors outside the component
                    # should not have color c (because those would become target_color after swap? Let's think.)

                    # Actually, we want to move v from target_color to c. Swapping the component will:
                    # - Change v from target_color to c.
                    # - Change any node in component that was c to target_color.
                    # For the coloring to remain valid:
                    #   - For any node x in component that was target_color (now c): its neighbors must not have color c.
                    #   - For any node x in component that was c (now target_color): its neighbors must not have color target_color.
                    # But note: neighbors inside the component are safe because they flip together.
                    # So we only need to check neighbors outside the component.

                    valid_swap = True
                    for node in component:
                        col_node = coloring[node]
                        for u in neighbors[node]:
                            if u not in component:
                                if col_node == target_color and coloring[u] == c:
                                    valid_swap = False
                                    break
                                if col_node == c and coloring[u] == target_color:
                                    valid_swap = False
                                    break
                        if not valid_swap:
                            break

                    if valid_swap:
                        # Perform the swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        improved = True
                        break
                if improved:
                    break

            if improved:
                # Re-normalize and update k
                coloring = normalize(coloring)
                k = num_colors(coloring)
            else:
                # Could not eliminate target_color, break
                break

        return coloring

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), use greedy
    if not candidates:
        # Simple greedy ordering by degree
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(normalize(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = normalize(best)

    # Apply Kempe chain reduction to try to improve
    best = kempe_reduce(best)
    best = normalize(best)

    # Final validation (should be valid by construction)
    if not is_valid_coloring(best):
        # Fallback to a simple valid coloring (e.g., greedy by index)
        colors = list(range(n))  # worst case, but valid
        # Actually, we can do better: greedy in order 0..n-1
        colors = [-1] * n
        for v in range(n):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best = normalize(colors)

    return best

