                    continue
                adjacent = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                u_best = -1
                max_common = -1
                min_deg_U = float('inf')
                for u in U:
                    common = 0
                    for w in adj_list[u]:
                        if w in W:
                            common += 1
                    # Tie-break: min degree in G[U]
                    deg_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_U += 1
                    if common > max_common or (common == max_common and deg_U < min_deg_U) or \
                       (common == max_common and deg_U == min_deg_U and u > u_best):
                        max_common = common
                        min_deg_U = deg_U
                        u_best = u
                # Add u_best to S
                S.add(u_best)
                U.remove(u_best)
                # Move neighbors of u_best from U to W
                for w in adj_list[u_best]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degree = [len(adj_list[u]) for u in range(n)]
        removed = [False] * n
        order = []
        # We'll use buckets for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u] and degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                break  # should not happen
            removed[v] = True
            order.append(v)
            for w in adj_list[v]:
                if not removed[w]:
                    degree[w] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Greedy on complement (clique cover via greedy clique in complement)
    def greedy_complement():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Start with a vertex, grow clique in complement
            v = next(iter(uncolored))
            clique = {v}
            # Candidates: vertices in uncolored not in clique that are adjacent to all in clique in complement
            cand = set()
            for u in uncolored:
                if u != v and (comp_adj[v] >> u) & 1:
                    cand.add(u)
            while cand:
                # Select vertex with max degree in cand (in complement subgraph)
                u_best = -1
                max_deg = -1
                for u in cand:
                    deg_u = 0
                    for w in cand:
                        if u != w and (comp_adj[u] >> w) & 1:
                            deg_u += 1
                    if deg_u > max_deg or (deg_u == max_deg and u > u_best):
                        max_deg = deg_u
                        u_best = u
                # Add u_best to clique
                clique.add(u_best)
                cand.remove(u_best)
                # Update cand: keep only those adjacent to u_best in complement
                cand = {w for w in cand if (comp_adj[u_best] >> w) & 1}
            # Assign color c to clique (independent set in original)
            for u in clique:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Run all strategies
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last),
        ("Greedy Complement", greedy_complement)
    ]
    for name, strat in strategies:
        try:
            coloring = strat()
            # Validate coloring
            valid = True
            for u in range(n):
                for v in adj_list[u]:
                    if u < v and color[u] == color[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                k = num_colors(coloring)
                if k < best_k:
                    best_k = k
                    best_coloring = coloring[:]
        except Exception:
            continue

    # Fallback: if no strategy worked (should not happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))

    # Compact colors: ensure 0..k-1
    if best_coloring:
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_coloring[i] = unique_colors[c]

    return best_coloring

