                                        visited.add(u)
                                        queue.append(u)
                        # Check if swapping is safe: no neighbor of component has color c
                        # (other than those in component)
                        safe = True
                        for node in component:
                            for u in neighbors[node]:
                                if u not in component and col[u] == c:
                                    safe = False
                                    break
                            if not safe:
                                break
                        if safe:
                            # Perform swap: c <-> color_to_remove in component
                            for node in component:
                                if col[node] == c:
                                    col[node] = color_to_remove
                                elif col[node] == color_to_remove:
                                    col[node] = c
                            # Update classes
                            if color_to_remove in classes:
                                classes[color_to_remove] = [v for v in classes[color_to_remove] if col[v] == color_to_remove]
                            if c not in classes:
                                classes[c] = []
                            classes[c] = [v for v in classes[c] if col[v] == c]
                            # Rebuild classes for simplicity (could be optimized)
                            classes = {}
                            for ii in range(n):
                                cc = col[ii]
                                if cc not in classes:
                                    classes[cc] = []
                                classes[cc].append(ii)
                            changed = True
                            break  # Break Kempe loop, restart while
                if changed:
                    break  # Break color_to_remove loop, restart while
            if changed:
                break  # Break outer while to restart

        # Compact colors: map to 0..k-1
        # Get unique colors used
        unique_colors = sorted(set(col))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        col = [mapping[c] for c in col]
        return col

    # Apply Kempe reduction to best coloring
    try:
        reduced = kempe_reduction(best_coloring)
        if is_valid(reduced):
            best_coloring = reduced
    except:
        pass  # Keep original if reduction fails

    # Final validation and compacting (ensure 0..k-1)
    if not is_valid(best_coloring):
        # Fallback to greedy if invalid
        best_coloring = greedy_color(list(range(n)))

    # Compact colors one last time
    unique_colors = sorted(set(best_coloring))
    if unique_colors != list(range(len(unique_colors))):
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

