def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                adj_list[i].append(j)
                bit_adj[i] |= (1 << j)

    deg = [len(adj_list[i]) for i in range(n)]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                v = max(uncolored, key=lambda x: deg[x])
            else:
                v = max(candidates, key=lambda x: deg[x])
            neighbor_colors = set()
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            c = 0
            while c in neighbor_colors:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in adj_list[v]:
                if color[u] == -1:
                    sat[u] += 1
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Start new color class
            S = set()
            # Pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for u in adj_list[x] if u in uncolored))
            S.add(v)
            uncolored.remove(v)
            # Partition: U (eligible), W (ineligible)
            W = set()
            for u in adj_list[v]:
                if u in uncolored:
                    W.add(u)
            U = uncolored - W
            while U:
                # Select u in U with max neighbors in W
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for x in adj_list[u] if x in W)
                    deg_in_U = sum(1 for x in adj_list[u] if x in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                S.add(u)
                uncolored.remove(u)
                U.remove(u)
                # Update W and U: move neighbors of u in U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        color = [-1] * n
        # Build core ordering (smallest-last)
        remaining = set(range(n))
        order = []
        deg_copy = deg[:]
        # Recompute degrees in induced subgraph dynamically
        while remaining:
            v = min(remaining, key=lambda x: sum(1 for u in adj_list[x] if u in remaining))
            order.append(v)
            remaining.remove(v)
        # Color in reverse order
        for v in reversed(order):
            used = set()
            for u in adj_list[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(color, a, b, v, bit_adj):
        from collections import deque
        if color[v] not in (a, b):
            return False
        queue = deque([v])
        visited = set([v])
        component = []
        while queue:
            node = queue.popleft()
            component.append(node)
            neighbors = bit_adj[node]
            while neighbors:
                w = (neighbors & -neighbors).bit_length() - 1
                neighbors &= neighbors - 1
                if color[w] in (a, b) and w not in visited:
                    visited.add(w)
                    queue.append(w)
        # Swap colors in component
        for node in component:
            if color[node] == a:
                color[node] = b
            else:
                color[node] = a
        return True

    # Try to eliminate the smallest color class using direct reassignment and Kempe swaps
    def reduce_color_count(color):
        if max(color) < 0:
            return color
        k = max(color) + 1
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            vertices = [v for v in range(n) if color[v] == target_color]
            if not vertices:
                continue
            # Try to recolor each vertex in this class
            changed = True
            while changed and vertices:
                changed = False
                v = vertices.pop()
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if color[u] != -1:
                        neighbor_colors.add(color[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        color[v] = c
                        changed = True
                        break
                if changed:
                    # Rebuild vertices list for this target color
                    vertices = [v for v in range(n) if color[v] == target_color]
                    continue
                # Try Kempe swaps with each lower color
                for c in range(target_color):
                    if kempe_swap(color, target_color, c, v, bit_adj):
                        changed = True
                        # After swap, check if v now has color c (should be)
                        if color[v] == c:
                            break
                        # Otherwise, v still has target_color, try again
                if changed:
                    vertices = [v for v in range(n) if color[v] == target_color]
        # Compact colors to be consecutive starting from 0
        unique_colors = sorted(set(color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[color[v]] for v in range(n)]

    # Validate coloring
    def is_valid(color):
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    return False
        return True

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Apply Kempe reduction to each candidate
    reduced = []
    for col in candidates:
        if is_valid(col):
            reduced.append(reduce_color_count(col[:]))

    # Select the coloring with the fewest colors
    if not reduced:
        # Fallback: greedy by degree order
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        color = [-1] * n
        for v in order:
            used = set()
            for u in adj_list[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        reduced.append(color)

    best = min(reduced, key=lambda c: max(c) + 1 if c else 0)
    # Final validation and compacting
    if not is_valid(best):
        # Last resort: DSATUR again
        best = dsatur()
        best = reduce_color_count(best)
    unique_colors = sorted(set(best))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best = [mapping[best[v]] for v in range(n)]
    return best

