def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build bitmask adjacency
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: count distinct colors
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: convert coloring to consecutive 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets as bitmask for fast saturation update
        neighbor_colors = [0] * n
        # degrees for tie-breaking
        deg = [len(adj_list[i]) for i in range(n)]
        colored = [False] * n

        # Select first vertex: max degree
        v = max(range(n), key=lambda x: deg[x])
        coloring[v] = 0
        colored[v] = True
        # Update neighbors of v
        for u in adj_list[v]:
            if not colored[u]:
                neighbor_colors[u] |= (1 << 0)
                sat[u] = 1

        for _ in range(1, n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            candidates = []
            max_sat = -1
            for u in range(n):
                if not colored[u]:
                    if sat[u] > max_sat:
                        max_sat = sat[u]
                        candidates = [u]
                    elif sat[u] == max_sat:
                        candidates.append(u)
            # Tie-break by degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                new_candidates = []
                for u in candidates:
                    # count uncolored neighbors
                    d = 0
                    for w in adj_list[u]:
                        if not colored[w]:
                            d += 1
                    if d > max_deg:
                        max_deg = d
                        new_candidates = [u]
                    elif d == max_deg:
                        new_candidates.append(u)
                candidates = new_candidates
            # Final tie-break randomly
            v = random.choice(candidates) if candidates else 0
            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True
            # Update neighbors
            for u in adj_list[v]:
                if not colored[u]:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1
        return normalize(coloring)

    # RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        colored = [False] * n
        color = 0
        # Precompute degrees in full graph for initial selection
        deg = [len(adj_list[i]) for i in range(n)]

        while not all(colored):
            # Step 1: pick uncolored vertex with max degree in uncolored subgraph
            max_deg = -1
            v = -1
            for u in range(n):
                if not colored[u]:
                    d = 0
                    for w in adj_list[u]:
                        if not colored[w]:
                            d += 1
                    if d > max_deg:
                        max_deg = d
                        v = u
            if v == -1:
                break  # should not happen
            # Start independent set S with v
            S = [v]
            colored[v] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if not colored[u]:
                    if u != v and not (adj_list[u] and v in adj_list[u]):  # not adjacent to v
                        U.add(u)
                    else:
                        W.add(u)
            # Step 4: while U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                for u in U:
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    if w_count > max_w_neighbors:
                        max_w_neighbors = w_count
                        best_u = u
                    elif w_count == max_w_neighbors:
                        # Tie-break: min degree in G[U]
                        deg_u = 0
                        for w in adj_list[u]:
                            if w in U:
                                deg_u += 1
                        deg_best = 0
                        for w in adj_list[best_u]:
                            if w in U:
                                deg_best += 1
                        if deg_u < deg_best:
                            best_u = u
                if best_u == -1:
                    break
                # Add best_u to S
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for u in S:
                coloring[u] = color
            color += 1
        return normalize(coloring)

    # Smallest-Last (Matula-Beck) ordering greedy
    def smallest_last():
        # Build degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll update degrees as we remove vertices
        curr_degree = degree[:]
        for _ in range(n):
            # find vertex with min curr_degree in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if curr_degree[u] < min_deg:
                    min_deg = curr_degree[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # decrease degree of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    curr_degree[u] -= 1
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen if input is valid
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest down
        improved = True
        while improved and k > 1:
            improved = False
            # Target the smallest color class (highest color index)
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [i for i in range(n) if coloring[i] == target_color]
            if not target_vertices:
                # already empty, compact
                for i in range(n):
                    if coloring[i] > target_color:
                        coloring[i] -= 1
                k -= 1
                improved = True
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        used |= (1 << coloring[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # Check if moving v to c causes conflict (shouldn't by used)
                        coloring[v] = c
                        # Re-normalize might be needed later, but we check validity after
                        break
                else:
                    # Direct reassignment not possible, try Kempe chains
                    for c in range(target_color):
                        # Consider swapping colors target_color and c in the component of v
                        # Only if v is not adjacent to any vertex of color c (otherwise swap might not help)
                        has_adj_c = False
                        for u in adj_list[v]:
                            if coloring[u] == c:
                                has_adj_c = True
                                break
                        if has_adj_c:
                            continue  # swapping would not free color c for v
                        # Build Kempe chain: vertices reachable from v via alternating colors c and target_color
                        stack = [v]
                        visited = set()
                        color_c_vertices = set()
                        color_target_vertices = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            col = coloring[node]
                            if col == c:
                                color_c_vertices.add(node)
                            elif col == target_color:
                                color_target_vertices.add(node)
                            else:
                                continue
                            for nb in adj_list[node]:
                                if nb not in visited and (coloring[nb] == c or coloring[nb] == target_color):
                                    stack.append(nb)
                        # Swapping is safe if no vertex in color_c_vertices is adjacent to a vertex in color_target_vertices outside the chain?
                        # Actually, swapping within a connected component of the subgraph induced by colors {c, target_color} is always safe.
                        # But we want to free color target_color for v, so we need v to be in the chain and after swap, v gets color c.
                        # However, if v is in the chain, after swap it will be color c (if it was target_color) or target_color (if it was c).
                        # We want v to become color c, so v must currently be target_color.
                        if v in color_target_vertices:
                            # Perform swap: c <-> target_color in the component
                            for node in color_c_vertices:
                                coloring[node] = target_color
                            for node in color_target_vertices:
                                coloring[node] = c
                            # Now v has color c
                            break
                    else:
                        # Could not recolor v via Kempe chain, continue to next vertex
                        continue
                    # If we broke out of the c loop, we successfully recolored v
                    break
                else:
                    # Failed to recolor v, continue to next target vertex
                    continue
                # If we successfully recolored v, break to restart the color reduction
                improved = True
                break
            if improved:
                # Re-normalize and update k
                coloring = normalize(coloring)
                k = num_colors(coloring)
        return coloring

    # Generate candidates
    start_time = time.time()
    candidates = []

    # DSATUR
    c1 = dsatur()
    if is_valid(c1):
        candidates.append(c1)
    # RLF
    c2 = rlf()
    if is_valid(c2):
        candidates.append(c2)
    # Smallest-Last
    c3 = smallest_last()
    if is_valid(c3):
        candidates.append(c3)

    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for c in candidates:
        k = num_colors(c)
        if k < best_k:
            best_k = k
            best = c
    if best is None:
        # fallback: greedy in order
        coloring = [-1] * n
        for i in range(n):
            used = 0
            for u in adj_list[i]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[i] = c
        best = normalize(coloring)

    # Apply Kempe reduction to best candidate
    best = kempe_reduce(best)
    # Final validation and normalization
    if not is_valid(best):
        # last resort: greedy
        coloring = [-1] * n
        for i in range(n):
            used = 0
            for u in adj_list[i]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[i] = c
        best = normalize(coloring)
    else:
        best = normalize(best)

    # Ensure within time limit (approximate)
    # if time.time() - start_time > 0.05:
    #     pass  # In practice, should be under 50ms for n<=100

    return best

