            if len(candidates) == 1:
                v = candidates[0]
            else:
                # Tie-break: max degree in uncolored subgraph
                def deg_in_uncolored(u):
                    return (bit_adj[u] & sum(1 << w for w in uncolored)).bit_count()
                v = max(candidates, key=deg_in_uncolored)
            # Assign smallest available color
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] == -1:
                    sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set S for color c
            # Start with vertex of max degree in uncolored subgraph
            def deg_in_uncolored(u):
                return (bit_adj[u] & sum(1 << w for w in uncolored)).bit_count()
            v = max(uncolored, key=deg_in_uncolored)
            S = {v}
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any((bit_adj[u] >> w) & 1 for w in S):
                    U.remove(u)
                    W.add(u)
            # Expand S
            while U:
                # Select u in U with max neighbors in W
                best_u = None
                best_score = -1
                for u in U:
                    score = sum(1 for w in W if (bit_adj[u] >> w) & 1)
                    if score > best_score or (score == best_score and (best_u is None or (bit_adj[u] & sum(1 << w for w in U)).bit_count() < (bit_adj[best_u] & sum(1 << w for w in U)).bit_count())):
                        best_score = score
                        best_u = u
                if best_u is None:
                    break  # Should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in list(U):
                    if (bit_adj[best_u] >> w) & 1:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering (smallest last)
        remaining = set(range(n))
        order = []
        degrees = [bit_adj[i].bit_count() for i in range(n)]
        # We'll use bucket sort for efficiency, but n <= 100 so simple loop is fine
        temp_deg = degrees[:]
        for _ in range(n):
            # Find vertex with minimum degree in remaining
            v = min(remaining, key=lambda x: temp_deg[x])
            order.append(v)
            remaining.remove(v)
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    temp_deg[u] -= 1
        # Color in reverse order
        return greedy_color(reversed(order))

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        candidates.append(col_sl)
    except Exception:
        pass
    # Also try Welsh-Powell (sort by degree descending)
    try:
        order_wp = sorted(range(n), key=lambda x: bit_adj[x].bit_count(), reverse=True)
        col_wp = greedy_color(order_wp)
        candidates.append(col_wp)
    except Exception:
        pass

    # Select the candidate with the fewest colors
    def num_colors(col):
        return max(col) + 1 if col else 0
    best_color = min(candidates, key=num_colors) if candidates else [0] * n
    k = num_colors(best_color)

    # If already optimal (lower bound from clique or degree), we could stop, but we try to reduce
    # Kempe chain based color reduction
    def kempe_reduction(color):
        nonlocal k
        # We'll try to eliminate the highest color class
        changed = True
        while changed and k > 0:
            changed = False
            # Find vertices with color k-1
            vertices_k = [v for v in range(n) if color[v] == k-1]
            if not vertices_k:
                k -= 1
                continue
            # Try to recolor each vertex in color k-1
            for v in vertices_k:
                # Try direct reassignment to a lower color
                used = 0
                for u in range(n):
                    if (bit_adj[v] >> u) & 1 and color[u] != -1:
                        used |= 1 << color[u]
                for c in range(k-1):
                    if not (used & (1 << c)):
                        # Can recolor v to c
                        color[v] = c
                        changed = True
                        break
                if changed:
                    break  # Restart while loop after change
                # Try Kempe chains with each lower color
                for c in range(k-1):
                    # If v already has color c after possible direct reassignment, skip
                    if color[v] == c:
                        continue
                    # Check if there is no path between v and any vertex of color c using only colors c and k-1
                    # We'll do BFS/DFS on the subgraph induced by colors c and k-1
                    from collections import deque
                    visited = [False] * n
                    queue = deque()
                    # Start from v if it has color c or k-1? Actually v is k-1, so we start from v
                    # We want to see if v is connected to any vertex of color c in the (c, k-1) subgraph
                    # If not, we can swap colors in the component containing v
                    # But note: v is color k-1, so we start from v and traverse only vertices of color c or k-1
                    if color[v] not in (c, k-1):
                        continue  # Should not happen
                    queue.append(v)
                    visited[v] = True
                    found_c = False  # whether we encountered a vertex of color c in this component
                    while queue:
                        x = queue.popleft()
                        if color[x] == c:
                            found_c = True
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1 and not visited[y] and color[y] in (c, k-1):
                                visited[y] = True
                                queue.append(y)
                    if not found_c:
                        # No vertex of color c in this component, we can swap c and k-1 in this component
                        for x in range(n):
                            if visited[x]:
                                if color[x] == c:
                                    color[x] = k-1
                                elif color[x] == k-1:
                                    color[x] = c
                        changed = True
                        break  # break from color loop
                if changed:
                    break  # break from vertex loop
            if not changed:
                # Could not eliminate color k-1, break
                break
            # After successful elimination, compact colors: but we already swapped, so k-1 might still be used?
            # Actually, if we eliminated color k-1 by moving all its vertices, we should reduce k
            # Recompute k
            new_k = num_colors(color)
            if new_k < k:
                k = new_k
                changed = True  # continue to try to reduce further
            else:
                # Should not happen if we removed a color, but safety break
                break
        return color

    # Apply Kempe reduction
    try:
        best_color = kempe_reduction(best_color)
    except Exception:
        pass

    # Final validation and compaction of colors (ensure 0..k-1)
    # Remap colors to consecutive integers
    mapping = {}
    next_color = 0
    for v in range(n):
        c = best_color[v]
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
        best_color[v] = mapping[c]
    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets and bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Initial vertex: max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        while uncolored:
            # Find vertex with max sat, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                # All sat 0, pick max degree in uncolored
                v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            else:
                # Tie-break by degree in uncolored subgraph
                v = max(candidates, key=lambda x: len(neighbors[x] & uncolored))
            # Assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        return color

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with max degree vertex in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = uncolored - {v} - (neighbors[v] & uncolored)
            # W: vertices adjacent to independent_set
            W = (neighbors[v] & uncolored)
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = None
                best_score = -1
                best_deg = float('inf')
                for u in U:
                    score = len(neighbors[u] & W)
                    deg_u = len(neighbors[u] & U)
                    if score > best_score or (score == best_score and deg_u < best_deg):
                        best_score = score
                        best_deg = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbors[u] & U
                U -= nbrs_u
                W |= nbrs_u
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[v]) for v in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d < len(buckets):
                buckets[d].add(v)
        # Peel
        for _ in range(n):
            # Find non-empty bucket with smallest index
            d = 0
            while d < len(buckets) and not buckets[d]:
                d += 1
            if d >= len(buckets):
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # Remove u from its current bucket
                    du = degree[u]
                    if du < len(buckets) and u in buckets[du]:
                        buckets[du].remove(u)
                    degree[u] -= 1
                    if degree[u] < len(buckets):
                        buckets[degree[u]].add(u)
            remaining.remove(v)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                k = count_colors(col)
                if k < best_k:
                    best_k = k
                    best_coloring = col[:]
        except Exception:
            continue

    # Fallback: greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Ensure colors are compact 0..k-1
        def compact(col):
            mapping = {}
            next_c = 0
            for v in range(n):
                c = col[v]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                col[v] = mapping[c]
            return col

        coloring = compact(coloring[:])
        k = count_colors(coloring)
        improved = True
        while improved and k > 1:
            improved = False
            # Target smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Should not happen if compact
                break
            # Try to recolor each target vertex
            for v in target_vertices:
                used = set()
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != target_color:
                        used.add(c)
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if c not in used:
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {c, target_color}
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == c or coloring[node] == target_color:
                            component.add(node)
                            for u in neighbors[node]:
                                if u not in visited and (coloring[u] == c or coloring[u] == target_color):
                                    stack.append(u)
                    # Check if any neighbor of v in the component has color c? Actually, we need to see if swapping removes v from target_color
                    # After swap, v will get color c if it was target_color, which is what we want.
                    # But we must ensure that no vertex in the component that is adjacent to v and has color c will cause conflict? 
                    # Actually, swapping is safe: adjacent vertices have different colors, so after swap they still differ.
                    # However, we must ensure that we do not introduce a duplicate color in the neighborhood? 
                    # The swap only changes colors within the component, and since the component is induced by {c, target_color}, 
                    # and adjacent vertices have different colors, swapping preserves validity.
                    # But we want to know if after swap, v is no longer color target_color (i.e., we can reduce the class).
                    # Since v is in the component and has color target_color, after swap it will have color c.
                    # So we can assign v to c and swap the component.
                    # However, we must check that no vertex in the component that is colored c and adjacent to v will become target_color and conflict? 
                    # Actually, if a vertex u in component is colored c and adjacent to v, then after swap u becomes target_color. 
                    # But v becomes c, so edge (v,u) will have colors c and target_color -> still different.
                    # So the swap is always valid.
                    # However, we must ensure that we do not pull other vertices into target_color? 
                    # The goal is to eliminate target_color from v. After swap, v is no longer target_color.
                    # But we might have added other vertices to target_color (those that were c and swapped to target_color).
                    # However, if we are targeting the entire color class elimination, we need to do this for all vertices.
                    # For now, we just try to recolor v to a lower color via Kempe chain.
                    # Perform the swap
                    for node in component:
                        if coloring[node] == c:
                            coloring[node] = target_color
                        else:  # must be target_color
                            coloring[node] = c
                    # Now v has color c (since it was target_color)
                    improved = True
                    break
                if improved:
                    break
            if improved:
                # Compact again
                coloring = compact(coloring)
                k = count_colors(coloring)
            else:
                # Could not eliminate any vertex from target color class, break
                break
        return coloring

    best_coloring = kempe_reduce(best_coloring)
    # Final validation and compact
    if not is_valid(best_coloring):
        # Last resort: greedy
        best_coloring = greedy_color(list(range(n)))
    best_coloring = compact(best_coloring) if 'compact' in locals() else best_coloring
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix vs list
    is_matrix = (len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for x in adj[0]))
    if is_matrix:
        # Convert matrix to adjacency list
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Convert adjacency list to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits
    def popcount(x):
        return x.bit_count()

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: DSATUR with bitmask optimization
    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [popcount(bit_adj[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = popcount(sat[v])
                d = uncolored_deg[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            uncolored.remove(v)
            # assign smallest free color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            # update neighbors
            for u in adj_list[v]:
                if colors[u] == -1:  # u is uncolored
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return colors

    # Helper: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: popcount(bit_adj[x] & sum((1 << u) for u in uncolored)))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = uncolored - independent_set
            W = set()
            for u in U:
                if bit_adj[u] & sum((1 << x) for x in independent_set):
                    W.add(u)
                else:
                    # u is not adjacent to independent_set, so in U
                    pass
            # Actually, recompute U and W properly
            U = {u for u in uncolored if u not in independent_set and not (bit_adj[u] & sum((1 << x) for x in independent_set))}
            W = uncolored - independent_set - U

            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    # neighbors in W
                    nbrs_in_W = bit_adj[u] & sum((1 << w) for w in W)
                    score = popcount(nbrs_in_W)
                    # degree in U-induced subgraph
                    deg_U = popcount(bit_adj[u] & sum((1 << x) for x in U))
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or (score == best_score and deg_U == best_deg_U and random.random() < 0.5):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                independent_set.add(u)
