                # move neighbors of u from U to W
                for w in list(U):
                    if bit_adj[u] & (1 << w):
                        U.remove(w)
                        W.add(w)
            # assign color to independent_set
            for v in independent_set:
                colors[v] = color
            uncolored -= independent_set
            color += 1
        return colors

    # Helper: smallest-last ordering
    def smallest_last():
