    # Select candidate with fewest colors
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        k = max(col) + 1 if col else 0
        if k < best_k:
            best_k = k
            best_coloring = col

    if best_coloring is None:
        # fallback: greedy with natural order
        best_coloring = greedy_color(list(range(n)))

    # Kempe chain color reduction
    def kempe_reduce(colors):
        # make a copy we can modify
        col = colors[:]
        changed = True
        while changed:
            changed = False
            # find color classes
            classes = {}
            for v, c in enumerate(col):
                classes.setdefault(c, []).append(v)
            if not classes:
                break
            max_color = max(classes.keys())
            # try to eliminate color classes from highest down
            for c in range(max_color, 0, -1):
                if c not in classes or not classes[c]:
                    continue
                # try to recolor each vertex in class c
                verts = classes[c][:]
                for v in verts:
                    if col[v] != c:  # might have been recolored already
                        continue
                    # try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in adj_list[v]:
                        if col[u] != -1:
                            neighbor_colors.add(col[u])
                    for c_new in range(c):
                        if c_new not in neighbor_colors:
                            col[v] = c_new
                            changed = True
                            break
                    if changed:
                        # update classes and break to restart
                        break
                if changed:
                    break
                # if no direct reassignment, try Kempe chains
                for v in verts:
                    if col[v] != c:
                        continue
                    for c2 in range(c):
                        # check if v can swap with c2 via Kempe chain
                        # BFS to find the Kempe chain component for (c, c2) containing v
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        component = set()
                        while queue:
                            node = queue.popleft()
                            component.add(node)
                            for nb in adj_list[node]:
                                if col[nb] == c or col[nb] == c2:
                                    if nb not in visited:
                                        visited.add(nb)
                                        queue.append(nb)
                        # check if any neighbor of v with color c2 is NOT in this component
                        has_external_c2 = False
                        for nb in adj_list[v]:
                            if col[nb] == c2 and nb not in component:
                                has_external_c2 = True
                                break
                        if not has_external_c2:
                            # we can swap c and c2 in this component
                            for node in component:
                                if col[node] == c:
                                    col[node] = c2
                                elif col[node] == c2:
                                    col[node] = c
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # after attempting to eliminate a color, compact if needed
            if changed:
                # rebuild color mapping to be consecutive
                used_colors = sorted(set(col))
                mapping = {old: new for new, old in enumerate(used_colors)}
                col = [mapping[c] for c in col]
        return col

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduce(best_coloring)
    except:
        pass  # if kempe fails, keep the coloring

    # Final validation and compaction
    # Ensure valid coloring
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # conflict, should not happen, but fix by greedy re-color
                best_coloring = greedy_color(list(range(n)))
                break
        else:
            continue
        break

    # Compact colors to 0..k-1
    used = sorted(set(best_coloring))
    if used != list(range(len(used))):
        mapping = {old: new for new, old in enumerate(used)}
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

