    bit_adj = [0] * n
    degree = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    bit_adj[u] |= (1 << v)
                    degree[u] += 1
    else:
        for u in range(n):
            for v in adj[u]:
                if v < 0 or v >= n:
                    continue
                bit_adj[u] |= (1 << v)
                degree[u] += 1

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            nbrs = bit_adj[v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                c = color[u]
                if c != -1:
                    used |= (1 << c)
                nbrs &= nbrs - 1
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

