        max_deg = -1
        for u in uncolored:
            if sat[u] > max_sat or (sat[u] == max_sat and degree[u] > max_deg) or \
               (sat[u] == max_sat and degree[u] == max_deg and (v == -1 or random.random() < 0.5)):
                max_sat = sat[u]
                max_deg = degree[u]
                v = u
        # assign smallest available color
        used = 0
        nbrs = bit_adj[v]
        while nbrs:
            u = (nbrs & -nbrs).bit_length() - 1
            c = color[u]
            if c != -1:
                used |= (1 << c)
            nbrs &= nbrs - 1
        c = 0
        while used & (1 << c):
            c += 1
