        nbrs = bit_adj[v]
        while nbrs:
            u = (nbrs & -nbrs).bit_length() - 1
            if u in uncolored:
                sat[u] += 1
            nbrs &= nbrs - 1
    k = count_colors(color)
    if k < best_k:
        best_k = k
        best_color = color[:]

    # 2. RLF (Largest First Independent Set Extraction)
    color = [-1] * n
    uncolored = set(range(n))
    c = 0
    while uncolored:
        # induced subgraph on uncolored: compute degrees
        deg_sub = [0] * n
        for u in uncolored:
            nbrs = bit_adj[u]
            while nbrs:
                v = (nbrs & -nbrs).bit_length() - 1
                if v in uncolored:
                    deg_sub[u] += 1
                nbrs &= nbrs - 1
        # select vertex with max degree in subgraph
        v = max(uncolored, key=lambda x: deg_sub[x])
        S = {v}
        uncolored.remove(v)
        # U: not adjacent to S, W: adjacent to S
        U = {u for u in uncolored if (bit_adj[u] & sum(1 << w for w in S)) == 0}
        W = uncolored - U
        while U:
            # select u in U with max |N(u) ∩ W|
            best_u = -1
            max_w = -1
            min_deg_u = float('inf')
            for u in U:
                # count neighbors in W
                nbrs = bit_adj[u]
                cnt = 0
                while nbrs:
                    v = (nbrs & -nbrs).bit_length() - 1
                    if v in W:
                        cnt += 1
                    nbrs &= nbrs - 1
                # degree in U-induced subgraph
                deg_u = 0
                nbrs = bit_adj[u]
                while nbrs:
                    v = (nbrs & -nbrs).bit_length() - 1
                    if v in U:
                        deg_u += 1
                    nbrs &= nbrs - 1
                if cnt > max_w or (cnt == max_w and deg_u < min_deg_u) or \
                   (cnt == max_w and deg_u == min_deg_u and (best_u == -1 or random.random() < 0.5)):
                    max_w = cnt
                    min_deg_u = deg_u
                    best_u = u
            u = best_u
            S.add(u)
            uncolored.remove(u)
