    def kempe_reduce(color):
        nonlocal n, bit_adj
        # make color indices consecutive
        unique_colors = {}
        next_color = 0
        for v in range(n):
            c = color[v]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            color[v] = unique_colors[c]
        k = next_color
        if k <= 1:
            return color
        improved = True
        while improved and k > 1:
            improved = False
            # find smallest color class
            class_size = [0] * k
            for v in range(n):
