                break
            # try to recolor each vertex of target_color
            target_vertices = [v for v in range(n) if color[v] == target_color]
            for v in target_vertices:
                # try direct reassignment to a lower color
                used = 0
                nbrs = bit_adj[v]
                while nbrs:
                    u = (nbrs & -nbrs).bit_length() - 1
                    c = color[u]
                    if c != -1:
                        used |= (1 << c)
