                        color[v] = c
                        improved = True
                        break
                if improved:
                    # rebuild class sizes and maybe reduce k
                    class_size = [0] * k
                    for v in range(n):
                        class_size[color[v]] += 1
                    # find new k
                    new_k = 0
                    for c in range(k-1, -1, -1):
                        if class_size[c] > 0:
                            new_k = c + 1
                            break
                    if new_k < k:
                        k = new_k
                        # reindex colors to be 0..k-1
                        mapping = {}
                        next_c = 0
                        for c in range(k):
                            if class_size[c] > 0:
                                mapping[c] = next_c
                                next_c += 1
                        for v in range(n):
                            color[v] = mapping[color[v]]
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # BFS to find Kempe chain component of v in colors {target_color, c}
                    from collections import deque
                    comp = set()
                    q = deque([v])
                    comp.add(v)
                    while q:
                        x = q.popleft()
