                        while nbrs:
                            y = (nbrs & -nbrs).bit_length() - 1
                            if color[y] == target_color or color[y] == c:
                                if y not in comp:
                                    comp.add(y)
                                    q.append(y)
                            nbrs &= nbrs - 1
                    # check if swapping colors in component is safe: no neighbor outside comp has color c after swap
                    safe = True
                    nbrs = bit_adj[v]
                    while nbrs and safe:
                        y = (nbrs & -nbrs).bit_length() - 1
                        if y not in comp and color[y] == c:
                            safe = False
                        nbrs &= nbrs - 1
                    if safe:
                        # perform swap
                        for x in comp:
                            if color[x] == target_color:
                                color[x] = c
                            else:
                                color[x] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # reindex colors
                class_size = [0] * k
                for v in range(n):
                    class_size[color[v]] += 1
                new_k = 0
                for c in range(k-1, -1, -1):
                    if class_size[c] > 0:
                        new_k = c + 1
                        break
                if new_k < k:
                    k = new_k
                    mapping = {}
                    next_c = 0
                    for c in range(k):
                        if class_size[c] > 0:
                            mapping[c] = next_c
                            next_c += 1
                    for v in range(n):
                        color[v] = mapping[color[v]]
        return color

    best_color = kempe_reduce(best_color)

    # Final validation and compacting
    def validate_and_compact(color):
        # check validity
        for u in range(n):
            nbrs = bit_adj[u]
            while nbrs:
                v = (nbrs & -nbrs).bit_length() - 1
                if color[u] == color[v]:
