        unique = {}
        next_c = 0
        for v in range(n):
            c = color[v]
            if c not in unique:
                unique[c] = next_c
                next_c += 1
            color[v] = unique[c]
        return color

    best_color = validate_and_compact(best_color)
    return best_color

