    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        bit_adj = [0] * n
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    bit_adj[u] |= 1 << v
    else:
        # Adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                bit_adj[u] |= 1 << v

    # Helper: DSATUR
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        sat = [0] * n  # saturation degree
        deg = [bit_adj[i].bit_count() for i in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if not colored[i]:
                    if sat[i] > max_sat or (sat[i] == max_sat and deg[i] > max_deg) or \
                       (sat[i] == max_sat and deg[i] == max_deg and (v == -1 or random.random() < 0.5)):
                        max_sat = sat[i]
                        max_deg = deg[i]
                        v = i
            # Assign smallest available color
            used = 0
            for u in range(n):
                if colored[u] and (bit_adj[v] >> u) & 1:
                    used |= 1 << colors[u]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            # Update saturation of neighbors
            for u in range(n):
                if not colored[u] and (bit_adj[v] >> u) & 1:
                    sat[u] += 1
        return colors

    # Helper: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for y in uncolored if (bit_adj[x] >> y) & 1))
                S.add(v)
                uncolored.remove(v)
            # W: neighbors of S (ineligible), U: uncolored and not adjacent to S (eligible)
            W = set()
            for u in S:
                for v in range(n):
                    if (bit_adj[u] >> v) & 1 and v in uncolored:
                        W.add(v)
            U = uncolored - W
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for v in range(n) if ((bit_adj[u] >> v) & 1) and v in W)
                    deg_in_U = sum(1 for v in range(n) if ((bit_adj[u] >> v) & 1) and v in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.add(best_u)
                uncolored.remove(best_u)
                # Update W and U: move neighbors of best_u from U to W
                for v in range(n):
                    if ((bit_adj[best_u] >> v) & 1) and v in U:
                        W.add(v)
                        U.remove(v)
            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
        return colors

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        deg = [bit_adj[i].bit_count() for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current min degree
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    old_deg = deg[u]
                    deg[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].remove(u)
                    if deg[u] <= max_deg:
                        buckets[deg[u]].append(u)
                    if deg[u] < ptr:
                        ptr = deg[u]
        # Color in reverse order using greedy
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in range(n):
                if colors[u] != -1 and (bit_adj[v] >> u) & 1:
                    used |= 1 << colors[u]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: max(x) + 1 if x else 0)
    k = max(best) + 1 if best else 0

    # Kempe chain color reduction
    def kempe_reduction(colors):
        nonlocal n, bit_adj
        changed = True
        while changed:
            changed = False
            # Find smallest color class
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                if colors[v] < k:  # only consider current colors
                    color_classes[colors[v]].append(v)
            # Try to eliminate from highest color down
            for c in range(k-1, -1, -1):
                if not color_classes[c]:
                    continue
                # Try to recolor each vertex in class c
                for v in color_classes[c][:]:  # iterate over copy
                    # Try direct reassignment to lower color
                    for c2 in range(c):
                        conflict = False
                        for u in range(n):
                            if (bit_adj[v] >> u) & 1 and colors[u] == c2:
                                conflict = True
                                break
                        if not conflict:
                            colors[v] = c2
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chains with each lower color
                    for c2 in range(c):
                        # Find Kempe chain component of v in colors {c, c2}
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for u in range(n):
                                if (bit_adj[node] >> u) & 1 and not visited[u]:
                                    if colors[u] == c or colors[u] == c2:
                                        visited[u] = True
                                        queue.append(u)
                        # Check if swapping c and c2 in component frees color c2 for v
                        # Actually, we want to see if after swap, v can be c2 (i.e., no neighbor in component has c2 after swap?)
                        # Instead: after swap, neighbors of v that were c2 become c, and vice versa.
                        # We want that no neighbor of v has color c2 after swap.
                        # Neighbors of v: if originally color c2, after swap become c -> not c2.
                        # If originally color c, after swap become c2 -> conflict.
                        # So we need that no neighbor of v is originally color c (because they'd become c2).
                        has_c_neighbor = False
                        for u in range(n):
                            if (bit_adj[v] >> u) & 1 and colors[u] == c:
                                has_c_neighbor = True
                                break
                        if not has_c_neighbor:
                            # Perform swap
                            for node in component:
                                if colors[node] == c:
                                    colors[node] = c2
                                elif colors[node] == c2:
                                    colors[node] = c
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # Compact colors if any class is empty
            if changed:
                # Re-map colors to 0..k'-1
                mapping = {}
                new_color = 0
                for c in range(k):
                    if color_classes[c]:
                        mapping[c] = new_color
                        new_color += 1
                for v in range(n):
                    if colors[v] in mapping:
                        colors[v] = mapping[colors[v]]
                k = new_color
        return colors

    best = kempe_reduction(best)
    # Final validation and compacting
    # Ensure colors are consecutive
    used_colors = set(best)
    mapping = {}
    new_color = 0
    for c in sorted(used_colors):
        mapping[c] = new_color
        new_color += 1
    for i in range(n):
        best[i] = mapping[best[i]]
    return best

