            color[u] = c
            uncolored.remove(u)
            # update saturation and uncolored degree for neighbors
            for v in adj_list[u]:
                if v in uncolored:
                    saturation[v] |= (1 << c)
                    uncolored_deg[v] -= 1
        return color

    # 2. RLF (Recursive Largest First)
    def rlf():
