            U = {u for u in uncolored if u not in S and all(u not in adj_list[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = sum(1 for y in adj_list[u] if y in W)
                    deg_U = sum(1 for y in adj_list[u] if y in U)
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or (score == best_score and deg_U == best_deg_U and (best_u == -1 or random.random() < 0.5)):
                        best_score = score
                        best_deg_U = deg_U
