                if nb in uncolored:
                    # update neighbor color mask
                    neighbor_color_mask[nb] |= (1 << c)
                    # update saturation degree: number of distinct colors in neighbor_color_mask[nb]
                    sat[nb] = bin(neighbor_color_mask[nb]).count('1')
