    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in induced subgraph of uncolored
            deg_uncolored = [0] * n
            for v in uncolored:
                deg_uncolored[v] = bin(bit_adj[v] & sum(1 << u for u in uncolored)).count('1')
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = uncolored - S - {u for u in uncolored if any(bit_adj[w] & (1 << u) for w in S)}
            W = {u for u in uncolored if any(bit_adj[w] & (1 << u) for w in S)}
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = -1
                for u in U:
                    score = bin(bit_adj[u] & sum(1 << w for w in W)).count('1')
                    if score > best_score or (score == best_score):
                        # tie-break by min degree in G[U]
                        degU = bin(bit_adj[u] & sum(1 << w for w in U)).count('1')
                        if score > best_score or (score == best_score and degU < best_degU):
                            best_score = score
                            best_degU = degU
                            best_u = u
                if best_u == -1:
                    best_u = next(iter(U))
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                nbrs = {w for w in U if bit_adj[best_u] & (1 << w)}
                U -= nbrs
                W |= nbrs
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color
    # Helper: Smallest-Last ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        deg = [len(graph[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for nb in graph[v]:
                if nb in remaining:
                    d = deg[nb]
                    buckets[d].remove(nb)
                    deg[nb] -= 1
                    buckets[deg[nb]].append(nb)
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in graph[v]:
                if color[nb] != -1:
                    used |= 1 << color[nb]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # If no candidate, fallback to simple greedy
    if not candidates:
        color = [-1] * n
        for v in range(n):
            used = 0
            for nb in graph[v]:
                if color[nb] != -1:
                    used |= 1 << color[nb]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        candidates.append(color)
    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Kempe chain color reduction
    def kempe_reduction(col):
        # make copy
        col = col[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(col)
            if k <= 1:
                break
            # target smallest color class (color k-1)
            target_color = k - 1
            vertices = [v for v in range(n) if col[v] == target_color]
            if not vertices:
                # should not happen, but skip
                break
            # Try to recolor each vertex in target class
            for v in vertices:
                # try direct reassignment to a lower color
                used = 0
                for nb in graph[v]:
                    if col[nb] != -1:
                        used |= 1 << col[nb]
                for c in range(target_color):
                    if not (used & (1 << c)):
                        col[v] = c
                        changed = True
                        break
                if changed:
                    # after moving v, break to restart
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # find Kempe chain of colors {target_color, c} containing v
                    # BFS/DFS to get component
                    stack = [v]
                    visited = set()
                    comp = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if col[node] == target_color or col[node] == c:
                            comp.add(node)
                            for nb in graph[node]:
                                if nb not in visited and (col[nb] == target_color or col[nb] == c):
                                    stack.append(nb)
                    # check if we can swap: after swap, no neighbor of v will have color c (since v becomes c)
                    # Actually, we need to ensure that swapping does not cause conflict: 
                    # After swap, v becomes c, and we need that no neighbor of v has color c (but they will have target_color after swap)
                    # So we check: for all neighbors u of v, if u in comp, then after swap col[u] becomes target_color, which is not c (since c != target_color)
                    # if u not in comp, col[u] stays same, and we need col[u] != c
                    conflict = False
                    for u in graph[v]:
                        if u in comp:
                            # after swap, u becomes target_color, which is not c (since target_color != c)
                            continue
                        else:
                            if col[u] == c:
                                conflict = True
                                break
                    if not conflict:
                        # perform swap
                        for node in comp:
                            if col[node] == target_color:
                                col[node] = c
                            else:  # col[node] == c
                                col[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            # if we removed all vertices of target_color, we can compact colors
            if not any(col[v] == target_color for v in range(n)):
                # remap colors: shift down all colors > target_color
                for v in range(n):
                    if col[v] > target_color:
                        col[v] -= 1
                changed = True
        return col
    best = kempe_reduction(best)
    # Final validation and compacting (ensure colors are 0..k-1)
    # Compact colors: remap to consecutive
    used_colors = set(best)
    mapping = {}
    for i, c in enumerate(sorted(used_colors)):
        mapping[c] = i
    best = [mapping[c] for c in best]
    return best

