            # select vertex with max sat, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and len([nb for nb in neighbors[u] if nb in uncolored]) > max_deg):
                    max_sat = sat[u]
                    max_deg = len([nb for nb in neighbors[u] if nb in uncolored])
                    v = u
                elif sat[u] == max_sat and len([nb for nb in neighbors[u] if nb in uncolored]) == max_deg and u < v:
                    v = u
            if v == -1:
