            used = 0
            for nb in neighbors[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for nb in neighbors[v]:
                if nb in uncolored:
                    sat[nb] += 1
