                        max_w = w_count
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in list(neighbors[u] & U):
                    U.remove(nb)
                    W.add(nb)
            # assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
