                    if u in visited:
                        continue
                    visited.add(u)
                    if best[u] == c or best[u] == target_color:
                        component.add(u)
                        for nb in neighbors[u]:
                            if nb not in visited and (best[nb] == c or best[nb] == target_color):
                                stack.append(nb)
                # Check if any neighbor of v in component has color c? Actually, we want to see if we can swap
                # After swap, v would become c if it was target_color, provided no neighbor of v becomes target_color conflict
                # Actually, swapping colors in component is safe; we just need to ensure that after swap, v is not target_color
                # Since v is target_color, after swap it becomes c. We must check that no neighbor of v is c after swap?
                # But neighbors of v that are in component and colored c will become target_color, which may conflict if they are adjacent to v?
                # However, if a neighbor u of v is in component and colored c, then after swap u becomes target_color, and v becomes c.
                # Since u and v are adjacent, we would have u: target_color, v: c -> no conflict as long as target_color != c (which is true).
                # But we must also check that no neighbor of v outside the component is colored c? Actually, after swap, neighbors outside component keep their color.
                # So we need to ensure that no neighbor of v is colored c outside the component? Because if neighbor w of v is colored c and not in component, after swap w remains c, and v becomes c -> conflict.
                # Therefore, the swap is valid only if no neighbor of v is colored c outside the component.
                # Equivalent: all neighbors of v colored c are in the component.
                # Let's check:
                conflict = False
                for nb in neighbors[v]:
                    if best[nb] == c and nb not in component:
                        conflict = True
                        break
                if not conflict:
                    # perform swap
                    for u in component:
                        if best[u] == c:
                            best[u] = target_color
                        else:  # best[u] == target_color
                            best[u] = c
                    made_change = True
                    improved = True
                    break
            if made_change:
                break
        if not made_change:
            # cannot eliminate this color, break
            break
        # compact colors: remap to 0..k-2
        # but we already may have changed some vertices; recompute k and remap
        used_colors = set(best)
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        best = [mapping[c] for c in best]
        k = len(used_colors)

    # Final validation and compacting (ensure 0..k-1)
    used_colors = set(best)
    mapping = {old: new for new, old in enumerate(sorted(used_colors)))
    best = [mapping[c] for c in best]
    if not is_valid(best):
        # last resort: greedy with DSATUR order
        best = dsatur()
        used_colors = set(best)
        mapping = {old: new for new, old in enumerate(sorted(used_colors)))
        best = [mapping[c] for c in best]
    return best

