import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    if len(adj) > 0 and len(adj[0]) == n and all(
        isinstance(x, int) and x in (0, 1) for row in adj for x in row
    ):
        # adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    bit_adj[i] |= 1 << j
    else:
        # adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    bit_adj[u] |= 1 << v

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in range(u + 1, n):
                if ((bit_adj[u] >> v) & 1) and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        sat = [0] * n  # saturation degree
        deg = [bin(bit_adj[i]).count('1') for i in range(n)]
        while uncolored:
            # select vertex with max sat, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                if sat[v] > best_sat or (sat[v] == best_sat and (
                    bin(bit_adj[v] & sum(1 << u for u in uncolored)).count('1') > best_deg or
                    (bin(bit_adj[v] & sum(1 << u for u in uncolored)).count('1') == best_deg and v < best_v)
                )):
                    best_sat = sat[v]
                    best_deg = bin(bit_adj[v] & sum(1 << u for u in uncolored)).count('1')
                    best_v = v
            v = best_v
            # assign smallest available color
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= 1 << color[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in uncolored:
                    sat[u] = bin(bit_adj[u] & sum(1 << w for w in range(n) if color[w] != -1)).count('1')
        return color

    # RLF: Recursive Largest First (independent set extraction)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0
        while uncolored:
            # build independent set for current_color
            S = set()
            # choose vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: bin(bit_adj[x] & sum(1 << u for u in uncolored)).count('1'))
            S.add(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - S
            W = set()
            for u in U:
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
            U -= W
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = bin(bit_adj[u] & sum(1 << w for w in W)).count('1')
                    if score > best_score or (score == best_score and bin(bit_adj[u] & sum(1 << w for w in U)).count('1') < bin(bit_adj[best_u] & sum(1 << w for w in U)).count('1') if best_u != -1 else True):
                        best_score = score
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in range(n):
                    if (bit_adj[u] >> w) & 1 and w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to S
            for v in S:
                color[v] = current_color
            uncolored -= S
            current_color += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        deg = [bin(bit_adj[i]).count('1') for i in range(n)]
        # current degree in remaining subgraph
        curr_deg = deg[:]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[curr_deg[v]].append(v)
        # pointer to non-empty bucket
        ptr = 0
        while remaining:
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # remove v
            remaining.remove(v)
            order.append(v)
            # update neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    d = curr_deg[u]
                    buckets[d].remove(u)
                    curr_deg[u] -= 1
                    buckets[curr_deg[u]].append(u)
                    if curr_deg[u] < ptr:
                        ptr = curr_deg[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap for (a,b) component containing v
    def kempe_swap(coloring, a, b, v):
        # returns new coloring after swapping a and b in the component of v in (a,b)-subgraph
        # or None if v not colored a or b
        if coloring[v] not in (a, b):
            return None
        from collections import deque
        visited = [False] * n
        queue = deque([v])
        visited[v] = True
        component = []
        while queue:
            u = queue.popleft()
            component.append(u)
            for w in range(n):
                if (bit_adj[u] >> w) & 1 and not visited[w] and coloring[w] in (a, b):
                    visited[w] = True
                    queue.append(w)
        # swap colors in component
        new_coloring = coloring[:]
        for u in component:
            new_coloring[u] = a if new_coloring[u] == b else b
        return new_coloring

    # Try to eliminate the largest color index via Kempe or reassignment
    def reduce_colors(coloring):
        k = count_colors(coloring)
        if k <= 1:
            return coloring
        # try from highest color down
        for target_color in range(k - 1, -1, -1):
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                continue
            # try to recolor each vertex in this class
            changed = False
            for v in vertices:
                # try direct reassignment to a lower color
                used = 0
                for u in range(n):
                    if (bit_adj[v] >> u) & 1:
                        used |= 1 << coloring[u]
                for c in range(target_color):
                    if not (used & (1 << c)):
                        # reassign v to color c
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # only try if v not adjacent to color c (otherwise swap would not help)
                    adjacent_to_c = any((bit_adj[v] >> u) & 1 and coloring[u] == c for u in range(n))
                    if adjacent_to_c:
                        continue
                    swapped = kempe_swap(coloring, target_color, c, v)
                    if swapped is not None:
                        # check if swap reduces the number of vertices in target_color
                        if swapped.count(target_color) < vertices.count(target_color):
                            # accept swap
                            for i in range(n):
                                coloring[i] = swapped[i]
                            changed = True
                            break
                if changed:
                    break
            if changed:
                # restart from highest color after a change
                return reduce_colors(coloring)
        # compact colors
        return compact_colors(coloring)

    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # Run DSATUR
    if time.time() - start_time < 0.05:
        c1 = dsatur()
        if is_valid(c1):
            k1 = count_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_coloring = c1

    # Run RLF
    if time.time() - start_time < 0.05:
        c2 = rlf()
        if is_valid(c2):
            k2 = count_colors(c2)
            if k2 < best_k:
                best_k = k2
                best_coloring = c2

    # Run Smallest-Last
    if time.time() - start_time < 0.05:
        c3 = smallest_last()
        if is_valid(c3):
            k3 = count_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_coloring = c3

    # If no valid coloring found (should not happen), fallback to greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_coloring = compact_colors(best_coloring)

    # Apply Kempe chain reduction iteratively (limited by time)
    for _ in range(3):  # limit iterations to stay within time
        if time.time() - start_time >= 0.05:
            break
        reduced = reduce_colors(best_coloring[:])
        if is_valid(reduced):
            k_reduced = count_colors(reduced)
            if k_reduced < best_k:
                best_k = k_reduced
                best_coloring = reduced
        else:
            break

    # Final validation and compaction
    if not is_valid(best_coloring):
        # last resort: greedy by degree order
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        best_coloring = greedy_color(order)
    best_coloring = compact_colors(best_coloring)

    return best_coloring

