def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for efficient access
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
    else:
        for u in range(n):
            # Assume adj[u] is a list of neighbors
            for v in adj[u]:
                if 0 <= v < n:
                    neighbors[u].add(v)

    # Degeneracy ordering via smallest-last (Matula & Beck, 1983)
    # Maintain current degree of each vertex in the remaining graph
    degree = [len(neighbors[i]) for i in range(n)]
    removed = [False] * n
    order = []  # removal order (will color in reverse)

    for _ in range(n):
        # Find vertex with minimum degree among unremoved
        min_deg = math.inf
        v = -1
        for i in range(n):
            if not removed[i] and degree[i] < min_deg:
                min_deg = degree[i]
                v = i
        if v == -1:  # Should not happen, but safeguard
            break
        removed[v] = True
        order.append(v)
        # Decrease degree of neighbors
        for u in neighbors[v]:
            if not removed[u]:
                degree[u] -= 1

    # Color vertices in reverse removal order using First-Fit
    color = [-1] * n
    for v in reversed(order):
        # Determine colors used by already colored neighbors
        used = [False] * n  # n is safe upper bound on colors needed
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        # Find smallest non-negative color not used
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c

    return color

