def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list if needed (matrix detection)
    if len(adj) > 0 and len(adj[0]) == n and all(all(x in (0, 1) for x in row) for row in adj):
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Precompute degrees
    degree = [len(adj_list[i]) for i in range(n)]

    # DSATUR with sum of degrees of uncolored neighbors as tie-breaker
    color = [-1] * n
    neighbor_colors = [set() for _ in range(n)]
    uncolored = set(range(n))

    # Initial vertex: highest degree
    v = max(range(n), key=lambda x: degree[x])
    color[v] = 0
    uncolored.remove(v)
    for u in adj_list[v]:
        neighbor_colors[u].add(0)

    while uncolored:
        # Find vertex with max saturation degree
        max_sat = -1
        candidates = []
        for v in uncolored:
            sat = len(neighbor_colors[v])
            if sat > max_sat:
                max_sat = sat
                candidates = [v]
            elif sat == max_sat:
                candidates.append(v)

        # Tie-break: sum of degrees of uncolored neighbors
        if len(candidates) > 1:
            def tie_break(v):
                return sum(degree[u] for u in adj_list[v] if u in uncolored)
            v = max(candidates, key=tie_break)
        else:
            v = candidates[0]

        # Assign smallest available color
        used = neighbor_colors[v]
        c = 0
        while c in used:
            c += 1
        color[v] = c
        uncolored.remove(v)
        for u in adj_list[v]:
            neighbor_colors[u].add(c)

    # Validate coloring
    for u in range(n):
        for v in adj_list[u]:
            if color[u] == color[v]:
                # Fallback to greedy by degree if invalid (should not happen)
                order = sorted(range(n), key=lambda x: (-degree[x], x))
                color = [-1] * n
                for v in order:
                    used = {color[u] for u in adj_list[v] if color[u] != -1}
                    c = 0
                    while c in used:
                        c += 1
                    color[v] = c
                break

    # Compact colors to 0..k-1
    unique_colors = sorted(set(color))
    mapping = {c: i for i, c in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    return color

import math
