def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build neighbor sets
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for v in adj[i]:
                if 0 <= v < n:
                    neighbors[i].add(v)
    # Ensure symmetry
    for i in range(n):
        for j in list(neighbors[i]):
            if i not in neighbors[j]:
                neighbors[j].add(i)
    # Edge cases
    if n == 1:
        return [0]
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n
    # Helper: greedy coloring with order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color
    # Helper: number of colors used
    def num_colors(col):
        return max(col) + 1 if col else 0
    # Helper: validate coloring
    def is_valid(col):
        for i in range(n):
            for j in neighbors[i]:
                if i < j and col[i] == col[j]:
                    return False
        return True
    # Order 1: DSATUR
    def dsatur_order():
        color = [-1] * n
        sat = [0] * n
        order = []
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree
            candidates = [v for v in range(n) if color[v] == -1]
            if not candidates:
                break
            max_sat = max(sat[v] for v in candidates)
            max_candidates = [v for v in candidates if sat[v] == max_sat]
            # tie-break by degree in uncolored subgraph
            def uncolored_degree(v):
                return sum(1 for u in neighbors[v] if color[u] == -1)
            max_deg = max(uncolored_degree(v) for v in max_candidates)
            max_deg_candidates = [v for v in max_candidates if uncolored_degree(v) == max_deg]
            v = random.choice(max_deg_candidates) if max_deg_candidates else max_candidates[0]
            order.append(v)
            # assign smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            # update saturation of uncolored neighbors
            for u in neighbors[v]:
                if color[u] == -1:
                    sat[u] += 1
        return order
    # Order 2: RLF (recursive largest first independent set extraction)
    def rlf_order():
        color = [-1] * n
        order = []
        remaining = set(range(n))
        while remaining:
            # induced subgraph degrees
            deg = {}
            for v in remaining:
                deg[v] = sum(1 for u in neighbors[v] if u in remaining)
            # pick vertex with max degree
            v = max(remaining, key=lambda x: deg[x])
            S = {v}
            remaining.remove(v)
            U = {u for u in remaining if not any(w in S for w in neighbors[u])}
            W = remaining - U
            while U:
                # select u in U with max neighbors in W
                def w_neighbors(u):
                    return sum(1 for w in neighbors[u] if w in W)
                max_w = max(w_neighbors(u) for u in U)
                max_w_candidates = [u for u in U if w_neighbors(u) == max_w]
                # tie-break by min degree in U-induced subgraph
                def deg_in_U(u):
                    return sum(1 for w in neighbors[u] if w in U)
                min_deg = min(deg_in_U(u) for u in max_w_candidates)
                min_deg_candidates = [u for u in max_w_candidates if deg_in_U(u) == min_deg]
                u = random.choice(min_deg_candidates) if min_deg_candidates else max_w_candidates[0]
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in list(neighbors[u]):
                    if w in U:
                        U.remove(w)
                        W.add(w)
            order.extend(S)
            remaining = W
        return order
    # Order 3: Smallest-Last (degeneracy ordering reversed)
    def sl_order():
        # copy degrees
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]  # degree buckets
        for v in range(n):
            if deg[v] < n:
                buckets[deg[v]].append(v)
        pos = 0
        for _ in range(n):
            # find non-empty bucket with smallest degree
            while pos < n and not buckets[pos]:
                pos += 1
            if pos >= n:
                break
            v = buckets[pos].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = deg[u]
                    if d < n:
                        buckets[d].remove(u)
                    deg[u] -= 1
                    if deg[u] < n:
                        buckets[deg[u]].append(u)
        order.reverse()
        return order
    # Order 4: Random walk diffusion for spectral-like clustering
    def rw_order():
        # stationary distribution via random walk (approximate)
        # use heat kernel or personalized PageRank? simple: compute influence via short walks
        steps = 10
        influence = [0.0] * n
        for start in range(n):
            prob = [0.0] * n
            prob[start] = 1.0
            for _ in range(steps):
                new_prob = [0.0] * n
                for v in range(n):
                    if prob[v] == 0.0:
                        continue
                    deg_v = len(neighbors[v])
                    if deg_v == 0:
                        new_prob[v] += prob[v]
                    else:
                        for u in neighbors[v]:
                            new_prob[u] += prob[v] / deg_v
                prob = new_prob
            for v in range(n):
                influence[v] += prob[v]
        # order by influence descending (high influence = central)
        order = list(range(n))
        order.sort(key=lambda x: (-influence[x], x))
        return order
    # Generate candidate colorings
    candidates = []
    for order_func in [dsatur_order, rlf_order, sl_order, rw_order]:
        try:
            order = order_func()
            col = greedy_color(order)
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue
    # Fallback: simple greedy by degree
    try:
        order = sorted(range(n), key=lambda x: (-len(neighbors[x]), x))
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(col)
    except Exception:
        pass
    # If no candidate, assign distinct colors
    if not candidates:
        return list(range(n))
    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    # Kempe chain color reduction
    def kempe_reduce(col):
        if not is_valid(col):
            return col
        k = num_colors(col)
        if k <= 1:
            return col
        # Try to eliminate color classes from highest down
        for target_color in range(k-1, 0, -1):
            # vertices with target_color
            verts = [v for v in range(n) if col[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex
            changed = True
            while changed and verts:
                changed = False
                v = verts.pop()
                # Try direct reassignment to lower color
                for c in range(target_color):
                    conflict = False
                    for u in neighbors[v]:
                        if col[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        col[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # BFS to find (target_color, c) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in neighbors[node]:
                            if not visited[nb] and (col[nb] == target_color or col[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if swapping colors in component frees color c for v
                    # After swap, v would have color c; check if any neighbor has color c (they would become target_color)
                    # Actually, we need to ensure that no neighbor of v has color c after swap.
                    # Neighbors of v in component: if they have color c, they become target_color -> not c.
                    # Neighbors of v not in component: if they have color c, they stay c -> conflict.
                    conflict_after_swap = False
                    for u in neighbors[v]:
                        if col[u] == c and u not in component:
                            conflict_after_swap = True
                            break
                    if not conflict_after_swap:
                        # perform swap
                        for node in component:
                            col[node] = c if col[node] == target_color else target_color
                        changed = True
                        break
                if changed:
                    # restart with remaining verts? but we broke out, so continue outer while
                    pass
            # After attempting to recolor all verts of target_color, check if any remain
            if any(col[v] == target_color for v in range(n)):
                # could not eliminate this color class, break
                break
            # else, color class eliminated; compact colors > target_color down by one
            # mapping: colors > target_color shift down
            mapping = {}
            for i in range(k):
                if i < target_color:
                    mapping[i] = i
                elif i > target_color:
                    mapping[i] = i - 1
                else:
                    # target_color eliminated, skip
                    pass
            new_col = [mapping[col[v]] for v in range(n)]
            col = new_col
            k = num_colors(col)
        return col
    best = kempe_reduce(best)
    # Ensure zero-based consecutive
    used = set(best)
    mapping = {old: i for i, old in enumerate(sorted(used))]
    best = [mapping[c] for c in best]
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    def compact_colors(coloring):
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
        return [unique_colors[c] for c in coloring]

    # Greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring

    # DSATUR heuristic
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # saturation degree
        # We'll maintain a list of uncolored vertices
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = saturated[v]
                # compute degree in uncolored subgraph
                deg_in_uncolored = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_in_uncolored += 1
                if sat_v > best_sat or (sat_v == best_sat and deg_in_uncolored > best_deg) or \
                   (sat_v == best_sat and deg_in_uncolored == best_deg and v > best_v):
                    best_sat = sat_v
                    best_deg = deg_in_uncolored
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # If color c is new in u's neighborhood, increase saturation
                    has_color = False
                    for w in adj_list[u]:
                        if coloring[w] == c:
                            has_color = True
                            break
                    if not has_color:
                        saturated[u] += 1
        return coloring

    # RLF heuristic
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            S = []  # independent set
            # Choose vertex with max degree in uncolored subgraph
            best_v = -1
            best_deg = -1
            for v in uncolored:
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if deg > best_deg:
                    best_deg = deg
                    best_v = v
            v = best_v
            S.append(v)
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = set(uncolored)  # copy
            U.discard(v)
            W = set()
            for u in U:
                for w in S:
                    if w in adj_list[u]:
                        W.add(u)
                        break
            U -= W
            # While U not empty, add vertices to S
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_in_U = None
                for u in U:
                    w_neighbors = 0
                    for w in W:
                        if w in adj_list[u]:
                            w_neighbors += 1
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_in_U += 1
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_in_U < best_deg_in_U) or \
                       (w_neighbors == best_w_neighbors and deg_in_U == best_deg_in_U and u < best_u):
                        best_w_neighbors = w_neighbors
                        best_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                S.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            uncolored -= set(S)
            color += 1
        return coloring

    # Smallest-Last ordering greedy
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[u]) for u in range(n)]
        order = []
        # We'll use bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # remove u from its current bucket
                    old_deg = degree[u]
                    buckets[old_deg].remove(u)
                    degree[u] -= 1
                    new_deg = degree[u]
                    buckets[new_deg].append(u)
                    if new_deg < ptr:
                        ptr = new_deg
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap attempt to eliminate a color
    def eliminate_color(coloring, target_color):
        # Get vertices with target_color
        target_vertices = [u for u in range(n) if coloring[u] == target_color]
        if not target_vertices:
            return coloring  # already eliminated

        # Try to recolor each target vertex
        for v in target_vertices:
            # Try direct reassignment to a lower color
            used_by_neighbors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used_by_neighbors |= (1 << coloring[u])
            # Find smallest color not used by neighbors
            for c in range(target_color):  # only try lower colors
                if not (used_by_neighbors & (1 << c)):
                    # Assign this color to v
                    coloring[v] = c
                    break
            else:
                # Direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    # Check if v and any vertex of color c are in different components
                    # We'll do BFS for the (v_color, c) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in adj_list[x]:
                            if not visited[y] and (coloring[y] == target_color or coloring[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # Check if any vertex of color c is not in this component
                    has_external = False
                    for u in range(n):
                        if coloring[u] == c and u not in component:
                            has_external = True
                            break
                    if has_external:
                        # Swap colors in the component
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            else:
                                coloring[x] = target_color
                        break  # success for this v
        # After attempting to recolor all target vertices, check if target_color is still used
        if any(coloring[u] == target_color for u in range(n)):
            return None  # failed to eliminate
        return coloring

    # Generate initial colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate, fall back to simple greedy
    if not candidates:
        coloring = greedy_color(list(range(n)))
        candidates.append(coloring)

    # Select best candidate (fewest colors)
    best_coloring = None
    best_num_colors = float('inf')
    for coloring in candidates:
        num_colors = len(set(coloring))
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_coloring = coloring

    # Ensure compact colors
    best_coloring = compact_colors(best_coloring)

    # Iteratively try to eliminate the highest color class
    current_coloring = best_coloring[:]
    while True:
        num_colors = len(set(current_coloring))
        if num_colors <= 1:
            break
        target_color = num_colors - 1
        new_coloring = eliminate_color(current_coloring[:], target_color)
        if new_coloring is not None:
            current_coloring = compact_colors(new_coloring)
        else:
            break

    return current_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            if is_matrix:
                for val in adj[i]:
                    if val not in (0, 1):
                        is_matrix = False
                        break
                if not is_matrix:
                    break

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                adj_list[i].append(j)
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        uncolored = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]

        while uncolored:
            # select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], degree[x], random.random()))
            # find smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # degree in uncolored subgraph
            deg_uncolored = [0] * n
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg_uncolored[v] += 1
            # start with vertex of max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            independent_set = {v}
            uncolored.remove(v)
            # ineligible: neighbors of independent_set
            ineligible = set()
            for u in adj_list[v]:
                if u in uncolored:
                    ineligible.add(u)
            # eligible: uncolored and not ineligible
            eligible = uncolored - ineligible
            while eligible:
                # select u in eligible with max neighbors in ineligible
                u = max(eligible, key=lambda x: sum(1 for w in adj_list[x] if w in ineligible))
                independent_set.add(u)
                uncolored.remove(u)
                # move u's neighbors from eligible to ineligible if they are in eligible
                for w in adj_list[u]:
                    if w in eligible:
                        eligible.remove(w)
                        ineligible.add(w)
                # update eligible
                eligible = uncolored - ineligible
            # assign color c to independent_set
            for v in independent_set:
                color[v] = c
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering
    def smallest_last():
        # compute degeneracy ordering
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)
                    if degree[u] < min_deg:
                        min_deg = degree[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Balanced Welsh-Powell (penalize large color classes)
    def balanced_welsh_powell():
        # initial order by degree descending
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        color = [-1] * n
        color_class_size = []  # dynamic list
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            # find smallest color that minimizes penalty for large classes
            best_c = -1
            best_penalty = float('inf')
            for c in range(len(color_class_size) + 1):  # allow new color
                if used & (1 << c):
                    continue
                # penalty: size of color class if existing, else 0 (new color has no penalty yet)
                size = color_class_size[c] if c < len(color_class_size) else 0
                # we want to avoid large classes unless necessary; but also prefer existing colors
                # heuristic: minimize size, and prefer smaller c (to keep colors packed)
                penalty = size * 1000 + c  # weight size heavily to avoid large classes
                if penalty < best_penalty:
                    best_penalty = penalty
                    best_c = c
            if best_c == -1:  # should not happen
                best_c = 0
                while used & (1 << best_c):
                    best_c += 1
            color[v] = best_c
            if best_c >= len(color_class_size):
                color_class_size.append(0)
            color_class_size[best_c] += 1
        return color

    # Generate candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last, balanced_welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except:
            pass

    # Also try greedy on random orders (a few iterations)
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(col)

    # Select best candidate (min colors)
    if candidates:
        best_coloring = min(candidates, key=count_colors)
        best_k = count_colors(best_coloring)
    else:
        # fallback: simple greedy on natural order
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        # make copy
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            k = max(col) + 1 if n > 0 else 0
            # try to eliminate color classes from highest to lowest
            for target_color in range(k-1, -1, -1):
                # collect vertices with target_color
                vertices = [v for v in range(n) if col[v] == target_color]
                if not vertices:
                    continue
                # try to recolor each vertex
                for v in vertices:
                    # try direct reassignment to a lower color
                    used = 0
                    for u in adj_list[v]:
                        if col[u] != -1:
                            used |= (1 << col[u])
                    for c in range(target_color):  # only lower colors
                        if not (used & (1 << c)):
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # try Kempe chains with each lower color
                    for c in range(target_color):
                        if used & (1 << c):
                            continue  # color c already used by neighbor, skip
                        # find Kempe chain (target_color, c) containing v
                        # BFS to get component
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if col[node] == target_color or col[node] == c:
                                component.add(node)
                                for nb in adj_list[node]:
                                    if nb not in visited and (col[nb] == target_color or col[nb] == c):
                                        stack.append(nb)
                        # check if swapping is safe: no neighbor of component has color c (would conflict after swap)
                        safe = True
                        for node in component:
                            for nb in adj_list[node]:
                                if nb not in component and col[nb] == c:
                                    safe = False
                                    break
                            if not safe:
                                break
                        if safe:
                            # perform swap
                            for node in component:
                                if col[node] == target_color:
                                    col[node] = c
                                else:
                                    col[node] = target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break  # restart from highest color
            # if no change, break
        # compact colors: remap to 0..k'-1
        mapping = {}
        next_color = 0
        for v in range(n):
            if col[v] not in mapping:
                mapping[col[v]] = next_color
                next_color += 1
            col[v] = mapping[col[v]]
        return col

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)

    # Final validation (should always hold)
    if not is_valid(best_coloring):
        # last resort: greedy on natural order
        best_coloring = greedy_color(list(range(n)))

    return best_coloring

