            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    adj_list[i].append(j)
    else:
        adj_list = adj
        # Ensure adjacency list is valid (no self-loops, symmetric not required but we assume undirected)
        for i in range(n):
            adj_list[i] = [x for x in adj_list[i] if x != i and 0 <= x < n]

    # Precompute neighbor sets for fast lookup
    neighbors = [set(adj_list[i]) for i in range(n)]

    # Build complement graph adjacency list (neighbors in complement = non-neighbors in G, excluding self)
    comp_neighbors = []
    for i in range(n):
        comp_set = set()
        for j in range(n):
            if i != j and j not in neighbors[i]:
                comp_set.add(j)
        comp_neighbors.append(comp_set)

    # Greedy algorithm on complement graph: repeatedly find a maximal clique (independent set in G)
    uncolored = set(range(n))
    color = [-1] * n
    current_color = 0

    while uncolored:
        # Start with vertex of max degree in complement graph among uncolored
        v = max(uncolored, key=lambda x: len(comp_neighbors[x] & uncolored))
        clique = [v]
        # Candidates: vertices in uncolored that are adjacent to all in clique in complement graph
        candidates = comp_neighbors[v] & uncolored

        while candidates:
            # Select candidate with most connections to current clique in complement graph
            u = max(candidates, key=lambda x: len(comp_neighbors[x] & set(clique)))
            clique.append(u)
            # Update candidates: must be adjacent to new vertex u in complement graph
            candidates &= comp_neighbors[u]

        # Assign current color to all vertices in the clique (independent set in original graph)
        for node in clique:
            color[node] = current_color
            uncolored.remove(node)

        current_color += 1

    return color

