def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build neighbor sets
    if is_matrix:
        neighbors = [set(v for v, val in enumerate(row) if val) for row in adj]
    else:
        neighbors = [set(row) for row in adj]

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = set()
            for v in neighbors[u]:
                if coloring[v] != -1:
                    used.add(coloring[v])
            c = 0
            while c in used:
                c += 1
            coloring[u] = c
        return coloring

    # Helper: Kempe chain swap for colors a and b starting from vertex u
    def kempe_swap(coloring, a, b, u):
        if coloring[u] not in (a, b):
            return coloring
        stack = [u]
        visited = set()
        comp = []
        while stack:
            v = stack.pop()
            if v in visited:
                continue
            visited.add(v)
            comp.append(v)
            for w in neighbors[v]:
                if coloring[w] in (a, b) and w not in visited:
                    stack.append(w)
        # Swap colors in component
        for v in comp:
            coloring[v] = a if coloring[v] == b else b
        return coloring

    # Helper: try to eliminate color 'target' using Kempe chains
    def eliminate_color(coloring, target):
        max_color = max(coloring)
        if target >= max_color:
            return coloring
        # Vertices with target color
        targets = [u for u in range(n) if coloring[u] == target]
        # Try to recolor each target vertex
        for u in targets:
            used_by_neighbors = set(coloring[v] for v in neighbors[u])
            # Try direct reassignment to a lower color
            for c in range(target):
                if c not in used_by_neighbors:
                    coloring[u] = c
                    break
            else:
                # Try Kempe chain swap with each lower color
                for c in range(target):
                    # Try to swap along (c, target) chain starting at u
                    # Only do swap if it doesn't pull any vertex into target color
                    stack = [u]
                    visited = set()
                    comp = []
                    pulls_target = False
                    while stack and not pulls_target:
                        v = stack.pop()
                        if v in visited:
                            continue
                        visited.add(v)
                        comp.append(v)
                        for w in neighbors[v]:
                            if coloring[w] == target and w not in visited:
                                pulls_target = True
                                break
                            if coloring[w] in (c, target) and w not in visited:
                                stack.append(w)
                        if pulls_target:
                            break
                    if not pulls_target:
                        # Safe to swap
                        for v in comp:
                            coloring[v] = c if coloring[v] == target else target
                        coloring[u] = c
                        break
                else:
                    # Could not recolor u, abort
                    return None
        # Reindex colors to be consecutive
        color_map = {}
        next_color = 0
        for u in range(n):
            c = coloring[u]
            if c not in color_map:
                color_map[c] = next_color
                next_color += 1
            coloring[u] = color_map[c]
        return coloring

    # Main: multiple randomized greedy passes + local improvement
    best_coloring = None
    best_k = float('inf')
    vertices = list(range(n))
    # Use time budget for iterations (approx 20 passes)
    for _ in range(20):
        # Random vertex order
        order = vertices[:]
        random.shuffle(order)
        coloring = greedy_color(order)
        # Local improvement: try to reduce colors by 1-opt moves
        improved = True
        while improved:
            improved = False
            # Try to recolor each vertex to a lower color if possible
            for u in vertices:
                cu = coloring[u]
                used = set(coloring[v] for v in neighbors[u])
                for c in range(cu):
                    if c not in used:
                        coloring[u] = c
                        improved = True
                        break
                if improved:
                    break
            # Try Kempe chain swaps to reduce color count
            if not improved:
                k = num_colors(coloring)
                if k > 0:
                    # Try to eliminate highest color class
                    target = k - 1
                    new_coloring = eliminate_color(coloring[:], target)
                    if new_coloring is not None and num_colors(new_coloring) < k:
                        coloring = new_coloring
                        improved = True
        k = num_colors(coloring)
        if k < best_k and is_valid(coloring):
            best_k = k
            best_coloring = coloring[:]
            # Early exit if optimal possible (lower bound: max clique size, but we use simple bound)
            if best_k <= 1:
                break

    # Fallback: if no valid coloring found (should not happen), use DSATUR-like
    if best_coloring is None or not is_valid(best_coloring):
        # Simple greedy by degree ordering
        order = sorted(vertices, key=lambda x: len(neighbors[x]), reverse=True)
        best_coloring = greedy_color(order)

    # Final validation and color compacting
    if not is_valid(best_coloring):
        # As last resort, assign each vertex a unique color
        best_coloring = list(range(n))
    else:
        # Ensure colors are consecutive
        color_map = {}
        next_color = 0
        for u in range(n):
            c = best_coloring[u]
            if c not in color_map:
                color_map[c] = next_color
                next_color += 1
            best_coloring[u] = color_map[c]

    return best_coloring

