import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = [list(neigh) for neigh in adj]
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR with bitmask
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg_uncolored = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                d = deg_uncolored[u]
                if s > max_sat or (s == max_sat and d > max_deg) or (s == max_sat and d == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = s
                    max_deg = d
                    v = u
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            # degree in current uncolored subgraph
            deg = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        deg[v] += 1
            # start with max degree vertex
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and all(u not in adj_list[w] for w in S)}
            # W: vertices adjacent to at least one in S
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = sum(1 for w in adj_list[u] if w in W)
                    du = sum(1 for w in adj_list[u] if w in U)
                    if nw > max_nw or (nw == max_nw and du < min_deg_u) or (nw == max_nw and du == min_deg_u and (best_u == -1 or random.random() < 0.5)):
                        max_nw = nw
                        min_deg_u = du
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # buckets by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current min degree
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    buckets[d].remove(u)
                    buckets[d-1].append(u)
                    if d-1 < ptr:
                        ptr = d-1
        # color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Jaccard-based heuristic for non-adjacent pairs
    def jaccard_heuristic():
        # Precompute Jaccard similarity for non-adjacent pairs
        sim = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(i+1, n):
                if j not in adj_list[i]:  # non-adjacent
                    set_i = set(adj_list[i])
                    set_j = set(adj_list[j])
                    union = set_i | set_j
                    if union:
                        inter = set_i & set_j
                        sim[i][j] = sim[j][i] = len(inter) / len(union)
                    else:
                        sim[i][j] = sim[j][i] = 0.0
        # Greedy coloring with priority to high-similarity non-adjacent pairs
        # We'll try to color vertices in order, but when choosing color, prefer to reuse colors
        # that are used by non-adjacent high-similarity vertices
        color = [-1] * n
        # Order vertices by degree descending
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            # Try to find a color that is used by a non-adjacent high-similarity vertex
            best_color = 0
            best_score = -1
            # Consider existing colors first
            for c in range(n):  # up to n colors enough
                if used & (1 << c):
                    continue
                # score: sum of similarity to vertices of color c that are non-adjacent to v
                score = 0
                for u in range(n):
                    if color[u] == c and u not in adj_list[v]:  # non-adjacent and same color
                        score += sim[v][u]
                if score > best_score:
                    best_score = score
                    best_color = c
            # If no existing color gives positive score, just take smallest available
            if best_score <= 0:
                c = 0
                while used & (1 << c):
                    c += 1
                color[v] = c
            else:
                color[v] = best_color
        return color

    # Run all strategies within time budget
    start = time.time()
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last),
        ("Jaccard", jaccard_heuristic)
    ]
    for name, func in strategies:
        if time.time() - start > 0.04:  # leave margin for Kempe
            break
        try:
            coloring = func()
            if is_valid(coloring):
                k = num_colors(coloring)
                if k < best_k:
                    best_k = k
                    best_coloring = coloring[:]
        except Exception:
            continue

    # If no valid coloring found, fallback to greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best_coloring = greedy_color(order)
        best_k = num_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find color classes
            classes = {}
            for v in range(n):
                c = col[v]
                if c not in classes:
                    classes[c] = []
                classes[c].append(v)
            colors = sorted(classes.keys())
            if not colors:
                return col
            # Try to eliminate the largest color index (we want to reduce max color)
            target = max(colors)
            # Try to recolor each vertex in target class
            for v in classes[target]:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if col[u] != -1:
                        used |= (1 << col[u])
                for c in range(target):  # only try colors < target
                    if not (used & (1 << c)):
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target):
                    if used & (1 << c):
                        continue  # color c is used by neighbor, cannot directly assign
                    # Build Kempe chain for (target, c) starting from v
                    # We want to see if we can swap colors in the component of v in the subgraph induced by colors {target, c}
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if nb not in visited and (col[nb] == target or col[nb] == c):
                                visited.add(nb)
                                queue.append(nb)
                    # Check if swapping is safe: no neighbor of any node in component has color c outside the component?
                    # Actually, swapping is always safe as it preserves validity.
                    # But we want to free color target for v, so after swap, v will have color c.
                    # We need to ensure that after swap, no two adjacent have same color, which is guaranteed.
                    # Perform swap: target <-> c in component
                    for node in component:
                        if col[node] == target:
                            col[node] = c
                        elif col[node] == c:
                            col[node] = target
                    changed = True
                    break
                if changed:
                    break
            # If we made a change, rebuild classes and try again
            if changed:
                # Compact colors: remap to 0..k-1
                # But we do that after reduction loop
                pass
        # Compact colors
        if not col:
            return col
        unique_colors = sorted(set(col))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        col = [mapping[c] for c in col]
        return col

    # Apply Kempe reduction
    if time.time() - start < 0.045:
        best_coloring = kempe_reduce(best_coloring)
        # Final validation
        if not is_valid(best_coloring):
            # fallback to greedy
            order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
            best_coloring = greedy_color(order)

    return best_coloring

