                c += 1
            color[v] = c
        return color

    # Kempe chain swap for (a,b)
    def kempe_swap(color, a, b, v):
        # returns new color array if swap changes color of v, else None
        # BFS to get component of v in (a,b) subgraph
        from collections import deque
        q = deque([v])
        visited = set([v])
        component = set()
        while q:
            u = q.popleft()
            component.add(u)
            for w in adj_list[u]:
                if w not in visited and (color[w] == a or color[w] == b):
                    visited.add(w)
                    q.append(w)
        # check if swapping is valid (always is, but we want to move v)
        # create new coloring
        new_color = color[:]
        for u in component:
            if new_color[u] == a:
                new_color[u] = b
            elif new_color[u] == b:
                new_color[u] = a
        return new_color

    # Try to eliminate the last color
    def reduce_colors(color):
        # make colors consecutive
        unique_colors = sorted(set(color))
        mapping = {c: i for i, c in enumerate(unique_colors)}
        color = [mapping[c] for c in color]
        k = len(unique_colors)
        if k <= 1:
            return color
        # try to eliminate color k-1
        target = k - 1
        vertices = [v for v in range(n) if color[v] == target]
        # try direct reassignment
        moved = [False] * n
        for v in vertices:
            used = 0
            for u in adj_list[v]:
                if color[u] != target:  # only consider colors < target
                    used |= (1 << color[u])
            for c in range(target):
                if not (used & (1 << c)):
                    color[v] = c
                    moved[v] = True
                    break
        # if all moved, we can reduce
        if all(moved):
            # reindex colors to be consecutive
            unique_colors = sorted(set(color))
            mapping = {c: i for i, c in enumerate(unique_colors)}
            return [mapping[c] for c in color]
        # try Kempe chains for remaining vertices
        remaining = [v for v in vertices if not moved[v]]
        changed = True
        while changed and remaining:
            changed = False
            v = remaining.pop()
            for c in range(target):
                # if v already has color c, skip (shouldn't happen)
                if color[v] == c:
                    continue
                # check if Kempe chain (target, c) swap can move v to c
                # i.e., if v is not in the same component as any vertex of color c that is adjacent to v?
                # Actually, we want to swap a component that contains v but no neighbor of v colored c
                # Standard: if in the (target,c) Kempe chain of v, there is no vertex colored c adjacent to v
                # then swapping will move v to c without conflict
                from collections import deque
                q = deque([v])
                visited = set([v])
                component = set()
                safe = True
                while q:
                    u = q.popleft()
                    component.add(u)
                    for w in adj_list[u]:
                        if w not in visited and (color[w] == target or color[w] == c):
                            visited.add(w)
                            q.append(w)
                # check if any vertex in component colored c is adjacent to v
                for u in component:
                    if color[u] == c:
                        for w in adj_list[u]:
                            if w == v:  # u adjacent to v
                                safe = False
                                break
                    if not safe:
                        break
                if safe:
                    # perform swap
                    for u in component:
                        if color[u] == target:
                            color[u] = c
                        elif color[u] == c:
                            color[u] = target
                    moved[v] = True
                    changed = True
                    # if v moved, break and restart
                    break
            if not changed:
                # couldn't move v, keep it
                pass
        # if all target vertices moved, reduce
        if all(moved):
            unique_colors = sorted(set(color))
            mapping = {c: i for i, c in enumerate(unique_colors)}
            return [mapping[c] for c in color]
        return color

    # Validate coloring
    def is_valid(color):
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    return False
        return True

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to greedy
    if not candidates:
        color = [-1] * n
        for v in range(n):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        candidates.append(color)

    # Select best (fewest colors)
    best = min(candidates, key=lambda x: len(set(x)))

    # Try to reduce colors iteratively
    for _ in range(10):  # limit iterations
        new_color = reduce_colors(best)
        if len(set(new_color)) < len(set(best)):
            best = new_color
        else:
            break

    # Ensure colors are consecutive starting from 0
    unique_colors = sorted(set(best))
    mapping = {c: i for i, c in enumerate(unique_colors)}
    best = [mapping[c] for c in best]

    return best

import math
