def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    graph[i].append(j)
    else:
        graph = [list(nei) for nei in adj]

    # Tarjan's algorithm for biconnected components (vertex-based)
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    time = 0
    stack = []
    bccs = []  # list of sets of vertices

    def dfs(u):
        nonlocal time
        disc[u] = low[u] = time
        time += 1
        children = 0
        for v in graph[u]:
            if disc[v] == -1:
                parent[v] = u
                children += 1
                stack.append((u, v))
                dfs(v)
                low[u] = min(low[u], low[v])
                if (parent[u] == -1 and children > 1) or (parent[u] != -1 and low[v] >= disc[u]):
                    comp = set()
                    while True:
                        e = stack.pop()
                        comp.add(e[0])
                        comp.add(e[1])
                        if e == (u, v):
                            break
                    bccs.append(comp)
            elif v != parent[u] and disc[v] < disc[u]:
                low[u] = min(low[u], disc[v])
                stack.append((u, v))

    for i in range(n):
        if disc[i] == -1:
            dfs(i)
            if stack:
                comp = set()
                while stack:
                    e = stack.pop()
                    comp.add(e[0])
                    comp.add(e[1])
                bccs.append(comp)

    # If no biconnected components (edgeless graph), treat as isolated vertices
    if not bccs:
        return [0] * n

    # Build block-cut tree: bipartite graph between blocks and cut vertices
    vertex_to_blocks = [[] for _ in range(n)]
    for idx, comp in enumerate(bccs):
        for v in comp:
            vertex_to_blocks[v].append(idx)

    cut_vertices = [v for v in range(n) if len(vertex_to_blocks[v]) > 1]
    is_cut = [False] * n
    for v in cut_vertices:
        is_cut[v] = True

    num_blocks = len(bccs)
    num_cuts = len(cut_vertices)
    total_nodes = num_blocks + num_cuts
    bc_adj = [[] for _ in range(total_nodes)]

    cut_id_map = {}
    for idx, v in enumerate(cut_vertices):
        cut_id_map[v] = num_blocks + idx

    for b_idx, comp in enumerate(bccs):
        for v in comp:
            if is_cut[v]:
                c_node = cut_id_map[v]
                bc_adj[b_idx].append(c_node)
                bc_adj[c_node].append(b_idx)

    # BFS to get processing order of blocks (root at block 0)
    from collections import deque
    visited = [False] * total_nodes
    parent_bc = [-1] * total_nodes
    block_order = []
    q = deque([0])
    visited[0] = True
    while q:
        node = q.popleft()
        if node < num_blocks:  # block node
            block_order.append(node)
        for nb in bc_adj[node]:
            if not visited[nb]:
                visited[nb] = True
                parent_bc[nb] = node
                q.append(nb)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for nb in graph[v]:
                if color[nb] != -1:
                    used[color[nb]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        colored = [False] * n
        for _ in range(n):
            # select uncolored vertex with max sat, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    if sat[u] > max_sat or (sat[u] == max_sat and len(graph[u]) > max_deg):
                        max_sat = sat[u]
                        max_deg = len(graph[u])
                        v = u
                    elif sat[u] == max_sat and len(graph[u]) == max_deg and u < v:
                        v = u
            if v == -1:
                break
            # assign smallest available color
            used = [False] * n
            for nb in graph[v]:
                if color[nb] != -1:
                    used[color[nb]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            colored[v] = True
            # update saturation of neighbors
            for nb in graph[v]:
                if not colored[nb]:
                    sat[nb] = len({color[w] for w in graph[nb] if color[w] != -1})
        return color

    # Helper: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in graph[x] if nb in uncolored))
            S = {v}
            U = {u for u in uncolored if u != v and all(nb not in S for nb in graph[u])}
            W = {u for u in uncolored if u != v and any(nb in S for nb in graph[u])}
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                u_star = None
                max_w_nei = -1
                min_deg_u = float('inf')
                for u in U:
                    w_nei = sum(1 for nb in graph[u] if nb in W)
                    deg_u = sum(1 for nb in graph[u] if nb in U)
                    if w_nei > max_w_nei or (w_nei == max_w_nei and deg_u < min_deg_u) or \
                       (w_nei == max_w_nei and deg_u == min_deg_u and u < u_star):
                        max_w_nei = w_nei
                        min_deg_u = deg_u
                        u_star = u
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star from U to W
                for nb in graph[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            for vertex in S:
                color[vertex] = c
                uncolored.remove(vertex)
            c += 1
        return color

    # Helper: smallest-last ordering
    def smallest_last():
        deg = [len(graph[i]) for i in range(n)]
        alive = [True] * n
        order = []
        bucket = [[] for _ in range(n)]
        for i in range(n):
            if deg[i] < n:
                bucket[deg[i]].append(i)
        pos = [0] * n
        for i in range(n):
            pos[i] = len(bucket[deg[i]]) - 1 if bucket[deg[i]] else -1
        for _ in range(n):
            d = 0
            while d < n and not bucket[d]:
                d += 1
            if d >= n:
                break
            while bucket[d] and pos[bucket[d][-1]] != len(bucket[d]) - 1:
                bucket[d].pop()
            if not bucket[d]:
                d += 1
                continue
            v = bucket[d].pop()
            pos[v] = -1
            order.append(v)
            alive[v] = False
            for nb in graph[v]:
                if alive[nb]:
                    d_nb = deg[nb]
                    # remove nb from bucket[d_nb]
                    if pos[nb] != -1:
                        last = bucket[d_nb][-1]
                        bucket[d_nb][pos[nb]] = last
                        pos[last] = pos[nb]
                        bucket[d_nb].pop()
                        if bucket[d_nb]:
                            pos[bucket[d_nb][-1]] = len(bucket[d_nb]) - 1
                        else:
                            pos[last] = -1
                    deg[nb] -= 1
                    if deg[nb] >= 0:
                        bucket[deg[nb]].append(nb)
                        pos[nb] = len(bucket[deg[nb]]) - 1
        return order[::-1]  # reverse for coloring order

    # Generate candidate colorings
    candidates = []

    # DSATUR
    candidates.append(dsatur())
    # RLF
    candidates.append(rlf())
    # Smallest-last greedy
    sl_order = smallest_last()
    candidates.append(greedy_color(sl_order))
    # Degree ordering (Welsh-Powell)
    deg_order = sorted(range(n), key=lambda x: (-len(graph[x]), x))
    candidates.append(greedy_color(deg_order))
    # Natural order
    candidates.append(greedy_color(list(range(n))))

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # validate
        valid = True
        for u in range(n):
            for v in graph[u]:
                if u < v and col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col[:]

    if best_color is None:
        best_color = [0] * n  # fallback

    # Kempe chain color reduction
    def kempe_reduce(color_in):
        color = color_in[:]
        while True:
            # find smallest color class (largest index)
            classes = [[] for _ in range(max(color) + 1) if color]
            if not color:
                break
            max_c = max(color)
            classes = [[] for _ in range(max_c + 1)]
            for v in range(n):
                classes[color[v]].append(v)
            # find highest color with non-empty class
            target_c = -1
            for c in range(max_c, -1, -1):
                if classes[c]:
                    target_c = c
                    break
            if target_c == 0:
                break  # cannot reduce further
            # try to recolor each vertex in target_c
            moved = False
            for v in classes[target_c][:]:
                # try direct reassignment to lower color
                for c in range(target_c):
                    if all(color[nb] != c for nb in graph[v]):
                        color[v] = c
                        moved = True
                        break
                if moved:
                    break
                # try Kempe chains
                for c in range(target_c):
                    # BFS for (target_c, c)-Kempe chain containing v
                        from collections import deque
                        visited_k = [False] * n
                        q = deque([v])
                        visited_k[v] = True
                        component = []
                        while q:
                            node = q.popleft()
                            component.append(node)
                            for nb in graph[node]:
                                if not visited_k[nb] and (color[nb] == target_c or color[nb] == c):
                                    visited_k[nb] = True
                                    q.append(nb)
                        # check if swapping frees color c for v
                        # after swap, v would get color c, so check if any neighbor has color c (they would become target_c)
                        conflict = False
                        for node in component:
                            for nb in graph[node]:
                                if color[nb] == c and nb not in component:
                                    conflict = True
                                    break
                            if conflict:
                                break
                        if not conflict:
                            # perform swap
                            for node in component:
                                if color[node] == target_c:
                                    color[node] = c
                                else:
                                    color[node] = target_c
                            moved = True
                            break
                    if moved:
                        break
                if moved:
                    break
            if not moved:
                break
        # compact colors
        unique_colors = {}
        next_color = 0
        for v in range(n):
            if color[v] not in unique_colors:
                unique_colors[color[v]] = next_color
                next_color += 1
        color = [unique_colors[color[v]] for v in range(n)]
        return color

    best_color = kempe_reduce(best_color)

    # Final validation and compacting (ensure 0..k-1)
    unique_colors = {}
    next_color = 0
    for v in range(n):
        if best_color[v] not in unique_colors:
            unique_colors[best_color[v]] = next_color
            next_color += 1
    best_color = [unique_colors[best_color[v]] for v in range(n)]

    return best_color

