def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and bitmask for fast operations
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)

    # Helper: compute number of edges for validation
    def count_edges():
        e = 0
        for u in range(n):
            for v in adj_list[u]:
                if u < v:
                    e += 1
        return e

    total_edges = count_edges()

    # Helper: validate coloring
    def is_valid_coloring(colors):
        if len(colors) != n:
            return False
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: convert coloring to consecutive 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph (initially full degree)
        uncolored_deg = [len(adj_list[u]) for u in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, then max uncolored degree, then min index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_count = saturation[u].bit_count()
                if sat_count > max_sat or (sat_count == max_sat and (
                    uncolored_deg[u] > max_deg or (uncolored_deg[u] == max_deg and u < v)
                )):
                    max_sat = sat_count
                    max_deg = uncolored_deg[u]
                    v = u
            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return colors

    # RLF: Recursive Largest First
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            # degree in uncolored subgraph
            deg_uncolored = [0] * n
            for u in uncolored:
                for v in adj_list[u]:
                    if v in uncolored:
                        deg_uncolored[u] += 1
            # start with vertex of max degree in uncolored
            v = max(uncolored, key=lambda u: (deg_uncolored[u], u))
            independent_set = {v}
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v} - set(adj_list[v])
            W = set(adj_list[v]) & uncolored
            # greedy expansion
            while U:
                # select u in U with max neighbors in W, then min degree in U-induced subgraph
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # degree in U-induced subgraph
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if (w_neighbors > max_w_neighbors or
                        (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or
                        (w_neighbors == max_w_neighbors and deg_u == min_deg_u and u < best_u)):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                # add best_u to independent set
                independent_set.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to independent set
            for u in independent_set:
                colors[u] = color
            uncolored -= independent_set
            color += 1
        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get removal order
        deg = [len(adj_list[u]) for u in range(n)]
        # buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[deg[u]].append(u)
        # track position of each vertex in bucket
        pos_in_bucket = [0] * n
        for d in range(max_deg + 1):
            for idx, u in enumerate(buckets[d]):
                pos_in_bucket[u] = idx
        # current min degree
        min_deg = 0
        order = []
        # replicated degree for updates
        curr_deg = deg[:]
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            u = buckets[min_deg].pop()
            pos_in_bucket[u] = len(buckets[min_deg])  # invalidate
            order.append(u)
            # update neighbors
            for v in adj_list[u]:
                if curr_deg[v] > 0:  # v not yet removed
                    # remove v from its bucket
                    d = curr_deg[v]
                    buckets[d].pop(pos_in_bucket[v])
                    if pos_in_bucket[v] < len(buckets[d]):
                        # swap with last
                        last_v = buckets[d][-1]
                        buckets[d][pos_in_bucket[v]] = last_v
                        pos_in_bucket[last_v] = pos_in_bucket[v]
                    curr_deg[v] -= 1
                    if curr_deg[v] < min_deg:
                        min_deg = curr_deg[v]
                    d_new = curr_deg[v]
                    buckets[d_new].append(v)
                    pos_in_bucket[v] = len(buckets[d_new]) - 1
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(compact_colors(c1))
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(compact_colors(c2))
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(compact_colors(c3))
    except:
        pass
    # Fallback: greedy by natural order
    try:
        c4 = greedy_color(list(range(n)))
        if is_valid_coloring(c4):
            candidates.append(compact_colors(c4))
    except:
        pass

    # Select best candidate (fewest colors)
    if not candidates:
        # ultimate fallback: assign each vertex a unique color
        best = list(range(n))
    else:
        best = min(candidates, key=lambda c: len(set(c)))

    # Iterative Kempe chain color reduction
    def kempe_reduce(colors):
        k = max(colors) + 1 if n > 0 else 0
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest downward
        for target_color in range(k-1, 0, -1):
            # collect vertices with target_color
            verts = [u for u in range(n) if colors[u] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            removed = True
            while removed and verts:
                removed = False
                # Try direct reassignment to a lower color
                for u in verts[:]:  # iterate over copy
                    used = 0
                    for v in adj_list[u]:
                        if colors[v] != -1:
                            used |= (1 << colors[v])
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            # can move u to color c
                            colors[u] = c
                            removed = True
                            verts.remove(u)
                            break
                if removed:
                    continue
                # Try Kempe chain swaps
                for u in verts[:]:
                    for c in range(target_color):
                        # Check if u can be swapped via (target_color, c) Kempe chain
                        # BFS to find the component of u in the subgraph of colors {target_color, c}
                        from collections import deque
                        visited = set()
                        queue = deque([u])
                        visited.add(u)
                        component = set()
                        while queue:
                            x = queue.popleft()
                            component.add(x)
                            for y in adj_list[x]:
                                if colors[y] in (target_color, c) and y not in visited:
                                    visited.add(y)
                                    queue.append(y)
                        # Check if any neighbor of u has color c (would cause conflict if we swap)
                        has_c_neighbor = any(colors[v] == c for v in adj_list[u])
                        if not has_c_neighbor:
                            # safe to swap: invert colors in component
                            for x in component:
                                if colors[x] == target_color:
                                    colors[x] = c
                                else:
                                    colors[x] = target_color
                            removed = True
                            verts.remove(u)
                            break
                    if removed:
                        break
            # If we removed all vertices of target_color, we can reduce k
            if not any(colors[u] == target_color for u in range(n)):
                # compact colors above target_color
                for u in range(n):
                    if colors[u] > target_color:
                        colors[u] -= 1
                # restart reduction with new k
                return kempe_reduce(colors)
        return colors

    # Apply Kempe reduction
    try:
        best = kempe_reduce(best)
    except:
        pass

    # Final validation and compaction
    if not is_valid_coloring(best):
        # last resort: greedy on natural order
        best = greedy_color(list(range(n)))
    best = compact_colors(best)

    return best

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and bitmask
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build bitmask adjacency
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        saturated = [0] * n
        uncolored = set(range(n))
        # Precompute degrees
        deg = [len(adj_list[i]) for i in range(n)]
        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (saturated[x], deg[x], random.random()))
            # Compute used colors from neighbors
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            # Find smallest available color
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u] += 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # Find vertex in uncolored with max degree in induced subgraph
            def degree_in_uncolored(v):
                return sum(1 for u in adj_list[v] if u in uncolored)
            v = max(uncolored, key=degree_in_uncolored)
            independent_set = {v}
            uncolored.remove(v)
            # Partition: U = not adjacent to any in S, W = adjacent to at least one in S
            # Initially, S = {v}
            W = set(adj_list[v]) & uncolored
            U = uncolored - W
            while U:
                # Select u in U with max |N(u) ∩ W|
                def weight(u):
                    return sum(1 for x in adj_list[u] if x in W)
                # Tie-break: min degree in G[U]
                def tie_breaker(u):
                    return (weight(u), -sum(1 for x in adj_list[u] if x in U), random.random())
                u = max(U, key=tie_breaker)
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degree = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # Use buckets for efficiency (since n <= 100, we can scan)
        for _ in range(n):
            # Find vertex with min degree among non-removed
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and degree[i] < min_deg:
                    min_deg = degree[i]
                    v = i
            if v == -1:
                break  # should not happen
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    degree[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Run all strategies and pick best
    strategies = [dsatur, rlf, smallest_last, welsh_powell]
    best_coloring = None
    best_k = float('inf')
    start_time = time.time()
    for strat in strategies:
        if time.time() - start_time > 0.04:  # leave some margin
            break
        coloring = strat()
        if not is_valid(coloring):
            continue
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]
    if best_coloring is None:
        # fallback: greedy on natural order
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        nonlocal n, adj_list, bit_adj
        # Make a copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find color classes
            classes = [[] for _ in range(best_k)]  # we don't know best_k yet, use current max
            max_color = max(col) if n > 0 else 0
            classes = [[] for _ in range(max_color + 1)]
            for v in range(n):
                classes[col[v]].append(v)
            # Try to eliminate color classes from highest down
            for target_color in range(len(classes)-1, 0, -1):
                if not classes[target_color]:
                    continue
                # Try to recolor each vertex in this class
                for v in classes[target_color][:]:  # iterate over copy
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in adj_list[v]:
                        if col[u] != -1:
                            used |= (1 << col[u])
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            col[v] = c
                            classes[target_color].remove(v)
                            classes[c].append(v)
                            changed = True
                            break
                    if changed:
                        break  # restart scan after change
                if changed:
                    break
            if not changed:
                # Try Kempe chains for the smallest color class (highest index)
                for target_color in range(len(classes)-1, 0, -1):
                    if not classes[target_color]:
                        continue
                    # Try to move each vertex in this class via Kempe chain
                    for v in classes[target_color][:]:
                        # For each lower color
                        for c in range(target_color):
                            # Check if v can be swapped with color c via Kempe chain
                            # Build the (target_color, c)-Kempe chain containing v
                            # Only if v has color target_color
                            if col[v] != target_color:
                                continue
                            # BFS to get the component
                            from collections import deque
                            visited = [False] * n
                            queue = deque([v])
                            visited[v] = True
                            component = []
                            while queue:
                                x = queue.popleft()
                                component.append(x)
                                for y in adj_list[x]:
                                    if not visited[y] and (col[y] == target_color or col[y] == c):
                                        visited[y] = True
                                        queue.append(y)
                            # Check if swapping colors in component is valid
                            # After swap, target_color becomes c and c becomes target_color
                            # We want to see if this frees up target_color for v (i.e., v becomes c)
                            # and no vertex in component becomes target_color from c (which would be bad)
                            # Actually, we want to eliminate color target_color, so we want that after swap,
                            # no vertex has color target_color.
                            # That means: in the component, there should be no vertex of color c
                            # because after swap, they would become target_color.
                            has_c = any(col[x] == c for x in component)
                            if not has_c:
                                # Swap colors in component
                                for x in component:
                                    if col[x] == target_color:
                                        col[x] = c
                                    elif col[x] == c:
                                        col[x] = target_color
                                # Update classes
                                for x in component:
                                    if col[x] == target_color:
                                        classes[target_color].append(x)
                                        if x in classes[c]:
                                            classes[c].remove(x)
                                    elif col[x] == c:
                                        classes[c].append(x)
                                        if x in classes[target_color]:
                                            classes[target_color].remove(x)
                                changed = True
                                break
                        if changed:
                            break
                    if changed:
                        break
            if changed:
                # Renumber colors to be consecutive
                # Map old colors to new consecutive ones
                mapping = {}
                next_color = 0
                for v in range(n):
                    if col[v] not in mapping:
                        mapping[col[v]] = next_color
                        next_color += 1
                for v in range(n):
                    col[v] = mapping[col[v]]
        return col

    # Apply Kempe reduction
    try:
        reduced = kempe_reduce(best_coloring)
        if is_valid(reduced):
            reduced_k = num_colors(reduced)
            if reduced_k < best_k:
                best_coloring = reduced
                best_k = reduced_k
    except Exception:
        pass  # fallback to best_coloring

    # Final validation and compacting
    if not is_valid(best_coloring):
        # Last resort: greedy on DSATUR order
        best_coloring = dsatur()
        if not is_valid(best_coloring):
            # Should not happen, but ensure
            best_coloring = greedy_color(list(range(n)))

    # Ensure colors are consecutive starting from 0
    used_colors = set(best_coloring)
    if used_colors:
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if binary matrix
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build bitmask adjacency and neighbor list
    bit_adj = [0] * n
    neighbor_list = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
                    neighbor_list[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < 0 or j >= n:
                    continue
                bit_adj[i] |= (1 << j)
                neighbor_list[i].append(j)
                # Ensure symmetry for undirected graph
                if i not in neighbor_list[j]:
                    neighbor_list[j].append(i)
                    bit_adj[j] |= (1 << i)

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # Degree in uncolored subgraph
        uncolored_deg = [len(neighbor_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, then max uncolored degree, then min index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = bit_count(saturation[u])
                deg_u = uncolored_deg[u]
                if sat_u > max_sat or (sat_u == max_sat and (deg_u > max_deg or (deg_u == max_deg and u < v))):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            if v == -1:
                break  # Should not happen

            # Find smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

            # Remove v from uncolored
            uncolored.remove(v)
            # Update neighbors
            for u in neighbor_list[v]:
                if u in uncolored:
                    # Add color c to saturation of u
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # RLF: Recursive Largest First via independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set S for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbor_list[x] if y in uncolored]))
            S.add(v)
            # Partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty, add vertex with max neighbors in W, tie-break by min degree in U
            while U:
                # Select u in U maximizing |N(u) ∩ W|
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in neighbor_list[u]:
                        if w in W:
                            w_neighbors += 1
                    deg_u = len([y for y in neighbor_list[u] if y in U])
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and (deg_u < best_deg_u or (deg_u == best_deg_u and u < best_u))):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                if best_u == -1:
                    break  # Should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in neighbor_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            # Remove S from uncolored
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(neighbor_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            # Find unremoved vertex with min degree
            v = -1
            min_deg = float('inf')
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for u in neighbor_list[v]:
                if not removed[u]:
                    deg[u] -= 1
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbor_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select candidate with fewest colors
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate and compact colors
        if not is_valid_coloring(col, bit_adj, n):
            continue
        compacted = compact_colors(col)
        k = max(compacted) + 1 if compacted else 0
        if k < best_k:
            best_k = k
            best_color = compacted
    if best_color is None:
        # Fallback to greedy by degree
        order = sorted(range(n), key=lambda x: len(neighbor_list[x]), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbor_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_color = compact_colors(color)

    # Kempe chain color reduction
    improved = True
    while improved:
        improved = False
        color = best_color[:]
        k = max(color) + 1 if color else 0
        if k <= 1:
            break
        # Target smallest color class (color k-1)
        target_color = k - 1
        vertices = [v for v in range(n) if color[v] == target_color]
        if not vertices:
            # Should not happen if compacted
            best_color = compact_colors(color)
            continue
        # Try to recolor each vertex in target class
        removed = set()
        for v in vertices:
            # Try direct reassignment to a lower color
            found = False
            for c in range(target_color):
                conflict = False
                for u in neighbor_list[v]:
                    if color[u] == c:
                        conflict = True
                        break
                if not conflict:
                    color[v] = c
                    removed.add(v)
                    found = True
                    break
            if found:
                continue
            # Try Kempe chain swap with each lower color
            for c in range(target_color):
                # Build (c, target_color)-Kempe chain containing v
                # We'll do BFS to get component
                from collections import deque
                visited = [False] * n
                queue = deque([v])
                visited[v] = True
                component = []
                while queue:
                    node = queue.popleft()
                    component.append(node)
                    for u in neighbor_list[node]:
                        if not visited[u] and (color[u] == c or color[u] == target_color):
                            visited[u] = True
                            queue.append(u)
                # Check if swapping this component frees color c for v
                # After swap, v would have color c, so we need that no neighbor of v has color c after swap
                # In the component, colors c <-> target_color are swapped
                # So neighbors of v that are in component and had color c will become target_color
                # Neighbors of v that are in component and had target_color will become c -> conflict if any such neighbor
                # Actually, we need: after swap, no neighbor of v has color c
                # Currently, neighbors of v with color c: if they are in component, they become target_color -> ok
                # if they are not in component, they remain c -> conflict
                # So we need that all neighbors of v with color c are in the component
                # Similarly, neighbors of v with color target_color: if in component, become c -> conflict unless we also swap them away? 
                # Actually, we are only swapping the component. For a neighbor u of v:
                # - If u not in component: color unchanged.
                # - If u in component: color flips between c and target_color.
                # We require that after swap, no neighbor of v has color c.
                # Let N_c = {u in N(v) | color[u] == c}
                # Let N_t = {u in N(v) | color[u] == target_color}
                # After swap:
                #   For u in N_c:
                #       if u in component: color becomes target_color -> ok
                #       if u not in component: color remains c -> conflict
                #   For u in N_t:
                #       if u in component: color becomes c -> conflict
                #       if u not in component: color remains target_color -> ok
                # So to avoid conflict, we need:
                #   N_c ⊆ component and N_t ∩ component = ∅
                N_c = set()
                N_t = set()
                for u in neighbor_list[v]:
                    if color[u] == c:
                        N_c.add(u)
                    elif color[u] == target_color:
                        N_t.add(u)
                if N_c.issubset(set(component)) and len(N_t.intersection(set(component))) == 0:
                    # Perform swap
                    for node in component:
                        if color[node] == c:
                            color[node] = target_color
                        elif color[node] == target_color:
                            color[node] = c
                    removed.add(v)
                    found = True
                    break
            if found:
                improved = True
                # If all vertices of target color are removed, we can drop the color
                if len(removed) == len(vertices):
                    break
        if improved:
            # Compact colors
            best_color = compact_colors(color)
        else:
