                    # Only if v is one of the two colors
                    if coloring[v] not in (target_color, c):
                        continue
                    # BFS to get component
                    stack = [v]
                    comp = set()
                    while stack:
                        node = stack.pop()
                        if node in comp:
                            continue
                        comp.add(node)
                        for u in neighbors[node]:
                            if coloring[u] in (target_color, c) and u not in comp:
