        # Use bucket sort for efficiency (n <= 100)
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d < len(buckets):
                buckets[d].append(v)
            else:
                # extend buckets if needed (should not happen with n<=100)
                buckets.extend([[] for _ in range(d - len(buckets) + 1)])
                buckets[d].append(v)
        # Pointer to current min non-empty bucket
        min_ptr = 0
        while remaining:
            # Find next non-empty bucket
            while min_ptr < len(buckets) and not buckets[min_ptr]:
                min_ptr += 1
            if min_ptr >= len(buckets):
                break  # should not happen
            # Get a vertex from this bucket
            v = buckets[min_ptr].pop()
            if v not in remaining:
                continue  # already removed, skip
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degree[u]
                    # remove u from its current bucket
                    if d < len(buckets) and u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    # ensure bucket exists
                    while d_new >= len(buckets):
                        buckets.append([])
                    buckets[d_new].append(u)
                    if d_new < min_ptr:
                        min_ptr = d_new
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(color, a, b, v):
        # Returns new coloring after swapping a and b in the component of v
        # Only if v has color a or b
        if color[v] not in (a, b):
            return color  # no change
        # BFS to get component
        from collections import deque
        comp = []
        seen = set()
        q = deque([v])
        seen.add(v)
        while q:
            node = q.popleft()
            comp.append(node)
            for nb in neighbors[node]:
                if nb not in seen and color[nb] in (a, b):
                    seen.add(nb)
                    q.append(nb)
        # Swap colors in component
        new_color = color[:]
        for node in comp:
            if new_color[node] == a:
                new_color[node] = b
            else:
                new_color[node] = a
        return new_color

    # Try to eliminate the last color via Kempe chains or reassignment
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target = k - 1
        # Vertices with target color
        targets = [v for v in range(n) if coloring[v] == target]
        changed = True
        # We'll try multiple passes
        for _pass in range(10):  # limit passes to avoid infinite loops
            if not targets:
                break
            made_progress = False
            for v in list(targets):  # iterate over copy
                if coloring[v] != target:
                    continue  # already recolored
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target):  # try colors 0..target-1
                    if not (used & (1 << c)):
                        # assign v to color c
                        coloring[v] = c
                        targets.remove(v)
                        made_progress = True
                        break
                if made_progress:
                    continue
                # Try Kempe chains with each lower color
                for c in range(target):
                    # Try swapping in component of v for colors (target, c)
                    # Only if v is in target color
                    if coloring[v] == target:
                        new_col = kempe_swap(coloring, target, c, v)
                        # Check if v is no longer target color
                        if new_col[v] != target:
                            # Accept the swap
                            coloring[:] = new_col
                            targets.remove(v)
                            made_progress = True
                            break
            if not made_progress:
                break
        # If target color class is empty, recurse
        if num_colors(coloring) < k:
            return reduce_colors(coloring)
        return coloring

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append(col_sl)
    except Exception:
        pass

    # If no candidate (should not happen), fall back to greedy by index
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_colors = num_colors(best)

    # Try to reduce colors using Kempe chains
    improved = reduce_colors(best[:])
    if is_valid(improved) and num_colors(improved) < best_colors:
        best = improved

    # Final validation and compacting (ensure colors are 0..k-1)
    # Though our methods should already do this, we re-map to be safe
    used_colors = set(best)
    mapping = {old: new for new, old in enumerate(sorted(used_colors)))
    final = [mapping[c] for c in best]
    # Double-check validity
    assert is_valid(final), "Invalid coloring produced"
    return final

