def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix or adjacency list
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Convert adjacency matrix to adjacency list
        adj_list = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
    else:
        # Treat as adjacency list
        adj_list = adj

    # Build bitmask representation for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits in integer
    def bit_count(x: int) -> int:
        return x.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur() -> list[int]:
        color = [-1] * n
        # saturation[v] = bitmask of colors used by colored neighbors
        saturation = [0] * n
        uncolored = set(range(n))
        # Precompute degrees for tie-breaking
        degree = [bit_count(bit_adj[u]) for u in range(n)]
        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (bit_count(saturation[x]), degree[x], random.random()))
            # Find smallest available color (mex)
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            neighbors = bit_adj[v] & ~((1 << n) - 1)  # mask to n bits
            for u in range(n):
                if (neighbors >> u) & 1 and u in uncolored:
                    saturation[u] |= (1 << c)
        return color

    # RLF (Recursive Largest First) independent set extraction
    def rlf() -> list[int]:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set S for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: bit_count(bit_adj[x] & uncolored_mask(uncolored)))
            S.add(v)
            # Partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            # Remove neighbors of v from U
            for u in list(U):
                if bit_adj[v] & (1 << u):
                    U.remove(u)
                    W.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = None
                best_score = -1
                best_deg = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = bit_count(bit_adj[u] & w_mask(W))
                    # Degree in U
                    deg_u = bit_count(bit_adj[u] & u_mask(U))
                    if w_count > best_score or (w_count == best_score and deg_u < best_deg):
                        best_score = w_count
                        best_deg = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in list(U):
                    if bit_adj[u] & (1 << w):
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: mask of uncolored set
    def uncolored_mask(uncolored_set):
        mask = 0
        for v in uncolored_set:
            mask |= (1 << v)
        return mask

    # Helper: mask of set W
    def w_mask(w_set):
        mask = 0
        for v in w_set:
            mask |= (1 << v)
        return mask

    # Helper: mask of set U
    def u_mask(u_set):
        mask = 0
        for v in u_set:
            mask |= (1 << v)
        return mask

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last() -> list[int]:
        if n == 0:
            return []
        # Compute degeneracy ordering via smallest-last
        remaining = set(range(n))
        order = []
        degrees = [bit_count(bit_adj[u]) for u in range(n)]
        # Current degrees in remaining subgraph
        curr_deg = degrees[:]
        while remaining:
            # Find vertex with minimum current degree
            v = min(remaining, key=lambda x: (curr_deg[x], x))
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    curr_deg[u] -= 1
        # Color in reverse order using first-fit
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select candidate with minimal number of colors
    def num_colors(col):
        return max(col) + 1 if col else 0

    best = min(candidates, key=num_colors)
    best_k = num_colors(best)

    # Kempe chain color reduction
    def kempe_reduction(color_in):
        nonlocal n, bit_adj
        color = color_in[:]
        changed = True
        while changed:
            changed = False
            # Find smallest color class (highest color index that is used)
            # We try to eliminate the highest color index first
            used_colors = set(color)
            if not used_colors:
                return color
            max_color = max(used_colors)
            # Try to eliminate colors from max_color downwards
            for target in range(max_color, -1, -1):
                # Collect vertices with color target
                targets = [v for v in range(n) if color[v] == target]
                if not targets:
                    continue
                # Try to recolor each target vertex
                for v in targets:
                    # Try direct reassignment to a lower color
                    used_by_neighbors = 0
                    for u in range(n):
                        if (bit_adj[v] >> u) & 1:
                            used_by_neighbors |= (1 << color[u])
                    for c in range(target):  # only try colors < target
                        if not (used_by_neighbors & (1 << c)):
                            color[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # If direct reassignment not possible, try Kempe chains
                    for c in range(target):
                        # Check if v is in a (target, c) Kempe chain that can be swapped
                        # We do BFS to find the component of v in the subgraph of colors target and c
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for nb in range(n):
                                if (bit_adj[node] >> nb) & 1:
                                    if color[nb] == target or color[nb] == c:
                                        if not visited[nb]:
                                            visited[nb] = True
                                            queue.append(nb)
                        # Check if swapping target<->c in this component is valid and frees color target for v
                        # After swap, v will have color c, so we need to ensure no neighbor of v has color c outside the component
                        # Actually, since we only swap within the component, and the component is connected via target/c edges,
                        # after swap, neighbors inside component will have the opposite color, but we must check neighbors outside
                        valid = True
                        for node in component:
                            for nb in range(n):
                                if (bit_adj[node] >> nb) & 1:
                                    if color[nb] == target and nb not in component:
                                        valid = False
                                        break
                                    if color[nb] == c and nb in component:
                                        # After swap, this nb will become target, which is ok as long as not conflicting
                                        pass
                            if not valid:
                                break
                        if valid:
                            # Perform swap: target <-> c in component
                            for node in component:
                                if color[node] == target:
                                    color[node] = c
                                elif color[node] == c:
                                    color[node] = target
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break
        # Compact colors to 0..k-1
        # Map existing colors to consecutive integers
        unique_colors = sorted(set(color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        color = [mapping[c] for c in color]
        return color

    # Apply Kempe reduction
    best = kempe_reduction(best)
    # Final validation (optional, but safe)
    for u in range(n):
        for v in adj_list[u]:
            if u < v and color[u] == color[v]:
                # In case of error, fallback to DSATUR
                return dsatur()
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)

    # Helper: compute number of colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if u < v and cu == coloring[v]:
                    return False
        return True

    # Helper: convert to consecutive colors starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Precompute degrees
        deg = [len(adj_list[i]) for i in range(n)]
        # Saturation sets: for each vertex, bitmask of colors used by neighbors
        sat = [0] * n
        # Order of coloring
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if color[u] == -1:
                    # saturation degree: number of distinct colors in neighbors
                    # we can compute by counting bits in sat[u]
                    s = sat[u].bit_count()
                    if s > max_sat or (s == max_sat and (deg[u] > max_deg or (deg[u] == max_deg and random.random() < 0.5))):
                        max_sat = s
                        max_deg = deg[u]
                        v = u
            if v == -1:
                break  # should not happen
            # Find smallest color not used by neighbors
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            # Update saturation of neighbors
            for nb in adj_list[v]:
                if color[nb] == -1:
                    sat[nb] |= (1 << c)
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        # Current color to assign
        c = 0
        # Set of uncolored vertices
        uncolored = set(range(n))
        while uncolored:
            # Build independent set for color c
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([nb for nb in adj_list[x] if nb in uncolored]))
            S.add(v)
            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = {u for u in uncolored if u not in S and all(nb not in S for nb in adj_list[u])}
            W = {u for u in uncolored if u not in S and u not in U}
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                u_best = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = len([nb for nb in adj_list[u] if nb in W])
                    deg_in_U = len([nb for nb in adj_list[u] if nb in U])
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        u_best = u
                if u_best is None:
                    break  # should not happen
                S.add(u_best)
                U.remove(u_best)
                # Move neighbors of u_best from U to W
                for nb in adj_list[u_best]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to all vertices in S
            for v in S:
                color[v] = c
            # Remove S from uncolored
            uncolored -= S
            c += 1
        return color

    # Smallest-Last (Matula & Beck) greedy
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll maintain a bucket queue for efficiency, but n<=100, so simple scan
        temp_deg = degree[:]
        remaining_set = set(range(n))
        while remaining_set:
            # Find vertex with minimum degree in remaining set
            v = min(remaining_set, key=lambda x: temp_deg[x])
            order.append(v)
            remaining_set.remove(v)
            # Decrease degree of neighbors
            for nb in adj_list[v]:
                if nb in remaining_set:
                    temp_deg[nb] -= 1
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen if input is valid
        # Make a copy to work on
        color = coloring[:]
        changed = True
        # We'll try to reduce colors until no improvement
        while changed:
            changed = False
            k = count_colors(color)
            if k <= 1:
                break
            # Try to eliminate color k-1
            target_color = k - 1
            # Vertices with target color
            target_vertices = [v for v in range(n) if color[v] == target_color]
            if not target_vertices:
                # Already missing, compact
                mapping = {}
                next_c = 0
                for v in range(n):
                    c_val = color[v]
                    if c_val not in mapping:
                        mapping[c_val] = next_c
                        next_c += 1
                color = [mapping[color[v]] for v in range(n)]
                changed = True
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for nb in adj_list[v]:
                    if color[nb] != -1:
                        used_by_neighbors |= (1 << color[nb])
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Can recolor v to c
                        color[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart from beginning after any change
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # If v already has color c after potential direct reassignment, skip
                    if color[v] == c:
                        continue
                    # Check if v and any vertex of color c are connected via a Kempe chain
                    # We only consider the subgraph induced by colors {c, target_color}
                    # If v is not connected to any vertex of color c in this subgraph, we can swap
                    # Build component from v using only colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (color[nb] == c or color[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any vertex in component has color c
                    has_color_c = any(color[node] == c for node in component)
                    if not has_color_c:
                        # Swap colors c and target_color in component
                        for node in component:
                            if color[node] == c:
                                color[node] = target_color
                            elif color[node] == target_color:
                                color[node] = c
                        changed = True
                        break
                if changed:
                    break
            # If we made a change, we may have reduced the number of colors
            if changed:
                # Compact colors
                mapping = {}
                next_c = 0
                for v in range(n):
                    c_val = color[v]
                    if c_val not in mapping:
                        mapping[c_val] = next_c
                        next_c += 1
                color = [mapping[color[v]] for v in range(n)]
        return color

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        color = [-1] * n
        for u in range(n):
            used = 0
            for nb in adj_list[u]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        candidates.append(color)

    # Select best candidate (fewest colors)
    best = min(candidates, key=count_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Ensure validity and consecutive colors
    if not is_valid(best):
        # Fallback to greedy if something went wrong
        color = [-1] * n
        for u in range(n):
            used = 0
            for nb in adj_list[u]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        best = color
    best = normalize(best)
    return best

