        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary entries)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute degrees
    if is_matrix:
        adj_list = []
        deg = [0] * n
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
                    deg[i] += 1
            adj_list.append(neighbors)
    else:
        adj_list = adj
        deg = [len(neighbors) for neighbors in adj_list]

    # Precompute bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize_coloring(coloring):
        if not coloring:
            return coloring
        # Map used colors to 0..k-1
        used = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(used)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # colored_neighbors_mask[v] = bitmask of colored neighbors
        colored_neighbors_mask = [0] * n
        # degree in uncolored subgraph (initially full degree)
        uncolored_degree = deg[:]
        uncolored_count = n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat_u = saturation[u]
                    deg_u = uncolored_degree[u]
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                       (sat_u == max_sat and deg_u == max_deg and random.random() < 0.5):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:  # should not happen
                break

            # Find smallest color not used by neighbors
            neighbor_colors = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    neighbor_colors |= (1 << coloring[nb])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            coloring[v] = color

            # Update uncolored neighbors: decrease their uncolored degree
            for nb in adj_list[v]:
                if coloring[nb] == -1:
                    uncolored_degree[nb] -= 1
            uncolored_count -= 1

            # Update saturation for uncolored neighbors: if this color is new to their neighborhood
            for nb in adj_list[v]:
                if coloring[nb] == -1:
                    # Check if color is already in nb's neighborhood from other colored neighbors
                    has_color = False
                    for nn in adj_list[nb]:
                        if coloring[nn] != -1 and coloring[nn] == color:
                            has_color = True
                            break
                    if not has_color:
                        saturation[nb] += 1
