    # RLF (Recursive Largest First) - independent set extraction
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set S for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: sum(1 for nb in adj_list[u] if nb in uncolored))
            S.add(v)
            # Partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(nb in S for nb in adj_list[u]):
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    # Count neighbors in W
                    nw = sum(1 for nb in adj_list[u] if nb in W)
                    deg_u = sum(1 for nb in adj_list[u] if nb in U)
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u) or \
                       (nw == max_nw and deg_u == min_deg_u and random.random() < 0.5):
                        max_nw = nw
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for u in S:
                coloring[u] = color
            uncolored -= S
            color += 1
        return normalize_coloring(coloring)

    # Smallest-Last (Matula & Beck) ordering + greedy
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        order = []
        degrees = deg[:]  # current degree in remaining graph
        removed = [False] * n
        # We'll use bucket sort for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            # Find vertex with min degree among non-removed
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u] and degrees[u] < min_deg:
                    min_deg = degrees[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            removed[v] = True
            # Decrease degree of neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    degrees[nb] -= 1
