                neighbor_colors = 0
                for nb in adj_list[v]:
                    if current[nb] != -1:
                        neighbor_colors |= (1 << current[nb])
                found = False
                for c in range(target_color):  # try colors 0 to k-2
                    if not (neighbor_colors & (1 << c)):
                        # Can recolor v to c directly
                        current[v] = c
                        found = True
                        break
                if found:
                    improved = True
                    # After recoloring v, check if target color class is empty
                    if not any(current[u] == target_color for u in range(n)):
                        k -= 1
                        # Normalize colors to be consecutive
                        used = sorted(set(current))
                        mapping = {old: new for new, old in enumerate(used)}
                        current = [mapping[c] for c in current]
                        break  # restart reduction with new k
                else:
                    # Try Kempe chain swap with each lower color
                    for c in range(target_color):
                        # We consider swapping colors target_color and c in the component containing v
                        # Build the Kempe chain: all vertices reachable from v via alternating target_color and c
                        # We'll do BFS
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            u = queue.popleft()
                            component.append(u)
                            for nb in adj_list[u]:
                                if not visited[nb] and (current[nb] == target_color or current[nb] == c):
                                    visited[nb] = True
                                    queue.append(nb)
                        # Check if swapping in this component would cause conflict:
                        # After swap, vertices originally target_color become c, and vice versa.
                        # We need to ensure that no vertex in the component that becomes c has a neighbor outside
                        # the component that is also c (and similarly for target_color, but we are removing target_color)
                        # Actually, we only care about the color c: after swap, we don't want two adjacent c's.
                        # So for any vertex u in component that originally had color c, after swap it becomes target_color.
                        # For any vertex u in component that originally had target_color, after swap it becomes c.
                        # We need to check: for any edge (u, w) where u in component and w not in component:
                        #   if current[u] == c and current[w] == c -> after swap, u becomes target_color, w remains c -> no conflict (target_color != c)
                        #   if current[u] == target_color and current[w] == c -> after swap, u becomes c, w is c -> conflict!
                        #   if current[u] == target_color and current[w] == target_color -> after swap, u becomes c, w becomes target_color -> no conflict
                        #   if current[u] == c and current[w] == target_color -> after swap, u becomes target_color, w becomes c -> no conflict
                        # So the only potential conflict is when we have an edge from a vertex in the component that is target_color
                        # to a vertex outside the component that is c.
                        # Similarly, we should also check for edges from component vertices that are c to outside vertices that are target_color?
                        #   After swap: u (was c) becomes target_color, w (was target_color) becomes c -> no conflict.
                        # So only one direction matters: component's target_color to outside's c.
                        conflict = False
                        for u in component:
                            if current[u] == target_color:
                                for nb in adj_list[u]:
                                    if not visited[nb] and current[nb] == c:
                                        conflict = True
                                        break
                            if conflict:
                                break
                        if not conflict:
                            # Perform the swap
                            for u in component:
                                if current[u] == target_color:
                                    current[u] = c
                                elif current[u] == c:
                                    current[u] = target_color
                            improved = True
                            # Check if target color class is now empty
                            if not any(current[u] == target_color for u in range(n)):
                                k -= 1
                                used = sorted(set(current))
                                mapping = {old: new for new, old in enumerate(used)}
                                current = [mapping[c] for c in current]
                                break  # break out of color loop
                        if improved:
                            break  # break out of vertex loop if we improved and possibly reduced k
                    if improved:
                        break  # break out of vertex loop
            # End for each target vertex
        return current

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            neighbor_colors = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    neighbor_colors |= (1 << coloring[nb])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            coloring[v] = color
        candidates.append(normalize_coloring(coloring))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and normalization
    if not is_valid_coloring(best):
        # Fallback to greedy ordering by degree
        order = sorted(range(n), key=lambda u: deg[u], reverse=True)
        coloring = [-1] * n
        for v in order:
            neighbor_colors = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    neighbor_colors |= (1 << coloring[nb])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            coloring[v] = color
        best = normalize_coloring(coloring)
    return best

