def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build bitmask adjacency list
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            nbrs = bit_adj[v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
                nbrs &= nbrs - 1
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: count distinct colors
    def count_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            c_u = colors[u]
            nbrs = bit_adj[u]
            while nbrs:
                v = (nbrs & -nbrs).bit_length() - 1
                if colors[v] == c_u:
                    return False
                nbrs &= nbrs - 1
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        # Precompute degrees
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        # Saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        colored = [False] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then index
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if not colored[i]:
                    sat = bin(saturation[i]).count('1')
                    deg = degrees[i]
                    if sat > max_sat or (sat == max_sat and (deg > max_deg or (deg == max_deg and i > v))):
                        max_sat = sat
                        max_deg = deg
                        v = i
            if v == -1:
                break  # should not happen
            # Find smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            # Update saturation of neighbors
            nbrs = bit_adj[v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                saturation[u] |= (1 << c)
                nbrs &= nbrs - 1
        return colors

    # RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            S = set()
            # Step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: bin(bit_adj[x] & sum((1 << u) for u in uncolored)).count('1'))
            S.add(v)
            # Partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            for u in U:
                if bit_adj[u] & (1 << v):
                    W.add(u)
                else:
                    # keep in U for now
                    pass
            # Actually, we need to split U and W properly
            U = {u for u in uncolored if u not in S and not (bit_adj[u] & sum((1 << s) for s in S))}
            W = uncolored - S - U
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = bin(bit_adj[u] & sum((1 << w) for w in W)).count('1')
                    deg_in_U = bin(bit_adj[u] & sum((1 << x) for x in U)).count('1')
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u is None:
                    break
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                nbrs = bit_adj[best_u]
                while nbrs:
                    w = (nbrs & -nbrs).bit_length() - 1
                    if w in U:
                        U.remove(w)
                        W.add(w)
                    nbrs &= nbrs - 1
            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
            # Next round: uncolored becomes W
            uncolored = W
        return colors

    # Smallest-Last ordering (degeneracy ordering)
    def smallest_last():
        if n == 0:
            return []
        # Copy degrees and adjacency for peeling
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        # adj_set for quick lookup
        adj_set = [set() for _ in range(n)]
        for i in range(n):
            nbrs = bit_adj[i]
            while nbrs:
                j = (nbrs & -nbrs).bit_length() - 1
                adj_set[i].add(j)
                nbrs &= nbrs - 1
        removed = [False] * n
        order = []
        # We'll maintain a list of vertices by current degree
        # Use buckets for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            d = degrees[i]
            if d < len(buckets):
                buckets[d].append(i)
        # Pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # Find next non-empty bucket
            while min_deg < len(buckets) and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= len(buckets):
                break  # should not happen
            v = buckets[min_deg].pop()
            if removed[v]:
                # find another
                while buckets[min_deg] and removed[buckets[min_deg][-1]]:
                    buckets[min_deg].pop()
                if not buckets[min_deg]:
                    min_deg += 1
                    continue
                v = buckets[min_deg].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            nbrs = bit_adj[v]
            while nbrs:
                u = (nbrs & -nbrs).bit_length() - 1
                if not removed[u]:
                    d = degrees[u]
                    # remove u from bucket d
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    degrees[u] -= 1
                    d_new = degrees[u]
                    if d_new < len(buckets):
                        buckets[d_new].append(u)
                nbrs &= nbrs - 1
        # Reverse order for coloring
        order.reverse()
        return greedy_color(order)

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(colors, a, b, v):
        if a == b:
            return False
        n = len(colors)
        # Find the Kempe chain component containing v in colors a,b
        stack = [v]
        visited = [False] * n
        visited[v] = True
        component = []
        while stack:
            u = stack.pop()
            component.append(u)
            nbrs = bit_adj[u]
            while nbrs:
                w = (nbrs & -nbrs).bit_length() - 1
                if not visited[w] and (colors[w] == a or colors[w] == b):
                    visited[w] = True
                    stack.append(w)
                nbrs &= nbrs - 1
        # Check if swapping is safe: no neighbor outside component has color a or b that would conflict
        # Actually, swapping within a component always preserves validity
        # Perform swap
        for u in component:
            if colors[u] == a:
                colors[u] = b
            else:
                colors[u] = a
        return True

    # Attempt to eliminate a color class via Kempe chains
    def reduce_colors_kempe(colors):
        if n == 0:
            return colors
        k = count_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            # Get vertices with this color
            vertices = [i for i in range(n) if colors[i] == target_color]
            if not vertices:
                continue
            # Try to recolor each vertex
            made_progress = False
            for v in vertices:
                # Try direct reassignment to a lower color
                used = 0
                nbrs = bit_adj[v]
                while nbrs:
                    u = (nbrs & -nbrs).bit_length() - 1
                    c = colors[u]
                    if c != -1:
                        used |= (1 << c)
                    nbrs &= nbrs - 1
                for c in range(target_color):  # only try lower colors
                    if not (used & (1 << c)):
                        colors[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Try to swap along (target_color, c) Kempe chain starting at v
                    # Make a copy to test
                    colors_copy = colors[:]
                    if kempe_swap(colors_copy, target_color, c, v):
                        # Check if after swap, v is no longer target_color (should be c)
                        if colors_copy[v] != target_color:
                            # Accept swap
                            colors[:] = colors_copy
                            made_progress = True
                            break
                if made_progress:
                    break
            if made_progress:
                # After recoloring, compact and try again
                colors = compact_colors(colors)
                return reduce_colors_kempe(colors)  # recurse
        # No progress, return current
        return colors

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(compact_colors(c1))
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(compact_colors(c2))
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(compact_colors(c3))
    except:
        pass
    # Fallback: greedy by degree order
    try:
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(compact_colors(c4))
    except:
        pass
    # If no candidates, assign all zeros (only valid for edgeless)
    if not candidates:
        return [0] * n

    # Select candidate with fewest colors
    best = min(candidates, key=lambda x: count_colors(x))
    # Apply Kempe reduction iteratively
    best = reduce_colors_kempe(best)
    # Final validation and compaction
    if not is_valid(best):
        # Should not happen, but fallback to DSATUR
        best = dsatur()
        best = compact_colors(best)
    return best

