            v = -1
            max_deg = -1
            for u in uncolored:
                deg = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
                elif deg == max_deg and (v == -1 or u < v):
                    v = u
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = set(uncolored)
            U.remove(v)
            W = set()
            for u in adj_list[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # Greedily add to independent set
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
