    # Kempe chain color reduction
    def kempe_reduce(coloring):
        n_local = n
        color_local = coloring[:]
        improved = True
        while improved:
            improved = False
            # Find smallest color class (highest color index that is used)
            used_colors = set(color_local)
            if not used_colors:
                break
            max_color = max(used_colors)
            # Try to eliminate color classes from highest down
            for target_color in range(max_color, -1, -1):
                vertices_target = [v for v in range(n_local) if color_local[v] == target_color]
                if not vertices_target:
                    continue
                # Try to recolor each vertex in this class
                made_progress = False
                for v in vertices_target:
                    used_by_neighbors = 0
                    for u in adj_list[v]:
                        c = color_local[u]
                        if c != -1:
                            used_by_neighbors |= (1 << c)
