                    for c in range(target_color):
                        if not (used_by_neighbors & (1 << c)):
                            color_local[v] = c
                            made_progress = True
                            improved = True
                            break
                    if made_progress:
                        break
                    # Try Kempe chains with each lower color
                    for c in range(target_color):
                        if used_by_neighbors & (1 << c):
                            continue  # Skip if neighbor already has color c (would cause conflict if swapped)
                        # Find Kempe chain of colors (target_color, c) containing v
                        visited = [False] * n_local
                        stack = [v]
                        visited[v] = True
                        component = []
                        while stack:
                            node = stack.pop()
                            component.append(node)
                            for nb in adj_list[node]:
                                if not visited[nb] and (color_local[nb] == target_color or color_local[nb] == c):
                                    visited[nb] = True
                                    stack.append(nb)
                        # Check if any neighbor of v in the component has color c (would cause conflict after swap)
                        conflict = False
                        for node in component:
                            for nb in adj_list[node]:
                                if color_local[nb] == c and nb in component:
                                    conflict = True
                                    break
                            if conflict:
                                break
                        if not conflict:
                            # Perform swap: target_color <-> c in component
                            for node in component:
                                if color_local[node] == target_color:
                                    color_local[node] = c
                                elif color_local[node] == c:
