            neighbors[i] = list(adj[i])  # ensure we have a list

    # Build bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: validate coloring
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                if color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Candidate 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_count = saturation[v].bit_count()
                deg = uncolored_deg[v]
                if sat_count > best_sat or (sat_count == best_sat and deg > best_deg) or \
                   (sat_count == best_sat and deg == best_deg and (best_v == -1 or random.random() < 0.5)):
                    best_sat = sat_count
                    best_deg = deg
                    best_v = v
            v = best_v
            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Candidate 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build maximal independent set for color c
            # start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible for this color)
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_u_deg = float('inf')
                for u in U:
                    score = sum(1 for w in neighbors[u] if w in W)
                    deg_in_U = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and deg_in_U < best_u_deg) or \
                       (score == best_score and deg_in_U == best_u_deg and (best_u == -1 or random.random() < 0.5)):
                        best_score = score
                        best_u_deg = deg_in_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for vertex in S:
                color[vertex] = c
                uncolored.remove(vertex)
            c += 1
        return color

    # Candidate 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # buckets for degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if deg[v] < len(buckets):
                buckets[deg[v]].append(v)
        # pointer to current min degree
        min_deg = 0
        while remaining:
            # find non-empty bucket
            while min_deg < len(buckets) and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= len(buckets):
                break
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    # move u from bucket deg[u] to deg[u]-1
                    old_deg = deg[u]
                    deg[u] -= 1
                    if old_deg < len(buckets):
                        # remove u from old bucket (inefficient but n<=100)
                        if u in buckets[old_deg]:
                            buckets[old_deg].remove(u)
                    if deg[u] < len(buckets):
                        buckets[deg[u]].append(u)
                    if deg[u] < min_deg:
                        min_deg = deg[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate, fallback to simple greedy
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=num_colors)

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color to free the color
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return True  # already empty
        # Try direct reassignment first
        new_coloring = coloring[:]
        for v in vertices:
            used = 0
            for u in neighbors[v]:
                if new_coloring[u] != -1:
                    used |= (1 << new_coloring[u])
            # find smallest color not used and < target_color if possible
            for c in range(target_color):  # only try colors less than target
                if not (used & (1 << c)):
                    new_coloring[v] = c
                    break
            else:
                # cannot reassign directly, try Kempe swap
                swapped = False
                for c in range(target_color):
                    # check if v is in a Kempe chain of (target_color, c) that does not include other target_color vertices?
                    # Actually, we try to swap the component containing v in the subgraph of colors {c, target_color}
                    # If after swap, v becomes c and no other vertex becomes target_color, we can free target_color
                    # But simpler: try to swap and see if we reduce the number of target_color
                    # We'll do BFS for the Kempe chain
                    stack = [v]
                    visited = set()
                    component = []
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.append(node)
                            for nb in neighbors[node]:
                                if coloring[nb] == target_color or coloring[nb] == c:
                                    if nb not in visited:
                                        stack.append(nb)
                    # In this component, count target_color and c
                    count_target = sum(1 for node in component if coloring[node] == target_color)
                    count_c = sum(1 for node in component if coloring[node] == c)
                    # If we swap, target_color becomes c and c becomes target_color
                    # After swap, number of target_color vertices would be count_c
                    # We want to eliminate target_color, so we need count_c == 0 after swap? 
                    # Actually, we want to reassign v to c without increasing target_color elsewhere.
                    # If the component has no other target_color vertices besides v, then after swap v becomes c and target_color is removed from component.
                    if count_target == 1:  # only v has target_color in this component
                        # perform swap
                        for node in component:
                            if coloring[node] == target_color:
                                new_coloring[node] = c
                            else:  # must be c
                                new_coloring[node] = target_color
                        swapped = True
                        break
                if swapped:
                    break
                else:
                    # could not swap for any c, leave as target_color for now
                    pass
        # After processing, check if target_color is still used
        if target_color not in new_coloring:
            return new_coloring
        # If not eliminated, try to see if we can reduce by reassigning some vertices to higher colors? 
        # But we want to eliminate, so return None if not eliminated
        return None

    # Iteratively try to eliminate the highest color class
    current = best_coloring[:]
    improved = True
    while improved and num_colors(current) > 0:
        k = num_colors(current)
        target = k - 1
        new_coloring = eliminate_color_class(current, target)
        if new_coloring is not None and is_valid_coloring(new_coloring):
            current = new_coloring
        else:
            improved = False

    # Ensure colors are consecutive starting from 0
    # Map colors to 0..k-1
    unique_colors = sorted(set(current))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    final = [mapping[c] for c in current]

    # Final validation (should be valid)
    if not is_valid_coloring(final):
        # fallback to greedy if something went wrong
        final = greedy_color(list(range(n)))
        unique_colors = sorted(set(final))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        final = [mapping[c] for c in final]

    return final

