def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:  # safety check
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # Precompute degrees
        deg = [len(adj_list[i]) for i in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    # Compute saturation: distinct colors in neighbors
                    neighbor_colors = set()
                    for nb in adj_list[u]:
                        if colors[nb] != -1:
                            neighbor_colors.add(colors[nb])
                    sat = len(neighbor_colors)
                    if sat > max_sat or (sat == max_sat and deg[u] > max_deg):
                        max_sat = sat
                        max_deg = deg[u]
                        v = u
            if v == -1:  # should not happen
                break
            # Find smallest available color
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used[colors[nb]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build independent set for this color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda u: len([w for w in adj_list[u] if w in uncolored]))
            S.append(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set(uncolored) - {v}
            W = set()
            for nb in adj_list[v]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W
                u_star = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = len([w for w in adj_list[u] if w in W])
                    deg_in_U = len([w for w in adj_list[u] if w in U])
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        u_star = u
                if u_star == -1:
                    break  # should not happen
                S.append(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for nb in adj_list[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for u in S:
                colors[u] = color
            uncolored -= S
            color += 1
        return compact_colors(colors)

    # Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll use buckets for efficiency, but n<=100 so simple scan is fine
        temp_deg = degree[:]
        remaining_set = set(range(n))
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining_set:
                if temp_deg[u] < min_deg:
                    min_deg = temp_deg[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining_set.remove(v)
            # Update degrees of neighbors
            for nb in adj_list[v]:
                if nb in remaining_set:
                    temp_deg[nb] -= 1
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used[colors[nb]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain-based color reduction
    def kempe_reduce(colors_in):
        colors = colors_in[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(colors)
            if k <= 1:
                break
            # Target smallest color class (color k-1)
            target_color = k - 1
            vertices = [i for i in range(n) if colors[i] == target_color]
            if not vertices:
                # Already compacted? should not happen
                break
            # Try to recolor each vertex in target class
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for nb in adj_list[v]:
                    if colors[nb] != -1:
                        neighbor_colors.add(colors[nb])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    # After moving one vertex, break to restart
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v is in a (target_color, c) Kempe chain that can be swapped
                    # We'll do BFS for the component containing v in the subgraph of colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for nb in adj_list[u]:
                            if not visited[nb] and colors[nb] in (target_color, c):
                                visited[nb] = True
                                queue.append(nb)
                    # Invert colors in component: target_color <-> c
                    # Check if after swap, no conflict arises (should be valid by Kempe)
                    # But we need to ensure we don't pull vertices into target_color from elsewhere?
                    # Actually, swapping preserves validity. We just need to see if v can leave target_color.
                    # After swap, v will have color c, so target_color loses v.
                    # Perform swap
                    for u in component:
                        if colors[u] == target_color:
                            colors[u] = c
                        elif colors[u] == c:
                            colors[u] = target_color
                    changed = True
                    break
                if changed:
                    break
            if changed:
                # Compact colors after any change
                colors = compact_colors(colors)
        return colors

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        colors = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    used[colors[nb]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[i] = c
        candidates.append(compact_colors(colors))

    # Apply Kempe reduction to each candidate and pick best
    best_colors = None
    best_k = float('inf')
    for col in candidates:
        reduced = kempe_reduce(col)
        if is_valid_coloring(reduced):
            k = num_colors(reduced)
            if k < best_k:
                best_k = k
                best_colors = reduced

    # Final validation and compact
    if best_colors is None:
        best_colors = candidates[0]
    best_colors = compact_colors(best_colors)
    if not is_valid_coloring(best_colors):
        # Ultimate fallback: greedy
        colors = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for nb in adj_list[i]:
                if colors[nb] != -1:
                    used[colors[nb]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[i] = c
        best_colors = compact_colors(colors)

    return best_colors

