def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle trivial cases
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        is_matrix = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for u in range(n):
            for v in adj_list[u]:
                bit_adj[u] |= (1 << v)

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: normalize colors to 0..k-1
    def normalize_colors(colors):
        if not colors:
            return colors
        # Map used colors to 0..k-1
        unique_colors = sorted(set(colors))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in colors]

    # DSATUR algorithm
    def dsatur():
        colors = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # colored neighbor sets as bitmask
        neighbor_colors = [0] * n
        # degree in uncolored subgraph (for tie-breaking)
        uncolored_deg = [len(adj_list[u]) for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and uncolored_deg[u] > max_deg) or \
                   (sat[u] == max_sat and uncolored_deg[u] == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat[u]
                    max_deg = uncolored_deg[u]
                    v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color (mex)
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

            # Update uncolored neighbors of v
            for u in adj_list[v]:
                if u in uncolored:
                    # Add color c to u's neighbor colors
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1
                    # Decrease uncolored degree
                    uncolored_deg[u] -= 1
            uncolored.remove(v)

        return normalize_colors(colors)

    # RLF algorithm (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: sum(1 for w in adj_list[u] if w in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = {u for u in uncolored if u != v and not any(w in adj_list[u] for w in independent_set)}
            W = {u for u in uncolored if u != v and any(w in adj_list[u] for w in independent_set)}

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_u_deg = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    u_deg = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and u_deg < min_u_deg) or \
                       (w_neighbors == max_w_neighbors and u_deg == min_u_deg and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_u_deg = u_deg
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to independent set
            for v in independent_set:
                colors[v] = color_idx
                uncolored.remove(v)
            color_idx += 1

        return normalize_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Core decomposition to get ordering
        deg = [len(adj_list[u]) for u in range(n)]
        # Bin vertices by degree
        max_deg = max(deg) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            bins[deg[u]].append(u)
        # Pointer to current non-empty bin
        ptr = 0
        order = []
        # Current degree of each vertex (will be updated)
        curr_deg = deg[:]
        removed = [False] * n

        for _ in range(n):
            # Find non-empty bin
            while ptr <= max_deg and not bins[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = bins[ptr].pop()
            if removed[v]:
                continue  # skip if already removed (should not happen with proper bin maintenance)
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    # Remove u from its current bin
                    old_deg = curr_deg[u]
                    bins[old_deg].remove(u)  # O(n) but n<=100
                    curr_deg[u] -= 1
                    new_deg = curr_deg[u]
                    bins[new_deg].append(u)
                    if new_deg < ptr:
                        ptr = new_deg

        # Color in reverse order using greedy first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

        return normalize_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                # Already empty, compact and continue
                colors = [c if c < target_color else c - 1 for c in colors]
                k -= 1
                continue

            # Try to recolor each target vertex
            for v in target_vertices:
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if colors[u] != -1:
                        used_by_neighbors |= (1 << colors[u])
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart from highest color

                # Try Kempe chain swaps
                for c in range(target_color):
                    # Check if v can be recolored to c via Kempe chain (target_color, c)
                    # Only if v is not adjacent to any vertex of color c
                    if used_by_neighbors & (1 << c):
                        continue  # adjacent to color c, cannot swap directly
                    # Find Kempe chain component containing v in colors {target_color, c}
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in adj_list[node]:
                            if not visited[u] and (colors[u] == target_color or colors[u] == c):
                                visited[u] = True
                                stack.append(u)
                    # Check if swapping this component is safe: 
                    # no vertex in component adjacent to a vertex of color c outside component
                    safe = True
                    for node in component:
                        for u in adj_list[node]:
                            if colors[u] == c and not visited[u]:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # Perform swap: target_color <-> c in component
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            else:  # must be c
                                colors[node] = target_color
                        improved = True
                        break
                if improved:
                    break

            if not improved:
                # Could not eliminate target color, try next lower
                # But we break to avoid infinite loop; in practice, we return current
                break

        return normalize_colors(colors)

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            colors = func()
            if not is_valid_coloring(colors):
                continue
            k = num_colors(colors)
            if k < best_k:
                best_k = k
                best_colors = colors
        except Exception:
            continue  # skip if any heuristic fails

    # Fallback: if all heuristics failed, use simple greedy
    if best_colors is None:
        colors = [-1] * n
        for u in range(n):
            used = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        best_colors = normalize_colors(colors)

    # Apply Kempe chain reduction to try to improve
    try:
        reduced = kempe_reduce(best_colors[:])
        if is_valid_coloring(reduced):
            k_red = num_colors(reduced)
            if k_red < num_colors(best_colors):
                best_colors = reduced
    except Exception:
        pass

    return best_colors

