def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square, binary entries)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = deg[v]
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and (best_v == -1 or v < best_v)):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            uncolored.remove(v)
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            # Update saturation and degree for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            deg_uncolored = [0] * n
            for v in uncolored:
                for u in neighbors[v]:
                    if u in uncolored:
                        deg_uncolored[v] += 1
            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            independent_set = {v}
            to_remove = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v}
            W = set()
            for u in neighbors[v]:
                if u in uncolored:
                    W.add(u)
                    if u in U:
                        U.remove(u)
            # While there are eligible vertices
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_u = float('inf')
                for u in U:
                    # count neighbors in W
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # degree in U-induced subgraph
                    deg_u = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or (score == best_score and deg_u == best_deg_u and (best_u == -1 or u < best_u)):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                to_remove.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to independent set
            for v in independent_set:
                color[v] = c
            uncolored -= to_remove
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Core decomposition to get ordering
        deg = [len(neighbors[i]) for i in range(n)]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # track current degree and position
        pos = [0] * n
        for d in range(max_deg + 1):
            for i, v in enumerate(buckets[d]):
                pos[v] = i
        # simulate peeling
        order = []
        current_deg = deg[:]
        # pointers to non-empty buckets
        ptr = [0] * (max_deg + 1)
        for d in range(max_deg + 1):
            ptr[d] = len(buckets[d]) - 1
        # We'll maintain a list of vertices in each bucket and update as we peel
        # Instead, we use a simple O(n^2) method since n <= 100
        remaining = set(range(n))
        for _ in range(n):
            # find vertex with min degree in remaining
            v = min(remaining, key=lambda x: current_deg[x])
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    current_deg[u] -= 1
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate initial candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best initial coloring (fewest colors)
    best_coloring = min(candidates, key=count_colors)
    if not is_valid(best_coloring):
        # fallback to simple greedy by degree order
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        best_coloring = greedy_color(order)

    # Kempe chain based color reduction
    def eliminate_color_class(coloring, target_color):
        # Get vertices with target_color
        verts = [v for v in range(n) if coloring[v] == target_color]
        if not verts:
            return coloring, True  # already eliminated

        # Try to recolor each vertex in target_color class
        # We'll try to move them to lower colors
        # Make a copy to work on
        new_coloring = coloring[:]
        # For each vertex in the target class, try to reassign
        for v in verts:
            used = 0
            for u in neighbors[v]:
                if new_coloring[u] != -1:
                    used |= (1 << new_coloring[u])
            # Try colors from 0 to target_color-1
            for c in range(target_color):
                if not (used & (1 << c)):
                    new_coloring[v] = c
                    break
            else:
                # Could not assign directly, try Kempe chains
                found = False
                for c in range(target_color):
                    # Check if we can swap along (c, target_color) Kempe chain
                    # If v is not in the c-colored component reachable via alternating c/target_color, we can swap
                    # Do BFS to find the Kempe chain component containing v for colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in neighbors[node]:
                            if not visited[nb] and (new_coloring[nb] == c or new_coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any neighbor of v has color c (which would cause conflict if we swap)
                    conflict = False
                    for nb in neighbors[v]:
                        if new_coloring[nb] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: c <-> target_color in component
                        for node in component:
                            if new_coloring[node] == c:
                                new_coloring[node] = target_color
                            elif new_coloring[node] == target_color:
                                new_coloring[node] = c
                        new_coloring[v] = c  # after swap, v should be color c
                        found = True
                        break
                if not found:
                    # Cannot recolor v, so we cannot eliminate this color class
                    return coloring, False
        # After processing all vertices, verify validity
        if is_valid(new_coloring):
            return new_coloring, True
        else:
            return coloring, False

    # Iteratively try to eliminate the highest color class
    current = best_coloring[:]
    k = count_colors(current)
    changed = True
    # Limit iterations to avoid infinite loops
    for _ in range(k):
        if not changed:
            break
        changed = False
        # Try to eliminate color k-1, then k-2, etc. (highest first)
        for target in range(k-1, -1, -1):
            new_coloring, success = eliminate_color_class(current, target)
            if success:
                current = new_coloring
                changed = True
                k = count_colors(current)
                # break to restart from highest color in new coloring
                break

    # Final validation and compaction (ensure colors are 0..k-1 consecutive)
    if not is_valid(current):
        # Last resort: greedy by degree
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        current = greedy_color(order)

    # Compact colors: remap to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = current[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        current[i] = unique_colors[c]

    return current

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute bit masks
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Build bit masks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # Precompute degrees
        deg = [len(adj_list[i]) for i in range(n)]
        # Track saturation: bitmask of colors used by neighbors
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                d = sum(1 for u in adj_list[v] if u in uncolored)
                if s > best_sat or (s == best_sat and d > best_deg) or (s == best_sat and d == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S = {v}
            # Partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = {u for u in uncolored if u != v and not any((1 << y) & bit_adj[u] for y in S)}
            W = {u for u in uncolored if u != v and any((1 << y) & bit_adj[u] for y in S)}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = float('inf')
                for u in U:
                    w_neighbors = sum(1 for y in adj_list[u] if y in W)
                    u_deg = sum(1 for y in adj_list[u] if y in U)
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and u_deg < best_u_deg):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in adj_list[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll maintain a list of vertices by current degree
        buckets = [[] for _ in range(n)]
        for v in range(n):
            d = degree[v]
            if d < n:
                buckets[d].append(v)
        # Pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # Find non-empty bucket
            while min_deg < n and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break  # should not happen
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    # Remove u from bucket d
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    if d_new < n:
                        buckets[d_new].append(u)
                    if d_new < min_deg:
                        min_deg = d_new
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select candidate with fewest colors
    best = min(candidates, key=count_colors)
    k = count_colors(best)

    # Kempe chain-based color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color to lower colors
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return True  # already eliminated
        # Try direct reassignment first
        moved = [False] * n
        for v in vertices:
            used = 0
            for u in adj_list[v]:
                c = coloring[u]
                if c != -1 and c < target_color:
                    used |= (1 << c)
            for c in range(target_color):
                if not (used & (1 << c)):
                    coloring[v] = c
                    moved[v] = True
                    break
        # If all moved, success
        if all(moved[v] for v in vertices):
            return True
        # Try Kempe chains for remaining vertices
        remaining_v = [v for v in vertices if not moved[v]]
        for v in remaining_v:
            for c in range(target_color):
                # Check if v can swap with color c via Kempe chain
                # Build the (c, target_color) component containing v
                stack = [v]
                visited = set()
                component = set()
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    if coloring[node] == c or coloring[node] == target_color:
                        component.add(node)
                        for nb in adj_list[node]:
                            if nb not in visited and (coloring[nb] == c or coloring[nb] == target_color):
                                stack.append(nb)
