                    moved[v] = True
                    break
            if moved[v]:
                break
        return all(moved[v] for v in vertices)

    # Iteratively try to eliminate highest color class
    improved = True
    while improved and k > 0:
        improved = False
        # Try from highest color down
        for target_color in range(k-1, -1, -1):
            # Make a copy to test
            test_coloring = best[:]
            if eliminate_color_class(test_coloring, target_color):
                # Success: compact colors
                # Relabel to consecutive
                used_colors = set(test_coloring)
                mapping = {old: new for new, old in enumerate(sorted(used_colors))]
                new_coloring = [mapping[c] for c in test_coloring]
                if is_valid(new_coloring) and count_colors(new_coloring) < k:
                    best = new_coloring
                    k = count_colors(best)
                    improved = True
                    break  # restart from new highest
        # If no improvement, break

    # Final validation and compacting (ensure 0..k-1)
    used = set(best)
    mapping = {old: new for new, old in enumerate(sorted(used))]
    best = [mapping[c] for c in best]
    return best

