import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Precompute triangle counts for each vertex
    triangle_count = [0] * n
    for u in range(n):
        neighbors = adj_list[u]
        deg_u = len(neighbors)
        for i in range(deg_u):
            v = neighbors[i]
            for j in range(i + 1, deg_u):
                w = neighbors[j]
                if (bit_adj[v] >> w) & 1:
                    triangle_count[u] += 1

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count distinct colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # Order 1: Descending triangle count, then degree
    order1 = sorted(range(n), key=lambda x: (-triangle_count[x], -len(adj_list[x])))
    coloring1 = greedy_color(order1)
    k1 = count_colors(coloring1)
    if k1 < best_k:
        best_k = k1
        best_coloring = coloring1

    # Order 2: Descending degree (Welsh-Powell)
    order2 = sorted(range(n), key=lambda x: -len(adj_list[x]))
    coloring2 = greedy_color(order2)
    k2 = count_colors(coloring2)
    if k2 < best_k:
        best_k = k2
        best_coloring = coloring2

    # Order 3: Smallest-Last (Matula-Beck degeneracy ordering)
    deg = [len(adj_list[i]) for i in range(n)]
    removed = [False] * n
    order3 = []
    for _ in range(n):
        min_deg = float('inf')
        v = -1
        for i in range(n):
            if not removed[i] and deg[i] < min_deg:
                min_deg = deg[i]
                v = i
        if v == -1:
            break
        removed[v] = True
        order3.append(v)
        for u in adj_list[v]:
            if not removed[u]:
                deg[u] -= 1
    order3.reverse()
    coloring3 = greedy_color(order3)
    k3 = count_colors(coloring3)
    if k3 < best_k:
        best_k = k3
        best_coloring = coloring3

    # Order 4: DSATUR with bitmask optimization
    color = [-1] * n
    saturated = [0] * n  # bitmask of colors used by neighbors
    uncolored = set(range(n))
    for _ in range(n):
        if not uncolored:
            break
        # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
        v = -1
        max_sat = -1
        max_deg_uncolored = -1
        for u in uncolored:
            sat_u = saturated[u].bit_count()
            deg_uncolored = 0
            for w in adj_list[u]:
                if w in uncolored:
                    deg_uncolored += 1
            if sat_u > max_sat or (sat_u == max_sat and deg_uncolored > max_deg_uncolored) or \
               (sat_u == max_sat and deg_uncolored == max_deg_uncolored and random.random() < 0.5):
                max_sat = sat_u
                max_deg_uncolored = deg_uncolored
                v = u
        # Assign smallest available color
        avail = ~saturated[v] & ((1 << (n + 1)) - 1)  # enough bits
        c = (avail & -avail).bit_length() - 1
        color[v] = c
        uncolored.remove(v)
        # Update saturation of neighbors
        for u in adj_list[v]:
            if u in uncolored:
                saturated[u] |= (1 << c)
    coloring4 = color
    k4 = count_colors(coloring4)
    if k4 < best_k:
        best_k = k4
        best_coloring = coloring4

    # Kempe chain color reduction
    def try_reduce_k(coloring):
        k = count_colors(coloring)
        if k <= 1:
            return coloring
        # Work on a copy
        color = coloring[:]
        changed = True
        while changed and k > 1:
            changed = False
            # Find smallest color class (highest color index)
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[color[v]].append(v)
            # Try to eliminate color k-1
            target_color = k - 1
            target_vertices = color_classes[target_color][:]
            # Try direct reassignment first
            for v in target_vertices:
                used = 0
                for u in adj_list[v]:
                    c = color[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target_color):
                    if not (used & (1 << c)):
                        color[v] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # Recompute classes and k
                color_classes = [[] for _ in range(k)]
                for v in range(n):
                    color_classes[color[v]].append(v)
                # Find new k
                new_k = 0
                for c in range(k-1, -1, -1):
                    if color_classes[c]:
                        new_k = c + 1
                        break
                if new_k < k:
                    k = new_k
                    color = [c if c < k else 0 for c in color]  # compact, though should not be needed
                    continue
            # Try Kempe chains for each vertex in target color
            for v in target_vertices:
                if color[v] != target_color:  # might have been recolored
                    continue
                for c in range(target_color):
                    # Find Kempe chain (target_color, c) containing v
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in adj_list[node]:
                            if not visited[u] and (color[u] == target_color or color[u] == c):
                                visited[u] = True
                                stack.append(u)
                    # Check if inverting this component is safe: no neighbor outside component has color c
                    safe = True
                    for node in component:
                        for u in adj_list[node]:
                            if not visited[u] and color[u] == c:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for node in component:
                            if color[node] == target_color:
                                color[node] = c
                            else:
                                color[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # Recompute k
                color_classes = [[] for _ in range(k)]
                for v in range(n):
                    color_classes[color[v]].append(v)
                new_k = 0
                for c in range(k-1, -1, -1):
                    if color_classes[c]:
                        new_k = c + 1
                        break
                if new_k < k:
                    k = new_k
        return color[:k] if k > 0 else []

    # Apply reduction to best coloring
    reduced = try_reduce_k(best_coloring)
    if reduced:
        # Validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if u < v and reduced[u] == reduced[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            # Ensure consecutive colors
            unique_colors = sorted(set(reduced))
            mapping = {old: new for new, old in enumerate(unique_colors)}
            final = [mapping[c] for c in reduced]
            return final

    # Fallback: return best found if reduction failed
    unique_colors = sorted(set(best_coloring))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    return [mapping[c] for c in best_coloring]

