def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert to consecutive colors
    def normalize(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # Heuristic 1: DSATUR with bitmask and tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        deg_uncolored = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex: max saturation, then max deg_uncolored, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and deg_uncolored[u] > max_deg) or \
                   (s == max_sat and deg_uncolored[u] == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = s
                    max_deg = deg_uncolored[u]
                    v = u
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # degree in uncolored subgraph
            deg = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in neighbors[v]:
                    if u in uncolored:
                        deg[v] += 1
            # start with max degree vertex
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to S, W: adjacent to S
            U = {u for u in uncolored if all(u not in neighbors[w] for w in S)}
            W = uncolored - U
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in neighbors[u] if w in W)
                    deg_u = sum(1 for w in neighbors[u] if w in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or \
                       (w_neighbors == max_w_neighbors and deg_u == min_deg_u and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
            uncolored = W  # for next color, only consider vertices adjacent to current S
        return color

    # Heuristic 3: Smallest-Last (Matula & Beck)
    def smallest_last():
        # Core decomposition to get ordering
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current min degree
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    buckets[d].remove(u)
                    deg[u] -= 1
                    buckets[deg[u]].append(u)
                    if deg[u] < ptr:
                        ptr = deg[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Heuristic 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Run all heuristics and collect candidates
    candidates = []
    for heuristic in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = heuristic()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # If no candidate, fallback to simple greedy
    if not candidates:
        col = greedy_color(list(range(n)))
        if is_valid(col):
            candidates.append(col)

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=count_colors) if candidates else [0]*n
    best_k = count_colors(best_coloring)

    # Local search: Kempe chain based color reduction
    def kempe_reduce(coloring):
        nonlocal best_k
        improved = True
        # Use tabu tenure to avoid cycling
        tabu = {}
        tabu_tenure = 5
        iteration = 0
        max_iterations = 100
        while improved and iteration < max_iterations:
            improved = False
            iteration += 1
            # Try to eliminate the largest color index
            max_color = max(coloring) if coloring else -1
            if max_color < 0:
                break
            # Get vertices with color max_color
            vertices = [v for v in range(n) if coloring[v] == max_color]
            random.shuffle(vertices)
            for v in vertices:
                # Try to recolor v to a smaller color
                neighbor_colors = set()
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        neighbor_colors.add(c)
                # Try direct reassignment
                for c in range(max_color):  # only try colors < max_color
                    if c not in neighbor_colors:
                        # Check tabu: (v, c) or (v, old_color) recent?
                        tabu_key = (v, c)
                        if tabu_key in tabu and tabu[tabu_key] > 0:
                            continue
                        # Make change
                        old_color = coloring[v]
                        coloring[v] = c
                        if is_valid(coloring):
                            # Update tabu
                            tabu[tabu_key] = tabu_tenure
                            tabu_old = (v, old_color)
                            tabu[tabu_old] = tabu_tenure
                            improved = True
                            break
                        else:
                            # revert
                            coloring[v] = old_color
                if improved:
                    break
                # Try Kempe chains for each color c < max_color
                if not improved:
                    for c in range(max_color):
                        if c in neighbor_colors:
                            continue  # already tried direct
                        # Build (max_color, c)-Kempe chain containing v
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if coloring[node] == max_color or coloring[node] == c:
                                component.add(node)
                                for u in neighbors[node]:
                                    if u not in visited and (coloring[u] == max_color or coloring[u] == c):
                                        stack.append(u)
                        # Check if we can swap: no neighbor of v in component has color c? Actually, swapping is safe if
                        # after swap, no adjacent same color. Since we only swap two colors, it's always valid.
                        # But we want to free color max_color for v? Actually, after swap, v gets color c.
                        # We already know v is not adjacent to any c (from neighbor_colors), so safe.
                        # Perform swap
                        for node in component:
                            if coloring[node] == max_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = max_color
                        if is_valid(coloring):
                            # Update tabu
                            tabu[(v, c)] = tabu_tenure
                            tabu[(v, max_color)] = tabu_tenure
                            improved = True
                            break
                        else:
                            # revert swap
                            for node in component:
                                if coloring[node] == max_color:
                                    coloring[node] = c
                                elif coloring[node] == c:
                                    coloring[node] = max_color
            # Update tabu tenures
            to_delete = []
            for key in tabu:
                tabu[key] -= 1
                if tabu[key] <= 0:
                    to_delete.append(key)
            for key in to_delete:
                del tabu[key]
        # Normalize colors to be consecutive
        return normalize(coloring)

    # Apply Kempe reduction to best candidate
    try:
        improved = kempe_reduce(best_coloring[:])  # work on a copy
        if is_valid(improved):
            improved_k = count_colors(improved)
            if improved_k < best_k:
                best_coloring = improved
                best_k = improved_k
    except Exception:
        pass

    # Final validation and normalization
    if not is_valid(best_coloring):
        # last resort: greedy
        best_coloring = greedy_color(list(range(n)))
    best_coloring = normalize(best_coloring)

    return best_coloring

