                    if not (used & (1 << c)):
                        if c < coloring[v]:
                            coloring[v] = c
                            improved = True
                        break
        return coloring

    best_coloring = None
    best_k = float('inf')

    # Multiple random greedy passes
    for _ in range(20):  # 20 passes for good coverage within time
