            order.append(v)
            remaining.remove(v)
            # update neighbors
            for nb in neighbors(v):
                if nb in remaining:
                    d = deg[nb]
                    if d > 0:
                        buckets[d].remove(nb)
                        deg[nb] -= 1
                        buckets[deg[nb]].append(nb)
                    else:
