                best_deg_in_U = float('inf')
                for u in U:
                    score = sum(1 for nb in adj_list[u] if nb in W)
                    deg_in_U = sum(1 for nb in adj_list[u] if nb in U)
                    if score > best_score or (score == best_score and deg_in_U < best_deg_in_U):
                        best_score = score
                        best_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                uncolored.remove(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1

        return normalize(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[v]) for v in range(n)]
        # bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # pointer to current min degree
        ptr = 0
        # current degrees (will be updated)
        curr_deg = degrees[:]
        while remaining:
            # find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # remove a vertex of min degree
            while buckets[ptr] and (buckets[ptr][-1] not in remaining):
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    # remove nb from its current bucket
                    d = curr_deg[nb]
                    if nb in buckets[d]:
                        buckets[d].remove(nb)
                    curr_deg[nb] -= 1
                    d2 = curr_deg[nb]
                    buckets[d2].append(nb)
        # color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(order):
            forbidden = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    forbidden |= (1 << coloring[nb])
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # try to eliminate color classes from highest downward
        changed = True
        while changed:
            changed = False
            k = num_colors(coloring)
            if k <= 1:
                break
            target_color = k - 1
            # vertices with target color
            targets = [v for v in range(n) if coloring[v] == target_color]
            if not targets:
                # already missing, compact
                mapping = {}
                next_c = 0
                for v in range(n):
                    c = coloring[v]
                    if c not in mapping:
                        mapping[c] = next_c
                        next_c += 1
                    coloring[v] = mapping[c]
                continue
            # try to recolor each target vertex
            for v in targets:
                # try direct reassignment to a lower color
                forbidden = 0
                for nb in adj_list[v]:
                    if coloring[nb] != -1:
                        forbidden |= (1 << coloring[nb])
                for c in range(target_color):
                    if not (forbidden & (1 << c)):
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c after potential direct reassignment, skip
                    if coloring[v] == c:
                        changed = True
                        break
                    # find the Kempe chain component of v in colors {c, target_color}
                    # if the component does not contain any vertex of color c that is adjacent to v,
                    # we can swap
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for nb in adj_list[x]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # check if any neighbor of v in the component has color c (would cause conflict if swapped)
                    conflict = False
                    for x in component:
                        for nb in adj_list[x]:
                            if coloring[nb] == c and nb in component:
                                # edge inside component, swapping would keep validity
                                pass
                            elif coloring[nb] == c and nb not in component:
                                # if neighbor of component has color c, swapping would cause two c's adjacent
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # perform swap: c <-> target_color in component
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target_color
                            elif coloring[x] == target_color:
                                coloring[x] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # compact colors
                mapping = {}
                next_c = 0
                for v in range(n):
                    c = coloring[v]
                    if c not in mapping:
                        mapping[c] = next_c
                        next_c += 1
                    coloring[v] = mapping[c]
        return coloring

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            coloring = func()
            if not is_valid(coloring):
                continue
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring[:]
        except Exception:
            continue

    # fallback: greedy by degree
    if best_coloring is None:
        ordering = list(range(n))
        ordering.sort(key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in ordering:
            forbidden = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    forbidden |= (1 << coloring[nb])
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    # apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)

    # final validation and normalization
    if not is_valid(best_coloring):
        # last resort: greedy
        coloring = [-1] * n
        for v in range(n):
            forbidden = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    forbidden |= (1 << coloring[nb])
            c = 0
            while forbidden & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    return best_coloring

