import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build neighbor bitmasks and adjacency lists
    bit_adj = [0] * n
    neighbors = [set() for _ in range(n)]
    for u in range(n):
        if is_matrix:
            for v in range(n):
                if adj[u][v]:
                    bit_adj[u] |= (1 << v)
                    neighbors[u].add(v)
        else:
            for v in adj[u]:
                if v < n:  # safety
                    bit_adj[u] |= (1 << v)
                    neighbors[u].add(v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert to consecutive colors
    def normalize(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    best_coloring = None
    best_k = float('inf')
    start_time = time.time()

    # --- DSATUR ---
    if time.time() - start_time < 0.04:
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([y for y in neighbors[x] if y in uncolored])))
            # compute used colors from neighbors
            used = 0
            for y in neighbors[v]:
                if color[y] != -1:
                    used |= (1 << color[y])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for y in neighbors[v]:
                if y in uncolored:
                    sat[y] = len({color[z] for z in neighbors[y] if color[z] != -1})
        if is_valid(color):
            k = count_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]

    # --- RLF ---
    if time.time() - start_time < 0.04:
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # pick vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S = {v}
            # U: vertices not adjacent to S
            U = {y for y in uncolored if y != v and not any(z in S for z in neighbors[y])}
            # W: vertices adjacent to S
            W = {y for y in uncolored if y != v and any(z in S for z in neighbors[y])}
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (len([z for z in neighbors[x] if z in W]), -len([z for z in neighbors[x] if z in U])))
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for y in list(U):
                    if y in neighbors[u]:
                        U.remove(y)
                        W.add(y)
            for vertex in S:
                color[vertex] = c
            uncolored -= S
            c += 1
        if is_valid(color):
            k = count_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]

    # --- Smallest-Last (Degeneracy) Ordering ---
    if time.time() - start_time < 0.04:
        # compute smallest-last ordering
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[v] & remaining) for v in range(n)]
        while remaining:
            v = min(remaining, key=lambda x: degrees[x])
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    degrees[u] -= 1
        # color in reverse order
        color = greedy_color(order[::-1])
        if is_valid(color):
            k = count_colors(color)
            if k < best_k:
                best_k = k
                best_coloring = color[:]

    # If no valid coloring found (should not happen), fallback to greedy by index
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_coloring = normalize(best_coloring)

    # Ensure valid and normalized
    best_coloring = normalize(best_coloring)
    if not is_valid(best_coloring):
        # last resort: greedy by index with normalization
        best_coloring = greedy_color(list(range(n)))
        best_coloring = normalize(best_coloring)

    return best_coloring

