        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Helper: count colors
    def count_colors(color):
        if not color:
            return 0
        return max(color) + 1
    # Helper: validate coloring
    def is_valid(color):
        for u in range(n):
            for v in neighbors[u]:
                if color[u] == color[v]:
                    return False
        return True
    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree: bitmask of neighbor colors
        uncolored = set(range(n))
