        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current min non-empty bucket
        min_deg = 0
        while remaining:
            # Find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degree[u]
                    # remove u from bucket d
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    dnew = degree[u]
                    if dnew >= 0:
                        if dnew >= len(buckets):
                            buckets.extend([[] for _ in range(dnew - len(buckets) + 1)])
                        buckets[dnew].append(u)
                    # update min_deg if needed
                    if dnew < min_deg:
                        min_deg = dnew
        # Reverse order for coloring
        order.reverse()
        return greedy_color(order)
    # Kempe chain swap for color elimination
    def kempe_swap(color, target_color, src_color):
        # Try to remove target_color by recoloring its vertices using Kempe chains with src_color
        # Returns new color if successful, else None
        # Build sets of vertices per color
        color_classes = [[] for _ in range(max(color) + 1 if color else 0)]
        for v, c in enumerate(color):
            if c < len(color_classes):
                color_classes[c].append(v)
        # For each vertex v of target_color
        for v in color_classes[target_color]:
            # Try direct reassignment to src_color
            conflict = False
            for u in neighbors[v]:
                if color[u] == src_color:
                    conflict = True
                    break
            if not conflict:
                # Move v to src_color
                color[v] = src_color
                # If this was the last vertex of target_color, we can eliminate it
                if all(color[x] != target_color for x in color_classes[target_color]):
                    return True
                else:
                    # Revert and try Kempe
                    color[v] = target_color
            # Kempe chain: consider subgraph induced by target_color and src_color
            # Find connected component of v in that subgraph
            stack = [v]
            visited = set()
            comp = set()
            while stack:
                node = stack.pop()
                if node in visited:
                    continue
                visited.add(node)
                if color[node] == target_color or color[node] == src_color:
                    comp.add(node)
                    for u in neighbors[node]:
                        if color[u] == target_color or color[u] == src_color:
                            if u not in visited:
                                stack.append(u)
            # Check if swapping colors in comp would cause conflict
            # For each node in comp, after swap, check neighbors
            valid = True
            for node in comp:
                new_color = src_color if color[node] == target_color else target_color
                for u in neighbors[node]:
                    if color[u] == new_color and u not in comp:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                # Perform swap
                for node in comp:
                    if color[node] == target_color:
                        color[node] = src_color
                    else:
                        color[node] = target_color
                # Check if target_color eliminated
                if all(color[x] != target_color for x in color_classes[target_color]):
                    return True
                else:
                    # Revert swap
                    for node in comp:
                        if color[node] == src_color:
                            color[node] = target_color
                        else:
                            color[node] = src_color
