            candidates.append(list(range(n)))
    # Select best candidate (fewest colors)
    best = min(candidates, key=count_colors)
    # Ensure consecutive colors
    # Remap colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best[i] = unique_colors[c]
    # Optional: Kempe chain reduction to try to lower chromatic number
    # Try to eliminate highest color classes iteratively
    changed = True
    while changed and max(best) > 0:
        changed = False
        k = max(best) + 1
        # Try from highest color down to 1
        for target_color in range(k-1, 0, -1):
            # Build color classes
            color_classes = [[] for _ in range(k)]
            for v, c in enumerate(best):
                if c < k:
                    color_classes[c].append(v)
            if not color_classes[target_color]:
                continue
            # Try to eliminate target_color by moving its vertices to lower colors
            made_progress = False
            for src_color in range(target_color):
                if kempe_swap(best, target_color, src_color):
                    made_progress = True
                    changed = True
                    break  # restart after change
            if made_progress:
                break
        if changed:
            # Remap colors again
            unique_colors = {}
            next_color = 0
            for i in range(n):
                c = best[i]
                if c not in unique_colors:
                    unique_colors[c] = next_color
                    next_color += 1
                best[i] = unique_colors[c]
    # Final validation (should hold)
    assert is_valid(best), "Invalid coloring produced"
    return best

