                    u_deg = sum(1 for w in adj_list[u] if w in U)
                    if w_deg > best_w_deg:
                        best_w_deg = w_deg
                        best_u_deg = u_deg
                        best_u = u
                    elif w_deg == best_w_deg:
                        if u_deg < best_u_deg:
                            best_u_deg = u_deg
                            best_u = u
                        elif u_deg == best_u_deg and random.random() < 0.5:
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
