            buckets[deg[i]].append(i)
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            for u in adj_list[v]:
