        best_color = greedy_color(list(range(n)))
        best_k = max(best_color) + 1 if n > 0 else 0

    # Kempe chain color reduction
    def kempe_reduction(color):
        # Ensure colors are compact
        def compact(col):
            mapping = {}
            next_c = 0
            for v in range(n):
                c = col[v]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                col[v] = mapping[c]
            return col

        color = compact(color[:])
        improved = True
        while improved:
            improved = False
            # Find smallest color class
            classes = [[] for _ in range(best_k)]
            for v in range(n):
                classes[color[v]].append(v)
            # Try to eliminate color classes from highest to lowest
            for c in range(best_k - 1, -1, -1):
                if not classes[c]:
                    continue
                # Try to recolor each vertex in class c
                removed = True
                while removed and classes[c]:
                    removed = False
                    v = classes[c].pop()
                    # Try direct reassignment to a lower color
                    for c2 in range(c):
                        conflict = False
                        for u in adj_list[v]:
                            if color[u] == c2:
                                conflict = True
                                break
                        if not conflict:
                            color[v] = c2
                            classes[c2].append(v)
                            removed = True
                            improved = True
                            break
                    if removed:
                        continue
                    # Try Kempe chain swap with each lower color
                    for c2 in range(c):
                        # BFS to find Kempe chain component of (c, c2) containing v
                        from collections import deque
                        comp = set()
                        q = deque([v])
                        comp.add(v)
                        while q:
                            node = q.popleft()
                            for u in adj_list[node]:
                                if color[u] == c2 and u not in comp:
                                    comp.add(u)
                                    q.append(u)
                                elif color[u] == c and u not in comp:
                                    comp.add(u)
                                    q.append(u)
                        # Check if swapping comp frees color c2 for v (i.e., no neighbor of v in comp has color c2 after swap?)
                        # Actually, after swap, v will have color c2. We need that no neighbor of v has color c2 after swap.
                        # But neighbors of v in comp: if they had color c, they become c2 -> conflict if adjacent to v?
                        # Instead, we check: after swap, will v have any neighbor with color c2?
                        # Currently, v has color c. Its neighbors with color c2 are outside the comp (since comp only includes c and c2, and if neighbor had c2, it would be in comp).
                        # After swap, v becomes c2. Its neighbors that were c become c2 -> conflict.
                        # So we need that v has no neighbor in the comp that currently has color c (because they will become c2).
                        # Actually, standard Kempe: we can swap if the component does not contain a neighbor of v with color c2? 
                        # Let's use the condition: after swap, v's new color (c2) must not conflict with any neighbor.
                        # Currently, neighbors of v with color c2 are not in comp (because if they were, they'd be same color c2 and adjacent -> but we only traverse same two colors).
                        # Actually, the component is induced by colors c and c2. So neighbors of v that are color c2 are in the component.
                        # After swap, v becomes c2, and its neighbors that were c become c2 -> so if v has any neighbor in the component that is color c, then after swap they become c2 -> conflict.
                        # Therefore, we can swap only if v has no neighbor in the component that is color c (other than itself?).
                        # But v is in the component and has color c. We exclude v.
                        has_c_neighbor = False
                        for u in adj_list[v]:
                            if u != v and color[u] == c and u in comp:
                                has_c_neighbor = True
                                break
                        if not has_c_neighbor:
                            # Perform swap
                            for node in comp:
                                if color[node] == c:
                                    color[node] = c2
                                else:
                                    color[node] = c
                                # Update classes
                                if color[node] == c2:
                                    classes[c2].append(node)
                                elif color[node] == c:
                                    classes[c].append(node)
                            # Rebuild classes from scratch for simplicity (since n small)
                            classes = [[] for _ in range(best_k)]
                            for vtx in range(n):
                                classes[color[vtx]].append(vtx)
                            removed = True
                            improved = True
                            break
                    if removed:
                        # Rebuild classes after successful Kempe swap
                        classes = [[] for _ in range(best_k)]
                        for vtx in range(n):
                            classes[color[vtx]].append(vtx)
                        break
                # If we exited while loop and class c is empty, we can reduce color count
                if not classes[c]:
                    # Shift down all higher colors
                    for vtx in range(n):
                        if color[vtx] > c:
                            color[vtx] -= 1
                    best_k -= 1
                    # Rebuild classes
                    classes = [[] for _ in range(best_k)]
                    for vtx in range(n):
                        classes[color[vtx]].append(vtx)
                    improved = True
                    break
        return color

    # Apply Kempe reduction
    best_color = kempe_reduction(best_color)
    # Final validation and compaction
    def compact_final(col):
        if not col:
            return col
        mapping = {}
        next_c = 0
        for v in range(n):
            c = col[v]
            if c not in mapping:
                mapping[c] = next_c
                next_c += 1
            col[v] = mapping[c]
        return col

    best_color = compact_final(best_color)
    # One last validation (should be valid by construction)
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best_color[u] == best_color[v]:
                # Fallback to greedy on natural order if invalid
                return greedy_color(list(range(n)))
    return best_color

