def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Convert to adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR heuristic
    def dsatur():
        colors = [-1] * n
        # Precompute neighbor counts for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))
        # Track saturation: number of distinct colors in neighbors
        saturation = [0] * n
        neighbor_colors = [set() for _ in range(n)]

        for _ in range(n):
            # Select vertex with max saturation, then max degree, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)
            if max_sat == -1:  # all uncolored, pick max degree
                v = max(uncolored, key=lambda x: degrees[x])
            else:
                # break tie by degree in uncolored subgraph
                v = max(candidates, key=lambda x: sum(1 for nb in adj_list[x] if nb in uncolored))
            # Assign smallest available color
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    if c not in neighbor_colors[nb]:
                        neighbor_colors[nb].add(c)
                        saturation[nb] += 1
        return compact_colors(colors)

    # RLF heuristic
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0
        # Precompute degrees in full graph for initial selection
        degrees = [len(adj_list[i]) for i in range(n)]

        while uncolored:
            # Build independent set for color_idx
            S = set()
            # Step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: sum(1 for nb in adj_list[x] if nb in uncolored))
            S.add(v)
            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = uncolored - S
            W = set()
            for u in list(U):
                if any(nb in S for nb in adj_list[u]):
                    W.add(u)
                    U.remove(u)
            # While U not empty, add vertices maximizing |N(u) ∩ W|
            while U:
                best_u = None
                best_score = -1
                best_deg_in_U = float('inf')
                for u in U:
                    # score = |N(u) ∩ W|
                    score = sum(1 for nb in adj_list[u] if nb in W)
                    deg_in_U = sum(1 for nb in adj_list[u] if nb in U)
                    if score > best_score or (score == best_score and deg_in_U < best_deg_in_U):
                        best_score = score
                        best_deg_in_U = deg_in_U
                        best_u = u
                if best_u is None:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        W.add(nb)
                        U.remove(nb)
            # Assign color_idx to all in S
            for v in S:
                colors[v] = color_idx
            uncolored -= S
            color_idx += 1
        return compact_colors(colors)

    # Smallest-Last (Matula & Beck) greedy
    def smallest_last():
        # Core decomposition to get ordering
        degrees = [len(adj_list[i]) for i in range(n)]
        # Bin vertices by degree
        max_deg = max(degrees) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        pos = [0] * n
        for v in range(n):
            d = degrees[v]
            bins[d].append(v)
            pos[v] = len(bins[d]) - 1
        # current degree and location
        curr_deg = degrees[:]
        # sequence of removal (smallest last)
        seq = []
        # For efficiency, maintain pointer to non-empty bin
        ptr = 0
        for _ in range(n):
            # find non-empty bin
            while ptr <= max_deg and not bins[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = bins[ptr].pop()
            pos[v] = -1  # removed
            seq.append(v)
            # decrease degree of neighbors
            for nb in adj_list[v]:
                if pos[nb] >= 0:  # nb not removed
                    d = curr_deg[nb]
                    # remove nb from bin d
                    bins[d].pop(pos[nb])
                    if pos[nb] < len(bins[d]):
                        # swap with last
                        last_v = bins[d][-1]
                        bins[d][pos[nb]] = last_v
                        pos[last_v] = pos[nb]
                    curr_deg[nb] -= 1
                    d_new = curr_deg[nb]
                    bins[d_new].append(nb)
                    pos[nb] = len(bins[d_new]) - 1
        # Color in reverse removal order
        colors = [-1] * n
        for v in reversed(seq):
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain elimination to reduce colors
    def kempe_reduce(colors):
        if not is_valid(colors):
            return colors  # should not happen if input valid
        k = max(colors) + 1 if n > 0 else 0
        # Try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                k -= 1
                changed = True
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                used_by_neighbors = set()
                for nb in adj_list[v]:
                    if colors[nb] < target_color:
                        used_by_neighbors.add(colors[nb])
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if c not in used_by_neighbors:
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    if c in used_by_neighbors:
                        continue  # skip if neighbor already has color c (would cause conflict if swapped)
                    # Find Kempe chain of colors (target_color, c) containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if colors[node] == target_color or colors[node] == c:
                            component.add(node)
                            for nb in adj_list[node]:
                                if colors[nb] == target_color or colors[nb] == c:
                                    if nb not in visited:
                                        stack.append(nb)
                    # Check if any neighbor of v with color c is in this component
                    has_c_neighbor_in_comp = False
                    for nb in adj_list[v]:
                        if colors[nb] == c and nb in component:
                            has_c_neighbor_in_comp = True
                            break
                    if not has_c_neighbor_in_comp:
                        # Swap colors in component
                        for node in component:
                            if colors[node] == target_color:
                                colors[node] = c
                            else:
                                colors[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # compact colors after changes
                colors = compact_colors(colors)
                k = max(colors) + 1 if n > 0 else 0
            else:
                # Could not eliminate target color, try next lower
                k -= 1
        return colors

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = set()
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        candidates.append(compact_colors(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda c: max(c) + 1 if n > 0 else 0)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid(best):
        # last resort: greedy
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = set()
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        best = compact_colors(colors)
    return best

