                    deg_u = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_u += 1
                    if w_nb > best_W_neighbors or (w_nb == best_W_neighbors and deg_u < best_deg_U) or (w_nb == best_W_neighbors and deg_u == best_deg_U and random.random() < 0.5):
                        best_W_neighbors = w_nb
                        best_deg_U = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
            # Next iteration: uncolored becomes W
            uncolored = W
        return normalize_colors(colors)
    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering via min-degree removal
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # We'll maintain current degrees in the remaining subgraph
        curr_degree = degree[:]
        while remaining:
            # Find vertex with minimum current degree
            v = min(remaining, key=lambda x: curr_degree[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    curr_degree[nb] -= 1
        # Color in reverse order using greedy
        colors = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for nb in adj_list[v]:
                c = colors[nb]
                if c != -1:
                    neighbor_colors |= (1 << c)
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        return normalize_colors(colors)
    # Kempe chain color reduction
    def kempe_reduce(colors):
        # Make a copy to work on
        cur_colors = colors[:]
        changed = True
        while changed:
            changed = False
            # Determine current number of colors
            k = num_colors(cur_colors)
            if k <= 1:
                break
            # Try to eliminate the last color (k-1)
            target_color = k - 1
            # Vertices with target color
            target_vertices = [v for v in range(n) if cur_colors[v] == target_color]
            # Try to reassign each target vertex to a lower color
            for v in target_vertices:
                # Find colors used by neighbors
                neighbor_colors = set()
                for nb in adj_list[v]:
                    neighbor_colors.add(cur_colors[nb])
                # Try direct reassignment to any color < target_color
                for c in range(target_color):
                    if c not in neighbor_colors:
                        cur_colors[v] = c
                        changed = True
                        break
                if changed:
                    # After change, break to recompute target set
                    break
                # Try Kempe chains with each color c < target_color
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue  # Kempe chain only useful if color c is present in neighborhood? Actually we need to check if swapping can free c
                    # Build the Kempe chain component for colors (target_color, c) containing v
                    # We'll do BFS/DFS over vertices colored target_color or c
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if cur_colors[node] == target_color or cur_colors[node] == c:
                            component.add(node)
                            for nb in adj_list[node]:
                                if cur_colors[nb] == target_color or cur_colors[nb] == c:
                                    if nb not in visited:
                                        stack.append(nb)
                    # Check if any neighbor of v in the component has color c? Actually we need to see if swapping would cause conflict
                    # After swap, v would become c. We need to ensure no neighbor of v is c after swap.
                    # Neighbors of v that are in component and have color c will become target_color.
                    # So we need that no neighbor of v is in the component and has color c? Actually if neighbor is in component and has color c, after swap it becomes target_color, which is not c, so okay.
                    # The only potential issue is if there is a neighbor of v that is not in the component but has color c? That neighbor would stay c, and v becomes c -> conflict.
                    # So we need that no neighbor of v has color c and is not in the component.
                    # Equivalent: all neighbors of v that have color c must be in the component.
                    conflict = False
                    for nb in adj_list[v]:
                        if cur_colors[nb] == c and nb not in component:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: target_color <-> c in the component
                        for node in component:
                            if cur_colors[node] == target_color:
                                cur_colors[node] = c
                            elif cur_colors[node] == c:
                                cur_colors[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            # If we eliminated the target color (no vertex has target_color), we can compact colors
            if not changed:
                # Check if target_color is still used
                if any(cur_colors[v] == target_color for v in range(n)):
                    # Could not eliminate, break
                    break
            else:
                # After a change, we may have gaps; normalize to consecutive colors
                cur_colors = normalize_colors(cur_colors)
        return cur_colors
    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except Exception:
        pass
    # If no candidates (should not happen), fallback to trivial greedy
    if not candidates:
        colors = [0] * n
        for i in range(1, n):
            used = set()
            for nb in adj_list[i]:
                used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[i] = c
        candidates.append(normalize_colors(colors))
    # Apply Kempe reduction to each candidate and select best
    best_colors = None
    best_k = float('inf')
    for col in candidates:
        reduced = kempe_reduce(col)
        k = num_colors(reduced)
        if k < best_k:
            best_k = k
            best_colors = reduced
    # Final validation (should be valid)
    if not is_valid_coloring(best_colors):
        # Fallback to DSATUR if something went wrong
        best_colors = dsatur()
    return best_colors

