def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Convert to adjacency list and bitmask
    if is_matrix:
        adj_list = []
        bit_adj = [0] * n
        for i in range(n):
            row = adj[i]
            neighbors = []
            bits = 0
            for j, val in enumerate(row):
                if val == 1:
                    neighbors.append(j)
                    bits |= (1 << j)
            adj_list.append(neighbors)
            bit_adj[i] = bits
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            bits = 0
            for nb in adj_list[i]:
                bits |= (1 << nb)
            bit_adj[i] = bits

    # Helper: greedy coloring given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for nb in adj_list[v]:
                c = color[nb]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(color):
        if not color:
            return 0
        return max(color) + 1

    # Helper: validate coloring
    def is_valid(color):
        for u in range(n):
            for v in adj_list[u]:
                if color[u] == color[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(color):
        mapping = {}
        next_color = 0
        for c in color:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in color]

    # DSATUR
    def dsatur():
        uncolored = set(range(n))
        color = [-1] * n
        sat = [0] * n
        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1') > max_deg):
                    max_sat = sat[u]
                    max_deg = bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1')
                    v = u
            # assign smallest available color
            used = 0
            for nb in adj_list[v]:
                c = color[nb]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    sat[nb] = bin(bit_adj[nb] & sum((1 << w) for w in uncolored if color[w] != -1)).count('1')
        return compact_colors(color)

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda u: bin(bit_adj[u] & sum((1 << w) for w in uncolored)).count('1'))
            S = {v}
            # U: vertices not adjacent to any in S
            U = uncolored - {v} - set()
            for nb in adj_list[v]:
                if nb in U:
                    U.remove(nb)
            W = set()
            # expand independent set S
            while U:
                # select u in U with max neighbors in W
                u_star = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = bin(bit_adj[u] & sum((1 << w) for w in W)).count('1')
                    deg_u = bin(bit_adj[u] & sum((1 << w) for w in U)).count('1')
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u):
                        max_nw = nw
                        min_deg_u = deg_u
                        u_star = u
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for nb in adj_list[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return compact_colors(color)

    # Smallest-Last ordering
    def smallest_last():
        # compute degeneracy ordering
        deg = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current min degree
        min_deg = 0
        for _ in range(n):
            # find non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    d = deg[nb]
                    buckets[d].remove(nb)
                    deg[nb] -= 1
                    buckets[deg[nb]].append(nb)
        # color in reverse order
        color = greedy_color(order[::-1])
        return compact_colors(color)

    # Kempe chain elimination
    def kempe_reduce(color):
        if not is_valid(color):
            return color
        k = num_colors(color)
        # try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            vertices = [v for v in range(n) if color[v] == target_color]
            if not vertices:
                continue
            # try to recolor each vertex in this class
            changed = True
            while changed and vertices:
                changed = False
                v = vertices.pop()
                # try direct reassignment to a lower color
                used = 0
                for nb in adj_list[v]:
                    c = color[nb]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target_color):
                    if not (used & (1 << c)):
                        color[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # try Kempe chains with each lower color
                for c in range(target_color):
                    if used & (1 << c):
                        continue
                    # find Kempe chain of (target_color, c) containing v
                    # BFS to get component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for nb in adj_list[u]:
                            if not visited[nb] and (color[nb] == target_color or color[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # check if swapping frees color c for v (i.e., no neighbor of v has color c after swap)
                    # after swap, v would get color c, so we need that no neighbor of v has color c in the current coloring
                    # but note: in the component, target_color <-> c are swapped
                    # so for a neighbor of v:
                    #   if it is in the component and had color target_color, after swap it becomes c -> conflict
                    #   if it is in the component and had color c, after swap it becomes target_color -> no conflict (since v becomes c)
                    #   if it is not in the component, color unchanged
                    # Therefore, v can take color c after swap iff no neighbor of v is in the component and had color target_color
                    conflict = False
                    for nb in adj_list[v]:
                        if visited[nb] and color[nb] == target_color:
                            conflict = True
                            break
                    if not conflict:
                        # perform swap
                        for u in component:
                            if color[u] == target_color:
                                color[u] = c
                            elif color[u] == c:
                                color[u] = target_color
                        color[v] = c  # v was target_color, now becomes c
                        changed = True
                        break
                if changed:
                    # restart the while loop for this target_color since we changed coloring
                    vertices = [v for v in range(n) if color[v] == target_color]
                    break
            # after trying to eliminate target_color, if any vertex still has it, break and move to next lower target?
            # Actually, we want to eliminate the highest color class first, but if we can't eliminate it, we try lower ones?
            # Standard approach: try to eliminate the last color (k-1), if success, reduce k and repeat.
            # Here we are iterating from high to low, but we break after first success? Let's change strategy.
            # Instead, we will attempt to eliminate the highest color class repeatedly until no more progress.
        # Now, try to eliminate the highest color class until no more progress
        while True:
            k = num_colors(color)
            if k <= 1:
                break
            target_color = k - 1
            vertices = [v for v in range(n) if color[v] == target_color]
            if not vertices:
                # should not happen, but safety
                break
            made_progress = False
            for v in vertices[:]:  # copy list
                used = 0
                for nb in adj_list[v]:
                    c = color[nb]
                    if c != -1:
                        used |= (1 << c)
                # try direct reassignment
                for c in range(target_color):
                    if not (used & (1 << c)):
                        color[v] = c
                        made_progress = True
                        break
                if made_progress:
                    continue
                # try Kempe chains
                for c in range(target_color):
                    if used & (1 << c):
                        continue
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for nb in adj_list[u]:
                            if not visited[nb] and (color[nb] == target_color or color[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    conflict = False
                    for nb in adj_list[v]:
                        if visited[nb] and color[nb] == target_color:
                            conflict = True
                            break
                    if not conflict:
                        for u in component:
                            if color[u] == target_color:
                                color[u] = c
                            elif color[u] == c:
                                color[u] = target_color
                        color[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                break
        return compact_colors(color)

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        col1 = dsatur()
        if is_valid(col1):
            candidates.append(col1)
    except:
        pass
    # RLF
    try:
        col2 = rlf()
        if is_valid(col2):
            candidates.append(col2)
    except:
        pass
    # Smallest-Last
    try:
        col3 = smallest_last()
        if is_valid(col3):
            candidates.append(col3)
    except:
        pass
    # If no candidates, fallback to greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        col = greedy_color(order)
        candidates.append(compact_colors(col))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compact
    if not is_valid(best):
        # last resort: greedy by degree
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        best = greedy_color(order)
    return compact_colors(best)

