    for col in candidates:
        if not is_valid_coloring(col):
            continue
        # renormalize to ensure consecutive
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        norm = [mapping[c] for c in col]
        k = max(norm) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best = norm
        elif k == best_k and best is not None:
            # tie-break by lexicographical order for determinism
            if norm < best:
                best = norm

    # fallback: if none valid (should not happen), use DSATUR
    if best is None:
        best = dsatur()
        mapping = {}
        next_color = 0
        for c in best:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        best = [mapping[c] for c in best]

    # final Kempe reduction
    best = kempe_reduce(best)

    # final validation and renormalize
    if not is_valid_coloring(best):
        # last resort: greedy Welsh-Powell
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
        colors = [-1] * n
        for u in order:
            used = set()
            for w in adj_list[u]:
                if colors[w] != -1:
                    used.add(colors[w])
            c = 0
            while c in used:
                c += 1
            colors[u] = c
        best = colors

    # ensure consecutive colors
    mapping = {}
    next_color = 0
    for c in best:
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
    best = [mapping[c] for c in best]

    return best

