    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                neighbors[u].append(v)
                bit_adj[u] |= (1 << v)

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bitmask for fast saturation update
        neighbor_colors = [0] * n
        # uncolored set
        uncolored = set(range(n))

        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v]
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = len([u for u in neighbors[v] if u in uncolored])
                elif sat == best_sat:
                    deg = len([u for u in neighbors[v] if u in uncolored])
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
                    elif deg == best_deg:
                        if random.random() < 0.5:
                            best_v = v
            v = best_v
            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update saturation and neighbor colors for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
