        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - S
            W = set()
            for u in list(U):
                if any(w in neighbors[u] for w in S):
                    W.add(u)
                    U.remove(u)
            # while U not empty
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = len([w for w in neighbors[u] if w in W])
                    deg_u = len([x for x in neighbors[u] if x in U])
                    if w_neighbors > best_w_neighbors:
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                    elif w_neighbors == best_w_neighbors:
                        if deg_u < best_deg_u:
                            best_deg_u = deg_u
                            best_u = u
                        elif deg_u == best_deg_u and random.random() < 0.5:
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        W.add(w)
                        U.remove(w)
            # assign color to S
            for v in S:
                colors[v] = color
            uncolored -= S
            color += 1
        return compact_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        degree = [len(neighbors[i]) for i in range(n)]
        # bin sort by degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            bins[degree[v]].append(v)
        # vertex status: 0=unremoved, 1=removed
        removed = [False] * n
        order = []
        # current min degree
        d = 0
        for _ in range(n):
            # find next non-empty bin
            while d <= max_deg and not bins[d]:
                d += 1
            if d > max_deg:
                break
            v = bins[d].pop()
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    if degree[u] > d:
                        degree[u] -= 1
                        bins[degree[u]].append(u)
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(colors, a, b, v):
        stack = [v]
        visited = set()
        component = []
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if colors[u] == a or colors[u] == b:
                component.append(u)
                for w in neighbors[u]:
                    if w not in visited and (colors[w] == a or colors[w] == b):
                        stack.append(w)
        # swap colors in component
        for u in component:
            if colors[u] == a:
                colors[u] = b
            else:
                colors[u] = a
        return colors

    # Attempt to eliminate a color class via Kempe chains
    def reduce_colors(colors):
