        v = max(range(n), key=lambda x: deg[x])
        coloring[v] = 0
        # update neighbors of v
        for u in neighbors[v]:
            neighbor_colors[u] |= (1 << 0)
            sat[u] = 1

        for _ in range(1, n):
            # select uncolored vertex with max sat, tie-break by degree, then index
            candidates = [-1]
            max_sat = -1
            for u in range(n):
                if coloring[u] == -1:
                    if sat[u] > max_sat or (sat[u] == max_sat and deg[u] > deg[candidates[0]]):
                        max_sat = sat[u]
                        candidates = [u]
                    elif sat[u] == max_sat and deg[u] == deg[candidates[0]]:
