        color = 0
        while uncolored:
            # independent set for this color
            S = []
            # choose vertex with max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
                S.append(v)
                uncolored.remove(v)
                # partition: U = not adj to S, W = adj to S
                U = {u for u in uncolored if not any(w in neighbors[u] for w in S)}
                W = uncolored - U
                while U:
                    # select u in U with max neighbors in W
                    u_star = -1
                    max_w_neighbors = -1
                    for u in U:
                        w_n = sum(1 for w in neighbors[u] if w in W)
                        if w_n > max_w_neighbors or (w_n == max_w_neighbors and len([x for x in neighbors[u] if x in U]) < len([x for x in neighbors[u_star] if x in U]) if u_star != -1 else True):
                            max_w_neighbors = w_n
                            u_star = u
                    if u_star == -1:
                        u_star = next(iter(U))
                    S.append(u_star)
                    U.remove(u_star)
                    # move neighbors of u_star in U to W
                    for nb in neighbors[u_star]:
                        if nb in U:
                            U.remove(nb)
                            W.add(nb)
            for v in S:
                coloring[v] = color
            color += 1
        return coloring

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # pointer to current min degree
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    if d < len(buckets):
                        buckets[d].append(u)
                    if degree[u] < ptr:
                        ptr = degree[u]
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

