    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                k -= 1
                improved = True
                continue
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to lower color
                used = 0
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        used |= (1 << coloring[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c from direct reassignment above, skip (but we broke)
                    # BFS for (c, target_color) Kempe chain starting at v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # check if any neighbor of the component has color c (would cause conflict if swapped)
                    has_c_neighbor = False
                    for x in component:
                        for y in neighbors[x]:
                            if coloring[y] == c and y not in component:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            break
                    if not has_c_neighbor:
                        # swap colors c and target_color in component
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target_color
                            elif coloring[x] == target_color:
                                coloring[x] = c
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # compact colors
                coloring = compact_colors(coloring)
                k = num_colors(coloring)
        return coloring

    # Run all heuristics
    start_time = time.time()
    best_coloring = None
    best_k = float('inf')

    # DSATUR
    c1 = dsatur()
    if time.time() - start_time < 0.05:  # 50ms budget
        c1 = compact_colors(c1)
        if is_valid(c1):
            k1 = num_colors(c1)
            if k1 < best_k:
                best_k = k1
                best_coloring = c1[:]

    # RLF
    if time.time() - start_time < 0.05:
        c2 = rlf()
        c2 = compact_colors(c2)
        if is_valid(c2):
            k2 = num_colors(c2)
            if k2 < best_k:
                best_k = k2
                best_coloring = c2[:]

    # Smallest-Last
    if time.time() - start_time < 0.05:
        c3 = smallest_last()
        c3 = compact_colors(c3)
        if is_valid(c3):
            k3 = num_colors(c3)
            if k3 < best_k:
                best_k = k3
                best_coloring = c3[:]

    # Apply Kempe reduction to the best found
    if best_coloring is not None and time.time() - start_time < 0.05:
        best_coloring = kempe_reduce(best_coloring)
        best_coloring = compact_colors(best_coloring)

    # Fallback: greedy by degree if nothing worked
    if best_coloring is None or not is_valid(best_coloring):
        ordering = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        coloring = [-1] * n
        for v in ordering:
