        buckets[d].append(v)
    # We'll track the current minimum degree
    order = []  # removal order (will be smallest-last)
    # We need to update degrees as we remove vertices
    # We'll maintain a list of removed flags
    removed = [False] * n
    # Current min degree pointer
    min_deg = 0
    for _ in range(n):
        # Find the next vertex to remove: non-removed with smallest current degree
        while min_deg <= max_deg and not buckets[min_deg]:
            min_deg += 1
        if min_deg > max_deg:
            # Should not happen if there are vertices left
            break
        # Get a vertex from the bucket
        v = buckets[min_deg].pop()
        # Skip if already removed (due to multiple entries)
        while removed[v]:
            if not buckets[min_deg]:
                break
            v = buckets[min_deg].pop()
        if removed[v]:
            # If we exhausted the bucket, increase min_deg and try again
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            while removed[v] and buckets[min_deg]:
                v = buckets[min_deg].pop()
            if removed[v]:
                # This should not happen if there are vertices left
                # Fallback: linear search
                for i in range(n):
                    if not removed[i]:
                        v = i
                        break
        # Now v is a valid vertex to remove
        removed[v] = True
        order.append(v)
        # Update neighbors: decrease their degree
        for u in graph[v]:
            if not removed[u]:
                d = degree[u]
                # Remove u from its current bucket
                if d < len(buckets):
                    # We cannot efficiently remove from middle of list, so we mark and skip later
                    # Instead, we'll just leave it and skip when we see removed flag
                    # But we need to update its degree and add to new bucket
                    degree[u] -= 1
                    d_new = degree[u]
                    if d_new < len(buckets):
                        buckets[d_new].append(u)
                    else:
                        # Extend buckets if necessary (should not happen as degree decreases)
                        while len(buckets) <= d_new:
                            buckets.append([])
                        buckets[d_new].append(u)
                else:
                    degree[u] -= 1
        # After processing, we may need to adjust min_deg (it can only decrease or stay)
        # But we will find it in the next iteration by scanning from current min_deg
    # If we didn't get all vertices (should not happen), add remaining in any order
    if len(order) < n:
        for v in range(n):
            if not removed[v]:
                order.append(v)
                removed[v] = True
    # Now color in reverse order (largest-last first) using First-Fit
    colors = [-1] * n
    for v in reversed(order):
        # Find colors used by colored neighbors
        neighbor_colors = set()
        for u in graph[v]:
            if colors[u] != -1:
                neighbor_colors.add(colors[u])
        # Assign smallest non-negative integer not in neighbor_colors
        c = 0
        while c in neighbor_colors:
            c += 1
        colors[v] = c
    return colors

