    # Helper: count unique colors
    def count_colors(coloring):
        return len(set(c for c in coloring if c != -1))

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # 1. Welsh-Powell: degree descending
    order_wp = sorted(range(n), key=lambda x: (-degree[x], x))
    c_wp = greedy_color(order_wp)
    if is_valid(c_wp):
        k_wp = count_colors(c_wp)
        if k_wp < best_k:
            best_k = k_wp
            best_coloring = c_wp[:]

    # 2. Smallest-Last (Matula-Beck) ordering
    # Compute core decomposition ordering
    remaining = set(range(n))
    deg_copy = degree[:]
    order_sl = []
    # Buckets for degree
    max_deg = max(degree) if n > 0 else 0
