    if is_valid(c_sl):
        k_sl = count_colors(c_sl)
        if k_sl < best_k:
            best_k = k_sl
            best_coloring = c_sl[:]

    # 3. DSATUR with degree tie-breaking
    color_dsatur = [-1] * n
    sat = [0] * n  # saturation degree
    uncolored = set(range(n))

