        c = 0
        while c < n and used[c]:
            c += 1
        color_dsatur[v] = c
        uncolored.remove(v)
        # Update saturation of uncolored neighbors
        for u in graph[v]:
            if u in uncolored:
                # Check if color c is new in neighborhood
                new_sat = sat[u]
                for w in graph[u]:
                    if color_dsatur[w] == c:
                        new_sat += 1
                        break
                # Actually, we need distinct colors, so better to recompute or track properly
                # For simplicity, we'll recompute saturation from scratch for affected vertices
                # Since n <= 100, it's acceptable
        # Recompute saturation for all uncolored vertices (simple but safe)
        for u in uncolored:
            neighbor_colors = set()
            for w in graph[u]:
                if color_dsatur[w] != -1:
