        if k_dsatur < best_k:
            best_k = k_dsatur
            best_coloring = color_dsatur[:]

    # 4. Recursive Largest First (RLF) style independent set extraction
    def rlf_coloring():
        color = [-1] * n
        remaining = set(range(n))
        c = 0
        while remaining:
            # Build independent set for color c
            # Start with vertex of max degree in remaining
            if not remaining:
                break
            v = max(remaining, key=lambda x: (sum(1 for w in graph[x] if w in remaining), -x))
            independent_set = {v}
            # Partition remaining \ {v} into U (not adjacent to any in S) and W (adjacent to at least one in S)
            U = set()
            W = set()
            for u in remaining:
                if u == v:
                    continue
                if any(w in independent_set for w in graph[u]):
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty, add vertices that maximize |N(u) ∩ W|
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = sum(1 for w in graph[u] if w in W)
                    deg_u = sum(1 for w in graph[u] if w in U)
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u):
                        max_nw = nw
                        min_deg_u = deg_u
                        best_u = u
                if best_u == -1:
                    break  # should not happen if U not empty
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in graph[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
            remaining -= independent_set
            c += 1
        return color

    c_rlf = rlf_coloring()
    if is_valid(c_rlf):
        k_rlf = count_colors(c_rlf)
        if k_rlf < best_k:
            best_k = k_rlf
            best_coloring = c_rlf[:]

    # If no valid coloring found (should not happen), fallback to greedy with natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
