def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (binary square matrix)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True

    # Convert to adjacency list and bitmask for fast operations
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    # Bitmask representation: bit i set if neighbor i exists
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: get uncolored neighbors mask
    def uncolored_neighbors_mask(u, colored_mask):
        return bit_adj[u] & ~colored_mask

    # Helper: saturation degree (number of distinct colors in neighbors)
    def saturation_degree(u, coloring):
        neighbor_colors = 0
        for v in adj_list[u]:
            if coloring[v] != -1:
                neighbor_colors |= (1 << coloring[v])
        return neighbor_colors.bit_count()

    # Helper: degree in subgraph induced by uncolored vertices
    def degree_in_uncolored(u, uncolored_set):
        if not uncolored_set:
            return 0
        mask = 0
        for v in uncolored_set:
            mask |= (1 << v)
        return (bit_adj[u] & mask).bit_count()

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        colored_mask = 0  # bitmask of colored vertices
        # Order by initial degree descending for tie-breaking in saturation
        degrees = [len(adj_list[i]) for i in range(n)]
        vertices = list(range(n))
        # Sort by degree descending, then by index
        vertices.sort(key=lambda x: (-degrees[x], x))

        for _ in range(n):
            # Select uncolored vertex with max saturation degree
            best_v = -1
            max_sat = -1
            max_deg = -1
            for v in vertices:
                if coloring[v] == -1:
                    sat = saturation_degree(v, coloring)
                    if sat > max_sat or (sat == max_sat and degree_in_uncolored(v, [u for u in range(n) if coloring[u] == -1]) > max_deg):
                        max_sat = sat
                        max_deg = degree_in_uncolored(v, [u for u in range(n) if coloring[u] == -1])
                        best_v = v
            if best_v == -1:
                break  # should not happen
            # Assign smallest available color
            used = 0
            for nb in adj_list[best_v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[best_v] = c
            colored_mask |= (1 << best_v)
        return coloring

    # RLF (Recursive Largest First) - maximal independent set extraction
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set S for current color
            S = set()
            # Start with vertex of max degree in G[uncolored]
            if uncolored:
                v = max(uncolored, key=lambda x: degree_in_uncolored(x, uncolored))
                S.add(v)
                uncolored.remove(v)

            # U: vertices not adjacent to S (eligible for this color)
            # W: vertices adjacent to S (ineligible for this color)
            U = set(uncolored)  # copy
            W = set()
            for v in S:
                for nb in adj_list[v]:
                    if nb in uncolored:
                        if nb in U:
                            U.remove(nb)
                        W.add(nb)

            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_neighbors += 1
                    deg_in_U = degree_in_uncolored(u, U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
            # Next uncolored set is W (vertices adjacent to S)
            uncolored = W
        return coloring

    # Smallest-Last ordering (Matula & Beck) with First-Fit
    def smallest_last():
        # Build smallest-last ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # We'll update degrees as we remove vertices
        deg_copy = degrees[:]
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = min(remaining, key=lambda x: (deg_copy[x], x))
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    deg_copy[nb] -= 1
        # Color in reverse order (last removed first)
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        current = coloring[:]
        k = num_colors(current)
        if k <= 1:
            return current

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                continue

            changed = True
            # Try to recolor all target_vertices
            while changed and target_vertices:
                changed = False
                v = target_vertices.pop()
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    # Check if color c is available (no neighbor has color c)
                    conflict = False
                    for nb in adj_list[v]:
                        if current[nb] == c:
                            conflict = True
                            break
                    if not conflict:
                        current[v] = c
                        changed = True
                        break
                if changed:
                    continue

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # We'll try to swap colors c and target_color in the component containing v
                    # Only if v is not adjacent to any vertex of color c (otherwise swap would cause conflict immediately)
                    has_c_neighbor = False
                    for nb in adj_list[v]:
                        if current[nb] == c:
                            has_c_neighbor = True
                            break
                    if has_c_neighbor:
                        continue  # swap would put two c's together on v and its neighbor

                    # Build the Kempe chain: connected component of v in subgraph of colors {c, target_color}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (current[nb] == c or current[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)

                    # Check if swapping is safe: no vertex in component has a neighbor outside with color c (for c->target) or target_color (for target->c)
                    # Actually, swapping preserves validity if we only swap within the component, because:
                    # - For an edge inside component: if both ends same color, after swap still same (but they were different before? Actually in Kempe chain, adjacent vertices have different colors, so after swap still different)
                    # - For edge from component to outside: 
                    #   * If outside vertex has color c: then inside vertex must have color target_color (because if inside had c, outside c would be same -> invalid, but coloring is valid so inside can't have c if outside has c). After swap: inside becomes c, outside c -> conflict! 
                    #   * Similarly, if outside has color target_color and inside has c, after swap inside becomes target_color -> conflict.
                    # Therefore, swap is safe iff there is no edge from component to a vertex colored c or target_color outside the component.
                    safe = True
                    for node in component:
                        for nb in adj_list[node]:
                            if not visited[nb]:
                                if current[nb] == c or current[nb] == target_color:
                                    safe = False
                                    break
                        if not safe:
                            break

                    if safe:
                        # Perform swap: c <-> target_color in component
                        for node in component:
                            if current[node] == c:
                                current[node] = target_color
                            else:  # must be target_color
                                current[node] = c
                        changed = True
                        # After swap, v now has color c, so we break and try to reassign it (but we already tried direct reassignment and failed, but now it's colored c which is < target_color, so we break inner loop)
                        break
                # If we changed coloring, we need to reconsider this vertex? Actually we moved on.
                # But we broke out of the Kempe loop, so we go to next vertex in target_vertices.
            # If we managed to recolor all target_vertices, we can eliminate this color
            if not any(current[v] == target_color for v in range(n)):
                # Renumber colors higher than target_color down by 1
                for v in range(n):
                    if current[v] > target_color:
                        current[v] -= 1
                # Break out and try again from high color since k reduced
                return kempe_reduce(current)
        return current

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Apply Kempe reduction to each candidate
    reduced = []
    for cand in candidates:
        reduced.append(kempe_reduce(cand))

    # Select the candidate with fewest colors
    best = min(reduced, key=num_colors)

    # Final validation and consecution of color indices
    # Ensure colors are consecutive from 0
    if not best:
        return []
    # Remap colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best[i] = unique_colors[c]

