def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build neighbor sets
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            neighbors[i] = set(adj[i])

    # Precompute degrees
    degrees = [len(neighbors[i]) for i in range(n)]

    # Find articulation points using DFS
    def find_articulation_points():
        disc = [-1] * n
        low = [-1] * n
        parent = [-1] * n
        ap = [False] * n
        time = [0]

        def dfs(u):
            children = 0
            disc[u] = low[u] = time[0]
            time[0] += 1
            for v in neighbors[u]:
                if disc[v] == -1:
                    parent[v] = u
                    children += 1
                    dfs(v)
                    low[u] = min(low[u], low[v])
                    if parent[u] == -1 and children > 1:
                        ap[u] = True
                    if parent[u] != -1 and low[v] >= disc[u]:
                        ap[u] = True
                elif v != parent[u]:
                    low[u] = min(low[u], disc[v])

        for i in range(n):
            if disc[i] == -1:
                dfs(i)
        return [i for i in range(n) if ap[i]]

    articulation_points = find_articulation_points()

    # Order: articulation points first (by degree descending), then others
    ordered_vertices = sorted(
        articulation_points,
        key=lambda x: (-degrees[x], x)
    ) + sorted(
        [v for v in range(n) if v not in articulation_points],
        key=lambda x: (-degrees[x], x)
    )

    # Greedy coloring in the determined order
    color = [-1] * n
    for u in ordered_vertices:
        used = [False] * (n + 1)
        for v in neighbors[u]:
            if color[v] != -1:
                used[color[v]] = True
        c = 0
        while c <= n and used[c]:
            c += 1
        color[u] = c

    # Compact colors
    unique_colors = sorted(set(color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    return color

