    def kempe_swap(color, a, b, u):
        if color[u] not in (a, b):
            return False
        stack = [u]
        visited = set()
        comp = []
        while stack:
            v = stack.pop()
            if v in visited:
                continue
            visited.add(v)
            comp.append(v)
            for w in neighbors[v]:
                if color[w] in (a, b) and w not in visited:
                    stack.append(w)
