        while U:
            # select u in U with max neighbors in W
            best_u = -1
            max_w_neighbors = -1
            for u in U:
                w_neighbors = sum(1 for w in neighbors[u] if w in W)
                if w_neighbors > max_w_neighbors:
                    max_w_neighbors = w_neighbors
                    best_u = u
                elif w_neighbors == max_w_neighbors:
                    # tie-break by min degree in U
                    deg_u = sum(1 for w in neighbors[u] if w in U)
                    deg_best = sum(1 for w in neighbors[best_u] if w in U) if best_u != -1 else float('inf')
                    if deg_u < deg_best or (deg_u == deg_best and u < best_u):
                        best_u = u
            if best_u == -1:
