    max_deg = max(degree) if n > 0 else 0
    buckets = [set() for _ in range(max_deg + 1)]
    for u in range(n):
        if degree[u] <= max_deg:
            buckets[degree[u]].add(u)
    for _ in range(n):
        # find non-empty bucket with smallest index
        i = 0
        while i <= max_deg and not buckets[i]:
            i += 1
        if i > max_deg:
            break
        v = buckets[i].pop()
        order.append(v)
        remaining.remove(v)
        for u in neighbors[v]:
            if u in remaining:
                # move u from bucket degree[u] to degree[u]-1
                old_deg = degree[u]
                degree[u] -= 1
                buckets[old_deg].remove(u)
                if degree[u] <= max_deg:
                    buckets[degree[u]].add(u)
                else:
                    # should not happen
                    pass
    # color in reverse order
    color = greedy_color(order[::-1])
    if is_valid(color):
        candidates.append(compact_colors(color))
    # 4. Simple greedy by original order
    color = greedy_color(list(range(n)))
    if is_valid(color):
        candidates.append(compact_colors(color))
    # 5. Greedy by descending degree
    order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    color = greedy_color(order)
    if is_valid(color):
        candidates.append(compact_colors(color))
    # Select best initial candidate (fewest colors)
    if not candidates:
        # fallback: assign each vertex a unique color
        best_color = list(range(n))
    else:
