    # Iterative Kempe chain reduction
    max_iterations = 10
    for _ in range(max_iterations):
        k = num_colors(best_color)
        if k <= 1:
            break
        target_color = k - 1
        # vertices with target color
        target_vertices = [v for v in range(n) if best_color[v] == target_color]
        made_progress = False
        # Try to recolor each target vertex
        for v in target_vertices:
            used = 0
            for u in neighbors[v]:
                c = best_color[u]
                if c != -1:
                    used |= (1 << c)
            # find smallest available color < target_color
            for c in range(target_color):
                if not (used & (1 << c)):
                    best_color[v] = c
                    made_progress = True
                    break
            if made_progress:
