                    for i in range(n_local):
                        coloring[i] = mapping[coloring[i]]
                    best_k = len(unique)
                else:
                    best_k = 0
        return coloring, best_k
    # Apply Kempe reduction
    best_coloring, best_k = kempe_reduce(best_coloring[:])
    # Final validation and ensure consecutive colors
    # Verify validity
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best_coloring[u] == best_coloring[v]:
                # Should not happen, but if so, fallback to DSATUR
                best_coloring = dsatur()
                break
    # Compact colors to 0..k-1
    present = set(best_coloring)
    if present:
        mapping = {old: new for new, old in enumerate(sorted(present))]
        best_coloring = [mapping[c] for c in best_coloring]
    return best_coloring

