def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Determine if input is adjacency matrix
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)
    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if cu == coloring[v]:
                    return False
        return True
    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # Helper: convert coloring to have consecutive colors starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        unique = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            coloring[i] = unique[c]
        return coloring
    # DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        sat = [0] * n
        # degree in uncolored subgraph (initially full degree)
        deg_uncolored = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by deg_uncolored, then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                # count bits in sat[u]
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and (deg_uncolored[u] > max_deg or (deg_uncolored[u] == max_deg and u < v))):
                    max_sat = s
                    max_deg = deg_uncolored[u]
                    v = u
            # assign smallest available color (mex)
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # add color c to saturation of u
                    sat[u] |= (1 << c)
                    deg_uncolored[u] -= 1
        return color
    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # independent set for color c
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.add(v)
            # partition U and W
            U = uncolored - {v}
            W = set()
            # move neighbors of v from U to W
            for u in adj_list[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)
            # while U not empty
            while U:
                # select u in U with max neighbors in W
                u_star = -1
                max_nw = -1
                min_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    nw = 0
                    for w in adj_list[u]:
                        if w in W:
                            nw += 1
                    # tie-break: min degree in G[U]
                    deg_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_U += 1
                    if nw > max_nw or (nw == max_nw and deg_U < min_deg_U):
                        max_nw = nw
                        min_deg_U = deg_U
                        u_star = u
                # add u_star to S
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star from U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color
    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # compute degeneracy ordering (smallest last)
        # copy of degrees
        degree = [len(adj_list[i]) for i in range(n)]
        # sets of vertices with given degree
        max_deg = max(degree) if n > 0 else 0
        bins = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            bins[d].add(v)
        # vertex ordering (peeled order)
        order = []
        # current min degree
        for _ in range(n):
            # find non-empty bin with smallest index
            d = 0
            while d <= max_deg and not bins[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            v = bins[d].pop()
            order.append(v)
            # update neighbors
            for u in adj_list[v]:
                if degree[u] > d:  # only if u not yet removed
                    # move u from bin[degree[u]] to bin[degree[u]-1]
                    bins[degree[u]].remove(u)
                    degree[u] -= 1
                    bins[degree[u]].add(u)
        # color in reverse order using first-fit
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        # make a copy to work on
        color = coloring[:]
        # helper: get vertices of a given color
        def get_color_class(c):
            return [v for v in range(n) if color[v] == c]
        # helper: check if vertex v can be recolored to color c without conflict
        def can_recolor(v, c):
            for u in adj_list[v]:
                if color[u] == c:
                    return False
            return True
        # helper: perform Kempe swap between colors a and b for the component containing v
        def kempe_swap(v, a, b):
            # BFS to get the (a,b)-Kempe component of v
            from collections import deque
            visited = [False] * n
            queue = deque([v])
            visited[v] = True
            component = []
            while queue:
                u = queue.popleft()
                component.append(u)
                for w in adj_list[u]:
                    if not visited[w] and (color[w] == a or color[w] == b):
                        visited[w] = True
                        queue.append(w)
            # swap colors a and b in the component
            for u in component:
                if color[u] == a:
                    color[u] = b
                elif color[u] == b:
                    color[u] = a
        # main loop: try to eliminate the highest color class
        changed = True
        while changed and num_colors(color) > 0:
            changed = False
            k = num_colors(color)
            # target the smallest color class (highest index)
            target = k - 1
            target_vertices = get_color_class(target)
            if not target_vertices:
                # should not happen, but skip
                break
            # try to recolor each vertex in target class
            for v in target_vertices:
                # try direct reassignment to a lower color
                for c in range(target):
                    if can_recolor(v, c):
                        color[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # check if v is isolated in the (c, target) Kempe subgraph
                    # i.e., no neighbor of v has color c
                    has_c_neighbor = False
                    for u in adj_list[v]:
                        if color[u] == c:
                            has_c_neighbor = True
                            break
                    if not has_c_neighbor:
                        # swapping the component of v (which is just v) frees color c
                        kempe_swap(v, c, target)
                        changed = True
                        break
                if changed:
                    break
            # if we changed, try to compact colors (remove gaps)
            if changed:
                # renumber colors to be consecutive
                mapping = {}
                next_c = 0
                for v in range(n):
                    if color[v] not in mapping:
                        mapping[color[v]] = next_c
                        next_c += 1
                    color[v] = mapping[color[v]]
        return color
    # Generate candidates
    candidates = []
    # DSATUR
    c1 = dsatur()
    if is_valid(c1):
        candidates.append(c1)
    # RLF
    c2 = rlf()
    if is_valid(c2):
        candidates.append(c2)
    # Smallest-Last
    c3 = smallest_last()
    if is_valid(c3):
        candidates.append(c3)
    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        # simple greedy in vertex order
        color = [-1] * n
        for v in range(n):
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        candidates.append(color)
    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Ensure validity and normalization
    if not is_valid(best):
        # fallback to DSATUR if something went wrong
        best = dsatur()
    best = normalize(best)
    return best

