def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets and adjacency bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if v < 0 or v >= n:
                    continue
                neighbors[u].add(v)
                bit_adj[u] |= (1 << v)

    # Build complement graph adjacency bitmasks
    bit_adj_comp = [0] * n
    full_mask = (1 << n) - 1
    for u in range(n):
        # Complement: all vertices except self and neighbors
        bit_adj_comp[u] = full_mask ^ bit_adj[u] ^ (1 << u)

    # Helper: greedy clique in complement graph (independent set in original)
    def greedy_clique_in_comp(P):
        if not P:
            return 0, []
        # Degeneracy ordering for pivot selection
        deg_in_P = {}
        for v in P:
            deg_in_P[v] = (bit_adj_comp[v] & P).bit_count()
        order = sorted(P, key=lambda x: deg_in_P[x])
        # Color the degeneracy ordering with greedy (largest first heuristic on complement)
        color = [-1] * n
        max_color_used = 0
        # Process in reverse degeneracy order
        for v in reversed(order):
            used = 0
            for w in range(n):
                if color[w] != -1 and (bit_adj_comp[v] >> w) & 1:
                    used |= (1 << color[w])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            if c > max_color_used:
                max_color_used = c
        # The largest color class in this greedy coloring is a large clique in complement
        # Find the color class with maximum size
        class_size = [0] * (max_color_used + 1)
        for v in P:
            if color[v] != -1:
                class_size[color[v]] += 1
        best_color = max(range(len(class_size)), key=lambda x: class_size[x]) if class_size else 0
        clique = [v for v in P if color[v] == best_color]
        return len(clique), clique

    # Main algorithm: iteratively find large independent sets (via cliques in complement)
    uncolored = set(range(n))
    color_assignment = [-1] * n
    current_color = 0

    while uncolored:
        # Find a large independent set in uncolored vertices via complement clique heuristic
        size, independent_set = greedy_clique_in_comp(uncolored)
        # Assign current color to this independent set
        for v in independent_set:
            color_assignment[v] = current_color
            uncolored.remove(v)
        current_color += 1

    # Compact colors to 0..k-1
    unique_colors = set(color_assignment)
    if not unique_colors:
        return [0] * n
    mapping = {old: new for new, old in enumerate(sorted(unique_colors))]
    compacted = [mapping[color_assignment[i]] for i in range(n)]

    # Validate coloring (debugging aid, can be removed for speed)
    # for u in range(n):
    #     for v in neighbors[u]:
    #         if u < v and compacted[u] == compacted[v]:
    #             # Invalid coloring, fallback to DSATUR
    #             return dsatur_fallback(adj, neighbors, bit_adj, n)
    return compacted

def dsatur_fallback(adj, neighbors, bit_adj, n):
    # Simple DSATUR implementation as fallback
    if n == 0:
        return []
    colors = [-1] * n
    # Degrees for tie-breaking
    degrees = [len(neighbors[i]) if isinstance(neighbors[i], set) else sum(1 for x in adj[i] if x) for i in range(n)]
    # Saturation degrees
    saturation = [0] * n
    # Colored neighbor colorsets (as bit masks for speed)
    neighbor_colors = [0] * n

    # Helper to update saturation
    def update_saturation(v):
        mask = 0
        for u in neighbors[v]:
            if colors[u] != -1:
                mask |= (1 << colors[u])
        saturation[v] = mask.bit_count()

    # Initial saturation is 0 for all
    for v in range(n):
        update_saturation(v)

    # Main loop
    for _ in range(n):
        # Select uncolored vertex with max saturation, then max degree
        v = -1
        max_sat = -1
        max_deg = -1
        for u in range(n):
            if colors[u] == -1:
                if saturation[u] > max_sat or (saturation[u] == max_sat and degrees[u] > max_deg):
                    max_sat = saturation[u]
                    max_deg = degrees[u]
                    v = u
                elif saturation[u] == max_sat and degrees[u] == max_deg and v == -1:
                    v = u
        if v == -1:
            break  # Should not happen
        # Find smallest available color
        used = neighbor_colors[v]
        c = 0
        while used & (1 << c):
            c += 1
        colors[v] = c
        # Update neighbors
        for u in neighbors[v]:
            if colors[u] == -1:
                neighbor_colors[u] |= (1 << c)
                update_saturation(u)
    # Compact colors
    unique = set(colors)
    mapping = {old: new for new, old in enumerate(sorted(unique))}
    return [mapping[colors[i]] for i in range(n)]

