    def normalize(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    best_coloring = None
    best_k = float('inf')
    start_time = time.time()
