                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Check if v is in a Kempe chain of colors (target_color, c) that does not include any other vertex of color target_color
                    # We'll do BFS to find the Kempe chain component containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (coloring[nb] == target_color or coloring[nb] == c):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any other vertex in component has color target_color (besides v)
                    has_other_target = any(coloring[node] == target_color and node != v for node in component)
                    if not has_other_target:
                        # Swap colors in component: target_color <-> c
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        # Now v has color c, so target color class loses v
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # Normalize colors to fill gaps
                mapping = {}
                next_c = 0
                for col in coloring:
                    if col not in mapping:
                        mapping[col] = next_c
                        next_c += 1
                coloring = [mapping[col] for col in coloring]
                k = count_colors(coloring)
            else:
                # Could not eliminate color k-1
                break
        if is_valid(coloring):
            k_final = count_colors(coloring)
            if k_final < best_k:
                best_k = k_final
                best_coloring = coloring[:]

    # Fallback: if no valid coloring found, use greedy on natural order
    if best_coloring is None or not is_valid(best_coloring):
        best_coloring = greedy_color(list(range(n)))
        if not is_valid(best_coloring):
            # Last resort: assign each vertex a unique color
            best_coloring = list(range(n))

    # Normalize and return
    best_coloring = normalize(best_coloring)
    return best_coloring

