    def jaccard_similarity(u, v):
        if v in adj_set[u]:
            return -1  # adjacent, skip
        union = adj_set[u] | adj_set[v]
        if not union:
            return 0.0
        intersection = adj_set[u] & adj_set[v]
        return len(intersection) / len(union)

    # Greedy coloring with vertex ordering based on Jaccard-driven pairing
    color = [-1] * n
    # Order vertices by descending degree (Welsh-Powell inspired)
    order = sorted(range(n), key=lambda x: len(adj_set[x]), reverse=True)

    for u in order:
        if color[u] != -1:
            continue
        # Find uncolored non-adjacent vertices with high Jaccard similarity to u
        candidates = []
        for v in order:
            if color[v] == -1 and v != u and v not in adj_set[u]:
                sim = jaccard_similarity(u, v)
                if sim > 0.5:  # threshold for high similarity
                    candidates.append((sim, v))
        # Sort candidates by similarity descending, then by degree descending
        candidates.sort(key=lambda x: (x[0], len(adj_set[x[1]])), reverse=True)

        # Try to assign same color to u and compatible candidates
        used_colors = set()
        for v in adj_set[u]:
            if color[v] != -1:
                used_colors.add(color[v])
        c = 0
        while c in used_colors:
            c += 1
        # Assign color c to u
        color[u] = c
        # Try to assign same color to high-similarity non-adjacent vertices
        for _, v in candidates:
            if color[v] != -1:
                continue
            # Check if v can take color c (no neighbor has color c)
            conflict = False
            for w in adj_set[v]:
                if color[w] == c:
                    conflict = True
                    break
            if not conflict:
                color[v] = c

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        if color[i] not in unique_colors:
            unique_colors[color[i]] = next_color
            next_color += 1
        color[i] = unique_colors[color[i]]

    return color

