        # Convert matrix to adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        # Already adjacency list
        graph = adj
        # Ensure symmetry for undirected graph
        for u in range(n):
            for v in graph[u]:
                if u not in graph[v]:
                    graph[v].append(u)
    # Handle trivial cases
    if n == 1:
        return [0]
    # Precompute degrees
    degrees = [len(graph[i]) for i in range(n)]
    # Try multiple heuristics and keep the best
    best_coloring = None
    best_k = float('inf')
    # Heuristic 1: DSATUR with degree tie-breaking
    coloring_dsatur = _dsatur(graph, degrees)
    k_dsatur = max(coloring_dsatur) + 1 if coloring_dsatur else 0
    if k_dsatur < best_k:
        best_k = k_dsatur
        best_coloring = coloring_dsatur[:]
    # Heuristic 2: RLF
    coloring_rlf = _rlf(graph, degrees)
    k_rlf = max(coloring_rlf) + 1 if coloring_rlf else 0
    if k_rlf < best_k:
        best_k = k_rlf
        best_coloring = coloring_rlf[:]
    # Heuristic 3: Smallest-Last ordering
    coloring_sl = _smallest_last(graph, degrees)
    k_sl = max(coloring_sl) + 1 if coloring_sl else 0
    if k_sl < best_k:
        best_k = k_sl
        best_coloring = coloring_sl[:]
