    best_coloring = _kempe_reduce(best_coloring, graph, best_k)
    # Validate and compact colors
    return _compact_colors(best_coloring, graph)

def _dsatur(graph, degrees):
    n = len(graph)
    colors = [-1] * n
    # saturation: number of distinct colors in neighbors
    saturation = [0] * n
    # neighbor color sets as bit masks for efficiency
    neighbor_colors = [0] * n
    uncolored = set(range(n))
    for _ in range(n):
        # Select uncolored vertex with max saturation, tie-break by degree
        max_sat = -1
        candidates = []
        for v in uncolored:
            sat = saturation[v]
            if sat > max_sat:
                max_sat = sat
                candidates = [v]
            elif sat == max_sat:
                candidates.append(v)
        # Tie-break by degree in the original graph (or uncolored subgraph degree)
        # Use degree in the uncolored subgraph for better accuracy
        if len(candidates) > 1:
            max_deg = -1
            best_v = candidates[0]
            for v in candidates:
                # count uncolored neighbors
                deg_uncolored = sum(1 for nb in graph[v] if nb in uncolored)
                if deg_uncolored > max_deg:
                    max_deg = deg_uncolored
                    best_v = v
                elif deg_uncolored == max_deg and v < best_v:
                    best_v = v
            v = best_v
        else:
            v = candidates[0]
        # Find smallest color not used by neighbors
        used = neighbor_colors[v]
        c = 0
        while used & (1 << c):
            c += 1
        colors[v] = c
        uncolored.remove(v)
        # Update saturation and neighbor colors for uncolored neighbors
        for nb in graph[v]:
            if nb in uncolored:
                # If this color is new in nb's neighbor set, increase saturation
                if not (neighbor_colors[nb] & (1 << c)):
                    neighbor_colors[nb] |= (1 << c)
                    saturation[nb] += 1
    return colors

def _rlf(graph, degrees):
    n = len(graph)
    colors = [-1] * n
    uncolored = set(range(n))
    color = 0
    while uncolored:
        # Build maximal independent set for this color
        independent_set = []
        # Step 1: pick vertex with max degree in uncolored subgraph
        max_deg = -1
        v0 = None
        for v in uncolored:
            deg = sum(1 for nb in graph[v] if nb in uncolored)
            if deg > max_deg:
                max_deg = deg
                v0 = v
        if v0 is None:
            break  # should not happen
        independent_set.append(v0)
        # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
        S = set(independent_set)
        U = set()
        W = set()
        for v in uncolored:
            if v == v0:
                continue
            if any(nb in S for nb in graph[v]):
                W.add(v)
            else:
                U.add(v)
        # Greedily add vertices from U to independent set
        while U:
            # Select u in U with max |N(u) ∩ W|
            best_u = None
            max_w_neighbors = -1
            for u in U:
                w_neighbors = sum(1 for nb in graph[u] if nb in W)
                if w_neighbors > max_w_neighbors:
                    max_w_neighbors = w_neighbors
                    best_u = u
                elif w_neighbors == max_w_neighbors:
                    # Tie-break by min degree in G[U]
                    deg_u = sum(1 for nb in graph[u] if nb in U)
                    deg_best = sum(1 for nb in graph[best_u] if nb in U) if best_u is not None else float('inf')
                    if deg_u < deg_best or (deg_u == deg_best and u < best_u):
                        best_u = u
            # Add best_u to independent set
            independent_set.append(best_u)
            S.add(best_u)
            U.remove(best_u)
            # Move neighbors of best_u that are in U to W
            for nb in graph[best_u]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
        # Assign color to all vertices in independent set
        for v in independent_set:
            colors[v] = color
            uncolored.remove(v)
        color += 1
    return colors

def _smallest_last(graph, degrees):
    n = len(graph)
    # Compute smallest-last ordering via core decomposition (peeling min degree)
    remaining = set(range(n))
    order = []
    deg = [len(graph[i]) for i in range(n)]
    # current degree in the remaining subgraph
    curr_deg = deg[:]
    while remaining:
        # find vertex with minimum current degree
        min_deg = float('inf')
        v_min = None
        for v in remaining:
            if curr_deg[v] < min_deg:
                min_deg = curr_deg[v]
                v_min = v
        order.append(v_min)
        remaining.remove(v_min)
        # update degrees of neighbors
        for nb in graph[v_min]:
            if nb in remaining:
                curr_deg[nb] -= 1
    # Color in reverse order using greedy first-fit
    colors = [-1] * n
    for v in reversed(order):
        used = 0
        for nb in graph[v]:
            if colors[nb] != -1:
                used |= (1 << colors[nb])
        c = 0
        while used & (1 << c):
            c += 1
        colors[v] = c
    return colors

def _kempe_reduce(colors, graph, k):
    if k <= 1:
        return colors
    n = len(graph)
    # Try to eliminate color classes from highest to lowest
    for target_color in range(k-1, -1, -1):
        # Get vertices with this color
        vertices = [v for v in range(n) if colors[v] == target_color]
        if not vertices:
            continue
        # Try to recolor each vertex to a lower color if possible
        made_change = False
        for v in vertices:
            # Try direct reassignment to a lower color
            for c in range(target_color):
                # Check if color c is available (no neighbor has color c)
                conflict = False
                for nb in graph[v]:
                    if colors[nb] == c:
                        conflict = True
                        break
                if not conflict:
                    colors[v] = c
                    made_change = True
                    break
            if made_change:
                break
        if made_change:
            # After a change, restart from the highest color again
            return _kempe_reduce(colors, graph, k)
        # If no direct reassignment, try Kempe chain swaps
        for v in vertices:
            for c in range(target_color):
                # Check if v can be swapped via Kempe chain (target_color, c)
                # We need to see if v is not connected to the c-colored component via a Kempe chain
                # Actually, we try to swap colors in the component of v in the subgraph induced by colors {target_color, c}
                # If swapping does not introduce a conflict, we can do it.
                # Build the Kempe chain component containing v for colors (target_color, c)
                from collections import deque
                visited = set()
                queue = deque([v])
                visited.add(v)
                component = set()
                while queue:
                    u = queue.popleft()
                    component.add(u)
                    for nb in graph[u]:
                        if nb not in visited and (colors[nb] == target_color or colors[nb] == c):
                            visited.add(nb)
                            queue.append(nb)
                # Check if swapping colors in this component is valid:
                # For any vertex in component, after swap, its new color should not conflict with neighbors outside component.
                valid = True
                for u in component:
                    new_color = c if colors[u] == target_color else target_color
                    for nb in graph[u]:
                        if nb not in component and colors[nb] == new_color:
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    # Perform swap
                    for u in component:
                        if colors[u] == target_color:
                            colors[u] = c
                        else:
                            colors[u] = target_color
                    made_change = True
                    break
            if made_change:
                break
        if made_change:
            return _kempe_reduce(colors, graph, k)
    return colors

def _compact_colors(colors, graph):
    # Validate coloring
    n = len(graph)
    for u in range(n):
        for v in graph[u]:
            if u < v and colors[u] == colors[v]:
                # Invalid coloring, but we hope it doesn't happen
                pass
    # Map colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = colors[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        colors[i] = unique_colors[c]
    return colors

