    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for this color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
                S.append(v)
                uncolored.remove(v)

            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                adjacent = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)

            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_neighbors_in_W = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    count = 0
                    for w in adj_list[u]:
                        if w in W:
                            count += 1
                    # Degree in U (number of neighbors in U)
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if count > max_neighbors_in_W or (count == max_neighbors_in_W and deg_in_U < min_deg_in_U) or \
                       (count == max_neighbors_in_W and deg_in_U == min_deg_in_U and (best_u == -1 or random.random() < 0.5)):
                        max_neighbors_in_W = count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                uncolored.remove(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
        return normalize(colors)

    # Smallest-Last (Matula-Beck) ordering with greedy coloring
    def smallest_last():
        if n == 0:
            return []
        # Build core ordering: repeatedly remove min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []  # will be peeled order (min degree first)
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            # Find unremoved vertex with min degree
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u] and deg[u] < min_deg:
                    min_deg = deg[u]
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if not removed[u]:
                    deg[u] -= 1
        # Color in reverse order (last removed first)
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return normalize(colors)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        if not is_valid_coloring(coloring):
            return coloring  # should not happen if input is valid
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # Try to eliminate the highest color class (k-1)
            target_color = k - 1
            vertices_target = [v for v in range(n) if coloring[v] == target_color]
            if not vertices_target:
                # Already empty, compact and continue
                coloring = normalize(coloring)
                k = num_colors(coloring)
                continue

            # Try to recolor each vertex in target class
            for v in vertices_target:
                # Try direct reassignment to a lower color
                used_by_neighbors = set()
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        used_by_neighbors.add(coloring[u])
                for c in range(target_color):  # try colors 0 to target_color-1
                    if c not in used_by_neighbors:
                        # Move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart from highest color after any change

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # We'll try to swap colors c and target_color in the component containing v
                    # Only if v is not already color c (it isn't, since it's target_color)
                    # Build the Kempe chain component for colors {c, target_color} containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque()
                    component = set()
                    # Start BFS from v only if it has color target_color (it does)
                    if coloring[v] == target_color:
                        queue.append(v)
                        visited[v] = True
                        component.add(v)
                    while queue:
                        x = queue.popleft()
                        for y in adj_list[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                                component.add(y)
                    # Check if we can swap: after swap, no two adjacent same color
                    # Swapping means: c -> target_color, target_color -> c in component
                    # We need to ensure that for every edge, colors remain different
                    valid_swap = True
                    for x in component:
                        new_color_x = c if coloring[x] == target_color else target_color
                        for y in adj_list[x]:
                            if y in component:
                                new_color_y = c if coloring[y] == target_color else target_color
                                if new_color_x == new_color_y:
                                    valid_swap = False
                                    break
                            else:
                                # neighbor y not in component keeps its color
                                if new_color_x == coloring[y]:
                                    valid_swap = False
                                    break
                        if not valid_swap:
                            break
                    if valid_swap:
                        # Perform the swap
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target_color
                            else:  # must be target_color
                                coloring[x] = c
                        improved = True
                        break  # break from color loop
                if improved:
                    break  # break from vertex loop
            if improved:
                # After any change, try to compact colors
                coloring = normalize(coloring)
                k = num_colors(coloring)

        return coloring

    # Run all heuristics and pick the best
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (shouldn't happen), fallback to greedy
    if not candidates:
        # Simple greedy ordering by index
        colors = [-1] * n
        for v in range(n):
            used = set()
            for u in adj_list[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        candidates.append(normalize(colors))

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    best = normalize(best)

    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    best = normalize(best)

    # Final validation (should be valid)
    if not is_valid_coloring(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
        best = normalize(best)

    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: count bits in integer
    def bit_count(x: int) -> int:
        return x.bit_count()

    # Helper: validate coloring
    def is_valid(coloring: list[int]) -> bool:
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring: list[int]) -> int:
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: make colors consecutive starting from 0
    def normalize(coloring: list[int]) -> list[int]:
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur() -> list[int]:
        if n == 0:
            return []
        colors = [-1] * n
        # saturation: set of colors in neighbors
        saturation = [set() for _ in range(n)]
        # degree in uncolored subgraph (initially full degree)
        degree_uncolored = [len(neighbors[i]) for i in range(n)]
        colored_count = 0
        # order of coloring
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree_uncolored, then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    sat_u = len(saturation[u])
                    deg_u = degree_uncolored[u]
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or (sat_u == max_sat and deg_u == max_deg and u < v):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen
            # find smallest color not used by neighbors
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c
            colored_count += 1
            # update saturation and degree_uncolored for neighbors
            for nb in neighbors[v]:
                if colors[nb] == -1:
                    saturation[nb].add(c)
                    degree_uncolored[nb] -= 1
        return colors

    # RLF algorithm (Largest First Independent Set extraction)
    def rlf() -> list[int]:
        if n == 0:
            return []
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda u: sum(1 for w in neighbors[u] if w in uncolored))
            S.add(v)
            # partition: U = vertices not adjacent to any in S, W = adjacent to at least one in S
            U = set()
            W = set()
            for u in uncolored:
                if u in S:
                    continue
                if any(w in S for w in neighbors[u]):
                    W.add(u)
                else:
                    U.add(u)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    score = sum(1 for w in neighbors[u] if w in W)
                    # degree in G[U]
                    deg_U = sum(1 for w in neighbors[u] if w in U)
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or (score == best_score and deg_U == best_deg_U and u < best_u):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u that are in U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for u in S:
                colors[u] = color
            uncolored -= S
            color += 1
        return colors

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        if n == 0:
            return []
        # copy of degrees
        degree = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []  # removal order
        # we will remove n vertices
        for _ in range(n):
            # find vertex with minimum degree among not removed
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u] and degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # decrease degree of neighbors
            for nb in neighbors[v]:
                if not removed[nb]:
                    degree[nb] -= 1
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for nb in neighbors[v]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    # Kempe chain color reduction
    def kempe_reduce(coloring: list[int]) -> list[int]:
        if n <= 1:
            return coloring
        # make a copy we can modify
        col = coloring[:]
        changed = True
        # we will try to reduce colors as much as possible
        while changed:
            changed = False
            k = num_colors(col)
            if k <= 1:
                break
            # target the last color (k-1)
            target_color = k - 1
            # vertices with target color
            target_vertices = [v for v in range(n) if col[v] == target_color]
            if not target_vertices:
                # should not happen if k is correct
                break
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = set()
                for nb in neighbors[v]:
                    if col[nb] < target_color:
                        used_by_neighbors.add(col[nb])
                for c in range(target_color):
                    if c not in used_by_neighbors:
                        col[v] = c
                        changed = True
                        break
                if changed:
                    # after changing one vertex, we break to restart the reduction
                    break
                # If direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    # We consider swapping colors c and target_color in the component containing v
                    # Only if v is not adjacent to any vertex of color c (otherwise swap would cause conflict)
                    if any(col[nb] == c for nb in neighbors[v]):
                        continue
                    # Build the Kempe chain component for colors {c, target_color} that contains v
                    # We'll do BFS/DFS
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if col[node] == c or col[node] == target_color:
                            component.add(node)
                            for nb in neighbors[node]:
                                if col[nb] == c or col[nb] == target_color:
                                    if nb not in visited:
                                        stack.append(nb)
                    # Check if any vertex in component adjacent to a vertex of color c outside component
                    # Actually, the condition for safe swap is that no vertex in the component is adjacent to a vertex of color c
                    # outside the component. Because if there is, after swap that outside vertex would be color c and adjacent
                    # to a vertex that becomes color c (from target_color) -> conflict.
                    safe = True
                    for node in component:
                        for nb in neighbors[node]:
                            if col[nb] == c and nb not in component:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # perform swap: c <-> target_color in component
                        for node in component:
                            if col[node] == c:
                                col[node] = target_color
                            else:  # must be target_color
                                col[node] = c
                        changed = True
                        break
                if changed:
                    break
            # After attempting to recolor target vertices, if we changed something, we continue loop
            # If we didn't change any target vertex, we cannot reduce further
            if not changed:
                break
        # normalize colors to be consecutive
        return normalize(col)

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidate (should not happen), fall back to trivial greedy
    if not candidates:
        # greedy in vertex order
        colors = [-1] * n
        for u in range(n):
            used = set()
            for nb in neighbors[u]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[u] = c
        candidates.append(colors)

    # Apply Kempe reduction to each candidate and pick best
    best_coloring = None
    best_k = float('inf')
    for cand in candidates:
        try:
            reduced = kempe_reduce(cand)
            if is_valid(reduced):
                k = num_colors(reduced)
                if k < best_k:
                    best_k = k
                    best_coloring = reduced
        except Exception:
            continue

    # Ensure we have a valid coloring
    if best_coloring is None or not is_valid(best_coloring):
        # final fallback: greedy
        colors = [-1] * n
        for u in range(n):
            used = set()
            for nb in neighbors[u]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[u] = c
        best_coloring = colors

    # Normalize and return
    return normalize(best_coloring)

import math
