def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        # adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                bit_adj[u] |= (1 << v)

    best_coloring = None
    best_k = n + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if coloring[u] == coloring[v]:
                        return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to consecutive 0..k-1
    def normalize(coloring):
        if not coloring:
            return []
        used = set(coloring)
        mapping = {c: i for i, c in enumerate(sorted(used))}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets as bit masks for fast saturation update
        neighbor_colors = [0] * n
        # degrees for tie-breaking
        degree = [bit_adj[i].bit_count() for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, break ties by degree, then random
            v = max(uncolored, key=lambda x: (saturation[x], degree[x], random.random()))
            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and neighbor colors for neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in uncolored:
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in current uncolored subgraph
            deg = {}
            for v in uncolored:
                deg[v] = sum(1 for u in uncolored if (bit_adj[v] >> u) & 1)
            # start with max degree vertex
            v = max(uncolored, key=lambda x: (deg[x], random.random()))
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and not ((bit_adj[v] >> u) & 1)}
            # W: vertices adjacent to S
            W = {u for u in uncolored if u != v and ((bit_adj[v] >> u) & 1)}
            while U:
                # select u in U with max neighbors in W, tie-break by min deg in U, then random
                def score(u):
                    neighbors_in_W = sum(1 for w in W if (bit_adj[u] >> w) & 1)
                    deg_in_U = sum(1 for w in U if w != u and (bit_adj[u] >> w) & 1)
                    return (neighbors_in_W, -deg_in_U, random.random())
                u = max(U, key=score)
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in list(U):
                    if (bit_adj[u] >> w) & 1:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        color = [-1] * n
        # copy of degrees
        deg = [bit_adj[i].bit_count() for i in range(n)]
        # adjacency sets for fast removal
        adj_set = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if (bit_adj[i] >> j) & 1:
                    adj_set[i].add(j)
        # stack for ordering
        stack = []
        remaining = set(range(n))
        while remaining:
            # find vertex of minimum degree in remaining
            v = min(remaining, key=lambda x: deg[x])
            stack.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in adj_set[v]:
                if u in remaining:
                    deg[u] -= 1
        # color in reverse order (last peeled first)
        for v in reversed(stack):
            used = 0
            for u in adj_set[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring
        k = num_colors(coloring)
        # try to eliminate color classes from highest to lowest
        changed = True
        while changed and k > 1:
            changed = False
            # target highest color class
            target_color = k - 1
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                # already empty, compact
                coloring = [c if c < target_color else c - 1 for c in coloring]
                k -= 1
                changed = True
                continue
            # try to recolor each vertex in target class
            for v in vertices:
                # try direct reassignment to a lower color
                for c in range(target_color):
                    conflict = False
                    for u in range(n):
                        if (bit_adj[v] >> u) & 1 and coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already recolored, break
                    if coloring[v] != target_color:
                        break
                    # BFS to find (target_color, c)-Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1 and not visited[y]:
                                if coloring[y] == target_color or coloring[y] == c:
                                    visited[y] = True
                                    queue.append(y)
                    # check if we can swap: no neighbor of component has color c outside component
                    can_swap = True
                    for x in component:
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1 and not visited[y]:
                                if coloring[y] == c:
                                    can_swap = False
                                    break
                        if not can_swap:
                            break
                    if can_swap:
                        # perform swap
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            elif coloring[x] == c:
                                coloring[x] = target_color
                        changed = True
                        break
            if changed:
                # compact colors
                used = set(coloring)
                mapping = {c: i for i, c in enumerate(sorted(used))}
                coloring = [mapping[c] for c in coloring]
                k = num_colors(coloring)
        return coloring

    # Run all heuristics
    for coloring in [dsatur(), rlf(), smallest_last()]:
        coloring = normalize(coloring)
        if is_valid(coloring):
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring[:]

    # Apply Kempe reduction to best
    if best_coloring is not None:
        best_coloring = kempe_reduce(best_coloring)
        best_coloring = normalize(best_coloring)

    # Fallback: greedy by degree if something went wrong
    if best_coloring is None or not is_valid(best_coloring):
        order = sorted(range(n), key=lambda x: bit_adj[x].bit_count(), reverse=True)
        color = [-1] * n
        for v in order:
            used = 0
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        best_coloring = normalize(color)

    return best_coloring

