            if best_v == -1:
                break  # should not happen
            # Find smallest available color
            used = 0
            for nb in neighbors[best_v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[best_v] = c
        return coloring

    # RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored_set = set(range(n))
        while uncolored_set:
            # Step 1: pick vertex with max degree in G[uncolored_set]
            if not uncolored_set:
                break
            v1 = max(uncolored_set, key=lambda x: len([nb for nb in neighbors[x] if nb in uncolored_set]))
            S = {v1}
            # Partition remaining uncolored into U and W
            U = set()
            W = set()
            for v in uncolored_set:
                if v == v1:
                    continue
                # check if v is adjacent to any in S
                adj_to_S = False
                for u in S:
                    if v in neighbors[u]:
                        adj_to_S = True
                        break
                if adj_to_S:
                    W.add(v)
                else:
                    U.add(v)
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    # count neighbors in W
                    score = 0
                    for nb in neighbors[u]:
                        if nb in W:
                            score += 1
                    # tie-break: min degree in G[U]
                    deg_U = 0
                    for nb in neighbors[u]:
                        if nb in U:
                            deg_U += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                        best_deg_U = deg_U
                    elif score == best_score:
                        if deg_U < best_deg_U:
                            best_deg_U = deg_U
                            best_u = u
                if best_u == -1:
                    break  # should not happen
                # Add best_u to S, remove from U, move its neighbors in U to W
                S.add(best_u)
                U.remove(best_u)
                for nb in neighbors[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            # Next color, uncolored set becomes W
            color += 1
            uncolored_set = W
        return coloring

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []  # will be removal order
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            # find unremoved vertex with min degree
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # decrease degree of neighbors
            for nb in neighbors[v]:
                if not removed[nb]:
                    deg[nb] -= 1
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in neighbors[v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, v, a, b):
        if coloring[v] not in (a, b):
            return False  # should not happen
        # Find the Kempe chain component containing v for colors a and b
        stack = [v]
        visited = set()
        component = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if coloring[u] in (a, b):
                component.add(u)
                for nb in neighbors[u]:
                    if nb not in visited and coloring[nb] in (a, b):
                        stack.append(nb)
        # Try to swap colors in this component: a->b, b->a
        # Check if after swap, no conflict arises (should be valid by Kempe theorem, but verify)
        # Actually, swapping within a component preserves validity, but we need to check if it helps
        # We will perform the swap and return the new coloring
        new_coloring = coloring[:]  # copy
        for u in component:
            if new_coloring[u] == a:
                new_coloring[u] = b
            else:
                new_coloring[u] = a
        return new_coloring

    # Attempt to eliminate the smallest color class using Kempe chains
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            # Get vertices with this color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                continue
            # Try to recolor each target vertex to a lower color if possible
            made_change = False
            for v in target_vertices:
                # Try direct reassignment to any lower color
                for c in range(target_color):
                    # Check if color c is available (no neighbor has color c)
                    conflict = False
                    for nb in neighbors[v]:
                        if coloring[nb] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Recolor v to c
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break
            if made_change:
                # After change, we may have unused colors; compact later
                break
            # If direct reassignment not possible, try Kempe chains
            for c in range(target_color):
                # For each vertex in target color, see if we can swap via Kempe chain (c, target_color)
                # to free color c for this vertex
                for v in target_vertices:
                    if coloring[v] != target_color:
                        continue
                    # Check if in the Kempe chain of v for colors c and target_color, 
                    # the component does not contain any vertex that would cause conflict if swapped?
                    # Actually, we can try to swap and see if it removes v from target color
                    new_coloring = kempe_swap(coloring, v, c, target_color)
                    # After swap, check if v is no longer target_color
                    if new_coloring[v] != target_color:
                        # Accept the swap
                        coloring[:] = new_coloring
                        made_change = True
                        break
                if made_change:
                    break
            if made_change:
                break
        # Compact colors: remap to 0..k'-1
        # Map used colors to consecutive integers
        used_colors = set()
        for v in range(n):
            if coloring[v] != -1:
                used_colors.add(coloring[v])
        if not used_colors:
            return coloring
        sorted_used = sorted(used_colors)
        mapping = {old: new for new, old in enumerate(sorted_used)}
        for v in range(n):
            if coloring[v] != -1:
                coloring[v] = mapping[coloring[v]]
        return coloring

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            used = 0
            for nb in neighbors[v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        candidates.append(coloring)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)

    # Apply iterative color reduction
    # Limit iterations to avoid timeout
    for _ in range(10):  # max 10 reduction attempts
        prev_colors = num_colors(best)
        new_best = reduce_colors(best[:])  # work on a copy
        if is_valid(new_best):
            new_colors = num_colors(new_best)
            if new_colors < prev_colors:
                best = new_best
            else:
                # No improvement, break early
                break
        else:
            break

    # Final validation and compacting (ensure 0..k-1)
    if not is_valid(best):
        # Should not happen, but fallback to greedy
        coloring = [-1] * n
        for v in range(n):
            used = 0
            for nb in neighbors[v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best = coloring

    # Ensure colors are consecutive starting from 0
    used_colors = set(best)
    if used_colors:
        sorted_used = sorted(used_colors)
        mapping = {old: new for new, old in enumerate(sorted_used)}
        for v in range(n):
            best[v] = mapping[best[v]]

    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency format and build bitmask adjacency
    if len(adj) > 0 and len(adj[0]) == len(adj) and all(
        isinstance(x, int) and x in (0, 1) for row in adj for x in row
    ):
        # Adjacency matrix
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        # Adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    bit_adj[u] |= (1 << v)

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if colors[u] == colors[v]:
                        return False
        return True

    # Helper: convert coloring to consecutive indices
    def normalize_colors(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # Helper: count unique colors
    def count_colors(colors):
        return len(set(colors)) if colors else 0

    # DSATUR algorithm
    def dsatur():
        colors = [-1] * n
        # Precompute degrees
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        # Saturation sets: bitmask of colors used by neighbors
        sat = [0] * n
        # Track uncolored vertices
        uncolored = set(range(n))

        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], degrees[x], random.random()))
            # Find smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            neighbors = bit_adj[v]
            u = 0
            while neighbors:
                if neighbors & 1:
                    if u in uncolored:
                        sat[u] |= (1 << c)
                neighbors >>= 1
                u += 1
        return colors

    # RLF algorithm
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: bin(bit_adj[x] & sum((1 << i) for i in uncolored)).count('1'))
                S.add(v)
                uncolored.remove(v)
                # U: vertices not adjacent to S, W: vertices adjacent to S
                U = uncolored - {u for u in uncolored if any((bit_adj[w] >> u) & 1 for w in S)}
                W = {u for u in uncolored if any((bit_adj[w] >> u) & 1 for w in S)}
                # While U not empty
                while U:
                    # Select u in U with max neighbors in W, tie-break by min degree in U
                    def score(u):
                        neighbors_in_W = bin(bit_adj[u] & sum((1 << w) for w in W)).count('1')
                        deg_in_U = bin(bit_adj[u] & sum((1 << i) for i in U)).count('1')
                        return (neighbors_in_W, -deg_in_U, random.random())
                    u = max(U, key=score)
                    S.add(u)
                    uncolored.remove(u)
                    U.remove(u)
                    # Move neighbors of u from U to W
                    nbrs = bit_adj[u]
                    v = 0
                    while nbrs:
                        if nbrs & 1:
                            if v in U:
                                U.remove(v)
                                W.add(v)
                        nbrs >>= 1
                        v += 1
            # Assign color to all in S
            for v in S:
                colors[v] = color
            color += 1
        return colors

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        order = []
        remaining = set(range(n))
        # Current degrees in remaining subgraph
        curr_deg = degrees[:]
        # Bucket sort by degree
        max_deg = max(degrees) if degrees else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = curr_deg[v]
            if d < len(buckets):
                buckets[d].append(v)
        # Pointer to current min degree
        min_deg = 0
        while remaining:
            # Find non-empty bucket
            while min_deg < len(buckets) and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= len(buckets):
                break
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            nbrs = bit_adj[v]
            u = 0
            while nbrs:
                if nbrs & 1:
                    if u in remaining:
                        d = curr_deg[u]
                        # Remove u from bucket d
                        if d < len(buckets) and u in buckets[d]:
                            buckets[d].remove(u)
                        curr_deg[u] -= 1
                        d_new = curr_deg[u]
                        if d_new < len(buckets):
                            buckets[d_new].append(u)
                nbrs >>= 1
                u += 1
            # Adjust min_deg if needed
            if min_deg > 0 and not buckets[min_deg-1]:
                min_deg -= 1
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            nbrs = bit_adj[v]
            u = 0
            while nbrs:
                if nbrs & 1:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
                nbrs >>= 1
                u += 1
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Kempe chain color reduction
    def kempe_reduce(colors):
        if not colors:
            return colors
        k = count_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # Target the smallest color class (by size)
            color_classes = [[] for _ in range(k)]
            for v, c in enumerate(colors):
                if c < k:
                    color_classes[c].append(v)
            # Find smallest non-empty class
            target_color = -1
            min_size = n + 1
            for c in range(k):
                if color_classes[c] and len(color_classes[c]) < min_size:
                    min_size = len(color_classes[c])
                    target_color = c
            if target_color == -1:
                break
            # Try to recolor each vertex in target_color
            for v in color_classes[target_color][:]:  # copy to avoid modification during iteration
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                nbrs = bit_adj[v]
                u = 0
                while nbrs:
                    if nbrs & 1:
                        if colors[u] != -1:
                            neighbor_colors.add(colors[u])
                    nbrs >>= 1
                    u += 1
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Move v to color c
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    # Rebuild color classes and restart
                    break
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Check if v is in a Kempe chain of (target_color, c) that does not include any other vertex of target_color?
                    # Actually, we want to swap a component that contains v and possibly other target_color vertices,
                    # but after swap, we want no vertex left in target_color? Not exactly.
                    # Standard: if we can swap a component containing v such that v becomes color c,
                    # and we don't care about others as long as we reduce the target color class size.
                    # We'll do: find the Kempe chain component of v for colors (target_color, c)
                    # If we swap, v will change to c, and any other target_color in the component will become c.
                    # So we can remove multiple vertices from target_color at once.
                    # But we must ensure the swap is valid (always is).
                    # We'll do BFS for the component.
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        nbrs_x = bit_adj[x]
                        y = 0
                        while nbrs_x:
                            if nbrs_x & 1:
                                if y not in visited and (colors[y] == target_color or colors[y] == c):
                                    visited.add(y)
                                    queue.append(y)
                            nbrs_x >>= 1
                            y += 1
                    # After swap, all target_color in component become c, and c become target_color.
                    # We want to know if after swap, the target_color class loses at least one vertex (v) and gains none?
                    # Actually, it loses all target_color in component and gains all c in component.
                    # We want the size of target_color to decrease.
                    # Let lose = number of target_color in component
                    # Let gain = number of c in component
                    # New size = old_size - lose + gain
                    # We want new_size < old_size => gain < lose.
                    lose = sum(1 for x in component if colors[x] == target_color)
                    gain = sum(1 for x in component if colors[x] == c)
                    if gain < lose:
                        # Perform swap
                        for x in component:
                            if colors[x] == target_color:
                                colors[x] = c
                            elif colors[x] == c:
                                colors[x] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # Renormalize colors to be consecutive
                colors = normalize_colors(colors)
                k = count_colors(colors)
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            cols = func()
            if is_valid_coloring(cols):
                cols = normalize_colors(cols)
                k = count_colors(cols)
                if k < best_k or (k == best_k and (best_colors is None or sum(cols) < sum(best_colors))):
                    best_k = k
                    best_colors = cols
        except Exception:
            continue

    # Fallback: greedy by initial degree
    if best_colors is None:
        order = sorted(range(n), key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            nbrs = bit_adj[v]
            u = 0
            while nbrs:
                if nbrs & 1:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
                nbrs >>= 1
                u += 1
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best_colors = normalize_colors(colors)

    # Apply Kempe reduction
    try:
        best_colors = kempe_reduce(best_colors)
        if not is_valid_coloring(best_colors):
            # If Kempe broke validity, fallback to best before Kempe
            pass
    except Exception:
        pass

    # Final validation and normalization
    if not is_valid_coloring(best_colors):
        # Last resort: greedy sequential
        colors = [0] * n
        for i in range(1, n):
            used = False
            for j in range(i):
                if (bit_adj[i] >> j) & 1:
                    if colors[j] == colors[i]:
                        used = True
                        break
            if used:
                for c in range(n):
                    conflict = False
                    for j in range(n):
                        if (bit_adj[i] >> j) & 1 and colors[j] == c:
                            conflict = True
                            break
                    if not conflict:
                        colors[i] = c
                        break
        best_colors = colors

    best_colors = normalize_colors(best_colors)
    return best_colors

