            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and (deg := len([w for w in adj_list[u] if w in uncolored])) > max_deg):
                    max_sat = s
                    max_deg = deg
                    v = u
                elif s == max_sat and (deg := len([w for w in adj_list[u] if w in uncolored])) == max_deg and v == -1:
                    v = u
