            S = {v}
            uncolored.remove(v)
            # U: vertices not adjacent to S; W: vertices adjacent to S
            U = {u for u in uncolored if not any(w in S for w in adj_list[u])}
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = None
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
