                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degrees = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Use bucket sort for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    old_deg = degrees[u]
                    degrees[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].remove(u)
                    if degrees[u] <= max_deg:
                        buckets[degrees[u]].append(u)
                    if ptr > degrees[u]:
                        ptr = degrees[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    for heuristic in [dsatur, rlf, smallest_last]:
        try:
            col = heuristic()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # Fallback: greedy by natural order
    try:
        col = greedy_color(list(range(n)))
        if is_valid(col):
            candidates.append(col)
    except Exception:
        pass

    if not candidates:
        # Last resort: assign distinct colors
        candidates.append(list(range(n)))

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Ensure colors are compact
        def compact(col):
            mapping = {}
            next_color = 0
            for c in col:
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
            return [mapping[c] for c in col]

        coloring = compact(coloring)
        k = num_colors(coloring)
        improved = True
        while improved and k > 1:
            improved = False
            # Target smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                coloring = compact(coloring)
                k = num_colors(coloring)
                continue

            # Try to recolor each target vertex
            for v in target_vertices[:]:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        used |= (1 << coloring[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Build (target_color, c)-Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for u in adj_list[node]:
                                if u not in visited and (coloring[u] == target_color or coloring[u] == c):
