                    safe = True
                    for node in component:
                        for u in adj_list[node]:
                            if u not in component and coloring[u] == c:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for node in component:
                            coloring[node] = c if coloring[node] == target_color else target_color
                        improved = True
                        break
                if improved:
                    break

            if improved:
                coloring = compact(coloring)
                k = num_colors(coloring)
            else:
                break
        return coloring

    best = kempe_reduce(best)
    # Final validation and compacting
    def compact_final(col):
        if not col:
            return col
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]

    best = compact_final(best)
    if not is_valid(best):
        # Ultimate fallback: greedy on DSATUR order
        order = []
        colored = set()
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            v = -1
            max_sat = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat:
                    max_sat = s
                    v = u
            if v == -1:
                v = next(iter(uncolored))
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            order.append(v)
            colored.add(v)
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        best = greedy_color(order)
        best = compact_final(best)

    return best

