def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    if is_matrix:
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)

    # Helper: get neighbors as list
    def neighbors(u):
        mask = bit_adj[u]
        res = []
        v = 0
        while mask:
            if mask & 1:
                res.append(v)
            mask >>= 1
            v += 1
        return res

    # Helper: count bits
    def bit_count(x):
        return x.bit_count()

    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Initial vertex: max degree
        if uncolored:
            v = max(uncolored, key=lambda x: bit_count(bit_adj[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in neighbors(v):
                if u in uncolored:
                    sat[u] += 1

        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                v = next(iter(uncolored))
            else:
                # Tie-break: max degree in uncolored subgraph
                v = max(candidates, key=lambda x: bit_count(bit_adj[x] & sum((1 << u) for u in uncolored)))
            # Find smallest available color
            used = 0
            for u in neighbors(v):
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors(v):
                if u in uncolored:
                    sat[u] += 1
        return color

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: bit_count(bit_adj[x] & sum((1 << u) for u in uncolored)))
            S.add(v)
            uncolored.remove(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = set()
            W = set()
            for u in uncolored:
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            while U:
                # Select u in U with max neighbors in W
                best_u = None
                max_w_neighbors = -1
                for u in U:
                    w_neighbors = bit_count(bit_adj[u] & sum((1 << w) for w in W))
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        # Tie-break: min degree in U
                        deg_u = bit_count(bit_adj[u] & sum((1 << x) for x in U))
                        if best_u is None or deg_u < bit_count(bit_adj[best_u] & sum((1 << x) for x in U)):
                            best_u = u
                if best_u is None:
                    best_u = next(iter(U))
                S.add(best_u)
                uncolored.remove(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for u in list(U):
                    if (bit_adj[best_u] >> u) & 1:
                        U.remove(u)
                        W.add(u)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

    # Smallest-Last (Matula & Beck) greedy
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [bit_count(bit_adj[v]) for v in range(n)]
        # We'll simulate peeling
        import heapq
        heap = [(degrees[v], v) for v in range(n)]
        heapq.heapify(heap)
        removed = [False] * n
        while heap:
            d, v = heapq.heappop(heap)
            if removed[v]:
                continue
            if d != degrees[v]:
                heapq.heappush(heap, (degrees[v], v))
                continue
            removed[v] = True
            order.append(v)
            for u in neighbors(v):
                if not removed[u]:
                    degrees[u] -= 1
                    heapq.heappush(heap, (degrees[u], u))
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors(v):
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain swap
    def kempe_swap(color, a, b, v):
        # Returns new color after swapping a and b in the component containing v, or None if invalid
        stack = [v]
        visited = set()
        comp = set()
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            comp.add(node)
            for u in neighbors(node):
                if color[u] == a or color[u] == b:
                    if u not in visited:
                        stack.append(u)
        # Check if swapping is safe: no neighbor outside comp has color a or b that would conflict
        for node in comp:
            for u in neighbors(node):
                if u not in comp and (color[u] == a or color[u] == b):
                    return None  # Would create conflict
        # Perform swap
        new_color = color[:]
        for node in comp:
            if new_color[node] == a:
                new_color[node] = b
            elif new_color[node] == b:
                new_color[node] = a
        return new_color

    # Try to eliminate a color class using Kempe chains
    def reduce_colors(color):
        # Map color to list of vertices
        color_classes = {}
        for v, c in enumerate(color):
            color_classes.setdefault(c, []).append(v)
        if not color_classes:
            return color
        max_color = max(color_classes.keys())
        # Try to eliminate from highest color down
        for target in range(max_color, -1, -1):
            if target not in color_classes:
                continue
            vertices = color_classes[target][:]
            # Try to recolor each vertex in this class
            for v in vertices:
                if color[v] != target:  # May have been recolored already
                    continue
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors(v):
                    c = color[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(target):
                    if not (used & (1 << c)):
                        # Move v to color c
                        color[v] = c
                        break
                else:
                    # Try Kempe chains with each lower color
                    for c in range(target):
                        new_color = kempe_swap(color, target, c, v)
                        if new_color is not None:
                            color = new_color
                            break
                    else:
                        continue
                    break
            # After attempting to recolor all vertices in target class, check if class is empty
            if target not in color_classes or not color_classes[target]:
                # Remove this color by shifting higher colors down
                for v in range(n):
                    if color[v] > target:
                        color[v] -= 1
                # Recurse to try further reduction
                return reduce_colors(color)
        return color

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to greedy
    if not candidates:
        color = [-1] * n
        for v in range(n):
            used = 0
            for u in neighbors(v):
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        candidates.append(color)

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for color in candidates:
        k = len(set(color))
        if k < best_k:
            best_k = k
            best_color = color

    # Apply Kempe reduction to best candidate
    best_color = reduce_colors(best_color)

    # Validate and compact colors
    # Ensure proper coloring
    for v in range(n):
        for u in neighbors(v):
            if v < u and best_color[v] == best_color[u]:
                # Conflict, fallback to greedy
                color = [-1] * n
                for v in range(n):
                    used = 0
                    for u in neighbors(v):
                        c = color[u]
                        if c != -1:
                            used |= (1 << c)
                    c = 0
                    while used & (1 << c):
                        c += 1
                    color[v] = c
                best_color = color
                break
        else:
            continue
        break

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for v in range(n):
        c = best_color[v]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_color[v] = unique_colors[c]

    return best_color

