def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list if necessary (detect adjacency matrix)
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj

    # Precompute bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in graph[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    def is_valid_coloring(colors):
        for u in range(n):
            for v in graph[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    def count_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in graph[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # Heuristic 1: DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        saturation = [0] * n
        # degree in uncolored subgraph (initially full degree)
        uncolored_deg = [len(graph[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                deg = uncolored_deg[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best):
                    best_sat = sat
                    best_deg = deg
                    best = v
            v = best
            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in graph[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return colors

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # build maximal independent set for this color
            # start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = {u for u in uncolored if u != v and all(u not in graph[w] for w in independent_set)}
            W = {u for u in uncolored if u != v and any(u in graph[w] for w in independent_set)}
            # expand independent set
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_deg_in_U = float('inf')
                for u in U:
                    score = sum(1 for w in graph[u] if w in W)
                    deg_in_U = sum(1 for w in graph[u] if w in U)
                    if score > best_score or (score == best_score and deg_in_U < best_deg_in_U) or (score == best_score and deg_in_U == best_deg_in_U and u < best_u):
                        best_score = score
                        best_deg_in_U = deg_in_U
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in graph[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to independent_set
            for v in independent_set:
                colors[v] = color
            uncolored -= independent_set
            color += 1
        return colors

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering by repeatedly removing min degree vertex
        degree = [len(graph[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # get a vertex from bucket[ptr]
            while buckets[ptr] and buckets[ptr][-1] not in remaining:
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in graph[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    if d <= max_deg:
                        buckets[d].append(u)
                    if degree[u] < ptr:
                        ptr = degree[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Heuristic 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        return greedy_color(order)

    # Run all heuristics and pick best
    candidates = [
        dsatur(),
        rlf(),
        smallest_last(),
        welsh_powell()
    ]
    # also try random order greedy a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        if is_valid_coloring(col):
            k = count_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col[:]

    # If no valid coloring found (should not happen), fallback to greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain based color reduction
    def eliminate_color_class(colors, k):
        # try to eliminate color k-1
        target = k - 1
        vertices = [v for v in range(n) if colors[v] == target]
        if not vertices:
            return colors, k - 1  # already eliminated
        # Try to recolor each vertex in target class
        # We'll try multiple passes
        improved = True
        while improved and vertices:
            improved = False
            # Try direct reassignment first
            for v in vertices[:]:  # iterate over copy
                if colors[v] != target:
                    continue  # already recolored
                used = 0
                for u in graph[v]:
                    if colors[u] != -1:
                        used |= (1 << colors[u])
