                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if colors[node] == target or colors[node] == c:
                                component.add(node)
                                for nb in graph[node]:
                                    if nb not in visited and (colors[nb] == target or colors[nb] == c):
                                        stack.append(nb)
                        # Check if swapping this component would free color c for v
                        # After swap, v would get color c (if v in component, which it is)
                        # We need to ensure that no neighbor of v gets color c after swap (which would cause conflict)
                        # Actually, we need to check that after swap, v can be colored c without conflict
                        # But since we are swapping only target and c, and v is target->c, we need to check neighbors of v:
                        # For neighbor u of v:
                        #   if u in component: its color flips (target<->c)
