                        #        if original color was target -> becomes c -> conflict if we set v to c? 
                        #          Actually, v is being set to c, and u becomes c -> conflict.
                        #        if original color was c -> becomes target -> no conflict (since v is c)
                        #   else:
                        #        color unchanged -> conflict if it was c
                        # So condition: no neighbor u of v such that:
                        #   (u in component and colors[u] == target) OR (u not in component and colors[u] == c)
                        conflict = False
                        for u in graph[v]:
                            if colors[u] == -1:
                                continue
                            if u in component:
                                if colors[u] == target:  # becomes c
                                    conflict = True
                                    break
                            else:
                                if colors[u] == c:
                                    conflict = True
