                        if not conflict:
                            # perform swap
                            for node in component:
                                if colors[node] == target:
                                    colors[node] = c
                                elif colors[node] == c:
                                    colors[node] = target
                            improved = True
                            vertices.remove(v)
                            break
                    if improved:
                        break
        # Recompact colors: ensure colors are 0..k'-1
        # Map used colors to consecutive integers
        used_colors = set()
        for v in range(n):
            if colors[v] != -1:
                used_colors.add(colors[v])
        if not used_colors:
            return colors, 0
        mapping = {}
        sorted_used = sorted(used_colors)
        for new, old in enumerate(sorted_used):
            mapping[old] = new
        for v in range(n):
            if colors[v] != -1:
                colors[v] = mapping[colors[v]]
        return colors, len(used_colors)

    # Apply color reduction iteratively
    current_colors = best_coloring[:]
    current_k = best_k
    improved = True
    while improved and current_k > 1:
        improved = False
        new_colors, new_k = eliminate_color_class(current_colors[:], current_k)
