        if new_k < current_k:
            current_coloring = new_coloring
            current_k = new_k
            improved = True

    # Ensure colors are consecutive starting from 0
    if n > 0:
        used_colors = set(current_coloring)
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        current_coloring = [mapping[c] for c in current_coloring]

    # Final validation (should always pass)
    for u in range(n):
        for v in adj_list[u]:
            if u < v and current_coloring[u] == current_coloring[v]:
                # Fallback to first valid candidate if invalid
                return best_coloring

    return current_coloring

import math
