def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert adjacency to bitmask representation and detect format
    bit_adj = [0] * n
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
        if is_matrix:
            for i in range(n):
                for j in range(n):
                    if adj[i][j] == 1:
                        bit_adj[i] |= (1 << j)
    if not is_matrix:
        # Treat as adjacency list
        for i in range(n):
            for neighbor in adj[i]:
                if 0 <= neighbor < n:
                    bit_adj[i] |= (1 << neighbor)

    # Helper: get neighbors as list from bitmask
    def neighbors_from_bitmask(bm):
        return [i for i in range(n) if bm & (1 << i)]

    # Helper: count bits
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors_from_bitmask(bit_adj[u]):
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: renumber colors to be consecutive starting from 0
    def renumber_colors(coloring):
        if not coloring:
            return coloring
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # colored neighbor masks for fast saturation update
        colored_mask = [0] * n
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation, break ties by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                # All uncolored have saturation 0, pick max degree in uncolored subgraph
                max_deg = -1
                for v in uncolored:
                    # degree in uncolored subgraph
                    deg = bit_count(bit_adj[v] & sum((1 << u) for u in uncolored))
                    if deg > max_deg:
                        max_deg = deg
                        candidates = [v]
                    elif deg == max_deg:
                        candidates.append(v)
            v = random.choice(candidates) if candidates else next(iter(uncolored))
            uncolored.remove(v)

            # Find smallest available color
            neighbor_colors = 0
            for u in neighbors_from_bitmask(bit_adj[v]):
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation of uncolored neighbors
            for u in neighbors_from_bitmask(bit_adj[v]):
                if u in uncolored:
                    # Add color c to u's saturation if not already present
                    if not (colored_mask[u] & (1 << c)):
                        colored_mask[u] |= (1 << c)
                        sat[u] += 1
        return renumber_colors(coloring)

    # RLF (Recursive Largest First) - independent set extraction
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set S for this color
            S = set()
            # Step 1: pick vertex with max degree in G[uncolored]
            if uncolored:
                v = max(uncolored, key=lambda x: bit_count(bit_adj[x] & sum((1 << u) for u in uncolored)))
                S.add(v)
                uncolored.remove(v)
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set(uncolored)  # copy
            W = set()
            # Remove from U any vertex adjacent to S
            to_remove_from_U = set()
            for u in U:
                for s in S:
                    if bit_adj[u] & (1 << s):
                        to_remove_from_U.add(u)
                        break
            U -= to_remove_from_U
            W |= to_remove_from_U
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = math.inf
                for u in U:
                    w_neighbors = bit_count(bit_adj[u] & sum((1 << w) for w in W))
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = bit_count(bit_adj[u] & sum((1 << x) for x in U))
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_in_U = bit_count(bit_adj[u] & sum((1 << x) for x in U))
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = u
                if best_u is None:
                    break  # should not happen
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for v in neighbors_from_bitmask(bit_adj[u]):
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
        return renumber_colors(coloring)

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        order = []  # will be removal order
        degrees = [bit_count(bit_adj[v]) for v in range(n)]
        # current degrees in the remaining subgraph
        curr_deg = degrees[:]
        # bucket sort like approach
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            if curr_deg[v] < len(buckets):
                buckets[curr_deg[v]].add(v)
        # Find min non-empty bucket
        def get_min_vertex():
            for d in range(len(buckets)):
                if buckets[d]:
                    v = buckets[d].pop()
                    return v, d
            return None, -1
        while remaining:
            v, d = get_min_vertex()
            if v is None:
                break
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in neighbors_from_bitmask(bit_adj[v]):
                if u in remaining:
                    old_deg = curr_deg[u]
                    curr_deg[u] -= 1
                    if old_deg < len(buckets):
                        buckets[old_deg].discard(u)
                    if curr_deg[u] < len(buckets):
                        buckets[curr_deg[u]].add(u)
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in neighbors_from_bitmask(bit_adj[v]):
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        return renumber_colors(coloring)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        # Try to eliminate color classes one by one from highest color down
        changed = True
        while changed:
            changed = False
            k = num_colors(coloring)
            # Try to remove highest color class
            for target_color in range(k-1, -1, -1):
                # Get vertices with target_color
                verts = [v for v in range(n) if coloring[v] == target_color]
                if not verts:
                    continue
                # Try to recolor each vertex in this class
                for v in verts:
                    # Check if v can take any color < target_color without conflict
                    neighbor_colors = 0
                    for u in neighbors_from_bitmask(bit_adj[v]):
                        if coloring[u] != -1:
                            neighbor_colors |= (1 << coloring[u])
                    # Try direct reassignment
                    for c in range(target_color):
                        if not (neighbor_colors & (1 << c)):
                            coloring[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chains with each color c < target_color
                    for c in range(target_color):
                        if neighbor_colors & (1 << c):
                            # Both colors present in neighborhood, try Kempe chain
                            # We want to see if we can swap v's color (target_color) with c
                            # by flipping a Kempe chain that does not pull other target_color vertices
                            # into target_color
                            # Build the (target_color, c) Kempe chain component containing v
                            stack = [v]
                            visited = set()
                            component = set()
                            while stack:
                                node = stack.pop()
                                if node in visited:
                                    continue
                                visited.add(node)
                                component.add(node)
                                for nb in neighbors_from_bitmask(bit_adj[node]):
                                    if nb not in visited and (coloring[nb] == target_color or coloring[nb] == c):
                                        stack.append(nb)
                            # Check if any neighbor of v with color c is in this component
                            # Actually, we need to see if flipping this component would cause
                            # any vertex to have two neighbors of same color? 
                            # Standard Kempe: flipping preserves validity.
                            # But we want to avoid pulling other target_color vertices into target_color?
                            # Actually, after flip, v will become color c, and some target_color vertices may become c.
                            # We want to free the target_color class entirely.
                            # So we need that after flip, no vertex remains color target_color.
                            # That means the component must include ALL vertices of color target_color?
                            # No, we are trying to recolor v only. We want to move v out of target_color.
                            # After flipping the component, v becomes c, and any target_color in component becomes c.
                            # So the number of target_color vertices decreases by |component ∩ target_color|.
                            # We want to eliminate the entire target_color class, so we need to do this for all vertices.
                            # Instead, we try to see if v can be moved to color c without creating conflict.
                            # Flipping a Kempe chain preserves validity, so if we flip the component containing v,
                            # the coloring remains valid.
                            # And v will change from target_color to c (if v was target_color) or c to target_color.
                            # Since v is target_color, after flip it becomes c.
                            # So we can assign v to c by flipping the component.
                            # But we must ensure that we don't accidentally pull other target_color vertices
                            # into the component and flip them to c, which is fine as long as we are
                            # trying to eliminate target_color.
                            # However, we are iterating over vertices in target_color, so flipping may
                            # affect other vertices we haven't processed yet.
                            # To avoid complexity, we just flip and break, then restart the reduction.
                            # Perform the swap
                            for node in component:
                                if coloring[node] == target_color:
                                    coloring[node] = c
                                elif coloring[node] == c:
                                    coloring[node] = target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                # Renumber colors to be consecutive
                coloring = renumber_colors(coloring)
        return coloring

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    for func in [dsatur, rlf, smallest_last]:
        try:
            coloring = func()
            if not is_valid_coloring(coloring):
                continue
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring[:]
        except Exception:
            continue

    # Fallback: greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: bit_count(bit_adj[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            neighbor_colors = 0
            for u in neighbors_from_bitmask(bit_adj[v]):
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = renumber_colors(coloring)

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best_coloring[:])
        if is_valid_coloring(improved):
            k_improved = num_colors(improved)
            if k_improved < num_colors(best_coloring):
                best_coloring = improved
    except Exception:
        pass

    # Final validation and renumber
    if not is_valid_coloring(best_coloring):
        # Last resort: simple greedy
        coloring = [-1] * n
        for v in range(n):
            neighbor_colors = 0
            for u in neighbors_from_bitmask(bit_adj[v]):
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = renumber_colors(coloring)
    else:
        best_coloring = renumber_colors(best_coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    # Convert to adjacency list and bitmask representation
    if len(adj) > 0 and len(adj[0]) == n and all(all(x in (0, 1) for x in row) for row in adj):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        # Adjacency list
        adj_list = adj
        bit_adj = [0] * n
        for u in range(n):
            for v in adj_list[u]:
                bit_adj[u] |= (1 << v)

    # Helper to check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper to get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper to compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # Greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used |= (1 << coloring[v])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return compact_colors(coloring)

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        # Precompute degrees for tie-breaking
        degrees = [len(adj_list[u]) for u in range(n)]

        for _ in range(n):
            # Select vertex with max saturation, break ties by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v]
                deg = degrees[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                   (sat == best_sat and deg == best_deg and (best_v == -1 or random.random() < 0.5)):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    # Count distinct colors in neighbors of u
                    neighbor_colors = 0
                    for w in adj_list[u]:
                        if coloring[w] != -1:
                            neighbor_colors |= (1 << coloring[w])
                    saturated[u] = neighbor_colors.bit_count()
        return compact_colors(coloring)

    # RLF: Recursive Largest First
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            # Degree in current uncolored subgraph
            deg_in_uncolored = [0] * n
            for u in uncolored:
                for v in adj_list[u]:
                    if v in uncolored:
                        deg_in_uncolored[u] += 1

            # Start with vertex of max degree in uncolored subgraph
            S = set()
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: deg_in_uncolored[x])
            S.add(v)
            uncolored.remove(v)

            # Partition: U (eligible), W (ineligible)
            U = set(uncolored)  # initially all uncolored are eligible
            W = set()
            for u in list(uncolored):
                if any(w in adj_list[u] for w in S):
                    U.remove(u)
                    W.add(u)

            # Greedily add to independent set
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in adj_list[u] if w in W)
                    deg_u = sum(1 for w in adj_list[u] if w in U)
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and (best_u == -1 or random.random() < 0.5)):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
        return compact_colors(coloring)

    # Smallest-Last ordering
    def smallest_last():
        # Core decomposition to get ordering
        degrees = [len(adj_list[u]) for u in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degrees[u]].append(u)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degrees[u]
                    buckets[d].remove(u)
                    degrees[u] -= 1
                    buckets[degrees[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap attempt
    def kempe_swap(coloring, v, c1, c2):
        # Try to swap colors c1 and c2 in the Kempe chain starting at v
        if coloring[v] != c1:
            return False, coloring
        visited = [False] * n
        stack = [v]
        visited[v] = True
        component = []
        while stack:
            u = stack.pop()
            component.append(u)
            for w in adj_list[u]:
                if not visited[w] and (coloring[w] == c1 or coloring[w] == c2):
                    visited[w] = True
                    stack.append(w)
        # Check if swapping is safe: no neighbor of component has color c2 (if we are removing c1)
        # Actually, for Kempe chain, swapping always preserves validity
        # Perform swap
        new_coloring = coloring[:]
        for u in component:
            if new_coloring[u] == c1:
                new_coloring[u] = c2
            else:
                new_coloring[u] = c1
        return True, new_coloring

    # Attempt to eliminate a color class
    def eliminate_color(coloring, target_color):
        # Get vertices with target_color
        verts = [v for v in range(n) if coloring[v] == target_color]
        if not verts:
            return coloring  # already eliminated

        # Try to reassign each vertex to a lower color
        for v in verts:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            # Try direct reassignment to lowest available color < target_color
            for c in range(target_color):
                if not (used & (1 << c)):
                    # Move v to color c
                    coloring[v] = c
                    break
            else:
                # Direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    # Check if v can be moved to c via Kempe chain (c1=target_color, c2=c)
                    success, new_col = kempe_swap(coloring, v, target_color, c)
                    if success:
                        # Verify the move actually changes v's color to c
                        if new_col[v] == c:
                            coloring = new_col
                            break
                else:
                    # Could not reassign v, continue to next vertex
                    continue
                # If we broke out, reassignment succeeded, go to next vertex
                continue

        # Check if target_color is still used
        if any(coloring[v] == target_color for v in range(n)):
            return coloring  # could not eliminate
        # Compact colors
        return compact_colors(coloring)

    # Generate initial colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best initial coloring (fewest colors)
    best = min(candidates, key=num_colors)

    # Iterative color reduction
    k = num_colors(best)
    improved = True
    while improved and k > 0:
        improved = False
        # Try to eliminate highest color class first
        for target_color in range(k-1, -1, -1):
            new_coloring = eliminate_color(best[:], target_color)
            new_k = num_colors(new_coloring)
            if new_k < k:
                best = new_coloring
                k = new_k
                improved = True
                break  # restart from highest color

    # Final validation and compacting
    best = compact_colors(best)
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
        best = compact_colors(best)

    return best

