    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = coloring[u]
                if c != -1:
                    used |= (1 << c)
            # Find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation[v] = bitmask of colors used by colored neighbors
        saturation = [0] * n
        # degree in uncolored subgraph (initially full degree)
        uncolored_degree = [len(neighbors[v]) for v in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by max uncolored degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                deg = uncolored_degree[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                   (sat == best_sat and deg == best_deg and (best_v == -1 or random.random() < 0.5)):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_degree[u] -= 1
        return normalize(coloring)

    # Helper: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            # degree in current uncolored subgraph
            deg_uncolored = {v: 0 for v in uncolored}
            for v in uncolored:
                for u in neighbors[v]:
                    if u in uncolored:
                        deg_uncolored[v] += 1

            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - independent_set - neighbors[v]
            W = (uncolored - independent_set) & set(neighbors[v])

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U-induced subgraph
                best_u = -1
                best_score = -1
                best_deg_u = float('inf')
                for u in U:
                    # score = |N(u) ∩ W|
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # degree in U-induced subgraph
                    deg_u = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or \
                       (score == best_score and deg_u == best_deg_u and (best_u == -1 or random.random() < 0.5)):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent_set
            for v in independent_set:
                coloring[v] = color
            uncolored -= independent_set
            color += 1
        return normalize(coloring)

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Core decomposition to get ordering
        degree = [len(neighbors[v]) for v in range(n)]
        # Bin vertices by degree
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            bins[degree[v]].append(v)
        # Pointer to current non-empty bin
        ptr = 0
        ordering = []
        # Copy of degree for modification
        curr_degree = degree[:]
        removed = [False] * n

        for _ in range(n):
            # Find non-empty bin
            while ptr <= max_deg and not bins[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = bins[ptr].pop()
            removed[v] = True
            ordering.append(v)
            # Decrease degree of neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = curr_degree[u]
                    if d > 0:
                        curr_degree[u] -= 1
                        bins[d].append(u)
                        if d < ptr:
                            ptr = d
        # Color in reverse order
        return greedy_color(ordering[::-1])

    # Helper: Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, a, b, v):
        # Returns new coloring if swap is performed, else None
        # We only consider swapping the component containing v
        stack = [v]
        visited = set()
        component = set()
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            if coloring[node] == a or coloring[node] == b:
                component.add(node)
                for nb in neighbors[node]:
                    if nb not in visited and (coloring[nb] == a or coloring[nb] == b):
                        stack.append(nb)
        # Check if swapping is valid: no neighbor outside component has color a or b that would conflict
        # Actually, Kempe swap always preserves validity, so we can just swap
        new_coloring = coloring[:]
        for node in component:
            if new_coloring[node] == a:
                new_coloring[node] = b
            else:
                new_coloring[node] = a
        return new_coloring

    # Helper: try to eliminate the smallest color class using Kempe chains
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                continue
            # Try to recolor each target vertex to a lower color
            made_change = False
            for v in target_vertices:
                used_by_neighbors = 0
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        used_by_neighbors |= (1 << c)
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Assign v to color c
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    new_col = kempe_swap(coloring, target_color, c, v)
                    if new_col is not None:
                        # Check if v now has color c (i.e., was swapped)
                        if new_col[v] == c:
                            coloring[:] = new_col
                            made_change = True
                            break
                if made_change:
                    break
            if made_change:
                # Recurse to try further reduction
                return reduce_colors(coloring)
        # If no color can be eliminated, return current
        return normalize(coloring)

    # Generate candidate colorings
    candidates = []
    start_time = time.time()

    # DSATUR
    col1 = dsatur()
    if is_valid(col1):
        candidates.append(col1)
    # RLF
    col2 = rlf()
    if is_valid(col2):
        candidates.append(col2)
    # Smallest-Last
    col3 = smallest_last()
    if is_valid(col3):
        candidates.append(col3)

    # If no candidate (should not happen), fallback to greedy by index
    if not candidates:
        col = greedy_color(list(range(n)))
        candidates.append(col)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = normalize(best)

    # Apply Kempe chain reduction to try to improve
    if time.time() - start_time < 0.04:  # leave some time for reduction
        best = reduce_colors(best)

    # Final validation and normalization
    assert is_valid(best), "Invalid coloring produced"
    best = normalize(best)
    return best

