def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect if input is adjacency matrix
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Build adjacency list from matrix
        neighbors = []
        for i in range(n):
            neighbors.append([j for j in range(n) if adj[i][j] == 1])
    else:
        # Assume adjacency list
        neighbors = adj
        # Ensure it's a list of lists and symmetric (undirected)
        for i in range(n):
            if not isinstance(neighbors[i], list):
                neighbors[i] = list(neighbors[i])
            # Remove self-loops and duplicates
            neighbors[i] = list(set(j for j in neighbors[i] if j != i))
        # Ensure symmetry
        for i in range(n):
            for j in neighbors[i]:
                if i not in neighbors[j]:
                    neighbors[j].append(i)

    # Build complement graph adjacency list (as sets for fast lookup)
    comp_adj = [set() for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and j not in neighbors[i]:
                comp_adj[i].add(j)

    uncolored = set(range(n))
    color = [-1] * n
    current_color = 0

    while uncolored:
        # Start with vertex of max degree in complement (within uncolored)
        v = max(uncolored, key=lambda x: len(comp_adj[x] & uncolored))
        clique = {v}
        candidates = comp_adj[v] & uncolored

        # Greedily grow clique in complement graph
        while candidates:
            # Select vertex with most connections to current clique
            u = max(candidates, key=lambda x: len(comp_adj[x] & clique))
            clique.add(u)
            candidates = candidates & comp_adj[u]

        # Assign current color to all vertices in the clique (independent set in original)
        for u in clique:
            color[u] = current_color
            uncolored.remove(u)
        current_color += 1

    return color

