import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = [list(neigh) for neigh in adj]
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in adj_list[i]:
            mask |= (1 << j)
        bit_adj[i] = mask

    # Precompute triangle count for each vertex
    triangle_count = [0] * n
    for u in range(n):
        neighbors = adj_list[u]
        deg = len(neighbors)
        for i in range(deg):
            v = neighbors[i]
            if v <= u:
                continue
            for j in range(i + 1, deg):
                w = neighbors[j]
                if w <= u:
                    continue
                if (bit_adj[v] >> w) & 1:
                    triangle_count[u] += 1
                    triangle_count[v] += 1
                    triangle_count[w] += 1

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with bitmask and triangle tie-breaking
    def dsatur():
        color = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored, then triangle count
            best_v = -1
            best_sat = -1
            best_deg = -1
            best_tri = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                deg = sum(1 for u in adj_list[v] if u in uncolored)
                tri = triangle_count[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and tri > best_tri):
                    best_sat = sat
                    best_deg = deg
                    best_tri = tri
                    best_v = v
            v = best_v
            # Assign smallest available color
            avail = (~saturated[v]) & ((1 << n) - 1)
            c = (avail & -avail).bit_length() - 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u] |= (1 << c)
        return color

    # Strategy 2: RLF with bitmask
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S = {v}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v}
            nbrs_S = set()
            for u in S:
                nbrs_S.update(adj_list[u])
            W = U & nbrs_S
            U = U - W
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U
                best_u = -1
                best_score = -1
                best_degU = float('inf')
                for u in U:
                    # Count neighbors in W
                        score = sum(1 for w in adj_list[u] if w in W)
                    degU = sum(1 for w in adj_list[u] if w in U)
                    if score > best_score or (score == best_score and degU < best_degU):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Update W: add neighbors of u that are in U
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    if d < len(buckets):
                        buckets[d].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Triangle-based ordering (high triangle count first)
    def triangle_order():
        order = sorted(range(n), key=lambda x: (-triangle_count[x], -len(adj_list[x]), x))
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, triangle_order]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # Fallback: simple greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: (-len(adj_list[x]), x))
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(col)
        else:
            # Ultimate fallback: assign distinct colors
            col = list(range(n))
            candidates.append(col)

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)

    # Kempe chain color reduction
    def eliminate_color_class(coloring, k):
        # Try to eliminate color k-1
        target = k - 1
        vertices = [v for v in range(n) if coloring[v] == target]
        if not vertices:
            return coloring, k - 1
        # Try to recolor each vertex in target class
        for v in vertices:
            used = set()
            for u in adj_list[v]:
                c = coloring[u]
                if c != -1:
                    used.add(c)
            for c in range(target):
                if c not in used:
                    coloring[v] = c
                    break
            else:
                # Try Kempe chains
                for c in range(target):
                    # Find (c, target)-Kempe chain containing v
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    while stack:
                        x = stack.pop()
                        for y in adj_list[x]:
                            if y not in visited and coloring[y] in (c, target):
                                visited.add(y)
                                stack.append(y)
                    # Check if we can swap: no neighbor of v has color c outside the chain
                    conflict = False
                    for y in adj_list[v]:
                        if y not in visited and coloring[y] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Swap colors c and target in the component
                        for x in visited:
                            if coloring[x] == c:
                                coloring[x] = target
                            elif coloring[x] == target:
                                coloring[x] = c
                        coloring[v] = c
                        break
                else:
                    # Could not recolor v
                    return coloring, k
        # If we get here, all vertices recolored
        # Compact colors: shift down colors > target
        for v in range(n):
            if coloring[v] > target:
                coloring[v] -= 1
        return coloring, k - 1

    # Apply Kempe reduction iteratively
    current = best[:]
    k = num_colors(current)
    improved = True
    while improved and k > 1:
        improved = False
        new_coloring, new_k = eliminate_color_class(current[:], k)
        if new_k < k:
            current = new_coloring
            k = new_k
            improved = True
        else:
            break

    # Final validation and compacting
    if not is_valid(current):
        # Re-greedy if invalid
        order = sorted(range(n), key=lambda x: (-len(adj_list[x]), x))
        current = greedy_color(order)
    # Ensure colors are consecutive
    used = set(current)
    mapping = {c: i for i, c in enumerate(sorted(used))]
    current = [mapping[c] for c in current]

    return current

