    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for nb in adj_list[i]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            c = 0
            while c < n + 1 and used[c]:
                c += 1
            coloring[i] = c
        candidates.append(compact_colors(coloring))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: len(set(x)) if x else 0)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid_coloring(best):
        # Last resort: greedy
        coloring = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for nb in adj_list[i]:
                if coloring[nb] != -1:
                    used[coloring[nb]] = True
            c = 0
            while c < n + 1 and used[c]:
                c += 1
            coloring[i] = c
        best = compact_colors(coloring)
    else:
        best = compact_colors(best)
    return best

import math
