def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle trivial cases
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list for uniform processing
    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj

    # Precompute degrees
    degrees = [len(graph[i]) for i in range(n)]

    # Helper function: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            # Find colors used by neighbors
            used = [False] * n  # n colors is safe upper bound
            for u in graph[v]:
                if color[u] != -1:
                    used[color[u]] = True
            # Find smallest available color
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper function: count number of colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper function: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper function: apply 1-opt local search (try to reduce color of each vertex)
    def local_search_1opt(coloring):
        improved = True
        while improved:
            improved = False
            # Try to improve each vertex in random order
            order = list(range(n))
            random.shuffle(order)
            for v in order:
                used = [False] * (count_colors(coloring) + 1)  # +1 for safety
                for u in graph[v]:
                    if coloring[u] != -1:
                        used[coloring[u]] = True
                # Try to find a better color (smaller than current)
                for c in range(coloring[v]):
                    if not used[c]:
                        # Check if moving to color c is valid
                        valid = True
                        for u in graph[v]:
                            if coloring[u] == c:
                                valid = False
                                break
                        if valid:
                            coloring[v] = c
                            improved = True
                            break  # Move to next vertex after improvement
        return coloring

    # Helper function: apply Kempe chain swap to try to eliminate a color
    def kempe_reduce(coloring):
        k = count_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate the highest color (k-1)
        target_color = k - 1
        vertices_with_target = [v for v in range(n) if coloring[v] == target_color]

        # Try to recolor each vertex with target color
        for v in vertices_with_target:
            # Try direct reassignment to a lower color
            used = [False] * k
            for u in graph[v]:
                if coloring[u] != -1 and coloring[u] < k:
                    used[coloring[u]] = True

            for c in range(target_color):
                if not used[c]:
                    # Check if color c is available (no neighbor has it)
                    available = True
                    for u in graph[v]:
                        if coloring[u] == c:
                            available = False
                            break
                    if available:
                        coloring[v] = c
                        break
            else:
                # Direct reassignment failed, try Kempe chains
                for c in range(target_color):
                    # Find the Kempe chain (v, target_color) <-> (v, c)
                    # We'll try to swap colors in the component containing v
                    # Only consider vertices with color target_color or c
                    stack = [v]
                    visited = [False] * n
                    component = []
                    while stack:
                        node = stack.pop()
                        if visited[node]:
                            continue
                        visited[node] = True
                        if coloring[node] == target_color or coloring[node] == c:
                            component.append(node)
                            for neighbor in graph[node]:
                                if not visited[neighbor] and (coloring[neighbor] == target_color or coloring[neighbor] == c):
                                    stack.append(neighbor)

                    # Check if swapping would cause conflict: 
                    # After swap, no neighbor of any node in component should have the new color
                    # For nodes originally target_color -> become c: check no neighbor has c (outside component)
                    # For nodes originally c -> become target_color: check no neighbor has target_color (outside component)
                    valid_swap = True
                    for node in component:
                        orig_color = coloring[node]
                        new_color = c if orig_color == target_color else target_color
                        for neighbor in graph[node]:
                            if not visited[neighbor]:  # neighbor outside component
                                if coloring[neighbor] == new_color:
                                    valid_swap = False
                                    break
                        if not valid_swap:
                            break

                    if valid_swap:
                        # Perform the swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        break  # Successfully recolored v, move to next vertex
                else:
                    # Could not recolor v with any Kempe chain, keep it
                    pass

        # Reindex colors to be consecutive
        # Map colors to 0..k'-1
        color_map = {}
        next_color = 0
        for v in range(n):
            c = coloring[v]
            if c not in color_map:
                color_map[c] = next_color
                next_color += 1
            coloring[v] = color_map[c]

        return coloring

    # Main algorithm: multiple randomized greedy passes with local search
    best_coloring = None
    best_num_colors = float('inf')

    # Number of randomized trials
    num_trials = 10

    for _ in range(num_trials):
        # Create random vertex order (perturbed by degree)
        vertices = list(range(n))
        # Sort by degree descending, but add random noise for tie-breaking
        vertices.sort(key=lambda v: (-degrees[v], random.random()))

        # Apply greedy coloring
        coloring = greedy_color(vertices)

        # Apply local search to try to improve
        coloring = local_search_1opt(coloring)

        # Try to reduce number of colors using Kempe chains
        coloring = kempe_reduce(coloring)

        # Validate and update best
        if is_valid(coloring):
            num_colors = count_colors(coloring)
            if num_colors < best_num_colors:
                best_num_colors = num_colors
                best_coloring = coloring[:]

    # Fallback: if no valid coloring found (should not happen), use simple greedy
    if best_coloring is None:
        order = list(range(n))
        order.sort(key=lambda v: (-degrees[v], v))
        best_coloring = greedy_color(order)
        # Ensure validity (greedy should produce valid coloring)
        if not is_valid(best_coloring):
            # Emergency fix: assign unique colors
            best_coloring = list(range(n))

    # Final validation and color compaction
    if not is_valid(best_coloring):
        # Last resort: assign each vertex a unique color
        best_coloring = list(range(n))
    else:
        # Compact colors to be 0..k-1
        color_map = {}
        next_color = 0
        for v in range(n):
            c = best_coloring[v]
            if c not in color_map:
                color_map[c] = next_color
                next_color += 1
            best_coloring[v] = color_map[c]

    return best_coloring

