            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # saturation degree: number of distinct colors in neighborhood
        sat = [0] * n
        # neighbor color sets as bitmask for efficiency
        neighbor_colors = [0] * n

        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    if sat[u] > max_sat or (sat[u] == max_sat and len(adj_list[u]) > max_deg):
                        max_sat = sat[u]
                        max_deg = len(adj_list[u])
                        v = u
            if v == -1:  # should not happen
                break

            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True

            # update saturation and neighbor colors for neighbors
            for u in adj_list[v]:
                if not colored[u]:
                    # update neighbor color bitmask
                    neighbor_colors[u] |= (1 << c)
                    # update saturation degree: count bits in neighbor_colors[u]
                    sat[u] = neighbor_colors[u].bit_count()
        return compact_colors(colors)

    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.add(v)
            # partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and not any(w in adj_list[u] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}

            while U:
                # select u in U with max |N(u) ∩ W|
                u_star = max(U, key=lambda x: len([y for y in adj_list[x] if y in W]))
                # tie-break: min degree in G[U]
                candidates = [u for u in U if len([y for y in adj_list[u] if y in W]) == len([y for y in adj_list[u_star] if y in W])]
                u_star = min(candidates, key=lambda x: len([y for y in adj_list[x] if y in U]))
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star in U to W
                for nb in adj_list[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
