    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    # select best (fewest colors)
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Kempe chain-based color reduction
    def try_reduce_k(colors, target_k):
        # attempt to eliminate color target_k-1
        if target_k <= 0:
            return colors
        color_class = [i for i in range(n) if colors[i] == target_k - 1]
        if not color_class:
            return try_reduce_k(colors, target_k - 1)

        # try to recolor each vertex in color class
        for v in color_class:
            used_by_neighbors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used_by_neighbors |= (1 << colors[u])
            # find available color < target_k-1
            for c in range(target_k - 1):
                if not (used_by_neighbors & (1 << c)):
                    colors[v] = c
                    break
            else:
                # try Kempe chain swap with each color c < target_k-1
                for c in range(target_k - 1):
                    # find (c, target_k-1) Kempe chain containing v
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (colors[nb] == c or colors[nb] == target_k - 1):
                                visited[nb] = True
                                stack.append(nb)
                    # check if color c is not present in the component (so swap is safe)
                    has_c = any(colors[node] == c for node in component)
                    if not has_c:
                        # swap colors c and target_k-1 in component
                        for node in component:
                            if colors[node] == c:
                                colors[node] = target_k - 1
                            elif colors[node] == target_k - 1:
                                colors[node] = c
                        # now v has color c
                        break
                else:
                    continue  # only executed if inner loop did NOT break
                break  # break outer loop if we successfully recolored v
            else:
                # failed to recolor v, continue to next vertex in color class
                continue
            # if we broke out, we recolored v, so restart reduction attempt
            return try_reduce_k(colors, target_k)
        # if we exited loop without breaking, no vertex recolored
        return try_reduce_k(colors, target_k - 1)

    # Apply reduction
    reduced = try_reduce_k(best[:], k)
    if is_valid_coloring(reduced) and num_colors(reduced) < k:
        best = reduced
        k = num_colors(best)

    # Final validation and compacting
    if not is_valid_coloring(best):
        # fallback: greedy coloring by degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        best = compact_colors(colors)
    else:
        best = compact_colors(best)

    return best

