import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency bitmasks and neighbor lists
    bit_adj = [0] * n
    neighbors = [None] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
            neighbors[i] = [j for j in range(n) if adj[i][j] == 1]
    else:
        for i in range(n):
            mask = 0
            for j in adj[i]:
                mask |= (1 << j)
            bit_adj[i] = mask
            neighbors[i] = adj[i][:]

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    best_coloring = None
    best_k = float('inf')

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by max uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and uncolored_deg[u] > max_deg) or \
                   (s == max_sat and uncolored_deg[u] == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = s
                    max_deg = uncolored_deg[u]
                    v = u
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation and uncolored degree of neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            S = set()
            # vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # U: vertices not adjacent to S (eligible), W: adjacent to S (ineligible)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in S for w in neighbors[u]):
                    U.remove(u)
                    W.add(u)
            # while U not empty, add vertex with max neighbors in W, tie-break by min degree in U
            while U:
                best_u = -1
                max_w_neighbors = -1
                min_u_deg = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in neighbors[u] if w in W)
                    u_deg = sum(1 for w in neighbors[u] if w in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and u_deg < min_u_deg) or \
                       (w_neighbors == max_w_neighbors and u_deg == min_u_deg and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_u_deg = u_deg
                        best_u = u
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    buckets[d].remove(u)
                    buckets[d-1].append(u)
                    if d-1 < ptr:
                        ptr = d-1
        # color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_color(order)

    # Run all heuristics
    for coloring in [dsatur(), rlf(), smallest_last(), welsh_powell()]:
        if is_valid(coloring):
            k = num_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring[:]

    # If no valid coloring found (should not happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        # make copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (highest index) that is non-empty
            # we try to eliminate the largest color index first
            max_color = max(col) if col else -1
            for target_color in range(max_color, -1, -1):
                # collect vertices with this color
                verts = [v for v in range(n) if col[v] == target_color]
                if not verts:
                    continue
                # try to recolor each vertex in this class
                for v in verts:
                    # try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if col[u] != -1:
                            neighbor_colors.add(col[u])
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            col[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # try Kempe chain swap with each lower color
                    for c in range(target_color):
                        if c in neighbor_colors:
                            continue
                        # build (target_color, c) Kempe chain containing v
                        # BFS/DFS over vertices colored target_color or c
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if col[node] == target_color or col[node] == c:
                                component.add(node)
                                for nb in neighbors[node]:
                                    if col[nb] == target_color or col[nb] == c:
                                        if nb not in visited:
                                            stack.append(nb)
                        # check if swapping this component would not cause conflict
                        # i.e., no neighbor of any node in component has color c (if we swap target->c)
                        # or color target_color (if we swap c->target)
                        # Actually, swapping is safe if for every node in component,
                        # its neighbors not in component do not have the opposite color
                        safe = True
                        for node in component:
                            for nb in neighbors[node]:
                                if nb not in component:
                                    if col[node] == target_color and col[nb] == c:
                                        safe = False
                                        break
                                    if col[node] == c and col[nb] == target_color:
                                        safe = False
                                        break
                            if not safe:
                                break
                        if safe:
                            # perform swap
                            for node in component:
                                if col[node] == target_color:
                                    col[node] = c
                                else:
                                    col[node] = target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # if we made a change, restart from highest color
            if changed:
                break
        # compact colors: remap to 0..k-1
        # get unique colors used
        unique_colors = sorted(set(col))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        col = [mapping[c] for c in col]
        return col

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)
    # Final validation (should be valid)
    if not is_valid(best_coloring):
        # fallback to greedy if something went wrong
        best_coloring = greedy_color(list(range(n)))
    return best_coloring

