                        safe = True
                        for node in comp:
                            for u in range(n):
                                if (bit_adj[node] >> u) & 1 and not visited[u] and col[u] == c_low:
                                    safe = False
                                    break
                            if not safe:
                                break
                        if safe:
                            # swap colors c and c_low in component
                            for node in comp:
                                if col[node] == c:
                                    col[node] = c_low
                                else:
                                    col[node] = c
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                # compact again
                color_map = {}
                next_color = 0
                for i in range(n):
                    c = col[i]
                    if c not in color_map:
                        color_map[c] = next_color
                        next_color += 1
                    col[i] = color_map[c]
        return col

    # Apply Kempe reduction
    best = kempe_reduction(best)
    # Final validation (should be valid)
    for u in range(n):
        for v in range(u + 1, n):
            if (bit_adj[u] >> v) & 1 and best[u] == best[v]:
                # fallback to greedy on natural order if invalid
                return greedy_color(list(range(n)))
    return best

import math
