def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build bitmask adjacency and degree list
    bit_adj = [0] * n
    degree = [0] * n
    for u in range(n):
        if is_matrix:
            for v in range(n):
                if adj[u][v]:
                    bit_adj[u] |= (1 << v)
                    degree[u] += 1
        else:
            for v in adj[u]:
                bit_adj[u] |= (1 << v)
                degree[u] += 1

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in range(n):
                if (bit_adj[u] >> v) & 1:
                    c = color[v]
                    if c != -1:
                        used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree
        uncolored = set(range(n))
        # Initial: pick vertex with max degree
        if uncolored:
            u = max(uncolored, key=lambda x: degree[x])
            color[u] = 0
            uncolored.remove(u)
            # Update saturation of neighbors
            for v in range(n):
                if (bit_adj[u] >> v) & 1 and color[v] == -1:
                    sat[v] += 1
        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            u = max(uncolored, key=lambda x: (sat[x], degree[x], random.random()))
            # Find smallest available color
            used = 0
            for v in range(n):
                if (bit_adj[u] >> v) & 1:
                    c = color[v]
                    if c != -1:
                        used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
            uncolored.remove(u)
            # Update saturation of uncolored neighbors
            for v in range(n):
                if (bit_adj[u] >> v) & 1 and color[v] == -1:
                    sat[v] += 1
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                u = max(uncolored, key=lambda x: sum(1 for v in range(n) if (bit_adj[x] >> v) & 1 and v in uncolored))
                S.append(u)
                uncolored.remove(u)
            # Partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for v in uncolored:
                if any((bit_adj[v] >> s) & 1 for s in S):
                    W.add(v)
                else:
                    U.add(v)
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                def score(u):
                    w_neighbors = sum(1 for v in range(n) if (bit_adj[u] >> v) & 1 and v in W)
                    u_degree = sum(1 for v in range(n) if (bit_adj[u] >> v) & 1 and v in U)
                    return (w_neighbors, -u_degree, random.random())
                u = max(U, key=score)
                S.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for v in list(U):
                    if (bit_adj[u] >> v) & 1:
                        U.remove(v)
                        W.add(v)
            # Assign color c to all in S
            for u in S:
                color[u] = c
            c += 1
        return color

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree_copy = degree[:]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree_copy[v]].append(v)
        # Pointer to current min non-empty bucket
        min_deg = 0
        for _ in range(n):
            # Find next non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in range(n):
                if (bit_adj[v] >> u) & 1 and u in remaining:
                    d = degree_copy[u]
                    if d > 0:
                        buckets[d].remove(u)
                        degree_copy[u] -= 1
                        buckets[degree_copy[u]].append(u)
        # Color in reverse order
        return greedy_color(reversed(order))

    # Helper: Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-degree[x], x))
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    candidates.append(welsh_powell())

    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate
        valid = True
        for u in range(n):
            for v in range(n):
                if (bit_adj[u] >> v) & 1:
                    if col[u] == col[v]:
                        valid = False
                        break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col[:]

    # Fallback: if no candidate valid (should not happen), use greedy on natural order
    if best_color is None:
        best_color = greedy_color(list(range(n)))
        best_k = max(best_color) + 1 if n > 0 else 0

    # Kempe chain-based color reduction
    def kempe_reduce(color_in):
        color = color_in[:]
        while True:
            # Find smallest non-empty color class
            classes = [[] for _ in range(best_k)]
            for v in range(n):
                if color[v] < best_k:
                    classes[color[v]].append(v)
            # Find the smallest color class (by size) that is non-empty
            target_color = -1
            min_size = float('inf')
            for c in range(best_k):
                if classes[c] and len(classes[c]) < min_size:
                    min_size = len(classes[c])
                    target_color = c
            if target_color == -1:  # no colored vertices
                break
            # Try to recolor each vertex in target_color
            removed = False
            for v in classes[target_color][:]:  # iterate over copy
                used = 0
                for u in range(n):
                    if (bit_adj[v] >> u) & 1:
                        c = color[u]
                        if c != -1:
                            used |= (1 << c)
                # Try direct reassignment to a smaller color
                for c in range(target_color):
                    if not (used & (1 << c)):
                        color[v] = c
                        removed = True
                        break
                if removed:
                    break
                # Try Kempe chain swap with each smaller color
                for c in range(target_color):
                    # If v already has color c after possible direct reassignment, skip
                    if color[v] == c:
                        continue
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # We do BFS/DFS on the subgraph induced by vertices of color target_color or c
                    from collections import deque
                    comp = []
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    while queue:
                        x = queue.popleft()
                        comp.append(x)
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1:
                                if color[y] == target_color or color[y] == c:
                                    if not visited[y]:
                                        visited[y] = True
                                        queue.append(y)
                    # Check if swapping colors in this component is safe:
                    # After swap, no adjacent vertices should have same color.
                    # Since we only swap two colors, it's safe if no neighbor outside the component
                    # has the color we are swapping to.
                    # Actually, Kempe swap always preserves validity for the two colors.
                    # But we want to free color target_color for v.
                    # After swap, v will have color c.
                    # We need to ensure that no neighbor of v has color c after swap.
                    # Neighbors of v in the component: their color will flip (target_color<->c)
                    # Neighbors of v outside the component: color unchanged.
                    # So, if any neighbor outside the component has color c, then after swap,
                    # v (now color c) and that neighbor (still color c) would conflict.
                    safe = True
                    for x in comp:
                        for y in range(n):
                            if (bit_adj[x] >> y) & 1:
                                if color[y] == c and y not in comp:
                                    safe = False
                                    break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for x in comp:
                            if color[x] == target_color:
                                color[x] = c
                            elif color[x] == c:
                                color[x] = target_color
                        removed = True
                        break
                if removed:
                    break
            if not removed:
                break  # cannot eliminate this color class
            # Compact colors: remove target_color and shift down higher colors
            # Build mapping from old color to new color
            mapping = {}
            new_c = 0
            for old_c in range(best_k):
                if old_c == target_color:
                    continue
                mapping[old_c] = new_c
                new_c += 1
            # Recolor
            for v in range(n):
                if color[v] < best_k:
                    if color[v] == target_color:
                        # should not happen, as we removed the class
                        color[v] = 0  # arbitrary, but will be remapped
                    else:
                        color[v] = mapping[color[v]]
            best_k -= 1
        return color

    # Apply Kempe reduction
    best_color = kempe_reduce(best_color)
    # Ensure colors are consecutive
    # Remap to 0..k-1
    unique_colors = {}
    next_color = 0
    for v in range(n):
        c = best_color[v]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_color[v] = unique_colors[c]
    return best_color

