                    degree[v] -= 1
                    dnew = degree[v]
                    buckets[dnew].append(v)
                    pos[v] = len(buckets[dnew]) - 1
            remaining.remove(u)
            # update min_deg if needed
            if min_deg > degree[u]:
                min_deg = degree[u]
        # Now color in reverse order
        colors = [-1] * n
        for u in reversed(order):
            used = 0
            for v in graph[u]:
                if colors[v] != -1:
                    used |= 1 << colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            target_color = k - 1
            # Get vertices with target color
            target_vertices = [u for u in range(n) if colors[u] == target_color]
            if not target_vertices:
                # Already compacted?
                return compact_colors(colors)
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in graph[v]:
                    if colors[u] < target_color:
                        neighbor_colors.add(colors[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Direct move possible
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Skip if c is already in neighborhood (direct move not possible)
                    neighbor_colors = set()
                    for u in graph[v]:
                        if colors[u] == c:
                            neighbor_colors.add(c)
                    if c in neighbor_colors:
                        continue
                    # Build Kempe chain for colors (target_color, c) starting from v
                    # We want to swap in the component of v if it does not contain any vertex of color c
                    # that is adjacent to v? Actually, we check if the component of v in the (target_color, c) subgraph
                    # does not reach any neighbor of v that has color c? Standard: if swapping the component of v
                    # does not cause conflict, we can do it.
                    # We'll BFS/DFS over vertices colored target_color or c
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        u = stack.pop()
                        if u in visited:
                            continue
                        visited.add(u)
                        if colors[u] == target_color or colors[u] == c:
                            component.add(u)
                            for w in graph[u]:
                                if w not in visited and (colors[w] == target_color or colors[w] == c):
                                    stack.append(w)
                    # Check if any neighbor of v with color c is in this component
                    conflict = False
                    for w in graph[v]:
                        if colors[w] == c and w in component:
                            conflict = True
                            break
                    if not conflict:
                        # Swap colors in component
                        for u in component:
                            if colors[u] == target_color:
                                colors[u] = c
                            else:
                                colors[u] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                colors = compact_colors(colors)
                k = num_colors(colors)
            else:
                break
        return colors

    # Run all heuristics
    best_colors = None
    best_k = float('inf')
    for func in [dsatur, rlf, smallest_last]:
        try:
            cols = func()
            if is_valid(cols):
                k = num_colors(cols)
                if k < best_k:
                    best_k = k
                    best_colors = cols
        except Exception:
            continue
    # Fallback: greedy random order
    if best_colors is None:
        order = list(range(n))
        random.shuffle(order)
        colors = [-1] * n
        for u in order:
            used = 0
            for v in graph[u]:
                if colors[v] != -1:
                    used |= 1 << colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        best_colors = compact_colors(colors)
    # Apply Kempe reduction
    best_colors = kempe_reduce(best_colors)
    # Final validation and compact
    if not is_valid(best_colors):
        # As last resort, use greedy with degree order
        order = sorted(range(n), key=lambda u: len(graph[u]), reverse=True)
        colors = [-1] * n
        for u in order:
            used = 0
            for v in graph[u]:
                if colors[v] != -1:
                    used |= 1 << colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        best_colors = compact_colors(colors)
    return best_colors

