def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix: square and binary entries (0/1)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True
    # Build neighbor list
    if is_matrix:
        neighbors = [ [j for j in range(n) if adj[i][j] == 1] for i in range(n) ]
    else:
        neighbors = [ list(lst) for lst in adj ]  # copy to avoid mutation
    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for i in range(n):
        mask = 0
        for j in neighbors[i]:
            mask |= (1 << j)
        bit_adj[i] = mask
    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True
    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # Helper: convert coloring to consecutive indices starting at 0
    def normalize(coloring):
        if not coloring:
            return coloring
        # map used colors to 0..k-1
        used = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in used:
                used[c] = next_color
                next_color += 1
            coloring[i] = used[c]
        return coloring
    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation sets: for each vertex, bitmask of colors used by neighbors
        sat = [0] * n
        colored = [False] * n
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                s = sat[v].bit_count()
                # degree in uncolored subgraph: count uncolored neighbors
                deg = 0
                for u in neighbors[v]:
                    if not colored[u]:
                        deg += 1
                if s > best_sat or (s == best_sat and deg > best_deg) or (s == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = s
                    best_deg = deg
                    best_v = v
            v = best_v
            # find smallest color not used by neighbors
            used_mask = 0
            for u in neighbors[v]:
                if colored[u]:
                    used_mask |= (1 << coloring[u])
            c = 0
            while used_mask & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True
            # update saturation of neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    sat[u] |= (1 << c)
        return coloring
    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        coloring = [-1] * n
        colored = [False] * n
        color = 0
        while not all(colored):
            # R: uncolored vertices
            R = [v for v in range(n) if not colored[v]]
            if not R:
                break
            # degree in induced subgraph G[R]
            deg_R = [0] * n
            for v in R:
                cnt = 0
                for u in neighbors[v]:
                    if not colored[u]:
                        cnt += 1
                deg_R[v] = cnt
            # pick vertex with max degree in R
            v1 = max(R, key=lambda x: deg_R[x])
            S = [v1]
            colored[v1] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for v in R:
                if v == v1:
                    continue
                adjacent = False
                for u in S:
                    if v in neighbors[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(v)
                else:
                    U.add(v)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    # score: number of neighbors in W
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # degree in U (for tie-break)
                    deg_U = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or (score == best_score and deg_U == best_deg_U and random.random() < 0.5):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.append(u)
                colored[u] = True
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
        return coloring
    # Smallest-Last ordering (Matula & Beck) greedy
    def smallest_last():
        # compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        degree = [len(neighbors[v]) for v in range(n)]
        order = []
        # we will simulate removal
        # copy degrees because we will modify
        deg = degree[:]
        # adjacency sets for fast lookup
        adj_set = [set(neighbors[v]) for v in range(n)]
        for _ in range(n):
            # find vertex with minimum degree in remaining
            min_v = -1
            min_deg = float('inf')
            for v in remaining:
                if deg[v] < min_deg:
                    min_deg = deg[v]
                    min_v = v
            if min_v == -1:
                break
            order.append(min_v)
            remaining.remove(min_v)
            # update degrees of neighbors
            for u in adj_set[min_v]:
                if u in remaining:
                    deg[u] -= 1
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)  # enough space
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        return coloring
    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass
    # If no candidate (should not happen), fallback to greedy by index
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while used[c]:
                c += 1
            coloring[v] = c
        candidates.append(coloring)
    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    best = normalize(best)
    # Iterative Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # find smallest color class (non-empty)
            color_classes = [[] for _ in range(n)]  # at most n colors
            for v in range(n):
                c = col[v]
                color_classes[c].append(v)
            # find the highest color that is used (we try to eliminate from high to low)
            # but we target the smallest color class (fewest vertices) to eliminate
            # Actually, we try to eliminate the last color if possible, but we can try any color.
            # We'll try to reduce the total number of colors by eliminating the highest color index if possible.
            # Determine current number of colors
            k = num_colors(col)
            if k <= 1:
                break
            # Try to eliminate color k-1
            target_color = k - 1
            targets = color_classes[target_color]
            if not targets:
                # should not happen because k is max+1
                break
            # Try to recolor each target vertex to a lower color if possible
            for v in targets:
                # try direct reassignment to any color < target_color
                neighbor_colors = set()
                for u in neighbors[v]:
                    if col[u] < target_color:
                        neighbor_colors.add(col[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        col[v] = c
                        changed = True
                        break
                if changed:
                    # after moving v, we need to update and break to restart
                    break
            if changed:
                continue
            # If no direct move, try Kempe chains for each target vertex and each lower color
            for v in targets:
                for c in range(target_color):
                    # Check if v can be recolored to c via Kempe chain swap
                    # Only consider if there is no neighbor of v with color c (otherwise swap would cause conflict)
                    has_neighbor_c = False
                    for u in neighbors[v]:
                        if col[u] == c:
                            has_neighbor_c = True
                            break
                    if has_neighbor_c:
                        continue
                    # We will attempt to swap colors c and target_color in the Kempe chain of v
                    # Build the component containing v in the subgraph induced by colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in neighbors[node]:
                            if not visited[nb] and (col[nb] == c or col[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any neighbor of the component has color c (outside the component)
                    # Actually, we need to ensure that swapping does not cause conflict:
                    # After swap, vertices in component originally color c become target_color, and vice versa.
                    # Conflict arises if a vertex in component that was color c has a neighbor outside component with color target_color,
                    # or a vertex that was target_color has a neighbor outside with color c.
                    # But we already checked that v has no neighbor with color c.
                    # However, other vertices in the component might have neighbors with color c or target_color outside.
                    # We need to verify that the swap is safe.
                    safe = True
                    for node in component:
                        if col[node] == c:
                            # after swap, becomes target_color; check neighbors for target_color outside component
                            for nb in neighbors[node]:
                                if not visited[nb] and col[nb] == target_color:
                                    safe = False
                                    break
                            if not safe:
                                break
                        else:  # col[node] == target_color
                            # after swap, becomes c; check neighbors for c outside component
                            for nb in neighbors[node]:
                                if not visited[nb] and col[nb] == c:
                                    safe = False
                                    break
                            if not safe:
                                break
                    if safe:
                        # perform swap
                        for node in component:
                            if col[node] == c:
                                col[node] = target_color
                            else:
                                col[node] = c
                        changed = True
                        break
                if changed:
                    break
            if not changed:
                # cannot reduce further
                break
        return col
    # Apply Kempe reduction
    best = kempe_reduce(best)
    best = normalize(best)
    # Final validation (should be valid)
    if not is_valid(best):
        # fallback to DSATUR if something went wrong
        best = dsatur()
        best = normalize(best)
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper function to validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper function to compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map used colors to 0..k-1
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR algorithm
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor_colors[v] = bitmask of colors used by neighbors
        neighbor_colors = [0] * n

        # Precompute degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]

        # Order of coloring
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    if saturation[u] > max_sat or \
                       (saturation[u] == max_sat and degrees[u] > max_deg) or \
                       (saturation[u] == max_sat and degrees[u] == max_deg and random.random() < 0.5):
                        max_sat = saturation[u]
                        max_deg = degrees[u]
                        v = u
            if v == -1:
                break  # Should not happen

            # Find smallest available color (mex)
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

            # Update neighbors of v
            for u in adj_list[v]:
                if colors[u] == -1:
                    # Add color c to neighbor's neighbor_colors if not present
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        saturation[u] += 1
        return compact_colors(colors)

    # RLF algorithm
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        color_idx = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for color_idx
            # R: uncolored vertices
            R = set(uncolored)
            S = []  # independent set for this color

            if not R:
                break

            # Step 2: choose vertex with max degree in G[R]
            v = max(R, key=lambda x: len([y for y in adj_list[x] if y in R]))
            S.append(v)
            R.remove(v)

            # Partition R into U (not adjacent to S) and W (adjacent to S)
            U = set()
            W = set()
            for u in R:
                adjacent_to_S = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)

            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = len([y for y in adj_list[u] if y in U])
                    if w_count > max_w_neighbors or \
                       (w_count == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_count == max_w_neighbors and deg_in_U == min_deg_in_U and random.random() < 0.5):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # Should not happen

                # Add best_u to S, remove from U, move its U-neighbors to W
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u that are in U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # Assign color_idx to all in S
            for vertex in S:
                colors[vertex] = color_idx
                uncolored.remove(vertex)
            color_idx += 1

        return compact_colors(colors)

    # Smallest-Last (Matula-Beck) greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []  # will be peeled order (smallest last)

        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d <= max_deg:
                buckets[d].add(v)

        for _ in range(n):
            # Find first non-empty bucket from low to high
            v = None
            for d in range(len(buckets)):
                if buckets[d]:
                    v = buckets[d].pop()
                    break
            if v is None:
                break
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # Remove u from its current bucket
                    old_deg = degree[u]
                    if old_deg < len(buckets):
                        buckets[old_deg].discard(u)
                    degree[u] -= 1
                    new_deg = degree[u]
                    if new_deg < len(buckets):
                        buckets[new_deg].add(u)
            remaining.remove(v)

        # Color in reverse order (largest degree first)
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

        return compact_colors(colors)

    # Kempe chain elimination
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        changed = True
        # We'll try to reduce colors until no improvement
        while changed:
            changed = False
            max_color = max(current) if current else -1
            if max_color < 0:
                break
            # Try to eliminate color classes from highest to lowest
            for target_color in range(max_color, -1, -1):
                # Collect vertices with target_color
                targets = [i for i in range(n) if current[i] == target_color]
                if not targets:
                    continue
                # Try to recolor each target vertex
                eliminated = True
                for v in targets:
                    # Check if v can take any color < target_color
                    used_by_neighbors = 0
                    for u in adj_list[v]:
                        if current[u] != -1:
                            used_by_neighbors |= (1 << current[u])
                    # Find smallest available color < target_color
                    found = False
                    for c in range(target_color):
                        if not (used_by_neighbors & (1 << c)):
                            # Recolor v to c
                            current[v] = c
                            found = True
                            break
                    if not found:
                        eliminated = False
                        break
                if eliminated:
                    # Successfully eliminated target_color, compact and restart
                    current = compact_colors(current)
                    changed = True
                    break  # Restart the while loop from beginning
        return current

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        col1 = dsatur()
        if is_valid(col1):
            candidates.append(col1)
    except:
        pass

    # RLF
    try:
        col2 = rlf()
        if is_valid(col2):
            candidates.append(col2)
    except:
        pass

    # Smallest-Last
    try:
        col3 = smallest_last()
