                adjacent = False
                for w in independent_set:
                    if w in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)

            # Greedily add vertices from U
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
