                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in independent_set
            for u in independent_set:
                coloring[u] = color
                uncolored.remove(u)
            color += 1
        return coloring

    # Smallest-Last (Matula-Beck) ordering greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []  # will store removal order
        # We'll use a list of sets for buckets by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for i in range(n):
            d = degree[i]
            buckets[d].add(i)

        for _ in range(n):
            # Find first non-empty bucket from low to high
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # remove u from its current degree bucket
                    old_deg = degree[u]
                    buckets[old_deg].remove(u)
                    degree[u] -= 1
                    new_deg = degree[u]
                    if new_deg >= len(buckets):
                        # extend buckets if needed
                        buckets.extend([set() for _ in range(new_deg - len(buckets) + 1)])
                    buckets[new_deg].add(u)
            remaining.remove(v)

