                    # so we need that no neighbor of v has color c (after swap, neighbors that were c become target_color)
                    # But note: neighbors of v that are in the component and have color c will become target_color,
                    # and neighbors of v that are target_color will become c.
                    # So after swap, v's color becomes c. We need that no neighbor of v has color c after swap.
                    # After swap:
                    #   - neighbors that were target_color become c
                    #   - neighbors that were c become target_color
                    #   - others unchanged
                    # So a neighbor of v will have color c after swap if:
                    #   - it was target_color and is in the component (so becomes c), OR
                    #   - it was c and is NOT in the component (so remains c)
                    # Therefore, to avoid conflict, we need:
                    #   No neighbor of v that is target_color is in the component (because they'd become c)
                    #   AND no neighbor of v that is c is outside the component (because they'd remain c)
                    # However, note that v itself is target_color and in component, but we are recoloring v.
                    # Actually, we are checking if we can recolor v to c via this swap. After swap, v becomes c.
                    # So we need that no neighbor of v has color c after the swap.
                    conflict = False
                    for nb in adj_list[v]:
                        if coloring[nb] == target_color:
                            if nb in component:  # becomes c after swap
                                conflict = True
                                break
                        elif coloring[nb] == c:
                            if nb not in component:  # remains c after swap
                                conflict = True
                                break
                    if not conflict:
                        # Perform the swap: swap colors target_color and c in the component
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            elif coloring[node] == c:
                                coloring[node] = target_color
                        improved = True
                        break
                if improved:
                    break

            if improved:
                # Compact colors and repeat
                coloring = compact_colors(coloring)
                k = num_colors(coloring)
            else:
                # Could not eliminate target color, break
                break

        return coloring

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
