    def dsatur():
        color = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        # Initial vertex: highest degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            color[v] = 0
            saturated[v] = 1 << 0
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] |= (1 << 0)
        while uncolored:
            # Select vertex with max saturation degree, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (
                saturated[x].bit_count(),
                len([y for y in neighbors[x] if y in uncolored]),
                -x  # lower index preferred if tie
            ))
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] |= (1 << c)
        return color

