            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S = {v}
            uncolored.remove(v)
            # W: vertices adjacent to S
            W = set()
            for u in neighbors[v]:
                if u in uncolored:
                    W.add(u)
            # U: vertices not adjacent to S
            U = uncolored - W
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(U, key=lambda x: (
                    len([y for y in neighbors[x] if y in W]),
                    -len([y for y in neighbors[x] if y in U]),  # min degree in U -> negative for max
                    -x
                ))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for vertex in S:
                color[vertex] = c
            c += 1
            uncolored = W  # next round
        return color

