        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # We'll simulate peeling
        temp_deg = degree[:]
        remaining_set = set(remaining)
        for _ in range(n):
            # find vertex with min temp_deg in remaining_set
            v = min(remaining_set, key=lambda x: (temp_deg[x], x))
            order.append(v)
            remaining_set.remove(v)
            for u in neighbors[v]:
                if u in remaining_set:
                    temp_deg[u] -= 1
        # Color in reverse order
        return greedy_color(reversed(order))

    # Kempe chain swap for colors a and b, starting from vertex v, returns new coloring if swap performed
    def kempe_swap(coloring, v, a, b):
        if coloring[v] not in (a, b):
            return coloring  # should not happen
        # Find the (a,b)-Kempe chain containing v
        stack = [v]
        visited = set()
        component = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if coloring[u] in (a, b):
                component.add(u)
                for w in neighbors[u]:
                    if w not in visited and coloring[w] in (a, b):
                        stack.append(w)
        # Try to swap colors in component
        new_coloring = coloring[:]
        for u in component:
            if new_coloring[u] == a:
                new_coloring[u] = b
            else:
                new_coloring[u] = a
        # Validate (should always be valid, but check)
        if is_valid(new_coloring):
            return new_coloring
        return coloring  # fallback

    # Attempt to eliminate the last color via Kempe chains or reassignment
    def reduce_colors(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target = k - 1
        vertices = [v for v in range(n) if coloring[v] == target]
        # Try direct reassignment first
        for v in vertices:
            used = 0
            for u in neighbors[v]:
                c = coloring[u]
                if c != -1:
                    used |= (1 << c)
            for c in range(target):  # try colors 0..target-1
                if not (used & (1 << c)):
                    # Recolor v to c
                    new_coloring = coloring[:]
                    new_coloring[v] = c
                    if is_valid(new_coloring):
                        return reduce_colors(new_coloring)  # recurse
        # Try Kempe chain swaps
        for v in vertices:
            for c in range(target):
                new_coloring = kempe_swap(coloring, v, target, c)
                if new_coloring is not coloring and num_colors(new_coloring) < k:
                    return reduce_colors(new_coloring)
        return coloring  # cannot reduce

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # Fallback: simple greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: (-len(neighbors[x]), x))
        candidates.append(greedy_color(order))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = reduce_colors(best)

    # Ensure colors are compact 0..k-1
    # Remap colors to consecutive integers
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best[i] = unique_colors[c]
    return best

