    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and compute degrees
    graph = [[] for _ in range(n)]
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    graph[u].append(v)
    else:
        for u in range(n):
            graph[u] = list(adj[u])  # copy to avoid modifying input

    deg = [len(graph[u]) for u in range(n)]

    # Special case: no edges
    if all(d == 0 for d in deg):
        return [0] * n

    # Smallest-last ordering (Matula & Beck, 1983)
    # Repeatedly remove vertex of minimum degree, push to stack
    current_deg = deg[:]  # current degrees in the remaining graph
    removed = [False] * n
    order = []  # will hold vertices in removal order (first removed first in list)

    for _ in range(n):
        # Find vertex with minimum current degree among unremoved
        min_deg = float('inf')
        v = -1
        for u in range(n):
            if not removed[u] and current_deg[u] < min_deg:
                min_deg = current_deg[u]
                v = u
        if v == -1:  # should not happen
            break
        removed[v] = True
        order.append(v)
        # Decrease degree of neighbors
        for nb in graph[v]:
            if not removed[nb]:
                current_deg[nb] -= 1

    # Color in reverse order (last removed first) with First-Fit
    color = [-1] * n
    for v in reversed(order):
        # Collect colors used by already colored neighbors
        used = [False] * n  # n is safe upper bound on colors needed
        for nb in graph[v]:
            c = color[nb]
            if c != -1:
                used[c] = True
        # Find smallest non-negative integer not used
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c

    return color

