                    coloring[v] = c
                    made_change = True
                    break
            if made_change:
                # after recoloring v, we may have emptied the last color, but continue to try others
                continue
            # try Kempe swaps with each lower color
            for c in range(k-1):
                if kempe_swap(coloring, v, k-1, c):
                    made_change = True
                    break
        # compact colors if last color class is empty
        if not any(coloring[v] == k-1 for v in range(n)):
            # remap colors > k-1? Actually we only use 0..k-1, so just decrement if above
            for v in range(n):
                if coloring[v] > k-1:
                    coloring[v] -= 1
            return coloring, True
        return coloring, made_change

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass

    # Smallest-last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy by index
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)

    # Iterative Kempe chain reduction
    improved = True
    while improved and num_colors(best) > 1:
        best, improved = eliminate_last_color(best)

    # Ensure consecutive colors (should already be, but remap just in case)
    used_colors = set(best)
    mapping = {old: new for new, old in enumerate(sorted(used_colors)))
    best = [mapping[c] for c in best]

    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Convert input to adjacency list
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = [list(neigh) for neigh in adj]

    # Helper: DSATUR with bitmask optimization
    def dsatur():
        if n == 0:
            return []
        color = [-1] * n
        sat = [0] * n
        deg = [len(graph[i]) for i in range(n)]
        uncolored = set(range(n))
        bit_adj = [0] * n
        for i in range(n):
            for j in graph[i]:
                bit_adj[i] |= (1 << j)

        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            v = max(uncolored, key=lambda x: (sat[x], deg[x], random.random()))
            # Compute used colors by neighbors
            used = 0
            for u in graph[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            # Find smallest free color
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in graph[v]:
                if u in uncolored:
                    sat[u] = bin(used | (1 << c)).count("1")
        return color

    # Helper: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set S for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in graph[x] if y in uncolored))
            S.add(v)
            # Partition U (eligible) and W (ineligible)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in S for w in graph[u]):
                    W.add(u)
                    U.remove(u)
            # Grow S
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = max(U, key=lambda x: (sum(1 for y in graph[x] if y in W), -sum(1 for y in graph[x] if y in U)))
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for y in graph[u_star]:
                    if y in U:
                        W.add(y)
                        U.remove(y)
            # Assign color c to S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering greedy
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering (smallest-last)
        deg = [len(graph[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(deg) if deg else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current min non-empty bucket
        ptr = 0
        while remaining:
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in graph[v]:
                if u in remaining:
                    deg[u] -= 1
                    if deg[u] < len(buckets):
                        buckets[deg[u]].append(u)
                    else:
                        # Should not happen if deg[u] < len(buckets) initially
                        pass
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for u in graph[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Run all heuristics and pick best (fewest colors)
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    # Select candidate with minimal number of colors
    best = min(candidates, key=lambda col: len(set(col)))
    k = len(set(best))

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        nonlocal n, graph
        color = coloring[:]
        changed = True
        while changed:
            changed = False
            # Try to eliminate the highest color class
            max_color = max(color) if color else -1
            if max_color < 0:
                return color
            # Vertices with max_color
            v_max = [v for v in range(n) if color[v] == max_color]
            if not v_max:
                # Compact colors
                mapping = {}
                next_c = 0
                for v in range(n):
                    if color[v] not in mapping:
                        mapping[color[v]] = next_c
                        next_c += 1
                    color[v] = mapping[color[v]]
                continue
            # Try to recolor each v in v_max
            for v in v_max:
                # Try direct reassignment to a lower color
                used = 0
                for u in graph[v]:
                    if color[u] != -1:
                        used |= (1 << color[u])
                for c in range(max_color):
                    if not (used & (1 << c)):
                        color[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(max_color):
                    # Build (c, max_color)-Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in graph[x]:
                            if not visited[y] and (color[y] == c or color[y] == max_color):
                                visited[y] = True
                                queue.append(y)
                    # Check if swapping this component frees color c for v
                    # After swap, v would get color c; check if any neighbor has color c
                    conflict = False
                    for x in component:
                        for y in graph[x]:
                            if y not in component and color[y] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Perform swap
                        for x in component:
                            if color[x] == c:
                                color[x] = max_color
                            elif color[x] == max_color:
                                color[x] = c
                        changed = True
                        break
                if changed:
                    break
            if not changed:
                # Compact colors if max_color class not eliminated but we try to reduce
                # Actually, if we cannot eliminate, we stop
                break
        # Final compacting
        mapping = {}
        next_c = 0
        for v in range(n):
            if color[v] not in mapping:
                mapping[color[v]] = next_c
                next_c += 1
            color[v] = mapping[color[v]]
        return color

    best = kempe_reduce(best)
    # Final validation (optional, but safe)
    for u in range(n):
        for v in graph[u]:
            if u < v and color[u] == color[v]:
                # Fallback to DSATUR if invalid (should not happen)
                return dsatur()
    return best

