def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert to consecutive colors starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # Candidate 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u].bit_count()
                deg_u = uncolored_deg[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            # assign smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Candidate 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # degree in uncolored subgraph
            deg_uncolored = [0] * n
            for u in uncolored:
                for v in adj_list[u]:
                    if v in uncolored:
                        deg_uncolored[u] += 1
            # pick vertex with max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any((bit_adj[u] >> w) & 1 for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # degree in U
                    deg_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_U += 1
                    if w_count > max_w_neighbors or \
                       (w_count == max_w_neighbors and deg_U < min_deg_U) or \
                       (w_count == max_w_neighbors and deg_U == min_deg_U and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_count
                        min_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Candidate 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(adj_list[i]) for i in range(n)]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    # move u to lower bucket
                    if d < len(buckets):
                        buckets[d].append(u)
                    if deg[u] < ptr:
                        ptr = deg[u]
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate initial candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except:
            continue

    # Fallback: simple greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(col)

    # Select best candidate (fewest colors)
    best_coloring = min(candidates, key=num_colors) if candidates else [0]*n
    best_coloring = normalize(best_coloring)
    k = num_colors(best_coloring)

    # Iterative color reduction: try to eliminate highest color class
    improved = True
    while improved and k > 1:
        improved = False
        target_color = k - 1
        # vertices with target color
        target_vertices = [v for v in range(n) if best_coloring[v] == target_color]
        random.shuffle(target_vertices)  # randomize order for robustness
        # Try to recolor each target vertex
        for v in target_vertices:
            # Try direct reassignment to a lower color
            used_by_neighbors = 0
            for u in adj_list[v]:
                c = best_coloring[u]
                if c != -1:
                    used_by_neighbors |= (1 << c)
            for c in range(target_color):  # try colors 0 to target_color-1
                if not (used_by_neighbors & (1 << c)):
                    # reassign v to color c
                    best_coloring[v] = c
                    improved = True
                    break
            if improved:
                # after reassignment, check if target color class is empty
                if any(best_coloring[u] == target_color for u in range(n)):
                    # still some vertices with target color, continue trying
                    pass
                else:
                    # target color eliminated, compact colors
                    k -= 1
                    # remap colors: any color > target_color shifted down? 
                    # but we only removed target_color, so colors > target_color should be shifted down by 1
                    for u in range(n):
                        if best_coloring[u] > target_color:
                            best_coloring[u] -= 1
                    break  # restart while loop with new k
            else:
                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Build Kempe chain for colors (c, target_color) starting from v
                    # We want to see if we can swap in the component of v to free color c for v
                    # Actually, we want to check if v is not connected to any vertex of color c via a Kempe chain
                    # Standard approach: if there is no Kempe chain between v and any vertex of color c in the subgraph of colors c and target_color, then we can swap
                    # But simpler: try to swap the component containing v and see if it frees color c
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb]:
                                nb_color = best_coloring[nb]
                                if nb_color == c or nb_color == target_color:
                                    visited[nb] = True
                                    stack.append(nb)
                    # Check if any neighbor of v has color c (outside the component? Actually, if a neighbor of v has color c, then v is adjacent to color c, so swapping would cause conflict)
                    # After swapping, v will get color c. So we need that no neighbor of v has color c after swap.
                    # Currently, neighbors of v have various colors. After swap, neighbors in the component that were color c become target_color, and vice versa.
                    # So a neighbor u of v will have color c after swap if:
                    #   - u is in component and currently has color target_color (becomes c)
                    #   - u is not in component and currently has color c (remains c)
                    # We need to avoid both.
                    conflict = False
                    for u in adj_list[v]:
                        if u in component:
                            if best_coloring[u] == target_color:  # after swap becomes c
                                conflict = True
                                break
                        else:
                            if best_coloring[u] == c:  # remains c
                                conflict = True
                                break
                    if not conflict:
                        # perform swap
                        for node in component:
                            if best_coloring[node] == c:
                                best_coloring[node] = target_color
                            elif best_coloring[node] == target_color:
                                best_coloring[node] = c
                        improved = True
                        break  # break from color loop
                if improved:
                    # after Kempe swap, check if target color class is empty
                    if any(best_coloring[u] == target_color for u in range(n)):
                        pass
                    else:
                        k -= 1
                        for u in range(n):
                            if best_coloring[u] > target_color:
                                best_coloring[u] -= 1
                        break  # break to restart while loop
        # end while improved

    # Final normalization
    best_coloring = normalize(best_coloring)
    return best_coloring

