    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Precompute bit adjacency and degrees
    bit_adj = [0] * n
    degrees = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
