    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: count distinct colors
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: get available colors mask for a vertex given neighbor colors
    def available_colors_mask(vertex, neighbor_colors_mask):
        used = 0
        # neighbor_colors_mask is a bitmask of colors used by neighbors
        # We'll compute it on the fly in callers
        # Instead, we compute used colors from neighbor list
        mask = 0
        for v in adj_list[vertex]:
            c = coloring[v]
            if c >= 0:  # only consider colored neighbors
                mask |= (1 << c)
        return ~mask  # bits set where color is available

    # DSATUR implementation
    def dsatur():
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbor masks for fast saturation update
        colored_neighbor_mask = [0] * n

        # Order vertices by degree descending for initial tie-breaking
        vertices = list(range(n))
        vertices.sort(key=lambda x: degrees[x], reverse=True)

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            max_sat = -1
            candidates = []
            for v in vertices:
                if coloring[v] == -1:
                    sat = saturation[v]
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)

            if not candidates:
                break  # should not happen

            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                # Compute degree in uncolored subgraph
                uncolored_deg = {}
                for v in candidates:
                    cnt = 0
                    for nb in adj_list[v]:
                        if coloring[nb] == -1:
                            cnt += 1
                    uncolored_deg[v] = cnt
                max_deg = max(uncolored_deg.values())
                candidates = [v for v in candidates if uncolored_deg[v] == max_deg]

            # Final tie-break: random
            v = random.choice(candidates)

            # Compute used colors by neighbors
            used_mask = 0
            for nb in adj_list[v]:
                c = coloring[nb]
                if c != -1:
                    used_mask |= (1 << c)

