            color = 0
            while used_mask & (1 << color):
                color += 1
            coloring[v] = color

            # Update saturation and colored neighbor masks for neighbors
            for nb in adj_list[v]:
                if coloring[nb] == -1:  # only update uncolored neighbors
                    # Add color v to nb's colored neighbor set
                    colored_neighbor_mask[nb] |= (1 << color)
