            if not uncolored:
                break
            # Find vertex in uncolored with max degree in uncolored subgraph
            max_deg = -1
            v0 = None
            for v in uncolored:
                deg = 0
                for nb in adj_list[v]:
                    if nb in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
            if v0 is None:
                v0 = next(iter(uncolored))

            independent_set = {v0}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = set()
            W = set()
            for v in uncolored:
                if v == v0:
                    continue
                adjacent = False
                for nb in adj_list[v]:
                    if nb in independent_set:
                        adjacent = True
                        break
                if adjacent:
                    W.add(v)
                else:
                    U.add(v)

            # Greedily add vertices from U to independent_set
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_nb_count = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_nb_count += 1
                    # Tie-break: min degree in U
                    u_deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            u_deg_in_U += 1
                    if w_nb_count > max_w_neighbors or (w_nb_count == max_w_neighbors and u_deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_nb_count
                        min_deg_in_U = u_deg_in_U
                        best_u = u
                if best_u is None:
                    break
                # Add best_u to independent_set
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # Assign color to all in independent_set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1

        return coloring

    # Smallest-Last ( degeneracy ordering ) greedy
    def smallest_last():
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []  # will store removal order
        degrees_copy = degrees[:]  # current degrees in remaining subgraph
        # We'll maintain a list of vertices by degree for efficiency, but n<=100 so we can scan
        while remaining:
            # Find vertex with min degree in remaining
            min_deg = float('inf')
            v_min = None
            for v in remaining:
                if degrees_copy[v] < min_deg:
                    min_deg = degrees_copy[v]
                    v_min = v
            if v_min is None:
                break
            order.append(v_min)
            remaining.remove(v_min)
            # Update degrees of neighbors
            for nb in adj_list[v_min]:
                if nb in remaining:
                    degrees_copy[nb] -= 1

        # Color in reverse order (last removed first)
        coloring = [-1] * n
        for v in reversed(order):
            # Find used colors by neighbors
            used_mask = 0
            for nb in adj_list[v]:
                c = coloring[nb]
                if c != -1:
                    used_mask |= (1 << c)
            color = 0
            while used_mask & (1 << color):
                color += 1
            coloring[v] = color

        return coloring

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        current = coloring[:]
        k = count_colors(current)
        # Try to reduce colors as long as possible
        improved = True
        while improved and k > 1:
            improved = False
            # Target the last color (k-1)
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                k -= 1
                continue

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_mask = 0
                for nb in adj_list[v]:
                    c = current[nb]
                    if c != -1:
                        used_mask |= (1 << c)
                # Try colors from 0 to target_color-1
                for c in range(target_color):
                    if not (used_mask & (1 << c)):
                        # Can recolor v to c
                        current[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart from beginning as coloring changed

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v can be swapped via (target_color, c) Kempe chain
                    # We'll do BFS/DFS to find the Kempe chain component containing v
                    # Only consider vertices colored target_color or c
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        node = queue.popleft()
                        component.add(node)
                        for nb in adj_list[node]:
                            if nb in visited:
                                continue
                            nb_color = current[nb]
                            if nb_color == target_color or nb_color == c:
                                visited.add(nb)
                                queue.append(nb)

                    # Check if swapping this component is safe:
                    # For all nodes in component, after swap:
                    #   target_color -> c, c -> target_color
                    # We need to ensure no neighbor outside component has conflicting color
                    safe = True
                    for node in component:
                        new_color = c if current[node] == target_color else target_color
                        for nb in adj_list[node]:
                            if nb not in component:
                                if current[nb] == new_color:
                                    safe = False
                                    break
                        if not safe:
                            break

                    if safe:
                        # Perform the swap
                        for node in component:
                            if current[node] == target_color:
                                current[node] = c
                            else:  # must be c
                                current[node] = target_color
                        improved = True
                        break  # break from color loop
                if improved:
                    break  # break from vertex loop

            # If we improved, rebuild target_vertices and possibly reduce k
            if improved:
                # Compact colors: reindex to 0..k'-1
                # But first, check if target_color class is empty
                target_vertices = [v for v in range(n) if current[v] == target_color]
                if not target_vertices:
                    k -= 1
                    # Reindex colors to be consecutive
                    # Map existing colors to 0..k-1
                    unique_colors = sorted(set(current))
                    if len(unique_colors) == k:
                        mapping = {old: new for new, old in enumerate(unique_colors)}
                        for v in range(n):
                            current[v] = mapping[current[v]]
                    else:
                        # Should not happen, but fallback
                        pass
            else:
                # Cannot reduce further
                break

        # Final compacting
        unique_colors = sorted(set(current))
        if len(unique_colors) > 0:
            mapping = {old: new for new, old in enumerate(unique_colors)}
            for v in range(n):
                current[v] = mapping[current[v]]

        return current

    # Generate candidate colorings
    candidates = []

    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass

    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass

    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), use greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            used_mask = 0
            for nb in adj_list[v]:
                c = coloring[nb]
                if c != -1:
                    used_mask |= (1 << c)
            color = 0
            while used_mask & (1 << color):
                color += 1
            coloring[v] = color
        candidates.append(coloring)

    # Select best candidate (fewest colors)
    best = min(candidates, key=count_colors)

    # Apply Kempe reduction to try to improve
    try:
        improved = kempe_reduce(best)
        if is_valid_coloring(improved) and count_colors(improved) <= count_colors(best):
            best = improved
    except:
        pass

    # Final validation and compacting (ensure 0..k-1)
    if not is_valid_coloring(best):
        # Fallback to greedy
        coloring = [-1] * n
        for v in range(n):
            used_mask = 0
            for nb in adj_list[v]:
                c = coloring[nb]
                if c != -1:
                    used_mask |= (1 << c)
            color = 0
            while used_mask & (1 << color):
                color += 1
            coloring[v] = color
        best = coloring

    # Compact colors
    unique_colors = sorted(set(best))
    if len(unique_colors) > 0:
        mapping = {old: new for new, old in enumerate(unique_colors)}
        for v in range(n):
            best[v] = mapping[best[v]]

    return best

