    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Convert adjacency matrix to adjacency list
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build complement graph adjacency list
    comp_adj = [[] for _ in range(n)]
    for i in range(n):
        neighbors_set = set(adj_list[i])
        for j in range(n):
            if i != j and j not in neighbors_set:
                comp_adj[i].append(j)

    # Degree in complement graph
    comp_deg = [len(comp_adj[i]) for i in range(n)]

    # Order vertices by descending degree in complement graph
    order = sorted(range(n), key=lambda x: (-comp_deg[x], x))

    # Greedy coloring on original graph using the order
    color = [-1] * n
    for v in order:
        used = [False] * n  # n is safe upper bound for colors needed
        for u in adj_list[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        if color[i] not in unique_colors:
            unique_colors[color[i]] = next_color
            next_color += 1
        color[i] = unique_colors[color[i]]

    return color

