def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = (len(adj) > 0 and len(adj[0]) == len(adj) and
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    # Build adjacency list and bit masks
    neighbors = []
    if is_matrix:
        for u in range(n):
            nbrs = [v for v in range(n) if adj[u][v] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = [list(set(lst)) for lst in adj]  # deduplicate

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in neighbors[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: count colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Heuristic 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree as bitmask of neighbor colors
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            best = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                s = sat[v].bit_count()
                if s > best_sat or (s == best_sat and (best == -1 or 
                                                       len([u for u in neighbors[v] if u in uncolored]) > best_deg)):
                    best_sat = s
                    best_deg = len([u for u in neighbors[v] if u in uncolored])
                    best = v
            v = best
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    # Heuristic 2: RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            # start with max degree vertex in uncolored subgraph
            deg_in_uncolored = {v: len([u for u in neighbors[v] if u in uncolored]) for v in uncolored}
            v = max(uncolored, key=lambda x: deg_in_uncolored[x])
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in independent_set)}
            W = {u for u in uncolored if u != v and any(u in neighbors[w] for w in independent_set)}
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = len([w for w in neighbors[u] if w in W])
                    deg_U = len([w for w in neighbors[u] if w in U])
                    if score > best_score or (score == best_score and deg_U < best_deg_U):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[v]) for v in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # maintain current min degree
        for _ in range(n):
            # find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            order.append(v)
            remaining.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # move u from bucket[degree[u]] to bucket[degree[u]-1]
                    old_deg = degree[u]
                    degree[u] -= 1
                    buckets[old_deg].remove(u)
                    buckets[degree[u]].append(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Run all heuristics and pick best
    candidates = []
    for heuristic in (dsatur, rlf, smallest_last):
        try:
            col = heuristic()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # fallback: simple greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(col)
        else:
            # last resort: assign distinct colors
            col = list(range(n))
            candidates.append(col)

    best = min(candidates, key=count_colors)
    k = count_colors(best)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        nonlocal k
        improved = True
        while improved and k > 1:
            improved = False
            # find smallest color class
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[coloring[v]].append(v)
            # find smallest non-empty class
            target_color = -1
            min_size = n + 1
            for c in range(k):
                if 0 < len(color_classes[c]) < min_size:
                    min_size = len(color_classes[c])
                    target_color = c
            if target_color == -1:
                break
            # try to recolor each vertex in target class
            for v in color_classes[target_color][:]:
                # try direct reassignment to lower color
                for c in range(target_color):
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # BFS to find (target_color, c)-Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (coloring[y] == target_color or coloring[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # check if swapping would free color c for v (i.e., no neighbor of v in component has color c)
                    # actually, after swap, v would get color c; we need to ensure no neighbor of v has color c post-swap
                    # but since we only swap within component, neighbors outside component keep their color
                    # so we need: for all u in neighbors[v], if u not in component then coloring[u] != c
                    # and for u in component, after swap they get the other color
                    # so condition: no neighbor of v has color c and is not in the component? 
                    # Actually, simpler: after swap, v gets color c. We need that no neighbor of v has color c.
                    # Neighbors of v: if in component, they get target_color (not c); if not in component, they keep their color.
                    # So we only need to check neighbors not in component: they must not have color c.
                    ok = True
                    for u in neighbors[v]:
                        if not visited[u] and coloring[u] == c:
                            ok = False
                            break
                    if ok:
                        # perform swap
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            else:
                                coloring[x] = target_color
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # compact colors: reindex to 0..k-1
                # but we only removed target_color if no vertex has it now
                if target_color < k and all(coloring[v] != target_color for v in range(n)):
                    # shift down colors > target_color
                    for v in range(n):
                        if coloring[v] > target_color:
                            coloring[v] -= 1
                    k -= 1
        return coloring

    best = kempe_reduce(best)
    # final validation and compacting
    if not is_valid(best):
        # fallback to greedy
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        best = greedy_color(order)
    # ensure colors are 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best[i] = unique_colors[c]
    return best

