def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list and compute bitmasks
    if len(adj) > 0 and len(adj[0]) == n and all(all(x in (0, 1) for x in row) for row in adj):
        # Adjacency matrix
        neighbors = []
        bit_adj = [0] * n
        for i in range(n):
            row_neighbors = []
            mask = 0
            for j in range(n):
                if adj[i][j]:
                    row_neighbors.append(j)
                    mask |= (1 << j)
            neighbors.append(row_neighbors)
            bit_adj[i] = mask
    else:
        # Adjacency list
        neighbors = adj
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for j in neighbors[i]:
                mask |= (1 << j)
            bit_adj[i] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = coloring[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring

    # Helper: 1-opt local improvement
    def local_improve(coloring):
        improved = True
        while improved:
            improved = False
            order = list(range(n))
            random.shuffle(order)
            for u in order:
                used = 0
                for v in neighbors[u]:
                    c = coloring[v]
                    if c != -1:
                        used |= (1 << c)
                # Try to find a better color
                for c in range(num_colors(coloring) + 1):
                    if not (used & (1 << c)):
                        if c < coloring[u]:
                            coloring[u] = c
                            improved = True
                        break
        return coloring

    best_coloring = None
    best_k = float('inf')

    # Multiple randomized greedy passes
    for _ in range(10):
        # Random vertex order
        order = list(range(n))
        random.shuffle(order)
        coloring = greedy_color(order)
        coloring = local_improve(coloring)
        k = num_colors(coloring)
        if k < best_k or (k == best_k and best_coloring is None):
            best_k = k
            best_coloring = coloring[:]

    # Fallback: try degree-sorted order
    order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    coloring = greedy_color(order)
    coloring = local_improve(coloring)
    k = num_colors(coloring)
    if k < best_k:
        best_k = k
        best_coloring = coloring[:]

    # Final validation
    assert is_valid(best_coloring), "Invalid coloring produced"
    return best_coloring

