        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # colored_neighbors[v] = bitmask of colored neighbors
        colored_neighbors = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] == -1:
                    sat_u = saturation[u]
                    deg_u = degree(u)
                    if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg):
                        max_sat = sat_u
                        max_deg = deg_u
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color
            neighbor_colors = 0
            nb = adj_list[v]
            for w in nb:
                if colors[w] != -1:
                    neighbor_colors |= (1 << colors[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c

            # Update saturation and colored_neighbors for uncolored neighbors
            for w in nb:
                if colors[w] == -1:
                    colored_neighbors[w] |= (1 << c)
                    # Count distinct colors in colored_neighbors[w]
                    saturation[w] = bin(colored_neighbors[w]).count("1")
        return compact_colors(colors)

    # RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        color_idx = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            to_remove = {v}

            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v}
            W = set()
            for y in adj_list[v]:
                if y in U:
                    U.remove(y)
                    W.add(y)

            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors of u that are in W
                    w_neighbors = sum(1 for y in adj_list[u] if y in W)
                    deg_in_U = sum(1 for y in adj_list[u] if y in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                # Add best_u to independent set
                independent_set.add(best_u)
                to_remove.add(best_u)
                # Update U and W: move best_u from U, and move its neighbors from U to W
                U.remove(best_u)
                for y in adj_list[best_u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color to all in independent_set
            for vertex in independent_set:
                colors[vertex] = color_idx
            color_idx += 1
            uncolored -= to_remove
        return compact_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []  # removal order
        # Current degrees in the remaining subgraph
        deg = [0] * n
        for v in range(n):
            deg[v] = sum(1 for y in adj_list[v] if y in remaining)

        while remaining:
            # Find vertex with minimum degree
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for y in adj_list[v]:
                if y in remaining:
                    deg[y] -= 1

        # Color in reverse removal order
        colors = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for w in adj_list[v]:
                if colors[w] != -1:
                    neighbor_colors |= (1 << colors[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        # Make a copy to work on
        current = coloring[:]
        improved = True
        while improved:
            improved = False
            k = num_colors(current)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Vertices with target_color
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # Already compacted?
                return compact_colors(current)

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for w in adj_list[v]:
                    if current[w] != -1:
                        neighbor_colors |= (1 << current[w])
                for c in range(target_color):  # try colors 0 to target_color-1
                    if not (neighbor_colors & (1 << c)):
                        # Can recolor v to c
                        current[v] = c
                        improved = True
                        break
                if improved:
                    break  # restart from beginning as coloring changed

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Consider (target_color, c) Kempe chain
                    # We'll check if v is in a component that, when swapped, frees target_color for v
                    # Actually, we want to see if we can swap a component containing v to move v to color c
                    # Standard: if in the (v, c) Kempe chain, the component of v does not contain any vertex of color target_color? 
                    # Actually, we want to swap colors target_color and c in the component of v in the subgraph induced by colors {target_color, c}
                    # After swap, v will have color c, and we free target_color if no other vertex in the component had target_color? 
                    # But note: we are trying to eliminate target_color, so we want to recolor v away from target_color.
                    # We can swap the component of v in the (target_color, c) subgraph. After swap, v gets color c.
                    # This operation is valid and may help if it doesn't increase the usage of target_color elsewhere? 
                    # Actually, we are moving v from target_color to c, so we reduce the count of target_color by 1 (if v was the only one? not necessarily).
                    # But we are iterating over target_vertices, so we try to recolor each one.
                    # We do not require that the swap frees the color entirely; we just want to recolor v.
                    # However, to avoid infinite loops, we note that the swap is valid and changes the coloring.
                    # We'll perform the swap if the component of v in {target_color, c} does not include a vertex that would cause conflict? 
                    # Actually, Kempe swap is always valid.
                    # But we want to avoid swapping if it doesn't help? We'll do it and see if we can then recolor v to c? 
                    # Actually, after swap, v will have color c (if we swap the component). So we can directly assign.
                    # However, note: if we swap, v's color becomes c, which is what we want.
                    # So we can do:
                    #   Let S be the connected component of v in the subgraph induced by vertices with color in {target_color, c}
                    #   Swap colors target_color and c for all vertices in S.
                    #   Then v will have color c.
                    # We do this and break.

                    # Find component of v in the subgraph of vertices with color target_color or c
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (current[y] == target_color or current[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # Perform swap: in component, swap target_color and c
                    for x in component:
                        if current[x] == target_color:
                            current[x] = c
                        elif current[x] == c:
                            current[x] = target_color
                    # Now v has color c (since it was target_color and we swapped)
                    improved = True
                    break  # break from c loop
                if improved:
                    break  # break from target_vertices loop
            if improved:
                # Compact colors after change
                current = compact_colors(current)
        return compact_colors(current)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        greedy = [-1] * n
        for v in range(n):
            used = 0
            for w in adj_list[v]:
                if greedy[w] != -1:
                    used |= (1 << greedy[w])
            c = 0
            while used & (1 << c):
                c += 1
            greedy[v] = c
        candidates.append(compact_colors(greedy))

    # Select candidate with fewest colors
    best = min(candidates, key=lambda x: num_colors(x))

    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)

    # Final validation and compaction
    if not is_valid_coloring(best):
        # Fallback to greedy if something went wrong
        greedy = [-1] * n
        for v in range(n):
            used = 0
            for w in adj_list[v]:
                if greedy[w] != -1:
                    used |= (1 << greedy[w])
            c = 0
            while used & (1 << c):
                c += 1
            greedy[v] = c
        best = compact_colors(greedy)
    else:
        best = compact_colors(best)

    return best

