            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colors[u] != -1:
                    continue
                # saturation degree: number of distinct colors in neighbors
                sat = saturation[u].bit_count()
                deg = degrees[u]
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and random.random() < 0.5):
                    max_sat = sat
                    max_deg = deg
                    v = u
            if v == -1:
                break  # should not happen
            # Find smallest available color
            used = saturation[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            # Update saturation of neighbors
            for nb in adj_list[v]:
                if colors[nb] == -1:
                    saturation[nb] |= (1 << c)
