        uncolored = set(range(n))
        while uncolored:
            # Build independent set for this color
            S = []  # independent set
            # Degree in the subgraph induced by uncolored
            deg_in_uncolored = [0] * n
            for u in uncolored:
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg_in_uncolored[u] = cnt
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: deg_in_uncolored[x])
            S.append(v)
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                for nb in adj_list[u]:
                    if nb in S:
                        W.add(u)
                        break
            U -= W
            # While U not empty, add vertices to S
            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                max_neighbors_in_W = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    cnt = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            cnt += 1
                    # Tie-break: min degree in U (current U)
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_in_U += 1
                    if cnt > max_neighbors_in_W or (cnt == max_neighbors_in_W and deg_in_U < min_deg_in_U) or (cnt == max_neighbors_in_W and deg_in_U == min_deg_in_U and random.random() < 0.5):
                        max_neighbors_in_W = cnt
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
