        deg = [len(adj_list[i]) for i in range(n)]
        # Remaining vertices
        remaining = set(range(n))
        order = []  # will be peeled order
        # Buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # Pointer to current min degree
        min_deg = 0
        while remaining:
            # Find non-empty bucket with min degree
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    d = deg[nb]
                    # remove from current bucket
                    if d < len(buckets) and nb in buckets[d]:
                        buckets[d].remove(nb)
                    deg[nb] -= 1
                    dnew = deg[nb]
                    if dnew < len(buckets):
                        buckets[dnew].append(nb)
                    else:
                        # extend buckets if needed
                        while len(buckets) <= dnew:
                            buckets.append([])
                        buckets[dnew].append(nb)
                    if dnew < min_deg:
                        min_deg = dnew
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain elimination to reduce colors
    def kempe_reduce(colors_in):
        colors = colors_in[:]
        changed = True
        while changed:
            changed = False
            k = count_colors(colors)
            if k <= 1:
                break
            # Target smallest color class (color k-1)
            target_color = k - 1
            # Vertices with target color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                # Already compacted?
                return compact_colors(colors)
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                used_by_neighbors = 0
                for nb in adj_list[v]:
                    if colors[nb] != -1:
                        used_by_neighbors |= (1 << colors[nb])
                for c in range(target_color):  # try colors 0..target_color-1
                    if not (used_by_neighbors & (1 << c)):
                        # Can recolor v to c
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart while loop after change
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # If v already has color c from direct reassignment above, skip
                    if colors[v] == c:
                        continue
                    # Check if v is adjacent to any vertex of color c (would cause conflict if we try to swap)
                    has_adjacent_c = False
                    for nb in adj_list[v]:
                        if colors[nb] == c:
                            has_adjacent_c = True
                            break
                    if has_adjacent_c:
                        continue  # swapping would put two adjacent c's if we swap v's color to c
                    # Build the (c, target_color) Kempe chain containing v
                    # We'll do BFS/DFS over vertices with color c or target_color
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        u = stack.pop()
                        if u in visited:
                            continue
                        visited.add(u)
                        if colors[u] == c or colors[u] == target_color:
                            component.add(u)
                            for nb in adj_list[u]:
                                if nb not in visited and (colors[nb] == c or colors[nb] == target_color):
                                    stack.append(nb)
                    # Check if any neighbor of v in the component has color c? Actually, we already checked no adjacent c.
                    # Swapping the component is safe: it will not create adjacent same colors.
                    # Perform swap: c <-> target_color in component
                    for u in component:
                        if colors[u] == c:
                            colors[u] = target_color
                        else:  # must be target_color
                            colors[u] = c
                    changed = True
                    break  # break from color loop, restart while
            if changed:
                # Compact colors after change
                colors = compact_colors(colors)
            else:
                # Could not eliminate target color, break
                break
        return compact_colors(colors)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except Exception:
        pass
    # If no candidates, fallback to trivial greedy
    if not candidates:
        colors = [0] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                if colors[nb] != -1:
