        neighbors = [set(j for j in range(n) if adj[i][j] == 1) for i in range(n)]
    else:
        neighbors = [set(adj[i]) for i in range(n)]

    # Degeneracy ordering (smallest-last) for good initial coloring
    def degeneracy_ordering():
        # Make a copy of degrees and neighbor sets
        deg = [len(neighbors[i]) for i in range(n)]
        # We'll work with sets of remaining vertices
        remaining = set(range(n))
        order = []
        # Buckets for vertices by degree (0 to n-1)
        buckets = [set() for _ in range(n)]
        for v in range(n):
            if deg[v] < n:
                buckets[deg[v]].add(v)

        # Current minimum degree
        min_deg = 0
        for _ in range(n):
            # Find next vertex with minimum degree
            while min_deg < n and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break  # No vertices left
            # Select a vertex from the bucket
            v = buckets[min_deg].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = deg[u]
                    deg[u] -= 1
                    if old_deg < n:
                        buckets[old_deg].discard(u)
                    if deg[u] < n:
                        buckets[deg[u]].add(u)
                    # Update min_deg if needed
                    if deg[u] < min_deg:
                        min_deg = deg[u]
        return order

    # Greedy coloring given a vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            # Find colors used by colored neighbors
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            # Find smallest available color
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Get degeneracy order and color
    order = degeneracy_ordering()
    # Color in reverse of removal order (largest last)
    color = greedy_color(order[::-1])

    # Compact colors to be consecutive starting from 0
    unique_colors = sorted(set(color))
    if unique_colors != list(range(len(unique_colors))):
        mapping = {old: new for new, old in enumerate(unique_colors)}
        color = [mapping[c] for c in color]

    return color

