            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            uncolored.remove(v)
            # W: neighbors of S in uncolored
            W = set()
            for u in adj_list[v]:
                if u in uncolored:
                    W.add(u)
            # U: uncolored not in W
            U = uncolored - W
            while U:
                # select u in U with max neighbors in W, then min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # degree in U
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if (w_neighbors > max_w_neighbors or
                        (w_neighbors == max_w_neighbors and deg_u < min_deg_in_U) or
                        (w_neighbors == max_w_neighbors and deg_u == min_deg_in_U and (best_u == -1 or random.random() < 0.5))):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_u
                        best_u = u
                # add best_u to S
                S.add(best_u)
                uncolored.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
                U.discard(best_u)
            # assign color c to all in S
            for u in S:
                color[u] = c
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # core decomposition to get order
        deg = [len(adj_list[i]) for i in range(n)]
        # bins for degrees
        max_deg = max(deg) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            bins[deg[i]].append(i)
        # pointer to current non-empty bin
        ptr = 0
        order = []
        # copy of degrees
        curr_deg = deg[:]
        removed = [False] * n
        for _ in range(n):
            # find non-empty bin
            while ptr <= max_deg and not bins[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = bins[ptr].pop()
            if removed[v]:
                # find another
                while bins[ptr] and removed[bins[ptr][-1]]:
                    bins[ptr].pop()
                if not bins[ptr]:
                    ptr += 1
                    while ptr <= max_deg and not bins[ptr]:
                        ptr += 1
                    if ptr > max_deg:
                        break
                    v = bins[ptr].pop()
            removed[v] = True
            order.append(v)
            for u in adj_list[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    if d > 0:
                        curr_deg[u] -= 1
                        bins[d].remove(u)
                        bins[d-1].append(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Welsh-Powell: sort by degree descending
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Kempe chain elimination to reduce colors
    def kempe_reduce(coloring):
        # make coloring consecutive
        def renumber(col):
            mapping = {}
            next_c = 0
            for i in range(n):
                c = col[i]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                col[i] = mapping[c]
            return col

        coloring = renumber(coloring[:])
        k = max(coloring) + 1 if n > 0 else 0
        improved = True
        while improved and k > 0:
            improved = False
            # find smallest color class
            classes = [[] for _ in range(k)]
            for v in range(n):
                classes[coloring[v]].append(v)
            # find first non-empty class from smallest index
            target_color = -1
            for c in range(k):
                if classes[c]:
                    target_color = c
                    break
            if target_color == -1:
                break
            # try to recolor each vertex in target class
            for v in classes[target_color][:]:
                # try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    neighbor_colors.add(coloring[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    # move v to new class, update structures
                    classes[target_color].remove(v)
                    classes[coloring[v]].append(v)
                    continue
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already recolored, break
                    if coloring[v] != target_color:
                        break
                    # BFS to find (target_color, c) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in adj_list[u]:
                            if not visited[w] and (coloring[w] == target_color or coloring[w] == c):
                                visited[w] = True
                                queue.append(w)
                    # check if swapping is safe: no neighbor of component has color c outside
                    safe = True
                    for u in component:
                        for w in adj_list[u]:
                            if coloring[w] == c and w not in component:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # perform swap
                        for u in component:
                            if coloring[u] == target_color:
                                coloring[u] = c
                            else:
                                coloring[u] = target_color
                        improved = True
                        break
            if improved:
                # renumber and update k
                coloring = renumber(coloring)
                k = max(coloring) + 1 if n > 0 else 0
        return coloring

    # Generate candidate colorings
    candidates = []
    start = time.time()
    # DSATUR
    col_dsatur = dsatur()
    if is_valid(col_dsatur):
        candidates.append(col_dsatur)
    # RLF
    col_rlf = rlf()
    if is_valid(col_rlf):
        candidates.append(col_rlf)
    # Smallest-Last
    col_sl = smallest_last()
    if is_valid(col_sl):
        candidates.append(col_sl)
    # Welsh-Powell
    col_wp = welsh_powell()
    if is_valid(col_wp):
        candidates.append(col_wp)
    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select best candidate (fewest colors)
    best = min(candidates, key=count_colors)
    best = kempe_reduce(best)
    # Final validation and renumber
    if not is_valid(best):
        # last resort: greedy
        best = greedy_color(list(range(n)))
    best = kempe_reduce(best)  # try again after fallback
    # Ensure consecutive colors
    def final_renumber(col):
        mapping = {}
        next_c = 0
        for i in range(n):
            c = col[i]
            if c not in mapping:
                mapping[c] = next_c
                next_c += 1
            col[i] = mapping[c]
        return col
    return final_renumber(best)

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Determine if adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build neighbor bitmasks and adjacency lists
    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1
    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True
    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n  # saturation degree
        # Use degree for initial tie-breaking
        deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max sat, then max deg in uncolored, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                if sat[u] > max_sat or (sat[u] == max_sat and deg[u] > max_deg) or (sat[u] == max_sat and deg[u] == max_deg and (v == -1 or u < v)):
                    max_sat = sat[u]
                    max_deg = deg[u]
                    v = u
            if v == -1:
                break  # should not happen
            # assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    sat[u] += 1
        return color
    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # degree in current uncolored subgraph
            deg_uncolored = [0] * n
            for u in uncolored:
                for v in neighbors[u]:
                    if v in uncolored:
                        deg_uncolored[u] += 1
            # start with vertex of max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = uncolored - {v} - set(neighbors[v])
            W = set(neighbors[v]) & uncolored
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = None
                for u in U:
                    # count neighbors in W
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    # tie-break by min degree in U-induced subgraph
                    deg_u = 0
                    for w in neighbors[u]:
                        if w in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and (best_deg_U is None or deg_u < best_deg_U)):
                        best_score = score
                        best_deg_U = deg_u
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                independent_set.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color
    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degree = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use a list of lists for buckets, but n <= 100, so simple scan is fine
        for _ in range(n):
            # find unremoved vertex with min degree
            v = -1
            min_deg = float('inf')
            for u in range(n):
                if not removed[u] and degree[u] < min_deg:
                    min_deg = degree[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            removed[v] = True
            for u in neighbors[v]:
                if not removed[u]:
                    degree[u] -= 1
        # color in reverse order
        return greedy_color(order[::-1])
    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append(col_sl)
    except Exception:
        pass
    # Also try greedy with degree ordering (Welsh-Powell)
    try:
        order_wp = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        col_wp = greedy_color(order_wp)
        if is_valid(col_wp):
            candidates.append(col_wp)
    except Exception:
        pass
    # If no candidates (should not happen), fallback to trivial
    if not candidates:
        # assign each vertex a unique color
        return list(range(n))
    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # Make a copy we can modify
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            # Determine current number of colors
            k = num_colors(col)
            if k <= 1:
                break
            # Find vertices of the last color (k-1)
            last_color = k - 1
            verts_last = [v for v in range(n) if col[v] == last_color]
            if not verts_last:
                # should not happen if k is correct
                break
            # Try to recolor each vertex in last color class
            for v in verts_last:
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = col[u]
                    if c != -1:
                        used |= (1 << c)
                for c in range(last_color):  # only try colors < last_color
                    if not (used & (1 << c)):
                        # can recolor v to c
                        col[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart while loop after any change
                # Try Kempe chains with each lower color
                for c in range(last_color):
                    # Check if v is adjacent to any vertex of color c
                    adjacent_to_c = False
                    for u in neighbors[v]:
                        if col[u] == c:
                            adjacent_to_c = True
                            break
                    if adjacent_to_c:
                        continue  # swapping would cause conflict directly
                    # Build the (c, last_color) Kempe chain containing v
                    # We'll BFS/DFS over vertices colored c or last_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (col[y] == c or col[y] == last_color):
                                visited[y] = True
                                queue.append(y)
                    # Swap colors c and last_color in this component
                    for x in component:
                        if col[x] == c:
                            col[x] = last_color
                        elif col[x] == last_color:
                            col[x] = c
                    # After swap, check if v is now color c (it should be, since we swapped)
                    # But we need to ensure we didn't introduce conflicts; Kempe swap preserves validity
                    # However, we want to see if we can reduce the number of vertices of last_color
                    # Actually, after swap, v becomes color c, so we have recolored v
                    col[v] = c  # ensure v is now c (it should be)
                    changed = True
                    break  # break from color loop
                if changed:
                    break  # break from vertex loop
            # After attempting to recolor all vertices of last color, if none changed, we cannot reduce further
            # Compact colors if last color class is empty
            if not changed:
                # Reindex colors to be consecutive
                # Map existing colors to 0..k'-1
                unique_colors = sorted(set(col))
                mapping = {old: new for new, old in enumerate(unique_colors)}
                col = [mapping[c] for c in col]
                # If we removed a color, we will have changed in next iteration via direct reassignment attempt
                # But to trigger change, we set changed = True if number of colors decreased
                new_k = num_colors(col)
                if new_k < k:
                    changed = True
        return col
    # Apply Kempe reduction
    try:
        col_reduced = kempe_reduction(best)
        if is_valid(col_reduced):
            best = col_reduced
    except Exception:
        pass
    # Final validation and compacting
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
    # Ensure colors are consecutive
    unique_colors = sorted(set(best))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    best = [mapping[c] for c in best]
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    if n > 0 and len(adj[0]) == n and all(
        isinstance(x, int) and x in (0, 1) for row in adj for x in row
    ):
        # Convert matrix to adjacency list
        adj_list = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
    else:
        # Treat as adjacency list
        adj_list = adj
        # Ensure symmetry and no self-loops
        for u in range(n):
            adj_list[u] = [v for v in adj_list[u] if v != u and 0 <= v < n]
            adj_list[u] = list(set(adj_list[u]))  # deduplicate
    # Build bitmask adjacency
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= 1 << v
        bit_adj[u] = mask
    # Helper: test if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            neighbors = bit_adj[u]
            v = 0
            while neighbors:
                if neighbors & 1:
                    if coloring[v] == cu:
                        return False
                neighbors >>= 1
                v += 1
        return True
    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0
    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        # saturation: list of sets of neighbor colors
        saturation = [set() for _ in range(n)]
        # degrees in the uncolored subgraph (initially full degree)
        deg_uncolored = [len(adj_list[u]) for u in range(n)]
        colored_count = 0
        while colored_count < n:
            # select uncolored vertex with max saturation, tie-break by max deg_uncolored, then random
            candidates = []
            max_rho = -1
            for u in range(n):
                if coloring[u] == -1:
                    rho = len(saturation[u])
                    if rho > max_rho:
                        max_rho = rho
                        candidates = [u]
                    elif rho == max_rho:
                        candidates.append(u)
            # tie-break by deg_uncolored (descending), then random
            candidates.sort(key=lambda x: (-deg_uncolored[x], random.random()))
            u = candidates[0]
            # find smallest color not used by neighbors
            used = saturation[u]
            c = 0
            while c in used:
                c += 1
            coloring[u] = c
            colored_count += 1
            # update saturation of uncolored neighbors
            for v in adj_list[u]:
                if coloring[v] == -1:
                    saturation[v].add(c)
                    deg_uncolored[v] -= 1  # one less uncolored neighbor
        return coloring
    # Recursive Largest First (RLF)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Step 1: pick vertex with max degree in G[uncolored]
            # compute degree in induced subgraph
            deg_sub = {}
            for u in uncolored:
                # count neighbors in uncolored
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg_sub[u] = cnt
            # pick max degree, tie-break randomly
            max_deg = max(deg_sub.values())
            candidates = [u for u in uncolored if deg_sub[u] == max_deg]
            v1 = random.choice(candidates)
            S = {v1}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v1:
                    continue
                # check if adjacent to any in S
                adjacent = False
                for v in S:
                    if u in adj_list[v] or v in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                best_deg_U = None
                for u in U:
                    # score = number of neighbors in W
                    score = 0
                    for v in adj_list[u]:
                        if v in W:
                            score += 1
                    # tie-break by min degree in G[U]
                    deg_U = 0
                    for v in adj_list[u]:
                        if v in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and (best_deg_U is None or deg_U < best_deg_U)):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u that are in U to W
                for v in adj_list[u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # assign color to all in S
            for u in S:
                coloring[u] = color
            # remove S from uncolored
            uncolored -= S
            color += 1
        return coloring
    # Smallest-Last (Matula & Beck) ordering + greedy
    def smallest_last():
        # compute degeneracy ordering
        # copy of degrees
        degree = [len(adj_list[u]) for u in range(n)]
        # list of sets for vertices of each degree
        max_deg = max(degree) if n > 0 else 0
        bins = [set() for _ in range(max_deg + 1)]
        for u in range(n):
            d = degree[u]
            bins[d].add(u)
        # ordering stack
        ordering = []
        # current min degree
        for _ in range(n):
            # find first non-empty bin
            d = 0
            while d <= max_deg and not bins[d]:
                d += 1
            if d > max_deg:
                break  # should not happen
            v = bins[d].pop()
            ordering.append(v)
            # decrease degree of neighbors
            for u in adj_list[v]:
                if degree[u] > d:  # only if not yet removed
                    # move u from bin degree[u] to degree[u]-1
                    bins[degree[u]].remove(u)
                    degree[u] -= 1
                    bins[degree[u]].add(u)
        # reverse ordering for coloring
        ordering.reverse()
        # greedy coloring in this order
        coloring = [-1] * n
        for u in ordering:
            used = set()
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used.add(coloring[v])
            c = 0
            while c in used:
                c += 1
            coloring[u] = c
        return coloring
    # Kempe chain elimination to reduce colors
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        # make copy to work on
        col = coloring[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(col)
            if k <= 1:
                break
            # target smallest color class (color k-1)
            target_color = k - 1
            vertices = [u for u in range(n) if col[u] == target_color]
            if not vertices:
                # should not happen, but compact anyway
                mapping = {}
                new_color = 0
                for c in range(k):
                    if any(col[u] == c for u in range(n)):
                        mapping[c] = new_color
                        new_color += 1
                col = [mapping[c] for c in col]
                changed = True
                continue
            # try to recolor each vertex in target class
            for u in vertices:
                # try direct reassignment to a lower color
                neighbor_colors = set()
                for v in adj_list[u]:
                    if col[v] != -1:
                        neighbor_colors.add(col[v])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        col[u] = c
                        changed = True
                        break
                if changed:
                    # after moving u, check if target color class is empty
                    if not any(col[v] == target_color for v in range(n)):
                        # compact colors
                        mapping = {}
                        new_color = 0
                        for c in range(k):
                            if any(col[v] == c for v in range(n)):
                                mapping[c] = new_color
                                new_color += 1
                        col = [mapping[c] for c in col]
                        changed = True
                        break
                    else:
                        # revert and try Kempe chains
                        col[u] = target_color
                # if not changed by direct, try Kempe chains
                if not changed:
                    for c in range(target_color):
                        # check if u is adjacent to any vertex of color c
                        adj_to_c = any(col[v] == c for v in adj_list[u])
                        if adj_to_c:
                            continue  # swapping would cause conflict if we pull in adjacent
                        # find the Kempe chain of (target_color, c) containing u
                        # Actually u is color target_color, we want to swap a component
                        # that does NOT include any neighbor of u of color c
                        # Standard: consider the connected component of u in the subgraph induced by colors {target_color, c}
                        # If in that component, there is no vertex of color c adjacent to u, we can swap
                        # But simpler: if u is not adjacent to any color c, we can attempt to swap the component
                        # containing u in the two-color subgraph, provided that swapping does not cause conflict.
                        # However, if u is not adjacent to any color c, then swapping its component will not create conflict
                        # because its neighbors are either not in {target_color, c} or are target_color (which become c, but u is not adjacent to them? Wait)
                        # Actually, we need to ensure that after swap, u's neighbors that were target_color become c, but if u had a neighbor of target_color,
                        # after swap that neighbor becomes c, and u becomes c -> conflict.
                        # So we must only swap if the component does not contain any neighbor of u.
                        # Therefore, we compute the component of u in the graph induced by vertices of colors target_color or c,
                        # and check if it contains any neighbor of u.
                        # If not, we can swap the component.
                        from collections import deque
                        visited = set()
                        queue = deque([u])
                        visited.add(u)
                        component = set()
                        while queue:
                            x = queue.popleft()
                            component.add(x)
                            for y in adj_list[x]:
                                if col[y] in (target_color, c) and y not in visited:
                                    visited.add(y)
                                    queue.append(y)
                        # check if any neighbor of u is in component
                        conflict = False
                        for v in adj_list[u]:
                            if v in component:
                                conflict = True
                                break
                        if not conflict:
                            # perform swap: target_color <-> c in component
                            for x in component:
                                if col[x] == target_color:
                                    col[x] = c
                                else:
                                    col[x] = target_color
                            changed = True
                            break
                    if changed:
                        # after swap, check if target color class is empty
                        if not any(col[v] == target_color for v in range(n)):
                            mapping = {}
                            new_color = 0
                            for c in range(k):
                                if any(col[v] == c for v in range(n)):
                                    mapping[c] = new_color
                                    new_color += 1
                            col = [mapping[c] for c in col]
                            changed = True
                        break
            # end for each vertex in target class
        return col
    # Generate candidates
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass
    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        greedy = [0] * n
        for u in range(n):
            used = set()
            for v in adj_list[u]:
                if greedy[v] != -1:  # but we are assigning in order, so need to check colored neighbors
                    # Actually we need to simulate greedy in order 0..n-1
                    pass
        # simple greedy in vertex order
        coloring = [-1] * n
        for u in range(n):
            used = set()
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used.add(coloring[v])
            c = 0
            while c in used:
                c += 1
            coloring[u] = c
        candidates.append(coloring)
    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        if not is_valid(col):
            continue
        k = num_colors(col)
        if k < best_k:
            best_k = k
            best = col
    # Apply Kempe reduction to best
    if best is not None:
        best = kempe_reduce(best)
        # ensure validity and compactness
        if not is_valid(best):
            # fallback to best before reduction
            pass
        # compact colors to 0..k-1
        k = num_colors(best)
        if k > 0:
            mapping = {}
            new_color = 0
            colors_present = set(best)
            for c in sorted(colors_present):
                mapping[c] = new_color
                new_color += 1
            best = [mapping[c] for c in best]
    else:
        # ultimate fallback
        best = list(range(n))  # worst case, but valid
    return best

