def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = (len(adj) > 0 and len(adj[0]) == len(adj) and
                 all(all(x == 0 or x == 1 for x in row) for row in adj))
    if is_matrix:
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        bit_adj = [0] * n
        for i in range(n):
            for v in adj[i]:
                bit_adj[i] |= (1 << v)

    def is_valid_coloring(colors):
        for u in range(n):
            for v in range(u + 1, n):
                if (bit_adj[u] >> v) & 1:
                    if colors[u] == colors[v]:
                        return False
        return True

    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    def dsatur():
        colors = [-1] * n
        saturated = [0] * n
        colored_mask = 0
        for _ in range(n):
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colors[v] != -1:
                    continue
                sat = saturated[v]
                deg = (bit_adj[v] & ~colored_mask).bit_count()
                if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                   (sat == best_sat and deg == best_deg and v < best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            if best_v == -1:
                break
            neighbor_colors = 0
            nb = bit_adj[best_v]
            while nb:
                w = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                if colors[w] != -1:
                    neighbor_colors |= (1 << colors[w])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            colors[best_v] = color
            colored_mask |= (1 << best_v)
            nb2 = bit_adj[best_v]
            while nb2:
                w = (nb2 & -nb2).bit_length() - 1
                nb2 &= nb2 - 1
                if colors[w] == -1:
                    saturated[w] += 1
        return compact_colors(colors)

    def rlf():
        colors = [-1] * n
        uncolored_mask = (1 << n) - 1
        color = 0
        while uncolored_mask:
            S = 0
            v = -1
            best_deg = -1
            temp = uncolored_mask
            while temp:
                u = (temp & -temp).bit_length() - 1
                temp &= temp - 1
                deg = (bit_adj[u] & uncolored_mask).bit_count()
                if deg > best_deg or (deg == best_deg and u < v):
                    best_deg = deg
                    v = u
            if v == -1:
                break
            S |= (1 << v)
            U = uncolored_mask & ~(bit_adj[v] | (1 << v))
            W = uncolored_mask & ~U & ~(1 << v)
            while U:
                best_u = -1
                best_w_neighbors = -1
                best_u_deg = -1
                temp = U
                while temp:
                    u = (temp & -temp).bit_length() - 1
                    temp &= temp - 1
                    w_neighbors = (bit_adj[u] & W).bit_count()
                    u_deg = (bit_adj[u] & U).bit_count()
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and u_deg < best_u_deg) or \
                       (w_neighbors == best_w_neighbors and u_deg == best_u_deg and u < best_u):
                        best_w_neighbors = w_neighbors
                        best_u_deg = u_deg
                        best_u = u
                if best_u == -1:
                    break
                S |= (1 << best_u)
                U &= ~(1 << best_u)
                nb = bit_adj[best_u]
                while nb:
                    w = (nb & -nb).bit_length() - 1
                    nb &= nb - 1
                    if (U >> w) & 1:
                        U &= ~(1 << w)
                        W |= (1 << w)
            for i in range(n):
                if (S >> i) & 1:
                    colors[i] = color
            uncolored_mask = W
            color += 1
        return compact_colors(colors)

    def smallest_last():
        order = []
        degrees = [0] * n
        removed = [False] * n
        adj_list = [[] for _ in range(n)]
        for u in range(n):
            nb = bit_adj[u]
            while nb:
                v = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                adj_list[u].append(v)
        for u in range(n):
            degrees[u] = len(adj_list[u])
        for _ in range(n):
            min_deg = n
            v = -1
            for u in range(n):
                if not removed[u] and degrees[u] < min_deg:
                    min_deg = degrees[u]
                    v = u
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            for u in adj_list[v]:
                if not removed[u]:
                    degrees[u] -= 1
        colors = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= (1 << colors[u])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            colors[v] = color
        return compact_colors(colors)

    def kempe_reduce(colors):
        k = max(colors) + 1 if n > 0 else 0
        if k <= 1:
            return colors
        while True:
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[colors[v]].append(v)
            target = k - 1
            if not color_classes[target]:
                break
            moved = False
            for v in color_classes[target][:]:
                neighbor_colors = 0
                nb = bit_adj[v]
                while nb:
                    u = (nb & -nb).bit_length() - 1
                    nb &= nb - 1
                    neighbor_colors |= (1 << colors[u])
                for c in range(target):
                    if not (neighbor_colors & (1 << c)):
                        colors[v] = c
                        color_classes[target].remove(v)
                        color_classes[c].append(v)
                        moved = True
                        break
                if moved:
                    break
            if moved:
                continue
            for v in color_classes[target][:]:
                for c in range(target):
                    if neighbor_colors & (1 << c):
                        continue
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        nb = bit_adj[node]
                        while nb:
                            w = (nb & -nb).bit_length() - 1
                            nb &= nb - 1
                            if colors[w] == c or colors[w] == target:
                                if not visited[w]:
                                    visited[w] = True
                                    stack.append(w)
                    swap_ok = True
                    for node in component:
                        nb = bit_adj[node]
                        while nb:
                            w = (nb & -nb).bit_length() - 1
                            nb &= nb - 1
                            if colors[w] == target and w not in component:
                                swap_ok = False
                                break
                        if not swap_ok:
                            break
                    if swap_ok:
                        for node in component:
                            if colors[node] == target:
                                colors[node] = c
                            elif colors[node] == c:
                                colors[node] = target
                        moved = True
                        break
                if moved:
                    break
            if not moved:
                break
            k = max(colors) + 1
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[colors[v]].append(v)
            while k > 0 and not color_classes[k - 1]:
                k -= 1
            if k == max(colors) + 1:
                break
            colors = [c if c < k else c - (max(colors) + 1 - k) for c in colors]
        return compact_colors(colors)

    start = time.time()
    best_colors = None
    best_k = float('inf')

    # DSATUR
    if time.time() - start < 0.04:
        c1 = dsatur()
        k1 = max(c1) + 1 if n > 0 else 0
        if k1 < best_k:
            best_k = k1
            best_colors = c1
    # RLF
    if time.time() - start < 0.04:
        c2 = rlf()
        k2 = max(c2) + 1 if n > 0 else 0
        if k2 < best_k:
            best_k = k2
            best_colors = c2
    # Smallest-Last
    if time.time() - start < 0.04:
        c3 = smallest_last()
        k3 = max(c3) + 1 if n > 0 else 0
        if k3 < best_k:
            best_k = k3
            best_colors = c3

    if best_colors is None:
        best_colors = [0] * n

    # Kempe reduction
    if time.time() - start < 0.04:
        best_colors = kempe_reduce(best_colors)

    # Final validation and compaction
    if not is_valid_coloring(best_colors):
        # Fallback to greedy
        order = list(range(n))
        order.sort(key=lambda x: bin(bit_adj[x]).count('1'), reverse=True)
        colors = [-1] * n
        for v in order:
            neighbor_colors = 0
            nb = bit_adj[v]
            while nb:
                w = (nb & -nb).bit_length() - 1
                nb &= nb - 1
                if colors[w] != -1:
                    neighbor_colors |= (1 << colors[w])
            color = 0
            while neighbor_colors & (1 << color):
                color += 1
            colors[v] = color
        best_colors = compact_colors(colors)

    return best_colors

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and bitmask representation
    neighbors_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            neighbors_list[i] = adj[i][:]
            mask = 0
            for j in adj[i]:
                mask |= (1 << j)
            bit_adj[i] = mask

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            for v in neighbors_list[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # Precompute degrees for tie-breaking
        degrees = [len(neighbors_list[i]) for i in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    # Compute saturation: distinct colors in neighbors
                    neighbor_colors = set()
                    for w in neighbors_list[u]:
                        if colored[w]:
                            neighbor_colors.add(colors[w])
                    sat = len(neighbor_colors)
                    if sat > max_sat or (sat == max_sat and (degrees[u] > max_deg or (degrees[u] == max_deg and random.random() < 0.5))):
                        max_sat = sat
                        max_deg = degrees[u]
                        v = u
            if v == -1:
                break  # should not happen
            # Find smallest available color
            used = [False] * (n + 1)
            for w in neighbors_list[v]:
                if colored[w]:
                    used[colors[w]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
            colored[v] = True
        return compact_colors(colors)

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build independent set for current color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda u: len([w for w in neighbors_list[u] if w in uncolored]))
            S.append(v)
            # Partition U and W
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in S for w in neighbors_list[u]):
                    W.add(u)
                    U.remove(u)
            # Grow independent set
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_neighbors_in_W = -1
                min_deg_in_U = float('inf')
                for u in U:
                    neighbors_in_W = sum(1 for w in neighbors_list[u] if w in W)
                    deg_in_U = len([w for w in neighbors_list[u] if w in U])
                    if (neighbors_in_W > max_neighbors_in_W or
                        (neighbors_in_W == max_neighbors_in_W and deg_in_U < min_deg_in_U) or
                        (neighbors_in_W == max_neighbors_in_W and deg_in_U == min_deg_in_U and random.random() < 0.5)):
                        max_neighbors_in_W = neighbors_in_W
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in neighbors_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for u in S:
                colors[u] = color
            color += 1
            uncolored = W  # next round
        return compact_colors(colors)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors_list[i]) for i in range(n)]
        order = []
        # We'll use bucket sort for efficiency, but n <= 100 so simple scan is fine
        temp_degree = degree[:]
        remaining_set = set(remaining)
        for _ in range(n):
            # Find vertex with min degree in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining_set:
                if temp_degree[u] < min_deg:
                    min_deg = temp_degree[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining_set.remove(v)
            for w in neighbors_list[v]:
                if w in remaining_set:
                    temp_degree[w] -= 1
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for w in neighbors_list[v]:
                if colors[w] != -1:
                    used[colors[w]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain swap for colors a and b, starting from vertex v, returns new coloring if swap performed, else None
    def kempe_swap(colors, v, a, b):
        if colors[v] not in (a, b):
            return None
        # Find the Kempe chain component containing v for colors a and b
        stack = [v]
        visited = set()
        component = set()
        target_colors = {a, b}
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if colors[u] in target_colors:
                component.add(u)
                for w in neighbors_list[u]:
                    if colors[w] in target_colors and w not in visited:
                        stack.append(w)
        # Try to swap colors in component: a->b, b->a
        new_colors = colors[:]
        for u in component:
            if new_colors[u] == a:
                new_colors[u] = b
            elif new_colors[u] == b:
                new_colors[u] = a
        # Validate (should always be valid, but check)
        if is_valid_coloring(new_colors):
            return new_colors
        return None

    # Attempt to eliminate the last color via Kempe chains or direct reassignment
    def reduce_colors(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color k-1
        target_color = k - 1
        vertices = [i for i in range(n) if colors[i] == target_color]
        # Try direct reassignment first
        for v in vertices:
            used = [False] * (k)  # only need to check colors 0..k-1
            for w in neighbors_list[v]:
                c = colors[w]
                if c < k:
                    used[c] = True
            for c in range(k):
                if not used[c]:
                    new_colors = colors[:]
                    new_colors[v] = c
                    # Compact after change
                    compacted = compact_colors(new_colors)
                    if is_valid_coloring(compacted):
                        return compacted
        # Try Kempe chains with each lower color
        for v in vertices:
            for c in range(target_color):
                swapped = kempe_swap(colors, v, target_color, c)
                if swapped is not None:
                    compacted = compact_colors(swapped)
                    if is_valid_coloring(compacted):
                        return compacted
        # Cannot reduce
        return colors

    # Generate initial candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_colors = best[:]

    # Iteratively try to reduce colors
    improved = True
    while improved:
        new_colors = reduce_colors(best_colors)
        if num_colors(new_colors) < num_colors(best_colors):
            best_colors = new_colors
            improved = True
        else:
            improved = False

    # Final validation and compact
    if not is_valid_coloring(best_colors):
        # Fallback to greedy on original order (should not happen)
        colors = [-1] * n
        for u in range(n):
            used = [False] * (n + 1)
            for w in neighbors_list[u]:
                if colors[w] != -1:
                    used[colors[w]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            colors[u] = c
        best_colors = compact_colors(colors)
    else:
        best_colors = compact_colors(best_colors)

    return best_colors

