            for j in range(n):
                if adj[i][j] == 1:
                    row.append(j)
                    mask |= (1 << j)
            adj_list.append(row)
            bit_adj[i] = mask
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for neighbor in adj_list[i]:
                mask |= (1 << neighbor)
            bit_adj[i] = mask

