        degree = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # Use buckets for efficiency (since n <= 100)
        for _ in range(n):
            # Find vertex with min degree among unremoved
            v = -1
            min_deg = float('inf')
            for i in range(n):
                if not removed[i] and degree[i] < min_deg:
                    min_deg = degree[i]
                    v = i
            if v == -1:
                break  # should not happen
            order.append(v)
            removed[v] = True
            for u in adj_list[v]:
                if not removed[u]:
                    degree[u] -= 1
        # Color in reverse order
        return greedy_coloring(order[::-1])

    # --- Heuristic 4: Welsh-Powell (degree descending) ---
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_coloring(order)

    # Run all heuristics
    for heuristic in [dsatur, rlf, smallest_last, welsh_powell]:
        coloring = heuristic()
        k = count_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]

    # If no coloring found (should not happen), fallback to greedy
    if best_coloring is None:
        best_coloring = greedy_coloring(list(range(n)))
        best_k = count_colors(best_coloring)

    # --- Kempe Chain Color Reduction ---
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Ensure coloring is valid and compact
    def compact_colors(coloring):
        # Map colors to 0..k-1
        unique = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            coloring[i] = unique[c]
