    # Try to reduce colors by eliminating the largest color class
    changed = True
    while changed and best_k > 1:
        changed = False
        # Count vertices per color
        color_count = [0] * best_k
        for c in best_coloring:
            color_count[c] += 1
        # Target the largest color class (to maximize chance of elimination)
        target_color = max(range(best_k), key=lambda c: color_count[c])
        # Try to recolor each vertex of target_color
        for v in [i for i in range(n) if best_coloring[i] == target_color]:
            used_by_neighbors = 0
            for u in adj_list[v]:
                if best_coloring[u] != target_color:  # only consider neighbors not in target color (they are fixed for now)
                    used_by_neighbors |= (1 << best_coloring[u])
            # Try direct reassignment to a lower color
            for c in range(target_color):
                if not (used_by_neighbors & (1 << c)):
                    # Move v to color c
                    best_coloring[v] = c
                    color_count[target_color] -= 1
                    color_count[c] += 1
                    changed = True
                    break
            if changed:
                break
            # Try Kempe chain swap with each lower color
            for c in range(target_color):
                # Check if v is connected to color c via Kempe chain (target_color, c)
                # We'll try to find the Kempe chain component of v in the subgraph of colors {target_color, c}
                # and see if we can swap to free target_color for v
                from collections import deque
                visited = [False] * n
                queue = deque([v])
                visited[v] = True
                component = []
                has_c = False  # whether component touches color c
                while queue:
                    x = queue.popleft()
                    component.append(x)
                    if best_coloring[x] == c:
                        has_c = True
                    for y in adj_list[x]:
                        if not visited[y] and best_coloring[y] in (target_color, c):
                            visited[y] = True
                            queue.append(y)
                # If the component does not contain any vertex of color c, we can swap
                if not has_c:
                    # Swap colors target_color and c in the component
                    for x in component:
                        if best_coloring[x] == target_color:
                            best_coloring[x] = c
                        else:
                            best_coloring[x] = target_color
                    # Update color counts
                    color_count[target_color] -= len([x for x in component if best_coloring[x] == target_color])  # after swap, these become c
                    color_count[c] += len([x for x in component if best_coloring[x] == c])   # after swap, these become target_color? Let's recalc properly
                    # Instead, recount the component
                    cnt_target = 0
                    cnt_c = 0
                    for x in component:
                        if best_coloring[x] == target_color:
                            cnt_target += 1
                        else:
                            cnt_c += 1
                    # After swap, target becomes c and c becomes target
                    color_count[target_color] = color_count[target_color] - cnt_target + cnt_c
                    color_count[c] = color_count[c] - cnt_c + cnt_target
                    changed = True
                    break
            if changed:
                break
        if changed:
            # Compact colors again
            best_coloring = compact_colors(best_coloring)
            best_k = count_colors(best_coloring)

    # Final validation and compact
    best_coloring = compact_colors(best_coloring)
    if not is_valid(best_coloring):
        # Last resort: DSATUR
        best_coloring = compact_colors(dsatur())

    return best_coloring

