def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = (len(adj) > 0 and len(adj[0]) == n and
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    # Build adjacency list
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = [j for j in range(n) if adj[i][j] == 1]
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Build bitmask adjacency for efficient operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Degeneracy ordering via smallest-last (Matula & Beck, 1983)
    # Maintain current degree and a bucket of vertices by degree
    degree = [len(adj_list[i]) for i in range(n)]
    removed = [False] * n
    order = []  # removal order (smallest-last first)
    buckets = [[] for _ in range(n)]  # buckets[deg] = list of vertices with that degree
    for i in range(n):
        if degree[i] < n:
            buckets[degree[i]].append(i)

    # Pointer to current minimum non-empty bucket
    min_deg = 0
    for _ in range(n):
        # Find next non-empty bucket
        while min_deg < n and not buckets[min_deg]:
            min_deg += 1
        if min_deg >= n:
            break  # should not happen
        v = buckets[min_deg].pop()
        if removed[v]:
            continue  # skip if already removed (can happen due to lazy updates)
        removed[v] = True
        order.append(v)
        # Update neighbors: decrease degree and move to appropriate bucket
        for u in adj_list[v]:
            if not removed[u]:
                d = degree[u]
                # remove u from bucket[d] (lazy: we'll skip removed ones later)
                degree[u] = d - 1
                if degree[u] >= 0:
                    buckets[degree[u]].append(u)
                # update min_deg if needed
                if degree[u] < min_deg:
                    min_deg = degree[u]

    # Color in reverse order (largest-last first) with First-Fit
    color = [-1] * n
    for v in reversed(order):
        # Compute neighbor colors as bitmask
        neighbor_colors = 0
        for u in adj_list[v]:
            c = color[u]
            if c != -1:
                neighbor_colors |= (1 << c)
        # Find smallest non-negative integer not in neighbor_colors (mex)
        c = 0
        while neighbor_colors & (1 << c):
            c += 1
        color[v] = c

    # Compact colors to ensure zero-based consecutive indices
    unique_colors = sorted(set(color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    return color

