        # saturation[v] = set of colors used by colored neighbors
        saturation = [set() for _ in range(n)]
        # degree in the uncolored subgraph (initially full degree)
        degree = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_v = len(saturation[v])
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)
            # Tie-break by degree in uncolored subgraph
            max_deg = -1
            final_candidates = []
            for v in candidates:
                deg_v = degree[v]
                if deg_v > max_deg:
                    max_deg = deg_v
                    final_candidates = [v]
                elif deg_v == max_deg:
                    final_candidates.append(v)
            v = random.choice(final_candidates) if final_candidates else next(iter(uncolored))

            # Find smallest available color
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)

            # Update saturation and degree for uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u].add(c)
                    degree[u] -= 1  # one less uncolored neighbor
