    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build independent set for current_color
            S = set()
            # Degree in the uncolored subgraph
            degree = [0] * n
            for v in uncolored:
                for u in adj_list[v]:
                    if u in uncolored:
                        degree[v] += 1

            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: degree[x])
            S.add(v)
            uncolored.remove(v)

            # Partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = set(uncolored)  # copy
            W = set()
            for u in list(uncolored):
                adjacent_to_S = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                    U.discard(u)

