                                new_coloring[u] = c
                            else:  # must be c
                                new_coloring[u] = k
                        found = True
                        break
                if not found:
                    # Cannot recolor v, so elimination fails
                    return None
        # Successfully recolored all verts_k; now compact colors > k down by 1
        # But note: we only used colors < k, so max color is at most k-1
        # However, there might be gaps; we normalize at the end.
        return new_coloring

    # Iterative color reduction
    current = best[:]
    changed = True
    while changed and num_colors(current) > 1:
        changed = False
        k = num_colors(current) - 1  # highest color index
        # Try to eliminate the highest color class first (often smallest)
        # But we can also try the smallest color class; we'll try highest as it's often easier to eliminate
        new_coloring = eliminate_color_class(current, k)
        if new_coloring is not None and is_valid_coloring(new_coloring):
            current = new_coloring
            changed = True
        else:
            # Try eliminating the smallest color class (may be more effective)
            # Find the color class with smallest size
            color_counts = {}
            for v in range(n):
                c = current[v]
                color_counts[c] = color_counts.get(c, 0) + 1
            if color_counts:
                min_color = min(color_counts, key=color_counts.get)
                new_coloring = eliminate_color_class(current, min_color)
                if new_coloring is not None and is_valid_coloring(new_coloring):
                    current = new_coloring
                    changed = True

    # Final normalization to ensure consecutive colors
    current = normalize_coloring(current)
    return current

