def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if it's a binary matrix (0/1)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and compute degrees
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = adj[i]
            nbrs = [j for j in range(n) if row[j] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = adj  # already adjacency list

    degrees = [len(neighbors[i]) for i in range(n)]

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets for saturation update
        neigh_colors = [set() for _ in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, break ties by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                if sat[v] > best_sat or (sat[v] == best_sat and len([u for u in neighbors[v] if u in uncolored]) > best_deg) or \
                   (sat[v] == best_sat and len([u for u in neighbors[v] if u in uncolored]) == best_deg and v < best_v):
                    best_sat = sat[v]
                    best_deg = len([u for u in neighbors[v] if u in uncolored])
                    best_v = v
            v = best_v

            # Assign smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)

            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    if c not in neigh_colors[u]:
                        neigh_colors[u].add(c)
                        sat[u] += 1
        return color

    # Strategy 2: RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0

        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([u for u in neighbors[x] if u in uncolored]))
            independent_set = {v}
            to_check = set(neighbors[v]) & uncolored  # neighbors of v that are uncolored -> ineligible for this color
            candidates = uncolored - {v} - to_check    # uncolored and not adjacent to v -> eligible

            while candidates:
                # Select candidate with max neighbors in to_check, tie-break by min degree in candidates subgraph
                best_u = -1
                best_w = -1
                best_deg_in_candidates = float('inf')
                for u in candidates:
                    w = len([x for x in neighbors[u] if x in to_check])
                    deg_in_candidates = len([x for x in neighbors[u] if x in candidates])
                    if w > best_w or (w == best_w and deg_in_candidates < best_deg_in_candidates) or \
                       (w == best_w and deg_in_candidates == best_deg_in_candidates and u < best_u):
                        best_w = w
                        best_deg_in_candidates = deg_in_candidates
                        best_u = u
                u = best_u
                independent_set.add(u)
                # Update: remove u from candidates, add its uncolored neighbors to to_check
                candidates.remove(u)
                new_ineligible = set(neighbors[u]) & candidates
                to_check.update(new_ineligible)
                candidates -= new_ineligible

            # Assign color c to independent set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1

        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = degrees[:]
        removed = [False] * n
        order = []
        # Buckets for vertices by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if deg[v] < len(buckets):
                buckets[deg[v]].append(v)
            else:
                # extend buckets if needed (should not happen with proper deg)
                buckets.extend([[] for _ in range(deg[v] - len(buckets) + 1)])
                buckets[deg[v]].append(v)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr < len(buckets) and not buckets[ptr]:
                ptr += 1
            if ptr >= len(buckets):
                break  # should not happen
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    # remove u from its current bucket
                    d = deg[u]
                    if d < len(buckets) and u in buckets[d]:
                        buckets[d].remove(u)
                    deg[u] -= 1
                    if deg[u] < len(buckets):
                        buckets[deg[u]].append(u)
                    else:
                        # extend buckets if needed
                        while len(buckets) <= deg[u]:
                            buckets.append([])
                        buckets[deg[u]].append(u)

        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-degrees[x], x))
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    try:
        c4 = welsh_powell()
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy on natural order
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select candidate with fewest colors
    best_coloring = min(candidates, key=num_colors)
    k = num_colors(best_coloring)

    # Kempe chain color reduction: try to eliminate color classes from highest downward
    # We'll attempt to reduce the number of colors by merging classes via Kempe swaps
    improved = True
    while improved and k > 1:
        improved = False
        # Try to eliminate color k-1
        target_color = k - 1
        vertices_target = [v for v in range(n) if best_coloring[v] == target_color]
        if not vertices_target:
            # This color class is empty, compact colors
            mapping = {}
            new_color = 0
            for c in range(k):
                if any(best_coloring[v] == c for v in range(n)):
                    mapping[c] = new_color
                    new_color += 1
            best_coloring = [mapping[best_coloring[v]] for v in range(n)]
            k = new_color
            improved = True
            continue

        # For each vertex in target color, try to recolor it to a lower color
        # via direct assignment or Kempe chain swap
        removed_all = True
        for v in vertices_target:
            # Try direct reassignment to a lower color
            neighbor_colors = set()
            for u in neighbors[v]:
                if best_coloring[u] < target_color:
                    neighbor_colors.add(best_coloring[u])
            for c in range(target_color):
                if c not in neighbor_colors:
                    # Can recolor v to c directly
                    best_coloring[v] = c
                    break
            else:
                # Direct reassignment not possible, try Kempe chains
                moved = False
                for c in range(target_color):
                    # Check if v is connected to color c via a Kempe chain that we can swap
                    # We'll do BFS for the (c, target_color) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (best_coloring[y] == c or best_coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of v in the component has color c? Actually, we need to see
                    # if swapping this component would free color c for v.
                    # After swap, v would get color c if it was target_color and in the component.
                    # But we need to ensure that no neighbor of v ends up with color c after swap?
                    # Actually, after swapping colors c and target_color in the component:
                    # - v (currently target_color) becomes c
                    # - Its neighbors: if a neighbor u is in the component and had color c, it becomes target_color -> conflict if u adjacent to v?
                    #   But if u is neighbor of v and in the component, then edge (v,u) has colors target_color and c -> after swap: c and target_color -> still different.
                    #   However, if a neighbor u is not in the component and has color c, then after swap v becomes c -> conflict.
                    # So we need that no neighbor of v outside the component has color c.
                    safe = True
                    for u in neighbors[v]:
                        if not visited[u] and best_coloring[u] == c:
                            safe = False
                            break
                    if safe:
                        # Perform swap: invert colors c and target_color in component
                        for x in component:
                            if best_coloring[x] == c:
                                best_coloring[x] = target_color
                            elif best_coloring[x] == target_color:
                                best_coloring[x] = c
                        moved = True
                        break
                if not moved:
                    removed_all = False
                    break
        if removed_all and not any(best_coloring[v] == target_color for v in range(n)):
            # Successfully eliminated target color
            k -= 1
            improved = True
        # If we didn't eliminate the color, we break to avoid infinite loop; in practice we might try other strategies
        else:
            # Try next lower color? For simplicity, break if we couldn't eliminate the highest
            break

    # Final validation and compacting
    # Ensure colors are consecutive starting from 0
    used_colors = set(best_coloring)
    if used_colors:
        mapping = {old: new for new, old in enumerate(sorted(used_colors))]
        best_coloring = [mapping[c] for c in best_coloring]

    # Double-check validity (should hold)
    if not is_valid(best_coloring):
        # Fallback to DSATUR if something went wrong
        best_coloring = dsatur()
        used_colors = set(best_coloring)
        if used_colors:
            mapping = {old: new for new, old in enumerate(sorted(used_colors))}
            best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

