def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:  # safety check
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper to test if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper to get number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper to normalize colors to 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map colors to consecutive integers
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR implementation
    def dsatur():
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # colored neighbor mask for fast saturation update
        colored_mask = [0] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    if sat[u] > max_sat or (sat[u] == max_sat and len(adj_list[u]) > max_deg):
                        max_sat = sat[u]
                        max_deg = len(adj_list[u])
                        v = u
                    elif sat[u] == max_sat and len(adj_list[u]) == max_deg and v == -1:
                        v = u  # first found

            if v == -1:
                break  # should not happen

            # Find smallest available color
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:
                    # Add color c to u's neighbor colors if not already present
                    if not (colored_mask[u] & (1 << c)):
                        colored_mask[u] |= (1 << c)
                        sat[u] += 1

        return normalize(coloring)

    # RLF implementation
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for this color
            independent_set = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
                independent_set.append(v)
                # Partition uncolored: U (not adjacent to S), W (adjacent to S)
                S = set(independent_set)
                U = {u for u in uncolored if u not in S and not any(w in adj_list[u] for w in S)}
                W = {u for u in uncolored if u not in S and u not in U}

                while U:
                    # Select u in U with max neighbors in W
                    u_star = -1
                    max_w_neighbors = -1
                    min_deg_in_U = float('inf')
                    for u in U:
                        w_neighbors = len([w for w in adj_list[u] if w in W])
                        deg_in_U = len([w for w in adj_list[u] if w in U])
                        if w_neighbors > max_w_neighbors or \
                           (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                           (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and u_star == -1):
                            max_w_neighbors = w_neighbors
                            min_deg_in_U = deg_in_U
                            u_star = u

                    if u_star == -1:
                        break  # should not happen

                    independent_set.append(u_star)
                    S.add(u_star)
                    U.remove(u_star)
                    # Move neighbors of u_star from U to W
                    for w in adj_list[u_star]:
                        if w in U:
