        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # Buckets for degrees
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].append(i)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)

        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c

        return normalize(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen if input is valid

        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            vertices = [i for i in range(n) if coloring[i] == target_color]
            if not vertices:
                continue

            # Try to recolor each vertex in this class
            removed = True
            while vertices and removed:
                removed = False
                v = vertices.pop()
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if coloring[u] < target_color:
                        neighbor_colors.add(coloring[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Check if moving v to color c would cause conflict (shouldn't by construction)
                        # But verify: neighbors of v with color c?
                        conflict = False
                        for u in adj_list[v]:
                            if coloring[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            coloring[v] = c
                            removed = True
                            break

                if not removed:
                    # Try Kempe chains with each lower color
                    for c in range(target_color):
                        # Skip if v already has a neighbor of color c (would cause immediate conflict if swapped)
                        has_c_neighbor = any(coloring[u] == c for u in adj_list[v])
                        if has_c_neighbor:
                            continue

                        # Build (target_color, c)-Kempe chain containing v
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if coloring[node] == target_color or coloring[node] == c:
                                component.add(node)
                                for nb in adj_list[node]:
                                    if nb not in visited and (coloring[nb] == target_color or coloring[nb] == c):
                                        stack.append(nb)

                        # Check if swapping this component is safe: 
                        # No vertex in component should have a neighbor outside component with the target color after swap
                        # Actually, for Kempe chain swap to be valid, we just need that after swap, 
                        # no two adjacent vertices have same color. Since we're swapping two colors in a component,
                        # it's valid if the component is a connected component of the subgraph induced by colors {target_color, c}.
                        # But we built it as such, so swap is always valid? Not exactly: we must ensure that 
                        # after swap, no vertex in component gets a color that conflicts with a neighbor outside component.
                        # However, by definition of Kempe chain, neighbors of the component in the subgraph 
                        # have colors other than {target_color, c}, so swap is safe.
                        # But we want to free color target_color for v, i.e., after swap, v should not be color target_color.
                        # Currently v is target_color, after swap it becomes c.
                        # We want to know if after swap, color target_color is still used in the component?
                        # Actually, we want to eliminate color target_color entirely, so we need that 
                        # after swap, no vertex has color target_color.
                        # That means we need the entire color class target_color to be in this Kempe component.
                        # So we check if all vertices of color target_color are in this component.
                        all_in = True
                        for u in range(n):
                            if coloring[u] == target_color and u not in component:
                                all_in = False
                                break
                        if all_in:
                            # Perform swap: target_color <-> c in component
                            for u in component:
                                if coloring[u] == target_color:
                                    coloring[u] = c
                                elif coloring[u] == c:
                                    coloring[u] = target_color
                            # After swap, v has color c, and target_color is eliminated from component
                            # But we need to check if target_color is used anywhere else
                            still_used = any(coloring[u] == target_color for u in range(n))
                            if not still_used:
                                # Target color eliminated, break and restart reduction
                                return kempe_reduce([x if x < target_color else (x-1 if x > target_color else x) for x in coloring])
                            # Otherwise, continue trying other vertices
                            removed = True
                            break
                    if removed:
                        break

            # If we couldn't remove all vertices of target_color, break and try next lower color
            if any(coloring[i] == target_color for i in range(n)):
                break  # cannot eliminate this color, try lower ones

        # Renormalize colors to be consecutive
        return normalize(coloring)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fall back to simple greedy
    if not candidates:
        coloring = [-1] * n
        for i in range(n):
            used = set()
            for j in adj_list[i]:
                if coloring[j] != -1:
                    used.add(coloring[j])
            c = 0
            while c in used:
                c += 1
            coloring[i] = c
        candidates.append(normalize(coloring))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)

    # Apply Kempe chain reduction to try to improve
    try:
        improved = kempe_reduce(best[:])
        if is_valid(improved) and num_colors(improved) < num_colors(best):
            best = improved
    except:
        pass

    return best

