import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask
    if is_matrix:
        adj_list = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        adj_list = [list(neighbors) for neighbors in adj]
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits
    def bit_count(x):
        return x.bit_count()

    # Helper: get uncolored neighbors mask
    def uncolored_neighbors_mask(u, colored_mask):
        return bit_adj[u] & ~colored_mask

    # Helper: saturation degree (number of distinct colors in neighbors)
    def saturation_degree(u, color_of, colored_mask):
        neighbor_mask = bit_adj[u] & colored_mask
        if neighbor_mask == 0:
            return 0
        colors = set()
        m = neighbor_mask
        while m:
            v = (m & -m).bit_length() - 1
            colors.add(color_of[v])
            m &= m - 1
        return len(colors)

    # Helper: degree in subgraph induced by uncolored vertices
    def degree_in_uncolored(u, uncolored_set):
        if not uncolored_set:
            return 0
        mask = 0
        for v in uncolored_set:
            mask |= (1 << v)
        return bit_count(bit_adj[u] & mask)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color_of = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = color_of[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color_of[u] = c
        return color_of

    # Helper: validate coloring
    def is_valid(color_of):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and color_of[u] == color_of[v]:
                    return False
        return True

    # Helper: normalize colors to 0..k-1
    def normalize(color_of):
        mapping = {}
        next_color = 0
        for c in color_of:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in color_of]

    # DSATUR
    def dsatur():
        color_of = [-1] * n
        colored_mask = 0
        uncolored = set(range(n))
        for _ in range(n):
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation_degree(v, color_of, colored_mask)
                if sat > best_sat or (sat == best_sat and degree_in_uncolored(v, uncolored) > best_deg):
                    best_sat = sat
                    best_deg = degree_in_uncolored(v, uncolored)
                    best_v = v
            v = best_v
            used = 0
            for u in adj_list[v]:
                c = color_of[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color_of[v] = c
            colored_mask |= (1 << v)
            uncolored.remove(v)
        return normalize(color_of)

    # RLF (Recursive Largest First)
    def rlf():
        color_of = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Find vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: degree_in_uncolored(x, uncolored))
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and (bit_adj[v] & (1 << u)) == 0}
            # W: vertices adjacent to S
            W = {u for u in uncolored if u != v and (bit_adj[v] & (1 << u)) != 0}
            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                best_w_neighbors = -1
                best_deg_U = float('inf')
                for u in U:
                    w_neighbors = bit_count(bit_adj[u] & sum((1 << w) for w in W))
                    deg_U = degree_in_uncolored(u, U)
                    if w_neighbors > best_w_neighbors or (w_neighbors == best_w_neighbors and deg_U < best_deg_U):
                        best_w_neighbors = w_neighbors
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                neighbors_u = {w for w in adj_list[u] if w in U}
                U -= neighbors_u
                W |= neighbors_u
            for u in S:
                color_of[u] = color
            color += 1
            uncolored -= S
        return normalize(color_of)

    # Smallest-Last ordering
    def smallest_last():
        # Core decomposition to get removal order
        degrees = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current min degree
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    old_deg = degrees[u]
                    degrees[u] -= 1
                    buckets[old_deg].remove(u)
                    buckets[degrees[u]].append(u)
                    if degrees[u] < ptr:
                        ptr = degrees[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Kempe chain swap: try to swap colors a and b in component containing v
    def kempe_swap(color_of, v, a, b):
        if color_of[v] not in (a, b):
            return False
        # Find connected component of v in subgraph induced by colors a and b
        stack = [v]
        visited = set()
        comp_color_a = set()
        comp_color_b = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            c = color_of[u]
            if c == a:
                comp_color_a.add(u)
            elif c == b:
                comp_color_b.add(u)
            for w in adj_list[u]:
                if w not in visited and color_of[w] in (a, b):
                    stack.append(w)
        # Check if swapping is safe: no neighbor outside component has color a or b that would conflict
        # Actually, swapping within a component is always safe for Kempe chain
        # Perform swap
        for u in comp_color_a:
            color_of[u] = b
        for u in comp_color_b:
            color_of[u] = a
        return True

    # Attempt to eliminate a color class via Kempe chains
    def reduce_colors(color_of):
        # Get color classes
        classes = {}
        for v, c in enumerate(color_of):
            classes.setdefault(c, []).append(v)
        if not classes:
            return color_of
        max_color = max(classes.keys())
        # Try to eliminate color classes from highest down
        for c in range(max_color, 0, -1):
            if c not in classes:
                continue
            vertices_c = classes[c]
            # Try to recolor each vertex in class c to a lower color
            changed = False
            for v in vertices_c[:]:  # copy because we may modify
                # Try direct reassignment to a lower color
                for target in range(c):
                    conflict = False
                    for u in adj_list[v]:
                        if color_of[u] == target:
                            conflict = True
                            break
                    if not conflict:
                        # Move v to target color
                        color_of[v] = target
                        classes[c].remove(v)
                        classes.setdefault(target, []).append(v)
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for target in range(c):
                    # Try to swap along (c, target) Kempe chain
                    # Make a copy to test
                    test_color = color_of[:]
                    if kempe_swap(test_color, v, c, target):
                        # Check if after swap, v is no longer color c (it should be target)
                        if test_color[v] != c:
                            color_of[:] = test_color
                            # Rebuild classes
                            classes = {}
                            for ii, col in enumerate(color_of):
                                classes.setdefault(col, []).append(ii)
                            changed = True
                            break
                if changed:
                    break
            if not changed and c in classes and classes[c]:
                # Could not eliminate this color, move to next lower
                continue
            # If we eliminated color c, restart from high
            if changed:
                return reduce_colors(color_of)
        return color_of

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate, fallback to greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        candidates.append(greedy_color(order))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: max(x) + 1 if x else 0)
    best = normalize(best)

    # Try to reduce colors using Kempe chains
    best = reduce_colors(best)
    best = normalize(best)

    # Final validation (should always hold)
    if not is_valid(best):
        # Last resort: greedy DSATUR again
        best = dsatur()
        best = normalize(best)

    return best

import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix if square and binary, else adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True

    # Build neighbor list and bitmask representation
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if v < n:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # Candidate 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        uncolored = set(range(n))
        # Precompute degrees for tie-breaking
        deg = [len(neighbors[i]) for i in range(n)]
        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_mask = 0
                for u in neighbors[v]:
                    if color[u] != -1:
                        sat_mask |= (1 << color[u])
                sat = sat_mask.bit_count()
                if sat > best_sat or (sat == best_sat and (deg[v] > best_deg or (deg[v] == best_deg and random.random() < 0.5))):
                    best_sat = sat
                    best_deg = deg[v]
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
        return color

    # Candidate 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            S = set()
            # Compute degrees in uncolored subgraph
            deg_uncolored = {v: len(neighbors[v] & uncolored) for v in uncolored}
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v} - (neighbors[v] & uncolored)
            W = neighbors[v] & uncolored
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = -1
                for u in U:
                    score = len(neighbors[u] & W)
                    degU = len(neighbors[u] & U)
                    if score > best_score or (score == best_score and degU < best_degU):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_u = neighbors[u] & U
                U -= nbrs_u
                W |= nbrs_u
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Candidate 3: Smallest-Last ordering (Matula-Beck)
    def smallest_last():
        # Core decomposition to get removal order
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].add(v)
        # Process from lowest degree up
        for d in range(max_deg + 1):
            while buckets[d]:
                # Find a vertex in bucket d that is still remaining
                v = None
                for candidate in buckets[d]:
                    if candidate in remaining:
                        v = candidate
                        break
                if v is None:
                    continue
                # Remove v
                order.append(v)
                remaining.remove(v)
                # Update neighbors
                for u in neighbors[v]:
                    if u in remaining:
                        old_deg = deg[u]
                        deg[u] -= 1
                        if old_deg <= max_deg:
                            buckets[old_deg].discard(u)
                            if deg[u] <= max_deg:
                                buckets[deg[u]].add(u)
        # Color in reverse order
        return greedy_color(reversed(order))

    # Generate initial candidates
    candidates = []
    for func in [dsatur, rlf, smallest_last]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(compact_colors(col))
        except:
            continue

    # Fallback: simple greedy by degree order
    if not candidates:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        col = greedy_color(order)
        if is_valid(col):
            candidates.append(compact_colors(col))
        else:
            # Last resort: assign each vertex a unique color
            candidates.append(list(range(n)))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best_k = num_colors(best)

    # Iterative Kempe chain reduction: try to eliminate highest color class
    improved = True
    while improved and best_k > 1:
        improved = False
        target_color = best_k - 1
        # Get vertices with target color
        target_vertices = [v for v in range(n) if best[v] == target_color]
        random.shuffle(target_vertices)  # Randomize order for robustness
        for v in target_vertices:
            # Try to recolor v to a lower color directly
            neighbor_colors = set()
            for u in neighbors[v]:
                if best[u] < target_color:
                    neighbor_colors.add(best[u])
            for c in range(target_color):
                if c not in neighbor_colors:
                    # Direct reassignment possible
                    best[v] = c
                    improved = True
                    break
            if improved:
                # After change, check if target color class is empty
                if target_color not in best:
                    # Compact colors
                    best = compact_colors(best)
                    best_k = num_colors(best)
                    break  # Restart with new highest color
                else:
                    # Continue trying other vertices in same target class
                    continue
            # If direct reassignment not possible, try Kempe chains
            for c in range(target_color):
                # Check if v can be swapped via (c, target_color) Kempe chain
                # Build the component containing v in the subgraph of colors c and target_color
                from collections import deque
                visited = set()
                queue = deque([v])
                visited.add(v)
                component = set()
                while queue:
                    x = queue.popleft()
                    component.add(x)
                    for y in neighbors[x]:
                        if y not in visited and (best[y] == c or best[y] == target_color):
                            visited.add(y)
                            queue.append(y)
                # Check if any neighbor of v in the component has color c (would cause conflict if swapped)
                conflict = False
                for x in component:
                    for y in neighbors[x]:
                        if y not in component and best[y] == c:
                            conflict = True
                            break
                    if conflict:
                        break
                if not conflict:
                    # Perform swap: c <-> target_color in component
                    for x in component:
                        if best[x] == c:
                            best[x] = target_color
                        elif best[x] == target_color:
                            best[x] = c
                    improved = True
                    # After swap, v now has color c
                    break
            if improved:
                # Check if target color class is now empty
                if target_color not in best:
                    best = compact_colors(best)
                    best_k = num_colors(best)
                    break
        # End while improved

    # Final validation and compacting
    if not is_valid(best):
        # Fallback to greedy if something went wrong
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        best = greedy_color(order)
    best = compact_colors(best)
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix (binary square) or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            for j in adj_list[i]:
                bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by max degree in uncolored, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                # count bits in sat[u]
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and (uncolored_deg[u] > max_deg or (uncolored_deg[u] == max_deg and random.random() < 0.5))):
                    max_sat = s
                    max_deg = uncolored_deg[u]
                    v = u
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = uncolored - {v} - set(adj_list[v])
            W = set(adj_list[v]) & uncolored
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for candidate in U:
                    w_neighbors = sum(1 for y in adj_list[candidate] if y in W)
                    deg_in_U = sum(1 for y in adj_list[candidate] if y in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        u = candidate
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in adj_list[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
            uncolored -= independent_set
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        degree = [len(adj_list[i]) for i in range(n)]
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].append(i)
        # Pointers for current min degree
        order = []
        # Current degree and position
        curr_deg = degree[:]
        pos = list(range(n))
        # For each vertex, we maintain its bucket index
        # We'll simulate removal
        seen = [False] * n
        for _ in range(n):
            # Find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].pop()
            if seen[v]:
                # Find another
                while buckets[d] and seen[buckets[d][-1]]:
                    buckets[d].pop()
                if not buckets[d]:
                    d += 1
                    while d <= max_deg and not buckets[d]:
                        d += 1
                    if d > max_deg:
                        break
                    v = buckets[d].pop()
            seen[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for u in adj_list[v]:
                if not seen[u]:
                    # Remove u from its current bucket
                    old_deg = curr_deg[u]
                    buckets[old_deg].remove(u)
                    curr_deg[u] -= 1
                    new_deg = curr_deg[u]
                    buckets[new_deg].append(u)
                    # Update max_deg if needed
                    if new_deg > max_deg:
                        max_deg = new_deg
        # Color in reverse order
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        candidates.append(greedy_color(list(range(n))))

    # Select candidate with fewest colors
    best = min(candidates, key=count_colors)
    k = count_colors(best)

    # Kempe chain-based color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color to lower colors
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return True, coloring  # already eliminated
        # For each vertex, try to move to a lower color
        for v in vertices:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            # Try direct reassignment to any lower color
            for c in range(target_color):
                if not (used & (1 << c)):
                    # Move v to color c
                    coloring[v] = c
                    break
            else:
                # Direct move not possible, try Kempe chains
                moved = False
                for c in range(target_color):
                    # Check if v and any vertex of color c are in different components of (target_color, c) subgraph
                    # We'll try to swap a component containing v
                    # BFS to get the Kempe chain component of v in colors {target_color, c}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in adj_list[x]:
                            if not visited[y] and (coloring[y] == target_color or coloring[y] == c):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of v in the component has color c? Actually, we want to see if we can swap
                    # After swap, v would become color c. We need to ensure no neighbor of v has color c after swap.
                    # Neighbors of v that are in the component and have color c will become target_color -> conflict if adjacent to v?
                    # Actually, after swap, neighbors in component that were color c become target_color.
                    # So if v has a neighbor in the component that is color c, after swap that neighbor becomes target_color -> same as v's new color? No, v becomes c, neighbor becomes target_color -> different.
                    # The only conflict would be if v has a neighbor not in the component that is color c -> remains c, and v becomes c -> conflict.
                    # So we need: no neighbor of v outside the component has color c.
                    conflict = False
                    for y in adj_list[v]:
                        if not visited[y] and coloring[y] == c:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: swap colors target_color and c in the component
                        for x in component:
                            if coloring[x] == target_color:
                                coloring[x] = c
                            elif coloring[x] == c:
                                coloring[x] = target_color
                        moved = True
                        break
                if not moved:
                    return False, coloring
        return True, coloring

    # Try to reduce colors from highest downward
    current_coloring = best[:]
    changed = True
    while changed and count_colors(current_coloring) > 0:
        changed = False
        k_curr = count_colors(current_coloring)
        # Try to eliminate the highest color class
        for target in range(k_curr - 1, -1, -1):
            success, new_coloring = eliminate_color_class(current_coloring[:], target)
            if success:
                # Compact colors: remap to 0..new_k-1
                mapping = {}
                next_color = 0
                for v in range(n):
                    col = new_coloring[v]
                    if col not in mapping:
                        mapping[col] = next_color
                        next_color += 1
                    new_coloring[v] = mapping[col]
                current_coloring = new_coloring
                changed = True
                break  # restart from highest color after compacting

    # Final validation and compacting (ensure 0..k-1)
    if not is_valid(current_coloring):
        current_coloring = best  # fallback to best validated
    # Compact colors
    mapping = {}
    next_color = 0
    for v in range(n):
        col = current_coloring[v]
        if col not in mapping:
            mapping[col] = next_color
            next_color += 1
        current_coloring[v] = mapping[col]

    return current_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix
    is_matrix = True
    if len(adj[0]) != n:
        is_matrix = False
    else:
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor bitmasks and list
    bit_adj = [0] * n
    neighbors = [[] for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
                    neighbors[i].append(j)
    else:
        for i in range(n):
            for j in adj[i]:
                bit_adj[i] |= (1 << j)
                neighbors[i].append(j)

    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    def kempe_chain(color, a, b, start):
        stack = [start]
        visited = set()
        while stack:
            v = stack.pop()
            if v in visited:
                continue
            visited.add(v)
            if color[v] not in (a, b):
                continue
            for u in neighbors[v]:
                if color[u] in (a, b) and u not in visited:
                    stack.append(u)
        return visited

    def local_search(color, max_iter=1000):
        n = len(color)
        current = color[:]
        best = current[:]
        best_k = max(best) + 1 if best else 0
        for _ in range(max_iter):
            # Find a conflict
            conflict = -1
            for u in range(n):
                for v in neighbors[u]:
                    if u < v and current[u] == current[v]:
                        conflict = u
                        break
                if conflict != -1:
                    break
            if conflict == -1:
                break  # No conflicts
            # Try to recolor conflict vertex
            used = set()
            for u in neighbors[conflict]:
                c = current[u]
                if c != -1:
                    used.add(c)
            # Try all possible colors up to best_k + 1
            for c in range(best_k + 2):
                if c not in used:
                    current[conflict] = c
                    # Check if this reduces the number of colors
                    new_k = max(current) + 1
                    if new_k < best_k:
                        best = current[:]
                        best_k = new_k
                    # Break after first improvement to stay fast
                    break
            else:
                # No improvement, revert and try Kempe
                current[conflict] = -1  # Uncolor temporarily
                # Try to fix by Kempe chain
                for c1 in range(best_k + 1):
                    if c1 in used:
                        continue
                    for c2 in used:
                        if c1 == c2:
                            continue
                        # Find a neighbor with color c2
                        for u in neighbors[conflict]:
                            if current[u] == c2:
                                chain = kempe_chain(current, c1, c2, u)
                                # Check if conflict is not in chain (so we can swap)
                                if conflict not in chain:
                                    # Swap colors c1 and c2 in chain
                                    for v in chain:
                                        if current[v] == c1:
                                            current[v] = c2
                                        elif current[v] == c2:
                                            current[v] = c1
                                    # Now try to color conflict with c1
                                    used2 = set()
                                    for v in neighbors[conflict]:
                                        cv = current[v]
                                        if cv != -1:
                                            used2.add(cv)
                                    if c1 not in used2:
                                        current[conflict] = c1
                                        new_k = max(current) + 1
                                        if new_k < best_k:
                                            best = current[:]
                                            best_k = new_k
                                        break
                                break
                        else:
                            continue
                        break
                    else:
                        continue
                    break
                current[conflict] = 0  # Reset if no Kempe worked (should not happen often)
        return best

    # Generate multiple random orders
    best_coloring = None
    best_k = float('inf')
    vertices = list(range(n))
    start_time = time.time()

    # We'll do 10 iterations or until 40ms passed
    for _ in range(10):
        if time.time() - start_time > 0.04:  # Leave 10ms for local search
            break
        order = vertices[:]
        random.shuffle(order)
        # Also try degree-based order
        random.shuffle(order)  # Second shuffle for more randomness
        color = greedy_color(order)
        k = max(color) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_coloring = color

    # If no coloring found (should not happen), use greedy
    if best_coloring is None:
        best_coloring = greedy_color(vertices)
        best_k = max(best_coloring) + 1 if n > 0 else 0

    # Apply local search to improve
    improved = local_search(best_coloring, max_iter=200)
    final_k = max(improved) + 1 if n > 0 else 0
    if final_k < best_k:
        best_coloring = improved

    # Compact colors
    if n > 0:
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = best_coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            best_coloring[i] = unique_colors[c]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle trivial cases
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix (square binary) or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    if not is_matrix:
        # Treat as adjacency list; ensure it's a list of lists
        for i in range(n):
            if not isinstance(adj[i], list):
                adj[i] = list(adj[i]) if hasattr(adj[i], '__iter__') else []

    # Build neighbor sets and bitmasks for fast operations
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    for u in range(n):
        if is_matrix:
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)
        else:
            for v in adj[u]:
                if v < n:  # Safety check
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)

    # Helper: compute chromatic number from coloring
    def chromatic_number(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in neighbors[u]:
                if coloring[v] == cu:
                    return False
        return True

    # Strategy 1: Jaccard-based greedy coloring for non-adjacent vertex pairs
    def jaccard_based_coloring():
        uncolored = set(range(n))
        coloring = [-1] * n
        color = 0
        # Precompute Jaccard similarities for non-adjacent pairs
        jaccard = [[0.0] * n for _ in range(n)]
        for u in range(n):
            for v in range(u + 1, n):
                if v not in neighbors[u]:  # non-adjacent
                    inter = len(neighbors[u] & neighbors[v])
                    union = len(neighbors[u] | neighbors[v])
                    jaccard[u][v] = jaccard[v][u] = inter / union if union > 0 else 0.0
        while uncolored:
            # Find the uncolored vertex with highest degree (break ties randomly)
            u = max(uncolored, key=lambda x: (len(neighbors[x]), random.random()))
            # Start a new color class with u
            coloring[u] = color
            uncolored.remove(u)
            # Candidates: uncolored vertices not adjacent to u
            candidates = [v for v in uncolored if v not in neighbors[u]]
            if not candidates:
                color += 1
                continue
            # Sort candidates by Jaccard similarity with u (descending), break ties randomly
            candidates.sort(key=lambda v: (jaccard[u][v], random.random()), reverse=True)
            # Try to add as many non-adjacent vertices with high Jaccard similarity
            for v in candidates:
                if v not in uncolored:
                    continue
                # Check if v is compatible with all vertices in this color class
                compatible = True
                color_class_vertices = [w for w in range(n) if coloring[w] == color]
                for w in color_class_vertices:
                    if v in neighbors[w]:
                        compatible = False
                        break
                if compatible:
                    coloring[v] = color
                    uncolored.remove(v)
            color += 1
        return coloring

    # Strategy 2: DSATUR with bitmask optimization
    def dsatur_coloring():
        coloring = [-1] * n
        # saturation[v] = bitmask of colors used by colored neighbors
        saturation = [0] * n
        colored_count = 0
        while colored_count < n:
            # Select uncolored vertex with max saturation, break ties by degree (uncolored neighbors), then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if coloring[v] == -1:
                    sat = saturation[v].bit_count()
                    # Degree in uncolored subgraph: count uncolored neighbors
                    deg = 0
                    for u in neighbors[v]:
                        if coloring[u] == -1:
                            deg += 1
                    if sat > best_sat or (sat == best_sat and deg > best_deg) or \
                       (sat == best_sat and deg == best_deg and random.random() < 0.5):
                        best_sat = sat
                        best_deg = deg
                        best_v = v
            v = best_v
            # Find smallest available color (MEX)
            used_colors = saturation[v]
            c = 0
            while used_colors & (1 << c):
                c += 1
            coloring[v] = c
            colored_count += 1
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if coloring[u] == -1:
                    saturation[u] |= (1 << c)
        return coloring

    # Strategy 3: Recursive Largest First (RLF)
    def rlf_coloring():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build maximal independent set for this color
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            independent_set.add(v)
            # Partition: U = vertices not adjacent to any in independent_set, W = adjacent
            U = {u for u in uncolored if u not in independent_set and not any(w in neighbors[u] for w in independent_set)}
            W = uncolored - independent_set - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in G[U]
                best_u = -1
                best_score = -1
                best_deg_u = float('inf')
                for u in U:
                    # Score: number of neighbors in W
                    score = len([w for w in neighbors[u] if w in W])
                    # Degree in G[U]
                    deg_u = len([w for w in neighbors[u] if w in U])
                    if score > best_score or (score == best_score and deg_u < best_deg_u) or \
                       (score == best_score and deg_u == best_deg_u and random.random() < 0.5):
                        best_score = score
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in list(U):  # iterate over copy
                    if w in neighbors[u]:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
            uncolored -= independent_set
            color += 1
        return coloring

    # Strategy 4: Smallest-Last (SL) ordering greedy
    def sl_coloring():
        # Compute smallest-last ordering
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[v]) for v in range(n)]
        # We'll simulate peeling by updating degrees
        deg_copy = degrees[:]
        for _ in range(n):
            # Find vertex with minimum degree in remaining
            min_v = -1
            min_deg = float('inf')
            for v in remaining:
                if deg_copy[v] < min_deg:
                    min_deg = deg_copy[v]
                    min_v = v
            if min_v == -1:
                break  # should not happen
            order.append(min_v)
            remaining.remove(min_v)
            # Update degrees of neighbors
            for u in neighbors[min_v]:
                if u in remaining:
                    deg_copy[u] -= 1
        # Color in reverse order (last peeled first)
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Generate candidate colorings
    candidates = []
    try:
        c1 = jaccard_based_coloring()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = dsatur_coloring()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = rlf_coloring()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    try:
        c4 = sl_coloring()
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass

    # Select best candidate (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for coloring in candidates:
        k = chromatic_number(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring

    # Fallback: if no candidate succeeded, use greedy by degree
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
