    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = [j for j in range(n) if adj[i][j] == 1]
            adj_list.append(neighbors)
    else:
        adj_list = [list(neighbors) for neighbors in adj]  # Ensure list of ints

    degrees = [len(adj_list[i]) for i in range(n)]

    # Precompute bitmasks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: First-Fit greedy coloring given an order
    def greedy_color(order):
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Helper: Welsh-Powell ordering (degree descending)
    def welsh_powell_order():
        return sorted(range(n), key=lambda x: (-degrees[x], x))

    # Helper: Smallest-Last (degeneracy) ordering
    def smallest_last_order():
        if n == 0:
            return []
        deg = degrees[:]
        alive = [True] * n
        order = []
        for _ in range(n):
            min_deg = n
            v = -1
            for i in range(n):
                if alive[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break
            order.append(v)
            alive[v] = False
            for u in adj_list[v]:
                if alive[u]:
                    deg[u] -= 1
        return order[::-1]  # reverse for coloring order

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then index
            v = -1
            max_sat = -1
            max_deg_uncolored = -1
            for u in uncolored:
                sat_u = saturated[u]
                deg_uncolored = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        deg_uncolored += 1
                if sat_u > max_sat or (sat_u == max_sat and deg_uncolored > max_deg_uncolored) or \
                   (sat_u == max_sat and deg_uncolored == max_deg_uncolored and u < v):
                    max_sat = sat_u
                    max_deg_uncolored = deg_uncolored
                    v = u
            # Assign smallest available color
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u] += 1
        return coloring

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        coloring = [-1] * n
