            v = -1
            max_deg = -1
            for u in uncolored:
                deg_uncolored = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        deg_uncolored += 1
                if deg_uncolored > max_deg:
                    max_deg = deg_uncolored
                    v = u
            if v == -1:
                break  # should not happen if uncolored non-empty
            S.add(v)
            # Partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            for u in U:
                for w in S:
                    if w in adj_list[u]:
                        W.add(u)
                        break
            U -= W
            # Greedily add vertices from U to S
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_neighbors_W = -1
                min_deg_U = n
                for u in U:
                    neighbors_in_W = 0
                    for w in adj_list[u]:
                        if w in W:
                            neighbors_in_W += 1
                    # Degree in U-induced subgraph
                    deg_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_U += 1
                    if (neighbors_in_W > max_neighbors_W or
                        (neighbors_in_W == max_neighbors_W and deg_U < min_deg_U) or
                        (neighbors_in_W == max_neighbors_W and deg_U == min_deg_U and u < best_u)):
                        max_neighbors_W = neighbors_in_W
                        min_deg_U = deg_U
                        best_u = u
                # Add best_u to S, update U and W
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u in U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
