    wp_order = welsh_powell_order()
    wp_coloring = greedy_color(wp_order)
    if is_valid(wp_coloring):
        candidates.append(wp_coloring)

    # Smallest-Last
    sl_order = smallest_last_order()
    sl_coloring = greedy_color(sl_order)
    if is_valid(sl_coloring):
        candidates.append(sl_coloring)

    # DSATUR
    ds_coloring = dsatur()
    if is_valid(ds_coloring):
        candidates.append(ds_coloring)

    # RLF
    rl_coloring = rlf()
    if is_valid(rl_coloring):
        candidates.append(rl_coloring)

    # If no candidate (should not happen), fallback to Welsh-Powell
    if not candidates:
        candidates.append(wp_coloring)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Kempe chain-based color reduction
    def eliminate_color_class(coloring, target_color):
        # Returns (new_coloring, success) where success is True if target_color class eliminated
        vertices = [v for v in range(n) if coloring[v] == target_color]
        if not vertices:
            return coloring, True  # already empty
        # Try to recolor each vertex in the class
        for v in vertices:
            # Try direct reassignment to a lower color
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            for c in range(target_color):  # only try colors < target_color
                if not (used & (1 << c)):
                    # Move v to color c
                    coloring[v] = c
                    # Update used for neighbors? Not needed as we check per vertex
                    break
            else:
                # Direct reassignment failed, try Kempe chains
                for c in range(target_color):
                    # Check if v can be swapped via (target_color, c) Kempe chain
                    # We want to see if v is not connected to any vertex of color c via a chain
                    # that would cause conflict if swapped. Actually, we can swap the component
                    # containing v in the subgraph of colors {target_color, c} if it does not
                    # contain any vertex of color c that is adjacent to a vertex of color target_color
                    # outside the component? Standard: swap the Kempe chain of v for colors (target_color, c)
                    # if it does not contain a neighbor of v of color c.
                    # Actually, we can always swap the component containing v; after swap, v becomes color c.
                    # We need to ensure that no neighbor of v becomes color c after swap? 
                    # After swap, neighbors of v that were color target_color become color c, and vice versa.
                    # So if any neighbor of v is color c, after swap it becomes target_color, which is ok as long as
                    # it doesn't conflict. Actually, the swap preserves validity.
                    # The only issue is if we want to free color target_color entirely, we need to ensure
                    # that after swap, no vertex remains in target_color. But we are processing one vertex at a time.
                    # Instead, we attempt to recolor v to c via Kempe swap, and if successful, we break.
                    # The swap will change the color of v and possibly others in the component.
                    # We will update the coloring accordingly and check if v is no longer target_color.
                    # Build the Kempe chain component containing v for colors {target_color, c}
                    from collections import deque
                    comp = set()
                    queue = deque([v])
                    comp.add(v)
                    while queue:
                        x = queue.popleft()
                        for y in adj_list[x]:
                            if y not in comp and (coloring[y] == target_color or coloring[y] == c):
                                comp.add(y)
                                queue.append(y)
                    # Check if swapping this component is safe: after swap, no adjacent vertices same color.
                    # Actually, Kempe swap always preserves validity. So we can perform it.
                    # Perform swap: target_color <-> c in the component
                    for x in comp:
                        if coloring[x] == target_color:
                            coloring[x] = c
                        elif coloring[x] == c:
                            coloring[x] = target_color
                    # Now v has color c (since it was target_color and in comp)
                    if coloring[v] == c:
                        return coloring, True  # v is no longer in target_color
                    # If not, something went wrong (should not happen)
                # If no Kempe swap worked, leave v in target_color (will fail elimination)
        # After processing all vertices, check if target_color class is empty
        new_vertices = [v for v in range(n) if coloring[v] == target_color]
        if not new_vertices:
            return coloring, True
        return coloring, False

    # Try to reduce colors iteratively
    current = best[:]
    changed = True
    while changed and num_colors(current) > 1:
        changed = False
        k_curr = num_colors(current)
        # Target the smallest color class (highest color index) for elimination
        target_color = k_curr - 1
        new_current, success = eliminate_color_class(current[:], target_color)  # work on copy
        if success:
            current = new_current
            changed = True
            # Compact colors: remap to 0..k-2
            mapping = {}
            next_color = 0
            for v in range(n):
                c = current[v]
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
                current[v] = mapping[c]
        # else: try next lower color? For simplicity, we break if cannot eliminate highest
        # but we could try lower colors; however, eliminating highest is most promising for reduction.
        # We'll break if cannot eliminate the current highest to avoid infinite loop.
        if not changed:
            break

    # Final validation and compacting (ensure colors are 0..k-1)
    # Re-compact just in case
    mapping = {}
    next_color = 0
    for v in range(n):
        c = current[v]
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
        current[v] = mapping[c]

    if not is_valid(current):
        # Fallback to best candidate if Kempe messed up
        current = best
        mapping = {}
        next_color = 0
        for v in range(n):
            c = current[v]
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
            current[v] = mapping[c]

    return current

