    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: count colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert to compact 0..k-1 colors
    def compact_colors(coloring):
        if not coloring:
            return coloring
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = [False] * n
            for v in adj_list[u]:
                if coloring[v] != -1:
                    used[coloring[v]] = True
            for c in range(n):
                if not used[c]:
                    coloring[u] = c
                    break
        return coloring

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        saturated = [set() for _ in range(n)]
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation, tie-break by degree, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = len(saturated[v])
                deg = degree[v]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
