        return coloring

    # Helper: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set.add(v)
            to_remove = {v}
            # Partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = uncolored - {v} - {u for u in adj_list[v] if u in uncolored}
            W = {u for u in adj_list[v] if u in uncolored}

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for nb in adj_list[u] if nb in W)
                    deg_u = sum(1 for nb in adj_list[u] if nb in U)
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u) or \
                       (w_neighbors == best_w_neighbors and deg_u == best_deg_u and random.random() < 0.5):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                to_remove.add(u)
                # Move u from U to W, and move its neighbors in U to W
                U.remove(u)
                W.add(u)
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to independent set
            for v in independent_set:
                coloring[v] = color
            uncolored -= to_remove
            color += 1
        return coloring

    # Helper: Smallest-Last ordering greedy
    def smallest_last():
        # Build smallest-last ordering
        remaining = set(range(n))
        order = []
        degrees = [len([nb for nb in adj_list[v] if nb in remaining]) for v in range(n)]
        # Use bucket queue for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degrees[v]
            if d < len(buckets):
                buckets[d].append(v)
        # Pointer to current min non-empty bucket
        min_bucket = 0
        while remaining:
            # Find next non-empty bucket
            while min_bucket < len(buckets) and not buckets[min_bucket]:
                min_bucket += 1
            if min_bucket >= len(buckets):
                break
            # Get a vertex from the bucket
            v = buckets[min_bucket].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update degrees of neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    old_d = degrees[nb]
                    degrees[nb] -= 1
                    new_d = degrees[nb]
                    if new_d < len(buckets):
                        buckets[new_d].append(nb)
                    # If old_d bucket needs cleanup later, we ignore for simplicity
            # Adjust min_bucket if needed
            if min_bucket > new_d:
                min_bucket = new_d
        # Reverse to get coloring order
        order.reverse()
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(compact_colors(c1))
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(compact_colors(c2))
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(compact_colors(c3))
    except:
        pass

    # Fallback: simple greedy by degree
    if not candidates:
        order = sorted(range(n), key=lambda x: (-degree[x], x))
        c_fallback = greedy_color(order)
        if is_valid(c_fallback):
            candidates.append(compact_colors(c_fallback))

    # Select best candidate (fewest colors)
    if not candidates:
        # Ultimate fallback: assign each vertex a unique color
        return list(range(n))
    best = min(candidates, key=lambda c: (count_colors(c), c))
    return best

