                        min_deg_in_U = len(neighbors[u] & U)
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_in_U = len(neighbors[u] & U)
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = u
                if best_u is None:
                    break  # should not happen
                S.add(best_u)
                uncolored.remove(best_u)
                # Update W and U: move best_u's neighbors from U to W
                nbrs = neighbors[best_u] & uncolored
                W.update(nbrs)
                U = uncolored - W

            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1

        return compact_colors(coloring)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering: repeatedly remove min degree vertex
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # We'll use a list of sets for bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degrees[v]
            if d <= max_deg:
                buckets[d].add(v)

        for _ in range(n):
            # Find first non-empty bucket from low to high
            v = None
            for d in range(len(buckets)):
                if buckets[d]:
                    v = buckets[d].pop()
                    break
            if v is None:
                break
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_d = degrees[u]
                    buckets[old_d].remove(u)
                    new_d = old_d - 1
                    degrees[u] = new_d
                    if new_d < len(buckets):
                        buckets[new_d].add(u)
                    else:
                        # Should not happen if buckets sized correctly
                        pass
            remaining.remove(v)

        # Color in reverse order using greedy first-fit
        coloring = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c

        return compact_colors(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not coloring:
            return coloring
        # Ensure coloring is compact and valid
        coloring = compact_colors(coloring)
        if not is_valid(coloring):
            return coloring  # fallback, should not happen if input valid

        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # Target the smallest color class (highest color index)
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already compacted?
                coloring = compact_colors(coloring)
                k = num_colors(coloring)
                continue

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in neighbors[v]:
                    if coloring[u] != -1:
                        neighbor_colors.add(coloring[u])
                for c in range(target_color):  # try colors 0 to target_color-1
                    if c not in neighbor_colors:
                        # Move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # We'll do BFS/DFS to get the component containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for nbr in neighbors[node]:
                                if nbr not in visited and (coloring[nbr] == target_color or coloring[nbr] == c):
                                    stack.append(nbr)

                    # Check if swapping colors in component would cause conflict
                    # Specifically, after swap, no vertex in component should have a neighbor
                    # with the same color (which would be the other color in the pair)
                    valid_swap = True
                    for node in component:
                        new_color = c if coloring[node] == target_color else target_color
                        for nbr in neighbors[node]:
                            if coloring[nbr] == new_color:
                                valid_swap = False
                                break
                        if not valid_swap:
                            break

                    if valid_swap:
                        # Perform the swap
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        improved = True
                        break
                if improved:
                    break

            if improved:
                # Compact colors and update k
                coloring = compact_colors(coloring)
                k = num_colors(coloring)
            else:
                # Could not eliminate target color, break
                break

        return coloring

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    # List of heuristic functions
    heuristics = [dsatur, rlf, smallest_last]

    for heuristic in heuristics:
        try:
            coloring = heuristic()
            if not is_valid(coloring):
                continue
            k = num_colors(coloring)
            if k < best_k or (k == best_k and (best_coloring is None or sum(1 for c in coloring if c == 0) > sum(1 for c in best_coloring if c == 0))):
                best_k = k
                best_coloring = coloring
        except Exception:
            continue  # skip heuristic on error

    # Fallback: if no heuristic produced valid coloring, use greedy by degree
    if best_coloring is None:
        ordering = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        coloring = [-1] * n
        for v in ordering:
            used = set()
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best_coloring = compact_colors(coloring)

    # Apply Kempe chain reduction to try to improve
    try:
        improved = kempe_reduce(best_coloring)
        if is_valid(improved):
            k_improved = num_colors(improved)
            k_best = num_colors(best_coloring)
            if k_improved < k_best or (k_improved == k_best and sum(1 for c in improved if c == 0) > sum(1 for c in best_coloring if c == 0)):
                best_coloring = improved
    except Exception:
        pass

    # Final validation and compaction
    if not is_valid(best_coloring):
        # Last resort: greedy coloring
        ordering = list(range(n))
        coloring = [-1] * n
        for v in ordering:
            used = set()
            for u in neighbors[v]:
                if coloring[u] != -1:
                    used.add(coloring[u])
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best_coloring = compact_colors(coloring)

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert input to adjacency list if needed
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if coloring[v] == cu:
                    return False
        return True

    # Helper: count number of colors used
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: renumber colors to be consecutive from 0
    def renumber_colors(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # Helper: greedy coloring with given order
    def greedy_coloring(order):
        coloring = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
        return renumber_colors(coloring)

    # Helper: DSATUR
    def dsatur():
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # colored neighbor sets for saturation update
        colored_neighbors = [set() for _ in range(n)]
        uncolored = set(range(n))
        # initial degree for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]
        while uncolored:
            # select vertex with max saturation, then max degree, then min index
            v = max(uncolored, key=lambda x: (sat[x], degrees[x], -x))
            # find smallest available color
            used = [False] * n
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used[coloring[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if c not in colored_neighbors[u]:
                        colored_neighbors[u].add(c)
                        sat[u] += 1
        return renumber_colors(coloring)

    # Helper: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # independent set for this color
            S = set()
            # start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
                S.add(v)
                uncolored.remove(v)
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = {u for u in uncolored if not any(w in S for w in adj_list[u])}
            W = uncolored - U
            while U:
                # select u in U with max neighbors in W, then min degree in U
                def score(u):
                    neighbors_in_W = len([w for w in adj_list[u] if w in W])
                    deg_in_U = len([w for w in adj_list[u] if w in U])
                    return (neighbors_in_W, -deg_in_U)
                u = max(U, key=score)
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1
        return renumber_colors(coloring)

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # we will remove min degree vertex repeatedly
        temp_degree = degree[:]
        remaining_set = set(range(n))
        stack = []
        while remaining_set:
            # find vertex with min degree in remaining
            v = min(remaining_set, key=lambda x: temp_degree[x])
            stack.append(v)
            remaining_set.remove(v)
            for u in adj_list[v]:
                if u in remaining_set:
                    temp_degree[u] -= 1
        # reverse stack for coloring order
        order = stack[::-1]
        return greedy_coloring(order)

    # Helper: Kempe chain swap for (a,b) chain containing v
    def kempe_swap(coloring, a, b, v):
        # returns new coloring after swapping a and b in the component of v in (a,b)-subgraph
        # or None if v not colored a or b
        if coloring[v] not in (a, b):
            return None
        # BFS to get the (a,b)-component of v
        from collections import deque
        queue = deque([v])
        visited = set([v])
        comp = set()
        target_colors = {a, b}
        while queue:
            u = queue.popleft()
            comp.add(u)
            for w in adj_list[u]:
                if w not in visited and coloring[w] in target_colors:
                    visited.add(w)
                    queue.append(w)
        # swap colors in component
        new_coloring = coloring[:]
        for u in comp:
            if new_coloring[u] == a:
                new_coloring[u] = b
            else:
                new_coloring[u] = a
        return new_coloring

    # Helper: try to eliminate the last color using Kempe chains
    def reduce_colors(coloring):
        k = count_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color k-1
        target_color = k - 1
        vertices = [v for v in range(n) if coloring[v] == target_color]
        # try direct reassignment first
        for v in vertices:
            used = [False] * n
            for u in adj_list[v]:
                if coloring[u] != -1 and coloring[u] < target_color:
                    used[coloring[u]] = True
            for c in range(target_color):
                if not used[c]:
                    # move v to color c
                    new_coloring = coloring[:]
                    new_coloring[v] = c
                    # renumber to fill gap if target_color is no longer used
                    if target_color not in new_coloring:
                        new_coloring = renumber_colors(new_coloring)
                    return new_coloring
        # try Kempe chains
        for v in vertices:
            for c in range(target_color):
                swapped = kempe_swap(coloring, target_color, c, v)
                if swapped is not None:
                    # check if target_color is still used
                    if target_color not in swapped:
                        swapped = renumber_colors(swapped)
                    return swapped
        # cannot eliminate target_color
        return coloring

    # Generate candidate colorings
    candidates = []
    try:
        candidates.append(dsatur())
    except:
        pass
    try:
        candidates.append(rlf())
    except:
        pass
    try:
        candidates.append(smallest_last())
    except:
        pass

    # Also try Welsh-Powell (degree ordering)
    try:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        candidates.append(greedy_coloring(order))
    except:
        pass

    # Select best candidate (fewest colors)
    best = None
    best_colors = float('inf')
    for col in candidates:
        if is_valid_coloring(col):
            c = count_colors(col)
            if c < best_colors:
                best_colors = c
                best = col

    # If no valid candidate, fallback to greedy on natural order
    if best is None:
        best = greedy_coloring(list(range(n)))

    # Iteratively try to reduce colors using Kempe chains
    current = best
    while True:
        reduced = reduce_colors(current)
        if reduced is current or count_colors(reduced) >= count_colors(current):
            break
        current = reduced

    # Final validation and renumbering
    if not is_valid_coloring(current):
        # last resort: greedy on DSATUR order
        current = dsatur()
    current = renumber_colors(current)
    return current

