    n = len(adj)

    # Detect input format and convert to adjacency list
    if n > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Adjacency list (ensure no self-loops and symmetric)
        adj_list = [list(set(neighbors)) for neighbors in adj]
        for i in range(n):
            for j in adj_list[i]:
                if i != j and i not in adj_list[j]:
                    adj_list[j].append(i)

    # Precompute bit masks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: count bits in mask (Python 3.8+ has int.bit_count)
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: normalize colors to 0..k-1
    def normalize(colors):
        if not colors:
            return colors
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR algorithm
    def dsatur():
        colors = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbor masks for saturation calculation
        colored_mask = [0] * n

        # Order vertices by degree descending for initial tie-breaking
        order = list(range(n))
        order.sort(key=lambda x: len(adj_list[x]), reverse=True)

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph, then by order
            v = -1
            max_sat = -1
            max_deg = -1
            for u in order:
                if colors[u] != -1:
