                deg_u = 0
                for w in adj_list[u]:
                    if colors[w] == -1:
                        deg_u += 1
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or (sat_u == max_sat and deg_u == max_deg and order.index(u) < order.index(v)):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            if v == -1:  # should not happen
                break

