            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c

            # Update saturation for uncolored neighbors
            for w in adj_list[v]:
                if colors[w] == -1:
                    # If this color is new in w's neighborhood, increase saturation
                    if not (colored_mask[w] & (1 << c)):
                        saturation[w] += 1
                        colored_mask[w] |= (1 << c)
