                    w_neighbors = len([w for w in adj_list[u] if w in W])
                    deg_u = len([w for w in adj_list[u] if w in U])
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_u < min_deg_u) or (w_neighbors == max_w_neighbors and deg_u == min_deg_u and u < best_u):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u that are in U to W
                for w in adj_list[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent set
            for v in independent_set:
                colors[v] = color
            uncolored -= independent_set
            color += 1
