        order = []
        # We'll simulate peeling
        temp_degree = degree[:]
        remaining_set = set(range(n))
        for _ in range(n):
            # find vertex of min degree in remaining
            v = min(remaining_set, key=lambda x: temp_degree[x])
            order.append(v)
            remaining_set.remove(v)
            for w in adj_list[v]:
                if w in remaining_set:
                    temp_degree[w] -= 1
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for w in adj_list[v]:
                if colors[w] != -1:
                    neighbor_colors |= (1 << colors[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        return normalize(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                continue

            # Try to recolor each target vertex
            made_change = False
            for v in target_vertices[:]:  # work on a copy
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for w in adj_list[v]:
                    if colors[w] < target_color:
                        neighbor_colors.add(colors[w])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        colors[v] = c
                        made_change = True
                        break
                if made_change:
                    break

                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Skip if v already has color c (shouldn't happen here)
                    if colors[v] == c:
                        continue
                    # Find the Kempe chain component for colors (c, target_color) containing v
                    # We'll do BFS to find the component
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for w in adj_list[node]:
                            if not visited[w] and (colors[w] == c or colors[w] == target_color):
                                visited[w] = True
                                queue.append(w)
                    # Check if we can swap: after swap, v would get color c
                    # We need to ensure that no neighbor of v has color c after swap
                    # Actually, in the component, we swap c and target_color
                    # So neighbors of v that are in the component and have color c will become target_color
                    # But we are moving v from target_color to c, so we need to check that
                    # no neighbor of v (outside the component) has color c, and
                    # no neighbor of v in the component has color c (because after swap they become target_color, which is not c)
                    # Actually, after swap:
                    #   - v: target_color -> c
                    #   - any node in component with color c -> target_color
                    #   - any node in component with color target_color -> c
                    # So for a neighbor w of v:
                    #   If w not in component: color unchanged
                    #   If w in component: 
                    #        if was c -> becomes target_color
                    #        if was target_color -> becomes c
                    # We require that after swap, no neighbor has color c.
                    #   - For w not in component: if colors[w] == c -> conflict
                    #   - For w in component: 
                    #        if was c -> becomes target_color (not c) -> ok
                    #        if was target_color -> becomes c -> conflict if w is neighbor of v
                    # So we need:
                    #   No neighbor of v outside the component has color c.
                    #   No neighbor of v inside the component has color target_color (because they become c).
                    safe = True
                    for w in adj_list[v]:
                        if not visited[w]:  # outside component
                            if colors[w] == c:
                                safe = False
                                break
                        else:  # inside component
                            if colors[w] == target_color:  # will become c
                                safe = False
                                break
                    if safe:
                        # Perform swap
                        for node in component:
                            if colors[node] == c:
                                colors[node] = target_color
                            elif colors[node] == target_color:
                                colors[node] = c
                        made_change = True
