            # Check if target_color is still used
            if target_color not in colors:
                # Renormalize and restart reduction from scratch
                colors = normalize(colors)
                return kempe_reduce(colors)  # recurse with new coloring
        return normalize(colors)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to greedy
    if not candidates:
        colors = [-1] * n
        for v in range(n):
            neighbor_colors = 0
            for w in adj_list[v]:
                if colors[w] != -1:
                    neighbor_colors |= (1 << colors[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(normalize(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)

    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)

    # Final validation and normalization
    if not is_valid_coloring(best):
        # Fallback to simple greedy if something went wrong
        colors = [-1] * n
        for v in range(n):
            neighbor_colors = 0
            for w in adj_list[v]:
                if colors[w] != -1:
                    neighbor_colors |= (1 << colors[w])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
        best = normalize(colors)

    return best

