def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if adj is adjacency matrix (square and binary)
    is_matrix = True
    if len(adj[0]) != n:
        is_matrix = False
    else:
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: validate coloring
    def validate(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert coloring to consecutive 0..k-1
    def normalize(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # degrees in the full graph
        deg = [len(adj_list[i]) for i in range(n)]
        # saturation sets: bitmask of colors used by neighbors
        sat = [0] * n
        # uncolored set as bitmask
        uncolored = (1 << n) - 1

        for _ in range(n):
            # select vertex: max saturation, then max degree in uncolored, then min index
            best_v = -1
            best_sat = -1
            best_deg = -1
            # iterate over uncolored vertices
            u = uncolored
            while u:
                v = (u & -u).bit_length() - 1
                u &= u - 1
                # compute saturation degree: number of distinct colors in neighbors
                neighbor_colors = sat[v]
                s = neighbor_colors.bit_count()
                # degree in uncolored subgraph
                d = (bit_adj[v] & uncolored).bit_count()
                if s > best_sat or (s == best_sat and (d > best_deg or (d == best_deg and v < best_v))):
                    best_sat = s
                    best_deg = d
                    best_v = v
            v = best_v
            # find smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            # remove v from uncolored
            uncolored &= ~(1 << v)
            # update saturation of neighbors
            for nb in adj_list[v]:
                if uncolored & (1 << nb):
                    sat[nb] |= (1 << c)
        return color

    # RLF: Recursive Largest First
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # degree in current uncolored subgraph
            deg_uncolored = {}
            for v in uncolored:
                deg_uncolored[v] = len([nb for nb in adj_list[v] if nb in uncolored])
            # start with vertex of max degree in uncolored
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = uncolored - {v} - set(adj_list[v])
            W = set()
            for nb in adj_list[v]:
                if nb in uncolored and nb not in S:
                    W.add(nb)
            # while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_degU = None
                for u in U:
                    # score: number of neighbors in W
                    score = len([nb for nb in adj_list[u] if nb in W])
                    # tie-break: min degree in G[U]
                    degU = len([nb for nb in adj_list[u] if nb in U])
                    if score > best_score or (score == best_score and (degU < best_degU or (degU == best_degU and u < best_u))):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for v in S:
                color[v] = c
            # remove S from uncolored
            uncolored -= S
            c += 1
        return color

    # Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        # compute degeneracy ordering: repeatedly remove min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # we will remove n vertices
        for _ in range(n):
            # find vertex with min degree among non-removed
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break  # should not happen
            order.append(v)
            removed[v] = True
            # decrease degree of neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    deg[nb] -= 1
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = 0
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy to work on
        color = coloring[:]
        # normalize to ensure consecutive colors
        color = normalize(color)
        k = max(color) + 1 if n > 0 else 0
        # iterate while we can reduce
        changed = True
        while changed and k > 1:
            changed = False
            # find smallest color class (by index, but we target the last color k-1 for simplicity)
            # we try to eliminate color k-1
            target = k - 1
            # vertices with target color
            targets = [v for v in range(n) if color[v] == target]
            if not targets:
                # already empty, should not happen if normalized
                k -= 1
                continue
            # try to recolor each target vertex
            for v in targets:
                # try direct reassignment to a lower color
                neighbor_colors = set()
                for nb in adj_list[v]:
                    if color[nb] < target:  # only consider colors < target
                        neighbor_colors.add(color[nb])
                for c in range(target):
                    if c not in neighbor_colors:
                        color[v] = c
                        changed = True
                        break
                if changed:
                    # after recoloring one vertex, break to restart
                    break
                # try Kempe chains with each lower color
                for c in range(target):
                    # if v already has color c from direct reassignment, skip (but we know it didn't work)
                    # build the Kempe chain for colors (c, target) containing v
                    # We'll do BFS over vertices with color c or target
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for nb in adj_list[u]:
                            if not visited[nb] and (color[nb] == c or color[nb] == target):
                                visited[nb] = True
                                queue.append(nb)
                    # check if any neighbor of the component has color c (external)
                    # if not, we can swap
                    has_external_c = False
                    for u in component:
                        for nb in adj_list[u]:
                            if color[nb] == c and nb not in component:
                                has_external_c = True
                                break
                        if has_external_c:
                            break
                    if not has_external_c:
                        # swap colors c and target in the component
                        for u in component:
                            if color[u] == c:
                                color[u] = target
                            else:  # must be target
                                color[u] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # renormalize and update k
                color = normalize(color)
                k = max(color) + 1 if n > 0 else 0
            else:
                # could not eliminate color k-1, break
                break
        return color

    # Run all heuristics
    candidates = []
    # DSATUR
    try:
        col1 = dsatur()
        if validate(col1):
            candidates.append(col1)
    except:
        pass
    # RLF
    try:
        col2 = rlf()
        if validate(col2):
            candidates.append(col2)
    except:
        pass
    # Smallest-Last
    try:
        col3 = smallest_last()
        if validate(col3):
            candidates.append(col3)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        color = [0] * n
        for i in range(n):
            used = 0
            for nb in adj_list[i]:
                if color[nb] != -1:  # but we are doing sequential, so check if colored
                    used |= (1 << color[nb])
            c = 0
            while used & (1 << c):
                c += 1
            color[i] = c
        candidates.append(color)

    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        col_norm = normalize(col)
        k = max(col_norm) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best = col_norm

    # Apply Kempe reduction to best candidate
    if best is not None:
        best = kempe_reduce(best)
        best = normalize(best)  # ensure consecutive

    return best if best is not None else [0] * n

