    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for v in adj[i]:
                if 0 <= v < n:
                    neighbors[i].append(v)
                    bit_adj[i] |= (1 << v)

