    def validate_and_compact(coloring):
        # Check validity
        for u in range(n):
            for v in neighbors[u]:
                if coloring[u] == coloring[v]:
                    return None
        # Compact colors
        used = set(coloring)
        if not used:
            return [0] * n
        mapping = {old: new for new, old in enumerate(sorted(used))]
        return [mapping[c] for c in coloring]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = coloring[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return validate_and_compact(coloring)

    best_coloring = None
    best_k = float('inf')

    # Heuristic 1: DSATUR
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        # Initial: pick vertex with max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(neighbors[x]))
            coloring[v] = 0
            saturated[v] = 1  # color 0 used
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] |= 1
            uncolored.remove(v)
        while uncolored:
            # Select vertex with max saturation degree (number of colors in saturated)
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat = saturated[v].bit_count()
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_v = candidates[0]
                for v in candidates:
                    deg = sum(1 for u in neighbors[v] if u in uncolored)
                    if deg > max_deg:
                        max_deg = deg
                        best_v = v
                    elif deg == max_deg and v < best_v:
                        best_v = v
                v = best_v
            else:
                v = candidates[0]
            # Assign smallest available color
            avail = ~saturated[v]
            c = 0
            while not (avail & (1 << c)):
                c += 1
            coloring[v] = c
            bit = 1 << c
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] |= bit
            uncolored.remove(v)
        return validate_and_compact(coloring)

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in independent_set)}
            # W: vertices adjacent to at least one in independent_set
            W = {u for u in uncolored if u not in independent_set and u not in U}
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in neighbors[u] if w in W)
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = sum(1 for x in neighbors[u] if x in U)
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        deg_in_U = sum(1 for x in neighbors[u] if x in U)
                        if deg_in_U < min_deg_in_U:
                            min_deg_in_U = deg_in_U
                            best_u = u
                if best_u is None:
                    break  # should not happen
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in neighbors[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent_set
            for v in independent_set:
                coloring[v] = color
            uncolored -= independent_set
            color += 1
        return validate_and_compact(coloring)

    # Heuristic 3: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current min non-empty bucket
        min_deg = 0
        while remaining:
            # Find next non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    if d < len(buckets):
                        buckets[d].append(u)
                    if degree[u] < min_deg:
                        min_deg = degree[u]
        # Color in reverse order
        return greedy_color(order[::-1])

    # Heuristic 4: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-len(neighbors[x]), x))
        return greedy_color(order)

    # Generate candidate colorings
    for heuristic in [dsatur, rlf, smallest_last, welsh_powell]:
        coloring = heuristic()
        if coloring is not None:
            k = max(coloring) + 1 if n > 0 else 0
            if k < best_k:
                best_k = k
                best_coloring = coloring

    # Fallback: if no heuristic produced a valid coloring (should not happen)
    if best_coloring is None:
        best_coloring = list(range(n))  # trivial coloring

    # Iterative color reduction via Kempe chains
    def kempe_reduction(coloring):
        if n == 0:
            return coloring
        # Try to reduce colors iteratively
        improved = True
        while improved:
            improved = False
            # Determine current number of colors
            k = max(coloring) + 1
            if k <= 1:
                break
            # Target the smallest color class (color k-1)
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already compacted?
                used = set(coloring)
                mapping = {old: new for new, old in enumerate(sorted(used))]
                return [mapping[c] for c in coloring]
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in neighbors[v]:
                    c = coloring[u]
                    if c != -1:
                        neighbor_colors.add(c)
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Recolor v to c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Skip if no vertex of color c exists (should not happen if k>1)
                    if all(coloring[u] != c for u in range(n)):
                        continue
                    # Find Kempe chain of colors (target_color, c) containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for w in neighbors[node]:
                                if w not in visited and (coloring[w] == target_color or coloring[w] == c):
                                    stack.append(w)
                    # Check if swapping this component is safe: 
                    # After swap, no two adjacent vertices have same color.
                    # Since we only swap two colors, it's valid if the component doesn't contain 
                    # a vertex u of color c that has a neighbor w of color c outside the component.
                    # Actually, swapping a Kempe chain always preserves validity.
                    # But we want to eliminate color target_color: after swap, 
                    # vertices in component that were target_color become c, and vice versa.
                    # We want that after swap, no vertex remains in target_color? 
                    # Actually, we want to move v out of target_color. 
                    # After swap, v (which was target_color) becomes c.
                    # We need to ensure that we don't accidentally create a new target_color elsewhere? 
                    # No, because we only swap within the component.
                    # The number of vertices of target_color may decrease if the component 
                    # contains fewer target_color vertices than c vertices? 
                    # Actually, we want to eliminate the color class entirely eventually.
                    # For now, we just try to recolor v to c via Kempe chain.
                    # Perform the swap: in component, swap target_color <-> c
                    for node in component:
                        if coloring[node] == target_color:
                            coloring[node] = c
                        elif coloring[node] == c:
                            coloring[node] = target_color
                    # Now v has color c (since it was target_color and in component)
                    improved = True
                    break
                if improved:
                    break
            # After attempting to recolor target vertices, compact colors
            if improved:
                used = set(coloring)
                mapping = {old: new for new, old in enumerate(sorted(used))]
                coloring = [mapping[c] for c in coloring]
        return coloring

    best_coloring = kempe_reduction(best_coloring)
    return best_coloring

