            while buckets[d] and removed[buckets[d][-1]]:
                buckets[d].pop()
            if not buckets[d]:
                d += 1
                while d < n and not buckets[d]:
                    d += 1
                if d >= n:
                    break
                v = buckets[d].pop()
        removed[v] = True
        order_sl.append(v)
        for u in adj_list[v]:
            if not removed[u]:
                old_deg = deg[u]
                deg[u] -= 1
                if old_deg < n:
