    coloring_sl = greedy_color(order_sl)
    k_sl = count_colors(coloring_sl)
    if k_sl < best_k:
        best_k = k_sl
        best_coloring = coloring_sl[:]

    # 3. DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        sat = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                # saturation degree: number of distinct colors in sat[u]
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and len([w for w in adj_list[u] if w in uncolored]) > max_deg):
                    max_sat = s
                    max_deg = len([w for w in adj_list[u] if w in uncolored])
                    v = u
                elif s == max_sat and len([w for w in adj_list[u] if w in uncolored]) == max_deg:
                    if v == -1 or u < v:
                        v = u
            # Assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] |= (1 << c)
        return color

    coloring_ds = dsatur()
    k_ds = count_colors(coloring_ds)
    if k_ds < best_k:
        best_k = k_ds
        best_coloring = coloring_ds[:]

    # 4. RLF (Recursive Largest First) - independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([w for w in adj_list[x] if w in uncolored]))
            S.append(v)
            # Partition uncolored \ {v} into U (not adj to S) and W (adj to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                if any(w in adj_list[u] for w in S):
                    W.add(u)
                else:
                    U.add(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max |N(u) ∩ W|
                u_star = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = len([w for w in adj_list[u] if w in W])
                    deg_in_U = len([w for w in adj_list[u] if w in U])
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        u_star = u
                    elif w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U:
                        if u_star == -1 or u < u_star:
                            u_star = u
                S.append(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in adj_list[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        return color

    coloring_rlf = rlf()
    k_rlf = count_colors(coloring_rlf)
    if k_rlf < best_k:
        best_k = k_rlf
        best_coloring = coloring_rlf[:]

    # Ensure best_coloring is set
    if best_coloring is None:
        best_coloring = [0] * n
        best_k = 1

    # Kempe chain color reduction
    def kempe_reduction(coloring):
        # Make coloring consecutive
        def renumber(col):
            mapping = {}
            next_c = 0
            for v in range(len(col)):
                if col[v] not in mapping:
                    mapping[col[v]] = next_c
                    next_c += 1
                col[v] = mapping[col[v]]
            return col

        coloring = renumber(coloring[:])
        k = max(coloring) + 1 if n > 0 else 0
        if k <= 1:
            return coloring

        improved = True
        while improved and k > 1:
            improved = False
            # Target smallest color class (color k-1)
            target_color = k - 1
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                # Should not happen, but safety
                coloring = renumber(coloring)
                k = max(coloring) + 1
                continue

            # Try to recolor each vertex in target class
            removed_all = True
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in adj_list[v]:
                    if coloring[u] < target_color:
                        neighbor_colors.add(coloring[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Direct move possible
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    # After moving one vertex, break to restart
                    break

                # Try Kempe chain swap with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {c, target_color}
                    if coloring[v] == target_color:
                        # BFS to get component
                        from collections import deque
                        comp = []
                        visited = [False] * n
                        q = deque([v])
                        visited[v] = True
                        while q:
                            node = q.popleft()
                            comp.append(node)
                            for nb in adj_list[node]:
                                if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                    visited[nb] = True
                                    q.append(nb)
                        # Check if swapping this component would not introduce conflict
                        # Actually, swapping is always safe for Kempe chain
                        # Perform swap: c <-> target_color in comp
                        for node in comp:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            else:
                                coloring[node] = c
                        # After swap, v now has color c
                        improved = True
                        break
                if improved:
                    break

            if not improved:
                # Could not recolor any vertex in target class
                break

            # Renumber and update k
            coloring = renumber(coloring)
            k = max(coloring) + 1 if n > 0 else 0

        return coloring

    # Apply Kempe reduction to the best candidate
    final_coloring = kempe_reduction(best_coloring)
    # Final validation (optional, but safe)
    for u in range(n):
        for v in adj_list[u]:
            if u < v and final_coloring[u] == final_coloring[v]:
                # Fallback to best_coloring if invalid (should not happen)
                return best_coloring
    return final_coloring

