import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format and convert to adjacency list
    if len(adj) > 0 and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Adjacency list
        adj_list = [list(neighbors) for neighbors in adj]

    # Convert adjacency list to bitmask for efficient operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring given an order
    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Helper: compute number of colors used
    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    # Helper: validate coloring
    def is_valid(colors):
        for u in range(n):
            for v in adj_list[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # Precompute degrees
        degrees = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))
        # Saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturation[v].bit_count()
                if sat > best_sat:
                    best_sat = sat
                    best_v = v
                    best_deg = sum(1 for u in adj_list[v] if u in uncolored)
                elif sat == best_sat:
                    deg = sum(1 for u in adj_list[v] if u in uncolored)
                    if deg > best_deg:
                        best_deg = deg
                        best_v = v
                    elif deg == best_deg:
                        if random.random() < 0.5:
                            best_v = v
            # Assign smallest available color
            used = saturation[best_v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[best_v] = c
            uncolored.remove(best_v)
            # Update saturation of uncolored neighbors
            for u in adj_list[best_v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
        return colors

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = {u for u in uncolored if u != v and not (adj_list[u] & (1 << v))}  # not adjacent to v
            W = {u for u in uncolored if u != v and (adj_list[u] & (1 << v))}      # adjacent to v
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    score = sum(1 for w in adj_list[u] if w in W)
                    if score > best_score:
                        best_score = score
                        best_u = u
                        # Compute degree in U for tie-break
                        deg_U = sum(1 for x in adj_list[u] if x in U)
                        best_deg_U = deg_U
                    elif score == best_score:
                        deg_U = sum(1 for x in adj_list[u] if x in U)
                        if deg_U < best_deg_U:
                            best_deg_U = deg_U
                            best_u = u
                        elif deg_U == best_deg_U and random.random() < 0.5:
                            best_u = u
                # Add best_u to independent set
                independent_set.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in independent_set
            for v in independent_set:
                colors[v] = color
                uncolored.remove(v)
            color += 1
        return colors

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        degrees = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current min degree
        ptr = 0
        # We'll simulate removal
        curr_deg = degrees[:]
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    # Remove u from its current bucket
                    d = curr_deg[u]
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    curr_deg[u] -= 1
                    buckets[curr_deg[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: simple greedy by degree
    try:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        c4 = greedy_color(order)
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass

    # If no candidate (should not happen), use trivial coloring
    if not candidates:
        return list(range(n))

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    best_colors = compact_colors(best)

    # Iterative Kempe chain color reduction
    def kempe_reduction(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if colors[v] == target_color]
            if not verts:
                continue
            changed = True
            while changed and verts:
                changed = False
                # Try to recolor each vertex in target_color
                for v in verts[:]:  # iterate over copy
                    if colors[v] != target_color:
                        continue  # already recolored
                    # Try direct reassignment to a lower color
                    free = [c for c in range(target_color) if all(colors[u] != c for u in adj_list[v])]
                    if free:
                        # Assign to the smallest free color
                        new_color = min(free)
                        colors[v] = new_color
                        changed = True
                        verts.remove(v)
                        continue
                    # Try Kempe chains with each lower color
                    for c in range(target_color):
                        # Check if v can be swapped via Kempe chain (v, target_color) with color c
                        # We'll BFS the Kempe chain component of v in colors {target_color, c}
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = []
                        while queue:
                            node = queue.popleft()
                            component.append(node)
                            for nb in adj_list[node]:
                                if not visited[nb] and (colors[nb] == target_color or colors[nb] == c):
                                    visited[nb] = True
                                    queue.append(nb)
                        # Check if any neighbor of the component has color c (would cause conflict if swapped)
                        has_conflict = False
                        for node in component:
                            for nb in adj_list[node]:
                                if colors[nb] == c and not visited[nb]:
                                    has_conflict = True
                                    break
                            if has_conflict:
                                break
                        if not has_conflict:
                            # Perform swap: target_color <-> c in component
                            for node in component:
                                if colors[node] == target_color:
                                    colors[node] = c
                                elif colors[node] == c:
                                    colors[node] = target_color
                            changed = True
                            if v in verts:
                                verts.remove(v)
                            break  # break color loop, restart vertex loop
                # If no changes in this pass, break
            # After trying to eliminate target_color, if no vertices left with that color, we can compact
            if not any(colors[v] == target_color for v in range(n)):
                # Compact colors above target_color down by one
                for v in range(n):
                    if colors[v] > target_color:
                        colors[v] -= 1
                # Break and restart from new highest color
                return kempe_reduction(colors)
        return colors

    # Apply Kempe reduction
    try:
        reduced = kempe_reduction(best_colors[:])
        if is_valid(reduced):
            best_colors = compact_colors(reduced)
    except:
        pass  # fallback to best_colors

    return best_colors

