        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
