    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to trivial greedy
    if not candidates:
        colors = [0] * n
        for i in range(1, n):
            used = 0
            for j in adj_list[i]:
                if j < i:  # only already colored neighbors
                    used |= (1 << colors[j])
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        candidates.append(colors)

