                for c in range(target_color):
                    if not (used_by_neighbors & (1 << c)):
                        # Direct move possible
                        cur_colors[v] = c
                        improved = True
                        break
                if improved:
                    # After moving one vertex, we break to restart the target color search
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # We'll try to swap colors c and target_color in the component containing v
                    # Only if v is not already color c (it isn't, since it's target_color)
                    # Build the Kempe chain: vertices reachable from v via alternating c and target_color
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb]:
                                nb_color = cur_colors[nb]
                                if nb_color == c or nb_color == target_color:
                                    visited[nb] = True
