                    # But in the component, neighbors with color c will become target_color, and vice versa.
                    # The swap is valid if and only if there is no edge between the component and a vertex of color c
                    # that is not in the component? Actually, Kempe chain swap always preserves validity.
                    # However, we want to know if after swap, color target_color is still used elsewhere?
                    # Our goal is to eliminate target_color if possible. We will check after swap if target_color is still used.
                    # But we can also check: if there is no vertex in the component that has a neighbor with color c
                    # outside the component? Actually, the swap is valid regardless.
                    # We perform the swap and then check if target_color is still used.
                    # Swap colors c and target_color in the component
                    for node in component:
                        if cur_colors[node] == c:
                            cur_colors[node] = target_color
                        else:  # must be target_color
                            cur_colors[node] = c
                    # Check if target_color is still used
                    if target_color not in cur_colors:
                        improved = True
                        break
                    else:
                        # Swap back to try other Kempe chains or direct moves
                        for node in component:
                            if cur_colors[node] == c:
                                cur_colors[node] = target_color
                            else:  # must be target_color
                                cur_colors[node] = c
                if improved:
                    break
            if improved:
                # Renormalize colors to fill gaps
                cur_colors = normalize_colors(cur_colors)
                k = num_colors(cur_colors)
            else:
                # Could not reduce further
                break
        return cur_colors

    # Apply Kempe reduction
    try:
        reduced = kempe_reduction(best_colors)
        if is_valid_coloring(reduced) and num_colors(reduced) < num_colors(best_colors):
            best_colors = reduced
    except:
        pass

    # Final normalization and validation
    final_colors = normalize_colors(best_colors)
    if not is_valid_coloring(final_colors):
        # Fallback: greedy in degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for v in order:
