def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        # Initial vertex: max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(adj_list[x]))
            color[v] = 0
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] += 1
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([y for y in adj_list[x] if y in uncolored])))
            # Find smallest available color
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    # Update saturation: if color c is new to u's neighbors
                    new_sat = 0
                    for w in adj_list[u]:
                        if color[w] != -1:
                            new_sat |= (1 << color[w])
                    sat[u] = new_sat.bit_count()
        return color

    # Helper: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S = {v}
            # U: vertices not adjacent to S
            U = {u for u in uncolored if u != v and not any(w in S for w in adj_list[u])}
            # W: vertices adjacent to S
            W = {u for u in uncolored if u not in S and any(w in S for w in adj_list[u])}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = max(U, key=lambda x: (len([y for y in adj_list[x] if y in W]), -len([y for y in adj_list[x] if y in U])))
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for nb in adj_list[u_star]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[i]) for i in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # Remove v
            remaining.remove(v)
            order.append(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in remaining:
                    d = degree[u]
                    degree[u] -= 1
                    if d < len(buckets):
                        buckets[d].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Run all heuristics
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # Validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col

    # If none valid (should not happen), fallback to greedy
    if best_color is None:
        best_color = greedy_color(list(range(n)))
        best_k = max(best_color) + 1 if n > 0 else 0

    # Kempe chain color reduction
    def kempe_reduction(color):
        # Map color to compact range if needed
        unique_colors = sorted(set(color))
        if len(unique_colors) == 0:
            return color
        mapping = {c: i for i, c in enumerate(unique_colors)}
        color = [mapping[c] for c in color]
        k = len(unique_colors)
        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 0:
            improved = False
            # Target smallest color class (by index, but we try to eliminate highest index first for compactness)
            # Actually, we try to reduce the number of colors by eliminating the last color
            target = k - 1
            # Get vertices with target color
            targets = [v for v in range(n) if color[v] == target]
            if not targets:
                # Already compacted
                k -= 1
                continue
            # Try to recolor each target vertex
            for v in targets:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if color[u] != target:  # only consider colors that are not target (but all are colored)
                        used |= (1 << color[u])
                for c in range(target):
                    if not (used & (1 << c)):
                        # Move v to color c
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains with each lower color
                for c in range(target):
                    # Find the Kempe chain component of v in colors {c, target}
                    # BFS to get component
                    from collections import deque
                    comp = []
                    visited = [False] * n
                    q = deque([v])
                    visited[v] = True
                    while q:
                        x = q.popleft()
                        comp.append(x)
                        for y in adj_list[x]:
                            if not visited[y] and (color[y] == c or color[y] == target):
                                visited[y] = True
                                q.append(y)
                    # Check if swapping this component would not introduce conflict
                    # Swap means: c->target, target->c in the component
                    # After swap, we want no two adjacent same color
                    # Since we only swap two colors, conflict can only happen if a neighbor outside comp has color c or target and adjacent to a vertex in comp
                    # But after swap, a vertex in comp originally color c becomes target, so if it has a neighbor outside comp with color target -> conflict
                    # Similarly, vertex originally target becomes c, neighbor outside with color c -> conflict
                    safe = True
                    for x in comp:
                        for y in adj_list[x]:
                            if not visited[y]:  # y not in component
                                if color[x] == c and color[y] == target:
                                    safe = False
                                    break
                                if color[x] == target and color[y] == c:
                                    safe = False
                                    break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for x in comp:
                            if color[x] == c:
                                color[x] = target
                            else:
                                color[x] = c
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # Cannot eliminate target color, break
                break
            # Compact colors: remove target color if no vertices have it
            if any(color[v] == target for v in range(n)):
                # Should not happen if we tried to eliminate
                pass
            else:
                # Remap colors > target down by one
                for v in range(n):
                    if color[v] > target:
                        color[v] -= 1
                k -= 1
        return color

    best_color = kempe_reduction(best_color)

    # Final validation and compacting
    unique_colors = sorted(set(best_color))
    mapping = {c: i for i, c in enumerate(unique_colors)}
    best_color = [mapping[c] for c in best_color]

    # Double-check validity
    for u in range(n):
        for v in adj_list[u]:
            if best_color[u] == best_color[v]:
                # Fallback to greedy if invalid (should not happen)
                return greedy_color(list(range(n)))

    return best_color

