                    conflict = False
                    for u in adj_list[v]:
                        if col[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        col[v] = c
                        moved = True
                        break
                if moved:
                    continue
                # Try Kempe chain swaps for each color c < target_color
                kempe_success = False
                for c in range(target_color):
                    # We want to see if we can swap colors in the (c, target_color) Kempe chain
                    # containing v, such that v ends up with color c and we don't introduce conflict.
                    # Actually, we want to free color c for v by swapping a component that does not contain
                    # any neighbor of v that has color c? 
                    # Standard approach: consider the Kempe chain of v for colors (c, target_color).
                    # If in that chain, there is no neighbor of v with color c, then we can swap the chain
                    # and v will get color c without conflict.
                    # Build the component containing v in the subgraph induced by colors c and target_color.
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in adj_list[x]:
                            if not visited[y] and (col[y] == c or col[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of v has color c and is in the component?
                    # Actually, we need to ensure that after swapping, v gets color c and no neighbor has color c.
                    # After swap, vertices in component that were color c become target_color, and vice versa.
                    # So v (currently target_color) will become c.
                    # A neighbor u of v will have color c after swap only if:
                    #   - u is in the component and currently has color target_color (so becomes c)
                    #   - or u is not in the component and currently has color c (remains c)
                    # We want no neighbor to have color c after swap.
                    # So we require:
                    #   (1) No neighbor u of v that is not in the component has color c.
                    #   (2) No neighbor u of v that is in the component has color target_color (because after swap it becomes c).
                    # Condition (1): for all u in adj_list[v], if u not in component then col[u] != c.
                    # Condition (2): for all u in adj_list[v], if u in component then col[u] != target_color.
                    # But note: v itself is in component and has target_color, but we are changing it.
                    ok = True
                    for u in adj_list[v]:
                        if u in component:
                            if col[u] == target_color:
                                ok = False
                                break
                        else:
                            if col[u] == c:
                                ok = False
                                break
                    if ok:
                        # Perform the swap: swap colors c and target_color in the component
                        for x in component:
                            if col[x] == c:
                                col[x] = target_color
                            elif col[x] == target_color:
                                col[x] = c
                        kempe_success = True
                        break
                if kempe_success:
                    continue
                # If we couldn't move v by direct or Kempe, then we fail to eliminate this color class
                success = False
                break
            if success:
                # All target vertices recolored, we can remove this color
                # Compact colors: we will reassign so that colors are 0..k-2
                # But note: we have already reassigned some vertices to lower colors, and the target color class is empty.
                # We need to compact the colors to remove gaps.
                # However, our current col may have colors up to k-1 but k-1 is unused.
                # We'll compact at the end of the reduction loop.
                k -= 1
                improved = True
            else:
                # Could not eliminate this color, break
                break
        # Compact the colors to ensure 0..k-1
        return compact_colors(col)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidate (should not happen), fallback to trivial greedy
    if not candidates:
        # Simple greedy in vertex order
        colors = [-1] * n
        for v in range(n):
            used = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(compact_colors(colors))

    # Select the candidate with the fewest colors
    best = min(candidates, key=num_colors)
    # Apply Kempe chain reduction to try to improve
    best = kempe_reduce(best)
    # Final validation (should be valid)
    if not is_valid(best):
        # Fallback to DSATUR if something went wrong
        best = dsatur()
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle trivial cases
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 and matrix is symmetric (undirected)
        all_binary = True
        symmetric = True
        for i in range(n):
            for j in range(n):
                val = adj[i][j]
                if val not in (0, 1):
                    all_binary = False
                    break
                if adj[i][j] != adj[j][i]:
                    symmetric = False
                    break
            if not all_binary or not symmetric:
                break
        if all_binary and symmetric:
            is_matrix = True

    # Build neighbor sets and bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)

    # Ensure undirected (symmetric) for safety
    for i in range(n):
        for j in neighbors[i]:
            if i not in neighbors[j]:
                neighbors[j].add(i)
                bit_adj[j] |= (1 << i)

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor color sets for saturation update
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))

        # initial degrees for tie-breaking
        degrees = [len(neighbors[i]) for i in range(n)]

        while uncolored:
            # select vertex with max saturation, then max degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u]
                deg_u = degrees[u]
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u

            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)

            # update saturation and neighbor colors for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1
        return color

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # independent set for current color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
                S.add(v)
                uncolored.remove(v)

            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored.copy()
            W = set()
            # remove neighbors of S from U
            for u in S:
                U -= neighbors[u]
            W = uncolored - U  # neighbors of S in uncolored

            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_common = -1
                min_deg_U = float('inf')
                for u in U:
                    common = len(neighbors[u] & W)
                    deg_U = len(neighbors[u] & U)
                    if common > max_common or (common == max_common and deg_U < min_deg_U) or \
                       (common == max_common and deg_U == min_deg_U and (best_u == -1 or random.random() < 0.5)):
                        max_common = common
                        min_deg_U = deg_U
                        best_u = u

                if best_u == -1:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for nb in neighbors[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            # assign color to S
            for v in S:
                color[v] = current_color
            current_color += 1

        return color

    # Smallest-Last (Matula-Beck) ordering + greedy
    def smallest_last():
        # core decomposition to get removal order
        deg = [len(neighbors[i]) for i in range(n)]
        # buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            d = deg[i]
            if d < len(buckets):
                buckets[d].append(i)
            else:
                # extend buckets if needed (should not happen with proper deg)
                while len(buckets) <= d:
                    buckets.append([])
                buckets[d].append(i)

        # pointer to current non-empty bucket
        ptr = 0
        order = []
        # copy of degrees for updating
        curr_deg = deg[:]
        # removed flag
        removed = [False] * n

        for _ in range(n):
            # find next non-empty bucket
            while ptr < len(buckets) and not buckets[ptr]:
                ptr += 1
            if ptr >= len(buckets):
                break  # should not happen
            # get vertex from bucket[ptr]
            while buckets[ptr] and removed[buckets[ptr][-1]]:
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    if d > 0:
                        curr_deg[u] -= 1
                        # move u to bucket[curr_deg[u]]
                        if curr_deg[u] < len(buckets):
                            buckets[curr_deg[u]].append(u)
                        else:
                            # extend buckets
                            while len(buckets) <= curr_deg[u]:
                                buckets.append([])
                            buckets[curr_deg[u]].append(u)

        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(color, a, b, v):
        if color[v] not in (a, b):
            return False  # not in the Kempe chain
        stack = [v]
        visited = set()
        component = []
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            if color[node] in (a, b):
                component.append(node)
                for nb in neighbors[node]:
                    if nb not in visited and color[nb] in (a, b):
                        stack.append(nb)
        # swap colors in component
        for node in component:
            if color[node] == a:
                color[node] = b
            else:
                color[node] = a
        return True

    # Try to eliminate the smallest color class using direct reassignment and Kempe chains
    def reduce_colors(color):
        # make color consecutive from 0
        unique_colors = sorted(set(color))
        if not unique_colors:
            return color
        mapping = {old: new for new, old in enumerate(unique_colors)}
        color = [mapping[c] for c in color]
        max_color = max(color) if n > 0 else -1

        # try to reduce from highest color downward
        changed = True
        while changed and max_color >= 0:
            changed = False
            # find smallest color class (by size)
            color_classes = [[] for _ in range(max_color + 1)]
            for i in range(n):
                if color[i] <= max_color:
                    color_classes[color[i]].append(i)

            # start from the smallest non-empty color class (to eliminate high colors)
            for c in range(max_color, -1, -1):
                if not color_classes[c]:
                    continue
                # try to recolor each vertex in class c
                eliminated = True
                for v in color_classes[c][:]:  # iterate over copy
                    # try direct reassignment to a lower color
                    used = set()
                    for u in neighbors[v]:
                        if color[u] < c:  # only consider colors lower than c
                            used.add(color[u])
                    found = False
                    for new_c in range(c):  # try colors 0 to c-1
                        if new_c not in used:
                            color[v] = new_c
                            found = True
                            break
                    if found:
                        # moved v, check if class c is now empty
                        if not any(color[u] == c for u in color_classes[c]):
                            eliminated = False  # class c not empty yet, but we made progress
                        break  # break to restart scan as color classes changed
                    else:
                        # try Kempe chains with each lower color
                        for new_c in range(c):
                            # only try if v is not already new_c (shouldn't be as v is color c)
                            if kempe_swap(color, c, new_c, v):
                                # after swap, v should be new_c
                                if color[v] == new_c:
                                    found = True
                                    break
                        if found:
                            if not any(color[u] == c for u in color_classes[c]):
                                eliminated = False
                            break
                if not eliminated:
                    changed = True
                    break  # restart the while loop as coloring changed
                # if we couldn't eliminate any vertex in class c, try next lower class
            # after processing, update max_color
            if max_color >= 0 and not any(color[i] == max_color for i in range(n)):
                max_color -= 1
                changed = True  # we reduced the max color, so continue

        # final compacting
        unique_colors = sorted(set(color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in color]

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        candidates.append(c3)
    except:
        pass

    # If no candidates, fallback to greedy
    if not candidates:
        color = [-1] * n
        for i in range(n):
            used = set()
            for j in neighbors[i]:
                if color[j] != -1:
                    used.add(color[j])
            c = 0
            while c in used:
                c += 1
            color[i] = c
        candidates.append(color)

    # Select best candidate (fewest colors)
    best_color = None
    best_num_colors = float('inf')
    for col in candidates:
        num_colors = len(set(col))
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_color = col

    # Apply Kempe chain reduction to best candidate
    if best_color is not None:
        best_color = reduce_colors(best_color)

    # Final validation (optional, but ensure correctness)
    # Verify no adjacent vertices share color
    for u in range(n):
        for v in neighbors[u]:
            if u < v and best_color[u] == best_color[v]:
                # Conflict: apply greedy fix as fallback
                color = [-1] * n
                order = list(range(n))
                random.shuffle(order)
                for v in order:
                    used = set()
                    for nb in neighbors[v]:
                        if color[nb] != -1:
                            used.add(color[nb])
                    c = 0
                    while c in used:
                        c += 1
                    color[v] = c
                return color

    return best_color if best_color is not None else [0]*n

