        pass

    # Strategy 3: Smallest-Last (Matula & Beck) ordering + greedy
    try:
        # Compute degeneracy ordering (smallest-last)
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # Use bucket queue for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            d = degrees[i]
            if d < len(buckets):
                buckets[d].append(i)
            else:
                # extend buckets if needed (should not happen with initial max_deg)
                buckets.extend([[] for _ in range(d - len(buckets) + 1)])
                buckets[d].append(i)
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr < len(buckets) and not buckets[ptr]:
