            # Try each color c < target_color
            for c in range(target_color):
                # Check if v can be recolored to c via Kempe chain (c, target_color)
                # Only if no neighbor of v has color c (otherwise direct conflict)
                if any(new_coloring[u] == c for u in neighbors[v]):
                    continue
                # Build Kempe chain component for colors c and target_color containing v
                stack = [v]
                visited = set()
                component = set()
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    if new_coloring[node] in (c, target_color):
                        component.add(node)
                        for u in neighbors[node]:
                            if new_coloring[u] in (c, target_color) and u not in visited:
                                stack.append(u)
                # Swap colors c and target_color in component
                swapped = new_coloring[:]
                for node in component:
                    if swapped[node] == c:
                        swapped[node] = target_color
                    elif swapped[node] == target_color:
                        swapped[node] = c
                # Check if v is now color c and target_color is reduced in the component
                if swapped[v] == c:
                    # Count target_color in component before and after
                    before = sum(1 for node in component if coloring[node] == target_color)
                    after = sum(1 for node in component if swapped[node] == target_color)
                    if after < before:  # we reduced the count of target_color
                        new_coloring = swapped
                        break  # break color loop, go to next vertex
            else:
                continue  # only executed if inner loop did NOT break
            break  # break vertex loop if we made a change
        # After processing, check if target_color is eliminated
        if target_color not in new_coloring:
            return new_coloring
        return coloring  # no elimination possible

    # Iteratively try to reduce colors
    current = best_coloring[:]
    changed = True
    while changed and num_colors(current) > 0:
        changed = False
        k = num_colors(current)
        # Target the smallest color class (highest color index) for elimination
        target = k - 1
        if target < 0:
            break
        new_current = eliminate_color_class(current, target)
        if new_current != current:
            current = new_current
            changed = True
            # Compact colors: remap to 0..k'-1
            # But eliminate_color_class may leave gaps; we compact at the end of iteration
            # Instead, we compact after successful elimination
            # Remap colors to consecutive
            mapping = {}
            next_color = 0
            for v in range(n):
                col = current[v]
                if col not in mapping:
                    mapping[col] = next_color
                    next_color += 1
                current[v] = mapping[col]

    # Final validation and compaction (ensure 0..k-1)
    if not is_valid(current):
        # Last resort: greedy by DSATUR order
        current = greedy_color(list(range(n)))
        # Ensure validity by conflict-free assignment (should be valid)
        for v in range(n):
            used = 0
            for u in neighbors[v]:
                if current[u] != -1:
                    used |= (1 << current[u])
            c = 0
            while used & (1 << c):
                c += 1
            current[v] = c
    # Compact colors
    mapping = {}
    next_color = 0
    for v in range(n):
        col = current[v]
        if col not in mapping:
            mapping[col] = next_color
            next_color += 1
        current[v] = mapping[col]

    return current

