def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    # Helper: compute degree from bitmask
    def degree_from_bit(u):
        return bit_adj[u].bit_count()
    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color
    # Helper: DSATUR
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by colored neighbors
        sat = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [degree_from_bit(i) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, then max uncolored degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                s = sat[u].bit_count()
                if s > max_sat or (s == max_sat and uncolored_deg[u] > max_deg):
                    max_sat = s
                    max_deg = uncolored_deg[u]
                    v = u
            if v == -1:
                v = next(iter(uncolored))
            # assign smallest available color
            used = sat[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in adj_list[v]:
                if color[u] == -1:
                    sat[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color
    # Helper: RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # degree in current uncolored subgraph
            deg = {}
            for u in uncolored:
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg[u] = cnt
            # pick vertex with max degree
            v = max(uncolored, key=lambda x: deg[x])
            S = {v}
            # U: vertices not adjacent to any in S
            U = {u for u in uncolored if u != v and v not in adj_list[u]}
            # W: vertices adjacent to S
            W = uncolored - S - U
            while U:
                # select u in U with max neighbors in W
                best_u = -1
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # tie-break: min degree in U
                    deg_u = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_u += 1
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_u < min_deg_U):
                        max_w_neighbors = w_neighbors
                        min_deg_U = deg_u
                        best_u = u
                if best_u == -1:
                    best_u = next(iter(U))
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color
    # Helper: smallest-last ordering
    def smallest_last():
        # core decomposition to get removal order
        degree = [degree_from_bit(i) for i in range(n)]
        # buckets for degrees
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            bins[degree[i]].append(i)
        # pointer to current min non-empty bin
        ptr = 0
        order = []
        # copy of degree for modification
        curr_deg = degree[:]
        removed = [False] * n
        for _ in range(n):
            # find next non-empty bin
            while ptr <= max_deg and not bins[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = bins[ptr].pop()
            while removed[v]:
                if not bins[ptr]:
                    break
                v = bins[ptr].pop()
            if removed[v]:
                # should not happen
                continue
            removed[v] = True
            order.append(v)
            for u in adj_list[v]:
                if not removed[u]:
                    d = curr_deg[u]
                    if d > 0:
                        curr_deg[u] -= 1
                        bins[d].remove(u)
                        bins[d-1].append(u)
        # color in reverse order
        return greedy_color(order[::-1])
    # Helper: Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(color, a, b, v):
        # returns new color list after swapping a and b in the component of v
        stack = [v]
        visited = set()
        comp_color = color[v]
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            # swap color
            if color[u] == a:
                color[u] = b
            elif color[u] == b:
                color[u] = a
            for w in adj_list[u]:
                if w not in visited and color[w] in (a, b):
                    stack.append(w)
        return color
    # Helper: try to eliminate a color class using Kempe chains
    def eliminate_color(color, target_color):
        # get vertices with target_color
        verts = [i for i in range(n) if color[i] == target_color]
        if not verts:
            return color, True  # already eliminated
        # try to recolor each vertex
        for v in verts:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            # find smallest available color not used by neighbors
            c = 0
            while used & (1 << c):
                c += 1
            if c < target_color:
                # recolor directly
                color[v] = c
                return color, False  # not eliminated yet, but changed
        # try Kempe chains for each vertex in target color
        for v in verts:
            for c in range(target_color):
                # check if v can be moved to color c via Kempe chain (c, target_color)
                # condition: v not adjacent to any vertex of color c
                conflict = False
                for u in adj_list[v]:
                    if color[u] == c:
                        conflict = True
                        break
                if not conflict:
                    # perform Kempe swap on component of v for colors c and target_color
                    # this will move v to color c if the component does not contain any vertex of color c adjacent to v? 
                    # Actually, if v is not adjacent to any c, then swapping the component will set v to c and remove it from target_color
                    new_color = color[:]
                    kempe_swap(new_color, c, target_color, v)
                    # verify that v is now color c (should be)
                    if new_color[v] == c:
                        return new_color, False
        # cannot eliminate
        return color, True
    # Generate candidate colorings
    candidates = []
    # DSATUR
    candidates.append(dsatur())
    # RLF
    candidates.append(rlf())
    # Smallest-last
    candidates.append(smallest_last())
    # Also try greedy with degree order (Welsh-Powell)
    order_deg = sorted(range(n), key=lambda x: degree_from_bit(x), reverse=True)
    candidates.append(greedy_color(order_deg))
    # Try random orders a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))
    # Select best candidate (fewest colors)
    best_color = None
    best_k = float('inf')
    for col in candidates:
        # validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_color = col
    if best_color is None:
        # fallback: DSATUR
        best_color = dsatur()
        best_k = max(best_color) + 1 if n > 0 else 0
    # Try to reduce colors via Kempe chain elimination
    changed = True
    while changed and best_k > 0:
        changed = False
        target = best_k - 1
        new_color, eliminated = eliminate_color(best_color[:], target)
        if eliminated:
            # compact colors: remap so that colors are 0..best_k-2
            mapping = {}
            next_c = 0
            for i in range(best_k):
                if i == target:
                    continue
                mapping[i] = next_c
                next_c += 1
            compacted = [mapping[c] for c in new_color]
            best_color = compacted
            best_k -= 1
            changed = True
        else:
            # try again with same target? no, break
            break
    # Ensure colors are consecutive
    if n > 0:
        # remap to 0..k-1
        unique_colors = {}
        next_c = 0
        for i in range(n):
            c = best_color[i]
            if c not in unique_colors:
                unique_colors[c] = next_c
                next_c += 1
            best_color[i] = unique_colors[c]
    return best_color

