            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if u not in S and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    nw = len([y for y in neighbors[u] if y in W])
                    deg_u = len([y for y in neighbors[u] if y in U])
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u) or \
                       (nw == max_nw and deg_u == min_deg_u and (best_u == -1 or random.random() < 0.5)):
                        max_nw = nw
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for v in S:
