        # Map color to list of vertices
        color_classes = {}
        for v, c in enumerate(color):
            color_classes.setdefault(c, []).append(v)
        # Get sorted unique colors
        unique_colors = sorted(color_classes.keys())
        # Try to eliminate highest color classes
        changed = True
        while changed and len(unique_colors) > 1:
            changed = False
            # Target the largest color index (hopefully smallest class)
            target_color = unique_colors[-1]
            target_vertices = color_classes[target_color][:]
            # Try to recolor each vertex in target class
            for v in target_vertices:
                if color[v] != target_color:  # might have been recolored
                    continue
                # Try direct reassignment to a lower color
                used = 0
                for u in neighbors[v]:
                    c = color[u]
                    if c != -1:
                        used |= (1 << c)
