                    if not (used & (1 << c)):
                        # Move v to color c
                        color[v] = c
                        color_classes[c].append(v)
                        color_classes[target_color].remove(v)
                        if not color_classes[target_color]:
                            del color_classes[target_color]
                            unique_colors.remove(target_color)
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # BFS to get component
                    from collections import deque
                    comp = []
                    visited = set()
                    q = deque([v])
                    visited.add(v)
                    while q:
                        x = q.popleft()
                        comp.append(x)
                        for y in neighbors[x]:
                            if y not in visited and (color[y] == target_color or color[y] == c):
                                visited.add(y)
                                q.append(y)
                    # Check if swapping colors in component frees color c for v
                    # After swap, v would get color c if it was target_color
                    # We need to ensure no neighbor of v gets color c after swap (except possibly v)
                    # Actually, we check if any neighbor of v has color c in the component
                    # If a neighbor of v is in the component and has color c, after swap it becomes target_color, so conflict avoided
                    # But we need to ensure that after swap, v's new color c is not used by any neighbor
                    # Since we are swapping only within component, neighbors outside component keep their color
                    # So we need: no neighbor of v has color c outside the component
                    has_conflict = False
                    for y in neighbors[v]:
                        if y not in visited and color[y] == c:
                            has_conflict = True
                            break
                    if not has_conflict:
                        # Perform swap
                        for x in comp:
                            if color[x] == target_color:
                                color[x] = c
                            elif color[x] == c:
                                color[x] = target_color
                        # Update color classes
                        color_classes[target_color] = [x for x in color_classes[target_color] if x not in comp]
                        color_classes[c] = [x for x in color_classes[c] if x not in comp]
                        for x in comp:
                            if color[x] == target_color:
                                color_classes[target_color].append(x)
                            else:
                                color_classes[c].append(x)
                        # Clean empty classes
                        if not color_classes[target_color]:
                            del color_classes[target_color]
                            unique_colors.remove(target_color)
                        if c not in color_classes:
                            color_classes[c] = []
                        changed = True
                        break
                if changed:
                    break
            # Re-sort unique colors
            unique_colors = sorted(color_classes.keys())
        # Compact colors to 0..k-1
        mapping = {}
        for i, c in enumerate(sorted(color_classes.keys())):
            mapping[c] = i
        new_color = [mapping[color[v]] for v in range(n)]
        return new_color
    # Apply Kempe reduction to best candidate
    try:
        improved = kempe_reduction(best_color[:])
        # Validate
        valid = True
        for u in range(n):
            for v in neighbors[u]:
                if u < v and improved[u] == improved[v]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            best_color = improved
    except:
        pass
    return best_color

