        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: check if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            cu = colors[u]
            for v in neighbors[u]:
                if cu == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: convert to consecutive colors starting from 0
    def normalize_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbor sets as bitmask for fast saturation update
        colored_neighbors_mask = [0] * n
        uncolored = set(range(n))

        # initial: all uncolored, saturation 0
        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u]
                if sat_u > max_sat:
                    max_sat = sat_u
                    max_deg = len([w for w in neighbors[u] if w in uncolored])
                    v = u
                elif sat_u == max_sat:
                    deg_u = len([w for w in neighbors[u] if w in uncolored])
                    if deg_u > max_deg:
                        max_deg = deg_u
                        v = u
                    elif deg_u == max_deg and u < v:
                        v = u
            # assign smallest available color
            used = colored_neighbors_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update saturation and colored neighbors mask for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    # if this color is new in u's neighborhood
                    if not (colored_neighbors_mask[u] & (1 << c)):
                        colored_neighbors_mask[u] |= (1 << c)
                        saturation[u] += 1
        return colors

    # RLF (Recursive Largest First) - maximal independent set extraction
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # build maximal independent set S for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                deg_u = len([w for w in neighbors[u] if w in uncolored])
                if deg_u > max_deg:
                    max_deg = deg_u
                    v = u
                elif deg_u == max_deg and u < v:
                    v = u
            if v == -1:  # should not happen if uncolored non-empty
                break
            S.add(v)
            # partition: U = vertices not adjacent to S, W = vertices adjacent to S
            U = set(uncolored) - {v}
            W = set()
            for u in list(U):
                if any(w in S for w in neighbors[u]):
                    W.add(u)
                    U.remove(u)
            # iteratively add to S from U
            while U:
                # select u in U with max |N(u) ∩ W|
                u_star = -1
                max_w_neighbors = -1
                min_deg_U = math.inf
                for u in U:
                    w_neighbors = len([w for w in neighbors[u] if w in W])
                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_deg_U = len([w for w in neighbors[u] if w in U])
                        u_star = u
                    elif w_neighbors == max_w_neighbors:
                        deg_u = len([w for w in neighbors[u] if w in U])
                        if deg_u < min_deg_U:
                            min_deg_U = deg_u
                            u_star = u
                        elif deg_u == min_deg_U and u < u_star:
                            u_star = u
                if u_star == -1:
                    break  # should not happen
                S.add(u_star)
                U.remove(u_star)
                # move neighbors of u_star from U to W
                for w in neighbors[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for u in S:
                colors[u] = color
            uncolored -= S
            color += 1
        return colors

    # Smallest-Last (Matula & Beck) greedy ordering
    def smallest_last():
        # compute degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        degree = [len(neighbors[i]) for i in range(n)]
        order = []  # will be removal order
        # we need updated degrees as we remove vertices
        deg_copy = degree[:]
        for _ in range(n):
            # find vertex with min degree in remaining
            v = -1
            min_deg = math.inf
            for u in remaining:
                if deg_copy[u] < min_deg:
                    min_deg = deg_copy[u]
                    v = u
                elif deg_copy[u] == min_deg and u < v:
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    deg_copy[u] -= 1
        # color in reverse order using first-fit
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Kempe chain based color reduction
    def kempe_reduce(colors):
        # make a copy to work on
        cur_colors = colors[:]
        k = num_colors(cur_colors)
        if k <= 1:
            return cur_colors
        # iterate trying to remove the highest color class
        while True:
            # find highest color present
            max_color = max(cur_colors) if cur_colors else -1
            if max_color < 0:
                break
            # vertices with color max_color
            verts_max = [i for i in range(n) if cur_colors[i] == max_color]
            if not verts_max:
                # no vertices with this color, should not happen if max_color is correct
                break
            # try to recolor each vertex in verts_max to a lower color
            removed = True
            while verts_max and removed:
                removed = False
                v = verts_max.pop()
                cv = cur_colors[v]
                # try direct reassignment to a lower color
                for c in range(cv):
                    # check if color c is available (no neighbor has color c)
                    conflict = False
                    for u in neighbors[v]:
                        if cur_colors[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        cur_colors[v] = c
                        removed = True
                        break
                if removed:
                    # after recoloring v, we may have reduced the max color
                    # rebuild verts_max for the current max color
                    max_color = max(cur_colors) if cur_colors else -1
                    verts_max = [i for i in range(n) if cur_colors[i] == max_color]
                    continue
                # try Kempe chain swaps with each lower color
                for c in range(cv):
                    # we consider swapping colors cv and c in the component containing v
                    # only if v is not already color c (it isn't)
                    # BFS/DFS to find the (cv, c)-Kempe chain starting from v
                    stack = [v]
                    visited = set()
                    component = set()
                    # we only traverse vertices with color cv or c
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        col_node = cur_colors[node]
                        if col_node == cv or col_node == c:
                            component.add(node)
                            for nb in neighbors[node]:
                                if nb not in visited:
                                    stack.append(nb)
                    # check if any neighbor of v in the component has color c? Actually, we want to see
                    # if swapping would cause conflict: after swap, v becomes c, so we need that no neighbor
                    # of v is colored c after swap. But note: in the component, neighbors of v that are in
                    # the component and have color c will become cv, so they won't be c anymore.
                    # However, neighbors outside the component: if they are color c, they remain c and would conflict.
                    # So we need that no neighbor of v outside the component is colored c.
                    safe = True
                    for nb in neighbors[v]:
                        if nb not in component and cur_colors[nb] == c:
                            safe = False
                            break
                    if safe:
                        # perform swap: cv <-> c in the component
                        for node in component:
                            if cur_colors[node] == cv:
                                cur_colors[node] = c
                            else:  # must be c
                                cur_colors[node] = cv
                        removed = True
                        break
                if removed:
                    max_color = max(cur_colors) if cur_colors else -1
                    verts_max = [i for i in range(n) if cur_colors[i] == max_color]
                    continue
            # if we couldn't remove any vertex from the max color class, break
            if not removed:
                break
        # normalize colors to be consecutive
        return normalize_colors(cur_colors)

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except Exception:
        pass

    # If no candidates (should not happen), fallback to greedy
    if not candidates:
        # simple greedy ordering by index
        colors = [-1] * n
        for v in range(n):
            used = 0
            for u in neighbors[v]:
                if colors[u] != -1:
                    used |= (1 << colors[u])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(colors)

    # Select the candidate with fewest colors
    best = min(candidates, key=num_colors)
    best_colors = best[:]

    # Apply Kempe reduction iteratively until no improvement
    prev_k = num_colors(best_colors)
    for _ in range(10):  # limit iterations to avoid infinite loop
        reduced = kempe_reduce(best_colors)
        new_k = num_colors(reduced)
        if new_k < prev_k:
            best_colors = reduced
            prev_k = new_k
        else:
            break

    # Final normalization and validation
    best_colors = normalize_colors(best_colors)
    if not is_valid_coloring(best_colors):
        # fallback to DSATUR if something went wrong
        best_colors = dsatur()
        best_colors = normalize_colors(best_colors)
    return best_colors

import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree array
    if is_matrix:
        adj_list = []
        for u in range(n):
            neighbors = []
            for v in range(n):
                if adj[u][v] == 1:
                    neighbors.append(v)
            adj_list.append(neighbors)
    else:
        adj_list = adj  # already adjacency list

    # Degeneracy ordering via smallest-last (Matula & Beck, 1983)
    # Repeatedly remove vertex of minimum degree, push to stack, update degrees
    degree = [len(adj_list[i]) for i in range(n)]
    removed = [False] * n
    order = []  # removal order (will color in reverse)
    # We'll use a list of lists for buckets by degree; max degree is n-1
    max_deg = n - 1
    buckets = [[] for _ in range(max_deg + 1)]
    for v in range(n):
        d = degree[v]
        if d <= max_deg:
            buckets[d].append(v)
    # Pointer to current non-empty bucket
    ptr = 0

    for _ in range(n):
        # Find next non-empty bucket
        while ptr <= max_deg and not buckets[ptr]:
            ptr += 1
        if ptr > max_deg:
            break  # should not happen
        # Get a vertex from the bucket
        v = buckets[ptr].pop()
        if removed[v]:
            continue  # skip if already removed (can happen due to lazy updates)
        removed[v] = True
        order.append(v)
        # Decrease degree of neighbors
        for u in adj_list[v]:
            if not removed[u]:
                d_u = degree[u]
                # Remove u from its current bucket
                if d_u <= max_deg:
                    # Since we don't have direct removal, we'll mark and skip later
                    # Instead, we decrease degree and add to lower bucket
                    pass
                degree[u] -= 1
                d_new = degree[u]
                if d_new <= max_deg:
                    buckets[d_new].append(u)
        # Note: We don't remove u from old bucket; we rely on degree array and skipped if removed.
        # This is lazy: we may have stale entries in buckets, but we check removed and current degree when popping.
        # To avoid infinite loop, we ensure we only process each vertex once by removed flag.

    # Now color in reverse order (last removed first) using First-Fit
    color = [-1] * n
    # For each vertex in reverse removal order
    for v in reversed(order):
        # Find colors used by colored neighbors
        used = [False] * n  # at most n colors needed
        for u in adj_list[v]:
            c = color[u]
            if c != -1:
                used[c] = True
        # Find smallest non-negative integer not used
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c

    return color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect and convert to adjacency list
    if isinstance(adj[0], list) and len(adj[0]) == n and all(x in (0, 1) for x in adj[0]):
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = adj

    # Precompute neighbor bitmasks for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in graph[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert coloring to consecutive colors starting from 0
    def compact_colors(coloring):
        if not coloring:
            return coloring
        unique_colors = sorted(set(coloring))
        mapping = {c: i for i, c in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # saturation degree: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor colorsets as bitmasks for fast saturation update
        neighbor_colors = [0] * n

        # order by degree descending for initial tie-breaking in degree
        degrees = [len(graph[i]) for i in range(n)]
        vertices = list(range(n))
        vertices.sort(key=lambda x: (-degrees[x], x))

        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in vertices:
                if colored[u]:
                    continue
                sat = saturation[u]
                deg = degrees[u]
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and u < v):
                    max_sat = sat
                    max_deg = deg
                    v = u
            if v == -1:
                break  # should not happen

            # find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True

            # update saturation and neighbor colors for neighbors
            for nb in graph[v]:
                if not colored[nb]:
                    # update neighbor's color set
                    neighbor_colors[nb] |= (1 << c)
                    # update saturation: count bits in neighbor_colors[nb]
                    saturation[nb] = neighbor_colors[nb].bit_count()

        return compact_colors(colors)

    # RLF: Recursive Largest First
    def rlf():
        colors = [-1] * n
        colored = [False] * n
        color = 0

        # Precompute degree in the full graph for initial ordering
        degrees = [len(graph[i]) for i in range(n)]

        while any(not c for c in colored):
            # Step 1: pick uncolored vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                # count uncolored neighbors
                deg = 0
                for nb in graph[u]:
                    if not colored[nb]:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
            if v == -1:
                break

            # Start independent set for this color
            independent_set = [v]
            colored[v] = True
            colors[v] = color

            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = set()
            W = set()
            for u in range(n):
                if colored[u]:
                    continue
                adjacent = False
                for nb in graph[u]:
                    if colored[nb] and colors[nb] == color:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)

            # Step 4: while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_nb_count = 0
                    for nb in graph[u]:
                        if nb in W:
                            w_nb_count += 1
                    # tie-break: min degree in G[U]
                    deg_in_U = 0
                    for nb in graph[u]:
                        if nb in U:
                            deg_in_U += 1
                    if (w_nb_count > max_w_neighbors or
                        (w_nb_count == max_w_neighbors and deg_in_U < min_deg_in_U) or
                        (w_nb_count == max_w_neighbors and deg_in_U == min_deg_in_U and u < best_u)):
                        max_w_neighbors = w_nb_count
                        min_deg_in_U = deg_in_U
                        best_u = u

                # add best_u to independent set
                independent_set.append(best_u)
                colored[best_u] = True
                colors[best_u] = color
                U.remove(best_u)

                # move neighbors of best_u from U to W
                for nb in graph[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            color += 1

        return compact_colors(colors)

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        # Copy of degrees for peeling
        degrees = [len(graph[i]) for i in range(n)]
        # adj list for current graph (we will simulate removal)
        # We use a list of sets for efficient removal
        adj_sets = [set(graph[i]) for i in range(n)]
        removed = [False] * n
        order = []  # will store vertices in removal order

        # Peeling: remove min degree vertex n times
        for _ in range(n):
            # find vertex with min degree among non-removed
            v = -1
            min_deg = float('inf')
            for i in range(n):
                if not removed[i] and degrees[i] < min_deg:
                    min_deg = degrees[i]
                    v = i
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            # decrease degree of neighbors
            for nb in graph[v]:
                if not removed[nb]:
                    degrees[nb] -= 1

        # Color in reverse order (last removed first)
        colors = [-1] * n
        for v in reversed(order):
            # find smallest color not used by colored neighbors
            used = 0
            for nb in graph[v]:
                if colors[nb] != -1:
                    used |= (1 << colors[nb])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Try to reduce colors iteratively
        improved = True
        while improved:
            improved = False
            # Get color classes
            max_color = max(coloring) if coloring else -1
            if max_color < 0:
                break
            color_classes = [[] for _ in range(max_color + 1)]
            for v, c in enumerate(coloring):
                color_classes[c].append(v)

            # Try to eliminate the last color class (highest color)
            target_color = max_color
            if not color_classes[target_color]:
                # already empty, trim
                coloring = [c if c < target_color else c - 1 for c in coloring]
                improved = True
                continue

            # For each vertex in target color, try to recolor to a lower color
            # We'll try direct move or Kempe swap
            target_vertices = color_classes[target_color][:]
            random.shuffle(target_vertices)  # randomize to avoid bad orders
            made_change = False
            for v in target_vertices:
                # Try direct move to a lower color
                neighbor_colors = 0
                for nb in graph[v]:
                    if coloring[nb] != -1:
                        neighbor_colors |= (1 << coloring[nb])
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        # direct move possible
                        coloring[v] = c
                        made_change = True
                        break
                if made_change:
                    break

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # We'll try to swap colors c and target_color in the component containing v
                    # Only if v is not adjacent to any vertex of color c (otherwise swap invalid immediately)
                    has_c_neighbor = False
                    for nb in graph[v]:
                        if coloring[nb] == c:
                            has_c_neighbor = True
                            break
                    if has_c_neighbor:
                        continue  # swap would cause conflict immediately

                    # Build the Kempe chain component for colors {c, target_color} containing v
                    # We'll do BFS/DFS
                    stack = [v]
                    visited = set()
                    component = []
                    # We only traverse vertices with color c or target_color
                    target_set = {c, target_color}
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        component.append(node)
                        for nb in graph[node]:
                            if coloring[nb] in target_set and nb not in visited:
                                stack.append(nb)

                    # Check if swapping is safe: no neighbor of any node in component
                    # has color c or target_color outside the component (would cause conflict after swap)
                    safe = True
                    for node in component:
                        for nb in graph[node]:
                            if coloring[nb] == c or coloring[nb] == target_color:
                                if nb not in component:
                                    safe = False
                                    break
                        if not safe:
                            break

                    if safe:
                        # Perform swap: c <-> target_color in component
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = target_color
                            else:  # must be target_color
                                coloring[node] = c
                        made_change = True
                        break
                if made_change:
                    break

            if made_change:
                improved = True
                # compact colors after change
                coloring = compact_colors(coloring)
            else:
                # Could not eliminate target color, break
                break

