    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        coloring = [-1] * n
        vertices = list(range(n))
        vertices.sort(key=lambda x: len(graph[x]), reverse=True)
        for v in vertices:
            used = 0
            for nb in graph[v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        candidates.append(compact_colors(coloring))

    # Select candidate with fewest colors
    best = min(candidates, key=lambda x: max(x) + 1 if x else 0)
    # Apply Kempe reduction to try to improve
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid(best):
        # last resort: greedy
        coloring = [-1] * n
        vertices = list(range(n))
        vertices.sort(key=lambda x: len(graph[x]), reverse=True)
        for v in vertices:
            used = 0
            for nb in graph[v]:
                if coloring[nb] != -1:
                    used |= (1 << coloring[nb])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best = compact_colors(coloring)
    else:
        best = compact_colors(best)

    return best

