def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build neighbor sets and degree list
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            neighbors[i] = set(adj[i])

    degrees = [len(neighbors[i]) for i in range(n)]

    # DSATUR algorithm with sum of degrees of uncolored neighbors as tie-breaker
    colors = [-1] * n
    # Precompute neighbor bits for fast saturation calculation
    neighbor_bits = [0] * n
    for i in range(n):
        for nb in neighbors[i]:
            neighbor_bits[i] |= (1 << nb)

    colored_mask = 0  # Bitmask of colored vertices
    color_bits = [0] * n  # Bitmask of vertices per color (up to n colors)

    for _ in range(n):
        # Select uncolored vertex with max saturation degree
        best_v = -1
        max_sat = -1
        max_tie_break = -1  # Sum of degrees of uncolored neighbors

        for v in range(n):
            if colors[v] != -1:
                continue

            # Calculate saturation: number of distinct colors in neighbors
            sat = 0
            for nb in neighbors[v]:
                if colors[nb] != -1:
                    sat |= (1 << colors[nb])
            sat_count = sat.bit_count()

            # Tie-breaker: sum of degrees of uncolored neighbors
            tie_break = 0
            for nb in neighbors[v]:
                if colors[nb] == -1:
                    tie_break += degrees[nb]

            if sat_count > max_sat or (sat_count == max_sat and tie_break > max_tie_break):
                max_sat = sat_count
                max_tie_break = tie_break
                best_v = v

        if best_v == -1:  # Should not happen
            break

        # Find smallest available color for best_v
        used_colors = 0
        for nb in neighbors[best_v]:
            if colors[nb] != -1:
                used_colors |= (1 << colors[nb])
        c = 0
        while used_colors & (1 << c):
            c += 1
        colors[best_v] = c

        # Update masks
        colored_mask |= (1 << best_v)
        color_bits[c] |= (1 << best_v)

    # Compact colors to 0..k-1
    unique_colors = set(colors)
    if len(unique_colors) == n:  # Already compact or worst case
        return colors
    mapping = {old: new for new, old in enumerate(sorted(unique_colors))]
    return [mapping[c] for c in colors]

import math
