import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list if needed
    if isinstance(adj[0], list) and len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for x in adj[0]):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Adjacency list
        adj_list = adj

    # Build bitmask adjacency for fast operations
    bit_adj = [0] * n
    for u in range(n):
        mask = 0
        for v in adj_list[u]:
            mask |= (1 << v)
        bit_adj[u] = mask

    # Helper: greedy coloring given an order
    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    used |= (1 << colors[v])
            c = 0
            while used & (1 << c):
                c += 1
            colors[u] = c
        return colors

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        saturated = [0] * n  # saturation degree
        uncolored = set(range(n))
        # Initial: pick vertex with max degree
        if uncolored:
            v = max(uncolored, key=lambda x: len(adj_list[x]))
            colors[v] = 0
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    saturated[u] += 1
        while uncolored:
            # Find vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (saturated[x], len([y for y in adj_list[x] if y in uncolored])))
            # Assign smallest available color
            used = 0
            for y in adj_list[v]:
                if colors[y] != -1:
                    used |= (1 << colors[y])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for y in adj_list[v]:
                if y in uncolored:
                    saturated[y] += 1
        return colors

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set S for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in adj_list[x] if y in uncolored]))
            S.add(v)
            uncolored.remove(v)
            # Partition remaining: U (eligible), W (ineligible)
            U = {u for u in uncolored if v not in adj_list[u]}  # not adjacent to v
            W = uncolored - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U-induced subgraph
                u_star = max(U, key=lambda x: (len([y for y in adj_list[x] if y in W]), -len([y for y in adj_list[x] if y in U])))
                S.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                nbrs_in_U = {y for y in adj_list[u_star] if y in U}
                U -= nbrs_in_U
                W |= nbrs_in_U
            # Assign color to S
            for u in S:
                colors[u] = color
            color += 1
        return colors

    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        degrees = [len(adj_list[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Buckets for vertices by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current min non-empty bucket
        ptr = 0
        while remaining:
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # Get vertex from bucket
            while buckets[ptr] and buckets[ptr][-1] not in remaining:
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    old_deg = degrees[u]
                    degrees[u] -= 1
                    if old_deg < len(buckets):
                        buckets[old_deg].remove(u)  # O(n) but n <= 100
                    if degrees[u] < len(buckets):
                        buckets[degrees[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Helper: Kempe chain swap for color elimination
    def kempe_reduce(colors):
        # Map color to vertices
        color_classes = {}
        for v, c in enumerate(colors):
            color_classes.setdefault(c, []).append(v)
        if not color_classes:
            return colors
        max_color = max(color_classes.keys())
        # Try to eliminate color classes from highest down
        for target_color in range(max_color, 0, -1):
            if target_color not in color_classes:
                continue
            verts = color_classes[target_color]
            changed = True
            while changed and verts:
                changed = False
                # Try direct reassignment
                for v in verts[:]:
                    used = 0
                    for u in adj_list[v]:
                        if colors[u] != -1:
                            used |= (1 << colors[u])
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            # Move v to color c
                            colors[v] = c
                            color_classes[c].append(v)
                            verts.remove(v)
                            color_classes[target_color].remove(v)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    continue
                # Try Kempe chains
                for v in verts[:]:
                    for c in range(target_color):
                        # Check if v can be swapped via Kempe chain (target_color, c)
                        # Avoid if v already has color c (shouldn't happen)
                        if colors[v] == c:
                            continue
                        # Build Kempe chain component containing v in colors {target_color, c}
                        stack = [v]
                        visited = set()
                        comp_color = colors[v]
                        other_color = c
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            for nb in adj_list[node]:
                                if colors[nb] in (comp_color, other_color) and nb not in visited:
                                    stack.append(nb)
                        # Check if any neighbor of v in the component has color c (would cause conflict if swapped)
                        conflict = False
                        for node in visited:
                            for nb in adj_list[node]:
                                if colors[nb] == c and nb not in visited:
                                    conflict = True
                                    break
                            if conflict:
                                break
                        if not conflict:
                            # Perform swap
                            for node in visited:
                                if colors[node] == target_color:
                                    colors[node] = c
                                elif colors[node] == c:
                                    colors[node] = target_color
                            # Update color classes
                            for node in visited:
                                old_c = colors[node] ^ (target_color ^ c)  # swap
                                # Actually, we swapped: target_color <-> c
                                if colors[node] == target_color:
                                    color_classes[target_color].append(node)
                                    if node in color_classes[c]:
                                        color_classes[c].remove(node)
                                else:  # colors[node] == c
                                    color_classes[c].append(node)
                                    if node in color_classes[target_color]:
                                        color_classes[target_color].remove(node)
                            # Rebuild verts list for this target_color
                            verts = color_classes.get(target_color, [])
                            changed = True
                            break
                    if changed:
                        break
            # If target color class is empty, we can reduce
            if target_color not in color_classes or not color_classes[target_color]:
                # Compact colors: remap higher colors down
                mapping = {}
                next_c = 0
                for c in sorted(color_classes.keys()):
                    if c == target_color:
                        continue
                    mapping[c] = next_c
                    next_c += 1
                new_colors = [0] * n
                for v in range(n):
                    c = colors[v]
                    if c in mapping:
                        new_colors[v] = mapping[c]
                    else:
                        new_colors[v] = c  # should be < target_color
                return kempe_reduce(new_colors)  # recurse
        return colors

    # Generate candidates
    start = time.time()
    candidates = []

    # DSATUR
    c1 = dsatur()
    if time.time() - start < 0.05:
        candidates.append(c1)

    # RLF
    c2 = rlf()
    if time.time() - start < 0.05:
        candidates.append(c2)

    # Smallest-Last
    c3 = smallest_last()
    if time.time() - start < 0.05:
        candidates.append(c3)

    # Select best (fewest colors)
    best = None
    best_colors = float('inf')
    for col in candidates:
        # Validate
        valid = True
        for u in range(n):
            for v in adj_list[u]:
                if u < v and col[u] == col[v]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        unique = len(set(col))
        if unique < best_colors:
            best_colors = unique
            best = col

    # Fallback: if no candidate valid, use greedy on natural order
    if best is None:
        best = greedy_color(list(range(n)))

    # Apply Kempe reduction to try to improve
    if time.time() - start < 0.04:  # leave time for Kempe
        best = kempe_reduce(best)

    # Final validation and compact colors
    # Ensure colors are 0..k-1
    mapping = {}
    next_c = 0
    for c in sorted(set(best)):
        mapping[c] = next_c
        next_c += 1
    best = [mapping[c] for c in best]

    return best

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type and build bitmask adjacency
    is_matrix = (len(adj) > 0 and len(adj[0]) == len(adj) and 
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    if is_matrix:
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    bit_adj[i] |= (1 << j)
    else:
        bit_adj = [0] * n
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    bit_adj[i] |= (1 << j)

    # Helper: get neighbors as list
    def neighbors(v):
        mask = bit_adj[v]
        res = []
        while mask:
            w = (mask & -mask).bit_length() - 1
            res.append(w)
            mask &= mask - 1
        return res

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors(u):
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Heuristic 1: BFS-based bipartite extraction + conflict resolution
    def bfs_bipartite_heuristic():
        color = [-1] * n
        from collections import deque
        q = deque()
        # Start BFS from vertex 0
        color[0] = 0
        q.append(0)
        while q:
            u = q.popleft()
            for v in neighbors(u):
                if color[v] == -1:
                    color[v] = color[u] ^ 1
                    q.append(v)
                elif color[v] == color[u]:
                    # Conflict: odd cycle detected, we will resolve later
                    pass
        # Now resolve conflicts by trying to assign third color where needed
        # We'll use a simple greedy approach on the conflict graph
        # But first, try to see if 2 colors work by checking if any edge same color
        conflict_edges = []
        for u in range(n):
            for v in neighbors(u):
                if u < v and color[u] == color[v]:
                    conflict_edges.append((u, v))
        if not conflict_edges:
            # Already bipartite
            return color
        # Try to assign a third color to some vertices to break conflicts
        # We'll use a greedy approach: for each conflict, try to recolor one vertex
        # with color 2 if possible
        temp_color = color[:]
        changed = True
        while changed:
            changed = False
            for u, v in conflict_edges:
                if temp_color[u] == temp_color[v]:
                    # Try to recolor u to 2 if not conflicting with its neighbors
                    can_use_2 = True
                    for w in neighbors(u):
                        if temp_color[w] == 2:
                            can_use_2 = False
                            break
                    if can_use_2:
                        temp_color[u] = 2
                        changed = True
                    else:
                        # Try to recolor v to 2
                        can_use_2 = True
                        for w in neighbors(v):
                            if temp_color[w] == 2:
                                can_use_2 = False
                                break
                        if can_use_2:
                            temp_color[v] = 2
                            changed = True
        # After this, check if valid
        if is_valid(temp_color):
            return temp_color
        # Fallback: use DSATUR
        return dsatur()

    # Heuristic 2: DSATUR
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # colored neighbors mask for each vertex
        colored_neighbors = [0] * n

        # Select first vertex: max degree
        degrees = [bin(bit_adj[i]).count('1') for i in range(n)]
        v = max(range(n), key=lambda i: degrees[i])
        coloring[v] = 0
        # Update neighbors
        for u in neighbors(v):
            saturation[u] = 1  # now has color 0 in neighbors
            colored_neighbors[u] |= (1 << v)

        for _ in range(n-1):
            # Select uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for i in range(n):
                if coloring[i] == -1:
                    sat = saturation[i]
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [i]
                    elif sat == max_sat:
                        candidates.append(i)
            # Tie-break: degree in uncolored subgraph (number of uncolored neighbors)
            if len(candidates) > 1:
                # Compute degree in uncolored subgraph
                def uncolored_degree(v):
                    count = 0
                    for u in neighbors(v):
                        if coloring[u] == -1:
                            count += 1
                    return count
                candidates.sort(key=lambda x: (-uncolored_degree(x), x))
            v = candidates[0]
            # Find smallest color not used by neighbors
            neighbor_colors = 0
            for u in neighbors(v):
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
            # Update saturation and colored_neighbors for neighbors of v
            for u in neighbors(v):
                if coloring[u] == -1:
                    # Add color c to u's neighbor colors if not already present
                    if not (colored_neighbors[u] & (1 << c)):
                        colored_neighbors[u] |= (1 << c)
                        saturation[u] += 1
        return coloring

    # Heuristic 3: RLF (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        coloring = [-1] * n
        color_count = 0
        uncolored = set(range(n))

        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            def degree_in_uncolored(v):
                return sum(1 for u in neighbors(v) if u in uncolored)

            v = max(uncolored, key=degree_in_uncolored)
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            W = set(neighbors(v)) & uncolored
            U = uncolored - {v} - W

            while U:
                # Select u in U with max |N(u) ∩ W|
                def w_neighbors_count(u):
                    return sum(1 for w in neighbors(u) if w in W)
                # Tie-break: min degree in G[U]
                def degree_in_U(u):
                    return sum(1 for x in neighbors(u) if x in U)
                u = max(U, key=lambda x: (w_neighbors_count(x), -degree_in_U(x)))
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u that are in U to W
                nbrs_u = set(neighbors(u)) & U
                W.update(nbrs_u)
                U -= nbrs_u

            # Assign color to all in independent_set
            for v in independent_set:
                coloring[v] = color_count
                uncolored.remove(v)
            color_count += 1

        return coloring

    # Heuristic 4: Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [bin(bit_adj[i]).count('1') for i in range(n)]
        order = []
        # We'll use bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)

        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find first non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors(v):
                if u in remaining:
                    d = degree[u]
                    buckets[d].remove(u)
                    degree[u] -= 1
                    buckets[degree[u]].append(u)

        # Color in reverse order using first-fit
        coloring = [-1] * n
        for v in reversed(order):
            neighbor_colors = 0
            for u in neighbors(v):
                if coloring[u] != -1:
                    neighbor_colors |= (1 << coloring[u])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        if not is_valid(coloring):
            return coloring  # should not happen if input is valid
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            vertices = [v for v in range(n) if coloring[v] == target_color]
            if not vertices:
                continue

            # Try to recolor each vertex in this class
            made_progress = False
            for v in vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for u in neighbors(v):
                    if coloring[u] != -1:
                        neighbor_colors |= (1 << coloring[u])
                for c in range(target_color):
                    if not (neighbor_colors & (1 << c)):
                        # Can recolor v to c
                        coloring[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break  # restart scanning from highest color

                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v is connected to color c via Kempe chain
                    # We'll do BFS on the subgraph of colors {c, target_color}
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        u = queue.popleft()
                        component.append(u)
                        for w in neighbors(u):
                            if not visited[w] and (coloring[w] == c or coloring[w] == target_color):
                                visited[w] = True
                                queue.append(w)
                    # Check if this component has no vertex of color c that is adjacent to a vertex outside the component with color target_color?
                    # Actually, we can swap if the component does not contain all vertices of color c that are adjacent to the component?
                    # Standard: swapping is safe if the component does not contain a vertex of color c that is adjacent to a vertex of color target_color outside the component?
                    # Actually, for Kempe chain swap to be valid, we just need that after swap, no adjacent same color.
                    # Swapping colors c and target_color in the component is always safe because:
                    # - Inside component: edges between c and target_color become target_color and c -> still different
                    # - Edges from component to outside: 
                    #   * If outside vertex has color c: after swap, inside becomes target_color, so edge is target_color vs c -> ok if not same
                    #   * If outside vertex has color target_color: after swap, inside becomes c, so edge is c vs target_color -> ok
                    #   * If outside vertex has other color: no conflict
                    #   * The only issue is if there is an edge between two vertices in the component that were same color? But they can't be same because we only traverse c and target_color.
                    # So the swap is always valid. However, we want to eliminate color target_color, so we want that after swap, no vertex in the component remains target_color.
                    # After swap, vertices originally c become target_color, and vertices originally target_color become c.
                    # So to eliminate target_color, we need that there are no vertices originally c in the component? No, we want that after swap, the component has no target_color.
                    # After swap, the component will have target_color only on vertices that were originally c.
                    # So if the component contains at least one vertex of color c, then after swap there will be vertices of color target_color (those that were c).
                    # Therefore, to eliminate target_color from the component, we need that the component contains no vertex of color c? 
