                # Should not happen, but if so, fallback to DSATUR
                return dsatur()

    # Compact colors
    if n == 0:
        return []
    max_c = max(best)
    if max_c < 0:
        return [0] * n
    # remap colors to consecutive integers
    unique_colors = sorted(set(best))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    compacted = [mapping[c] for c in best]

    return compacted

