def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if adjacency matrix (square and binary)
    is_matrix = (len(adj) > 0 and len(adj[0]) == n and
                 all(isinstance(x, int) and x in (0, 1) for row in adj for x in row))

    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    def is_valid_coloring(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    def greedy_coloring(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = coloring[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring

    # Heuristic 1: DSATUR
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                deg = sum(1 for u in neighbors[v] if u in uncolored)
                if sat > best_sat or (sat == best_sat and deg > best_deg):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            used = saturated[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] |= (1 << c)
        return coloring

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            S.add(v)
            # U: vertices not adjacent to S (eligible), W: vertices adjacent to S (ineligible)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in S for w in neighbors[u]):
                    W.add(u)
                    U.remove(u)
            # Greedily add to S from U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_neighbors = -1
                best_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for w in neighbors[u] if w in W)
                    deg_u = sum(1 for w in neighbors[u] if w in U)
                    if w_neighbors > best_w_neighbors or \
                       (w_neighbors == best_w_neighbors and deg_u < best_deg_u):
                        best_w_neighbors = w_neighbors
                        best_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                coloring[v] = color
            uncolored -= S
            color += 1
        return coloring

    # Heuristic 3: Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # Compute degeneracy ordering (smallest last)
        order = []
        remaining = set(range(n))
        degrees = [len(neighbors[i]) for i in range(n)]
        # We'll use bucket sort for efficiency
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = degrees[u]
                    buckets[d].remove(u)
                    degrees[u] -= 1
                    buckets[degrees[u]].append(u)
        # Color in reverse order
        return greedy_coloring(order[::-1])

    # Heuristic 4: Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        return greedy_coloring(order)

    # Generate initial colorings from multiple heuristics
    candidates = []
    for heuristic in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            coloring = heuristic()
            if is_valid_coloring(coloring):
                candidates.append(coloring)
        except Exception:
            continue

    # If no valid coloring from heuristics, fallback to simple greedy
    if not candidates:
        candidates.append(greedy_coloring(list(range(n))))

    # Select the coloring with the fewest colors
    best_coloring = min(candidates, key=lambda c: max(c) + 1 if c else 0)

    # Kempe chain-based color reduction
    def eliminate_color_class(coloring, target_color):
        # Get vertices with target_color
        verts = [v for v in range(n) if coloring[v] == target_color]
        if not verts:
            return coloring, True  # already eliminated
        # Try to recolor each vertex to a lower color
        for v in verts:
            used_by_neighbors = 0
            for u in neighbors[v]:
                c = coloring[u]
                if c != -1:
                    used_by_neighbors |= (1 << c)
            # Try direct reassignment to lowest available color < target_color
            for c in range(target_color):
                if not (used_by_neighbors & (1 << c)):
                    coloring[v] = c
                    break
            else:
                # Direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    # Check if v and any neighbor of color c are in different (c, target_color) components
                    # We'll do BFS to find the (c, target_color) component of v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in neighbors[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # Check if any neighbor of v with color c is NOT in this component
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c and u not in component:
                            conflict = True
                            break
                    if not conflict:
                        # Swap colors c and target_color in the component
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target_color
                            elif coloring[x] == target_color:
                                coloring[x] = c
                        # Now v has color c (since it was target_color and swapped)
                        break
                else:
                    # Could not recolor v, fail
                    return coloring, False
        return coloring, True

    # Try to eliminate colors from highest down
    max_color = max(best_coloring) if best_coloring else -1
    for target_color in range(max_color, -1, -1):
        new_coloring, eliminated = eliminate_color_class(best_coloring[:], target_color)
        if eliminated:
            # Compact colors: remap to consecutive indices
            color_map = {}
            next_color = 0
            for v in range(n):
                c = new_coloring[v]
                if c not in color_map:
                    color_map[c] = next_color
                    next_color += 1
                new_coloring[v] = color_map[c]
            best_coloring = new_coloring
            max_color = max(best_coloring) if best_coloring else -1
        else:
            # Could not eliminate this color, try lower
            continue

    # Final validation and compacting (ensure 0..k-1)
    if not is_valid_coloring(best_coloring):
        # Fallback to greedy on natural order
        best_coloring = greedy_coloring(list(range(n)))
    # Remap to consecutive colors
    used_colors = set(best_coloring)
    color_map = {c: i for i, c in enumerate(sorted(used_colors))]
    best_coloring = [color_map[c] for c in best_coloring]

    return best_coloring

