def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if v < n:  # safety check
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)

    # Helper: test if coloring is valid
    def is_valid_coloring(colors):
        for u in range(n):
            cu = colors[u]
            for v in adj_list[u]:
                if cu == colors[v]:
                    return False
        return True

    # Helper: count distinct colors
    def count_colors(colors):
        return len(set(colors)) if n > 0 else 0

    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # Heuristic 1: DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # Precompute neighbor bitsets
        neighbor_bits = bit_adj[:]
        for _ in range(n):
            # Select uncolored vertex with max saturation degree
            max_sat = -1
            candidates = []
            for v in range(n):
                if colored[v]:
                    continue
                # Compute saturation: distinct colors in neighbors
                sat_set = 0
                nb = neighbor_bits[v]
                while nb:
                    w = (nb & -nb).bit_length() - 1
                    if colors[w] != -1:
                        sat_set |= (1 << colors[w])
                    nb &= nb - 1
                sat = sat_set.bit_count()
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                best_v = candidates[0]
                for v in candidates:
                    deg = 0
                    nb = neighbor_bits[v]
                    while nb:
                        w = (nb & -nb).bit_length() - 1
                        if not colored[w]:
                            deg += 1
                        nb &= nb - 1
                    if deg > max_deg:
                        max_deg = deg
                        best_v = v
                v = best_v
            else:
                v = candidates[0]
            # Assign smallest available color
            used = 0
            nb = neighbor_bits[v]
            while nb:
                w = (nb & -nb).bit_length() - 1
                if colors[w] != -1:
                    used |= (1 << colors[w])
                nb &= nb - 1
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
        return compact_colors(colors)

    # Heuristic 2: RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build independent set for this color
            S = []
            # Start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v0 = None
            for v in uncolored:
                deg = 0
                for w in adj_list[v]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
            if v0 is None:
                break  # should not happen
            S.append(v0)
            # Partition: U = not adj to S, W = adj to S
            U = set(uncolored) - {v0}
            W = set()
            for w in adj_list[v0]:
                if w in U:
                    U.remove(w)
                    W.add(w)
            # Grow independent set
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                best_score = -1
                for u in U:
                    score = 0
                    for w in adj_list[u]:
                        if w in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # Tie-break: min degree in G[U]
                        deg_u = sum(1 for w in adj_list[u] if w in U)
                        deg_best = sum(1 for w in adj_list[best_u] if w in U) if best_u is not None else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u is None:
                    break
                S.append(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                colors[v] = color
            uncolored -= set(S)
            color += 1
        return compact_colors(colors)

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[v]) for v in range(n)]
        # Bucket sort by degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degrees[v]
            if d < len(buckets):
                buckets[d].add(v)
        # Peel min degree vertex
        for _ in range(n):
            # Find non-empty bucket with smallest index
            d = 0
            while d < len(buckets) and not buckets[d]:
                d += 1
            if d >= len(buckets):
                break  # should not happen
            v = buckets[d].pop()
            order.append(v)
            # Update neighbors
            for w in adj_list[v]:
                if w in remaining:
                    # Remove w from its current bucket
                    dw = degrees[w]
                    if dw < len(buckets) and w in buckets[dw]:
                        buckets[dw].remove(w)
                    degrees[w] -= 1
                    if degrees[w] >= 0:
                        if degrees[w] < len(buckets):
                            buckets[degrees[w]].add(w)
            remaining.remove(v)
        # Color in reverse order (largest last first)
        colors = [-1] * n
        for v in reversed(order):
            used = 0
            for w in adj_list[v]:
                if colors[w] != -1:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except Exception:
        pass

    # Fallback: greedy by original order
    def greedy_order():
        colors = [-1] * n
        for v in range(n):
            used = 0
            for w in adj_list[v]:
                if colors[w] != -1:
                    used |= (1 << colors[w])
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return compact_colors(colors)
    candidates.append(greedy_order())

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: (count_colors(x), x))
    k = count_colors(best)

    # Iterative Kempe chain color reduction
    def kempe_reduce(colors, k_target):
        # Try to eliminate color k_target-1
        while k_target > 0:
            # Find vertices with color k_target-1
            verts = [v for v in range(n) if colors[v] == k_target - 1]
            if not verts:
                k_target -= 1
                continue
            made_progress = False
            # Try direct reassignment to lower color
            for v in verts:
                used = 0
                for w in adj_list[v]:
                    if colors[w] != -1:
                        used |= (1 << colors[w])
                for c in range(k_target - 1):
                    if not (used & (1 << c)):
                        colors[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
            if made_progress:
                continue
            # Try Kempe chain swaps
            for v in verts:
                for c in range(k_target - 1):
                    # Check if v can be recolored to c via (c, k_target-1) Kempe chain
                    # Build component of v in subgraph of colors c and k_target-1
                    from collections import deque
                    comp = set()
                    q = deque([v])
                    comp.add(v)
                    target_colors = {c, k_target - 1}
                    while q:
                        u = q.popleft()
                        for w in adj_list[u]:
                            if colors[w] in target_colors and w not in comp:
                                comp.add(w)
                                q.append(w)
                    # Check if any neighbor of v has color c (would cause conflict if swapped)
                    conflict = False
                    for w in adj_list[v]:
                        if colors[w] == c and w not in comp:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: flip colors in component
                        for u in comp:
                            if colors[u] == c:
                                colors[u] = k_target - 1
                            elif colors[u] == k_target - 1:
                                colors[u] = c
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                break  # cannot eliminate this color
        return compact_colors(colors), k_target

    # Apply Kempe reduction
    best_colors, final_k = kempe_reduce(best[:], k)
    if is_valid_coloring(best_colors) and count_colors(best_colors) < count_colors(best):
        best = best_colors

    # Final validation and compacting
    if not is_valid_coloring(best):
        # Last resort: greedy
        best = greedy_order()
    best = compact_colors(best)
    return best

