def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Convert to adjacency list and compute degrees
    if is_matrix:
        graph = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    graph[u].append(v)
    else:
        graph = adj

    # Ensure symmetry for undirected graph
    for u in range(n):
        for v in graph[u]:
            if u not in graph[v]:
                graph[v].append(u)

    # Compute degree for each vertex
    degree = [len(graph[i]) for i in range(n)]

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in graph[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: count number of colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # DSATUR algorithm
    def dsatur():
        if n == 0:
            return []
        colors = [-1] * n
        # saturation: number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor colors as bitmask for efficiency
        neighbor_colors = [0] * n

        # Order vertices by degree descending for initial tie-breaking
        vertices = list(range(n))
        vertices.sort(key=lambda x: degree[x], reverse=True)

        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in vertices:
                if colors[u] == -1:
                    if saturation[u] > max_sat or \
                       (saturation[u] == max_sat and degree[u] > max_deg) or \
                       (saturation[u] == max_sat and degree[u] == max_deg and u < v):
                        max_sat = saturation[u]
                        max_deg = degree[u]
                        v = u
            if v == -1:
                break  # should not happen

            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c

            # Update saturation and neighbor colors for neighbors
            for nb in graph[v]:
                if colors[nb] == -1:  # only update uncolored neighbors
                    # Update neighbor colors bitmask
                    neighbor_colors[nb] |= (1 << c)
                    # Update saturation: count distinct colors in neighbor_colors[nb]
                    # We can compute by bit_count, but we maintain saturation incrementally
                    # Actually, we can update saturation by checking if this color is new
                    # But easier: recalculate saturation from neighbor_colors[nb] bit_count
                    saturation[nb] = neighbor_colors[nb].bit_count()

        return colors

    # RLF algorithm (Recursive Largest First)
    def rlf():
        if n == 0:
            return []
        colors = [-1] * n
        color_idx = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set for current color
            independent_set = []
            # Start with vertex of max degree in uncolored subgraph
            if uncolored:
                v = max(uncolored, key=lambda x: sum(1 for nb in graph[x] if nb in uncolored))
                independent_set.append(v)
                # Partition uncolored into U (not adjacent to any in S) and W (adjacent to S)
                U = uncolored - {v}
                W = set()
                for nb in graph[v]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
