def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build neighbor sets
    if is_matrix:
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        neighbors = [set(lst) for lst in adj]

    # Build complement graph adjacency (neighbors in complement)
    comp_neighbors = [set() for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and j not in neighbors[i]:
                comp_neighbors[i].add(j)

    color = [-1] * n
    uncolored = set(range(n))
    current_color = 0

    # Helper: greedy maximal clique in complement graph (i.e., maximal independent set in original)
    def greedy_clique(candidates):
        if not candidates:
            return set()
        # Degeneracy ordering: repeatedly remove min degree vertex in induced subgraph
        deg = {v: len(comp_neighbors[v] & candidates) for v in candidates}
        order = []
        remaining = set(candidates)
        while remaining:
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            for u in comp_neighbors[v]:
                if u in remaining:
                    deg[u] -= 1
        # Process in reverse order to build clique
        clique = set()
        for v in reversed(order):
            if all(u in comp_neighbors[v] for u in clique):
                clique.add(v)
        return clique

    # Main coloring loop: extract independent sets via complement cliques
    while uncolored:
        clique = greedy_clique(uncolored)
        for v in clique:
            color[v] = current_color
            uncolored.remove(v)
        current_color += 1

    # Compact colors to 0..k-1
    unique_colors = sorted(set(color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    color = [mapping[c] for c in color]

    return color

