    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    neighbors[u].add(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                neighbors[u].add(v)
                bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in neighbors[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: convert to consecutive colors
    def compress_colors(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # Heuristic 1: Triangle count ordering
    def triangle_count_order():
        tri_count = [0] * n
        for u in range(n):
            for v in neighbors[u]:
                if v > u:
                    common = neighbors[u] & neighbors[v]
                    for w in common:
                        if w > v:
                            tri_count[u] += 1
                            tri_count[v] += 1
                            tri_count[w] += 1
        order = list(range(n))
        order.sort(key=lambda x: (-tri_count[x], -len(neighbors[x]), x))
        return order

    # Heuristic 2: DSATUR with bit masks
    def dsatur():
        color = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = saturated[v].bit_count()
                deg = sum(1 for u in neighbors[v] if u in uncolored)
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Assign smallest available color
            c = 0
            while saturated[v] & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturated[u] |= (1 << c)
        return color

    # Heuristic 3: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = {u for u in uncolored if u != v and not (neighbors[u] & independent_set)}
            # W: vertices adjacent to at least one in independent_set
            W = {u for u in uncolored if u != v and (neighbors[u] & independent_set)}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                best_w_deg = -1
                best_u_deg = float('inf')
                for u in U:
                    w_deg = sum(1 for y in neighbors[u] if y in W)
                    u_deg = sum(1 for y in neighbors[u] if y in U)
                    if w_deg > best_w_deg or (w_deg == best_w_deg and u_deg < best_u_deg) or (w_deg == best_w_deg and u_deg == best_u_deg and u < best_u):
                        best_w_deg = w_deg
                        best_u_deg = u_deg
                        best_u = u
                u = best_u
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Heuristic 4: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[v]) for v in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Peel vertices
        for _ in range(n):
            # Find first non-empty bucket
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
            if i > max_deg:
                break
            v = buckets[i].pop()
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = degree[u]
                    degree[u] -= 1
                    if old_deg <= max_deg:
                        buckets[old_deg].remove(u)
                    if degree[u] <= max_deg:
                        buckets[degree[u]].append(u)
        # Color in reverse order
        return greedy_color(order[::-1])

    # Heuristic 5: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-len(neighbors[x]), x))
        return greedy_color(order)

    # Run all heuristics and collect candidates
    candidates = []
    for heuristic in [triangle_count_order, dsatur, rlf, smallest_last, welsh_powell]:
        try:
            if heuristic == triangle_count_order:
                order = heuristic()
                col = greedy_color(order)
            else:
