def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix
    is_matrix = True
    if len(adj) != len(adj[0]):
        is_matrix = False
    else:
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets and bitmasks
    if is_matrix:
        neighbors = [set() for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        neighbors = [set(lst) for lst in adj]
        bit_adj = [0] * n
        for i in range(n):
            for j in neighbors[i]:
                bit_adj[i] |= (1 << j)

    # Helper: compute chromatic number of a coloring
    def chromatic_number(col):
        return max(col) + 1 if col else 0

    # Helper: validate coloring
    def is_valid(col):
        for u in range(n):
            for v in neighbors[u]:
                if col[u] == col[v]:
                    return False
        return True

    # Helper: convert coloring to 0..k-1 consecutive
    def normalize(col):
        if not col:
            return col
        mapping = {}
        next_color = 0
        for c in col:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in col]

    # DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        colored = [False] * n
        # Initial vertex: max degree
        v = max(range(n), key=lambda x: len(neighbors[x]))
        color[v] = 0
        colored[v] = True
        for u in neighbors[v]:
            sat[u] = 1
        for _ in range(n - 1):
            # Select uncolored vertex with max saturation, tie-break by degree
            candidates = [u for u in range(n) if not colored[u]]
            if not candidates:
                break
            v = max(candidates, key=lambda u: (sat[u], len(neighbors[u])))
            # Find smallest available color
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if colored[u]:
                    used[color[u]] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
            colored[v] = True
            # Update saturation of neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    # Recompute saturation: number of distinct colors in neighbors
                    neighbor_colors = set()
                    for w in neighbors[u]:
                        if colored[w]:
                            neighbor_colors.add(color[w])
                    sat[u] = len(neighbor_colors)
        return normalize(color)

    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len(neighbors[x] & uncolored))
            S.add(v)
            # Partition: U = not adjacent to S, W = adjacent to S
            U = uncolored - {v} - (neighbors[v] & uncolored)
            W = neighbors[v] & uncolored
            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U
                u = max(U, key=lambda x: (len(neighbors[x] & W), -len(neighbors[x] & U)))
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nb = neighbors[u] & U
                U -= nb
                W |= nb
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return normalize(color)

    # Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(neighbors[v]) for v in range(n)]
        order = []
        # Bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degree[v]].append(v)
        # Peel min degree vertex
        for _ in range(n):
            # Find non-empty bucket with smallest index
            i = 0
            while i <= max_deg and not buckets[i]:
                i += 1
