        color = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
        return normalize(color)

