    def kempe_swap(color, a, b):
        # Build mapping of color to vertices
        color_classes = [[] for _ in range(max(color) + 1 if color else 0)]
        for v in range(n):
            if color[v] < len(color_classes):
                color_classes[color[v]].append(v)
        # Ensure a and b are valid
        if a >= len(color_classes) or b >= len(color_classes):
            return color
        visited = [False] * n
        # For each vertex of color a, try to swap its Kempe chain with b
        for start in color_classes[a]:
            if visited[start]:
                continue
            # BFS to get the (a,b)-Kempe component
            stack = [start]
            comp_a = set()
            comp_b = set()
            visited[start] = True
            while stack:
                v = stack.pop()
                if color[v] == a:
                    comp_a.add(v)
                elif color[v] == b:
                    comp_b.add(v)
                for u in neighbors[v]:
                    if not visited[u] and (color[u] == a or color[u] == b):
                        visited[u] = True
                        stack.append(u)
            # Check if we can swap: no vertex in comp_b adjacent to a vertex outside comp_a of color a?
            # Actually, swapping is always valid as it preserves proper coloring.
            # But we want to free color a for some vertex? Here we just attempt to reduce color usage.
            # Instead, we try to see if after swap, color a becomes unused somewhere.
            # For simplicity, we perform the swap and later check if color a can be removed.
            # Swap colors in the component
            for v in comp_a:
                color[v] = b
            for v in comp_b:
                color[v] = a
        return color

    # Attempt to eliminate the smallest color class via Kempe chains or reassignment
    def reduce_colors(color):
        if not color:
            return color
        k = chromatic_number(color)
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k - 1, -1, -1):
