                for c in range(target_color):
                    conflict = False
                    for u in neighbors[v]:
                        if color[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        color[v] = c
                        changed = True
                        # Update classes
                        if c < len(classes):
                            classes[c].append(v)
                        break
                if not changed:
