                    for c in range(target_color):
                        # Temporarily swap and see if we can free the target color
                        # We'll attempt to swap along (target_color, c) Kempe chain starting from v
                        # Make a copy for trial
                        trial_color = color[:]
                        visited = [False] * n
                        stack = [v]
                        comp_target = set()
                        comp_c = set()
                        visited[v] = True
                        while stack:
                            node = stack.pop()
                            if trial_color[node] == target_color:
                                comp_target.add(node)
                            elif trial_color[node] == c:
                                comp_c.add(node)
                            for u in neighbors[node]:
                                if not visited[u] and (trial_color[u] == target_color or trial_color[u] == c):
                                    visited[u] = True
