                        # Also check that no adjacent vertices have same color (should hold by Kempe property)
                        valid = True
                        for u in range(n):
                            for w in neighbors[u]:
                                if trial_color[u] == trial_color[w]:
                                    valid = False
                                    break
                            if not valid:
                                break
                        if valid and trial_color[v] == c:
                            # Accept the swap
                            color = trial_color
                            changed = True
                            # Update classes: v moved from target_color to c
                            if c < len(classes):
