                if not valid:
                    break
            if valid:
                k = max(col) + 1 if n > 0 else 0
                candidates.append((k, col))
        except:
            continue

    if not candidates:
        # Fallback: greedy arbitrary order
        colors = [0] * n
        for i in range(1, n):
            used = 0
            for j in neighbors[i]:
                if j < i:
                    used |= 1 << colors[j]
            c = 0
            while used & (1 << c):
                c += 1
            colors[i] = c
        candidates.append((max(colors) + 1 if n > 0 else 0, colors))

    # Select best candidate (min colors)
    best_k, best_coloring = min(candidates, key=lambda x: x[0])

    # Kempe chain color reduction
    def kempe_reduce(colors):
        nonlocal n, neighbors, bit_adj
        k = max(colors) + 1 if n > 0 else 0
        if k <= 1:
            return colors
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if colors[v] == target_color]
            if not target_vertices:
                continue
            # Try to recolor each target vertex
            changed = True
            while changed and target_vertices:
                changed = False
                v = target_vertices.pop()
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for u in neighbors[v]:
                    if colors[u] < target_color:
                        neighbor_colors.add(colors[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    # Re-add any vertices that might now be recolorable due to this change
                    for u in neighbors[v]:
                        if colors[u] == target_color and u not in target_vertices:
                            target_vertices.append(u)
                    continue
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Find Kempe chain (c, target_color) containing v
                    # BFS to get component
                    from collections import deque
                    queue = deque([v])
                    visited = set([v])
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for y in neighbors[x]:
                            if colors[y] == c or colors[y] == target_color:
                                if y not in visited:
                                    visited.add(y)
                                    queue.append(y)
                    # Check if swapping frees color c for v
                    # After swap, v would get color c if it's in the component
                    # We need that no neighbor of v has color c after swap
                    # Neighbors of v that are in the component will change from target_color to c
                    # Neighbors of v not in the component keep their color
                    conflict = False
                    for u in neighbors[v]:
                        if colors[u] == c and u not in component:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap
                        for x in component:
                            if colors[x] == c:
                                colors[x] = target_color
                            else:  # must be target_color
                                colors[x] = c
                        changed = True
                        # After swap, v now has color c
                        # Re-check neighbors for potential recoloring
                        for u in neighbors[v]:
                            if colors[u] == target_color and u not in target_vertices:
                                target_vertices.append(u)
                        break
            # If no target vertices left, this color is eliminated
            if not any(colors[v] == target_color for v in range(n)):
                # Compact colors: map [0..target_color-1] -> same, [target_color+1..k-1] -> shifted down
                mapping = {}
                for c in range(k):
                    if c < target_color:
                        mapping[c] = c
                    elif c > target_color:
                        mapping[c] = c - 1
                colors = [mapping[c] for c in colors]
                k -= 1
                # Try to eliminate next color (now at same index)
                # Break to restart from new highest color
                break
        return colors

    # Apply Kempe reduction
    best_coloring = kempe_reduce(best_coloring)

    # Ensure colors are consecutive
    if best_coloring:
        unique_colors = sorted(set(best_coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if entries are binary (0 or 1)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to adjacency list and bitmask for fast operations
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build bitmask adjacency: bit_adj[u] has bit v set if (u,v) is an edge
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: convert coloring to use consecutive colors starting from 0
    def normalize(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR algorithm
    def dsatur():
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # degree in the uncolored subgraph (for tie-breaking)
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        colored = [False] * n

        for _ in range(n):
            # Select uncolored vertex with max saturation, then max degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if colored[u]:
                    continue
                if saturation[u] > max_sat or (saturation[u] == max_sat and uncolored_deg[u] > max_deg) or \
                   (saturation[u] == max_sat and uncolored_deg[u] == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = saturation[u]
                    max_deg = uncolored_deg[u]
                    v = u
            if v == -1:
                break  # should not happen

            # Find smallest color not used by neighbors
            neighbor_colors = 0
            for nb in adj_list[v]:
                if colored[nb]:
                    neighbor_colors |= (1 << coloring[nb])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
            colored[v] = True

            # Update saturation and uncolored degree for neighbors
            for nb in adj_list[v]:
                if not colored[nb]:
                    # Update saturation: if color c is new in nb's neighbors
                    if not (saturation[nb] & (1 << c)):
                        saturation[nb] |= (1 << c)
                    # Update uncolored degree: v is now colored, so remove from uncolored neighbor count
                    uncolored_deg[nb] -= 1
        return normalize(coloring)

    # RLF algorithm (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        colored = [False] * n
        color = 0

        while not all(colored):
            # R: set of uncolored vertices
            R = [i for i in range(n) if not colored[i]]
            if not R:
                break

            # Build induced subgraph degrees for R
            deg_in_R = [0] * n
            for u in R:
                for v in adj_list[u]:
                    if not colored[v]:
                        deg_in_R[u] += 1

            # Step 2: choose v1 in R with max degree in G[R]
            v1 = max(R, key=lambda x: deg_in_R[x])
            S = [v1]
            colored[v1] = True  # temporarily mark as colored for partitioning

            # Partition R \ {v1} into U (not adjacent to S) and W (adjacent to S)
            U = []
            W = []
            for v in R:
                if v == v1:
                    continue
                adjacent_to_S = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.append(v)
                else:
                    U.append(v)

            # While U is not empty, add vertices to S
            while U:
                # For each u in U, compute |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                # Precompute adjacency to W for speed
                for u in U:
                    w_neighbors = 0
                    for nb in adj_list[u]:
                        if not colored[nb] and nb in W:  # nb is in W and uncolored
                            w_neighbors += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if not colored[nb] and nb in U:
                            deg_in_U += 1
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and (best_u == -1 or random.random() < 0.5)):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen if U not empty
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if not colored[nb] and nb in U:
                        U.remove(nb)
                        W.append(nb)

            # Assign current color to all vertices in S
            for v in S:
                coloring[v] = color
            color += 1

        return normalize(coloring)

    # Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # Compute core ordering (smallest-last)
        degree = [len(adj_list[i]) for i in range(n)]
        # We'll use a bucket sort like approach for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[degree[i]].append(i)
        # Pointer to current non-empty bucket
        ptr = 0
        ordering = []
        # Copy of degree for updating
        curr_deg = degree[:]
        removed = [False] * n

        for _ in range(n):
            # Find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            # Remove a vertex from bucket[ptr]
            v = buckets[ptr].pop()
            while removed[v]:
                if not buckets[ptr]:
                    break
                v = buckets[ptr].pop()
            if removed[v]:
                # Should not happen if we managed buckets correctly
                for i in range(n):
                    if not removed[i]:
                        v = i
                        break
            ordering.append(v)
            removed[v] = True
            # Update neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    # Remove nb from its current bucket
                    d = curr_deg[nb]
                    if d < len(buckets) and nb in buckets[d]:
                        buckets[d].remove(nb)
                    curr_deg[nb] -= 1
                    if curr_deg[nb] >= 0:
                        buckets[curr_deg[nb]].append(nb)
        # Color in reverse order using greedy first-fit
        coloring = [-1] * n
        for v in reversed(ordering):
            neighbor_colors = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    neighbor_colors |= (1 << coloring[nb])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        return normalize(coloring)

    # Kempe chain based color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        current = coloring[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(current)
            if k <= 1:
                break
            # Target the last color (k-1)
            target_color = k - 1
            # Vertices with target color
            target_vertices = [v for v in range(n) if current[v] == target_color]
            if not target_vertices:
                # Already normalized, should not happen
                break

            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = 0
                for nb in adj_list[v]:
                    if current[nb] != -1:
                        neighbor_colors |= (1 << current[nb])
                # Find smallest color not in neighbor_colors
                for c in range(target_color):  # only try colors < target_color
                    if not (neighbor_colors & (1 << c)):
                        # Can recolor v to c
                        current[v] = c
                        changed = True
                        break
                if changed:
                    break  # restart the while loop after any change

                # If direct reassignment not possible, try Kempe chains
                for c in range(target_color):
                    # Check if v is connected to color c via a Kempe chain
                    # We'll try to swap colors c and target_color in the component of v
                    # Only if doing so doesn't pull any vertex into target_color from outside
                    # We do BFS to get the Kempe chain component for colors (c, target_color)
                    from collections import deque
                    visited = [False] * n
                    queue = deque()
                    # Start BFS from v only if it has color target_color (it does)
                    if current[v] != target_color:
                        continue
                    queue.append(v)
                    visited[v] = True
                    component = []
                    is_valid_swap = True
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and (current[nb] == c or current[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # Check if any neighbor of the component has color c (external)
                    # If so, swapping would cause conflict
                    for node in component:
                        for nb in adj_list[node]:
                            if not visited[nb] and current[nb] == c:
                                is_valid_swap = False
                                break
                        if not is_valid_swap:
                            break
                    if is_valid_swap:
                        # Perform swap: c <-> target_color in component
                        for node in component:
                            if current[node] == c:
                                current[node] = target_color
                            elif current[node] == target_color:
                                current[node] = c
                        changed = True
                        break
                if changed:
                    break
            # If we changed something, we may have emptied target_color; normalize and repeat
            if changed:
                # Renormalize colors to be consecutive
                # Map current colors to 0..k'-1
                mapping = {}
                next_c = 0
                for i in range(n):
                    if current[i] not in mapping:
                        mapping[current[i]] = next_c
                        next_c += 1
                    current[i] = mapping[current[i]]
        return current

    # Generate candidate colorings
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select the candidate with the fewest colors
    best = min(candidates, key=num_colors)
    best_coloring = kempe_reduce(best)

    # Final validation and normalization
    if not is_valid(best_coloring):
        # Fallback: use greedy on degree order
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            neighbor_colors = 0
            for nb in adj_list[v]:
                if coloring[nb] != -1:
                    neighbor_colors |= (1 << coloring[nb])
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize(coloring)

    return best_coloring

import math
