from collections import deque

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list if necessary
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        graph = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    graph[u].append(v)
    else:
        graph = [list(neigh) for neigh in adj]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = [False] * n
            for v in graph[u]:
                if color[v] != -1:
                    used[color[v]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[u] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR
    def dsatur():
        color = [-1] * n
        saturated = [set() for _ in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (len(saturated[x]), len([y for y in graph[x] if y in uncolored]), x))
            # Assign smallest available color
            used = [False] * n
            for y in graph[v]:
                if color[y] != -1:
                    used[color[y]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for y in graph[v]:
                if y in uncolored:
                    saturated[y].add(c)
        return color

    col_dsatur = dsatur()
    k_dsatur = num_colors(col_dsatur)
    if k_dsatur < best_k:
        best_k = k_dsatur
        best_coloring = col_dsatur

    # 2. RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in graph[x] if y in uncolored]))
            independent_set = {v}
            # Partition: U = vertices not adjacent to any in independent_set, W = adjacent
            U = {x for x in uncolored if x != v and all(y not in independent_set for y in graph[x])}
            W = {x for x in uncolored if x != v and any(y in independent_set for y in graph[x])}
            while U:
                # Select u in U with max neighbors in W
                u = max(U, key=lambda x: len([y for y in graph[x] if y in W]))
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in graph[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    col_rlf = rlf()
    k_rlf = num_colors(col_rlf)
    if k_rlf < best_k:
        best_k = k_rlf
        best_coloring = col_rlf

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        deg = [len(graph[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # Bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [deque() for _ in range(max_deg + 1)]
        for i in range(n):
            buckets[deg[i]].append(i)
        # Peeling
        for _ in range(n):
            # Find first non-empty bucket
            d = 0
            while d <= max_deg and not buckets[d]:
                d += 1
            if d > max_deg:
                break
            v = buckets[d].popleft()
            order.append(v)
            remaining.remove(v)
            # Decrease degree of neighbors
            for y in graph[v]:
                if y in remaining:
                    old_deg = deg[y]
                    deg[y] -= 1
                    if old_deg < len(buckets):
                        buckets[old_deg].remove(y)
                    if deg[y] < len(buckets):
                        buckets[deg[y]].append(y)
        # Color in reverse order
        return greedy_color(order[::-1])

    col_sl = smallest_last()
    k_sl = num_colors(col_sl)
    if k_sl < best_k:
        best_k = k_sl
        best_coloring = col_sl

    # If we already have a good coloring, try to improve via Kempe chains
    def kempe_reduce(coloring):
        # Make coloring compact
        def compact(col):
            mapping = {}
            next_color = 0
            for c in col:
                if c not in mapping:
                    mapping[c] = next_color
                    next_color += 1
            return [mapping[c] for c in col]

        coloring = compact(coloring)
        k = num_colors(coloring)
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest to lowest
        improved = True
        while improved and k > 1:
            improved = False
            # Target the smallest color class (highest index)
            target_color = k - 1
            target_vertices = [v for v in range(n) if coloring[v] == target_color]
            if not target_vertices:
                # Already compact
                coloring = compact(coloring)
                k = num_colors(coloring)
                continue

            # Try to recolor each target vertex
            for v in target_vertices[:]:  # copy list as we may modify
                # Try direct reassignment to a lower color
                used = [False] * k
                for u in graph[v]:
                    if coloring[u] != -1:
                        used[coloring[u]] = True
                for c in range(target_color):
                    if not used[c]:
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    # Recompact and break to restart
                    coloring = compact(coloring)
                    k = num_colors(coloring)
                    break

                # Try Kempe chain swaps with each lower color
                for c in range(target_color):
                    # Find the Kempe chain component of v in colors {target_color, c}
                    # BFS to get component
                    comp = []
                    seen = set()
                    stack = [v]
                    seen.add(v)
                    while stack:
                        node = stack.pop()
                        comp.append(node)
                        for u in graph[node]:
                            if u not in seen and coloring[u] in (target_color, c):
                                seen.add(u)
                                stack.append(u)
                    # Check if swapping colors in comp would cause conflict
                    # After swap: target_color -> c, c -> target_color
                    # Check neighbors of comp for color c (which would become target_color)
                    conflict = False
                    for node in comp:
                        for u in graph[node]:
                            if u not in comp and coloring[u] == c:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Perform swap
                        for node in comp:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        improved = True
                        # Recompact and break to restart
                        coloring = compact(coloring)
                        k = num_colors(coloring)
                        break
                if improved:
                    break

        return coloring

    # Apply Kempe reduction to the best coloring so far
    if best_coloring is not None:
        improved_coloring = kempe_reduce(best_coloring[:])  # work on a copy
        k_improved = num_colors(improved_coloring)
        if k_improved < best_k:
            best_k = k_improved
            best_coloring = improved_coloring

    # Final validation and compaction
    if best_coloring is None:
        # Fallback: greedy by degree
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        best_coloring = greedy_color(order)

    # Ensure compact and valid
    def is_valid(col):
        for u in range(n):
            for v in graph[u]:
                if u < v and col[u] == col[v]:
                    return False
        return True

    if not is_valid(best_coloring):
        # Last resort: greedy
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        best_coloring = greedy_color(order)

    # Compact final coloring
    mapping = {}
    next_color = 0
    for c in best_coloring:
        if c not in mapping:
            mapping[c] = next_color
            next_color += 1
    best_coloring = [mapping[c] for c in best_coloring]

    return best_coloring

import math
