def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flatten times for faster access
    flat_times = [0] * (N * M)
    for i in range(N):
        for j in range(M):
            flat_times[i * M + j] = times[i][j]

    # Compute total processing times for NEH priority
    P = [0] * N
    for i in range(N):
        s = 0
        base = i * M
        for j in range(M):
            s += flat_times[base + j]
        P[i] = s

    # Sort jobs by descending total processing time
    order = list(range(N))
    order.sort(key=lambda i: P[i], reverse=True)

    # Helper to compute makespan of a given sequence
    def makespan(seq):
        t = [0] * M
        for job in seq:
            base = job * M
            t[0] += flat_times[base]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + flat_times[base + m]
        return t[M-1]

    # Initialize with first two jobs
    if N >= 2:
        j0, j1 = order[0], order[1]
        seq0 = [j0, j1]
        seq1 = [j1, j0]
        if makespan(seq0) <= makespan(seq1):
            current_seq = seq0
        else:
