            else:
                e[r][0] = e[r-1][0] + flat_times[base_r]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + flat_times[base_r + m]

        # Compute backward tail matrix q[0..k][0..M-1]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = current_seq[r]
            base_r = job_r * M
            q[r][M-1] = q[r+1][M-1] + flat_times[base_r + M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + flat_times[base_r + m]

        # Evaluate all k+1 insertion positions
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            # Compute forward vector f for inserting job at position i
            if i == 0:
                f0 = flat_times[base_job]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], 0) + flat_times[base_job + m])
            else:
                base_prev = current_seq[i-1] * M
                f0 = e[i-1][0] + flat_times[base_job]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], e[i-1][m]) + flat_times[base_job + m])

            # Compute makespan: max_m (f[m] + q[i][m])
            makespan_i = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_i:
                    makespan_i = val

            if makespan_i < best_makespan:
                best_makespan = makespan_i
                best_pos = i

        current_seq.insert(best_pos, job)

    # Iterated Greedy refinement
    random.seed(42)  # Deterministic seed for reproducibility
    total_processing = sum(P)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-9:
