def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * m
        for job in seq:
            job_time = times[job]
            t[0] += job_time[0]
            for k in range(1, m):
                t[k] = max(t[k-1], t[k]) + job_time[k]
        return t[-1]

    def compute_tail_matrix(seq):
        k = len(seq)
        if k == 0:
            return [[0] * m]
        tail = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            job_time = times[job]
            tail[r][m-1] = tail[r+1][m-1] + job_time[m-1]
            for mc in range(m-2, -1, -1):
                tail[r][mc] = max(tail[r+1][mc], tail[r][mc+1]) + job_time[mc]
        return tail

    def compute_forward_matrix(seq):
        k = len(seq)
        if k == 0:
            return [[0] * m]
        forward = [[0] * m for _ in range(k)]
        for r in range(k):
            job = seq[r]
            job_time = times[job]
            if r == 0:
                forward[0][0] = job_time[0]
                for mc in range(1, m):
                    forward[0][mc] = forward[0][mc-1] + job_time[mc]
            else:
                forward[r][0] = forward[r-1][0] + job_time[0]
                for mc in range(1, m):
                    forward[r][mc] = max(forward[r-1][mc], forward[r][mc-1]) + job_time[mc]
        return forward

    def insert_job_with_tail(seq, job, forward, tail):
        k = len(seq)
        best_pos = 0
        best_makespan = float('inf')
        job_time = times[job]
        for i in range(k+1):
            if i == 0:
                f0 = job_time[0]
                f = [f0]
                for mc in range(1, m):
                    f.append(max(f[mc-1], 0) + job_time[mc])
            else:
                prev_row = forward[i-1]
                f0 = prev_row[0] + job_time[0]
                f = [f0]
                for mc in range(1, m):
                    f.append(max(f[mc-1], prev_row[mc]) + job_time[mc])
            makespan_val = 0
            tail_row = tail[i]
            for mc in range(m):
                val = f[mc] + tail_row[mc]
                if val > makespan_val:
                    makespan_val = val
            if makespan_val < best_makespan:
                best_makespan = makespan_val
                best_pos = i
        return seq[:best_pos] + [job] + seq[best_pos:], best_makespan

    # NEH construction with Taillard acceleration
    job_sums = [sum(job) for job in times]
    order = sorted(range(n), key=lambda i: job_sums[i], reverse=True)
    seq = [order[0]]
    best_makespan = makespan(seq)
    for idx in range(1, n):
        job = order[idx]
        forward = compute_forward_matrix(seq)
        tail = compute_tail_matrix(seq)
        seq, best_makespan = insert_job_with_tail(seq, job, forward, tail)

    # Iterated Greedy refinement
    current_seq = seq[:]
    best_seq = seq[:]
    best_makespan_val = best_makespan
    T_param = 0.5
    T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
    d = 3 if n > 20 else 2
    max_iter = 50
    no_improve_limit = 15
    no_improve = 0

    for _ in range(max_iter):
        if no_improve >= no_improve_limit:
            break
        indices = list(range(n))
        random.shuffle(indices)
        removed = []
        remaining = current_seq[:]
        for _ in range(d):
            if not remaining:
                break
            idx_remove = indices.pop()
            pos = remaining.index(idx_remove)
            removed.append(remaining.pop(pos))
        random.shuffle(removed)
        for job in removed:
            forward = compute_forward_matrix(remaining)
            tail = compute_tail_matrix(remaining)
            remaining, _ = insert_job_with_tail(remaining, job, forward, tail)
        current_seq = remaining
        current_makespan = makespan(current_seq)
        if current_makespan < best_makespan_val:
            best_seq = current_seq[:]
            best_makespan_val = current_makespan
            no_improve = 0
        elif current_makespan < makespan(seq):
            seq = current_seq[:]
            no_improve = 0
        else:
            if random.random() < math.exp(-(current_makespan - makespan(seq)) / T):
                seq = current_seq[:]
                no_improve += 1
            else:
                no_improve += 1

    return best_seq

