def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    P = [0] * N
    for i in range(N):
        s = 0
        row = times[i]
        for j in range(M):
            s += row[j]
        P[i] = s
        total_processing += s

    order = sorted(range(N), key=lambda i: P[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            row = times[job]
            t[0] += row[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + row[m]
        return t[M-1]

    def taillard_insertion(current_seq, job_x):
        k = len(current_seq)
        if k == 0:
            return [job_x]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = current_seq[r]
            row_r = times[job_r]
            if r == 0:
                e[0][0] = row_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + row_r[m]
            else:
                e[r][0] = e[r-1][0] + row_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + row_r[m]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = current_seq[r]
            row_r = times[job_r]
            q[r][M-1] = q[r+1][M-1] + row_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + row_r[m]
        best_pos = 0
        best_cmax = float('inf')
        row_x = times[job_x]
        for i in range(k+1):
            if i == 0:
                f0 = row_x[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], 0) + row_x[m])
            else:
                prev_e = e[i-1]
                f0 = prev_e[0] + row_x[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], prev_e[m]) + row_x[m])
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return current_seq[:best_pos] + [job_x] + current_seq[best_pos:]

    perm = []
    for idx in order:
        perm = taillard_insertion(perm, idx)

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3
    max_iters = 60
    current = perm[:]
    best = current[:]
    best_cmax = makespan(best)
    current_cmax = best_cmax

    for _ in range(max_iters):
        destroyed = current[:]
        random.shuffle(destroyed)
        R = destroyed[:d]
        pi_D = destroyed[d:]
        for job in R:
            pi_D = taillard_insertion(pi_D, job)
        new_cmax = makespan(pi_D)
        if new_cmax < current_cmax or random.random() < math.exp(-(new_cmax - current_cmax) / T):
            current = pi_D
            current_cmax = new_cmax
            if new_cmax < best_cmax:
                best = current[:]
                best_cmax = new_cmax
    return best

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if N == 1:
        return [0]
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flatten times for faster access
    flat_times = [t for job in times for t in job]
    def get_time(job, machine):
        return flat_times[job * M + machine]

    # Helper: makespan of a permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            base = 0
            for m in range(M):
                base = max(t[m], base) + get_time(job, m)
                t[m] = base
        return t[-1]

    # Taillard's accelerated makespan evaluation for insertion
    def evaluate_insertion(partial, job, pos, fwd, bw):
        # fwd: forward matrix for partial schedule (size len(partial) x M)
        # bw: backward matrix for partial schedule (size (len(partial)+1) x M)
        # Compute forward vector f for inserting 'job' at position 'pos'
        f = [0] * M
        if pos == 0:
            prev = [0] * M
        else:
            prev = fwd[pos-1]
        for m in range(M):
            if m == 0:
                f[m] = prev[0] + get_time(job, 0)
            else:
                f[m] = max(f[m-1], prev[m]) + get_time(job, m)
        # Compute makespan: max over m of f[m] + bw[pos][m]
        max_val = 0
        for m in range(M):
            val = f[m] + bw[pos][m]
            if val > max_val:
                max_val = val
        return max_val

    # Taillard's forward and backward matrices for a given partial schedule
    def compute_taillard(partial):
        k = len(partial)
        if k == 0:
            return ([], [[0]*M])  # fwd empty, bw[0] = [0]*M
        # Forward matrix fwd[r][m] for r in [0, k-1]
        fwd = [[0]*M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            for m in range(M):
                if m == 0:
                    if r == 0:
                        fwd[r][m] = get_time(job, 0)
                    else:
                        fwd[r][m] = fwd[r-1][m] + get_time(job, 0)
                else:
                    if r == 0:
                        fwd[r][m] = fwd[r][m-1] + get_time(job, 0)
                    else:
                        fwd[r][m] = max(fwd[r-1][m], fwd[r][m-1]) + get_time(job, m)
        # Backward matrix bw[r][m] for r in [0, k] (bw[k] = [0]*M)
        bw = [[0]*M for _ in range(k+1)]
        # bw[k] already zero
        for r in range(k-1, -1, -1):
            job = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    bw[r][m] = bw[r+1][m] + get_time(job, m)
                else:
                    bw[r][m] = max(bw[r+1][m], bw[r][m+1]) + get_time(job, m)
        return (fwd, bw)

    # NEH construction with Taillard acceleration
    def neh_construction():
        # Job priority: total processing time descending
        job_sums = [sum(get_time(i, j) for j in range(M)) for i in range(N)]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        # Start with first two jobs
        if N >= 2:
            a, b = order[0], order[1]
            seq1 = [a, b]
            seq2 = [b, a]
            if makespan(seq1) <= makespan(seq2):
                partial = seq1[:]
            else:
                partial = seq2[:]
            start_idx = 2
        else:
            partial = [order[0]]
            start_idx = 1
        # Insert remaining jobs
        for idx in range(start_idx, N):
            job = order[idx]
            k = len(partial)
            fwd, bw = compute_taillard(partial)
            best_pos = 0
            best_makespan = float('inf')
            # Evaluate all k+1 insertion positions
            for pos in range(k+1):
                mks = evaluate_insertion(partial, job, pos, fwd, bw)
                if mks < best_makespan:
                    best_makespan = mks
                    best_pos = pos
            partial.insert(best_pos, job)
        return partial

    # Iterated Greedy (IG) metaheuristic
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing = sum(get_time(i, j) for i in range(N) for j in range(M))
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
