            if mk_new < best_mk:
                best = seq[:]
                best_mk = mk_new
                current = seq[:]
            elif mk_new < makespan(current):
                current = seq[:]
            else:
                if random.random() < math.exp(-(mk_new - makespan(current)) / T):
                    current = seq[:]
