    # Main execution
    initial = neh_construction()
    # Early exit if makespan equals a lower bound (optional, but cheap)
    # Compute Taillard's LB (machine bottleneck)
    LB = 0
    for m in range(M):
        min_pre = min(get_time(i, l) for i in range(N) for l in range(m)) if m > 0 else 0
        min_suf = min(get_time(i, l) for i in range(N) for l in range(m+1, M)) if m < M-1 else 0
        machine_sum = sum(get_time(i, m) for i in range(N))
        lb_m = min_pre + machine_sum + min_suf
        if lb_m > LB:
            LB = lb_m
    if makespan(initial) == LB:
        return initial
    # Run IG
    improved = iterated_greedy(initial, max_iter=50)
    return improved

