def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten times for faster access
    flat_times = [0] * (N * M)
    for i in range(N):
        for j in range(M):
            flat_times[i * M + j] = times[i][j]

    # Helper to get processing time
    def p(i, j):
        return flat_times[i * M + j]

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            base = p(job, 0)
            t[0] += base
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p(job, m)
        return t[M-1]

    # Taillard accelerated insertion evaluation
    def evaluate_insertion(partial, job, k):
        # partial: list of job indices of length k
        if k == 0:
            return p(job, 0) + (sum(p(job, m) for m in range(1, M)) if M > 1 else 0)
        # Compute forward matrix e (size k x M)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            if r == 0:
                e[0][0] = p(job_r, 0)
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p(job_r, m)
            else:
                e[r][0] = e[r-1][0] + p(job_r, 0)
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p(job_r, m)
        # Compute backward tail matrix q (size (k+1) x M)
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            q[r][M-1] = q[r+1][M-1] + p(job_r, M-1)
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p(job_r, m)
        # Evaluate each insertion position i in [0, k]
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            # Compute forward vector f for job at position i
            if i == 0:
                f0 = p(job, 0)
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], 0) + p(job, m))
            else:
                prev_e = e[i-1]
                f0 = prev_e[0] + p(job, 0)
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], prev_e[m]) + p(job, m))
            # Compute makespan candidate: max_m (f[m] + q[i][m])
            cand = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cand:
                    cand = val
            if cand < best_makespan:
                best_makespan = cand
                best_pos = i
        return best_pos, best_makespan

    # NEH construction with Taillard acceleration
    total_proc = [sum(p(i, m) for m in range(M)) for i in range(N)]
    order = sorted(range(N), key=lambda i: (-total_proc[i], i))
    perm = [order[0]]
    if N > 1:
        # Evaluate first two jobs
        job0, job1 = order[0], order[1]
        m1 = makespan([job0, job1])
        m2 = makespan([job1, job0])
        if m2 < m1:
            perm = [job1, job0]
        else:
            perm = [job0, job1]
        # Insert remaining jobs
        for idx in range(2, N):
            job = order[idx]
            pos, _ = evaluate_insertion(perm, job, len(perm))
            perm.insert(pos, job)

    # Iterated Greedy (IG) refinement
    total_sum = sum(total_proc)
    T_param = 0.5
    T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
    current = perm[:]
    current_makespan = makespan(current)
    best = current[:]
    best_makespan = current_makespan

    max_iter = 60  # Calibrated to stay within 50ms for N<=120, M<=20
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d > 0:
            indices = random.sample(range(N), d)
            removed = [current[i] for i in sorted(indices, reverse=True)]
            for i in sorted(indices, reverse=True):
                del current[i]
        else:
            removed = []
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            pos, _ = evaluate_insertion(current, job, len(current))
            current.insert(pos, job)
        # Compute new makespan
        new_makespan = makespan(current)
        # Acceptance criterion
        if new_makespan < current_makespan:
            current = current[:]
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best = current[:]
                best_makespan = new_makespan
        elif new_makespan < best_makespan:
            # Accept with probability (Metropolis)
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current = current[:]
                current_makespan = new_makespan
            else:
                # Revert to previous current (not best)
                pass  # current remains unchanged
        else:
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current = current[:]
                current_makespan = new_makespan
        # Early exit if optimal (optional, requires LB which is omitted for speed)
    return best

