                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job_r][m]
        # backward tail matrix q[r][m] for r in 0..k
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job_r][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
        # evaluate each insertion position i in 0..k
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            # forward vector f[m] for job at position i
            f = [0] * M
            for m in range(M):
                if m == 0:
                    f[m] = (e[i-1][m] if i > 0 else 0) + p[job][m]
                else:
                    f[m] = max(f[m-1], e[i-1][m] if i > 0 else 0) + p[job][m]
            # makespan = max_m (f[m] + q[i][m])
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return best_pos, best_mk

    # NEH construction with Taillard acceleration
    def neh(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            # evaluate two jobs
            mk1 = makespan([order[0], order[1]])
            mk2 = makespan([order[1], order[0]])
            seq = [order[0], order[1]] if mk1 <= mk2 else [order[1], order[0]]
            start = 2
        else:
            start = 1
        for idx in range(start, len(order)):
            job = order[idx]
            pos, _ = evaluate_insertion(seq, job, len(seq))
            seq.insert(pos, job)
        return seq

    # Try multiple orderings: total_p descending, slope descending
    order_total = sorted(range(N), key=lambda i: total_p[i], reverse=True)
    order_slope = sorted(range(N), key=lambda i: slope[i], reverse=True)
    best_seq = None
    best_mk = float('inf')
    for order in (order_total, order_slope):
        seq = neh(order)
        mk = makespan(seq)
        if mk < best_mk:
            best_mk = mk
            best_seq = seq

    # Iterated Greedy refinement
    # Parameters
    T_param = 0.5
    total_processing = sum(total_p)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2  # destruction size
    max_iter = 60  # calibrated for <50ms
    current_seq = best_seq[:]
    current_mk = best_mk
    best_seq_ig = current_seq[:]
    best_mk_ig = current_mk

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            removed = current_seq[:]
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            destroyed = [current_seq[i] for i in indices]
            removed = [current_seq[i] for i in range(N) if i not in indices_set]
        # Reconstruction: reinsert using NEH insertion (Taillard accelerated)
        for job in destroyed:
            pos, _ = evaluate_insertion(removed, job, len(removed))
            removed.insert(pos, job)
        new_seq = removed
        new_mk = makespan(new_seq)
        # Acceptance
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current_seq = new_seq
            current_mk = new_mk
            if new_mk < best_mk_ig:
                best_seq_ig = new_seq[:]
                best_mk_ig = new_mk
        # Early exit if optimal (not implemented due to no LB)
    return best_seq_ig

