def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data and total processing times
    job_data = [row[:] for row in times]
    total_time = [sum(job) for job in job_data]

    # NEH with Taillard acceleration
    def makespan_neh(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            p = job_data[job]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[m]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            pj = job_data[perm[r]]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pj = job_data[perm[r]]
            if r == k-1:
                q[r][M-1] = pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = q[r][m+1] + pj[m]
            else:
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    def insertion_cost(perm, job, pos):
        k = len(perm)
        if k == 0:
            return job_data[job][-1]
        e = compute_forward(perm)
        q = compute_backward(perm)
        i = pos
        pj = job_data[job]
        f = [0] * M
        if i == 0:
            f[0] = pj[0]
            for m in range(1, M):
                f[m] = f[m-1] + pj[m]
        else:
            e_prev = e[i-1]
            f[0] = e_prev[0] + pj[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + pj[m]
        q_i = q[i]
        max_val = 0
        for m in range(M):
            val = f[m] + q_i[m]
            if val > max_val:
                max_val = val
        return max_val

    # Build initial NEH solution
    order = sorted(range(N), key=lambda i: total_time[i], reverse=True)
    perm_neh = [order[0]]
    if N > 1:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan_neh(seq1) <= makespan_neh(seq2):
            perm_neh = seq1
        else:
            perm_neh = seq2
        for idx in range(2, N):
            job = order[idx]
            best_pos = 0
            best_cost = insertion_cost(perm_neh, job, 0)
            for pos in range(1, len(perm_neh) + 1):
                cost = insertion_cost(perm_neh, job, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            perm_neh.insert(best_pos, job)

    # Iterated Greedy
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            p = job_data[job]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[m]
        return t[-1]

    def destroy(perm, d):
        indices = random.sample(range(len(perm)), d)
        removed = [perm[i] for i in indices]
        remaining = [perm[i] for i in range(len(perm)) if i not in indices]
        return remaining, removed

    def reconstruct(remaining, removed):
        perm = remaining[:]
        for job in removed:
            best_pos = 0
            best_cost = insertion_cost(perm, job, 0)
            for pos in range(1, len(perm) + 1):
                cost = insertion_cost(perm, job, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # IG parameters
    total_processing = sum(total_time)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0
    d = 3 if N > 5 else 2
    max_iter = 50

    current = perm_neh[:]
    best = current[:]
    best_makespan = makespan(current)

    for _ in range(max_iter):
        remaining, removed = destroy(current, d)
        candidate = reconstruct(remaining, removed)
        cand_makespan = makespan(candidate)
        curr_makespan = makespan(current)
        if cand_makespan < curr_makespan:
            current = candidate
            if cand_makespan < best_makespan:
                best = candidate[:]
                best_makespan = cand_makespan
        elif cand_makespan < best_makespan:
            if random.random() < math.exp(-(cand_makespan - curr_makespan) / T):
                current = candidate
                best = candidate[:]
                best_makespan = cand_makespan
            else:
                current = candidate
        else:
            current = candidate

    return best

