def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)

    # Precompute job sums and slopes
    job_sums = [sum(job) for job in times]
    job_slopes = [sum((2 * m - M + 1) * times[i][m] for m in range(M)) for i in range(N)]

    # Makespan calculation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[-1]

    # NEH construction with Taillard acceleration
    def construct_neh(order):
        if not order:
            return []
        seq = [order[0]]
        e = [0] * M
        job0 = times[order[0]]
        e[0] = job0[0]
        for m in range(1, M):
            e[m] = e[m-1] + job0[m]
        for idx in range(1, len(order)):
            job_idx = order[idx]
            p = times[job_idx]
            k = len(seq)
            f = [0] * M
            best_pos = 0
            best_cmax = float('inf')
            for i in range(k + 1):
                if i == 0:
                    f[0] = p[0]
                else:
                    f[0] = e[i-1][0] + p[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + p[m]
                cmax_candidate = 0
                for m in range(M):
                    val = f[m] + (0 if i == k else 0)  # q[i][m] will be computed below
                    if val > cmax_candidate:
                        cmax_candidate = val
                # Compute q[i][m] on the fly for current i
                if i < k:
                    q = [0] * M
                    q[M-1] = times[seq[i]][M-1]
                    for m in range(M-2, -1, -1):
                        q[m] = max(q[m+1], q[m]) + times[seq[i]][m]
                    for m in range(M):
                        val = f[m] + q[m]
                        if val > cmax_candidate:
                            cmax_candidate = val
                else:
                    cmax_candidate = f[-1]
                if cmax_candidate < best_cmax:
                    best_cmax = cmax_candidate
                    best_pos = i
            # Insert job at best_pos
            seq.insert(best_pos, job_idx)
            # Update e matrix for new seq
            e = [0] * M
            job_first = times[seq[0]]
            e[0] = job_first[0]
            for m in range(1, M):
                e[m] = e[m-1] + job_first[m]
            for r in range(1, len(seq)):
                job_r = times[seq[r]]
                e[0] += job_r[0]
                for m in range(1, M):
                    e[m] = max(e[m], e[m-1]) + job_r[m]
        return seq

    # Try multiple orderings for initial solution
    orders = [
        sorted(range(N), key=lambda i: job_sums[i], reverse=True),
        sorted(range(N), key=lambda i: job_slopes[i], reverse=True),
        list(range(N))
    ]
    random.shuffle(orders)
    best_seq = None
    best_cmax = float('inf')
    for order in orders:
        seq = construct_neh(order)
        cmax = makespan(seq)
        if cmax < best_cmax:
            best_cmax = cmax
            best_seq = seq

    current_seq = best_seq[:]
    pi_star = best_seq[:]
    cmax_star = best_cmax

    # Iterated Greedy
    max_iter = 60
    d = 3 if N > 20 else 2
    for _ in range(max_iter):
        # Destruction
        if d >= N:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            remaining = [current_seq[i] for i in range(N) if i not in indices_set]
            destroyed = [current_seq[i] for i in indices]
        # Reconstruction
        seq = remaining[:]
        for job in destroyed:
            p = times[job]
            k = len(seq)
            if k == 0:
                seq.append(job)
                continue
            # Compute e for current seq
            e = [0] * M
            job0 = times[seq[0]]
            e[0] = job0[0]
            for m in range(1, M):
                e[m] = e[m-1] + job0[m]
            for r in range(1, k):
                job_r = times[seq[r]]
                e[0] += job_r[0]
                for m in range(1, M):
                    e[m] = max(e[m], e[m-1]) + job_r[m]
            # Evaluate insertions
            best_pos = 0
            best_cmax = float('inf')
            for i in range(k + 1):
                f = [0] * M
                if i == 0:
                    f[0] = p[0]
                else:
                    f[0] = e[i-1][0] + p[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + p[m]
                if i < k:
                    # Compute q[i][m]
                    q = [0] * M
                    q[M-1] = times[seq[i]][M-1]
                    for m in range(M-2, -1, -1):
                        q[m] = max(q[m+1], q[m]) + times[seq[i]][m]
                    cmax_candidate = 0
                    for m in range(M):
                        val = f[m] + q[m]
                        if val > cmax_candidate:
                            cmax_candidate = val
                else:
                    cmax_candidate = f[-1]
                if cmax_candidate < best_cmax:
                    best_cmax = cmax_candidate
                    best_pos = i
            seq.insert(best_pos, job)
        cmax_new = makespan(seq)
        if cmax_new < cmax_star:
            cmax_star = cmax_new
            pi_star = seq[:]
        if cmax_new < makespan(current_seq):
            current_seq = seq[:]
        else:
            if random.random() < math.exp(-(cmax_new - makespan(current_seq)) / T):
                current_seq = seq[:]
    return pi_star

