def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten times for faster access: flat[i * M + j] = times[i][j]
    flat = [0] * (N * M)
    for i in range(N):
        for j in range(M):
            flat[i * M + j] = times[i][j]

    # Precompute total processing times for NEH priority
    total = [0] * N
    for i in range(N):
        s = 0
        base = i * M
        for j in range(M):
            s += flat[base + j]
        total[i] = s

    # NEH with Taillard acceleration
    def makespan_from_perm(perm):
        if not perm:
            return 0
        # forward pass
        e = [0] * M
        first = perm[0]
        base = first * M
        e[0] = flat[base]
        for m in range(1, M):
            e[m] = e[m-1] + flat[base + m]
        for idx in range(1, len(perm)):
            job = perm[idx]
            base = job * M
            e[0] += flat[base]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + flat[base + m]
        return e[M-1]

    def taillard_insert(current, job):
        k = len(current)
        if k == 0:
            return [job]
        # forward matrix e: k x M
        e = [[0] * M for _ in range(k)]
        # backward matrix q: (k+1) x M
        q = [[0] * M for _ in range(k+1)]
        # compute e
        for r in range(k):
            job_r = current[r]
            base = job_r * M
            if r == 0:
                e[0][0] = flat[base]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + flat[base + m]
            else:
                e[r][0] = e[r-1][0] + flat[base]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + flat[base + m]
        # compute q
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = current[r]
            base = job_r * M
            q[r][M-1] = q[r+1][M-1] + flat[base + M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + flat[base + m]
        # evaluate insertion positions
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            # forward vector f for job at position i
            f = [0] * M
            if i == 0:
                f[0] = flat[job * M]
                for m in range(1, M):
                    f[m] = f[m-1] + flat[job * M + m]
            else:
                base_prev = (i-1) * M  # dummy, will be overridden
                # actually use e[i-1][m]
                f[0] = e[i-1][0] + flat[job * M]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + flat[job * M + m]
            # makespan = max_m (f[m] + q[i][m])
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return current[:best_pos] + [job] + current[best_pos:]

    # NEH construction
    order = sorted(range(N), key=lambda i: total[i], reverse=True)
    perm = [order[0], order[1]]
    # evaluate initial two
    mk1 = makespan_from_perm(perm)
    mk2 = makespan_from_perm([order[1], order[0]])
    if mk2 < mk1:
        perm = [order[1], order[0]]
    # insert remaining
    for idx in range(2, N):
        job = order[idx]
        perm = taillard_insert(perm, job)

    # Iterated Greedy
    def destruction_construction(current, d):
        if d >= len(current):
            return current[:]
        indices = random.sample(range(len(current)), d)
        removed = [current[i] for i in indices]
        remaining = [current[i] for i in range(len(current)) if i not in set(indices)]
        random.shuffle(removed)
        for job in removed:
            remaining = taillard_insert(remaining, job)
        return remaining

    # Parameters
    total_sum = sum(total)
    T_param = 0.5
    T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-6
    current = perm[:]
    best = perm[:]
    best_mk = makespan_from_perm(best)
    # Iterate until time budget ~40ms
    for _ in range(60):  # safe for <50ms
        new_perm = destruction_construction(current, 3 if N < 40 else 4)
        new_mk = makespan_from_perm(new_perm)
        if new_mk < best_mk:
            best_mk = new_mk
            best = new_perm[:]
            current = new_perm[:]
        elif new_mk < makespan_from_perm(current):
            current = new_perm[:]
        else:
            if random.random() < math.exp(-(new_mk - makespan_from_perm(current)) / T):
                current = new_perm[:]
    return best

