        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Compute Palmer's slope index weighted by inverse machine variance
    slope = [0] * N
    for j in range(M):
        col = [times[i][j] for i in range(N)]
        mean = sum(col) / N
        var = sum((x - mean) ** 2 for x in col) / N
        weight = 1.0 / (var + 1e-9)  # Avoid division by zero
        coeff = 2 * j - M + 1
        for i in range(N):
            slope[i] += coeff * col[i] * weight

    # Sort jobs by slope descending
    order = sorted(range(N), key=lambda i: slope[i], reverse=True)

