    proc = times

    # Helper: compute makespan of a sequence
    def makespan(seq):
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += proc[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + proc[job][m]
        return t[-1]

