            for r in range(k):
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + proc[seq[r]][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + proc[seq[r]][m]
            # Recompute backward matrix q for current seq
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + proc[seq[r]][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + proc[seq[r]][m]
            # Evaluate insertion positions
            best_pos = 0
            best_cmax = float('inf')
            for i in range(k+1):
                # Forward pass for job at position i
                f = [0] * M
