            e = [[0] * M for _ in range(k)]
            q = [[0] * M for _ in range(k + 1)]
            for r in range(k):
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + proc[destroyed[r]][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + proc[destroyed[r]][m]
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + proc[destroyed[r]][m]
