    job_data = [row[:] for row in times]
    total_processing = sum(sum(row) for row in job_data)
    LB = 0
    for m in range(M):
        min_before = min(job_data[i][m2] for i in range(N) for m2 in range(m)) if m > 0 else 0
        machine_sum = sum(job_data[i][m] for i in range(N))
        min_after = min(job_data[i][m2] for i in range(N) for m2 in range(m+1, M)) if m < M-1 else 0
        LB_m = min_before + machine_sum + min_after
        if LB_m > LB:
            LB = LB_m

    # Compute total processing time per job for NEH priority
    P = [sum(job) for job in job_data]
    order = sorted(range(N), key=lambda i: P[i], reverse=True)

    # Makespan calculation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += job_data[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_data[job][m]
        return t[-1]

    # Taillard-accelerated insertion makespan evaluation
    def evaluate_insertion(partial, job, pos):
        k = len(partial)
        if k == 0:
            return job_data[job][0] + (sum(job_data[job][1:]) if M > 1 else 0)
        # Forward matrix e for partial schedule
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + job_data[job_r][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + job_data[job_r][m]
        # Backward tail matrix q
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + job_data[job_r][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_data[job_r][m]
        # Forward vector f for job at position pos
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev = e[pos-1][m] if pos > 0 else 0
                f[m] = prev + job_data[job][m]
            else:
                prev_f = f[m-1]
                prev_e = e[pos-1][m] if pos > 0 else 0
                f[m] = max(prev_f, prev_e) + job_data[job][m]
        # Makespan candidate
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    perm = [order[0]]
    for idx in range(1, N):
        job = order[idx]
        best_pos = 0
        best_makespan = float('inf')
        for pos in range(len(perm)+1):
            # Quick lower-bound pruning: estimate makespan if job inserted at pos
            # Using machine-wise lower bound contribution
            est = 0
            for m in range(M):
                before = sum(job_data[perm[i]][m] for i in range(pos)) if pos > 0 else 0
                after = sum(job_data[perm[i]][m] for i in range(pos, len(perm))) if pos < len(perm) else 0
                est_m = before + job_data[job][m] + after
                if est_m > est:
                    est = est_m
            if est >= best_makespan:
                continue
            ms = evaluate_insertion(perm, job, pos)
            if ms < best_makespan:
                best_makespan = ms
                best_pos = pos
