        return best_perm

    # IG parameters
    d = 3 if N > 5 else max(1, N//2)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del current[idx]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(current)+1):
                # Quick lower-bound pruning
                est = 0
                for m in range(M):
                    before = sum(job_data[current[i]][m] for i in range(pos)) if pos > 0 else 0
                    after = sum(job_data[current[i]][m] for i in range(pos, len(current))) if pos < len(current) else 0
                    est_m = before + job_data[job][m] + after
                    if est_m > est:
                        est = est_m
                if est >= best_makespan:
                    continue
                ms = evaluate_insertion(current, job, pos)
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            current.insert(best_pos, job)
        # Acceptance
        curr_ms = makespan(current)
        if curr_ms < best_ms:
            best_perm = current[:]
            best_ms = curr_ms
            no_improve = 0
            if best_ms == LB:
                break
        elif curr_ms < makespan(perm):
            perm = current[:]
            no_improve = 0
        else:
            if random.random() < math.exp(-(curr_ms - makespan(perm)) / T):
                perm = current[:]
            no_improve += 1
        if no_improve >= no_improve_limit:
            break

    return best_perm

