    def makespan(perm):
        if not perm:
            return 0
        e = [0] * M
        for job in perm:
            p = job_data[job]
            e[0] += p[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + p[m]
        return e[-1]

    # CDS: generate M-1 two-machine subproblems via Johnson's rule
    best_perm = None
    best_cmax = float('inf')
    for l in range(1, M):
        # Artificial two-machine processing times
        p1 = [sum(job[:l]) for job in job_data]
        p2 = [sum(job[M-l:]) for job in job_data]
        # Johnson's rule: split into left (p1 <= p2) and right (p1 > p2)
        left = []
        right = []
        for i in range(N):
            if p1[i] <= p2[i]:
                left.append(i)
            else:
                right.append(i)
        # Sort left by p1 ascending, right by p2 descending
        left.sort(key=lambda i: p1[i])
        right.sort(key=lambda i: p2[i], reverse=True)
        perm = left + right
        cmax = makespan(perm)
        if cmax < best_cmax:
            best_cmax = cmax
            best_perm = perm

    return best_perm if best_perm is not None else list(range(N))

