                    cmax_i = val
            if cmax_i < best_cmax:
                best_cmax = cmax_i
                best_pos = i
        return current_seq[:best_pos] + [job_x] + current_seq[best_pos:]

    def neh_construct():
        job_sums = [sum(job) for job in times]
        jobs_sorted = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
        if N == 0:
            return []
        seq = [jobs_sorted[0]]
        if N == 1:
            return seq
        seq1 = [jobs_sorted[0], jobs_sorted[1]]
        seq2 = [jobs_sorted[1], jobs_sorted[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for k in range(2, N):
            e_mat = compute_e_matrix(seq, k)
            q_mat = compute_q_matrix(seq, k)
            seq = insert_job_taillard(seq, jobs_sorted[k], e_mat, q_mat)
        return seq

    current_seq = neh_construct()
    best_seq = current_seq[:]
    best_cmax = makespan(best_seq)

    if best_cmax == 0:
        return best_seq

    T = T0
    max_iter = 60
    for _ in range(max_iter):
        if len(current_seq) <= destroy_size:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(len(current_seq)), destroy_size)
            indices_set = set(indices)
            destroyed = [current_seq[i] for i in indices]
            remaining = [current_seq[i] for i in range(len(current_seq)) if i not in indices_set]

        e_mat = compute_e_matrix(remaining, len(remaining))
        q_mat = compute_q_matrix(remaining, len(remaining))

        random.shuffle(destroyed)
        for job in destroyed:
            remaining = insert_job_taillard(remaining, job, e_mat, q_mat)
            e_mat = compute_e_matrix(remaining, len(remaining))
            q_mat = compute_q_matrix(remaining, len(remaining))

        new_cmax = makespan(remaining)
        if new_cmax < best_cmax:
            best_cmax = new_cmax
            best_seq = remaining[:]

        if new_cmax < makespan(current_seq):
            current_seq = remaining[:]
        else:
            delta = new_cmax - makespan(current_seq)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current_seq = remaining[:]

        T *= 0.95

    return best_seq

