def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9

    P = [sum(job) for job in times]
    S = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    def makespan_taillard(seq, e=None, q=None):
        if not seq:
            return 0
        k = len(seq)
        if e is None:
            e = [[0] * M for _ in range(k)]
        if q is None:
            q = [[0] * M for _ in range(k+1)]
        for r in range(k):
            job = seq[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job][m]
        for r in range(k-1, -1, -1):
            job = seq[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        makespan_val = 0
        for m in range(M):
            makespan_val = max(makespan_val, e[k-1][m] + q[k][m])
        return makespan_val

    def insertion_cost_taillard(partial, job, pos, e, q):
        k = len(partial)
        if pos == 0:
            f0 = times[job][0]
        else:
            f0 = e[pos-1][0] + times[job][0]
        f = [0] * M
        f[0] = f0
        for m in range(1, M):
            f[m] = max(f[m-1], e[pos-1][m] if pos > 0 else 0) + times[job][m]
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
        return best

    def neh_construct(priority):
        if not priority:
            return []
        seq = [priority[0]]
        if len(priority) > 1:
            seq1 = [priority[0], priority[1]]
            seq2 = [priority[1], priority[0]]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        e = [[0] * M for _ in range(len(seq))]
        q = [[0] * M for _ in range(len(seq)+1)]
        for idx in range(2, len(priority)):
            job = priority[idx]
            best_pos = 0
            best_cost = float('inf')
            for pos in range(len(seq)+1):
                cost = insertion_cost_taillard(seq, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            seq.insert(best_pos, job)
            e = [[0] * M for _ in range(len(seq))]
            q = [[0] * M for _ in range(len(seq)+1)]
        return seq

    def destroy_and_reconstruct(seq, d):
        if d <= 0 or d >= len(seq):
            return seq[:]
        indices = random.sample(range(len(seq)), d)
        extracted = [seq[i] for i in indices]
        remaining = [seq[i] for i in range(len(seq)) if i not in set(indices)]
        random.shuffle(extracted)
        e = [[0] * M for _ in range(len(remaining))]
        q = [[0] * M for _ in range(len(remaining)+1)]
        for job in extracted:
            best_pos = 0
            best_cost = float('inf')
            for pos in range(len(remaining)+1):
                cost = insertion_cost_taillard(remaining, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            remaining.insert(best_pos, job)
            e = [[0] * M for _ in range(len(remaining))]
            q = [[0] * M for _ in range(len(remaining)+1)]
        return remaining

    best_seq = neh_construct(sorted(range(N), key=lambda i: (-P[i], -S[i])))
    best_makespan = makespan(best_seq)
    current_seq = best_seq[:]

    LB = 0
    for m in range(M):
        min_pre = min((sum(times[i][:m]) for i in range(N)), default=0)
        min_suf = min((sum(times[i][m+1:]) for i in range(N)), default=0)
        machine_load = sum(times[i][m] for i in range(N))
        LB = max(LB, min_pre + machine_load + min_suf)
    if best_makespan == LB:
        return best_seq

    max_iters = 60
    for _ in range(max_iters):
        d = 3 if random.random() < 0.7 else 4
        new_seq = destroy_and_reconstruct(current_seq, d)
        new_makespan = makespan(new_seq)
        if new_makespan < best_makespan:
            best_makespan = new_makespan
            best_seq = new_seq[:]
            current_seq = new_seq[:]
        if new_makespan < makespan(current_seq):
            current_seq = new_seq[:]
        else:
            delta = new_makespan - makespan(current_seq)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current_seq = new_seq[:]
        if best_makespan == LB:
            break

    return best_seq

