def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    P = [0] * N
    for i in range(N):
        s = 0
        row = times[i]
        for j in range(M):
            s += row[j]
        P[i] = s
        total_processing += s

    order = list(range(N))
    order.sort(key=lambda i: P[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for idx in perm:
            job = times[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def makespan_with_insertion(base_perm, job_idx, pos):
        if not base_perm:
            return times[job_idx][0] if M == 1 else _makespan_single_job(times[job_idx])
        k = len(base_perm)
        e = [[0] * M for _ in range(k)]
        r = 0
        for idx in base_perm:
            job = times[idx]
            if r == 0:
                e[r][0] = job[0]
                for m in range(1, M):
                    e[r][m] = e[r][m-1] + job[m]
            else:
                e[r][0] = e[r-1][0] + job[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job[m]
            r += 1
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            idx = base_perm[r]
            job = times[idx]
            q[r][M-1] = q[r+1][M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job[m]
        f = [0] * M
        if pos == 0:
            for m in range(M):
                if m == 0:
                    f[m] = times[job_idx][m]
                else:
                    f[m] = f[m-1] + times[job_idx][m]
        else:
            prev_e = e[pos-1]
            job = times[job_idx]
            f[0] = prev_e[0] + job[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev_e[m]) + job[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def _makespan_single_job(job):
        t = 0
        for m in range(M):
            t += job[m]
        return t

    current = []
    for idx in order:
        best_pos = 0
        best_makespan = float('inf')
        for pos in range(len(current) + 1):
            m = makespan_with_insertion(current, idx, pos)
            if m < best_makespan:
                best_makespan = m
                best_pos = pos
        current.insert(best_pos, idx)

    pi_star = current[:]
    pi = current[:]
    best_makespan_val = makespan(pi_star)

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 60

    for _ in range(max_iter):
        if len(pi) <= d:
            R = pi[:]
            pi_D = []
        else:
            indices = random.sample(range(len(pi)), d)
            indices.sort(reverse=True)
            R = [pi.pop(i) for i in indices]
            pi_D = pi
        for job_idx in R:
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(pi_D) + 1):
                m = makespan_with_insertion(pi_D, job_idx, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            pi_D.insert(best_pos, job_idx)
        pi_new = pi_D
        m_new = makespan(pi_new)
        if m_new < makespan(pi):
            pi = pi_new
        if m_new < best_makespan_val:
            pi_star = pi_new[:]
            best_makespan_val = m_new
        else:
            if T > 1e-10:
                delta = m_new - makespan(pi)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    pi = pi_new
    return pi_star

