def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = [sum(job) for job in times]
    p0 = [job[0] for job in times]
    max_p0 = max(p0) if p0 else 0
    penalty_weight = 0.3 if max_p0 > 0 else 0.0
    adjusted_priority = [total_processing[i] - penalty_weight * p0[i] for i in range(N)]
    order = sorted(range(N), key=lambda i: adjusted_priority[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + times[job][m]
        return t[-1]

    def makespan_taillard(perm):
        if not perm:
            return 0
        e = [0] * M
        for job in perm:
            e[0] += times[job][0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + times[job][m]
        return e[-1]

    def makespan_insert(perm, job, pos):
        k = len(perm)
        e = [0] * M
        if pos > 0:
            for idx in range(pos):
                j = perm[idx]
                e[0] += times[j][0]
                for m in range(1, M):
                    e[m] = max(e[m-1], e[m]) + times[j][m]
        f = [0] * M
        f[0] = (e[0] if pos > 0 else 0) + times[job][0]
        for m in range(1, M):
            f[m] = max(f[m-1], (e[m] if pos > 0 else 0)) + times[job][m]
        q = [0] * M
        for idx in range(k-1, pos-1, -1):
            j = perm[idx]
            q[M-1] += times[j][M-1]
            for m in range(M-2, -1, -1):
                q[m] = max(q[m], q[m+1]) + times[j][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    current = [order[0]]
    if N > 1:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            current = seq1
        else:
            current = seq2
    for k in range(2, N):
        job = order[k]
        best_pos = 0
        best_makespan = makespan_insert(current, job, 0)
        for pos in range(1, k+1):
            m = makespan_insert(current, job, pos)
            if m < best_makespan:
                best_makespan = m
                best_pos = pos
        current.insert(best_pos, job)

    best_perm = current[:]
    best_makespan = makespan_taillard(current)
    total = sum(total_processing)
    T_param = 0.5
    T = T_param * total / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N > 5 else 2
    max_iter = 60
    if N * M > 2000:
        max_iter = 40
    elif N * M < 400:
        max_iter = 80

    for _ in range(max_iter):
        indices = list(range(N))
        random.shuffle(indices)
        removed = []
        remaining = current[:]
        for idx in indices[:d]:
            job = remaining.pop(indices.index(idx) if idx in remaining else remaining.index(idx) if idx in remaining else 0)
            removed.append(job)
        for job in removed:
            best_pos = 0
            best_makespan = makespan_insert(remaining, job, 0)
            for pos in range(1, len(remaining)+1):
                m = makespan_insert(remaining, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            remaining.insert(best_pos, job)
        new_makespan = makespan_taillard(remaining)
        if new_makespan < makespan_taillard(current):
            current = remaining[:]
            if new_makespan < best_makespan:
                best_makespan = new_makespan
                best_perm = current[:]
        elif new_makespan < best_makespan or random.random() < math.exp(-(new_makespan - makespan_taillard(current)) / T):
            current = remaining[:]
    return best_perm

