def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job data for fast access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]

    # Makespan calculation
    def makespan(seq):
        t = [0] * M
        for job in seq:
            job_p = p[job]
            t[0] += job_p[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_p[m]
        return t[-1]

    # Taillard acceleration: forward matrix
    def compute_forward(seq):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = seq[r]
            job_p = p[job]
            if r == 0:
                e[0][0] = job_p[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_p[m]
            else:
                e[r][0] = e[r-1][0] + job_p[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_p[m]
        return e

    # Taillard acceleration: backward matrix
    def compute_backward(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            job_p = p[job]
            q[r][M-1] = q[r+1][M-1] + job_p[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_p[m]
        return q

    # Evaluate insertion makespan for job x at position i in partial seq of length k
    def insertion_cost(seq, x, i, e, q):
        k = len(seq)
        f = [0] * M
        # Compute forward vector for job x up to insertion point
        if i == 0:
            f[0] = p[x][0]
            for m in range(1, M):
                f[m] = f[m-1] + p[x][m]
        else:
            f[0] = e[i-1][0] + p[x][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + p[x][m]
        # Combine with backward tail
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    # NEH with Taillard acceleration
    def neh_construct():
        jobs = list(range(N))
        jobs.sort(key=lambda i: total_p[i], reverse=True)
        if N <= 1:
            return jobs[:]
        # Start with first two jobs
        seq = [jobs[0], jobs[1]]
        if makespan([jobs[1], jobs[0]]) < makespan(seq):
            seq = [jobs[1], jobs[0]]
        # Insert remaining jobs
        for idx in range(2, N):
            job = jobs[idx]
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_cost = float('inf')
            for pos in range(len(seq) + 1):
                cost = insertion_cost(seq, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size 3
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_cost = makespan(best)
        total_processing = sum(total_p)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

        for _ in range(max_iter):
            # Destruction: remove 3 random jobs
            if N <= 3:
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(N), 3)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(N) if i not in indices_set]

            # Reconstruct using NEH insertion on remaining sequence
            if not remaining:
                new_seq = destroyed[:]
                random.shuffle(new_seq)
            else:
                e = compute_forward(remaining)
                q = compute_backward(remaining)
                seq = remaining[:]
                for job in destroyed:
                    best_pos = 0
                    best_cost_ins = float('inf')
                    for pos in range(len(seq) + 1):
                        cost = insertion_cost(seq, job, pos, e, q)
                        if cost < best_cost_ins:
                            best_cost_ins = cost
                            best_pos = pos
                    seq.insert(best_pos, job)
                new_seq = seq

            new_cost = makespan(new_seq)
            # Acceptance criterion
            if new_cost < makespan(current) or random.random() < math.exp(-(new_cost - makespan(current)) / T):
                current = new_seq[:]
                if new_cost < best_cost:
                    best = new_seq[:]
                    best_cost = new_cost
        return best

    # Build initial solution and refine
    init_seq = neh_construct()
    return iterated_greedy(init_seq, max_iter=50)

