    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data and total processing times
    job_data = times
    total_p = [sum(job) for job in job_data]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            pj = job_data[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + pj[m]
        return t[-1]

    # Taillard accelerated insertion evaluation for a single job
    def evaluate_insertion(current_seq, job, e, q):
        k = len(current_seq)
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k + 1):
            # Compute forward vector f for inserting job at position i
            if i == 0:
                f0 = job[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[-1], 0) + job[m])
            else:
                f0 = e[i-1][0] + job[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[-1], e[i-1][m]) + job[m])
            # Compute makespan: max over m of f[m] + q[i][m]
            ms = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > ms:
                    ms = val
            if ms < best_makespan:
                best_makespan = ms
                best_pos = i
        return best_pos, best_makespan

    # Construct initial solution using NEH with Taillard acceleration
    def construct_initial():
        # Sort jobs by total processing time descending
        order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N < 2:
            return order[:]
        # Start with first two jobs
        seq = [order[0], order[1]]
        ms1 = makespan(seq)
        seq2 = [order[1], order[0]]
        ms2 = makespan(seq2)
        if ms2 < ms1:
            seq = seq2
