            for r in range(k):
                job_r = job_data[seq[r]]
                if r == 0:
                    e[0][0] = job_r[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_r[m]
                else:
                    e[r][0] = e[r-1][0] + job_r[0]
                    for m in range(1, M):
