            for r in range(k-1, -1, -1):
                job_r = job_data[seq[r]]
                q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
        return seq

    # Iterated Greedy with destruction size 2 and block insertion of 2 jobs
    def iterated_greedy(initial_seq, max_iter=50):
        current = initial_seq[:]
        best = current[:]
        best_ms = makespan(best)
        total = sum(total_p)
        T_param = 0.5
        T = T_param * total / (10 * N * M) if N * M > 0 else 1e-6
        d = 2  # destruction size: remove 2 jobs
        for _ in range(max_iter):
            # Destruction: remove d jobs at random positions
            if N <= d:
                destroyed = []
                remaining = []
            else:
                positions = random.sample(range(N), d)
                positions.sort(reverse=True)
                destroyed = []
                remaining = current[:]
                for pos in positions:
                    destroyed.append(remaining.pop(pos))
            # Reconstruction: insert the two jobs as a block in best position
            if not destroyed:
                new_seq = current[:]
            else:
                # Evaluate all possible insertion positions for the block
                best_block_pos = 0
                best_block_ms = float('inf')
                block_seq = destroyed  # keep the order as destroyed (random)
                for pos in range(len(current) - d + 1):
                    # Build temporary sequence with block inserted at pos
                    temp = current[:pos] + block_seq + current[pos+d:]
                    ms = makespan(temp)
                    if ms < best_block_ms:
                        best_block_ms = ms
                        best_block_pos = pos
                new_seq = current[:best_block_pos] + block_seq + current[best_block_pos+d:]
            # Acceptance criterion
            new_ms = makespan(new_seq)
            if new_ms < best_ms:
                best = new_seq[:]
                best_ms = new_ms
                if new_ms < makespan(current):
                    current = new_seq
                else:
                    # Metropolis acceptance
                    if random.random() < math.exp(-(new_ms - makespan(current)) / T):
                        current = new_seq
            elif new_ms < makespan(current):
                current = new_seq
            else:
                if random.random() < math.exp(-(new_ms - makespan(current)) / T):
                    current = new_seq
        return best

    # Build initial solution
    init_seq = construct_initial()
    # Apply iterated greedy refinement
    final_seq = iterated_greedy(init_seq, max_iter=40)
    return final_seq

