    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flatten times for fast access
    flat_times = [times[i][j] for i in range(N) for j in range(M)]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            base = job * M
            t[0] += flat_times[base]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + flat_times[base + m]
        return t[-1]

    def makespan_with_tail(seq, e, q, pos, job):
        base = job * M
        f = [0] * M
        if pos == 0:
            f[0] = flat_times[base]
            for m in range(1, M):
                f[m] = max(f[m-1], 0) + flat_times[base + m]
        else:
            f[0] = e[pos-1][0] + flat_times[base]
            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + flat_times[base + m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Beam search with width K=2
    K = 2
    # Initial job order: sort by total processing time descending
    total_times = [sum(times[i]) for i in range(N)]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Start with first job
    beams = [[order[0]]]

    for idx in range(1, N):
        job = order[idx]
        new_beams = []
        for seq in beams:
            k = len(seq)
            # Precompute forward matrix e for current seq
            e = [[0]*M for _ in range(k)]
            for r in range(k):
                job_r = seq[r]
                base_r = job_r * M
                if r == 0:
                    e[0][0] = flat_times[base_r]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + flat_times[base_r + m]
                else:
                    e[r][0] = e[r-1][0] + flat_times[base_r]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + flat_times[base_r + m]
            # Precompute backward tail matrix q
            q = [[0]*M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                base_r = job_r * M
                q[r][M-1] = q[r+1][M-1] + flat_times[base_r + M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + flat_times[base_r + m]
            # Evaluate all insertion positions
            for pos in range(k+1):
                makespan_val = makespan_with_tail(seq, e, q, pos, job)
                new_seq = seq[:pos] + [job] + seq[pos:]
                new_beams.append((makespan_val, new_seq))
        # Prune to top K beams
        new_beams.sort(key=lambda x: x[0])
        beams = [seq for _, seq in new_beams[:K]]

    # Return the best beam
    best_seq = beams[0]
    best_makespan = makespan(best_seq)
    for seq in beams[1:]:
        m = makespan(seq)
        if m < best_makespan:
            best_makespan = m
            best_seq = seq
    return best_seq

