def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for fast access
    p = [row[:] for row in times]

    # Compute total processing times for NEH priority
    total = [sum(job) for job in p]
    order = sorted(range(N), key=lambda i: total[i], reverse=True)

    # Makespan evaluation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            job_p = p[job]
            t[0] += job_p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_p[m]
        return t[-1]

    # Taillard's accelerated insertion evaluation
    def evaluate_insertion(partial, job_idx, k):
        if k == 0:
            f = [p[job_idx][m] for m in range(M)]
            q = [0] * M
            for m in range(M-2, -1, -1):
                q[m] = max(q[m+1], q[m]) + p[partial[m]][m] if partial else 0
            return max(f[m] + q[m] for m in range(M))

        # Forward matrix e for partial schedule
        e = [[0]*M for _ in range(k)]
        job0 = partial[0]
        e[0][0] = p[job0][0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + p[job0][m]
        for r in range(1, k):
            job_r = partial[r]
            e[r][0] = e[r-1][0] + p[job_r][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]

        # Backward tail matrix q
        q = [[0]*M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]

        best = float('inf')
        for i in range(k+1):
            # Compute forward vector f for insertion at position i
            if i == 0:
                f0 = p[job_idx][0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], 0) + p[job_idx][m])
            else:
                f = [0]*M
                f[0] = e[i-1][0] + p[job_idx][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + p[job_idx][m]

            # Compute makespan candidate
            cand = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cand:
                    cand = val
            if cand < best:
                best = cand
        return best

    # Construct initial solution using NEH with Taillard acceleration
    def construct_neh():
        if N < 2:
            return order[:]
        # Initial pair
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        if makespan(seq0) <= makespan(seq1):
            perm = seq0[:]
        else:
            perm = seq1[:]
        # Insert remaining jobs
        for k in range(2, N):
            job_idx = order[k]
            best_pos = 0
            best_val = float('inf')
            for i in range(k+1):
                val = evaluate_insertion(perm, job_idx, k)
                if val < best_val:
                    best_val = val
                    best_pos = i
            perm.insert(best_pos, job_idx)
        return perm

    # Iterated Greedy refinement
    def iterated_greedy(init_perm, max_iter=60):
        current = init_perm[:]
        best = current[:]
        best_makespan = makespan(best)
        total_processing = sum(total)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        d = 3 if N > 20 else 2

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build destroyed sequence keeping original order
            destroyed = [current[i] for i in range(N) if i not in indices]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                k = len(destroyed)
                best_pos = 0
                best_val = float('inf')
                for i in range(k+1):
                    val = evaluate_insertion(destroyed, job, k)
                    if val < best_val:
                        best_val = val
                        best_pos = i
                destroyed.insert(best_pos, job)
            current = destroyed
            curr_makespan = makespan(current)
            # Acceptance criterion
            if curr_makespan < makespan(best):
                best = current[:]
                best_makespan = curr_makespan
            if curr_makespan < makespan(init_perm):
                current = current[:]
            else:
                delta = curr_makespan - makespan(init_perm)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    init_perm = current[:]
        return best

    # Build initial solution and refine
    init_perm = construct_neh()
    # Quick lower bound check (optional, can skip for speed)
    # Refine with Iterated Greedy
    return iterated_greedy(init_perm, max_iter=50)

