    priority_orders = [
        list(range(N)),  # original
        sorted(range(N), key=lambda i: total_times[i], reverse=True),  # NEH
        sorted(range(N), key=lambda i: slope_index[i], reverse=True)   # Palmer
    ]
    priority_orders = [list(dict.fromkeys(order)) for order in priority_orders]  # deduplicate

    best_sequence = None
    best_makespan = float('inf')

    # Makespan calculation function
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[-1]

    # Taillard's accelerated insertion evaluation
    def evaluate_insertion(partial, job, k):
        if k == 0:
            f = [0] * M
            for m in range(M):
                if m == 0:
                    f[0] = times[job][0]
                else:
                    f[m] = max(f[m-1], 0) + times[job][m]
            q = [0] * M
            for r in range(k-1, -1, -1):
                job_r = partial[r]
                job_r_time = times[job_r]
                if m := M-1:
                    q[m] = q[m] + job_r_time[m]
                for m in range(M-2, -1, -1):
                    q[m] = max(q[m], q[m+1]) + job_r_time[m]
            return max(f[m] + q[m] for m in range(M))

        # Forward matrix e[0..k-1][0..M-1]
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            job_r_time = times[job_r]
            if r == 0:
                e[0][0] = job_r_time[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_r_time[m]
            else:
                e[r][0] = e[r-1][0] + job_r_time[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r_time[m]

        # Backward matrix q[0..k][0..M-1]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            job_r_time = times[job_r]
            q[r][M-1] = q[r+1][M-1] + job_r_time[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r_time[m]

        best_pos = 0
        best_val = float('inf')
        for i in range(k+1):
            # forward vector f for insertion at i
            f = [0]*M
            if i == 0:
                prev = [0]*M
            else:
                prev = e[i-1]
            for m in range(M):
                if m == 0:
                    f[0] = prev[0] + times[job][0]
                else:
                    f[m] = max(f[m-1], prev[m]) + times[job][m]
            makespan_val = max(f[m] + q[i][m] for m in range(M))
            if makespan_val < best_val:
                best_val = makespan_val
                best_pos = i
        return best_pos, best_val

    # NEH construction with Taillard acceleration
    def neh_construction(priority):
        if not priority:
            return []
        seq = [priority[0]]
        for idx in range(1, len(priority)):
            job = priority[idx]
            pos, _ = evaluate_insertion(seq, job, len(seq))
            seq.insert(pos, job)
        return seq

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_seq, max_iters=50):
        nonlocal best_sequence, best_makespan
        current_seq = initial_seq[:]
        current_makespan = makespan(current_seq)
        if current_makespan < best_makespan:
            best_makespan = current_makespan
            best_sequence = current_seq[:]

