        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        if T < 1e-6:
            T = 1e-6

        for _ in range(max_iters):
            # Destruction: remove d jobs
            d = 3 if N > 20 else 2
            if d > N:
                d = N
            indices = random.sample(range(N), d)
            removed = [current_seq[i] for i in indices]
            # Build destruction sequence
            remaining = [job for idx, job in enumerate(current_seq) if idx not in indices]

            # Reconstruction: reinsert removed jobs one by one
            for job in removed:
                pos, _ = evaluate_insertion(remaining, job, len(remaining))
                remaining.insert(pos, job)

            new_seq = remaining
            new_makespan = makespan(new_seq)

            # Acceptance criterion
            if new_makespan < current_makespan or random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current_seq = new_seq
                current_makespan = new_makespan
                if current_makespan < best_makespan:
                    best_makespan = current_makespan
                    best_sequence = current_seq[:]

        return best_sequence

    # Try each priority order
    for priority in priority_orders:
        init_seq = neh_construction(priority)
        iterated_greedy(init_seq, max_iters=40)
        if best_makespan == 0:
            break

    return best_sequence if best_sequence is not None else list(range(N))

