        for _ in range(max_iters):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build partial sequence without removed indices
            partial = [current[i] for i in range(N) if i not in indices]
            # Reconstruct by reinserting removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                job_t = times[job]
                # Build forward and backward for current partial
                k = len(partial)
                forward = [[0]*M for _ in range(k)]
                backward = [[0]*M for _ in range(k+1)]
                if k > 0:
                    # Forward
                    for r in range(k):
                        if r == 0:
                            forward[r][0] = times[partial[r]][0]
                            for m in range(1, M):
                                forward[r][m] = max(forward[r-1][m] if r>0 else 0, forward[r][m-1]) + times[partial[r]][m]
                        else:
                            forward[r][0] = forward[r-1][0] + times[partial[r]][0]
                            for m in range(1, M):
                                forward[r][m] = max(forward[r-1][m], forward[r][m-1]) + times[partial[r]][m]
                    # Backward
                    for m in range(M):
                        backward[k][m] = 0
                    for r in range(k-1, -1, -1):
                        job_r = times[partial[r]]
                        backward[r][M-1] = backward[r+1][M-1] + job_r[M-1]
                        for m in range(M-2, -1, -1):
                            backward[r][m] = max(backward[r+1][m], backward[r][m+1]) + job_r[m]
                # Evaluate insertion positions for job
                best_pos = 0
                best_mk_ins = float('inf')
                for i in range(k + 1):
                    # Compute forward vector f for job at position i
                    f = [0] * M
                    if i == 0:
                        f[0] = job_t[0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], 0) + job_t[m]
                    else:
                        f[0] = forward[i-1][0] + job_t[0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], forward[i-1][m]) + job_t[m]
                    # Compute makespan if inserted at i
                    mk_ins = 0
                    for m in range(M):
                        val = f[m] + backward[i][m]
                        if val > mk_ins:
                            mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                partial.insert(best_pos, job)
            new_seq = partial
            new_mk = makespan(new_seq)
            # Acceptance criterion
            if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
                current = new_seq
                current_mk = new_mk
                if new_mk < best_mk:
                    best = new_seq[:]
                    best_mk = new_mk
        return best

    improved_seq = ig_improve(best_seq)
    return improved_seq

