import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_times[m]
        return t[-1]

    def johnson_rule(p1, p2):
        n = len(p1)
        left, right = 0, n - 1
        seq = [0] * n
        jobs = list(range(n))
        while jobs:
            best_idx = -1
            best_val = float('inf')
            for idx in jobs:
                if p1[idx] < best_val:
                    best_val = p1[idx]
                    best_idx = idx
                if p2[idx] < best_val:
                    best_val = p2[idx]
                    best_idx = idx
            if p1[best_idx] <= p2[best_idx]:
                seq[left] = best_idx
                left += 1
            else:
                seq[right] = best_idx
                right -= 1
            jobs.remove(best_idx)
        return seq

    def cds_variant():
        best_seq = None
        best_mk = float('inf')
        for l in range(1, M):
            p1 = [sum(times[i][:l]) for i in range(N)]
            p2 = [sum(times[i][M-l:]) for i in range(N)]
            seq_idx = johnson_rule(p1, p2)
            seq = [seq_idx[i] for i in range(N)]
            mk = makespan(seq)
            if mk < best_mk:
                best_mk = mk
                best_seq = seq
        return best_seq

    def neh_construct():
        job_sums = [sum(times[i]) for i in range(N)]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_mk = float('inf')
            for pos in range(k + 1):
                new_seq = seq[:pos] + [job] + seq[pos:]
                mk = makespan(new_seq)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq = seq[:best_pos] + [job] + seq[best_pos:]
        return seq

    def taillard_forward_backward(partial):
        k = len(partial)
        if k == 0:
            return [[0]*M for _ in range(k+1)], [[0]*M for _ in range(k+1)]
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            job_t = times[job]
            if r == 0:
                e[0][0] = job_t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_t[m]
            else:
                e[r][0] = e[r-1][0] + job_t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            job_t = times[job]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        return e, q

    def taillard_insert(seq, job):
        k = len(seq)
        if k == 0:
            return [job]
        e, q = taillard_forward_backward(seq)
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            f = [0]*M
            if i == 0:
                prev_e = [0]*M
            else:
                prev_e = e[i-1]
            job_t = times[job]
            f[0] = prev_e[0] + job_t[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev_e[m]) + job_t[m]
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return seq[:best_pos] + [job] + seq[best_pos:]

    def iterated_greedy(initial_seq, max_iters=50):
        current = initial_seq[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing = sum(sum(row) for row in times)
        T = 0.5 * total_processing / (10 * N * M) if N * M > 0 else 1e-9
        d = 3 if N >= 3 else N
        for _ in range(max_iters):
            if len(current) <= d:
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(len(current)), d)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(len(current)) if i not in indices]
            for job in destroyed:
                remaining = taillard_insert(remaining, job)
            if makespan(remaining) < makespan(current):
                current = remaining[:]
                if makespan(current) < best_mk:
                    best = current[:]
                    best_mk = makespan(best)
            else:
                if makespan(remaining) < best_mk:
                    best = remaining[:]
                    best_mk = makespan(best)
                diff = makespan(remaining) - makespan(current)
                if diff < 0 or random.random() < math.exp(-diff / T):
                    current = remaining[:]
        return best

    cds_seq = cds_variant()
    neh_seq = neh_construct()
    ig_cds = iterated_greedy(cds_seq, max_iters=30)
    ig_neh = iterated_greedy(neh_seq, max_iters=30)
    cds_mk = makespan(cds_seq)
    neh_mk = makespan(neh_seq)
    ig_cds_mk = makespan(ig_cds)
    ig_neh_mk = makespan(ig_neh)
    best_seq = cds_seq
    best_mk = cds_mk
    if neh_mk < best_mk:
        best_mk = neh_mk
        best_seq = neh_seq
    if ig_cds_mk < best_mk:
        best_mk = ig_cds_mk
        best_seq = ig_cds
    if ig_neh_mk < best_mk:
        best_mk = ig_neh_mk
        best_seq = ig_neh
    return best_seq

