def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10.0 * N * M) if N * M > 0 else 1.0

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    def compute_tail_matrix(seq):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = seq[r]
            job_t = times[job]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        return q

    def compute_forward_matrix(seq):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = times[seq[0]][m] if m == 0 else (e[0][m-1] + times[seq[0]][m])
        for r in range(1, k):
            job = seq[r]
            job_t = times[job]
            e[r][0] = e[r-1][0] + job_t[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
        return e

    def neh_insertion(partial_seq, job):
        k = len(partial_seq)
        if k == 0:
            return [job]
        e = compute_forward_matrix(partial_seq)
        q = compute_tail_matrix(partial_seq)
        best_pos = 0
        best_makespan = float('inf')
        job_t = times[job]
        for i in range(k+1):
            f = [0] * M
            if i == 0:
                f[0] = job_t[0]
                for m in range(1, M):
                    f[m] = f[m-1] + job_t[m]
            else:
                f[0] = e[i-1][0] + job_t[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + job_t[m]
            makespan_val = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_val:
                    makespan_val = val
            if makespan_val < best_makespan:
                best_makespan = makespan_val
                best_pos = i
        return partial_seq[:best_pos] + [job] + partial_seq[best_pos:]

    # Initial solution via NEH
    job_sums = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: (-job_sums[i], i))
    current = []
    for job in order:
        current = neh_insertion(current, job)
    best = current[:]
    best_makespan = makespan(best)

    # Iterated Greedy
    max_iter = 60
    d = 3
    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(len(current)), d)
            indices_set = set(indices)
            destroyed = [current[i] for i in indices]
            remaining = [current[i] for i in range(len(current)) if i not in indices_set]
        random.shuffle(destroyed)
        for job in destroyed:
            remaining = neh_insertion(remaining, job)
        new_seq = remaining
        new_makespan = makespan(new_seq)
        if new_makespan < makespan(current):
            current = new_seq
            if new_makespan < best_makespan:
                best = new_seq[:]
                best_makespan = new_makespan
        else:
            delta = new_makespan - makespan(current)
            if random.random() < math.exp(-delta / T):
                current = new_seq
    return best

