def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    def makespan_taillard(seq, e=None, q=None):
        if not seq:
            return 0
        k = len(seq)
        if e is None or q is None or len(e) != k or len(q) != k+1:
            e = [[0] * M for _ in range(k)]
            q = [[0] * M for _ in range(k+1)]
            for r in range(k):
                job = seq[r]
                job_t = times[job]
                if r == 0:
                    e[0][0] = job_t[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_t[m]
                else:
                    e[r][0] = e[r-1][0] + job_t[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job = seq[r]
                job_t = times[job]
                q[r][M-1] = q[r+1][M-1] + job_t[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        best_cmax = float('inf')
        best_pos = 0
        for i in range(k+1):
            f = [0] * M
            if i == 0:
                for m in range(M):
                    f[m] = job_t[m] + (q[0][m] if k > 0 else 0)
            else:
                prev_e = e[i-1] if i-1 < k else [0]*M
                f[0] = prev_e[0] + job_t[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + job_t[m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_cmax, best_pos, e, q

    def NEH_taillard(jobs):
        if not jobs:
            return []
        seq = [jobs[0]]
        if len(jobs) > 1:
            job0, job1 = jobs[0], jobs[1]
            c01 = makespan([job0, job1])
            c10 = makespan([job1, job0])
            seq = [job0, job1] if c01 <= c10 else [job1, job0]
        e = None
        q = None
        for idx in range(2, len(jobs)):
            job = jobs[idx]
            job_t = times[job]
            _, pos, e, q = makespan_taillard(seq, e, q, job_t=job_t)
            seq.insert(pos, job)
        return seq

    def Gupta_heuristic():
        slopes = []
        for i in range(N):
            s = 0
            for j in range(M):
                s += (2 * j - M + 1) * times[i][j]
            slopes.append((s, i))
        slopes.sort(key=lambda x: x[0], reverse=True)
        return [idx for _, idx in slopes]

    def total_flow_time(seq):
        if not seq:
            return 0
        t = [0] * M
        flow = 0
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
            flow += t[-1]
        return flow

    def Johnson_two_machine(m1, m2):
        left = []
        right = []
        for i in range(N):
            if m1[i] <= m2[i]:
                left.append(i)
            else:
                right.append(i)
        left.sort(key=lambda i: m1[i])
        right.sort(key=lambda i: m2[i], reverse=True)
        return left + right

    def CDS():
        best_seq = None
        best_cmax = float('inf')
        for l in range(1, M):
            m1 = [0] * N
            m2 = [0] * N
            for i in range(N):
                for j in range(l):
                    m1[i] += times[i][j]
                for j in range(M-l, M):
                    m2[i] += times[i][j]
            seq = Johnson_two_machine(m1, m2)
            cmax = makespan(seq)
            if cmax < best_cmax:
                best_cmax = cmax
                best_seq = seq
        return best_seq if best_seq is not None else list(range(N))

    def destroy_and_reconstruct(seq, d):
        if d >= len(seq):
            return seq[:]
        indices = random.sample(range(len(seq)), d)
        extracted = [seq[i] for i in indices]
        remaining = [seq[i] for i in range(len(seq)) if i not in indices]
        random.shuffle(extracted)
        current = remaining[:]
        e = None
        q = None
        for job in extracted:
            job_t = times[job]
            _, pos, e, q = makespan_taillard(current, e, q, job_t=job_t)
            current.insert(pos, job)
        return current

    def IG(initial_seq, max_iter=50):
        current = initial_seq[:]
        best = initial_seq[:]
        best_cmax = makespan(best)
        if best_cmax == 0:
            return best
        for _ in range(max_iter):
            d = 3 if N > 20 else 4
            if d > N:
                d = N
            candidate = destroy_and_reconstruct(current, d)
            cmax_cand = makespan(candidate)
            if cmax_cand < makespan(current):
                current = candidate[:]
                if cmax_cand < best_cmax:
                    best = candidate[:]
                    best_cmax = cmax_cand
            else:
                delta = cmax_cand - makespan(current)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    current = candidate[:]
        return best

    NEH_seq = NEH_taillard(sorted(range(N), key=lambda i: -sum(times[i])))
    Gupta_seq = Gupta_heuristic()
    CDS_seq = CDS()
    candidates = [NEH_seq, Gupta_seq, CDS_seq]
    best_seq = min(candidates, key=makespan)
    improved_seq = IG(best_seq, max_iter=60)
    return improved_seq

