        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times for NEH priority
    total_times = [sum(job) for job in times]
    jobs_sorted = sorted(range(n), key=lambda i: total_times[i], reverse=True)

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * m
        for job in perm:
            for k in range(m):
                if k == 0:
                    t[k] += times[job][k]
                else:
                    t[k] = max(t[k], t[k-1]) + times[job][k]
        return t[-1]

    # NEH construction with Taillard acceleration
    def neh_taillard(perm):
        k = len(perm)
        if k == 0:
            return []
        # Forward matrix e
        e = [[0] * m for _ in range(k)]
        e[0][0] = times[perm[0]][0]
        for j in range(1, m):
            e[0][j] = e[0][j-1] + times[perm[0]][j]
        for i in range(1, k):
            e[i][0] = e[i-1][0] + times[perm[i]][0]
            for j in range(1, m):
                e[i][j] = max(e[i-1][j], e[i][j-1]) + times[perm[i]][j]
        # Backward matrix q
        q = [[0] * m for _ in range(k+1)]
        for i in range(k-1, -1, -1):
            q[i][m-1] = q[i+1][m-1] + times[perm[i]][m-1]
            for j in range(m-2, -1, -1):
                q[i][j] = max(q[i+1][j], q[i][j+1]) + times[perm[i]][j]
        return e, q

    # Build initial solution using NEH
    perm = [jobs_sorted[0]]
    for idx in range(1, n):
        job = jobs_sorted[idx]
        best_pos = 0
        best_mk = float('inf')
        e, q = neh_taillard(perm)
        k = len(perm)
        for pos in range(k+1):
            # Compute forward vector f for inserting 'job' at 'pos'
            f = [0] * m
            if pos == 0:
                prev_e = [0] * m
            else:
                prev_e = e[pos-1]
            f[0] = prev_e[0] + times[job][0]
            for j in range(1, m):
                f[j] = max(f[j-1], prev_e[j]) + times[job][j]
            # Compute makespan for this insertion
            mk = 0
            for j in range(m):
                val = f[j] + q[pos][j]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = pos
        perm.insert(best_pos, job)
    return perm

