    # Preprocess: flatten times for faster access
    flat_times = [t for job in times for t in job]

    def makespan(seq: list[int]) -> int:
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            base = job * M
            t[0] += flat_times[base]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + flat_times[base + m]
        return t[-1]

