    def compute_forward(seq: list[int]):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = seq[r]
            base = job * M
            if r == 0:
                e[0][0] = flat_times[base]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + flat_times[base + m]
            else:
                e[r][0] = e[r-1][0] + flat_times[base]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + flat_times[base + m]
        return e

    # Helper to compute backward tail matrix for a given sequence
    def compute_backward(seq: list[int]):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            base = job * M
            q[r][M-1] = q[r+1][M-1] + flat_times[base + M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + flat_times[base + m]
