                    f[0] = e[prev_idx][0] + flat_times[job * M]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[prev_idx][m]) + flat_times[job * M + m]
                makespan_val = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > makespan_val:
                        makespan_val = val
                if makespan_val < best_makespan:
                    best_makespan = makespan_val
                    best_pos = pos
            seq.insert(best_pos, job)

    # Iterated Greedy refinement
    current_seq = seq[:]
    best_seq = seq[:]
    best_makespan = makespan(best_seq)
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0
    d = 3 if N >= 3 else N
    max_iters = 60
    iters = 0

    while iters < max_iters:
        # Destruction: remove d random jobs
        indices = list(range(N))
        random.shuffle(indices)
        removed_indices = indices[:d]
        removed_indices.sort(reverse=True)
        destroyed_seq = current_seq[:]
        removed_jobs = []
        for idx in removed_indices:
            removed_jobs.append(destroyed_seq.pop(idx))
        # Reconstruction: reinsert using NEH insertion with Taillard
        for job in removed_jobs:
            best_pos = 0
            best_makespan_val = float('inf')
            e = compute_forward(destroyed_seq)
            q = compute_backward(destroyed_seq)
            k = len(destroyed_seq)
            for pos in range(k+1):
                f = [0] * M
                if pos == 0:
                    f[0] = flat_times[job * M]
                    for m in range(1, M):
                        f[m] = f[m-1] + flat_times[job * M + m]
                else:
                    prev_idx = pos - 1
                    f[0] = e[prev_idx][0] + flat_times[job * M]
                    for m in range(1, M):
