                makespan_val = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > makespan_val:
                        makespan_val = val
                if makespan_val < best_makespan_val:
                    best_makespan_val = makespan_val
                    best_pos = pos
            destroyed_seq.insert(best_pos, job)
        # Acceptance
        new_makespan = makespan(destroyed_seq)
        if new_makespan < makespan(current_seq):
