def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(row) for row in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9

    # Precompute total processing times and slope indices
    P = [sum(times[i]) for i in range(N)]
    S = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    def taillard_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = (e[0][m-1] if m > 0 else 0) + times[perm[0]][m]
        for r in range(1, k):
            job_t = times[perm[r]]
            e[r][0] = e[r-1][0] + job_t[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
        return e

    def taillard_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_t = times[perm[r]]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        return q

    def makespan_insert(e, q, job, pos):
        k = len(e)
        f = [0] * M
        if pos == 0:
            for m in range(M):
                f[m] = (f[m-1] if m > 0 else 0) + times[job][m]
        else:
            e_prev = e[pos-1]
            f[0] = e_prev[0] + times[job][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + times[job][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def construct_neh(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            seq1 = [order[0], order[1]]
            seq2 = [order[1], order[0]]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, len(order)):
            job = order[idx]
            e = taillard_forward(seq)
            q = taillard_backward(seq)
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(seq) + 1):
                m = makespan_insert(e, q, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    def destroy_and_reconstruct(seq, d):
        if d <= 0 or d >= len(seq):
            return seq[:]
        indices = random.sample(range(len(seq)), d)
        removed = [seq[i] for i in indices]
        remaining = [seq[i] for i in range(len(seq)) if i not in indices]
        random.shuffle(removed)
        for job in removed:
            e = taillard_forward(remaining)
            q = taillard_backward(remaining)
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(remaining) + 1):
                m = makespan_insert(e, q, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            remaining.insert(best_pos, job)
        return remaining

    # Initial solution using NEH with slope as tie-breaker
    order_slope = sorted(range(N), key=lambda i: (-S[i], -P[i]))
    pi = construct_neh(order_slope)
    pi_best = pi[:]
    makespan_best = makespan(pi)

    # Iterated Greedy
    max_iter = 60
    d = 3
    for _ in range(max_iter):
        pi_new = destroy_and_reconstruct(pi, d)
        makespan_new = makespan(pi_new)
        if makespan_new < makespan(pi):
            pi = pi_new[:]
            if makespan_new < makespan_best:
                pi_best = pi_new[:]
                makespan_best = makespan_new
        elif makespan_new < makespan_best:
            pi_best = pi_new[:]
            makespan_best = makespan_new
        else:
            if random.random() < math.exp(-(makespan_new - makespan(pi)) / T):
                pi = pi_new[:]

    return pi_best

