        extracted = [current_seq[i] for i in indices]
        remaining = [current_seq[i] for i in range(N) if i not in indices]
        if use_swap:
            if len(extracted) >= 2:
                a, b = random.sample(range(len(extracted)), 2)
                extracted[a], extracted[b] = extracted[b], extracted[a]
            for job in extracted:
                k = len(remaining)
                if k == 0:
                    remaining.append(job)
                    continue
                e, q = compute_eh_matrices(remaining)
                best_pos = 0
                best_mk = makespan_after_insert(e, q, job, 0, k)
                for pos in range(1, k+1):
                    mk = makespan_after_insert(e, q, job, pos, k)
                    if mk < best_mk:
