def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    for i in range(N):
        total_processing += sum(times[i])

    # Precompute job data for fast access
    job_data = [times[i][:] for i in range(N)]

    # Helper: makespan calculation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            pj = job_data[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + pj[m]
        return t[-1]

    # Helper: makespan after inserting job at position i in partial sequence
    # Using Taillard's acceleration: forward/backward decomposition
    def insertion_makespan(partial, x, i):
        k = len(partial)
        if k == 0:
            return job_data[x][-1]  # makespan of single job
        # Forward matrix e for partial sequence
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            pj = job_data[partial[r]]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        # Backward tail matrix q
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pj = job_data[partial[r]]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        # Forward vector f for job x at insertion point i
        f = [0] * M
        if i == 0:
            f[0] = job_data[x][0]
            for m in range(1, M):
                f[m] = f[m-1] + job_data[x][m]
        else:
            pj = job_data[x]
            f[0] = e[i-1][0] + pj[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + pj[m]
        # Compute makespan: max over m of f[m] + q[i][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    job_sums = [sum(job_data[i]) for i in range(N)]
    order = sorted(range(N), key=lambda i: (-job_sums[i], i))
    seq = [order[0]]
    if N > 1:
        # Evaluate first two jobs
        makespan_01 = makespan([order[0], order[1]])
        makespan_10 = makespan([order[1], order[0]])
        if makespan_10 < makespan_01:
            seq = [order[1], order[0]]
        else:
            seq = [order[0], order[1]]
        # Insert remaining jobs
        for idx in range(2, N):
            job = order[idx]
            best_pos = 0
            best_makespan = insertion_makespan(seq, job, 0)
            for pos in range(1, len(seq)+1):
                m = insertion_makespan(seq, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            seq.insert(best_pos, job)

    # Iterated Greedy refinement
    current = seq[:]
    best = seq[:]
    best_makespan = makespan(best)
    d = 4  # destruction size
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-6:
        T = 1e-6
    max_iter = 60  # calibrated for <50ms
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            remaining = current[:]
            random.shuffle(remaining)
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            destroyed = [current[i] for i in indices]
            remaining = [current[i] for i in range(N) if i not in indices_set]
        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        for job in destroyed:
            best_pos = 0
            best_m = insertion_makespan(remaining, job, 0)
            for pos in range(1, len(remaining)+1):
                m = insertion_makespan(remaining, job, pos)
                if m < best_m:
                    best_m = m
                    best_pos = pos
            remaining.insert(best_pos, job)
        # Acceptance criterion
        new_makespan = makespan(remaining)
        if new_makespan < makespan(current):
            current = remaining[:]
            if new_makespan < best_makespan:
                best = remaining[:]
                best_makespan = new_makespan
        elif new_makespan < best_makespan:
            # Accept with probability even if worse than current but better than best
                if random.random() < math.exp(-(new_makespan - makespan(current)) / T):
                    current = remaining[:]
                else:
                    # Revert to current
                    pass
        else:
            if random.random() < math.exp(-(new_makespan - makespan(current)) / T):
                current = remaining[:]
    return best

