def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    lower_bound = 0
    for m in range(M):
        min_prefix = min(sum(job[:m]) for job in times) if m > 0 else 0
        min_suffix = min(sum(job[m+1:]) for job in times) if m < M-1 else 0
        machine_load = sum(job[m] for job in times)
        lb_m = min_prefix + machine_load + min_suffix
        if lb_m > lower_bound:
            lower_bound = lb_m

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for idx in seq:
            job = times[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def compute_forward(partial):
        k = len(partial)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_idx = partial[r]
            job = times[job_idx]
            if r == 0:
                e[0][0] = job[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job[m]
            else:
                e[r][0] = e[r-1][0] + job[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job[m]
        return e

    def compute_backward(partial):
        k = len(partial)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_idx = partial[r]
            job = times[job_idx]
            q[r][M-1] = q[r+1][M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job[m]
        return q

    def insertion_cost(partial, e, q, job_idx):
        k = len(partial)
        job = times[job_idx]
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = job[0]
                fm = [f0]
                for m in range(1, M):
                    fm.append(max(fm[m-1], 0) + job[m])
            else:
                prev_e = e[i-1]
                f0 = prev_e[0] + job[0]
                fm = [f0]
                for m in range(1, M):
                    fm.append(max(fm[m-1], prev_e[m]) + job[m])
            makespan_i = 0
            for m in range(M):
                val = fm[m] + q[i][m]
                if val > makespan_i:
                    makespan_i = val
            if makespan_i < best_makespan:
                best_makespan = makespan_i
                best_pos = i
        return best_pos, best_makespan

    def construct_initial():
        job_sums = [sum(job) for job in times]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        seq = [order[0], order[1]]
        rev_seq = [order[1], order[0]]
        if makespan(seq) > makespan(rev_seq):
            seq = rev_seq
        for k in range(2, N):
            job_idx = order[k]
            e = compute_forward(seq)
            q = compute_backward(seq)
            pos, _ = insertion_cost(seq, e, q, job_idx)
            seq.insert(pos, job_idx)
        return seq

    def destroy_and_reconstruct(seq, d):
        if d >= len(seq):
            return seq[:]
        indices = random.sample(range(len(seq)), d)
        indices_set = set(indices)
        remaining = [seq[i] for i in range(len(seq)) if i not in indices_set]
        removed = [seq[i] for i in indices]
        random.shuffle(removed)
        current = remaining[:]
        for job in removed:
            e = compute_forward(current)
            q = compute_backward(current)
            pos, _ = insertion_cost(current, e, q, job)
            current.insert(pos, job)
        return current

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    current = construct_initial()
    current_makespan = makespan(current)
    best_seq = current[:]
    best_makespan = current_makespan

    if best_makespan == lower_bound:
        return best_seq

    max_iter = 60
    for _ in range(max_iter):
        d = 3 if N > 20 else 2
        if d > N:
            d = N
        new_seq = destroy_and_reconstruct(current, d)
        new_makespan = makespan(new_seq)
        if new_makespan < current_makespan:
            current = new_seq
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_seq = new_seq[:]
                best_makespan = new_makespan
                if best_makespan == lower_bound:
                    break
        else:
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current = new_seq
                current_makespan = new_makespan
    return best_seq

