    for job in jobs_sorted:
        length = insert_job_taillard(perm, length, job)
    current_perm = perm[:length]
    best_perm = current_perm[:]
    best_makespan = makespan_from_perm(best_perm)

    # Iterated Greedy parameters
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for _ in range(max_iter):
        if no_improve >= no_improve_limit:
            break
        # Destruction: remove d random jobs
        indices = list(range(N))
        random.shuffle(indices)
        removed_indices = indices[:d]
        removed_indices.sort()
        remaining = [current_perm[i] for i in range(N) if i not in removed_indices]
        extracted = [current_perm[i] for i in removed_indices]
        # Reconstruction: reinsert extracted jobs one by one in random order
        random.shuffle(extracted)
        temp_perm = remaining[:]
        for job in extracted:
            length_temp = len(temp_perm)
            temp_perm.append(0)  # temporary expansion
            length_temp = insert_job_taillard(temp_perm, length_temp, job)
        # Evaluate new solution
        new_makespan = makespan_from_perm(temp_perm)
        # Acceptance criterion
        if new_makespan < makespan_from_perm(current_perm):
            current_perm = temp_perm[:]
            if new_makespan < best_makespan:
                best_perm = temp_perm[:]
                best_makespan = new_makespan
                no_improve = 0
            else:
                no_improve += 1
        else:
            delta = new_makespan - makespan_from_perm(current_perm)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current_perm = temp_perm[:]
                no_improve += 1
            else:
                no_improve += 1

    return best_perm

