    def neh_construct():
        order = sorted(range(n), key=lambda i: total[i], reverse=True)
        if n == 0:
            return []
        if n == 1:
            return [order[0]]
        # Initial pair
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        seq = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        # Insert remaining jobs
        for k in range(2, n):
            job = order[k]
            best_pos = 0
            best_mk = float('inf')
            # Forward matrix e for current seq (length k)
            e = [[0]*m for _ in range(k)]
            for r in range(k):
                job_r = seq[r]
                tj = p[job_r]
                if r == 0:
                    e[0][0] = tj[0]
                    for j in range(1, m):
                        e[0][j] = e[0][j-1] + tj[j]
                else:
                    e[r][0] = e[r-1][0] + tj[0]
                    for j in range(1, m):
                        e[r][j] = max(e[r-1][j], e[r][j-1]) + tj[j]
            # Backward matrix q for current seq (length k)
            q = [[0]*m for _ in range(k+1)]
            # q[k][:] already 0
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                tj = p[job_r]
                q[r][m-1] = q[r+1][m-1] + tj[m-1]
                for j in range(m-2, -1, -1):
                    q[r][j] = max(q[r+1][j], q[r][j+1]) + tj[j]
            # Evaluate each insertion position i in [0, k]
            for i in range(k+1):
