                    for j in range(1, m):
                        f[j] = max(f[j-1], prev[j]) + tj[j]
                    # Makespan = max over m of (f[j] + q[i][j])
                    mk = 0
                    for j in range(m):
                        val = f[j] + q[i][j]
                        if val > mk:
                            mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
