                if k == 0:
                    e = []
                else:
                    e = [[0]*m for _ in range(k)]
                    for r in range(k):
                        job_r = seq[r]
                        tj = p[job_r]
                        if r == 0:
                            e[0][0] = tj[0]
                            for j in range(1, m):
                                e[0][j] = e[0][j-1] + tj[j]
                        else:
                            e[r][0] = e[r-1][0] + tj[0]
                            for j in range(1, m):
                                e[r][j] = max(e[r-1][j], e[r][j-1]) + tj[j]
                # Backward matrix q for current seq
                q = [[0]*m for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = seq[r]
                    tj = p[job_r]
                    q[r][m-1] = q[r+1][m-1] + tj[m-1]
                    for j in range(m-2, -1, -1):
                        q[r][j] = max(q[r+1][j], q[r][j+1]) + tj[j]
                # Try each insertion position
                for i in range(k+1):
                    if i == 0:
                        prev = [0]*m
                    else:
                        prev = e[i-1]
                    tj = p[job]
                    if m == 0:
                        mk_ins = 0
                    else:
                        f = [0]*m
                        f[0] = prev[0] + tj[0]
                        for j in range(1, m):
                            f[j] = max(f[j-1], prev[j]) + tj[j]
                        mk_ins = 0
                        for j in range(m):
                            val = f[j] + q[i][j]
                            if val > mk_ins:
                                mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                seq.insert(best_pos, job)
            # Acceptance criterion
            mk_new = makespan(seq)
            if mk_new < best_mk:
                best_mk = mk_new
                best = seq[:]
            if mk_new < makespan(current):
                current = seq[:]
            else:
                if random.random() < math.exp(-(mk_new - makespan(current)) / T):
                    current = seq[:]
        return best

    # Run NEH then IG
    init_seq = neh_construct()
    return iterated_greedy(init_seq, max_iter=50)

