                if new_mk < best_mk:
                    best = new_seq[:]
                    best_mk = new_mk
        return best

    # Initial solution via NEH
    init_seq = neh_construction()
    # Refine with Iterated Greedy
    final_seq = iterated_greedy(init_seq, max_iter=50)
