    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job data for fast access
    job_data = [times[i][:] for i in range(N)]
    total_processing = [sum(job) for job in job_data]

    # Makespan evaluation using forward pass
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job_idx in seq:
            p = job_data[job_idx]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[m]
        return t[M-1]

    # Taillard acceleration: forward completion matrix for prefix seq[0:k]
    def forward_matrix(seq, k):
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            p = job_data[seq[r]]
            if r == 0:
                e[0][0] = p[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[m]
            else:
                e[r][0] = e[r-1][0] + p[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[m]
        return e

    # Taillard acceleration: backward tail matrix for suffix seq[k:]
    def backward_matrix(seq, k):
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            p = job_data[seq[r]]
            q[r][M-1] = q[r+1][M-1] + p[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[m]
        return q

    # Evaluate makespan of inserting job x at position i in seq (length k) using Taillard
    def insertion_makespan(seq, k, x, e, q):
        f = [0] * M
        p = job_data[x]
        if k == 0:
            f[0] = p[0]
            for m in range(1, M):
                f[m] = f[m-1] + p[m]
        else:
            f[0] = e[0][0] + p[0] if k > 0 else p[0]
            for m in range(1, M):
                prev_e = e[k-1][m] if k-1 >= 0 else 0
                f[m] = max(f[m-1], prev_e) + p[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[k][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    def neh_construction():
        order = sorted(range(N), key=lambda i: total_processing[i], reverse=True)
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        # Initial pair
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Greedy insertion
        for k in range(2, N):
            job = order[k]
            e = forward_matrix(seq, k)
            q = backward_matrix(seq, k)
            best_pos = 0
            best_makespan = float('inf')
            for i in range(k+1):
                msp = insertion_makespan(seq, k, job, e, q)
                if msp < best_makespan:
                    best_makespan = msp
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(initial_seq):
        current_seq = initial_seq[:]
        best_seq = initial_seq[:]
        best_makespan = makespan(best_seq)
        total_sum = sum(total_processing)
        T_param = 0.5
        T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 5 else max(1, N // 2)
        max_iter = 60
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current_seq[i] for i in sorted(indices, reverse=True)]
            for idx in sorted(indices, reverse=True):
                del current_seq[idx]
            # Reconstruction: reinsert removed jobs one by one
            for job in removed:
                k = len(current_seq)
                if k == 0:
                    current_seq.append(job)
                    continue
                e = forward_matrix(current_seq, k)
                q = backward_matrix(current_seq, k)
                best_pos = 0
                best_msp = float('inf')
                for i in range(k+1):
                    msp = insertion_makespan(current_seq, k, job, e, q)
                    if msp < best_msp:
                        best_msp = msp
                        best_pos = i
                current_seq.insert(best_pos, job)
            # Acceptance
            msp_current = makespan(current_seq)
            if msp_current < best_makespan:
                best_makespan = msp_current
                best_seq = current_seq[:]
            if msp_current < makespan(initial_seq):  # always accept if better than current start of iteration
                pass  # current_seq is already updated
            else:
                if msp_current == makespan(initial_seq) or random.random() < math.exp(-(msp_current - makespan(initial_seq)) / T):
                    pass  # accept current_seq
                else:
                    current_seq = initial_seq[:]  # reject, revert to initial sequence for this iteration
        return best_seq

    # Build initial solution
    initial_seq = neh_construction()
    # Refine with Iterated Greedy
    improved_seq = iterated_greedy(initial_seq)
    return improved_seq

