                    best_pos = i
            pi.insert(best_pos, job)

    # Iterated Greedy refinement
    pi_best = pi[:]
    best_makespan = makespan(pi_best)
    total_processing = sum(get_time(i, m) for i in range(N) for m in range(M))
    T_param = 0.5
