                for c in range(m-1, -1, -1):
                    if c == m-1:
                        q_ig[r][c] = q_ig[r+1][c] + times[job_r][c]
                    elif r == k_new-1:
                        q_ig[r][c] = q_ig[r][c+1] + times[job_r][c]
                    else:
                        q_ig[r][c] = max(q_ig[r+1][c], q_ig[r][c+1]) + times[job_r][c]
