def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for each job
    total_times = [sum(job) for job in times]

    # Makespan evaluation function
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # CDS: Generate m-1 artificial two-machine subproblems using Johnson's rule
    best_seq = None
    best_cmax = float('inf')

    for l in range(1, M):
        # Artificial processing times for two-machine subproblem
        p1 = [sum(job[:l]) for job in times]  # sum of first l machines
        p2 = [sum(job[M-l:]) for job in times]  # sum of last l machines

        # Johnson's rule: partition jobs into two sets
        set1 = []  # jobs with p1 <= p2
        set2 = []  # jobs with p1 > p2
        for i in range(N):
            if p1[i] <= p2[i]:
                set1.append(i)
            else:
                set2.append(i)

        # Sort set1 by p1 ascending, set2 by p2 descending
        set1.sort(key=lambda i: p1[i])
        set2.sort(key=lambda i: p2[i], reverse=True)

        # Candidate sequence
        cand_seq = set1 + set2
        cand_cmax = makespan(cand_seq)

        if cand_cmax < best_cmax:
            best_cmax = cand_cmax
            best_seq = cand_seq

    return best_seq if best_seq is not None else list(range(N))

