    jobs = list(range(N))
    jobs.sort(key=lambda i: total_processing[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[-1]

    def makespan_with_tail(perm, e, q):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[-1]

    def taillard_makespan_insert(partial, job, e, q):
        k = len(partial)
        if k == 0:
            return times[job][0] if M == 1 else _compute_makespan_from_job(job)
        f = [0] * M
        for m in range(M):
            prev_f = f[m-1] if m > 0 else 0
            prev_e = e[k-1][m] if k-1 >= 0 else 0
            base = prev_f if prev_f > prev_e else prev_e
            f[m] = base + times[job][m]
        best_cmax = float('inf')
        best_pos = 0
        for i in range(k+1):
            if i == 0:
                f_val = [times[job][m] for m in range(M)]
            else:
                f_val = [0] * M
                for m in range(M):
                    prev_f = f_val[m-1] if m > 0 else 0
                    prev_e = e[i-1][m] if i-1 >= 0 else 0
                    base = prev_f if prev_f > prev_e else prev_e
                    f_val[m] = base + times[job][m]
            tail = q[i]
            cmax = 0
            for m in range(M):
                val = f_val[m] + tail[m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_cmax, best_pos

    def _compute_makespan_from_job(job):
        t = 0
        for m in range(M):
            t += times[job][m]
        return t

    def build_forward_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0]*M for _ in range(k)], [[0]*M for _ in range(k+1)]
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            job_time = times[job]
            if r == 0:
                e[0][0] = job_time[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_time[m]
            else:
                e[r][0] = e[r-1][0] + job_time[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_time[m]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            job_time = times[job]
            q[r][M-1] = q[r+1][M-1] + job_time[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_time[m]
        return e, q

    def neh_construct():
        if len(jobs) <= 1:
            return jobs[:]
        seq = [jobs[0], jobs[1]]
        e, q = build_forward_backward(seq)
        c01, _ = taillard_makespan_insert(seq[:0], jobs[1], [[0]*M], [[0]*M, [0]*M]) if False else (0,0)
        c10, _ = taillard_makespan_insert(seq[:1], jobs[0], [[0]*M], [[0]*M, [0]*M]) if False else (0,0)
        if makespan([jobs[0], jobs[1]]) <= makespan([jobs[1], jobs[0]]):
            seq = [jobs[0], jobs[1]]
        else:
            seq = [jobs[1], jobs[0]]
        e, q = build_forward_backward(seq)
        for idx in range(2, len(jobs)):
            job = jobs[idx]
            _, pos = taillard_makespan_insert(seq, job, e, q)
            seq.insert(pos, job)
            e, q = build_forward_backward(seq)
        return seq

    def destroy_and_reconstruct(seq, d):
        if d >= len(seq):
            return neh_construct()
        indices = random.sample(range(len(seq)), d)
        removed = [seq[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del seq[idx]
        e, q = build_forward_backward(seq)
        for job in removed:
            _, pos = taillard_makespan_insert(seq, job, e, q)
            seq.insert(pos, job)
            e, q = build_forward_backward(seq)
        return seq

    current = neh_construct()
    current_makespan = makespan(current)
    best = current[:]
    best_makespan = current_makespan
    total = sum(total_processing)
    T_param = 0.5
    T = T_param * total / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 60
    for _ in range(max_iter):
        d = 3 if random.random() < 0.7 else 4
        candidate = destroy_and_reconstruct(current[:], d)
        candidate_makespan = makespan(candidate)
        if candidate_makespan < current_makespan:
            current = candidate
            current_makespan = candidate_makespan
            if candidate_makespan < best_makespan:
                best = candidate[:]
                best_makespan = candidate_makespan
        elif candidate_makespan < best_makespan:
            best = candidate[:]
            best_makespan = candidate_makespan
        if candidate_makespan != current_makespan:
            diff = candidate_makespan - current_makespan
            if diff < 0 or random.random() < math.exp(-diff / T):
                current = candidate
                current_makespan = candidate_makespan
    return best

