    # Sort jobs by total processing time descending (NEH priority)
    jobs_sorted = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Initialize schedule with first two jobs
    if N >= 2:
        j0, j1 = jobs_sorted[0], jobs_sorted[1]
        # Evaluate both orders for the first two jobs
        makespan_01 = _makespan([j0, j1], times)
        makespan_10 = _makespan([j1, j0], times)
        if makespan_01 <= makespan_10:
            current = [j0, j1]
        else:
            current = [j1, j0]
    else:
        current = [jobs_sorted[0]]

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]  # forward completion times
    q = [[0] * M for _ in range(N + 1)]  # backward tail times (q[N][m] = 0)

    # Insert remaining jobs using Taillard-accelerated NEH
    for k in range(2, N):
        job_idx = jobs_sorted[k]
        p_job = times[job_idx]

        # Compute forward completion matrix e[0..k-1][0..M-1] for current schedule
        for r in range(k):
            job_r = current[r]
            p_r = times[job_r]
            if r == 0:
                e[0][0] = p_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p_r[m]
            else:
                e[r][0] = e[r-1][0] + p_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p_r[m]

        # Compute backward tail matrix q[r][m] for r in [0, k] (q[k][m] = 0)
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = current[r]
            p_r = times[job_r]
            q[r][M-1] = q[r+1][M-1] + p_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p_r[m]

        # Find best insertion position for job_idx using O(k*M) evaluation
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k + 1):  # insertion positions 0..k
            # Compute forward vector f for job_idx at position i
            if i == 0:
                f0 = p_job[0]
                f = [f0]
                for m in range(1, M):
                    f.append(f[-1] + p_job[m])
            else:
                prev_e = e[i-1]
                f0 = prev_e[0] + p_job[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[-1], prev_e[m]) + p_job[m])

            # Compute makespan if job_idx inserted at position i
            makespan_i = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_i:
                    makespan_i = val

            if makespan_i < best_makespan:
                best_makespan = makespan_i
                best_pos = i

        # Insert job_idx at best_pos
        current.insert(best_pos, job_idx)

    # Iterated Greedy refinement
    pi = current[:]
    pi_star = pi[:]
    makespan_star = _makespan(pi_star, times)
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

    # Number of IG iterations scaled to stay within time budget
    max_iter = 60
    d = 3 if N > 20 else 2  # destruction size

    for _ in range(max_iter):
        # Destruction: remove d jobs randomly
        if d >= N:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            destroyed = [pi[i] for i in indices]
            remaining = [pi[i] for i in range(N) if i not in indices_set]

        # Reconstruct using NEH insertion with Taillard acceleration on remaining jobs
        if not remaining:
