                        e_rec[0][0] = p_r[0]
                        for m in range(1, M):
                            e_rec[0][m] = e_rec[0][m-1] + p_r[m]
                    else:
                        e_rec[r][0] = e_rec[r-1][0] + p_r[0]
                        for m in range(1, M):
                            e_rec[r][m] = max(e_rec[r-1][m], e_rec[r][m-1]) + p_r[m]

                # Compute backward tail for pi_new[0..k-1]
                for m in range(M):
                    q_rec[k][m] = 0
                for r in range(k-1, -1, -1):
                    job_r = pi_new[r]
                    p_r = times[job_r]
                    q_rec[r][M-1] = q_rec[r+1][M-1] + p_r[M-1]
                    for m in range(M-2, -1, -1):
                        q_rec[r][m] = max(q_rec[r+1][m], q_rec[r][m+1]) + p_r[m]

                # Find best insertion position
                best_pos_rec = 0
                best_makespan_rec = float('inf')
                for i in range(k + 1):
                    if i == 0:
                        f0 = p_job[0]
                        f = [f0]
