                    else:
                        prev_e = e_rec[i-1]
                        f0 = prev_e[0] + p_job[0]
                        f = [f0]
                        for m in range(1, M):
                            f.append(max(f[-1], prev_e[m]) + p_job[m])

                    makespan_i = 0
                    for m in range(M):
                        val = f[m] + q_rec[i][m]
                        if val > makespan_i:
                            makespan_i = val

                    if makespan_i < best_makespan_rec:
                        best_makespan_rec = makespan_i
                        best_pos_rec = i

                pi_new.insert(best_pos_rec, job_idx)

            # Insert destroyed jobs one by one using same NEH insertion
            for job_idx in destroyed:
                p_job = times[job_idx]
                k = len(pi_new)

                # Compute forward completion for current pi_new
                for r in range(k):
                    job_r = pi_new[r]
                    p_r = times[job_r]
                    if r == 0:
                        e_rec[0][0] = p_r[0]
                        for m in range(1, M):
                            e_rec[0][m] = e_rec[0][m-1] + p_r[m]
                    else:
                        e_rec[r][0] = e_rec[r-1][0] + p_r[0]
                        for m in range(1, M):
                            e_rec[r][m] = max(e_rec[r-1][m], e_rec[r][m-1]) + p_r[m]

                # Compute backward tail
                for m in range(M):
                    q_rec[k][m] = 0
                for r in range(k-1, -1, -1):
                    job_r = pi_new[r]
                    p_r = times[job_r]
                    q_rec[r][M-1] = q_rec[r+1][M-1] + p_r[M-1]
                    for m in range(M-2, -1, -1):
                        q_rec[r][m] = max(q_rec[r+1][m], q_rec[r][m+1]) + p_r[m]

                # Find best insertion position
                best_pos_rec = 0
                best_makespan_rec = float('inf')
                for i in range(k + 1):
                    if i == 0:
                        f0 = p_job[0]
                        f = [f0]
                        for m in range(1, M):
                            f.append(f[-1] + p_job[m])
                    else:
                        prev_e = e_rec[i-1]
                        f0 = prev_e[0] + p_job[0]
                        f = [f0]
                        for m in range(1, M):
                            f.append(max(f[-1], prev_e[m]) + p_job[m])

                    makespan_i = 0
                    for m in range(M):
                        val = f[m] + q_rec[i][m]
                        if val > makespan_i:
                            makespan_i = val

                    if makespan_i < best_makespan_rec:
                        best_makespan_rec = makespan_i
                        best_pos_rec = i

                pi_new.insert(best_pos_rec, job_idx)

