        makespan_new = _makespan(pi_new, times)
        if makespan_new < makespan_star:
            pi_star = pi_new[:]
            makespan_star = makespan_new
        if makespan_new < _makespan(pi, times):
            pi = pi_new[:]
        else:
            if makespan_star > 0:
                prob = math.exp(-(makespan_new - _makespan(pi, times)) / T)
                if random.random() < prob:
                    pi = pi_new[:]

    return pi_star

def _makespan(perm, times):
    if not perm:
        return 0
    M = len(times[0])
    t = [0] * M
    for job in perm:
        job_times = times[job]
        t[0] += job_times[0]
        for m in range(1, M):
            t[m] = max(t[m-1], t[m]) + job_times[m]
    return t[M-1]

