def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for each job
    total_times = [sum(job) for job in times]

    # NEH construction with Taillard acceleration
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    def taillard_evaluate(partial_seq, job, pos):
        k = len(partial_seq)
        # Forward matrix e for partial_seq
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial_seq[r]
            p_r = times[job_r]
            if r == 0:
                e[0][0] = p_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p_r[m]
            else:
                e[r][0] = e[r-1][0] + p_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p_r[m]
        # Backward matrix q for partial_seq
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = partial_seq[r]
            p_r = times[job_r]
            q[r][M-1] = q[r+1][M-1] + p_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p_r[m]
        # Evaluate insertion at position pos
        f = [0] * M
        if pos == 0:
            for m in range(M):
                f[m] = times[job][m]
        else:
            prev = e[pos-1]
            job_p = times[job]
            f[0] = prev[0] + job_p[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev[m]) + job_p[m]
        # Compute makespan
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Build initial solution using NEH
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    if N >= 2:
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        seq = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        start = 2
    else:
        seq = [order[0]]
        start = 1
    for idx in range(start, N):
        job = order[idx]
        best_pos = 0
        best_makespan = float('inf')
        for pos in range(len(seq) + 1):
            m = taillard_evaluate(seq, job, pos)
            if m < best_makespan:
                best_makespan = m
                best_pos = pos
        seq.insert(best_pos, job)

    # Variable Neighborhood Search (VNS) with two neighborhoods
    def makespan_fast(seq):
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    def neighborhood_insert(seq):
        best_seq = seq[:]
        best_m = makespan_fast(best_seq)
        n = len(seq)
        for i in range(n):
            job = seq[i]
            seq_without = seq[:i] + seq[i+1:]
            for j in range(n):  # n positions in the new sequence of length n-1
                new_seq = seq_without[:j] + [job] + seq_without[j:]
                m = makespan_fast(new_seq)
                if m < best_m:
                    best_m = m
                    best_seq = new_seq
        return best_seq, best_m

    def neighborhood_swap(seq):
        best_seq = seq[:]
        best_m = makespan_fast(best_seq)
        n = len(seq)
        for i in range(n):
            for j in range(i+1, n):
                new_seq = seq[:]
                new_seq[i], new_seq[j] = new_seq[j], new_seq[i]
                m = makespan_fast(new_seq)
                if m < best_m:
                    best_m = m
                    best_seq = new_seq
        return best_seq, best_m

    current_seq = seq[:]
    current_makespan = makespan_fast(current_seq)
    best_seq = current_seq[:]
    best_makespan = current_makespan

    # VNS main loop
    k_max = 2  # two neighborhoods
    k = 1
    max_iter = 200
    it = 0
    while it < max_iter and k <= k_max:
        if k == 1:
            neighbor_seq, neighbor_makespan = neighborhood_insert(current_seq)
        else:
            neighbor_seq, neighbor_makespan = neighborhood_swap(current_seq)
        if neighbor_makespan < current_makespan:
            current_seq = neighbor_seq
            current_makespan = neighbor_makespan
            if current_makespan < best_makespan:
                best_seq = current_seq[:]
                best_makespan = current_makespan
            k = 1  # reset to first neighborhood
        else:
            k += 1  # move to next neighborhood
        it += 1

    return best_seq

