    total_times = [sum(job) for job in times]
    # Sort jobs by total processing time descending
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Makespan evaluation function
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[-1]

    # NEH construction with Taillard acceleration
    def construct_initial():
        if N < 2:
            return order[:]
        # Start with first two jobs
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        seq = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            k_len = len(seq)
            # Forward matrix e: completion times of current seq
            e = [[0] * M for _ in range(k_len)]
            for r in range(k_len):
                job_r = times[seq[r]]
                if r == 0:
                    e[0][0] = job_r[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_r[m]
                else:
                    e[r][0] = e[r-1][0] + job_r[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
            # Backward matrix q: tail times
            q = [[0] * M for _ in range(k_len + 1)]
            # q[k_len][m] = 0 already
            for r in range(k_len - 1, -1, -1):
                job_r = times[seq[r]]
                q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
            # Evaluate insertion positions
            best_pos = 0
            best_mk = float('inf')
            for i in range(k_len + 1):
                # Compute forward vector f for job at position i
                f = [0] * M
                if i == 0:
                    prev_e = [0] * M
                else:
                    prev_e = e[i-1]
                job_t = times[job]
                f[0] = prev_e[0] + job_t[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + job_t[m]
                # Compute makespan if job inserted at i
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reinsertion
    def iterated_greedy(init_seq, max_iters=60):
        current = init_seq[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        d = 3 if N > 20 else 2
        if N > 60:
            d = 4
        for _ in range(max_iters):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build partial sequence without removed jobs
            removed_set = set(removed)
            partial = [job for job in current if job not in removed_set]
            # Reconstruction: reinsert each removed job using Taillard acceleration
            for job in removed:
                k_len = len(partial)
                # Forward matrix e for partial
                e = [[0] * M for _ in range(k_len)]
                for r in range(k_len):
                    job_r = times[partial[r]]
                    if r == 0:
                        e[0][0] = job_r[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + job_r[m]
                    else:
                        e[r][0] = e[r-1][0] + job_r[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
                # Backward matrix q
                q = [[0] * M for _ in range(k_len + 1)]
                for r in range(k_len - 1, -1, -1):
                    job_r = times[partial[r]]
                    q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
                # Find best insertion position
                best_pos = 0
                best_mk_ins = float('inf')
                for i in range(k_len + 1):
                    if i == 0:
                        prev_e = [0] * M
                    else:
                        prev_e = e[i-1]
                    job_t = times[job]
                    f = [0] * M
                    f[0] = prev_e[0] + job_t[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev_e[m]) + job_t[m]
                    mk_ins = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk_ins:
                            mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                partial.insert(best_pos, job)
            # New candidate sequence
            candidate = partial
            candidate_mk = makespan(candidate)
            # Acceptance criterion
            if candidate_mk < best_mk:
                best = candidate[:]
                best_mk = candidate_mk
                current = candidate
            elif candidate_mk < makespan(current):
                current = candidate
            else:
                if random.random() < math.exp(-(candidate_mk - makespan(current)) / T):
                    current = candidate
        return best

    # Build initial solution and refine
    init_seq = construct_initial()
    # Quick lower bound check (optional, can be skipped for speed)
    # Run iterated greedy
    return iterated_greedy(init_seq, max_iters=50)

