    LB_param = total_processing / (10 * N * M) if N * M > 0 else 1.0
    T_param = 0.5
    T = T_param * LB_param
    d = 3
    max_iter = 50

    job_sums = [sum(row) for row in times]
    order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        e = [[0] * M for _ in range(k)]
        if k == 0:
            return e
        job0 = times[perm[0]]
        e[0][0] = job0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0[m]
        for r in range(1, k):
            job = times[perm[r]]
            er = e[r]
            er_prev = e[r-1]
            er[0] = er_prev[0] + job[0]
            for m in range(1, M):
                er[m] = max(er_prev[m], er[m-1]) + job[m]
        return e

    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        if k == 0:
            return q
        for r in range(k-1, -1, -1):
            job = times[perm[r]]
            qr = q[r]
            qr_next = q[r+1]
            qr[M-1] = qr_next[M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                qr[m] = max(qr_next[m], qr[m+1]) + job[m]
        return q

    def insert_best(perm, job, e, q):
        k = len(perm)
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = job[0]
            else:
                f0 = e[i-1][0] + job[0]
            f = [0] * M
            f[0] = f0
            for m in range(1, M):
                if i == 0:
                    f[m] = max(f[m-1], 0) + job[m]
                else:
                    f[m] = max(f[m-1], e[i-1][m]) + job[m]
            makespan_val = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_val:
                    makespan_val = val
            if makespan_val < best_makespan:
                best_makespan = makespan_val
                best_pos = i
