        perm = []
        for idx in order:
            if len(perm) < 2:
                perm.append(idx)
                if len(perm) == 2:
                    job0, job1 = perm[0], perm[1]
                    if makespan([job1, job0]) < makespan(perm):
                        perm[0], perm[1] = job1, job0
            else:
                e = compute_forward(perm)
                q = compute_backward(perm)
                perm = insert_best(perm, idx, e, q)
        return perm

    current = neh_construct()
    best = current[:]
    best_makespan = makespan(best)

    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            R = current[:]
            current = []
        else:
            indices = random.sample(range(len(current)), d)
