        if curr_makespan < makespan(current):
            current = current[:]
        else:
            if curr_makespan < makespan(best):
                best = current[:]
                best_makespan = curr_makespan
            if random.random() < math.exp(-(curr_makespan - makespan(current)) / T):
                current = current[:]
            else:
                current = best[:]

    return best

