    partial = [order[0]]
    for idx in range(1, N):
        job = order[idx]
        e = compute_forward(partial)
        q = compute_backward(partial)
        pos, _ = insert_job(partial, job, e, q)
        partial.insert(pos, job)

    current = partial[:]
    best = current[:]
    best_cmax = makespan(current)

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3
    max_iter = 60

    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            R = current[:]
        else:
            indices = random.sample(range(len(current)), d)
            indices.sort(reverse=True)
            destroyed = [current.pop(i) for i in indices]
            R = destroyed

        e = compute_forward(current)
        q = compute_backward(current)

        for job in R:
            pos, _ = insert_job(current, job, e, q)
            current.insert(pos, job)
            e = compute_forward(current)
            q = compute_backward(current)

        new_cmax = makespan(current)
        if new_cmax < best_cmax:
            best_cmax = new_cmax
            best = current[:]

        if new_cmax < makespan(current):
            current = current[:]
        elif random.random() < math.exp(-(new_cmax - makespan(current)) / T):
            current = current[:]
        else:
            current = best[:]

    return best

