    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[-1]

    # Taillard acceleration: compute forward matrix e for a given prefix
    def compute_forward(prefix):
        k = len(prefix)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = times[prefix[0]][m] if m == 0 else max(e[0][m-1], 0) + times[prefix[0]][m]
        for r in range(1, k):
            job = prefix[r]
            job_time = times[job]
            for m in range(M):
                if m == 0:
                    e[r][m] = e[r-1][m] + job_time[m]
                else:
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_time[m]
        return e

    # Taillard acceleration: compute backward matrix q for a given prefix
    def compute_backward(prefix):
        k = len(prefix)
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = prefix[r]
            job_time = times[job]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + job_time[m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_time[m]
        return q

    # Evaluate makespan for inserting job x at position i in prefix using Taillard
    def insertion_makespan(prefix, x, i):
        k = len(prefix)
        e = compute_forward(prefix)
        q = compute_backward(prefix)
        f = [0] * M
        # compute forward vector for job x
        if i == 0:
            prev_e = [0] * M
        else:
            prev_e = e[i-1]
        for m in range(M):
            if m == 0:
                f[m] = prev_e[0] + times[x][0]
            else:
                f[m] = max(f[m-1], prev_e[m]) + times[x][m]
        # compute makespan candidate
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
