    def neh_construct(order):
        if not order:
            return []
        # start with first job
        seq = [order[0]]
        if len(order) == 1:
            return seq
        # try both orders of first two
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # insert remaining jobs
        for idx in range(2, len(order)):
            job = order[idx]
            best_pos = 0
            best_mk = float('inf')
            # test all positions
            for pos in range(len(seq)+1):
                mk = insertion_makespan(seq, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size 3
    def iterated_greedy(initial_seq, max_iters=60):
        current = initial_seq[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        for _ in range(max_iters):
