            if len(current) < 3:
                destroyed = current[:]
                remaining = []
            else:
                indices = random.sample(range(len(current)), 3)
                indices.sort(reverse=True)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(len(current)) if i not in indices]
            # reconstruction: reinsert destroyed jobs one by one in random order
            random.shuffle(destroyed)
            seq = remaining[:]
            for job in destroyed:
                best_pos = 0
                best_mk_ins = float('inf')
                for pos in range(len(seq)+1):
                    mk = insertion_makespan(seq, job, pos)
                    if mk < best_mk_ins:
                        best_mk_ins = mk
                        best_pos = pos
                seq.insert(best_pos, job)
            # acceptance
            mk_new = makespan(seq)
            if mk_new < makespan(current):
                current = seq[:]
                if mk_new < best_mk:
                    best = seq[:]
                    best_mk = mk_new
            else:
                if random.random() < math.exp(-(mk_new - makespan(current)) / T):
                    current = seq[:]
        return best

    # Try multiple orderings: total time descending, slope index descending
    order_total = sorted(range(N), key=lambda i: (-total_times[i], i))
    order_slope = sorted(range(N), key=lambda i: (-slope_index[i], i))

    seq_total = neh_construct(order_total)
    seq_slope = neh_construct(order_slope)

    best_seq = seq_total if makespan(seq_total) <= makespan(seq_slope) else seq_slope
    best_mk = makespan(best_seq)

    # Apply iterated greedy refinement
    refined_total = iterated_greedy(seq_total)
    refined_slope = iterated_greedy(seq_slope)
    mk_refined_total = makespan(refined_total)
    mk_refined_slope = makespan(refined_slope)

    if mk_refined_total <= mk_refined_slope:
        return refined_total
    else:
        return refined_slope

