    var = [0.0] * M
    for j in range(M):
        mean = sum(times[i][j] for i in range(N)) / N
        var[j] = sum((times[i][j] - mean) ** 2 for i in range(N)) / N
        if var[j] == 0:
            var[j] = 1.0  # Avoid division by zero

    # Weighted slope: divide by variance to reduce impact of erratic machines
    weighted_slopes = [slopes[i] / sum(var) * M for i in range(N)]  # Normalize by total variance scaled by M
    order = sorted(range(N), key=lambda i: weighted_slopes[i], reverse=True)

    # Makespan evaluation function
    def makespan(seq):
