    def compute_forward(partial):
        k = len(partial)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = (e[0][m-1] if m > 0 else 0) + times[partial[0]][m]
        for r in range(1, k):
            for m in range(M):
                e[r][m] = max(e[r-1][m], e[r][m-1] if m > 0 else 0) + times[partial[r]][m]
        return e

