        t = [0] * M
        for job in perm:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_times[m]
        return t[-1]

    def taillard_insert(partial, job_idx):
        k = len(partial)
        if k == 0:
            return [job_idx]
        # Forward matrix e: completion times of partial schedule
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            job_times = times[job]
            if r == 0:
                e[0][0] = job_times[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_times[m]
            else:
                e[r][0] = e[r-1][0] + job_times[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_times[m]
        # Backward matrix q: tail times from each position
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already
        for r in range(k-1, -1, -1):
            job = partial[r]
            job_times = times[job]
            q[r][M-1] = q[r+1][M-1] + job_times[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_times[m]
        best_pos = 0
        best_mk = float('inf')
        # Evaluate each insertion position
        for i in range(k+1):
            # Forward pass for job_idx up to machine M-1 from position i
            f = [0] * M
            if i == 0:
                prev_e = [0] * M
            else:
                prev_e = e[i-1]
            job_times = times[job_idx]
            f[0] = prev_e[0] + job_times[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev_e[m]) + job_times[m]
            # Compute makespan: max over m of f[m] + q[i][m]
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return partial[:best_pos] + [job_idx] + partial[best_pos:]

    # Generate initial solution using NEH with Taillard
    order = sorted(range(N), key=lambda i: (-total_times[i], -slope_index[i]))
    perm = []
    for idx in order:
        perm = taillard_insert(perm, idx)

    # Iterated Greedy refinement
    current = perm[:]
    best = current[:]
    best_mk = makespan_from_perm(best)
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    max_iter = 60
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        remaining = [current[i] for i in range(N) if i not in indices]
        # Reconstruction: reinsert removed jobs in random order
        random.shuffle(removed)
        for job in removed:
            remaining = taillard_insert(remaining, job)
        new_seq = remaining
        new_mk = makespan_from_perm(new_seq)
        # Acceptance criterion
        if new_mk < best_mk:
            best_mk = new_mk
            best = new_seq[:]
            current = new_seq[:]
        elif new_mk < makespan_from_perm(current):
            current = new_seq[:]
        else:
            if random.random() < math.exp(-(new_mk - makespan_from_perm(current)) / T):
                current = new_seq[:]
    return best

