    LB = 0
    for m in range(M):
        min_before = min(times[i][l] for i in range(N) for l in range(m)) if m > 0 else 0
        min_after = min(times[i][l] for i in range(N) for l in range(m + 1, M)) if m < M - 1 else 0
        sum_m = sum(times[i][m] for i in range(N))
        LB_m = min_before + sum_m + min_after
        if LB_m > LB:
            LB = LB_m

