                        e[r][m] = (e[r - 1][m] if r > 0 else 0) + times[perm[r]][m]
                    else:
                        e[r][m] = max(e[r - 1][m] if r > 0 else 0, e[r][m - 1]) + times[perm[r]][m]
            # Update backward matrix q for current perm
            for m in range(M):
                q[k][m] = 0
            for r in range(k - 1, -1, -1):
                for m in range(M - 1, -1, -1):
                    if m == M - 1:
                        q[r][m] = q[r + 1][m] + times[perm[r]][m]
                    else:
                        q[r][m] = max(q[r + 1][m], q[r][m + 1]) + times[perm[r]][m]
            # Evaluate insertion positions using Taillard's O(k*M) method
            best_pos = 0
            best_makespan = float('inf')
