                        e[r][m] = max(e[r - 1][m] if r > 0 else 0, e[r][m - 1]) + times[remaining[r]][m]
            # Build backward matrix q for current remaining
            q = [[0] * M for _ in range(k + 1)]
            for m in range(M):
                q[k][m] = 0
            for r in range(k - 1, -1, -1):
                for m in range(M - 1, -1, -1):
                    if m == M - 1:
                        q[r][m] = q[r + 1][m] + times[remaining[r]][m]
                    else:
                        q[r][m] = max(q[r + 1][m], q[r][m + 1]) + times[remaining[r]][m]
            # Find best insertion position
