                    prev_e = e[i - 1]
                for m in range(M):
                    if m == 0:
                        f[m] = prev_e[m] + times[job][m]
                    else:
                        f[m] = max(f[m - 1], prev_e[m]) + times[job][m]
                # Makespan candidate
                cand = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cand:
                        cand = val
                if cand < best_mk_ins:
                    best_mk_ins = cand
                    best_pos = i
            remaining.insert(best_pos, job)
