    # IG parameters
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    current = best_perm[:]
    current_mk = best_mk
    # Determine number of iterations to stay within time budget (~40ms for IG)
    max_iter = 60 if N > 30 else 30
