                best_pos = i
        return current_seq[:best_pos] + [job_idx] + current_seq[best_pos:]

    def neh_construct(job_order):
        seq = []
        for idx in job_order:
            seq = taillard_insert(seq, idx)
        return seq

    best_seq = None
    best_cmax = float('inf')
    total_sum = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N > 20 else 2
    max_iter = 50
    iter_count = 0
    while iter_count < max_iter:
        job_order = list(range(N))
        noise = [random.uniform(0.9, 1.1) for _ in range(N)]
        job_order.sort(key=lambda i: (sum(times[i]) * noise[i]), reverse=True)
        seq = neh_construct(job_order)
        cmax = makespan(seq)
        if cmax < best_cmax:
            best_cmax = cmax
            best_seq = seq[:]
        if best_cmax == 0:
            break
        pi = best_seq[:]
        for _ in range(d):
            pos = random.randrange(len(pi))
            extracted = pi.pop(pos)
            R = [extracted]
        random.shuffle(R)
        pi_D = pi[:]
        for job in R:
            pi_D = taillard_insert(pi_D, job)
        cmax_D = makespan(pi_D)
        if cmax_D < makespan(pi):
            pi = pi_D[:]
            if cmax_D < best_cmax:
                best_cmax = cmax_D
                best_seq = pi_D[:]
        elif random.random() < math.exp(-(cmax_D - makespan(pi)) / T):
            pi = pi_D[:]
        iter_count += 1
    return best_seq if best_seq is not None else list(range(N))

