def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_data = [row[:] for row in times]
    P = [sum(job) for job in job_data]
    S = [sum((2 * j - M + 1) * job_data[i][j] for j in range(M)) for i in range(N)]

    # Makespan evaluation for a given permutation
    def makespan(perm):
        t = [0] * M
        for idx in perm:
            pj = job_data[idx]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[-1]

    # Taillard's acceleration: forward completion matrix for a partial schedule
    def forward_matrix(perm):
        k = len(perm)
        e = [[0] * M for _ in range(k)]
        if k == 0:
            return e
        p0 = job_data[perm[0]]
        e[0][0] = p0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + p0[m]
        for r in range(1, k):
            pj = job_data[perm[r]]
            e[r][0] = e[r-1][0] + pj[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    # Taillard's acceleration: backward tail matrix for a partial schedule
    def backward_matrix(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        if k == 0:
            return q
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            pj = job_data[perm[r]]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    # NEH construction with Taillard acceleration and slope matching priority
    def construct_initial():
        order = sorted(range(N), key=lambda i: (-S[i], -P[i]))
        if N < 2:
            return order[:]
        # Initial pair
        best_seq = None
        best_cmax = float('inf')
        for seq in ([order[0], order[1]], [order[1], order[0]]):
            cmax = makespan(seq)
            if cmax < best_cmax:
                best_cmax = cmax
                best_seq = seq[:]
        current = best_seq
        # Greedy insertion
        for k in range(2, N):
            job = order[k]
            e = forward_matrix(current)
            q = backward_matrix(current)
            best_pos = 0
            best_cmax = float('inf')
            for i in range(k+1):
                # Forward pass for job at position i
                f = [0] * M
                if i == 0:
                    f[0] = job_data[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + job_data[job][m]
                else:
                    f[0] = e[i-1][0] + job_data[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + job_data[job][m]
                # Compute makespan: max over m of f[m] + q[i][m]
                cmax_candidate = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax_candidate:
                        cmax_candidate = val
                if cmax_candidate < best_cmax:
                    best_cmax = cmax_candidate
                    best_pos = i
            current = current[:best_pos] + [job] + current[best_pos:]
        return current

    # Iterated Greedy with Taillard-accelerated reinsertion
    def iterated_greedy(init_perm, max_iter=60):
        current = init_perm[:]
        best = current[:]
        best_cmax = makespan(best)
        total_processing = sum(P)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 5 else N

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in sorted(indices, reverse=True)]
            for idx in sorted(indices, reverse=True):
                del current[idx]
            # Reconstruction: reinsert each removed job using Taillard acceleration
            for job in removed:
                e = forward_matrix(current)
                q = backward_matrix(current)
                best_pos = 0
                best_cmax_local = float('inf')
                for i in range(len(current)+1):
                    f = [0] * M
                    if i == 0:
                        f[0] = job_data[job][0]
                        for m in range(1, M):
                            f[m] = f[m-1] + job_data[job][m]
                    else:
                        f[0] = e[i-1][0] + job_data[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + job_data[job][m]
                cmax_candidate = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax_candidate:
                        cmax_candidate = val
                if cmax_candidate < best_cmax_local:
                    best_cmax_local = cmax_candidate
                    best_pos = i
                current = current[:best_pos] + [job] + current[best_pos:]
            # Acceptance criterion
            current_cmax = makespan(current)
            if current_cmax < best_cmax:
                best_cmax = current_cmax
                best = current[:]
            if current_cmax < makespan(init_perm):  # Always improve over last accept
                if random.random() < math.exp(-(current_cmax - makespan(init_perm)) / T):
                    init_perm = current[:]
            else:
                if random.random() < math.exp(-(current_cmax - makespan(init_perm)) / T):
                    init_perm = current[:]
        return best

    # Build initial solution and refine
    init_perm = construct_initial()
    # Quick lower bound check (optional, can skip for speed)
    # Refine with Iterated Greedy
    return iterated_greedy(init_perm, max_iter=50)

