def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job data for faster access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]

    # Makespan calculation
    def makespan(seq):
        t = [0] * m
        for job in seq:
            for mach in range(m):
                if mach == 0:
                    t[mach] += p[job][mach]
                else:
                    t[mach] = max(t[mach], t[mach-1]) + p[job][mach]
        return t[-1]

    # Taillard's forward-backward for insertion evaluation
    def evaluate_insertion(partial, job):
        k = len(partial)
        if k == 0:
            f = p[job][:]
            return f[-1]
        # forward matrix e for partial schedule
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            for mach in range(m):
                if mach == 0:
                    e[r][mach] = (e[r-1][mach] if r > 0 else 0) + p[job_r][mach]
                else:
                    e[r][mach] = max(e[r-1][mach] if r > 0 else 0, e[r][mach-1]) + p[job_r][mach]
        # backward tail matrix q
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            for mach in range(m-1, -1, -1):
                if mach == m-1:
                    q[r][mach] = q[r+1][mach] + p[job_r][mach]
                else:
                    q[r][mach] = max(q[r+1][mach], q[r][mach+1]) + p[job_r][mach]
        best_cmax = float('inf')
        best_pos = 0
        for i in range(k+1):
            # forward vector f for job at position i
            f = [0] * m
            prev_e = e[i-1] if i > 0 else [0] * m
            for mach in range(m):
                if mach == 0:
                    f[mach] = prev_e[mach] + p[job][mach]
                else:
                    f[mach] = max(f[mach-1], prev_e[mach]) + p[job][mach]
            # makespan if inserted at i
            cmax = 0
            for mach in range(m):
                val = f[mach] + q[i][mach]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_cmax, best_pos

    # NEH construction with Taillard acceleration
    def construct_neh():
        order = sorted(range(n), key=lambda i: total_p[i], reverse=True)
        seq = [order[0]]
        for idx in range(1, n):
            job = order[idx]
            _, pos = evaluate_insertion(seq, job)
            seq.insert(pos, job)
        return seq

    # Iterated Greedy
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        bc = makespan(current)
        bestc = bc
        total = sum(total_p)
        T = 0.5 * total / (10 * n * m) if n * m > 0 else 1e-6
        d = 3 if n < 30 else 4
        for _ in range(max_iter):
            # destruction
            if d >= n:
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(n), d)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(n) if i not in indices_set]
            # reconstruction
            for job in destroyed:
                _, pos = evaluate_insertion(remaining, job)
                remaining.insert(pos, job)
            current = remaining
            cc = makespan(current)
            if cc < bc:
                bc = cc
                current = current[:]
            if cc < bestc:
                bestc = cc
                best = current[:]
            elif cc > bc and random.random() >= math.exp(-(cc - bc) / T):
                current = current[:]  # revert
        return best

    # Main
    init_seq = construct_neh()
    # Quick lower bound check (optional, can be skipped for speed)
    # Refine with Iterated Greedy
    return iterated_greedy(init_seq, max_iter=50)

