        if k == 0:
            return 0
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = seq[r]
            pj = times[job]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e[k-1][M-1]

    # Insertion makespan using forward vector and precomputed tail
    def insertion_makespan(seq, job, pos):
        k = len(seq)
        f = [0] * M
        if pos == 0:
            f[0] = times[job][0]
            for m in range(1, M):
                f[m] = f[m-1] + times[job][m]
        else:
            prev = seq[pos-1]
            e_prev = [0] * M
            e_prev[0] = times[prev][0]
            for m in range(1, M):
                e_prev[m] = max(e_prev[m-1], times[prev][m]) + (e_prev[m-1] if m > 0 else 0)
            f[0] = e_prev[0] + times[job][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + times[job][m]
