            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, len(order)):
            job = order[idx]
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(seq) + 1):
                m = insertion_makespan(seq, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            seq.insert(best_pos, job)
