        pi_new = pi_D
        m_new = makespan(pi_new)
        # Acceptance criterion
        if m_new < makespan(pi):
            pi = pi_new
            if m_new < best_makespan:
                best_pi = pi_new[:]
                best_makespan = m_new
                no_improve = 0
            else:
                no_improve += 1
        else:
            delta = m_new - makespan(pi)
            if random.random() < math.exp(-delta / T):
                pi = pi_new
                no_improve += 1
            else:
                no_improve += 1

    return best_pi

