                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    down = q[r+1][m]
                    right = q[r][m+1]
                    q[r][m] = max(down, right) + times[job][m]
        return q

    def makespan_insert(e, q, job, pos):
        k = len(e)
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev = e[pos-1][0] if pos > 0 else 0
                f[m] = prev + times[job][m]
            else:
                left = f[m-1]
                up = e[pos-1][m] if pos > 0 else 0
                f[m] = max(left, up) + times[job][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_construct(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            job1, job2 = order[0], order[1]
            seq1 = [job1, job2]
            seq2 = [job2, job1]
            if makespan(seq1) <= makespan(seq2):
                seq = seq1
            else:
                seq = seq2
        for idx in range(2, len(order)):
            job = order[idx]
            partial = seq[:]
            e = compute_forward(partial)
            q = compute_backward(partial)
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(partial) + 1):
                cmax = makespan_insert(e, q, job, pos)
                if cmax < best_makespan:
                    best_makespan = cmax
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    current = neh_construct(sigma)
    best = current[:]
    best_makespan = makespan(current)

    for _ in range(max_iter):
        destroyed = current[:]
        random.shuffle(destroyed)
        removed = destroyed[:d]
        partial = destroyed[d:]
        R = removed[:]
        random.shuffle(R)
        for job in R:
            e = compute_forward(partial)
            q = compute_backward(partial)
            best_pos = 0
            best_makespan_val = float('inf')
            for pos in range(len(partial) + 1):
                cmax = makespan_insert(e, q, job, pos)
                if cmax < best_makespan_val:
                    best_makespan_val = cmax
                    best_pos = pos
            partial.insert(best_pos, job)
        current = partial
        current_makespan = makespan(current)
        if current_makespan < best_makespan:
            best_makespan = current_makespan
            best = current[:]
        if current_makespan < makespan(best):
            if random.random() < math.exp(-(current_makespan - makespan(best)) / T):
                best = current[:]
        if current_makespan < makespan(best):
            best = current[:]

    return best

