def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for fast access
    p_flat = [times[i][:] for i in range(N)]
    total_processing = sum(sum(row) for row in times)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            pj = p_flat[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[-1]

    def taillard_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        job0 = perm[0]
        p0 = p_flat[job0]
        e[0][0] = p0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + p0[m]
        for r in range(1, k):
            job = perm[r]
            pr = p_flat[job]
            er = e[r]
            er_prev = e[r-1]
            er[0] = er_prev[0] + pr[0]
            for m in range(1, M):
                er[m] = max(er_prev[m], er[m-1]) + pr[m]
        return e

    def taillard_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            pr = p_flat[job]
            qr = q[r]
            qr_next = q[r+1]
            qr[M-1] = qr_next[M-1] + pr[M-1]
            for m in range(M-2, -1, -1):
                qr[m] = max(qr_next[m], qr[m+1]) + pr[m]
        return q

    def insertion_cost_efficient(perm, job, pos):
        k = len(perm)
        if k == 0:
            e_im1 = [0] * M
        else:
            e = taillard_forward(perm)
            e_im1 = e[pos-1] if pos > 0 else [0] * M
        q = taillard_backward(perm)
        q_i = q[pos]
        pj = p_flat[job]
        f = [0] * M
        f[0] = e_im1[0] + pj[0]
        for m in range(1, M):
            f[m] = max(f[m-1], e_im1[m]) + pj[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q_i[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_taillard():
        P = [sum(p_flat[i]) for i in range(N)]
        order = sorted(range(N), key=lambda i: (-P[i], i))
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        perm = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_cost = float('inf')
            for pos in range(k+1):
                cost = insertion_cost_efficient(perm, job, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    def ig_metaheuristic(initial_perm, max_iter=60):
        current = initial_perm[:]
        best = initial_perm[:]
        best_makespan = makespan(best)
        d = 3 if N < 30 else 4
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        if T < 1e-6:
            T = 1e-6

        for _ in range(max_iter):
            if makespan(current) == best_makespan and best_makespan == 0:
                break
            indices = list(range(N))
            random.shuffle(indices)
            removed_indices = indices[:d]
            removed_indices.sort(reverse=True)
            R = []
            for idx in removed_indices:
                R.append(current.pop(idx))
            random.shuffle(R)
            for job in R:
                best_pos = 0
                best_cost = float('inf')
                for pos in range(len(current)+1):
                    cost = insertion_cost_efficient(current, job, pos)
                    if cost < best_cost:
                        best_cost = cost
                        best_pos = pos
                current.insert(best_pos, job)
            current_makespan = makespan(current)
            if current_makespan < makespan(best):
                best = current[:]
            if current_makespan < makespan(initial_perm):
                if random.random() < math.exp(-(current_makespan - makespan(initial_perm)) / T):
                    initial_perm = current[:]
            else:
                initial_perm = current[:]
        return best

    initial_perm = neh_taillard()
    if N <= 20:
        return initial_perm
    refined_perm = ig_metaheuristic(initial_perm, max_iter=50)
    return refined_perm

