def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    P = [0] * N
    for i in range(N):
        row = times[i]
        s = 0
        for j in range(M):
            s += row[j]
        P[i] = s
        total_processing += s

    order = list(range(N))
    order.sort(key=lambda i: P[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            row = times[job]
            t[0] += row[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + row[m]
        return t[-1]

    def compute_forward(seq):
        k = len(seq)
        if k == 0:
            return [[0]*M]
        e = [[0]*M for _ in range(k)]
        row0 = times[seq[0]]
        e[0][0] = row0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + row0[m]
        for r in range(1, k):
            row = times[seq[r]]
            er = e[r]
            er_1 = e[r-1]
            er[0] = er_1[0] + row[0]
            for m in range(1, M):
                er[m] = max(er_1[m], er[m-1]) + row[m]
        return e

    def compute_backward(seq):
        k = len(seq)
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            row = times[seq[r]]
            qr = q[r]
            qr1 = q[r+1]
            qr[M-1] = qr1[M-1] + row[M-1]
            for m in range(M-2, -1, -1):
                qr[m] = max(qr1[m], qr[m+1]) + row[m]
        return q

    def insertion_cost(e, q, job, pos):
        row = times[job]
        f = [0] * M
        if pos == 0:
            f[0] = row[0]
        else:
            e_prev = e[pos-1]
            f[0] = e_prev[0] + row[0]
        for m in range(1, M):
            if pos == 0:
                f[m] = f[m-1] + row[m]
            else:
                e_prev = e[pos-1]
                f[m] = max(f[m-1], e_prev[m]) + row[m]
        q_pos = q[pos]
        cmax = 0
        for m in range(M):
            val = f[m] + q_pos[m]
            if val > cmax:
                cmax = val
        return cmax

    def NEH_with_Taillard(job_order):
        if not job_order:
            return []
        seq = [job_order[0]]
        for k in range(1, len(job_order)):
            job = job_order[k]
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_cost = insertion_cost(e, q, job, 0)
            for pos in range(1, k+1):
                cost = insertion_cost(e, q, job, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    def destroy(sequence, d):
        if d <= 0 or d >= len(sequence):
            return [], sequence[:]
        indices = random.sample(range(len(sequence)), d)
        indices_set = set(indices)
        R = [sequence[i] for i in indices]
        pi_D = [sequence[i] for i in range(len(sequence)) if i not in indices_set]
        return R, pi_D

    def reconstruct(pi_D, R):
        seq = pi_D[:]
        for job in R:
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_cost = insertion_cost(e, q, job, 0)
            for pos in range(1, len(seq)+1):
                cost = insertion_cost(e, q, job, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    pi = NEH_with_Taillard(order)
    pi_star = pi[:]
    C_star = makespan(pi_star)

    LB = 0
    for m in range(M):
        min_pre = min((sum(times[i][:m]) for i in range(N)), default=0)
        min_suf = min((sum(times[i][m+1:]) for i in range(N)), default=0)
        sum_m = sum(times[i][m] for i in range(N))
        LB_m = min_pre + sum_m + min_suf
        if LB_m > LB:
            LB = LB_m
    if C_star == LB:
        return pi_star

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-9:
        T = 1e-9

    max_iter = 60
    for _ in range(max_iter):
        d = 3 if random.random() < 0.5 else 4
        if d > N:
            d = N
        R, pi_D = destroy(pi, d)
        pi_new = reconstruct(pi_D, R)
        C_new = makespan(pi_new)
        if C_new < C_star:
            pi_star = pi_new[:]
            C_star = C_new
            if C_star == LB:
                break
        if C_new < makespan(pi):
            pi = pi_new[:]
        else:
            delta = C_new - makespan(pi)
            if random.random() < math.exp(-delta / T):
                pi = pi_new[:]
    return pi_star

