def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for NEH priority
    total_times = [sum(job) for job in times]
    jobs_sorted = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Precompute total processing sum for temperature
    total_processing = sum(total_times)

    # Makespan evaluation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_times[m]
        return t[-1]

    # Taillard-accelerated NEH construction
    def construct_neh():
        if len(jobs_sorted) < 2:
            return jobs_sorted[:]
        # Initial two jobs
        seq0 = [jobs_sorted[0], jobs_sorted[1]]
        seq1 = [jobs_sorted[1], jobs_sorted[0]]
        current_seq = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        # Iteratively insert remaining jobs
        for idx in range(2, N):
            job = jobs_sorted[idx]
            k = len(current_seq)
            # Forward matrix e: completion times of current_seq
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = current_seq[r]
                job_r_times = times[job_r]
                if r == 0:
                    e[0][0] = job_r_times[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_r_times[m]
                else:
                    e[r][0] = e[r-1][0] + job_r_times[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r_times[m]
            # Backward matrix q: tail times from position r
            q = [[0] * M for _ in range(k+1)]  # q[k][:] = 0
            for r in range(k-1, -1, -1):
                job_r = current_seq[r]
                job_r_times = times[job_r]
                q[r][M-1] = q[r+1][M-1] + job_r_times[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r_times[m]
            # Evaluate insertion positions
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Forward pass for job at position i
                f = [0] * M
                if i == 0:
                    f[0] = job_times[0]
                    for m in range(1, M):
                        f[m] = f[m-1] + job_times[m]
                else:
                    prev = e[i-1]
                    f[0] = prev[0] + job_times[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev[m]) + job_times[m]
                # Compute makespan if job inserted at i
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            current_seq.insert(best_pos, job)
        return current_seq

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(initial_seq):
        current_seq = initial_seq[:]
        best_seq = current_seq[:]
        best_mk = makespan(best_seq)
        # Temperature parameter
        T = 0.5 * total_processing / (10 * N * M)
        if T < 1e-6:
            T = 1e-6
        destruction_size = 3 if N > 5 else N
        max_iter = 60  # calibrated for <50ms
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            if destruction_size == 0:
                destroyed = []
            else:
                indices = random.sample(range(N), destruction_size)
                indices.sort(reverse=True)
                destroyed = [current_seq.pop(i) for i in indices]
            # Reconstruction: reinsert using NEH insertion with Taillard
            for job in destroyed:
                k = len(current_seq)
                if k == 0:
                    current_seq.append(job)
                    continue
                # Forward matrix e
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    job_r = current_seq[r]
                    job_r_times = times[job_r]
                    if r == 0:
                        e[0][0] = job_r_times[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + job_r_times[m]
                    else:
                        e[r][0] = e[r-1][0] + job_r_times[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r_times[m]
                # Backward matrix q
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = current_seq[r]
                    job_r_times = times[job_r]
                    q[r][M-1] = q[r+1][M-1] + job_r_times[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r_times[m]
                # Evaluate insertion positions
                best_pos = 0
                best_mk_ins = float('inf')
                job_times = times[job]
                for i in range(k+1):
                    # Forward pass for job at position i
                    f = [0] * M
                    if i == 0:
                        f[0] = job_times[0]
                        for m in range(1, M):
                            f[m] = f[m-1] + job_times[m]
                    else:
                        prev = e[i-1]
                        f[0] = prev[0] + job_times[0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], prev[m]) + job_times[m]
                    # Compute makespan if job inserted at i
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_ins:
                        best_mk_ins = mk
                        best_pos = i
                current_seq.insert(best_pos, job)
            # Acceptance criterion
            new_mk = makespan(current_seq)
            if new_mk < makespan(best_seq):
                best_seq = current_seq[:]
            if new_mk < makespan(initial_seq):
                # Always accept if better than current
                pass
            else:
                # Metropolis acceptance
                delta = new_mk - makespan(initial_seq)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    initial_seq = current_seq[:]
                else:
                    # Revert to previous state
                    current_seq = initial_seq[:]
        return best_seq

    # Build initial solution and refine
    initial_seq = construct_neh()
    return iterated_greedy(initial_seq)

