def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if N == 1:
        return [0]
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data as flat lists for faster access
    p = [times[i][:] for i in range(N)]
    total_p = [sum(p[i]) for i in range(N)]
    total_processing = sum(total_p)

    # Compute lower bound (Taillard's machine bottleneck)
    lb = 0
    for m in range(M):
        sum_m = sum(p[i][m] for i in range(N))
        min_prefix = min(sum(p[i][:m]) for i in range(N)) if m > 0 else 0
        min_suffix = min(sum(p[i][m+1:]) for i in range(N)) if m < M-1 else 0
        lb_m = min_prefix + sum_m + min_suffix
        if lb_m > lb:
            lb = lb_m

    # NEH with Taillard acceleration
    def makespan_from_perm(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[-1]

    def makespan_neh_insert(perm, job_idx):
        k = len(perm)
        if k == 0:
            return p[job_idx][0] if M > 0 else 0
        # Forward matrix e: completion times of current perm
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            if r == 0:
                e[0][0] = p[job][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[job][m]
            else:
                e[r][0] = e[r-1][0] + p[job][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job][m]
        # Backward matrix q: tail times
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            if r == k-1:
                for m in range(M):
                    q[r][m] = p[job][m]
            else:
                q[r][M-1] = q[r+1][M-1] + p[job][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]
        best_makespan = float('inf')
        best_pos = 0
        for i in range(k+1):
            # Compute forward vector f for inserting job_idx at position i
            f = [0] * M
            if i == 0:
                prev = [0] * M
            else:
                prev = e[i-1]
            f[0] = prev[0] + p[job_idx][0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev[m]) + p[job_idx][m]
            # Compute makespan: max_m (f[m] + q[i][m])
            ms = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > ms:
                    ms = val
            if ms < best_makespan:
                best_makespan = ms
                best_pos = i
        return best_makespan, best_pos

    # Initial NEH construction
    job_order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
    perm = [job_order[0]]
    for idx in range(1, N):
        job = job_order[idx]
        _, pos = makespan_neh_insert(perm, job)
        perm.insert(pos, job)

