        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[M-1]

    # Function to compute makespan using Taillard acceleration for insertion
    def makespan_with_insertion(base_perm, job, pos):
        k = len(base_perm)
        if k == 0:
            return p[job][0] if M == 1 else _makespan_single_job(job)
        # Forward matrix e for base_perm[0:pos]
        e = [[0] * M for _ in range(pos)]
        for r in range(pos):
            job_r = base_perm[r]
            if r == 0:
                e[0][0] = p[job_r][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[job_r][m]
            else:
                e[r][0] = e[r-1][0] + p[job_r][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]
        # Backward matrix q for base_perm[pos:k]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, pos-1, -1):
