            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + p[job][m]
        # Compute makespan: max over m of f[m] + q[pos][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
