        p2 = [sum(p[i][M-l:]) for i in range(N)]
        # Johnson's rule: job i before j if min(p1[i], p2[j]) < min(p1[j], p2[i])
        left = []
        right = []
        jobs = list(range(N))
        while jobs:
            # Find job with minimum min(p1[i], p2[i])
            min_val = float('inf')
            sel = -1
            for i in jobs:
                v = min(p1[i], p2[i])
                if v < min_val:
                    min_val = v
                    sel = i
            if p1[sel] <= p2[sel]:
                left.append(sel)
            else:
                right.append(sel)
            jobs.remove(sel)
