        # Reconstruction: reinsert removed jobs one by one using Taillard acceleration
        for job in removed_jobs:
            best_pos = 0
            best_insert_makespan = float('inf')
            # Evaluate all possible insertion positions
            for pos in range(len(destroyed_perm) + 1):
                m = makespan_with_insertion(destroyed_perm, job, pos)
                if m < best_insert_makespan:
                    best_insert_makespan = m
                    best_pos = pos
            # Insert job at best_pos
            destroyed_perm.insert(best_pos, job)
        new_perm = destroyed_perm
        new_makespan = makespan(new_perm)
        # Acceptance criterion
        if new_makespan < current_makespan or random.random() < math.exp(-(new_makespan - current_makespan) / T):
            current_perm = new_perm
            current_makespan = new_makespan
            if new_makespan < best_makespan_ig:
                best_perm_ig = new_perm[:]
                best_makespan_ig = new_makespan

