def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten times for faster access
    p = [times[i][:] for i in range(N)]

    # Precompute total processing times and slope indices
    total = [sum(p[i]) for i in range(N)]
    slope = [sum((2 * j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]

    # Determine if processing times are bimodal
    flat_times = [t for job in p for t in job]
    if len(flat_times) > 1:
        mean_val = sum(flat_times) / len(flat_times)
        variance = sum((x - mean_val) ** 2 for x in flat_times) / len(flat_times)
        std_dev = math.sqrt(variance) if variance > 0 else 0
        bimodal = std_dev > mean_val * 0.5
    else:
        bimodal = False

    # Create job order based on bimodality
    if bimodal:
        # Separate anchor (large) and filler (small) jobs
        median_total = sorted(total)[N // 2]
        anchors = [i for i in range(N) if total[i] >= median_total]
        fillers = [i for i in range(N) if total[i] < median_total]
        # Sort anchors by total descending, fillers by slope descending
        anchors.sort(key=lambda i: total[i], reverse=True)
        fillers.sort(key=lambda i: slope[i], reverse=True)
        # Interleave: anchor, filler, anchor, filler, ...
        order = []
        a_idx, f_idx = 0, 0
        while a_idx < len(anchors) or f_idx < len(fillers):
            if a_idx < len(anchors):
                order.append(anchors[a_idx])
                a_idx += 1
            if f_idx < len(fillers):
                order.append(fillers[f_idx])
                f_idx += 1
    else:
        # Use slope index as primary, total as tie-breaker
        order = sorted(range(N), key=lambda i: (slope[i], total[i]), reverse=True)

    # Makespan calculation using Taillard's forward pass
    def makespan(seq):
        if not seq:
            return 0
        e_prev = [0] * M
        for job in seq:
            e_curr = [0] * M
            for m in range(M):
                if m == 0:
                    e_curr[m] = e_prev[m] + p[job][m]
                else:
                    e_curr[m] = max(e_prev[m], e_curr[m-1]) + p[job][m]
            e_prev = e_curr
        return e_prev[M-1]

    # NEH insertion with Taillard acceleration for a given job order
    def neh_construct(job_order):
        if not job_order:
            return []
        # Start with first job
        seq = [job_order[0]]
        best_seq = seq[:]
        best_makespan = makespan(seq)
        # Try swapping first two jobs
        if len(job_order) > 1:
            seq2 = [job_order[1], job_order[0]]
            m2 = makespan(seq2)
            if m2 < best_makespan:
                best_seq = seq2[:]
                best_makespan = m2
                seq = seq2
        # Insert remaining jobs
        for k in range(2, len(job_order)):
            job = job_order[k]
            # Build forward matrix e for current seq (length k)
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = seq[r]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job_r][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job_r][m]
            # Build backward matrix q for current seq (length k)
            q = [[0] * M for _ in range(k+1)]  # q[k][:] = 0
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + p[job_r][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
            # Evaluate insertion positions
            best_pos = 0
            best_m = float('inf')
            for i in range(k+1):  # insert before index i
                # Compute forward vector f for job at position i
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev_e = e[i-1][m] if i > 0 else 0
                        f[m] = prev_e + p[job][m]
                    else:
                        f[m] = max(f[m-1], e[i-1][m] if i > 0 else 0) + p[job][m]
                # Compute makespan if inserted at i
                m_val = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > m_val:
                        m_val = val
                if m_val < best_m:
                    best_m = m_val
                    best_pos = i
            # Insert job at best_pos
            seq.insert(best_pos, job)
            if best_m < best_makespan:
                best_makespan = best_m
                best_seq = seq[:]
        return best_seq

    # Initial solution via NEH
    current = neh_construct(order)
    best = current[:]
    best_makespan = makespan(current)

    # Iterated Greedy parameters
    total_processing = sum(total)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 5 else max(1, N // 2)
    max_iter = 60  # Calibrated for <50ms

    # Iterated Greedy loop
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            removed = current[:]
        else:
            indices = random.sample(range(N), d)
            indices.sort(reverse=True)
            removed = [current.pop(i) for i in indices]
            destroyed = current
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            # Build forward matrix e for current destroyed (length L)
            L = len(destroyed)
            if L == 0:
                destroyed.append(job)
                continue
            e = [[0] * M for _ in range(L)]
            for r in range(L):
                job_r = destroyed[r]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job_r][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job_r][m]
            # Build backward matrix q for current destroyed (length L)
            q = [[0] * M for _ in range(L+1)]  # q[L][:] = 0
            for r in range(L-1, -1, -1):
                job_r = destroyed[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + p[job_r][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
            # Evaluate insertion positions
            best_pos = 0
            best_m = float('inf')
            for i in range(L+1):  # insert before index i
                # Compute forward vector f for job at position i
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev_e = e[i-1][m] if i > 0 else 0
                        f[m] = prev_e + p[job][m]
                    else:
                        f[m] = max(f[m-1], e[i-1][m] if i > 0 else 0) + p[job][m]
                # Compute makespan if inserted at i
                m_val = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > m_val:
                        m_val = val
                if m_val < best_m:
                    best_m = m_val
                    best_pos = i
            # Insert job at best_pos
            destroyed.insert(best_pos, job)
        current = destroyed
        current_makespan = makespan(current)
        # Acceptance criterion
        if current_makespan < makespan(best):
            best = current[:]
            best_makespan = current_makespan
        if current_makespan < makespan(current):
            current = current[:]
        else:
            delta = current_makespan - makespan(current)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current = current[:]

    return best

