        new_partial = partial[:best_pos] + [job] + partial[best_pos:]
        return new_partial, best_mk

    # NEH construction with Taillard acceleration
    partial = []
    for idx in idxs:
        if not partial:
            partial = [idx]
            continue
        e = compute_forward(partial)
        q = compute_backward(partial)
        partial, _ = insert_job_accelerated(partial, idx, e, q)
    pi = partial[:]
    pi_star = pi[:]
    C_star = makespan(pi)
    C_current = C_star

    # Iterated Greedy
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-6:
        T = 1e-6
    max_iter = 60
    d = 3 if N > 20 else 2
    if N > 80:
        d = 4
    if N > 100:
        d = 5

    for _ in range(max_iter):
        # Destruction
        if d >= N:
            pi_D = []
            R = pi[:]
        else:
            R = random.sample(pi, d)
            pi_D = [x for x in pi if x not in R]
        # Reconstruction
        pi_new = pi_D[:]
        random.shuffle(R)
        for job in R:
            if not pi_new:
                pi_new = [job]
                continue
            e = compute_forward(pi_new)
            q = compute_backward(pi_new)
            pi_new, _ = insert_job_accelerated(pi_new, job, e, q)
        C_new = makespan(pi_new)
        if C_new < C_current:
            pi = pi_new
            C_current = C_new
            if C_new < C_star:
                pi_star = pi_new
                C_star = C_new
        else:
            if random.random() < math.exp(-(C_new - C_current) / T):
                pi = pi_new
                C_current = C_new

    return pi_star

