def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data and totals
    P = [sum(job) for job in times]
    order = list(range(N))
    order.sort(key=lambda i: P[i], reverse=True)

    # Makespan evaluation for a given permutation
    def makespan(seq):
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Taillard acceleration: forward and backward matrices
    def forward_matrix(seq):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = seq[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][m] = prev + times[job][m]
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + times[job][m]
        return e

    def backward_matrix(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    down = q[r][m+1]
                    right = q[r+1][m]
                    q[r][m] = max(down, right) + times[job][m]
        return q

    # Evaluate makespan for inserting job x at position i in seq (length k)
    def insertion_makespan(seq, x, i):
        k = len(seq)
        if k == 0:
            return times[x][0] if M == 1 else _makespan_single_job(x)
        e = forward_matrix(seq)
        q = backward_matrix(seq)
        f = [0] * M
        im1 = i-1
        for m in range(M):
            if m == 0:
                prev_e = e[im1][0] if im1 >= 0 else 0
                f[m] = prev_e + times[x][m]
            else:
                left = f[m-1]
                up = e[im1][m] if im1 >= 0 else 0
                f[m] = max(left, up) + times[x][m]
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    def _makespan_single_job(job):
        t = 0
        for m in range(M):
            t += times[job][m]
        return t

    # Beam search with width K=2
    K = 2
    beams = [[]]
    for idx in order:
        new_beams = []
        for seq in beams:
            for pos in range(len(seq) + 1):
                new_seq = seq[:pos] + [idx] + seq[pos:]
                new_beams.append(new_seq)
        # Prune to top K by makespan
        new_beams.sort(key=lambda s: makespan(s))
        beams = new_beams[:K]
    best_seq = beams[0]
    best_makespan = makespan(best_seq)

    # Iterated Greedy refinement
    T_param = 0.5
    total_processing = sum(P)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 5 else max(1, N // 2)
    current = best_seq[:]
    current_makespan = best_makespan
    pi_star = current[:]
    pi_star_makespan = current_makespan
    max_iter = 50
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        remaining = [current[i] for i in range(N) if i not in indices]
        # Reconstruction: reinsert each removed job using NEH with Taillard
        for job in removed:
            best_pos = 0
            best_val = float('inf')
            for pos in range(len(remaining) + 1):
                val = insertion_makespan(remaining, job, pos)
                if val < best_val:
                    best_val = val
                    best_pos = pos
            remaining = remaining[:best_pos] + [job] + remaining[best_pos:]
        current = remaining
        current_makespan = makespan(current)
        if current_makespan < pi_star_makespan:
            pi_star = current[:]
            pi_star_makespan = current_makespan
        # Acceptance criterion
        if current_makespan < best_makespan:
            best_makespan = current_makespan
            best_seq = current[:]
        elif random.random() < math.exp(-(current_makespan - best_makespan) / T):
            best_seq = current[:]
            best_makespan = current_makespan
        else:
            current = pi_star[:]
            current_makespan = pi_star_makespan

    return best_seq

