        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    P = [0] * N
    for i in range(N):
        row = times[i]
        s = 0
        for j in range(M):
            s += row[j]
            total_processing += row[j]
        P[i] = s

    # Slope index for tie-breaking
    S = [0] * N
    for i in range(N):
        row = times[i]
        s_val = 0
        for j in range(M):
            s_val += (2 * j - M + 1) * row[j]
        S[i] = s_val

    jobs = list(range(N))
    jobs.sort(key=lambda i: (-P[i], -S[i]))

    # Makespan function
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for idx in perm:
            job = times[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    # Taillard-based insertion makespan for a candidate job at position i
    def insertion_makespan(forward, backward, job_idx, pos):
        job = times[job_idx]
        f = [0] * M
        if pos == 0:
            for m in range(M):
                f[m] = job[m]
        else:
            f[0] = forward[pos-1][0] + job[0]
            for m in range(1, M):
                f[m] = max(f[m-1], forward[pos-1][m]) + job[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + backward[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    perm = [jobs[0]]
    if N > 1:
        # Evaluate first two jobs
        seq1 = [jobs[0], jobs[1]]
        seq2 = [jobs[1], jobs[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2

        # Preallocate matrices
        forward = [[0] * M for _ in range(N)]
        backward = [[0] * M for _ in range(N+1)]

        for k in range(2, N):
            job_idx = jobs[k]
            # Compute forward matrix for current perm (length k)
            for r in range(k):
                job_r = times[perm[r]]
                if r == 0:
                    forward[r][0] = job_r[0]
                    for m in range(1, M):
                        forward[r][m] = max(forward[r][m-1], forward[r-1][m] if r>0 else 0) + job_r[m]
                else:
                    forward[r][0] = forward[r-1][0] + job_r[0]
                    for m in range(1, M):
                        forward[r][m] = max(forward[r-1][m], forward[r][m-1]) + job_r[m]

            # Compute backward matrix for current perm (length k)
            for m in range(M):
                backward[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = times[perm[r]]
                backward[r][M-1] = backward[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    backward[r][m] = max(backward[r+1][m], backward[r][m+1]) + job_r[m]

            # Find best insertion position
            best_pos = 0
            best_makespan = insertion_makespan(forward, backward, job_idx, 0)
            for pos in range(1, k+1):
                mk = insertion_makespan(forward, backward, job_idx, pos)
                if mk < best_makespan:
                    best_makespan = mk
                    best_pos = pos
            perm.insert(best_pos, job_idx)

    # Iterated Greedy refinement
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    if d < 2:
        d = 2

