                if makespan(seq1) <= makespan(seq2):
                    perm_D = seq1
                else:
                    perm_D = seq2

                # Preallocate for reconstruction
                forward_D = [[0] * M for _ in range(len(current_D))]
                backward_D = [[0] * M for _ in range(len(current_D)+1)]

                for k in range(2, len(current_D)):
                    job_idx = current_D[k]
                    for r in range(k):
                        job_r = times[perm_D[r]]
                        if r == 0:
                            forward_D[r][0] = job_r[0]
                            for m in range(1, M):
                                forward_D[r][m] = max(forward_D[r][m-1], forward_D[r-1][m] if r>0 else 0) + job_r[m]
                        else:
                            forward_D[r][0] = forward_D[r-1][0] + job_r[0]
                            for m in range(1, M):
                                forward_D[r][m] = max(forward_D[r-1][m], forward_D[r][m-1]) + job_r[m]

                    for m in range(M):
                        backward_D[k][m] = 0
                    for r in range(k-1, -1, -1):
                        job_r = times[perm_D[r]]
                        backward_D[r][M-1] = backward_D[r+1][M-1] + job_r[M-1]
                        for m in range(M-2, -1, -1):
                            backward_D[r][m] = max(backward_D[r+1][m], backward_D[r][m+1]) + job_r[m]

                    best_pos = 0
                    best_mk = insertion_makespan(forward_D, backward_D, job_idx, 0)
                    for pos in range(1, k+1):
                        mk = insertion_makespan(forward_D, backward_D, job_idx, pos)
                        if mk < best_mk:
                            best_mk = mk
                            best_pos = pos
                    perm_D.insert(best_pos, job_idx)

        # Reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job_idx in removed:
            if not perm_D:
                perm_D = [job_idx]
            else:
                # Reuse forward/backward for current perm_D
                k_len = len(perm_D)
                forward_ins = [[0] * M for _ in range(k_len)]
                backward_ins = [[0] * M for _ in range(k_len+1)]

                for r in range(k_len):
                    job_r = times[perm_D[r]]
                    if r == 0:
                        forward_ins[r][0] = job_r[0]
                        for m in range(1, M):
                            forward_ins[r][m] = max(forward_ins[r][m-1], forward_ins[r-1][m] if r>0 else 0) + job_r[m]
                    else:
                        forward_ins[r][0] = forward_ins[r-1][0] + job_r[0]
                        for m in range(1, M):
                            forward_ins[r][m] = max(forward_ins[r-1][m], forward_ins[r][m-1]) + job_r[m]

                for m in range(M):
                    backward_ins[k_len][m] = 0
                for r in range(k_len-1, -1, -1):
                    job_r = times[perm_D[r]]
                    backward_ins[r][M-1] = backward_ins[r+1][M-1] + job_r[M-1]
                    for m in range(M-2, -1, -1):
                        backward_ins[r][m] = max(backward_ins[r+1][m], backward_ins[r][m+1]) + job_r[m]

                best_pos = 0
                best_mk = insertion_makespan(forward_ins, backward_ins, job_idx, 0)
                for pos in range(1, k_len+1):
                    mk = insertion_makespan(forward_ins, backward_ins, job_idx, pos)
                    if mk < best_mk:
                        best_mk = mk
                        best_pos = pos
                perm_D.insert(best_pos, job_idx)

        current = perm_D
        curr_mk = makespan(current)
        if curr_mk < best_makespan:
            best_makespan = curr_mk
            best = current[:]

        # Acceptance criterion
        if curr_mk < makespan(perm):
            perm = current[:]
        else:
            diff = curr_mk - makespan(perm)
            if diff < 0 or random.random() < math.exp(-diff / T):
                perm = current[:]

    return best

