def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices for alternative orderings
    total_times = [sum(job) for job in times]
    slope_indices = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Try multiple priority orderings to increase robustness
    orderings = [
        sorted(range(N), key=lambda i: total_times[i], reverse=True),  # NEH
        sorted(range(N), key=lambda i: slope_indices[i], reverse=True),  # Palmer
        list(range(N)),  # Natural order
        sorted(range(N), key=lambda i: total_times[i]),  # Ascending total time
    ]

    best_seq = None
    best_makespan = float('inf')

    # Precompute total processing sum for temperature in IG
    total_processing_sum = sum(total_times)

    for order in orderings:
        # Build initial sequence using accelerated NEH with this ordering
        seq = [order[0]]
        if N > 1:
            # Evaluate both orders of first two jobs
            seq1 = [order[0], order[1]]
            seq2 = [order[1], order[0]]
            makespan1 = _makespan(seq1, times)
            makespan2 = _makespan(seq2, times)
            seq = seq1 if makespan1 <= makespan2 else seq2

            # Preallocate matrices for Taillard acceleration
            e = [[0] * M for _ in range(N)]
            q = [[0] * M for _ in range(N + 1)]

            # Greedy insertion loop with Taillard acceleration
            for k in range(2, N):
                job_idx = order[k]
                job = times[job_idx]

                # Forward pass: compute e[0..k-1][0..M-1]
                for r in range(k):
                    if r == 0:
                        e[0][0] = job[0] if r == 0 else e[r-1][0] + times[seq[r]][0]
                        for m in range(1, M):
                            e[0][m] = max(e[0][m-1], 0) + times[seq[0]][m]
                    else:
                        e[r][0] = e[r-1][0] + times[seq[r]][0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + times[seq[r]][m]

                # Backward pass: compute q[0..k][0..M-1]
                for m in range(M):
                    q[k][m] = 0
                for r in range(k-1, -1, -1):
                    q[r][M-1] = q[r+1][M-1] + times[seq[r]][M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[seq[r]][m]

                # Find best insertion position for current job
                best_pos = 0
                best_makespan_k = float('inf')
                for i in range(k+1):
                    # Compute forward vector f for inserting job at position i
                    if i == 0:
                        f0 = job[0]
                        fm = [f0]
                        for m in range(1, M):
                            fm.append(max(fm[m-1], 0) + job[m])
                    else:
                        f0 = e[i-1][0] + job[0]
                        fm = [f0]
                        for m in range(1, M):
                            fm.append(max(fm[m-1], e[i-1][m]) + job[m])

                    # Compute makespan if job inserted at position i
                    makespan_i = 0
                    for m in range(M):
                        val = fm[m] + q[i][m]
                        if val > makespan_i:
                            makespan_i = val
                    if makespan_i < best_makespan_k:
                        best_makespan_k = makespan_i
                        best_pos = i

                # Insert job at best position
                seq.insert(best_pos, job_idx)

        # Evaluate makespan of initial sequence
        makespan_seq = _makespan(seq, times)
        if makespan_seq < best_makespan:
            best_makespan = makespan_seq
            best_seq = seq[:]

        # If we hit the lower bound, we can stop early
        lb = _taillard_lower_bound(times)
        if best_makespan == lb:
            return best_seq

        # Apply Iterated Greedy refinement
        refined_seq, refined_makespan = _iterated_greedy(
            seq, times, best_makespan, total_processing_sum, N, M
        )
        if refined_makespan < best_makespan:
            best_makespan = refined_makespan
            best_seq = refined_seq[:]
            if best_makespan == lb:
                return best_seq

    return best_seq

def _makespan(seq, times):
    if not seq:
        return 0
    M = len(times[0])
    t = [0] * M
    for job_idx in seq:
        job = times[job_idx]
        t[0] += job[0]
        for m in range(1, M):
            t[m] = max(t[m-1], t[m]) + job[m]
    return t[-1]

def _taillard_lower_bound(times):
    N = len(times)
    if N == 0:
        return 0
    M = len(times[0])
    lb = 0
    for m in range(M):
        sum_m = sum(times[i][m] for i in range(N))
        min_before = min((sum(times[i][l] for l in range(m)) for i in range(N)), default=0)
        min_after = min((sum(times[i][l] for l in range(m+1, M)) for i in range(N)), default=0)
        lb_m = min_before + sum_m + min_after
        if lb_m > lb:
            lb = lb_m
    return lb

def _iterated_greedy(init_seq, times, current_best_makespan, total_processing_sum, N, M):
    # Parameters for IG
    T_param = 0.5
    T = T_param * total_processing_sum / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N  # destruction size
    max_iter = 60  # calibrated to stay within time budget

    seq = init_seq[:]
    best_seq = seq[:]
    best_makespan = _makespan(seq, times)

    # Preallocate matrices for Taillard acceleration in reconstruction
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N + 1)]

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d == 0:
            destroyed = []
            remaining = seq[:]
        else:
            positions = random.sample(range(N), d)
            positions.sort(reverse=True)
            destroyed = []
            remaining = seq[:]
            for pos in positions:
                destroyed.append(remaining.pop(pos))

        # Reconstruction: reinsert destroyed jobs one by one using NEH with Taillard
        for job_idx in destroyed:
            job = times[job_idx]
            k = len(remaining)

            # Forward pass for current remaining sequence
            for r in range(k):
                if r == 0:
                    e[0][0] = job[0] if k == 0 else times[remaining[0]][0]
                    for m in range(1, M):
                        e[0][m] = max(e[0][m-1], 0) + times[remaining[0]][m]
                else:
                    e[r][0] = e[r-1][0] + times[remaining[r]][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + times[remaining[r]][m]

            # Backward pass
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                q[r][M-1] = q[r+1][M-1] + times[remaining[r]][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[remaining[r]][m]

            # Find best insertion position
            best_pos = 0
            best_makespan_k = float('inf')
            for i in range(k+1):
                if i == 0:
                    f0 = job[0]
                    fm = [f0]
                    for m in range(1, M):
                        fm.append(max(fm[m-1], 0) + job[m])
                else:
                    f0 = e[i-1][0] + job[0]
                    fm = [f0]
                    for m in range(1, M):
                        fm.append(max(fm[m-1], e[i-1][m]) + job[m])

                makespan_i = 0
                for m in range(M):
                    val = fm[m] + q[i][m]
                    if val > makespan_i:
                        makespan_i = val
                if makespan_i < best_makespan_k:
                    best_makespan_k = makespan_i
                    best_pos = i

            remaining.insert(best_pos, job_idx)

        # Evaluate new sequence
        new_makespan = _makespan(remaining, times)
        if new_makespan < best_makespan:
            best_makespan = new_makespan
            best_seq = remaining[:]

        # Acceptance criterion
        if new_makespan < _makespan(seq, times) or random.random() < math.exp(-(new_makespan - _makespan(seq, times)) / T):
            seq = remaining[:]

    return best_seq, best_makespan

