def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_p = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_p / (10 * N * M) if N * M > 0 else 1.0

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_t = times[perm[r]]
            if r == 0:
                e[0][0] = job_t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_t[m]
            else:
                e[r][0] = e[r-1][0] + job_t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
        return e

    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_t = times[perm[r]]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        return q

    def insert_job(perm, job, e, q):
        k = len(perm)
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = job[0]
            else:
                f0 = e[i-1][0] + job[0]
            f = [0] * M
            f[0] = f0
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + job[m] if i > 0 else max(f[m-1], 0) + job[m]
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        perm.insert(best_pos, job)
        return best_mk

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: (-P[i], i))
    perm = []
    for idx in order:
        job = times[idx]
        if not perm:
            perm.append(idx)
        else:
            e = compute_forward(perm)
            q = compute_backward(perm)
            insert_job(perm, idx, e, q)
    best_perm = perm[:]
    best_mk = makespan(best_perm)

    def destruction(perm, d):
        indices = random.sample(range(len(perm)), d)
        removed = [perm[i] for i in indices]
        remaining = [perm[i] for i in range(len(perm)) if i not in indices]
        return remaining, removed

    max_iter = 60
    for _ in range(max_iter):
        current_perm = best_perm[:]
        d = 3 if N > 20 else 2
        if d > N:
            d = N
        remaining, removed = destruction(current_perm, d)
        e = compute_forward(remaining)
        q = compute_backward(remaining)
        for job_idx in removed:
            insert_job(remaining, job_idx, e, q)
            e = compute_forward(remaining)
            q = compute_backward(remaining)
        mk = makespan(remaining)
        if mk < best_mk:
            best_mk = mk
            best_perm = remaining[:]
        elif mk < makespan(current_perm):
            if random.random() < math.exp(-(mk - makespan(current_perm)) / T):
                best_perm = remaining[:]
                best_mk = mk
    return best_perm

