            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_times[m]
        return t[-1]

    def makespan_with_insertion(perm, job, e, q, k):
        if k == 0:
            f0 = job[0]
            f = [f0]
            for m in range(1, M):
                f.append(max(f[m-1], 0) + job[m])
            return max(f[m] + q[0][m] for m in range(M))
        best_cmax = float('inf')
        for i in range(k + 1):
            if i == 0:
                f0 = job[0]
            else:
                f0 = e[i-1][0] + job[0]
            f = [f0]
            for m in range(1, M):
                f.append(max(f[m-1], e[i-1][m]) + job[m])
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
        return best_cmax

    def taillard_neh_insertion(current_perm, job, k):
        if k == 0:
            return [job]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = times[current_perm[r]]
            if r == 0:
                e[0][0] = job_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_r[m]
            else:
                e[r][0] = e[r-1][0] + job_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = times[current_perm[r]]
            q[r][M-1] = q[r+1][M-1] + job_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = job[0]
            else:
                f0 = e[i-1][0] + job[0]
            f = [f0]
            for m in range(1, M):
                f.append(max(f[m-1], e[i-1][m]) + job[m])
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return current_perm[:best_pos] + [job] + current_perm[best_pos:]

    perm = [order[0]]
    if N > 1:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        perm = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, N):
            job_idx = order[idx]
            perm = taillard_neh_insertion(perm, times[job_idx], idx)

    best_perm = perm[:]
    best_cmax = makespan(best_perm)

    max_iters = 60
    for _ in range(max_iters):
        d = 3 if N <= 30 else 4
