        random.shuffle(removed)
        for job_idx in removed:
            perm = taillard_neh_insertion(perm, times[job_idx], len(perm))
        new_cmax = makespan(perm)
        if new_cmax < best_cmax:
            best_cmax = new_cmax
            best_perm = perm[:]
        if new_cmax < makespan(perm):
            perm = perm[:]
        else:
            if random.random() < math.exp(-(new_cmax - makespan(perm)) / T):
                perm = perm[:]
            else:
                perm = best_perm[:]

    return best_perm

