        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten processing times for faster access
    p = [times[i][:] for i in range(N)]
    total_processing = sum(sum(job) for job in p)

    # Makespan calculation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard's accelerated makespan evaluation for insertion
    def makespan_with_insertion(seq, job, pos):
        k = len(seq)
        if k == 0:
            return p[job][0] if M == 1 else _taillard_makespan([job])
        # Forward matrix e for seq[0:pos]
        e = [[0] * M for _ in range(pos)]
        for r in range(pos):
            job_r = seq[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job_r][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job_r][m]
        # Backward matrix q for seq[pos:k]
        q = [[0] * M for _ in range(k + 1)]
        for r in range(k-1, pos-1, -1):
            job_r = seq[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job_r][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
        # Forward vector f for inserting job
        f = [0] * M
        for m in range(M):
            if m == 0:
                f[m] = (e[pos-1][m] if pos > 0 else 0) + p[job][m]
            else:
                f[m] = max(f[m-1], e[pos-1][m] if pos > 0 else 0) + p[job][m]
        # Compute makespan
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def _taillard_makespan(seq):
        if not seq:
            return 0
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = seq[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job_r][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job_r][m]
        return e[-1][-1]

    # NEH construction with Taillard acceleration
    job_sums = [sum(job) for job in p]
    order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
    seq = [order[0]]
    for idx in range(1, N):
        job = order[idx]
        best_pos = 0
        best_makespan = float('inf')
        for pos in range(idx + 1):
            ms = makespan_with_insertion(seq, job, pos)
            if ms < best_makespan:
                best_makespan = ms
                best_pos = pos
        seq.insert(best_pos, job)

    # Iterated Greedy refinement
    pi = seq[:]
    pi_best = pi[:]
    best_makespan = makespan(pi)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 60
    for _ in range(max_iter):
        # Destruction
        indices = random.sample(range(N), d)
        extracted = [pi[i] for i in indices]
        remaining = [pi[i] for i in range(N) if i not in indices]
        # Reconstruction
        for job in extracted:
            best_pos = 0
            best_m = float('inf')
            for pos in range(len(remaining) + 1):
                ms = makespan_with_insertion(remaining, job, pos)
                if ms < best_m:
                    best_m = ms
                    best_pos = pos
            remaining.insert(best_pos, job)
        pi_new = remaining
        m_new = makespan(pi_new)
        if m_new < best_makespan:
            best_makespan = m_new
            pi_best = pi_new[:]
        if m_new < makespan(pi) or random.random() < math.exp(-(m_new - makespan(pi)) / T):
            pi = pi_new[:]
    return pi_best

