            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        row0 = times[partial[0]]
        e[0][0] = row0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + row0[m]
        for r in range(1, k):
            prow = times[partial[r]]
            er = e[r]
            er_prev = e[r-1]
            er[0] = er_prev[0] + prow[0]
            for m in range(1, M):
                er[m] = max(er_prev[m], er[m-1]) + prow[m]
        return e

    def compute_backward(partial):
        k = len(partial)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
