            prow = times[partial[r]]
            qr = q[r]
            qr1 = q[r+1]
            qr[M-1] = qr1[M-1] + prow[M-1]
            for m in range(M-2, -1, -1):
                qr[m] = max(qr1[m], qr[m+1]) + prow[m]
        return q

    def makespan_insert(partial, x, i, e, q):
