                    cmax = makespan_insert(pi_D, job, i, e, q)
                    if cmax < best_cmax:
                        best_cmax = cmax
                        best_pos = i
                pi_D.insert(best_pos, job)
            pi_new = pi_D
            c_new = makespan(pi_new)
            if c_new < c_star:
                pi_star = pi_new[:]
                c_star = c_new
            if c_new < makespan(pi):
                pi = pi_new
            else:
                if random.random() < math.exp(-(c_new - makespan(pi)) / T):
                    pi = pi_new
        return pi_star

    d = 3 if N > 20 else 2
    initial_seq = neh_construct()
    improved_seq = ig_improve(initial_seq, max_iter=50)
    return improved_seq

