def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(row) for row in times)
    lower_bound = 0
    for m in range(M):
        min_before = min(times[i][l] for i in range(N) for l in range(m)) if m > 0 else 0
        min_after = min(times[i][l] for i in range(N) for l in range(m+1, M)) if m < M-1 else 0
        sum_m = sum(times[i][m] for i in range(N))
        lb_m = min_before + sum_m + min_after
        if lb_m > lower_bound:
            lower_bound = lb_m

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[-1]

    def makespan_taillard(perm, e, q):
        if not perm:
            return 0
        t = [0] * M
        for idx, job in enumerate(perm):
            job_time = times[job]
            if idx == 0:
                t[0] = job_time[0]
                for m in range(1, M):
                    t[m] = t[m-1] + job_time[m]
            else:
                t[0] = e[idx-1][0] + job_time[0]
                for m in range(1, M):
                    t[m] = max(t[m-1], e[idx-1][m]) + job_time[m]
        return t[-1]

