    order = sorted(range(N), key=lambda i: (-P[i], i))

    def neh_taillard(perm_order):
        if not perm_order:
            return []
        first_job = perm_order[0]
        if len(perm_order) == 1:
            return [first_job]
        second_job = perm_order[1]
        seq1 = [first_job, second_job]
        seq2 = [second_job, first_job]
        current = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        k = 2
        while k < len(perm_order):
            job = perm_order[k]
            e = [[0] * M for _ in range(k)]
            for m in range(M):
                e[0][m] = times[current[0]][m] if k > 0 else 0
            for r in range(1, k):
                job_r = current[r]
                job_time = times[job_r]
                e[r][0] = e[r-1][0] + job_time[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_time[m]
            q = [[0] * M for _ in range(k+1)]
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = current[r]
                job_time = times[job_r]
                q[r][M-1] = q[r+1][M-1] + job_time[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_time[m]
            best_pos = 0
            best_makespan = float('inf')
            for i in range(k+1):
                f = [0] * M
                if i == 0:
                    prev_e = [0] * M
                else:
                    prev_e = e[i-1]
                job_time = times[job]
                f[0] = prev_e[0] + job_time[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + job_time[m]
                ms = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > ms:
                        ms = val
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = i
