    current_makespan = makespan(current_seq)
    best_makespan = current_makespan

    if best_makespan == lower_bound:
        return best_seq

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 60
    iter_count = 0

    while iter_count < max_iter and current_makespan > lower_bound:
        indices = list(range(N))
        random.shuffle(indices)
        destroyed_indices = indices[:d]
        remaining_indices = indices[d:]
        remaining_seq = [current_seq[i] for i in remaining_indices]
        destroyed_jobs = [current_seq[i] for i in destroyed_indices]

        e = [[0] * M for _ in range(len(remaining_seq))]
        if remaining_seq:
            for m in range(M):
                e[0][m] = times[remaining_seq[0]][m]
            for r in range(1, len(remaining_seq)):
                job_r = remaining_seq[r]
                job_time = times[job_r]
                e[r][0] = e[r-1][0] + job_time[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_time[m]
        q = [[0] * M for _ in range(len(remaining_seq)+1)]
        if remaining_seq:
            for m in range(M):
                q[len(remaining_seq)][m] = 0
            for r in range(len(remaining_seq)-1, -1, -1):
                job_r = remaining_seq[r]
                job_time = times[job_r]
                q[r][M-1] = q[r+1][M-1] + job_time[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_time[m]

        random.shuffle(destroyed_jobs)
        for job in destroyed_jobs:
            best_pos = 0
            best_makespan = float('inf')
            for i in range(len(remaining_seq)+1):
                f = [0] * M
                if i == 0:
                    prev_e = [0] * M
                else:
                    prev_e = e[i-1]
                job_time = times[job]
                f[0] = prev_e[0] + job_time[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + job_time[m]
                ms = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > ms:
                        ms = val
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = i
            remaining_seq = remaining_seq[:best_pos] + [job] + remaining_seq[best_pos:]

        new_seq = remaining_seq
        new_makespan = makespan(new_seq)

        if new_makespan < current_makespan:
            current_seq = new_seq
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_seq = new_seq
                best_makespan = new_makespan
        else:
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current_seq = new_seq
                current_makespan = new_makespan

        iter_count += 1

    return best_seq

