def _makespan(perm, p, n, m):
    if n == 0:
        return 0
    # Compute completion times using DP table
    t = [0] * m
    for idx in perm:
        job = p[idx]
        t[0] += job[0]
        for mc in range(1, m):
            t[mc] = max(t[mc-1], t[mc]) + job[mc]
    return t[m-1]

