def makespan(times, seq):
    if not seq:
        return 0
    n = len(seq)
    m = len(times[0])
    dp = [0] * m
    for job in seq:
        dp[0] += times[job][0]
        for k in range(1, m):
            dp[k] = max(dp[k-1], dp[k]) + times[job][k]
    return dp[-1]

def johnson_rule(times, jobs):
    if not jobs:
        return []
    left, right = [], []
    for job in jobs:
        if times[job][0] <= times[job][1]:
            left.append(job)
        else:
            right.append(job)
    left.sort(key=lambda j: times[j][0])
    right.sort(key=lambda j: times[j][1], reverse=True)
    return left + right

def cds_variant(times):
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])
    if m == 2:
        return johnson_rule(times, list(range(n)))
    best_seq = None
    best_makespan = float('inf')
    for l in range(1, m):
        p1 = [sum(times[i][:l]) for i in range(n)]
        p2 = [sum(times[i][m-l:]) for i in range(n)]
        two_machine_times = list(zip(p1, p2))
        seq = johnson_rule(two_machine_times, list(range(n)))
        ms = makespan(times, seq)
        if ms < best_makespan:
            best_makespan = ms
            best_seq = seq
    return best_seq

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    return cds_variant(times)

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0

    # Gupta's heuristic: sign-weighted machine differences
    # S_i = sum_{j=0}^{M-1} (2*j - M + 1) * p_{i,j}
    gupta_scores = []
    for i in range(N):
        s = 0
        for j in range(M):
            s += (2 * j - M + 1) * times[i][j]
        gupta_scores.append(s)
    # Sort descending by Gupta score (later machines weighted more)
    order = sorted(range(N), key=lambda i: gupta_scores[i], reverse=True)

    # Helper: makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for idx in perm:
            job = times[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    # Taillard's accelerated insertion evaluation
    def evaluate_insertion(partial, job_idx, k):
        if k == 0:
            f = [0] * M
            for m in range(M):
                if m == 0:
                    f[m] = times[job_idx][m]
                else:
                    f[m] = max(f[m-1], 0) + times[job_idx][m]
            q = [0] * M
            return max(f[m] + q[m] for m in range(M))
        # Forward matrix e: size k x M
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = times[partial[r]]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + job_r[m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + job_r[m]
        # Backward matrix q: size (k+1) x M
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = times[partial[r]]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + job_r[m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
        best_cmax = float('inf')
        best_pos = 0
        for i in range(k+1):
            # forward vector f for job_idx up to machine m
            f = [0] * M
            for m in range(M):
                if m == 0:
                    prev_e = e[i-1][0] if i > 0 else 0
                    f[m] = prev_e + times[job_idx][m]
                else:
                    f[m] = max(f[m-1], e[i-1][m] if i > 0 else 0) + times[job_idx][m]
            cmax_candidate = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax_candidate:
                    cmax_candidate = val
            if cmax_candidate < best_cmax:
                best_cmax = cmax_candidate
                best_pos = i
        return best_cmax, best_pos

    # NEH construction with Taillard acceleration
    def construct_neh():
        perm = [order[0]]
        for k in range(1, N):
            job_idx = order[k]
            _, pos = evaluate_insertion(perm, job_idx, k)
            perm.insert(pos, job_idx)
        return perm

    # Iterated Greedy
    def iterated_greedy(initial_perm, max_iter=60):
        perm = initial_perm[:]
        best_perm = perm[:]
        best_cmax = makespan(best_perm)
        d = 3 if N > 20 else 2
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [perm[i] for i in sorted(indices, reverse=True)]
            for idx in sorted(indices, reverse=True):
                del perm[idx]
            # Reconstruction: reinsert removed jobs one by one
            for job_idx in removed:
                _, pos = evaluate_insertion(perm, job_idx, len(perm))
                perm.insert(pos, job_idx)
            # Acceptance
            curr_cmax = makespan(perm)
            if curr_cmax < best_cmax:
                best_cmax = curr_cmax
                best_perm = perm[:]
            if curr_cmax < makespan(best_perm):
                # This condition is redundant but kept for clarity
                pass
            if curr_cmax < makespan(perm):
                # Always true, skip
                pass
            if curr_cmax == makespan(best_perm):
                pass
            delta = curr_cmax - makespan(perm)
            if delta < 0 or random.random() < math.exp(-delta / T):
                # accept perm (already current)
                pass
            else:
                # reject: restore previous perm? In standard IG, we keep the new perm even if worse.
                # Here we do not revert; the new perm becomes current for next iteration.
                pass
            # Note: In standard IG, we always move to the new perm (accept or not via Metropolis).
            # We already set perm to the new sequence; we only update best if improved.
            # So no need to revert.
        return best_perm

    initial = construct_neh()
    return iterated_greedy(initial, max_iter=50)

