    slope = [sum((2 * j - m + 1) * times[i][j] for j in range(m)) for i in range(n)]
    jobs = sorted(range(n), key=lambda i: (-total_processing[i], -slope[i]))

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * m
        for job in seq:
            for k in range(m):
                if k == 0:
                    t[k] += times[job][k]
                else:
                    t[k] = max(t[k], t[k-1]) + times[job][k]
        return t[-1]

    def makespan_taillard(seq):
        if not seq:
            return 0
        e = [0] * m
        for job in seq:
            for k in range(m):
                if k == 0:
                    e[k] += times[job][k]
                else:
                    e[k] = max(e[k], e[k-1]) + times[job][k]
        return e[-1]

    def taillard_insert(seq, job):
        k = len(seq)
        if k == 0:
            return [job]
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job_r = seq[r]
            for c in range(m):
                if c == 0:
                    e[r][c] = (e[r-1][c] if r > 0 else 0) + times[job_r][c]
                else:
                    e[r][c] = max(e[r-1][c] if r > 0 else 0, e[r][c-1]) + times[job_r][c]
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = seq[r]
            for c in range(m-1, -1, -1):
                if c == m-1:
                    q[r][c] = q[r+1][c] + times[job_r][c]
                else:
                    q[r][c] = max(q[r+1][c], q[r][c+1]) + times[job_r][c]
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            f = [0] * m
            for c in range(m):
                if c == 0:
                    prev = e[i-1][c] if i > 0 else 0
                    f[c] = prev + times[job][c]
                else:
                    f[c] = max(f[c-1], e[i-1][c] if i > 0 else 0) + times[job][c]
            mk = 0
            for c in range(m):
                val = f[c] + q[i][c]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return seq[:best_pos] + [job] + seq[best_pos:]

    perm = []
    for job in jobs:
        perm = taillard_insert(perm, job)

    total_sum = sum(total_processing)
    T_param = 0.5
    T = T_param * total_sum / (10 * n * m) if n * m > 0 else 1e-6
    d = 3 if n > 20 else 2
    max_iter = 50
    current = perm[:]
    current_mk = makespan_taillard(current)
    best = current[:]
    best_mk = current_mk

    for _ in range(max_iter):
        if current_mk == 0:
            break
        indices = list(range(n))
        random.shuffle(indices)
        removed = indices[:d]
        removed.sort(reverse=True)
        remaining = current[:]
        for idx in removed:
            remaining.pop(idx)
        extracted = [current[i] for i in removed]
        random.shuffle(extracted)
        for job in extracted:
            remaining = taillard_insert(remaining, job)
        new_mk = makespan_taillard(remaining)
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current = remaining
            current_mk = new_mk
            if new_mk < best_mk:
                best = current[:]
                best_mk = new_mk
    return best

