def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    for i in range(N):
        for j in range(M):
            total_processing += times[i][j]

    # Precompute total processing times and slope indices
    total_times = [0] * N
    slope = [0] * N
    for i in range(N):
        total = 0
        s = 0
        for j in range(M):
            p = times[i][j]
            total += p
            s += (2 * j - M + 1) * p
        total_times[i] = total
        slope[i] = s

    # Try multiple priority orders: total time descending, slope descending
    orders = [
        sorted(range(N), key=lambda i: (-total_times[i], i)),
        sorted(range(N), key=lambda i: (-slope[i], i))
    ]

    def makespan_from_perm(perm):
        if not perm:
            return 0
        t_prev = [0] * M
        for job in perm:
            t_curr = [0] * M
            for m in range(M):
                if m == 0:
                    t_curr[m] = t_prev[m] + times[job][m]
                else:
                    t_curr[m] = max(t_prev[m], t_curr[m-1]) + times[job][m]
            t_prev = t_curr
        return t_prev[-1]

    def taillard_evaluate_insertion(partial, job, k, e, q):
        # partial: current permutation of length k
        # e: forward matrix for partial (k x M)
        # q: backward tail matrix for partial ((k+1) x M)
        best_pos = 0
        best_makespan = float('inf')
        f = [0] * M
        for i in range(k + 1):
            # compute forward vector f for inserting job at position i
            if i == 0:
                f[0] = times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], 0) + times[job][m]
            else:
                f[0] = e[i-1][0] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + times[job][m]
            # makespan = max_m (f[m] + q[i][m])
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_makespan:
                best_makespan = mk
                best_pos = i
        return best_pos, best_makespan

    def compute_forward_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0]*M], [[0]*M]  # e: 0xM, q: 1xM (but we need q of size (k+1) x M)
        # e: k x M
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    if r == 0:
                        e[r][m] = times[job][m]
                    else:
                        e[r][m] = e[r-1][m] + times[job][m]
                else:
                    if r == 0:
                        e[r][m] = e[r][m-1] + times[job][m]
                    else:
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job][m]
        # q: (k+1) x M
        q = [[0]*M for _ in range(k+1)]
        # q[k][m] = 0 already
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return e, q

    def neh_construct(order):
        if not order:
            return []
        perm = [order[0]]
        if len(order) > 1:
            job1, job2 = order[0], order[1]
            perm1 = [job1, job2]
            perm2 = [job2, job1]
            if makespan_from_perm(perm1) <= makespan_from_perm(perm2):
                perm = perm1
            else:
                perm = perm2
        # Insert remaining jobs
        for idx in range(2, len(order)):
            job = order[idx]
            k = len(perm)
            e, q = compute_forward_backward(perm)
            pos, _ = taillard_evaluate_insertion(perm, job, k, e, q)
            perm.insert(pos, job)
        return perm

    best_perm = None
    best_mk = float('inf')

    for order in orders:
        perm = neh_construct(order)
        mk = makespan_from_perm(perm)
        if mk < best_mk:
            best_mk = mk
            best_perm = perm[:]

    # Iterated Greedy refinement
    if best_perm is None:
        best_perm = list(range(N))
        best_mk = makespan_from_perm(best_perm)

    current_perm = best_perm[:]
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-6:
        T = 1e-6

    max_iter = 60
    for _ in range(max_iter):
        # Destruction: remove d=3 jobs randomly
        d = 3
        if N <= d:
            indices = list(range(N))
        else:
            indices = random.sample(range(N), d)
        indices_set = set(indices)
        # Build destroyed permutation and removed jobs
        destroyed = [job for job in current_perm if job not in indices_set]
        removed = [job for job in current_perm if job in indices_set]
        # Random order of removed jobs for insertion
        random.shuffle(removed)
        # Reconstruct using NEH insertion with Taillard acceleration
        for job in removed:
            k = len(destroyed)
            if k == 0:
                destroyed.append(job)
                continue
            e, q = compute_forward_backward(destroyed)
            pos, _ = taillard_evaluate_insertion(destroyed, job, k, e, q)
            destroyed.insert(pos, job)
        new_perm = destroyed
        new_mk = makespan_from_perm(new_perm)
        # Acceptance criterion
        if new_mk < makespan_from_perm(current_perm):
            current_perm = new_perm[:]
            if new_mk < best_mk:
                best_mk = new_mk
                best_perm = new_perm[:]
        else:
            delta = new_mk - makespan_from_perm(current_perm)
            if random.random() < math.exp(-delta / T):
                current_perm = new_perm[:]
    return best_perm

