    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    for i in range(N):
        for j in range(M):
            total_processing += times[i][j]

    # Compute job priorities: total processing time and slope index
    P = [0] * N
    S = [0] * N
    for i in range(N):
        pi = times[i]
        total = 0
        slope = 0
        for j in range(M):
            t = pi[j]
            total += t
            slope += (2 * j - M + 1) * t
        P[i] = total
        S[i] = slope

    # Sort by total processing time descending, then by slope index descending
    order = list(range(N))
    order.sort(key=lambda i: (P[i], S[i]), reverse=True)

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N + 1)]

    def makespan_partial(perm, length):
        # Compute forward completion matrix e for perm[0:length]
        for r in range(length):
            job = perm[r]
            job_times = times[job]
            if r == 0:
                e[0][0] = job_times[0]
                for m in range(1, M):
                    e[0][m] = e[0][m - 1] + job_times[m]
            else:
                e[r][0] = e[r - 1][0] + job_times[0]
                for m in range(1, M):
                    e[r][m] = max(e[r - 1][m], e[r][m - 1]) + job_times[m]
        # Compute backward tail matrix q for perm[0:length]
        for m in range(M):
            q[length][m] = 0
        for r in range(length - 1, -1, -1):
            job = perm[r]
            job_times = times[job]
            q[r][M - 1] = q[r + 1][M - 1] + job_times[M - 1]
            for m in range(M - 2, -1, -1):
                q[r][m] = max(q[r + 1][m], q[r][m + 1]) + job_times[m]
        return e[length - 1][M - 1] if length > 0 else 0

    def makespan_full(perm):
        return makespan_partial(perm, len(perm))

    def makespan_insert(perm, length, job, pos):
        job_times = times[job]
        # Compute forward vector f for inserting job at position pos
        f = [0] * M
        if pos == 0:
            f[0] = job_times[0]
            for m in range(1, M):
                f[m] = f[m - 1] + job_times[m]
        else:
            f[0] = e[pos - 1][0] + job_times[0]
            for m in range(1, M):
                f[m] = max(f[m - 1], e[pos - 1][m]) + job_times[m]
        # Compute makespan: max over m of f[m] + q[pos][m]
        max_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > max_val:
                max_val = val
        return max_val

    # Construct initial solution using NEH with Taillard acceleration
    perm = []
    for idx in order:
        k = len(perm)
        best_pos = 0
        best_makespan = float('inf')
        for pos in range(k + 1):
            cmax = makespan_insert(perm, k, idx, pos)
            if cmax < best_makespan:
                best_makespan = cmax
                best_pos = pos
        perm.insert(best_pos, idx)

    # Iterated Greedy refinement
    current = perm[:]
    best = current[:]
    best_makespan = makespan_full(best)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 60
    if N > 60:
        max_iter = 40

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        removed = random.sample(current, d)
        remaining = [job for job in current if job not in removed]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            k = len(remaining)
            best_pos = 0
            best_makespan_insert = float('inf')
            for pos in range(k + 1):
                cmax = makespan_insert(remaining, k, job, pos)
                if cmax < best_makespan_insert:
                    best_makespan_insert = cmax
                    best_pos = pos
            remaining.insert(best_pos, job)
        current = remaining
        current_makespan = makespan_full(current)
        if current_makespan < best_makespan:
            best_makespan = current_makespan
            best = current[:]
        # Metropolis acceptance
        if current_makespan < makespan_full(perm) or random.random() < math.exp(-(current_makespan - makespan_full(perm)) / T):
            perm = current[:]

    return best

