        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = (e[0][m-1] if m > 0 else 0) + times[seq[0]][m]
        for i in range(1, k):
            job_t = times[seq[i]]
            for m in range(M):
                e[i][m] = max(e[i-1][m], e[i][m-1] if m > 0 else 0) + job_t[m]
        return e

    # Taillard's backward tail matrix for a given sequence
    def compute_backward(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for i in range(k-1, -1, -1):
            job_t = times[seq[i]]
            for m in range(M-1, -1, -1):
                q[i][m] = max(q[i+1][m], q[i][m+1] if m < M-1 else 0) + job_t[m]
        return q

    # Compute makespan after inserting job x at position i using Taillard's O(M) method
    def insertion_makespan(e, q, x, i):
        f = [0] * M
        prev_e = e[i-1] if i > 0 else [0] * M
        job_t = times[x]
        for m in range(M):
            f[m] = max(f[m-1] if m > 0 else 0, prev_e[m]) + job_t[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    def construct_initial():
        if N < 2:
            return order[:N]
        best_seq = None
        best_ms = float('inf')
        for a, b in [(order[0], order[1]), (order[1], order[0])]:
            seq = [a, b]
            ms = makespan(seq)
            if ms < best_ms:
                best_ms = ms
                best_seq = seq[:]
        e = compute_forward(best_seq)
        q = compute_backward(best_seq)
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_ms = float('inf')
            for i in range(k+1):
                ms = insertion_makespan(e, q, job, i)
                if ms < best_ms:
                    best_ms = ms
                    best_pos = i
            best_seq.insert(best_pos, job)
            e = compute_forward(best_seq)
            q = compute_backward(best_seq)
        return best_seq

    # Iterated Greedy with destruction size 2
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_ms = makespan(best)
        total_processing = sum(P)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        for _ in range(max_iter):
            # Destruction: remove 2 random jobs
            if N < 2:
                break
            pos1 = random.randrange(N)
            pos2 = random.randrange(N-1)
            if pos2 >= pos1:
                pos2 += 1
            job1, job2 = current[pos1], current[pos2]
            # Remove higher index first
            if pos1 > pos2:
                current.pop(pos1)
                current.pop(pos2)
            else:
                current.pop(pos2)
                current.pop(pos1)
            # Reconstruction: reinsert job1 and job2 as a block
            e = compute_forward(current)
            q = compute_backward(current)
            k = len(current)
            best_block_ms = float('inf')
            best_block_seq = None
            # Try all combinations of positions for the two jobs
            for i in range(k+1):
                for j in range(i, k+2):
                    # Insert job1 at i, job2 at j (adjusted for first insertion)
                    seq_temp = current[:]
                    seq_temp.insert(i, job1)
                    seq_temp.insert(j, job2)  # j is relative to after first insertion
                    ms = makespan(seq_temp)
                    if ms < best_block_ms:
                        best_block_ms = ms
                        best_block_seq = seq_temp
            current = best_block_seq
            if makespan(current) < makespan(best):
                best = current[:]
            # Metropolis acceptance
            if makespan(current) < makespan(initial_seq) or random.random() < math.exp(-(makespan(current) - makespan(initial_seq)) / T):
                initial_seq = current[:]
        return best

    initial_seq = construct_initial()
    return iterated_greedy(initial_seq)

