def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_times = [sum(job) for job in times]
    slope_indices = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # NEH with Taillard acceleration and beam width K=2
    order = sorted(range(N), key=lambda i: (-total_times[i], -slope_indices[i]))
    beams = [[order[0]]]  # Start with the first job

    for idx in range(1, N):
        job = order[idx]
        candidates = []
        for beam in beams:
            k = len(beam)
            # Forward matrix e: completion times of current beam
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = beam[r]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job_r][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job_r][m]
            # Backward matrix q: tail times from position r to end
            q = [[0] * M for _ in range(k+1)]  # q[k][:] = 0 already
            for r in range(k-1, -1, -1):
                job_r = beam[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + times[job_r][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
            # Evaluate all insertion positions for current job
            for pos in range(k+1):
                # Forward pass for the job up to insertion point
                f = [0] * M
                prev_e = e[pos-1] if pos > 0 else [0] * M
                for m in range(M):
                    if m == 0:
                        f[m] = prev_e[m] + times[job][m]
                    else:
                        f[m] = max(f[m-1], prev_e[m]) + times[job][m]
                # Makespan = max over m of (f[m] + q[pos][m])
                makespan = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > makespan:
                        makespan = val
                new_beam = beam[:pos] + [job] + beam[pos:]
                candidates.append((makespan, new_beam))
        # Prune to top K=2 beams by makespan
        candidates.sort(key=lambda x: x[0])
        beams = [beam for _, beam in candidates[:2]]

    # Return the best beam (lowest makespan)
    best_beam = beams[0]
    best_makespan = float('inf')
    for beam in beams:
        # Compute makespan of beam
        e = [[0] * M for _ in range(len(beam))]
        for r in range(len(beam)):
            job_r = beam[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job_r][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job_r][m]
        makespan = e[-1][-1] if e else 0
        if makespan < best_makespan:
            best_makespan = makespan
            best_beam = beam
    return best_beam

