def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    P = [0] * N
    for i in range(N):
        row = times[i]
        s = 0
        for t in row:
            s += t
        P[i] = s
        total_processing += s

    order = list(range(N))
    order.sort(key=lambda i: P[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            pj = times[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[-1]

    def makespan_with_tail(perm, fwd, tail):
        if not perm:
            return 0
        return max(fwd[m] + tail[m] for m in range(M))

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        fwd = [[0] * M for _ in range(k)]
        job0 = perm[0]
        p0 = times[job0]
        fwd[0][0] = p0[0]
        for m in range(1, M):
            fwd[0][m] = fwd[0][m-1] + p0[m]
        for r in range(1, k):
            job = perm[r]
            pj = times[job]
            fwd[r][0] = fwd[r-1][0] + pj[0]
            for m in range(1, M):
                fwd[r][m] = max(fwd[r-1][m], fwd[r][m-1]) + pj[m]
        return fwd

    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M for _ in range(k+1)]
        tail = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            pj = times[job]
            tail[r][M-1] = tail[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                tail[r][m] = max(tail[r+1][m], tail[r][m+1]) + pj[m]
        return tail

    def evaluate_insertion(fwd, tail, job, pos):
        k = len(fwd)
        pj = times[job]
        if pos == 0:
            f = pj[:]
        else:
            prev = fwd[pos-1]
            f = [0] * M
            f[0] = prev[0] + pj[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev[m]) + pj[m]
        best = 0
        for m in range(M):
            val = f[m] + tail[pos][m]
            if val > best:
                best = val
        return best

    def construct_neh():
        if N == 0:
            return []
        perm = [order[0]]
        if N == 1:
            return perm
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        for k in range(2, N):
            job = order[k]
            fwd = compute_forward(perm)
            tail = compute_backward(perm)
            best_pos = 0
            best_mk = evaluate_insertion(fwd, tail, job, 0)
            for pos in range(1, k+1):
                mk = evaluate_insertion(fwd, tail, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    def ig_iteration(current, current_mk):
        d = 3 if N > 5 else N
        if d < 2:
            d = 2
        indices = random.sample(range(N), d)
        extracted = [current[i] for i in indices]
        remaining = [current[i] for i in range(N) if i not in indices]
        fwd = compute_forward(remaining)
        tail = compute_backward(remaining)
        random.shuffle(extracted)
        for job in extracted:
            best_pos = 0
            best_mk = evaluate_insertion(fwd, tail, job, 0)
            for pos in range(1, len(remaining)+1):
                mk = evaluate_insertion(fwd, tail, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            remaining.insert(best_pos, job)
            fwd = compute_forward(remaining)
            tail = compute_backward(remaining)
        new_mk = makespan(remaining)
        if new_mk < current_mk:
            return remaining, new_mk
        T_param = 0.5
        T = T_param * total_processing / (10.0 * N * M)
        if T <= 0:
            T = 1e-6
        delta = new_mk - current_mk
        if random.random() < math.exp(-delta / T):
            return remaining, new_mk
        else:
            return current, current_mk

    perm = construct_neh()
    current_mk = makespan(perm)
    best_perm = list(perm)
    best_mk = current_mk

    max_iter = 60
    for _ in range(max_iter):
        perm, current_mk = ig_iteration(perm, current_mk)
        if current_mk < best_mk:
            best_mk = current_mk
            best_perm = list(perm)

    return best_perm

