def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])
    if M == 2:
        return johnson_rule(times)

    # Precompute job processing times as flat lists for faster access
    proc = [row[:] for row in times]
    total_proc = [sum(row) for row in proc]

    # Initial solution via NEH with Taillard acceleration
    order = sorted(range(N), key=lambda i: total_proc[i], reverse=True)
    pi = neh_construction(proc, order)
    best_pi = pi[:]
    best_cmax = makespan_taillard(pi, proc)

    # Calculate lower bound for early termination
    lb = taillard_lower_bound(proc)
    if best_cmax == lb:
        return best_pi

    # Iterated Greedy parameters
    T_param = 0.5
    total_sum = sum(total_proc)
    T = T_param * total_sum / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 50

    current_pi = pi[:]
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            destroyed = [current_pi[i] for i in indices]
            remaining = [current_pi[i] for i in range(N) if i not in indices_set]

        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        for job in destroyed:
            best_pos, best_cmax_local = taillard_insertion_search(remaining, job, proc)
            remaining.insert(best_pos, job)

        new_pi = remaining
        new_cmax = makespan_taillard(new_pi, proc)

        # Acceptance criterion
        if new_cmax < makespan_taillard(current_pi, proc) or \
           random.random() < math.exp(-(new_cmax - makespan_taillard(current_pi, proc)) / T):
            current_pi = new_pi
            if new_cmax < best_cmax:
                best_pi = new_pi[:]
                best_cmax = new_cmax
                if best_cmax == lb:
                    break

    return best_pi

def makespan_taillard(perm, proc):
    if not perm:
        return 0
    M = len(proc[0])
    t = [0] * M
    for job in perm:
        t[0] += proc[job][0]
        for m in range(1, M):
            t[m] = max(t[m-1], t[m]) + proc[job][m]
    return t[-1]

def taillard_insertion_search(perm, job, proc):
    k = len(perm)
    M = len(proc[0])
    if k == 0:
        return 0, proc[job][0] if M == 1 else _makespan_single_job(proc, job)

    # Forward matrix e: completion times of current perm
    e = [[0] * M for _ in range(k)]
    for r in range(k):
        job_r = perm[r]
        if r == 0:
            e[0][0] = proc[job_r][0]
            for m in range(1, M):
                e[0][m] = e[0][m-1] + proc[job_r][m]
        else:
            e[r][0] = e[r-1][0] + proc[job_r][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + proc[job_r][m]

    # Backward matrix q: tail times from position r
    q = [[0] * M for _ in range(k+1)]
    for r in range(k-1, -1, -1):
        job_r = perm[r]
        q[r][M-1] = q[r+1][M-1] + proc[job_r][M-1]
        for m in range(M-2, -1, -1):
            q[r][m] = max(q[r+1][m], q[r][m+1]) + proc[job_r][m]

    best_pos = 0
    best_cmax = float('inf')
    for i in range(k+1):
        # Compute forward completion for job at position i
        if i == 0:
            f0 = proc[job][0]
            fm = [0] * M
            fm[0] = f0
            for m in range(1, M):
                fm[m] = max(fm[m-1], 0) + proc[job][m]
        else:
            prev = e[i-1]
            f0 = prev[0] + proc[job][0]
            fm = [0] * M
            fm[0] = f0
            for m in range(1, M):
                fm[m] = max(fm[m-1], prev[m]) + proc[job][m]

        # Compute makespan: max over m of fm[m] + q[i][m]
        cmax = 0
        for m in range(M):
            val = fm[m] + q[i][m]
            if val > cmax:
                cmax = val
        if cmax < best_cmax:
            best_cmax = cmax
            best_pos = i
    return best_pos, best_cmax

def neh_construction(proc, order):
    if not order:
        return []
    seq = [order[0]]
    for idx in order[1:]:
        best_pos, _ = taillard_insertion_search(seq, idx, proc)
        seq.insert(best_pos, idx)
    return seq

def taillard_lower_bound(proc):
    if not proc:
        return 0
    N = len(proc)
    M = len(proc[0])
    lb = 0
    for m in range(M):
        sum_m = sum(proc[i][m] for i in range(N))
        min_before = min((sum(proc[i][l] for l in range(m)) for i in range(N)), default=0)
        min_after = min((sum(proc[i][l] for l in range(m+1, M)) for i in range(N)), default=0)
        lb_m = min_before + sum_m + min_after
        if lb_m > lb:
            lb = lb_m
    return lb

def johnson_rule(times):
    N = len(times)
    if N == 0:
        return []
    left = []
    right = []
    jobs = list(range(N))
    while jobs:
        min_val = float('inf')
        min_job = -1
        min_machine = -1
        for j in jobs:
            if times[j][0] < min_val:
                min_val = times[j][0]
                min_job = j
                min_machine = 0
            if times[j][1] < min_val:
                min_val = times[j][1]
                min_job = j
                min_machine = 1
        jobs.remove(min_job)
        if min_machine == 0:
            left.append(min_job)
        else:
            right.insert(0, min_job)
    return left + right

def _makespan_single_job(proc, job):
    return sum(proc[job])

