def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flatten times for faster access
    flat = [times[i][j] for i in range(N) for j in range(M)]
    total_processing = sum(flat)
    lower_bound = 0
    for m in range(M):
        min_before = min(sum(times[i][l] for l in range(m)) for i in range(N)) if m > 0 else 0
        machine_sum = sum(times[i][m] for i in range(N))
        min_after = min(sum(times[i][l] for l in range(m+1, M)) for i in range(N)) if m < M-1 else 0
        lb_m = min_before + machine_sum + min_after
        if lb_m > lower_bound:
            lower_bound = lb_m

    # Helper: makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            base = flat[job*M:(job+1)*M]
            t[0] += base[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + base[m]
        return t[-1]

    # Taillard acceleration: compute forward matrix e for prefix perm[0:k]
    def compute_forward(perm, k):
        e = [0] * (k * M)
        for r in range(k):
            base = flat[perm[r]*M:(perm[r]+1)*M]
            if r == 0:
                for m in range(M):
                    e[r*M + m] = base[m]
            else:
                for m in range(M):
                    if m == 0:
                        e[r*M + m] = e[(r-1)*M + m] + base[m]
                    else:
                        e[r*M + m] = max(e[(r-1)*M + m], e[r*M + (m-1)]) + base[m]
        return e

    # Taillard acceleration: compute backward tail matrix q for suffix perm[k:]
    def compute_backward(perm, k):
        q = [0] * ((k+1) * M)
        for m in range(M):
            q[k*M + m] = 0
        for r in range(k-1, -1, -1):
            base = flat[perm[r]*M:(perm[r]+1)*M]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r*M + m] = q[(r+1)*M + m] + base[m]
                else:
                    q[r*M + m] = max(q[(r+1)*M + m], q[r*M + (m+1)]) + base[m]
        return q

    # Evaluate makespan when inserting job x at position i in perm of length k
    def insertion_makespan(perm, k, x, e, q):
        base = flat[x*M:(x+1)*M]
        f = [0] * M
        if k == 0:
            f[0] = base[0]
            for m in range(1, M):
                f[m] = max(f[m-1], 0) + base[m]
        else:
            e_im1 = [e[(k-1)*M + m] if k-1 >= 0 else 0 for m in range(M)] if k-1 >= 0 else [0]*M
            f[0] = (e_im1[0] if k-1 >= 0 else 0) + base[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_im1[m]) + base[m]
        q_i = [q[k*M + m] for m in range(M)]
        max_val = 0
        for m in range(M):
            val = f[m] + q_i[m]
            if val > max_val:
                max_val = val
        return max_val

    # NEH with Taillard acceleration
    job_order = sorted(range(N), key=lambda i: -sum(times[i]))
    perm = [job_order[0]]
    if N > 1:
        seq1 = [job_order[0], job_order[1]]
        seq2 = [job_order[1], job_order[0]]
        perm = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for k in range(2, N):
            x = job_order[k]
            e = compute_forward(perm, k)
            q = compute_backward(perm, k)
            best_pos = 0
            best_makespan = float('inf')
            for i in range(k+1):
                m = insertion_makespan(perm, k, x, e, q)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = i
            perm.insert(best_pos, x)

    # Iterated Greedy
    current = perm[:]
    best = current[:]
    best_makespan = makespan(best)
    if best_makespan == lower_bound:
        return best

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for _ in range(max_iter):
        if no_improve >= no_improve_limit:
