def makespan(order, times):
    if not order:
        return 0
    n = len(order)
    m = len(times[0])
    t = [0] * m
    for job in order:
        job_t = times[job]
        t[0] += job_t[0]
        for i in range(1, m):
            t[i] = max(t[i-1], t[i]) + job_t[i]
    return t[-1]

def johnson_rule(times):
    n = len(times)
    left, right = [], []
    for i in range(n):
        if times[i][0] <= times[i][1]:
            left.append(i)
        else:
            right.append(i)
    left.sort(key=lambda i: times[i][0])
    right.sort(key=lambda i: times[i][1], reverse=True)
    return left + right

def cds_variant(times):
    n = len(times)
    m = len(times[0])
    if n == 0:
        return []
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])
    if m == 2:
        return johnson_rule(times)
    best_order = None
    best_cmax = float('inf')
    for l in range(1, m):
        p1 = [sum(times[i][:l]) for i in range(n)]
        p2 = [sum(times[i][m-l:]) for i in range(n)]
        two_machine_times = list(zip(p1, p2))
        order = johnson_rule(two_machine_times)
        cmax = makespan(order, times)
        if cmax < best_cmax:
            best_cmax = cmax
            best_order = order
    return best_order

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    return cds_variant(times)

