def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    total_processing = [sum(row) for row in times]
    jobs_sorted = sorted(range(n), key=lambda i: total_processing[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        dp = [0] * m
        for job in perm:
            dp[0] += times[job][0]
            for k in range(1, m):
                dp[k] = max(dp[k-1], dp[k]) + times[job][k]
        return dp[-1]

    def taillard_makespan(perm):
        if not perm:
            return 0
        e = [0] * m
        for job in perm:
            e[0] += times[job][0]
            for k in range(1, m):
                e[k] = max(e[k-1], e[k]) + times[job][k]
        return e[-1]

    def taillard_insertion_cost(current_perm, job_x):
        k = len(current_perm)
        if k == 0:
            return times[job_x][0] if m == 1 else taillard_makespan([job_x])
        f = [0] * m
        f[0] = times[job_x][0]
        for i in range(1, m):
            f[i] = max(f[i-1], f[i]) + times[job_x][i]
        best_cost = float('inf')
        best_pos = 0
        for pos in range(k + 1):
            if pos == 0:
                e_prev = [0] * m
            else:
                e_prev = [0] * m
                job_prev = current_perm[pos-1]
                e_prev[0] = times[job_prev][0]
                for i in range(1, m):
                    e_prev[i] = max(e_prev[i-1], e_prev[i]) + times[job_prev][i]
            q_tail = [0] * m
            if pos < k:
                job_next = current_perm[pos]
                q_tail[m-1] = times[job_next][m-1]
                for i in range(m-2, -1, -1):
                    q_tail[i] = max(q_tail[i+1], q_tail[i]) + times[job_next][i]
            cost = 0
            for i in range(m):
                val = f[i] + q_tail[i]
                if val > cost:
                    cost = val
            if cost < best_cost or (cost == best_cost and pos < best_pos):
                best_cost = cost
                best_pos = pos
        return best_cost, best_pos

    def construct_neh():
        if len(jobs_sorted) < 2:
            return jobs_sorted[:]
        seq0 = [jobs_sorted[0], jobs_sorted[1]]
        seq1 = [jobs_sorted[1], jobs_sorted[0]]
        if taillard_makespan(seq0) <= taillard_makespan(seq1):
            current = seq0[:]
        else:
            current = seq1[:]
        for idx in range(2, len(jobs_sorted)):
            job = jobs_sorted[idx]
            _, pos = taillard_insertion_cost(current, job)
            current.insert(pos, job)
        return current

    current = construct_neh()
    best = current[:]
    best_makespan = taillard_makespan(best)

    total_sum = sum(total_processing)
    T_param = 0.5
    T = T_param * total_sum / (10 * n * m) if n * m > 0 else 1e-6
    d = 3 if n > 20 else 2
    max_iter = 60

    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            R = current[:]
            current = []
        else:
            indices = random.sample(range(len(current)), d)
            indices.sort(reverse=True)
            R = [current.pop(i) for i in indices]
            destroyed = current
        random.shuffle(R)
        for job in R:
            _, pos = taillard_insertion_cost(destroyed, job)
            destroyed.insert(pos, job)
        current = destroyed
        curr_makespan = taillard_makespan(current)
        if curr_makespan < best_makespan:
            best_makespan = curr_makespan
            best = current[:]
        if curr_makespan < taillard_makespan(best):
            best = current[:]
            best_makespan = curr_makespan
        if curr_makespan < taillard_makespan(current):
            current = current[:]
        if curr_makespan < taillard_makespan(best):
            best = current[:]
            best_makespan = curr_makespan
        if curr_makespan < taillard_makespan(current) or random.random() < math.exp(-(curr_makespan - taillard_makespan(current)) / T):
            pass
        else:
            current = best[:]

    return best

