                current_makespan = new_makespan
                improved = True
                if new_makespan < best_makespan:
                    best_makespan = new_makespan
                    best_perm = perm[:]
            else:
                # Revert swap if not improving
                perm[i], perm[i+1] = perm[i+1], perm[i]
        if not improved:
            no_improve += 1
            if no_improve >= no_improve_limit:
