def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + times[job][m]
        return t[-1]

    def makespan_with_tail(seq, x):
        k = len(seq)
        if k == 0:
            t = [0] * M
            for m in range(M):
                t[m] = (t[m-1] if m > 0 else 0) + times[x][m]
            return t[-1]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = (e[0][m-1] if m > 0 else 0) + times[seq[0]][m]
        for r in range(1, k):
            job_r = seq[r]
            for m in range(M):
                left = e[r-1][m]
                up = e[r][m-1] if m > 0 else 0
                e[r][m] = max(left, up) + times[job_r][m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = seq[r]
            for m in range(M-1, -1, -1):
                down = q[r+1][m]
                right = q[r][m+1] if m < M-1 else 0
                q[r][m] = max(down, right) + times[job_r][m]
        best_cmax = float('inf')
        best_pos = 0
        for i in range(k+1):
            f = [0] * M
            if i == 0:
                prev_e = [0] * M
            else:
                prev_e = e[i-1]
            for m in range(M):
                left = f[m-1] if m > 0 else 0
                up = prev_e[m]
                f[m] = max(left, up) + times[x][m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_cmax, best_pos

    def neh_construct(job_order):
        if not job_order:
            return []
        seq = [job_order[0]]
        for idx in range(1, len(job_order)):
            job = job_order[idx]
            _, pos = makespan_with_tail(seq, job)
            seq.insert(pos, job)
        return seq

    def ig_improve(initial_seq, max_iters, T):
        current = initial_seq[:]
        best = current[:]
        best_cmax = makespan(best)
        N_local = len(current)
        if N_local <= 1:
            return best
        for _ in range(max_iters):
            d = min(3, N_local)
            if d < 1:
                d = 1
            positions = random.sample(range(N_local), d)
            removed = [current[pos] for pos in sorted(positions, reverse=True)]
            for pos in sorted(positions, reverse=True):
                del current[pos]
            random.shuffle(removed)
            for job in removed:
                _, pos = makespan_with_tail(current, job)
                current.insert(pos, job)
            curr_cmax = makespan(current)
            if curr_cmax < best_cmax:
                best_cmax = curr_cmax
                best = current[:]
            if curr_cmax < makespan(best):
                pass
            if curr_cmax < makespan(current):
                current = current[:]
            delta = curr_cmax - makespan(current)
            if curr_cmax < makespan(current) or random.random() < math.exp(-delta / T):
                pass
            if curr_cmax < makespan(current):
                pass
            if curr_cmax < makespan(best):
                best = current[:]
                best_cmax = curr_cmax
            if curr_cmax < makespan(current) or random.random() < math.exp(-(curr_cmax - makespan(current)) / T):
                current = current[:]
        return best

    total = sum(sum(job) for job in times)
    T = 0.5 * total / (10 * N * M) if N * M > 0 else 1e-6
    base_order = sorted(range(N), key=lambda i: sum(times[i]), reverse=True)
    best_seq = None
    best_cmax = float('inf')
    for _ in range(3):
        noise = [random.uniform(0.9, 1.1) for _ in range(N)]
        noisy_order = sorted(range(N), key=lambda i: sum(times[i]) * noise[i], reverse=True)
        seq = neh_construct(noisy_order)
        cmax = makespan(seq)
        if cmax < best_cmax:
            best_cmax = cmax
            best_seq = seq
    improved = ig_improve(best_seq, 50, T)
    return improved

