        removed = [current_seq[i] for i in indices]
        # Build partial sequence without removed jobs
        idx = 0
        for i in range(N):
            if i not in indices:
                partial_seq[idx] = current_seq[i]
                idx += 1
        partial_len = N - d

        # Reconstruct by reinserting removed jobs one by one
        for job in removed:
            # Compute forward matrix e for current partial_seq
            for r in range(partial_len):
                if r == 0:
                    e[0][0] = times[partial_seq[0]][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + times[partial_seq[0]][m]
                else:
                    e[r][0] = e[r-1][0] + times[partial_seq[r]][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + times[partial_seq[r]][m]
            # Compute backward matrix q for current partial_seq
            for m in range(M):
                q[partial_len][m] = 0
            for r in range(partial_len-1, -1, -1):
                q[r][M-1] = q[r+1][M-1] + times[partial_seq[r]][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[partial_seq[r]][m]
            # Evaluate insertion positions for job
            best_pos = 0
            best_cmax_local = float('inf')
            for i in range(partial_len + 1):
                if i == 0:
                    f_vec[0] = times[job][0]
                    for m in range(1, M):
                        f_vec[m] = max(f_vec[m-1], 0) + times[job][m]
                else:
                    f_vec[0] = e[i-1][0] + times[job][0]
                    for m in range(1, M):
                        f_vec[m] = max(f_vec[m-1], e[i-1][m]) + times[job][m]
                cmax_candidate = 0
                for m in range(M):
                    val = f_vec[m] + q[i][m]
                    if val > cmax_candidate:
                        cmax_candidate = val
                if cmax_candidate < best_cmax_local:
                    best_cmax_local = cmax_candidate
                    best_pos = i
            # Insert job at best_pos
            partial_seq.insert(best_pos, job)
            partial_len += 1

        new_seq = partial_seq[:]
        new_cmax = makespan(new_seq)

        # Acceptance criterion
        if new_cmax < current_cmax:
            current_seq = new_seq
            current_cmax = new_cmax
            if new_cmax < best_cmax:
                best_seq = new_seq[:]
                best_cmax = new_cmax
        else:
            if random.random() < math.exp(-(new_cmax - current_cmax) / T):
                current_seq = new_seq
                current_cmax = new_cmax

    return best_seq

