def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten processing times for fast access
    p_flat = [times[i][j] for i in range(N) for j in range(M)]
    total_processing = sum(p_flat)

    # Precompute job priority for NEH: total processing time descending
    job_totals = [sum(times[i]) for i in range(N)]
    job_order = sorted(range(N), key=lambda i: (-job_totals[i], i))

    # Helper: makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            base = p_flat[job * M:(job + 1) * M]
            t[0] += base[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + base[m]
        return t[-1]

    # Taillard acceleration: compute forward matrix e for prefix of length k
    def compute_forward(perm, k):
        e = [[0] * M for _ in range(k)]
        if k == 0:
            return e
        job0 = perm[0]
        base0 = p_flat[job0 * M:(job0 + 1) * M]
        e[0][0] = base0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + base0[m]
        for r in range(1, k):
            job = perm[r]
            base = p_flat[job * M:(job + 1) * M]
            e[r][0] = e[r-1][0] + base[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + base[m]
        return e

    # Taillard acceleration: compute backward tail matrix q for prefix of length k
    def compute_backward(perm, k):
        q = [[0] * M for _ in range(k+1)]
        if k == 0:
            return q
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = perm[r]
            base = p_flat[job * M:(job + 1) * M]
            q[r][M-1] = q[r+1][M-1] + base[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + base[m]
        return q

    # Evaluate makespan of inserting job x at position i in perm of length k using Taillard
    def insertion_makespan(perm, k, x, e, q):
        f = [0] * M
        base_x = p_flat[x * M:(x + 1) * M]
        if k == 0:
            f[0] = base_x[0]
            for m in range(1, M):
                f[m] = f[m-1] + base_x[m]
        else:
            e_prev = e[-1] if k-1 >= 0 else [0]*M
            if k-1 >= 0:
                f[0] = e_prev[0] + base_x[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e_prev[m]) + base_x[m]
            else:
                f[0] = base_x[0]
                for m in range(1, M):
                    f[m] = f[m-1] + base_x[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[k][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH with Taillard acceleration
    def neh_construct():
        if N == 0:
            return []
        perm = [job_order[0]]
        if N == 1:
            return perm
        # Try both orders for first two jobs
        seq1 = [job_order[0], job_order[1]]
        seq2 = [job_order[1], job_order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        # Insert remaining jobs
        for k in range(2, N):
            job = job_order[k]
            e = compute_forward(perm, k)
            q = compute_backward(perm, k)
            best_pos = 0
            best_makespan = float('inf')
            for i in range(k+1):
                m = insertion_makespan(perm, k, job, e, q)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(initial_perm):
        current = initial_perm[:]
        best = current[:]
        best_makespan = makespan(best)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N >= 3 else N
        max_iter = 60

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            if d == 0:
                destroyed = []
                remaining = current[:]
            else:
                indices = random.sample(range(N), d)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(N) if i not in indices_set]

            # Reconstruction: reinsert destroyed jobs one by one using NEH insertion with Taillard
            for job in destroyed:
                k = len(remaining)
                e = compute_forward(remaining, k)
                q = compute_backward(remaining, k)
                best_pos = 0
                best_m = float('inf')
                for i in range(k+1):
                    m = insertion_makespan(remaining, k, job, e, q)
                    if m < best_m:
                        best_m = m
                        best_pos = i
                remaining.insert(best_pos, job)

            current = remaining
            curr_makespan = makespan(current)
            if curr_makespan < best_makespan:
                best_makespan = curr_makespan
                best = current[:]
            # Metropolis acceptance
            if curr_makespan < makespan(current):
                current = current[:]
            elif random.random() < math.exp(-(curr_makespan - makespan(current)) / T):
                current = current[:]
            else:
                # Revert to previous current (not accepted)
                pass  # current remains as destroyed+reinserted only if accepted

        return best

    # Run NEH then IG
    initial = neh_construct()
    return iterated_greedy(initial)

