def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[M-1]

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0]*M]
        e = [[0]*M for _ in range(k)]
        job0 = times[perm[0]]
        e[0][0] = job0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0[m]
        for r in range(1, k):
            job = times[perm[r]]
            e[r][0] = e[r-1][0] + job[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job[m]
        return e

    def compute_backward(perm):
        k = len(perm)
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = times[perm[r]]
            q[r][M-1] = q[r+1][M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job[m]
        return q

    def makespan_insert(e, q, job_idx, pos):
        job = times[job_idx]
        f = [0]*M
        if pos == 0:
            f[0] = job[0]
            for m in range(1, M):
                f[m] = f[m-1] + job[m]
        else:
            e_prev = e[pos-1]
            f[0] = e_prev[0] + job[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + job[m]
        q_pos = q[pos]
        max_val = 0
        for m in range(M):
            val = f[m] + q_pos[m]
            if val > max_val:
                max_val = val
        return max_val

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: (-P[i], i))

    perm = [order[0]]
    if N > 1:
        job1 = order[1]
        seq1 = [order[0], job1]
        seq2 = [job1, order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2

    for idx in range(2, N):
        job = order[idx]
        e = compute_forward(perm)
        q = compute_backward(perm)
        best_pos = 0
        best_makespan = float('inf')
        for pos in range(len(perm)+1):
            cmax = makespan_insert(e, q, job, pos)
            if cmax < best_makespan:
                best_makespan = cmax
                best_pos = pos
        perm.insert(best_pos, job)

    pi = perm[:]
    pi_star = pi[:]
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 4
    max_iter = 60

    for _ in range(max_iter):
        indices = list(range(N))
        random.shuffle(indices)
        removed = []
        remaining = pi[:]
        for idx in indices[:d]:
            job = remaining.pop(remaining.index(indices[idx]))
            removed.append(job)
        random.shuffle(removed)
        for job in removed:
            e = compute_forward(remaining)
            q = compute_backward(remaining)
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(remaining)+1):
                cmax = makespan_insert(e, q, job, pos)
                if cmax < best_makespan:
                    best_makespan = cmax
                    best_pos = pos
            remaining.insert(best_pos, job)
        pi_new = remaining
        c_new = makespan(pi_new)
        c_curr = makespan(pi)
        if c_new < c_curr:
            pi = pi_new
            if c_new < makespan(pi_star):
                pi_star = pi_new[:]
        elif T > 1e-10:
            if random.random() < math.exp(-(c_new - c_curr) / T):
                pi = pi_new

    return pi_star

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if N == 1:
        return [0]
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten times for faster access
    flat_times = [0] * (N * M)
    for i in range(N):
        for j in range(M):
            flat_times[i * M + j] = times[i][j]

    # Helper to get processing time
    def p(job, machine):
        return flat_times[job * M + machine]

    # Compute makespan for a given sequence
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            base = p(job, 0)
            t[0] += base
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p(job, m)
        return t[M-1]

    # Taillard's acceleration for makespan evaluation after insertion
    def makespan_with_insertion(partial_seq, job, pos):
        k = len(partial_seq)
        # Forward matrix e: [k][M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial_seq[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][m] = prev + p(job_r, m)
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + p(job_r, m)

        # Backward matrix q: [(k+1)][M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = partial_seq[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    down = q[r+1][m]
                    q[r][m] = down + p(job_r, m)
                else:
                    down = q[r+1][m]
                    right = q[r][m+1]
                    q[r][m] = max(down, right) + p(job_r, m)

        # Forward vector f for inserting 'job' at position 'pos'
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev_e = e[pos-1][0] if pos > 0 else 0
                f[m] = prev_e + p(job, m)
            else:
                left_f = f[m-1]
                up_e = e[pos-1][m] if pos > 0 else 0
                f[m] = max(left_f, up_e) + p(job, m)

        # Compute makespan: max over m of (f[m] + q[pos][m])
        max_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > max_val:
                max_val = val
        return max_val

    # NEH construction with Taillard acceleration
    total_times = [0] * N
    for i in range(N):
        s = 0
        base = i * M
        for j in range(M):
            s += flat_times[base + j]
        total_times[i] = s

    # Sort jobs by total processing time descending
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    if N == 0:
        return []
    if N == 1:
        return [order[0]]

    # Initial pair
    seq = [order[0], order[1]]
    rev_seq = [order[1], order[0]]
    if makespan(rev_seq) < makespan(seq):
        seq = rev_seq

    # Greedy insertion
    for k in range(2, N):
        job = order[k]
        best_pos = 0
        best_mk = makespan_with_insertion(seq, job, 0)
        for pos in range(1, k+1):
            mk = makespan_with_insertion(seq, job, pos)
            if mk < best_mk:
                best_mk = mk
                best_pos = pos
        seq.insert(best_pos, job)

    # Iterated Greedy (IG) parameters
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
    max_iter = 50  # Calibrated for <50ms

    pi = seq[:]
    pi_star = pi[:]
    mk_star = makespan(pi_star)

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d > 0 and len(pi) >= d:
            indices = random.sample(range(len(pi)), d)
            indices.sort(reverse=True)
            R = []
            for idx in indices:
                R.append(pi.pop(idx))
            pi_D = pi[:]  # remaining sequence
        else:
            pi_D = pi[:]
            R = []

        # Reconstruction: reinsert jobs in R using NEH insertion (Taillard accelerated)
        for job in R:
            if not pi_D:
                pi_D.append(job)
                continue
            best_pos = 0
            best_mk = makespan_with_insertion(pi_D, job, 0)
            for pos in range(1, len(pi_D)+1):
                mk = makespan_with_insertion(pi_D, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            pi_D.insert(best_pos, job)

        pi_new = pi_D
        mk_new = makespan(pi_new)

        # Acceptance criterion
        if mk_new < makespan(pi):
            pi = pi_new
            if mk_new < mk_star:
                pi_star = pi_new
                mk_star = mk_new
        else:
            delta = mk_new - makespan(pi)
            if delta < 0 or random.random() < math.exp(-delta / T):
                pi = pi_new

    return pi_star

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten processing times for faster access
    p = [times[i][:] for i in range(N)]

    # Compute total processing times for each job
    total = [sum(p[i]) for i in range(N)]

    # Sort jobs by total processing time descending (NEH priority)
    order = sorted(range(N), key=lambda i: total[i], reverse=True)

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += p[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard acceleration: compute forward matrix e for a partial schedule
    def compute_forward(perm):
        k = len(perm)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][m] = prev + p[job][m]
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + p[job][m]
        return e

    # Taillard acceleration: compute backward tail matrix q for a partial schedule
    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already by initialization
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job][m]
                else:
                    down = q[r+1][m]
                    right = q[r][m+1]
                    q[r][m] = max(down, right) + p[job][m]
        return q

    # Evaluate makespan for inserting job x at position i in partial schedule perm
    def insertion_makespan(perm, x, i, e, q):
        # Compute forward vector f for job x up to insertion point
        f = [0] * M
        if i == 0:
            prev_e = [0] * M
        else:
            prev_e = e[i-1]
        for m in range(M):
            if m == 0:
                f[m] = prev_e[0] + p[x][0]
            else:
                f[m] = max(f[m-1], prev_e[m]) + p[x][m]
        # Compute makespan as max over m of f[m] + q[i][m]
        ms = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > ms:
                ms = val
        return ms

    # Construct initial solution using NEH with Taillard acceleration
    def construct_initial():
        if len(order) < 2:
            return order[:]
        # Start with first two jobs
        best_start = [order[0], order[1]]
        alt_start = [order[1], order[0]]
        if makespan(alt_start) < makespan(best_start):
            best_start = alt_start
        perm = best_start[:]
        # Insert remaining jobs
        for idx in range(2, len(order)):
            job = order[idx]
            e = compute_forward(perm)
            q = compute_backward(perm)
            best_pos = 0
            best_ms = float('inf')
            # Try all insertion positions
            for pos in range(len(perm) + 1):
                ms = insertion_makespan(perm, job, pos, e, q)
                if ms < best_ms:
                    best_ms = ms
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_perm, max_iters=60):
        current = initial_perm[:]
        best = current[:]
        best_ms = makespan(best)
        total_processing = sum(total)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        d = 3 if N > 20 else 2  # destruction size

        for _ in range(max_iters):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build destroyed sequence by keeping non-removed jobs
            destroyed = [current[i] for i in range(N) if i not in indices]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                e = compute_forward(destroyed)
                q = compute_backward(destroyed)
                best_pos = 0
                best_ms_insert = float('inf')
                for pos in range(len(destroyed) + 1):
                    ms = insertion_makespan(destroyed, job, pos, e, q)
                    if ms < best_ms_insert:
                        best_ms_insert = ms
                        best_pos = pos
                destroyed.insert(best_pos, job)
            new_perm = destroyed
            new_ms = makespan(new_perm)
            # Acceptance criterion
            if new_ms < makespan(current):
                current = new_perm
                if new_ms < best_ms:
                    best = new_perm[:]
                    best_ms = new_ms
            else:
                if random.random() < math.exp(-(new_ms - makespan(current)) / T):
                    current = new_perm
        return best

    # Build initial solution
    init_perm = construct_initial()
    # Apply iterated greedy refinement
    final_perm = iterated_greedy(init_perm)
    return final_perm

