def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job data into flat lists for fast access
    p_flat = [0] * (N * M)
    for i in range(N):
        base = i * M
        row = times[i]
        for j in range(M):
            p_flat[base + j] = row[j]
    total_sum = sum(p_flat)

    # Helper: makespan of a given permutation (list of job indices)
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            base = job * M
            t[0] += p_flat[base]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p_flat[base + m]
        return t[-1]

    # Helper: compute forward completion matrix e for prefix of length k
    def compute_forward(prefix):
        k = len(prefix)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = prefix[r]
            base = job * M
            if r == 0:
                e[0][0] = p_flat[base]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p_flat[base + m]
            else:
                e[r][0] = e[r-1][0] + p_flat[base]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p_flat[base + m]
        return e

    # Helper: compute backward tail matrix q for prefix of length k
    def compute_backward(prefix):
        k = len(prefix)
        q = [[0] * M for _ in range(k+1)]  # q[k][*] = 0
        for r in range(k-1, -1, -1):
            job = prefix[r]
            base = job * M
            q[r][M-1] = q[r+1][M-1] + p_flat[base + M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p_flat[base + m]
        return q

    # Helper: evaluate makespan for inserting job x at position i in prefix
    def insertion_makespan(prefix, x, i, e, q):
        f = [0] * M
        base_x = x * M
        if i == 0:
            f[0] = p_flat[base_x]
            for m in range(1, M):
                f[m] = f[m-1] + p_flat[base_x + m]
        else:
            e_im1 = e[i-1]
            f[0] = e_im1[0] + p_flat[base_x]
            for m in range(1, M):
                f[m] = max(f[m-1], e_im1[m]) + p_flat[base_x + m]
        q_i = q[i]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q_i[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Helper: NEH insertion of one job using Taillard acceleration
    def neh_insert(prefix, job):
        k = len(prefix)
        if k == 0:
            return [job]
        e = compute_forward(prefix)
        q = compute_backward(prefix)
        best_pos = 0
        best_mk = insertion_makespan(prefix, job, 0, e, q)
        for pos in range(1, k+1):
            mk = insertion_makespan(prefix, job, pos, e, q)
            if mk < best_mk:
                best_mk = mk
                best_pos = pos
        return prefix[:best_pos] + [job] + prefix[best_pos:]

    # Construct initial solution using NEH with Taillard acceleration
    job_sums = [0] * N
    for i in range(N):
        base = i * M
        s = 0
        for j in range(M):
            s += p_flat[base + j]
        job_sums[i] = s
    order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
    if N >= 2:
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        if makespan(seq0) <= makespan(seq1):
            perm = seq0
        else:
            perm = seq1
    else:
        perm = [order[0]]
    for idx in range(2, N):
        perm = neh_insert(perm, order[idx])

    # Iterated Greedy refinement
    best_perm = perm[:]
    best_mk = makespan(best_perm)
    T_param = 0.5
    T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N >= 3 else N
    max_iter = 60  # calibrated for <50ms
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = list(range(N))
        random.shuffle(indices)
        removed = indices[:d]
        removed_set = set(removed)
        remaining = [job for job in perm if job not in removed_set]
        random.shuffle(removed)  # randomize reinsertion order
        # Reconstruction: reinsert each removed job using NEH insertion (Taillard accelerated)
        for job in removed:
            remaining = neh_insert(remaining, job)
        # Acceptance criterion
        mk = makespan(remaining)
        if mk < best_mk:
            best_mk = mk
            best_perm = remaining[:]
            perm = remaining[:]
        elif mk < makespan(perm):
            perm = remaining[:]
        else:
            if random.random() < math.exp(-(mk - makespan(perm)) / T):
                perm = remaining[:]
    return best_perm

