            if r == 0:
                e[0][0] = pj[0]
                for mc in range(1, m):
                    e[0][mc] = e[0][mc-1] + pj[mc]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for mc in range(1, m):
                    e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + pj[mc]
        return e

    def compute_backward(seq):
        k = len(seq)
        if k == 0:
            return [[0] * m]
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
