        pj = p[job]
        f = [0] * m
        if pos == 0:
            f[0] = pj[0]
            for mc in range(1, m):
                f[mc] = f[mc-1] + pj[mc]
        else:
            e_prev = e[pos-1]
            f[0] = e_prev[0] + pj[0]
            for mc in range(1, m):
                f[mc] = max(f[mc-1], e_prev[mc]) + pj[mc]
        q_pos = q[pos]
        max_val = 0
        for mc in range(m):
            val = f[mc] + q_pos[mc]
            if val > max_val:
                max_val = val
        return max_val

    def taillard_neh(seq, job):
