    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_times = [sum(job) for job in times]
    slope = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Helper: makespan of a permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # NEH with Taillard acceleration
    def neh_construction(order):
        if len(order) <= 1:
            return order[:]
        # Start with first two jobs
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        # Insert remaining jobs
        for k in range(2, len(order)):
            job = order[k]
            best_seq = None
            best_mk = float('inf')
            # Build forward matrix e for current seq (length k)
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = seq[r]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job_r][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job_r][m]
            # Build backward matrix q for current seq (length k)
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + times[job_r][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
            # Try all insertion positions
            for i in range(k+1):
                # Compute forward vector f for job at position i
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev = e[i-1][m] if i > 0 else 0
                        f[m] = prev + times[job][m]
                    else:
                        prev_f = f[m-1]
                        prev_e = e[i-1][m] if i > 0 else 0
                        f[m] = max(prev_f, prev_e) + times[job][m]
                # Compute makespan if job inserted at i
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
