            # Build forward matrix e for remaining (length k)
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = remaining[r]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job_r][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job_r][m]
            # Build backward matrix q for remaining (length k)
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = remaining[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + times[job_r][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
            # Try all insertion positions
            for i in range(k+1):
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev = e[i-1][m] if i > 0 else 0
                        f[m] = prev + times[job][m]
                    else:
                        prev_f = f[m-1]
                        prev_e = e[i-1][m] if i > 0 else 0
                        f[m] = max(prev_f, prev_e) + times[job][m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk_local:
                    best_mk_local = mk
                    best_seq_local = remaining[:i] + [job] + remaining[i:]
            remaining = best_seq_local
        new_seq = remaining
        new_mk = makespan(new_seq)
        # Acceptance criterion
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current_seq = new_seq
            current_mk = new_mk
            if new_mk < best_mk:
                best_seq = new_seq[:]
                best_mk = new_mk

    return best_seq

