def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0]) if n > 0 else 0
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times for each job
    total = [sum(times[i]) for i in range(n)]
    # Sort jobs by total processing time descending (NEH priority)
    order = sorted(range(n), key=lambda i: total[i], reverse=True)

    # Initialize makespan matrix for NEH construction
    makespan = [[0] * m for _ in range(n)]
    seq = [order[0]]
    # Makespan for first job
    makespan[0][0] = times[order[0]][0]
    for j in range(1, m):
        makespan[0][j] = makespan[0][j-1] + times[order[0]][j]

    # NEH construction with incremental makespan update
    for pos in range(1, n):
        job = order[pos]
        best_ms = float('inf')
        best_idx = 0
        # Try inserting 'job' at each possible position
        for idx in range(pos + 1):
            # Compute makespan for insertion at idx
            if idx == 0:
                # Insert at beginning
                prev = [0] * m
            else:
                prev = makespan[idx-1][:]
            # Process the inserted job
            curr = [0] * m
            for j in range(m):
                if j == 0:
                    curr[j] = prev[j] + times[job][j]
                else:
                    curr[j] = max(curr[j-1], prev[j]) + times[job][j]
            # Process remaining jobs from idx to pos-1 (shifted)
            for k in range(idx, pos):
                jk = seq[k]
                for j in range(m):
                    if j == 0:
                        curr[j] = curr[j] + times[jk][j]
                    else:
                        curr[j] = max(curr[j-1], curr[j]) + times[jk][j]
            ms = curr[m-1]
            if ms < best_ms:
                best_ms = ms
                best_idx = idx
        # Insert job at best_idx
        seq.insert(best_idx, job)
        # Recompute makespan matrix up to current length
        for i in range(pos + 1):
            if i == 0:
                makespan[0][0] = times[seq[0]][0]
                for j in range(1, m):
                    makespan[0][j] = makespan[0][j-1] + times[seq[0]][j]
            else:
                makespan[i][0] = makespan[i-1][0] + times[seq[i]][0]
                for j in range(1, m):
                    makespan[i][j] = max(makespan[i-1][j], makespan[i][j-1]) + times[seq[i]][j]

    # Iterated Greedy refinement
    def compute_makespan(s):
        ms = [[0] * m for _ in range(len(s))]
        if not s:
            return 0
        ms[0][0] = times[s[0]][0]
        for j in range(1, m):
            ms[0][j] = ms[0][j-1] + times[s[0]][j]
        for i in range(1, len(s)):
            ms[i][0] = ms[i-1][0] + times[s[i]][0]
            for j in range(1, m):
                ms[i][j] = max(ms[i-1][j], ms[i][j-1]) + times[s[i]][j]
        return ms[-1][-1] if ms else 0

    current_seq = seq[:]
    best_seq = current_seq[:]
    best_ms = compute_makespan(best_seq)
    total_processing = sum(total)
    T_param = 0.5
    T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6

    # Number of IG iterations calibrated for <50ms
    max_iter = 60
    for _ in range(max_iter):
        # Destruction: remove d=3 jobs randomly
        d = 3
        if n <= d:
            destroyed = []
            remaining = []
        else:
