            indices.sort(reverse=True)
            destroyed = [current_seq[i] for i in indices]
            remaining = [current_seq[i] for i in range(n) if i not in indices]
        # Reconstruction: reinsert destroyed jobs one by one
        for job in destroyed:
            best_ins_ms = float('inf')
            best_ins_idx = 0
            # Try inserting job at each position in remaining
            for idx in range(len(remaining) + 1):
                # Build temporary sequence
                temp = remaining[:idx] + [job] + remaining[idx:]
                ms = compute_makespan(temp)
                if ms < best_ins_ms:
                    best_ins_ms = ms
                    best_ins_idx = idx
            remaining.insert(best_ins_idx, job)
        new_seq = remaining
        new_ms = compute_makespan(new_seq)
        # Acceptance criterion
        if new_ms < compute_makespan(current_seq):
            current_seq = new_seq
            if new_ms < best_ms:
                best_seq = new_seq[:]
                best_ms = new_ms
        else:
            if random.random() < math.exp(-(new_ms - compute_makespan(current_seq)) / T):
                current_seq = new_seq
    return best_seq

