    T = T_param * total_work / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
    max_iters = 60

    for _ in range(max_iters):
        # Destruction: remove d random jobs
        indices = list(range(N))
        random.shuffle(indices)
        removed = indices[:d]
        removed_set = set(removed)
        pi_D = [job for job in pi if job not in removed_set]
        R = [pi[i] for i in removed]  # preserve removal order for reinsertion

        # Reconstruction: reinsert each job in R using Taillard-accelerated NEH
        for job in R:
            k = len(pi_D)
            if k == 0:
                pi_D = [job]
                continue
            # Rebuild e and q for current pi_D
            e = [[0] * M for _ in range(k)]
            q = [[0] * M for _ in range(k + 1)]
            for r in range(k):
                if r == 0:
                    e[r][0] = p(pi_D[r], 0)
                else:
                    e[r][0] = e[r-1][0] + p(pi_D[r], 0)
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p(pi_D[r], m)
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                q[r][M-1] = q[r+1][M-1] + p(pi_D[r], M-1)
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p(pi_D[r], m)
            # Find best insertion position
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                if i == 0:
                    f0 = p(job, 0)
                else:
                    f0 = e[i-1][0] + p(job, 0)
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], e[i-1][m]) + p(job, m))
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            pi_D.insert(best_pos, job)

        pi_new = pi_D
        C_new = makespan(pi_new)

        # Acceptance criterion
        if C_new < C_star:
            pi_star = pi_new[:]
            C_star = C_new
        if C_new < makespan(pi):
            pi = pi_new
        else:
            if random.random() < math.exp(-(C_new - makespan(pi)) / T):
                pi = pi_new

    return pi_star

