def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data and lower bounds
    job_data = [row[:] for row in times]
    total_processing = [sum(job) for job in job_data]
    job_order = sorted(range(N), key=lambda i: total_processing[i], reverse=True)
    sumM = sum(total_processing)
    LB = 0
    for m in range(M):
        sum_m = sum(job[i][m] for i in range(N))
        min_before = min((sum(job[i][:m]) for i in range(N)), default=0)
        min_after = min((sum(job[i][m+1:]) for i in range(N)), default=0)
        LB = max(LB, min_before + sum_m + min_after)

    # Helper: makespan of a permutation
    def makespan(perm):
        t = [0] * M
        for idx in perm:
            job = job_data[idx]
            for m in range(M):
                if m == 0:
                    t[m] += job[m]
                else:
                    t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    # NEH with Taillard acceleration and lower-bound pruning
    def neh_construction():
        if N == 0:
            return []
        seq = [job_order[0]]
        if N == 1:
            return seq
        # Initial pair
        seq1 = [job_order[0], job_order[1]]
        seq2 = [job_order[1], job_order[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        # Preallocate matrices
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N+1)]
        for k in range(2, N):
            job_idx = job_order[k]
            job = job_data[job_idx]
            # Forward pass for current seq (length k)
            for r in range(k):
                idx_j = seq[r]
                pj = job_data[idx_j]
                if r == 0:
                    e[0][0] = pj[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + pj[m]
                else:
                    e[r][0] = e[r-1][0] + pj[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
            # Backward pass
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                idx_j = seq[r]
                pj = job_data[idx_j]
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
            # Evaluate insertion positions with LB pruning
            best_pos = 0
            best_cmax = float('inf')
            e_im1 = [0] * M
            for i in range(k+1):
                if i > 0:
                    idx_prev = seq[i-1]
                    e_im1 = e[i-1][:]
                # Forward vector for job
                f = [0] * M
                f[0] = e_im1[0] + job[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e_im1[m]) + job[m]
                # LB-based pruning: optimistic makespan
                optimistic = f[-1] + sum(q[i])  # sum(q[i]) is a rough tail estimate
                if optimistic >= best_cmax:
                    continue
                # True makespan via max(f[m] + q[i][m])
                cmax = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax:
                        cmax = val
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = i
            seq.insert(best_pos, job_idx)
        return seq

    # Iterated Greedy with destruction size 3
    def iterated_greedy(init_seq, max_iters=50):
        current = init_seq[:]
        best = current[:]
        best_cmax = makespan(best)
        if best_cmax == LB:
            return best
        # Preallocate for speed
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N+1)]
        job_indices = list(range(N))
        for _ in range(max_iters):
            # Destruction: remove 3 random jobs
            if N <= 3:
                destroyed = []
                remaining = []
            else:
                destroyed = random.sample(job_indices, 3)
                remaining = [j for j in current if j not in destroyed]
            # Reconstruction: reinsert using NEH-like insertion
            for job_idx in destroyed:
                job = job_data[job_idx]
                k = len(remaining)
                # Forward pass for remaining
                for r in range(k):
                    idx_j = remaining[r]
                    pj = job_data[idx_j]
                    if r == 0:
                        e[0][0] = pj[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + pj[m]
                    else:
                        e[r][0] = e[r-1][0] + pj[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
                # Backward pass
                for m in range(M):
                    q[k][m] = 0
                for r in range(k-1, -1, -1):
                    idx_j = remaining[r]
                    pj = job_data[idx_j]
                    q[r][M-1] = q[r+1][M-1] + pj[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
                # Find best insert position
                best_pos = 0
                best_cmax_local = float('inf')
                e_im1 = [0] * M
                for i in range(k+1):
                    if i > 0:
                        idx_prev = remaining[i-1]
                        e_im1 = e[i-1][:]
                    f = [0] * M
                    f[0] = e_im1[0] + job[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e_im1[m]) + job[m]
                    # Prune with optimistic bound
                    optimistic = f[-1] + sum(q[i])
                    if optimistic >= best_cmax_local:
                        continue
                    cmax = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > cmax:
                            cmax = val
                    if cmax < best_cmax_local:
                        best_cmax_local = cmax
                        best_pos = i
                remaining.insert(best_pos, job_idx)
            current = remaining
            curr_cmax = makespan(current)
            if curr_cmax < best_cmax:
                best_cmax = curr_cmax
                best = current[:]
                if best_cmax == LB:
                    break
            # Metropolis acceptance
            if curr_cmax < makespan(current):
                current = current[:]
            elif random.random() < math.exp(-(curr_cmax - makespan(current)) / (0.5 * sumM / (10 * N * M))):
                current = current[:]
        return best

    # Run NEH then IG
    init_seq = neh_construction()
    return iterated_greedy(init_seq, max_iters=40)

