def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [row[:] for row in times]
    total_p = [sum(job) for job in p]

    # Makespan calculation using flow shop recurrence
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[-1]

    # Johnson's rule for two-machine flow shop
    def johnson_rule(job_indices, m1, m2):
        left, right = [], []
        for idx in job_indices:
            a, b = p[idx][m1], p[idx][m2]
            if a <= b:
                left.append(idx)
            else:
                right.append(idx)
        left.sort(key=lambda i: p[i][m1])
        right.sort(key=lambda i: p[i][m2], reverse=True)
        return left + right

    # CDS: generate M-1 permutations via Johnson's rule on artificial two-machine problems
    best_perm = None
    best_makespan = float('inf')
    for l in range(1, M):
        m1 = list(range(l))      # machines 0..l-1
        m2 = list(range(M-l, M)) # machines M-l..M-1
        p1 = [sum(p[i][j] for j in m1) for i in range(N)]
        p2 = [sum(p[i][j] for j in m2) for i in range(N)]
        # Create temporary processing times for Johnson's rule
        p_save = p[:]
        for i in range(N):
            p[i] = [p1[i], p2[i]]
        perm = johnson_rule(list(range(N)), 0, 1)
        p = p_save  # restore
        m = makespan(perm)
        if m < best_makespan:
            best_makespan = m
            best_perm = perm

    return best_perm

