def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times for NEH priority
    total = [sum(job) for job in times]
    order = sorted(range(n), key=lambda i: total[i], reverse=True)

    # Initialize makespan matrix for incremental evaluation
    C = [[0] * m for _ in range(n)]
    seq = []

    # NEH construction with idle time and waiting time awareness
    for idx in order:
        best_pos = 0
        best_makespan = float('inf')
        # Try inserting current job at each position
        for pos in range(len(seq) + 1):
            # Build temporary sequence
            temp_seq = seq[:pos] + [idx] + seq[pos:]
            # Compute makespan for temp_seq
            # Reset completion times
            for i in range(len(temp_seq)):
                for j in range(m):
                    if i == 0 and j == 0:
                        C[i][j] = times[temp_seq[i]][j]
                    elif i == 0:
                        C[i][j] = C[i][j-1] + times[temp_seq[i]][j]
                    elif j == 0:
                        C[i][j] = C[i-1][j] + times[temp_seq[i]][j]
                    else:
                        C[i][j] = max(C[i-1][j], C[i][j-1]) + times[temp_seq[i]][j]
            makespan = C[len(temp_seq)-1][m-1]
            # Calculate idle time and waiting time for this insertion
            idle_time = 0
            wait_time = 0
            for j in range(m):
                machine_idle = 0
                for i in range(len(temp_seq)):
                    start = C[i-1][j] if i > 0 else 0
                    if j > 0:
                        start = max(start, C[i][j-1])
                    else:
                        start = max(start, 0)
                    machine_idle += start - (C[i-1][j] if i > 0 else 0)
                idle_time += machine_idle
                job_wait = 0
                for i in range(len(temp_seq)):
                    start = C[i-1][j] if i > 0 else 0
                    if j > 0:
                        start = max(start, C[i][j-1])
                    else:
                        start = max(start, 0)
                    job_wait += start - (C[i-1][j] if i > 0 else 0)  # same as idle, but conceptually wait
                wait_time += job_wait
            # Combined objective: minimize makespan + idle + wait (weighted)
            score = makespan + 0.1 * idle_time + 0.1 * wait_time
            if score < best_makespan:
                best_makespan = score
                best_pos = pos
        seq.insert(best_pos, idx)

    return seq

