def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    P = [sum(row) for row in times]
    S = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Sort jobs by total processing time descending (primary), slope descending (secondary)
    jobs = sorted(range(N), key=lambda i: (-P[i], -S[i]))

    # Makespan evaluation function
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Taillard-accelerated insertion evaluation for a candidate job into a partial sequence
    def evaluate_insertion(partial, job, k):
        if k == 0:
            # Forward vector for empty partial
            f = [0] * M
            for m in range(M):
                if m == 0:
                    f[0] = times[job][0]
                else:
                    f[m] = max(f[m-1], 0) + times[job][m]
            # Backward tail for empty partial (q[0][m] = 0)
            return max(f)

        # Compute forward completion matrix e[0..k-1][0..M-1]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][0] = prev + times[job_r][0]
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + times[job_r][m]

        # Compute backward tail matrix q[0..k][0..M-1]
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already by initialization
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job_r][m]
                else:
                    down = q[r+1][m]
                    right = q[r][m+1]
                    q[r][m] = max(down, right) + times[job_r][m]

        best_cmax = float('inf')
        best_idle = float('inf')
        best_pos = 0

        # Evaluate each insertion position i in [0, k]
        for i in range(k+1):
            # Compute forward vector f for job at position i
            f = [0] * M
            if i == 0:
                prev_e = [0] * M
            else:
                prev_e = e[i-1]
            for m in range(M):
                if m == 0:
                    f[0] = prev_e[0] + times[job][0]
                else:
                    f[m] = max(f[m-1], prev_e[m]) + times[job][m]

            # Compute makespan: max_m (f[m] + q[i][m])
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val

            # Compute idle time on last machine if needed for tie-breaking
            if cmax == best_cmax:
                # Idle time on last machine: start time of last job on last machine minus completion of previous job on last machine
                if i == 0:
                    prev_comp_last = 0
                elif i == k:
                    prev_comp_last = e[k-1][M-1] if k > 0 else 0
                else:
                    prev_comp_last = e[i-1][M-1]
                start_last = f[M-1]
                idle = start_last - prev_comp_last
                if idle < best_idle:
                    best_idle = idle
                    best_pos = i
            elif cmax < best_cmax:
                best_cmax = cmax
                best_idle = float('inf')
                best_pos = i

        return best_pos

    # Construct initial solution using NEH with Taillard acceleration
    seq = [jobs[0]]
    for idx in range(1, N):
        job = jobs[idx]
        k = len(seq)
        pos = evaluate_insertion(seq, job, k)
        seq.insert(pos, job)

    # Iterated Greedy refinement
    current = seq[:]
    best = seq[:]
    best_cmax = makespan(best)

    # Compute average processing time for temperature
    total_p = sum(P)
    avg_p = total_p / (N * M) if N * M > 0 else 0
    T_param = 0.5
    T = T_param * avg_p * 10  # Scaled to ensure reasonable acceptance probability

    destruction_size = 3 if N > 20 else 2
    max_iterations = 50
    random.seed(42)  # For deterministic behavior in evaluation

    for _ in range(max_iterations):
        # Destruction: remove d jobs randomly
        if destruction_size >= N:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(N), destruction_size)
            indices_set = set(indices)
            destroyed = [current[i] for i in indices]
            remaining = [current[i] for i in range(N) if i not in indices_set]

        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        seq_D = remaining[:]
        for job in destroyed:
            k = len(seq_D)
            pos = evaluate_insertion(seq_D, job, k)
            seq_D.insert(pos, job)

        # Evaluate new solution
        new_cmax = makespan(seq_D)

        # Acceptance criterion
        if new_cmax < makespan(current) or random.random() < math.exp(-(new_cmax - makespan(current)) / T):
            current = seq_D[:]
            if new_cmax < best_cmax:
                best = seq_D[:]
                best_cmax = new_cmax

    return best

