def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing time and slope index
    total_times = [sum(job) for job in times]
    slope_index = []
    for i in range(N):
        s = 0
        for j in range(M):
            s += (2 * j - M + 1) * times[i][j]
        slope_index.append(s)

    # Try multiple priority orderings: total time descending, slope index descending
    priority_orders = [
        sorted(range(N), key=lambda i: (-total_times[i], i)),
        sorted(range(N), key=lambda i: (-slope_index[i], i))
    ]

    best_overall_seq = None
    best_overall_mk = float('inf')

    # Makespan calculation function
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + times[job][m]
        return t[-1]

    # Taillard acceleration for NEH insertion
    def taillard_neh(priority):
        if len(priority) == 0:
            return []
        seq = [priority[0]]
        if len(priority) == 1:
            return seq
        # Try both orders for first two jobs
        seq1 = [priority[0], priority[1]]
        seq2 = [priority[1], priority[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2

        # Insert remaining jobs
        for k in range(2, len(priority)):
            job = priority[k]
            best_pos = 0
            best_mk = float('inf')
            # Precompute forward matrix e for current seq of length k
            e = [[0] * M for _ in range(k)]
            # r = 0
            e[0][0] = times[seq[0]][0]
            for m in range(1, M):
                e[0][m] = e[0][m-1] + times[seq[0]][m]
            # r >= 1
            for r in range(1, k):
                e[r][0] = e[r-1][0] + times[seq[r]][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + times[seq[r]][m]

            # Precompute backward tail matrix q for current seq of length k
            q = [[0] * M for _ in range(k+1)]  # q[k][*] = 0
            # r from k-1 down to 0
            for r in range(k-1, -1, -1):
                q[r][M-1] = q[r+1][M-1] + times[seq[r]][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[seq[r]][m]

            # Evaluate each insertion position i in [0, k]
            for i in range(k+1):
                # Compute forward vector f for job at position i
                if i == 0:
                    prev_e = [0] * M
                else:
                    prev_e = e[i-1]
                f = [0] * M
                f[0] = prev_e[0] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + times[job][m]
                # Compute makespan: max_m (f[m] + q[i][m])
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk or (mk == best_mk and i < best_pos):
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Run NEH for each priority and keep the best
    for priority in priority_orders:
        seq = taillard_neh(priority)
        mk = makespan(seq)
        if mk < best_overall_mk:
            best_overall_mk = mk
            best_overall_seq = seq

    # Iterated Greedy refinement
    current_seq = best_overall_seq[:]
    current_mk = best_overall_mk
    best_seq = current_seq[:]
    best_mk = current_mk

    # Parameters for IG
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
    max_iter = 60  # Calibrated to stay within time budget

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d > 0:
            positions = random.sample(range(N), d)
            positions.sort(reverse=True)
            removed = []
            for pos in positions:
                removed.append(current_seq.pop(pos))
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                best_pos = 0
                best_mk = float('inf')
                k = len(current_seq)
                if k == 0:
                    current_seq.append(job)
                    continue
                # Precompute forward matrix e for current_seq
                e = [[0] * M for _ in range(k)]
                e[0][0] = times[current_seq[0]][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + times[current_seq[0]][m]
                for r in range(1, k):
                    e[r][0] = e[r-1][0] + times[current_seq[r]][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + times[current_seq[r]][m]
                # Precompute backward tail matrix q
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    q[r][M-1] = q[r+1][M-1] + times[current_seq[r]][M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[current_seq[r]][m]
                # Evaluate insertion positions
                for i in range(k+1):
                    if i == 0:
                        prev_e = [0] * M
                    else:
                        prev_e = e[i-1]
                    f = [0] * M
                    f[0] = prev_e[0] + times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev_e[m]) + times[job][m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk or (mk == best_mk and i < best_pos):
                        best_mk = mk
                        best_pos = i
                current_seq.insert(best_pos, job)
        else:
            # d == 0, no change
            pass

        new_mk = makespan(current_seq)
        # Acceptance criterion
        if new_mk < current_mk:
            current_seq = current_seq[:]
            current_mk = new_mk
            if new_mk < best_mk:
                best_seq = current_seq[:]
                best_mk = new_mk
        elif new_mk < best_mk:
            best_seq = current_seq[:]
            best_mk = new_mk
            if random.random() < math.exp(-(new_mk - current_mk) / T):
                current_seq = current_seq[:]
                current_mk = new_mk
        else:
            if random.random() < math.exp(-(new_mk - current_mk) / T):
                current_seq = current_seq[:]
                current_mk = new_mk

    return best_seq

