        if not jobs:
            return []
        seq = [jobs[0]]
        if len(jobs) == 1:
            return seq
        seq1 = [jobs[0], jobs[1]]
        seq2 = [jobs[1], jobs[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for k in range(2, len(jobs)):
            job = jobs[k]
            best_pos = 0
            best_ms = float('inf')
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = seq[r]
