            for i in range(k+1):
                f = [0] * M
                if i == 0:
                    f[0] = times[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + times[job][m]
                else:
                    prev = e[i-1]
                    f[0] = prev[0] + times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev[m]) + times[job][m]
                ms = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > ms:
                        ms = val
                if ms < best_ms:
                    best_ms = ms
                    best_pos = i
            seq.insert(best_pos, job)
