                    if r == 0:
                        e[0][0] = pj[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + pj[m]
                    else:
                        e[r][0] = e[r-1][0] + pj[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
                q = [[0] * M for _ in range(k+1)]
                for m in range(M):
                    q[k][m] = 0
                for r in range(k-1, -1, -1):
                    job_r = remaining[r]
                    pj = times[job_r]
                    q[r][M-1] = q[r+1][M-1] + pj[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
                for i in range(k+1):
                    f = [0] * M
                    if i == 0:
                        f[0] = times[job][0]
                        for m in range(1, M):
                            f[m] = f[m-1] + times[job][m]
                    else:
                        prev = e[i-1]
                        f[0] = prev[0] + times[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], prev[m]) + times[job][m]
                    ms = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > ms:
                            ms = val
                    if ms < best_ms_local:
                        best_ms_local = ms
                        best_pos = i
                remaining.insert(best_pos, job)
            new_ms = makespan(remaining)
            if new_ms < best_ms:
                best_ms = new_ms
                best_seq = remaining[:]
            if new_ms < makespan(current_seq) or random.random() < math.exp(-(new_ms - makespan(current_seq)) / T):
                current_seq = remaining[:]
        return best_seq

    total_times = [sum(row) for row in times]
    best_overall_seq = None
    best_overall_ms = float('inf')
    for _ in range(3):
        noise = [1.0 + random.uniform(-0.1, 0.1) for _ in range(N)]
