        jobs = sorted(range(N), key=lambda i: noisy_times[i], reverse=True)
        seq = taillard_neh(jobs)
        seq = ig_improve(seq, max_iter=50)
        ms = makespan(seq)
        if ms < best_overall_ms:
            best_overall_ms = ms
            best_overall_seq = seq
    return best_overall_seq

