        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for faster access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += p[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # NEH construction with Taillard acceleration
    def neh_construction():
        # Sort jobs by total processing time descending
        order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N == 0:
            return []
        # Start with first job
        perm = [order[0]]
        # Preallocate matrices
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N+1)]
        for k in range(1, N):
            job = order[k]
            # Forward pass for current perm of length k
            for r in range(k):
                jj = perm[r]
                if r == 0:
                    e[r][0] = p[jj][0]
                else:
                    e[r][0] = e[r-1][0] + p[jj][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[jj][m]
            # Backward pass initialization
            for m in range(M):
                q[k][m] = 0
            # Backward pass for current perm of length k
            for r in range(k-1, -1, -1):
                jj = perm[r]
                if r == k-1:
                    q[r][M-1] = p[jj][M-1]
                else:
                    q[r][M-1] = q[r+1][M-1] + p[jj][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[jj][m]
            # Evaluate insertion positions
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Compute forward vector f for job at position i
                if i == 0:
                    f0 = p[job][0]
                else:
                    f0 = e[i-1][0] + p[job][0]
                f = [0] * M
                f[0] = f0
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + p[job][m]
                # Compute makespan if inserted at i
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with Taillard-accelerated reinsertion
    def iterated_greedy(init_perm, max_iters=60):
        current = init_perm[:]
        best = current[:]
        best_mk = makespan(best)
        total = sum(total_p)
        T_param = 0.5
        T = T_param * total / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 5 else N
        # Preallocate for destruction/reconstruction
        perm_D = [0] * (N - d)
        R = [0] * d
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N+1)]
        for it in range(max_iters):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            # Build partial sequence
            idx = 0
            for i in range(N):
                if i not in indices_set:
                    perm_D[idx] = current[i]
                    idx += 1
            # Build extracted jobs list
            for idx, i in enumerate(indices):
                R[idx] = current[i]
            # Reconstruct using NEH insertion on perm_D
            # Start with empty sequence and insert jobs in R one by one
            seq = []
            for job in R:
                k = len(seq)
                if k == 0:
                    seq.append(job)
                    continue
                # Forward pass for current seq
                for r in range(k):
                    jj = seq[r]
                    if r == 0:
                        e[r][0] = p[jj][0]
                    else:
                        e[r][0] = e[r-1][0] + p[jj][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + p[jj][m]
                # Backward pass
                for m in range(M):
                    q[k][m] = 0
                for r in range(k-1, -1, -1):
                    jj = seq[r]
                    if r == k-1:
                        q[r][M-1] = p[jj][M-1]
                    else:
                        q[r][M-1] = q[r+1][M-1] + p[jj][M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + p[jj][m]
                # Evaluate insertion positions
                best_pos = 0
                best_mk_ins = float('inf')
                for i in range(k+1):
                    if i == 0:
                        f0 = p[job][0]
                    else:
                        f0 = e[i-1][0] + p[job][0]
                    f = [0] * M
                    f[0] = f0
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + p[job][m]
                    mk_ins = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk_ins:
                            mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                seq.insert(best_pos, job)
            new_perm = seq
            new_mk = makespan(new_perm)
            # Acceptance criterion
            if new_mk < best_mk:
                best_mk = new_mk
                best = new_perm[:]
            if new_mk < makespan(current):
                current = new_perm[:]
            else:
                if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                    current = new_perm[:]
        return best

    # Run NEH then IG
    init_perm = neh_construction()
    return iterated_greedy(init_perm, max_iters=50)

