def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = [sum(job) for job in times]
    first_machine = [job[0] for job in times]
    max_first = max(first_machine) if first_machine else 0
    adjusted_priority = [total_processing[i] - 0.5 * first_machine[i] for i in range(N)]
    order = sorted(range(N), key=lambda i: adjusted_priority[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_times[m]
        return t[-1]

    def taillard_makespan(perm):
        if not perm:
            return 0
        e_prev = [0] * M
        for job in perm:
            job_times = times[job]
            e_curr = [0] * M
            e_curr[0] = e_prev[0] + job_times[0]
            for m in range(1, M):
                e_curr[m] = max(e_prev[m], e_curr[m-1]) + job_times[m]
            e_prev = e_curr
        return e_prev[-1]

    def evaluate_insertion(current, job, e_prev, q_next):
        if not current:
            return times[job][0] if M == 1 else taillard_makespan([job])
        f = [0] * M
        job_times = times[job]
        if len(current) == 0:
            f[0] = job_times[0]
            for m in range(1, M):
                f[m] = max(f[m-1], 0) + job_times[m]
        else:
            f[0] = e_prev[0] + job_times[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + job_times[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q_next[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def taillard_insertion(current, job):
        k = len(current)
        if k == 0:
            return [job]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = current[r]
            job_times = times[job_r]
            if r == 0:
                e[0][0] = job_times[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_times[m]
            else:
                e[r][0] = e[r-1][0] + job_times[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_times[m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = current[r]
            job_times = times[job_r]
            q[r][M-1] = q[r+1][M-1] + job_times[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_times[m]
        best_pos = 0
        best_ms = float('inf')
        for i in range(k+1):
            if i == 0:
                e_prev = [0] * M
            else:
                e_prev = e[i-1]
            if i == k:
                q_next = [0] * M
            else:
                q_next = q[i]
            ms = evaluate_insertion(current, job, e_prev, q_next)
            if ms < best_ms:
                best_ms = ms
                best_pos = i
        return current[:best_pos] + [job] + current[best_pos:]

    def construct_initial():
        if N == 0:
            return []
        current = [order[0]]
        for idx in range(1, N):
            job = order[idx]
            current = taillard_insertion(current, job)
        return current

    def iterated_greedy(initial_sol, max_iters=50):
        current = initial_sol[:]
        best = current[:]
        best_ms = taillard_makespan(best)
        total_sum = sum(total_processing)
        T_param = 0.5
        T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 5 else N
        for _ in range(max_iters):
            destroyed = current[:]
            random.shuffle(destroyed)
            removed = destroyed[:d]
            pi_D = destroyed[d:]
            random.shuffle(removed)
            for job in removed:
                pi_D = taillard_insertion(pi_D, job)
            if taillard_makespan(pi_D) < taillard_makespan(current):
                current = pi_D[:]
            if taillard_makespan(pi_D) < best_ms:
                best = pi_D[:]
                best_ms = taillard_makespan(best)
            elif taillard_makespan(pi_D) > taillard_makespan(current):
                diff = taillard_makespan(pi_D) - taillard_makespan(current)
                if random.random() < math.exp(-diff / T):
                    current = pi_D[:]
        return best

    initial_sol = construct_initial()
    refined_sol = iterated_greedy(initial_sol, max_iters=40)
    return refined_sol

