                fi0 = e[i-1][0] + p[job][0]
                f = [fi0]
                for m in range(1, M):
                    f.append(max(f[m-1], e[i-1][m]) + p[job][m])
            # compute makespan: max over m of f[m] + q[i][m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
        return best_cmax

    def insert_job_neh(partial, job):
        k = len(partial)
        if k == 0:
            return [job]
        e = compute_forward(partial)
        q = compute_backward(partial)
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = p[job][0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], 0) + p[job][m])
            else:
                fi0 = e[i-1][0] + p[job][0]
                f = [fi0]
                for m in range(1, M):
                    f.append(max(f[m-1], e[i-1][m]) + p[job][m])
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return partial[:best_pos] + [job] + partial[best_pos:]

    # ---------- NEH construction with Taillard ----------
    def neh_construction():
        order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N < 2:
            return order[:]
        # initial two jobs
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        seq = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        for idx in range(2, N):
            seq = insert_job_neh(seq, order[idx])
        return seq

    # ---------- Iterated Greedy ----------
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_c = makespan(best)
        total_load = sum(total_p)
        T_param = 0.5
        T = T_param * total_load / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2
        if N > 60:
            d = 4

        for _ in range(max_iter):
            # destruction: remove d random jobs
            if d >= len(current):
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(len(current)), d)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(len(current)) if i not in indices_set]
            # reconstruction: reinsert destroyed jobs one by one in random order
            random.shuffle(destroyed)
            for job in destroyed:
                remaining = insert_job_neh(remaining, job)
            # acceptance
            new_c = makespan(remaining)
            if new_c < best_c:
                best_c = new_c
                best = remaining[:]
                current = remaining[:]
            elif new_c < makespan(current):
                current = remaining[:]
            else:
                if random.random() < math.exp(-(new_c - makespan(current)) / T):
                    current = remaining[:]
        return best

    # ---------- Main pipeline ----------
    initial_seq = neh_construction()
    # quick lower bound check (optional, can be skipped for speed)
    # refined = iterated_greedy(initial_seq, max_iter=50)
    refined = iterated_greedy(initial_seq, max_iter=40)  # tuned for <50ms
    return refined

