def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[-1]

    def taillard_evaluate(partial, job):
        k = len(partial)
        if k == 0:
            f = [0] * M
            for m in range(M):
                f[m] = (f[m-1] if m > 0 else 0) + times[job][m]
            return f[-1]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = (e[0][m-1] if m > 0 else 0) + times[partial[0]][m]
        for r in range(1, k):
            job_r = partial[r]
            job_r_t = times[job_r]
            for m in range(M):
                e[r][m] = max(e[r-1][m], e[r][m-1] if m > 0 else 0) + job_r_t[m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            job_r_t = times[job_r]
            for m in range(M-1, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1] if m < M-1 else 0) + job_r_t[m]
        best_cmax = float('inf')
        best_pos = 0
        for i in range(k+1):
            f = [0] * M
            if i == 0:
                for m in range(M):
                    f[m] = (f[m-1] if m > 0 else 0) + times[job][m]
            else:
                prev = e[i-1]
                for m in range(M):
                    f[m] = max(f[m-1] if m > 0 else 0, prev[m]) + times[job][m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_cmax, best_pos

    def taillard_evaluate_pair(partial, job1, job2):
        k = len(partial)
        if k == 0:
            f1 = [0] * M
            for m in range(M):
                f1[m] = (f1[m-1] if m > 0 else 0) + times[job1][m]
            f2 = [0] * M
            for m in range(M):
                f2[m] = max(f2[m-1] if m > 0 else 0, f1[m]) + times[job2][m]
            return f2[-1], 0
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = (e[0][m-1] if m > 0 else 0) + times[partial[0]][m]
        for r in range(1, k):
            job_r = partial[r]
            job_r_t = times[job_r]
            for m in range(M):
                e[r][m] = max(e[r-1][m], e[r][m-1] if m > 0 else 0) + job_r_t[m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            job_r_t = times[job_r]
            for m in range(M-1, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1] if m < M-1 else 0) + job_r_t[m]
        best_cmax = float('inf')
        best_i = 0
        best_j = 0
        for i in range(k+1):
            f1 = [0] * M
            if i == 0:
                for m in range(M):
                    f1[m] = (f1[m-1] if m > 0 else 0) + times[job1][m]
            else:
                prev = e[i-1]
                for m in range(M):
                    f1[m] = max(f1[m-1] if m > 0 else 0, prev[m]) + times[job1][m]
            for j in range(i, k+1):
                f2 = [0] * M
                if j == i:
                    for m in range(M):
                        f2[m] = max(f2[m-1] if m > 0 else 0, f1[m]) + times[job2][m]
                else:
                    prev = e[j-1]
                    for m in range(M):
                        f2[m] = max(f2[m-1] if m > 0 else 0, prev[m]) + times[job2][m]
                cmax = 0
                for m in range(M):
                    val = f2[m] + q[j][m]
                    if val > cmax:
                        cmax = val
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_i = i
                    best_j = j
        return best_cmax, best_i, best_j

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: (-P[i], i))
    pi = [order[0], order[1]]
    c1, _ = taillard_evaluate([order[0]], order[1])
    c2, _ = taillard_evaluate([order[1]], order[0])
    if c2 < c1:
        pi = [order[1], order[0]]
    for idx in range(2, N):
        job = order[idx]
        _, pos = taillard_evaluate(pi, job)
        pi.insert(pos, job)
    pi_star = pi[:]
    best_makespan = makespan(pi)
    max_iter = 60
    for _ in range(max_iter):
        d = 3 if N > 20 else 2
        if d > N:
            d = N
        indices = random.sample(range(N), d)
        indices.sort(reverse=True)
        removed = []
        for idx in indices:
            removed.append(pi.pop(idx))
        random.shuffle(removed)
        for job in removed:
            _, pos = taillard_evaluate(pi, job)
            pi.insert(pos, job)
        curr_makespan = makespan(pi)
        if curr_makespan < best_makespan:
            best_makespan = curr_makespan
            pi_star = pi[:]
        if curr_makespan < makespan(pi):
            pi = pi[:]
        else:
            delta = curr_makespan - makespan(pi)
            if delta < 0 or random.random() < math.exp(-delta / T):
                pi = pi[:]
            else:
                pi = pi_star[:]
    return pi_star

