import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for sorting
    total_times = [sum(job) for job in times]
    jobs_sorted = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Preallocate matrices for forward and backward passes
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N + 1)]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            pj = times[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[M-1]

    def compute_forward(seq, length):
        if length == 0:
            for m in range(M):
                e[-1][m] = 0  # using e[-1] as virtual row; handled via condition
        for r in range(length):
            job = seq[r]
            pj = times[job]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]

    def compute_backward(seq, length):
        for m in range(M):
            q[length][m] = 0
        for r in range(length-1, -1, -1):
            job = seq[r]
            pj = times[job]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]

    def insert_job_taillard(seq, length, job):
        best_pos = 0
        best_makespan = float('inf')
        pj = times[job]
        for i in range(length + 1):
            # Compute forward vector f for job at position i
            f = [0] * M
            if i == 0:
                f[0] = pj[0]
                for m in range(1, M):
                    f[m] = f[m-1] + pj[m]
            else:
                f[0] = e[i-1][0] + pj[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + pj[m]
            # Compute makespan candidate: max_m (f[m] + q[i][m])
            makespan_candidate = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_candidate:
                    makespan_candidate = val
            if makespan_candidate < best_makespan:
                best_makespan = makespan_candidate
                best_pos = i
        return best_pos

    # Construct initial solution using NEH with Taillard acceleration
    pi = []
    for idx in jobs_sorted:
        k = len(pi)
        pos = insert_job_taillard(pi, k, idx)
        pi.insert(pos, idx)
        compute_forward(pi, len(pi))
        compute_backward(pi, len(pi))

    # Iterated Greedy refinement
    current_pi = pi[:]
    best_pi = pi[:]
    current_makespan = makespan(current_pi)
    best_makespan = current_makespan

    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N

    max_iterations = 60
    for _ in range(max_iterations):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current_pi[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del current_pi[i]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            k = len(current_pi)
            pos = insert_job_taillard(current_pi, k, job)
            current_pi.insert(pos, job)
            compute_forward(current_pi, len(current_pi))
            compute_backward(current_pi, len(current_pi))
        # Acceptance criterion
        new_makespan = makespan(current_pi)
        if new_makespan < current_makespan:
            current_pi = current_pi[:]
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_pi = current_pi[:]
                best_makespan = new_makespan
        elif new_makespan < best_makespan:
            best_pi = current_pi[:]
            best_makespan = new_makespan
        else:
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current_pi = current_pi[:]
                current_makespan = new_makespan

    return best_pi

