import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flatten times for faster access
    flat_times = [t for row in times for t in row]
    def get_time(job, machine):
        return flat_times[job * M + machine]

    # Helper: compute makespan of a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            base = 0
            for m in range(M):
                base = max(t[m], base) + get_time(job, m)
                t[m] = base
        return t[-1]

    # Taillard's forward completion matrix for a given permutation (length k)
    def forward_matrix(perm):
        k = len(perm)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][0] = prev + get_time(job, 0)
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + get_time(job, m)
        return e

    # Taillard's backward tail matrix for a given permutation (length k)
    def backward_matrix(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]  # q[k][:] = 0
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + get_time(job, m)
                else:
                    down = q[r+1][m]
                    right = q[r][m+1]
                    q[r][m] = max(down, right) + get_time(job, m)
        return q

    # Evaluate makespan for inserting job x at position i in perm (length k)
    def insertion_makespan(perm, x, i):
        k = len(perm)
        e = forward_matrix(perm)
        q = backward_matrix(perm)
        # f[m]: completion of job x on machine m after insertion at i
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev_e = e[i-1][0] if i > 0 else 0
                f[0] = prev_e + get_time(x, 0)
            else:
                left = f[m-1]
                up = e[i-1][m] if i > 0 else 0
                f[m] = max(left, up) + get_time(x, m)
        # makespan = max_m (f[m] + q[i][m])
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    total_times = [sum(get_time(i, j) for j in range(M)) for i in range(N)]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    perm = [order[0], order[1]]
    if makespan([order[1], order[0]]) < makespan(perm):
        perm = [order[1], order[0]]
    for k in range(2, N):
        job = order[k]
        best_pos = 0
        best_mk = insertion_makespan(perm, job, 0)
        for pos in range(1, k+1):
            mk = insertion_makespan(perm, job, pos)
            if mk < best_mk:
                best_mk = mk
                best_pos = pos
        perm.insert(best_pos, job)

    # Iterated Greedy refinement
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2  # destruction size
    current = perm[:]
    best = perm[:]
    best_mk = makespan(best)
    max_iter = 60  # calibrated for <50ms
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del current[idx]
        # Reconstruction: reinsert each removed job using NEH insertion (Taillard)
        for job in removed:
            best_pos = 0
            best_mk_ins = insertion_makespan(current, job, 0)
            for pos in range(1, len(current)+1):
                mk = insertion_makespan(current, job, pos)
                if mk < best_mk_ins:
                    best_mk_ins = mk
                    best_pos = pos
            current.insert(best_pos, job)
        # Acceptance
        curr_mk = makespan(current)
        if curr_mk < best_mk:
            best_mk = curr_mk
            best = current[:]
        if curr_mk < makespan(perm):
            perm = current[:]
        else:
            if random.random() < math.exp(-(curr_mk - makespan(perm)) / T):
                perm = current[:]
            else:
                current = perm[:]  # reset to current perm for next iteration
    return best

