def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_time = [0] * N
    slope = [0] * N
    total_sum = 0
    for i in range(N):
        row = times[i]
        s = 0
        for j in range(M):
            t = row[j]
            s += t
            slope[i] += (2 * j - M + 1) * t
        total_time[i] = s
        total_sum += s

    # NEH construction with Taillard acceleration
    def makespan_from_order(order):
        if not order:
            return 0
        t0 = times[order[0]]
        c = t0[:]
        for m in range(1, M):
            c[m] += c[m-1]
        for idx in order[1:]:
            t = times[idx]
            c[0] += t[0]
            for m in range(1, M):
                c[m] = max(c[m-1], c[m]) + t[m]
        return c[-1]

    def evaluate_insertion(partial, job_idx, pos):
        k = len(partial)
        if k == 0:
            return times[job_idx][-1] if M == 1 else makespan_from_order([job_idx])
        # Forward matrix e for partial[0:pos]
        e = [0] * M
        if pos > 0:
            t0 = times[partial[0]]
            e[:] = t0[:]
            for m in range(1, M):
                e[m] += e[m-1]
            for r in range(1, pos):
                tr = times[partial[r]]
                e[0] += tr[0]
                for m in range(1, M):
                    e[m] = max(e[m-1], e[m]) + tr[m]
        # Forward vector f for job_idx
        f = [0] * M
        if pos == 0:
            f[:] = times[job_idx][:]
        else:
            t_job = times[job_idx]
            f[0] = e[0] + t_job[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[m]) + t_job[m]
        # Backward tail matrix q for partial[pos:k]
        q = [0] * M
        if pos < k:
            # Initialize q[k] = 0
            # Compute backward from r = k-1 down to pos
            for r in range(k-1, pos-1, -1):
                tr = times[partial[r]]
                if r == k-1:
                    for m in range(M):
                        q[m] = tr[m]
                else:
                    q[M-1] += tr[M-1]
                    for m in range(M-2, -1, -1):
                        q[m] = max(q[m], q[m+1]) + tr[m]
        # Compute makespan
        makespan = 0
        for m in range(M):
            val = f[m] + q[m]
            if val > makespan:
                makespan = val
        return makespan

    # Build initial order by total time descending
    order = list(range(N))
    order.sort(key=lambda i: total_time[i], reverse=True)
    # Start with first two jobs
    if N >= 2:
        best_two = [order[0], order[1]]
        best_two_rev = [order[1], order[0]]
        if makespan_from_order(best_two_rev) < makespan_from_order(best_two):
            best_two = best_two_rev
        current = best_two[:]
    else:
        current = order[:1]
    # Insert remaining jobs
    for idx in range(2, N):
        job = order[idx]
        best_pos = 0
        best_makespan = float('inf')
        for pos in range(len(current) + 1):
            m = evaluate_insertion(current, job, pos)
            if m < best_makespan:
                best_makespan = m
                best_pos = pos
        current.insert(best_pos, job)

    # Iterated Greedy refinement
    def destroy_and_reconstruct(seq, d):
        if d <= 0 or d > len(seq):
            return seq[:]
        indices = random.sample(range(len(seq)), d)
        removed = [seq[i] for i in indices]
        remaining = [seq[i] for i in range(len(seq)) if i not in indices]
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(remaining) + 1):
                m = evaluate_insertion(remaining, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            remaining.insert(best_pos, job)
        return remaining

    # Parameters for IG
    T_param = 0.5
    T = T_param * total_sum / (10 * N * M)
    if T < 1e-6:
        T = 1e-6
    current_seq = current[:]
    best_seq = current_seq[:]
    best_makespan = makespan_from_order(best_seq)
    # Determine number of iterations based on problem size to stay within time budget
    max_iter = 40 if N <= 30 else 60 if N <= 60 else 80
    d = 3 if N < 40 else 4
    for _ in range(max_iter):
        new_seq = destroy_and_reconstruct(current_seq, d)
        new_makespan = makespan_from_order(new_seq)
        if new_makespan < best_makespan:
            best_makespan = new_makespan
            best_seq = new_seq[:]
            current_seq = new_seq[:]
        elif new_makespan < makespan_from_order(current_seq):
            current_seq = new_seq[:]
        else:
            if random.random() < math.exp(-(new_makespan - makespan_from_order(current_seq)) / T):
                current_seq = new_seq[:]
    return best_seq

