            new_mk = makespan(seq)
            if new_mk < best_mk:
                best = seq[:]
                best_mk = new_mk
                current = seq[:]
            elif new_mk < makespan(current):
                current = seq[:]
            else:
                if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                    current = seq[:]
