def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flat list of processing times for each job
    p = [times[i][:] for i in range(N)]

    # Helper: makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[-1]

    # Taillard acceleration: forward completion matrix for a partial schedule
    def compute_forward(perm):
        k = len(perm)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][0] = prev + p[job][0]
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + p[job][m]
        return e

    # Taillard acceleration: backward tail matrix for a partial schedule
    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]  # q[k][:] = 0
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job][m]
                else:
                    down = q[r][m+1]
                    right = q[r+1][m]
                    q[r][m] = max(down, right) + p[job][m]
        return q

    # Evaluate makespan after inserting job x at position i using Taillard's O(M) method
    def evaluate_insertion(e, q, i, x):
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev_e = e[i-1][0] if i > 0 else 0
                f[0] = prev_e + p[x][0]
            else:
                left = f[m-1]
                up = e[i-1][m] if i > 0 else 0
                f[m] = max(left, up) + p[x][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    total_p = [sum(job) for job in p]
    order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
    perm = [order[0]]
    for k in range(1, N):
        job = order[k]
        e = compute_forward(perm)
        q = compute_backward(perm)
        best_pos = 0
        best_makespan = float('inf')
        for i in range(len(perm)+1):
            mk = evaluate_insertion(e, q, i, job)
            if mk < best_makespan:
                best_makespan = mk
                best_pos = i
        perm.insert(best_pos, job)

    # Iterated Greedy (IG) refinement
    total_processing = sum(total_p)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
    best_perm = perm[:]
    best_mk = makespan(best_perm)
    current_perm = perm[:]
    max_iters = 60  # Calibrated for <50ms on N<=120, M<=20
    for _ in range(max_iters):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current_perm[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del current_perm[idx]
        # Reconstruction: reinsert each removed job using NEH/Taillard
        for job in removed:
            e = compute_forward(current_perm)
            q = compute_backward(current_perm)
            best_pos = 0
            best_mk_ins = float('inf')
            for i in range(len(current_perm)+1):
                mk_ins = evaluate_insertion(e, q, i, job)
                if mk_ins < best_mk_ins:
                    best_mk_ins = mk_ins
                    best_pos = i
            current_perm.insert(best_pos, job)
        # Acceptance
        curr_mk = makespan(current_perm)
        if curr_mk < best_mk:
            best_mk = curr_mk
            best_perm = current_perm[:]
        if curr_mk < makespan(perm):
            perm = current_perm[:]
        else:
            if random.random() < math.exp(-(curr_mk - makespan(perm)) / T):
                perm = current_perm[:]
            else:
                current_perm = perm[:]
    return best_perm

