        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times and total times
    proc = [row[:] for row in times]
    total = [sum(row) for row in proc]

    # NEH with Taillard acceleration
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for idx in perm:
            p = proc[idx]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[m]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0]*M]
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            p = proc[perm[r]]
            if r == 0:
                e[0][0] = p[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[m]
            else:
                e[r][0] = e[r-1][0] + p[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[m]
        return e

    def compute_backward(perm):
        k = len(perm)
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            p = proc[perm[r]]
            if r == k-1:
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = p[m]
                    else:
                        q[r][m] = q[r][m+1] + p[m]
            else:
                q[r][M-1] = q[r+1][M-1] + p[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[m]
        return q

    def insertion_cost(perm, job, pos, e, q):
        if pos == 0:
            f = [0]*M
            pj = proc[job]
            if M > 0:
                f[0] = pj[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], 0) + pj[m]
            return max(f[m] + q[0][m] for m in range(M)) if M > 0 else 0
        else:
            e_prev = e[pos-1]
            pj = proc[job]
            f = [0]*M
            f[0] = e_prev[0] + pj[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + pj[m]
            return max(f[m] + q[pos][m] for m in range(M))

    # NEH construction
    order = sorted(range(N), key=lambda i: total[i], reverse=True)
    perm = [order[0]]
    if N > 1:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        perm = seq1 if makespan(seq1) <= makespan(seq2) else seq2
    for idx in range(2, N):
        job = order[idx]
        e = compute_forward(perm)
        q = compute_backward(perm)
        best_cost = float('inf')
        best_pos = 0
        for pos in range(len(perm)+1):
            cost = insertion_cost(perm, job, pos, e, q)
            if cost < best_cost:
                best_cost = cost
                best_pos = pos
        perm.insert(best_pos, job)

    # Iterated Greedy
    random.seed(42)
    total_proc = sum(total)
    T_param = 0.5
    T = T_param * total_proc / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N < 30 else 4
    current = perm[:]
    best = perm[:]
    best_makespan = makespan(best)
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for it in range(max_iter):
        if no_improve >= no_improve_limit:
            break
        # Destruction
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        remaining = [current[i] for i in range(N) if i not in indices]
        # Reconstruction
        for job in removed:
            e = compute_forward(remaining)
            q = compute_backward(remaining)
            best_cost = float('inf')
            best_pos = 0
            for pos in range(len(remaining)+1):
                cost = insertion_cost(remaining, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            remaining.insert(best_pos, job)
        # Acceptance
        new_makespan = makespan(remaining)
        if new_makespan < makespan(current):
            current = remaining[:]
            if new_makespan < best_makespan:
                best = remaining[:]
                best_makespan = new_makespan
                no_improve = 0
            else:
                no_improve += 1
        else:
            delta = new_makespan - makespan(current)
            if random.random() < math.exp(-delta / T):
                current = remaining[:]
                no_improve += 1
            else:
                no_improve += 1

    return best

