    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            base = p(job, 0)
            t[0] += base
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p(job, m)
        return t[-1]

    # Taillard accelerated insertion evaluation
    def evaluate_insertion(partial, job, k):
        if k == 0:
            e = [[0] * M]
            q = [[0] * M, [0] * M]
        else:
            # Forward matrix e: size k x M
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = partial[r]
                if r == 0:
                    e[0][0] = p(job_r, 0)
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + p(job_r, m)
                else:
                    e[r][0] = e[r-1][0] + p(job_r, 0)
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + p(job_r, m)
            # Backward matrix q: size (k+1) x M
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = partial[r]
                q[r][M-1] = q[r+1][M-1] + p(job_r, M-1)
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p(job_r, m)
        # Evaluate all insertion positions
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            # Compute forward vector f for job at position i
