    if N >= 2:
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        if makespan(seq0) <= makespan(seq1):
            current = seq0[:]
        else:
            current = seq1[:]
    else:
        current = [order[0]]
    for idx in range(2, N):
        job = order[idx]
        pos, _ = evaluate_insertion(current, job, len(current))
        current.insert(pos, job)

    # Iterated Greedy (IG) refinement
    total_processing = sum(total_p)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
