    best_seq = current[:]
    best_cmax = makespan(best_seq)
    current_seq = current[:]
    current_cmax = best_cmax
    max_iter = 60
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d == 0:
            destroyed = current_seq[:]
            extracted = []
        else:
            indices = random.sample(range(len(current_seq)), d)
            indices.sort(reverse=True)
            extracted = [current_seq.pop(i) for i in indices]
            destroyed = current_seq[:]
        # Reconstruction: reinsert extracted jobs one by one
        for job in extracted:
            k = len(destroyed)
            pos, _ = evaluate_insertion(destroyed, job, k)
            destroyed.insert(pos, job)
        new_seq = destroyed
        new_cmax = makespan(new_seq)
        # Acceptance criterion
        if new_cmax < current_cmax:
            current_seq = new_seq
            current_cmax = new_cmax
            if new_cmax < best_cmax:
                best_seq = new_seq
                best_cmax = new_cmax
        else:
            if random.random() < math.exp(-(new_cmax - current_cmax) / T):
                current_seq = new_seq
                current_cmax = new_cmax
    return best_seq

