def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data as flat lists for faster access
    p = [times[i][:] for i in range(N)]
    total_p = [sum(job) for job in p]

    # Compute lower bound (Taillard's machine-based)
    LB = 0
    for m in range(M):
        min_before = min(p[i][m'] for i in range(N) for m' in range(m)) if m > 0 else 0
        machine_sum = sum(p[i][m] for i in range(N))
        min_after = min(p[i][m'] for i in range(N) for m' in range(m+1, M)) if m < M-1 else 0
        LB = max(LB, min_before + machine_sum + min_after)

    # Makespan calculation with early termination if LB is reached
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for idx in seq:
            job = p[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
                if t[m] >= LB and m == M-1:  # Early exit if we already exceed LB at last machine
                    return t[m]
        return t[-1]

    # NEH construction with Taillard acceleration and lower-bound pruning
    def NEH():
        # Sort jobs by total processing time descending
        order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N <= 2:
            seq0 = [order[0], order[1]]
            seq1 = [order[1], order[0]]
            return seq0 if makespan(seq0) <= makespan(seq1) else seq1

        # Start with first two jobs
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]

