        for k in range(2, N):
            job_idx = order[k]
            job = p[job_idx]
            best_pos = 0
            best_mk = float('inf')

            # Precompute forward matrix e for current seq (length k)
            e = [[0]*M for _ in range(k)]
            for r in range(k):
                job_r = p[seq[r]]
                if r == 0:
                    e[0][0] = job_r[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_r[m]
                else:
                    e[r][0] = e[r-1][0] + job_r[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]

            # Precompute backward tail matrix q for current seq (length k)
            q = [[0]*M for _ in range(k+1)]  # q[k][:] = 0
            for r in range(k-1, -1, -1):
                job_r = p[seq[r]]
                q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]

            # Try all insertion positions 0..k
            for i in range(k+1):
                # Compute forward vector f for inserting job at position i
                f = [0]*M
                if i == 0:
                    f[0] = job[0]
                    for m in range(1, M):
                        f[m] = f[m-1] + job[m]
                else:
                    f[0] = e[i-1][0] + job[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + job[m]

                # Compute makespan candidate using f and q[i]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                        # Early exit if already worse than best
                        if mk >= best_mk:
                            break

                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
                    # Early exit if we hit the lower bound
                    if best_mk == LB:
                        break

            seq.insert(best_pos, job_idx)

        return seq

    # Iterated Greedy with Metropolis acceptance
    def iterated_greedy(init_seq, max_iters=50):
