                            f[m] = max(f[m-1], e[i-1][m]) + job[m]

                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                            if mk >= best_mk:
                                break

                    if mk < best_mk:
                        best_mk = mk
                        best_pos = i
                        if best_mk == LB:
                            break

                remaining.insert(best_pos, job_idx)

            # New sequence after reinsertion
            new_seq = remaining
            new_mk = makespan(new_seq)

            # Acceptance criterion
            if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
