def makespan(times, seq):
    if not seq:
        return 0
    n = len(seq)
    m = len(times[0])
    t = [0] * m
    for job in seq:
        job_t = times[job]
        t[0] += job_t[0]
        for i in range(1, m):
            t[i] = max(t[i-1], t[i]) + job_t[i]
    return t[-1]

def johnson_rule(times_two_machine):
    n = len(times_two_machine)
    left, right = [], []
    for idx, (a, b) in enumerate(times_two_machine):
        if a <= b:
            left.append((a, idx))
        else:
            right.append((b, idx))
    left.sort(key=lambda x: x[0])
    right.sort(key=lambda x: x[0], reverse=True)
    return [idx for _, idx in left] + [idx for _, idx in right]

def cds_variant(times):
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])
    if n == 1:
        return [0]
    best_seq = None
    best_cmax = float('inf')
    for l in range(1, m):
        times_two = []
        for i in range(n):
            a = sum(times[i][:l])
            b = sum(times[i][m-l:])
            times_two.append((a, b))
        seq = johnson_rule(times_two)
        cmax = makespan(times, seq)
        if cmax < best_cmax:
            best_cmax = cmax
            best_seq = seq
    return best_seq

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    return cds_variant(times)

