            q = [[0] * M for _ in range(k+1)]
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = p[pi_D[r]]
                q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
            for job in R:
                best_pos = 0
                best_mk = float('inf')
                for i in range(k+1):
                    if i == 0:
                        f0 = p[job][0]
                        f = [f0]
                        for m in range(1, M):
                            f.append(max(f[m-1], 0) + p[job][m])
