                        f0 = e[i-1][0] + p[job][0]
                        f = [f0]
                        for m in range(1, M):
                            f.append(max(f[m-1], e[i-1][m]) + p[job][m])
                    makespan_i = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > makespan_i:
                            makespan_i = val
                    if makespan_i < best_mk:
                        best_mk = makespan_i
                        best_pos = i
                pi_D.insert(best_pos, job)
                k += 1
            new_seq = pi_D
            new_makespan = makespan(new_seq)
            if new_makespan < current_makespan:
                current = new_seq
                current_makespan = new_makespan
                if new_makespan < best_makespan:
                    best = new_seq[:]
