        return perm[:best_i] + [job_idx] + perm[best_i:]

    def neh_construction():
        job_sums = [sum(job) for job in job_times]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        perm = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        for k in range(2, N):
            best_perm = None
            best_ms = float('inf')
            job_idx = order[k]
            for i in range(k + 1):
                candidate = perm[:i] + [job_idx] + perm[i:]
                ms = makespan(candidate)
                if ms < best_ms:
                    best_ms = ms
                    best_perm = candidate
            perm = best_perm
        return perm

    def iterated_greedy(initial_perm, max_iter=60):
        perm = initial_perm[:]
        best_perm = perm[:]
        best_ms = makespan(perm)
        d = 3 if N >= 3 else N
        for _ in range(max_iter):
            indices = list(range(N))
            random.shuffle(indices)
            removed_indices = indices[:d]
            removed_jobs = [perm[i] for i in removed_indices]
            remaining = [perm[i] for i in range(N) if i not in removed_indices]
            for job_idx in removed_jobs:
                best_pos = 0
                best_ms_local = float('inf')
                for pos in range(len(remaining) + 1):
                    candidate = remaining[:pos] + [job_idx] + remaining[pos:]
                    ms = makespan(candidate)
                    if ms < best_ms_local:
                        best_ms_local = ms
                        best_pos = pos
                remaining = remaining[:best_pos] + [job_idx] + remaining[best_pos:]
            if makespan(remaining) < best_ms:
                best_ms = makespan(remaining)
                best_perm = remaining[:]
            if makespan(remaining) < makespan(perm):
                perm = remaining[:]
            else:
                delta = makespan(remaining) - makespan(perm)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    perm = remaining[:]
        return best_perm

    initial_perm = neh_construction()
    improved_perm = iterated_greedy(initial_perm, max_iter=50)
    return improved_perm

