    flat_times = [t for job in times for t in job]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            base = job * M
            t[0] += flat_times[base]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + flat_times[base + m]
        return t[-1]

    # NEH with Taillard acceleration
    total_times = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    seq = [order[0]]
