        job = order[k]
        base_job = job * M

        # Forward pass for current seq (length k)
        for r in range(k):
            job_r = seq[r]
            base_r = job_r * M
            if r == 0:
                e[0][0] = flat_times[base_r]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + flat_times[base_r + m]
            else:
                e[r][0] = e[r-1][0] + flat_times[base_r]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + flat_times[base_r + m]

        # Backward pass initialization
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = seq[r]
            base_r = job_r * M
            q[r][M-1] = q[r+1][M-1] + flat_times[base_r + M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + flat_times[base_r + m]

        # Evaluate insertion positions
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            if i == 0:
                f[0] = flat_times[base_job]
                for m in range(1, M):
                    f[m] = f[m-1] + flat_times[base_job + m]
            else:
                job_prev = seq[i-1]
                base_prev = job_prev * M
                f[0] = e[i-1][0] + flat_times[base_job]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + flat_times[base_job + m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        seq.insert(best_pos, job)

