                    e[r][0] = e[r-1][0] + flat_times[base_r]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + flat_times[base_r + m]

            # Backward pass
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = current_seq[r]
                base_r = job_r * M
                q[r][M-1] = q[r+1][M-1] + flat_times[base_r + M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + flat_times[base_r + m]

            # Evaluate insertions
            best_pos = 0
            best_cmax_local = float('inf')
            for i in range(k+1):
                if i == 0:
                    f[0] = flat_times[base_job]
                    for m in range(1, M):
                        f[m] = f[m-1] + flat_times[base_job + m]
                else:
                    job_prev = current_seq[i-1]
                    base_prev = job_prev * M
                    f[0] = e[i-1][0] + flat_times[base_job]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + flat_times[base_job + m]
                cmax_local = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax_local:
                        cmax_local = val
                if cmax_local < best_cmax_local:
                    best_cmax_local = cmax_local
                    best_pos = i
            current_seq.insert(best_pos, job)

        # Acceptance
        current_cmax = makespan(current_seq)
        if current_cmax < best_cmax:
            best_cmax = current_cmax
            best_seq = current_seq[:]
        if current_cmax < makespan(seq):
            seq = current_seq[:]
        else:
            if random.random() < math.exp(-(current_cmax - makespan(seq)) / T):
                seq = current_seq[:]

    return best_seq

