def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times and total processing times
    p = [row[:] for row in times]
    P = [sum(row) for row in p]

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Compute forward completion matrix for a partial schedule
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job][m]
        return e

    # Compute backward tail matrix for a partial schedule
    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]
        return q

    # Evaluate makespan for inserting job x at position i in partial schedule perm
    def insertion_makespan(perm, x, i, e, q):
        k = len(perm)
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev = e[i-1][m] if i-1 >= 0 else 0
                f[m] = prev + p[x][m]
            else:
                prev = e[i-1][m] if i-1 >= 0 else 0
                f[m] = max(f[m-1], prev) + p[x][m]
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    def construct_initial():
        order = sorted(range(N), key=lambda i: P[i], reverse=True)
        if N == 0:
            return []
        perm = [order[0]]
        if N == 1:
            return perm
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            e = compute_forward(perm)
            q = compute_backward(perm)
            best_pos = 0
            best_mk = insertion_makespan(perm, job, 0, e, q)
            for i in range(1, k+1):
                mk = insertion_makespan(perm, job, i, e, q)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy refinement
    def iterated_greedy(init_perm):
        current = init_perm[:]
        best = current[:]
        total_p = sum(P)
        T_param = 0.5
        T = T_param * total_p / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N >= 3 else N
        max_iters = 60
        for _ in range(max_iters):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build destroyed sequence
            destroyed = [current[i] for i in range(N) if i not in indices]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                e = compute_forward(destroyed)
                q = compute_backward(destroyed)
                best_pos = 0
                best_mk = insertion_makespan(destroyed, job, 0, e, q)
                for i in range(1, len(destroyed)+1):
                    mk = insertion_makespan(destroyed, job, i, e, q)
                    if mk < best_mk:
                        best_mk = mk
                        best_pos = i
                destroyed.insert(best_pos, job)
            # New candidate sequence
            candidate = destroyed
            # Acceptance criterion
            curr_mk = makespan(current)
            cand_mk = makespan(candidate)
            best_mk = makespan(best)
            if cand_mk < curr_mk:
                current = candidate
                if cand_mk < best_mk:
                    best = candidate[:]
            else:
                if cand_mk < best_mk:
                    best = candidate[:]
                # Metropolis acceptance
                delta = cand_mk - curr_mk
                if delta < 0 or random.random() < math.exp(-delta / T):
                    current = candidate
        return best

    # Build initial solution and refine
    init_perm = construct_initial()
    return iterated_greedy(init_perm)

