                f0 = forward[i-1][0] + job_times[0]
            f = [0] * M
            f[0] = f0
            for m in range(1, M):
                f[m] = max(f[m-1], forward[i-1][m] if i-1 >= 0 else 0) + job_times[m]
            cmax = 0
            for m in range(M):
                val = f[m] + backward[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos, best_cmax

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: P[i], reverse=True)

    beam_width = 2
    beams = [([order[0]], None, None), ([order[1]], None, None)]
    if makespan([order[0], order[1]]) < makespan([order[1], order[0]]):
        beams = [([order[0], order[1]], None, None)]
    else:
        beams = [([order[1], order[0]], None, None)]

    for idx in range(2, N):
        job = order[idx]
        new_beams = []
        for seq, _, _ in beams:
            forward, backward = compute_forward_backward(seq)
            k = len(seq)
            pos, _ = insert_job_taillard(forward, backward, job, k)
            new_seq = seq[:pos] + [job] + seq[pos:]
            new_beams.append((new_seq, forward, backward))
        if len(new_beams) > beam_width:
            new_beams.sort(key=lambda x: makespan_with_tail(x[0], x[1], x[2]))
            beams = new_beams[:beam_width]
        else:
            beams = new_beams

    best_seq = None
    best_cmax = float('inf')
    for seq, forward, backward in beams:
        cmax = makespan_with_tail(seq, forward, backward)
        if cmax < best_cmax:
            best_cmax = cmax
            best_seq = seq
    return best_seq

