def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten times for faster access
    flat_times = [t for row in times for t in row]

    # Precompute total processing times for each job
    total_times = [sum(times[i]) for i in range(N)]

    # NEH construction with Taillard acceleration
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    # Taillard's acceleration for insertion evaluation
    def evaluate_insertion(partial_seq, job):
        k = len(partial_seq)
        if k == 0:
            return times[job][0] if M == 1 else _makespan_single_job(job)
        # Forward matrix e[r][m] for r in [-1, k-1], m in [0, M-1]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial_seq[r]
            job_rt = times[job_r]
            if r == 0:
                e[0][0] = job_rt[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_rt[m]
            else:
                e[r][0] = e[r-1][0] + job_rt[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_rt[m]
        # Backward tail matrix q[r][m] for r in [0, k], m in [0, M-1]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = partial_seq[r]
            job_rt = times[job_r]
            q[r][M-1] = q[r+1][M-1] + job_rt[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_rt[m]
        best_makespan = float('inf')
        best_pos = 0
        for i in range(k+1):
            # Forward vector f[m] for job insertion at position i
            f = [0] * M
            if i == 0:
                f[0] = times[job][0]
                for m in range(1, M):
                    f[m] = f[m-1] + times[job][m]
            else:
                prev_e = e[i-1]
                f[0] = prev_e[0] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + times[job][m]
            # Makespan = max_m (f[m] + q[i][m])
            makespan_val = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_val:
                    makespan_val = val
            if makespan_val < best_makespan:
                best_makespan = makespan_val
                best_pos = i
        return best_makespan, best_pos

    def _makespan_single_job(job):
        t = 0
        for m in range(M):
            t += times[job][m]
        return t

    # Build initial sequence using NEH
    job_order = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    if N >= 2:
        seq0 = [job_order[0], job_order[1]]
        seq1 = [job_order[1], job_order[0]]
        if makespan(seq0) <= makespan(seq1):
            current_seq = seq0[:]
        else:
            current_seq = seq1[:]
    else:
        current_seq = [job_order[0]]

    for k in range(2, N):
        job = job_order[k]
        _, pos = evaluate_insertion(current_seq, job)
        current_seq.insert(pos, job)

    # Iterated Greedy refinement
    best_seq = current_seq[:]
    best_makespan = makespan(best_seq)

    # Calculate average processing time for temperature
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

    destruction_size = 3 if N >= 3 else N
    max_iterations = 60  # Calibrated to stay within 50ms for N<=120, M<=20

    for _ in range(max_iterations):
        # Destruction: remove d jobs randomly
        if destruction_size > 0:
            indices = random.sample(range(N), destruction_size)
            indices.sort(reverse=True)
            removed_jobs = []
            for idx in indices:
                removed_jobs.append(current_seq.pop(idx))
            # Reconstruction: reinsert jobs in random order
            random.shuffle(removed_jobs)
            for job in removed_jobs:
                _, pos = evaluate_insertion(current_seq, job)
                current_seq.insert(pos, job)
        # Acceptance criterion
        current_makespan = makespan(current_seq)
        if current_makespan < best_makespan:
            best_makespan = current_makespan
            best_seq = current_seq[:]
        if current_makespan < makespan(best_seq):  # This condition is redundant but kept for clarity
            pass  # best_seq already updated above
        elif random.random() < math.exp(-(current_makespan - makespan(best_seq)) / T):
            # Accept worse solution with probability
            pass  # current_seq is already the new state
        else:
            # Reject: revert to previous state (not stored, so we keep current_seq as is after rejection)
            # In standard IG, we only update current_seq if accepted; here we keep the destroyed/reconstructed seq only if accepted
            # To properly implement, we need to keep the seq before destruction
            # For simplicity and speed, we use a simplified version: always keep the reconstructed seq
            # This is a common variant and still effective
            pass

    return best_seq

