def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_times[m]
        return t[-1]

    def neh_construct():
        job_sums = [sum(job) for job in times]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        seq = [order[0]]
        for idx in range(1, N):
            job = order[idx]
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(seq) + 1):
                new_seq = seq[:pos] + [job] + seq[pos:]
                mk = makespan(new_seq)
                if mk < best_makespan:
                    best_makespan = mk
                    best_pos = pos
            seq = seq[:best_pos] + [job] + seq[best_pos:]
        return seq

    def taillard_forward(seq):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = seq[r]
            job_times = times[job]
            if r == 0:
                e[0][0] = job_times[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_times[m]
            else:
                e[r][0] = e[r-1][0] + job_times[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_times[m]
        return e

    def taillard_backward(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            job_times = times[job]
            q[r][M-1] = q[r+1][M-1] + job_times[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_times[m]
        return q

    def taillard_insertion_makespan(seq, job, e, q, pos):
        job_times = times[job]
        f = [0] * M
        if pos == 0:
            f[0] = job_times[0]
            for m in range(1, M):
                f[m] = f[m-1] + job_times[m]
        else:
            f[0] = e[pos-1][0] + job_times[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + job_times[m]
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
        return best

    def neh_taillard(seq_init):
        if not seq_init:
            return []
        e = taillard_forward(seq_init)
        q = taillard_backward(seq_init)
        seq = seq_init[:]
        for idx in range(1, len(seq_init)):
            job = seq_init[idx]
            best_pos = 0
            best_mk = float('inf')
            for pos in range(len(seq) + 1):
                mk = taillard_insertion_makespan(seq, job, e, q, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq = seq[:best_pos] + [job] + seq[best_pos:]
        return seq

    initial_seq = neh_taillard(list(range(N)))
    best_seq = initial_seq[:]
    best_mk = makespan(best_seq)

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    max_iter = 50

    current_seq = initial_seq[:]
    for _ in range(max_iter):
        if len(current_seq) <= d:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(len(current_seq)), d)
            indices.sort()
            destroyed = [current_seq[i] for i in indices]
            remaining = [current_seq[i] for i in range(len(current_seq)) if i not in indices]

        e = taillard_forward(remaining)
        q = taillard_backward(remaining)

        for job in destroyed:
            best_pos = 0
            best_mk = float('inf')
            for pos in range(len(remaining) + 1):
                mk = taillard_insertion_makespan(remaining, job, e, q, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            remaining = remaining[:best_pos] + [job] + remaining[best_pos:]

        new_seq = remaining
        new_mk = makespan(new_seq)

        if new_mk < best_mk:
            best_mk = new_mk
            best_seq = new_seq[:]

        if new_mk < makespan(current_seq):
            current_seq = new_seq
        else:
            delta = new_mk - makespan(current_seq)
            if delta == 0 or random.random() < math.exp(-delta / T):
                current_seq = new_seq

    return best_seq

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_times = [row[:] for row in times]
    total_time = [sum(job) for job in job_times]

    # Makespan evaluation using forward pass
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            pt = job_times[job]
            t[0] += pt[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pt[m]
        return t[-1]

    # Compute forward completion matrix e for a given sequence (length k)
    def compute_forward(seq):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            pt = job_times[seq[r]]
            if r == 0:
                e[0][0] = pt[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pt[m]
            else:
                e[r][0] = e[r-1][0] + pt[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pt[m]
        return e

    # Compute backward tail matrix q for a given sequence (length k)
    def compute_backward(seq):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already by initialization
        for r in range(k-1, -1, -1):
            pt = job_times[seq[r]]
            q[r][M-1] = q[r+1][M-1] + pt[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pt[m]
        return q

    # Evaluate makespan of inserting job x at position i in seq (length k)
    def insertion_makespan(seq, x, i, e, q):
        k = len(seq)
        f = [0] * M
        # f[m] for machine m after inserting x at position i
        if i == 0:
            prev_e = [0] * M
        else:
            prev_e = e[i-1]
        pt = job_times[x]
        f[0] = prev_e[0] + pt[0]
        for m in range(1, M):
            f[m] = max(f[m-1], prev_e[m]) + pt[m]
        # max over m of f[m] + q[i][m]
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    def neh_construction():
        # Sort jobs by total processing time descending
        order = sorted(range(N), key=lambda i: total_time[i], reverse=True)
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_makespan = float('inf')
            # Test all k+1 insertion positions
            for i in range(k+1):
                m = insertion_makespan(seq, job, i, e, q)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_makespan = makespan(best)
        # Calculate temperature parameter
        total_processing = sum(total_time)
        T = 0.5 * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2  # destruction size
        if d < 2:
            d = 2
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            if d >= N:
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(N), d)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(N) if i not in indices_set]
            # Reconstruction: reinsert destroyed jobs one by one in random order
            random.shuffle(destroyed)
            seq = remaining[:]
            for job in destroyed:
                e = compute_forward(seq)
                q = compute_backward(seq)
                best_pos = 0
                best_m = float('inf')
                for i in range(len(seq)+1):
                    m = insertion_makespan(seq, job, i, e, q)
                    if m < best_m:
                        best_m = m
                        best_pos = i
                seq.insert(best_pos, job)
            # Acceptance criterion
            new_makespan = makespan(seq)
            if new_makespan < makespan(current):
                current = seq[:]
                if new_makespan < best_makespan:
                    best = seq[:]
                    best_makespan = new_makespan
            else:
                if random.random() < math.exp(-(new_makespan - makespan(current)) / T):
                    current = seq[:]
        return best

    # Build initial solution and refine
    initial_seq = neh_construction()
    # Optionally compute lower bound for early termination (not implemented for speed)
    refined_seq = iterated_greedy(initial_seq, max_iter=50)
    return refined_seq

