def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_times = [sum(job) for job in times]
    slope_indices = []
    for i in range(n):
        s = 0
        for j in range(m):
            s += (2 * j - m + 1) * times[i][j]
        slope_indices.append((s, i))
    slope_indices.sort(reverse=True)
    order_slope = [idx for _, idx in slope_indices]

    # Helper to compute makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            tj = times[job]
            t[0] += tj[0]
            for k in range(1, m):
                t[k] = max(t[k], t[k-1]) + tj[k]
        return t[-1]

    # NEH construction with Taillard acceleration
    def neh_construct(job_order):
        if not job_order:
            return []
        perm = [job_order[0]]
        # Forward and backward matrices will be reused
        e = [[0] * m for _ in range(len(job_order))]
        q = [[0] * m for _ in range(len(job_order) + 1)]
        for k in range(1, len(job_order)):
            job = job_order[k]
            # Update forward matrix e for current perm (length k)
            for r in range(k):
                rj = times[perm[r]]
                if r == 0:
                    e[r][0] = e[r-1][0] + rj[0] if r > 0 else rj[0]
                else:
                    e[r][0] = e[r-1][0] + rj[0]
                for mc in range(1, m):
                    e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + rj[mc]
            # Update backward matrix q for current perm (length k)
            for mc in range(m):
                q[k][mc] = 0
            for r in range(k-1, -1, -1):
                rj = times[perm[r]]
                q[r][m-1] = q[r+1][m-1] + rj[m-1]
                for mc in range(m-2, -1, -1):
                    q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + rj[mc]
            # Find best insertion position for job
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Compute forward vector f for job at position i
                f = [0] * m
                if i == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[i-1]
                f[0] = prev_e[0] + times[job][0]
                for mc in range(1, m):
                    f[mc] = max(f[mc-1], prev_e[mc]) + times[job][mc]
                # Compute makespan candidate
                mk = 0
                for mc in range(m):
                    val = f[mc] + q[i][mc]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Try multiple orderings for initial solution
    order_total = sorted(range(n), key=lambda i: total_times[i], reverse=True)
    best_perm = neh_construct(order_total)
    best_mk = makespan(best_perm)
    perm_slope = neh_construct(order_slope)
    mk_slope = makespan(perm_slope)
    if mk_slope < best_mk:
        best_mk = mk_slope
        best_perm = perm_slope

    # Lower bound check (Taillard's LB)
    lb = 0
    for mc in range(m):
        min_pre = min((sum(times[j][:mc]) for j in range(n)), default=0)
        min_suf = min((sum(times[j][mc+1:]) for j in range(n)), default=0)
        sum_mc = sum(times[j][mc] for j in range(n))
        lb_mc = min_pre + sum_mc + min_suf
        if lb_mc > lb:
            lb = lb_mc
    if best_mk == lb:
        return best_perm

    # Iterated Greedy parameters
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * n * m)
    d = 3 if n > 20 else 2
    max_iter = 50
    current_perm = best_perm[:]
    current_mk = best_mk

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= n:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(n), d)
            indices_set = set(indices)
            destroyed = [current_perm[i] for i in indices]
            remaining = [current_perm[i] for i in range(n) if i not in indices_set]
        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        for job in destroyed:
            # Rebuild forward and backward matrices for current remaining
            k = len(remaining)
            if k == 0:
                remaining = [job]
                continue
            e = [[0] * m for _ in range(k)]
            q = [[0] * m for _ in range(k + 1)]
            for r in range(k):
                rj = times[remaining[r]]
                if r == 0:
                    e[r][0] = rj[0]
                else:
                    e[r][0] = e[r-1][0] + rj[0]
                for mc in range(1, m):
                    e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + rj[mc]
            for mc in range(m):
                q[k][mc] = 0
            for r in range(k-1, -1, -1):
                rj = times[remaining[r]]
                q[r][m-1] = q[r+1][m-1] + rj[m-1]
                for mc in range(m-2, -1, -1):
                    q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + rj[mc]
