            best_mk_ins = float('inf')
            for i in range(k+1):
                f = [0] * m
                if i == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[i-1]
                f[0] = prev_e[0] + times[job][0]
                for mc in range(1, m):
                    f[mc] = max(f[mc-1], prev_e[mc]) + times[job][mc]
                mk_ins = 0
                for mc in range(m):
                    val = f[mc] + q[i][mc]
                    if val > mk_ins:
                        mk_ins = val
                if mk_ins < best_mk_ins:
                    best_mk_ins = mk_ins
                    best_pos = i
            remaining.insert(best_pos, job)
        new_perm = remaining
        new_mk = makespan(new_perm)
        # Acceptance criterion
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current_perm = new_perm
            current_mk = new_mk
            if new_mk < best_mk:
                best_mk = new_mk
                best_perm = new_perm[:]
                if best_mk == lb:
                    break
    return best_perm

