def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    N = len(times)
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_sum = 0
    P = [0] * N
    for i in range(N):
        row = times[i]
        s = 0
        for t in row:
            s += t
        P[i] = s
        total_sum += s

    order = list(range(N))
    order.sort(key=lambda i: P[i], reverse=True)

    def compute_makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for idx in seq:
            pj = times[idx]
            prev = t[0]
            t[0] = prev + pj[0]
            for m in range(1, M):
                prev = t[m]
                t[m] = max(t[m-1], prev) + pj[m]
        return t[-1]

    def makespan_neh_insert(partial, job_idx, e, q):
        k = len(partial)
        pj = times[job_idx]
        best_pos = 0
        best_mk = float('inf')
        for i in range(k + 1):
            if i == 0:
                f0 = pj[0]
            else:
                f0 = e[i-1][0] + pj[0]
            f = [0] * M
            f[0] = f0
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + pj[m]
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return best_pos, best_mk

    pi = [order[0]]
    if N > 1:
        mk1 = compute_makespan([order[0], order[1]])
        mk2 = compute_makespan([order[1], order[0]])
        if mk1 <= mk2:
            pi = [order[0], order[1]]
        else:
            pi = [order[1], order[0]]

    for k in range(2, N):
        e = [[0] * M for _ in range(k)]
        r0 = pi[0]
        pj0 = times[r0]
        e[0][0] = pj0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + pj0[m]
        for r in range(1, k):
            ri = pi[r]
            pjr = times[ri]
            e[r][0] = e[r-1][0] + pjr[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + pjr[m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            ri = pi[r]
            pjr = times[ri]
            q[r][M-1] = q[r+1][M-1] + pjr[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pjr[m]
        job_idx = order[k]
        pos, _ = makespan_neh_insert(pi, job_idx, e, q)
        pi.insert(pos, job_idx)

    best_pi = pi[:]
    best_mk = compute_makespan(best_pi)
    LB = 0
    for m in range(M):
        min_pre = float('inf')
        min_suf = float('inf')
        for i in range(N):
            pre = sum(times[i][:m])
            suf = sum(times[i][m+1:])
            if pre < min_pre:
                min_pre = pre
            if suf < min_suf:
                min_suf = suf
        machine_sum = sum(times[i][m] for i in range(N))
        lb_m = min_pre + machine_sum + min_suf
        if lb_m > LB:
            LB = lb_m
    if best_mk == LB:
        return best_pi

    T_param = 0.5
    T = T_param * total_sum / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iters = 60

    current_pi = pi[:]
    for _ in range(max_iters):
        if len(current_pi) <= d:
            destroyed = []
            R = current_pi[:]
        else:
            indices = random.sample(range(len(current_pi)), d)
            indices.sort(reverse=True)
            R = [current_pi[i] for i in indices]
            destroyed = current_pi[:]
            for idx in indices:
                del destroyed[idx]
        pi_D = destroyed

        if pi_D:
            kd = len(pi_D)
            e = [[0] * M for _ in range(kd)]
            if kd > 0:
                r0 = pi_D[0]
                pj0 = times[r0]
                e[0][0] = pj0[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj0[m]
                for r in range(1, kd):
                    ri = pi_D[r]
                    pjr = times[ri]
                    e[r][0] = e[r-1][0] + pjr[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pjr[m]
            q = [[0] * M for _ in range(kd+1)]
            for m in range(M):
                q[kd][m] = 0
            for r in range(kd-1, -1, -1):
                ri = pi_D[r]
                pjr = times[ri]
                q[r][M-1] = q[r+1][M-1] + pjr[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pjr[m]
        else:
            e = []
            q = [[0] * M for _ in range(1)]
            for m in range(M):
                q[0][m] = 0

        for job_idx in R:
            if not pi_D:
                pi_D = [job_idx]
                continue
            kd = len(pi_D)
            pos, _ = makespan_neh_insert(pi_D, job_idx, e, q)
            pi_D.insert(pos, job_idx)

        new_pi = pi_D
        new_mk = compute_makespan(new_pi)
        if new_mk < best_mk:
            best_mk = new_mk
            best_pi = new_pi[:]
            if best_mk == LB:
                break
        if new_mk < compute_makespan(current_pi):
            current_pi = new_pi
        else:
            diff = new_mk - compute_makespan(current_pi)
            if diff == 0 or random.random() < math.exp(-diff / T):
                current_pi = new_pi

    return best_pi

