def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data and total processing times
    jobs = [list(t) for t in times]
    total = [sum(job) for job in jobs]

    # Compute Taillard's machine-based lower bound
    LB = 0
    for m in range(M):
        sum_m = sum(job[m] for job in jobs)
        min_before = min(sum(job[:m]) for job in jobs) if m > 0 else 0
        min_after = min(sum(job[m+1:]) for job in jobs) if m < M-1 else 0
        LB_m = min_before + sum_m + min_after
        if LB_m > LB:
            LB = LB_m

    # Sort jobs by total processing time descending (NEH priority)
    order = sorted(range(N), key=lambda i: total[i], reverse=True)

    # Initialize with first two jobs
    seq = [order[0], order[1]]
    best_seq = seq[:]
    best_cmax = _makespan(seq, jobs)
    if _makespan([order[1], order[0]], jobs) < best_cmax:
        seq = [order[1], order[0]]
        best_seq = seq[:]
        best_cmax = _makespan(seq, jobs)

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N+1)]

    # Main NEH loop with Taillard acceleration and lower bound pruning
    for k in range(2, N):
        job_idx = order[k]
        p_job = jobs[job_idx]

        # Compute forward matrix e for current sequence of length k
        for r in range(k):
            p_r = jobs[seq[r]]
            if r == 0:
                e[0][0] = p_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p_r[m]
            else:
                e[r][0] = e[r-1][0] + p_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p_r[m]

        # Compute backward matrix q for current sequence of length k
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            p_r = jobs[seq[r]]
            q[r][M-1] = q[r+1][M-1] + p_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p_r[m]

        # Evaluate insertion positions with lower bound pruning
        best_pos = 0
        best_val = float('inf')
        for i in range(k+1):
            # Compute forward vector f for inserting job at position i
            f = [0] * M
            if i == 0:
                f[0] = p_job[0]
                for m in range(1, M):
                    f[m] = f[m-1] + p_job[m]
            else:
                f[0] = e[i-1][0] + p_job[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + p_job[m]

            # Compute makespan candidate: max_m (f[m] + q[i][m])
            makespan_candidate = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_candidate:
                    makespan_candidate = val

            # Prune if candidate cannot improve current best
            if makespan_candidate >= best_cmax:
                continue

            if makespan_candidate < best_val:
                best_val = makespan_candidate
                best_pos = i

        # Insert job at best position
        seq.insert(best_pos, job_idx)

        # Update best sequence if improved
        if best_val < best_cmax:
            best_cmax = best_val
            best_seq = seq[:]

    return best_seq

def _makespan(seq, jobs):
    if not seq:
        return 0
    M = len(jobs[0])
    t = [0] * M
    for idx in seq:
        p = jobs[idx]
        t[0] += p[0]
        for m in range(1, M):
            t[m] = max(t[m-1], t[m]) + p[m]
    return t[-1]

