def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_data = [list(row) for row in times]

    # Helper: Johnson's rule for two-machine flow shop
    def johnsons_rule(p1, p2):
        left, right = [], []
        indices = list(range(N))
        indices.sort(key=lambda i: min(p1[i], p2[i]))
        for i in indices:
            if p1[i] <= p2[i]:
                left.append(i)
            else:
                right.append(i)
        right.reverse()
        return left + right

    # Helper: makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += job_data[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + job_data[job][m]
        return t[-1]

    # CDS: generate M-1 permutations from two-machine subproblems
    best_perm = None
    best_makespan = float('inf')
    for l in range(1, M):
        p1 = [sum(job_data[i][:l]) for i in range(N)]
        p2 = [sum(job_data[i][M-l:]) for i in range(N)]
        perm = johnsons_rule(p1, p2)
        m = makespan(perm)
        if m < best_makespan:
            best_makespan = m
            best_perm = perm

    return best_perm

