def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    LB = 0
    for m in range(M):
        min_before = min(times[i][:m] for i in range(N)) if m > 0 else [0] * N
        min_after = min(times[i][m+1:] for i in range(N)) if m < M-1 else [0] * N
        sum_m = sum(times[i][m] for i in range(N))
        lb_m = min(sum(row) for row in min_before) + sum_m + min(sum(row) for row in min_after)
        if lb_m > LB:
            LB = lb_m

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m-1], t[m]) + times[job][m]
        return t[-1]

    def taillard_forward_backward(partial):
        k = len(partial)
        if k == 0:
            return ([], [[0]*M for _ in range(k+1)])
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r>0 else 0) + times[job][m]
                else:
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job][m]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return (e, q)

    def insertion_cost(partial, e, q, job):
        k = len(partial)
        best_cost = float('inf')
        best_pos = 0
        for i in range(k+1):
            f = [0]*M
            for m in range(M):
                if m == 0:
                    prev = e[i-1][m] if i>0 else 0
                    f[m] = prev + times[job][m]
                else:
                    f[m] = max(f[m-1], e[i-1][m] if i>0 else 0) + times[job][m]
            cost = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cost:
                    cost = val
            if cost < best_cost:
                best_cost = cost
                best_pos = i
        return best_pos, best_cost

    def neh_construct():
        job_sums = [sum(job) for job in times]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        e, q = taillard_forward_backward(seq)
        pos, _ = insertion_cost(seq, e, q, order[1])
        seq.insert(pos, order[1])
        e, q = taillard_forward_backward(seq)
        for idx in range(2, N):
            job = order[idx]
            pos, _ = insertion_cost(seq, e, q, job)
            seq.insert(pos, job)
            e, q = taillard_forward_backward(seq)
            if makespan(seq) == LB:
                break
        return seq

    def destroy_and_reconstruct(seq, d):
        if d >= len(seq):
            return neh_construct()
        indices = random.sample(range(len(seq)), d)
        removed = [seq[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del seq[idx]
        e, q = taillard_forward_backward(seq)
        for job in removed:
            pos, _ = insertion_cost(seq, e, q, job)
            seq.insert(pos, job)
            e, q = taillard_forward_backward(seq)
        return seq

    current = neh_construct()
    best = current[:]
    best_makespan = makespan(best)
    if best_makespan == LB:
        return best

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-6:
        T = 1e-6

    max_iter = 60
    for _ in range(max_iter):
        if makespan(current) == LB:
            break
        d = 3 if N > 20 else 2
        candidate = destroy_and_reconstruct(current[:], d)
        cand_makespan = makespan(candidate)
        if cand_makespan < makespan(current):
            current = candidate
            if cand_makespan < best_makespan:
                best = candidate[:]
                best_makespan = cand_makespan
                if best_makespan == LB:
                    break
        else:
            diff = cand_makespan - makespan(current)
            if random.random() < math.exp(-diff / T):
                current = candidate
    return best

