            seq1 = [job_order[0], job_order[1]]
            seq2 = [job_order[1], job_order[0]]
            makespan1 = compute_makespan(seq1, times)
            makespan2 = compute_makespan(seq2, times)
            seq = seq1 if makespan1 <= makespan2 else seq2

        for k in range(2, N):
            job = job_order[k]
            best_pos = 0
            best_mk = float('inf')
            # Evaluate all insertion positions using Taillard acceleration
            e = [[0] * M for _ in range(k)]
            # Forward pass
            for r in range(k):
                job_r = seq[r]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job_r][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job_r][m]

            # Backward pass
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + times[job_r][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]

            # Evaluate each insertion position
            for i in range(k+1):
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev_e = e[i-1][m] if i > 0 else 0
                        f[m] = prev_e + times[job][m]
                    else:
                        prev_f = f[m-1]
                        prev_e = e[i-1][m] if i > 0 else 0
                        f[m] = max(prev_f, prev_e) + times[job][m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)

        mk = compute_makespan(seq, times)
        if mk < best_makespan:
            best_makespan = mk
            best_seq = seq[:]

    if best_seq is None:
        best_seq = list(range(N))

    # Iterated Greedy refinement
    current_seq = best_seq[:]
    current_mk = best_makespan
    best_seq_ig = current_seq[:]
    best_mk_ig = current_mk

    # Calculate temperature parameter
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

    # Number of IG iterations calibrated for <50ms
    max_iter = 60
    d = 3  # destruction size

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if N <= d:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            destroyed = [current_seq[i] for i in indices]
            remaining = [current_seq[i] for i in range(N) if i not in indices_set]

        # Reconstruction: reinsert destroyed jobs one by one using NEH with Taillard
        for job in destroyed:
            best_pos = 0
            best_mk_ins = float('inf')
            k = len(remaining)
            if k == 0:
                remaining = [job]
                continue

            # Forward pass for current remaining sequence
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = remaining[r]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job_r][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job_r][m]

            # Backward pass
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = remaining[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + times[job_r][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]

            # Evaluate insertion positions
            for i in range(k+1):
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev_e = e[i-1][m] if i > 0 else 0
                        f[m] = prev_e + times[job][m]
                    else:
                        prev_f = f[m-1]
                        prev_e = e[i-1][m] if i > 0 else 0
                        f[m] = max(prev_f, prev_e) + times[job][m]
                mk_ins = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk_ins:
                        mk_ins = val
                if mk_ins < best_mk_ins:
                    best_mk_ins = mk_ins
                    best_pos = i
            remaining.insert(best_pos, job)

        new_seq = remaining
        new_mk = compute_makespan(new_seq, times)

        # Acceptance criterion
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current_seq = new_seq
            current_mk = new_mk
            if new_mk < best_mk_ig:
                best_seq_ig = new_seq[:]
                best_mk_ig = new_mk

    return best_seq_ig

def compute_makespan(seq, times):
    if not seq:
        return 0
    N = len(seq)
    M = len(times[0])
    # Using two rows for space efficiency
    dp = [0] * M
    for idx in seq:
        job = times[idx]
        dp[0] += job[0]
        for m in range(1, M):
            dp[m] = max(dp[m-1], dp[m]) + job[m]
    return dp[M-1]

