def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_data = [times[i][:] for i in range(N)]
    total_proc = [sum(job) for job in job_data]
    slope = [sum((2 * j - M + 1) * job_data[i][j] for j in range(M)) for i in range(N)]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            p = job_data[job]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[m]
        return t[-1]

    # NEH construction with Taillard acceleration
    def neh_construction(order):
        if not order:
            return []
        perm = [order[0]]
        if len(order) == 1:
            return perm
        # Initial pair
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        # Greedy insertion
        for k in range(2, len(order)):
            job = order[k]
            best_pos = 0
            best_mk = float('inf')
            # Forward matrix e: completion times of current perm
            e = [[0] * M for _ in range(len(perm))]
            for r in range(len(perm)):
                pj = job_data[perm[r]]
                if r == 0:
                    e[0][0] = pj[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + pj[m]
                else:
                    e[r][0] = e[r-1][0] + pj[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
            # Backward matrix q: tail times
            q = [[0] * M for _ in range(len(perm) + 1)]
            for r in range(len(perm)-1, -1, -1):
                pj = job_data[perm[r]]
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
            # Evaluate each insertion position
            for i in range(len(perm) + 1):
                # Forward pass for job at position i
                f = [0] * M
                if i == 0:
                    f[0] = job_data[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + job_data[job][m]
                else:
                    f[0] = e[i-1][0] + job_data[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + job_data[job][m]
                # Makespan = max_m (f[m] + q[i][m])
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Try multiple orderings and pick the best
    orders = [
        sorted(range(N), key=lambda i: -total_proc[i]),  # NEH: total time descending
        sorted(range(N), key=lambda i: -slope[i]),       # Palmer's slope descending
        list(range(N)),                                  # Natural order
        list(reversed(range(N)))                         # Reverse order
    ]
    random.shuffle(orders)  # Add randomness to avoid worst-case
    best_perm = None
    best_mk = float('inf')
    for order in orders:
        perm = neh_construction(order)
        mk = makespan(perm)
        if mk < best_mk:
            best_mk = mk
            best_perm = perm
            if best_mk == 0:  # Optimal if zero processing time
                break

    # Iterated Greedy refinement
    current = best_perm[:]
    current_mk = best_mk
    best_perm_ig = current[:]
    best_mk_ig = current_mk

    # IG parameters
    T_param = 0.5
    total_processing = sum(total_proc)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0
    d = 3 if N > 5 else max(1, N // 2)  # Destruction size
    max_iter = 60  # Iteration count tuned for <50ms

    for _ in range(max_iter):
        # Destruction: remove d jobs at random positions
        if d >= N:
            destroyed = []
            remaining = []
        else:
            positions = random.sample(range(N), d)
            positions.sort()
            destroyed = [current[pos] for pos in positions]
            # Build remaining sequence
            remaining = []
            pos_idx = 0
            for i in range(N):
                if pos_idx < d and i == positions[pos_idx]:
                    pos_idx += 1
                else:
                    remaining.append(current[i])
        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        seq = remaining[:]
        for job in destroyed:
            best_pos = 0
            best_mk = float('inf')
            # Forward matrix e for current seq
            e = [[0] * M for _ in range(len(seq))]
            for r in range(len(seq)):
                pj = job_data[seq[r]]
                if r == 0:
                    e[0][0] = pj[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + pj[m]
                else:
                    e[r][0] = e[r-1][0] + pj[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
            # Backward matrix q
            q = [[0] * M for _ in range(len(seq) + 1)]
            for r in range(len(seq)-1, -1, -1):
                pj = job_data[seq[r]]
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
            # Evaluate insertion positions
            for i in range(len(seq) + 1):
                f = [0] * M
                if i == 0:
                    f[0] = job_data[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + job_data[job][m]
                else:
                    f[0] = e[i-1][0] + job_data[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + job_data[job][m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        new_mk = best_mk
        # Acceptance criterion
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current = seq
            current_mk = new_mk
            if new_mk < best_mk_ig:
                best_mk_ig = new_mk
                best_perm_ig = current[:]
    return best_perm_ig

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for faster access
    p = [list(times[i]) for i in range(N)]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[-1]

    # Taillard-accelerated makespan for partial sequence + candidate insertion
    def insertion_makespan(partial, candidate):
        k = len(partial)
        if k == 0:
            return sum(p[candidate])
        # Forward matrix e[r][m] for r in [-1..k-1], m in [0..M-1]; e[-1][:] = 0
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            if r == 0:
                e[0][0] = p[job][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[job][m]
            else:
                e[r][0] = e[r-1][0] + p[job][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job][m]
        # Backward matrix q[r][m] for r in [0..k], m in [0..M-1]; q[k][:] = 0
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            q[r][M-1] = q[r+1][M-1] + p[job][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]
        best = float('inf')
        # Try all insertion positions i in [0..k]
        for i in range(k+1):
            # Forward pass for candidate up to machine m
            f = [0] * M
            if i == 0:
                f[0] = p[candidate][0]
                for m in range(1, M):
                    f[m] = f[m-1] + p[candidate][m]
            else:
                f[0] = e[i-1][0] + p[candidate][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + p[candidate][m]
            # Makespan = max_m (f[m] + q[i][m])
            for m in range(M):
                val = f[m] + q[i][m]
                if val < best:
                    best = val
        return best

    # NEH construction with Taillard acceleration
    total = [sum(p[i]) for i in range(N)]
    order = sorted(range(N), key=lambda i: total[i], reverse=True)
    if N >= 2:
        seq = [order[0], order[1]]
        if insertion_makespan([order[0]], order[1]) > insertion_makespan([order[1]], order[0]):
            seq = [order[1], order[0]]
        for idx in range(2, N):
            job = order[idx]
            best_pos = 0
            best_mk = insertion_makespan(seq, job)
            for pos in range(1, len(seq)+1):
                mk = insertion_makespan(seq[:pos] + [job] + seq[pos:], None)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq = seq[:best_pos] + [job] + seq[best_pos:]
    else:
        seq = [order[0]]

    # Iterated Greedy with Metropolis acceptance
    current = seq[:]
    best = seq[:]
    current_mk = makespan(current)
    best_mk = current_mk
    total_processing = sum(total)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for it in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        # Build destroyed sequence by keeping non-removed jobs in order
        destroyed = [current[i] for i in range(N) if i not in indices]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        seq = destroyed[:]
        for job in removed:
            best_pos = 0
            best_mk_ins = insertion_makespan(seq, job)
            for pos in range(1, len(seq)+1):
                mk = insertion_makespan(seq[:pos] + [job] + seq[pos:], None)
                if mk < best_mk_ins:
                    best_mk_ins = mk
                    best_pos = pos
            seq = seq[:best_pos] + [job] + seq[best_pos:]
        new_mk = makespan(seq)
        # Acceptance criterion
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current = seq[:]
            current_mk = new_mk
            if new_mk < best_mk:
                best = seq[:]
                best_mk = new_mk
                no_improve = 0
            else:
                no_improve += 1
        else:
            no_improve += 1
        if no_improve >= no_improve_limit:
            break

    # Lightweight VNS: alternate between insert and swap neighborhoods
    def vns_local_search(start_seq):
        seq = start_seq[:]
        mk = makespan(seq)
        improved = True
        while improved:
            improved = False
            # Neighborhood 1: single-job relocation (insert)
            for i in range(len(seq)):
                job = seq[i]
                seq_without = seq[:i] + seq[i+1:]
                for j in range(len(seq_without)+1):
                    if j == i:
                        continue
                    candidate = seq_without[:j] + [job] + seq_without[j:]
                    candidate_mk = makespan(candidate)
                    if candidate_mk < mk:
                        seq = candidate
                        mk = candidate_mk
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # Neighborhood 2: job-pair swap
                for i in range(len(seq)):
                    for j in range(i+1, len(seq)):
                        seq[i], seq[j] = seq[j], seq[i]
                        candidate_mk = makespan(seq)
                        if candidate_mk < mk:
                            mk = candidate_mk
                            improved = True
                            break
                        seq[i], seq[j] = seq[j], seq[i]  # revert
                    if improved:
                        break
        return seq, mk

    best_seq, best_mk = vns_local_search(best)
    return best_seq

