    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]
    p0 = [row[0] for row in p]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            job_p = p[job]
            t[0] += job_p[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_p[m]
        return t[-1]

    # NEH construction with Taillard acceleration and modified priority
    def construct_neh():
        # Modified priority: penalize high first machine time
        priority = [total_p[i] - 0.5 * p0[i] for i in range(N)]
        order = sorted(range(N), key=lambda i: priority[i], reverse=True)

        if N == 0:
            return []
        if N == 1:
            return [order[0]]

        # Initial two jobs
        best_seq = None
        best_cmax = float('inf')
        for seq in ([order[0], order[1]], [order[1], order[0]]):
            cmax = makespan(seq)
            if cmax < best_cmax:
                best_cmax = cmax
                best_seq = seq[:]
        perm = best_seq

        # Insert remaining jobs using Taillard acceleration
        for k in range(2, N):
            job = order[k]
            job_p = p[job]

            # Compute forward completion matrix e for current perm (length k)
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = perm[r]
                job_r_p = p[job_r]
                if r == 0:
                    e[0][0] = job_r_p[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_r_p[m]
                else:
                    e[r][0] = e[r-1][0] + job_r_p[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r_p[m]

            # Compute backward tail matrix q for current perm (length k)
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = perm[r]
                job_r_p = p[job_r]
                if r == k-1:
                    for m in range(M):
                        q[r][m] = job_r_p[m]
                else:
                    q[r][M-1] = q[r+1][M-1] + job_r_p[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r_p[m]

            # Evaluate all insertion positions
            best_pos = 0
            best_cmax = float('inf')
            for i in range(k+1):
                # Compute forward vector f for inserting job at position i
                f = [0] * M
                if i == 0:
                    f[0] = job_p[0]
                    for m in range(1, M):
                        f[m] = f[m-1] + job_p[m]
                else:
                    prev_e = e[i-1]
                    f[0] = prev_e[0] + job_p[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev_e[m]) + job_p[m]

                # Compute makespan for this insertion
                cmax = 0
                tail = q[i]
                for m in range(M):
                    val = f[m] + tail[m]
                    if val > cmax:
                        cmax = val
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = i
            perm.insert(best_pos, job)
