                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r_p[m]

                # Compute backward tail matrix q for current (length k)
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = current[r]
                    job_r_p = p[job_r]
                    if r == k-1:
                        for m in range(M):
                            q[r][m] = job_r_p[m]
                    else:
                        q[r][M-1] = q[r+1][M-1] + job_r_p[M-1]
                        for m in range(M-2, -1, -1):
                            q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r_p[m]

                # Evaluate all insertion positions
                best_pos = 0
                best_cmax_local = float('inf')
                for i in range(k+1):
                    # Compute forward vector f for inserting job at position i
                    f = [0] * M
                    if i == 0:
                        f[0] = job_p[0]
                        for m in range(1, M):
                            f[m] = f[m-1] + job_p[m]
                    else:
                        prev_e = e[i-1]
                        f[0] = prev_e[0] + job_p[0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], prev_e[m]) + job_p[m]

                    # Compute makespan for this insertion
                    cmax = 0
                    tail = q[i]
                    for m in range(M):
                        val = f[m] + tail[m]
                        if val > cmax:
                            cmax = val
                    if cmax < best_cmax_local:
                        best_cmax_local = cmax
                        best_pos = i
                current.insert(best_pos, job)

            # Acceptance criterion
            current_cmax = makespan(current)
            if current_cmax < best_cmax:
                best_cmax = current_cmax
                best = current[:]
            if current_cmax < makespan(init_perm):  # Always accept if better than start of iteration
                pass  # current is already set
            else:
                if current_cmax < makespan(init_perm) or random.random() < math.exp(-(current_cmax - makespan(init_perm)) / T):
                    pass  # accept current
                else:
                    current = init_perm[:]  # revert to start of iteration

        return best

    # Build initial solution
    init_perm = construct_neh()
    # Refine with Iterated Greedy
    result = iterated_greedy(init_perm, max_iter=50)
    return result

