    P = [sum(job) for job in times]
    S = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Try multiple priority orders: total time (NEH), slope (Palmer), and random
    orders = [
        sorted(range(N), key=lambda i: (-P[i], i)),
