                            e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job_r][m]

                # Compute backward tail matrix q for current seq (length k)
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = seq[r]
                    for m in range(M-1, -1, -1):
                        if m == M-1:
                            q[r][m] = q[r+1][m] + times[job_r][m]
                        else:
                            q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
            else:
                e = []
                q = [[0] * M]  # q[0][m] = 0 for all m

            # Evaluate each insertion position i in [0, k]
            for i in range(k+1):
                # Compute forward vector f for job at position i
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev_e = e[i-1][m] if i > 0 and k > 0 else 0
                        f[m] = prev_e + times[job][m]
                    else:
                        prev_e = e[i-1][m] if i > 0 and k > 0 else 0
                        f[m] = max(f[m-1], prev_e) + times[job][m]

                # Compute makespan if job inserted at i
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
