                best_seq = seq[:]
        elif new_mk < best_makespan:
            best_makespan = new_mk
            best_seq = seq[:]
            # Accept with probability
            if random.random() < math.exp(-(new_mk - current_mk) / T):
                current_seq = seq
                current_mk = new_mk
        else:
            if random.random() < math.exp(-(new_mk - current_mk) / T):
                current_seq = seq
                current_mk = new_mk

    return best_seq

def _makespan(times: list[list[int]], seq: list[int]) -> int:
    if not seq:
        return 0
    N = len(seq)
    M = len(times[0])
    t = [0] * M
    for idx in seq:
        job = times[idx]
        t[0] += job[0]
        for m in range(1, M):
            t[m] = max(t[m-1], t[m]) + job[m]
    return t[-1]

