        t = [0] * M
        for job in seq:
            pj = job_data[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + pj[m]
        return t[-1]

    # ---------- Taillard acceleration ----------
    def compute_forward(partial_seq, k):
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            pj = job_data[partial_seq[r]]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    def compute_backward(partial_seq, k):
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pj = job_data[partial_seq[r]]
            if r == k-1:
                for m in range(M):
                    q[r][m] = pj[m]
            else:
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    def insert_job_taillard(partial_seq, job, e, q, k):
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            if i == 0:
                f = [0] * M
                pj = job_data[job]
                f[0] = pj[0]
                for m in range(1, M):
                    f[m] = f[m-1] + pj[m]
            else:
                f = [0] * M
                pj = job_data[job]
                f[0] = e[i-1][0] + pj[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + pj[m]
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return best_pos

    def insert_two_jobs_taillard(partial_seq, job_a, job_b, e, q, k):
        best_seq = None
        best_mk = float('inf')
