        for pos_a in range(L):
            seq_a = partial_seq[:pos_a] + [job_a] + partial_seq[pos_a:]
            e_a = compute_forward(seq_a, pos_a+1)
            q_a = compute_backward(seq_a, pos_a+1)
            for pos_b in range(L):
                if pos_b <= pos_a:
                    seq_new = seq_a[:pos_b] + [job_b] + seq_a[pos_b:]
                else:
                    seq_new = seq_a[:pos_b] + [job_b] + seq_a[pos_b:]
                mk = makespan(seq_new)
                if mk < best_mk:
                    best_mk = mk
