        indices = list(range(N))
        random.shuffle(indices)
        removed = indices[:d]
        removed_jobs = [current[i] for i in removed]
        remain = [current[i] for i in indices[d:]]
        seq = remain[:]
        for job in removed_jobs:
            k = len(seq)
            if k == 0:
                seq = [job]
