            pos = insert_job_taillard(seq, job, e, q, k)
            seq = seq[:pos] + [job] + seq[pos:]
        mk = makespan(seq)
        if mk < best_mk:
            best_mk = mk
            best = seq[:]
            current = seq[:]
        elif mk < makespan(current):
            current = seq[:]
        else:
            if random.random() < math.exp(-(mk - makespan(current)) / T):
                current = seq[:]

    return best

