def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices for NEH variants
    total_times = [sum(job) for job in times]
    slope_indices = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_times[m]
        return t[-1]

    def taillard_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            p = times[job]
            if r == 0:
                e[0][0] = p[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[m]
            else:
                e[r][0] = e[r-1][0] + p[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[m]
        return e

    def taillard_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            p = times[job]
            q[r][M-1] = q[r+1][M-1] + p[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[m]
        return q

    def neh_construct(priority):
        if not priority:
            return []
        seq = [priority[0]]
        if len(priority) > 1:
            job1, job2 = priority[0], priority[1]
            seq1 = [job1, job2]
            seq2 = [job2, job1]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, len(priority)):
            job = priority[idx]
            best_pos = 0
            best_makespan = float('inf')
            e = taillard_forward(seq)
            q = taillard_backward(seq)
            for pos in range(len(seq) + 1):
                f = [0] * M
                if pos == 0:
                    for m in range(M):
                        f[m] = (e[0][m] if seq else 0) + times[job][m]
                else:
                    f[0] = e[pos-1][0] + times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[pos-1][m]) + times[job][m]
                max_val = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > max_val:
                        max_val = val
                if max_val < best_makespan:
                    best_makespan = max_val
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Generate initial solutions using different priority orders
    order_total = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    order_slope = sorted(range(N), key=lambda i: slope_indices[i], reverse=True)
    pi_total = neh_construct(order_total)
    pi_slope = neh_construct(order_slope)
    best_perm = pi_total if makespan(pi_total) <= makespan(pi_slope) else pi_slope
    best_makespan = makespan(best_perm)

    # Iterated Greedy parameters
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    max_iter = 50
    no_improve_limit = 10
    no_improve = 0

    current_perm = best_perm[:]
    current_makespan = best_makespan

    for it in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current_perm[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del current_perm[i]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_makespan_val = float('inf')
            e = taillard_forward(current_perm)
            q = taillard_backward(current_perm)
            for pos in range(len(current_perm) + 1):
                f = [0] * M
                if pos == 0:
                    for m in range(M):
                        f[m] = (e[0][m] if current_perm else 0) + times[job][m]
                else:
                    f[0] = e[pos-1][0] + times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[pos-1][m]) + times[job][m]
                max_val = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > max_val:
                        max_val = val
                if max_val < best_makespan_val:
                    best_makespan_val = max_val
                    best_pos = pos
            current_perm.insert(best_pos, job)
        new_makespan = makespan(current_perm)
        # Acceptance criterion
        if new_makespan < current_makespan:
            current_perm = current_perm[:]
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_perm = current_perm[:]
                best_makespan = new_makespan
                no_improve = 0
            else:
                no_improve += 1
        else:
            delta = new_makespan - current_makespan
            if random.random() < math.exp(-delta / T):
                current_perm = current_perm[:]
                current_makespan = new_makespan
                no_improve += 1
            else:
                no_improve += 1
        if no_improve >= no_improve_limit:
            break

    return best_perm

