    M = len(times[0]) if N > 0 else 0
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job data for fast access
    jobs = [times[i][:] for i in range(N)]
    total_times = [sum(job) for job in jobs]

    # NEH with Taillard acceleration
    def makespan_from_perm(perm):
        if not perm:
            return 0
        t = [0] * M
        for job_idx in perm:
            job = jobs[job_idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def compute_forward_backward(perm):
        k = len(perm)
        if k == 0:
            return ([[0]*M], [[0]*M])
        e = [[0]*M for _ in range(k)]
        job0 = jobs[perm[0]]
        e[0][0] = job0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0[m]
        for r in range(1, k):
            job = jobs[perm[r]]
            e[r][0] = e[r-1][0] + job[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job[m]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = jobs[perm[r]]
            q[r][M-1] = q[r+1][M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job[m]
        return (e, q)

    def makespan_with_insertion(e, q, job_idx, insert_pos):
        k = len(e)
        job = jobs[job_idx]
        if insert_pos == 0:
            f0 = job[0]
        else:
            f0 = e[insert_pos-1][0] + job[0]
        f = [f0]
        for m in range(1, M):
            if insert_pos == 0:
                prev_e = 0
            else:
                prev_e = e[insert_pos-1][m]
            fm = max(f[m-1], prev_e) + job[m]
            f.append(fm)
        makespan = 0
        for m in range(M):
            val = f[m] + q[insert_pos][m]
            if val > makespan:
                makespan = val
        return makespan

    def neh_construction():
        order = sorted(range(N), key=lambda i: total_times[i], reverse=True)
        if N == 1:
            return order[:]
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        if makespan_from_perm(seq0) <= makespan_from_perm(seq1):
            perm = seq0[:]
        else:
            perm = seq1[:]
        for idx in range(2, N):
            job = order[idx]
            e, q = compute_forward_backward(perm)
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(perm)+1):
                ms = makespan_with_insertion(e, q, job, pos)
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy
    def destruction_construction(current_perm, d):
        if d <= 0 or d >= len(current_perm):
            return current_perm[:]
        indices = random.sample(range(len(current_perm)), d)
        removed = [current_perm[i] for i in indices]
        remaining = [current_perm[i] for i in range(len(current_perm)) if i not in indices]
        random.shuffle(removed)
        perm = remaining[:]
        for job in removed:
            e, q = compute_forward_backward(perm)
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(perm)+1):
                ms = makespan_with_insertion(e, q, job, pos)
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # Main IG loop
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0
    current = neh_construction()
    best = current[:]
    best_ms = makespan_from_perm(best)
    if best_ms == 0:
        return best
    max_iters = 60
    for _ in range(max_iters):
        d = 3 if N > 20 else 4
        if d > N:
            d = N
        candidate = destruction_construction(current, d)
        cand_ms = makespan_from_perm(candidate)
        if cand_ms < best_ms:
            best = candidate[:]
            best_ms = cand_ms
            if best_ms == 0:
                break
        if cand_ms < makespan_from_perm(current):
            current = candidate
        else:
            delta = cand_ms - makespan_from_perm(current)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current = candidate
    return best

