            random.shuffle(pi_new)
        else:
            positions = random.sample(range(len(pi)), d)
            positions.sort(reverse=True)
            extracted = []
            for pos in positions:
                extracted.append(pi.pop(pos))
            pi_D = pi[:]
            random.shuffle(extracted)
            for job in extracted:
                e = compute_forward(pi_D)
                q = compute_backward(pi_D)
                best_pos = 0
                best_makespan = float('inf')
                for i in range(len(pi_D) + 1):
                    e_prev = e[i-1] if i > 0 else None
                    q_i = q[i]
                    cmax = makespan_insert(e_prev, job, i, q_i)
                    if cmax < best_makespan:
                        best_makespan = cmax
                        best_pos = i
                pi_D.insert(best_pos, job)
            pi_new = pi_D
        new_makespan = makespan(pi_new)
        if new_makespan < makespan(pi):
            pi = pi_new[:]
        if new_makespan < best_makespan:
            pi_best = pi_new[:]
            best_makespan = new_makespan
        if new_makespan != makespan(pi):
            delta = new_makespan - makespan(pi)
            if delta > 0:
                prob = math.exp(-delta / T)
                if random.random() < prob:
                    pi = pi_new[:]
    return pi_best

