def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and variances per machine
    total = [0] * N
    var = [0.0] * M
    mean = [0.0] * M
    for i in range(N):
        for j in range(M):
            t = times[i][j]
            total[i] += t
            mean[j] += t
    for j in range(M):
        mean[j] /= N
    for i in range(N):
        for j in range(M):
            diff = times[i][j] - mean[j]
            var[j] += diff * diff
    for j in range(M):
        var[j] /= N
        if var[j] == 0:
            var[j] = 1e-9  # Avoid division by zero

    # Compute modified Palmer slope: weight by inverse variance
    slope = [0.0] * N
    for i in range(N):
        s = 0.0
        for j in range(M):
            weight = (2 * j - M + 1) / var[j]
            s += weight * times[i][j]
        slope[i] = s
    # Sort jobs by slope descending
    order = sorted(range(N), key=lambda i: slope[i], reverse=True)

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N + 1)]
    f = [0] * M

    def makespan_from_partial(perm, k):
        # Compute forward completion matrix e[0..k-1][0..M-1]
        for r in range(k):
            job = perm[r]
            if r == 0:
                e[0][0] = times[job][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + times[job][m]
            else:
                e[r][0] = e[r-1][0] + times[job][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job][m]
        # Compute backward tail matrix q[0..k][0..M-1]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = perm[r]
            q[r][M-1] = q[r+1][M-1] + times[job][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return e, q

    def insert_job(perm, k, job, e, q):
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            # Compute forward vector f for inserting job at position i
            if i == 0:
                f[0] = times[job][0]
                for m in range(1, M):
                    f[m] = f[m-1] + times[job][m]
            else:
                f[0] = e[i-1][0] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + times[job][m]
            # Compute makespan: max_m (f[m] + q[i][m])
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        perm.insert(best_pos, job)
        return best_mk

    # NEH construction with Taillard acceleration
    perm = []
    for idx in range(N):
        job = order[idx]
        if idx == 0:
            perm = [job]
            e, q = makespan_from_partial(perm, 1)
        elif idx == 1:
            job0, job1 = order[0], order[1]
            # Try [job0, job1]
            perm0 = [job0, job1]
            e0, q0 = makespan_from_partial(perm0, 2)
            mk0 = e0[1][M-1]
            # Try [job1, job0]
            perm1 = [job1, job0]
            e1, q1 = makespan_from_partial(perm1, 2)
            mk1 = e1[1][M-1]
            if mk0 <= mk1:
                perm = perm0
                e, q = e0, q0
            else:
                perm = perm1
                e, q = e1, q1
        else:
            mk = insert_job(perm, idx, job, e, q)
            e, q = makespan_from_partial(perm, idx+1)

    # Iterated Greedy refinement
    def makespan(perm):
        if not perm:
            return 0
        e_curr = [[0] * M for _ in range(len(perm))]
        q_curr = [[0] * M for _ in range(len(perm) + 1)]
        for r in range(len(perm)):
            job = perm[r]
            if r == 0:
                e_curr[0][0] = times[job][0]
                for m in range(1, M):
                    e_curr[0][m] = e_curr[0][m-1] + times[job][m]
            else:
                e_curr[r][0] = e_curr[r-1][0] + times[job][0]
                for m in range(1, M):
                    e_curr[r][m] = max(e_curr[r-1][m], e_curr[r][m-1]) + times[job][m]
        for m in range(M):
            q_curr[len(perm)][m] = 0
        for r in range(len(perm)-1, -1, -1):
            job = perm[r]
            q_curr[r][M-1] = q_curr[r+1][M-1] + times[job][M-1]
            for m in range(M-2, -1, -1):
                q_curr[r][m] = max(q_curr[r+1][m], q_curr[r][m+1]) + times[job][m]
        return e_curr[len(perm)-1][M-1]

    current = perm[:]
    best = current[:]
    best_mk = makespan(best)
    total_processing = sum(total)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N >= 3 else N
    max_iters = 60
    for _ in range(max_iters):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del current[idx]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            # Build e and q for current partial sequence
            k = len(current)
            e_partial = [[0] * M for _ in range(k)]
            q_partial = [[0] * M for _ in range(k + 1)]
            for r in range(k):
                job_r = current[r]
                if r == 0:
                    e_partial[0][0] = times[job_r][0]
                    for m in range(1, M):
                        e_partial[0][m] = e_partial[0][m-1] + times[job_r][m]
                else:
                    e_partial[r][0] = e_partial[r-1][0] + times[job_r][0]
                    for m in range(1, M):
                        e_partial[r][m] = max(e_partial[r-1][m], e_partial[r][m-1]) + times[job_r][m]
            for m in range(M):
                q_partial[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = current[r]
                q_partial[r][M-1] = q_partial[r+1][M-1] + times[job_r][M-1]
                for m in range(M-2, -1, -1):
                    q_partial[r][m] = max(q_partial[r+1][m], q_partial[r][m+1]) + times[job_r][m]
            # Insert job using Taillard O(M) per position
            best_pos = 0
            best_mk_ins = float('inf')
            f_ins = [0] * M
            for i in range(k+1):
                if i == 0:
                    f_ins[0] = times[job][0]
                    for m in range(1, M):
                        f_ins[m] = f_ins[m-1] + times[job][m]
                else:
                    f_ins[0] = e_partial[i-1][0] + times[job][0]
                    for m in range(1, M):
                        f_ins[m] = max(f_ins[m-1], e_partial[i-1][m]) + times[job][m]
                mk_ins = 0
                for m in range(M):
                    val = f_ins[m] + q_partial[i][m]
                    if val > mk_ins:
                        mk_ins = val
                if mk_ins < best_mk_ins:
                    best_mk_ins = mk_ins
                    best_pos = i
            current.insert(best_pos, job)
        # Acceptance
        curr_mk = makespan(current)
        if curr_mk < best_mk:
            best = current[:]
            best_mk = curr_mk
        if curr_mk < makespan(best):
            # This condition is redundant due to above, but kept for clarity
            pass
        if curr_mk < makespan(perm):
            perm = current[:]
        else:
            if random.random() < math.exp(-(curr_mk - makespan(perm)) / T):
                perm = current[:]
    return best

