def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    def taillard_forward(seq):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = seq[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][m] = prev + times[job][m]
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + times[job][m]
        return e

    def taillard_backward(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    down = q[r+1][m]
                    q[r][m] = down + times[job][m]
                else:
                    right = q[r][m+1]
                    down = q[r+1][m]
                    q[r][m] = max(right, down) + times[job][m]
        return q

    def evaluate_insertion(e, q, job, i, M):
        f = [0] * M
        for m in range(M):
            if m == 0:
                left = e[i-1][0] if i > 0 else 0
                f[m] = left + times[job][m]
            else:
                left = f[m-1]
                up = e[i-1][m] if i > 0 else 0
                f[m] = max(left, up) + times[job][m]
        best_cmax = float('inf')
        for m in range(M):
            val = f[m] + q[i][m]
            if val < best_cmax:
                best_cmax = val
        return best_cmax

    def neh_taillard(jobs):
        if not jobs:
            return []
        seq = [jobs[0]]
        if len(jobs) > 1:
            job1, job2 = jobs[0], jobs[1]
            c1 = makespan([job1, job2])
            c2 = makespan([job2, job1])
            seq = [job1, job2] if c1 <= c2 else [job2, job1]
        for idx in range(2, len(jobs)):
            job = jobs[idx]
            e = taillard_forward(seq)
            q = taillard_backward(seq)
            best_pos = 0
            best_cmax = float('inf')
            for pos in range(len(seq)+1):
                cmax = evaluate_insertion(e, q, job, pos, M)
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    def ig_destroy_reconstruct(seq, d):
        if d >= len(seq):
            return seq[:]
        indices = random.sample(range(len(seq)), d)
        removed = [seq[i] for i in indices]
        remaining = [seq[i] for i in range(len(seq)) if i not in indices]
        random.shuffle(removed)
        for job in removed:
            e = taillard_forward(remaining)
            q = taillard_backward(remaining)
            best_pos = 0
            best_cmax = float('inf')
            for pos in range(len(remaining)+1):
                cmax = evaluate_insertion(e, q, job, pos, M)
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = pos
            remaining.insert(best_pos, job)
        return remaining

    job_sums = [sum(job) for job in times]
    jobs_sorted = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
    current = neh_taillard(jobs_sorted)
    best = current[:]
    best_cmax = makespan(best)

    max_iter = 60
    for _ in range(max_iter):
        d = 3 if N < 30 else 4
        candidate = ig_destroy_reconstruct(current, d)
        cmax_candidate = makespan(candidate)
        if cmax_candidate < makespan(current):
            current = candidate
            if cmax_candidate < best_cmax:
                best = candidate[:]
                best_cmax = cmax_candidate
        elif cmax_candidate < makespan(best):
            best = candidate[:]
            best_cmax = cmax_candidate
        else:
            delta = cmax_candidate - makespan(current)
            if delta < 0:
                current = candidate
            else:
                prob = math.exp(-delta / T)
                if random.random() < prob:
                    current = candidate
    return best

