def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    N = len(times)
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    def johnson_rule(p1, p2):
        n = len(p1)
        left, right = 0, n - 1
        seq = [0] * n
        jobs = list(range(n))
        while jobs:
            min_val = float('inf')
            min_job = -1
            min_side = -1
            for j in jobs:
                if p1[j] < min_val:
                    min_val = p1[j]
                    min_job = j
                    min_side = 0
                if p2[j] < min_val:
                    min_val = p2[j]
                    min_job = j
                    min_side = 1
            if min_side == 0:
                seq[left] = min_job
                left += 1
            else:
                seq[right] = min_job
                right -= 1
            jobs.remove(min_job)
        return seq

    best_perm = None
    best_makespan = float('inf')

    for l in range(1, M):
        p1 = [sum(times[i][:l]) for i in range(N)]
        p2 = [sum(times[i][M-l:]) for i in range(N)]
        perm = johnson_rule(p1, p2)
        mk = makespan(perm)
        if mk < best_makespan:
            best_makespan = mk
            best_perm = perm

    return best_perm

