def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Flatten times for faster access
    flat_times = [times[i][j] for i in range(n) for j in range(m)]
    total_processing = sum(flat_times)

    # Helper to compute makespan using forward recursion
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * m
        for job in seq:
            base = job * m
            t[0] += flat_times[base]
            for k in range(1, m):
                t[k] = max(t[k-1], t[k]) + flat_times[base + k]
        return t[-1]

    # Taillard's accelerated insertion evaluation
    def evaluate_insertion(current_seq, job_idx, forward_e, backward_q):
        k = len(current_seq)
        best_pos = 0
        best_cmax = float('inf')
        job_base = job_idx * m
        for pos in range(k + 1):
            # Compute forward vector f for inserting job at pos
            f = [0] * m
            if pos == 0:
                prev_e = [0] * m
            else:
                prev_e = [forward_e[pos-1][mm] for mm in range(m)]
            f[0] = prev_e[0] + flat_times[job_base]
            for mm in range(1, m):
                f[mm] = max(f[mm-1], prev_e[mm]) + flat_times[job_base + mm]
            # Compute makespan candidate: max_m (f[mm] + backward_q[pos][mm])
            cmax_candidate = 0
            for mm in range(m):
                val = f[mm] + backward_q[pos][mm]
                if val > cmax_candidate:
                    cmax_candidate = val
            if cmax_candidate < best_cmax:
                best_cmax = cmax_candidate
                best_pos = pos
        return best_pos, best_cmax

    # NEH construction with Taillard acceleration
    def construct_neh():
        # Job priority: total processing time descending
        job_order = sorted(range(n), key=lambda i: -sum(times[i]))
        if n == 0:
            return []
        # Start with first job
        seq = [job_order[0]]
        if n == 1:
            return seq
        # Initialize forward and backward for first job
        job0_base = job_order[0] * m
        e = [[0] * m]
        e[0][0] = flat_times[job0_base]
        for mm in range(1, m):
            e[0][mm] = e[0][mm-1] + flat_times[job0_base + mm]
        q = [[0] * m, [0] * m]  # q[0] and q[1]; q[1] is for r=1 (after first job)
        # q[1][mm] = 0 initially
        # Compute q[0] from q[1] and job0
        for mm in range(m-1, -1, -1):
            if mm == m-1:
                q[0][mm] = q[1][mm] + flat_times[job0_base + mm]
            else:
                q[0][mm] = max(q[1][mm], q[0][mm+1]) + flat_times[job0_base + mm]
        # Insert remaining jobs
        for idx in range(1, n):
            job_idx = job_order[idx]
            job_base = job_idx * m
            best_pos, _ = evaluate_insertion(seq, job_idx, e, q)
            seq.insert(best_pos, job_idx)
            # Update forward matrix e: recompute from scratch for new seq (k+1 jobs)
            k_new = len(seq)
            e_new = [[0] * m for _ in range(k_new)]
            for r in range(k_new):
                job_r = seq[r]
                base_r = job_r * m
                if r == 0:
                    e_new[0][0] = flat_times[base_r]
                    for mm in range(1, m):
                        e_new[0][mm] = e_new[0][mm-1] + flat_times[base_r + mm]
                else:
                    e_new[r][0] = e_new[r-1][0] + flat_times[base_r]
                    for mm in range(1, m):
                        e_new[r][mm] = max(e_new[r-1][mm], e_new[r][mm-1]) + flat_times[base_r + mm]
            e = e_new
            # Update backward matrix q: size (k_new+1) x m
            q_new = [[0] * m for _ in range(k_new + 1)]
            # q_new[k_new] = [0]*m already
            for r in range(k_new-1, -1, -1):
                job_r = seq[r]
                base_r = job_r * m
                for mm in range(m-1, -1, -1):
                    if mm == m-1:
                        q_new[r][mm] = q_new[r+1][mm] + flat_times[base_r + mm]
                    else:
                        q_new[r][mm] = max(q_new[r+1][mm], q_new[r][mm+1]) + flat_times[base_r + mm]
            q = q_new
        return seq

    # Iterated Greedy with destruction size 3
    def iterated_greedy(initial_seq, max_iter=50):
        current_seq = initial_seq[:]
        best_seq = initial_seq[:]
        best_cmax = makespan(best_seq)
        # Temperature parameter
        T = 0.5 * total_processing / (10 * n * m)
        if T < 1e-6:
            T = 1e-6
        for _ in range(max_iter):
            # Destruction: remove d=3 random jobs
            d = 3
            if n <= d:
                destroyed = []
                remaining = []
            else:
                positions = random.sample(range(n), d)
                positions.sort(reverse=True)
                destroyed = [current_seq.pop(pos) for pos in positions]
                remaining = current_seq
            # Reconstruction: reinsert destroyed jobs one by one using NEH insertion
            # Sort destroyed jobs by descending total processing time (NEH style)
            destroyed_sorted = sorted(destroyed, key=lambda j: -sum(times[j]))
            for job in destroyed_sorted:
                # Build forward and backward for current remaining sequence
                k = len(remaining)
                if k == 0:
                    e = [[0] * m]
                    job0_base = job * m
                    e[0][0] = flat_times[job0_base]
                    for mm in range(1, m):
                        e[0][mm] = e[0][mm-1] + flat_times[job0_base + mm]
                    q = [[0] * m, [0] * m]
                    for mm in range(m-1, -1, -1):
                        if mm == m-1:
                            q[0][mm] = q[1][mm] + flat_times[job0_base + mm]
                        else:
                            q[0][mm] = max(q[1][mm], q[0][mm+1]) + flat_times[job0_base + mm]
                else:
                    # Compute forward e for remaining
                    e = [[0] * m for _ in range(k)]
                    for r in range(k):
                        job_r = remaining[r]
                        base_r = job_r * m
                        if r == 0:
                            e[0][0] = flat_times[base_r]
                            for mm in range(1, m):
                                e[0][mm] = e[0][mm-1] + flat_times[base_r + mm]
                        else:
                            e[r][0] = e[r-1][0] + flat_times[base_r]
                            for mm in range(1, m):
                                e[r][mm] = max(e[r-1][mm], e[r][mm-1]) + flat_times[base_r + mm]
                    # Compute backward q for remaining
                    q = [[0] * m for _ in range(k + 1)]
                    # q[k] = [0]*m
                    for r in range(k-1, -1, -1):
                        job_r = remaining[r]
                        base_r = job_r * m
                        for mm in range(m-1, -1, -1):
                            if mm == m-1:
                                q[r][mm] = q[r+1][mm] + flat_times[base_r + mm]
                            else:
                                q[r][mm] = max(q[r+1][mm], q[r][mm+1]) + flat_times[base_r + mm]
                # Evaluate insertion positions for job
                best_pos, _ = evaluate_insertion(remaining, job, e, q)
                remaining.insert(best_pos, job)
            # New sequence after reconstruction
            new_seq = remaining
            new_cmax = makespan(new_seq)
            # Acceptance criterion
            if new_cmax < makespan(current_seq):
                current_seq = new_seq[:]
                if new_cmax < best_cmax:
                    best_seq = new_seq[:]
                    best_cmax = new_cmax
            else:
                if random.random() < math.exp(-(new_cmax - makespan(current_seq)) / T):
                    current_seq = new_seq[:]
        return best_seq

    # Build initial solution
    initial_seq = construct_neh()
    # Apply iterated greedy refinement
    refined_seq = iterated_greedy(initial_seq, max_iter=40)
    return refined_seq

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    P = [sum(job) for job in times]
    S = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Determine if bimodal: check variance in total processing times
    meanP = sum(P) / N
    varP = sum((p - meanP) ** 2 for p in P) / N
    is_bimodal = varP > (meanP * 0.3) ** 2  # heuristic threshold

    # Priority order: if bimodal, use slope index; else use total processing time
    if is_bimodal:
        order = sorted(range(N), key=lambda i: (-S[i], -P[i]))
    else:
        order = sorted(range(N), key=lambda i: (-P[i], -S[i]))

    # Precompute job processing times for fast access
    p = [job[:] for job in times]

    # Makespan calculation for a given sequence
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard's accelerated insertion evaluation
    def evaluate_insertion(partial, job_idx, k):
        # partial: current sequence of length k
        # job_idx: job to insert
        # Returns list of makespans for insertion at positions 0..k
        if k == 0:
            return [p[job_idx][0] + sum(p[job_idx][1:])]  # only one position

        # Forward matrix e: size k x M
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job][m]

        # Backward matrix q: size (k+1) x M, q[k][m] = 0
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]

        # Evaluate each insertion position i in 0..k
        makespans = [0] * (k+1)
        for i in range(k+1):
            # Compute forward vector f for job_idx up to machine m
            f = [0] * M
            for m in range(M):
                if m == 0:
                    prev_e = e[i-1][0] if i > 0 else 0
                    f[m] = prev_e + p[job_idx][m]
                else:
                    left = f[m-1]
                    up = e[i-1][m] if i > 0 else 0
                    f[m] = max(left, up) + p[job_idx][m]
            # Compute makespan: max over m of f[m] + q[i][m]
            max_val = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > max_val:
                    max_val = val
            makespans[i] = max_val
        return makespans

    # Construct initial solution using accelerated NEH
    def construct_initial():
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        # Evaluate first two jobs
        job0, job1 = order[0], order[1]
        seq1 = [job0, job1]
        seq2 = [job1, job0]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Insert remaining jobs
        for idx in range(2, N):
            job = order[idx]
            k = len(seq)
            makespans = evaluate_insertion(seq, job, k)
            # Find best position (earliest in case of tie)
            best_pos = 0
            best_val = makespans[0]
            for pos in range(1, k+1):
                if makespans[pos] < best_val:
                    best_val = makespans[pos]
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(initial_seq, max_iters=60):
        current = initial_seq[:]
        best = current[:]
        best_makespan = makespan(best)
        total_processing = sum(P)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        d = 3 if N > 20 else 2  # destruction size

        for _ in range(max_iters):
            # Destruction: remove d random jobs
            if d >= len(current):
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(len(current)), d)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(len(current)) if i not in indices_set]
            # Reconstruction: reinsert destroyed jobs one by one in random order
            random.shuffle(destroyed)
            seq = remaining[:]
            for job in destroyed:
                k = len(seq)
                if k == 0:
                    seq.append(job)
                else:
                    makespans = evaluate_insertion(seq, job, k)
                    best_pos = 0
                    best_val = makespans[0]
                    for pos in range(1, k+1):
                        if makespans[pos] < best_val:
                            best_val = makespans[pos]
                            best_pos = pos
                    seq.insert(best_pos, job)
            # Acceptance criterion
            new_makespan = makespan(seq)
            if new_makespan < makespan(current):
                current = seq
                if new_makespan < best_makespan:
                    best = seq[:]
                    best_makespan = new_makespan
            elif new_makespan < best_makespan:
                # Accept with probability based on Metropolis
                if random.random() < math.exp(-(new_makespan - makespan(current)) / T):
                    current = seq
                else:
                    # Reject: current remains unchanged
                    pass
            else:
                if random.random() < math.exp(-(new_makespan - makespan(current)) / T):
                    current = seq
        return best

    # Build initial solution and refine
    initial_seq = construct_initial()
    # Early exit if makespan is low (optional, but safe)
    if makespan(initial_seq) < 1000:  # arbitrary threshold, unlikely to trigger
        return initial_seq
    refined_seq = iterated_greedy(initial_seq, max_iters=50)
    return refined_seq

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_data = [row[:] for row in times]
    total_processing = [sum(row) for row in job_data]

    # Makespan evaluation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            pj = job_data[job]
            t[0] += pj[0]
            for k in range(1, m):
                t[k] = max(t[k-1], t[k]) + pj[k]
        return t[-1]

    # Taillard's acceleration: compute forward and backward matrices
    def compute_eb(perm):
        k = len(perm)
        if k == 0:
            return None, None
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            pj = job_data[perm[r]]
            if r == 0:
                e[0][0] = pj[0]
                for mc in range(1, m):
                    e[0][mc] = e[0][mc-1] + pj[mc]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for mc in range(1, m):
                    e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + pj[mc]
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pj = job_data[perm[r]]
            q[r][m-1] = q[r+1][m-1] + pj[m-1]
            for mc in range(m-2, -1, -1):
                q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + pj[mc]
        return e, q

    # Evaluate insertion makespan for job x at position i using precomputed e, q
    def insertion_makespan(e, q, x, i):
        pj = job_data[x]
        f = [0] * m
        if i == 0:
            f[0] = pj[0]
            for mc in range(1, m):
                f[mc] = f[mc-1] + pj[mc]
        else:
            f[0] = e[i-1][0] + pj[0]
            for mc in range(1, m):
                f[mc] = max(f[mc-1], e[i-1][mc]) + pj[mc]
        best = 0
        for mc in range(m):
            val = f[mc] + q[i][mc]
            if val > best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    def neh_construction():
        order = sorted(range(n), key=lambda i: total_processing[i], reverse=True)
        if n == 0:
            return []
        perm = [order[0]]
        if n == 1:
            return perm
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        # Insert remaining jobs
        for k in range(2, n):
            job = order[k]
            e, q = compute_eb(perm)
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                mk = insertion_makespan(e, q, job, i)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with destruction size 3
    def iterated_greedy(initial_perm, max_iters=60):
        current = initial_perm[:]
        best = current[:]
        best_mk = makespan(best)
        total_sum = sum(total_processing)
        T_param = 0.5
        T = T_param * total_sum / (10 * n * m) if n * m > 0 else 1e-6

        for _ in range(max_iters):
            # Destruction: remove 3 random jobs
            if n <= 3:
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(n), 3)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(n) if i not in indices_set]

            # Reconstruct using NEH insertion on remaining sequence
            if not remaining:
                perm_new = destroyed[:]
                random.shuffle(perm_new)
            else:
                e, q = compute_eb(remaining)
                perm_new = remaining[:]
                # Insert destroyed jobs one by one in random order
                random.shuffle(destroyed)
                for job in destroyed:
                    best_pos = 0
                    best_mk_local = float('inf')
                    for i in range(len(perm_new)+1):
                        mk = insertion_makespan(e, q, job, i)
                        if mk < best_mk_local:
                            best_mk_local = mk
                            best_pos = i
                    perm_new.insert(best_pos, job)
                    # Update e, q for next insertion (inefficient but necessary for correctness)
                    e, q = compute_eb(perm_new)

            mk_new = makespan(perm_new)
            # Acceptance criterion
            if mk_new < makespan(current) or random.random() < math.exp(-(mk_new - makespan(current)) / T):
                current = perm_new[:]
                if mk_new < best_mk:
                    best_mk = mk_new
                    best = current[:]
        return best

    # Build initial solution and refine
    initial_perm = neh_construction()
    refined_perm = iterated_greedy(initial_perm, max_iters=50)
    return refined_perm

