def _makespan_taillard(seq, job_data, M):
    if not seq:
        return 0
    n = len(seq)
    t = [0] * M
    for idx in seq:
        job = job_data[idx]
        t[0] += job[0]
        for m in range(1, M):
            t[m] = max(t[m-1], t[m]) + job[m]
    return t[M-1]

