def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for faster access
    proc = [times[i][:] for i in range(N)]
    total_proc = [sum(row) for row in proc]
    makespan_lower_bound = 0  # Will be updated if needed

    # Helper: compute makespan of a permutation
    def compute_makespan(perm):
        t = [0] * M
        for job in perm:
            pj = proc[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[-1]

    # Taillard-accelerated insertion: evaluate all positions in O(k*M)
    def evaluate_insertion(partial, job_idx):
        k = len(partial)
        if k == 0:
            return [job_idx], proc[job_idx][:]
        # Forward matrix e: completion times of partial schedule
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            pj = proc[partial[r]]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        # Backward matrix q: tail times from position r to end
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already
        for r in range(k-1, -1, -1):
            pj = proc[partial[r]]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        # Evaluate each insertion position i in [0, k]
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            # Forward pass for job_idx up to machine m, starting from e[i-1][:]
            f = [0] * M
            if i == 0:
                f[0] = proc[job_idx][0]
                for m in range(1, M):
                    f[m] = f[m-1] + proc[job_idx][m]
            else:
                f[0] = e[i-1][0] + proc[job_idx][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + proc[job_idx][m]
            # Compute makespan if inserted at i: max_m (f[m] + q[i][m])
            makespan_candidate = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_candidate:
                    makespan_candidate = val
            if makespan_candidate < best_makespan:
                best_makespan = makespan_candidate
                best_pos = i
        # Build new partial schedule
        new_partial = partial[:best_pos] + [job_idx] + partial[best_pos:]
        # Compute forward completion times for the new partial (needed for next insertion)
        k_new = len(new_partial)
        e_new = [[0] * M for _ in range(k_new)]
        for r in range(k_new):
            pj = proc[new_partial[r]]
            if r == 0:
                e_new[0][0] = pj[0]
                for m in range(1, M):
                    e_new[0][m] = e_new[0][m-1] + pj[m]
            else:
                e_new[r][0] = e_new[r-1][0] + pj[0]
                for m in range(1, M):
                    e_new[r][m] = max(e_new[r-1][m], e_new[r][m-1]) + pj[m]
        return new_partial, e_new

    # NEH construction with Taillard acceleration
    order = sorted(range(N), key=lambda i: total_proc[i], reverse=True)
    # Start with first two jobs
    if N >= 2:
        a, b = order[0], order[1]
        ab = compute_makespan([a, b])
        ba = compute_makespan([b, a])
        if ab <= ba:
            current = [a, b]
        else:
            current = [b, a]
        start_idx = 2
    else:
        current = [order[0]]
        start_idx = 1
    # Insert remaining jobs
    for idx in range(start_idx, N):
        job_idx = order[idx]
        current, _ = evaluate_insertion(current, job_idx)

    # Iterated Greedy refinement
    random.seed(42)  # Deterministic behavior
    T_param = 0.5
    total_processing = sum(total_proc)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    current_perm = current[:]
    best_perm = current_perm[:]
    best_makespan = compute_makespan(best_perm)
    d = 3 if N > 20 else 2  # Destruction size
    max_iter = 60  # Calibrated for <50ms

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            destroyed = [current_perm[i] for i in indices]
            remaining = [current_perm[i] for i in range(N) if i not in indices_set]
        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        perm = remaining[:]
        for job_idx in destroyed:
            perm, _ = evaluate_insertion(perm, job_idx)
        # Acceptance criterion
        new_makespan = compute_makespan(perm)
        if new_makespan < best_makespan:
            best_makespan = new_makespan
            best_perm = perm[:]
        if new_makespan < compute_makespan(current_perm):
            current_perm = perm
        else:
            if random.random() < math.exp(-(new_makespan - compute_makespan(current_perm)) / T):
                current_perm = perm
    return best_perm

