def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job data for fast access
    job_data = [row[:] for row in times]
    total_processing = [sum(job) for job in job_data]

    # Makespan calculation using recurrence
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            pj = job_data[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[M-1]

    # NEH construction with Taillard acceleration
    def neh_construct():
        # Sort by total processing time descending
        order = sorted(range(N), key=lambda i: total_processing[i], reverse=True)
        if N == 0:
            return []
        # Start with first job
        seq = [order[0]]
        if N == 1:
            return seq
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Greedy insertion for remaining jobs
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_mk = float('inf')
            # Evaluate all k+1 insertion positions using Taillard acceleration
            # Build forward matrix e for current seq (length k)
            e = [[0]*M for _ in range(k)]
            for r in range(k):
                pj = job_data[seq[r]]
                if r == 0:
                    e[0][0] = pj[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + pj[m]
                else:
                    e[r][0] = e[r-1][0] + pj[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
            # Build backward matrix q for current seq (length k)
            q = [[0]*M for _ in range(k+1)]  # q[k][*] = 0 already
            for r in range(k-1, -1, -1):
                pj = job_data[seq[r]]
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
            # Test each insertion position i in [0, k]
            for i in range(k+1):
                # Compute forward vector f for inserting job at position i
                f = [0]*M
                if i == 0:
                    # e[-1][m] = 0
                    f[0] = job_data[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], 0) + job_data[job][m]
                else:
                    pj = job_data[job]
                    im1 = i-1
                    f[0] = e[im1][0] + pj[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[im1][m]) + pj[m]
                # Compute makespan candidate: max_m (f[m] + q[i][m])
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            # Insert job at best_pos
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing_sum = sum(total_processing)
        T_param = 0.5
        T = T_param * total_processing_sum / (10 * N * M)
        d = 3 if N > 5 else N  # destruction size
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build partial sequence without removed jobs
            remaining = [job for idx, job in enumerate(current) if idx not in indices]
            # Reconstruction: reinsert removed jobs one by one using NEH insertion (Taillard accelerated)
            for job in removed:
                best_pos = 0
                best_mk_pos = float('inf')
                k = len(remaining)
                if k == 0:
                    remaining.append(job)
                    continue
                # Build forward matrix e for remaining (length k)
                e = [[0]*M for _ in range(k)]
                for r in range(k):
                    pj = job_data[remaining[r]]
                    if r == 0:
                        e[0][0] = pj[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + pj[m]
                    else:
                        e[r][0] = e[r-1][0] + pj[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
                # Build backward matrix q for remaining (length k)
                q = [[0]*M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    pj = job_data[remaining[r]]
                    q[r][M-1] = q[r+1][M-1] + pj[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
                # Test each insertion position i in [0, k]
                for i in range(k+1):
                    f = [0]*M
                    if i == 0:
                        f[0] = job_data[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], 0) + job_data[job][m]
                    else:
                        pj = job_data[job]
                        im1 = i-1
                        f[0] = e[im1][0] + pj[0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[im1][m]) + pj[m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_pos:
                        best_mk_pos = mk
                        best_pos = i
                remaining.insert(best_pos, job)
            # New candidate sequence
            candidate = remaining
            mk_candidate = makespan(candidate)
            # Acceptance criterion
            if mk_candidate < makespan(current):
                current = candidate[:]
                if mk_candidate < best_mk:
                    best = candidate[:]
                    best_mk = mk_candidate
            else:
                if random.random() < math.exp(-(mk_candidate - makespan(current)) / T):
                    current = candidate[:]
        return best

    # Get initial solution via NEH
    init_seq = neh_construct()
    # Refine with Iterated Greedy
    improved_seq = iterated_greedy(init_seq, max_iter=50)
    # Final check: if NEH alone is better, use it (should not happen, but safe)
    if makespan(init_seq) < makespan(improved_seq):
        return init_seq
    return improved_seq

