        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for NEH priority
    total_times = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Makespan evaluation function
    def makespan(seq):
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # NEH construction with Taillard acceleration
    def neh_construct():
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        # Initial pair
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        # Preallocate matrices
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N + 1)]
        # Iterative insertion
        for k in range(2, N):
            job = order[k]
            # Forward pass: compute e[0..k-1][*]
            for r in range(k):
                if r == 0:
                    e[0][0] = times[order[0]][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + times[order[0]][m]
                else:
                    e[r][0] = e[r-1][0] + times[order[r]][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + times[order[r]][m]
            # Backward pass: compute q[k][*] = 0, then q[k-1..0][*]
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                q[r][M-1] = q[r+1][M-1] + times[order[r]][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[order[r]][m]
            # Evaluate insertion positions
            best_pos = 0
            best_cmax = float('inf')
            for i in range(k+1):
                # Forward vector f for inserting job at position i
                if i == 0:
                    f0 = times[job][0]
                    f = [f0]
                    for m in range(1, M):
                        f.append(max(f[m-1], 0) + times[job][m])
                else:
                    f0 = e[i-1][0] + times[job][0]
                    f = [f0]
                    for m in range(1, M):
                        f.append(max(f[m-1], e[i-1][m]) + times[job][m])
                # Compute makespan candidate: max_m (f[m] + q[i][m])
                cmax_cand = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax_cand:
                        cmax_cand = val
                if cmax_cand < best_cmax:
                    best_cmax = cmax_cand
                    best_pos = i
            # Insert job at best_pos
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_cmax = makespan(best)
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 5 else N  # destruction size
        # Preallocate matrices for reconstruction
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N + 1)]
        for it in range(max_iter):
            # Destruction: remove d random jobs
            indices = list(range(N))
            random.shuffle(indices)
            removed_indices = indices[:d]
            removed_set = set(removed_indices)
            # Build destroyed sequence
            destroyed = [current[i] for i in range(N) if i not in removed_set]
            removed_jobs = [current[i] for i in removed_indices]
            # Reconstruct: insert removed jobs one by one using NEH/Taillard
            for job in removed_jobs:
                k = len(destroyed)
                if k == 0:
                    destroyed = [job]
                    continue
                # Forward pass for current destroyed sequence
                for r in range(k):
                    if r == 0:
                        e[0][0] = times[destroyed[0]][0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + times[destroyed[0]][m]
                    else:
                        e[r][0] = e[r-1][0] + times[destroyed[r]][0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + times[destroyed[r]][m]
                # Backward pass
                for m in range(M):
                    q[k][m] = 0
                for r in range(k-1, -1, -1):
                    q[r][M-1] = q[r+1][M-1] + times[destroyed[r]][M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[destroyed[r]][m]
                # Evaluate insertion positions
                best_pos = 0
                best_cmax_local = float('inf')
                for i in range(k+1):
                    if i == 0:
                        f0 = times[job][0]
                        f = [f0]
                        for m in range(1, M):
                            f.append(max(f[m-1], 0) + times[job][m])
                    else:
                        f0 = e[i-1][0] + times[job][0]
                        f = [f0]
                        for m in range(1, M):
                            f.append(max(f[m-1], e[i-1][m]) + times[job][m])
                    cmax_cand = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > cmax_cand:
                            cmax_cand = val
                    if cmax_cand < best_cmax_local:
                        best_cmax_local = cmax_cand
                        best_pos = i
                destroyed.insert(best_pos, job)
            current = destroyed
            current_cmax = makespan(current)
            # Acceptance criterion
            if current_cmax < best_cmax:
                best = current[:]
                best_cmax = current_cmax
            if current_cmax < makespan(best):  # redundant but safe
                best = current[:]
                best_cmax = current_cmax
            elif current_cmax < makespan(current):  # always true, but kept for structure
                pass
            else:
                delta = current_cmax - makespan(current)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    # accept worse solution
                    pass
                else:
                    # reject and keep current (which is unchanged from before destruction?)
                    # Actually, we already set current = destroyed, so to reject we need to revert?
                    # But in standard IG, we always accept the new solution (destroyed+reconstructed)
                    # and then decide whether to update the current solution for next iteration.
                    # Here, we always use the reconstructed solution as the basis for next iteration.
                    # The acceptance is only for updating the current solution.
                    # So we do nothing: current remains the reconstructed solution.
                    pass
        return best

    # Build initial solution
    initial_seq = neh_construct()
    # Apply iterated greedy refinement
    improved_seq = iterated_greedy(initial_seq, max_iter=50)
    return improved_seq

