def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T0 = T_param * total_processing / (10 * N * M)

    def makespan(perm):
        t = [0] * M
        for job in perm:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_times[m]
        return t[-1]

    def taillard_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        job0 = perm[0]
        e[0][0] = times[job0][0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + times[job0][m]
        for r in range(1, k):
            job = perm[r]
            e[r][0] = e[r-1][0] + times[job][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job][m]
        return e

    def taillard_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            q[r][M-1] = q[r+1][M-1] + times[job][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return q

    def insert_cost(perm, job, e_prev, q_next):
        if not perm:
            f = [0] * M
            f[0] = times[job][0]
            for m in range(1, M):
                f[m] = f[m-1] + times[job][m]
            return f[-1]
        f = [0] * M
        f[0] = e_prev[0] + times[job][0] if e_prev else times[job][0]
        for m in range(1, M):
            f[m] = max(f[m-1], e_prev[m]) + times[job][m]
        best = float('inf')
        for m in range(M):
            val = f[m] + q_next[m]
            if val < best:
                best = val
        return best

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: (-P[i], i))

    perm = [order[0]]
    for idx in range(1, N):
        job = order[idx]
        best_pos = 0
        best_cost = float('inf')
        e_prev = taillard_forward(perm)
        q_next = taillard_backward(perm)
        for pos in range(len(perm)+1):
            e_prev_pos = e_prev[pos-1] if pos > 0 else None
            q_next_pos = q_next[pos]
            cost = insert_cost(perm, job, e_prev_pos, q_next_pos)
            if cost < best_cost:
                best_cost = cost
                best_pos = pos
        perm.insert(best_pos, job)

    best_perm = perm[:]
    best_makespan = makespan(best_perm)

    max_iters = 60
    for it in range(max_iters):
        T = T0 * math.exp(-5.0 * it / max_iters)
        d = 3 if N < 30 else 4
        if d > N:
            d = N
        indices = random.sample(range(N), d)
        indices.sort(reverse=True)
        removed = []
        for idx in indices:
            removed.append(perm.pop(idx))
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_cost = float('inf')
            e_prev = taillard_forward(perm)
            q_next = taillard_backward(perm)
            for pos in range(len(perm)+1):
                e_prev_pos = e_prev[pos-1] if pos > 0 else None
                q_next_pos = q_next[pos]
                cost = insert_cost(perm, job, e_prev_pos, q_next_pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            perm.insert(best_pos, job)
        current_makespan = makespan(perm)
        if current_makespan < best_makespan:
            best_makespan = current_makespan
            best_perm = perm[:]
        if current_makespan < makespan(best_perm):
            pass
        if random.random() < math.exp(-(current_makespan - makespan(best_perm)) / T) if current_makespan > makespan(best_perm) else True:
            pass
        if current_makespan < makespan(perm):
            pass

    return best_perm

