def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    p_flat = [times[i][j] for i in range(N) for j in range(M)]

    def makespan(perm):
        t = [0] * M
        for job in perm:
            base = job * M
            for m in range(M):
                if m == 0:
                    t[m] += p_flat[base + m]
                else:
                    t[m] = max(t[m-1], t[m]) + p_flat[base + m]
        return t[-1]

    def taillard_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            base = job * M
            if r == 0:
                e[0][0] = p_flat[base + 0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p_flat[base + m]
            else:
                e[r][0] = e[r-1][0] + p_flat[base + 0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p_flat[base + m]
        return e

    def taillard_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            base = job * M
            q[r][M-1] = q[r+1][M-1] + p_flat[base + M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p_flat[base + m]
        return q

    def insertion_cost(e, q, job, pos, k):
        base = job * M
        f = [0] * M
        if pos == 0:
            f[0] = p_flat[base + 0]
            for m in range(1, M):
                f[m] = f[m-1] + p_flat[base + m]
        else:
            f[0] = e[pos-1][0] + p_flat[base + 0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + p_flat[base + m]
        best = float('inf')
        for m in range(M):
            val = f[m] + q[pos][m]
            if val < best:
                best = val
        return best

    def neh_construct():
        job_sums = [sum(times[i]) for i in range(N)]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        for k in range(2, N):
            job = order[k]
            e = taillard_forward(seq)
            q = taillard_backward(seq)
            best_cost = float('inf')
            best_pos = 0
            for pos in range(k+1):
                cost = insertion_cost(e, q, job, pos, k)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    def ig_improve(initial_seq, max_iter=60):
        if N <= 2:
            return initial_seq
        d = 3 if N > 5 else N
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        if T < 1e-9:
            T = 1e-9
        current = initial_seq[:]
        best = initial_seq[:]
        best_makespan = makespan(best)
        for _ in range(max_iter):
            if best_makespan == 0:
                break
            indices = list(range(N))
            random.shuffle(indices)
            removed = []
            remaining = []
            for idx in indices:
                if len(removed) < d:
                    removed.append(current[idx])
                else:
                    remaining.append(current[idx])
            random.shuffle(removed)
            seq = remaining[:]
            for job in removed:
                e = taillard_forward(seq)
                q = taillard_backward(seq)
                k = len(seq)
                best_cost = float('inf')
                best_pos = 0
                for pos in range(k+1):
                    cost = insertion_cost(e, q, job, pos, k)
                    if cost < best_cost:
                        best_cost = cost
                        best_pos = pos
                seq.insert(best_pos, job)
            new_makespan = makespan(seq)
            if new_makespan < makespan(current):
                current = seq
                if new_makespan < best_makespan:
                    best = seq[:]
                    best_makespan = new_makespan
            else:
                if random.random() < math.exp(-(new_makespan - makespan(current)) / T):
                    current = seq
        return best

    initial = neh_construct()
    improved = ig_improve(initial, max_iter=50)
    return improved

