    if N == 1:
        return [0]
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten processing times for fast access
    p = [times[i][:] for i in range(N)]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_p = p[job]
            t[0] += job_p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_p[m]
        return t[-1]

    # Precompute total processing times for NEH priority
    total = [sum(p[i]) for i in range(N)]
    order = sorted(range(N), key=lambda i: total[i], reverse=True)

    # Taillard-accelerated NEH construction
    def forward_backward(seq):
        k = len(seq)
        if k == 0:
            return ([], [[0]*M])
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            job = seq[r]
            job_p = p[job]
            if r == 0:
                e[0][0] = job_p[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_p[m]
            else:
                e[r][0] = e[r-1][0] + job_p[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_p[m]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            job_p = p[job]
            q[r][M-1] = q[r+1][M-1] + job_p[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_p[m]
        return e, q

    def insertion_cost(e, q, job, pos):
        k = len(e)
        job_p = p[job]
        f = [0]*M
        if pos == 0:
            f[0] = job_p[0]
            for m in range(1, M):
                f[m] = f[m-1] + job_p[m]
        else:
            f[0] = e[pos-1][0] + job_p[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + job_p[m]
        best = float('inf')
        for m in range(M):
            val = f[m] + q[pos][m]
            if val < best:
                best = val
        return best

    # Build initial solution with NEH
    pi = [order[0]]
    e, q = forward_backward(pi)
    for idx in range(1, N):
        job = order[idx]
        best_cost = float('inf')
        best_pos = 0
        for pos in range(len(pi)+1):
            cost = insertion_cost(e, q, job, pos)
            if cost < best_cost:
                best_cost = cost
                best_pos = pos
        pi.insert(best_pos, job)
        e, q = forward_backward(pi)

    # Iterated Greedy refinement
    best_pi = pi[:]
    best_cmax = makespan(pi)
    total_processing = sum(total)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N < 30 else 4
    max_iter = 60

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [pi[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del pi[i]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            e, q = forward_backward(pi)
            best_cost = float('inf')
            best_pos = 0
            for pos in range(len(pi)+1):
                cost = insertion_cost(e, q, job, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            pi.insert(best_pos, job)
        # Acceptance
        current_cmax = makespan(pi)
        if current_cmax < best_cmax:
            best_cmax = current_cmax
            best_pi = pi[:]
        if current_cmax < makespan(best_pi):
            # Accept if better than current
            if random.random() < math.exp(-(current_cmax - makespan(best_pi)) / T):
                pass  # keep current pi
            else:
                pi = best_pi[:]  # revert to best
        else:
            # Worse than current, metropolis
            if random.random() < math.exp(-(current_cmax - makespan(best_pi)) / T):
                pass  # accept worse
            else:
                pi = best_pi[:]  # revert to best

    return best_pi

