def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total = [sum(job) for job in times]
    slope = [sum((2 * j - m + 1) * times[i][j] for j in range(m)) for i in range(n)]

    # Makespan evaluation for a given permutation
    def makespan(perm):
        t = [0] * m
        for job in perm:
            for k in range(m):
                if k == 0:
                    t[k] += times[job][k]
                else:
                    t[k] = max(t[k], t[k-1]) + times[job][k]
        return t[-1]

    # Taillard's acceleration: compute forward and backward matrices for a partial schedule
    def taillard_matrices(perm):
        k = len(perm)
        e = [[0] * m for _ in range(k)]
        if k == 0:
            return e, [[0] * m for _ in range(k+1)]
        # Forward pass
        for r in range(k):
            job = perm[r]
            for c in range(m):
                if r == 0 and c == 0:
                    e[r][c] = times[job][c]
                elif r == 0:
                    e[r][c] = e[r][c-1] + times[job][c]
                elif c == 0:
                    e[r][c] = e[r-1][c] + times[job][c]
                else:
                    e[r][c] = max(e[r-1][c], e[r][c-1]) + times[job][c]
        # Backward pass
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            for c in range(m-1, -1, -1):
                if r == k-1 and c == m-1:
                    q[r][c] = times[job][c]
                elif r == k-1:
                    q[r][c] = q[r][c+1] + times[job][c]
                elif c == m-1:
                    q[r][c] = q[r+1][c] + times[job][c]
                else:
                    q[r][c] = max(q[r+1][c], q[r][c+1]) + times[job][c]
        return e, q

    # Evaluate makespan of inserting job x at position i in partial schedule perm
    def insertion_makespan(perm, x, i, e, q):
        f = [0] * m
        prev_e = e[i-1] if i > 0 else [0] * m
        for c in range(m):
            if c == 0:
                f[c] = prev_e[0] + times[x][c]
            else:
                f[c] = max(f[c-1], prev_e[c]) + times[x][c]
        makespan_val = 0
        for c in range(m):
            val = f[c] + q[i][c]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    def neh_construction(order):
        if not order:
            return []
        perm = [order[0]]
        if len(order) == 1:
            return perm
        # Initial pair
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        # Greedy insertion
        for idx in range(2, len(order)):
            job = order[idx]
            e, q = taillard_matrices(perm)
            best_pos = 0
            best_mk = insertion_makespan(perm, job, 0, e, q)
            for pos in range(1, len(perm)+1):
                mk = insertion_makespan(perm, job, pos, e, q)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_perm, max_iter=60):
        current = initial_perm[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing = sum(total)
        T_param = 0.5
        T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
        d = 3 if n < 30 else 4
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(n), d)
            removed = [current[i] for i in indices]
            remaining = [current[i] for i in range(n) if i not in indices]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                e, q = taillard_matrices(remaining)
                best_pos = 0
                best_mk_ins = insertion_makespan(remaining, job, 0, e, q)
                for pos in range(1, len(remaining)+1):
                    mk = insertion_makespan(remaining, job, pos, e, q)
                    if mk < best_mk_ins:
                        best_mk_ins = mk
                        best_pos = pos
                remaining.insert(best_pos, job)
            # Acceptance
            new_mk = makespan(remaining)
            if new_mk < makespan(current):
                current = remaining[:]
                if new_mk < best_mk:
                    best = remaining[:]
                    best_mk = new_mk
            elif new_mk < best_mk:
                # Metropolis acceptance
                delta = new_mk - makespan(current)
                if random.random() < math.exp(-delta / T):
                    current = remaining[:]
        return best

    # Try multiple priority orders and pick the best
    orders = []
    # Order by total processing time descending
    orders.append(sorted(range(n), key=lambda i: total[i], reverse=True))
    # Order by slope index descending
    orders.append(sorted(range(n), key=lambda i: slope[i], reverse=True))
    # Order by first machine time descending
    orders.append(sorted(range(n), key=lambda i: times[i][0], reverse=True))
    # Order by last machine time descending
    orders.append(sorted(range(n), key=lambda i: times[i][-1], reverse=True))

    best_overall = None
    best_overall_mk = float('inf')
    for order in orders:
        init_perm = neh_construction(order)
        refined_perm = iterated_greedy(init_perm, max_iter=50)
        mk = makespan(refined_perm)
        if mk < best_overall_mk:
            best_overall_mk = mk
            best_overall = refined_perm[:]
    return best_overall

