def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and variances per machine
    P = [0] * N
    var = [0.0] * M
    mean = [0.0] * M
    for i in range(N):
        for j in range(M):
            t = times[i][j]
            P[i] += t
            mean[j] += t
    for j in range(M):
        mean[j] /= N
        v = 0.0
        for i in range(N):
            d = times[i][j] - mean[j]
            v += d * d
        var[j] = v / N if N > 0 else 0.0

    # Compute Palmer-like slope index with inverse variance weighting
    slope = [0.0] * N
    for i in range(N):
        s = 0.0
        for j in range(M):
            # Weight: (2j - M + 1) / (var[j] + 1e-9) to avoid division by zero
            w = (2 * j - M + 1) / (var[j] + 1e-9)
            s += w * times[i][j]
        slope[i] = s

    # Sort jobs by slope descending
    order = sorted(range(N), key=lambda i: slope[i], reverse=True)

    # Helper: makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t_prev = [0] * M
        for job in perm:
            t_curr = [0] * M
            for m in range(M):
                if m == 0:
                    t_curr[m] = t_prev[m] + times[job][m]
                else:
                    t_curr[m] = max(t_prev[m], t_curr[m-1]) + times[job][m]
            t_prev = t_curr
        return t_prev[M-1]

    # Taillard's accelerated insertion evaluation
    def evaluate_insertion(partial, job, k):
        # partial: list of job indices of length k
        # Returns list of makespans for inserting job at positions 0..k
        if k == 0:
            return [times[job][0]]  # only one machine? handled below
        # Forward matrix e: k x M
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][m] = prev + times[job_r][m]
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + times[job_r][m]
        # Backward tail matrix q: (k+1) x M
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job_r][m]
                else:
                    down = q[r+1][m]
                    right = q[r][m+1]
                    q[r][m] = max(down, right) + times[job_r][m]
        # Evaluate each insertion position i in 0..k
        res = [0] * (k+1)
        for i in range(k+1):
            # forward vector f for job at position i
            f = [0] * M
            for m in range(M):
                if m == 0:
                    prev_e = e[i-1][0] if i > 0 else 0
                    f[m] = prev_e + times[job][m]
                else:
                    left = f[m-1]
                    up = e[i-1][m] if i > 0 else 0
                    f[m] = max(left, up) + times[job][m]
            # makespan = max_m (f[m] + q[i][m])
            best = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > best:
                    best = val
            res[i] = best
        return res

    # Construct initial solution using NEH with Taillard acceleration
    perm = []
    for idx in order:
        k = len(perm)
        costs = evaluate_insertion(perm, idx, k)
        # Find best position (earliest in case of tie)
        best_pos = 0
        min_cost = costs[0]
        for pos in range(1, k+1):
            if costs[pos] < min_cost:
                min_cost = costs[pos]
                best_pos = pos
        perm.insert(best_pos, idx)

    # Iterated Greedy refinement
    current = perm[:]
    current_makespan = makespan(current)
    best_perm = current[:]
    best_makespan = current_makespan

    total_processing = sum(P)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N > 3 else N
    max_iter = 60
    if N * M > 2000:
        max_iter = 30
    elif N * M < 200:
        max_iter = 100

    for _ in range(max_iter):
        # Destruction: remove d jobs at random positions
        if d >= N:
            destroyed = []
            R = current[:]
        else:
            positions = random.sample(range(N), d)
            positions.sort(reverse=True)
            destroyed = [current.pop(pos) for pos in positions]
            R = destroyed
        # Reconstruction: reinsert each job in R using NEH insertion
        for job in R:
            k = len(current)
            costs = evaluate_insertion(current, job, k)
            best_pos = 0
            min_cost = costs[0]
            for pos in range(1, k+1):
                if costs[pos] < min_cost:
                    min_cost = costs[pos]
                    best_pos = pos
            current.insert(best_pos, job)
        new_makespan = makespan(current)
        # Acceptance criterion
        if new_makespan < current_makespan:
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_makespan = new_makespan
                best_perm = current[:]
        elif new_makespan < best_makespan or random.random() < math.exp(-(new_makespan - current_makespan) / T):
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_makespan = new_makespan
                best_perm = current[:]
        else:
            # Reject: restore current to previous state (need to rebuild from best? or keep current?)
            # For simplicity, we keep the rejected solution as current for next iteration
            pass

    return best_perm

