                e[r][0] = e[r-1][0] + times[current[r]][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + times[current[r]][m]
        for m in range(M):
            q[cur_len][m] = 0
        for r in range(cur_len-1, -1, -1):
            q[r][M-1] = q[r+1][M-1] + times[current[r]][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + times[current[r]][m]
        # Insert each removed job in random order
        random.shuffle(removed_jobs)
        for job in removed_jobs:
            best_pos = 0
            best_mk = float('inf')
            for i in range(len(current)+1):
                f = [0] * M
                if i == 0:
                    f[0] = times[job][0]
                else:
                    f[0] = e[i-1][0] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m] if i-1 >= 0 else 0) + times[job][m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            current.insert(best_pos, job)
            # Update e and q for new current (length increased by 1)
            # Recompute e and q from scratch for simplicity (still O(N*M) per insertion)
            cur_len = len(current)
            e = [[0] * M for _ in range(cur_len)]
            q = [[0] * M for _ in range(cur_len + 1)]
            for r in range(cur_len):
                if r == 0:
                    e[r][0] = times[current[r]][0]
                else:
                    e[r][0] = e[r-1][0] + times[current[r]][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + times[current[r]][m]
            for m in range(M):
                q[cur_len][m] = 0
            for r in range(cur_len-1, -1, -1):
                q[r][M-1] = q[r+1][M-1] + times[current[r]][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[current[r]][m]
        # Evaluate new solution
        mk = makespan(current)
        if mk < best_mk:
            best_mk = mk
            best_perm = current[:]
            no_improve = 0
        # Acceptance criterion
        if mk < makespan(perm) or random.random() < math.exp(-(mk - makespan(perm)) / T):
            perm = current[:]
            if mk < makespan(perm):
                no_improve = 0
            else:
                no_improve += 1
        else:
            no_improve += 1

    return best_perm

