import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flat arrays and total processing times
    p = [sum(job) for job in times]
    flat_p = [times[i][j] for i in range(N) for j in range(M)]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            base = job * M
            for m in range(M):
                if m == 0:
                    t[m] += flat_p[base + m]
                else:
                    t[m] = max(t[m], t[m-1]) + flat_p[base + m]
        return t[-1]

    # Taillard acceleration: forward matrix
    def compute_forward(perm, k):
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            base = job * M
            if r == 0:
                e[0][0] = flat_p[base]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + flat_p[base + m]
            else:
                e[r][0] = e[r-1][0] + flat_p[base]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + flat_p[base + m]
        return e

    # Taillard acceleration: backward matrix
    def compute_backward(perm, k):
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            base = job * M
            q[r][M-1] = q[r+1][M-1] + flat_p[base + M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + flat_p[base + m]
        return q

    # Evaluate insertion of job x at position i using Taillard's O(M) method
    def insert_cost(e, q, i, x, k):
        base = x * M
        f = [0] * M
        if i == 0:
            f[0] = flat_p[base]
            for m in range(1, M):
                f[m] = f[m-1] + flat_p[base + m]
        else:
            f[0] = e[i-1][0] + flat_p[base]
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + flat_p[base + m]
        best = float('inf')
        for m in range(M):
            val = f[m] + q[i][m]
            if val < best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    def neh_construction():
        order = sorted(range(N), key=lambda i: p[i], reverse=True)
        if N == 1:
            return order[:]
        # Initial pair
        seq = [order[0], order[1]]
        best_seq = [order[1], order[0]]
        if makespan(seq) > makespan(best_seq):
            seq = best_seq
        # Greedy insertion
        for k in range(2, N):
            job = order[k]
            e = compute_forward(seq, k)
            q = compute_backward(seq, k)
            best_pos = 0
            best_cost = float('inf')
            for i in range(k+1):
                cost = insert_cost(e, q, i, job, k)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_seq):
        current = initial_seq[:]
        best = current[:]
        best_makespan = makespan(best)
        total_processing = sum(p)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 5 else max(1, N // 2)
        max_iter = 60
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build partial sequence without removed jobs
            marker = [False] * N
            for idx in indices:
                marker[idx] = True
            partial = [current[i] for i in range(N) if not marker[i]]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                k = len(partial)
                e = compute_forward(partial, k)
                q = compute_backward(partial, k)
                best_pos = 0
                best_cost = float('inf')
                for i in range(k+1):
                    cost = insert_cost(e, q, i, job, k)
                    if cost < best_cost:
                        best_cost = cost
                        best_pos = i
                partial.insert(best_pos, job)
            current = partial
            curr_makespan = makespan(current)
            # Acceptance criterion
            if curr_makespan < makespan(best):
                best = current[:]
                best_makespan = curr_makespan
            if curr_makespan < makespan(initial_seq):
                current = current[:]
            else:
                if random.random() < math.exp(-(curr_makespan - makespan(initial_seq)) / T):
                    current = current[:]
                else:
                    current = initial_seq[:]
        return best

    # Run the pipeline
    initial_seq = neh_construction()
    refined_seq = iterated_greedy(initial_seq)
    return refined_seq

