def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for NEH priority
    total_times = [sum(row) for row in times]
    jobs_sorted = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Makespan calculation function
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[-1]

    # Taillard-accelerated makespan for insertion evaluation
    def insertion_makespan(seq, job, pos):
        k = len(seq)
        if k == 0:
            return times[job][-1] if M == 1 else _makespan_single_job(times[job])
        # Forward matrix e for seq[0:pos]
        e = [0] * M
        for idx in range(pos):
            j = seq[idx]
            jt = times[j]
            if idx == 0:
                e[0] = jt[0]
                for m in range(1, M):
                    e[m] = e[m-1] + jt[m]
            else:
                e[0] += jt[0]
                for m in range(1, M):
                    e[m] = max(e[m-1], e[m]) + jt[m]
        # Backward matrix q for seq[pos:k]
        q = [0] * M
        for idx in range(k-1, pos-1, -1):
            j = seq[idx]
            jt = times[j]
            if idx == k-1:
                q[M-1] = jt[M-1]
                for m in range(M-2, -1, -1):
                    q[m] = q[m+1] + jt[m]
            else:
                q[M-1] += jt[M-1]
                for m in range(M-2, -1, -1):
                    q[m] = max(q[m], q[m+1]) + jt[m]
        # Forward vector f for job at position pos
        f = [0] * M
        if pos == 0:
            f[0] = times[job][0]
            for m in range(1, M):
                f[m] = f[m-1] + times[job][m]
        else:
            f[0] = e[0] + times[job][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[m]) + times[job][m]
        # Compute makespan
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Helper for single job makespan (used when seq empty)
    def _makespan_single_job(job_time):
        t = 0
        for m in range(M):
            t += job_time[m]
        return t

    # NEH construction with Taillard acceleration
    def constructive_neh():
        if len(jobs_sorted) < 2:
            return jobs_sorted[:]
        # Initial pair
        seq0 = [jobs_sorted[0], jobs_sorted[1]]
        seq1 = [jobs_sorted[1], jobs_sorted[0]]
        seq = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        # Insert remaining jobs
        for idx in range(2, N):
            job = jobs_sorted[idx]
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(seq) + 1):
                m = insertion_makespan(seq, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(initial_seq):
        current_seq = initial_seq[:]
        best_seq = current_seq[:]
        best_makespan = makespan(current_seq)
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2
        max_iter = 60
        no_improve_limit = 20
        no_improve = 0

        for it in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current_seq[i] for i in sorted(indices, reverse=True)]
            for i in sorted(indices, reverse=True):
                del current_seq[i]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                best_pos = 0
                best_m = float('inf')
                for pos in range(len(current_seq) + 1):
                    m = insertion_makespan(current_seq, job, pos)
                    if m < best_m:
                        best_m = m
                        best_pos = pos
                current_seq.insert(best_pos, job)
            # Acceptance
            curr_makespan = makespan(current_seq)
            if curr_makespan < best_makespan:
                best_makespan = curr_makespan
                best_seq = current_seq[:]
                no_improve = 0
            if curr_makespan < makespan(initial_seq):  # Always accept if better than start of iteration
                initial_seq = current_seq[:]  # Optional: shift reference
            else:
                if random.random() < math.exp(-(curr_makespan - makespan(initial_seq)) / T):
                    initial_seq = current_seq[:]  # Accept worse solution
                else:
                    current_seq = initial_seq[:]  # Revert to previous state
            # Early exit if no improvement
            if no_improve >= no_improve_limit:
                break
            no_improve += 1
        return best_seq

    # Generate initial solution and refine
    initial_seq = constructive_neh()
    refined_seq = iterated_greedy(initial_seq)
    return refined_seq

