def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    if n == 1:
        return [0]
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_times = [row[:] for row in times]
    total_time = [sum(job) for job in job_times]

    # Makespan calculation
    def makespan(seq):
        t = [0] * m
        for job in seq:
            for k in range(m):
                if k == 0:
                    t[k] += job_times[job][k]
                else:
                    t[k] = max(t[k], t[k-1]) + job_times[job][k]
        return t[-1]

    # Taillard acceleration: forward matrix e and backward matrix q
    def compute_forward(seq):
        k = len(seq)
        if k == 0:
            return [[0] * m]
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job = seq[r]
            pj = job_times[job]
            if r == 0:
                e[0][0] = pj[0]
                for mm in range(1, m):
                    e[0][mm] = e[0][mm-1] + pj[mm]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for mm in range(1, m):
                    e[r][mm] = max(e[r-1][mm], e[r][mm-1]) + pj[mm]
        return e

    def compute_backward(seq):
        k = len(seq)
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            pj = job_times[job]
            q[r][m-1] = q[r+1][m-1] + pj[m-1]
            for mm in range(m-2, -1, -1):
                q[r][mm] = max(q[r+1][mm], q[r][mm+1]) + pj[mm]
        return q

    # NEH construction with Taillard acceleration
    def neh_construct():
        jobs = list(range(n))
        jobs.sort(key=lambda i: total_time[i], reverse=True)
        if n == 0:
            return []
        seq = [jobs[0]]
        if n == 1:
            return seq
        # Try both orders for first two
        seq1 = [jobs[0], jobs[1]]
        seq2 = [jobs[1], jobs[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        # Insert remaining jobs
        for idx in range(2, n):
            job = jobs[idx]
            k = len(seq)
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_mk = float('inf')
            for pos in range(k+1):
                # Compute forward vector f for inserting job at pos
                f = [0] * m
                if pos == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[pos-1]
                pj = job_times[job]
                f[0] = prev_e[0] + pj[0]
                for mm in range(1, m):
                    f[mm] = max(f[mm-1], prev_e[mm]) + pj[mm]
                # Compute makespan: max over m of f[mm] + q[pos][mm]
                mk = 0
                for mm in range(m):
                    val = f[mm] + q[pos][mm]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size 3
    def iterated_greedy(initial_seq, max_iter=60):
        current_seq = initial_seq[:]
        best_seq = current_seq[:]
        best_mk = makespan(current_seq)
        total_processing = sum(total_time)
        T_param = 0.5
        T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
        for _ in range(max_iter):
            # Destruction: remove d=3 jobs at random positions
            d = 3
            if n <= d:
                destroyed = []
                remaining = []
            else:
                positions = random.sample(range(n), d)
                positions.sort(reverse=True)
                destroyed = [current_seq.pop(pos) for pos in positions]
                remaining = current_seq
            # Reconstruction: reinsert destroyed jobs one by one using NEH insertion
            for job in destroyed:
                k = len(remaining)
                if k == 0:
                    remaining.append(job)
                    continue
                e = compute_forward(remaining)
                q = compute_backward(remaining)
                best_pos = 0
                best_mk = float('inf')
                for pos in range(k+1):
                    f = [0] * m
                    if pos == 0:
                        prev_e = [0] * m
                    else:
                        prev_e = e[pos-1]
                    pj = job_times[job]
                    f[0] = prev_e[0] + pj[0]
                    for mm in range(1, m):
                        f[mm] = max(f[mm-1], prev_e[mm]) + pj[mm]
                    mk = 0
                    for mm in range(m):
                        val = f[mm] + q[pos][mm]
                        if val > mk:
                            mk = val
                    if mk < best_mk:
                        best_mk = mk
                        best_pos = pos
                remaining.insert(best_pos, job)
            new_seq = remaining
            new_mk = makespan(new_seq)
            # Acceptance criterion
            if new_mk < best_mk:
                best_mk = new_mk
                best_seq = new_seq[:]
                current_seq = new_seq
            elif new_mk < makespan(current_seq):
                current_seq = new_seq
            else:
                if random.random() < math.exp(-(new_mk - makespan(current_seq)) / T):
                    current_seq = new_seq
        return best_seq

    # Main pipeline
    initial_seq = neh_construct()
    # If initial solution is already good, refine lightly
    refined_seq = iterated_greedy(initial_seq, max_iter=40)
    return refined_seq

