def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_times = [sum(job) for job in times]
    slope_indices = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # NEH with Taillard acceleration
    order = sorted(range(N), key=lambda i: (-total_times[i], -slope_indices[i]))

    def compute_forward(perm):
        if not perm:
            return [[0] * M]
        e = [[0] * M for _ in range(len(perm))]
        for r, job in enumerate(perm):
            t = times[job]
            if r == 0:
                e[0][0] = t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + t[m]
            else:
                e[r][0] = e[r-1][0] + t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + t[m]
        return e

    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k + 1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            t = times[job]
            q[r][M-1] = q[r+1][M-1] + t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + t[m]
        return q

    def makespan_with_insertion(perm, pos, job):
        k = len(perm)
        if k == 0:
            return sum(times[job])
        e = compute_forward(perm)
        q = compute_backward(perm)
        f = [0] * M
        prev_e = e[pos-1] if pos > 0 else [0] * M
        t = times[job]
        f[0] = prev_e[0] + t[0]
        for m in range(1, M):
            f[m] = max(f[m-1], prev_e[m]) + t[m]
        makespan = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan:
                makespan = val
        return makespan

    def makespan(perm):
        if not perm:
            return 0
        e = compute_forward(perm)
        return e[-1][-1]

    # Build initial solution
    perm = [order[0]]
    best_two = [order[0], order[1]]
    alt_two = [order[1], order[0]]
    perm = best_two if makespan(best_two) <= makespan(alt_two) else alt_two
    for idx in range(2, N):
        job = order[idx]
        best_pos = 0
        best_val = makespan_with_insertion(perm, 0, job)
        for pos in range(1, idx + 1):
            val = makespan_with_insertion(perm, pos, job)
            if val < best_val:
                best_val = val
                best_pos = pos
        perm.insert(best_pos, job)

    current = perm[:]
    best = current[:]
    best_makespan = makespan(best)
    total_processing = sum(total_times)

    # Iterated Greedy
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 80
    if N > 80:
        max_iter = 50
    if N > 100:
        max_iter = 30

    for _ in range(max_iter):
        # Destruction
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        remaining = [current[i] for i in range(N) if i not in indices]
        random.shuffle(removed)
        # Reconstruction
        for job in removed:
            best_pos = 0
            best_val = makespan_with_insertion(remaining, 0, job)
            for pos in range(1, len(remaining) + 1):
                val = makespan_with_insertion(remaining, pos, job)
                if val < best_val:
                    best_val = val
                    best_pos = pos
            remaining.insert(best_pos, job)
        current = remaining
        curr_makespan = makespan(current)
        if curr_makespan < best_makespan:
            best_makespan = curr_makespan
            best = current[:]
        # Metropolis acceptance
        if curr_makespan < makespan(current):
            pass  # current already updated
