                left = f[m-1]
                up = e[i-1][m] if i > 0 else 0
                f[m] = max(left, up) + get_time(x, m)
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    total_times = [sum(get_time(i, m) for m in range(M)) for i in range(N)]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    perm = [order[0]]
    e, q = compute_eq(perm)
    for idx in range(1, N):
        job = order[idx]
        best_pos = 0
        best_mk = float('inf')
        for pos in range(len(perm) + 1):
            mk = insertion_makespan(perm, e, q, job, pos)
            if mk < best_mk:
                best_mk = mk
                best_pos = pos
        perm.insert(best_pos, job)
        e, q = compute_eq(perm)

    # Iterated Greedy (IG) refinement
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    current = perm[:]
    best = perm[:]
    best_mk = makespan(best)
    max_iters = 60
    no_improve_limit = 20
    no_improve = 0

    for _ in range(max_iters):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del current[i]
        # Reconstruction: reinsert each removed job using NEH/Taillard
        for job in removed:
            e_cur, q_cur = compute_eq(current)
            best_pos = 0
            best_mk_ins = float('inf')
            for pos in range(len(current) + 1):
                mk_ins = insertion_makespan(current, e_cur, q_cur, job, pos)
                if mk_ins < best_mk_ins:
                    best_mk_ins = mk_ins
                    best_pos = pos
            current.insert(best_pos, job)
        # Acceptance
        curr_mk = makespan(current)
        if curr_mk < best_mk:
            best = current[:]
            best_mk = curr_mk
            no_improve = 0
        else:
            if curr_mk < makespan(perm):
                perm = current[:]
                no_improve = 0
            else:
                if random.random() < math.exp(-(curr_mk - makespan(perm)) / T):
                    perm = current[:]
                no_improve += 1
        if no_improve >= no_improve_limit:
            break
        current = perm[:]

    return best

