def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for fast access
    p = [row[:] for row in times]

    # Compute total processing times and bottleneck machine
    total = [sum(job) for job in p]
    machine_load = [sum(p[i][j] for i in range(n)) for j in range(m)]
    bottleneck = machine_load.index(max(machine_load))

    # Compute Palmer's slope index
    slope = [sum((2 * j - m + 1) * p[i][j] for j in range(m)) for i in range(n)]

    # Create job order: primary by total time descending, secondary by slope descending
    order = sorted(range(n), key=lambda i: (-total[i], -slope[i]))

    # Helper to compute makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            for mach in range(m):
                if mach == 0:
                    t[mach] += p[job][mach]
                else:
                    t[mach] = max(t[mach], t[mach-1]) + p[job][mach]
        return t[-1]

    # NEH construction with Taillard acceleration
    def neh_construction(job_order):
        if not job_order:
            return []
        perm = [job_order[0]]
        e = [0] * m  # forward completion times
        for job in perm:
            for mach in range(m):
                if mach == 0:
                    e[mach] += p[job][mach]
                else:
                    e[mach] = max(e[mach], e[mach-1]) + p[job][mach]

        for idx in range(1, len(job_order)):
            job = job_order[idx]
            k = len(perm)
            # Compute forward matrix e for current perm (already computed)
            # Compute backward tail matrix q
            q = [[0] * m for _ in range(k+1)]
            for mach in range(m):
                q[k][mach] = 0
            for r in range(k-1, -1, -1):
                job_r = perm[r]
                for mach in range(m-1, -1, -1):
                    if mach == m-1:
                        q[r][mach] = q[r+1][mach] + p[job_r][mach]
                    else:
                        q[r][mach] = max(q[r+1][mach], q[r][mach+1]) + p[job_r][mach]

            best_pos = 0
            best_makespan = float('inf')
            # Try inserting job at each position
            for pos in range(k+1):
                # Compute forward vector f for job at position pos
                f = [0] * m
                if pos == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[pos-1]
                for mach in range(m):
                    if mach == 0:
                        f[mach] = prev_e[mach] + p[job][mach]
                    else:
                        f[mach] = max(f[mach-1], prev_e[mach]) + p[job][mach]
                # Compute makespan if job inserted at pos
                ms = 0
                for mach in range(m):
                    val = f[mach] + q[pos][mach]
                    if val > ms:
                        ms = val
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            # Insert job at best_pos
            perm.insert(best_pos, job)
            # Update e for new perm
            e = [0] * m
            for job_in_perm in perm:
                for mach in range(m):
                    if mach == 0:
                        e[mach] += p[job_in_perm][mach]
                    else:
                        e[mach] = max(e[mach], e[mach-1]) + p[job_in_perm][mach]
        return perm

    # Iterated Greedy with destruction size 3
    def iterated_greedy(initial_perm, max_iters=50):
        current = initial_perm[:]
        best = current[:]
        best_ms = makespan(best)
        total_processing = sum(total)
        T_param = 0.5
        T = T_param * total_processing / (10 * n * m)

        for _ in range(max_iters):
            # Destruction: remove d=3 jobs at random positions
            if n <= 3:
                destroyed = []
                remaining = []
            else:
                positions = random.sample(range(n), 3)
                positions.sort(reverse=True)
                destroyed = [current[pos] for pos in positions]
                remaining = current[:]
                for pos in positions:
                    remaining.pop(pos)
            # Reconstruction: reinsert destroyed jobs one by one using NEH insertion
            # Sort destroyed jobs by total processing time descending for deterministic reinsertion
            destroyed_sorted = sorted(destroyed, key=lambda i: -total[i])
            seq = remaining[:]
            for job in destroyed_sorted:
                k = len(seq)
                # Compute forward matrix e for seq
                e = [0] * m
                for j in seq:
                    for mach in range(m):
                        if mach == 0:
                            e[mach] += p[j][mach]
                        else:
                            e[mach] = max(e[mach], e[mach-1]) + p[j][mach]
                # Compute backward tail matrix q for seq
                q = [[0] * m for _ in range(k+1)]
                for mach in range(m):
                    q[k][mach] = 0
                for r in range(k-1, -1, -1):
                    job_r = seq[r]
                    for mach in range(m-1, -1, -1):
                        if mach == m-1:
                            q[r][mach] = q[r+1][mach] + p[job_r][mach]
                        else:
                            q[r][mach] = max(q[r+1][mach], q[r][mach+1]) + p[job_r][mach]
                # Find best position to insert job
                best_pos = 0
                best_ms_insert = float('inf')
                for pos in range(k+1):
                    f = [0] * m
                    if pos == 0:
                        prev_e = [0] * m
                    else:
                        prev_e = e[pos-1]
                    for mach in range(m):
                        if mach == 0:
                            f[mach] = prev_e[mach] + p[job][mach]
                        else:
                            f[mach] = max(f[mach-1], prev_e[mach]) + p[job][mach]
                    ms_val = 0
                    for mach in range(m):
                        val = f[mach] + q[pos][mach]
                        if val > ms_val:
                            ms_val = val
                    if ms_val < best_ms_insert:
                        best_ms_insert = ms_val
                        best_pos = pos
                seq.insert(best_pos, job)
            # New candidate sequence
            candidate = seq
            candidate_ms = makespan(candidate)
            # Acceptance criterion
            if candidate_ms < makespan(current):
                current = candidate[:]
                if candidate_ms < best_ms:
                    best = candidate[:]
                    best_ms = candidate_ms
            else:
                if random.random() < math.exp(-(candidate_ms - makespan(current)) / T):
                    current = candidate[:]
        return best

    # Build initial solution using NEH
    initial_perm = neh_construction(order)
    # Apply iterated greedy refinement
    refined_perm = iterated_greedy(initial_perm, max_iters=40)
    return refined_perm

