def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for sorting
    total_times = [sum(job) for job in times]
    # Sort jobs by total processing time descending (NEH priority)
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Current permutation (as a list of job indices)
    pi = [order[0], order[1]] if times[order[0]][0] + times[order[0]][1] <= times[order[1]][0] + times[order[1]][1] else [order[1], order[0]]

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in N]  # forward completion
    q = [[0] * M for _ in (N + 1)]  # backward tail (size N+1 for safety)

    # Helper: compute makespan of a given permutation (used for initial pair and fallback)
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Main NEH loop with Taillard acceleration
    for k in range(2, N):
        job_idx = order[k]
        p_job = times[job_idx]

        # Compute forward completion matrix e[0..k-1][0..M-1] for current pi[0..k-1]
        for r in range(k):
            job_r = pi[r]
            p_r = times[job_r]
            if r == 0:
                e[0][0] = p_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p_r[m]
            else:
                e[r][0] = e[r-1][0] + p_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p_r[m]

        # Compute backward tail matrix q[0..k][0..M-1]; q[k][*] = 0
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = pi[r]
            p_r = times[job_r]
            q[r][M-1] = q[r+1][M-1] + p_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p_r[m]

        # Find best insertion position for job_idx
        best_pos = 0
        best_mk = float('inf')
        e_im1 = [0] * M  # e[i-1][*] for current i

        for i in range(k+1):
            # Compute forward vector f for inserting job_idx at position i
            f = [0] * M
            if i == 0:
                # e[-1][m] = 0
                f[0] = p_job[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], 0) + p_job[m]
            else:
                # e[i-1] is already computed in e_im1 from previous iteration
                f[0] = e_im1[0] + p_job[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e_im1[m]) + p_job[m]

            # Compute makespan candidate: max_m (f[m] + q[i][m])
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i

            # Update e_im1 for next i: if i < k, then e_im1 becomes e[i][*]
            if i < k:
                e_im1 = e[i][:]  # copy current e[i] for next i

        # Insert job_idx at best_pos
        pi.insert(best_pos, job_idx)

    return pi

