    total_times = [sum(job) for job in times]
    slope_indices = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_time[m]
        return t[-1]

    # Taillard's forward completion matrix for a given permutation
    def compute_forward(perm):
        e = [[0] * M for _ in range(len(perm))]
        for r, job in enumerate(perm):
            job_time = times[job]
            if r == 0:
                e[0][0] = job_time[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_time[m]
            else:
                e[r][0] = e[r-1][0] + job_time[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_time[m]
        return e

    # Taillard's backward tail matrix for a given permutation
    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            job_time = times[job]
            q[r][M-1] = q[r+1][M-1] + job_time[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_time[m]
        return q

    # NEH construction with Taillard acceleration
    def construct_initial():
        order = sorted(range(N), key=lambda i: (-total_times[i], -slope_indices[i], i))
        if N == 1:
            return order[:]
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        for k in range(2, N):
            job = order[k]
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                f = [0] * M
                if i == 0:
                    f[0] = times[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + times[job][m]
                else:
                    f[0] = e[i-1][0] + times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + times[job][m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size d=3
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        current_mk = makespan(current)
        best_seq = current[:]
        best_mk = current_mk
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

        for _ in range(max_iter):
            # Destruction: remove 3 random jobs
            indices = random.sample(range(N), 3)
            removed = [current[i] for i in sorted(indices, reverse=True)]
            for idx in sorted(indices, reverse=True):
                del current[idx]
            # Reconstruction: reinsert using NEH-like insertion with Taillard
            for job in removed:
                e = compute_forward(current)
                q = compute_backward(current)
                best_pos = 0
                best_mk = float('inf')
                for i in range(len(current)+1):
                    f = [0] * M
                    if i == 0:
                        f[0] = times[job][0]
                        for m in range(1, M):
                            f[m] = f[m-1] + times[job][m]
                    else:
                        f[0] = e[i-1][0] + times[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + times[job][m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk:
                        best_mk = mk
                        best_pos = i
                current.insert(best_pos, job)
            new_mk = makespan(current)
            # Acceptance criterion
            if new_mk < current_mk:
                current = current[:]
                current_mk = new_mk
                if new_mk < best_mk:
                    best_seq = current[:]
                    best_mk = new_mk
            elif new_mk < best_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
                current = current[:]
                current_mk = new_mk
        return best_seq

    initial_seq = construct_initial()
    return iterated_greedy(initial_seq)

