    def makespan(perm):
        t = [0] * M
        for job in perm:
            pj = proc[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + pj[m]
        return t[-1]

    # NEH with Taillard acceleration
    def neh_taillard():
        order = sorted(range(N), key=lambda i: total_proc[i], reverse=True)
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        # Initial two jobs
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        seq = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        # Iteratively insert remaining jobs
        for k in range(2, N):
            job = order[k]
            k_len = len(seq)
            # Forward matrix e: completion times of current seq
            e = [[0]*M for _ in range(k_len)]
            for r in range(k_len):
                pj = proc[seq[r]]
                if r == 0:
                    e[0][0] = pj[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + pj[m]
                else:
                    e[r][0] = e[r-1][0] + pj[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
            # Backward matrix q: tail times
            q = [[0]*M for _ in range(k_len+1)]  # q[k_len][*] = 0
            for r in range(k_len-1, -1, -1):
                pj = proc[seq[r]]
                if r == k_len-1:
                    for m in range(M-1, -1, -1):
                        if m == M-1:
                            q[r][m] = pj[m]
                        else:
                            q[r][m] = q[r][m+1] + pj[m]
