                        q[r][M-1] = q[r+1][M-1] + pj[M-1]
                        for m in range(M-2, -1, -1):
                            q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
                # Evaluate insertion positions for job
                best_pos = 0
                best_cmax_local = float('inf')
                for i in range(k_len+1):
                    f = [0]*M
                    if i == 0:
                        prev_e = [0]*M
                    else:
                        prev_e = e[i-1]
                    pj = proc[job]
                    f[0] = prev_e[0] + pj[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev_e[m]) + pj[m]
                    cmax_candidate = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > cmax_candidate:
                            cmax_candidate = val
                    if cmax_candidate < best_cmax_local:
                        best_cmax_local = cmax_candidate
                        best_pos = i
                remaining.insert(best_pos, job)
            # New sequence after reconstruction
            new_seq = remaining
            new_cmax = makespan(new_seq)
            # Acceptance criterion
            if new_cmax < makespan(current):
                current = new_seq
                if new_cmax < best_cmax:
                    best = new_seq[:]
                    best_cmax = new_cmax
            else:
                if random.random() < math.exp(-(new_cmax - makespan(current)) / T):
                    current = new_seq
        return best

    # Build initial solution and refine
    init_seq = neh_taillard()
    return iterated_greedy(init_seq, max_iter=50)

