            for m in range(M):
                if m == 0:
                    e_curr[m] = e_prev[m] + t[m]
                else:
                    e_curr[m] = max(e_prev[m], e_curr[m-1]) + t[m]
            e_prev = e_curr
        return e_prev[-1]

    def makespan_after_insert(perm, pos, job, e_forward, q_backward):
