            else:
                f_curr[m] = max(f_prev[m], f_curr[m-1]) + t[m]
        makespan_val = 0
        for m in range(M):
            val = f_curr[m] + q_backward[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    schedule = [order[0]]
    for k in range(1, N):
        job = order[k]
        e_forward = [[0]*M for _ in range(k)]
        if k > 0:
            job0 = schedule[0]
            t0 = times[job0]
            e_forward[0][0] = t0[0]
            for m in range(1, M):
