                    t_r = times[job_r]
                    e_forward[r][0] = e_forward[r-1][0] + t_r[0]
                    for m in range(1, M):
                        e_forward[r][m] = max(e_forward[r-1][m], e_forward[r][m-1]) + t_r[m]
            q_backward = [[0]*M for _ in range(len(remaining)+1)]
            for m in range(M):
                q_backward[len(remaining)][m] = 0
            for r in range(len(remaining)-1, -1, -1):
                job_r = remaining[r]
                t_r = times[job_r]
                q_backward[r][M-1] = q_backward[r+1][M-1] + t_r[M-1]
                for m in range(M-2, -1, -1):
                    q_backward[r][m] = max(q_backward[r+1][m], q_backward[r][m+1]) + t_r[m]
            for pos in range(len(remaining)+1):
                if pos == 0:
                    f_prev = [0] * M
                else:
                    f_prev = e_forward[pos-1]
                t = times[job]
                f_curr = [0] * M
                for m in range(M):
                    if m == 0:
                        f_curr[m] = f_prev[m] + t[m]
                    else:
                        f_curr[m] = max(f_prev[m], f_curr[m-1]) + t[m]
                makespan_val = 0
                for m in range(M):
                    val = f_curr[m] + q_backward[pos][m]
                    if val > makespan_val:
                        makespan_val = val
                if makespan_val < best_makespan:
                    best_makespan = makespan_val
                    best_pos = pos
            remaining.insert(best_pos, job)
        return remaining

    current = schedule[:]
    best = schedule[:]
    best_makespan = makespan(best)
    avg_p = sum(total_processing) / (N * M)
    T = 0.5 * avg_p
    max_iter = 60
    for _ in range(max_iter):
        d = 3 if N > 20 else 2
        candidate = destroy_and_reconstruct(current, d)
        candidate_makespan = makespan(candidate)
        if candidate_makespan < makespan(current):
            current = candidate[:]
            if candidate_makespan < best_makespan:
                best = candidate[:]
                best_makespan = candidate_makespan
        else:
            if random.random() < math.exp(-(candidate_makespan - makespan(current)) / T):
                current = candidate[:]
    return best

import math
