def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flatten times for faster access
    flat_times = [0] * (N * M)
    for i in range(N):
        base = i * M
        for j in range(M):
            flat_times[base + j] = times[i][j]

    def get_time(i, j):
        return flat_times[i * M + j]

    # Precompute total processing times per job
    total_time = [0] * N
    for i in range(N):
        base = i * M
        s = 0
        for j in range(M):
            s += flat_times[base + j]
        total_time[i] = s

    # Makespan evaluation with Taillard acceleration for a given sequence
    def makespan_with_tail(seq):
        k = len(seq)
        if k == 0:
            return 0
        # Forward matrix e: completion times of current sequence
        e = [[0] * M for _ in range(k)]
        # First job
        e[0][0] = get_time(seq[0], 0)
        for m in range(1, M):
            e[0][m] = e[0][m-1] + get_time(seq[0], m)
        # Remaining jobs
        for r in range(1, k):
            job = seq[r]
            e[r][0] = e[r-1][0] + get_time(job, 0)
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + get_time(job, m)
        # Backward tail matrix q
        q = [[0] * M for _ in range(k+1)]
        # Initialize q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = seq[r]
            q[r][M-1] = q[r+1][M-1] + get_time(job, M-1)
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + get_time(job, m)
        # Evaluate insertion makespan for all positions using forward vectors
        best_cmax = float('inf')
        for i in range(k+1):
            # Compute forward vector f for insertion at position i
            f = [0] * M
            if i == 0:
                # No predecessors
                f[0] = get_time(0, 0)  # dummy, will be overwritten
                # Actually, we compute per job in loop below
                pass
            # We'll compute f per candidate job in the insertion loop
            # But here we need to evaluate for a dummy job? No, we need to evaluate for a specific job.
            # This function is for a fixed sequence, so we don't need insertion evaluation here.
            # Actually, we only need the makespan of the sequence itself.
            # So we can just return e[k-1][M-1]
            pass
        return e[k-1][M-1]

    # Actually, we don't need the full tail for makespan of the sequence, just the forward pass.
    # Let's simplify: makespan is e[k-1][M-1] from forward pass.
    def makespan(seq):
        if not seq:
            return 0
        e_prev = [0] * M
        for idx in seq:
            e_curr = [0] * M
            e_curr[0] = e_prev[0] + get_time(idx, 0)
            for m in range(1, M):
                e_curr[m] = max(e_curr[m-1], e_prev[m]) + get_time(idx, m)
            e_prev = e_curr
        return e_prev[M-1]

    # NEH construction with Taillard acceleration for insertion evaluation
    def neh_construction():
        # Job order by total processing time descending
        order = sorted(range(N), key=lambda i: total_time[i], reverse=True)
        # Start with first two jobs
        if N == 1:
            return [order[0]]
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_cmax = float('inf')
            # Evaluate all insertion positions using Taillard's O(k*M) method
            # Build forward matrix e for current seq of length k
            e = [[0] * M for _ in range(k)]
            if k > 0:
                e[0][0] = get_time(seq[0], 0)
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + get_time(seq[0], m)
                for r in range(1, k):
                    ejob = seq[r]
                    e[r][0] = e[r-1][0] + get_time(ejob, 0)
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + get_time(ejob, m)
            # Build backward tail matrix q for current seq
            q = [[0] * M for _ in range(k+1)]
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                ejob = seq[r]
                q[r][M-1] = q[r+1][M-1] + get_time(ejob, M-1)
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + get_time(ejob, m)
            # Now evaluate inserting job at each position i in [0, k]
            for i in range(k+1):
                # Compute forward vector f for job at position i
                f = [0] * M
                if i == 0:
                    # No predecessors, so e[i-1][m] = 0 for all m
                    f[0] = get_time(job, 0)
                    for m in range(1, M):
                        f[m] = max(f[m-1], 0) + get_time(job, m)
                else:
                    # Use e[i-1] as the forward state
                    f[0] = e[i-1][0] + get_time(job, 0)
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + get_time(job, m)
                # Compute makespan if job inserted at i: max_m (f[m] + q[i][m])
                cmax_i = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax_i:
                        cmax_i = val
                if cmax_i < best_cmax:
                    best_cmax = cmax_i
                    best_pos = i
            # Insert job at best_pos
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size d=3
    def iterated_greedy(initial_seq, max_iter=50):
        current_seq = initial_seq[:]
        best_seq = initial_seq[:]
        best_cmax = makespan(best_seq)
        total_processing = sum(total_time)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3  # destruction size
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            if N <= d:
                destroyed = []
                remaining = []
            else:
                positions = random.sample(range(N), d)
                positions.sort(reverse=True)
                destroyed = [current_seq[pos] for pos in positions]
                remaining = current_seq[:]
                for pos in positions:
                    remaining.pop(pos)
            # Reconstruction: reinsert destroyed jobs one by one using NEH insertion (with Taillard)
            for job in destroyed:
                k = len(remaining)
                if k == 0:
                    remaining = [job]
                    continue
                # Build forward matrix e for remaining
                e = [[0] * M for _ in range(k)]
                if k > 0:
                    e[0][0] = get_time(remaining[0], 0)
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + get_time(remaining[0], m)
                    for r in range(1, k):
                        ejob = remaining[r]
                        e[r][0] = e[r-1][0] + get_time(ejob, 0)
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + get_time(ejob, m)
                # Build backward tail matrix q for remaining
                q = [[0] * M for _ in range(k+1)]
                for m in range(M):
                    q[k][m] = 0
                for r in range(k-1, -1, -1):
                    ejob = remaining[r]
                    q[r][M-1] = q[r+1][M-1] + get_time(ejob, M-1)
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + get_time(ejob, m)
                # Find best position to insert job
                best_pos = 0
                best_cmax = float('inf')
                for i in range(k+1):
                    # Forward vector f for job at position i
                    f = [0] * M
                    if i == 0:
                        f[0] = get_time(job, 0)
                        for m in range(1, M):
                            f[m] = max(f[m-1], 0) + get_time(job, m)
                    else:
                        f[0] = e[i-1][0] + get_time(job, 0)
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + get_time(job, m)
                    cmax_i = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > cmax_i:
                            cmax_i = val
                    if cmax_i < best_cmax:
                        best_cmax = cmax_i
                        best_pos = i
                remaining.insert(best_pos, job)
            new_seq = remaining
            new_cmax = makespan(new_seq)
            # Acceptance criterion
            if new_cmax < makespan(current_seq):
                current_seq = new_seq
                if new_cmax < best_cmax:
                    best_seq = new_seq
                    best_cmax = new_cmax
            else:
                if makespan(current_seq) > 0:
                    delta = new_cmax - makespan(current_seq)
                    prob = math.exp(-delta / T)
                    if random.random() < prob:
                        current_seq = new_seq
        return best_seq

    # Get initial solution via NEH
    init_seq = neh_construction()
    # Apply iterated greedy refinement
    refined_seq = iterated_greedy(init_seq, max_iter=40)
    return refined_seq

