    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for NEH priority
    total_times = [sum(job) for job in times]
    jobs_sorted = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Initialize makespan matrix for partial schedule (forward pass)
    e = [[0] * M for _ in range(N)]

    # Start with first job
    seq = [jobs_sorted[0]]
    job0 = jobs_sorted[0]
    e[0][0] = times[job0][0]
    for m in range(1, M):
        e[0][m] = e[0][m-1] + times[job0][m]

    # NEH construction with Taillard acceleration
    for k in range(1, N):
        job = jobs_sorted[k]
        p_job = times[job]

        # Compute forward matrix e for current sequence of length k
        for r in range(k):
            rj = seq[r]
            p_r = times[rj]
            if r == 0:
                e[r][0] = p_r[0]
            else:
                e[r][0] = e[r-1][0] + p_r[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + p_r[m]

