            f = [0] * M
            if i == 0:
                prev_e = [0] * M
            else:
                prev_e = e[i-1]
            f[0] = prev_e[0] + p_job[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev_e[m]) + p_job[m]

