            return 0
        t = [0] * M
        first = True
        for job in s:
            p_job = times[job]
            if first:
                t[0] = p_job[0]
                for m in range(1, M):
                    t[m] = t[m-1] + p_job[m]
                first = False
            else:
                t[0] += p_job[0]
                for m in range(1, M):
                    t[m] = max(t[m-1], t[m]) + p_job[m]
        return t[M-1]

    current_makespan = compute_makespan(current_seq)
    best_seq = current_seq[:]
    best_makespan = current_makespan

    # IG parameters
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
