            e_curr = [[0] * M for _ in range(max(k, 1))]
            if k > 0:
                for r in range(k):
                    rj = current_seq[r]
                    p_r = times[rj]
                    if r == 0:
                        e_curr[r][0] = p_r[0]
                    else:
