                    if val > makespan:
                        makespan = val
                if makespan < best_makespan_local:
                    best_makespan_local = makespan
                    best_pos = i

            current_seq.insert(best_pos, job)

        # Compute makespan of new sequence
        new_makespan = compute_makespan(current_seq)

        # Acceptance criterion
        if new_makespan < current_makespan:
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_makespan = new_makespan
                best_seq = current_seq[:]
        elif new_makespan < best_makespan or random.random() < math.exp(-(new_makespan - current_makespan) / T):
            current_seq = current_seq[:]
