    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Precompute total processing times for NEH priority
    total_times = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Initialize with first two jobs
    if N == 2:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        return seq1 if makespan(seq1) <= makespan(seq2) else seq2

    # Start with first two jobs in best order
    seq = [order[0], order[1]]
    if makespan([order[1], order[0]]) < makespan(seq):
        seq = [order[1], order[0]]

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N+1)]

    def compute_forward(schedule, length):
        if length == 0:
            for m in range(M):
                e[-1][m] = 0  # handled via condition in function
            return
        for m in range(M):
            if m == 0:
                e[0][m] = times[schedule[0]][m]
            else:
                e[0][m] = e[0][m-1] + times[schedule[0]][m]
        for r in range(1, length):
            job_idx = schedule[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = e[r-1][m] + times[job_idx][m]
                else:
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job_idx][m]

    def compute_backward(schedule, length):
        for m in range(M):
            q[length][m] = 0
        for r in range(length-1, -1, -1):
            job_idx = schedule[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job_idx][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_idx][m]

    # NEH construction with Taillard acceleration
    for k in range(2, N):
        job_idx = order[k]
        compute_forward(seq, k)
        compute_backward(seq, k)
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            # Compute forward vector f for inserting job_idx at position i
            f = [0] * M
            if i == 0:
                prev = [0] * M
            else:
                prev = e[i-1]
            for m in range(M):
                if m == 0:
                    f[m] = prev[0] + times[job_idx][m]
                else:
                    f[m] = max(f[m-1], prev[m]) + times[job_idx][m]
            # Compute makespan candidate: max_m (f[m] + q[i][m])
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        seq.insert(best_pos, job_idx)

    current = seq[:]
    best = seq[:]
    best_mk = makespan(best)

    # Iterated Greedy parameters
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 5 else N
    max_iter = 50
    iter_count = 0
    no_improve = 0
    max_no_improve = 10

    while iter_count < max_iter and no_improve < max_no_improve:
        # Destruction: remove d random jobs
        indices = list(range(N))
        random.shuffle(indices)
        removed_indices = indices[:d]
        removed_indices.sort(reverse=True)
        removed_jobs = []
        for idx in removed_indices:
            removed_jobs.append(current.pop(idx))
        # Reconstruction: reinsert using NEH insertion with Taillard
        for job in removed_jobs:
            k = len(current)
            compute_forward(current, k)
            compute_backward(current, k)
            best_pos = 0
            best_mk_ins = float('inf')
            for i in range(k+1):
                f = [0] * M
                if i == 0:
                    prev = [0] * M
                else:
                    prev = e[i-1]
                for m in range(M):
                    if m == 0:
                        f[m] = prev[0] + times[job][m]
                    else:
                        f[m] = max(f[m-1], prev[m]) + times[job][m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk_ins:
                    best_mk_ins = mk
                    best_pos = i
            current.insert(best_pos, job)
        # Evaluate new solution
        new_mk = makespan(current)
        # Acceptance criterion
        if new_mk < makespan(seq):
            seq = current[:]
            if new_mk < best_mk:
                best = current[:]
                best_mk = new_mk
                no_improve = 0
            else:
                no_improve += 1
        else:
            delta = new_mk - makespan(seq)
            if random.random() < math.exp(-delta / T):
                seq = current[:]
            no_improve += 1
        current = seq[:]
        iter_count += 1

    return best

