def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    def compute_e_matrix(seq, k):
        e = [[0] * M for _ in range(k)]
        if k == 0:
            return e
        job0 = seq[0]
        job0_t = times[job0]
        e[0][0] = job0_t[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0_t[m]
        for r in range(1, k):
            job_r = seq[r]
            job_rt = times[job_r]
            e[r][0] = e[r-1][0] + job_rt[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job_rt[m]
        return e

    def compute_q_matrix(seq, k):
        q = [[0] * M for _ in range(k+1)]
        if k == 0:
            return q
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = seq[r]
            job_rt = times[job_r]
            q[r][M-1] = q[r+1][M-1] + job_rt[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_rt[m]
        return q

    def insert_with_tail(seq, job, e_prev, q_prev):
        k = len(seq)
        if k == 0:
            return [job], job_t[0] if (job_t := times[job]) else 0
        best_pos = 0
        best_mk = float('inf')
        job_t = times[job]
        for i in range(k+1):
            if i == 0:
                f0 = job_t[0]
            else:
                f0 = e_prev[i-1][0] + job_t[0]
            f = [f0]
            for m in range(1, M):
                em = e_prev[i-1][m] if i-1 >= 0 else 0
                f.append(max(f[m-1], em) + job_t[m])
            mk = 0
            for m in range(M):
                val = f[m] + q_prev[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        new_seq = seq[:best_pos] + [job] + seq[best_pos:]
        return new_seq, best_mk

    P = [sum(job) for job in times]
    S = [sum((2*j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]
    penalty = [times[i][0] * M for i in range(N)]
    modified_P = [P[i] - penalty[i] for i in range(N)]

    order1 = sorted(range(N), key=lambda i: (-modified_P[i], i))
    order2 = sorted(range(N), key=lambda i: (-S[i], i))
    order3 = sorted(range(N), key=lambda i: (-P[i], i))

    def construct_neh(order):
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        seq = [order[0], order[1]]
        rev_seq = [order[1], order[0]]
        if makespan(rev_seq) < makespan(seq):
            seq = rev_seq
        for k in range(2, N):
            job = order[k]
            e_mat = compute_e_matrix(seq, k)
            q_mat = compute_q_matrix(seq, k)
            seq, _ = insert_with_tail(seq, job, e_mat, q_mat)
        return seq

    best_seq = None
    best_mk = float('inf')
    for order in [order1, order2, order3]:
        seq = construct_neh(order)
        mk = makespan(seq)
        if mk < best_mk:
            best_mk = mk
            best_seq = seq

    def destroy_and_reconstruct(seq, d):
        if d <= 0 or d >= len(seq):
            return seq
        indices = random.sample(range(len(seq)), d)
        indices_set = set(indices)
        R = [seq[i] for i in indices]
        pi_D = [seq[i] for i in range(len(seq)) if i not in indices_set]
        random.shuffle(R)
        for job in R:
            e_mat = compute_e_matrix(pi_D, len(pi_D))
            q_mat = compute_q_matrix(pi_D, len(pi_D))
            pi_D, _ = insert_with_tail(pi_D, job, e_mat, q_mat)
        return pi_D

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    current_seq = best_seq[:]
    current_mk = best_mk
    T_min = 1e-6
    alpha = 0.95
    max_iter = 80
    iter_count = 0

    while iter_count < max_iter and T > T_min:
        d = 3 if N < 60 else 4
        new_seq = destroy_and_reconstruct(current_seq, d)
        new_mk = makespan(new_seq)
        if new_mk < current_mk:
            current_seq = new_seq
            current_mk = new_mk
            if new_mk < best_mk:
                best_seq = new_seq[:]
                best_mk = new_mk
        else:
            if random.random() < math.exp(-(new_mk - current_mk) / T):
                current_seq = new_seq
                current_mk = new_mk
        T *= alpha
        iter_count += 1

    return best_seq

