                    best_pos_rec = 0
                    best_makespan_rec = float('inf')
                    for i in range(k+1):
                        f = [0] * M
                        if i == 0:
                            f[0] = pj[0]
                            for m in range(1, M):
                                f[m] = max(f[m-1], 0) + pj[m]
                        else:
                            prev_e = e_rec[i-1]
                            f[0] = prev_e[0] + pj[0]
                            for m in range(1, M):
                                f[m] = max(f[m-1], prev_e[m]) + pj[m]

                        makespan_val = 0
                        qi = q_rec[i]
                        for m in range(M):
                            val = f[m] + qi[m]
                            if val > makespan_val:
                                makespan_val = val

                        if makespan_val < best_makespan_rec:
                            best_makespan_rec = makespan_val
                            best_pos_rec = i

                    perm_rec.insert(best_pos_rec, job_idx)

                # Now insert destroyed_sorted jobs one by one
                for job_idx in destroyed_sorted:
                    pj = job_data[job_idx]
                    k = len(perm_rec)

                    # Recompute e and q for current perm_rec
                    e_rec = [[0] * M for _ in range(k)]
                    q_rec = [[0] * M for _ in range(k+1)]

                    # Forward
                    for r in range(k):
                        job_r = perm_rec[r]
                        pr = job_data[job_r]
                        if r == 0:
                            e_rec[0][0] = pr[0]
                            for m in range(1, M):
                                e_rec[0][m] = e_rec[0][m-1] + pr[m]
                        else:
                            e_rec[r][0] = e_rec[r-1][0] + pr[0]
                            for m in range(1, M):
                                e_rec[r][m] = max(e_rec[r-1][m], e_rec[r][m-1]) + pr[m]

                    # Backward
                    for m in range(M):
                        q_rec[k][m] = 0
                    for r in range(k-1, -1, -1):
                        job_r = perm_rec[r]
                        pr = job_data[job_r]
                        q_rec[r][M-1] = q_rec[r+1][M-1] + pr[M-1]
                        for m in range(M-2, -1, -1):
                            q_rec[r][m] = max(q_rec[r+1][m], q_rec[r][m+1]) + pr[m]

                    # Evaluate insertion positions
                    best_pos_ins = 0
                    best_makespan_ins = float('inf')
                    for i in range(k+1):
                        f = [0] * M
                        if i == 0:
                            f[0] = pj[0]
