                            for m in range(1, M):
                                f[m] = max(f[m-1], prev_e[m]) + pj[m]

                        makespan_val = 0
                        qi = q_rec[i]
                        for m in range(M):
                            val = f[m] + qi[m]
                            if val > makespan_val:
                                makespan_val = val

                        if makespan_val < best_makespan_ins:
                            best_makespan_ins = makespan_val
                            best_pos_ins = i

                    perm_rec.insert(best_pos_ins, job_idx)

            new_perm = perm_rec

        # Compute makespan of new solution
        new_makespan = compute_makespan(new_perm)

        # Acceptance criterion
        if new_makespan < compute_makespan(current_perm):
            current_perm = new_perm[:]
            if new_makespan < best_makespan:
                best_makespan = new_makespan
                best_perm = new_perm[:]
        elif new_makespan < best_makespan:
            # Accept with probability if better than current but not best
            # Simplified: always accept if better than current, occasional uphill
            if random.random() < math.exp(-(new_makespan - compute_makespan(current_perm)) / T):
                current_perm = new_perm[:]
        else:
            # Uphill move with probability
            if random.random() < math.exp(-(new_makespan - compute_makespan(current_perm)) / T):
                current_perm = new_perm[:]

    return best_perm

