import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]

    # Slope index for tie-breaking and alternative ordering
    slope = [sum((2 * j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]

    # Makespan evaluation with Taillard acceleration for a given sequence
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[M-1]

    # NEH construction with Taillard acceleration
    def construct_neh():
        # Sort by total processing time descending, break ties by slope descending
        order = sorted(range(N), key=lambda i: (-total_p[i], -slope[i]))
        if N == 0:
            return []
        # Start with first job
        seq = [order[0]]
        if N == 1:
            return seq
        # Evaluate first two jobs in both orders
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        # Iteratively insert remaining jobs
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_mk = float('inf')
            # Forward matrix e: completion times of current seq[0:k]
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = seq[r]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job_r][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job_r][m]
            # Backward matrix q: tail times from position r to end of seq[0:k]
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + p[job_r][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
            # Test insertion at each position i in [0, k]
            for i in range(k+1):
                # Forward pass for job at position i
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev = e[i-1][m] if i > 0 else 0
                        f[m] = prev + p[job][m]
                    else:
                        prev = e[i-1][m] if i > 0 else 0
                        f[m] = max(f[m-1], prev) + p[job][m]
                # Compute makespan if job inserted at i
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(init_seq, max_iters=60):
        current = init_seq[:]
        best = init_seq[:]
        best_mk = makespan(best)
        total = sum(total_p)
        T_param = 0.5
        T = T_param * total / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 5 else 2

        for _ in range(max_iters):
            # Destruction: remove d random jobs
            if d >= N:
                destroyed = []
                removed = current[:]
            else:
                indices = random.sample(range(N), d)
                indices.sort(reverse=True)
                removed = [current.pop(i) for i in indices]
                destroyed = current
            # Reconstruction: reinsert removed jobs one by one using NEH insertion with Taillard
            for job in removed:
                best_pos = 0
                best_mk_ins = float('inf')
                k = len(destroyed)
                # If destroyed is empty, just place the job
                if k == 0:
                    destroyed.append(job)
                    continue
                # Forward matrix e for destroyed sequence
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    job_r = destroyed[r]
                    for m in range(M):
                        if m == 0:
                            e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job_r][m]
                        else:
                            e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job_r][m]
                # Backward matrix q for destroyed sequence
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = destroyed[r]
                    for m in range(M-1, -1, -1):
                        if m == M-1:
                            q[r][m] = q[r+1][m] + p[job_r][m]
                        else:
                            q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
                # Test insertion at each position i in [0, k]
                for i in range(k+1):
                    f = [0] * M
                    for m in range(M):
                        if m == 0:
                            prev = e[i-1][m] if i > 0 else 0
                            f[m] = prev + p[job][m]
                        else:
                            prev = e[i-1][m] if i > 0 else 0
                            f[m] = max(f[m-1], prev) + p[job][m]
                    mk_ins = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk_ins:
                            mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                destroyed.insert(best_pos, job)
            # New candidate sequence
            candidate = destroyed[:]
            mk_candidate = makespan(candidate)
            # Acceptance criterion
            if mk_candidate < makespan(current):
                current = candidate[:]
                if mk_candidate < best_mk:
                    best = candidate[:]
                    best_mk = mk_candidate
            else:
                if random.random() < math.exp(-(mk_candidate - makespan(current)) / T):
                    current = candidate[:]
        return best

    # Build initial solution with NEH
    init_seq = construct_neh()
    # Refine with Iterated Greedy
    return iterated_greedy(init_seq, max_iters=50)

