def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[-1]

    P = [sum(job) for job in times]
    jobs_sorted = sorted(range(N), key=lambda i: P[i], reverse=True)

    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N+1)]

    def compute_forward(perm, length):
        for r in range(length):
            job = perm[r]
            job_t = times[job]
            if r == 0:
                e[0][0] = job_t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_t[m]
            else:
                e[r][0] = e[r-1][0] + job_t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]

    def compute_backward(perm, length):
        for m in range(M):
            q[length][m] = 0
        for r in range(length-1, -1, -1):
            job = perm[r]
            job_t = times[job]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]

    perm = [jobs_sorted[0], jobs_sorted[1]]
    makespan1 = makespan(perm)
    perm_swap = [jobs_sorted[1], jobs_sorted[0]]
    makespan2 = makespan(perm_swap)
    if makespan2 < makespan1:
        perm = perm_swap

    for k in range(2, N):
        job = jobs_sorted[k]
        job_t = times[job]
        compute_forward(perm, k)
        compute_backward(perm, k)
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = job_t[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], 0) + job_t[m])
            else:
                f0 = e[i-1][0] + job_t[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], e[i-1][m]) + job_t[m])
            makespan_i = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_i:
                    makespan_i = val
            if makespan_i < best_makespan:
                best_makespan = makespan_i
                best_pos = i
        perm.insert(best_pos, job)

    pi = perm[:]
    pi_best = pi[:]
    best_makespan = makespan(pi)
    current_makespan = best_makespan
    max_iters = 60

    for _ in range(max_iters):
        d = 3 if N > 5 else N
        if d <= 0:
            break
        indices = random.sample(range(N), d)
        indices.sort(reverse=True)
        removed = []
        for idx in indices:
            removed.append(pi.pop(idx))
        destroyed = pi[:]
        L = len(destroyed)
        if L > 0:
            compute_forward(destroyed, L)
            compute_backward(destroyed, L)
        for job in removed:
            job_t = times[job]
            best_pos = 0
            best_m = float('inf')
            for i in range(L+1):
                if i == 0:
                    f0 = job_t[0]
                    f = [f0]
                    for m in range(1, M):
                        f.append(max(f[m-1], 0) + job_t[m])
                else:
                    f0 = e[i-1][0] + job_t[0]
                    f = [f0]
                    for m in range(1, M):
                        f.append(max(f[m-1], e[i-1][m]) + job_t[m])
                m_val = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > m_val:
                        m_val = val
                if m_val < best_m:
                    best_m = m_val
                    best_pos = i
            pi.insert(best_pos, job)
            L += 1
        new_makespan = makespan(pi)
        if new_makespan < current_makespan:
            pi = pi[:]
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                pi_best = pi[:]
                best_makespan = new_makespan
        elif new_makespan < best_makespan:
            pi_best = pi[:]
            best_makespan = new_makespan
        else:
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                pi = pi[:]
                current_makespan = new_makespan
    return pi_best

