        row = times[i]
        for j in range(M):
            s += row[j]
        P[i] = s
        total_processing += s

    sigma = list(range(N))
    sigma.sort(key=lambda i: P[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            row = times[job]
            t[0] += row[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + row[m]
        return t[-1]

    def makespan_taillard(seq):
        if not seq:
            return 0
        e = [0] * M
        for job in seq:
            row = times[job]
            e[0] += row[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + row[m]
        return e[-1]

    def makespan_taillard_insert(seq, x, i):
        k = len(seq)
        if i == 0:
            f0 = times[x][0]
            f = [0] * M
            f[0] = f0
            for m in range(1, M):
                f[m] = max(f[m-1], 0) + times[x][m]
            q = [0] * M
            for r in range(k-1, -1, -1):
