                row = times[job]
                q[M-1] += row[M-1]
                for m in range(M-2, -1, -1):
                    q[m] = max(q[m+1], q[m]) + row[m]
            best = 0
            for m in range(M):
                val = f[m] + q[m]
                if val > best:
                    best = val
            return best
        elif i == k:
            e = [0] * M
            for r in range(k):
                job = seq[r]
                row = times[job]
                e[0] += row[0]
                for m in range(1, M):
                    e[m] = max(e[m-1], e[m]) + row[m]
            f0 = e[0] + times[x][0]
            f = [0] * M
            f[0] = f0
            for m in range(1, M):
                f[m] = max(f[m-1], e[m]) + times[x][m]
            best = 0
            for m in range(M):
                val = f[m]
                if val > best:
                    best = val
            return best
        else:
            e = [0] * M
            for r in range(i):
                job = seq[r]
                row = times[job]
                e[0] += row[0]
                for m in range(1, M):
                    e[m] = max(e[m-1], e[m]) + row[m]
            f0 = e[0] + times[x][0]
