                best_pos = pos
        pi.insert(best_pos, job)

    pi_star = pi[:]
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N < 30 else 4
    max_iter = 60 if N < 60 else 40

    for _ in range(max_iter):
        indices = list(range(N))
        random.shuffle(indices)
        R_indices = indices[:d]
        R = [pi[i] for i in R_indices]
        pi_D = [pi[i] for i in range(N) if i not in set(R_indices)]
        random.shuffle(R)
        pi_new = pi_D[:]
        for job in R:
