            if makespan_taillard(pi_new) < makespan_taillard(pi_star):
                pi_star = pi_new[:]
        else:
            delta = makespan_taillard(pi_new) - makespan_taillard(pi)
            if random.random() < math.exp(-delta / T):
                pi = pi_new[:]

    return pi_star

