            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[0][m] = job[m]
                else:
                    q[0][m] = max(q[0][m+1], 0) + job[m]
            continue
        # compute q for current perm (length k)
        # q[k] = [0]*M already
        for r in range(k-1, -1, -1):
            job_r = times[perm[r]]
            q[r][M-1] = q[r+1][M-1] + job_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
        # evaluate insertion positions
        best_cmax = float('inf')
        best_pos = 0
        for i in range(k+1):
            # forward for job at i
            if i == 0:
                f = [0] * M
                f[0] = times[idx][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], 0) + times[idx][m]
            else:
                prev_e = e[i-1]
                f = [0] * M
                f[0] = prev_e[0] + times[idx][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + times[idx][m]
            # compute cmax = max_m (f[m] + q[i][m])
            cmax = 0
            tail = q[i]
            for m in range(M):
                val = f[m] + tail[m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        # insert idx at best_pos
        perm.insert(best_pos, idx)
        # recompute e for new perm (length k+1)
        for r in range(k+1):
            job_r = times[perm[r]]
            if r == 0:
                e[0][0] = job_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_r[m]
            else:
                prev_e = e[r-1]
                e[r][0] = prev_e[0] + job_r[0]
                for m in range(1, M):
                    e[r][m] = max(prev_e[m], e[r][m-1]) + job_r[m]

    # Iterated Greedy refinement
    def destroy_and_reconstruct(current_perm, d):
        if d > len(current_perm):
            d = len(current_perm)
        indices = random.sample(range(len(current_perm)), d)
        removed = [current_perm[i] for i in indices]
        # build destruction permutation without those indices
        remaining = [current_perm[i] for i in range(len(current_perm)) if i not in set(indices)]
        # reinsert each removed job using NEH insertion with Taillard
        for job_idx in removed:
            k = len(remaining)
            if k == 0:
                remaining.append(job_idx)
                continue
            # compute e for remaining
            e_rem = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = times[remaining[r]]
                if r == 0:
                    e_rem[0][0] = job_r[0]
                    for m in range(1, M):
                        e_rem[0][m] = e_rem[0][m-1] + job_r[m]
                else:
                    prev_e = e_rem[r-1]
                    e_rem[r][0] = prev_e[0] + job_r[0]
                    for m in range(1, M):
                        e_rem[r][m] = max(prev_e[m], e_rem[r][m-1]) + job_r[m]
            # compute q for remaining (size k, q[k] = zero)
            q_rem = [[0] * M for _ in range(k+1)]
            # q_rem[k] already zero
            for r in range(k-1, -1, -1):
                job_r = times[remaining[r]]
                q_rem[r][M-1] = q_rem[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    q_rem[r][m] = max(q_rem[r+1][m], q_rem[r][m+1]) + job_r[m]
            # evaluate insertion positions for job_idx
            best_cmax = float('inf')
            best_pos = 0
            job = times[job_idx]
            for i in range(k+1):
                if i == 0:
                    f = [0] * M
                    f[0] = job[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], 0) + job[m]
                else:
                    prev_e = e_rem[i-1]
                    f = [0] * M
                    f[0] = prev_e[0] + job[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev_e[m]) + job[m]
                cmax = 0
                tail = q_rem[i]
                for m in range(M):
                    val = f[m] + tail[m]
                    if val > cmax:
                        cmax = val
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = i
            remaining.insert(best_pos, job_idx)
        return remaining

    # IG parameters
    T_param = 0.5
    T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-6
    current = perm[:]
    best = current[:]
    best_cmax = makespan_from_perm(best)
    # Lower bound (Taillard)
    LB = 0
    for m in range(M):
        min_pre = min((sum(times[i][:m]) for i in range(N)), default=0)
        min_suf = min((sum(times[i][m+1:]) for i in range(N)), default=0)
        machine_sum = sum(times[i][m] for i in range(N))
        LB_m = min_pre + machine_sum + min_suf
        if LB_m > LB:
            LB = LB_m
    if best_cmax == LB:
        return best

    # IG loop: aim for ~40-60 iterations to stay within 50ms
    max_iter = 50
    for _ in range(max_iter):
        d = 3 if N > 20 else 2
        if N > 80:
            d = 4
        new_perm = destroy_and_reconstruct(current, d)
        new_cmax = makespan_from_perm(new_perm)
        if new_cmax < best_cmax:
            best_cmax = new_cmax
            best = new_perm[:]
        if new_cmax < makespan_from_perm(current):
            current = new_perm[:]
        else:
            if random.random() < math.exp(-(new_cmax - makespan_from_perm(current)) / T):
                current = new_perm[:]
        if best_cmax == LB:
            break

    return best

