def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T0 = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    def taillard_forward(partial):
        k = len(partial)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            pj = times[job]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    def taillard_backward(partial):
        k = len(partial)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            pj = times[job]
            if r == k-1:
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = pj[m]
                    else:
                        q[r][m] = q[r][m+1] + pj[m]
            else:
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    def insertion_cost(partial, job, pos, e, q):
        if pos == 0:
            f0 = times[job][0]
        else:
            f0 = e[pos-1][0] + times[job][0]
        f = [f0]
        for m in range(1, M):
            val = max(f[m-1], e[pos-1][m] if pos-1 >= 0 else 0) + times[job][m]
            f.append(val)
        makespan_val = 0
        for m in range(M):
            cand = f[m] + q[pos][m]
            if cand > makespan_val:
                makespan_val = cand
        return makespan_val

    def neh_taillard(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            seq1 = [order[0], order[1]]
            seq2 = [order[1], order[0]]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for k in range(2, len(order)):
            job = order[k]
            e = taillard_forward(seq)
            q = taillard_backward(seq)
            best_pos = 0
            best_cost = math.inf
            for pos in range(len(seq)+1):
                cost = insertion_cost(seq, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    P = [sum(job) for job in times]
    order_NEH = sorted(range(N), key=lambda i: (-P[i], i))
    S = [sum((2*j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]
    order_SLOPE = sorted(range(N), key=lambda i: (-S[i], i))
    initial_seq = neh_taillard(order_NEH)
    best_seq = initial_seq[:]
    best_makespan = makespan(initial_seq)
    if best_makespan == 0:
        return best_seq

    LB = 0
    for m in range(M):
        min_pre = min((sum(times[i][:m]) for i in range(N)), default=0)
        min_suf = min((sum(times[i][m+1:]) for i in range(N)), default=0)
        machine_sum = sum(times[i][m] for i in range(N))
        LB_m = min_pre + machine_sum + min_suf
        if LB_m > LB:
            LB = LB_m
    if best_makespan == LB:
        return best_seq

    max_iter = 60
    d = 3
    T = T0
    current_seq = initial_seq[:]
    for it in range(max_iter):
        if len(current_seq) <= d:
            destroyed = []
            extracted = current_seq[:]
            random.shuffle(extracted)
            current_seq = []
        else:
            indices = random.sample(range(len(current_seq)), d)
            indices.sort(reverse=True)
            extracted = [current_seq.pop(idx) for idx in indices]
            destroyed = current_seq
        e = taillard_forward(destroyed)
        q = taillard_backward(destroyed)
        for job in extracted:
            best_pos = 0
            best_cost = math.inf
            for pos in range(len(destroyed)+1):
                cost = insertion_cost(destroyed, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            destroyed.insert(best_pos, job)
            e = taillard_forward(destroyed)
            q = taillard_backward(destroyed)
        current_seq = destroyed
        current_makespan = makespan(current_seq)
        if current_makespan < best_makespan:
            best_makespan = current_makespan
            best_seq = current_seq[:]
            if best_makespan == LB:
                break
        if current_makespan < makespan(initial_seq):
            initial_seq = current_seq[:]
        if current_makespan > makespan(initial_seq):
            delta = current_makespan - makespan(initial_seq)
            if delta > 0 and random.random() < math.exp(-delta / T):
                initial_seq = current_seq[:]
        T *= 0.95
    return best_seq

