            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[-1]

    def taillard_forward_backward(perm):
        k = len(perm)
        if k == 0:
            return [0] * M, [0] * M
        e = [[0] * M for _ in range(k)]
        job0 = times[perm[0]]
        e[0][0] = job0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0[m]
        for r in range(1, k):
            job = times[perm[r]]
            e[r][0] = e[r-1][0] + job[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job[m]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = times[perm[r]]
            q[r][M-1] = q[r+1][M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job[m]
        return e, q

    def insert_with_taillard(current_perm, job_idx):
        k = len(current_perm)
        if k == 0:
            return [job_idx]
        e, q = taillard_forward_backward(current_perm)
        best_pos = 0
        best_makespan = float('inf')
        job = times[job_idx]
        for i in range(k+1):
            f = [0] * M
            if i == 0:
                f[0] = job[0]
                for m in range(1, M):
                    f[m] = f[m-1] + job[m]
