    T = T_param * total_processing / (10 * N * M)
    d = 3
    max_iter = 60

    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            R = current[:]
            random.shuffle(R)
        else:
            indices = random.sample(range(len(current)), d)
            indices.sort(reverse=True)
            R = [current.pop(i) for i in indices]
            destroyed = current
        random.shuffle(R)
        for job in R:
            best_pos = 0
            best_makespan_job = float('inf')
            for pos in range(len(destroyed) + 1):
                cmax = taillard_makespan(destroyed, job, pos)
                if cmax < best_makespan_job:
