def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(row) for row in times)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[-1]

    def compute_tail_matrix(seq, k):
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = seq[r]
            job_time = times[job]
            q[r][M-1] = q[r+1][M-1] + job_time[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_time[m]
        return q

    def compute_forward_matrix(seq, k):
        e = [[0] * M for _ in range(k)]
        if k == 0:
            return e
        job0 = seq[0]
        job0_time = times[job0]
        e[0][0] = job0_time[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0_time[m]
        for r in range(1, k):
            job = seq[r]
            job_time = times[job]
            e[r][0] = e[r-1][0] + job_time[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job_time[m]
        return e

    def insert_job_neh_tail(seq, job, e, q, k):
        best_pos = 0
        best_cmax = float('inf')
        job_time = times[job]
        for i in range(k+1):
            if i == 0:
                f0 = job_time[0]
            else:
                f0 = e[i-1][0] + job_time[0]
            f = [0] * M
            f[0] = f0
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + job_time[m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos

    def neh_construction():
        P = [sum(times[i]) for i in range(N)]
        order = sorted(range(N), key=lambda i: (-P[i], i))
        seq = [order[0]]
        if N > 1:
            job1 = order[1]
            seq1 = [order[0], job1]
            seq2 = [job1, order[0]]
            if makespan(seq1) <= makespan(seq2):
                seq = seq1
            else:
                seq = seq2
        for k in range(2, N):
            job = order[k]
            e = compute_forward_matrix(seq, k)
            q = compute_tail_matrix(seq, k)
            pos = insert_job_neh_tail(seq, job, e, q, k)
            seq.insert(pos, job)
        return seq

    pi = neh_construction()
    pi_star = pi[:]
    c_star = makespan(pi_star)

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3
    max_iter = 60

    for _ in range(max_iter):
        if c_star == 0:
            break
        indices = list(range(N))
        random.shuffle(indices)
        R = indices[:d]
        R_set = set(R)
        pi_D = [pi[i] for i in range(N) if i not in R_set]
        k = N - d
        e = compute_forward_matrix(pi_D, k)
        q = compute_tail_matrix(pi_D, k)
        for job in R:
            pos = insert_job_neh_tail(pi_D, job, e, q, k)
            pi_D.insert(pos, job)
            k += 1
            if k < N:
                e = compute_forward_matrix(pi_D, k)
                q = compute_tail_matrix(pi_D, k)
        c_new = makespan(pi_D)
        if c_new < makespan(pi):
            pi = pi_D[:]
        if c_new < c_star:
            pi_star = pi_D[:]
            c_star = c_new
        if c_new != makespan(pi):
            delta = c_new - makespan(pi)
            if delta < 0 or random.random() < math.exp(-delta / T):
                pi = pi_D[:]

    return pi_star

