        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N+1)]

        for k in range(1, N):
            job = job_order[k]
            # Forward pass for current seq (length k)
            for r in range(k):
                if r == 0:
                    e[r][0] = p[seq[r]][0]
                else:
                    e[r][0] = e[r-1][0] + p[seq[r]][0]
                for m in range(1, M):
