                    C[idx][m] = times[job][m]
                elif idx == 0:
                    C[idx][m] = C[idx][m-1] + times[job][m]
                elif m == 0:
                    C[idx][m] = C[idx-1][m] + times[job][m]
                else:
                    C[idx][m] = max(C[idx-1][m], C[idx][m-1]) + times[job][m]
        return C[len(seq)-1][M-1]

    def taillard_insert(seq, job):
        """Find best insertion position for job in seq using Taillard acceleration."""
        k = len(seq)
        if k == 0:
            return [job]
        # Forward matrix e: completion times of current seq
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = seq[r]
            for m in range(M):
