        best_makespan = float('inf')
        for i in range(k+1):
            # Compute forward vector f for job at position i
            f = [0] * M
            prev_e = e[i-1] if i > 0 else [0] * M
            for m in range(M):
                if m == 0:
                    f[m] = (prev_e[0] if i > 0 else 0) + times[job][m]
