        # Acceptance criterion
        new_makespan = makespan(destroyed)
        if new_makespan < makespan(current_seq):
            current_seq = destroyed[:]
            if new_makespan < best_makespan:
                best_seq = destroyed[:]
                best_makespan = new_makespan
                no_improve = 0
            else:
                no_improve += 1
        else:
            delta = new_makespan - makespan(current_seq)
            if random.random() < math.exp(-delta / T):
                current_seq = destroyed[:]
                no_improve += 1
            else:
                no_improve += 1
        if no_improve >= no_improve_limit:
            break

    # Final refinement: apply NEH with bottleneck-aware priority
    # Priority: jobs with high load on bottleneck machine first
    bottleneck_priority = sorted(range(N), key=lambda i: (-p[i][bottleneck_m], -total_p[i], i))
    seq_bottleneck = [bottleneck_priority[0]]
    for idx in range(1, N):
        seq_bottleneck = taillard_insert(seq_bottleneck, bottleneck_priority[idx])
    if makespan(seq_bottleneck) < best_makespan:
        best_seq = seq_bottleneck
        best_makespan = makespan(best_seq)

    return best_seq

