def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [row[:] for row in times]
    total_p = [sum(job) for job in p]

    # Taillard lower bound for early termination
    def compute_lower_bound():
        LB = 0
        for m in range(M):
            min_before = min(p[i][l] for i in range(N) for l in range(m)) if m > 0 else 0
            min_after = min(p[i][l] for i in range(N) for l in range(m+1, M)) if m < M-1 else 0
            sum_m = sum(p[i][m] for i in range(N))
            LB_m = min_before + sum_m + min_after
            if LB_m > LB:
                LB = LB_m
        return LB

    LB = compute_lower_bound()

    # Makespan calculation using iterative update (O(N*M))
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[-1]

    # Taillard's acceleration for NEH insertion
    def neh_with_taillard(job_order):
        if not job_order:
            return []
        seq = [job_order[0]]
        if len(job_order) == 1:
            return seq
        # Try both orders for first two jobs
        seq1 = [job_order[0], job_order[1]]
        seq2 = [job_order[1], job_order[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2

        for k in range(2, len(job_order)):
            job = job_order[k]
            # Build forward matrix e for current seq (length k)
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = seq[r]
                if r == 0:
                    e[0][0] = p[job_r][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + p[job_r][m]
                else:
                    e[r][0] = e[r-1][0] + p[job_r][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]
            # Build backward tail matrix q for current seq (length k)
            q = [[0] * M for _ in range(k+1)]  # q[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
            # Evaluate insertion positions 0..k
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Compute forward vector f for job at position i
                f = [0] * M
                if i == 0:
                    prev = [0] * M
                else:
                    prev = e[i-1]
                f[0] = prev[0] + p[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev[m]) + p[job][m]
                # Compute makespan if job inserted at i: max_m (f[m] + q[i][m])
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size 3
    def iterated_greedy(initial_seq, max_time_ms=40):
        start_time = random.random()  # Placeholder; we use iteration count instead
        current = initial_seq[:]
        best = current[:]
        best_mk = makespan(best)
        if best_mk == LB:
            return best
        # Use fixed number of iterations calibrated for <50ms
        num_iters = 60
        for _ in range(num_iters):
            # Destruction: remove d=3 random jobs
            if N <= 3:
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(N), 3)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(N) if i not in indices_set]
            # Reconstruction: reinsert destroyed jobs one by one using NEH insertion
            for job in destroyed:
                # Build forward matrix e for current remaining seq
                k = len(remaining)
                if k == 0:
                    remaining.append(job)
                    continue
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    job_r = remaining[r]
                    if r == 0:
                        e[0][0] = p[job_r][0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + p[job_r][m]
                    else:
                        e[r][0] = e[r-1][0] + p[job_r][0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]
                # Build backward tail matrix q
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = remaining[r]
                    q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
                # Find best insertion position
                best_pos = 0
                best_mk = float('inf')
                for i in range(k+1):
                    f = [0] * M
                    if i == 0:
                        prev = [0] * M
                    else:
                        prev = e[i-1]
                    f[0] = prev[0] + p[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev[m]) + p[job][m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk:
                        best_mk = mk
                        best_pos = i
                remaining.insert(best_pos, job)
            # Evaluate new sequence
            new_mk = makespan(remaining)
            # Acceptance criterion
            if new_mk < makespan(current):
                current = remaining[:]
                if new_mk < best_mk:
                    best_mk = new_mk
                    best = current[:]
                    if best_mk == LB:
                        break
            else:
                # Metropolis acceptance
                avg_p = sum(total_p) / (N * M)
                T = 0.5 * avg_p  # T_param * (sum p)/(10*N*M) * 10? Adjusted for stability
                delta = new_mk - makespan(current)
                if random.random() < math.exp(-delta / T):
                    current = remaining[:]
        return best

    # Main: NEH construction with multiple orderings
    # Order 1: descending total processing time (NEH standard)
    order1 = sorted(range(N), key=lambda i: total_p[i], reverse=True)
    # Order 2: Palmer's slope
    slope = [sum((2*j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]
    order2 = sorted(range(N), key=lambda i: slope[i], reverse=True)
    # Order 3: ascending total processing time (diversification)
    order3 = sorted(range(N), key=lambda i: total_p[i])

    best_seq = None
    best_mk = float('inf')

    for job_order in [order1, order2, order3]:
        seq = neh_with_taillard(job_order)
        mk = makespan(seq)
        if mk < best_mk:
            best_mk = mk
            best_seq = seq
            if best_mk == LB:
                break

    # Apply Iterated Greedy refinement
    refined_seq = iterated_greedy(best_seq)
    refined_mk = makespan(refined_seq)
    if refined_mk < best_mk:
        return refined_seq
    else:
        return best_seq

