def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    def makespan(seq):
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m-1], t[m]) + times[job][m]
        return t[-1]

    def johnson_rule(p1, p2):
        n = len(p1)
        left, right = 0, n - 1
        seq = [0] * n
        jobs = list(range(n))
        while jobs:
            min_val = float('inf')
            min_job = -1
            min_side = -1
            for j in jobs:
                if p1[j] < min_val:
                    min_val = p1[j]
                    min_job = j
                    min_side = 0
                if p2[j] < min_val:
                    min_val = p2[j]
                    min_job = j
                    min_side = 1
            if min_side == 0:
                seq[left] = min_job
                left += 1
            else:
                seq[right] = min_job
                right -= 1
            jobs.remove(min_job)
        return seq

    def cds_variant():
        best_seq = None
        best_cmax = float('inf')
        for l in range(1, M):
            p1 = [sum(times[i][:l]) for i in range(N)]
            p2 = [sum(times[i][M-l:]) for i in range(N)]
            seq = johnson_rule(p1, p2)
            cmax = makespan(seq)
            if cmax < best_cmax:
                best_cmax = cmax
                best_seq = seq
        return best_seq

    # Try CDS variant first
    pi = cds_variant()
    pi_star = pi[:]
    cmax_pi = makespan(pi)
    cmax_pi_star = cmax_pi

    # Calculate total processing time for temperature
    total_p = sum(sum(row) for row in times)
    T_param = 0.5
    T = T_param * total_p / (10 * N * M) if N * M > 0 else 1e-6

    max_iter = 50
    d = 3

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        R = [pi[i] for i in indices]
        pi_D = [pi[i] for i in range(N) if i not in indices]

        # Reconstruction: reinsert each job in R using NEH with Taillard acceleration
        for job in R:
            k = len(pi_D)
            if k == 0:
                pi_D = [job]
                continue

            # Build forward matrix e for current pi_D
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = pi_D[r]
                for m in range(M):
                    if m == 0:
                        prev = e[r-1][0] if r > 0 else 0
                        e[r][m] = prev + times[job_r][m]
                    else:
                        left = e[r-1][m] if r > 0 else 0
                        up = e[r][m-1]
                        e[r][m] = max(left, up) + times[job_r][m]

            # Build backward matrix q for current pi_D
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = pi_D[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        down = q[r+1][m]
                        q[r][m] = down + times[job_r][m]
                    else:
                        down = q[r+1][m]
                        right = q[r][m+1]
                        q[r][m] = max(down, right) + times[job_r][m]

            # Evaluate each insertion position
            best_pos = 0
            best_makespan = float('inf')
            for i in range(k+1):
                # Compute forward vector f for job at position i
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev_e = e[i-1][0] if i > 0 else 0
                        f[m] = prev_e + times[job][m]
                    else:
                        left_f = f[m-1]
                        up_e = e[i-1][m] if i > 0 else 0
                        f[m] = max(left_f, up_e) + times[job][m]

                # Compute makespan if job inserted at i
                current_max = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > current_max:
                        current_max = val
                if current_max < best_makespan:
                    best_makespan = current_max
                    best_pos = i

            pi_D.insert(best_pos, job)

        pi_new = pi_D
        cmax_new = makespan(pi_new)

        # Acceptance criterion
        if cmax_new < cmax_pi:
            pi = pi_new
            cmax_pi = cmax_new
            if cmax_new < cmax_pi_star:
                pi_star = pi_new[:]
                cmax_pi_star = cmax_new
        else:
            if random.random() < math.exp(-(cmax_new - cmax_pi) / T):
                pi = pi_new
                cmax_pi = cmax_new

    return pi_star

