def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_times = [sum(job) for job in times]
    slope_indices = [sum((2 * j - m + 1) * times[i][j] for j in range(m)) for i in range(n)]

    # Sort by total processing time descending, tie-break by slope index descending
    jobs_sorted = sorted(range(n), key=lambda i: (-total_times[i], -slope_indices[i]))

    # Initialize schedule with first job
    schedule = [jobs_sorted[0]]

    # Preallocate matrices for forward and backward passes
    e = [[0] * m for _ in range(n)]
    q = [[0] * m for _ in range(n + 1)]

    # Helper to compute makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            t[0] += times[job][0]
            for k in range(1, m):
                t[k] = max(t[k], t[k - 1]) + times[job][k]
        return t[-1]

    # Main NEH construction loop with Taillard acceleration
    for k in range(1, n):
        job = jobs_sorted[k]
        best_pos = 0
        best_mk = float('inf')

        # Forward pass: compute e[0..k-1][0..m-1] for current schedule
        for i in range(k):
            job_i = schedule[i]
            if i == 0:
                e[0][0] = times[job_i][0]
                for mm in range(1, m):
                    e[0][mm] = e[0][mm - 1] + times[job_i][mm]
            else:
                e[i][0] = e[i - 1][0] + times[job_i][0]
                for mm in range(1, m):
                    e[i][mm] = max(e[i - 1][mm], e[i][mm - 1]) + times[job_i][mm]

        # Backward pass: compute q[0..k][0..m-1] for current schedule
        for mm in range(m):
            q[k][mm] = 0
        for i in range(k - 1, -1, -1):
            job_i = schedule[i]
            q[i][m - 1] = q[i + 1][m - 1] + times[job_i][m - 1]
            for mm in range(m - 2, -1, -1):
                q[i][mm] = max(q[i + 1][mm], q[i][mm + 1]) + times[job_i][mm]

        # Try inserting 'job' at each position 0..k
        for pos in range(k + 1):
            # Compute forward vector f for inserting 'job' at 'pos'
            if pos == 0:
                f0 = times[job][0]
                f = [f0]
                for mm in range(1, m):
                    f.append(f[-1] + times[job][mm])
            else:
                prev_e = e[pos - 1]
                f0 = prev_e[0] + times[job][0]
                f = [f0]
                for mm in range(1, m):
                    f.append(max(f[-1], prev_e[mm]) + times[job][mm])

            # Compute makespan: max over m of (f[m] + q[pos][m])
            mk = 0
            for mm in range(m):
                val = f[mm] + q[pos][mm]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = pos

        schedule.insert(best_pos, job)

    return schedule

