def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [times[i][:] for i in range(N)]
    total_p = [sum(job) for job in p]

    # Compute makespan using Taillard's scheme
    def makespan(seq):
        if not seq:
            return 0
        e_prev = [0] * M
        for idx in seq:
            job = p[idx]
            f0 = e_prev[0] + job[0]
            f = [f0]
            for m in range(1, M):
                f.append(max(f[m-1], e_prev[m]) + job[m])
            e_prev = f
        return e_prev[-1]

    # Compute forward matrix e for partial schedule seq[0:k]
    def compute_e(seq, k):
        e = [[0] * M for _ in range(k)]
        if k == 0:
            return e
        job0 = p[seq[0]]
        e[0][0] = job0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0[m]
        for r in range(1, k):
            job = p[seq[r]]
            er = e[r]
            er_prev = e[r-1]
            er[0] = er_prev[0] + job[0]
            for m in range(1, M):
                er[m] = max(er_prev[m], er[m-1]) + job[m]
        return e

    # Compute backward tail matrix q for partial schedule seq[0:k]
    def compute_q(seq, k):
        q = [[0] * M for _ in range(k+1)]
        if k == 0:
            return q
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = p[seq[r]]
            qr = q[r]
            qr_next = q[r+1]
            qr[M-1] = qr_next[M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                qr[m] = max(qr_next[m], qr[m+1]) + job[m]
        return q

    # Evaluate makespan for inserting job x at position i in seq of length k
    def insertion_makespan(e, q, x, i, k):
        job = p[x]
        f0 = (e[i-1][0] if i-1 >= 0 else 0) + job[0]
        f = [f0]
        for m in range(1, M):
            em = e[i-1][m] if i-1 >= 0 else 0
            f.append(max(f[m-1], em) + job[m])
        qi = q[i]
        max_val = 0
        for m in range(M):
            val = f[m] + qi[m]
            if val > max_val:
                max_val = val
        return max_val

    # NEH with Taillard acceleration
    def construct_initial():
        order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            e_mat = compute_e(seq, k)
            q_mat = compute_q(seq, k)
            best_pos = 0
            best_mk = insertion_makespan(e_mat, q_mat, job, 0, k)
            for i in range(1, k+1):
                mk = insertion_makespan(e_mat, q_mat, job, i, k)
                if mk < best_mk:
