def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and job data
    P = [sum(row) for row in times]
    job_data = times  # direct reference for speed

    # Makespan evaluation function
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            pj = job_data[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + pj[m]
        return t[-1]

    # Taillard-accelerated insertion evaluation
    def evaluate_insertion(partial, job, k):
        if k == 0:
            e_prev = [0] * M
        else:
            e_prev = [[0] * M for _ in range(k)]
            for r in range(k):
                pj = job_data[partial[r]]
                if r == 0:
                    e_prev[0][0] = pj[0]
                    for m in range(1, M):
                        e_prev[0][m] = e_prev[0][m-1] + pj[m]
                else:
                    e_prev[r][0] = e_prev[r-1][0] + pj[0]
                    for m in range(1, M):
                        e_prev[r][m] = max(e_prev[r-1][m], e_prev[r][m-1]) + pj[m]

        # Compute backward tail matrix q
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pj = job_data[partial[r]]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]

        best_pos = 0
        best_val = float('inf')
        for i in range(k+1):
            if i == 0:
                f = [0] * M
            else:
                f = [0] * M
                e_im1 = e_prev[i-1] if i-1 < k else [0]*M
                pj = job_data[job]
                f[0] = (e_im1[0] if i-1 >= 0 else 0) + pj[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e_im1[m]) + pj[m]

            q_i = q[i]
            current_max = 0
            for m in range(M):
                val = f[m] + q_i[m]
                if val > current_max:
                    current_max = val
            if current_max < best_val:
                best_val = current_max
                best_pos = i
        return best_pos, best_val

    # NEH construction with Taillard acceleration
    def neh_construct(order):
        if N <= 1:
            return order[:]
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        for k in range(2, N):
            job = order[k]
            pos, _ = evaluate_insertion(seq, job, k)
            seq.insert(pos, job)
        return seq

    # Iterated Greedy with destruction/reconstruction
    def iterated_greedy(init_seq, max_iters=50):
        current = init_seq[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing = sum(P)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 5 else max(1, N//2)

        for _ in range(max_iters):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            indices_set = set(indices)
            # Build partial sequence without removed jobs
            partial = [current[i] for i in range(N) if i not in indices_set]

            # Reconstruction: re-insert removed jobs in random order
            random.shuffle(removed)
            for job in removed:
                k = len(partial)
                pos, _ = evaluate_insertion(partial, job, k)
                partial.insert(pos, job)

            # New candidate sequence
            candidate = partial
            mk_candidate = makespan(candidate)

            # Acceptance criterion
            if mk_candidate < makespan(current):
                current = candidate
                if mk_candidate < best_mk:
                    best = candidate[:]
                    best_mk = mk_candidate
            else:
                delta = mk_candidate - makespan(current)
                if random.random() < math.exp(-delta / T):
                    current = candidate

        return best

    # Multi-start NEH with noise
    best_overall = None
    best_mk_overall = float('inf')
    for _ in range(3):
        # Apply noise to total processing times
        noisy_P = [P[i] * random.uniform(0.9, 1.1) for i in range(N)]
        order = sorted(range(N), key=lambda i: noisy_P[i], reverse=True)
        seq = neh_construct(order)
        mk = makespan(seq)
        if mk < best_mk_overall:
            best_mk_overall = mk
            best_overall = seq

    # Refine with Iterated Greedy
    refined = iterated_greedy(best_overall, max_iters=40)
    return refined

