            return 0
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard accelerated insertion evaluation for a partial schedule
    def evaluate_insertion(partial, job, e, q):
        k = len(partial)
        f = [0] * M
        for m in range(M):
            prev_e = e[k-1][m] if k > 0 else 0
            if m == 0:
                f[m] = prev_e + p[job][0]
            else:
                f[m] = max(f[m-1], prev_e) + p[job][m]
        best_cmax = float('inf')
        best_pos = 0
        for i in range(k + 1):
            val = 0
            for m in range(M):
                tmp = f[m] + q[i][m]
                if tmp > val:
                    val = tmp
            if val < best_cmax:
                best_cmax = val
                best_pos = i
        return best_pos, best_cmax

    # Construct initial solution using NEH with Taillard acceleration
    def construct_initial():
        order = sorted(range(N), key=lambda i: total[i], reverse=True)
        if N == 0:
            return []
        perm = [order[0]]
        if N == 1:
            return perm
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        # Build e and q for current perm (length 2)
        k = len(perm)
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r>0 else 0) + p[job][0]
                else:
                    e[r][m] = max(e[r-1][m] if r>0 else 0, e[r][m-1]) + p[job][m]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]
        # Insert remaining jobs
        for idx in range(2, N):
            job = order[idx]
            pos, _ = evaluate_insertion(perm, job, e, q)
            perm.insert(pos, job)
            # Rebuild e and q for new perm
            k = len(perm)
            e = [[0]*M for _ in range(k)]
            for r in range(k):
                job_r = perm[r]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r>0 else 0) + p[job_r][0]
                    else:
                        e[r][m] = max(e[r-1][m] if r>0 else 0, e[r][m-1]) + p[job_r][m]
            q = [[0]*M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = perm[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + p[job_r][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
        return perm

    # Variable Neighborhood Search with insert and swap neighborhoods
    def variable_neighborhood_search(init_perm, max_time=0.04):
        import time
        start = time.time()
        current = init_perm[:]
        best = current[:]
        best_cmax = makespan(best)
        k_max = 2  # two neighborhoods: 0=insert, 1=swap
        k = 0
        while time.time() - start < max_time:
            if k == 0:
                # Neighborhood: single-job relocation (insert)
                improved = False
                for i in range(N):
                    job = current.pop(i)
                    for j in range(N):  # N because after pop, length is N-1, insert at 0..N-1
                        if j > len(current):
                            continue
                        trial = current[:]
                        trial.insert(j, job)
                        trial_cmax = makespan(trial)
                        if trial_cmax < best_cmax:
                            best = trial[:]
                            best_cmax = trial_cmax
                            current = trial[:]
                            improved = True
                            break
                    if improved:
                        break
                    current.insert(i, job)  # restore
                if not improved:
                    k = 1
                else:
                    k = 0
            else:
                # Neighborhood: job-pair swap
                improved = False
                for i in range(N):
                    for j in range(i+1, N):
                        trial = current[:]
                        trial[i], trial[j] = trial[j], trial[i]
                        trial_cmax = makespan(trial)
                        if trial_cmax < best_cmax:
                            best = trial[:]
                            best_cmax = trial_cmax
                            current = trial[:]
                            improved = True
                            break
                    if improved:
                        break
                if not improved:
                    k = 0
                else:
                    k = 1
        return best

    # Main execution
    init_perm = construct_initial()
    # Refine with VNS
    improved_perm = variable_neighborhood_search(init_perm, max_time=0.04)
    return improved_perm

