    p = [row[:] for row in times]

    # Compute total processing time and slope index for priority ordering
    total_time = [sum(job) for job in p]
    slope = [sum((2 * j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]

    # Combine criteria: primary by total_time descending, secondary by slope descending
    jobs = list(range(N))
    jobs.sort(key=lambda i: (-total_time[i], -slope[i]))

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += p[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard's accelerated insertion evaluation for a partial schedule
    def evaluate_insertion(partial, job, k):
        # k is the length of partial schedule
        if k == 0:
            f = [p[job][m] for m in range(M)]
            return f[-1]

        # Forward matrix e for partial schedule (size k x M)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job_r][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job_r][m]

        # Backward tail matrix q for partial schedule (size (k+1) x M)
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job_r][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]

        best_cmax = float('inf')
        best_pos = 0
        # Try inserting job at each position i in [0, k]
        for i in range(k+1):
            # Compute forward vector f for job at position i
            f = [0] * M
            if i == 0:
                prev_e = [0] * M
            else:
                prev_e = e[i-1]
            for m in range(M):
                if m == 0:
                    f[m] = prev_e[m] + p[job][m]
                else:
                    f[m] = max(f[m-1], prev_e[m]) + p[job][m]
            # Compute makespan if job inserted at i
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_cmax, best_pos

    # NEH construction with Taillard acceleration
    def neh_construct(job_order):
        if not job_order:
            return []
        seq = [job_order[0]]
        for idx in range(1, len(job_order)):
            job = job_order[idx]
            _, pos = evaluate_insertion(seq, job, len(seq))
            seq.insert(pos, job)
        return seq

    # Initial solution
    current = neh_construct(jobs)
    best = current[:]
    best_cmax = makespan(best)

    # Iterated Greedy parameters
    T_param = 0.5
    total_processing = sum(total_time)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2  # destruction size
    max_iter = 50  # calibrated for <50ms

    for _ in range(max_iter):
        # Destruction: remove d jobs randomly
        if d >= N:
            destroyed = []
            remaining = current[:]
            random.shuffle(remaining)
        else:
            indices = random.sample(range(N), d)
            indices.sort(reverse=True)
            destroyed = [current[i] for i in indices]
            remaining = current[:]
            for i in indices:
                remaining.pop(i)

        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        seq = remaining[:]
        for job in destroyed:
            _, pos = evaluate_insertion(seq, job, len(seq))
            seq.insert(pos, job)

        # Acceptance criterion
        new_cmax = makespan(seq)
        if new_cmax < best_cmax:
            best_cmax = new_cmax
            best = seq[:]
            current = seq[:]
        elif new_cmax < makespan(current):
            current = seq[:]
        else:
            if random.random() < math.exp(-(new_cmax - makespan(current)) / T):
                current = seq[:]

    return best

