    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m - 1]) + times[job][m]
        return t[-1]

    # Taillard-accelerated NEH insertion: returns best permutation and makespan when inserting job x into perm
    def insert_job_neh(perm, x):
        k = len(perm)
        if k == 0:
            return [x], times[x][0] if M == 1 else 0  # dummy, will be computed properly

        # Forward matrix e: completion times of current perm
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r - 1][m] if r > 0 else 0) + times[job][m]
                else:
                    e[r][m] = max(e[r - 1][m] if r > 0 else 0, e[r][m - 1]) + times[job][m]

        # Backward matrix q: tail times from position r to end
        q = [[0] * M for _ in range(k + 1)]
        for r in range(k - 1, -1, -1):
            job = perm[r]
            for m in range(M - 1, -1, -1):
                if m == M - 1:
                    q[r][m] = q[r + 1][m] + times[job][m]
                else:
                    q[r][m] = max(q[r + 1][m], q[r][m + 1]) + times[job][m]

        best_perm = None
        best_mk = float('inf')
        # Try all insertion positions
        for i in range(k + 1):
            # Forward pass for job x up to machine m
            f = [0] * M
            for m in range(M):
                if m == 0:
                    prev = e[i - 1][0] if i > 0 else 0
                    f[m] = prev + times[x][m]
                else:
                    prev_f = f[m - 1]
                    prev_e = e[i - 1][m] if i > 0 else 0
                    f[m] = max(prev_f, prev_e) + times[x][m]
            # Compute makespan: max over m of f[m] + q[i][m]
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_perm = perm[:i] + [x] + perm[i:]
        return best_perm, best_mk

    # Construct initial solution using NEH with priority order (total descending)
    order = sorted(range(N), key=lambda i: total[i], reverse=True)
    perm, mk = [order[0]], 0
    for idx in range(1, N):
