        # Destruction: remove d jobs at random positions
        if d >= N:
            destroyed = []
            remaining = []
        else:
            positions = random.sample(range(N), d)
            positions.sort(reverse=True)
            destroyed = [current_perm[pos] for pos in positions]
            remaining = [current_perm[i] for i in range(N) if i not in positions]
        # Reconstruction: reinsert destroyed jobs one by one using NEH insertion
        for job in destroyed:
            remaining, _ = insert_job_neh(remaining, job)
        new_perm = remaining
        new_mk = makespan(new_perm)

        # Acceptance criterion
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current_perm = new_perm
            current_mk = new_mk
            if new_mk < best_mk:
                best_perm = new_perm[:]
                best_mk = new_mk

    return best_perm

