def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    if n == 1:
        return [0]
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1.0

    p = [job[:] for job in times]

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            job_t = p[job]
            t[0] += job_t[0]
            for i in range(1, m):
                t[i] = max(t[i-1], t[i]) + job_t[i]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        e = [[0] * m for _ in range(k)]
        if k == 0:
            return e
        job0 = p[perm[0]]
        e[0][0] = job0[0]
        for i in range(1, m):
            e[0][i] = e[0][i-1] + job0[i]
        for r in range(1, k):
            job_r = p[perm[r]]
            e[r][0] = e[r-1][0] + job_r[0]
            for c in range(1, m):
                e[r][c] = max(e[r-1][c], e[r][c-1]) + job_r[c]
        return e

    def compute_backward(perm):
        k = len(perm)
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = p[perm[r]]
            q[r][m-1] = q[r+1][m-1] + job_r[m-1]
            for c in range(m-2, -1, -1):
                q[r][c] = max(q[r+1][c], q[r][c+1]) + job_r[c]
        return q

    def makespan_insert(e, q, job_idx, pos):
        job = p[job_idx]
        if pos == 0:
            f0 = job[0]
        else:
            f0 = e[pos-1][0] + job[0]
        f = [f0]
        for i in range(1, m):
            val = e[pos-1][i] if pos-1 >= 0 else 0
            f.append(max(f[-1], val) + job[i])
        makespan_val = 0
        for i in range(m):
            val = f[i] + q[pos][i]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_taillard(perm):
        e = compute_forward(perm)
        q = compute_backward(perm)
        k = len(perm)
        best_pos = 0
        best_ms = makespan_insert(e, q, job_idx, 0)
        for pos in range(1, k+1):
            ms = makespan_insert(e, q, job_idx, pos)
            if ms < best_ms:
                best_ms = ms
                best_pos = pos
        return best_pos

    def neh_construct():
        job_sums = [sum(job) for job in p]
        order = sorted(range(n), key=lambda i: job_sums[i], reverse=True)
        if n == 0:
            return []
        if n == 1:
            return [order[0]]
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        for idx in range(2, n):
            job_idx = order[idx]
            pos = neh_taillard(seq)
            seq.insert(pos, job_idx)
        return seq

    def ig_iteration(current_seq):
        d = 3 if n > 5 else max(1, n//2)
        if d > n:
            d = n
        indices = random.sample(range(n), d)
        removed = [current_seq[i] for i in indices]
        remaining = [current_seq[i] for i in range(n) if i not in indices]
        random.shuffle(removed)
        seq = remaining[:]
