    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: P[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_time[m]
        return t[-1]

    def compute_forward(partial):
        k = len(partial)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            pj = times[job]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    def compute_backward(partial):
        k = len(partial)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            pj = times[job]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    def makespan_insert(e, q, job, pos):
        pj = times[job]
        i = pos
        if i == 0:
            f0 = pj[0]
        else:
            f0 = e[i-1][0] + pj[0]
        f = [f0]
        for m in range(1, M):
            if i == 0:
                prev_e = 0
            else:
                prev_e = e[i-1][m]
            fm = max(f[m-1], prev_e) + pj[m]
            f.append(fm)
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_with_tard():
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        for k in range(2, N):
            job = order[k]
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_makespan = makespan_insert(e, q, job, 0)
            for pos in range(1, k+1):
                m = makespan_insert(e, q, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            seq.insert(best_pos, job)
