    current = neh_with_tard()
    best = current[:]
    best_makespan = makespan(current)

    max_iter = 60
    d = 3 if N < 30 else 4
    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            R = current[:]
        else:
            indices = random.sample(range(len(current)), d)
            indices.sort(reverse=True)
            R = [current[i] for i in indices]
            destroyed = current[:]
            for idx in indices:
                destroyed.pop(idx)
