                    best_pos = pos
            pi_D.insert(best_pos, job)
            e = compute_forward(pi_D)
            q = compute_backward(pi_D)
        pi_new = pi_D
        m_new = makespan(pi_new)
        if m_new < best_makespan:
            best_makespan = m_new
            best = pi_new[:]
        if m_new < makespan(current):
            current = pi_new
        else:
            delta = m_new - makespan(current)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current = pi_new
    return best

