                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job][m]
        return e

    # Helper: compute backward tail matrix q for a partial schedule
    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]  # q[k][*] = 0
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return q

    # Helper: evaluate makespan for inserting job x at position i in perm using Taillard's O(M) method
    def evaluate_insertion(perm, x, i):
        k = len(perm)
        e_prev = [0] * M
        if i > 0:
            # compute e[i-1][*] on the fly without storing full matrix
            t = [0] * M
            for r in range(i):
                job = perm[r]
                for m in range(M):
                    if m == 0:
                        t[m] += times[job][m]
                    else:
                        t[m] = max(t[m], t[m-1]) + times[job][m]
            e_prev = t[:]
        # forward pass for job x
        f = [0] * M
        for m in range(M):
            if m == 0:
                f[m] = e_prev[0] + times[x][0]
            else:
                f[m] = max(f[m-1], e_prev[m]) + times[x][m]
        # backward tail q[i][*] from perm[i:] (if any)
        q_i = [0] * M
        if i < k:
            t = [0] * M
            for r in range(i, k):
                job = perm[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        t[m] += times[job][m]
                    else:
                        t[m] = max(t[m], t[m+1]) + times[job][m]
            q_i = t[:]
        # makespan = max_m (f[m] + q_i[m])
        makespan_val = 0
        for m in range(M):
            val = f[m] + q_i[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    def neh_construction(priority):
        if N == 0:
            return []
        # start with first two jobs
        a, b = priority[0], priority[1]
        ab = makespan([a, b])
        ba = makespan([b, a])
        perm = [a, b] if ab <= ba else [b, a]
        # insert remaining jobs
        for idx in range(2, N):
            job = priority[idx]
            best_pos = 0
            best_makespan = float('inf')
            # evaluate all insertion positions 0..idx
            for pos in range(idx + 1):
                msp = evaluate_insertion(perm, job, pos)
                if msp < best_makespan:
                    best_makespan = msp
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # Generate initial solution using NEH with total time ordering
    priority_total = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    best_perm = neh_construction(priority_total)
    best_makespan = makespan(best_perm)
    current_perm = best_perm[:]

    # Iterated Greedy parameters
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2  # destruction size
    max_iter = 60  # calibrated for <50ms

    # Main IG loop
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current_perm[i] for i in indices]
        # Build partial sequence without removed jobs
        remaining_set = set(indices)
        pi_D = [current_perm[i] for i in range(N) if i not in remaining_set]
        # Reconstruction: re-insert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(pi_D) + 1):
                msp = evaluate_insertion(pi_D, job, pos)
                if msp < best_makespan:
                    best_makespan = msp
                    best_pos = pos
            pi_D.insert(best_pos, job)
        current_perm = pi_D
        current_makespan = makespan(current_perm)
        # Acceptance criterion
        if current_makespan < makespan(best_perm):
            best_perm = current_perm[:]
            best_makespan = current_makespan
        if current_makespan < makespan(best_perm):  # redundant but safe
            best_perm = current_perm[:]
            best_makespan = current_makespan
        elif current_makespan < makespan(best_perm):
            best_perm = current_perm[:]
            best_makespan = current_makespan
        else:
            delta = current_makespan - makespan(best_perm)
            if delta < 0 or random.random() < math.exp(-delta / T):
                best_perm = current_perm[:]  # accept worse solution
    return best_perm

