def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard accelerated makespan for insertion evaluation
    def taillard_insert_makespan(base_perm, job, pos):
        k = len(base_perm)
        # Forward matrix e[r][m] for base_perm[0..k-1]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = base_perm[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job_r][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job_r][m]
        # Backward matrix q[r][m] for base_perm[r..k-1]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = base_perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job_r][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
        # Evaluate insertion at position pos
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev_e = e[pos-1][m] if pos > 0 else 0
                f[m] = prev_e + p[job][m]
            else:
                prev_f = f[m-1]
                prev_e = e[pos-1][m] if pos > 0 else 0
                f[m] = max(prev_f, prev_e) + p[job][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    def neh_construction():
        # Sort jobs by total processing time descending
        order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N < 2:
            return order[:]
        # Initial two jobs
        best_start = [order[0], order[1]]
        best_rev = [order[1], order[0]]
        if makespan(best_rev) < makespan(best_start):
            best_start = best_rev
        perm = best_start[:]
        # Insert remaining jobs
        for idx in range(2, N):
            job = order[idx]
            best_pos = 0
            best_makespan = taillard_insert_makespan(perm, job, 0)
            for pos in range(1, idx+1):
                msp = taillard_insert_makespan(perm, job, pos)
                if msp < best_makespan:
                    best_makespan = msp
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(initial_perm, max_iter=60):
        current = initial_perm[:]
        best = current[:]
        best_makespan = makespan(current)
        total_processing = sum(total_p)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2  # Destruction size

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in sorted(indices, reverse=True)]
            for i in sorted(indices, reverse=True):
                del current[i]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                best_pos = 0
                best_msp = taillard_insert_makespan(current, job, 0)
                for pos in range(1, len(current)+1):
                    msp = taillard_insert_makespan(current, job, pos)
                    if msp < best_msp:
                        best_msp = msp
                        best_pos = pos
                current.insert(best_pos, job)
            # Acceptance criterion
            curr_makespan = makespan(current)
            if curr_makespan < best_makespan:
                best = current[:]
                best_makespan = curr_makespan
            if curr_makespan < makespan(best):  # current is better than best, should be caught above
                best = current[:]
                best_makespan = curr_makespan
            elif curr_makespan == makespan(best):
                pass  # keep current best
            else:
                # Metropolis acceptance
                delta = curr_makespan - makespan(best)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    best = current[:]  # accept current as new base for next iteration
        return best

    # Build initial solution and refine
    init_perm = neh_construction()
    # Quick makespan check for potential early termination
    init_makespan = makespan(init_perm)
    # Refine with Iterated Greedy
    refined_perm = iterated_greedy(init_perm, max_iter=50)
    return refined_perm

