                        f[m] = max(f[m-1], prev) + times[job][m]
                cmax_local = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax_local:
                        cmax_local = val
                if cmax_local < best_cmax_local:
                    best_cmax_local = cmax_local
                    best_pos = i
            destroyed.insert(best_pos, job)
        # New solution after reconstruction
        new_solution = destroyed
        new_cmax = makespan(new_solution)
        # Acceptance criterion
        if new_cmax < makespan(current_solution):
            current_solution = new_solution
            if new_cmax < best_cmax:
                best_solution = new_solution[:]
                best_cmax = new_cmax
        else:
            delta = new_cmax - makespan(current_solution)
            if random.random() < math.exp(-delta / T):
                current_solution = new_solution
    return best_solution

