def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for faster access
    proc = [times[i] for i in range(N)]

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            pj = proc[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[-1]

    # Initial solution using NEH with Taillard acceleration
    def neh_taillard():
        # Sort jobs by total processing time descending
        total = [sum(p) for p in proc]
        order = sorted(range(N), key=lambda i: total[i], reverse=True)
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        # Start with first two jobs
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_mk = float('inf')
            # Precompute forward completion matrix e for current seq
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                pj = proc[seq[r]]
                if r == 0:
                    e[0][0] = pj[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + pj[m]
                else:
                    e[r][0] = e[r-1][0] + pj[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
            # Precompute backward tail matrix q for current seq
            q = [[0] * M for _ in range(k+1)]  # q[k][*] = 0
            for r in range(k-1, -1, -1):
                pj = proc[seq[r]]
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
            # Evaluate each insertion position
            for i in range(k+1):
                # Compute forward vector f for inserting job at position i
                f = [0] * M
                if i == 0:
                    # e[-1][m] = 0
                    f[0] = proc[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + proc[job][m]
                else:
                    pj = proc[job]
                    e_im1 = e[i-1]
                    f[0] = e_im1[0] + pj[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e_im1[m]) + pj[m]
                # Compute makespan: max_m (f[m] + q[i][m])
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size d=3
    def iterated_greedy(init_seq, max_iters=50):
        current = init_seq[:]
        best = init_seq[:]
        best_mk = makespan(best)
        total_processing = sum(sum(p) for p in proc)
        T = 0.5 * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3
        no_improve = 0
        for _ in range(max_iters):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            remaining = [current[i] for i in range(N) if i not in indices]
            # Reconstruction: reinsert removed jobs one by one using NEH insertion (Taillard style)
            for job in removed:
                best_pos = 0
                best_mk_local = float('inf')
                k = len(remaining)
                if k == 0:
                    remaining = [job]
                    continue
                # Precompute forward completion matrix e for remaining
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    pj = proc[remaining[r]]
                    if r == 0:
                        e[0][0] = pj[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + pj[m]
                    else:
                        e[r][0] = e[r-1][0] + pj[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
                # Precompute backward tail matrix q for remaining
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    pj = proc[remaining[r]]
                    q[r][M-1] = q[r+1][M-1] + pj[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
                # Evaluate insertion positions
                for i in range(k+1):
                    f = [0] * M
                    if i == 0:
                        f[0] = proc[job][0]
                        for m in range(1, M):
                            f[m] = f[m-1] + proc[job][m]
                    else:
                        pj = proc[job]
                        e_im1 = e[i-1]
                        f[0] = e_im1[0] + pj[0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e_im1[m]) + pj[m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_local:
                        best_mk_local = mk
                        best_pos = i
                remaining.insert(best_pos, job)
            current = remaining
            mk = makespan(current)
            # Acceptance criterion
            if mk < best_mk:
                best = current[:]
                best_mk = mk
                no_improve = 0
            elif mk < makespan(init_seq):  # Always accept if better than initial
                current = current[:]
                no_improve = 0
            else:
                if random.random() < math.exp(-(mk - makespan(current)) / T):
                    current = current[:]
                else:
                    # Revert to previous current (not accepted)
                    pass
                no_improve += 1
            if no_improve > 10:
                break
        return best

    # Generate initial solution
    init_seq = neh_taillard()
    # Apply iterated greedy refinement
    improved_seq = iterated_greedy(init_seq, max_iters=40)
    return improved_seq

