    job_data = [list(t) for t in times]
    total_times = [sum(job) for job in job_data]

    # --- NEH Construction with Taillard Acceleration ---
    def makespan_neh(perm):
        if not perm:
            return 0
        e = [0] * M
        for idx in perm:
            t = job_data[idx]
            e[0] += t[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + t[m]
        return e[-1]

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0]*M]
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            t = job_data[perm[r]]
            if r == 0:
                e[0][0] = t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + t[m]
            else:
                e[r][0] = e[r-1][0] + t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + t[m]
        return e

    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0]*M for _ in range(k+1)]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            t = job_data[perm[r]]
            q[r][M-1] = q[r+1][M-1] + t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + t[m]
        return q

    def insertion_makespan(e_prev, f_vec, q_row):
        best = 0
        for m in range(M):
            val = f_vec[m] + q_row[m]
            if val > best:
                best = val
        return best

    # NEH: sort by total processing time descending
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    if N >= 2:
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        perm = seq0 if makespan_neh(seq0) <= makespan_neh(seq1) else seq1
    else:
        perm = [order[0]]

    for k in range(2, N):
        job = order[k]
        e_mat = compute_forward(perm)
        q_mat = compute_backward(perm)
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            # forward vector for insertion at i
            if i == 0:
                f_prev = [0]*M
            else:
                f_prev = e_mat[i-1]
            f_vec = [0]*M
            t = job_data[job]
            f_vec[0] = f_prev[0] + t[0]
            for m in range(1, M):
                f_vec[m] = max(f_vec[m-1], f_prev[m]) + t[m]
            mk = insertion_makespan(f_vec, f_vec, q_mat[i])
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        perm.insert(best_pos, job)

    # --- Iterated Greedy Refinement ---
    def makespan(perm):
        if not perm:
            return 0
        e = [0] * M
        for idx in perm:
            t = job_data[idx]
            e[0] += t[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + t[m]
        return e[-1]

    current = perm[:]
    best_perm = current[:]
    best_mk = makespan(current)
    total_load = sum(total_times)
    T_param = 0.5
    T = T_param * total_load / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
    max_iters = 60

    for _ in range(max_iters):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        # Build destroyed sequence keeping original order
        destroyed = [current[i] for i in range(N) if i not in indices]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        seq = destroyed[:]
        for job in removed:
            # Compute forward and backward for current seq
            e_mat = compute_forward(seq)
            q_mat = compute_backward(seq)
            best_pos = 0
            best_mk = float('inf')
            for i in range(len(seq)+1):
                if i == 0:
                    f_prev = [0]*M
                else:
                    f_prev = e_mat[i-1]
                f_vec = [0]*M
                t = job_data[job]
                f_vec[0] = f_prev[0] + t[0]
                for m in range(1, M):
                    f_vec[m] = max(f_vec[m-1], f_prev[m]) + t[m]
                mk = insertion_makespan(f_vec, f_vec, q_mat[i])
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        # Acceptance
        mk_new = makespan(seq)
        if mk_new < best_mk:
            best_mk = mk_new
            best_perm = seq[:]
        if mk_new < makespan(current) or random.random() < math.exp(-(mk_new - makespan(current)) / T):
            current = seq[:]

    return best_perm

