def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = [sum(row) for row in times]
    jobs = sorted(range(N), key=lambda i: total_processing[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    def taillard_makespan(seq):
        if not seq:
            return 0
        e = [0] * M
        for job in seq:
            f = [0] * M
            for m in range(M):
                if m == 0:
                    f[m] = e[m] + times[job][m]
                else:
                    f[m] = max(f[m-1], e[m]) + times[job][m]
            e = f
        return e[-1]

    def evaluate_insertion_taillard(partial, job, pos):
        k = len(partial)
        e = [0] * M
        if pos > 0:
            for idx in range(pos):
                job_idx = partial[idx]
                for m in range(M):
                    if m == 0:
                        e[m] = e[m] + times[job_idx][m]
                    else:
                        e[m] = max(e[m-1], e[m]) + times[job_idx][m]
        f = [0] * M
        for m in range(M):
            if m == 0:
                f[m] = (e[m] if pos > 0 else 0) + times[job][m]
            else:
                f[m] = max(f[m-1], (e[m] if pos > 0 else 0)) + times[job][m]
        q = [0] * M
        if pos < k:
            for idx in range(k-1, pos-1, -1):
                job_idx = partial[idx]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[m] = q[m] + times[job_idx][m]
                    else:
                        q[m] = max(q[m], q[m+1]) + times[job_idx][m]
        max_val = 0
        for m in range(M):
            val = f[m] + q[m]
            if val > max_val:
                max_val = val
        return max_val

    def neh_construct():
        if len(jobs) < 2:
            return jobs[:]
        seq0 = [jobs[0], jobs[1]]
        seq1 = [jobs[1], jobs[0]]
        if taillard_makespan(seq0) <= taillard_makespan(seq1):
            current = seq0[:]
        else:
            current = seq1[:]
        for idx in range(2, len(jobs)):
            job = jobs[idx]
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(current) + 1):
                m = evaluate_insertion_taillard(current, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            current.insert(best_pos, job)
        return current

    def destroy_and_reconstruct(seq, d):
        if d >= len(seq):
            return neh_construct()
        indices = random.sample(range(len(seq)), d)
        indices.sort(reverse=True)
        removed = [seq.pop(i) for i in indices]
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(seq) + 1):
                m = evaluate_insertion_taillard(seq, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    current = neh_construct()
    best = current[:]
    best_makespan = taillard_makespan(best)
    total = sum(total_processing)
    T_param = 0.5
    T = T_param * total / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 60
    for _ in range(max_iter):
        d = 3 if random.random() < 0.5 else 4
        candidate = destroy_and_reconstruct(current[:], d)
        candidate_makespan = taillard_makespan(candidate)
        if candidate_makespan < taillard_makespan(current):
            current = candidate
            if candidate_makespan < best_makespan:
                best = candidate[:]
                best_makespan = candidate_makespan
        elif candidate_makespan < best_makespan and random.random() < math.exp(-(candidate_makespan - taillard_makespan(current)) / T):
            current = candidate
            best = candidate[:]
            best_makespan = candidate_makespan
        elif candidate_makespan < best_makespan:
            current = candidate
    return best

