        t = [0] * M
        for job in seq:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[M-1]

    def calc_totals():
        return [sum(job) for job in times]

    def calc_slopes():
        slopes = [0] * N
        for i in range(N):
            s = 0
            for j in range(M):
                s += (2 * j - M + 1) * times[i][j]
            slopes[i] = s
        return slopes

    def taillard_insertion(partial, job, e, q, k):
        f = [0] * M
        if k == 0:
            f[0] = times[job][0]
            for m in range(1, M):
