        for idx, job in enumerate(perm):
            job_start = job * m
            for mc in range(m):
                p = flat[job_start + mc]
                if idx == 0 and mc == 0:
                    e[idx][mc] = p
                elif idx == 0:
                    e[idx][mc] = e[idx][mc - 1] + p
                elif mc == 0:
                    e[idx][mc] = e[idx - 1][mc] + p
                else:
                    e[idx][mc] = max(e[idx - 1][mc], e[idx][mc - 1]) + p
        return e[len(perm) - 1][m - 1]

    # NEH construction with Taillard acceleration
    def neh_construct(priority):
        perm = [priority[0]]
