    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-9:
        T = 1e-9

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_times[m]
        return t[-1]

    P = [sum(row) for row in times]
    sigma = sorted(range(N), key=lambda i: P[i], reverse=True)

    def makespan_neh_insert(partial, x):
        k = len(partial)
        if k == 0:
            return times[x][0] if M > 0 else 0
        e = [[0] * M for _ in range(k)]
        r0 = partial[0]
        e[0][0] = times[r0][0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + times[r0][m]
        for r in range(1, k):
            job_r = partial[r]
            e[r][0] = e[r-1][0] + times[job_r][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job_r][m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            q[r][M-1] = q[r+1][M-1] + times[job_r][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
        best_cmax = float('inf')
        best_pos = 0
        for i in range(k+1):
            if i == 0:
                f0 = times[x][0]
            else:
                f0 = e[i-1][0] + times[x][0]
            f = [0] * M
            f[0] = f0
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + times[x][m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_cmax

