    if N >= 2:
        job0, job1 = sigma[0], sigma[1]
        c01 = makespan_neh_insert([job0], job1)
        c10 = makespan_neh_insert([job1], job0)
        if c01 <= c10:
            pi = [job0, job1]
        else:
            pi = [job1, job0]
    else:
        pi = [sigma[0]]

    for idx in range(2, N):
        job = sigma[idx]
        pi = pi[:]  # copy
        pos = 0
        best_cmax = makespan_neh_insert(pi, job)
        for i in range(1, len(pi)+1):
            cmax = makespan_neh_insert(pi, job)
            if cmax < best_cmax:
                best_cmax = cmax
                pos = i
            if i < len(pi):
                pi = pi[:i] + [job] + pi[i:]
        pi = pi[:pos] + [job] + pi[pos:]

    pi_star = pi[:]
    c_star = makespan(pi)
    c_current = c_star
    max_iter = 60
    for _ in range(max_iter):
        d = 3 if N > 5 else N
