        indices.sort(reverse=True)
        R = []
        for idx in indices:
            R.append(pi.pop(idx))
        while R:
            job = R.pop(random.randrange(len(R)))
            best_cmax = float('inf')
            best_pos = 0
            for pos in range(len(pi)+1):
