                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = pos
            pi = pi[:best_pos] + [job] + pi[best_pos:]
        c_new = makespan(pi)
        if c_new < c_current:
            c_current = c_new
            if c_new < c_star:
                c_star = c_new
                pi_star = pi[:]
        else:
            if random.random() < math.exp(-(c_new - c_current) / T):
                c_current = c_new
                pi = pi[:]
    return pi_star

