        e = compute_forward(current)
        q = compute_backward(current)
        for job in removed:
            pos = insert_best_partial(current, job, e, q)
            current.insert(pos, job)
            e = compute_forward(current)
            q = compute_backward(current)
        ms = makespan(current)
        if ms < best_ms:
            best_ms = ms
            best_seq = current[:]
        if ms < makespan(current):
            current = current[:]
        elif random.random() < math.exp(-(ms - makespan(current)) / T):
            pass
        else:
            current = best_seq[:]

    return best_seq

