def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total = [sum(job) for job in times]
    slope = []
    for i in range(N):
        s = 0
        for j in range(M):
            s += (2 * j - M + 1) * times[i][j]
        slope.append(s)

    # Create job orders: NEH (total descending), Palmer (slope descending)
    order_NEH = sorted(range(N), key=lambda i: (-total[i], i))
    order_Palmer = sorted(range(N), key=lambda i: (-slope[i], i))

    # Taillard-accelerated makespan evaluation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        e = [0] * M
        for job in perm:
            t = times[job]
            e[0] += t[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + t[m]
        return e[-1]

    # NEH construction with Taillard acceleration for a given job order
    def neh_construct(job_order):
        if not job_order:
            return []
        perm = [job_order[0]]
        if len(job_order) == 1:
            return perm
        # Evaluate first two jobs
        seq1 = [job_order[0], job_order[1]]
        seq2 = [job_order[1], job_order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        # Greedy insertion for remaining jobs
        for idx in range(2, len(job_order)):
            job = job_order[idx]
            k = len(perm)
            # Forward matrix e: completion times of current perm
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                t = times[perm[r]]
                if r == 0:
                    e[0][0] = t[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + t[m]
                else:
                    e[r][0] = e[r-1][0] + t[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + t[m]
            # Backward matrix q: tail times
            q = [[0] * M for _ in range(k+1)]
            # q[k][m] = 0 already
            for r in range(k-1, -1, -1):
                t = times[perm[r]]
                q[r][M-1] = q[r+1][M-1] + t[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + t[m]
            # Evaluate insertion positions
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Forward vector f for job at position i
                f = [0] * M
                if i == 0:
                    f[0] = t[0]
                    for m in range(1, M):
                        f[m] = f[m-1] + t[m]
                else:
                    f[0] = e[i-1][0] + t[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + t[m]
                # Compute makespan: max_m (f[m] + q[i][m])
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with destruction size d=3
    def iterated_greedy(initial_perm, max_iter=50):
        current = initial_perm[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing = sum(total)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        d = 3
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build partial sequence without removed jobs
            removed_set = set(indices)
            partial = [current[i] for i in range(N) if i not in removed_set]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                k = len(partial)
                # Forward matrix e for partial
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    t = times[partial[r]]
                    if r == 0:
                        e[0][0] = t[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + t[m]
                    else:
                        e[r][0] = e[r-1][0] + t[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + t[m]
                # Backward matrix q
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    t = times[partial[r]]
                    q[r][M-1] = q[r+1][M-1] + t[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + t[m]
                # Find best insertion position for job
                best_pos = 0
                best_mk_ins = float('inf')
                t_job = times[job]
                for i in range(k+1):
                    # Forward vector f
                    f = [0] * M
                    if i == 0:
                        f[0] = t_job[0]
                        for m in range(1, M):
                            f[m] = f[m-1] + t_job[m]
                    else:
                        f[0] = e[i-1][0] + t_job[0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + t_job[m]
                    # Compute makespan
                    mk_ins = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk_ins:
                            mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                partial.insert(best_pos, job)
            # Acceptance criterion
            new_mk = makespan(partial)
            if new_mk < makespan(current):
                current = partial[:]
                if new_mk < best_mk:
                    best = partial[:]
                    best_mk = new_mk
            else:
                if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                    current = partial[:]
        return best

    # Try both NEH and Palmer orders, pick best initial solution
    perm_NEH = neh_construct(order_NEH)
    perm_Palmer = neh_construct(order_Palmer)
    mk_NEH = makespan(perm_NEH)
    mk_Palmer = makespan(perm_Palmer)
    if mk_NEH <= mk_Palmer:
        initial = perm_NEH
    else:
        initial = perm_Palmer

    # Apply Iterated Greedy refinement
    result = iterated_greedy(initial, max_iter=40)
    return result

