def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    P = [sum(job) for job in times]
    sigma = sorted(range(N), key=lambda i: P[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for idx in perm:
            job = times[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def makespan_taillard(perm):
        if not perm:
            return 0
        e = [0] * M
        for idx in perm:
            job = times[idx]
            e[0] += job[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + job[m]
        return e[-1]

    def compute_forward_backward(perm):
        k = len(perm)
        e = [[0] * M for _ in range(k)]
        if k > 0:
            job0 = times[perm[0]]
            e[0][0] = job0[0]
            for m in range(1, M):
                e[0][m] = e[0][m-1] + job0[m]
            for r in range(1, k):
                job = times[perm[r]]
                e[r][0] = e[r-1][0] + job[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job[m]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = times[perm[r]]
            q[r][M-1] = q[r+1][M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job[m]
        return e, q

    def insert_job_taillard(e, q, job, i, M):
        if i == 0:
            f0 = job[0]
            f = [f0]
            for m in range(1, M):
                f.append(max(f[m-1], 0) + job[m])
        else:
            f0 = e[i-1][0] + job[0]
            f = [f0]
            for m in range(1, M):
                f.append(max(f[m-1], e[i-1][m]) + job[m])
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_taillard():
        if N < 2:
            return sigma[:]
        best_perm = None
        best_ms = float('inf')
        for first, second in [(sigma[0], sigma[1]), (sigma[1], sigma[0])]:
            perm = [first, second]
            ms = makespan_taillard(perm)
            if ms < best_ms:
                best_ms = ms
                best_perm = perm[:]
        for k in range(2, N):
            job_idx = sigma[k]
            job = times[job_idx]
            e, q = compute_forward_backward(best_perm)
            best_pos = 0
            best_ms = float('inf')
            for i in range(k+1):
                ms = insert_job_taillard(e, q, job, i, M)
                if ms < best_ms:
                    best_ms = ms
                    best_pos = i
            best_perm.insert(best_pos, job_idx)
        return best_perm

    def destruction_construction(perm, d):
        if d >= len(perm):
            return neh_taillard()
        indices = random.sample(range(len(perm)), d)
        removed = [perm[i] for i in indices]
        remaining = [perm[i] for i in range(len(perm)) if i not in indices]
        random.shuffle(removed)
        for job in removed:
            e, q = compute_forward_backward(remaining)
            best_pos = 0
            best_ms = float('inf')
            for i in range(len(remaining)+1):
                ms = insert_job_taillard(e, q, times[job], i, M)
                if ms < best_ms:
                    best_ms = ms
                    best_pos = i
            remaining.insert(best_pos, job)
        return remaining

    current = neh_taillard()
    best = current[:]
    best_ms = makespan_taillard(best)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T <= 0:
        T = 1e-6
    max_iter = 60
    for _ in range(max_iter):
        d = 3 if N > 20 else 2
        candidate = destruction_construction(current, d)
        cand_ms = makespan_taillard(candidate)
        if cand_ms < makespan_taillard(current):
            current = candidate[:]
            if cand_ms < best_ms:
                best = candidate[:]
                best_ms = cand_ms
        elif cand_ms < best_ms:
            current = candidate[:]
            best = candidate[:]
            best_ms = cand_ms
        else:
            if random.random() < math.exp(-(cand_ms - makespan_taillard(current)) / T):
                current = candidate[:]
    return best

