            job_r = perm[r]
            for mc in range(m):
                if mc == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][mc] = prev + times[job_r][mc]
                else:
                    up = e[r-1][mc] if r > 0 else 0
                    left = e[r][mc-1]
                    e[r][mc] = max(up, left) + times[job_r][mc]
        # Backward matrix q[0..k][0..m-1]
        q = [[0] * m for _ in range(k+1)]
