            for mc in range(m-1, -1, -1):
                if mc == m-1:
                    down = q[r+1][mc]
                    q[r][mc] = down + times[job_r][mc]
                else:
                    down = q[r+1][mc]
                    right = q[r][mc+1]
                    q[r][mc] = max(down, right) + times[job_r][mc]
        # Evaluate insertion at pos
        f = [0] * m
        for mc in range(m):
            if mc == 0:
                prev_e = e[pos-1][0] if pos > 0 else 0
                f[mc] = prev_e + times[job][mc]
            else:
                left_f = f[mc-1]
                up_e = e[pos-1][mc] if pos > 0 else 0
                f[mc] = max(left_f, up_e) + times[job][mc]
        best = 0
        for mc in range(m):
            val = f[mc] + q[pos][mc]
            if val > best:
