                    best_pos = pos
            partial.insert(best_pos, job)
        # Acceptance
        new_mk = makespan(partial)
        if new_mk < makespan(current):
            current = partial[:]
            if new_mk < best_mk:
                best = partial[:]
                best_mk = new_mk
        elif new_mk < best_mk:
            current = partial[:]
            best = partial[:]
            best_mk = new_mk
        else:
            if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                current = partial[:]

    return best

