        if pos == 0:
            for m in range(M):
                f[m] = times[job_idx][m]
        else:
            e_prev = e[pos-1]
            row = times[job_idx]
            f[0] = e_prev[0] + row[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + row[m]
        q_pos = q[pos]
        max_val = 0
        for m in range(M):
            val = f[m] + q_pos[m]
            if val > max_val:
                max_val = val
        return max_val

    def construct_initial():
        order = sorted(range(N), key=lambda i: P[i], reverse=True)
        if N <= 1:
            return order[:]
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        for k in range(2, N):
            job = order[k]
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_mk = makespan_insert(e, q, job, 0)
            for pos in range(1, k+1):
                mk = makespan_insert(e, q, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    def destroy_and_reconstruct(seq, d):
        if d <= 0 or d >= N:
            return seq[:]
        indices = random.sample(range(N), d)
        indices_set = set(indices)
        remaining = [seq[i] for i in range(N) if i not in indices_set]
        extracted = [seq[i] for i in indices]
        random.shuffle(extracted)
        for job in extracted:
            e = compute_forward(remaining)
            q = compute_backward(remaining)
            best_pos = 0
            best_mk = makespan_insert(e, q, job, 0)
            for pos in range(1, len(remaining)+1):
                mk = makespan_insert(e, q, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            remaining.insert(best_pos, job)
        return remaining

    current = construct_initial()
    best = current[:]
    best_mk = makespan(best)
    T0 = 0.5 * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    T = T0
    max_iter = 60
    for it in range(max_iter):
        d = 3 if N > 20 else 2
        candidate = destroy_and_reconstruct(current, d)
        mk_candidate = makespan(candidate)
        if mk_candidate < makespan(current):
            current = candidate
            if mk_candidate < best_mk:
                best = candidate[:]
                best_mk = mk_candidate
        else:
            delta = mk_candidate - makespan(current)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current = candidate
        T *= 0.95
        if best_mk == 0:
            break
    return best

