def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_times = [times[i] for i in range(n)]
    total_time = [sum(job) for job in job_times]

    # Makespan calculation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * m
        for job in seq:
            p = job_times[job]
            t[0] += p[0]
            for j in range(1, m):
                t[j] = max(t[j-1], t[j]) + p[j]
        return t[-1]

    # Taillard acceleration: compute forward matrix e for a sequence
    def compute_e(seq):
        k = len(seq)
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            p = job_times[seq[r]]
            for j in range(m):
                if r == 0:
                    e[r][j] = (e[r][j-1] if j > 0 else 0) + p[j]
                else:
                    e[r][j] = max(e[r-1][j], e[r][j-1] if j > 0 else 0) + p[j]
        return e

    # Taillard acceleration: compute backward matrix q for a sequence
    def compute_q(seq):
        k = len(seq)
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            p = job_times[seq[r]]
            for j in range(m-1, -1, -1):
                if j == m-1:
                    q[r][j] = q[r+1][j] + p[j]
                else:
                    q[r][j] = max(q[r+1][j], q[r][j+1]) + p[j]
        return q

    # Evaluate makespan when inserting job x at position i in seq using Taillard
    def evaluate_insertion(seq, e, q, x, i):
        p = job_times[x]
        f = [0] * m
        # Compute forward vector f for job x after prefix seq[0:i]
        for j in range(m):
            if i == 0:
                prev_e = 0
            else:
                prev_e = e[i-1][j]
            if j == 0:
                f[j] = prev_e + p[j]
            else:
                f[j] = max(f[j-1], prev_e) + p[j]
        # Compute makespan: max over j of f[j] + q[i][j]
        max_val = 0
        for j in range(m):
            val = f[j] + q[i][j]
            if val > max_val:
                max_val = val
        return max_val

    # NEH construction with Taillard acceleration
    def neh_construction():
        # Sort jobs by total processing time descending
        order = sorted(range(n), key=lambda i: total_time[i], reverse=True)
        if n == 0:
            return []
        seq = [order[0]]
        if n == 1:
            return seq
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Insert remaining jobs
        for k in range(2, n):
            job = order[k]
            e = compute_e(seq)
            q = compute_q(seq)
            best_pos = 0
            best_makespan = float('inf')
            # Try all insertion positions
            for i in range(len(seq) + 1):
                cmax = evaluate_insertion(seq, e, q, job, i)
                if cmax < best_makespan:
                    best_makespan = cmax
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(initial_seq, max_iter=50):
        current_seq = initial_seq[:]
        best_seq = initial_seq[:]
        best_makespan = makespan(best_seq)
        total_processing = sum(total_time)
        T_param = 0.5
        T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
        d = 3 if n >= 3 else n

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            if d > 0:
                indices = random.sample(range(len(current_seq)), d)
                removed = [current_seq[i] for i in sorted(indices, reverse=True)]
                for idx in sorted(indices, reverse=True):
                    del current_seq[idx]
            else:
                removed = current_seq[:]
                current_seq = []

            # Reconstruction: reinsert removed jobs one by one using NEH insertion
            for job in removed:
                e = compute_e(current_seq)
                q = compute_q(current_seq)
                best_pos = 0
                best_makespan_insert = float('inf')
                for i in range(len(current_seq) + 1):
                    cmax = evaluate_insertion(current_seq, e, q, job, i)
                    if cmax < best_makespan_insert:
                        best_makespan_insert = cmax
                        best_pos = i
                current_seq.insert(best_pos, job)

            # Acceptance criterion
            current_makespan = makespan(current_seq)
            if current_makespan < best_makespan:
                best_makespan = current_makespan
                best_seq = current_seq[:]
            if current_makespan < makespan(initial_seq):  # Always accept if better than current
                # current_seq is already updated
                pass
            else:
                # Metropolis acceptance
                delta = current_makespan - makespan(initial_seq)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    # Accept current_seq (already set)
                    pass
                else:
                    # Reject: revert to initial_seq for this iteration
                    current_seq = initial_seq[:]

        return best_seq

    # Build initial solution
    initial_seq = neh_construction()
    # Apply iterated greedy refinement
    refined_seq = iterated_greedy(initial_seq, max_iter=40)
    return refined_seq

