                else:
                    f[0] = e[i-1][0] + p[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + p[job][m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk_local:
                    best_mk_local = mk
                    best_pos = i
            current_D = current_D[:best_pos] + [job] + current_D[best_pos:]
        current = current_D
        mk = makespan(current)
        if mk < best_mk:
            best_mk = mk
            best = current[:]
        if mk < makespan(best):
            current = current[:]
        else:
            if random.random() < math.exp(-(mk - makespan(best)) / T):
                current = current[:]
    return best

