        removed = [current_pi[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del current_pi[idx]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            current_pi = taillard_insert(current_pi, job)
        # Acceptance criterion
        current_makespan = makespan(current_pi)
        if current_makespan < best_makespan:
            best_makespan = current_makespan
            pi_best = current_pi[:]
        if current_makespan < makespan(pi):
            pi = current_pi[:]
        else:
            if random.random() < math.exp(-(current_makespan - makespan(pi)) / T):
                pi = current_pi[:]
            else:
                current_pi = pi[:]

    return pi_best

