def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data as flat lists for fast access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]

    # Beam search parameters
    K = 2  # Beam width
    d = 3  # Destruction size for IG
    max_iter = 50  # Max IG iterations
    T_param = 0.5  # Temperature parameter

    # Helper: makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Helper: Taillard accelerated insertion makespan evaluation
    def insertion_makespan(partial, job_idx):
        k = len(partial)
        if k == 0:
            return p[job_idx][-1]  # Makespan of single job
        # Forward matrix e (k x M)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job][m]
        # Backward matrix q ((k+1) x M)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]
        # Evaluate each insertion position
        best_cmax = float('inf')
        for i in range(k+1):
            # Forward pass for job_idx up to position i-1
            f = [0] * M
            for m in range(M):
                if m == 0:
                    prev_e = e[i-1][m] if i > 0 else 0
                    f[m] = prev_e + p[job_idx][m]
                else:
                    prev_e = e[i-1][m] if i > 0 else 0
                    f[m] = max(f[m-1], prev_e) + p[job_idx][m]
            # Combine with tail
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
        return best_cmax

    # Constructive phase: beam search with NEH ordering
    order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
    beam = [([order[0]], makespan([order[0]]))]  # (perm, makespan)
    for idx in range(1, N):
        job = order[idx]
        candidates = []
        for perm, _ in beam:
            for pos in range(len(perm)+1):
                new_perm = perm[:pos] + [job] + perm[pos:]
                cmax = makespan(new_perm)
                candidates.append((new_perm, cmax))
        # Prune to top K
        candidates.sort(key=lambda x: x[1])
        beam = candidates[:K]
    # Best from beam
    current = min(beam, key=lambda x: x[1])[0]
    best = current[:]
    best_cmax = makespan(best)

    # Iterated Greedy refinement
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        remaining = [current[i] for i in range(N) if i not in indices]
        # Reconstruction: reinsert each removed job using Taillard acceleration
        for job in removed:
            best_pos = 0
            best_cmax_local = float('inf')
            for pos in range(len(remaining)+1):
                cmax = insertion_makespan(remaining[:pos] + [job] + remaining[pos:], job)
                if cmax < best_cmax_local:
                    best_cmax_local = cmax
                    best_pos = pos
            remaining = remaining[:best_pos] + [job] + remaining[best_pos:]
        # Acceptance criterion
        new_cmax = makespan(remaining)
        if new_cmax < makespan(current):
            current = remaining[:]
            if new_cmax < best_cmax:
                best = remaining[:]
                best_cmax = new_cmax
        elif new_cmax < best_cmax:
            # Metropolis acceptance
            avg_p = sum(total_p) / (N * M)
            T = T_param * avg_p / 10.0
            if T > 0 and random.random() < math.exp(-(new_cmax - makespan(current)) / T):
                current = remaining[:]
    return best

