def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    P = [0] * N
    for i in range(N):
        row = times[i]
        s = 0
        for j in range(M):
            s += row[j]
        P[i] = s
        total_processing += s

    order = list(range(N))
    order.sort(key=lambda i: P[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for idx in perm:
            job = times[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def makespan_taillard(perm, e=None, q=None):
        k = len(perm)
        if k == 0:
            return 0
        if e is None or q is None:
            e = [[0] * M for _ in range(k)]
            q = [[0] * M for _ in range(k+1)]
        for r in range(k):
            job = times[perm[r]]
            if r == 0:
                e[0][0] = job[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job[m]
            else:
                e[r][0] = e[r-1][0] + job[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job[m]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = times[perm[r]]
            q[r][M-1] = q[r+1][M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job[m]
        return e[k-1][M-1]

    def insertion_cost_taillard(job_idx, perm, e, q):
        k = len(perm)
        if k == 0:
            return times[job_idx][0] if M == 1 else (sum(times[job_idx][:1]) if M == 1 else 0)
        f = [0] * M
        job = times[job_idx]
        if k == 0:
            f[0] = job[0]
            for m in range(1, M):
                f[m] = f[m-1] + job[m]
        else:
            i = 0
            f[0] = (e[i-1][0] if i-1 >= 0 else 0) + job[0]
            for m in range(1, M):
                f[m] = max(f[m-1], (e[i-1][m] if i-1 >= 0 else 0)) + job[m]
        best_cmax = float('inf')
        for i in range(0, k+1):
            if i > 0:
                job = times[job_idx]
                f[0] = (e[i-1][0] if i-1 >= 0 else 0) + job[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], (e[i-1][m] if i-1 >= 0 else 0)) + job[m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_i = i
        return best_cmax, best_i

    def construct_initial():
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        perm = [order[0], order[1]]
        c1 = makespan_taillard(perm)
        perm2 = [order[1], order[0]]
        c2 = makespan_taillard(perm2)
        if c2 < c1:
            perm = perm2
        e = [[0] * M for _ in range(2)]
        q = [[0] * M for _ in range(3)]
        makespan_taillard(perm, e, q)
        for k in range(2, N):
            job_idx = order[k]
            _, pos = insertion_cost_taillard(job_idx, perm, e, q)
            perm.insert(pos, job_idx)
            e = [[0] * M for _ in range(k+1)]
            q = [[0] * M for _ in range(k+2)]
            makespan_taillard(perm, e, q)
        return perm

    def destroy_and_reconstruct(perm, d):
        if d >= len(perm):
            return perm[:]
        indices = random.sample(range(len(perm)), d)
        indices_set = set(indices)
        remaining = [perm[i] for i in range(len(perm)) if i not in indices_set]
        removed = [perm[i] for i in indices]
        e = [[0] * M for _ in range(len(remaining))] if remaining else []
        q = [[0] * M for _ in range(len(remaining)+1)] if remaining else []
        if remaining:
            makespan_taillard(remaining, e, q)
        for job_idx in removed:
            _, pos = insertion_cost_taillard(job_idx, remaining, e, q)
            remaining.insert(pos, job_idx)
            e = [[0] * M for _ in range(len(remaining))]
            q = [[0] * M for _ in range(len(remaining)+1)]
            if remaining:
                makespan_taillard(remaining, e, q)
        return remaining

    current = construct_initial()
    current_makespan = makespan_taillard(current)
    best = current[:]
    best_makespan = current_makespan

    sum_pt = total_processing
    T_param = 0.5
    T = T_param * sum_pt / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    max_iter = 60
    if N > 60:
        max_iter = 40
    if N > 100:
        max_iter = 30

    for _ in range(max_iter):
        new_perm = destroy_and_reconstruct(current, d)
        new_makespan = makespan_taillard(new_perm)
        if new_makespan < current_makespan or random.random() < math.exp(-(new_makespan - current_makespan) / T):
            current = new_perm
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best = new_perm[:]
                best_makespan = new_makespan
    return best

