        else:
            f[0] = e[pos-1][0] + get_time(job, 0)
            for m in range(1, M_val):
                f[m] = max(f[m-1], e[pos-1][m]) + get_time(job, m)
        best = float('inf')
        for m in range(M_val):
            val = f[m] + q[pos][m]
            if val < best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    def construct_initial():
        order = sorted(range(N), key=lambda i: job_totals[i], reverse=True)
        if N < 2:
            return order[:]
        # Initial two jobs
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        perm = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        # Preallocate matrices
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N+1)]
        for k in range(2, N):
            job = order[k]
            # Forward pass for current perm (length k)
            for r in range(k):
                job_r = perm[r]
                if r == 0:
                    e[r][0] = get_time(job_r, 0)
                else:
                    e[r][0] = e[r-1][0] + get_time(job_r, 0)
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + get_time(job_r, m)
            # Backward pass
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = perm[r]
                q[r][M-1] = q[r+1][M-1] + get_time(job_r, M-1)
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + get_time(job_r, m)
            # Find best insertion position
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                mk = evaluate_insertion(perm, job, i, e, q)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with Taillard-accelerated reinsertion
    def iterated_greedy(initial_perm, max_iters=60):
        current = initial_perm[:]
        best = current[:]
        best_mk = makespan(best)
        total_proc = sum(job_totals)
        T = 0.5 * total_proc / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2
        if d < 2:
            d = 2
        # Preallocate matrices for reuse
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N+1)]
        for it in range(max_iters):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            indices_set = set(indices)
            # Build partial sequence (remaining jobs in order)
            partial = [current[i] for i in range(N) if i not in indices_set]
            k = len(partial)
            # Rebuild forward matrix for partial
            for r in range(k):
                job_r = partial[r]
                if r == 0:
                    e[r][0] = get_time(job_r, 0)
                else:
                    e[r][0] = e[r-1][0] + get_time(job_r, 0)
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + get_time(job_r, m)
            # Rebuild backward matrix for partial
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = partial[r]
                q[r][M-1] = q[r+1][M-1] + get_time(job_r, M-1)
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + get_time(job_r, m)
            # Reinsert each removed job using Taillard acceleration
            for job in removed:
                best_pos = 0
                best_mk_ins = float('inf')
                for i in range(k+1):
                    mk_ins = evaluate_insertion(partial, job, i, e, q)
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                partial.insert(best_pos, job)
                k += 1
            # New candidate sequence
            candidate = partial
            mk_candidate = makespan(candidate)
            # Acceptance criterion
            if mk_candidate < makespan(current):
                current = candidate
                if mk_candidate < best_mk:
                    best = candidate[:]
                    best_mk = mk_candidate
            else:
                if random.random() < math.exp(-(mk_candidate - makespan(current)) / T):
                    current = candidate
        return best

    # Build initial solution and refine
    init_perm = construct_initial()
    return iterated_greedy(init_perm, max_iters=50)

