def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times for faster access
    proc = [row[:] for row in times]

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            pj = proc[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[-1]

    # Taillard acceleration: compute forward matrix e for current partial schedule
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            pj = proc[perm[r]]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + pj[m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + pj[m]
        return e

    # Taillard acceleration: compute backward tail matrix q for current partial schedule
    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]  # q[k][*] = 0
        for r in range(k-1, -1, -1):
            pj = proc[perm[r]]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + pj[m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    # Evaluate makespan for inserting job x at position i in current perm of length k
    def insertion_makespan(perm, x, i, e, q):
        k = len(perm)
        pj = proc[x]
        # Compute forward vector f for job x up to machine m
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev_e = e[i-1][m] if i-1 >= 0 else 0
                f[m] = prev_e + pj[m]
            else:
                prev_f = f[m-1]
                prev_e = e[i-1][m] if i-1 >= 0 else 0
                f[m] = max(prev_f, prev_e) + pj[m]
        # Compute makespan candidate: max over m of f[m] + q[i][m]
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    def neh_construction():
        # Job priority: total processing time descending
        job_sums = [sum(proc[i]) for i in range(N)]
        order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
        if N == 0:
            return []
        # Start with first two jobs
        perm = [order[0], order[1]]
        best2 = makespan(perm)
        rev2 = [order[1], order[0]]
        if makespan(rev2) < best2:
            perm = rev2
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            e = compute_forward(perm)
            q = compute_backward(perm)
            best_pos = 0
            best_val = insertion_makespan(perm, job, 0, e, q)
            for i in range(1, k+1):
                val = insertion_makespan(perm, job, i, e, q)
                if val < best_val:
                    best_val = val
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_perm):
        # Parameters
        d = 3 if N >= 3 else N
        T_param = 0.5
        total_proc = sum(sum(row) for row in proc)
        T = T_param * total_proc / (10 * N * M) if N * M > 0 else 1e-6
        max_iter = 60  # calibrated to stay within time budget

        current = initial_perm[:]
        best = initial_perm[:]
        best_makespan = makespan(best)

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            if d == 0:
                destroyed = []
                remaining = current[:]
            else:
                indices = random.sample(range(N), d)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(N) if i not in indices_set]
            # Reconstruction: reinsert destroyed jobs one by one using NEH insertion with Taillard
            for job in destroyed:
                e = compute_forward(remaining)
                q = compute_backward(remaining)
                best_pos = 0
                best_val = insertion_makespan(remaining, job, 0, e, q)
                for i in range(1, len(remaining)+1):
                    val = insertion_makespan(remaining, job, i, e, q)
                    if val < best_val:
                        best_val = val
                        best_pos = i
                remaining.insert(best_pos, job)
            # New candidate solution
            candidate = remaining
            candidate_makespan = makespan(candidate)
            # Acceptance criterion
            if candidate_makespan < makespan(current):
                current = candidate
                if candidate_makespan < best_makespan:
                    best = candidate[:]
                    best_makespan = candidate_makespan
            else:
                if makespan(current) > 0:
                    delta = candidate_makespan - makespan(current)
                    prob = math.exp(-delta / T)
                    if random.random() < prob:
                        current = candidate
        return best

    # Build initial solution and refine
    initial = neh_construction()
    return iterated_greedy(initial)

