def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    if n == 1:
        return [0]
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times for NEH priority
    total_times = [sum(job) for job in times]
    order = sorted(range(n), key=lambda i: total_times[i], reverse=True)

    # Helper: makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            job_t = times[job]
            t[0] += job_t[0]
            for k in range(1, m):
                t[k] = max(t[k-1], t[k]) + job_t[k]
        return t[-1]

    # Helper: compute forward matrix e for a given permutation
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * m]
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job_t = times[perm[r]]
            if r == 0:
                e[0][0] = job_t[0]
                for mc in range(1, m):
                    e[0][mc] = e[0][mc-1] + job_t[mc]
            else:
                e[r][0] = e[r-1][0] + job_t[0]
                for mc in range(1, m):
                    e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + job_t[mc]
        return e

    # Helper: compute backward tail matrix q for a given permutation
    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * m]
        q = [[0] * m for _ in range(k+1)]
        # q[k][:] already 0
        for r in range(k-1, -1, -1):
            job_t = times[perm[r]]
            q[r][m-1] = q[r+1][m-1] + job_t[m-1]
            for mc in range(m-2, -1, -1):
                q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + job_t[mc]
        return q

    # NEH construction with Taillard acceleration
    def neh_construction():
        if n == 0:
            return []
        # Start with first two jobs
        best_perm = [order[0], order[1]]
        best_mk = makespan(best_perm)
        alt_perm = [order[1], order[0]]
        alt_mk = makespan(alt_perm)
        if alt_mk < best_mk:
            best_perm, best_mk = alt_perm, alt_mk
        # Insert remaining jobs
        for idx in range(2, n):
            job = order[idx]
            k = idx  # current partial schedule length
            e = compute_forward(best_perm)
            q = compute_backward(best_perm)
            best_pos = 0
            best_mk_insert = float('inf')
            # Try all insertion positions 0..k
            for pos in range(k+1):
                # Compute forward vector f for inserting job at pos
                f = [0] * m
                if pos == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[pos-1]
                f[0] = prev_e[0] + times[job][0]
                for mc in range(1, m):
                    f[mc] = max(f[mc-1], prev_e[mc]) + times[job][mc]
                # Makespan if inserted at pos: max over m of f[mc] + q[pos][mc]
                mk = 0
                for mc in range(m):
                    val = f[mc] + q[pos][mc]
                    if val > mk:
                        mk = val
                if mk < best_mk_insert:
                    best_mk_insert = mk
                    best_pos = pos
            # Insert job at best_pos
            best_perm.insert(best_pos, job)
        return best_perm

    # Iterated Greedy with Metropolis acceptance
    def iterated_greedy(initial_perm):
        current = initial_perm[:]
        current_mk = makespan(current)
        best_perm = current[:]
        best_mk = current_mk
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
        d = 3 if n >= 3 else n
        max_iters = 60  # calibrated for <50ms
        for _ in range(max_iters):
            # Destruction: remove d random jobs
            indices = list(range(n))
            random.shuffle(indices)
            removed_indices = indices[:d]
            removed_indices.sort(reverse=True)
            removed_jobs = []
            for idx in removed_indices:
                removed_jobs.append(current.pop(idx))
            # Reconstruction: reinsert each removed job using NEH insertion (Taillard accelerated)
            for job in removed_jobs:
                k = len(current)
                if k == 0:
                    current.append(job)
                    continue
                e = compute_forward(current)
                q = compute_backward(current)
                best_pos = 0
                best_mk_insert = float('inf')
                for pos in range(k+1):
                    if pos == 0:
                        prev_e = [0] * m
                    else:
                        prev_e = e[pos-1]
                    f = [0] * m
                    f[0] = prev_e[0] + times[job][0]
                    for mc in range(1, m):
                        f[mc] = max(f[mc-1], prev_e[mc]) + times[job][mc]
                    mk = 0
                    for mc in range(m):
                        val = f[mc] + q[pos][mc]
                        if val > mk:
                            mk = val
                    if mk < best_mk_insert:
                        best_mk_insert = mk
                        best_pos = pos
                current.insert(best_pos, job)
            new_mk = makespan(current)
            # Acceptance
            if new_mk < current_mk:
                current = current[:]
                current_mk = new_mk
                if new_mk < best_mk:
                    best_perm = current[:]
                    best_mk = new_mk
            else:
                if random.random() < math.exp(-(new_mk - current_mk) / T):
                    current = current[:]
                    current_mk = new_mk
        return best_perm

    # Run NEH then IG
    initial_perm = neh_construction()
    return iterated_greedy(initial_perm)

