def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(row) for row in times)
    lower_bound = 0
    for m in range(M):
        min_before = min(times[i][:m] for i in range(N)) if m > 0 else 0
        min_after = min(times[i][m+1:] for i in range(N)) if m < M-1 else 0
        lb_m = sum(min_before) + sum(times[i][m] for i in range(N)) + sum(min_after)
        if lb_m > lower_bound:
            lower_bound = lb_m

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + times[job][m]
        return t[-1]

    psum = [sum(row) for row in times]
    order = sorted(range(N), key=lambda i: psum[i], reverse=True)

    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N+1)]

    def makespan_with_tail(partial, job):
        k = len(partial)
        for r in range(k):
            job_r = partial[r]
            if r == 0:
                e[r][0] = times[job_r][0]
            else:
                e[r][0] = e[r-1][0] + times[job_r][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job_r][m]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            q[r][M-1] = q[r+1][M-1] + times[job_r][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
        best_ms = float('inf')
        best_pos = 0
        for i in range(k+1):
            if i == 0:
                f0 = times[job][0]
            else:
                f0 = e[i-1][0] + times[job][0]
            f = [f0]
            for m in range(1, M):
                f.append(max(f[m-1], e[i-1][m]) + times[job][m])
            ms = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > ms:
                    ms = val
            if ms < best_ms:
                best_ms = ms
                best_pos = i
        return best_ms, best_pos

    perm = []
    for idx in order:
        if not perm:
            perm.append(idx)
        else:
            _, pos = makespan_with_tail(perm, idx)
            perm.insert(pos, idx)
            if len(perm) > 2 and makespan(perm) == lower_bound:
                return perm

    best_perm = perm[:]
    best_ms = makespan(best_perm)
    if best_ms == lower_bound:
        return best_perm

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iters = 50
    no_improve_limit = 10
    no_improve = 0
    current_perm = perm[:]
    current_ms = best_ms

    for it in range(max_iters):
        if no_improve >= no_improve_limit:
            break
        indices = list(range(N))
        random.shuffle(indices)
        removed = []
        remaining = current_perm[:]
        for _ in range(d):
            if not remaining:
                break
            idx_in_rem = random.randrange(len(remaining))
            job = remaining.pop(idx_in_rem)
            removed.append(job)
        for job in removed:
            _, pos = makespan_with_tail(remaining, job)
            remaining.insert(pos, job)
        new_ms = makespan(remaining)
        if new_ms < current_ms or random.random() < math.exp(-(new_ms - current_ms) / T):
            current_perm = remaining
            current_ms = new_ms
            if new_ms < best_ms:
                best_perm = current_perm[:]
                best_ms = new_ms
                no_improve = 0
                if best_ms == lower_bound:
                    break
            else:
                no_improve += 1
        else:
            no_improve += 1

    return best_perm

