                q[r][M-1] = q[r+1][M-1] + times[perm[r]][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[perm[r]][m]
            # Insert job using Taillard
            pos, _ = taillard_insert(perm, job, e, q)
            perm.insert(pos, job)
        return perm

    # Generate two candidate orders: total time descending and slope descending
    order_total = sorted(range(N), key=lambda i: (-total_times[i], i))
    order_slope = sorted(range(N), key=lambda i: (-slope[i], i))

    perm_total = construct_neh(order_total)
    perm_slope = construct_neh(order_slope)

    # Choose better initial solution
    if makespan(perm_slope) < makespan(perm_total):
        current = perm_slope[:]
    else:
        current = perm_total[:]
    best = current[:]
    best_cmax = makespan(best)

    # Compute lower bound for early termination
    lb = 0
    for m in range(M):
        min_before = min(times[i][m] for i in range(N)) if m > 0 else 0
        min_after = min(times[i][m] for i in range(N)) if m < M-1 else 0
        sum_m = sum(times[i][m] for i in range(N))
        lb_candidate = min_before + sum_m + min_after
        if lb_candidate > lb:
            lb = lb_candidate
    if best_cmax == lb:
        return best

    # Iterated Greedy parameters
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    # Preallocate lists for destruction/reconstruction
    extracted = [0] * d
    remaining = [0] * (N - d)

    for it in range(max_iter):
        # Destruction: randomly extract d jobs
        indices = list(range(N))
        random.shuffle(indices)
        for i in range(d):
            extracted[i] = current[indices[i]]
        rem_idx = 0
        for i in range(d, N):
            remaining[rem_idx] = current[indices[i]]
            rem_idx += 1

        # Reconstruction: reinsert extracted jobs one by one using NEH with Taillard
        # Reconstruct e and q incrementally as we build the sequence
        perm = remaining[:N-d]  # current partial sequence
        if not perm:
            perm = []
        # Reinsert each extracted job
        for job in extracted[:d]:
            k = len(perm)
            if k == 0:
                perm = [job]
                continue
            # Resize e and q as needed (max size N)
            if len(e) < k+1:
                e.extend([[0]*M for _ in range(N - len(e))])
                q.extend([[0]*M for _ in range(N+1 - len(q))])
            # Compute forward matrix e for current perm
            for r in range(k):
                if r == 0:
                    e[r][0] = times[perm[r]][0]
                else:
                    e[r][0] = e[r-1][0] + times[perm[r]][0]
                for m in range(1, M):
                    if r == 0:
                        e[r][m] = e[r][m-1] + times[perm[r]][m]
                    else:
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + times[perm[r]][m]
            # Compute backward tail matrix q
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                q[r][M-1] = q[r+1][M-1] + times[perm[r]][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[perm[r]][m]
            # Insert job
            pos, _ = taillard_insert(perm, job, e, q)
            perm.insert(pos, job)
        # New candidate solution
        candidate = perm
        cand_cmax = makespan(candidate)
        # Acceptance criterion
        if cand_cmax < makespan(current):
            current = candidate[:]
            if cand_cmax < best_cmax:
                best = candidate[:]
                best_cmax = cand_cmax
                no_improve = 0
                if best_cmax == lb:
                    break
            else:
                no_improve += 1
        else:
            delta = cand_cmax - makespan(current)
            if random.random() < math.exp(-delta / T):
                current = candidate[:]
                no_improve += 1
            else:
                no_improve += 1
        if no_improve >= no_improve_limit:
            break

    return best

