def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for fast access
    p = [row[:] for row in times]

    # Total processing time per job for NEH priority
    total_p = [sum(job) for job in p]
    jobs_sorted = sorted(range(N), key=lambda i: total_p[i], reverse=True)

    # Makespan evaluation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            tj = p[job]
            t[0] += tj[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + tj[m]
        return t[-1]

    # Taillard's acceleration: forward matrix e for prefix perm[0:k]
    def compute_forward(prefix):
        k = len(prefix)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = prefix[r]
            pj = p[job]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    # Taillard's acceleration: backward matrix q for suffix perm[k:]
    def compute_backward(prefix):
        k = len(prefix)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already by initialization
        for r in range(k-1, -1, -1):
            job = prefix[r]
            pj = p[job]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    # NEH construction with Taillard acceleration
    def neh_construction():
        if N == 0:
            return []
        perm = [jobs_sorted[0]]
        for k in range(1, N):
            job = jobs_sorted[k]
            best_pos = 0
            best_mk = float('inf')
            e = compute_forward(perm)
            q = compute_backward(perm)
            for i in range(k+1):
                # forward vector f for inserting job at position i
                f = [0] * M
                if i == 0:
                    f[0] = p[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + p[job][m]
                else:
                    prev = e[i-1]
                    f[0] = prev[0] + p[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev[m]) + p[job][m]
                # makespan if job inserted at i: max_m (f[m] + q[i][m])
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with destruction size d=3 or 4
    def iterated_greedy(initial_perm, max_iters=60):
        current = initial_perm[:]
        best = current[:]
        best_mk = makespan(best)
        total = sum(total_p)
        T = 0.5 * total / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N <= 30 else 4
        for _ in range(max_iters):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build partial sequence without removed jobs
            removed_set = set(removed)
            partial = [job for job in current if job not in removed_set]
            # Reconstruction: reinsert removed jobs one by one using NEH insertion (Taillard accelerated)
            for job in removed:
                best_pos = 0
                best_mk_ins = float('inf')
                e = compute_forward(partial)
                q = compute_backward(partial)
                k = len(partial)
                for i in range(k+1):
                    f = [0] * M
                    if i == 0:
                        f[0] = p[job][0]
                        for m in range(1, M):
                            f[m] = f[m-1] + p[job][m]
                    else:
                        prev = e[i-1]
                        f[0] = prev[0] + p[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], prev[m]) + p[job][m]
                    mk_ins = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk_ins:
                            mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                partial.insert(best_pos, job)
            # Acceptance criterion
            new_mk = makespan(partial)
            if new_mk < makespan(current):
                current = partial[:]
                if new_mk < best_mk:
                    best = partial[:]
                    best_mk = new_mk
            elif new_mk < best_mk:
                current = partial[:]
                best = partial[:]
                best_mk = new_mk
            else:
                if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                    current = partial[:]
        return best

    # Run NEH then IG
    init_perm = neh_construction()
    return iterated_greedy(init_perm)

