    def makespan(perm):
        if not perm:
            return 0
        # Initialize first job
        e[0][0] = times[perm[0]][0]
        for m in range(1, M):
            e[0][m] = e[0][m - 1] + times[perm[0]][m]
        # Process remaining jobs
        for i in range(1, len(perm)):
            job = perm[i]
            e[i][0] = e[i - 1][0] + times[job][0]
            for m in range(1, M):
                e[i][m] = max(e[i - 1][m], e[i][m - 1]) + times[job][m]
        return e[len(perm) - 1][M - 1]

    # NEH construction with Taillard acceleration
    perm = [order[0], order[1]]
    if makespan([order[1], order[0]]) < makespan(perm):
        perm = [order[1], order[0]]

    for k in range(2, N):
        job = order[k]
        best_pos = 0
        best_mk = float('inf')

        # Forward pass: compute e for current perm[0:k]
        e[0][0] = times[perm[0]][0]
        for m in range(1, M):
            e[0][m] = e[0][m - 1] + times[perm[0]][m]
        for i in range(1, k):
            e[i][0] = e[i - 1][0] + times[perm[i]][0]
            for m in range(1, M):
                e[i][m] = max(e[i - 1][m], e[i][m - 1]) + times[perm[i]][m]

        # Backward pass: compute q for current perm[0:k]
        for m in range(M):
            q[k][m] = 0
        for i in range(k - 1, -1, -1):
            job_i = perm[i]
            q[i][M - 1] = q[i + 1][M - 1] + times[job_i][M - 1]
