                fm = max(f[m - 1], prev_e) + times[job][m]
                f.append(fm)
            # Compute makespan candidate
            mk = 0
            for m in range(M):
                val = f[m] + q[pos][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = pos
        perm.insert(best_pos, job)

    # Iterated Greedy refinement
    current = perm[:]
    best = current[:]
    best_mk = makespan(best)
    total_processing = sum(total)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N > 5 else N
