        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        seq = destroyed[:]
        for job in removed:
            best_pos = 0
            best_mk_ins = float('inf')
            L = len(seq)
            # Forward pass for current seq
            if L > 0:
                e[0][0] = times[seq[0]][0]
                for m in range(1, M):
                    e[0][m] = e[0][m - 1] + times[seq[0]][m]
                for i in range(1, L):
                    e[i][0] = e[i - 1][0] + times[seq[i]][0]
                    for m in range(1, M):
                        e[i][m] = max(e[i - 1][m], e[i][m - 1]) + times[seq[i]][m]
            # Backward pass for current seq
            for m in range(M):
                q[L][m] = 0
            for i in range(L - 1, -1, -1):
                job_i = seq[i]
                q[i][M - 1] = q[i + 1][M - 1] + times[job_i][M - 1]
                for m in range(M - 2, -1, -1):
                    q[i][m] = max(q[i + 1][m], q[i][m + 1]) + times[job_i][m]
            # Try all insertion positions
            for pos in range(L + 1):
                if pos == 0:
                    f0 = times[job][0]
                else:
                    f0 = e[pos - 1][0] + times[job][0]
                f = [f0]
                for m in range(1, M):
                    if pos == 0:
                        prev_e = 0
                    else:
                        prev_e = e[pos - 1][m]
                    fm = max(f[m - 1], prev_e) + times[job][m]
                    f.append(fm)
                mk = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > mk:
                        mk = val
                if mk < best_mk_ins:
                    best_mk_ins = mk
                    best_pos = pos
            seq.insert(best_pos, job)
        # Evaluate new solution
        new_mk = makespan(seq)
        # Acceptance criterion
        if new_mk < makespan(current) or random.random() < math.exp(-(new_mk - makespan(current)) / T):
            current = seq
            if new_mk < best_mk:
                best = seq[:]
                best_mk = new_mk

    return best

