def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = [sum(job) for job in times]
    jobs_sorted = sorted(range(N), key=lambda i: total_processing[i], reverse=True)

    p = times

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[M-1]

    def forward_backward(partial):
        k = len(partial)
        if k == 0:
            return [], [ [0]*M for _ in range(k+1) ]
        e = [ [0]*M for _ in range(k) ]
        for m in range(M):
            e[0][m] = p[partial[0]][m] if m == 0 else max(e[0][m-1], 0) + p[partial[0]][m]
        for r in range(1, k):
            e[r][0] = e[r-1][0] + p[partial[r]][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + p[partial[r]][m]
        q = [ [0]*M for _ in range(k+1) ]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            q[r][M-1] = q[r+1][M-1] + p[partial[r]][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[partial[r]][m]
        return e, q

    def insert_job(partial, job, e, q):
        k = len(partial)
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = p[job][0]
            else:
                f0 = e[i-1][0] + p[job][0]
            f = [f0]
            for m in range(1, M):
                val = e[i-1][m] if i-1 >= 0 else 0
                f.append(max(f[m-1], val) + p[job][m])
            cmax = 0
            for m in range(M):
                cand = f[m] + q[i][m]
                if cand > cmax:
                    cmax = cand
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return partial[:best_pos] + [job] + partial[best_pos:], best_cmax

    current = [jobs_sorted[0]]
    for idx in range(1, N):
        job = jobs_sorted[idx]
        e, q = forward_backward(current)
        current, _ = insert_job(current, job, e, q)

    best_seq = current[:]
    best_cmax = makespan(current)

    LB = 0
    for m in range(M):
        min_pre = min((sum(p[i][:m]) for i in range(N)), default=0)
        min_suf = min((sum(p[i][m+1:]) for i in range(N)), default=0)
        machine_sum = sum(p[i][m] for i in range(N))
        LB = max(LB, min_pre + machine_sum + min_suf)
    if best_cmax == LB:
        return best_seq

    T_param = 0.5
    avg_p = sum(total_processing) / (N * M)
    T = T_param * avg_p / (10.0)

    random.seed(42)
    max_iter = 60
    d = 3

    for _ in range(max_iter):
        if len(current) < d:
            destroyed = current[:]
            current = []
            R = destroyed[:]
        else:
            indices = random.sample(range(len(current)), d)
            R = [current[i] for i in indices]
            current = [current[i] for i in range(len(current)) if i not in indices]
        for job in R:
            e, q = forward_backward(current)
            current, _ = insert_job(current, job, e, q)
        curr_cmax = makespan(current)
        if curr_cmax < best_cmax:
            best_cmax = curr_cmax
            best_seq = current[:]
        if curr_cmax < makespan(current):
            pass
        if curr_cmax < makespan(best_seq):
            best_seq = current[:]
            best_cmax = curr_cmax
        if curr_cmax < makespan(current):
            pass
        if makespan(current) > curr_cmax:
            diff = makespan(current) - curr_cmax
            if random.random() < math.exp(-diff / T):
                pass
        if curr_cmax < makespan(current):
            pass
        if makespan(current) > curr_cmax and random.random() < math.exp(-(makespan(current) - curr_cmax) / T):
            pass
        if curr_cmax < makespan(best_seq):
            best_seq = current[:]
            best_cmax = curr_cmax

    return best_seq

