def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices for sorting
    P = [sum(job) for job in times]
    S = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Sort by total processing time descending (NEH primary), break ties by slope index descending
    order = sorted(range(N), key=lambda i: (-P[i], -S[i]))

    # Precompute lower bounds for early termination (Taillard's machine-based LB)
    sum_machine = [sum(times[i][m] for i in range(N)) for m in range(M)]
    LB = 0
    for m in range(M):
        min_prefix = min(sum(times[i][k] for k in range(m)) for i in range(N)) if m > 0 else 0
        min_suffix = min(sum(times[i][k] for k in range(m + 1, M)) for i in range(N)) if m < M - 1 else 0
        LB_m = min_prefix + sum_machine[m] + min_suffix
        if LB_m > LB:
            LB = LB_m

    # Makespan computation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m - 1], t[m]) + times[job][m]
        return t[-1]

    # Taillard-accelerated insertion: evaluates all positions in O(k*M)
    def insert_job_taillard(partial, job, e, q):
        k = len(partial)
        if k == 0:
            return [job]
        best_pos = 0
        best_mk = float('inf')
        for i in range(k + 1):
            # Compute forward vector f for inserting job at position i
            f = [0] * M
            if i == 0:
                f[0] = times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m - 1], 0) + times[job][m]
            else:
                f[0] = e[i - 1][0] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m - 1], e[i - 1][m]) + times[job][m]
            # Compute makespan candidate: max_m (f[m] + q[i][m])
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        # Insert job at best_pos
        return partial[:best_pos] + [job] + partial[best_pos:]

    # Construct initial solution using NEH with Taillard acceleration
    def construct_initial():
        if N == 0:
            return []
        partial = [order[0]]
        # Allocate e and q matrices with max size N x M
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N + 1)]
        for k in range(1, N):
            job = order[k]
            # Compute forward matrix e for current partial (length k)
            for r in range(k):
                if r == 0:
                    e[0][0] = times[partial[0]][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m - 1] + times[partial[0]][m]
                else:
                    e[r][0] = e[r - 1][0] + times[partial[r]][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r - 1][m], e[r][m - 1]) + times[partial[r]][m]
            # Compute backward tail matrix q for current partial (length k)
            for m in range(M):
                q[k][m] = 0
            for r in range(k - 1, -1, -1):
                q[r][M - 1] = q[r + 1][M - 1] + times[partial[r]][M - 1]
                for m in range(M - 2, -1, -1):
                    q[r][m] = max(q[r + 1][m], q[r][m + 1]) + times[partial[r]][m]
            # Insert job using Taillard's O(k*M) method
            partial = insert_job_taillard(partial, job, e, q)
        return partial

    pi = construct_initial()
    pi_star = pi[:]
    C_star = makespan(pi)
    if C_star == LB:
        return pi_star

    total_processing = sum(P)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3  # Destruction size
    max_iter = 60  # Iteration count tuned for <50ms

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        indices.sort(reverse=True)
        R = []
        pi_D = pi[:]
        for idx in indices:
            R.append(pi_D.pop(idx))
        random.shuffle(R)  # Randomize reinsertion order

        # Reconstruction: reinsert jobs using Taillard-accelerated NEH
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N + 1)]
        for job in R:
            k = len(pi_D)
            if k == 0:
                pi_D = [job]
                continue
            # Compute forward matrix e for current pi_D (length k)
            for r in range(k):
                if r == 0:
                    e[0][0] = times[pi_D[0]][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m - 1] + times[pi_D[0]][m]
                else:
                    e[r][0] = e[r - 1][0] + times[pi_D[r]][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r - 1][m], e[r][m - 1]) + times[pi_D[r]][m]
            # Compute backward tail matrix q for current pi_D (length k)
            for m in range(M):
                q[k][m] = 0
            for r in range(k - 1, -1, -1):
                q[r][M - 1] = q[r + 1][M - 1] + times[pi_D[r]][M - 1]
                for m in range(M - 2, -1, -1):
                    q[r][m] = max(q[r + 1][m], q[r][m + 1]) + times[pi_D[r]][m]
            # Insert job using Taillard's O(k*M) method
            pi_D = insert_job_taillard(pi_D, job, e, q)

        C_new = makespan(pi_D)
        if C_new < C_star:
            pi_star = pi_D[:]
            C_star = C_new
            if C_star == LB:
                break
        if C_new < makespan(pi):
            pi = pi_D[:]
        else:
            if random.random() < math.exp(-(C_new - makespan(pi)) / T):
                pi = pi_D[:]

    return pi_star

