def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Helper: makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Helper: Johnson's rule for two-machine flow shop
    def johnson_rule(p1, p2):
        n = len(p1)
        left, right = [], []
        indices = list(range(n))
        while indices:
            min_val = float('inf')
            min_job = -1
            min_machine = -1  # 0 for p1, 1 for p2
            for idx in indices:
                if p1[idx] < min_val:
                    min_val = p1[idx]
                    min_job = idx
                    min_machine = 0
                if p2[idx] < min_val:
                    min_val = p2[idx]
                    min_job = idx
                    min_machine = 1
            if min_machine == 0:
                left.append(min_job)
            else:
                right.append(min_job)
            indices.remove(min_job)
        right.reverse()
        return left + right

    # Generate CDS permutations
    best_perm = None
    best_makespan = float('inf')
    for l in range(1, M):
        p1 = [0] * N
        p2 = [0] * N
        for i in range(N):
            p1[i] = sum(times[i][:l])
            p2[i] = sum(times[i][M-l:])
        perm = johnson_rule(p1, p2)
        m = makespan(perm)
        if m < best_makespan:
            best_makespan = m
            best_perm = perm

    return best_perm

