    def makespan_neh(seq):
        if not seq:
            return 0
        e = [0] * M
        for job in seq:
            job_t = times[job]
            e[0] += job_t[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + job_t[m]
        return e[-1]

    def taillard_insert(seq, job):
        k = len(seq)
        if k == 0:
            return [job]
        e = [[0] * M for _ in range(k)]
        r0 = seq[0]
        job_r0 = times[r0]
        e[0][0] = job_r0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job_r0[m]
        for r in range(1, k):
            job_r = times[seq[r]]
            e[r][0] = e[r-1][0] + job_r[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = times[seq[r]]
            q[r][M-1] = q[r+1][M-1] + job_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            f = [0] * M
            if i == 0:
                f[0] = times[job][0]
                for m in range(1, M):
                    f[m] = f[m-1] + times[job][m]
            else:
                f[0] = e[i-1][0] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + times[job][m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return seq[:best_pos] + [job] + seq[best_pos:]

