        if cnew < makespan(pi):
            pi = pi_D
            if cnew < cbest:
                pi_best = pi_D[:]
                cbest = cnew
        else:
            if random.random() < math.exp(-(cnew - makespan(pi)) / T):
                pi = pi_D
    return pi_best

