def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_times = [sum(job) for job in times]
    slope_index = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Helper: makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Helper: makespan after inserting job x at position pos in current perm
    def makespan_with_insertion(perm, x, pos):
        k = len(perm)
        if k == 0:
            return times[x][0] if M == 1 else _makespan_single_job(x)
        # Forward pass up to pos-1
        f = [0] * M
        if pos > 0:
            f[0] = times[perm[0]][0]
            for m in range(1, M):
                f[m] = f[m-1] + times[perm[0]][m]
            for i in range(1, pos):
                job = perm[i]
                f[0] += times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m], f[m-1]) + times[job][m]
        # Process job x
        if pos == 0:
            fx = [0] * M
            fx[0] = times[x][0]
            for m in range(1, M):
                fx[m] = fx[m-1] + times[x][m]
        else:
            fx = [0] * M
            fx[0] = f[0] + times[x][0]
            for m in range(1, M):
                fx[m] = max(fx[m-1], f[m]) + times[x][m]
        # Backward pass from pos to end
        b = fx[:]
        for i in range(pos, k):
            job = perm[i]
            b[0] += times[job][0]
            for m in range(1, M):
                b[m] = max(b[m], b[m-1]) + times[job][m]
        return b[-1]

    def _makespan_single_job(x):
        t = 0
        for m in range(M):
            t += times[x][m]
        return t

    # NEH construction with slope-based tie-breaking
    order = sorted(range(N), key=lambda i: (-total_times[i], -slope_index[i]))
    perm = [order[0]]
    for idx in range(1, N):
        job = order[idx]
        best_pos = 0
        best_makespan = float('inf')
        for pos in range(len(perm) + 1):
            ms = makespan_with_insertion(perm, job, pos)
            if ms < best_makespan or (ms == best_makespan and pos < best_pos):
                best_makespan = ms
                best_pos = pos
        perm.insert(best_pos, job)

    # Iterated Greedy refinement
    random.seed(42)  # for deterministic behavior
    current = perm[:]
    best = perm[:]
    best_ms = makespan(best)
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 60
    d = 3 if N > 20 else 2

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del current[i]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_ms_local = float('inf')
            for pos in range(len(current) + 1):
                ms = makespan_with_insertion(current, job, pos)
                if ms < best_ms_local or (ms == best_ms_local and pos < best_pos):
                    best_ms_local = ms
                    best_pos = pos
            current.insert(best_pos, job)
        # Acceptance criterion
        curr_ms = makespan(current)
        if curr_ms < best_ms:
            best = current[:]
            best_ms = curr_ms
        if curr_ms < makespan(perm):
            perm = current[:]
        else:
            if random.random() < math.exp(-(curr_ms - makespan(perm)) / T):
                perm = current[:]
            else:
                current = perm[:]

    return best

