    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = [sum(times[i]) for i in range(N)]
    order = sorted(range(N), key=lambda i: total_processing[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = times[perm[0]][m] if m == 0 else (e[0][m-1] + times[perm[0]][m])
        for r in range(1, k):
            e[r][0] = e[r-1][0] + times[perm[r]][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + times[perm[r]][m]
        return e

    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = perm[r]
            q[r][M-1] = q[r+1][M-1] + times[job][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return q

    def makespan_insert(e, q, job, pos):
        f = [0] * M
        if pos == 0:
            for m in range(M):
                f[m] = times[job][m] if m == 0 else (f[m-1] + times[job][m])
        else:
            prev = e[pos-1]
            f[0] = prev[0] + times[job][0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev[m]) + times[job][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_construct():
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            job1, job2 = order[0], order[1]
            seq1 = [job1, job2]
            seq2 = [job2, job1]
            if makespan(seq1) <= makespan(seq2):
                seq = seq1
            else:
                seq = seq2
        for idx in range(2, len(order)):
            job = order[idx]
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_makespan = float('inf')
            best_idle = float('inf')
            for pos in range(len(seq) + 1):
                ms = makespan_insert(e, q, job, pos)
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
                    if pos == 0:
                        idle = 0
                    elif pos == len(seq):
                        idle = 0
                    else:
                        idle = max(0, e[pos-1][M-1] - (e[pos-1][M-2] if M > 1 else 0) - times[seq[pos-1]][M-1]) if M > 1 else 0
                    best_idle = idle
                elif ms == best_makespan:
                    if pos == 0:
                        idle = 0
                    elif pos == len(seq):
                        idle = 0
                    else:
                        idle = max(0, e[pos-1][M-1] - (e[pos-1][M-2] if M > 1 else 0) - times[seq[pos-1]][M-1]) if M > 1 else 0
                    if idle < best_idle:
                        best_pos = pos
                        best_idle = idle
            seq.insert(best_pos, job)
