    current = neh_construct()
    best = current[:]
    best_ms = makespan(best)

    total_sum = sum(total_processing)
    T_param = 0.5
    T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N > 5 else max(1, N // 2)
    max_iter = 60

    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            R = current[:]
        else:
            indices = random.sample(range(len(current)), d)
            indices.sort(reverse=True)
            R = [current[i] for i in indices]
            destroyed = current[:]
            for i in indices:
                destroyed.pop(i)
        pi_D = destroyed
        for job in R:
            if not pi_D:
                pi_D = [job]
                continue
            e = compute_forward(pi_D)
            q = compute_backward(pi_D)
            best_pos = 0
            best_makespan = float('inf')
            best_idle = float('inf')
            for pos in range(len(pi_D) + 1):
                ms = makespan_insert(e, q, job, pos)
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
                    if pos == 0:
                        idle = 0
                    elif pos == len(pi_D):
                        idle = 0
                    else:
                        idle = max(0, e[pos-1][M-1] - (e[pos-1][M-2] if M > 1 else 0) - times[pi_D[pos-1]][M-1]) if M > 1 else 0
                    best_idle = idle
                elif ms == best_makespan:
                    if pos == 0:
                        idle = 0
                    elif pos == len(pi_D):
                        idle = 0
                    else:
                        idle = max(0, e[pos-1][M-1] - (e[pos-1][M-2] if M > 1 else 0) - times[pi_D[pos-1]][M-1]) if M > 1 else 0
                    if idle < best_idle:
                        best_pos = pos
                        best_idle = idle
            pi_D.insert(best_pos, job)
        current = pi_D
        curr_ms = makespan(current)
        if curr_ms < best_ms:
            best_ms = curr_ms
            best = current[:]
        if curr_ms < makespan(best):
            if random.random() < math.exp(-(curr_ms - makespan(best)) / T):
                current = current[:]
        else:
            if random.random() < math.exp(-(curr_ms - makespan(current)) / T):
                current = current[:]

    return best

