    total_times = [sum(job) for job in times]
    slope_indices = [sum((2 * j - m + 1) * times[i][j] for j in range(m)) for i in range(n)]

    # Create initial permutation: sort by total time descending, then slope descending
    perm = list(range(n))
    perm.sort(key=lambda i: (-total_times[i], -slope_indices[i]))

