    def makespan(seq):
        t = [0] * m
        for job in seq:
            t[0] += times[job][0]
            for k in range(1, m):
                t[k] = max(t[k], t[k-1]) + times[job][k]
        return t[-1]

    current_makespan = makespan(perm)
    best_perm = perm[:]
    best_makespan = current_makespan

    # Bounded adjacent pairwise interchange (bubble-sort style descent)
    max_iterations = 200  # Conservative bound to stay within 50ms for N<=120, M<=20
    for _ in range(max_iterations):
        improved = False
        for i in range(n - 1):
            # Swap adjacent jobs at positions i and i+1
            perm[i], perm[i+1] = perm[i+1], perm[i]
            new_makespan = makespan(perm)
            if new_makespan < current_makespan:
                current_makespan = new_makespan
                improved = True
                if current_makespan < best_makespan:
                    best_makespan = current_makespan
                    best_perm = perm[:]
            else:
                # Revert swap if not improving
                perm[i], perm[i+1] = perm[i+1], perm[i]
        if not improved:
            break  # Local minimum reached

    return best_perm

