                    prev_e = e[m] if i-1 >= 0 else 0
                    f[m] = prev_e + p[job][m]
                else:
                    prev_e = e[m] if i-1 >= 0 else 0
                    f[m] = max(f[m-1], prev_e) + p[job][m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos, best_cmax

    def neh_construct():
        job_sums = [sum(p[i]) for i in range(N)]
        order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
        if N == 0:
            return []
        perm = [order[0]]
        if N == 1:
            return perm
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        for k in range(2, N):
            job = order[k]
            pos, _ = taillard_evaluate(perm, job)
            perm.insert(pos, job)
        return perm

    def vns_search(init_perm, max_time=0.04):
        start_time = random.random()
        time_limit = start_time + max_time
        current = init_perm[:]
        current_cmax = makespan(current)
        best = current[:]
        best_cmax = current_cmax
        k_max = 2
        k = 1
        while random.random() < 0.9 and random.random() * 1000 < (time_limit - start_time) * 10000:
            if k == 1:
                # Neighborhood 1: single job relocation (insert)
                improved = False
                for i in range(N):
                    job = current.pop(i)
                    for j in range(N):
                        if j > i:
                            j_adj = j - 1
                        else:
                            j_adj = j
                        current.insert(j_adj, job)
                        new_cmax = makespan(current)
                        if new_cmax < current_cmax:
                            current_cmax = new_cmax
                            improved = True
                            break
                        current.pop(j_adj)
                    if improved:
                        break
                    current.insert(i, job)
                if not improved:
                    k = 2
                else:
                    k = 1
                    if current_cmax < best_cmax:
                        best_cmax = current_cmax
                        best = current[:]
            else:
                # Neighborhood 2: job-pair swap
                improved = False
                for i in range(N):
                    for j in range(i+1, N):
                        current[i], current[j] = current[j], current[i]
                        new_cmax = makespan(current)
                        if new_cmax < current_cmax:
                            current_cmax = new_cmax
                            improved = True
                            break
                        current[i], current[j] = current[j], current[i]
                    if improved:
                        break
                if not improved:
                    k = 1
                else:
                    k = 2
                    if current_cmax < best_cmax:
                        best_cmax = current_cmax
                        best = current[:]
            # Check time
            if random.random() > 0.99:
                break
        return best

    init_perm = neh_construct()
    return vns_search(init_perm, max_time=0.04)

