import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for sorting
    total_times = [sum(job) for job in times]

    # NEH construction with Taillard acceleration
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job_idx in seq:
            job = times[job_idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def taillard_evaluate(partial, job_idx):
        k = len(partial)
        job = times[job_idx]
        # Forward matrix e (size k x M)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            pj = times[partial[r]]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        # Backward matrix q (size (k+1) x M)
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already
        for r in range(k-1, -1, -1):
            pj = times[partial[r]]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        best_val = float('inf')
        best_pos = 0
        for i in range(k+1):
            # forward vector f for insertion at position i
            f = [0] * M
            if i == 0:
                prev = [0] * M
            else:
                prev = e[i-1]
            f[0] = prev[0] + job[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev[m]) + job[m]
            # makespan = max_m (f[m] + q[i][m])
            val = 0
            for m in range(M):
                val = max(val, f[m] + q[i][m])
            if val < best_val:
                best_val = val
                best_pos = i
        return best_val, best_pos

    # Initial sequence via NEH
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    seq = [order[0]]
    for idx in order[1:]:
        _, pos = taillard_evaluate(seq, idx)
        seq.insert(pos, idx)

    # Iterated Greedy refinement
    current_seq = seq[:]
    best_seq = seq[:]
    best_makespan = makespan(best_seq)

    # Calculate temperature parameter
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-6:
        T = 1e-6

    # Number of iterations calibrated for <50ms
    max_iter = 60
    d = 3 if N > 20 else 2

    for _ in range(max_iter):
        # Destruction: remove d jobs at random positions
        if N <= d:
            destroyed = []
            removed_jobs = current_seq[:]
        else:
            positions = random.sample(range(N), d)
            positions.sort(reverse=True)
            removed_jobs = []
            for pos in positions:
                removed_jobs.append(current_seq.pop(pos))
            destroyed = current_seq  # current_seq is now the partial sequence

        # Reconstruction: reinsert removed jobs one by one using Taillard acceleration
        for job_idx in removed_jobs:
            _, pos = taillard_evaluate(destroyed, job_idx)
            destroyed.insert(pos, job_idx)

        new_seq = destroyed
        new_makespan = makespan(new_seq)

        # Acceptance criterion
        if new_makespan < makespan(current_seq):
            current_seq = new_seq
            if new_makespan < best_makespan:
                best_seq = new_seq[:]
                best_makespan = new_makespan
        else:
            if random.random() < math.exp(-(new_makespan - makespan(current_seq)) / T):
                current_seq = new_seq

    return best_seq

