def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_data = [list(t) for t in times]
    total_processing = [sum(job) for job in job_data]
    slope_index = [sum((2 * j - M + 1) * job[j] for j in range(M)) for job in job_data]

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            pj = job_data[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[-1]

    # Taillard acceleration: compute forward completion matrix e for prefix of length k
    def compute_forward(prefix):
        k = len(prefix)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            pj = job_data[prefix[r]]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    # Taillard acceleration: compute backward tail matrix q for prefix of length k
    def compute_backward(prefix):
        k = len(prefix)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pj = job_data[prefix[r]]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    # Insert a single job at position i using Taillard's O(M) evaluation
    def insert_job_evaluate(prefix, job, i):
        k = len(prefix)
        if k == 0:
            return job_data[job][0] if M == 1 else sum(job_data[job])
        e = compute_forward(prefix)
        q = compute_backward(prefix)
        f = [0] * M
        pj = job_data[job]
        if i == 0:
            f[0] = pj[0]
            for m in range(1, M):
                f[m] = f[m-1] + pj[m]
        else:
            f[0] = e[i-1][0] + pj[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + pj[m]
        best = float('inf')
        for m in range(M):
            val = f[m] + q[i][m]
            if val < best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    def construct_neh(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            seq1 = [order[0], order[1]]
            seq2 = [order[1], order[0]]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, len(order)):
            job = order[idx]
            best_pos = 0
            best_mk = float('inf')
            for pos in range(len(seq) + 1):
                mk = insert_job_evaluate(seq, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size 2 (block insertion heuristic)
    def iterated_greedy(initial_seq, max_iters=60):
        current = list(initial_seq)
        best = list(current)
        best_mk = makespan(best)
        total_work = sum(total_processing)
        T_param = 0.5
        T = T_param * total_work / (10 * N * M) if N * M > 0 else 1e-6
        d = 2  # destruction size: remove 2 jobs at a time

        for _ in range(max_iters):
            # Destruction: remove d random jobs
            if d >= len(current):
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(len(current)), d)
                indices.sort(reverse=True)
                destroyed = [current.pop(i) for i in indices]
                remaining = current[:]

            # Reconstruction: reinsert destroyed jobs one by one using NEH insertion
            for job in destroyed:
                if not remaining:
                    remaining.append(job)
                else:
                    best_pos = 0
                    best_mk_ins = float('inf')
                    for pos in range(len(remaining) + 1):
                        mk_ins = insert_job_evaluate(remaining, job, pos)
                        if mk_ins < best_mk_ins:
                            best_mk_ins = mk_ins
                            best_pos = pos
                    remaining.insert(best_pos, job)

            current = remaining
            mk = makespan(current)
            if mk < best_mk:
                best_mk = mk
                best = list(current)
            if mk < makespan(current):
                current = list(current)
            else:
                if mk < makespan(current):
                    current = list(current)
                else:
                    delta = mk - makespan(current)
                    if delta < 0 or random.random() < math.exp(-delta / T):
                        current = list(current)
                    else:
                        # Revert to previous current (not stored, so keep as is)
                        pass
        return best

    # Generate multiple initial solutions using different orderings
    order_total = sorted(range(N), key=lambda i: total_processing[i], reverse=True)
    order_slope = sorted(range(N), key=lambda i: slope_index[i], reverse=True)
    order_random = list(range(N))
    random.shuffle(order_random)

    best_overall = []
    best_mk_overall = float('inf')

    for order in [order_total, order_slope, order_random]:
        if not order:
            continue
        init_seq = construct_neh(order)
        mk_init = makespan(init_seq)
        if mk_init < best_mk_overall:
            best_mk_overall = mk_init
            best_overall = init_seq
        # Apply IG refinement
        refined_seq = iterated_greedy(init_seq, max_iters=40)
        mk_refined = makespan(refined_seq)
        if mk_refined < best_mk_overall:
            best_mk_overall = mk_refined
            best_overall = refined_seq

    return best_overall

