                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            current.insert(best_pos, job_idx)
            k += 1
            if k > 0:
                # Update e_cur and q_cur for the new current sequence
                r = k-1
                job_r = current[r]
                job_rp = p[job_r]
                if r == 0:
                    e_cur[r][0] = job_rp[0]
                else:
                    e_cur[r][0] = e_cur[r-1][0] + job_rp[0]
                for m in range(1, M):
                    e_cur[r][m] = max(e_cur[r-1][m], e_cur[r][m-1]) + job_rp[m]
