                for m in range(M-2, -1, -1):
                    q_cur[r][m] = max(q_cur[r+1][m], q_cur[r][m+1]) + job_rp[m]

        pi_new = current
        C_new = makespan(pi_new)
        if C_new < C_pi:
            pi = pi_new
            C_pi = C_new
            if C_new < C_star:
                pi_star = pi_new[:]
                C_star = C_new
        else:
            if random.random() < math.exp(-(C_new - C_pi) / T):
                pi = pi_new
                C_pi = C_new

    return pi_star

