    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data as flat lists for fast access
    p = [row[:] for row in times]
    P = [sum(row) for row in p]
    S = [sum((2 * j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]

    # Makespan evaluation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            tj = p[job]
            t[0] += tj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + tj[m]
        return t[-1]

    # Taillard's accelerated makespan for insertion at position pos in partial schedule
    def insertion_makespan(partial, x, pos):
        k = len(partial)
        # Forward matrix e[r][m] for partial schedule
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            pj = p[job]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        # Backward tail matrix q[r][m]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            pj = p[job]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        # Forward vector f for job x up to insertion point
        f = [0] * M
        if pos == 0:
            for m in range(M):
                f[m] = p[x][m]
        else:
            e_prev = e[pos-1]
            f[0] = e_prev[0] + p[x][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + p[x][m]
        # Compute makespan: max_m (f[m] + q[pos][m])
        makespan_val = 0
        q_pos = q[pos]
        for m in range(M):
            val = f[m] + q_pos[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration and multiple priority orders
    def neh_construction(priority):
        if len(priority) == 0:
            return []
        seq = [priority[0]]
        if len(priority) >= 2:
            # Try both orders for first two jobs
            seq1 = [priority[0], priority[1]]
            seq2 = [priority[1], priority[0]]
            if makespan(seq1) <= makespan(seq2):
                seq = seq1
            else:
                seq = seq2
        for idx in range(2, len(priority)):
            job = priority[idx]
            best_pos = 0
            best_mk = insertion_makespan(seq, job, 0)
            for pos in range(1, len(seq)+1):
                mk = insertion_makespan(seq, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Generate initial solution using multiple priority orders
    order1 = sorted(range(N), key=lambda i: (-P[i], i))
    order2 = sorted(range(N), key=lambda i: (-S[i], i))
    best_seq = neh_construction(order1)
    best_mk = makespan(best_seq)
    seq2 = neh_construction(order2)
    mk2 = makespan(seq2)
    if mk2 < best_mk:
        best_mk = mk2
        best_seq = seq2

    # Iterated Greedy (IG) refinement
    current = best_seq[:]
    current_mk = best_mk
    total_processing = sum(P)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
    max_iters = 60
    if N > 60:
        max_iters = 40
    if N > 100:
        max_iters = 30

    for _ in range(max_iters):
        # Destruction: remove d random jobs
        if d == 0:
            destroyed = current[:]
            R = []
        else:
            indices = random.sample(range(N), d)
            indices.sort(reverse=True)
            R = [current[i] for i in indices]
            destroyed = [current[i] for i in range(N) if i not in set(indices)]
        # Reconstruction: reinsert jobs in random order using Taillard-accelerated NEH
        random.shuffle(R)
        for job in R:
            best_pos = 0
            best_mk = insertion_makespan(destroyed, job, 0)
            for pos in range(1, len(destroyed)+1):
                mk = insertion_makespan(destroyed, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            destroyed.insert(best_pos, job)
        new_seq = destroyed
        new_mk = best_mk
        # Acceptance criterion
        if new_mk < current_mk:
            current = new_seq
            current_mk = new_mk
            if new_mk < best_mk:
                best_mk = new_mk
                best_seq = new_seq[:]
        elif new_mk < best_mk:
            # Accept with probability based on Metropolis
            if random.random() < math.exp(-(new_mk - current_mk) / T):
                current = new_seq
                current_mk = new_mk
            if new_mk < best_mk:
                best_mk = new_mk
                best_seq = new_seq[:]
        else:
            if random.random() < math.exp(-(new_mk - current_mk) / T):
                current = new_seq
                current_mk = new_mk

    return best_seq

