    total = [sum(job) for job in times]
    slope = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Function to compute makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[-1]

    # Function to compute forward completion matrix e for a partial schedule
    def compute_forward(perm):
        k = len(perm)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            job_t = times[job]
            if r == 0:
                e[0][0] = job_t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_t[m]
            else:
                e[r][0] = e[r-1][0] + job_t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
        return e

    # Function to compute backward tail matrix q for a partial schedule
    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            job_t = times[job]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        return q

    # Function to evaluate makespan when inserting job x at position i using Taillard's scheme
    def evaluate_insertion(e, q, x, i):
        job_t = times[x]
        f = [0] * M
        if i == 0:
            f[0] = job_t[0]
            for m in range(1, M):
                f[m] = f[m-1] + job_t[m]
        else:
            f[0] = e[i-1][0] + job_t[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + job_t[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Function to insert job x into partial schedule perm using Taillard acceleration
    def insert_job(perm, x):
        k = len(perm)
        if k == 0:
            return [x]
        e = compute_forward(perm)
        q = compute_backward(perm)
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            m = evaluate_insertion(e, q, x, i)
            if m < best_makespan:
                best_makespan = m
                best_pos = i
        return perm[:best_pos] + [x] + perm[best_pos:]

    # NEH construction with given job order
    def neh(order):
        if not order:
            return []
        seq = [order[0]]
        for idx in range(1, len(order)):
            seq = insert_job(seq, order[idx])
        return seq

    # Try multiple orderings: total time descending, slope descending
    orders = []
    order1 = sorted(range(N), key=lambda i: total[i], reverse=True)
    orders.append(order1)
    order2 = sorted(range(N), key=lambda i: slope[i], reverse=True)
    if order2 != order1:
        orders.append(order2)

    best_seq = None
    best_makespan = float('inf')
    for order in orders:
        seq = neh(order)
        m = makespan(seq)
        if m < best_makespan:
            best_makespan = m
            best_seq = seq

    # Iterated Greedy refinement
    current_seq = best_seq[:]
    current_makespan = best_makespan
    best_seq_ig = current_seq[:]
    best_makespan_ig = current_makespan

    # Calculate average processing time for temperature
    total_processing = sum(total)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

    destruction_size = 3 if N >= 3 else N
    max_iterations = 60

    for _ in range(max_iterations):
        # Destruction: remove destruction_size jobs at random positions
        if destruction_size > 0:
            positions = random.sample(range(N), destruction_size)
            positions.sort(reverse=True)
            removed_jobs = []
            for pos in positions:
                removed_jobs.append(current_seq.pop(pos))
            # Reconstruction: reinsert removed jobs in random order
            random.shuffle(removed_jobs)
            for job in removed_jobs:
                current_seq = insert_job(current_seq, job)
        # Evaluate new sequence
        m = makespan(current_seq)
        # Acceptance criterion
        if m < current_makespan:
            current_makespan = m
            if m < best_makespan_ig:
                best_makespan_ig = m
                best_seq_ig = current_seq[:]
        else:
            if random.random() < math.exp(-(m - current_makespan) / T):
                current_makespan = m
            # else: keep current_seq unchanged (rejection)

    return best_seq_ig

