                        left = e[r][mc-1]
                        e[r][mc] = max(up, left) + times[job_r][mc]
            # Precompute backward tail matrix q for current seq (length k)
            q = [[0] * m for _ in range(k+1)]  # q[k][*] = 0
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                for mc in range(m-1, -1, -1):
                    if mc == m-1:
                        down = q[r+1][mc]
                        q[r][mc] = down + times[job_r][mc]
                    else:
                        down = q[r+1][mc]
                        right = q[r][mc+1]
                        q[r][mc] = max(down, right) + times[job_r][mc]
            # Try inserting job at each position i in [0, k]
            for i in range(k+1):
                # Compute forward vector f for job at position i
                f = [0] * m
                for mc in range(m):
                    if mc == 0:
                        prev = e[i-1][0] if i > 0 else 0
                        f[mc] = prev + times[job][mc]
                    else:
                        left = f[mc-1]
                        up = e[i-1][mc] if i > 0 else 0
                        f[mc] = max(left, up) + times[job][mc]
                # Compute makespan if job inserted at i
                current_max = 0
                for mc in range(m):
                    val = f[mc] + q[i][mc]
                    if val > current_max:
                        current_max = val
                if current_max < best_makespan:
                    best_makespan = current_max
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Generate initial solution using NEH with total time order
    order_total = sorted(range(n), key=lambda i: total_times[i], reverse=True)
    pi = neh_construction(order_total)
    best_pi = pi[:]
    best_makespan_val = makespan(pi)

    # Iterated Greedy parameters
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
    d = 3 if n >= 3 else n
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    # Main IG loop
    for it in range(max_iter):
        # Destruction: remove d random jobs
        indices = list(range(n))
        random.shuffle(indices)
        removed_indices = indices[:d]
        removed_jobs = [pi[i] for i in removed_indices]
        # Build partial sequence without removed jobs
        pi_partial = [pi[i] for i in range(n) if i not in removed_indices]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed_jobs)
        for job in removed_jobs:
            best_pos = 0
            best_mk = float('inf')
            k = len(pi_partial)
            if k == 0:
                pi_partial = [job]
                continue
            # Precompute forward matrix e for pi_partial (length k)
            e = [[0] * m for _ in range(k)]
            for r in range(k):
                job_r = pi_partial[r]
                for mc in range(m):
                    if mc == 0:
                        prev = e[r-1][0] if r > 0 else 0
                        e[r][mc] = prev + times[job_r][mc]
                    else:
                        up = e[r-1][mc] if r > 0 else 0
                        left = e[r][mc-1]
                        e[r][mc] = max(up, left) + times[job_r][mc]
            # Precompute backward tail matrix q for pi_partial (length k)
            q = [[0] * m for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = pi_partial[r]
                for mc in range(m-1, -1, -1):
                    if mc == m-1:
                        down = q[r+1][mc]
                        q[r][mc] = down + times[job_r][mc]
                    else:
                        down = q[r+1][mc]
                        right = q[r][mc+1]
                        q[r][mc] = max(down, right) + times[job_r][mc]
            # Try inserting job at each position i in [0, k]
            for i in range(k+1):
                f = [0] * m
                for mc in range(m):
                    if mc == 0:
                        prev = e[i-1][0] if i > 0 else 0
                        f[mc] = prev + times[job][mc]
                    else:
                        left = f[mc-1]
                        up = e[i-1][mc] if i > 0 else 0
                        f[mc] = max(left, up) + times[job][mc]
                current_max = 0
                for mc in range(m):
                    val = f[mc] + q[i][mc]
                    if val > current_max:
                        current_max = val
                if current_max < best_mk:
                    best_mk = current_max
                    best_pos = i
            pi_partial.insert(best_pos, job)
        pi_new = pi_partial
        mk_new = makespan(pi_new)
        # Acceptance criterion
        if mk_new < makespan(pi):
            pi = pi_new
            if mk_new < best_makespan_val:
                best_pi = pi_new[:]
                best_makespan_val = mk_new
                no_improve = 0
            else:
                no_improve += 1
        else:
            delta = mk_new - makespan(pi)
            if random.random() < math.exp(-delta / T):
                pi = pi_new
                no_improve += 1
            else:
                no_improve += 1
        if no_improve >= no_improve_limit:
            break

    return best_pi

