def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_times = [sum(job) for job in times]
    slope_indices = [sum((2 * j - m + 1) * times[i][j] for j in range(m)) for i in range(n)]

    # Helper: makespan of a permutation
    def makespan(perm):
        t = [0] * m
        for job in perm:
            for k in range(m):
                if k == 0:
                    t[k] += times[job][k]
                else:
                    t[k] = max(t[k], t[k-1]) + times[job][k]
        return t[-1]

    # Helper: makespan after inserting job x at position pos in current perm
    def insertion_makespan(perm, x, pos):
        k = len(perm)
        e = [[0] * m for _ in range(k+1)]  # forward completion matrix
        for r in range(k):
            job = perm[r]
            for mc in range(m):
                if mc == 0:
                    e[r+1][mc] = e[r][mc] + times[job][mc]
                else:
                    e[r+1][mc] = max(e[r][mc], e[r+1][mc-1]) + times[job][mc]
        q = [[0] * m for _ in range(k+2)]  # backward tail matrix
        for r in range(k, -1, -1):
            if r < k:
                job = perm[r]
                for mc in range(m-1, -1, -1):
                    if mc == m-1:
                        q[r][mc] = q[r+1][mc] + times[job][mc]
                    else:
                        q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + times[job][mc]
        f = [0] * m
        for mc in range(m):
            if mc == 0:
                prev = e[pos][0] if pos > 0 else 0
                f[mc] = prev + times[x][mc]
            else:
                prev_e = e[pos][mc] if pos > 0 else 0
                f[mc] = max(f[mc-1], prev_e) + times[x][mc]
        makespan_val = 0
        for mc in range(m):
            val = f[mc] + q[pos][mc]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    order = sorted(range(n), key=lambda i: (-total_times[i], -slope_indices[i]))
    perm = [order[0]]
    for idx in range(1, n):
        job = order[idx]
        best_pos = 0
        best_ms = float('inf')
        for pos in range(idx + 1):
            ms = insertion_makespan(perm, job, pos)
            if ms < best_ms:
                best_ms = ms
                best_pos = pos
        perm.insert(best_pos, job)

    # Iterated Greedy refinement
    current = perm[:]
    best = current[:]
    best_ms = makespan(best)
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
    d = 3 if n > 20 else 2
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for it in range(max_iter):
        if no_improve >= no_improve_limit:
            break
        # Destruction: remove d random jobs
        indices = random.sample(range(n), d)
        removed = [current[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del current[i]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_ms_local = float('inf')
            for pos in range(len(current) + 1):
                ms = insertion_makespan(current, job, pos)
                if ms < best_ms_local:
                    best_ms_local = ms
                    best_pos = pos
            current.insert(best_pos, job)
        # Acceptance
        curr_ms = makespan(current)
        if curr_ms < best_ms:
            best = current[:]
            best_ms = curr_ms
            no_improve = 0
        elif curr_ms < makespan(best):  # This condition is redundant but kept for clarity
            pass
        else:
            if random.random() < math.exp(-(curr_ms - makespan(best)) / T):
                current = current[:]
            else:
                # Revert to previous state before this iteration's changes? Not storing, so keep current as is but count no improve
                no_improve += 1
                continue
        no_improve = 0

    return best

