def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(row) for row in times)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_time[m]
        return t[-1]

    def taillard_forward(partial):
        k = len(partial)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = times[partial[0]][m] if m == 0 else (e[0][m-1] + times[partial[0]][m])
        for r in range(1, k):
            job = partial[r]
            job_time = times[job]
            e[r][0] = e[r-1][0] + job_time[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job_time[m]
        return e

    def taillard_backward(partial):
        k = len(partial)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = partial[r]
            job_time = times[job]
            q[r][M-1] = q[r+1][M-1] + job_time[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_time[m]
        return q

    def insert_best(partial, job, e, q):
        k = len(partial)
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = times[job][0]
            else:
                f0 = e[i-1][0] + times[job][0]
            f = [0] * M
            f[0] = f0
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m] if i-1 >= 0 else 0) + times[job][m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos

    P = [sum(row) for row in times]
    order = sorted(range(N), key=lambda i: (-P[i], i))

    if N == 2:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        return seq1 if makespan(seq1) <= makespan(seq2) else seq2

    partial = [order[0], order[1]]
    if makespan([order[1], order[0]]) < makespan(partial):
        partial = [order[1], order[0]]

    for k in range(2, N):
        job = order[k]
        e = taillard_forward(partial)
        q = taillard_backward(partial)
        pos = insert_best(partial, job, e, q)
        partial.insert(pos, job)

    current = partial[:]
    best = current[:]
    best_cmax = makespan(best)

    d = 3
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-9:
        T = 1e-9

    max_iters = 60
    for _ in range(max_iters):
        destroyed = current[:]
        random.shuffle(destroyed)
        R = destroyed[:d]
        pi_D = destroyed[d:]

        for job in R:
            e = taillard_forward(pi_D)
            q = taillard_backward(pi_D)
            pos = insert_best(pi_D, job, e, q)
            pi_D.insert(pos, job)

        pi_new = pi_D
        new_cmax = makespan(pi_new)

        if new_cmax < best_cmax:
            best_cmax = new_cmax
            best = pi_new[:]

        if new_cmax < makespan(current):
            current = pi_new
        else:
            delta = new_cmax - makespan(current)
            if random.random() < math.exp(-delta / T):
                current = pi_new

    return best

