        t = [0] * M
        for job in perm:
            pt = times[job]
            t[0] += pt[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + pt[m]
        return t[-1]

    def makespan_with_tails(perm):
        n = len(perm)
        e = [[0] * M for _ in range(n)]
        for r in range(n):
            job = perm[r]
            pt = times[job]
            if r == 0:
                e[0][0] = pt[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pt[m]
            else:
                e[r][0] = e[r-1][0] + pt[0]
                for m in range(1, M):
