    pi = perm[:]
    pi_best = pi[:]
    best_makespan_val = makespan(pi)

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 60

    for _ in range(max_iter):
