        if makespan(pi_D) < makespan(pi):
            pi = pi_D[:]
            if makespan(pi) < best_makespan_val:
                pi_best = pi[:]
                best_makespan_val = makespan(pi)
        elif random.random() < math.exp(-(makespan(pi_D) - makespan(pi)) / T):
            pi = pi_D[:]

    return pi_best

