def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    p_flat = [p for job in times for p in job]

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for idx in perm:
            job = times[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def compute_e_matrix(perm, k):
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        job0 = times[perm[0]]
        e[0][0] = job0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0[m]
        for r in range(1, k):
            job = times[perm[r]]
            e[r][0] = e[r-1][0] + job[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job[m]
        return e

    def compute_q_matrix(perm, k):
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = times[perm[r]]
            q[r][M-1] = q[r+1][M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job[m]
        return q

    def insertion_cost_with_tail(perm, k, x, e, q):
        f = [0] * M
        if k == 0:
            f[0] = times[x][0]
            for m in range(1, M):
                f[m] = f[m-1] + times[x][m]
            return f[-1]
        job_x = times[x]
        if k > 0:
            prev = e[k-1] if k-1 < len(e) else [0]*M
            f[0] = prev[0] + job_x[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev[m]) + job_x[m]
        else:
            f[0] = job_x[0]
            for m in range(1, M):
                f[m] = f[m-1] + job_x[m]
        best = float('inf')
        for i in range(k+1):
            tail = q[i] if i < len(q) else [0]*M
            val = 0
            for m in range(M):
                cand = f[m] + tail[m]
                if cand > val:
                    val = cand
            if val < best:
                best = val
                if i == k:
                    break
        return best

    def neh_construct():
        job_sums = [sum(job) for job in times]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        seq = [order[0], order[1]]
        if makespan([seq[1], seq[0]]) < makespan(seq):
            seq = [seq[1], seq[0]]
        for k in range(2, N):
            job = order[k]
            e = compute_e_matrix(seq, k)
            q = compute_q_matrix(seq, k)
            best_pos = 0
            best_cost = float('inf')
            for pos in range(k+1):
                cost = insertion_cost_with_tail(seq, k, job, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    def ig_improve(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_makespan = makespan(best)
        if best_makespan == 0:
            return best
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        d = 3 if N > 20 else 2
        for _ in range(max_iter):
            if makespan(best) == 0:
                break
            indices = list(range(N))
            random.shuffle(indices)
            removed = []
            remaining = current[:]
            for idx in indices[:d]:
                job = remaining.pop(remaining.index(idx))
                removed.append(job)
            for job in removed:
                e = compute_e_matrix(remaining, len(remaining))
                q = compute_q_matrix(remaining, len(remaining))
                best_pos = 0
                best_cost = float('inf')
                for pos in range(len(remaining)+1):
                    cost = insertion_cost_with_tail(remaining, len(remaining), job, e, q)
                    if cost < best_cost:
                        best_cost = cost
                        best_pos = pos
                remaining.insert(best_pos, job)
            new_seq = remaining
            new_makespan = makespan(new_seq)
            if new_makespan < makespan(current):
                current = new_seq
                if new_makespan < best_makespan:
                    best = new_seq[:]
                    best_makespan = new_makespan
            else:
                if random.random() < math.exp(-(new_makespan - makespan(current)) / T):
                    current = new_seq
        return best

    initial_seq = neh_construct()
    improved_seq = ig_improve(initial_seq)
