def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)

    def makespan(perm):
        t = [0] * M
        for job in perm:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_times[m]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        job0 = perm[0]
        e[0][0] = times[job0][0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + times[job0][m]
        for r in range(1, k):
            job = perm[r]
            e[r][0] = e[r-1][0] + times[job][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job][m]
        return e

    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            q[r][M-1] = q[r+1][M-1] + times[job][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return q

    def insert_best(perm, job, e_prev, q_prev):
        k = len(perm)
        if k == 0:
            return [job]
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = times[job][0]
                fm = [0] * M
                fm[0] = f0
                for m in range(1, M):
                    fm[m] = max(fm[m-1], 0) + times[job][m]
            else:
                prev_job = perm[i-1]
                f0 = e_prev[i-1][0] + times[job][0]
                fm = [0] * M
                fm[0] = f0
                for m in range(1, M):
                    fm[m] = max(fm[m-1], e_prev[i-1][m]) + times[job][m]
            mk = 0
            for m in range(M):
                val = fm[m] + q_prev[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return perm[:best_pos] + [job] + perm[best_pos:]

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: (-P[i], i))

    perm = [order[0]]
    for idx in range(1, N):
        job = order[idx]
        e_prev = compute_forward(perm)
        q_prev = compute_backward(perm)
        perm = insert_best(perm, job, e_prev, q_prev)

    best_perm = perm[:]
    best_mk = makespan(best_perm)

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N < 30 else 4
    max_iter = 60

    current_perm = best_perm[:]
    for _ in range(max_iter):
        if len(current_perm) <= d:
            destroyed = []
            R = current_perm[:]
        else:
            indices = random.sample(range(len(current_perm)), d)
            indices.sort(reverse=True)
            R = [current_perm.pop(i) for i in indices]
            destroyed = current_perm

        e_destroyed = compute_forward(destroyed)
        q_destroyed = compute_backward(destroyed)

        for job in R:
            destroyed = insert_best(destroyed, job, e_destroyed, q_destroyed)
            e_destroyed = compute_forward(destroyed)
            q_destroyed = compute_backward(destroyed)

        new_perm = destroyed
        new_mk = makespan(new_perm)

        if new_mk < best_mk:
            best_mk = new_mk
            best_perm = new_perm[:]

        if new_mk < makespan(current_perm):
            current_perm = new_perm
        else:
            delta = new_mk - makespan(current_perm)
            if delta == 0 or random.random() < math.exp(-delta / T):
                current_perm = new_perm

    return best_perm

