        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as tuples for faster access
    job_times = [tuple(row) for row in times]

    # Helper function to compute makespan of a sequence
    def compute_makespan(seq):
        t = [0] * M
        for job in seq:
            p = job_times[job]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[m]
        return t[M-1]

