    # Step 1: sort jobs by total processing time descending
    total_times = [sum(p) for p in job_times]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Initialize with first job
    seq = [order[0]]
    if N == 1:
        return seq

    # Preallocate matrices for forward and backward passes
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N+1)]

    # Insert jobs one by one using Taillard's scheme
    for k in range(1, N):
        job = order[k]
        p_job = job_times[job]

        # Forward pass: compute e[0..k-1][0..M-1] for current seq of length k
        for r in range(k):
            p_r = job_times[seq[r]]
            if r == 0:
                e[0][0] = p_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p_r[m]
            else:
                e[r][0] = e[r-1][0] + p_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p_r[m]

        # Backward pass: compute q[0..k][0..M-1]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            p_r = job_times[seq[r]]
            q[r][M-1] = q[r+1][M-1] + p_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p_r[m]

        # Evaluate all k+1 insertion positions
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            # Compute forward vector f for inserting job at position i
            if i == 0:
                f0 = p_job[0]
                f = [f0]
                for m in range(1, M):
                    f.append(f[m-1] + p_job[m])
            else:
                prev = e[i-1]
                f0 = prev[0] + p_job[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], prev[m]) + p_job[m])

            # Compute makespan: max over m of f[m] + q[i][m]
            makespan_val = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_val:
                    makespan_val = val

            if makespan_val < best_makespan:
                best_makespan = makespan_val
                best_pos = i

        seq.insert(best_pos, job)

