    current_seq = seq[:]
    current_makespan = compute_makespan(current_seq)
    best_seq = current_seq[:]
    best_makespan = current_makespan

    # Calculate average processing time for temperature
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

    # Number of IG iterations: aim for ~40ms total, ~0.3ms per iteration
    max_iter = 60
    d = 3  # destruction size

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            R = current_seq[:]
        else:
            indices = random.sample(range(N), d)
            indices.sort(reverse=True)
            R = []
            for idx in indices:
                R.append(current_seq.pop(idx))
            destroyed = current_seq  # remaining sequence

        # Reconstruction: reinsert jobs in R using NEH insertion (Taillard accelerated)
        # We'll rebuild the sequence from scratch using the same NEH logic but starting from destroyed
        if not destroyed:
            seq_recon = []
        else:
            seq_recon = destroyed[:]
            # Rebuild forward and backward matrices for the current destroyed sequence
            k_destroyed = len(destroyed)
            e_recon = [[0] * M for _ in range(k_destroyed)]
            q_recon = [[0] * M for _ in range(k_destroyed+1)]

            # Forward pass for destroyed sequence
            for r in range(k_destroyed):
                p_r = job_times[destroyed[r]]
                if r == 0:
                    e_recon[0][0] = p_r[0]
                    for m in range(1, M):
                        e_recon[0][m] = e_recon[0][m-1] + p_r[m]
                else:
                    e_recon[r][0] = e_recon[r-1][0] + p_r[0]
                    for m in range(1, M):
                        e_recon[r][m] = max(e_recon[r-1][m], e_recon[r][m-1]) + p_r[m]

            # Backward pass for destroyed sequence
            for m in range(M):
                q_recon[k_destroyed][m] = 0
            for r in range(k_destroyed-1, -1, -1):
                p_r = job_times[destroyed[r]]
                q_recon[r][M-1] = q_recon[r+1][M-1] + p_r[M-1]
                for m in range(M-2, -1, -1):
                    q_recon[r][m] = max(q_recon[r+1][m], q_recon[r][m+1]) + p_r[m]

        # Insert each job in R one by one
        for job in R:
            p_job = job_times[job]
            k = len(seq_recon)

            # If seq_recon is empty, just add the job
            if k == 0:
                seq_recon.append(job)
                continue

            # Recompute forward pass for current seq_recon (length k)
            e_cur = [[0] * M for _ in range(k)]
            q_cur = [[0] * M for _ in range(k+1)]
            for r in range(k):
                p_r = job_times[seq_recon[r]]
                if r == 0:
                    e_cur[0][0] = p_r[0]
                    for m in range(1, M):
                        e_cur[0][m] = e_cur[0][m-1] + p_r[m]
                else:
                    e_cur[r][0] = e_cur[r-1][0] + p_r[0]
                    for m in range(1, M):
                        e_cur[r][m] = max(e_cur[r-1][m], e_cur[r][m-1]) + p_r[m]
            for m in range(M):
                q_cur[k][m] = 0
            for r in range(k-1, -1, -1):
                p_r = job_times[seq_recon[r]]
                q_cur[r][M-1] = q_cur[r+1][M-1] + p_r[M-1]
                for m in range(M-2, -1, -1):
                    q_cur[r][m] = max(q_cur[r+1][m], q_cur[r][m+1]) + p_r[m]

            # Evaluate k+1 insertion positions
            best_pos = 0
            best_makespan_val = float('inf')
            for i in range(k+1):
                if i == 0:
                    f0 = p_job[0]
                    f = [f0]
                    for m in range(1, M):
                        f.append(f[m-1] + p_job[m])
                else:
                    prev = e_cur[i-1]
                    f0 = prev[0] + p_job[0]
                    f = [f0]
                    for m in range(1, M):
                        f.append(max(f[m-1], prev[m]) + p_job[m])

                makespan_val = 0
                for m in range(M):
                    val = f[m] + q_cur[i][m]
                    if val > makespan_val:
                        makespan_val = val

                if makespan_val < best_makespan_val:
                    best_makespan_val = makespan_val
                    best_pos = i

            seq_recon.insert(best_pos, job)

        # Evaluate reconstructed sequence
        new_makespan = compute_makespan(seq_recon)

        # Acceptance criterion
        if new_makespan < current_makespan:
            current_seq = seq_recon
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_seq = seq_recon[:]
                best_makespan = new_makespan
        elif new_makespan < best_makespan:
            # Accept with probability even if worse than current but better than best
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current_seq = seq_recon
                current_makespan = new_makespan
            best_seq = seq_recon[:]
            best_makespan = new_makespan
        else:
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current_seq = seq_recon
                current_makespan = new_makespan

    return best_seq

