    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job_idx in perm:
            job = times[job_idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    # Function to apply Johnson's rule for two-machine flow shop
    def johnson_rule(p1, p2):
        left, right = [], []
        jobs = list(range(N))
        # Sort by min(p1[i], p2[i]) ascending
        jobs.sort(key=lambda i: min(p1[i], p2[i]))
        for i in jobs:
            if p1[i] <= p2[i]:
                left.append(i)
            else:
                right.append(i)
        return left + right[::-1]

    # Generate CDS permutations: M-1 two-machine subproblems
    best_perm = None
    best_makespan = float('inf')
    for l in range(1, M):
        # p1: sum of first l machines, p2: sum of last M-l machines
        p1 = [sum(times[i][:l]) for i in range(N)]
        p2 = [sum(times[i][l:]) for i in range(N)]
        perm = johnson_rule(p1, p2)
        m = makespan(perm)
        if m < best_makespan:
            best_makespan = m
            best_perm = perm

    return best_perm

