def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for faster access
    p = [row[:] for row in times]

    # Makespan computation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Compute lower bound (Taillard) for early termination
    def lower_bound():
        total = [0] * M
        for i in range(N):
            for m in range(M):
                total[m] += p[i][m]
        lb = 0
        for m in range(M):
            left = min((sum(p[i][:m]) for i in range(N)), default=0)
            right = min((sum(p[i][m+1:]) for i in range(N)), default=0)
            lb = max(lb, left + total[m] + right)
        return lb

    LB = lower_bound()

    # NEH with Taillard acceleration for initial solution
    def neh_taillard(order):
        if not order:
            return []
        seq = [order[0]]
        # Forward matrix e: e[r][m] for r in [-1..k-1], m in [0..M-1]; e[-1][m] = 0
        e = [[0] * M]
        # Backward matrix q: q[r][m] for r in [0..k], m in [0..M-1]; q[k][m] = 0
        q = [[0] * M]
        for idx in range(1, len(order)):
            job = order[idx]
            k = len(seq)  # current length of seq
            # Extend e for current seq (0..k-1)
            e_new = [0] * M
            for m in range(M):
                if m == 0:
                    e_new[m] = e[-1][0] + p[seq[-1]][0]
                else:
                    e_new[m] = max(e[-1][m], e_new[m-1]) + p[seq[-1]][m]
            e.append(e_new)
            # Extend q for current seq (we will compute q for r in [0..k])
            q_new = [0] * M
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q_new[m] = q[0][m] + p[seq[0]][m]
                else:
                    q_new[m] = max(q[0][m], q_new[m+1]) + p[seq[0]][m]
            q.insert(0, q_new)
            # Now evaluate insertion positions for job at idx (0..k)
            best_pos = 0
            best_mk = float('inf')
            # f[m] will be computed for each position i
            for i in range(k+1):
                # Compute forward vector f for job at position i
                f = [0] * M
                if i == 0:
                    prev_e = [0] * M
                else:
                    prev_e = e[i-1]
                for m in range(M):
                    if m == 0:
                        f[m] = prev_e[0] + p[job][0]
                    else:
                        f[m] = max(f[m-1], prev_e[m]) + p[job][m]
                # Compute makespan if job inserted at i: max_m (f[m] + q[i][m])
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            # Insert job at best_pos
            seq.insert(best_pos, job)
            # Rebuild e and q from scratch for new seq (simpler and fast for N<=120)
            e = [[0]*M]
            for j in seq:
                e_new = [0]*M
                for m in range(M):
                    if m == 0:
                        e_new[m] = e[-1][0] + p[j][0]
                    else:
                        e_new[m] = max(e[-1][m], e_new[m-1]) + p[j][m]
                e.append(e_new)
            q = [[0]*M] * (len(seq)+1)
            for r in range(len(seq)-1, -1, -1):
                q_new = [0]*M
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q_new[m] = q[r+1][m] + p[seq[r]][m]
                    else:
                        q_new[m] = max(q[r+1][m], q_new[m+1]) + p[seq[r]][m]
                q[r] = q_new
        return seq

    # Initial solution via NEH on descending total processing time
    order = sorted(range(N), key=lambda i: sum(p[i]), reverse=True)
    pi = neh_taillard(order)
    best_pi = pi[:]
    best_mk = makespan(pi)
    if best_mk == LB:
        return best_pi

    # Iterated Greedy parameters
    T_param = 0.5
    avg_p = sum(sum(row) for row in p) / (N * M)
    T = T_param * avg_p * N * M / 10.0
    d = 3 if N > 20 else 2
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for it in range(max_iter):
        # Destruction: remove d random jobs
        indices = list(range(N))
        random.shuffle(indices)
        removed = indices[:d]
        removed_set = set(removed)
        pi_D = [job for job in pi if job not in removed_set]
        R = [pi[i] for i in removed]  # extracted jobs in order of removal

        # Reconstruction: reinsert each job in R using NEH insertion (Taillard style)
        for job in R:
            k = len(pi_D)
            # Build e and q for current pi_D
            e = [[0]*M]
            for j in pi_D:
                e_new = [0]*M
                for m in range(M):
                    if m == 0:
                        e_new[m] = e[-1][0] + p[j][0]
                    else:
                        e_new[m] = max(e[-1][m], e_new[m-1]) + p[j][m]
                e.append(e_new)
            q = [[0]*M] * (k+1)
            for r in range(k-1, -1, -1):
                q_new = [0]*M
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q_new[m] = q[r+1][m] + p[pi_D[r]][m]
                    else:
                        q_new[m] = max(q[r+1][m], q_new[m+1]) + p[pi_D[r]][m]
                q[r] = q_new
            # Find best insertion position
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                f = [0]*M
                prev_e = [0]*M if i == 0 else e[i-1]
                for m in range(M):
                    if m == 0:
                        f[m] = prev_e[0] + p[job][0]
                    else:
                        f[m] = max(f[m-1], prev_e[m]) + p[job][m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            pi_D.insert(best_pos, job)
        pi_new = pi_D
        mk_new = makespan(pi_new)
        # Acceptance criterion
        if mk_new < best_mk:
            best_mk = mk_new
            best_pi = pi_new[:]
            no_improve = 0
        if mk_new < makespan(pi):
            pi = pi_new
            no_improve = 0
        else:
            if random.random() < math.exp(-(mk_new - makespan(pi)) / T):
                pi = pi_new
                no_improve += 1
            else:
                no_improve += 1
        if no_improve >= no_improve_limit:
            break
        # Optional: adjust temperature (simple cooling)
        T *= 0.95

    return best_pi

