        k = len(seq)
        if pos == 0:
            e_prev = [0] * M
        else:
            e_prev = [0] * M
            for idx in range(pos):
                j = seq[idx]
                if idx == 0:
                    e_prev[0] = times[j][0]
                    for m in range(1, M):
                        e_prev[m] = max(e_prev[m-1], e_prev[m]) + times[j][m]
                else:
                    f0 = e_prev[0] + times[j][0]
                    e_prev[0] = f0
                    for m in range(1, M):
                        e_prev[m] = max(e_prev[m-1], e_prev[m]) + times[j][m]
        f = [0] * M
        if pos == 0:
            f[0] = times[job][0]
        else:
            f[0] = e_prev[0] + times[job][0]
        for m in range(1, M):
            f[m] = max(f[m-1], e_prev[m]) + times[job][m]
        # Compute q matrix for tail
        q = [0] * M
        for idx in range(pos, k):
            j = seq[idx]
            if idx == pos:
                q[M-1] = times[j][M-1]
                for m in range(M-2, -1, -1):
                    q[m] = max(q[m+1], q[m]) + times[j][m]
            else:
                q[M-1] += times[j][M-1]
                for m in range(M-2, -1, -1):
                    q[m] = max(q[m+1], q[m]) + times[j][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Build initial solution using NEH with Taillard
    order = sorted(range(N), key=lambda i: (-total_times[i], -slope_indices[i]))
    seq = [order[0]]
    best_seq = seq[:]
    best_makespan = makespan_taillard(seq)
    for idx in range(1, N):
        job = order[idx]
        best_pos = 0
        best_m = float('inf')
        for pos in range(len(seq) + 1):
            m = taillard_insert_eval(seq, job, pos)
            if m < best_m:
                best_m = m
                best_pos = pos
        seq.insert(best_pos, job)
        if best_m < best_makespan:
            best_makespan = best_m
            best_seq = seq[:]
    seq = best_seq

    # Iterated Greedy with VNS
    def destroy_and_reconstruct(seq, d):
        indices = random.sample(range(len(seq)), d)
        removed = [seq[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del seq[i]
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_m = float('inf')
            for pos in range(len(seq) + 1):
                m = taillard_insert_eval(seq, job, pos)
                if m < best_m:
                    best_m = m
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    def vns_neighborhood(seq, neighborhood_type):
        n = len(seq)
        if neighborhood_type == 0:  # insert
            i, j = random.sample(range(n), 2)
            job = seq.pop(i)
            seq.insert(j, job)
        else:  # swap
            i, j = random.sample(range(n), 2)
            seq[i], seq[j] = seq[j], seq[i]
        return seq

    current_seq = seq[:]
    current_makespan = makespan_taillard(current_seq)
    best_seq = current_seq[:]
    best_makespan = current_makespan
    temp_param = 0.5
    total_processing = sum(total_times)
    T = temp_param * total_processing / (10 * N * M) if N * M > 0 else 1.0
    no_improve_limit = 10
    no_improve = 0
    neighborhood_type = 0
    max_iter = 60
    for it in range(max_iter):
        if no_improve >= no_improve_limit:
            neighborhood_type = 1 - neighborhood_type
            no_improve = 0
        # Destruction-Reconstruction
        d = 3 if N > 5 else 2
        new_seq = destroy_and_reconstruct(current_seq[:], d)
        new_makespan = makespan_taillard(new_seq)
        # Acceptance
        if new_makespan < current_makespan or random.random() < math.exp((current_makespan - new_makespan) / T):
            current_seq = new_seq
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_makespan = new_makespan
                best_seq = new_seq[:]
                no_improve = 0
            else:
                no_improve += 1
        else:
            no_improve += 1
        # VNS move
        if random.random() < 0.3:  # 30% chance to apply VNS
            vns_seq = vns_neighborhood(current_seq[:], neighborhood_type)
            vns_makespan = makespan_taillard(vns_seq)
            if vns_makespan < current_makespan:
                current_seq = vns_seq
                current_makespan = vns_makespan
                if vns_makespan < best_makespan:
                    best_makespan = vns_makespan
                    best_seq = vns_seq[:]
                    no_improve = 0
                else:
                    no_improve += 1
            else:
                no_improve += 1
    return best_seq

