def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_time = 0
    for i in range(N):
        total_time += sum(times[i])

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[-1]

    def compute_forward(partial_seq):
        k = len(partial_seq)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial_seq[r]
            job_t = times[job]
            if r == 0:
                e[0][0] = job_t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_t[m]
            else:
                e[r][0] = e[r-1][0] + job_t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
        return e

    def compute_backward(partial_seq):
        k = len(partial_seq)
        if k == 0:
            return [[0] * M for _ in range(1)]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial_seq[r]
            job_t = times[job]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        return q

    def evaluate_insertion(partial_seq, e, q, job_x):
        k = len(partial_seq)
        best_pos = 0
        best_cmax = float('inf')
        job_t = times[job_x]
        for i in range(k+1):
            if i == 0:
                f0 = job_t[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], 0) + job_t[m])
            else:
                prev_e = e[i-1]
                f0 = prev_e[0] + job_t[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], prev_e[m]) + job_t[m])
            cmax = 0
            tail = q[i]
            for m in range(M):
                val = f[m] + tail[m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos, best_cmax

    def construct_neh(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            job1 = order[1]
            seq1 = [order[0], job1]
            seq2 = [job1, order[0]]
            if makespan(seq1) <= makespan(seq2):
                seq = seq1
            else:
                seq = seq2
        for idx in range(2, len(order)):
            job = order[idx]
            e = compute_forward(seq)
            q = compute_backward(seq)
            pos, _ = evaluate_insertion(seq, e, q, job)
            seq.insert(pos, job)
        return seq

    P = [sum(times[i]) for i in range(N)]
    first_op = [times[i][0] for i in range(N)]
    penalty_factor = 0.5
    adjusted_priority = [P[i] - penalty_factor * first_op[i] for i in range(N)]
    order = sorted(range(N), key=lambda i: adjusted_priority[i], reverse=True)
    pi = construct_neh(order)
    pi_star = pi[:]
    c_star = makespan(pi_star)

    T_param = 0.5
    T = T_param * total_time / (10 * N * M) if N * M > 0 else 1e-9
    d = 3
    max_iter = 60
    it = 0
    while it < max_iter:
        pi_current = pi_star[:]
        if len(pi_current) <= d:
            extracted = pi_current[:]
            remaining = []
        else:
            extracted = random.sample(pi_current, d)
            remaining = [j for j in pi_current if j not in extracted]
        random.shuffle(extracted)
        for job in extracted:
            e = compute_forward(remaining)
            q = compute_backward(remaining)
            pos, _ = evaluate_insertion(remaining, e, q, job)
            remaining.insert(pos, job)
        pi_new = remaining
        c_new = makespan(pi_new)
        if c_new < c_star:
            pi_star = pi_new[:]
            c_star = c_new
            pi = pi_new[:]
        if c_new < makespan(pi):
            pi = pi_new[:]
        else:
            delta = c_new - makespan(pi)
            if delta < 0 or random.random() < math.exp(-delta / T):
                pi = pi_new[:]
        it += 1

    return pi_star

