def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    p_flat = [job[:] for job in times]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            pj = p_flat[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + pj[m]
        return t[-1]

    def taillard_forward(partial_seq, k):
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial_seq[r]
            pj = p_flat[job]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    def taillard_backward(partial_seq, k):
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial_seq[r]
            pj = p_flat[job]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    def insert_cost(partial_seq, k, job, e, q):
        i_positions = k + 1
        best_cost = float('inf')
        best_i = 0
        for i in range(i_positions):
            f = [0] * M
            if i == 0:
                f[0] = p_flat[job][0]
                for m in range(1, M):
                    f[m] = f[m-1] + p_flat[job][m]
            else:
                f[0] = e[i-1][0] + p_flat[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + p_flat[job][m]
            cost = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cost:
                    cost = val
            if cost < best_cost:
                best_cost = cost
                best_i = i
        return best_i, best_cost

    def neh_taillard():
        P = [sum(job) for job in p_flat]
        order = sorted(range(N), key=lambda i: (-P[i], i))
        if N == 1:
            return [order[0]]
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        for k in range(2, N):
            job = order[k]
            e = taillard_forward(seq, k)
            q = taillard_backward(seq, k)
            pos, _ = insert_cost(seq, k, job, e, q)
            seq.insert(pos, job)
        return seq

    def beam_search_neh(K=2):
        P = [sum(job) for job in p_flat]
        order = sorted(range(N), key=lambda i: (-P[i], i))
        beams = [[order[0]]]
        for idx in range(1, N):
            job = order[idx]
            new_beams = []
            for seq in beams:
                k = len(seq)
                e = taillard_forward(seq, k)
                q = taillard_backward(seq, k)
                for pos in range(k+1):
                    new_seq = seq[:pos] + [job] + seq[pos:]
                    new_beams.append(new_seq)
            if not new_beams:
                beams = [[order[0]]]
                continue
            scored = [(makespan(seq), seq) for seq in new_beams]
            scored.sort(key=lambda x: x[0])
            beams = [seq for _, seq in scored[:K]]
        best_seq = min(beams, key=makespan)
        return best_seq

    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_makespan = makespan(best)
        d = 3 if N > 20 else 4
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        for _ in range(max_iter):
            if makespan(current) == best_makespan:
                pass
            indices = list(range(N))
            random.shuffle(indices)
            removed = []
            remaining = []
            for idx in indices:
                if len(removed) < d:
                    removed.append(current[idx])
                else:
                    remaining.append(current[idx])
            random.shuffle(removed)
            for job in removed:
                k = len(remaining)
                if k == 0:
                    remaining = [job]
                    continue
                e = taillard_forward(remaining, k)
                q = taillard_backward(remaining, k)
                pos, _ = insert_cost(remaining, k, job, e, q)
                remaining.insert(pos, job)
            current = remaining
            current_makespan = makespan(current)
            if current_makespan < best_makespan:
                best_makespan = current_makespan
                best = current[:]
            elif current_makespan < makespan(current):
                current = current[:]
            else:
                if random.random() < math.exp(-(current_makespan - makespan(current)) / T):
                    current = current[:]
        return best

    initial = beam_search_neh(K=2)
    refined = iterated_greedy(initial, max_iter=50)
    return refined

