def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten times for faster access
    flat_times = [times[i][j] for i in range(N) for j in range(M)]
    def p(i, j):
        return flat_times[i * M + j]

    # Makespan evaluation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            base = t[0] + p(job, 0)
            t[0] = base
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p(job, m)
        return t[-1]

    # Compute total processing time for each job (for NEH priority)
    total_time = [sum(p(i, j) for j in range(M)) for i in range(N)]
    # Sort jobs by total_time descending (NEH priority)
    order = sorted(range(N), key=lambda i: total_time[i], reverse=True)

    # Helper: compute makespan after inserting job x at position pos in partial schedule
    def insertion_makespan(partial, x, pos):
        k = len(partial)
        if k == 0:
            return p(x, 0) if M == 1 else _makespan_single_job(x)
        # Forward matrix e for partial schedule
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            if r == 0:
                e[0][0] = p(job_r, 0)
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p(job_r, m)
            else:
                e[r][0] = e[r-1][0] + p(job_r, 0)
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p(job_r, m)
        # Backward tail matrix q for partial schedule
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            if r == k-1:
                for m in range(M):
                    q[r][m] = p(job_r, m)
            else:
                q[r][M-1] = q[r+1][M-1] + p(job_r, M-1)
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p(job_r, m)
        # Evaluate insertion at position pos
        # Forward vector f for job x
        f = [0] * M
        if pos == 0:
            f[0] = p(x, 0)
            for m in range(1, M):
                f[m] = f[m-1] + p(x, m)
        else:
            prev_job_idx = pos - 1
            f[0] = e[prev_job_idx][0] + p(x, 0)
            for m in range(1, M):
                f[m] = max(f[m-1], e[prev_job_idx][m]) + p(x, m)
        # Compute makespan: max over m of f[m] + q[pos][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Special case for single job makespan (used when partial is empty)
    def _makespan_single_job(x):
        t = 0
        for m in range(M):
            t += p(x, m)
        return t

    # NEH construction with Taillard acceleration
    perm = []
    for idx in order:
        best_pos = 0
        best_makespan = float('inf')
        # Try all insertion positions
        for pos in range(len(perm) + 1):
            m = insertion_makespan(perm, idx, pos)
            if m < best_makespan:
                best_makespan = m
                best_pos = pos
        perm.insert(best_pos, idx)

    # Iterated Greedy (IG) refinement
    current = perm[:]
    best_perm = current[:]
    best_makespan = makespan(current)
    total_processing = sum(total_time)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N >= 3 else N
    max_iter = 50  # Calibrated to stay within time budget

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d == 0:
            destroyed = current[:]
            R = []
        else:
            indices = random.sample(range(N), d)
            indices.sort(reverse=True)
            R = [current[i] for i in indices]
            destroyed = current[:]
            for i in indices:
                del destroyed[i]
        # Reconstruction: reinsert jobs in R using NEH insertion (Taillard accelerated)
        for job in R:
            best_pos = 0
            best_makespan_job = float('inf')
            for pos in range(len(destroyed) + 1):
                m = insertion_makespan(destroyed, job, pos)
                if m < best_makespan_job:
                    best_makespan_job = m
                    best_pos = pos
            destroyed.insert(best_pos, job)
        # New candidate solution
        candidate = destroyed
        candidate_makespan = makespan(candidate)
        # Acceptance criterion
        if candidate_makespan < makespan(current):
            current = candidate
            if candidate_makespan < best_makespan:
                best_perm = candidate[:]
                best_makespan = candidate_makespan
        else:
            delta = candidate_makespan - makespan(current)
            if random.random() < math.exp(-delta / T):
                current = candidate
    return best_perm

