        k = len(perm)
        best_pos = 0
        best_makespan = float('inf')
        # Evaluate each insertion position 0..k
        for i in range(k + 1):
            # Forward pass for job at position i
            f = [0] * M
            if i == 0:
                prev_e = [0] * M
            else:
                prev_e = e[i-1]
            for m in range(M):
                if m == 0:
                    f[m] = prev_e[m] + times[job][m]
                else:
                    f[m] = max(f[m-1], prev_e[m]) + times[job][m]
            # Makespan if job inserted at i
            ms = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > ms:
