                q[r][M-1] = q[r+1][M-1] + times[current_perm[r]][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[current_perm[r]][m]
            # Evaluate insertion positions
            pos, _ = evaluate_insertion(current_perm, job, e, q)
            current_perm.insert(pos, job)
        return current_perm

    current_perm = construct_initial()
    current_makespan = makespan(current_perm)
    best_perm = current_perm[:]
    best_makespan = current_makespan

    # Compute total processing for temperature
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

    # Iterated Greedy refinement
    max_iter = 60  # Calibrated for <50ms
    d = 3  # Destruction size
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current_perm[i] for i in indices]
        # Build partial sequence without removed jobs
        removed_set = set(removed)
        partial = [job for job in current_perm if job not in removed_set]
        # Reconstruct by reinserting removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            # Recompute e and q for current partial
            k = len(partial)
            if k == 0:
                e = [[0] * M]
                q = [[0] * M, [0] * M]
            else:
                e = [[0] * M for _ in range(k)]
                q = [[0] * M for _ in range(k+1)]
                # Forward
                for r in range(k):
                    if r == 0:
                        e[r][0] = times[partial[r]][0]
                    else:
                        e[r][0] = e[r-1][0] + times[partial[r]][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + times[partial[r]][m]
                # Backward
                for m in range(M):
                    q[k][m] = 0
                for r in range(k-1, -1, -1):
                    q[r][M-1] = q[r+1][M-1] + times[partial[r]][M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[partial[r]][m]
            # Find best insertion position for job
            best_pos = 0
            best_ms = float('inf')
            for i in range(k + 1):
                # Forward for job at i
                f = [0] * M
                if i == 0:
                    prev_e = [0] * M
                else:
                    prev_e = e[i-1]
                for m in range(M):
                    if m == 0:
                        f[m] = prev_e[m] + times[job][m]
                    else:
                        f[m] = max(f[m-1], prev_e[m]) + times[job][m]
                # Makespan
                ms = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > ms:
                        ms = val
                if ms < best_ms:
                    best_ms = ms
                    best_pos = i
            partial.insert(best_pos, job)
        # New candidate solution
        candidate = partial
        candidate_makespan = makespan(candidate)
        # Acceptance criterion
        if candidate_makespan < current_makespan:
            current_perm = candidate
            current_makespan = candidate_makespan
            if candidate_makespan < best_makespan:
                best_perm = candidate[:]
                best_makespan = candidate_makespan
        else:
            if random.random() < math.exp(-(candidate_makespan - current_makespan) / T):
                current_perm = candidate
                current_makespan = candidate_makespan
    return best_perm

