def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for NEH priority
    total_times = [sum(job) for job in times]
    jobs_sorted = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Initialize makespan matrix for current partial schedule
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N + 1)]

    def makespan_of_sequence(seq):
        if not seq:
            return 0
        e_local = [0] * M
        for idx in seq:
            job = times[idx]
            e_local[0] += job[0]
            for m in range(1, M):
                e_local[m] = max(e_local[m-1], e_local[m]) + job[m]
        return e_local[-1]

    # NEH construction with Taillard acceleration
    def neh_construction():
        if len(jobs_sorted) < 2:
            return jobs_sorted[:]
        # Initial pair
        seq0 = [jobs_sorted[0], jobs_sorted[1]]
        seq1 = [jobs_sorted[1], jobs_sorted[0]]
        if makespan_of_sequence(seq0) <= makespan_of_sequence(seq1):
            current_seq = seq0[:]
        else:
            current_seq = seq1[:]
        k = 2
        while k < N:
            job_idx = jobs_sorted[k]
            job = times[job_idx]
            # Forward matrix for current_seq (length k)
            for r in range(k):
                idx_r = current_seq[r]
                p = times[idx_r]
                if r == 0:
                    e[r][0] = p[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[m]
                else:
                    e[r][0] = e[r-1][0] + p[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + p[m]
            # Backward matrix (q) for current_seq (length k)
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                idx_r = current_seq[r]
                p = times[idx_r]
                q[r][M-1] = q[r+1][M-1] + p[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[m]
            # Evaluate insertion positions
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Forward vector for job at position i
                if i == 0:
                    f0 = job[0]
                    f = [0] * M
                    f[0] = f0
                    for m in range(1, M):
                        f[m] = max(f[m-1], 0) + job[m]
                else:
                    prev_idx = current_seq[i-1]
                    prev_job = times[prev_idx]
                    f0 = e[i-1][0] + job[0]
                    f = [0] * M
                    f[0] = f0
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + job[m]
                # Makespan candidate
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            # Insert job at best_pos
            current_seq.insert(best_pos, job_idx)
            k += 1
        return current_seq

    # Iterated Greedy refinement
    def iterated_greedy(initial_seq):
        current_seq = initial_seq[:]
        best_seq = current_seq[:]
        best_mk = makespan_of_sequence(best_seq)
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2
        max_iter = 60
        no_improve_limit = 20
        no_improve = 0

        for it in range(max_iter):
            # Destruction: remove d random jobs
            if d >= N:
                destroyed = current_seq[:]
                remaining = []
            else:
                indices = random.sample(range(N), d)
                indices.sort(reverse=True)
                destroyed = []
                remaining = current_seq[:]
                for idx in indices:
                    destroyed.append(remaining.pop(idx))
            # Reconstruction: reinsert destroyed jobs one by one using NEH-like insertion
            for job_idx in destroyed:
                job = times[job_idx]
                k = len(remaining)
                # Build forward matrix for remaining
                for r in range(k):
                    idx_r = remaining[r]
                    p = times[idx_r]
                    if r == 0:
                        e[r][0] = p[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[m]
                    else:
                        e[r][0] = e[r-1][0] + p[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + p[m]
                # Build backward matrix for remaining
                for m in range(M):
                    q[k][m] = 0
                for r in range(k-1, -1, -1):
                    idx_r = remaining[r]
                    p = times[idx_r]
                    q[r][M-1] = q[r+1][M-1] + p[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + p[m]
                # Find best insertion position
                best_pos = 0
                best_mk_local = float('inf')
                for i in range(k+1):
                    if i == 0:
                        f0 = job[0]
                        f = [0] * M
                        f[0] = f0
                        for m in range(1, M):
                            f[m] = max(f[m-1], 0) + job[m]
                    else:
                        prev_idx = remaining[i-1]
                        prev_job = times[prev_idx]
                        f0 = e[i-1][0] + job[0]
                        f = [0] * M
                        f[0] = f0
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + job[m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_local:
                        best_mk_local = mk
                        best_pos = i
                remaining.insert(best_pos, job_idx)
            current_seq = remaining
            mk = makespan_of_sequence(current_seq)
            if mk < best_mk:
                best_mk = mk
                best_seq = current_seq[:]
                no_improve = 0
            else:
                no_improve += 1
                if mk < makespan_of_sequence(current_seq):
                    current_seq = current_seq[:]  # keep current
                else:
                    # Metropolis acceptance
                    delta = mk - makespan_of_sequence(current_seq)
                    if delta < 0 or random.random() < math.exp(-delta / T):
                        current_seq = current_seq[:]
                    else:
                        # Revert to previous current_seq (not stored, so keep as is)
                        pass
            if no_improve >= no_improve_limit:
                break
        return best_seq

    initial_seq = neh_construction()
    return iterated_greedy(initial_seq)

