    def compute_makespan(seq):
        if not seq:
            return 0
        ms = [[0] * M for _ in range(len(seq))]
        for i, job in enumerate(seq):
            for m in range(M):
                if i == 0 and m == 0:
                    ms[i][m] = times[job][m]
                elif i == 0:
                    ms[i][m] = ms[i][m-1] + times[job][m]
                elif m == 0:
                    ms[i][m] = ms[i-1][m] + times[job][m]
                else:
                    ms[i][m] = max(ms[i-1][m], ms[i][m-1]) + times[job][m]
        return ms[-1][-1] if ms else 0

    # Insert first two jobs
    j0, j1 = sorted_jobs[0], sorted_jobs[1]
    seq1 = [j0, j1]
    seq2 = [j1, j0]
    if compute_makespan(seq1) <= compute_makespan(seq2):
        schedule = seq1[:]
    else:
        schedule = seq2[:]

