def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flatten times for faster access
    flat_times = [t for job in times for t in job]

    def makespan(seq: list[int]) -> int:
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            base = job * M
            t[0] += flat_times[base]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + flat_times[base + m]
        return t[-1]

    # Lower bound (Taillard)
    total = [0] * N
    for i in range(N):
        base = i * M
        s = 0
        for m in range(M):
            s += flat_times[base + m]
        total[i] = s
    LB = 0
    for m in range(M):
        min_pre = min((sum(flat_times[i*M:(i*M+m)]) for i in range(N)), default=0)
        min_suf = min((sum(flat_times[i*M+m+1:i*M+M]) for i in range(N)), default=0)
        mid = sum(flat_times[i*M+m] for i in range(N))
        LB = max(LB, min_pre + mid + min_suf)
    if LB == 0:
        LB = min(total)

    # NEH with Taillard acceleration
    order = sorted(range(N), key=lambda i: total[i], reverse=True)
    seq = [order[0], order[1]]
    if makespan([order[1], order[0]]) < makespan(seq):
        seq = [order[1], order[0]]

    for k in range(2, N):
        job = order[k]
        base_job = job * M
        best_pos = 0
        best_mk = float('inf')

        # Forward matrix e (size k x M)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            bj = seq[r] * M
            if r == 0:
                e[0][0] = flat_times[bj]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + flat_times[bj + m]
            else:
                e[r][0] = e[r-1][0] + flat_times[bj]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + flat_times[bj + m]

        # Backward matrix q (size (k+1) x M)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            bj = seq[r] * M
            q[r][M-1] = q[r+1][M-1] + flat_times[bj + M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + flat_times[bj + m]

        # Evaluate insertion positions
        for i in range(k+1):
            # Forward pass for job at position i
            f = [0] * M
            if i == 0:
                f[0] = flat_times[base_job]
                for m in range(1, M):
                    f[m] = f[m-1] + flat_times[base_job + m]
            else:
                prev = e[i-1]
                f[0] = prev[0] + flat_times[base_job]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev[m]) + flat_times[base_job + m]
            # Makespan if inserted at i
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        seq.insert(best_pos, job)

    if makespan(seq) == LB:
        return seq

    # Iterated Greedy
    random.seed(42)
    T_param = 0.5
    sum_pt = sum(total)
    T = T_param * sum_pt / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    current = seq[:]
    best = seq[:]
    best_mk = makespan(best)
    max_iter = 60
    it = 0

    while it < max_iter and best_mk > LB:
        # Destruction
        pos = random.sample(range(N), d)
        pos.sort()
        removed = [current[i] for i in pos]
        # Build current_D by skipping destroyed positions
        current_D = []
        idx = 0
        for i in range(N):
            if idx < d and i == pos[idx]:
                idx += 1
            else:
                current_D.append(current[i])
        # Reconstruction: insert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            base_job = job * M
            best_pos = 0
            best_mk_ins = float('inf')
            L = len(current_D)
            # Forward matrix e for current_D
            e = [[0] * M for _ in range(L)] if L > 0 else []
            for r in range(L):
                bj = current_D[r] * M
                if r == 0:
                    e[0][0] = flat_times[bj]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + flat_times[bj + m]
                else:
                    e[r][0] = e[r-1][0] + flat_times[bj]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + flat_times[bj + m]
            # Backward matrix q for current_D
            q = [[0] * M for _ in range(L+1)]
            for r in range(L-1, -1, -1):
                bj = current_D[r] * M
                q[r][M-1] = q[r+1][M-1] + flat_times[bj + M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + flat_times[bj + m]
            # Try all insertion positions
            for i in range(L+1):
                if i == 0:
                    f0 = flat_times[base_job]
                    fm = [f0]
                    for m in range(1, M):
                        fm.append(fm[-1] + flat_times[base_job + m])
                else:
                    prev = e[i-1]
                    f0 = prev[0] + flat_times[base_job]
                    fm = [f0]
                    for m in range(1, M):
                        fm.append(max(fm[-1], prev[m]) + flat_times[base_job + m])
                mk_ins = 0
                for m in range(M):
                    val = fm[m] + q[i][m]
                    if val > mk_ins:
                        mk_ins = val
                if mk_ins < best_mk_ins:
                    best_mk_ins = mk_ins
                    best_pos = i
            current_D.insert(best_pos, job)
        # Acceptance
        new_mk = makespan(current_D)
        if new_mk < best_mk:
            best_mk = new_mk
            best = current_D[:]
            current = current_D[:]
        elif new_mk < makespan(current):
            current = current_D[:]
        else:
            if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                current = current_D[:]
        it += 1

    return best

