    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for fast access
    p = [times[i] for i in range(N)]
    total_processing = sum(sum(row) for row in p)

    # Helper: makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            tj = p[job]
            t[0] += tj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + tj[m]
        return t[-1]

    # Helper: compute forward completion matrix e for a given prefix of length k
    def compute_forward(perm, k):
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            tj = p[job]
            if r == 0:
                e[0][0] = tj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + tj[m]
            else:
                e[r][0] = e[r-1][0] + tj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + tj[m]
        return e

    # Helper: compute backward tail matrix q for a given prefix of length k
    def compute_backward(perm, k):
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already by initialization
        for r in range(k-1, -1, -1):
            job = perm[r]
            tj = p[job]
            q[r][M-1] = q[r+1][M-1] + tj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + tj[m]
        return q

    # Helper: evaluate makespan for inserting job x at position i in current perm of length k
    # using precomputed forward e and backward q matrices
    def evaluate_insertion(perm, k, e, q, x):
        tj = p[x]
        # forward vector f for job x
        f = [0] * M
        if k == 0:
            f[0] = tj[0]
            for m in range(1, M):
                f[m] = f[m-1] + tj[m]
        else:
            # e[i-1] is the forward state before insertion point
            prev = e[-1] if k == 0 else e[k-1]  # dummy, will be overridden
            for i in range(k+1):
                if i == 0:
                    f[0] = tj[0]
                    for m in range(1, M):
                        f[m] = f[m-1] + tj[m]
                else:
                    prev_e = e[i-1]
                    f[0] = prev_e[0] + tj[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev_e[m]) + tj[m]
                # makespan candidate = max_m (f[m] + q[i][m])
                best = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > best:
                        best = val
                if i == 0 or best < best_val:
                    best_val = best
                    best_pos = i
        return best_pos

    # NEH construction with Taillard acceleration
    job_order = sorted(range(N), key=lambda i: sum(p[i]), reverse=True)
    perm = [job_order[0], job_order[1]]
    if makespan([job_order[1], job_order[0]]) < makespan(perm):
        perm = [job_order[1], job_order[0]]

    for k in range(2, N):
        job = job_order[k]
        e = compute_forward(perm, k)
        q = compute_backward(perm, k)
        best_pos = 0
        best_val = float('inf')
        tj = p[job]
        for i in range(k+1):
            # compute forward vector f for inserting job at position i
            f = [0] * M
            if i == 0:
                f[0] = tj[0]
                for m in range(1, M):
                    f[m] = f[m-1] + tj[m]
            else:
                prev_e = e[i-1]
                f[0] = prev_e[0] + tj[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + tj[m]
            # compute makespan candidate
            val = 0
            for m in range(M):
                cand = f[m] + q[i][m]
                if cand > val:
                    val = cand
            if val < best_val:
                best_val = val
                best_pos = i
