    random.seed(42)  # deterministic seed for reproducibility
    current = perm[:]
    best = perm[:]
    best_makespan = makespan(best)
    # LB check (optional early exit)
    # For simplicity, we skip LB computation here to stay within time budget
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 60
    it = 0
    while it < max_iter:
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del current[idx]
        # Reconstruction: reinsert removed jobs one by one using NEH insertion with Taillard
        for job in removed:
            k = len(current)
            if k == 0:
                current.append(job)
                continue
            e = compute_forward(current, k)
            q = compute_backward(current, k)
            best_pos = 0
            best_val = float('inf')
            tj = p[job]
            for i in range(k+1):
                f = [0] * M
                if i == 0:
                    f[0] = tj[0]
                    for m in range(1, M):
                        f[m] = f[m-1] + tj[m]
                else:
                    prev_e = e[i-1]
                    f[0] = prev_e[0] + tj[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev_e[m]) + tj[m]
                val = 0
                for m in range(M):
                    cand = f[m] + q[i][m]
                    if cand > val:
                        val = cand
                if val < best_val:
                    best_val = val
                    best_pos = i
            current.insert(best_pos, job)
        # Acceptance criterion
        curr_makespan = makespan(current)
        if curr_makespan < makespan(best):
            best = current[:]
        if curr_makespan < makespan(perm):
            perm = current[:]
        else:
            if random.random() < math.exp(-(curr_makespan - makespan(perm)) / T):
                perm = current[:]
        it += 1

    return best

import math
