def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for fast access
    p = [times[i] for i in range(n)]

    # Compute Palmer's slope index weighted by inverse machine variance
    slope = [0.0] * n
    var = [0.0] * m
    mean = [0.0] * m
    for j in range(m):
        s = 0.0
        ss = 0.0
        for i in range(n):
            val = p[i][j]
            s += val
            ss += val * val
        mean[j] = s / n
        var[j] = ss / n - mean[j] * mean[j]
        if var[j] < 1e-9:
            var[j] = 1e-9
    for i in range(n):
        s_val = 0.0
        for j in range(m):
            weight = 1.0 / var[j]
            s_val += (2 * j - m + 1) * p[i][j] * weight
        slope[i] = s_val
    order = sorted(range(n), key=lambda i: (-slope[i], i))

    # Makespan computation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            job_t = p[job]
            t[0] += job_t[0]
            for k in range(1, m):
                t[k] = max(t[k-1], t[k]) + job_t[k]
        return t[-1]

    # NEH construction with Taillard acceleration
    def neh_construction(job_order):
        if not job_order:
            return []
        perm = [job_order[0]]
        if len(job_order) == 1:
            return perm
        # Evaluate first two jobs
        seq1 = [job_order[0], job_order[1]]
        seq2 = [job_order[1], job_order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        # Insert remaining jobs
        for idx in range(2, len(job_order)):
            job = job_order[idx]
            k = len(perm)
            # Forward matrix e: completion times of current perm
            e = [[0] * m for _ in range(k)]
            for r in range(k):
                job_r = p[perm[r]]
                if r == 0:
                    e[0][0] = job_r[0]
                    for mc in range(1, m):
                        e[0][mc] = e[0][mc-1] + job_r[mc]
                else:
                    e[r][0] = e[r-1][0] + job_r[0]
                    for mc in range(1, m):
                        e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + job_r[mc]
            # Backward matrix q: tail times
            q = [[0] * m for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = p[perm[r]]
                q[r][m-1] = q[r+1][m-1] + job_r[m-1]
                for mc in range(m-2, -1, -1):
                    q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + job_r[mc]
            # Evaluate insertion positions
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Forward vector f for job at position i
                f = [0] * m
                if i == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[i-1]
                job_t = p[job]
                f[0] = prev_e[0] + job_t[0]
                for mc in range(1, m):
                    f[mc] = max(f[mc-1], prev_e[mc]) + job_t[mc]
                # Compute makespan: max over m of f[mc] + q[i][mc]
                mk = 0
                for mc in range(m):
                    val = f[mc] + q[i][mc]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with Taillard-accelerated reinsertion
    def iterated_greedy(init_perm, max_iters=50):
        current = init_perm[:]
        best = current[:]
        best_mk = makespan(best)
        total = sum(sum(job) for job in p)
        T = 0.5 * total / (10 * n * m) if n * m > 0 else 1e-6
        d = 3 if n >= 3 else n
        for _ in range(max_iters):
            # Destruction: remove d random jobs
            if d == 0:
                destroyed = current[:]
                extracted = []
            else:
                indices = random.sample(range(len(current)), d)
                indices.sort(reverse=True)
                extracted = [current.pop(idx) for idx in indices]
                destroyed = current[:]
            # Reconstruction: reinsert extracted jobs one by one
            for job in extracted:
                k = len(destroyed)
