def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and bottleneck machine
    total_times = [sum(job) for job in times]
    machine_loads = [sum(times[i][j] for i in range(N)) for j in range(M)]
    bottleneck = max(range(M), key=lambda m: machine_loads[m])

    # Palmer's slope index for initial ordering
    slopes = []
    for i in range(N):
        s = 0
        for j in range(M):
            s += (2 * j - M + 1) * times[i][j]
        slopes.append(s)
    order = sorted(range(N), key=lambda i: (-slopes[i], -total_times[i]))

    # Makespan calculation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Taillard acceleration: compute forward matrix e for a sequence
    def compute_e(seq):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = (e[0][m-1] if m > 0 else 0) + times[seq[0]][m]
        for r in range(1, k):
            job = seq[r]
            for m in range(M):
                left = e[r-1][m]
                up = e[r][m-1] if m > 0 else 0
                e[r][m] = max(left, up) + times[job][m]
        return e

    # Taillard acceleration: compute backward tail matrix q for a sequence
    def compute_q(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            for m in range(M-1, -1, -1):
                down = q[r+1][m]
                right = q[r][m+1] if m < M-1 else 0
                q[r][m] = max(down, right) + times[job][m]
        return q

    # Compute makespan after inserting job x at position i using Taillard's O(M) method
    def insertion_makespan(e, q, x, i):
        f = [0] * M
        if i == 0:
            prev_e = [0] * M
        else:
            prev_e = e[i-1]
        for m in range(M):
            left = f[m-1] if m > 0 else 0
            up = prev_e[m]
            f[m] = max(left, up) + times[x][m]
        max_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > max_val:
                max_val = val
        return max_val

    # NEH construction with Taillard acceleration
    def construct_neh(ordered_jobs):
        if not ordered_jobs:
            return []
        seq = [ordered_jobs[0]]
        if len(ordered_jobs) == 1:
            return seq
        # Evaluate first two jobs
        seq1 = [ordered_jobs[0], ordered_jobs[1]]
        seq2 = [ordered_jobs[1], ordered_jobs[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Greedy insertion
        for k in range(2, len(ordered_jobs)):
            job = ordered_jobs[k]
            e = compute_e(seq)
            q = compute_q(seq)
            best_pos = 0
            best_makespan = float('inf')
            for i in range(len(seq) + 1):
                cmax = insertion_makespan(e, q, job, i)
                if cmax < best_makespan:
                    best_makespan = cmax
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

