                for i in range(len(seq) + 1):
                    cmax = insertion_makespan(e, q, job, i)
                    if cmax < best_makespan_insert:
                        best_makespan_insert = cmax
                        best_pos = i
                seq.insert(best_pos, job)
            # Acceptance criterion
            current_makespan = makespan(seq)
            if current_makespan < makespan(current):
                current = seq
                if current_makespan < best_makespan:
                    best = seq[:]
                    best_makespan = current_makespan
            else:
                if random.random() < math.exp(-(current_makespan - makespan(current)) / T):
                    current = seq
        return best

    # Build initial solution and refine
    initial_seq = construct_neh(order)
    refined_seq = iterated_greedy(initial_seq, max_iters=40)
    return refined_seq

