        min_after = min(times[i][m+1:] for i in range(N)) if m < M-1 else [0] * N
        sum_before = [sum(row[:m]) for row in times] if m > 0 else [0] * N
        sum_after = [sum(row[m+1:]) for row in times] if m < M-1 else [0] * N
        lb_m = min(sum_before[i] + sum_m + sum_after[i] for i in range(N))
        if lb_m > LB:
            LB = lb_m

    # Sort jobs by total processing time descending (NEH)
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

