    # Compute completion times using DP
    dp = [0] * M
    for job in seq:
        for m in range(M):
            if m == 0:
                dp[m] += times[job][m]
            else:
                dp[m] = max(dp[m-1], dp[m]) + times[job][m]
    return dp[-1]

