    for job in perm:
        job_times = times[job]
        t[0] += job_times[0]
        for i in range(1, m):
            t[i] = max(t[i-1], t[i]) + job_times[i]
    return t[-1]

def johnson_rule(times_sub):
    n = len(times_sub)
    if n == 0:
        return []
    left, right = 0, n - 1
    seq = [0] * n
    jobs = list(range(n))
    while jobs:
        best_job = None
        best_val = None
        best_side = None
        for j in jobs:
            a, b = times_sub[j]
            if a <= b:
                val = a
                side = 'left'
            else:
                val = b
                side = 'right'
            if best_val is None or val < best_val or (val == best_val and side == 'left' and best_side == 'right'):
                best_val = val
                best_job = j
                best_side = side
        if best_side == 'left':
            seq[left] = best_job
            left += 1
        else:
            seq[right] = best_job
            right -= 1
        jobs.remove(best_job)
    return seq

def cds_variant(times):
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])
    best_perm = None
    best_makespan = float('inf')
    for l in range(1, m):
        times_sub = []
        for i in range(n):
            a = sum(times[i][:l])
            b = sum(times[i][m-l:])
            times_sub.append((a, b))
        perm_sub = johnson_rule(times_sub)
        perm = [None] * n
        for idx, job in enumerate(perm_sub):
            perm[job] = idx
        sorted_jobs = sorted(range(n), key=lambda x: perm[x])
        ms = makespan(sorted_jobs, times)
        if ms < best_makespan:
            best_makespan = ms
            best_perm = sorted_jobs
    return best_perm

