def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for fast access
    proc = [times[i][:] for i in range(N)]

    # Helper: makespan of a sequence (O(N*M))
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            pj = proc[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[-1]

    # Helper: forward completion matrix for a sequence (O(len(seq)*M))
    def forward_matrix(seq):
        k = len(seq)
        if k == 0:
            return [[0]*M]
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            pj = proc[seq[r]]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    # Helper: backward tail matrix for a sequence (O(len(seq)*M))
    def backward_matrix(seq):
        k = len(seq)
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pj = proc[seq[r]]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    # Helper: makespan after inserting job x at position i in seq (O(M))
    def insertion_makespan(seq, x, i):
        k = len(seq)
        e = [[0]*M for _ in range(k)]
        if k > 0:
            for r in range(k):
                pj = proc[seq[r]]
                if r == 0:
                    e[0][0] = pj[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + pj[m]
                else:
                    e[r][0] = e[r-1][0] + pj[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        # Compute forward vector f for job x up to position i-1
        f = [0]*M
        if i == 0:
            for m in range(M):
                f[m] = proc[x][m]
        else:
            e_prev = e[i-1]
            pjx = proc[x]
            f[0] = e_prev[0] + pjx[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + pjx[m]
        # Compute backward tail q from position i
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pj = proc[seq[r]]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        # Makespan is max over m of f[m] + q[i][m]
        q_i = q[i]
        max_val = 0
        for m in range(M):
            val = f[m] + q_i[m]
            if val > max_val:
                max_val = val
        return max_val

    # Constructive heuristic: NEH with Taillard acceleration and idle/waiting bias
    total_proc = [sum(pj) for pj in proc]
    order = sorted(range(N), key=lambda i: total_proc[i], reverse=True)

    seq = [order[0]]
    for idx in range(1, N):
        job = order[idx]
        best_pos = 0
        best_mk = float('inf')
        # Evaluate all insertion positions
        for pos in range(len(seq)+1):
            mk = insertion_makespan(seq, job, pos)
            if mk < best_mk or (mk == best_mk and pos < best_pos):
                best_mk = mk
                best_pos = pos
        seq.insert(best_pos, job)

    # Iterated Greedy refinement
    random.seed(42)  # deterministic seed for reproducibility
    current = seq[:]
    best = current[:]
    best_mk = makespan(best)

    # Lower bound for early termination (optional, not always tight)
    # Not implemented to stay within time; rely on iteration count

    # IG parameters
    d = 3  # destruction size
    T_param = 0.5
    total_processing = sum(total_proc)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

    max_iter = 60  # calibrated to stay within ~40ms for N<=120, M<=20
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if N <= d:
            destroyed = []
            remaining = []
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            destroyed = [current[i] for i in indices]
            remaining = [current[i] for i in range(N) if i not in indices_set]

        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        for job in destroyed:
            best_pos = 0
            best_mk_insert = float('inf')
            for pos in range(len(remaining)+1):
                mk = insertion_makespan(remaining, job, pos)
                if mk < best_mk_insert or (mk == best_mk_insert and pos < best_pos):
                    best_mk_insert = mk
                    best_pos = pos
            remaining.insert(best_pos, job)

        current = remaining
        curr_mk = makespan(current)

        # Acceptance criterion
        if curr_mk < best_mk:
            best = current[:]
            best_mk = curr_mk
            if curr_mk < makespan(seq):  # improvement over NEH
                current = best[:]
            else:
                # Metropolis acceptance
                if curr_mk < makespan(current) or random.random() < math.exp(-(curr_mk - makespan(current)) / T):
                    pass  # accept current
                else:
                    current = best[:]  # revert to best
        else:
            # Accept worse solution with probability
            if random.random() < math.exp(-(curr_mk - makespan(current)) / T):
                pass  # accept current
            else:
                current = best[:]  # revert to best

    return best

