def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times and slopes for sorting
    total_times = [sum(job) for job in times]
    slopes = [sum((2 * j - m + 1) * times[i][j] for j in range(m)) for i in range(n)]

    # Try multiple priority orderings: total time, slope, and machine-specific
    priority_orders = [
        sorted(range(n), key=lambda i: (-total_times[i], i)),
        sorted(range(n), key=lambda i: (-slopes[i], i)),
        sorted(range(n), key=lambda i: (-times[i][m-1], i)) if m > 1 else list(range(n)),
        sorted(range(n), key=lambda i: (-times[i][0], i))
    ]

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            for k in range(m):
                if k == 0:
                    t[k] += times[job][k]
                else:
                    t[k] = max(t[k], t[k-1]) + times[job][k]
        return t[-1]

    def taillard_forward(perm):
        k = len(perm)
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job = perm[r]
            pj = times[job]
            if r == 0:
                e[0][0] = pj[0]
                for mc in range(1, m):
                    e[0][mc] = e[0][mc-1] + pj[mc]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for mc in range(1, m):
                    e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + pj[mc]
        return e

    def taillard_backward(perm):
        k = len(perm)
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            pj = times[job]
            if r == k-1:
                q[r][m-1] = pj[m-1]
                for mc in range(m-2, -1, -1):
                    q[r][mc] = q[r][mc+1] + pj[mc]
            else:
                q[r][m-1] = q[r+1][m-1] + pj[m-1]
                for mc in range(m-2, -1, -1):
                    q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + pj[mc]
        return q

    def insert_best(perm, job, e, q):
        k = len(perm)
        best_pos = 0
        best_cmax = float('inf')
        pj = times[job]
        for i in range(k+1):
            if i == 0:
                f0 = pj[0]
                fm = [0] * m
                fm[0] = f0
                for mc in range(1, m):
                    fm[mc] = max(fm[mc-1], 0) + pj[mc]
            else:
                prev = e[i-1]
                f0 = prev[0] + pj[0]
                fm = [0] * m
                fm[0] = f0
                for mc in range(1, m):
                    fm[mc] = max(fm[mc-1], prev[mc]) + pj[mc]
            cmax = 0
            for mc in range(m):
                val = fm[mc] + q[i][mc]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        perm.insert(best_pos, job)
        return best_cmax

    def construct_neh(order):
        if not order:
            return []
        perm = [order[0]]
        if len(order) > 1:
            job1 = order[1]
            seq1 = [order[0], job1]
            seq2 = [job1, order[0]]
            perm = seq1 if makespan(seq1) <= makespan(seq2) else seq2
            start = 2
        else:
            start = 1
        for idx in range(start, len(order)):
            job = order[idx]
            e = taillard_forward(perm)
            q = taillard_backward(perm)
            insert_best(perm, job, e, q)
        return perm

    def local_search(perm):
        improved = True
        current = perm[:]
        best = current[:]
        best_cmax = makespan(best)
        while improved:
            improved = False
            for i in range(len(current)-1):
                for j in range(i+1, len(current)):
                    nxt = current[:]
                    nxt[i], nxt[j] = nxt[j], nxt[i]
                    cmax = makespan(nxt)
                    if cmax < best_cmax:
                        best_cmax = cmax
                        best = nxt[:]
                        improved = True
            if improved:
                current = best[:]
        return best

    best_perm = None
    best_cmax = float('inf')
    for order in priority_orders:
        perm = construct_neh(order)
        perm = local_search(perm)
        cmax = makespan(perm)
        if cmax < best_cmax:
            best_cmax = cmax
            best_perm = perm

    return best_perm

