                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
            # Backward tail matrix q for current seq (length k)
            q = [[0] * M for _ in range(k+1)]  # q[k][:] = 0
            for r in range(k-1, -1, -1):
                pj = job_data[seq[r]]
                q[r][M-1] = q[r+1][M-1] + pj[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
            # Evaluate insertion positions
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Compute forward vector f for inserting job at position i
                f = [0] * M
                if i == 0:
                    prev_e = [0] * M
                else:
                    prev_e = e[i-1]
                pj = job_data[job]
                f[0] = prev_e[0] + pj[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + pj[m]
                # Compute makespan for this insertion
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(init_seq, max_iter=60):
        current = init_seq[:]
        best = init_seq[:]
        best_mk = makespan(best)
        total_processing = sum(total_time)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 5 else max(1, N//2)
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build partial sequence without removed indices
            current_partial = [current[i] for i in range(N) if i not in indices]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                k = len(current_partial)
                if k == 0:
                    current_partial = [job]
                    continue
                # Forward matrix e for current_partial
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    pj = job_data[current_partial[r]]
                    if r == 0:
                        e[0][0] = pj[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + pj[m]
                    else:
                        e[r][0] = e[r-1][0] + pj[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
                # Backward tail matrix q for current_partial
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    pj = job_data[current_partial[r]]
                    q[r][M-1] = q[r+1][M-1] + pj[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
                # Evaluate insertion positions
                best_pos = 0
                best_mk_ins = float('inf')
