                    if i == 0:
                        prev_e = [0] * M
                    else:
                        prev_e = e[i-1]
                    pj = job_data[job]
                    f[0] = prev_e[0] + pj[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev_e[m]) + pj[m]
                    # Compute makespan for this insertion
                    mk_ins = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk_ins:
                            mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                current_partial.insert(best_pos, job)
            current = current_partial
            mk = makespan(current)
            if mk < best_mk:
                best_mk = mk
                best = current[:]
            # Metropolis acceptance
            if mk < makespan(init_seq) or random.random() < math.exp(-(mk - makespan(init_seq)) / T):
                init_seq = current[:]
        return best

    # Build initial solution and refine
    init_seq = construct_initial()
    return iterated_greedy(init_seq, max_iter=50)

