def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total = [[0] * M for _ in range(N)]
    P = [0] * N
    for i in range(N):
        s = 0
        for j in range(M):
            t = times[i][j]
            total[i][j] = t
            s += t
        P[i] = s

    S = [0] * N
    for i in range(N):
        s_val = 0
        for j in range(M):
            s_val += (2 * j - M + 1) * total[i][j]
        S[i] = s_val

    indices = list(range(N))
    indices.sort(key=lambda i: (-P[i], -S[i], -total[i][0]))

    def makespan(seq):
        if not seq:
            return 0
        t_prev = [0] * M
        for job in seq:
            t_cur = [0] * M
            for m in range(M):
                if m == 0:
                    t_cur[m] = t_prev[m] + total[job][m]
                else:
                    t_cur[m] = max(t_prev[m], t_cur[m-1]) + total[job][m]
            t_prev = t_cur
        return t_prev[-1]

    def taillard_forward_backward(partial):
        k = len(partial)
        if k == 0:
            return None, None
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + total[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + total[job][m]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + total[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + total[job][m]
        return e, q

    def insert_with_taillard(partial, job, e, q):
        k = len(partial)
        if k == 0:
            return [job]
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = total[job][0]
                f = [0] * M
                f[0] = f0
                for m in range(1, M):
                    f[m] = max(f[m-1], 0) + total[job][m]
            else:
                f = [0] * M
                prev_job = partial[i-1]
                f[0] = e[i-1][0] + total[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + total[job][m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return partial[:best_pos] + [job] + partial[best_pos:]

    def neh_construct():
        seq = []
        for idx in indices:
            if not seq:
                seq = [idx]
                continue
            e, q = taillard_forward_backward(seq)
            seq = insert_with_taillard(seq, idx, e, q)
        return seq

    def iterated_greedy(initial_seq, max_iters=60):
        current = initial_seq[:]
        best = current[:]
        best_cmax = makespan(best)
        sum_pt = sum(P)
        T_param = 0.5
        T0 = T_param * sum_pt / (10 * N * M)
        T = T0
        for it in range(max_iters):
            d = 3 if N > 20 else 2
            if d > N:
                d = N
            positions = random.sample(range(N), d)
            positions.sort(reverse=True)
            removed = []
            for pos in positions:
                removed.append(current.pop(pos))
            random.shuffle(removed)
            e, q = taillard_forward_backward(current)
            for job in removed:
                current = insert_with_taillard(current, job, e, q)
                e, q = taillard_forward_backward(current)
            curr_cmax = makespan(current)
            if curr_cmax < best_cmax:
                best_cmax = curr_cmax
                best = current[:]
            if curr_cmax < makespan(current):
                current = current[:]
            else:
                delta = curr_cmax - makespan(current)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    current = current[:]
                else:
                    current = best[:]
            T *= 0.95
        return best

    initial_seq = neh_construct()
    refined_seq = iterated_greedy(initial_seq, max_iters=50)
    return refined_seq

