def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    N = len(times)
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times for fast access
    proc = [row[:] for row in times]  # proc[job][machine]

    # Makespan evaluation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += proc[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + proc[job][m]
        return t[-1]

    # NEH with Taillard acceleration for initial solution
    def construct_initial():
        total_time = [sum(proc[j]) for j in range(N)]
        order = sorted(range(N), key=lambda j: (-total_time[j], j))
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        # Start with first two jobs
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        seq = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        # Iteratively insert remaining jobs
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_mk = float('inf')
            # Forward matrix e: completion times of current seq
            e = [[0]*M for _ in range(len(seq))]
            for r in range(len(seq)):
                for m in range(M):
                    if m == 0:
                        prev = e[r-1][0] if r > 0 else 0
                        e[r][m] = prev + proc[seq[r]][m]
                    else:
                        left = e[r][m-1]
                        up = e[r-1][m] if r > 0 else 0
                        e[r][m] = max(left, up) + proc[seq[r]][m]
            # Backward tail matrix q
            q = [[0]*M for _ in range(len(seq)+1)]
            for r in range(len(seq)-1, -1, -1):
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + proc[seq[r]][m]
                    else:
                        down = q[r][m+1]
                        right = q[r+1][m]
                        q[r][m] = max(down, right) + proc[seq[r]][m]
            # Evaluate each insertion position
            for i in range(len(seq)+1):
                # Forward pass for job at position i
                f = [0]*M
                for m in range(M):
                    if m == 0:
                        prev = e[i-1][0] if i > 0 else 0
                        f[m] = prev + proc[job][m]
                    else:
                        left = f[m-1]
                        up = e[i-1][m] if i > 0 else 0
                        f[m] = max(left, up) + proc[job][m]
                # Makespan if job inserted at i
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(init_seq, max_iter=60):
        current = init_seq[:]
        best = init_seq[:]
        best_mk = makespan(best)
        total_processing = sum(sum(row) for row in proc)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            remaining = [current[i] for i in range(N) if i not in indices]
            # Reconstruction: reinsert each removed job using NEH insertion
            for job in removed:
                best_pos = 0
                best_mk_local = float('inf')
                # Forward matrix for remaining
                e = [[0]*M for _ in range(len(remaining))]
                for r in range(len(remaining)):
                    for m in range(M):
                        if m == 0:
                            prev = e[r-1][0] if r > 0 else 0
                            e[r][m] = prev + proc[remaining[r]][m]
                        else:
                            left = e[r][m-1]
                            up = e[r-1][m] if r > 0 else 0
                            e[r][m] = max(left, up) + proc[remaining[r]][m]
                # Backward tail for remaining
                q = [[0]*M for _ in range(len(remaining)+1)]
                for r in range(len(remaining)-1, -1, -1):
                    for m in range(M-1, -1, -1):
                        if m == M-1:
                            q[r][m] = q[r+1][m] + proc[remaining[r]][m]
                        else:
                            down = q[r][m+1]
                            right = q[r+1][m]
                            q[r][m] = max(down, right) + proc[remaining[r]][m]
                # Try all insertion positions
                for i in range(len(remaining)+1):
                    f = [0]*M
                    for m in range(M):
                        if m == 0:
                            prev = e[i-1][0] if i > 0 else 0
                            f[m] = prev + proc[job][m]
                        else:
                            left = f[m-1]
                            up = e[i-1][m] if i > 0 else 0
                            f[m] = max(left, up) + proc[job][m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_local:
                        best_mk_local = mk
                        best_pos = i
                remaining.insert(best_pos, job)
            # New candidate sequence
            candidate = remaining
            mk_candidate = makespan(candidate)
            # Acceptance criterion
            if mk_candidate < makespan(current):
                current = candidate[:]
                if mk_candidate < best_mk:
                    best = candidate[:]
                    best_mk = mk_candidate
            else:
                if random.random() < math.exp(-(mk_candidate - makespan(current)) / T):
                    current = candidate[:]
        return best

    # Main flow
    init_seq = construct_initial()
    # Early exit if makespan is low (optional, not required for correctness)
    return iterated_greedy(init_seq, max_iter=50)

