        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = [sum(job) for job in times]
    jobs_sorted = sorted(range(N), key=lambda i: total_processing[i], reverse=True)

    def compute_makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    def taillard_neh_construct(sorted_jobs):
        if not sorted_jobs:
            return []
        seq = [sorted_jobs[0]]
        e_prev = [0] * M
        for m in range(M):
            e_prev[m] = (e_prev[m-1] if m > 0 else 0) + times[sorted_jobs[0]][m]
        for idx in range(1, len(sorted_jobs)):
            job = sorted_jobs[idx]
            k = len(seq)
            f = [0] * M
            best_pos = 0
            best_mk = float('inf')
            for i in range(k + 1):
                if i == 0:
                    f[0] = times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], 0) + times[job][m]
                else:
                    job_prev = seq[i-1]
                    f[0] = e_prev[0] + times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e_prev[m]) + times[job][m]
                tail = [0] * M
                if i < k:
                    tail[M-1] = times[seq[i]][M-1]
                    for m in range(M-2, -1, -1):
                        tail[m] = max(tail[m+1], times[seq[i]][m]) + (tail[m+1] if m < M-1 else 0)
                    for r in range(i+1, k):
                        job_r = seq[r]
                        tail[M-1] += times[job_r][M-1]
                        for m in range(M-2, -1, -1):
                            tail[m] = max(tail[m+1], times[job_r][m]) + tail[m+1]
                mk = 0
                for m in range(M):
                    val = f[m] + tail[m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
            e_prev = [0] * M
            for r in range(len(seq)):
                job_r = seq[r]
                if r == 0:
                    e_prev[0] = times[job_r][0]
                    for m in range(1, M):
                        e_prev[m] = max(e_prev[m-1], e_prev[m]) + times[job_r][m]
                else:
                    e_prev[0] = e_prev[0] + times[job_r][0]
                    for m in range(1, M):
                        e_prev[m] = max(e_prev[m-1], e_prev[m]) + times[job_r][m]
        return seq

    def destroy(sequence, d):
        if d >= len(sequence):
            return [], sequence[:]
        indices = random.sample(range(len(sequence)), d)
        indices_set = set(indices)
        removed = [sequence[i] for i in indices]
        remaining = [sequence[i] for i in range(len(sequence)) if i not in indices_set]
        return removed, remaining

    def reconstruct(partial, removed):
        seq = partial[:]
        for job in removed:
            k = len(seq)
            f = [0] * M
            best_pos = 0
            best_mk = float('inf')
            for i in range(k + 1):
                if i == 0:
                    f[0] = times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], 0) + times[job][m]
                else:
                    job_prev = seq[i-1]
                    f[0] = f[0] + times[job][0] if i == 1 else e_prev[i-1][0] + times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], (e_prev[i-1][m] if i > 0 else 0)) + times[job][m]
                tail = [0] * M
                if i < k:
                    tail[M-1] = times[seq[i]][M-1]
                    for m in range(M-2, -1, -1):
                        tail[m] = max(tail[m+1], times[seq[i]][m]) + tail[m+1]
                    for r in range(i+1, k):
                        job_r = seq[r]
                        tail[M-1] += times[job_r][M-1]
                        for m in range(M-2, -1, -1):
                            tail[m] = max(tail[m+1], times[job_r][m]) + tail[m+1]
                mk = 0
                for m in range(M):
                    val = f[m] + tail[m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
            e_prev = [[0]*M for _ in range(len(seq))]
            for r in range(len(seq)):
                job_r = seq[r]
                if r == 0:
                    e_prev[r][0] = times[job_r][0]
                    for m in range(1, M):
                        e_prev[r][m] = max(e_prev[r][m-1], e_prev[r][m]) + times[job_r][m]
                else:
                    e_prev[r][0] = e_prev[r-1][0] + times[job_r][0]
                    for m in range(1, M):
                        e_prev[r][m] = max(e_prev[r-1][m], e_prev[r][m-1]) + times[job_r][m]
        return seq

    initial_seq = taillard_neh_construct(jobs_sorted)
    best_seq = initial_seq[:]
    best_mk = compute_makespan(best_seq)
    current_seq = initial_seq[:]
    T_param = 0.5
    total_sum = sum(total_processing)
    T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-9
    max_iter = 60
    for _ in range(max_iter):
        d = 3 if N > 20 else 2
        removed, partial = destroy(current_seq, d)
        new_seq = reconstruct(partial, removed)
        new_mk = compute_makespan(new_seq)
        if new_mk < best_mk:
            best_mk = new_mk
            best_seq = new_seq[:]
        if new_mk < compute_makespan(current_seq):
            current_seq = new_seq[:]
        else:
            if random.random() < math.exp(-(new_mk - compute_makespan(current_seq)) / T):
                current_seq = new_seq[:]
    return best_seq

