        for r in range(k-1, -1, -1):
            job = perm[r]
            job_times = times[job]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + job_times[m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_times[m]
        return q

    # Helper: compute forward vector f for inserting job x at position i
    def compute_forward_vector(e_prev, job_x, i):
        # e_prev is e[i-1] (list of M), or zeros if i==0
        f = [0] * M
        job_times = times[job_x]
        if i == 0:
            prev = [0] * M
        else:
            prev = e_prev
        for m in range(M):
            if m == 0:
                f[m] = prev[0] + job_times[0]
            else:
                f[m] = max(f[m-1], prev[m]) + job_times[m]
        return f

    # NEH construction with Taillard acceleration
    def neh_construction():
        if N == 0:
            return []
        # Start with first job
        perm = [order[0]]
        if N == 1:
            return perm
        # Try both orders for first two jobs
        perm1 = [order[0], order[1]]
        perm2 = [order[1], order[0]]
        if makespan(perm1) <= makespan(perm2):
            perm = perm1
        else:
            perm = perm2
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            e = compute_forward(perm)
            q = compute_backward(perm)
            best_pos = 0
            best_mk = float('inf')
            # Evaluate each insertion position i in [0, k]
            for i in range(k+1):
                # e[i-1] is forward completion up to position i-1
                if i == 0:
                    e_prev = [0] * M
                else:
                    e_prev = e[i-1]
                f = compute_forward_vector(e_prev, job, i)
                # Compute makespan for insertion at i: max_m (f[m] + q[i][m])
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy refinement
    def iterated_greedy(initial_perm):
        current = initial_perm[:]
        best = current[:]
        best_mk = makespan(best)
        # Destruction size: 3 or 4
        d = 3 if N < 20 else 4
        max_iter = 60  # calibrated to stay within time budget
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in sorted(indices, reverse=True)]
            for idx in sorted(indices, reverse=True):
                del current[idx]
            # Reconstruction: re-insert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                e = compute_forward(current)
                q = compute_backward(current)
                best_pos = 0
                best_mk_insert = float('inf')
                k = len(current)
                for i in range(k+1):
                    if i == 0:
                        e_prev = [0] * M
                    else:
                        e_prev = e[i-1]
                    f = compute_forward_vector(e_prev, job, i)
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_insert:
                        best_mk_insert = mk
                        best_pos = i
                current.insert(best_pos, job)
            # Acceptance criterion
            curr_mk = makespan(current)
            if curr_mk < best_mk:
                best_mk = curr_mk
                best = current[:]
            if curr_mk < makespan(initial_perm):  # always accept if better than current start of iteration
                # current is already updated
                pass
            else:
                # Metropolis acceptance
                delta = curr_mk - makespan(initial_perm)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    # accept current
                    pass
                else:
                    # revert to initial_perm for this iteration
                    current = initial_perm[:]
        return best

    # Build initial solution
    init_perm = neh_construction()
    # Refine with Iterated Greedy
    final_perm = iterated_greedy(init_perm)
    return final_perm

