def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    P = [0] * N
    for i in range(N):
        row = times[i]
        s = 0
        for j in range(M):
            s += row[j]
            total_processing += row[j]
        P[i] = s

    order = list(range(N))
    order.sort(key=lambda i: P[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for idx in seq:
            job = times[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def makespan_taillard(seq):
        if not seq:
            return 0
        t = [0] * M
        for idx in seq:
            job = times[idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def compute_forward_backward(seq):
        k = len(seq)
        if k == 0:
            return None, None
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = times[seq[r]]
            if r == 0:
                e[0][0] = job[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job[m]
            else:
                e[r][0] = e[r-1][0] + job[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job[m]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = times[seq[r]]
            q[r][M-1] = q[r+1][M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job[m]
        return e, q

    def insert_job_taillard(seq, job_idx, e, q):
        k = len(seq)
        if k == 0:
            return [job_idx], times[job_idx][0] if M == 1 else (sum(times[job_idx]) if M == 1 else 0)
        job = times[job_idx]
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = job[0]
                f = [0] * M
                f[0] = f0
                for m in range(1, M):
                    f[m] = max(f[m-1], 0) + job[m]
            else:
                prev_e = e[i-1]
                f0 = prev_e[0] + job[0]
                f = [0] * M
                f[0] = f0
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + job[m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        new_seq = seq[:best_pos] + [job_idx] + seq[best_pos:]
        return new_seq, best_cmax

    def neh_taillard():
        if N <= 1:
            return order[:N]
        seq = [order[0], order[1]]
        c0 = makespan([order[0], order[1]])
        c1 = makespan([order[1], order[0]])
        if c1 < c0:
            seq = [order[1], order[0]]
        e, q = compute_forward_backward(seq)
        for k in range(2, N):
            job_idx = order[k]
            seq, _ = insert_job_taillard(seq, job_idx, e, q)
            e, q = compute_forward_backward(seq)
        return seq

    current = neh_taillard()
    best = current[:]
    best_cmax = makespan_taillard(best)

    LB = 0
    for m in range(M):
        min_pre = float('inf')
        min_post = float('inf')
        sum_m = 0
        for i in range(N):
            pre = sum(times[i][:m]) if m > 0 else 0
            post = sum(times[i][m+1:]) if m < M-1 else 0
            sum_m += times[i][m]
            if pre < min_pre:
                min_pre = pre
            if post < min_post:
                min_post = post
        lb_m = min_pre + sum_m + min_post
        if lb_m > LB:
            LB = lb_m
    if best_cmax == LB:
        return best

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 50
    if N > 60:
        max_iter = 30
    if N > 100:
        max_iter = 20

    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            R = current[:]
        else:
            indices = random.sample(range(len(current)), d)
            indices.sort(reverse=True)
            R = [current[i] for i in indices]
            destroyed = current[:]
            for idx in indices:
                destroyed.pop(idx)
        pi_D = destroyed
        e, q = compute_forward_backward(pi_D)
        for job_idx in R:
            pi_D, _ = insert_job_taillard(pi_D, job_idx, e, q)
            e, q = compute_forward_backward(pi_D)
        current = pi_D
        current_cmax = makespan_taillard(current)
        if current_cmax < best_cmax:
            best_cmax = current_cmax
            best = current[:]
            if best_cmax == LB:
                break
        elif current_cmax < makespan_taillard(best):
            pass
        else:
            delta = current_cmax - makespan_taillard(best)
            if delta < 0:
                acceptance_prob = 1.0
            else:
                acceptance_prob = math.exp(-delta / T) if T > 0 else 0.0
            if random.random() < acceptance_prob:
                pass
            else:
                current = best[:]

    return best

