    q = [[0] * M for _ in range(N + 1)]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m - 1]) + job_t[m]
        return t[-1]

    def taillard_insert(partial, job):
        k = len(partial)
        if k == 0:
            return [job]

        for m in range(M):
            e[0][m] = times[partial[0]][m] if m == 0 else max(e[0][m - 1], 0) + times[partial[0]][m]
        for r in range(1, k):
            e[r][0] = e[r - 1][0] + times[partial[r]][0]
            for m in range(1, M):
                e[r][m] = max(e[r - 1][m], e[r][m - 1]) + times[partial[r]][m]

        for m in range(M):
            q[k][m] = 0
        for r in range(k - 1, -1, -1):
            q[r][M - 1] = q[r + 1][M - 1] + times[partial[r]][M - 1]
            for m in range(M - 2, -1, -1):
                q[r][m] = max(q[r + 1][m], q[r][m + 1]) + times[partial[r]][m]

        best_pos = 0
        best_cmax = float('inf')
        for i in range(k + 1):
            f0 = (e[i - 1][0] if i - 1 >= 0 else 0) + times[job][0]
            f = [f0]
            for m in range(1, M):
                f.append(max(f[m - 1], e[i - 1][m] if i - 1 >= 0 else 0) + times[job][m])
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return partial[:best_pos] + [job] + partial[best_pos:]

    pi = []
    for idx in order:
        pi = taillard_insert(pi, idx)

    pi_best = pi[:]
    cmax_best = makespan(pi)

    max_iters = 60
    for _ in range(max_iters):
        d = 3 if N > 5 else N
        indices = random.sample(range(N), d)
        extracted = [pi[i] for i in indices]
        pi_D = [pi[i] for i in range(N) if i not in indices]
        random.shuffle(extracted)
        pi_new = pi_D[:]
        for job in extracted:
            pi_new = taillard_insert(pi_new, job)
        cmax_new = makespan(pi_new)
        if cmax_new < cmax_best:
            pi_best = pi_new[:]
            cmax_best = cmax_new
        if cmax_new < makespan(pi):
            pi = pi_new[:]
        else:
            if random.random() < math.exp(-(cmax_new - makespan(pi)) / T):
                pi = pi_new[:]
    return pi_best

