def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices
    total_times = [sum(job) for job in times]
    slope_indices = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Makespan calculation for a given permutation
    def makespan(seq):
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Taillard's accelerated makespan evaluation for insertion
    def evaluate_insertion(partial_seq, job_idx, pos):
        k = len(partial_seq)
        if k == 0:
            f = [0] * M
            for m in range(M):
                if m == 0:
                    f[m] = times[job_idx][m]
                else:
                    f[m] = f[m-1] + times[job_idx][m]
            return f[-1]

        # Forward matrix e
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial_seq[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job][m]

        # Backward matrix q
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial_seq[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]

        # Forward vector f for job_idx at position pos
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev = e[pos-1][m] if pos > 0 else 0
                f[m] = prev + times[job_idx][m]
            else:
                prev_e = e[pos-1][m] if pos > 0 else 0
                f[m] = max(f[m-1], prev_e) + times[job_idx][m]

        # Compute makespan
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    def neh_construction(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            seq1 = [order[0], order[1]]
            seq2 = [order[1], order[0]]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, len(order)):
            job = order[idx]
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(len(seq) + 1):
                m = evaluate_insertion(seq, job, pos)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Try multiple orderings: total time, slope, and random
    orders = [
        sorted(range(N), key=lambda i: total_times[i], reverse=True),
        sorted(range(N), key=lambda i: slope_indices[i], reverse=True),
        list(range(N))
    ]
    random.shuffle(orders[2])
    best_seq = None
    best_makespan = float('inf')
    for order in orders:
        seq = neh_construction(order)
        m = makespan(seq)
        if m < best_makespan:
            best_makespan = m
            best_seq = seq[:]

    # Iterated Greedy refinement
    current_seq = best_seq[:]
    current_makespan = best_makespan
    best_seq_ig = current_seq[:]
    best_makespan_ig = current_makespan

    # Parameters
    d = 3 if N > 20 else 2
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 50

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current_seq[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del current_seq[i]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_m = float('inf')
            for pos in range(len(current_seq) + 1):
                m = evaluate_insertion(current_seq, job, pos)
                if m < best_m:
                    best_m = m
                    best_pos = pos
            current_seq.insert(best_pos, job)
        # Evaluate new sequence
        new_makespan = makespan(current_seq)
        # Acceptance criterion
        if new_makespan < current_makespan or random.random() < math.exp(-(new_makespan - current_makespan) / T):
            current_seq = current_seq[:]
            current_makespan = new_makespan
            if new_makespan < best_makespan_ig:
                best_makespan_ig = new_makespan
                best_seq_ig = current_seq[:]
        else:
            # Revert to previous state (not storing explicitly, but we keep current_seq as is after rejection)
            pass

    return best_seq_ig

