def best_insertion_position(job, seq, job_data, N, M):
    k = len(seq)
    if k == 0:
        return 0, job_data[job][0]  # makespan for single job
    # Precompute forward matrix e (k x M)
    e = [[0] * M for _ in range(k)]
    # r=0
    e[0][0] = job_data[seq[0]][0]
    for m in range(1, M):
        e[0][m] = e[0][m-1] + job_data[seq[0]][m]
    # r>=1
    for r in range(1, k):
        e[r][0] = e[r-1][0] + job_data[seq[r]][0]
        for m in range(1, M):
            e[r][m] = max(e[r-1][m], e[r][m-1]) + job_data[seq[r]][m]
    # Precompute backward tail matrix q ((k+1) x M)
    q = [[0] * M for _ in range(k+1)]
    # q[k][m] = 0 already
    for r in range(k-1, -1, -1):
        q[r][M-1] = q[r+1][M-1] + job_data[seq[r]][M-1]
        for m in range(M-2, -1, -1):
            q[r][m] = max(q[r+1][m], q[r][m+1]) + job_data[seq[r]][m]
    # Evaluate each insertion position i in [0, k]
    best_pos = 0
    best_cmax = float('inf')
    for i in range(k+1):
        # Compute forward vector f for job at position i
        if i == 0:
            prev_e = [0] * M
        else:
            prev_e = e[i-1]
        f = [0] * M
        f[0] = prev_e[0] + job_data[job][0]
        for m in range(1, M):
            f[m] = max(f[m-1], prev_e[m]) + job_data[job][m]
        # Compute makespan: max_m (f[m] + q[i][m])
        cmax = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > cmax:
                cmax = val
        if cmax < best_cmax:
            best_cmax = cmax
            best_pos = i
    return best_pos, best_cmax

def makespan_taillard(seq, job_data, N, M):
    if not seq:
        return 0
    k = len(seq)
    # Forward matrix e
    e = [[0] * M for _ in range(k)]
    e[0][0] = job_data[seq[0]][0]
    for m in range(1, M):
        e[0][m] = e[0][m-1] + job_data[seq[0]][m]
    for r in range(1, k):
        e[r][0] = e[r-1][0] + job_data[seq[r]][0]
        for m in range(1, M):
            e[r][m] = max(e[r-1][m], e[r][m-1]) + job_data[seq[r]][m]
    # Backward tail matrix q
    q = [[0] * M for _ in range(k+1)]
    for r in range(k-1, -1, -1):
        q[r][M-1] = q[r+1][M-1] + job_data[seq[r]][M-1]
        for m in range(M-2, -1, -1):
            q[r][m] = max(q[r+1][m], q[r][m+1]) + job_data[seq[r]][m]
    # Makespan is max_m (e[k-1][m] + q[k][m]) but q[k][m]=0, so it's max_m e[k-1][m]
    # However, to be consistent with insertion logic, we compute as below
    cmax = 0
    for m in range(M):
        val = e[k-1][m] + q[k][m]  # q[k][m] is 0
        if val > cmax:
            cmax = val
    return cmax

def compute_lower_bound(times, N, M):
    LB = 0
    for m in range(M):
        # min_i sum_{l=0}^{m-1} p_{i,l}
        min_before = float('inf')
        for i in range(N):
            s = 0
            for l in range(m):
                s += times[i][l]
            if s < min_before:
                min_before = s
        # sum_i p_{i,m}
        sum_m = 0
        for i in range(N):
            sum_m += times[i][m]
        # min_i sum_{l=m+1}^{M-1} p_{i,l}
        min_after = float('inf')
        for i in range(N):
            s = 0
            for l in range(m+1, M):
                s += times[i][l]
            if s < min_after:
                min_after = s
        LB_m = min_before + sum_m + min_after
        if LB_m > LB:
            LB = LB_m
    return LB

