def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job processing times into flat lists for faster access
    p = [row[:] for row in times]

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            tj = p[job]
            t[0] += tj[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + tj[m]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            pj = p[job]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            pj = p[job]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    def makespan_after_insert(e, q, i, job):
        pj = p[job]
        f = [0] * M
        if i == 0:
            f[0] = pj[0]
            for m in range(1, M):
                f[m] = f[m-1] + pj[m]
        else:
            f[0] = e[i-1][0] + pj[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + pj[m]
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    total_proc = [sum(pj) for pj in p]
    order = sorted(range(N), key=lambda i: total_proc[i], reverse=True)
    perm = [order[0]]
    if N > 1:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        perm = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, N):
            job = order[idx]
            e = compute_forward(perm)
            q = compute_backward(perm)
            best_pos = 0
            best_mk = makespan_after_insert(e, q, 0, job)
            for pos in range(1, len(perm)+1):
                mk = makespan_after_insert(e, q, pos, job)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            perm.insert(best_pos, job)

    # Iterated Greedy refinement
    total_sum = sum(total_proc)
    T_param = 0.5
    T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 5 else max(1, N//2)
    current = perm[:]
    best_perm = current[:]
    best_mk = makespan(current)
    max_iters = 60
    it = 0
    while it < max_iters:
        # Destruction
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        indices_set = set(indices)
        destroyed = [current[i] for i in range(N) if i not in indices_set]
        # Reconstruction
        for job in removed:
            e = compute_forward(destroyed)
            q = compute_backward(destroyed)
            best_pos = 0
            best_mk_ins = makespan_after_insert(e, q, 0, job)
            for pos in range(1, len(destroyed)+1):
                mk_ins = makespan_after_insert(e, q, pos, job)
                if mk_ins < best_mk_ins:
                    best_mk_ins = mk_ins
                    best_pos = pos
            destroyed.insert(best_pos, job)
        current = destroyed
        mk = makespan(current)
        if mk < best_mk:
            best_mk = mk
            best_perm = current[:]
        # Acceptance
        if mk < makespan(perm):
            perm = current[:]
        else:
            delta = mk - makespan(perm)
            if delta < 0 or random.random() < math.exp(-delta / T):
                perm = current[:]
        it += 1

    return best_perm

