    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # NEH with Taillard acceleration for initial solution
    def neh_taillard(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) == 1:
            return seq
        # Evaluate first two jobs
        c00 = makespan([order[0], order[1]])
        c01 = makespan([order[1], order[0]])
        seq = [order[0], order[1]] if c00 <= c01 else [order[1], order[0]]
        # Insert remaining jobs
        for k in range(2, len(order)):
            job = order[k]
            best_pos = 0
            best_cmax = float('inf')
            # Forward matrix e: completion times of current seq
            e = [[0] * M for _ in range(len(seq))]
            for r in range(len(seq)):
                for m in range(M):
                    if m == 0:
                        prev = e[r-1][0] if r > 0 else 0
                        e[r][m] = prev + times[seq[r]][m]
                    else:
                        up = e[r-1][m] if r > 0 else 0
                        left = e[r][m-1]
                        e[r][m] = max(up, left) + times[seq[r]][m]
            # Backward matrix q: tail times
            q = [[0] * M for _ in range(len(seq) + 1)]
            for r in range(len(seq)-1, -1, -1):
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        down = q[r+1][m]
                        q[r][m] = down + times[seq[r]][m]
                    else:
                        down = q[r+1][m]
                        right = q[r][m+1]
                        q[r][m] = max(down, right) + times[seq[r]][m]
            # Try all insertion positions
            for i in range(len(seq) + 1):
                # Forward pass for job
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev = e[i-1][0] if i > 0 else 0
                        f[m] = prev + times[job][m]
                    else:
                        left = f[m-1]
                        up = e[i-1][m] if i > 0 else 0
                        f[m] = max(left, up) + times[job][m]
                # Compute makespan with job inserted at i
                cmax = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax:
                        cmax = val
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

