    order_total = sorted(range(N), key=lambda i: total[i], reverse=True)
    pi = neh_taillard(order_total)
    pi_star = pi[:]
    c_star = makespan(pi_star)

    # Iterated Greedy parameters
    d = 3 if N > 20 else 2
    T_param = 0.5
    total_processing = sum(total)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for it in range(max_iter):
        # Destruction: remove d jobs at random positions
        if N <= d:
            pi_new = pi[:]
            random.shuffle(pi_new)
        else:
            positions = random.sample(range(N), d)
            positions.sort(reverse=True)
            extracted = []
            pi_D = pi[:]
            for pos in positions:
                extracted.append(pi_D.pop(pos))
            # Reconstruction: reinsert extracted jobs one by one in random order
            random.shuffle(extracted)
            for job in extracted:
                best_pos = 0
                best_cmax = float('inf')
                # Recompute forward matrix e for current pi_D
                e = [[0] * M for _ in range(len(pi_D))]
                for r in range(len(pi_D)):
                    for m in range(M):
                        if m == 0:
                            prev = e[r-1][0] if r > 0 else 0
                            e[r][m] = prev + times[pi_D[r]][m]
                        else:
                            up = e[r-1][m] if r > 0 else 0
                            left = e[r][m-1]
                            e[r][m] = max(up, left) + times[pi_D[r]][m]
                # Recompute backward matrix q for current pi_D
                q = [[0] * M for _ in range(len(pi_D) + 1)]
                for r in range(len(pi_D)-1, -1, -1):
                    for m in range(M-1, -1, -1):
                        if m == M-1:
                            down = q[r+1][m]
                            q[r][m] = down + times[pi_D[r]][m]
                        else:
                            down = q[r+1][m]
                            right = q[r][m+1]
                            q[r][m] = max(down, right) + times[pi_D[r]][m]
                # Try all insertion positions for job
                for i in range(len(pi_D) + 1):
                    f = [0] * M
                    for m in range(M):
                        if m == 0:
                            prev = e[i-1][0] if i > 0 else 0
                            f[m] = prev + times[job][m]
                        else:
                            left = f[m-1]
                            up = e[i-1][m] if i > 0 else 0
                            f[m] = max(left, up) + times[job][m]
                    cmax = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > cmax:
                            cmax = val
                    if cmax < best_cmax:
                        best_cmax = cmax
                        best_pos = i
                pi_D.insert(best_pos, job)
            pi_new = pi_D
        c_new = makespan(pi_new)
        # Acceptance criterion
        if c_new < makespan(pi):
            pi = pi_new[:]
            if c_new < c_star:
                pi_star = pi_new[:]
                c_star = c_new
                no_improve = 0
            else:
                no_improve += 1
        else:
            if random.random() < math.exp(-(c_new - makespan(pi)) / T):
                pi = pi_new[:]
            no_improve += 1
        if no_improve >= no_improve_limit:
            break

    return pi_star

