def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Compute total processing times and variances per machine
    total_time = [0] * N
    machine_sum = [0.0] * M
    machine_sum_sq = [0.0] * M
    for i in range(N):
        row = times[i]
        for j in range(M):
            p = row[j]
            total_time[i] += p
            machine_sum[j] += p
            machine_sum_sq[j] += p * p

    # Compute Palmer slope with inverse variance weighting
    slope = [0.0] * N
    for i in range(N):
        s = 0.0
        for j in range(M):
            p = times[i][j]
            var = machine_sum_sq[j] - (machine_sum[j] * machine_sum[j]) / N
            if var < 1e-9:
                w = 1.0
            else:
                w = 1.0 / var
            s += (2 * j - M + 1) * p * w
        slope[i] = s

    # Sort jobs by slope descending
    order = sorted(range(N), key=lambda i: slope[i], reverse=True)

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N + 1)]
    f = [0] * M

    def makespan_from_schedule(perm):
        # Compute makespan using forward pass only
        for idx in range(len(perm)):
            job = perm[idx]
            row = times[job]
            if idx == 0:
                e[0][0] = row[0]
                for m in range(1, M):
                    e[0][m] = e[0][m - 1] + row[m]
            else:
                e[idx][0] = e[idx - 1][0] + row[0]
                for m in range(1, M):
                    e[idx][m] = max(e[idx - 1][m], e[idx][m - 1]) + row[m]
        return e[len(perm) - 1][M - 1]

    def taillard_insert(current, job, pos):
        k = len(current)
        # Forward matrix e for current schedule
        for r in range(k):
            job_r = current[r]
            row = times[job_r]
            if r == 0:
                e[0][0] = row[0]
                for m in range(1, M):
                    e[0][m] = e[0][m - 1] + row[m]
            else:
                e[r][0] = e[r - 1][0] + row[0]
                for m in range(1, M):
                    e[r][m] = max(e[r - 1][m], e[r][m - 1]) + row[m]
        # Backward tail matrix q
        for m in range(M):
            q[k][m] = 0
        for r in range(k - 1, -1, -1):
            job_r = current[r]
            row = times[job_r]
            q[r][M - 1] = q[r + 1][M - 1] + row[M - 1]
            for m in range(M - 2, -1, -1):
                q[r][m] = max(q[r + 1][m], q[r][m + 1]) + row[m]
        # Evaluate insertion at pos
        job_ins = job
        row_ins = times[job_ins]
        if pos == 0:
            f[0] = row_ins[0]
            for m in range(1, M):
                f[m] = f[m - 1] + row_ins[m]
        else:
            f[0] = e[pos - 1][0] + row_ins[0]
            for m in range(1, M):
                f[m] = max(f[m - 1], e[pos - 1][m]) + row_ins[m]
        makespan = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan:
                makespan = val
        return makespan

    # Construct initial solution using NEH with Taillard acceleration
    perm = [order[0]]
    best_perm = perm[:]
    best_makespan = makespan_from_schedule(perm)
    for idx in range(1, N):
        job = order[idx]
        best_pos = 0
        best_m = float('inf')
        for pos in range(len(perm) + 1):
            m = taillard_insert(perm, job, pos)
            if m < best_m:
                best_m = m
                best_pos = pos
        perm.insert(best_pos, job)
        if best_m < best_makespan:
            best_makespan = best_m
            best_perm = perm[:]

    # Iterated Greedy refinement
    T_param = 0.5
    total_processing = sum(total_time)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    current = best_perm[:]
    current_makespan = best_makespan
    iterations = 60
    d = 3

    for _ in range(iterations):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            extracted = current[:]
        else:
            indices = random.sample(range(N), d)
            indices.sort(reverse=True)
            extracted = []
            for idx in indices:
                extracted.append(current.pop(idx))
            destroyed = current  # remaining sequence

        # Reconstruction: reinsert extracted jobs one by one
        for job in extracted:
            best_pos = 0
            best_m = float('inf')
            for pos in range(len(destroyed) + 1):
                m = taillard_insert(destroyed, job, pos)
                if m < best_m:
                    best_m = m
                    best_pos = pos
            destroyed.insert(best_pos, job)

        new_perm = destroyed
        new_makespan = taillard_insert([], 0, 0)  # dummy to reset e/q
        # Recompute makespan for new_perm using forward pass
        for idx in range(len(new_perm)):
            job = new_perm[idx]
            row = times[job]
            if idx == 0:
                e[0][0] = row[0]
                for m in range(1, M):
                    e[0][m] = e[0][m - 1] + row[m]
            else:
                e[idx][0] = e[idx - 1][0] + row[0]
                for m in range(1, M):
                    e[idx][m] = max(e[idx - 1][m], e[idx][m - 1]) + row[m]
        new_makespan = e[len(new_perm) - 1][M - 1]

        # Acceptance criterion
        if new_makespan < current_makespan:
            current = new_perm
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_makespan = new_makespan
                best_perm = new_perm[:]
        else:
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current = new_perm
                current_makespan = new_makespan

    return best_perm

