def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            for k in range(m):
                if k == 0:
                    t[k] += times[job][k]
                else:
                    t[k] = max(t[k-1], t[k]) + times[job][k]
        return t[-1]

    def johnson_rule(p1, p2):
        n_jobs = len(p1)
        left, right = [], []
        jobs = list(range(n_jobs))
        while jobs:
            min_val = float('inf')
            min_job = -1
            min_side = ''
            for j in jobs:
                if p1[j] < min_val:
                    min_val = p1[j]
                    min_job = j
                    min_side = 'left'
                if p2[j] < min_val:
                    min_val = p2[j]
                    min_job = j
                    min_side = 'right'
            jobs.remove(min_job)
            if min_side == 'left':
                left.append(min_job)
            else:
                right.insert(0, min_job)
        return left + right

    best_perm = None
    best_cmax = float('inf')
    for l in range(1, m):
        p1 = [sum(times[i][:l]) for i in range(n)]
        p2 = [sum(times[i][m-l:]) for i in range(n)]
        perm = johnson_rule(p1, p2)
        cmax = makespan(perm)
        if cmax < best_cmax:
            best_cmax = cmax
            best_perm = perm
    return best_perm

