        if k == 0:
            return [[0] * m]
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            pj = times[job]
            q[r][m-1] = q[r+1][m-1] + pj[m-1]
            for mc in range(m-2, -1, -1):
                q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + pj[mc]
        return q

    def insert_job_neh(partial, job, e, q):
        k = len(partial)
        if k == 0:
            return [job]
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            if i == 0:
                f = [0] * m
                f[0] = times[job][0]
                for mc in range(1, m):
                    f[mc] = f[mc-1] + times[job][mc]
            else:
                f = [0] * m
                prev = e[i-1]
                pj = times[job]
                f[0] = prev[0] + pj[0]
                for mc in range(1, m):
                    f[mc] = max(f[mc-1], prev[mc]) + pj[mc]
            mk = 0
            tail = q[i]
            for mc in range(m):
                val = f[mc] + tail[mc]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return partial[:best_pos] + [job] + partial[best_pos:]

    def construct_neh():
        if len(order) < 2:
            return order[:]
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        for idx in range(2, n):
            job = order[idx]
            e = compute_forward(seq)
            q = compute_backward(seq)
            seq = insert_job_neh(seq, job, e, q)
        return seq

    current = construct_neh()
    best = current[:]
    best_mk = makespan(best)
    d = 3
    max_iters = 60
    it = 0
    while it < max_iters:
        if len(current) < d:
            destroyed = current[:]
            remaining = []
        else:
            indices = random.sample(range(len(current)), d)
            indices.sort(reverse=True)
            destroyed = [current[i] for i in indices]
            remaining = [current[i] for i in range(len(current)) if i not in indices]
        random.shuffle(destroyed)
        for job in destroyed:
            e = compute_forward(remaining)
            q = compute_backward(remaining)
            remaining = insert_job_neh(remaining, job, e, q)
        new_seq = remaining
        new_mk = makespan(new_seq)
        if new_mk < best_mk:
            best = new_seq[:]
            best_mk = new_mk
        if new_mk < makespan(current) or random.random() < math.exp(-(new_mk - makespan(current)) / T):
            current = new_seq
        it += 1
    return best

