def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: total_processing[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    def makespan_taillard(seq):
        if not seq:
            return 0
        e = [[0] * M for _ in range(len(seq))]
        for r in range(len(seq)):
            job = seq[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job][m]
        return e[-1][-1]

    def makespan_taillard_insertion(partial_seq, job, pos):
        k = len(partial_seq)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            j = partial_seq[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + times[j][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[j][m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            j = partial_seq[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[j][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[j][m]
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev_e = e[pos-1][0] if pos > 0 else 0
                f[m] = prev_e + times[job][m]
            else:
                f[m] = max(f[m-1], e[pos-1][m] if pos > 0 else 0) + times[job][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def construct_neh():
        if N == 0:
            return []
        pi = [order[0]]
        if N == 1:
            return pi
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan_taillard(seq1) <= makespan_taillard(seq2):
            pi = seq1
        else:
            pi = seq2
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_makespan = makespan_taillard_insertion(pi, job, 0)
            for pos in range(1, k+1):
                ms = makespan_taillard_insertion(pi, job, pos)
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            pi.insert(best_pos, job)
        return pi

    def ig_improve(initial_pi, max_iter=60):
        pi = initial_pi[:]
        pi_best = pi[:]
        total_sum = sum(total_processing)
        T_param = 0.5
        T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N >= 3 else N
        for _ in range(max_iter):
            if d > len(pi):
                d = len(pi)
            indices = random.sample(range(len(pi)), d)
            removed = [pi[i] for i in indices]
            pi_remaining = [pi[i] for i in range(len(pi)) if i not in indices]
            random.shuffle(removed)
            pi_new = pi_remaining[:]
            for job in removed:
                best_pos = 0
                best_ms = makespan_taillard_insertion(pi_new, job, 0)
                for pos in range(1, len(pi_new)+1):
                    ms = makespan_taillard_insertion(pi_new, job, pos)
                    if ms < best_ms:
                        best_ms = ms
                        best_pos = pos
                pi_new.insert(best_pos, job)
            if makespan_taillard(pi_new) < makespan_taillard(pi):
                pi = pi_new[:]
                if makespan_taillard(pi_new) < makespan_taillard(pi_best):
                    pi_best = pi_new[:]
            else:
                delta = makespan_taillard(pi_new) - makespan_taillard(pi)
                if random.random() < math.exp(-delta / T):
                    pi = pi_new[:]
        return pi_best

    initial_pi = construct_neh()
    return ig_improve(initial_pi, max_iter=50)

