def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_times = [sum(job) for job in times]

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job_idx in perm:
            job = times[job_idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job[m]
        return t[-1]

    def taillard_forward_backward(perm):
        k = len(perm)
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            job_idx = perm[r]
            job = times[job_idx]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + job[m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + job[m]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_idx = perm[r]
            job = times[job_idx]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + job[m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job[m]
        return e, q

    def insert_job(e, q, job_idx, pos):
        job = times[job_idx]
        f = [0]*M
        for m in range(M):
            if m == 0:
                prev_e = e[pos-1][m] if pos > 0 else 0
                f[m] = prev_e + job[m]
            else:
                f[m] = max(f[m-1], e[pos-1][m] if pos > 0 else 0) + job[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def construct_neh(order):
        if len(order) < 2:
            return order[:]
        best_seq = None
        best_ms = float('inf')
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        ms1 = makespan(seq1)
        ms2 = makespan(seq2)
        if ms1 <= ms2:
            best_seq = seq1
            best_ms = ms1
        else:
            best_seq = seq2
            best_ms = ms2
        for k in range(2, len(order)):
            job_idx = order[k]
            e, q = taillard_forward_backward(best_seq)
            best_pos = 0
            best_ms_insert = float('inf')
            for pos in range(k+1):
                ms = insert_job(e, q, job_idx, pos)
                if ms < best_ms_insert:
                    best_ms_insert = ms
                    best_pos = pos
            best_seq = best_seq[:best_pos] + [job_idx] + best_seq[best_pos:]
        return best_seq

    best_perm = None
    best_ms = float('inf')
    for _ in range(3):
        noisy = [(total_times[i] * random.uniform(0.9, 1.1), i) for i in range(N)]
        noisy.sort(key=lambda x: x[0], reverse=True)
        order = [idx for _, idx in noisy]
        perm = construct_neh(order)
        ms = makespan(perm)
        if ms < best_ms:
            best_ms = ms
            best_perm = perm

    current = best_perm[:]
    current_ms = best_ms
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9

    for _ in range(60):
        d = 3 if N > 3 else N
        indices = random.sample(range(N), d)
        indices.sort(reverse=True)
        removed = []
        for idx in indices:
            removed.append(current.pop(idx))
        random.shuffle(removed)
        for job_idx in removed:
            e, q = taillard_forward_backward(current)
            best_pos = 0
            best_ms_insert = float('inf')
            for pos in range(len(current)+1):
                ms = insert_job(e, q, job_idx, pos)
                if ms < best_ms_insert:
                    best_ms_insert = ms
                    best_pos = pos
            current = current[:best_pos] + [job_idx] + current[best_pos:]
        new_ms = makespan(current)
        if new_ms < current_ms:
            current_ms = new_ms
            if new_ms < best_ms:
                best_ms = new_ms
                best_perm = current[:]
        elif new_ms < best_ms or random.random() < math.exp(-(new_ms - current_ms) / T):
            current_ms = new_ms
            if new_ms < best_ms:
                best_ms = new_ms
                best_perm = current[:]
    return best_perm

