import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    for i in range(N):
        for j in range(M):
            total_processing += times[i][j]

    # Compute total processing times for each job (P_i)
    P = [sum(times[i]) for i in range(N)]
    # Sort jobs by descending P_i
    order = sorted(range(N), key=lambda i: P[i], reverse=True)

    # Initialize schedule with first job
    pi = [order[0]]

    # Preallocate matrices for Taillard's acceleration
    e = [[0] * M for _ in range(N)]  # forward completion matrix
    q = [[0] * M for _ in range(N + 1)]  # backward tail matrix

    # NEH construction with Taillard acceleration
    for k in range(1, N):
        job_idx = order[k]
        p_job = times[job_idx]

        # Compute forward completion matrix e[0..k-1][0..M-1]
        for r in range(k):
            job_r = pi[r]
            p_r = times[job_r]
            if r == 0:
                e[0][0] = p_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p_r[m]
            else:
                e[r][0] = e[r-1][0] + p_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p_r[m]

        # Compute backward tail matrix q[0..k][0..M-1]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = pi[r]
            p_r = times[job_r]
            q[r][M-1] = q[r+1][M-1] + p_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p_r[m]

        # Find best insertion position for job_idx
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            # Compute forward vector f for inserting job_idx at position i
            if i == 0:
                f0 = p_job[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], 0) + p_job[m])
            else:
                f0 = e[i-1][0] + p_job[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], e[i-1][m]) + p_job[m])

            # Compute makespan: max_m (f[m] + q[i][m])
            makespan = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan:
                    makespan = val

            if makespan < best_makespan:
                best_makespan = makespan
                best_pos = i

        pi.insert(best_pos, job_idx)

    # Iterated Greedy refinement
    current_pi = pi[:]
    best_pi = current_pi[:]

    # Function to compute makespan of a permutation
    def compute_makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            p_job = times[job]
            t[0] += p_job[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p_job[m]
        return t[M-1]

    current_makespan = compute_makespan(current_pi)
    best_makespan = current_makespan

    # IG parameters
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 5 else N  # destruction size
    max_iter = 50  # number of IG iterations

    for _ in range(max_iter):
        # Destruction: remove d jobs randomly
        if d >= N:
            remaining = []
            removed = current_pi[:]
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            remaining = [current_pi[i] for i in range(N) if i not in indices_set]
            removed = [current_pi[i] for i in indices]

        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job_idx in removed:
            p_job = times[job_idx]
            best_pos = 0
            best_makespan_local = float('inf')
            L = len(remaining)
            # Precompute forward matrix for remaining
            e_rem = [[0] * M for _ in range(L)]
            for r in range(L):
                job_r = remaining[r]
                p_r = times[job_r]
                if r == 0:
                    e_rem[0][0] = p_r[0]
                    for m in range(1, M):
                        e_rem[0][m] = e_rem[0][m-1] + p_r[m]
                else:
                    e_rem[r][0] = e_rem[r-1][0] + p_r[0]
                    for m in range(1, M):
                        e_rem[r][m] = max(e_rem[r-1][m], e_rem[r][m-1]) + p_r[m]
            # Precompute backward tail for remaining
            q_rem = [[0] * M for _ in range(L + 1)]
            for m in range(M):
                q_rem[L][m] = 0
            for r in range(L-1, -1, -1):
                job_r = remaining[r]
                p_r = times[job_r]
                q_rem[r][M-1] = q_rem[r+1][M-1] + p_r[M-1]
                for m in range(M-2, -1, -1):
                    q_rem[r][m] = max(q_rem[r+1][m], q_rem[r][m+1]) + p_r[m]
            # Try all insertion positions
            for i in range(L+1):
                if i == 0:
                    f0 = p_job[0]
                    f = [f0]
                    for m in range(1, M):
                        f.append(max(f[m-1], 0) + p_job[m])
                else:
                    f0 = e_rem[i-1][0] + p_job[0]
                    f = [f0]
                    for m in range(1, M):
                        f.append(max(f[m-1], e_rem[i-1][m]) + p_job[m])
                makespan_val = 0
                for m in range(M):
                    val = f[m] + q_rem[i][m]
                    if val > makespan_val:
                        makespan_val = val
                if makespan_val < best_makespan_local:
                    best_makespan_local = makespan_val
                    best_pos = i
            remaining.insert(best_pos, job_idx)

        new_pi = remaining
        new_makespan = compute_makespan(new_pi)

        # Acceptance criterion
        if new_makespan < current_makespan:
            current_pi = new_pi
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_pi = new_pi[:]
                best_makespan = new_makespan
        else:
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current_pi = new_pi
                current_makespan = new_makespan

    return best_pi

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job data for fast access
    p = [list(job) for job in times]
    total_p = [sum(job) for job in p]
    slope = [sum((2 * j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]

    # Makespan evaluation using forward pass
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            tj = p[job]
            t[0] += tj[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + tj[m]
        return t[M-1]

    # Taillard's accelerated insertion evaluation for a partial schedule
    def taillard_insert(seq, job):
        k = len(seq)
        if k == 0:
            return p[job][:]
        # Forward matrix e: completion times of current seq
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = seq[r]
            tj = p[job_r]
            if r == 0:
                e[0][0] = tj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + tj[m]
            else:
                e[r][0] = e[r-1][0] + tj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + tj[m]
        # Backward tail matrix q
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = seq[r]
            tj = p[job_r]
            q[r][M-1] = q[r+1][M-1] + tj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + tj[m]
        # Evaluate each insertion position
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            # Forward pass for job at position i
            f = [0] * M
            if i == 0:
                f[0] = p[job][0]
                for m in range(1, M):
                    f[m] = f[m-1] + p[job][m]
            else:
                prev = e[i-1]
                f[0] = prev[0] + p[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev[m]) + p[job][m]
            # Compute makespan: max over m of f[m] + q[i][m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos, best_cmax

    # NEH construction with Taillard acceleration and slope as tie-breaker
    def neh_construct(priority):
        seq = []
        for idx in priority:
            if not seq:
                seq.append(idx)
            else:
                pos, _ = taillard_insert(seq, idx)
                seq.insert(pos, idx)
        return seq

    # Try multiple priority orders: total processing time and slope
    priority_tpt = sorted(range(N), key=lambda i: (-total_p[i], i))
    priority_slope = sorted(range(N), key=lambda i: (-slope[i], i))
    best_seq = neh_construct(priority_tpt)
    best_cmax = makespan(best_seq)
    seq2 = neh_construct(priority_slope)
    cmax2 = makespan(seq2)
    if cmax2 < best_cmax:
        best_seq, best_cmax = seq2, cmax2

    # Iterated Greedy with Metropolis acceptance
    T_param = 0.5
    total_processing = sum(total_p)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    current_seq = best_seq[:]
    current_cmax = best_cmax
    dest_size = 3 if N > 5 else max(1, N // 2)
    max_iter = 60
    random.seed(42)  # Deterministic behavior

    for _ in range(max_iter):
        # Destruction: remove dest_size jobs at random positions
        positions = random.sample(range(N), dest_size)
        positions.sort(reverse=True)
        removed = []
        for pos in positions:
