    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flatten times for faster access
    flat = [t for row in times for t in row]
    def p(i, j): return flat[i * M + j]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            base = 0
            for m in range(M):
                base = max(t[m], base) + p(job, m)
                t[m] = base
        return t[-1]

    # Taillard's forward completion matrix for a given permutation
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][0] = prev + p(job, 0)
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + p(job, m)
        return e

    # Taillard's backward tail matrix for a given permutation
    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p(job, m)
                else:
                    down = q[r][m+1]
                    right = q[r+1][m]
                    q[r][m] = max(down, right) + p(job, m)
        return q

    # NEH construction with Taillard acceleration and first-machine penalty
    total_time = [sum(p(i, j) for j in range(M)) for i in range(N)]
    first_machine = [p(i, 0) for i in range(N)]
    # Penalty: subtract a fraction of first machine time to avoid bottleneck jobs early
    penalty_factor = 0.3
    adjusted_priority = [total_time[i] - penalty_factor * first_machine[i] for i in range(N)]
    order = sorted(range(N), key=lambda i: adjusted_priority[i], reverse=True)

    # Start with first two jobs
    best_seq = [order[0], order[1]]
    best_mk = makespan(best_seq)
    alt_seq = [order[1], order[0]]
    alt_mk = makespan(alt_seq)
    if alt_mk < best_mk:
        best_seq, best_mk = alt_seq, alt_mk

    current_seq = best_seq[:]
    for k in range(2, N):
        job = order[k]
        best_pos = 0
        best_mk_insert = float('inf')
        e = compute_forward(current_seq)
        q = compute_backward(current_seq)
        for i in range(k+1):
            # Compute forward vector f for inserting job at position i
            f = [0] * M
            if i == 0:
                prev_e = [0] * M
            else:
                prev_e = e[i-1]
            for m in range(M):
                if m == 0:
                    f[0] = prev_e[0] + p(job, 0)
                else:
                    f[m] = max(f[m-1], prev_e[m]) + p(job, m)
            # Compute makespan: max over m of f[m] + q[i][m]
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk_insert:
                best_mk_insert = mk
                best_pos = i
