    current = current_seq[:]
    best = current_seq[:]
    best_mk = makespan(best)
    total_processing = sum(total_time)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N < 30 else 4
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for _ in range(max_iter):
        if no_improve >= no_improve_limit:
            break
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del current[idx]
        # Reconstruction: reinsert each removed job using NEH insertion with Taillard
        for job in removed:
            best_pos = 0
            best_mk_insert = float('inf')
            e = compute_forward(current)
            q = compute_backward(current)
            for i in range(len(current)+1):
                if i == 0:
                    prev_e = [0] * M
                else:
                    prev_e = e[i-1]
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        f[0] = prev_e[0] + p(job, 0)
                    else:
                        f[m] = max(f[m-1], prev_e[m]) + p(job, m)
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk_insert:
                    best_mk_insert = mk
                    best_pos = i
            current.insert(best_pos, job)
        # Acceptance criterion
        mk_current = makespan(current)
        if mk_current < best_mk:
            best = current[:]
            best_mk = mk_current
            no_improve = 0
        elif mk_current < makespan(best):
            current = current[:]
            no_improve += 1
        else:
            delta = mk_current - makespan(best)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current = current[:]
                no_improve += 1
            else:
                # Revert to previous current (not best) if not accepted
                # For simplicity, we keep current as is and count as no improve
                no_improve += 1

    return best

