    proc = times
    total = [sum(job) for job in proc]

    # Helper: compute makespan using iterative DP
    def makespan(seq):
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += proc[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + proc[job][m]
        return t[-1]

    # Taillard acceleration: compute forward matrix e for prefix seq[0:k]
    def compute_forward(seq, k):
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = seq[r]
            pj = proc[job]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    # Taillard acceleration: compute backward matrix q for suffix seq[r:k]
    def compute_backward(seq, k):
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            pj = proc[job]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    # NEH construction with Taillard acceleration
    def neh_construct():
        order = sorted(range(N), key=lambda i: total[i], reverse=True)
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        # Try both orders for first two
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            e = compute_forward(seq, k)
            q = compute_backward(seq, k)
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Compute forward vector f for inserting job at position i
                f = [0] * M
                if i == 0:
                    f[0] = proc[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + proc[job][m]
                else:
                    f[0] = e[i-1][0] + proc[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + proc[job][m]
                # Compute makespan candidate
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(init_seq, max_iter=60):
        current = init_seq[:]
        best = current[:]
        best_mk = makespan(current)
        total_proc = sum(total)
        T_param = 0.5
        T = T_param * total_proc / (10 * N * M)
        d = 3 if N > 20 else 2
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build partial sequence without removed indices
            marker = [False] * N
            for idx in indices:
                marker[idx] = True
            partial = [current[i] for i in range(N) if not marker[i]]
            # Reconstruction: reinsert each removed job using Taillard acceleration
            for job in removed:
                k = len(partial)
                e = compute_forward(partial, k)
                q = compute_backward(partial, k)
                best_pos = 0
                best_mk_ins = float('inf')
                for i in range(k+1):
                    f = [0] * M
                    if i == 0:
                        f[0] = proc[job][0]
                        for m in range(1, M):
                            f[m] = f[m-1] + proc[job][m]
                    else:
                        f[0] = e[i-1][0] + proc[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + proc[job][m]
                    mk_ins = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk_ins:
                            mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                partial.insert(best_pos, job)
            current = partial
            mk = makespan(current)
            if mk < best_mk:
                best_mk = mk
                best = current[:]
            # Metropolis acceptance
            if mk < makespan(init_seq) or random.random() < math.exp(-(mk - makespan(init_seq)) / T):
                init_seq = current[:]
        return best

    # Run NEH then IG
    init_seq = neh_construct()
    final_seq = iterated_greedy(init_seq)
    return final_seq

