    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    # Taillard-accelerated insertion: given current perm, job x, and position i, return makespan
    def insertion_makespan(perm, x, i):
        k = len(perm)
        # Forward matrix e[0..k-1][0..M-1]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            job_t = times[job]
            if r == 0:
                e[0][0] = job_t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_t[m]
            else:
                e[r][0] = e[r-1][0] + job_t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
        # Backward matrix q[0..k][0..M-1]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            job_t = times[job]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        # Forward vector f for job x at position i
        f = [0] * M
        if i == 0:
            f[0] = times[x][0]
            for m in range(1, M):
                f[m] = f[m-1] + times[x][m]
        else:
            prev = e[i-1]
            f[0] = prev[0] + times[x][0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev[m]) + times[x][m]
        # Compute makespan for insertion at i
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
