                    pass
            else:
                if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                    current = partial[:]
        return best

    # Run NEH then IG
    initial = neh_construction()
    improved = iterated_greedy(initial, max_iters=50)
    return improved

