                cmax_candidate = makespan_taillard_insert(current_seq[:i] + current_seq[i:], job)
                if cmax_candidate < best_cmax_insert:
                    best_cmax_insert = cmax_candidate
                    best_pos_insert = i
            current_seq.insert(best_pos_insert, job)
        current_cmax = makespan(current_seq)
        if current_cmax < best_cmax:
            best_cmax = current_cmax
            best_seq = current_seq[:]
        if current_cmax < makespan(best_seq):
            current_seq = best_seq[:]
        else:
            if random.random() < math.exp(-(current_cmax - makespan(best_seq)) / T):
                current_seq = current_seq[:]
            else:
                current_seq = best_seq[:]

    return best_seq

