import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    jobs = list(range(N))
    job_sums = [sum(times[j]) for j in jobs]
    jobs.sort(key=lambda j: job_sums[j], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for j in seq:
            tj = times[j]
            t[0] += tj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + tj[m]
        return t[-1]

    def taillard_makespan(seq, job_x, pos):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        if k > 0:
            job0 = seq[0]
            t0 = times[job0]
            e[0][0] = t0[0]
            for m in range(1, M):
                e[0][m] = e[0][m-1] + t0[m]
            for r in range(1, k):
                jr = seq[r]
                tr = times[jr]
                er = e[r]
                er_prev = e[r-1]
                er[0] = er_prev[0] + tr[0]
                for m in range(1, M):
                    er[m] = max(er_prev[m], er[m-1]) + tr[m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            jr = seq[r]
            tr = times[jr]
            qr = q[r]
            qr_next = q[r+1]
            qr[M-1] = qr_next[M-1] + tr[M-1]
            for m in range(M-2, -1, -1):
                qr[m] = max(qr_next[m], qr[m+1]) + tr[m]
        f = [0] * M
        if pos == 0:
            for m in range(M):
                f[m] = (0 if m == 0 else f[m-1]) + times[job_x][m]
        else:
            e_prev = e[pos-1]
            tj = times[job_x]
            f[0] = e_prev[0] + tj[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + tj[m]
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
        return best

    def neh_construct():
        if not jobs:
            return []
        seq = [jobs[0]]
        if len(jobs) > 1:
            j1 = jobs[1]
            seq1 = [jobs[0], j1]
            seq2 = [j1, jobs[0]]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, len(jobs)):
            job = jobs[idx]
            best_pos = 0
            best_ms = float('inf')
            for pos in range(len(seq) + 1):
                ms = taillard_makespan(seq, job, pos)
                if ms < best_ms:
                    best_ms = ms
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    def ig_improve(initial_seq, max_iters=60):
        if N <= 2:
            return initial_seq
        d = 3 if N > 5 else N
        current = initial_seq[:]
        best = current[:]
        best_ms = makespan(best)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        if T < 1e-9:
            T = 1e-9
        for _ in range(max_iters):
            destroyed = current[:]
            random.shuffle(destroyed)
            R = destroyed[:d]
            pi_D = destroyed[d:]
            for job in R:
                best_pos = 0
                best_ms_local = float('inf')
                for pos in range(len(pi_D) + 1):
                    ms = taillard_makespan(pi_D, job, pos)
                    if ms < best_ms_local:
                        best_ms_local = ms
                        best_pos = pos
                pi_D.insert(best_pos, job)
            new_seq = pi_D
            new_ms = makespan(new_seq)
            if new_ms < makespan(current) or random.random() < math.exp(-(new_ms - makespan(current)) / T):
                current = new_seq
                if new_ms < best_ms:
                    best = new_seq[:]
                    best_ms = new_ms
        return best

    initial_seq = neh_construct()
    improved_seq = ig_improve(initial_seq)
    return improved_seq

