def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    t_param = 0.5
    T = t_param * total_processing / (10 * n * m) if n * m > 0 else 0

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * m
        for job in seq:
            for i in range(m):
                if i == 0:
                    t[i] += job[i]
                else:
                    t[i] = max(t[i-1], t[i]) + job[i]
        return t[-1]

    def makespan_taillard(seq):
        if not seq:
            return 0
        k = len(seq)
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job = seq[r]
            for mc in range(m):
                if mc == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][mc] = prev + job[mc]
                else:
                    left = e[r][mc-1]
                    up = e[r-1][mc] if r > 0 else 0
                    e[r][mc] = max(left, up) + job[mc]
        return e[-1][-1] if k > 0 else 0

    def taillard_insert(seq, job):
        k = len(seq)
        if k == 0:
            return [job]
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job_r = seq[r]
            for mc in range(m):
                if mc == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][mc] = prev + job_r[mc]
                else:
                    left = e[r][mc-1]
                    up = e[r-1][mc] if r > 0 else 0
                    e[r][mc] = max(left, up) + job_r[mc]
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = seq[r]
            for mc in range(m-1, -1, -1):
                if mc == m-1:
                    q[r][mc] = q[r+1][mc] + job_r[mc]
                else:
                    down = q[r+1][mc]
                    right = q[r][mc+1]
                    q[r][mc] = max(down, right) + job_r[mc]
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            f = [0] * m
            for mc in range(m):
                if mc == 0:
                    prev = e[i-1][0] if i > 0 else 0
                    f[mc] = prev + job[mc]
                else:
                    left = f[mc-1]
                    up = e[i-1][mc] if i > 0 else 0
                    f[mc] = max(left, up) + job[mc]
            cmax = 0
            for mc in range(m):
                val = f[mc] + q[i][mc]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return seq[:best_pos] + [job] + seq[best_pos:]

    def neh_taillard():
        job_sums = [sum(job) for job in times]
        order = sorted(range(n), key=lambda i: job_sums[i], reverse=True)
        seq = [order[0]]
        for idx in range(1, n):
            seq = taillard_insert(seq, times[order[idx]])
        return seq

    current = neh_taillard()
    current_cmax = makespan_taillard(current)
    best_seq = list(current)
    best_cmax = current_cmax

    d = 3
    max_iter = 60
    for _ in range(max_iter):
        if current_cmax == 0:
            break
        indices = list(range(n))
        random.shuffle(indices)
        destroyed_indices = set(indices[:d])
        remaining_seq = [current[i] for i in range(n) if i not in destroyed_indices]
        removed_jobs = [current[i] for i in range(n) if i in destroyed_indices]
        random.shuffle(removed_jobs)
        for job_idx in removed_jobs:
            job = times[job_idx]
            remaining_seq = taillard_insert(remaining_seq, job)
        new_cmax = makespan_taillard(remaining_seq)
        if new_cmax < current_cmax or random.random() < math.exp(-(new_cmax - current_cmax) / T):
            current = remaining_seq
            current_cmax = new_cmax
            if new_cmax < best_cmax:
                best_seq = list(current)
                best_cmax = new_cmax
    return best_seq

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten processing times for faster access
    p = [job for job in times]  # p[i][j] is processing time of job i on machine j

    # Precompute total processing times for NEH priority
    total_time = [sum(job) for job in p]
    # Sort jobs by total processing time descending (NEH priority)
    order = sorted(range(N), key=lambda i: total_time[i], reverse=True)

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += p[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard acceleration: compute forward matrix e for a partial schedule
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job][m]
        return e

    # Taillard acceleration: compute backward tail matrix q for a partial schedule
    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]  # q[k] is all zeros
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]
        return q

    # Compute makespan after inserting job x at position i in partial schedule perm (length k)
    # Uses Taillard's O(M) evaluation per position
    def insertion_makespan(perm, x, i):
        k = len(perm)
        # Forward vector f for job x up to position i-1
        f = [0] * M
        if i == 0:
            # e[-1][m] = 0
            for m in range(M):
                if m == 0:
                    f[m] = p[x][m]
                else:
                    f[m] = max(f[m-1], 0) + p[x][m]
        else:
            # e[i-1] is the forward state after i-1 jobs
            e_prev = compute_forward(perm[:i])[-1]  # e[i-1][*]
            for m in range(M):
                if m == 0:
                    f[m] = e_prev[0] + p[x][m]
                else:
                    f[m] = max(f[m-1], e_prev[m]) + p[x][m]
        # Backward tail q[i] for the suffix starting at position i
        q_i = compute_backward(perm[i:])[0]  # q[i][*] for suffix perm[i:]
        # Makespan = max over m of (f[m] + q_i[m])
        makespan_val = 0
        for m in range(M):
            val = f[m] + q_i[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration for insertion evaluation
    def neh_construct():
        if N == 0:
            return []
        # Start with first two jobs
        best_seq = [order[0], order[1]]
        best_makespan = makespan(best_seq)
        rev_seq = [order[1], order[0]]
        rev_makespan = makespan(rev_seq)
        if rev_makespan < best_makespan:
            best_seq = rev_seq
            best_makespan = rev_makespan
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_val = float('inf')
            # Try all k+1 insertion positions
            for i in range(k+1):
                val = insertion_makespan(best_seq, job, i)
                if val < best_val:
                    best_val = val
                    best_pos = i
            # Insert job at best_pos
            best_seq.insert(best_pos, job)
        return best_seq

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_seq, max_iter=50):
        current = initial_seq[:]
        current_makespan = makespan(current)
        best_seq = current[:]
        best_makespan = current_makespan
        # Total processing sum for temperature calculation
        total_processing = sum(total_time)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2  # Destruction size

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in sorted(indices, reverse=True)]
            for idx in sorted(indices, reverse=True):
                del current[idx]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                best_pos = 0
                best_val = float('inf')
                # Try all insertion positions in current sequence
                for i in range(len(current) + 1):
                    val = insertion_makespan(current, job, i)
                    if val < best_val:
                        best_val = val
                        best_pos = i
                current.insert(best_pos, job)
            # Evaluate new sequence
            new_makespan = makespan(current)
            # Acceptance criterion
            if new_makespan < current_makespan:
                current_makespan = new_makespan
                if new_makespan < best_makespan:
                    best_makespan = new_makespan
                    best_seq = current[:]
            else:
                if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                    current_makespan = new_makespan
                    # Note: we do not update best unless it's better
                # else: reject, keep current
        return best_seq

    # Build initial solution using NEH
    initial_seq = neh_construct()
    # Refine with Iterated Greedy
    improved_seq = iterated_greedy(initial_seq, max_iter=60)
    return improved_seq

