    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for each job
    total_times = [sum(job) for job in times]
    # Sort jobs by total processing time descending
    sorted_jobs = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Helper: makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        # Use a 1D array for current machine completion times
        machine_time = [0] * M
        for job in perm:
            job_time = times[job]
            machine_time[0] += job_time[0]
            for m in range(1, M):
                machine_time[m] = max(machine_time[m], machine_time[m-1]) + job_time[m]
        return machine_time[-1]

    # Taillard's accelerated makespan evaluation for insertion
    def insertion_makespan(current_perm, job, pos):
        k = len(current_perm)
        # Forward matrix e: completion times of current_perm
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = current_perm[r]
            p_r = times[job_r]
            if r == 0:
                e[0][0] = p_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p_r[m]
            else:
                e[r][0] = e[r-1][0] + p_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p_r[m]
        # Backward matrix q: tail times
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = current_perm[r]
            p_r = times[job_r]
            q[r][M-1] = q[r+1][M-1] + p_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p_r[m]
        # Forward vector f for inserting 'job' at position 'pos'
        f = [0] * M
        if pos == 0:
            prev_e = [0] * M
        else:
            prev_e = e[pos-1]
        p_job = times[job]
        f[0] = prev_e[0] + p_job[0]
        for m in range(1, M):
            f[m] = max(f[m-1], prev_e[m]) + p_job[m]
        # Compute makespan: max over m of f[m] + q[pos][m]
        max_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > max_val:
                max_val = val
        return max_val

    # Construct initial solution using NEH with Taillard acceleration
    perm = []
    for idx in sorted_jobs:
        if not perm:
            perm.append(idx)
        elif len(perm) == 1:
            # Evaluate both orders for the first two jobs
            c1 = insertion_makespan([perm[0]], idx, 1)  # insert at end
            c2 = insertion_makespan([perm[0]], idx, 0)  # insert at front
            if c1 <= c2:
                perm.append(idx)
            else:
                perm.insert(0, idx)
        else:
            best_pos = 0
            best_cmax = float('inf')
            # Try all insertion positions
            for pos in range(len(perm) + 1):
                cmax = insertion_makespan(perm, idx, pos)
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = pos
            perm.insert(best_pos, idx)

    # Iterated Greedy refinement
    current_perm = perm[:]
    current_cmax = makespan(current_perm)
    best_perm = current_perm[:]
    best_cmax = current_cmax

    # Calculate average processing time for temperature scaling
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

    destruction_size = 3 if N >= 3 else N
    max_iterations = 50  # Adjusted to stay within time budget

    for _ in range(max_iterations):
        # Destruction: remove 'destruction_size' jobs at random positions
        if destruction_size == 0:
            destroyed_perm = current_perm[:]
            R = []
        else:
            positions = random.sample(range(N), destruction_size)
            positions.sort(reverse=True)
            R = []
            destroyed_perm = current_perm[:]
            for pos in positions:
                R.append(destroyed_perm.pop(pos))
        # Reconstruction: reinsert jobs in R using NEH insertion with Taillard
        for job in R:
            if not destroyed_perm:
                destroyed_perm.append(job)
            elif len(destroyed_perm) == 1:
                c1 = insertion_makespan([destroyed_perm[0]], job, 1)
                c2 = insertion_makespan([destroyed_perm[0]], job, 0)
                if c1 <= c2:
                    destroyed_perm.append(job)
                else:
                    destroyed_perm.insert(0, job)
            else:
                best_pos = 0
                best_cmax = float('inf')
                for pos in range(len(destroyed_perm) + 1):
                    cmax = insertion_makespan(destroyed_perm, job, pos)
                    if cmax < best_cmax:
                        best_cmax = cmax
                        best_pos = pos
                destroyed_perm.insert(best_pos, job)
        # Evaluate new solution
        new_cmax = makespan(destroyed_perm)
        # Acceptance criterion
        if new_cmax < current_cmax:
            current_perm = destroyed_perm[:]
            current_cmax = new_cmax
            if new_cmax < best_cmax:
                best_perm = current_perm[:]
                best_cmax = new_cmax
        else:
            if random.random() < math.exp(-(new_cmax - current_cmax) / T):
                current_perm = destroyed_perm[:]
                current_cmax = new_cmax

    return best_perm

