        e = [[0] * M for _ in range(k)]
        if k == 0:
            return e
        for m in range(M):
            e[0][m] = times[seq[0]][m]
        for i in range(1, k):
            job = seq[i]
            e[i][0] = e[i-1][0] + times[job][0]
            for m in range(1, M):
                e[i][m] = max(e[i-1][m], e[i][m-1]) + times[job][m]
        return e

    def compute_backward_tail(seq):
