        for m in range(M):
            q[k][m] = 0
        for i in range(k-1, -1, -1):
            job = seq[i]
            q[i][M-1] = q[i+1][M-1] + times[job][M-1]
            for m in range(M-2, -1, -1):
                q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job][m]
