        if pos == 0:
            for m in range(M):
                f[m] = times[job][m]
        else:
            f[0] = e[pos-1][0] + times[job][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + times[job][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_construct():
        if N == 0:
            return []
        seq = [order[0]]
        for k in range(1, N):
            job = order[k]
            e = compute_forward_tail(seq)
            q = compute_backward_tail(seq)
            best_pos = 0
            best_cost = float('inf')
            for pos in range(k+1):
                cost = insertion_cost(seq, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    current = neh_construct()
    best = current[:]
    best_makespan = makespan(current)
    if best_makespan == lower_bound:
        return best

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 50
    if N > 60:
        max_iter = 30
    if N > 100:
        max_iter = 20

    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            R = current[:]
        else:
            indices = random.sample(range(len(current)), d)
            indices.sort(reverse=True)
            R = [current[i] for i in indices]
            destroyed = current[:]
            for idx in indices:
                destroyed.pop(idx)
        pi_D = destroyed
        for job in R:
            if not pi_D:
                pi_D = [job]
                continue
            e = compute_forward_tail(pi_D)
            q = compute_backward_tail(pi_D)
            best_pos = 0
            best_cost = float('inf')
            for pos in range(len(pi_D)+1):
                cost = insertion_cost(pi_D, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            pi_D.insert(best_pos, job)
        current = pi_D
        current_makespan = makespan(current)
        if current_makespan < best_makespan:
            best_makespan = current_makespan
            best = current[:]
            if best_makespan == lower_bound:
                break
        if current_makespan < makespan(best):
            best = current[:]
        if current_makespan < makespan(current):
            pass
        else:
            if makespan(current) > 0:
                delta = current_makespan - makespan(current)
                if delta < 0:
                    accept = True
                else:
                    accept = random.random() < math.exp(-delta / T)
                if accept:
                    pass
                else:
                    current = best[:]

    return best

