def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    if n == 1:
        return [0]
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Compute variance for each machine to weight slope index
    var = [0.0] * m
    for j in range(m):
        mean = sum(times[i][j] for i in range(n)) / n
        var[j] = sum((times[i][j] - mean) ** 2 for i in range(n)) / n
        if var[j] == 0:
            var[j] = 1.0  # Avoid division by zero

    # Compute weighted slope index: S_i = sum_j (2j - m + 1) * p_ij / var_j
    slope = [0.0] * n
    for i in range(n):
        s = 0.0
        for j in range(m):
            s += (2 * j - m + 1) * times[i][j] / var[j]
        slope[i] = s

    # Sort jobs by slope descending (high slope -> early in schedule)
    order = sorted(range(n), key=lambda i: slope[i], reverse=True)

    # Taillard-accelerated NEH construction
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for idx in perm:
            job = times[idx]
            t[0] += job[0]
            for k in range(1, m):
                t[k] = max(t[k-1], t[k]) + job[k]
        return t[-1]

    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0]*m for _ in range(k)]
        e = [[0]*m for _ in range(k)]
        for r in range(k):
            job_idx = perm[r]
            p = times[job_idx]
            if r == 0:
                e[0][0] = p[0]
                for mc in range(1, m):
                    e[0][mc] = e[0][mc-1] + p[mc]
            else:
                e[r][0] = e[r-1][0] + p[0]
                for mc in range(1, m):
                    e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + p[mc]
        return e

    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0]*m for _ in range(k+1)]
        q = [[0]*m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_idx = perm[r]
            p = times[job_idx]
            if r == k-1:
                for mc in range(m):
                    q[r][mc] = p[mc]
            else:
                q[r][m-1] = q[r+1][m-1] + p[m-1]
                for mc in range(m-2, -1, -1):
                    q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + p[mc]
        return q

    def makespan_with_insertion(perm, pos, job_idx):
        k = len(perm)
        e = compute_forward(perm)
        q = compute_backward(perm)
        f = [0] * m
        pj = times[job_idx]
        # Compute forward vector f for insertion at pos
        if pos == 0:
            prev_e = [0] * m
        else:
            prev_e = e[pos-1]
        f[0] = prev_e[0] + pj[0]
        for mc in range(1, m):
            f[mc] = max(f[mc-1], prev_e[mc]) + pj[mc]
        # Compute makespan: max over m of f[m] + q[pos][m]
        makespan_val = 0
        for mc in range(m):
            val = f[mc] + q[pos][mc]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    perm = []
    for idx in order:
        best_pos = 0
        best_ms = float('inf')
        for pos in range(len(perm) + 1):
            ms = makespan_with_insertion(perm, pos, idx)
            if ms < best_ms:
                best_ms = ms
                best_pos = pos
        perm.insert(best_pos, idx)

    # Iterated Greedy refinement
    random.seed(42)  # Deterministic seed for reproducibility
    current = perm[:]
    best = current[:]
    best_ms = makespan(best)
    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
    d = 3  # Destruction size
    max_iter = 60  # Calibrated for <50ms

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(n), d)
        removed = [current[i] for i in indices]
        # Build partial sequence without removed indices
        current_set = set(indices)
        pi_D = [current[i] for i in range(n) if i not in current_set]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_ms_insert = float('inf')
            for pos in range(len(pi_D) + 1):
                ms = makespan_with_insertion(pi_D, pos, job)
                if ms < best_ms_insert:
                    best_ms_insert = ms
                    best_pos = pos
            pi_D.insert(best_pos, job)
        # Acceptance criterion
        new_ms = makespan(pi_D)
        if new_ms < best_ms:
            best_ms = new_ms
            best = pi_D[:]
            current = pi_D[:]
        elif new_ms < makespan(current):
            current = pi_D[:]
        else:
            if random.random() < math.exp(-(new_ms - makespan(current)) / T):
                current = pi_D[:]
    return best

