            e = compute_forward(perm)
            q = compute_backward(perm)
            for idx in range(2, N):
                job = order[idx]
                pos = insert_job(perm, job, e, q)
                perm.insert(pos, job)
                e = compute_forward(perm)
                q = compute_backward(perm)
        return perm

    current = neh_construct()
    best = current[:]
    best_cmax = makespan(best)

    bottleneck = max(range(M), key=lambda m: sum(times[i][m] for i in range(N)))
