    for l in range(1, M):
        mach_a = [sum(job[:l]) for job in job_data]
        mach_b = [sum(job[l:]) for job in job_data]
        seq = johnson_rule(mach_a, mach_b)
        mk = makespan(seq)
        if mk < best_makespan:
            best_makespan = mk
