    p = [row[:] for row in times]  # N x M
    total = [sum(row) for row in p]
    slope = [sum((2 * j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]

    # Gupta's heuristic: sign-weighted machine differences
    gupta = [0] * N
    for i in range(N):
        early_sum = 0
        late_sum = 0
        mid = M // 2
        for j in range(M):
            if j < mid:
                early_sum += p[i][j]
            elif j >= mid:
                late_sum += p[i][j]
        gupta[i] = early_sum - late_sum  # Positive: early-loaded, negative: late-loaded

    # Combined priority: prioritize Gupta, then slope, then total
    priority = list(range(N))
    priority.sort(key=lambda i: (-gupta[i], -slope[i], -total[i]))

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard's accelerated insertion evaluation for a job into a partial schedule
    def evaluate_insertion(partial, job, k):
        # partial: list of job indices of length k
        if k == 0:
            f = [p[job][m] for m in range(M)]
            return max(f)
        # Forward matrix e: completion times of partial schedule
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            if r == 0:
                e[0][0] = p[job_r][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[job_r][m]
            else:
                e[r][0] = e[r-1][0] + p[job_r][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]
        # Backward matrix q: tail times from position r
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            if r == k-1:
                q[r][M-1] = p[job_r][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = q[r][m+1] + p[job_r][m]
            else:
                q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
        # Evaluate all insertion positions
        best_pos = 0
        best_val = float('inf')
        for i in range(k+1):
            # Forward pass for job at position i
            f = [0] * M
            if i == 0:
                f[0] = p[job][0]
                for m in range(1, M):
                    f[m] = f[m-1] + p[job][m]
            else:
                prev = e[i-1]
                f[0] = prev[0] + p[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev[m]) + p[job][m]
            # Compute makespan candidate: max_m (f[m] + q[i][m])
            curr_max = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > curr_max:
                    curr_max = val
            if curr_max < best_val:
                best_val = curr_max
                best_pos = i
        return best_pos, best_val

    # NEH construction with Taillard acceleration
    def neh_construction(jobs):
        if not jobs:
            return []
        seq = [jobs[0]]
        if len(jobs) > 1:
            job1, job2 = jobs[0], jobs[1]
            seq1 = [job1, job2]
            seq2 = [job2, job1]
            if makespan(seq1) <= makespan(seq2):
                seq = seq1
            else:
                seq = seq2
        for idx in range(2, len(jobs)):
            job = jobs[idx]
            pos, _ = evaluate_insertion(seq, job, len(seq))
            seq.insert(pos, job)
        return seq

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_seq, max_iter=50):
        current = initial_seq[:]
        best = current[:]
        best_makespan = makespan(best)
        total_processing = sum(total)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        d = 3 if N > 20 else 2  # Destruction size

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build destroyed sequence by keeping non-removed jobs in order
            destroyed = [current[i] for i in range(N) if i not in indices]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            seq = destroyed[:]
            for job in removed:
                pos, _ = evaluate_insertion(seq, job, len(seq))
                seq.insert(pos, job)
            # Acceptance criterion
            curr_makespan = makespan(seq)
            if curr_makespan < best_makespan:
                best_makespan = curr_makespan
                best = seq[:]
                current = seq[:]
            elif curr_makespan < makespan(current):
                current = seq[:]
            else:
                if random.random() < math.exp(-(curr_makespan - makespan(current)) / T):
                    current = seq[:]
        return best

    # Build initial solution using NEH with Gupta-sorted priority
    initial_seq = neh_construction(priority)
    # Refine with Iterated Greedy
    improved_seq = iterated_greedy(initial_seq, max_iter=60)
    return improved_seq

