    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    def makespan_with_taillard(seq):
        if not seq:
            return 0
        e = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    e[m] += times[job][m]
                else:
                    e[m] = max(e[m], e[m-1]) + times[job][m]
        return e[-1]

    def compute_forward_backward(seq):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        if k > 0:
            for m in range(M):
                e[0][m] = times[seq[0]][m] if m == 0 else (e[0][m-1] + times[seq[0]][m])
            for i in range(1, k):
                for m in range(M):
                    if m == 0:
                        e[i][m] = e[i-1][m] + times[seq[i]][m]
                    else:
                        e[i][m] = max(e[i-1][m], e[i][m-1]) + times[seq[i]][m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for i in range(k-1, -1, -1):
            job = seq[i]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[i][m] = q[i+1][m] + times[job][m]
                else:
                    q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job][m]
        return e, q

    def insert_job_with_taillard(seq, job, e, q, pos):
        k = len(seq)
        f = [0] * M
        if pos == 0:
            prev_e = [0] * M
        else:
            prev_e = e[pos-1]
        for m in range(M):
            if m == 0:
                f[m] = prev_e[m] + times[job][m]
            else:
                f[m] = max(f[m-1], prev_e[m]) + times[job][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_construction():
        job_sums = [sum(job) for job in times]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        best_makespan = float('inf')
        best_seq = None
        for first, second in [(order[0], order[1]), (order[1], order[0])]:
            s = [first, second]
            ms = makespan_with_taillard(s)
            if ms < best_makespan:
                best_makespan = ms
                best_seq = s[:]
        seq = best_seq
        e, q = compute_forward_backward(seq)
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_ms = float('inf')
            for pos in range(k+1):
                ms = insert_job_with_taillard(seq, job, e, q, pos)
                if ms < best_ms:
                    best_ms = ms
                    best_pos = pos
            seq.insert(best_pos, job)
            e, q = compute_forward_backward(seq)
        return seq

    def destruction_construction(seq, d):
        if d >= len(seq):
            return neh_construction()
        indices = random.sample(range(len(seq)), d)
        removed = [seq[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del seq[idx]
        e, q = compute_forward_backward(seq)
        random.shuffle(removed)
        for job in removed:
            best_pos = 0
            best_ms = float('inf')
            for pos in range(len(seq)+1):
                ms = insert_job_with_taillard(seq, job, e, q, pos)
                if ms < best_ms:
                    best_ms = ms
                    best_pos = pos
            seq.insert(best_pos, job)
            e, q = compute_forward_backward(seq)
        return seq

    current_seq = neh_construction()
    best_seq = current_seq[:]
    best_ms = makespan_with_taillard(best_seq)
    if best_ms == 0:
        return best_seq

    max_iter = 60
    for _ in range(max_iter):
        d = 3 if N < 30 else 4
        new_seq = destruction_construction(current_seq[:], d)
        new_ms = makespan_with_taillard(new_seq)
        if new_ms < best_ms:
            best_ms = new_ms
            best_seq = new_seq[:]
        if new_ms < makespan_with_taillard(current_seq):
            current_seq = new_seq
        else:
            delta = new_ms - makespan_with_taillard(current_seq)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current_seq = new_seq
        if best_ms == 0:
            break

    return best_seq

