def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flatten times for faster access
    flat = [p for row in times for p in row]
    def p(i, j):
        return flat[i * M + j]

    total_processing = sum(flat)
    # Temperature parameter for IG
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0

    # Makespan computation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            base = t[0] + p(job, 0)
            t[0] = base
            for m in range(1, M):
                base = max(t[m], base) + p(job, m)
                t[m] = base
        return t[-1]

    # Taillard acceleration: forward matrix
    def compute_forward(seq):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = seq[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][0] = prev + p(job, 0)
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + p(job, m)
        return e

    # Taillard acceleration: backward tail matrix
    def compute_backward(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p(job, m)
                else:
                    down = q[r][m+1]
                    right = q[r+1][m]
                    q[r][m] = max(down, right) + p(job, m)
        return q

    # Evaluate insertion of job x at position i using Taillard's O(M) method
    def evaluate_insertion(e, q, x, i):
        k = len(e)  # current seq length
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev_e = e[i-1][0] if i > 0 else 0
                f[0] = prev_e + p(x, 0)
            else:
                left = f[m-1]
                up = e[i-1][m] if i > 0 else 0
                f[m] = max(left, up) + p(x, m)
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    P = [sum(p(i, j) for j in range(M)) for i in range(N)]
    order = sorted(range(N), key=lambda i: (-P[i], i))
    seq = [order[0]]
    if N > 1:
        # initial pair
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        # greedy insertion
        for k in range(2, N):
            job = order[k]
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_cmax = float('inf')
            best_idle = float('inf')
            for i in range(k+1):
                cmax = evaluate_insertion(e, q, job, i)
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = i
                    # compute idle time on last machine for tie-breaking
                    if i == 0:
                        prev_end = 0
                    else:
                        prev_end = e[i-1][M-1]
                    if i == k:
                        next_start = 0
                    else:
                        next_start = q[i][M-1]
                    idle = max(0, next_start - prev_end - p(job, M-1))
                    best_idle = idle
                elif cmax == best_cmax:
                    # tie-break: minimize idle time on last machine
                    if i == 0:
                        prev_end = 0
                    else:
                        prev_end = e[i-1][M-1]
                    if i == k:
                        next_start = 0
                    else:
                        next_start = q[i][M-1]
                    idle = max(0, next_start - prev_end - p(job, M-1))
                    if idle < best_idle:
                        best_pos = i
                        best_idle = idle
            seq.insert(best_pos, job)
    # Iterated Greedy refinement
    best_seq = seq[:]
    best_cmax = makespan(seq)
    current_seq = seq[:]
    max_iter = 60  # calibrated for <50ms
    d = 3  # destruction size
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            R = current_seq[:]
        else:
            indices = random.sample(range(N), d)
            indices.sort(reverse=True)
            R = [current_seq[i] for i in indices]
            destroyed = current_seq[:]
            for idx in indices:
                destroyed.pop(idx)
        # Reconstruction: reinsert jobs in R using NEH insertion with Taillard
        for job in R:
            e = compute_forward(destroyed)
            q = compute_backward(destroyed)
            best_pos = 0
            best_cmax_ins = float('inf')
            best_idle = float('inf')
            for i in range(len(destroyed)+1):
                cmax = evaluate_insertion(e, q, job, i)
                if cmax < best_cmax_ins:
                    best_cmax_ins = cmax
                    best_pos = i
                    if i == 0:
                        prev_end = 0
                    else:
                        prev_end = e[i-1][M-1]
                    if i == len(destroyed):
                        next_start = 0
                    else:
                        next_start = q[i][M-1]
                    idle = max(0, next_start - prev_end - p(job, M-1))
                    best_idle = idle
                elif cmax == best_cmax_ins:
                    if i == 0:
                        prev_end = 0
                    else:
                        prev_end = e[i-1][M-1]
                    if i == len(destroyed):
                        next_start = 0
                    else:
                        next_start = q[i][M-1]
                    idle = max(0, next_start - prev_end - p(job, M-1))
                    if idle < best_idle:
                        best_pos = i
                        best_idle = idle
            destroyed.insert(best_pos, job)
        current_seq = destroyed
        current_cmax = makespan(current_seq)
        if current_cmax < best_cmax:
            best_cmax = current_cmax
            best_seq = current_seq[:]
        # Metropolis acceptance
        if current_cmax < makespan(seq) or random.random() < math.exp(-(current_cmax - makespan(seq)) / T):
            seq = current_seq[:]
    return best_seq

