    def taillard_insertion(perm, job):
        k = len(perm)
        if k == 0:
            return [job]
        # Forward matrix e: completion times of current perm
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job_r = perm[r]
            for c in range(m):
                if c == 0:
                    e[r][c] = (e[r-1][c] if r > 0 else 0) + times[job_r][c]
                else:
                    e[r][c] = max(e[r-1][c] if r > 0 else 0, e[r][c-1]) + times[job_r][c]
        # Backward matrix q: tail times from each position
        q = [[0] * m for _ in range(k+1)]  # q[k][*] = 0
        for r in range(k-1, -1, -1):
            job_r = perm[r]
            for c in range(m-1, -1, -1):
                if c == m-1:
                    q[r][c] = q[r+1][c] + times[job_r][c]
                else:
                    q[r][c] = max(q[r+1][c], q[r][c+1]) + times[job_r][c]
        best_pos = 0
        best_ms = float('inf')
        # Try inserting job at each position i in [0, k]
        for i in range(k+1):
            # Compute forward vector f for job at position i
            f = [0] * m
            for c in range(m):
                if c == 0:
                    prev = e[i-1][c] if i > 0 else 0
                    f[c] = prev + times[job][c]
                else:
                    prev = e[i-1][c] if i > 0 else 0
                    f[c] = max(f[c-1], prev) + times[job][c]
            # Compute makespan if job inserted at i
            ms = 0
            for c in range(m):
                val = f[c] + q[i][c]
                if val > ms:
