            if ms < best_ms:
                best_ms = ms
                best_pos = i
        return perm[:best_pos] + [job] + perm[best_pos:]

    # Build initial solution using NEH
    perm = []
    for idx in order:
        perm = taillard_insertion(perm, idx)

    # Iterated Greedy refinement
    current = perm[:]
    best = current[:]
    best_ms = makespan(best)
    total_processing = sum(total)
