def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job data for fast access
    p = [row[:] for row in times]
    P = [sum(row) for row in p]

    # Makespan evaluation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard's acceleration: compute forward matrix e and backward matrix q for a partial schedule
    def compute_eq(partial):
        k = len(partial)
        if k == 0:
            return ([], [[0]*M for _ in range(k+1)])
        e = [[0]*M for _ in range(k)]
        # Forward pass
        for r in range(k):
            job = partial[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][0] = prev + p[job][0]
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + p[job][m]
        # Backward pass
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    down = q[r+1][m]
                    q[r][m] = down + p[job][m]
                else:
                    right = q[r][m+1]
                    down = q[r+1][m]
                    q[r][m] = max(right, down) + p[job][m]
        return (e, q)

    # Evaluate makespan when inserting job x at position i in partial schedule using Taillard's scheme
    def insertion_makespan(partial, e, q, x, i):
        k = len(partial)
        # Compute forward vector f for job x up to position i-1
        f = [0] * M
        if i == 0:
            # Insert at beginning
            for m in range(M):
                if m == 0:
                    f[0] = p[x][0]
                else:
                    f[m] = f[m-1] + p[x][m]
        else:
            # Insert after position i-1
            for m in range(M):
                if m == 0:
                    f[0] = e[i-1][0] + p[x][0]
                else:
                    f[m] = max(f[m-1], e[i-1][m]) + p[x][m]
        # Compute makespan as max over m of f[m] + q[i][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration
    def neh_construction():
        # Sort jobs by total processing time descending
        order = sorted(range(N), key=lambda i: P[i], reverse=True)
        if N == 0:
            return []
        # Start with first job
        perm = [order[0]]
        if N == 1:
            return perm
        # Try both orders for first two jobs
        perm1 = [order[0], order[1]]
        perm2 = [order[1], order[0]]
        if makespan(perm1) <= makespan(perm2):
            perm = perm1
        else:
            perm = perm2
        # Insert remaining jobs one by one
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_makespan = float('inf')
            partial = perm[:k]  # current partial schedule of length k
            e, q = compute_eq(partial)
            # Try all k+1 insertion positions
            for i in range(k+1):
                m = insertion_makespan(partial, e, q, job, i)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_perm):
        current = initial_perm[:]
        best = current[:]
        best_makespan = makespan(best)
        total_processing = sum(P)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N >= 3 else N
        max_iter = 60  # calibrated to stay within time budget
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build destroyed sequence by keeping non-removed jobs in order
            destroyed = [current[i] for i in range(N) if i not in set(indices)]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                best_pos = 0
                best_m = float('inf')
                # Try all positions in current destroyed sequence
                for i in range(len(destroyed) + 1):
                    # Compute e and q for destroyed prefix up to i
                    prefix = destroyed[:i]
                    e, q = compute_eq(prefix)
                    m = insertion_makespan(prefix, e, q, job, i)
                    if m < best_m:
                        best_m = m
                        best_pos = i
                destroyed.insert(best_pos, job)
            # New candidate solution
            candidate = destroyed
            cand_makespan = makespan(candidate)
            # Acceptance criterion
            if cand_makespan < makespan(current):
                current = candidate
                if cand_makespan < best_makespan:
                    best = candidate[:]
                    best_makespan = cand_makespan
            else:
                if random.random() < math.exp(-(cand_makespan - makespan(current)) / T):
                    current = candidate
        return best

    # Generate initial solution and refine
    init_perm = neh_construction()
    refined_perm = iterated_greedy(init_perm)
    return refined_perm

