        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = times[perm[0]][m] if m == 0 else (e[0][m-1] + times[perm[0]][m])
        for r in range(1, k):
            job = perm[r]
            e[r][0] = e[r-1][0] + times[job][0]
            for m in range(1, M):
