            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = perm[r]
            q[r][M-1] = q[r+1][M-1] + times[job][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return q

    def insert_job_taillard(perm, job, e, q):
        k = len(perm)
        if k == 0:
            return [job], times[job][0] + sum(times[job][1:]) if M > 1 else times[job][0]
        best_pos = 0
