        for r in range(k):
            job = prefix[r]
            pj = times[job]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        return e

    # Helper: compute backward tail matrix for a prefix
    def compute_backward(prefix):
        k = len(prefix)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = prefix[r]
            pj = times[job]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        return q

    # Helper: evaluate insertion positions for a job into a prefix using Taillard acceleration
    def evaluate_insertions(prefix, job, e, q):
        k = len(prefix)
        f = [0] * M
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            if i == 0:
                f[0] = job
                for m in range(1, M):
                    f[m] = f[m-1] + job
            else:
                pj = times[job]
                f[0] = (e[i-1][0] if i-1 >= 0 else 0) + pj[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], (e[i-1][m] if i-1 >= 0 else 0)) + pj[m]
            makespan_val = 0
            for m in range(M):
                val = f[m] + (q[i][m] if i < len(q) else 0)
                if val > makespan_val:
                    makespan_val = val
            if makespan_val < best_makespan:
                best_makespan = makespan_val
                best_pos = i
        return best_pos, best_makespan

    # NEH construction with Taillard acceleration
    order = sorted(range(N), key=lambda i: (-total_times[i], -slope_indices[i]))
    perm = [order[0]]
    if N > 1:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        perm = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        e = compute_forward(perm)
        q = compute_backward(perm)
        for idx in range(2, N):
            job = order[idx]
            pos, _ = evaluate_insertions(perm, job, e, q)
            perm.insert(pos, job)
            e = compute_forward(perm)
            q = compute_backward(perm)

    # Iterated Greedy refinement
    random.seed(42)
    current = perm[:]
    best = perm[:]
    best_makespan = makespan(best)
    avg_pt = sum(total_times) / (N * M)
    T_param = 0.5
    T = T_param * avg_pt * N * M / 10.0
    d = 3 if N > 20 else 2
    max_iter = 60
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del current[i]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            e = compute_forward(current)
            q = compute_backward(current)
            pos, _ = evaluate_insertions(current, job, e, q)
            current.insert(pos, job)
        # Acceptance criterion
        curr_makespan = makespan(current)
        if curr_makespan < best_makespan:
            best_makespan = curr_makespan
            best = current[:]
        if curr_makespan < makespan(perm):
            perm = current[:]
        else:
            if random.random() < math.exp(-(curr_makespan - makespan(perm)) / T):
                perm = current[:]
            else:
                current = perm[:]
    return best

