def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[-1]

    def makespan_taillard(perm):
        if not perm:
            return 0
        e = [0] * M
        for job in perm:
            job_t = times[job]
            e[0] += job_t[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + job_t[m]
        return e[-1]

    def taillard_insertion_cost(partial, job_idx):
        k = len(partial)
        if k == 0:
            e_prev = [0] * M
        else:
            e_prev = [0] * M
            for idx in partial:
                job_t = times[idx]
                e_prev[0] += job_t[0]
                for m in range(1, M):
                    e_prev[m] = max(e_prev[m-1], e_prev[m]) + job_t[m]
        q = [0] * M
        for idx in reversed(partial):
            job_t = times[idx]
            q[M-1] += job_t[M-1]
            for m in range(M-2, -1, -1):
                q[m] = max(q[m], q[m+1]) + job_t[m]
        best_cost = float('inf')
        best_pos = 0
        job_t = times[job_idx]
        for i in range(k+1):
            if i == 0:
                f = job_t[:]
            else:
                f = [0] * M
                f[0] = e_prev[0] + job_t[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e_prev[m]) + job_t[m]
            cost = 0
            for m in range(M):
                val = f[m] + q[m]
                if val > cost:
                    cost = val
            if cost < best_cost:
                best_cost = cost
                best_pos = i
        return best_pos, best_cost

    def neh_taillard():
        job_sums = [sum(job) for job in times]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        seq = [order[0], order[1]]
        cost01 = makespan_taillard(seq)
        seq[0], seq[1] = seq[1], seq[0]
        cost10 = makespan_taillard(seq)
        if cost10 < cost01:
            seq = [order[1], order[0]]
        else:
            seq = [order[0], order[1]]
        for k in range(2, N):
            job_idx = order[k]
            pos, _ = taillard_insertion_cost(seq, job_idx)
            seq.insert(pos, job_idx)
        return seq

    current = neh_taillard()
    current_makespan = makespan_taillard(current)
    best = list(current)
    best_makespan = current_makespan

    max_iter = 60
    d = 3 if N > 20 else 2
    if N > 80:
        d = 4

    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            R = list(current)
        else:
            indices = random.sample(range(len(current)), d)
            indices.sort(reverse=True)
            destroyed = [current.pop(i) for i in indices]
            R = destroyed
        for job in R:
            pos, _ = taillard_insertion_cost(current, job)
            current.insert(pos, job)
        new_makespan = makespan_taillard(current)
        if new_makespan < current_makespan:
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_makespan = new_makespan
                best = list(current)
        elif new_makespan < best_makespan or random.random() < math.exp(-(new_makespan - current_makespan) / T):
            current_makespan = new_makespan
            best = list(current)
            best_makespan = new_makespan
        else:
            current_makespan = new_makespan

    return best

