        for r in range(k-1, -1, -1):
            job = perm[r]
            row = times[job]
            q[r][M-1] = q[r+1][M-1] + row[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + row[m]
