    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    total_processing = 0
    p = []
    for i in range(n):
        row = times[i]
        p.append(row)
        total_processing += sum(row)

    # Precompute total processing times for NEH priority
    total_time = [sum(p[i]) for i in range(n)]
    order = sorted(range(n), key=lambda i: total_time[i], reverse=True)

    # Makespan evaluation for a given sequence
    def makespan(seq):
        t = [0] * m
        for job in seq:
            for k in range(m):
                if k == 0:
                    t[k] += p[job][k]
                else:
                    t[k] = max(t[k], t[k-1]) + p[job][k]
        return t[-1]

    # NEH construction with Taillard acceleration
    def neh_construction():
        if n == 0:
            return []
        seq = [order[0]]
        if n == 1:
            return seq
        # Evaluate first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Insert remaining jobs
        for k in range(2, n):
            job = order[k]
            # Build forward matrix e for current seq (length k)
            e = [[0] * m for _ in range(k)]
            for r in range(k):
                job_r = seq[r]
                for mc in range(m):
                    if r == 0 and mc == 0:
                        e[r][mc] = p[job_r][mc]
                    elif r == 0:
                        e[r][mc] = e[r][mc-1] + p[job_r][mc]
                    elif mc == 0:
                        e[r][mc] = e[r-1][mc] + p[job_r][mc]
                    else:
                        e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + p[job_r][mc]
            # Build backward matrix q for current seq (length k)
            q = [[0] * m for _ in range(k+1)]  # q[k][*] = 0
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                for mc in range(m-1, -1, -1):
                    if r == k-1 and mc == m-1:
                        q[r][mc] = p[job_r][mc]
                    elif r == k-1:
                        q[r][mc] = q[r][mc+1] + p[job_r][mc]
                    elif mc == m-1:
                        q[r][mc] = q[r+1][mc] + p[job_r][mc]
                    else:
                        q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + p[job_r][mc]
            # Evaluate insertion positions
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Compute forward vector f for inserting job at position i
                f = [0] * m
                prev_e = e[i-1] if i-1 >= 0 else [0] * m
                for mc in range(m):
                    if mc == 0:
                        f[mc] = prev_e[mc] + p[job][mc]
                    else:
                        f[mc] = max(f[mc-1], prev_e[mc]) + p[job][mc]
                # Compute makespan candidate
                mk = 0
                for mc in range(m):
                    val = f[mc] + q[i][mc]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size 3 or 4
    def iterated_greedy(initial_seq):
        current = initial_seq[:]
        best = current[:]
