            indices.sort()
            removed = [current[i] for i in indices]
            # Build partial sequence
            partial = [current[i] for i in range(n) if i not in indices]
            # Reconstruction: reinsert removed jobs one by one
            for job in removed:
                # Build forward matrix e for current partial
                k = len(partial)
                if k == 0:
                    e = []
                else:
                    e = [[0] * m for _ in range(k)]
                    for r in range(k):
                        job_r = partial[r]
                        for mc in range(m):
                            if r == 0 and mc == 0:
                                e[r][mc] = p[job_r][mc]
                            elif r == 0:
                                e[r][mc] = e[r][mc-1] + p[job_r][mc]
                            elif mc == 0:
                                e[r][mc] = e[r-1][mc] + p[job_r][mc]
                            else:
                                e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + p[job_r][mc]
                # Build backward matrix q for current partial
                q = [[0] * m for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = partial[r]
                    for mc in range(m-1, -1, -1):
                        if r == k-1 and mc == m-1:
                            q[r][mc] = p[job_r][mc]
                        elif r == k-1:
                            q[r][mc] = q[r][mc+1] + p[job_r][mc]
                        elif mc == m-1:
                            q[r][mc] = q[r+1][mc] + p[job_r][mc]
                        else:
                            q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + p[job_r][mc]
                # Evaluate insertion positions
                best_pos = 0
                best_mk_ins = float('inf')
                for i in range(k+1):
                    f = [0] * m
                    prev_e = e[i-1] if i-1 >= 0 else [0] * m
                    for mc in range(m):
                        if mc == 0:
                            f[mc] = prev_e[mc] + p[job][mc]
                        else:
                            f[mc] = max(f[mc-1], prev_e[mc]) + p[job][mc]
                    mk_ins = 0
                    for mc in range(m):
                        val = f[mc] + q[i][mc]
                        if val > mk_ins:
                            mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                partial.insert(best_pos, job)
            # New candidate sequence
            candidate = partial
            mk_candidate = makespan(candidate)
            # Acceptance criterion
            if mk_candidate < makespan(current):
                current = candidate[:]
                if mk_candidate < best_mk:
                    best = candidate[:]
                    best_mk = mk_candidate
            else:
                delta = mk_candidate - makespan(current)
                if random.random() < math.exp(-delta / T):
                    current = candidate[:]
        return best

    # Build initial solution
    initial_seq = neh_construction()
    # Refine with IG
    final_seq = iterated_greedy(initial_seq)
    return final_seq

