    order = sorted(range(n), key=lambda i: (-total_processing[i], -job_data[i][bottleneck]))
    seq = [order[0]]
    for idx in range(1, n):
        job = order[idx]
        best_pos = 0
        best_cost = insertion_cost(seq, job, 0)
        for pos in range(1, len(seq)+1):
            cost = insertion_cost(seq, job, pos)
            if cost < best_cost:
                best_cost = cost
                best_pos = pos
        seq.insert(best_pos, job)

    # Iterated Greedy refinement
    random.seed(42)
    current = seq[:]
    best = seq[:]
    best_makespan = makespan(best)
    total_work = sum(total_processing)
    T_param = 0.5
    T = T_param * total_work / (10 * n * m) if n * m > 0 else 1e-6
    max_iter = 60
    d = 3 if n > 20 else 2

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= n:
            destroyed = []
            remaining = []
        else:
            positions = random.sample(range(n), d)
            positions.sort(reverse=True)
            destroyed = [current.pop(pos) for pos in positions]
            remaining = current
        # Reconstruction: reinsert jobs one by one in random order
        random.shuffle(destroyed)
        for job in destroyed:
            if not remaining:
                remaining.append(job)
                continue
            best_pos = 0
            best_cost = insertion_cost(remaining, job, 0)
            for pos in range(1, len(remaining)+1):
                cost = insertion_cost(remaining, job, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            remaining.insert(best_pos, job)
        current = remaining
        curr_makespan = makespan(current)
        if curr_makespan < best_makespan:
            best_makespan = curr_makespan
            best = current[:]
        elif curr_makespan < makespan(seq):
            if random.random() < math.exp(-(curr_makespan - makespan(seq)) / T):
                seq = current[:]

    return best

