def makespan(perm, times):
    if not perm:
        return 0
    n = len(perm)
    m = len(times[0])
    dp = [0] * m
    for job in perm:
        dp[0] += times[job][0]
        for k in range(1, m):
            dp[k] = max(dp[k-1], dp[k]) + times[job][k]
    return dp[-1]

def johnson_rule(times):
    n = len(times)
    if n == 0:
        return []
    if n == 1:
        return [0]
    left, right = 0, n - 1
    perm = [0] * n
    jobs = list(range(n))
    while jobs:
        best_idx = -1
        best_val = float('inf')
        for j in jobs:
            a, b = times[j]
            val = min(a, b)
            if val < best_val:
                best_val = val
                best_idx = j
        if times[best_idx][0] <= times[best_idx][1]:
            perm[left] = best_idx
            left += 1
        else:
            perm[right] = best_idx
            right -= 1
        jobs.remove(best_idx)
    return perm

def schedule_flowshop(times: list[list[int]]) -> list[int]:
