    best_perm = None
    best_makespan = float('inf')

    for l in range(1, m):
        sub_times = []
        for i in range(n):
            t1 = sum(times[i][:l])
            t2 = sum(times[i][m-l:])
            sub_times.append([t1, t2])
        perm = johnson_rule(sub_times)
        current_makespan = makespan(perm, times)
        if current_makespan < best_makespan:
            best_makespan = current_makespan
            best_perm = perm

    return best_perm

