    def neh_construct(priority_order):
        if not priority_order:
            return []
        perm = [priority_order[0]]
        if len(priority_order) == 1:
            return perm

        # Try both orders for first two jobs
        seq1 = [priority_order[0], priority_order[1]]
        seq2 = [priority_order[1], priority_order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2

        k = 2
        while k < len(priority_order):
            job = priority_order[k]
            best_pos = 0
            best_makespan = float('inf')

            # Precompute forward matrix e for current perm of length k
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = perm[r]
                for m in range(M):
                    if m == 0:
                        prev = e[r-1][0] if r > 0 else 0
                        e[r][m] = prev + times[job_r][m]
                    else:
                        left = e[r][m-1]
                        up = e[r-1][m] if r > 0 else 0
                        e[r][m] = max(left, up) + times[job_r][m]

            # Precompute backward tail matrix q for current perm of length k
            q = [[0] * M for _ in range(k+1)]  # q[k][*] = 0 already
            for r in range(k-1, -1, -1):
                job_r = perm[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        down = q[r+1][m]
                        q[r][m] = down + times[job_r][m]
                    else:
                        right = q[r][m+1]
                        down = q[r+1][m]
                        q[r][m] = max(right, down) + times[job_r][m]

            # Evaluate each insertion position i in [0, k]
            for i in range(k+1):
                # Compute forward vector f for inserting job at position i
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev_e = e[i-1][0] if i > 0 else 0
                        f[m] = prev_e + times[job][m]
