        removed_indices = indices[:d]
        removed_set = set(removed_indices)

        # Build destruction permutation (remaining jobs)
        perm_D = [job for job in current_perm if job not in removed_set]
        removed_jobs = [job for job in current_perm if job in removed_set]

        # Reconstruction: reinsert removed jobs one by one using NEH insertion with Taillard
        for job in removed_jobs:
            k = len(perm_D)
            if k == 0:
                perm_D = [job]
                continue

            best_pos = 0
            best_makespan_val = float('inf')

            # Precompute forward matrix e for perm_D
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = perm_D[r]
                for m in range(M):
                    if m == 0:
                        prev = e[r-1][0] if r > 0 else 0
                        e[r][m] = prev + job_times[job_r][m]
                    else:
                        left = e[r][m-1]
                        up = e[r-1][m] if r > 0 else 0
                        e[r][m] = max(left, up) + job_times[job_r][m]

            # Precompute backward tail matrix q for perm_D
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = perm_D[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        down = q[r+1][m]
                        q[r][m] = down + job_times[job_r][m]
                    else:
                        right = q[r][m+1]
                        down = q[r+1][m]
                        q[r][m] = max(right, down) + job_times[job_r][m]

            # Evaluate insertion positions
            for i in range(k+1):
                f = [0] * M
                for m in range(M):
                    if m == 0:
                        prev_e = e[i-1][0] if i > 0 else 0
                        f[m] = prev_e + job_times[job][m]
                    else:
                        left = f[m-1]
                        up = e[i-1][m] if i > 0 else 0
                        f[m] = max(left, up) + job_times[job][m]

                current_max = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > current_max:
                        current_max = val
                if current_max < best_makespan_val:
                    best_makespan_val = current_max
                    best_pos = i

            perm_D.insert(best_pos, job)

        new_perm = perm_D
        new_makespan = makespan(new_perm)

        # Acceptance criterion
        if new_makespan < makespan(current_perm):
            current_perm = new_perm
            if new_makespan < best_makespan:
                best_perm = new_perm[:]
                best_makespan = new_makespan
        else:
            delta = new_makespan - makespan(current_perm)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current_perm = new_perm

    return best_perm

