def makespan_naive(times, seq):
    if not seq:
        return 0
    N = len(seq)
    M = len(times[0])
    # Compute completion times using DP table
    dp = [[0] * M for _ in range(N)]
    for i in range(N):
        job_idx = seq[i]
        p_job = times[job_idx]
        for j in range(M):
            if i == 0 and j == 0:
                dp[i][j] = p_job[j]
            elif i == 0:
                dp[i][j] = dp[i][j-1] + p_job[j]
            elif j == 0:
                dp[i][j] = dp[i-1][j] + p_job[j]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + p_job[j]
    return dp[N-1][M-1]

