def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess: flatten times for faster access
    flat_times = [t for job in times for t in job]

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            base = job * M
            t[0] += flat_times[base]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + flat_times[base + m]
        return t[-1]

    def taillard_forward(seq):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = seq[r]
            base = job * M
            if r == 0:
                e[0][0] = flat_times[base]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + flat_times[base + m]
            else:
                e[r][0] = e[r-1][0] + flat_times[base]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + flat_times[base + m]
        return e

    def taillard_backward(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = seq[r]
            base = job * M
            q[r][M-1] = q[r+1][M-1] + flat_times[base + M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + flat_times[base + m]
        return q

    def makespan_insert(seq, job, pos, e, q):
        k = len(seq)
        f = [0] * M
        base = job * M
        if pos == 0:
            f[0] = flat_times[base]
        else:
            f[0] = e[pos-1][0] + flat_times[base]
        for m in range(1, M):
            f[m] = max(f[m-1], e[pos-1][m] if pos-1 >= 0 else 0) + flat_times[base + m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_taillard():
        job_sums = [sum(job) for job in times]
        order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        # initial pair
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        for k in range(2, N):
            job = order[k]
            e = taillard_forward(seq)
            q = taillard_backward(seq)
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(k+1):
                m = makespan_insert(seq, job, pos, e, q)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    def ig_refinement(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = initial_seq[:]
        best_makespan = makespan(best)
        total_processing = sum(sum(job) for job in times)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N >= 3 else N
        no_improve_limit = 10
        no_improve = 0
        for it in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in sorted(indices, reverse=True)]
            for idx in sorted(indices, reverse=True):
                del current[idx]
            # Reconstruction: reinsert each removed job using NEH insertion with Taillard
            for job in removed:
                e = taillard_forward(current)
                q = taillard_backward(current)
                best_pos = 0
                best_m = float('inf')
                for pos in range(len(current)+1):
                    m = makespan_insert(current, job, pos, e, q)
                    if m < best_m:
                        best_m = m
                        best_pos = pos
                current.insert(best_pos, job)
            # Acceptance
            curr_makespan = makespan(current)
            if curr_makespan < best_makespan:
                best = current[:]
                best_makespan = curr_makespan
                no_improve = 0
            if curr_makespan < makespan(initial_seq):  # always accept if better than starting point of this iteration
                pass  # current is already updated
            else:
                if curr_makespan == makespan(initial_seq):
                    pass
                else:
                    delta = curr_makespan - makespan(initial_seq)
                    if random.random() < math.exp(-delta / T):
                        pass  # accept worse
                    else:
                        # revert to initial_seq of this iteration
                        current = initial_seq[:]
            # Optional: early exit if at lower bound (skip for simplicity, LB computation costly)
            if no_improve >= no_improve_limit:
                break
            no_improve += 1
        return best

    # Main flow
    init_seq = neh_taillard()
    refined_seq = ig_refinement(init_seq, max_iter=50)
    return refined_seq

