    # Precompute total processing times for NEH priority
    total_times = [sum(job) for job in times]
    # Sort jobs by total processing time descending
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Initialize makespan matrix for current partial schedule
    makespan = [[0] * M for _ in range(N)]

    def compute_makespan_for_partial(seq):
        """Compute makespan matrix for a given sequence (used in NEH initialization)."""
        if not seq:
            return [[0] * M]
        # Initialize first job
        makespan[0][0] = times[seq[0]][0]
        for m in range(1, M):
            makespan[0][m] = makespan[0][m-1] + times[seq[0]][m]
        # Initialize first machine
        for r in range(1, len(seq)):
            makespan[r][0] = makespan[r-1][0] + times[seq[r]][0]
        # Fill the rest
        for r in range(1, len(seq)):
            for m in range(1, M):
                makespan[r][m] = max(makespan[r-1][m], makespan[r][m-1]) + times[seq[r]][m]
        return makespan

    def makespan_of_sequence(seq):
        """Compute makespan of a full sequence using incremental update."""
        if not seq:
            return 0
        # Reuse makespan matrix, only compute up to len(seq)
        for m in range(M):
            makespan[0][m] = (makespan[0][m-1] if m > 0 else 0) + times[seq[0]][m]
        for r in range(1, len(seq)):
            makespan[r][0] = makespan[r-1][0] + times[seq[r]][0]
            for m in range(1, M):
                makespan[r][m] = max(makespan[r-1][m], makespan[r][m-1]) + times[seq[r]][m]
        return makespan[len(seq)-1][M-1]

    def taillard_evaluate_insertion(partial_seq, job_idx, k):
        """
        Evaluate makespan for inserting job_idx into all k+1 positions of partial_seq (length k)
        using Taillard's acceleration. Returns best position and makespan.
        """
        if k == 0:
            return 0, times[job_idx][0] if M == 1 else sum(times[job_idx][m] for m in range(M))  # Simplified for k=0

        # Build forward matrix e for partial_seq[0:k]
        e = [[0] * M for _ in range(k)]
        # First row (r=0)
        e[0][0] = times[partial_seq[0]][0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + times[partial_seq[0]][m]
        # Remaining rows
        for r in range(1, k):
            e[r][0] = e[r-1][0] + times[partial_seq[r]][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + times[partial_seq[r]][m]

        # Build backward tail matrix q for partial_seq[0:k] (size k+1 x M)
        q = [[0] * M for _ in range(k+1)]
        # Initialize q[k][m] = 0
        # Compute backwards from r = k-1 down to 0
        for r in range(k-1, -1, -1):
            job_r = partial_seq[r]
            q[r][M-1] = q[r+1][M-1] + times[job_r][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]

        best_pos = 0
        best_makespan = float('inf')
        # Evaluate each insertion position i in [0, k]
        for i in range(k+1):
            # Compute forward vector f for job_idx up to insertion point i
            f = [0] * M
            if i == 0:
                # No jobs before, so e[-1][m] = 0
                f[0] = times[job_idx][0]
                for m in range(1, M):
                    f[m] = f[m-1] + times[job_idx][m]
            else:
                # e[i-1][m] is available
                f[0] = e[i-1][0] + times[job_idx][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + times[job_idx][m]
            # Compute makespan candidate: max_m (f[m] + q[i][m])
            makespan_candidate = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_candidate:
                    makespan_candidate = val
            if makespan_candidate < best_makespan:
                best_makespan = makespan_candidate
                best_pos = i
        return best_pos, best_makespan

    # NEH construction with Taillard acceleration
    current_seq = [order[0]]
    for k in range(1, N):
        job_idx = order[k]
        pos, _ = taillard_evaluate_insertion(current_seq, job_idx, k)
        current_seq.insert(pos, job_idx)

    # Iterated Greedy (IG) parameters
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2  # Adaptive destruction size
    max_iter = 50  # Calibrated to stay within 50ms for N<=120, M<=20
    best_seq = current_seq[:]
    best_makespan = makespan_of_sequence(best_seq)

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed_seq = []
            removed = current_seq[:]
        else:
            indices = random.sample(range(N), d)
            indices.sort(reverse=True)
            removed = []
            destroyed_seq = current_seq[:]
            for idx in indices:
                removed.append(destroyed_seq.pop(idx))
        # Reconstruction: reinsert removed jobs one by one using NEH/Taillard
        for job_idx in removed:
            k = len(destroyed_seq)
            if k == 0:
                destroyed_seq.append(job_idx)
            else:
                pos, _ = taillard_evaluate_insertion(destroyed_seq, job_idx, k)
                destroyed_seq.insert(pos, job_idx)
        # Acceptance criterion
        new_makespan = makespan_of_sequence(destroyed_seq)
        if new_makespan < makespan_of_sequence(current_seq):
            current_seq = destroyed_seq[:]
            if new_makespan < best_makespan:
                best_seq = destroyed_seq[:]
                best_makespan = new_makespan
        else:
            # Metropolis acceptance
            delta = new_makespan - makespan_of_sequence(current_seq)
            if delta < 0 or random.random() < math.exp(-delta / T):
                current_seq = destroyed_seq[:]
    return best_seq

