import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_data = [row[:] for row in times]
    total_processing = [sum(job) for job in job_data]

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            p = job_data[job]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[m]
        return t[-1]

    # Taillard acceleration for insertion evaluation
    def evaluate_insertion(partial, job_idx, k):
        if k == 0:
            f = [0] * M
            pj = job_data[job_idx]
            for m in range(M):
                if m == 0:
                    f[m] = pj[m]
                else:
                    f[m] = max(f[m-1], f[m]) + pj[m]
            return f[-1]

        # Forward matrix e for partial schedule
        e = [[0] * M for _ in range(k)]
        p0 = job_data[partial[0]]
        e[0][0] = p0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + p0[m]
        for r in range(1, k):
            pr = job_data[partial[r]]
            e[r][0] = e[r-1][0] + pr[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + pr[m]

        # Backward tail matrix q
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            pr = job_data[partial[r]]
            q[r][M-1] = q[r+1][M-1] + pr[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pr[m]

        best_cmax = float('inf')
        best_pos = 0
        for i in range(k+1):
            # Forward pass for job_idx up to insertion point
            f = [0] * M
            pj = job_data[job_idx]
            if i == 0:
                prev_e = [0] * M
            else:
                prev_e = e[i-1]
            for m in range(M):
                if m == 0:
                    f[m] = prev_e[0] + pj[0]
                else:
                    f[m] = max(f[m-1], prev_e[m]) + pj[m]
            # Calculate makespan: max over m of f[m] + q[i][m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos, best_cmax

    # Constructive NEH with Taillard acceleration
    def constructive_neh():
        # Sort jobs by total processing time descending
        order = sorted(range(N), key=lambda i: total_processing[i], reverse=True)
        if N < 2:
            return order
        # Initial pair
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        if makespan(seq0) <= makespan(seq1):
            perm = seq0[:]
        else:
            perm = seq1[:]
        # Insert remaining jobs
        for k in range(2, N):
            job_idx = order[k]
            pos, _ = evaluate_insertion(perm, job_idx, k)
            perm.insert(pos, job_idx)
        return perm

    # Iterated Greedy with block insertion of size 2
    def iterated_greedy(initial_perm, max_iters=60):
        current = initial_perm[:]
        best = current[:]
        best_cmax = makespan(best)
        total_sum = sum(total_processing)
        T_param = 0.5
        T = T_param * total_sum / (10 * N * M) if N * M > 0 else 1e-6

        for _ in range(max_iters):
            # Destruction: remove 2 jobs at random
            if N < 2:
                break
            indices = random.sample(range(N), 2)
            indices.sort(reverse=True)
            removed = []
            for idx in indices:
                removed.append(current.pop(idx))
            # Reconstruction: reinsert the two jobs in random order
            random.shuffle(removed)
            for job_idx in removed:
                k = len(current)
                pos, _ = evaluate_insertion(current, job_idx, k)
                current.insert(pos, job_idx)
            # Acceptance criterion
            curr_cmax = makespan(current)
            if curr_cmax < best_cmax:
                best_cmax = curr_cmax
                best = current[:]
            if curr_cmax < makespan(initial_perm):  # Always improve upon current state in IG
                initial_perm = current[:]
            else:
                if curr_cmax < makespan(best):  # This condition is redundant but kept for clarity
                    best_cmax = curr_cmax
                    best = current[:]
                delta = curr_cmax - makespan(initial_perm)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    initial_perm = current[:]
        return best

    # Build initial solution and apply IG
    init_perm = constructive_neh()
    # If NEH already gives a good solution, limit IG iterations
    max_iters = 40 if N > 50 else 60
    return iterated_greedy(init_perm, max_iters)

