def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices for job ordering
    total_time = [sum(job) for job in times]
    slope = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Helper: makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Helper: compute forward completion matrix e for a partial schedule (length k)
    def compute_forward(perm):
        k = len(perm)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][m] = prev + times[job][m]
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + times[job][m]
        return e

    # Helper: compute backward tail matrix q for a partial schedule (length k)
    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]  # q[k][:] = 0
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    down = q[r+1][m]
                    right = q[r][m+1]
                    q[r][m] = max(down, right) + times[job][m]
        return q

    # Helper: evaluate makespan when inserting job x at position i in partial schedule perm (length k)
    def evaluate_insertion(perm, e, q, x, i):
        k = len(perm)
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev_e = e[i-1][0] if i-1 >= 0 else 0
                f[m] = prev_e + times[x][m]
            else:
                left = f[m-1]
                up = e[i-1][m] if i-1 >= 0 else 0
                f[m] = max(left, up) + times[x][m]
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    # Helper: insert job x into perm at best position using Taillard acceleration
    def insert_job(perm, x):
        k = len(perm)
        if k == 0:
            return [x]
        e = compute_forward(perm)
        q = compute_backward(perm)
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            mk = evaluate_insertion(perm, e, q, x, i)
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return perm[:best_pos] + [x] + perm[best_pos:]

    # Beam Search with width K=2
    K = 2
    # Initial jobs sorted by total_time descending, then slope descending
    order = sorted(range(N), key=lambda i: (-total_time[i], -slope[i]))
    beams = [[]]  # list of partial sequences
    for idx in order:
        job = idx
        new_beams = []
        for seq in beams:
            for pos in range(len(seq)+1):
                new_seq = seq[:pos] + [job] + seq[pos:]
                new_beams.append(new_seq)
        # Evaluate all new beams by makespan of partial sequence
        scored = [(makespan(seq), seq) for seq in new_beams]
        scored.sort(key=lambda x: x[0])
        beams = [seq for _, seq in scored[:K]]
    # Return the best complete sequence from beam
    best_seq = min(beams, key=makespan)
    return best_seq

