def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0

    # Precompute job data for fast access
    job_data = [list(job) for job in times]
    total_times = [sum(job) for job in job_data]

    def compute_makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job_idx in seq:
            p = job_data[job_idx]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[m]
        return t[-1]

    def compute_tail_matrix(seq, k):
        # seq is list of job indices, length k
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            p = job_data[seq[r]]
            q[r][M-1] = q[r+1][M-1] + p[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[m]
        return q

    def compute_forward_matrix(seq, k):
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            p = job_data[seq[r]]
            if r == 0:
                e[0][0] = p[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[m]
            else:
                e[r][0] = e[r-1][0] + p[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[m]
        return e

    def evaluate_insertion(seq, job_idx, e, q, k):
        # seq length k, insert job_idx at pos i in [0, k]
        p = job_data[job_idx]
        best_i = 0
        best_cmax = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = p[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], e[i-1][m] if i-1 >= 0 else 0) + p[m])
            else:
                f0 = (e[i-1][0] if i-1 >= 0 else 0) + p[0]
                f = [f0]
                for m in range(1, M):
                    f.append(max(f[m-1], e[i-1][m]) + p[m])
            cmax = 0
            for m in range(M):
                val = f[m] + (q[i][m] if i < k else 0)
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_i = i
        return best_i, best_cmax

    # NEH construction with Taillard acceleration
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    if N >= 2:
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        seq = seq0 if compute_makespan(seq0) <= compute_makespan(seq1) else seq1
        start_k = 2
    else:
        seq = [order[0]]
        start_k = 1

    for k in range(start_k, N):
        job_idx = order[k]
        e = compute_forward_matrix(seq, k)
        q = compute_tail_matrix(seq, k)
        pos, _ = evaluate_insertion(seq, job_idx, e, q, k)
        seq.insert(pos, job_idx)

    best_seq = seq[:]
    best_cmax = compute_makespan(best_seq)
    if best_cmax == 0:
        return best_seq

    # Iterated Greedy refinement
    max_iter = 60
    d = 3 if N > 20 else 4
    for _ in range(max_iter):
        # Destruction
        indices = random.sample(range(N), d)
        removed = [seq[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del seq[i]
        # Reconstruction
        for job_idx in removed:
            k = len(seq)
            e = compute_forward_matrix(seq, k)
            q = compute_tail_matrix(seq, k)
            pos, _ = evaluate_insertion(seq, job_idx, e, q, k)
            seq.insert(pos, job_idx)
        # Acceptance
        curr_cmax = compute_makespan(seq)
        if curr_cmax < best_cmax:
            best_cmax = curr_cmax
            best_seq = seq[:]
        if curr_cmax < compute_makespan(best_seq):
            # This condition is redundant but kept for clarity
            pass
        if curr_cmax < compute_makespan(seq):  # Always true, kept for structure
            pass
        else:
            if curr_cmax < compute_makespan(best_seq):
                best_seq = seq[:]
                best_cmax = curr_cmax
            delta = curr_cmax - compute_makespan(best_seq)
            if delta > 0 and random.random() < math.exp(-delta / T):
                pass  # Accept worse solution
            else:
                if curr_cmax > compute_makespan(best_seq):
                    seq = best_seq[:]  # Reset to best if not accepting worse
        # Early exit if optimal found (lower bound not implemented for speed)
    return best_seq

