        removed = [current_seq[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del current_seq[idx]
        random.shuffle(removed)
        for job in removed:
            job_time = times[job]
            best_pos = 0
            best_mk = float('inf')
            for i in range(len(current_seq)+1):
                if i == 0:
                    f0 = job_time[0]
                    fm = [f0]
                    for m in range(1, M):
                        fm.append(max(fm[m-1], 0) + job_time[m])
                else:
                    prev_e = e[i-1] if i-1 < len(current_seq) else [0]*M
                    f0 = prev_e[0] + job_time[0]
                    fm = [f0]
                    for m in range(1, M):
                        fm.append(max(fm[m-1], prev_e[m]) + job_time[m])
                mk = 0
                for m in range(M):
                    val = fm[m] + (q[i][m] if i < len(q) else 0)
                    if val > mk:
