        if current_mk < best_mk:
            best_mk = current_mk
            best_seq = current_seq[:]
        if current_mk > best_mk:
            diff = current_mk - best_mk
            if random.random() < math.exp(-diff / T):
                best_seq = current_seq[:]
                best_mk = current_mk
    return best_seq

