def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job processing times as tuples for faster access
    p = [tuple(row) for row in times]

    # Precompute total processing times for sorting
    total = [sum(job) for job in p]

    # Helper: makespan evaluation for a given sequence
    def makespan(seq):
        t = [0] * M
        for job in seq:
            job_t = p[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[-1]

    # Taillard-accelerated insertion evaluation
    def insert_job(seq, job):
        k = len(seq)
        if k == 0:
            return [job]

        # Forward matrix e: completion times of current seq
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = p[seq[r]]
            if r == 0:
                e[0][0] = job_r[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_r[m]
            else:
                e[r][0] = e[r-1][0] + job_r[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]

        # Backward tail matrix q
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = p[seq[r]]
            if r == k-1:
                for m in range(M):
                    q[r][m] = job_r[m]
            else:
                q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]

        best_pos = 0
        best_makespan = float('inf')
        job_p = p[job]

        for i in range(k+1):
            # Compute forward vector f for inserting job at position i
            if i == 0:
                f = [0] * M
                f[0] = job_p[0]
                for m in range(1, M):
                    f[m] = f[m-1] + job_p[m]
            else:
                prev = e[i-1]
                f = [0] * M
                f[0] = prev[0] + job_p[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev[m]) + job_p[m]

            # Compute makespan: max over m of f[m] + q[i][m]
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_makespan:
                best_makespan = mk
                best_pos = i

        return seq[:best_pos] + [job] + seq[best_pos:]

    # NEH construction with Taillard acceleration
    order = sorted(range(N), key=lambda i: total[i], reverse=True)
    seq = [order[0], order[1]]
    seq0_mk = makespan(seq)
    seq1_mk = makespan([order[1], order[0]])
    if seq1_mk < seq0_mk:
        seq = [order[1], order[0]]

    for idx in range(2, N):
        job = order[idx]
        seq = insert_job(seq, job)

    # Iterated Greedy refinement
    current = seq[:]
    best = seq[:]
    current_mk = makespan(current)
    best_mk = current_mk

    # IG parameters
    d = 3 if N > 20 else 2
    T_param = 0.5
    total_processing = sum(total)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

    max_iter = 50
    if N > 60:
        max_iter = 30
    if N > 100:
        max_iter = 20

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            removed = current[:]
        else:
            indices = random.sample(range(N), d)
            indices.sort(reverse=True)
            removed = []
            for idx in indices:
                removed.append(current.pop(idx))
            destroyed = current  # remaining sequence

        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            destroyed = insert_job(destroyed, job)

        new_seq = destroyed
        new_mk = makespan(new_seq)

        # Acceptance criterion
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current = new_seq
            current_mk = new_mk
            if new_mk < best_mk:
                best = new_seq[:]
                best_mk = new_mk

    return best

