def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    job_sums = [0] * N
    for i in range(N):
        s = 0
        row = times[i]
        for j in range(M):
            s += row[j]
            total_processing += row[j]
        job_sums[i] = s

    order = list(range(N))
    order.sort(key=lambda i: job_sums[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            row = times[job]
            t[0] += row[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + row[m]
        return t[-1]

    def makespan_taillard(seq):
        if not seq:
            return 0
        e = [0] * M
        for job in seq:
            row = times[job]
            e[0] += row[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + row[m]
        return e[-1]

    def makespan_insertion_taillard(partial, x, i):
        k = len(partial)
        if k == 0:
            e_prev = [0] * M
        else:
            e_prev = [0] * M
            e_prev[0] = times[partial[0]][0]
            for m in range(1, M):
                e_prev[m] = max(e_prev[m-1], e_prev[m]) + times[partial[0]][m]
            for r in range(1, k):
                row = times[partial[r]]
                e_prev[0] += row[0]
                for m in range(1, M):
                    e_prev[m] = max(e_prev[m-1], e_prev[m]) + row[m]
        f = [0] * M
        row_x = times[x]
        if i == 0:
            f[0] = row_x[0]
        else:
            f[0] = e_prev[0] + row_x[0]
        for m in range(1, M):
            f[m] = max(f[m-1], e_prev[m]) + row_x[m]
        q = [0] * M
        for r in range(k-1, i-1, -1):
            row = times[partial[r]]
            q[M-1] += row[M-1]
            for m in range(M-2, -1, -1):
                q[m] = max(q[m+1], q[m]) + row[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    current = [order[0]]
    if N >= 2:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan_taillard(seq1) <= makespan_taillard(seq2):
            current = seq1
        else:
            current = seq2
    for k in range(2, N):
        job = order[k]
        best_pos = 0
        best_mk = makespan_insertion_taillard(current, job, 0)
        for pos in range(1, k+1):
            mk = makespan_insertion_taillard(current, job, pos)
            if mk < best_mk:
                best_mk = mk
                best_pos = pos
        current.insert(best_pos, job)

    makespan_current = makespan_taillard(current)
    LB = 0
    for m in range(M):
        min_pre = min(times[i][m] for i in range(N)) if m > 0 else 0
        min_suf = min(times[i][m] for i in range(N)) if m < M-1 else 0
        sum_m = sum(times[i][m] for i in range(N))
        lb_m = min_pre + sum_m + min_suf
        if lb_m > LB:
            LB = lb_m
    if makespan_current == LB:
        return current

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-9:
        T = 1e-9

    pi = current[:]
    pi_star = pi[:]
    makespan_star = makespan_current
    d = 3 if N >= 3 else N
    max_iter = 60

    for _ in range(max_iter):
        if makespan_star == LB:
            break
        indices = list(range(N))
        random.shuffle(indices)
        removed = indices[:d]
        removed.sort(reverse=True)
        pi_D = pi[:]
        for idx in removed:
            pi_D.pop(idx)
        R = [pi[idx] for idx in indices[:d]]
        random.shuffle(R)
        for job in R:
            best_pos = 0
            best_mk = makespan_insertion_taillard(pi_D, job, 0)
            for pos in range(1, len(pi_D)+1):
                mk = makespan_insertion_taillard(pi_D, job, pos)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            pi_D.insert(best_pos, job)
        makespan_new = makespan_taillard(pi_D)
        if makespan_new < makespan_star:
            pi_star = pi_D[:]
            makespan_star = makespan_new
        if makespan_new < makespan_taillard(pi):
            pi = pi_D[:]
        else:
            delta = makespan_new - makespan_taillard(pi)
            if random.random() < math.exp(-delta / T):
                pi = pi_D[:]
    return pi_star

