    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Flatten processing times for faster access
    p = [times[i][:] for i in range(n)]
    total_processing = sum(sum(row) for row in p)

    # Helper: makespan of a permutation using DP (O(n*m))
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * m
        for job in seq:
            t[0] += p[job][0]
            for k in range(1, m):
                t[k] = max(t[k-1], t[k]) + p[job][k]
        return t[-1]

    # NEH construction with Taillard acceleration
    job_sums = [sum(row) for row in p]
    order = sorted(range(n), key=lambda i: job_sums[i], reverse=True)

    # Initial sequence with first two jobs
    seq = [order[0], order[1]]
    best_ms = makespan(seq)
    alt_ms = makespan([order[1], order[0]])
    if alt_ms < best_ms:
        seq = [order[1], order[0]]
        best_ms = alt_ms

    # Preallocate matrices for Taillard acceleration
    e = [[0] * m for _ in range(n)]
    q = [[0] * m for _ in range(n + 1)]

    # Insert remaining jobs using Taillard's O(k*m) method
    for k in range(2, n):
        job = order[k]
        # Forward pass: completion times of current seq[0..k-1]
        for r in range(k):
            if r == 0:
                e[r][0] = p[seq[r]][0]
            else:
                e[r][0] = e[r-1][0] + p[seq[r]][0]
            for mc in range(1, m):
                e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + p[seq[r]][mc]

        # Backward pass: tail times from position r to end
        for mc in range(m):
            q[k][mc] = 0
        for r in range(k-1, -1, -1):
            q[r][m-1] = q[r+1][m-1] + p[seq[r]][m-1]
            for mc in range(m-2, -1, -1):
                q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + p[seq[r]][mc]

        # Evaluate insertion positions 0..k
        best_pos = 0
        best_ms_local = float('inf')
        for i in range(k+1):
            # Forward vector for inserting job at position i
            if i == 0:
                f0 = p[job][0]
            else:
                f0 = e[i-1][0] + p[job][0]
            f = [f0]
            for mc in range(1, m):
                prev_f = f[mc-1]
                prev_e = e[i-1][mc] if i-1 >= 0 else 0
                f.append(max(prev_f, prev_e) + p[job][mc])
            # Compute makespan candidate
            ms_candidate = 0
            for mc in range(m):
                val = f[mc] + q[i][mc]
                if val > ms_candidate:
                    ms_candidate = val
            if ms_candidate < best_ms_local:
                best_ms_local = ms_candidate
                best_pos = i
        seq.insert(best_pos, job)
        best_ms = best_ms_local

    # Iterated Greedy refinement
    random.seed(42)  # Deterministic behavior
    current_seq = seq[:]
    current_ms = best_ms
    best_seq = current_seq[:]
    best_ms_overall = current_ms

    # Temperature parameter
    T_param = 0.5
    T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
    d = 3 if n > 20 else 2  # Destruction size

