                continue
            # Recompute e and q for current_seq
            for r in range(k):
                if r == 0:
                    e[r][0] = p[current_seq[r]][0]
                else:
                    e[r][0] = e[r-1][0] + p[current_seq[r]][0]
                for mc in range(1, m):
                    e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + p[current_seq[r]][mc]
            for mc in range(m):
                q[k][mc] = 0
            for r in range(k-1, -1, -1):
                q[r][m-1] = q[r+1][m-1] + p[current_seq[r]][m-1]
                for mc in range(m-2, -1, -1):
                    q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + p[current_seq[r]][mc]
            # Evaluate insertion positions
            best_pos = 0
            best_ms_local = float('inf')
            for i in range(k+1):
                if i == 0:
                    f0 = p[job][0]
                else:
                    f0 = e[i-1][0] + p[job][0]
                f = [f0]
                for mc in range(1, m):
                    prev_f = f[mc-1]
                    prev_e = e[i-1][mc] if i-1 >= 0 else 0
                    f.append(max(prev_f, prev_e) + p[job][mc])
                ms_candidate = 0
                for mc in range(m):
                    val = f[mc] + q[i][mc]
                    if val > ms_candidate:
                        ms_candidate = val
                if ms_candidate < best_ms_local:
                    best_ms_local = ms_candidate
                    best_pos = i
            current_seq.insert(best_pos, job)
        # Compute new makespan
        new_ms = makespan(current_seq)
        # Acceptance criterion
        if new_ms < current_ms or random.random() < math.exp(-(new_ms - current_ms) / T):
            current_seq = current_seq[:]
            current_ms = new_ms
            if new_ms < best_ms_overall:
                best_seq = current_seq[:]
                best_ms_overall = new_ms
        else:
            # Revert to previous state (not stored, so rebuild from best known)
            current_seq = best_seq[:]
            current_ms = best_ms_overall

    return best_seq

