            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]

    def compute_forward(e, seq, end_idx):
        for m in range(M):
            if end_idx == 0:
                e[0][m] = times[seq[0]][m]
            else:
                if m == 0:
                    e[end_idx][0] = e[end_idx-1][0] + times[seq[end_idx]][0]
                else:
                    e[end_idx][m] = max(e[end_idx-1][m], e[end_idx][m-1]) + times[seq[end_idx]][m]

    def evaluate_insertion(e, q, job, pos, cur_len):
        f = [0] * M
        if pos == 0:
            for m in range(M):
                f[m] = times[job][m]
        else:
            job_t = times[job]
            f[0] = e[pos-1][0] + job_t[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + job_t[m]
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
        return best

    def NEH():
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N+1)]
        seq = []
        for idx in order:
            k = len(seq)
            if k == 0:
                seq.append(idx)
                e[0][:] = times[idx][:]
                compute_tail(q, seq, 0)
                continue
            if k == 1:
                job0, job1 = seq[0], idx
                m0 = makespan([job0, job1])
                m1 = makespan([job1, job0])
                if m0 <= m1:
                    seq = [job0, job1]
                else:
                    seq = [job1, job0]
                compute_forward(e, seq, 0)
                compute_forward(e, seq, 1)
                compute_tail(q, seq, 2)
                continue
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(k+1):
                m = evaluate_insertion(e, q, idx, pos, k)
                if m < best_makespan:
                    best_makespan = m
                    best_pos = pos
            seq.insert(best_pos, idx)
            compute_forward(e, seq, best_pos)
            for r in range(best_pos-1, -1, -1):
                compute_forward(e, seq, r)
            compute_tail(q, seq, len(seq))
        return seq

    def IG(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = initial_seq[:]
        best_makespan = makespan(best)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        d = 3 if N > 20 else 2
        if N > 60:
            d = 4
        e = [[0] * M for _ in range(N)]
        q = [[0] * M for _ in range(N+1)]
        for _ in range(max_iter):
            if makespan(best) == 0:
                break
            indices = list(range(N))
            random.shuffle(indices)
            removed = []
            remaining = []
            for i in range(d):
                removed.append(current[indices[i]])
            for i in range(d, N):
                remaining.append(current[indices[i]])
            seq = remaining[:]
            k = len(seq)
            if k > 0:
                compute_forward(e, seq, 0)
                for r in range(1, k):
                    compute_forward(e, seq, r)
                compute_tail(q, seq, k)
            for job in removed:
                best_pos = 0
                best_m = float('inf')
                for pos in range(k+1):
                    m = evaluate_insertion(e, q, job, pos, k)
                    if m < best_m:
                        best_m = m
                        best_pos = pos
                seq.insert(best_pos, job)
                compute_forward(e, seq, best_pos)
                for r in range(best_pos-1, -1, -1):
                    compute_forward(e, seq, r)
                compute_tail(q, seq, len(seq))
                k = len(seq)
            m_new = makespan(seq)
            if m_new < makespan(current):
                current = seq[:]
                if m_new < best_makespan:
                    best = seq[:]
                    best_makespan = m_new
            else:
                if random.random() < math.exp(-(m_new - makespan(current)) / T):
                    current = seq[:]
        return best

    initial = NEH()
    refined = IG(initial)
    return refined

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job processing times and total times
    job_times = [row[:] for row in times]
    total_times = [sum(row) for row in job_times]

    # Makespan evaluation for a given permutation
    def makespan(perm):
        t = [0] * m
        for job in perm:
            p = job_times[job]
            t[0] += p[0]
            for j in range(1, m):
                t[j] = max(t[j-1], t[j]) + p[j]
        return t[m-1]

    # Taillard's acceleration for insertion evaluation
    def evaluate_insertion(partial, job, forward, backward):
        k = len(partial)
        f = [0] * m
        if k == 0:
            f[0] = job_times[job][0]
            for j in range(1, m):
                f[j] = f[j-1] + job_times[job][j]
        else:
            f[0] = forward[0] + job_times[job][0] if k > 0 else job_times[job][0]
            for j in range(1, m):
                f[j] = max(f[j-1], forward[j]) + job_times[job][j]
        best_cmax = float('inf')
        best_pos = 0
        for pos in range(k + 1):
            cmax = 0
            for j in range(m):
                val = f[j] + backward[pos][j]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = pos
            if pos < k:
                # Update forward for next position: insert partial[pos] after current job
                pj = job_times[partial[pos]]
                f[0] = max(f[0], forward[pos][0]) + pj[0]
                for j in range(1, m):
                    f[j] = max(f[j-1], forward[pos][j]) + pj[j]
        return best_pos, best_cmax

    # NEH construction with Taillard acceleration
    def neh_construction():
        # Sort jobs by total processing time descending
        order = sorted(range(n), key=lambda i: total_times[i], reverse=True)
        if n == 0:
            return []
        # Start with first job
        perm = [order[0]]
        if n == 1:
            return perm
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        # Preallocate forward and backward matrices
        forward = [[0] * m for _ in range(n)]
        backward = [[0] * m for _ in range(n + 1)]
        # Iteratively insert remaining jobs
        for k in range(2, n):
            job = order[k]
            # Compute forward matrix for current perm (length k)
            for r in range(k):
                pj = job_times[perm[r]]
                if r == 0:
                    forward[r][0] = pj[0]
                    for j in range(1, m):
                        forward[r][j] = forward[r][j-1] + pj[j]
                else:
                    forward[r][0] = forward[r-1][0] + pj[0]
                    for j in range(1, m):
                        forward[r][j] = max(forward[r-1][j], forward[r][j-1]) + pj[j]
            # Compute backward matrix for current perm (length k)
            for j in range(m):
                backward[k][j] = 0
            for r in range(k-1, -1, -1):
                pj = job_times[perm[r]]
                backward[r][m-1] = backward[r+1][m-1] + pj[m-1]
                for j in range(m-2, -1, -1):
                    backward[r][j] = max(backward[r+1][j], backward[r][j+1]) + pj[j]
            # Evaluate insertion positions
            best_pos, _ = evaluate_insertion(perm, job, forward[k-1] if k > 0 else [0]*m, backward)
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with Metropolis acceptance
    def iterated_greedy(initial_perm):
        current_perm = initial_perm[:]
        current_cmax = makespan(current_perm)
        best_perm = current_perm[:]
        best_cmax = current_cmax
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
        # Preallocate destruction structures
        extracted = [0] * 4
        # Run fixed number of iterations (calibrated for <50ms)
        max_iter = 60
        for _ in range(max_iter):
            # Destruction: remove d=3 jobs randomly
            d = 3
            indices = random.sample(range(n), d)
            indices.sort(reverse=True)
            for idx, pos in enumerate(indices):
                extracted[idx] = current_perm.pop(pos)
            # Reconstruction: reinsert using NEH-like insertion with Taillard
            # Rebuild forward and backward for current partial perm
            k = len(current_perm)
            forward = [[0] * m for _ in range(k)]
            backward = [[0] * m for _ in range(k + 1)]
            for r in range(k):
                pj = job_times[current_perm[r]]
                if r == 0:
                    forward[r][0] = pj[0]
                    for j in range(1, m):
                        forward[r][j] = forward[r][j-1] + pj[j]
                else:
                    forward[r][0] = forward[r-1][0] + pj[0]
                    for j in range(1, m):
                        forward[r][j] = max(forward[r-1][j], forward[r][j-1]) + pj[j]
            for j in range(m):
                backward[k][j] = 0
            for r in range(k-1, -1, -1):
                pj = job_times[current_perm[r]]
                backward[r][m-1] = backward[r+1][m-1] + pj[m-1]
                for j in range(m-2, -1, -1):
                    backward[r][j] = max(backward[r+1][j], backward[r][j+1]) + pj[j]
            # Reinsert each extracted job in random order
            random.shuffle(extracted)
            for idx in range(d):
                job = extracted[idx]
                # Evaluate insertion positions using current forward/backward
                f = [0] * m
                if k == 0:
                    f[0] = job_times[job][0]
                    for j in range(1, m):
                        f[j] = f[j-1] + job_times[job][j]
                else:
                    f[0] = forward[0] + job_times[job][0] if k > 0 else job_times[job][0]
                    for j in range(1, m):
                        f[j] = max(f[j-1], forward[j]) + job_times[job][j]
                best_pos = 0
                best_cmax_insert = float('inf')
                for pos in range(k + 1):
                    cmax_val = 0
                    for j in range(m):
                        val = f[j] + backward[pos][j]
                        if val > cmax_val:
                            cmax_val = val
                    if cmax_val < best_cmax_insert:
                        best_cmax_insert = cmax_val
                        best_pos = pos
                    if pos < k:
                        pj = job_times[current_perm[pos]]
                        f[0] = max(f[0], forward[pos][0]) + pj[0]
                        for j in range(1, m):
                            f[j] = max(f[j-1], forward[pos][j]) + pj[j]
                current_perm.insert(best_pos, job)
                k += 1
            # Update current makespan
            current_cmax = makespan(current_perm)
            # Acceptance criterion
            if current_cmax < best_cmax:
                best_perm = current_perm[:]
                best_cmax = current_cmax
            if current_cmax < makespan(initial_perm):  # Always improve over initial
                current_perm = current_perm[:]
            else:
                delta = current_cmax - makespan(initial_perm)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    current_perm = current_perm[:]
                else:
                    # Revert to initial permutation for next iteration
                    current_perm = initial_perm[:]
        return best_perm

    # Build initial solution and refine
    init_perm = neh_construction()
    return iterated_greedy(init_perm)

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for each job
    total_times = [sum(job) for job in times]
    # Sort jobs by total processing time descending (NEH priority)
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Initialize with the first job
    current_seq = [order[0]]
    # Preallocate forward and backward matrices for efficiency
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N + 1)]

    # Helper to compute makespan of a sequence using DP (used only for initial pair)
    def makespan(seq):
        if not seq:
            return 0
        # 1D DP array for current machine completion times
        dp = [0] * M
        for job in seq:
            pj = times[job]
            dp[0] += pj[0]
            for m in range(1, M):
                dp[m] = max(dp[m-1], dp[m]) + pj[m]
        return dp[-1]

    # Handle the first two jobs
    if N >= 2:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            current_seq = seq1
        else:
            current_seq = seq2

    # Main NEH insertion loop with Taillard acceleration
    for k in range(2, N):
        job_idx = order[k]
        pj = times[job_idx]
        # Compute forward matrix e for current_seq (length k)
        for r in range(k):
            job_r = current_seq[r]
            pr = times[job_r]
            if r == 0:
                e[0][0] = pr[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pr[m]
            else:
                e[r][0] = e[r-1][0] + pr[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pr[m]
        # Compute backward matrix q for current_seq (length k)
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = current_seq[r]
            pr = times[job_r]
            q[r][M-1] = q[r+1][M-1] + pr[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pr[m]
        # Find best insertion position for job_idx
        best_pos = 0
        best_makespan = float('inf')
        # Try inserting at each position i from 0 to k
        for i in range(k+1):
            # Compute forward vector f for inserting job_idx at position i
            f = [0] * M
            if i == 0:
                # e[-1][m] is 0
                f[0] = pj[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], 0) + pj[m]
            else:
                # e[i-1][m] is available
                f[0] = e[i-1][0] + pj[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + pj[m]
            # Compute makespan candidate: max_m (f[m] + q[i][m])
            makespan_candidate = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_candidate:
                    makespan_candidate = val
            if makespan_candidate < best_makespan:
                best_makespan = makespan_candidate
                best_pos = i
        # Insert job_idx at best_pos
        current_seq.insert(best_pos, job_idx)

    # Iterated Greedy refinement
    # Parameters calibrated for speed and effectiveness
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N > 20 else 2  # Destruction size
    max_iter = 50  # Number of IG iterations

    best_seq = current_seq[:]
    best_makespan = makespan(current_seq)

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            remaining = current_seq[:]
            random.shuffle(remaining)
        else:
            indices = random.sample(range(N), d)
            indices_set = set(indices)
            destroyed = [current_seq[i] for i in indices]
            remaining = [current_seq[i] for i in range(N) if i not in indices_set]
        # Reconstruction: reinsert destroyed jobs one by one in random order
        random.shuffle(destroyed)
        seq = remaining[:]
        for job in destroyed:
            pj = times[job]
            # Reuse the same Taillard acceleration for insertion into current seq
            k = len(seq)
            if k == 0:
                seq.append(job)
                continue
            # Compute forward matrix e for current seq
            for r in range(k):
                job_r = seq[r]
                pr = times[job_r]
                if r == 0:
                    e[0][0] = pr[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + pr[m]
                else:
                    e[r][0] = e[r-1][0] + pr[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + pr[m]
            # Compute backward matrix q for current seq
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                pr = times[job_r]
                q[r][M-1] = q[r+1][M-1] + pr[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + pr[m]
            # Find best insertion position for job
            best_pos = 0
            best_makespan_local = float('inf')
            for i in range(k+1):
                f = [0] * M
                if i == 0:
                    f[0] = pj[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], 0) + pj[m]
                else:
                    f[0] = e[i-1][0] + pj[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + pj[m]
                makespan_candidate = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > makespan_candidate:
                        makespan_candidate = val
                if makespan_candidate < best_makespan_local:
                    best_makespan_local = makespan_candidate
                    best_pos = i
            seq.insert(best_pos, job)
        # Evaluate new sequence
        new_makespan = makespan(seq)
        # Acceptance criterion
        if new_makespan < best_makespan:
            best_makespan = new_makespan
            best_seq = seq[:]
            current_seq = seq[:]
        elif new_makespan < makespan(current_seq):
            current_seq = seq[:]
        else:
            if random.random() < math.exp(-(new_makespan - makespan(current_seq)) / T):
                current_seq = seq[:]

    return best_seq

import math
