def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for faster access
    proc = [row[:] for row in times]
    total_proc = [sum(row) for row in proc]

    # Makespan evaluation using forward recursion
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * m
        for job in seq:
            pj = proc[job]
            t[0] += pj[0]
            for k in range(1, m):
                t[k] = max(t[k-1], t[k]) + pj[k]
        return t[-1]

    # NEH construction with Taillard's acceleration
    def neh_construct(order):
        if not order:
            return []
        seq = [order[0]]
        # Forward and backward matrices: e[r][c], q[r][c] for r in [0, len(seq)], c in [0, m)
        e = [[0] * m]
        q = [[0] * m, [0] * m]  # q[0] for r=0, q[1] for r=1 (dummy for r=len(seq))
        for idx in range(1, len(order)):
            job = order[idx]
            pj = proc[job]
            k = len(seq)  # current length of seq
            # Extend e and q for new length k+1
            e.append([0] * m)
            q.append([0] * m)
            # Update forward matrix e for the current seq (without the new job)
            for r in range(k):
                if r == 0:
                    e[r][0] = e[r-1][0] + proc[seq[r]][0] if r > 0 else proc[seq[r]][0]
                else:
                    e[r][0] = e[r-1][0] + proc[seq[r]][0]
                for c in range(1, m):
                    e[r][c] = max(e[r-1][c], e[r][c-1]) + proc[seq[r]][c]
            # Update backward matrix q for the current seq
            # q[k][c] = 0 already set
            for r in range(k-1, -1, -1):
                if r == k-1:
                    q[r][m-1] = q[r+1][m-1] + proc[seq[r]][m-1]
                else:
                    q[r][m-1] = q[r+1][m-1] + proc[seq[r]][m-1]
                for c in range(m-2, -1, -1):
                    q[r][c] = max(q[r+1][c], q[r][c+1]) + proc[seq[r]][c]
            # Now evaluate insertion positions for job
            best_pos = 0
            best_mk = float('inf')
            # For each insertion position i in [0, k]
            for i in range(k+1):
                # Compute forward vector f for job at position i
                f = [0] * m
                if i == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[i-1]
                f[0] = prev_e[0] + pj[0]
                for c in range(1, m):
                    f[c] = max(f[c-1], prev_e[c]) + pj[c]
                # Compute makespan if job inserted at i: max_c (f[c] + q[i][c])
                mk = 0
                for c in range(m):
                    val = f[c] + q[i][c]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            # Insert job at best_pos
            seq.insert(best_pos, job)
            # Rebuild e and q for the new seq of length k+1
            # Recompute e from scratch for the new seq
            e = [[0] * m for _ in range(k+1)]
            for r in range(k+1):
                if r == 0:
                    e[r][0] = proc[seq[r]][0]
                else:
                    e[r][0] = e[r-1][0] + proc[seq[r]][0]
                for c in range(1, m):
                    e[r][c] = max(e[r-1][c], e[r][c-1]) + proc[seq[r]][c]
            # Recompute q from scratch for the new seq
            q = [[0] * m for _ in range(k+2)]  # q[0..k+1], q[k+1] is dummy zeros
            # q[k+1][c] = 0 already
            for r in range(k, -1, -1):
                if r == k:
                    q[r][m-1] = q[r+1][m-1] + proc[seq[r]][m-1]
                else:
                    q[r][m-1] = q[r+1][m-1] + proc[seq[r]][m-1]
                for c in range(m-2, -1, -1):
                    q[r][c] = max(q[r+1][c], q[r][c+1]) + proc[seq[r]][c]
        return seq

    # Initial solution via NEH with descending total processing time
    order = sorted(range(n), key=lambda i: total_proc[i], reverse=True)
    pi = neh_construct(order)
    pi_best = pi[:]
    best_mk = makespan(pi)

    # Iterated Greedy parameters
    total_sum = sum(total_proc)
    T_param = 0.5
