def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices for priority ordering
    total_time = [sum(job) for job in times]
    slope_index = []
    for i in range(n):
        s = 0
        for j in range(m):
            s += (2 * j - m + 1) * times[i][j]
        slope_index.append(s)

    # Create job order: primary by total_time descending, secondary by slope_index descending
    jobs = list(range(n))
    jobs.sort(key=lambda i: (-total_time[i], -slope_index[i]))

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            for k in range(m):
                if k == 0:
                    t[k] += times[job][k]
                else:
                    t[k] = max(t[k], t[k-1]) + times[job][k]
        return t[-1]

    # Taillard acceleration: forward completion matrix for a given partial schedule
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * m]
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for c in range(m):
                if c == 0:
                    e[r][c] = (e[r-1][c] if r > 0 else 0) + times[job][c]
                else:
                    e[r][c] = max(e[r-1][c] if r > 0 else 0, e[r][c-1]) + times[job][c]
        return e

    # Taillard acceleration: backward tail matrix for a given partial schedule
    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * m]
        q = [[0] * m for _ in range(k+1)]
        # q[k] is already [0]*m
        for r in range(k-1, -1, -1):
            job = perm[r]
            for c in range(m-1, -1, -1):
                if c == m-1:
                    q[r][c] = q[r+1][c] + times[job][c]
                else:
                    q[r][c] = max(q[r+1][c], q[r][c+1]) + times[job][c]
        return q

    # NEH construction with Taillard acceleration
    def construct_neh():
        if n == 0:
            return []
        # Start with first two jobs
        best_seq = [jobs[0], jobs[1]]
        best_makespan = makespan(best_seq)
        rev_seq = [jobs[1], jobs[0]]
        rev_makespan = makespan(rev_seq)
        if rev_makespan < best_makespan:
            best_seq = rev_seq
            best_makespan = rev_makespan

        # Iteratively insert remaining jobs
        for k in range(2, n):
            job = jobs[k]
            e = compute_forward(best_seq)
            q = compute_backward(best_seq)
            best_pos = 0
            best_val = float('inf')
            # Try all insertion positions
            for i in range(k+1):
                # Compute forward vector f for inserting job at position i
                f = [0] * m
                for c in range(m):
                    if c == 0:
                        prev = e[i-1][c] if i > 0 else 0
                        f[c] = prev + times[job][c]
                    else:
                        f[c] = max(f[c-1], e[i-1][c] if i > 0 else 0) + times[job][c]
                # Compute makespan for this insertion
                current_max = 0
                for c in range(m):
                    val = f[c] + q[i][c]
                    if val > current_max:
                        current_max = val
                if current_max < best_val:
                    best_val = current_max
                    best_pos = i
            # Insert job at best_pos
            best_seq.insert(best_pos, job)
        return best_seq

    # Iterated Greedy with destruction size d=3 or 4
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = initial_seq[:]
        current_makespan = makespan(current)
        best_makespan = current_makespan
        total_processing = sum(total_time)
        T_param = 0.5
        T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6

        for _ in range(max_iter):
            # Destruction: remove d jobs randomly
            d = 3 if n <= 30 else 4
            indices = random.sample(range(n), d)
            removed = [current[i] for i in indices]
            # Build destroyed sequence by keeping non-removed jobs
            destroyed = [current[i] for i in range(n) if i not in indices]

            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            seq = destroyed[:]
            for job in removed:
                e = compute_forward(seq)
                q = compute_backward(seq)
                best_pos = 0
                best_val = float('inf')
                k = len(seq)
                for i in range(k+1):
                    f = [0] * m
                    for c in range(m):
                        if c == 0:
                            prev = e[i-1][c] if i > 0 else 0
                            f[c] = prev + times[job][c]
                        else:
                            f[c] = max(f[c-1], e[i-1][c] if i > 0 else 0) + times[job][c]
                    current_max = 0
                    for c in range(m):
                        val = f[c] + q[i][c]
                        if val > current_max:
                            current_max = val
                    if current_max < best_val:
                        best_val = current_max
                        best_pos = i
                seq.insert(best_pos, job)

            new_makespan = makespan(seq)
            # Acceptance criterion
            if new_makespan < current_makespan:
                current = seq
                current_makespan = new_makespan
                if new_makespan < best_makespan:
                    best = seq[:]
                    best_makespan = new_makespan
            else:
                if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                    current = seq
                    current_makespan = new_makespan
        return best

    # Build initial solution using NEH
    initial_seq = construct_neh()
    # Refine using Iterated Greedy
    improved_seq = iterated_greedy(initial_seq)
    return improved_seq

