                if m == 0:
                    t[m] += p[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Palmer's slope index for initial ordering
    slope = [0] * N
    for i in range(N):
        s = 0
        for j in range(M):
            s += (2 * j - M + 1) * p[i][j]
        slope[i] = s
    perm = sorted(range(N), key=lambda i: slope[i], reverse=True)

    # Local search via adjacent pairwise interchange (bubble-sort style)
    improved = True
    it = 0
    max_it = 100  # iteration cap to stay within time budget
    while improved and it < max_it:
        improved = False
        it += 1
        for i in range(N - 1):
            # Swap adjacent jobs at i and i+1
            perm[i], perm[i+1] = perm[i+1], perm[i]
            if makespan(perm) < makespan(perm):
                improved = True
            else:
                # revert swap
                perm[i], perm[i+1] = perm[i+1], perm[i]
    return perm

