    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    def neh_taillard(seq):
        n = len(seq)
        if n <= 1:
            return seq[:]
        e = [[0] * M for _ in range(n)]
        for r in range(n):
            job = seq[r]
            job_t = times[job]
            if r == 0:
                e[0][0] = job_t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_t[m]
            else:
                e[r][0] = e[r-1][0] + job_t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
        q = [[0] * M for _ in range(n+1)]
        for r in range(n-1, -1, -1):
            job = seq[r]
            job_t = times[job]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        best_seq = None
        best_cmax = float('inf')
        for i in range(n+1):
            if i == 0:
                f = [0] * M
            else:
                job = seq[i-1]
                job_t = times[job]
                f = [0] * M
                f[0] = e[i-1][0] + job_t[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + job_t[m]
            for m in range(M):
                f[m] += q[i][m]
            cmax = max(f) if M > 0 else 0
            if cmax < best_cmax:
                best_cmax = cmax
                best_seq = seq[:i] + [seq[i]] + seq[i:] if i < n else seq[:]
        return best_seq

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: P[i], reverse=True)
    if N >= 2:
        seq = [order[0], order[1]]
        alt_seq = [order[1], order[0]]
        seq = seq if makespan(seq) <= makespan(alt_seq) else alt_seq
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_cmax = float('inf')
            for pos in range(k+1):
                cand = seq[:pos] + [job] + seq[pos:]
                cmax = makespan(cand)
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = pos
            seq = seq[:best_pos] + [job] + seq[best_pos:]
    else:
        seq = order[:]

    best_seq = seq[:]
    best_cmax = makespan(best_seq)
    current_seq = seq[:]
    current_cmax = best_cmax
    T = T_param * LB_param

    max_iters = 60
    for _ in range(max_iters):
        d = 3 if N > 5 else N
        indices = random.sample(range(N), d)
        removed = [current_seq[i] for i in indices]
