                    best_cmax_local = cmax_local
                    best_pos = pos
            remaining = remaining[:best_pos] + [job] + remaining[best_pos:]
        new_seq = remaining
        new_cmax = makespan(new_seq)
        if new_cmax < current_cmax:
            current_seq = new_seq
            current_cmax = new_cmax
            if new_cmax < best_cmax:
                best_seq = new_seq
                best_cmax = new_cmax
        elif new_cmax < best_cmax:
            best_seq = new_seq
            best_cmax = new_cmax
        if random.random() < math.exp(-(new_cmax - current_cmax) / T):
            current_seq = new_seq
            current_cmax = new_cmax
    return best_seq

