def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: total_processing[i], reverse=True)

    makespan_cache = {}

    def compute_makespan(seq):
        key = tuple(seq)
        if key in makespan_cache:
            return makespan_cache[key]
        if not seq:
            makespan_cache[key] = 0
            return 0
        machine_time = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    machine_time[m] += times[job][m]
                else:
                    machine_time[m] = max(machine_time[m], machine_time[m-1]) + times[job][m]
        makespan_cache[key] = machine_time[-1]
        return makespan_cache[key]

    def taillard_forward_backward(partial):
        k = len(partial)
        if k == 0:
            return [[0] * M], [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = (e[0][m-1] if m > 0 else 0) + times[partial[0]][m]
        for r in range(1, k):
            job = partial[r]
            for m in range(M):
                left = e[r-1][m] if r-1 >= 0 else 0
                up = e[r][m-1] if m-1 >= 0 else 0
                e[r][m] = max(left, up) + times[job][m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = partial[r]
            for m in range(M-1, -1, -1):
                down = q[r+1][m] if r+1 <= k else 0
                right = q[r][m+1] if m+1 < M else 0
                q[r][m] = max(down, right) + times[job][m]
        return e, q

    def insert_job_taillard(partial, job, e, q):
        k = len(partial)
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            f = [0] * M
            if i == 0:
                prev_e = [0] * M
            else:
                prev_e = e[i-1]
            for m in range(M):
                left = f[m-1] if m-1 >= 0 else 0
                up = prev_e[m] if i > 0 else 0
                f[m] = max(left, up) + times[job][m]
            makespan = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan:
                    makespan = val
            if makespan < best_makespan:
                best_makespan = makespan
                best_pos = i
        return best_pos

    def neh_construct():
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        first_two = [order[0], order[1]]
        seq1 = first_two[:]
        seq2 = [order[1], order[0]]
        if compute_makespan(seq1) <= compute_makespan(seq2):
            current = seq1
        else:
            current = seq2
        for idx in range(2, N):
            job = order[idx]
            e, q = taillard_forward_backward(current)
            pos = insert_job_taillard(current, job, e, q)
            current.insert(pos, job)
        return current

    def ig_improve(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_makespan = compute_makespan(best)
        avg_pt = sum(total_processing) / (N * M)
        T = 0.5 * avg_pt
        d = 3 if N > 20 else 2
        if d < 2:
            d = 2
        for _ in range(max_iter):
            if len(current) <= d:
                destroyed = []
                extracted = current[:]
            else:
                indices = random.sample(range(len(current)), d)
                indices.sort(reverse=True)
                extracted = [current.pop(i) for i in indices]
                destroyed = current
            e, q = taillard_forward_backward(destroyed)
            for job in extracted:
                pos = insert_job_taillard(destroyed, job, e, q)
                destroyed.insert(pos, job)
            current = destroyed
            current_makespan = compute_makespan(current)
            if current_makespan < best_makespan:
                best_makespan = current_makespan
                best = current[:]
            if current_makespan < compute_makespan(initial_seq):
                if random.random() < math.exp(-(current_makespan - compute_makespan(initial_seq)) / T):
                    initial_seq = current[:]
        return best

    initial_seq = neh_construct()
    improved_seq = ig_improve(initial_seq, max_iter=50)
    return improved_seq

