                if mc == 0:
                    prev = e[pos-1][mc] if pos > 0 else 0
                    f[mc] = prev + times[job][mc]
                else:
                    f[mc] = max(f[mc-1], e[pos-1][mc] if pos > 0 else 0) + times[job][mc]
            # Makespan if inserted at pos
            mk = 0
            for mc in range(m):
                val = f[mc] + q[pos][mc]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = pos
        best_seq.insert(best_pos, job)
        best_makespan = best_mk

    # Iterated Greedy refinement
    current_seq = best_seq[:]
    current_mk = best_makespan
    best_seq_overall = current_seq[:]
    best_mk_overall = current_mk

    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
    d = 3 if n > 5 else max(1, n // 2)
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for it in range(max_iter):
        # Destruction: remove d jobs
        removed = random.sample(range(n), d)
        removed_set = set(removed)
        destroyed_seq = [job for job in current_seq if job not in removed_set]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            k = len(destroyed_seq)
            # Forward matrix e for destroyed_seq
            e = [[0] * m for _ in range(k)]
            for r in range(k):
                job_r = destroyed_seq[r]
                for mc in range(m):
                    if mc == 0:
                        e[r][mc] = (e[r-1][mc] if r > 0 else 0) + times[job_r][mc]
                    else:
                        e[r][mc] = max(e[r-1][mc] if r > 0 else 0, e[r][mc-1]) + times[job_r][mc]
            # Backward matrix q
            q = [[0] * m for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = destroyed_seq[r]
                for mc in range(m-1, -1, -1):
                    if mc == m-1:
                        q[r][mc] = q[r+1][mc] + times[job_r][mc]
                    else:
                        q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + times[job_r][mc]
            # Evaluate insertion positions
            best_pos = 0
            best_mk = float('inf')
            for pos in range(k+1):
                f = [0] * m
                for mc in range(m):
                    if mc == 0:
                        prev = e[pos-1][mc] if pos > 0 else 0
                        f[mc] = prev + times[job][mc]
                    else:
                        f[mc] = max(f[mc-1], e[pos-1][mc] if pos > 0 else 0) + times[job][mc]
                mk = 0
                for mc in range(m):
                    val = f[mc] + q[pos][mc]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            destroyed_seq.insert(best_pos, job)
        new_seq = destroyed_seq
        new_mk = best_mk
        # Acceptance
        if new_mk < current_mk:
            current_seq, current_mk = new_seq, new_mk
            if new_mk < best_mk_overall:
                best_seq_overall, best_mk_overall = new_seq[:], new_mk
                no_improve = 0
            else:
                no_improve += 1
        else:
            delta = new_mk - current_mk
            if random.random() < math.exp(-delta / T):
                current_seq, current_mk = new_seq, new_mk
                no_improve += 1
            else:
                no_improve += 1
        if no_improve >= no_improve_limit:
            break

    return best_seq_overall

def makespan(times, seq):
    if not seq:
        return 0
    n = len(seq)
    m = len(times[0])
    # Compute completion times using DP
    dp = [0] * m
    for job in seq:
        for mc in range(m):
            if mc == 0:
                dp[mc] += times[job][mc]
            else:
                dp[mc] = max(dp[mc-1], dp[mc]) + times[job][mc]
    return dp[-1]

