def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [row[:] for row in times]
    P = [sum(row) for row in p]
    S = [sum((2 * j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]

    # Makespan calculation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[-1]

    # Taillard acceleration: forward completion matrix
    def compute_forward(seq):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        if k == 0:
            return e
        for m in range(M):
            e[0][m] = p[seq[0]][m] if m == 0 else (e[0][m-1] + p[seq[0]][m])
        for r in range(1, k):
            job = seq[r]
            e[r][0] = e[r-1][0] + p[job][0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job][m]
        return e

    # Taillard acceleration: backward tail matrix
    def compute_backward(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        if k == 0:
            return q
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = seq[r]
            q[r][M-1] = q[r+1][M-1] + p[job][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]
        return q

    # Evaluate makespan of inserting job x at position i in seq (length k)
    def evaluate_insertion(seq, x, i, e, q):
        k = len(seq)
        f = [0] * M
        if i == 0:
            for m in range(M):
                f[m] = p[x][m] if m == 0 else (f[m-1] + p[x][m])
        else:
            f[0] = e[i-1][0] + p[x][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[i-1][m]) + p[x][m]
        best = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    def neh_construction(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            seq1 = [order[0], order[1]]
            seq2 = [order[1], order[0]]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, len(order)):
            job = order[idx]
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_mk = float('inf')
            for pos in range(len(seq) + 1):
                mk = evaluate_insertion(seq, job, pos, e, q)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size 2 (block insertion)
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_mk = makespan(best)
        total = sum(P)
        T = 0.5 * total / (10 * N * M) if N * M > 0 else 1e-6
        d = 2  # destruction size: remove 2 jobs at a time

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            if len(current) < d:
                destroyed = current[:]
                remaining = []
            else:
                indices = random.sample(range(len(current)), d)
                indices.sort(reverse=True)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(len(current)) if i not in indices]

            # Reconstruction: reinsert destroyed jobs one by one using NEH insertion with Taillard
            for job in destroyed:
                if not remaining:
                    remaining = [job]
                    continue
                e = compute_forward(remaining)
                q = compute_backward(remaining)
                best_pos = 0
                best_mk_ins = float('inf')
                for pos in range(len(remaining) + 1):
                    mk = evaluate_insertion(remaining, job, pos, e, q)
                    if mk < best_mk_ins:
                        best_mk_ins = mk
                        best_pos = pos
                remaining.insert(best_pos, job)
            current = remaining

            # Acceptance criterion
            curr_mk = makespan(current)
            if curr_mk < best_mk:
                best_mk = curr_mk
                best = current[:]
            if curr_mk < makespan(best):
                best = current[:]
                best_mk = curr_mk
            if curr_mk < makespan(current):
                current = current[:]
            else:
                if curr_mk == makespan(current):
                    current = current[:]
                else:
                    delta = curr_mk - makespan(current)
                    if delta < 0 or random.random() < math.exp(-delta / T):
                        current = current[:]
                    else:
                        # Revert to previous current (not stored, so keep as is; simplification)
                        pass
        return best

    # Try multiple orderings: NEH (total time), Palmer (slope), and random
    orders = [
        sorted(range(N), key=lambda i: (-P[i], i)),  # NEH: descending total time
        sorted(range(N), key=lambda i: (-S[i], i)),  # Palmer: descending slope
        list(range(N))  # natural order
    ]
    random.shuffle(orders)  # add variability

    best_overall = []
    best_mk_overall = float('inf')

    for order in orders:
        init_seq = neh_construction(order)
        refined_seq = iterated_greedy(init_seq, max_iter=40)
        mk = makespan(refined_seq)
        if mk < best_mk_overall:
            best_mk_overall = mk
            best_overall = refined_seq[:]
        if best_mk_overall == 0:  # optimal possible
            break

    return best_overall

