def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job times for fast access
    p = [list(row) for row in times]
    total_p = [sum(row) for row in p]

    # Precompute lower bound for early termination (Taillard's machine bottleneck)
    lb = 0
    for m in range(M):
        min_before = min(p[i][l] for i in range(N) for l in range(m)) if m > 0 else 0
        min_after = min(p[i][l] for i in range(N) for l in range(m+1, M)) if m < M-1 else 0
        machine_sum = sum(p[i][m] for i in range(N))
        lb_candidate = min_before + machine_sum + min_after
        if lb_candidate > lb:
            lb = lb_candidate

    # Makespan evaluation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[-1]

    # Taillard-accelerated NEH insertion: evaluate all insertion positions for job x in current partial schedule
    def evaluate_insertion(partial, x):
        k = len(partial)
        if k == 0:
            return [x], p[x][0] if M == 1 else _makespan_single_job(x, p, M)
        # Forward matrix e: completion times of partial schedule
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job_r][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job_r][m]
        # Backward matrix q: tail times from position r to end
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job_r][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
        # Evaluate each insertion position i in [0, k]
        best_i = 0
        best_mk = float('inf')
        for i in range(k+1):
            # Forward pass for job x up to insertion point i-1
            f = [0] * M
            for m in range(M):
                if m == 0:
                    prev = e[i-1][m] if i > 0 else 0
                    f[m] = prev + p[x][m]
                else:
                    left = f[m-1]
                    up = e[i-1][m] if i > 0 else 0
                    f[m] = max(left, up) + p[x][m]
            # Combine with tail from position i
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_i = i
        # Build new permutation
        new_perm = partial[:best_i] + [x] + partial[best_i:]
        return new_perm, best_mk

    def _makespan_single_job(job, p, M):
        t = 0
        for m in range(M):
            t += p[job][m]
        return t

    # Construct initial solution using NEH with Taillard acceleration
    jobs_sorted = sorted(range(N), key=lambda i: total_p[i], reverse=True)
    perm = [jobs_sorted[0]]
    best_mk = p[jobs_sorted[0]][0] if M == 1 else _makespan_single_job(jobs_sorted[0], p, M)
    for idx in range(1, N):
        job = jobs_sorted[idx]
        perm, best_mk = evaluate_insertion(perm, job)
        if best_mk == lb:
            break

    # Iterated Greedy refinement
    current = perm[:]
    current_mk = best_mk
    best_perm = current[:]
    best_mk_overall = current_mk

    # IG parameters
    d = 3 if N > 5 else max(1, N//2)
    T_param = 0.5
    total_processing = sum(total_p)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 50
    if N > 80:
        max_iter = 30
    elif N > 40:
        max_iter = 40

    for _ in range(max_iter):
        # Destruction: remove d jobs at random positions
        if d >= N:
            destroyed = []
            extracted = current[:]
        else:
            positions = random.sample(range(N), d)
            positions.sort(reverse=True)
            extracted = []
            for pos in positions:
                extracted.append(current.pop(pos))
            destroyed = current  # remaining sequence

        # Reconstruction: reinsert extracted jobs one by one using NEH/Taillard
        for job in extracted:
            destroyed, _ = evaluate_insertion(destroyed, job)
        new_perm = destroyed
        new_mk = makespan(new_perm)

        # Acceptance criterion
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current = new_perm
            current_mk = new_mk
            if new_mk < best_mk_overall:
                best_perm = new_perm[:]
                best_mk_overall = new_mk
                if best_mk_overall == lb:
                    break

    return best_perm

