def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    if total_processing == 0:
        return list(range(N))

    # Precompute job data for faster access
    p = [row[:] for row in times]
    P = [sum(job) for job in p]

    # Makespan calculation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_p = p[job]
            t[0] += job_p[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_p[m]
        return t[-1]

    # Taillard's acceleration: compute forward matrix e for a sequence
    def compute_e(seq):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        job0 = p[seq[0]]
        e[0][0] = job0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0[m]
        for r in range(1, k):
            job_r = p[seq[r]]
            e[r][0] = e[r-1][0] + job_r[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
        return e

    # Taillard's acceleration: compute backward tail matrix q for a sequence
    def compute_q(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        if k == 0:
            return q
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = p[seq[r]]
            q[r][M-1] = q[r+1][M-1] + job_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
        return q

    # Evaluate makespan for inserting job x at position i using Taillard's O(M) method
    def evaluate_insertion(e, q, x, i):
        # f[m] = completion of job x on machine m when inserted after first i jobs
        f = [0] * M
        if i == 0:
            f[0] = p[x][0]
            for m in range(1, M):
                f[m] = f[m-1] + p[x][m]
        else:
            e_im1 = e[i-1]
            f[0] = e_im1[0] + p[x][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_im1[m]) + p[x][m]
        q_i = q[i]
        max_val = 0
        for m in range(M):
            val = f[m] + q_i[m]
            if val > max_val:
                max_val = val
        return max_val

    # NEH construction with Taillard acceleration
    def neh_construction():
        # Sort jobs by total processing time descending
        order = sorted(range(N), key=lambda i: P[i], reverse=True)
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            e = compute_e(seq)
            q = compute_q(seq)
            best_pos = 0
            best_makespan = float('inf')
            # Try all k+1 positions
            for i in range(k+1):
                cmax = evaluate_insertion(e, q, job, i)
                if cmax < best_makespan:
                    best_makespan = cmax
                    best_pos = i
            seq.insert(best_pos, job)
        return seq

    # Iterated Greedy with destruction size d=3
    def iterated_greedy(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        best_makespan = makespan(best)
        # Temperature parameter
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        d = 3  # destruction size

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            if d >= N:
                destroyed = []
                remaining = []
            else:
                positions = random.sample(range(N), d)
                positions.sort(reverse=True)
                destroyed = [current[pos] for pos in positions]
                remaining = current[:]
                for pos in positions:
                    remaining.pop(pos)
            # Reconstruction: reinsert destroyed jobs one by one in random order
            random.shuffle(destroyed)
            seq = remaining[:]
            for job in destroyed:
                e = compute_e(seq)
                q = compute_q(seq)
                best_pos = 0
                best_makespan_insert = float('inf')
                for i in range(len(seq)+1):
                    cmax = evaluate_insertion(e, q, job, i)
                    if cmax < best_makespan_insert:
                        best_makespan_insert = cmax
                        best_pos = i
                seq.insert(best_pos, job)
            # Acceptance criterion
            new_makespan = makespan(seq)
            if new_makespan < makespan(current):
                current = seq
                if new_makespan < best_makespan:
                    best = seq[:]
                    best_makespan = new_makespan
            elif new_makespan < best_makespan:
                # Accept with probability based on Metropolis
                if random.random() < math.exp(-(new_makespan - makespan(current)) / T):
                    current = seq
                else:
                    # Reject, keep current
                    pass
            else:
                if random.random() < math.exp(-(new_makespan - makespan(current)) / T):
                    current = seq
        return best

    # Build initial solution with NEH
    initial_seq = neh_construction()
    # Refine with Iterated Greedy
    best_seq = iterated_greedy(initial_seq, max_iter=50)
    return best_seq

