def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and variances per machine
    total_time = [0] * N
    machine_variance = [0.0] * M
    machine_mean = [0.0] * M
    for i in range(N):
        for j in range(M):
            t = times[i][j]
            total_time[i] += t
            machine_mean[j] += t
    for j in range(M):
        machine_mean[j] /= N
    for i in range(N):
        for j in range(M):
            diff = times[i][j] - machine_mean[j]
            machine_variance[j] += diff * diff
    for j in range(M):
        machine_variance[j] /= N
        if machine_variance[j] == 0:
            machine_variance[j] = 1e-9  # Avoid division by zero

    # Palmer's slope index with inverse variance weighting
    slope = [0.0] * N
    for i in range(N):
        s = 0.0
        for j in range(M):
            weight = (2 * j - M + 1) / machine_variance[j]
            s += weight * times[i][j]
        slope[i] = s
    # Sort jobs by slope descending
    order = sorted(range(N), key=lambda i: slope[i], reverse=True)

    # Makespan calculation
    def makespan(perm):
        if not perm:
            return 0
        t_prev = [0] * M
        for job in perm:
            t_curr = [0] * M
            for m in range(M):
                if m == 0:
                    t_curr[m] = t_prev[m] + times[job][m]
                else:
                    t_curr[m] = max(t_prev[m], t_curr[m-1]) + times[job][m]
            t_prev = t_curr
        return t_prev[-1]

    # Taillard's accelerated insertion evaluation for a partial schedule
    def evaluate_insertion(partial, job, k):
        # k is the length of partial schedule
        # Build forward matrix e for partial schedule (size k x M)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_r = partial[r]
            for m in range(M):
                if m == 0:
                    prev = e[r-1][m] if r > 0 else 0
                    e[r][m] = prev + times[job_r][m]
                else:
                    left = e[r][m-1]
                    up = e[r-1][m] if r > 0 else 0
                    e[r][m] = max(left, up) + times[job_r][m]
        # Build backward tail matrix q for partial schedule (size (k+1) x M)
        q = [[0] * M for _ in range(k+1)]
        # q[k][m] = 0 already
        for r in range(k-1, -1, -1):
            job_r = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job_r][m]
                else:
                    down = q[r+1][m]
                    right = q[r][m+1]
                    q[r][m] = max(down, right) + times[job_r][m]
        # Evaluate insertion at each position i in [0, k]
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            # Compute forward vector f for job at position i
            f = [0] * M
            for m in range(M):
                if m == 0:
                    prev_e = e[i-1][m] if i > 0 else 0
                    f[m] = prev_e + times[job][m]
                else:
                    left_f = f[m-1]
                    up_e = e[i-1][m] if i > 0 else 0
                    f[m] = max(left_f, up_e) + times[job][m]
            # Compute makespan candidate: max_m (f[m] + q[i][m])
            cand = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cand:
                    cand = val
            if cand < best_makespan:
                best_makespan = cand
                best_pos = i
        return best_pos, best_makespan

    # NEH construction with Taillard acceleration
    def neh_construction(job_order):
        if not job_order:
            return []
        seq = [job_order[0]]
        if len(job_order) == 1:
            return seq
        # Try both orders of first two jobs
        seq1 = [job_order[0], job_order[1]]
        seq2 = [job_order[1], job_order[0]]
        if makespan(seq1) <= makespan(seq2):
            seq = seq1
        else:
            seq = seq2
        # Insert remaining jobs
        for idx in range(2, len(job_order)):
            job = job_order[idx]
            pos, _ = evaluate_insertion(seq, job, len(seq))
            seq.insert(pos, job)
        return seq

    # Iterated Greedy with destruction size d=3
    def iterated_greedy(initial_seq, max_iter=50):
        current = initial_seq[:]
        best = initial_seq[:]
        best_makespan = makespan(best)
        total_processing = sum(total_time)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        for _ in range(max_iter):
            # Destruction: remove d=3 random jobs
            if len(current) < 3:
                destroyed = current[:]
                remaining = []
            else:
                indices = random.sample(range(len(current)), 3)
                indices.sort(reverse=True)
                destroyed = []
                for idx in indices:
                    destroyed.append(current.pop(idx))
                remaining = current
            # Reconstruction: reinsert destroyed jobs one by one in random order
            random.shuffle(destroyed)
            for job in destroyed:
                pos, _ = evaluate_insertion(remaining, job, len(remaining))
                remaining.insert(pos, job)
            current = remaining
            curr_makespan = makespan(current)
            # Acceptance criterion
            if curr_makespan < makespan(best):
                best = current[:]
                best_makespan = curr_makespan
            if curr_makespan < makespan(initial_seq):  # Always improve over current
                initial_seq = current[:]
            else:
                delta = curr_makespan - makespan(initial_seq)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    initial_seq = current[:]
        return best

    # Build initial solution using NEH
    initial_seq = neh_construction(order)
    # Refine with Iterated Greedy
    improved_seq = iterated_greedy(initial_seq, max_iter=40)
    return improved_seq

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0]) if n > 0 else 0
    if n == 1:
        return [0]
    if m == 0:
        return list(range(n))
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_data = [times[i][:] for i in range(n)]
    total_processing = [sum(job) for job in job_data]

    # Identify bottleneck machine (machine with highest total workload)
    machine_loads = [sum(job_data[i][j] for i in range(n)) for j in range(m)]
    bottleneck = machine_loads.index(max(machine_loads))

    # Palmer's slope index for alternative ordering
    slope = [sum((2 * j - m + 1) * job_data[i][j] for j in range(m)) for i in range(n)]

    # NEH construction with Taillard acceleration
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            pt = job_data[job]
            t[0] += pt[0]
            for k in range(1, m):
                t[k] = max(t[k-1], t[k]) + pt[k]
        return t[-1]

    def taillard_insert(partial, job):
        k = len(partial)
        if k == 0:
            return [job]
        # Forward matrix e: completion times of partial schedule
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            pt = job_data[partial[r]]
            if r == 0:
                e[0][0] = pt[0]
                for mc in range(1, m):
                    e[0][mc] = e[0][mc-1] + pt[mc]
            else:
                e[r][0] = e[r-1][0] + pt[0]
                for mc in range(1, m):
                    e[r][mc] = max(e[r-1][mc], e[r][mc-1]) + pt[mc]
        # Backward matrix q: tail times from job r to end
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pt = job_data[partial[r]]
            q[r][m-1] = q[r+1][m-1] + pt[m-1]
            for mc in range(m-2, -1, -1):
                q[r][mc] = max(q[r+1][mc], q[r][mc+1]) + pt[mc]
        best_pos, best_mk = 0, float('inf')
        for i in range(k+1):
            # Forward pass for job insertion at position i
            f = [0] * m
            if i == 0:
                f[0] = job_data[job][0]
                for mc in range(1, m):
                    f[mc] = f[mc-1] + job_data[job][mc]
            else:
                pt = job_data[job]
                f[0] = e[i-1][0] + pt[0]
                for mc in range(1, m):
                    f[mc] = max(f[mc-1], e[i-1][mc]) + pt[mc]
            # Makespan = max over machines of (forward + backward)
            mk = 0
            for mc in range(m):
                val = f[mc] + q[i][mc]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return partial[:best_pos] + [job] + partial[best_pos:]

    # Build initial solution using NEH with Palmer's slope as tie-breaker in sorting
    indices = list(range(n))
    indices.sort(key=lambda i: (-total_processing[i], -slope[i]))
    perm = [indices[0], indices[1]]
    if makespan([indices[1], indices[0]]) < makespan(perm):
        perm = [indices[1], indices[0]]
    for idx in indices[2:]:
        perm = taillard_insert(perm, idx)

    # Iterated Greedy refinement
    def ig_iteration(current):
        # Destruction: remove d jobs randomly
        d = 3 if n > 5 else max(1, n // 3)
        if d >= n:
            return current[:]
        pos = random.sample(range(n), d)
        removed = [current[i] for i in pos]
        remaining = [current[i] for i in range(n) if i not in pos]
        random.shuffle(removed)  # randomize reinsertion order
        # Reconstruction: reinsert using Taillard-accelerated NEH
        for job in removed:
            remaining = taillard_insert(remaining, job)
        return remaining

    current = perm[:]
    best = current[:]
    best_mk = makespan(best)
    total = sum(total_processing)
    T_param = 0.5
    T = T_param * total / (10 * n * m) if n * m > 0 else 1e-6
    max_iter = 60  # calibrated to stay within time budget
    for _ in range(max_iter):
        candidate = ig_iteration(current)
        mk = makespan(candidate)
        if mk < best_mk:
            best_mk = mk
            best = candidate[:]
            if mk == sum(job_data[i][bottleneck] for i in range(n)) + min(sum(job_data[i][:bottleneck] for i in range(n))) + min(sum(job_data[i][bottleneck+1:] for i in range(n))):
                break  # reached lower bound (simplified check)
        if mk < makespan(current) or random.random() < math.exp(-(mk - makespan(current)) / T):
            current = candidate[:]
    return best

import math
