def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices for alternative orderings
    total_times = [sum(job) for job in times]
    slope_index = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Taillard's machine-based lower bound for early termination
    def lower_bound():
        lb = 0
        for m in range(M):
            min_before = min(times[i][:m] if m > 0 else [0] for i in range(N))
            min_after = min(times[i][m+1:] if m < M-1 else [0] for i in range(N))
            machine_sum = sum(times[i][m] for i in range(N))
            lb_m = min_before + machine_sum + min_after
            if lb_m > lb:
                lb = lb_m
        return lb

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    # Taillard-accelerated makespan evaluation for insertion
    def evaluate_insertion(partial, job_idx, e, q):
        k = len(partial)
        job_t = times[job_idx]
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k + 1):
            # Forward pass up to position i
            f = [0] * M
            if i == 0:
                f[0] = job_t[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], 0) + job_t[m]
            else:
                f[0] = e[i-1][0] + job_t[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[i-1][m]) + job_t[m]
            # Calculate makespan if inserted at position i
            current_max = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > current_max:
                    current_max = val
            if current_max < best_makespan:
                best_makespan = current_max
                best_pos = i
        return best_pos, best_makespan

    # NEH construction with Taillard acceleration
    def neh_construct(order):
        if not order:
            return []
        perm = [order[0]]
        if len(order) == 1:
            return perm
        # Evaluate first two jobs
        job0, job1 = order[0], order[1]
        m01 = makespan([job0, job1])
        m10 = makespan([job1, job0])
        perm = [job0, job1] if m01 <= m10 else [job1, job0]
        # Prepare forward and backward matrices
        e = [[0] * M for _ in range(len(perm))]
        q = [[0] * M for _ in range(len(perm) + 1)]
        # Fill e for current perm
        for r in range(len(perm)):
            job = perm[r]
            job_t = times[job]
            if r == 0:
                e[0][0] = job_t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_t[m]
            else:
                e[r][0] = e[r-1][0] + job_t[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
        # Fill q for current perm
        for m in range(M):
            q[len(perm)][m] = 0
        for r in range(len(perm)-1, -1, -1):
            job = perm[r]
            job_t = times[job]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        # Insert remaining jobs
        for idx in range(2, len(order)):
            job_idx = order[idx]
            # Recompute e and q for current perm (length = idx)
            k = len(perm)
            # Recompute e
            for r in range(k):
                job = perm[r]
                job_t = times[job]
                if r == 0:
                    e[0][0] = job_t[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_t[m]
                else:
                    e[r][0] = e[r-1][0] + job_t[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
            # Recompute q
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job = perm[r]
                job_t = times[job]
                q[r][M-1] = q[r+1][M-1] + job_t[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
            # Evaluate insertion positions
            pos, _ = evaluate_insertion(perm, job_idx, e, q)
            perm.insert(pos, job_idx)
        return perm

    # Try multiple orderings: total time descending, slope index descending
    order_total = sorted(range(N), key=lambda i: total_times[i], reverse=True)
    order_slope = sorted(range(N), key=lambda i: slope_index[i], reverse=True)
    best_perm = None
    best_makespan = float('inf')
    lb = lower_bound()
    for order in [order_total, order_slope]:
        perm = neh_construct(order)
        m = makespan(perm)
        if m < best_makespan:
            best_makespan = m
            best_perm = perm
            if best_makespan == lb:
                return best_perm

    # Iterated Greedy refinement
    def iterated_greedy(init_perm, init_makespan, max_iter=60):
        nonlocal best_perm, best_makespan
        current_perm = init_perm[:]
        current_makespan = init_makespan
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current_perm[i] for i in sorted(indices, reverse=True)]
            for i in sorted(indices, reverse=True):
                del current_perm[i]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job_idx in removed:
                k = len(current_perm)
                # Build e and q for current_perm
                e = [[0] * M for _ in range(k)]
                q = [[0] * M for _ in range(k + 1)]
                for r in range(k):
                    job = current_perm[r]
                    job_t = times[job]
                    if r == 0:
                        e[0][0] = job_t[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + job_t[m]
                    else:
                        e[r][0] = e[r-1][0] + job_t[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[m]
                for m in range(M):
                    q[k][m] = 0
                for r in range(k-1, -1, -1):
                    job = current_perm[r]
                    job_t = times[job]
                    q[r][M-1] = q[r+1][M-1] + job_t[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
                # Find best insertion position
                best_pos = 0
                best_m = float('inf')
                job_t = times[job_idx]
                for i in range(k + 1):
                    f = [0] * M
                    if i == 0:
                        f[0] = job_t[0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], 0) + job_t[m]
                    else:
                        f[0] = e[i-1][0] + job_t[0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + job_t[m]
                    current_max = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > current_max:
                            current_max = val
                    if current_max < best_m:
                        best_m = current_max
                        best_pos = i
                current_perm.insert(best_pos, job_idx)
            new_makespan = makespan(current_perm)
            # Acceptance criterion
            if new_makespan < current_makespan:
                current_perm = current_perm[:]
                current_makespan = new_makespan
                if new_makespan < best_makespan:
                    best_makespan = new_makespan
                    best_perm = current_perm[:]
                    if best_makespan == lb:
                        break
            else:
                if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                    current_perm = current_perm[:]
                    current_makespan = new_makespan
        return best_perm

    best_perm = iterated_greedy(best_perm, best_makespan)
    return best_perm

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_data = [times[i][:] for i in range(n)]
    total_processing = [sum(job) for job in job_data]

    # Function to compute makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            pj = job_data[job]
            t[0] += pj[0]
            for k in range(1, m):
                t[k] = max(t[k], t[k-1]) + pj[k]
        return t[-1]

    # Function to compute forward completion matrix e for a prefix of length k
    def compute_forward(prefix):
        k = len(prefix)
        if k == 0:
            return [[0]*m]
        e = [[0]*m for _ in range(k)]
        for i in range(k):
            pj = job_data[prefix[i]]
            if i == 0:
                e[0][0] = pj[0]
                for j in range(1, m):
                    e[0][j] = e[0][j-1] + pj[j]
            else:
                e[i][0] = e[i-1][0] + pj[0]
                for j in range(1, m):
                    e[i][j] = max(e[i-1][j], e[i][j-1]) + pj[j]
        return e

    # Function to compute backward tail matrix q for a prefix of length k
    def compute_backward(prefix):
        k = len(prefix)
        if k == 0:
            return [[0]*m]
        q = [[0]*m for _ in range(k+1)]
        # q[k][:] is already 0
        for i in range(k-1, -1, -1):
            pj = job_data[prefix[i]]
            q[i][m-1] = q[i+1][m-1] + pj[m-1]
            for j in range(m-2, -1, -1):
                q[i][j] = max(q[i+1][j], q[i][j+1]) + pj[j]
        return q

    # Function to compute makespan when inserting job x at position i in prefix (length k)
    def insert_makespan(prefix, x, i):
        k = len(prefix)
        # Compute forward vector f for job x up to position i-1
        f = [0]*m
        if i == 0:
            # e[-1][:] = 0
            f[0] = job_data[x][0]
            for j in range(1, m):
                f[j] = f[j-1] + job_data[x][j]
        else:
            e_prev = compute_forward(prefix[:i])[-1]  # e[i-1][:]
            f[0] = e_prev[0] + job_data[x][0]
            for j in range(1, m):
                f[j] = max(f[j-1], e_prev[j]) + job_data[x][j]
        # Compute backward tail q for prefix from position i onward
        q = compute_backward(prefix[i:])  # q[0][:] corresponds to start at index i in prefix
        # Makespan = max over m of (f[m] + q[0][m])
        makespan_val = 0
        for j in range(m):
            val = f[j] + q[0][j]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH with Taillard acceleration: builds initial solution
    def neh_taillard():
        # Sort jobs by total processing time descending
        order = sorted(range(n), key=lambda i: total_processing[i], reverse=True)
        if n == 0:
            return []
        # Start with first job
        perm = [order[0]]
        for k in range(1, n):
            job = order[k]
            best_pos = 0
            best_makespan = float('inf')
            # Try inserting job at each position from 0 to k
            for pos in range(k+1):
                msp = insert_makespan(perm, job, pos)
                if msp < best_makespan:
                    best_makespan = msp
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy (IG) with destruction size d=3
    def iterated_greedy(initial_perm, max_iter=50):
        current = initial_perm[:]
        best = current[:]
        best_makespan = makespan(best)
        total_processing_sum = sum(total_processing)
        T_param = 0.5
        T = T_param * total_processing_sum / (10 * n * m) if n * m > 0 else 1e-6
        d = 3  # destruction size

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            if n <= d:
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(n), d)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(n) if i not in indices_set]
            # Reconstruction: reinsert destroyed jobs one by one in random order
            random.shuffle(destroyed)
            for job in destroyed:
                best_pos = 0
                best_msp = float('inf')
                for pos in range(len(remaining)+1):
                    msp = insert_makespan(remaining, job, pos)
                    if msp < best_msp:
                        best_msp = msp
                        best_pos = pos
                remaining.insert(best_pos, job)
            # New candidate solution
            candidate = remaining[:]
            candidate_makespan = makespan(candidate)
            # Acceptance criterion
            if candidate_makespan < makespan(current):
                current = candidate[:]
                if candidate_makespan < best_makespan:
                    best = candidate[:]
                    best_makespan = candidate_makespan
            else:
                if random.random() < math.exp(-(candidate_makespan - makespan(current)) / T):
                    current = candidate[:]
        return best

    # Generate initial solution using NEH
    init_perm = neh_taillard()
    # Apply iterated greedy refinement
    final_perm = iterated_greedy(init_perm, max_iter=40)
    return final_perm

