    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    def makespan_taillard(seq, e, q):
        if not seq:
            return 0
        k = len(seq)
        for r in range(k):
            job = seq[r]
            if r == 0:
                e[0] = times[job][0]
                for m in range(1, M):
                    e[m] = e[m-1] + times[job][m]
            else:
                e[r*M + 0] = e[(r-1)*M + 0] + times[job][0]
                for m in range(1, M):
                    e[r*M + m] = max(e[(r-1)*M + m], e[r*M + m-1]) + times[job][m]
        for r in range(k-1, -1, -1):
            job = seq[r]
            if r == k-1:
                for m in range(M):
                    q[r*M + m] = times[job][m] + (q[(r+1)*M + m] if r+1 < k else 0)
            else:
                q[r*M + M-1] = times[job][M-1] + q[(r+1)*M + M-1]
                for m in range(M-2, -1, -1):
                    q[r*M + m] = times[job][m] + max(q[(r+1)*M + m], q[r*M + m+1])
        best = float('inf')
        for i in range(k+1):
            f = [0] * M
            if i == 0:
                for m in range(M):
                    f[m] = (e[-1*M + m] if -1 >= 0 else 0) + times[seq[0]][m] if k > 0 else 0
                if k == 0:
                    for m in range(M):
                        f[m] = times[seq[0]][m] if k > 0 else 0
            else:
                base_idx = (i-1)*M
                f[0] = e[base_idx] + times[seq[i]][0] if i < k else e[base_idx] + 0
                for m in range(1, M):
                    f[m] = max(f[m-1], e[base_idx + m]) + (times[seq[i]][m] if i < k else 0)
            tail_idx = i*M
            current = 0
            for m in range(M):
                val = f[m] + (q[tail_idx + m] if i < k else 0)
                if val > current:
                    current = val
            if current < best:
                best = current
        return best

    def makespan_taillard_insert(seq, job, e, q):
        k = len(seq)
        if k == 0:
            f = [0] * M
            for m in range(M):
                f[m] = (0 if m == 0 else f[m-1]) + times[job][m]
            return f[-1]
        best = float('inf')
        for i in range(k+1):
            f = [0] * M
            if i == 0:
                f[0] = times[job][0]
                for m in range(1, M):
                    f[m] = f[m-1] + times[job][m]
            else:
                base_idx = (i-1)*M
                f[0] = e[base_idx] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[base_idx + m]) + times[job][m]
            tail_idx = i*M
            current = 0
            for m in range(M):
                val = f[m] + (q[tail_idx + m] if i < k else 0)
                if val > current:
                    current = val
            if current < best:
                best = current
        return best

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: (-P[i], i))
    e = [0] * (N * M)
    q = [0] * (N * M)
    seq = []
    for idx in order:
        job = idx
        if not seq:
            seq.append(job)
            e[0*M + 0] = times[job][0]
            for m in range(1, M):
                e[0*M + m] = e[0*M + m-1] + times[job][m]
            for m in range(M):
                q[0*M + m] = times[job][m]
        else:
            best_pos = 0
            best_mk = float('inf')
            for pos in range(len(seq)+1):
                mk = makespan_taillard_insert(seq, job, e, q)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq.insert(best_pos, job)
            k = len(seq)
            for r in range(k):
                job_r = seq[r]
                if r == 0:
                    e[r*M + 0] = times[job_r][0]
                    for m in range(1, M):
                        e[r*M + m] = e[r*M + m-1] + times[job_r][m]
                else:
                    e[r*M + 0] = e[(r-1)*M + 0] + times[job_r][0]
                    for m in range(1, M):
                        e[r*M + m] = max(e[(r-1)*M + m], e[r*M + m-1]) + times[job_r][m]
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                if r == k-1:
                    for m in range(M):
                        q[r*M + m] = times[job_r][m] + (q[(r+1)*M + m] if r+1 < k else 0)
                else:
                    q[r*M + M-1] = times[job_r][M-1] + q[(r+1)*M + M-1]
                    for m in range(M-2, -1, -1):
                        q[r*M + m] = times[job_r][m] + max(q[(r+1)*M + m], q[r*M + m+1])
    best_seq = seq[:]
    best_mk = makespan(best_seq)
    LB = 0
    for m in range(M):
        min_pre = min((sum(times[i][:m]) for i in range(N)), default=0)
        min_suf = min((sum(times[i][m+1:]) for i in range(N)), default=0)
        machine_sum = sum(times[i][m] for i in range(N))
        LB = max(LB, min_pre + machine_sum + min_suf)
    if best_mk == LB:
        return best_seq
    current_seq = best_seq[:]
    current_mk = best_mk
    T = T_param * LB_param
    max_iters = 60
    for _ in range(max_iters):
        d = 3 if N > 5 else N
        if d < 1:
            d = 1
        indices = random.sample(range(N), d)
        extracted = [current_seq[i] for i in indices]
        remaining = [current_seq[i] for i in range(N) if i not in indices]
        e_rem = [0] * ((N - d) * M)
        q_rem = [0] * ((N - d) * M)
        for idx, job in enumerate(remaining):
            if idx == 0:
                e_rem[0*M + 0] = times[job][0]
                for m in range(1, M):
                    e_rem[0*M + m] = e_rem[0*M + m-1] + times[job][m]
                for m in range(M):
                    q_rem[0*M + m] = times[job][m]
            else:
                e_rem[idx*M + 0] = e_rem[(idx-1)*M + 0] + times[job][0]
                for m in range(1, M):
                    e_rem[idx*M + m] = max(e_rem[(idx-1)*M + m], e_rem[idx*M + m-1]) + times[job][m]
        for idx in range(N-d-1, -1, -1):
            job = remaining[idx]
            if idx == N-d-1:
                for m in range(M):
                    q_rem[idx*M + m] = times[job][m] + (q_rem[(idx+1)*M + m] if idx+1 < N-d else 0)
            else:
                q_rem[idx*M + M-1] = times[job][M-1] + q_rem[(idx+1)*M + M-1]
                for m in range(M-2, -1, -1):
                    q_rem[idx*M + m] = times[job][m] + max(q_rem[(idx+1)*M + m], q_rem[idx*M + m+1])
        random.shuffle(extracted)
        for job in extracted:
            best_pos = 0
            best_mk_ins = float('inf')
            for pos in range(len(remaining)+1):
                mk_ins = makespan_taillard_insert(remaining, job, e_rem, q_rem)
                if mk_ins < best_mk_ins:
                    best_mk_ins = mk_ins
                    best_pos = pos
            remaining.insert(best_pos, job)
            k = len(remaining)
            for r in range(k):
                job_r = remaining[r]
                if r == 0:
                    e_rem[r*M + 0] = times[job_r][0]
                    for m in range(1, M):
                        e_rem[r*M + m] = e_rem[r*M + m-1] + times[job_r][m]
                else:
                    e_rem[r*M + 0] = e_rem[(r-1)*M + 0] + times[job_r][0]
                    for m in range(1, M):
                        e_rem[r*M + m] = max(e_rem[(r-1)*M + m], e_rem[r*M + m-1]) + times[job_r][m]
            for r in range(k-1, -1, -1):
                job_r = remaining[r]
                if r == k-1:
                    for m in range(M):
                        q_rem[r*M + m] = times[job_r][m] + (q_rem[(r+1)*M + m] if r+1 < k else 0)
                else:
                    q_rem[r*M + M-1] = times[job_r][M-1] + q_rem[(r+1)*M + M-1]
                    for m in range(M-2, -1, -1):
                        q_rem[r*M + m] = times[job_r][m] + max(q_rem[(r+1)*M + m], q_rem[r*M + m+1])
        new_seq = remaining
        new_mk = makespan(new_seq)
        if new_mk < current_mk or (current_mk > 0 and random.random() < math.exp(-(new_mk - current_mk) / T)):
            current_seq = new_seq
            current_mk = new_mk
            if new_mk < best_mk:
                best_seq = new_seq[:]
                best_mk = new_mk
                if best_mk == LB:
                    break
    return best_seq

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job data for faster access
    p = [list(row) for row in times]
    total_p = [sum(job) for job in p]
    slope = [sum((2 * j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += p[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard acceleration: forward completion matrix for a partial schedule
    def forward_matrix(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job][m]
        return e

    # Taillard acceleration: backward tail matrix for a partial schedule
    def backward_matrix(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k + 1)]
        for r in range(k - 1, -1, -1):
            job = perm[r]
            for m in range(M - 1, -1, -1):
                if m == M - 1:
                    q[r][m] = q[r + 1][m] + p[job][m]
                else:
                    q[r][m] = max(q[r + 1][m], q[r][m + 1]) + p[job][m]
        return q

    # Evaluate makespan for inserting job x at position i in partial schedule perm (length k)
    def insertion_makespan(perm, x, i):
        k = len(perm)
        e = forward_matrix(perm)
        q = backward_matrix(perm)
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev_e = e[i-1][0] if i > 0 else 0
                f[m] = prev_e + p[x][m]
            else:
                prev_e = e[i-1][m] if i > 0 else 0
                f[m] = max(f[m-1], prev_e) + p[x][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration and idle-time tie-breaking
    def construct_neh(order):
        if not order:
            return []
        perm = [order[0]]
        for idx in range(1, len(order)):
            job = order[idx]
            best_pos = 0
            best_makespan = float('inf')
            best_idle = float('inf')
            for pos in range(len(perm) + 1):
                ms = insertion_makespan(perm, job, pos)
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
                    # Compute idle time on last machine for tie-breaking
                    if len(perm) == 0:
                        idle = 0
                    else:
                        # Simulate to get completion times on last machine
                        t = [0] * M
                        for j in perm[:pos]:
                            for m in range(M):
                                if m == 0:
                                    t[m] += p[j][m]
                                else:
                                    t[m] = max(t[m], t[m-1]) + p[j][m]
                        # Insert job
                        for m in range(M):
                            if m == 0:
                                t[m] = t[m] + p[job][m]
                            else:
                                t[m] = max(t[m], t[m-1]) + p[job][m]
                        for j in perm[pos:]:
                            for m in range(M):
                                if m == 0:
                                    t[m] += p[j][m]
                                else:
                                    t[m] = max(t[m], t[m-1]) + p[j][m]
                        idle = t[-1] - sum(p[job][m] for m in range(M))  # idle before job on last machine
                elif ms == best_makespan:
                    # Tie-break: minimize idle time on last machine before the job
                    if len(perm) == 0:
                        idle = 0
                    else:
                        t = [0] * M
                        for j in perm[:pos]:
                            for m in range(M):
                                if m == 0:
                                    t[m] += p[j][m]
                                else:
                                    t[m] = max(t[m], t[m-1]) + p[j][m]
                        for m in range(M):
                            if m == 0:
                                t[m] = t[m] + p[job][m]
                            else:
                                t[m] = max(t[m], t[m-1]) + p[job][m]
                        for j in perm[pos:]:
                            for m in range(M):
                                if m == 0:
                                    t[m] += p[j][m]
                                else:
                                    t[m] = max(t[m], t[m-1]) + p[j][m]
                        idle = t[-1] - sum(p[job][m] for m in range(M))
                    if idle < best_idle:
                        best_idle = idle
                        best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # Try multiple orderings: total processing time and slope index
    order_tp = sorted(range(N), key=lambda i: (-total_p[i], i))
    order_slope = sorted(range(N), key=lambda i: (-slope[i], i))
    best_perm = None
    best_ms = float('inf')
    for order in [order_tp, order_slope]:
        perm = construct_neh(order)
        ms = makespan(perm)
        if ms < best_ms:
            best_ms = ms
            best_perm = perm

    # Iterated Greedy refinement
    def destroy(perm, d):
        indices = random.sample(range(len(perm)), d)
        removed = [perm[i] for i in indices]
        remaining = [perm[i] for i in range(len(perm)) if i not in indices]
        return remaining, removed

    def reconstruct(remaining, removed):
        perm = remaining[:]
        for job in removed:
            best_pos = 0
            best_ms = float('inf')
            for pos in range(len(perm) + 1):
                ms = insertion_makespan(perm, job, pos)
                if ms < best_ms:
                    best_ms = ms
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # IG parameters
    T_param = 0.5
    total_processing = sum(total_p)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    current_perm = best_perm[:]
    current_ms = best_ms
    best_perm_ig = current_perm[:]
    best_ms_ig = current_ms
    max_iter = 60  # Calibrated to stay within 50ms for N<=120, M<=20

    for _ in range(max_iter):
        # Destruction
        d = 3 if N > 20 else 2
        remaining, removed = destroy(current_perm, d)
        # Reconstruction
        new_perm = reconstruct(remaining, removed)
        new_ms = makespan(new_perm)
        # Acceptance
        if new_ms < current_ms or random.random() < math.exp(-(new_ms - current_ms) / T):
            current_perm = new_perm
            current_ms = new_ms
            if new_ms < best_ms_ig:
                best_perm_ig = new_perm[:]
                best_ms_ig = new_ms
        # Early exit if optimal (lower bound match not implemented due to complexity)
        # but we can stop if we hit a very low makespan (heuristic)
        if best_ms_ig == 0:
            break

    return best_perm_ig

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Preprocess job data for fast access
    p = [row[:] for row in times]  # copy to avoid aliasing issues
    total_p = [sum(row) for row in p]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[M-1]

    # Taillard's accelerated insertion evaluation
    def evaluate_insertion(perm, job, e, q):
        k = len(perm)
        best_pos = 0
        best_cmax = float('inf')
        # For each insertion position i from 0 to k
        for i in range(k+1):
            # forward pass for job at position i
            if i == 0:
                f0 = p[job][0]
                fm = [0] * M
                fm[0] = f0
                for m in range(1, M):
                    fm[m] = max(fm[m-1], e[i-1][m] if i-1 >= 0 else 0) + p[job][m]
            else:
                fm = [0] * M
                fm[0] = e[i-1][0] + p[job][0]
                for m in range(1, M):
                    fm[m] = max(fm[m-1], e[i-1][m]) + p[job][m]
            # makespan with job inserted at i
            cmax = 0
            for m in range(M):
                val = fm[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos, best_cmax

    # NEH construction with Taillard acceleration
    def neh_construct(order):
        if not order:
            return []
        # start with first job
        perm = [order[0]]
        if len(order) == 1:
            return perm
        # evaluate first two jobs in both orders
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2
        # prepare e and q for current perm length = 2
        k = len(perm)
        e = [[0]*M for _ in range(k)]
        # forward matrix e
        for r in range(k):
            job_r = perm[r]
            if r == 0:
                e[0][0] = p[job_r][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[job_r][m]
            else:
                e[r][0] = e[r-1][0] + p[job_r][0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]
        # backward matrix q, size (k+1) x M
        q = [[0]*M for _ in range(k+1)]
        # q[k][:] already 0
        for r in range(k-1, -1, -1):
            job_r = perm[r]
            q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
        # insert remaining jobs
        for idx in range(2, len(order)):
            job = order[idx]
            pos, _ = evaluate_insertion(perm, job, e, q)
            perm.insert(pos, job)
            k = len(perm)
            # recompute e and q for new perm
            e = [[0]*M for _ in range(k)]
            for r in range(k):
                job_r = perm[r]
                if r == 0:
                    e[0][0] = p[job_r][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + p[job_r][m]
                else:
                    e[r][0] = e[r-1][0] + p[job_r][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]
            q = [[0]*M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = perm[r]
                q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
        return perm

    # Multi-start NEH with noise
    best_perm = None
    best_cmax = float('inf')
    for _ in range(3):
        # noisy total processing times
        noisy = [total_p[i] * random.uniform(0.9, 1.1) for i in range(N)]
        order = sorted(range(N), key=lambda i: noisy[i], reverse=True)
        perm = neh_construct(order)
        cmax = makespan(perm)
        if cmax < best_cmax:
            best_cmax = cmax
            best_perm = perm

    # Iterated Greedy refinement
    def ig_refine(init_perm, init_cmax, max_iter=60):
        perm = init_perm[:]
        current_cmax = init_cmax
        best_perm = perm[:]
        best_cmax = current_cmax
        total = sum(total_p)
        T = 0.5 * total / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2
        for _ in range(max_iter):
            # destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [perm[i] for i in indices]
            # build destruction sequence keeping original order
            perm_D = [perm[i] for i in range(N) if i not in set(indices)]
            # reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                # build e and q for current perm_D
                k = len(perm_D)
                if k == 0:
                    e = []
                    q = [[0]*M]
                else:
                    e = [[0]*M for _ in range(k)]
                    for r in range(k):
                        job_r = perm_D[r]
                        if r == 0:
                            e[0][0] = p[job_r][0]
                            for m in range(1, M):
                                e[0][m] = e[0][m-1] + p[job_r][m]
                        else:
                            e[r][0] = e[r-1][0] + p[job_r][0]
                            for m in range(1, M):
                                e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]
                    q = [[0]*M for _ in range(k+1)]
                    for r in range(k-1, -1, -1):
                        job_r = perm_D[r]
                        q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
                        for m in range(M-2, -1, -1):
                            q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
                # find best insertion position for job
                best_pos = 0
                best_cmax_local = float('inf')
                for i in range(k+1):
                    if i == 0:
                        fm = [0]*M
                        fm[0] = p[job][0]
                        for m in range(1, M):
                            fm[m] = max(fm[m-1], 0) + p[job][m]
                    else:
                        fm = [0]*M
                        fm[0] = e[i-1][0] + p[job][0]
                        for m in range(1, M):
                            fm[m] = max(fm[m-1], e[i-1][m]) + p[job][m]
                    cmax_local = 0
                    for m in range(M):
                        val = fm[m] + q[i][m]
                        if val > cmax_local:
                            cmax_local = val
                    if cmax_local < best_cmax_local:
                        best_cmax_local = cmax_local
                        best_pos = i
                perm_D.insert(best_pos, job)
            # new candidate solution
            perm_new = perm_D
            cmax_new = makespan(perm_new)
            # acceptance criterion
            if cmax_new < current_cmax or random.random() < math.exp(-(cmax_new - current_cmax) / T):
                perm = perm_new
                current_cmax = cmax_new
                if current_cmax < best_cmax:
                    best_cmax = current_cmax
                    best_perm = perm[:]
        return best_perm, best_cmax

    refined_perm, refined_cmax = ig_refine(best_perm, best_cmax)
    if refined_cmax < best_cmax:
        return refined_perm
    else:
        return best_perm

