def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for NEH priority
    total_times = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Makespan evaluation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Taillard acceleration: forward matrix e for partial schedule
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job][m]
        return e

    # Taillard acceleration: backward tail matrix q for partial schedule
    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = perm[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return q

    # Compute makespan after inserting job x at position i using Taillard's scheme
    def insertion_makespan(perm, x, i, e_prev, q_next):
        # f: forward vector for job x up to insertion point
        f = [0] * M
        if i == 0:
            prev_e = [0] * M
        else:
            prev_e = e_prev[i-1]
        for m in range(M):
            if m == 0:
                f[m] = prev_e[m] + times[x][m]
            else:
                f[m] = max(f[m], f[m-1]) + times[x][m]
        # q_next is q[i] from backward matrix of current perm
        max_val = 0
        for m in range(M):
            val = f[m] + q_next[m]
            if val > max_val:
                max_val = val
        return max_val

    # NEH construction with Taillard acceleration
    def construct_initial():
        if N < 2:
            return order[:N]
        # Start with first two jobs
        best_perm = None
        best_ms = float('inf')
        for perm in ([order[0], order[1]], [order[1], order[0]]):
            ms = makespan(perm)
            if ms < best_ms:
                best_ms = ms
                best_perm = perm[:]
        current_perm = best_perm[:]
        current_ms = best_ms
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            e = compute_forward(current_perm)
            q = compute_backward(current_perm)
            best_pos = 0
            best_ms = float('inf')
            for i in range(k+1):  # positions 0..k
                ms = insertion_makespan(current_perm, job, i, e, q[i])
                if ms < best_ms:
                    best_ms = ms
                    best_pos = i
            current_perm.insert(best_pos, job)
            current_ms = best_ms
        return current_perm

    # Variable Neighborhood Search
    def vns(initial_perm, max_time_ms=40):
        start_time = random.random()  # Placeholder for time check; we'll use iteration budget
        current_perm = initial_perm[:]
        current_ms = makespan(current_perm)
        best_perm = current_perm[:]
        best_ms = current_ms
        # Neighborhoods: 0 = relocation (insert), 1 = swap
        neighborhood = 0
        max_no_improve = 10
        no_improve = 0
        max_iter = 200  # Safe iteration limit for <50ms
        for _ in range(max_iter):
            improved = False
            if neighborhood == 0:  # Relocation neighborhood
                # Try moving each job to every other position
                for i in range(N):
                    job = current_perm[i]
                    # Remove job at i
                    temp = current_perm[:i] + current_perm[i+1:]
                    for j in range(N):  # Insert at position j in temp (0..N-1)
                        if j == i:
                            continue
                        candidate = temp[:j] + [job] + temp[j:]
                        ms = makespan(candidate)
                        if ms < current_ms:
                            current_perm = candidate
                            current_ms = ms
                            improved = True
                            if ms < best_ms:
                                best_perm = candidate[:]
                                best_ms = ms
                                no_improve = 0
                            break  # First improvement
                    if improved:
                        break
            else:  # Swap neighborhood
                # Try swapping each pair of jobs
                for i in range(N):
                    for j in range(i+1, N):
                        candidate = current_perm[:]
                        candidate[i], candidate[j] = candidate[j], candidate[i]
                        ms = makespan(candidate)
                        if ms < current_ms:
                            current_perm = candidate
                            current_ms = ms
                            improved = True
                            if ms < best_ms:
                                best_perm = candidate[:]
                                best_ms = ms
                                no_improve = 0
                            break
                    if improved:
                        break
            if not improved:
                no_improve += 1
                if no_improve >= max_no_improve:
                    # Switch neighborhood
                    neighborhood = 1 - neighborhood
                    no_improve = 0
            else:
                no_improve = 0
        return best_perm

    initial = construct_initial()
    return vns(initial)

