def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    proc = [row[:] for row in times]
    total_proc = [sum(row) for row in proc]
    max_proc = [max(row) for row in proc]
    min_proc = [min(row) for row in proc]

    # Compute lower bound (Taillard's machine bottleneck)
    LB = 0
    for m in range(M):
        sum_m = sum(proc[i][m] for i in range(N))
        min_before = min((sum(proc[i][l] for l in range(m)) for i in range(N)), default=0)
        min_after = min((sum(proc[i][l] for l in range(m+1, M)) for i in range(N)), default=0)
        LB = max(LB, min_before + sum_m + min_after)

    # Makespan evaluation with caching for partial schedules
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            pj = proc[job]
            t[0] += pj[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pj[m]
        return t[-1]

    # Taillard's accelerated insertion for a given job into a partial schedule
    def insert_job_taillard(partial, job, e=None, q=None):
        k = len(partial)
        if k == 0:
            return [job], proc[job][:]
        if e is None or q is None:
            # Build e and q from scratch if not provided
            e = [[0]*M for _ in range(k)]
            for r in range(k):
                job_r = proc[partial[r]]
                if r == 0:
                    e[0][0] = job_r[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_r[m]
                else:
                    e[r][0] = e[r-1][0] + job_r[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
            q = [[0]*M for _ in range(k+1)]
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = proc[partial[r]]
                q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
        else:
            # Use provided e and q
            pass

        best_pos = 0
        best_mk = float('inf')
        pj = proc[job]
        for i in range(k+1):
            # Compute forward vector f for inserting job at position i
            if i == 0:
                f = [0]*M
                f[0] = pj[0]
                for m in range(1, M):
                    f[m] = f[m-1] + pj[m]
            else:
                f = [0]*M
                e_im1 = e[i-1]
                f[0] = e_im1[0] + pj[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e_im1[m]) + pj[m]
            # Compute makespan candidate: max_m (f[m] + q[i][m])
            mk = 0
            q_i = q[i]
            for m in range(M):
                val = f[m] + q_i[m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        new_seq = partial[:best_pos] + [job] + partial[best_pos:]
        return new_seq, best_mk

    # Construct initial solution using NEH with Taillard acceleration
    order = sorted(range(N), key=lambda i: total_proc[i], reverse=True)
    seq = [order[0]]
    e = [[proc[order[0]][0]] + [0]*(M-1)]
    for m in range(1, M):
        e[0][m] = e[0][m-1] + proc[order[0]][m]
    q = [[0]*M for _ in range(2)]
    for m in range(M):
        q[1][m] = 0
    q[0][M-1] = proc[order[0]][M-1]
    for m in range(M-2, -1, -1):
        q[0][m] = q[0][m+1] + proc[order[0]][m]

    for idx in range(1, N):
        job = order[idx]
        seq, mk = insert_job_taillard(seq, job, e, q)
        k = len(seq)
        # Update e and q for the new sequence
        e_new = [[0]*M for _ in range(k)]
        for r in range(k):
            job_r = proc[seq[r]]
            if r == 0:
                e_new[0][0] = job_r[0]
                for m in range(1, M):
                    e_new[0][m] = e_new[0][m-1] + job_r[m]
            else:
                e_new[r][0] = e_new[r-1][0] + job_r[0]
                for m in range(1, M):
                    e_new[r][m] = max(e_new[r-1][m], e_new[r][m-1]) + job_r[m]
        e = e_new
        q_new = [[0]*M for _ in range(k+1)]
        for m in range(M):
            q_new[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = proc[seq[r]]
            q_new[r][M-1] = q_new[r+1][M-1] + job_r[M-1]
            for m in range(M-2, -1, -1):
                q_new[r][m] = max(q_new[r+1][m], q_new[r][m+1]) + job_r[m]
        q = q_new
        if mk == LB:
            return seq

    # Iterated Greedy refinement
    current_seq = seq[:]
    current_mk = makespan(current_seq)
    best_seq = current_seq[:]
    best_mk = current_mk
    total = sum(total_proc)
    T_param = 0.5
    T = T_param * total / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
    max_iter = 60
    no_improve_limit = 20
    no_improve = 0

    for it in range(max_iter):
        if no_improve >= no_improve_limit:
            break
        # Destruction: remove d jobs randomly
        positions = random.sample(range(N), d)
        positions.sort(reverse=True)
        removed = []
        for p in positions:
            removed.append(current_seq.pop(p))
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            current_seq, _ = insert_job_taillard(current_seq, job)
        # Evaluate new solution
        new_mk = makespan(current_seq)
        # Acceptance criterion
        if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
            current_mk = new_mk
            if new_mk < best_mk:
                best_mk = new_mk
                best_seq = current_seq[:]
                no_improve = 0
            else:
                no_improve += 1
        else:
            # Revert to previous state by reinserting removed jobs in original order? 
            # Instead, we keep the worsened state as per IG standard
            current_mk = new_mk
            no_improve += 1

    return best_seq

