def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(row) for row in times)
    LB = 0
    for m in range(M):
        min_prefix = min(times[i][m] for i in range(N))
        min_suffix = min(times[i][m] for i in range(N))
        sum_m = sum(times[i][m] for i in range(N))
        LB_candidate = min_prefix + sum_m + min_suffix
        if LB_candidate > LB:
            LB = LB_candidate

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_time[m]
        return t[-1]

    def makespan_taillard(perm):
        if not perm:
            return 0
        e_prev = [0] * M
        for job in perm:
            job_time = times[job]
            e_curr = [0] * M
            e_curr[0] = e_prev[0] + job_time[0]
            for m in range(1, M):
                e_curr[m] = max(e_prev[m], e_curr[m-1]) + job_time[m]
            e_prev = e_curr
        return e_prev[-1]

    def makespan_taillard_partial(perm):
        k = len(perm)
        if k == 0:
            return [0] * M
        e = [[0] * M for _ in range(k)]
        job0 = times[perm[0]]
        e[0][0] = job0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0[m]
        for i in range(1, k):
            job_time = times[perm[i]]
            e[i][0] = e[i-1][0] + job_time[0]
            for m in range(1, M):
                e[i][m] = max(e[i-1][m], e[i][m-1]) + job_time[m]
        return e

    def makespan_taillard_tail(perm):
        k = len(perm)
        if k == 0:
            return [0] * M
        q = [[0] * M for _ in range(k+1)]
        for i in range(k-1, -1, -1):
            job_time = times[perm[i]]
            q[i][M-1] = q[i+1][M-1] + job_time[M-1]
            for m in range(M-2, -1, -1):
                q[i][m] = max(q[i+1][m], q[i][m+1]) + job_time[m]
        return q

    def insert_block_taillard(perm, block):
        k = len(perm)
        if k == 0:
            return block[:]
        e = makespan_taillard_partial(perm)
        q = makespan_taillard_tail(perm)
        best_makespan = float('inf')
        best_seq = None
        for pos in range(k+1):
            f = [0] * M
            if pos == 0:
                f[0] = block[0][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], 0) + block[0][m]
            else:
                f[0] = e[pos-1][0] + block[0][0]
                for m in range(1, M):
                    f[m] = max(f[m-1], e[pos-1][m]) + block[0][m]
            g = [0] * M
            g[0] = f[0] + block[1][0]
            for m in range(1, M):
                g[m] = max(g[m-1], f[m]) + block[1][m]
            makespan_candidate = 0
            for m in range(M):
                val = g[m] + q[pos][m]
                if val > makespan_candidate:
                    makespan_candidate = val
            if makespan_candidate < best_makespan:
                best_makespan = makespan_candidate
                best_seq = perm[:pos] + block + perm[pos:]
        return best_seq

    def neh_taillard():
        job_sums = [sum(times[i]) for i in range(N)]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        if N < 2:
            return order[:]
        seq = [order[0], order[1]]
        if makespan_taillard([order[1], order[0]]) < makespan_taillard(seq):
            seq = [order[1], order[0]]
        for idx in range(2, N):
            job = order[idx]
            block = [times[job]]  # dummy, will be replaced
            best_pos = 0
            best_mk = float('inf')
            e = makespan_taillard_partial(seq)
            q = makespan_taillard_tail(seq)
            for pos in range(len(seq)+1):
                f = [0] * M
                if pos == 0:
                    f[0] = times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], 0) + times[job][m]
                else:
                    f[0] = e[pos-1][0] + times[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[pos-1][m]) + times[job][m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
            seq = seq[:best_pos] + [job] + seq[best_pos:]
        return seq

    def ig():
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        current = neh_taillard()
        current_mk = makespan_taillard(current)
        best = current[:]
        best_mk = current_mk
        if current_mk == LB:
            return best
        max_iters = 60
        for _ in range(max_iters):
            if current_mk == LB:
                break
            d = 3 if N >= 3 else N
            indices = random.sample(range(N), d)
            extracted = [current[i] for i in indices]
            remaining = [current[i] for i in range(N) if i not in set(indices)]
            random.shuffle(extracted)
            for job in extracted:
                best_pos = 0
                best_mk_ins = float('inf')
                e = makespan_taillard_partial(remaining)
                q = makespan_taillard_tail(remaining)
                for pos in range(len(remaining)+1):
                    f = [0] * M
                    if pos == 0:
                        f[0] = times[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], 0) + times[job][m]
                    else:
                        f[0] = e[pos-1][0] + times[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[pos-1][m]) + times[job][m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[pos][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_ins:
                        best_mk_ins = mk
                        best_pos = pos
                remaining = remaining[:best_pos] + [job] + remaining[best_pos:]
            current = remaining
            current_mk = makespan_taillard(current)
            if current_mk < best_mk:
                best_mk = current_mk
                best = current[:]
            if current_mk < makespan_taillard(best):
                if random.random() < math.exp(-(current_mk - makespan_taillard(best)) / T):
                    best = current[:]
                    best_mk = current_mk
            if current_mk == LB:
                break
        return best

    result = ig()
    if makespan_taillard(result) == LB:
        return result
    return result

