            return 0
        t = [0] * M
        for job in perm:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[M-1]

    # Helper: Taillard acceleration for insertion evaluation
    def taillard_insert_eval(partial, job_idx):
        k = len(partial)
        if k == 0:
            f = [0] * M
            f[0] = times[job_idx][0]
            for m in range(1, M):
                f[m] = f[m-1] + times[job_idx][m]
            return f[M-1]

        # Forward matrix e (size k x M)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            p = times[job]
            if r == 0:
                e[0][0] = p[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[m]
            else:
                e[r][0] = e[r-1][0] + p[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[m]

        # Backward tail matrix q (size (k+1) x M)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            p = times[job]
            q[r][M-1] = q[r+1][M-1] + p[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[m]

        # Evaluate all insertion positions
        best_val = float('inf')
        best_pos = 0
        for i in range(k+1):
            # Compute forward vector f for job_idx at position i
            f = [0] * M
            if i == 0:
                prev_e = [0] * M
            else:
                prev_e = e[i-1]
            f[0] = prev_e[0] + times[job_idx][0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev_e[m]) + times[job_idx][m]
            # Makespan if inserted at i
            val = 0
            for m in range(M):
                val = max(val, f[m] + q[i][m])
            if val < best_val:
                best_val = val
                best_pos = i
        return best_val, best_pos

    # Beam Search with width K=2
    K = 2
    # Initial jobs sorted by total time descending, then slope descending
    jobs_sorted = sorted(range(N), key=lambda i: (-total_times[i], -slope_indices[i]))
    beams = [([jobs_sorted[0]], makespan([jobs_sorted[0]]))] if N > 0 else []

    for idx in range(1, N):
        job = jobs_sorted[idx]
        candidates = []
        for seq, _ in beams:
            for pos in range(len(seq) + 1):
                new_seq = seq[:pos] + [job] + seq[pos:]
                candidates.append((new_seq, makespan(new_seq)))
        # Prune to top K by makespan
        candidates.sort(key=lambda x: x[1])
        beams = candidates[:K]

    # Return best sequence from beam
    return min(beams, key=lambda x: x[1])[0]

