                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + times[job_r][m]

            # Compute backward tail q[0..k][0..M-1]
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                q[r][M-1] = q[r+1][M-1] + times[job_r][M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]

            # Evaluate insertion positions for job
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                if i == 0:
                    f0 = times[job][0]
                    fm = [f0]
                    for m in range(1, M):
                        fm.append(max(fm[m-1], 0) + times[job][m])
                else:
                    f0 = e[i-1][0] + times[job][0]
                    fm = [f0]
                    for m in range(1, M):
                        fm.append(max(fm[m-1], e[i-1][m]) + times[job][m])
                mk = 0
                for m in range(M):
                    val = fm[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            seq.insert(best_pos, job)

        # Evaluate new sequence
        new_mk = makespan_of_seq(seq)
        # Acceptance criterion
        if new_mk < makespan_of_seq(pi):
            pi = seq[:]
            if new_mk < best_mk:
                best_mk = new_mk
                best_seq = seq[:]
        else:
            if new_mk < best_mk:
                # Always accept if better than best
                pi = seq[:]
                best_mk = new_mk
                best_seq = seq[:]
            else:
                # Metropolis
                delta = new_mk - makespan_of_seq(pi)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    pi = seq[:]

    return best_seq

