import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for NEH priority
    total_times = [sum(job) for job in times]
    # Sort jobs by total processing time descending
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]  # forward completion times
    q = [[0] * M for _ in range(N + 1)]  # backward tail times

    def makespan(seq):
        if not seq:
            return 0
        # Compute makespan for a given sequence using DP
        c = [0] * M
        for job in seq:
            p = times[job]
            c[0] += p[0]
            for m in range(1, M):
                c[m] = max(c[m - 1], c[m]) + p[m]
        return c[M - 1]

    def compute_forward_backward(seq):
        k = len(seq)
        # Forward matrix e[0..k-1][0..M-1]
        for r in range(k):
            job = seq[r]
            p = times[job]
            if r == 0:
                e[0][0] = p[0]
                for m in range(1, M):
                    e[0][m] = e[0][m - 1] + p[m]
            else:
                e[r][0] = e[r - 1][0] + p[0]
                for m in range(1, M):
                    e[r][m] = max(e[r - 1][m], e[r][m - 1]) + p[m]
        # Backward matrix q[0..k][0..M-1]
        for m in range(M):
            q[k][m] = 0
        for r in range(k - 1, -1, -1):
            job = seq[r]
            p = times[job]
            q[r][M - 1] = q[r + 1][M - 1] + p[M - 1]
            for m in range(M - 2, -1, -1):
                q[r][m] = max(q[r + 1][m], q[r][m + 1]) + p[m]

    def insert_job_neh(seq, job):
        k = len(seq)
        if k == 0:
            return [job]
        compute_forward_backward(seq)
        best_pos = 0
        best_makespan = float('inf')
        # Evaluate all k+1 insertion positions
        for i in range(k + 1):
            # Compute forward vector f for job at position i
            f = [0] * M
            if i == 0:
                f[0] = job  # dummy, will be overwritten
                f[0] = times[job][0]
                for m in range(1, M):
                    f[m] = f[m - 1] + times[job][m]
            else:
                f[0] = e[i - 1][0] + times[job][0]
                for m in range(1, M):
                    f[m] = max(f[m - 1], e[i - 1][m]) + times[job][m]
            # Compute makespan if job inserted at i: max_m (f[m] + q[i][m])
            makespan_i = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > makespan_i:
                    makespan_i = val
            if makespan_i < best_makespan:
                best_makespan = makespan_i
                best_pos = i
        # Insert job at best_pos
        return seq[:best_pos] + [job] + seq[best_pos:]

    # Construct initial solution using NEH
    pi = []
    for idx in order:
        pi = insert_job_neh(pi, idx)
    pi_star = pi[:]
    c_star = makespan(pi)

    # Iterated Greedy parameters
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0
    d = 3 if N > 20 else 2  # destruction size
    max_iter = 50  # iterations, tuned for <50ms

    current = pi[:]
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            removed = current[:]
        else:
            positions = random.sample(range(N), d)
            positions.sort(reverse=True)
            removed = []
            for pos in positions:
                removed.append(current.pop(pos))
            destroyed = current  # remaining sequence
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            destroyed = insert_job_neh(destroyed, job)
        new_seq = destroyed
        new_makespan = makespan(new_seq)
        # Acceptance criterion
        if new_makespan < makespan(current):
            current = new_seq[:]
            if new_makespan < c_star:
                pi_star = new_seq[:]
                c_star = new_makespan
        else:
            delta = new_makespan - makespan(current)
            if random.random() < math.exp(-delta / T):
                current = new_seq[:]
    return pi_star

