import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)

    # Precompute job data for fast access
    job_data = [list(job) for job in times]
    job_sums = [sum(job) for job in job_data]

    # Makespan calculation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            p = job_data[job]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + p[m]
        return t[-1]

    # Taillard's forward matrix
    def compute_forward(seq):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            p = job_data[seq[r]]
            if r == 0:
                e[0][0] = p[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + p[m]
            else:
                e[r][0] = e[r-1][0] + p[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + p[m]
        return e

    # Taillard's backward matrix
    def compute_backward(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            p = job_data[seq[r]]
            q[r][M-1] = q[r+1][M-1] + p[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + p[m]
        return q

    # Evaluate insertion positions using Taillard's acceleration
    def evaluate_insertion(seq, job, e, q):
        k = len(seq)
        best_pos = 0
        best_mk = float('inf')
        for i in range(k+1):
            # Compute forward vector f for job at position i
            f = [0] * M
            if i == 0:
                f[0] = job[0]
                for m in range(1, M):
                    f[m] = f[m-1] + job[m]
            else:
                prev = e[i-1]
                f[0] = prev[0] + job[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev[m]) + job[m]
            # Compute makespan candidate
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return best_pos

    # NEH construction with Taillard acceleration
    def construct_initial():
        order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
        seq = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(seq):
            seq = [order[1], order[0]]
        for idx in range(2, N):
            job_idx = order[idx]
            p_job = job_data[job_idx]
            e = compute_forward(seq)
            q = compute_backward(seq)
            pos = evaluate_insertion(seq, p_job, e, q)
            seq.insert(pos, job_idx)
        return seq

    # Iterated Greedy
    def iterated_greedy(init_seq, max_iter=60):
        current = init_seq[:]
        best = current[:]
        best_mk = makespan(best)
        d = 3 if N > 5 else max(1, N//2)
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in sorted(indices, reverse=True)]
            for idx in sorted(indices, reverse=True):
                del current[idx]
            # Reconstruction: reinsert using NEH with Taillard
            e = compute_forward(current)
            q = compute_backward(current)
            for job_idx in removed:
                p_job = job_data[job_idx]
                pos = evaluate_insertion(current, p_job, e, q)
                current.insert(pos, job_idx)
                # Update e and q for next insertion
                e = compute_forward(current)
                q = compute_backward(current)
            # Acceptance criterion
            curr_mk = makespan(current)
            if curr_mk < best_mk:
                best_mk = curr_mk
                best = current[:]
            if curr_mk < makespan(init_seq):
                current = current[:]
            else:
                delta = curr_mk - makespan(init_seq)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    current = current[:]
                else:
                    current = init_seq[:]
        return best

    init_seq = construct_initial()
    return iterated_greedy(init_seq)

