            makespan_pi_star = makespan_pi
        if makespan_pi < makespan_seq:
            seq = pi[:]
            makespan_seq = makespan_pi
        else:
            if random.random() < math.exp(-(makespan_pi - makespan_seq) / T):
                seq = pi[:]
                makespan_seq = makespan_pi
    return pi_star

def makespan(times, seq):
    if not seq:
        return 0
    N = len(seq)
    M = len(times[0])
    # t[m] will hold the completion time of the last job on machine m
    t = [0] * M
