    e = [[0] * M for _ in range(N)]  # forward completion matrix
    q = [[0] * M for _ in range(N + 1)]  # backward tail matrix (q[N] is zero row)

    # NEH construction with Taillard acceleration for remaining jobs
    for k in range(start_k, N):
