            for r in range(k-1, -1, -1):
                job_r = pi[r]
                p_r = times[job_r]
                q[r][M-1] = q[r+1][M-1] + p_r[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p_r[m]

            # Find best insertion position for job_idx in [0, k]
            best_pos = 0
            best_cmax = float('inf')
            for i in range(k+1):
                # Compute forward vector f for inserting job_idx at position i
                f = [0] * M
                if i == 0:
                    f[0] = p_job[0]
                    for m in range(1, M):
                        f[m] = f[m-1] + p_job[m]
                else:
                    job_prev = pi[i-1]
                    p_prev = times[job_prev]
                    f[0] = e[i-1][0] + p_job[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + p_job[m]

                # Compute makespan if job_idx inserted at position i
                cmax = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax:
                        cmax = val
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = i

            pi.insert(best_pos, job_idx)

        # Evaluate makespan of new pi
        makespan_new = makespan_taillard(times, pi, e, q)

        # Acceptance criterion
        if makespan_new < makespan_taillard(times, pi_star, e, q):
            pi_star = pi[:]
            makespan_star = makespan_new
        if makespan_new < makespan_taillard(times, pi, e, q):
            pi = pi[:]  # accept
        else:
            delta = makespan_new - makespan_taillard(times, pi, e, q)
            if delta < 0 or random.random() < math.exp(-delta / T):
                pi = pi[:]  # accept
            # else: reject, pi remains unchanged

    return pi_star

def makespan_two_machines(times, perm):
    """Makespan for two-machine flow shop (used in NEH initialization)."""
    if not perm:
        return 0
    M = len(times[0])
    if M < 2:
        return sum(times[job][0] for job in perm)
    # Machine 0
    t0 = 0
    for job in perm:
        t0 += times[job][0]
    # Machine 1
    t1 = 0
    for job in perm:
        t1 = max(t1, t0) + times[job][1]
        t0 -= times[job][0]  # t0 now holds completion time of previous job on machine 0
    return t1

def makespan_taillard(times, perm, e, q):
    """Compute makespan using Taillard's decomposition given forward/backward matrices."""
    N = len(perm)
    M = len(times[0])
    if N == 0:
        return 0
    # Compute forward matrix e[0..N-1]
    for r in range(N):
        job_r = perm[r]
        p_r = times[job_r]
        if r == 0:
            e[0][0] = p_r[0]
            for m in range(1, M):
                e[0][m] = e[0][m-1] + p_r[m]
        else:
            e[r][0] = e[r-1][0] + p_r[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + p_r[m]
    # Compute backward matrix q[r][m] for r in [0, N]
    for r in range(N-1, -1, -1):
        job_r = perm[r]
        p_r = times[job_r]
        q[r][M-1] = q[r+1][M-1] + p_r[M-1]
        for m in range(M-2, -1, -1):
            q[r][m] = max(q[r+1][m], q[r][m+1]) + p_r[m]
    # Makespan is max_m (e[N-1][m] + q[N][m]) but q[N][:] = 0
    makespan = 0
    last = e[N-1]
    for m in range(M):
        if last[m] > makespan:
            makespan = last[m]
    return makespan

