def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Compute Palmer's slope index weighted by inverse machine variance
    P = [sum(times[i]) for i in range(N)]
    var = [0.0] * M
    for j in range(M):
        col = [times[i][j] for i in range(N)]
        mu = sum(col) / N
        var[j] = sum((x - mu) ** 2 for x in col) / N
    # Avoid division by zero: add epsilon and invert
    slope = [0.0] * N
    eps = 1e-9
    for i in range(N):
        s = 0.0
        for j in range(M):
            w = 1.0 / (var[j] + eps)
            s += (2 * j - M + 1) * times[i][j] * w
        slope[i] = s
    order = sorted(range(N), key=lambda i: (-slope[i], -P[i]))

    # Makespan evaluation
    def makespan(seq):
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Taillard acceleration helpers
    def compute_forward(partial):
        k = len(partial)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job][m]
        return e

    def compute_backward(partial):
        k = len(partial)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + times[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
        return q

    def insert_best(partial, job, e, q):
        k = len(partial)
        best_pos, best_mk = 0, float('inf')
        for i in range(k+1):
            # Compute forward vector f for inserting job at position i
            f = [0] * M
            for m in range(M):
                if m == 0:
                    prev = e[i-1][m] if i > 0 else 0
                    f[m] = prev + times[job][m]
                else:
                    f[m] = max(f[m-1], e[i-1][m] if i > 0 else 0) + times[job][m]
            # Compute makespan candidate: max_m (f[m] + q[i][m])
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return best_pos

    # Construct initial solution using accelerated NEH
    pi = [order[0]]
    if N > 1:
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        pi = seq1 if makespan(seq1) <= makespan(seq2) else seq2
    e = compute_forward(pi)
    q = compute_backward(pi)
    for idx in range(2, N):
        job = order[idx]
        pos = insert_best(pi, job, e, q)
        pi.insert(pos, job)
        e = compute_forward(pi)
        q = compute_backward(pi)

    # Iterated Greedy refinement
    random.seed(42)
    total_processing = sum(P)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-9
    d = 3 if N > 5 else max(1, N//2)
    pi_current = pi[:]
    pi_best = pi[:]
    mk_best = makespan(pi_best)
    max_iters = 60
    it = 0
    while it < max_iters:
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [pi_current[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del pi_current[idx]
        # Reconstruction: reinsert each removed job using NEH with Taillard
        for job in removed:
            e = compute_forward(pi_current)
            q = compute_backward(pi_current)
            pos = insert_best(pi_current, job, e, q)
            pi_current.insert(pos, job)
        # Acceptance
        mk_current = makespan(pi_current)
        if mk_current < mk_best:
            pi_best = pi_current[:]
            mk_best = mk_current
        if mk_current < makespan(pi):
            pi = pi_current[:]
        else:
            if random.random() < math.exp(-(mk_current - makespan(pi)) / T):
                pi = pi_current[:]
        it += 1

    return pi_best

