def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    def makespan(perm):
        t = [0] * m
        for job in perm:
            t[0] += times[job][0]
            for k in range(1, m):
                t[k] = max(t[k], t[k-1]) + times[job][k]
        return t[-1]

    def johnson_rule(p1, p2):
        left, right = [], []
        indices = list(range(len(p1)))
        while indices:
            min_val = float('inf')
            min_idx = -1
            for idx in indices:
                if p1[idx] < min_val:
                    min_val = p1[idx]
                    min_idx = idx
                if p2[idx] < min_val:
                    min_val = p2[idx]
                    min_idx = idx
            if p1[min_idx] <= p2[min_idx]:
                left.append(min_idx)
            else:
                right.append(min_idx)
            indices.remove(min_idx)
        return left + right[::-1]

    def cds_variant():
        best_perm = None
        best_makespan = float('inf')
        for l in range(1, m):
            p1 = [0] * n
            p2 = [0] * n
            for i in range(n):
                p1[i] = sum(times[i][:l])
                p2[i] = sum(times[i][m-l:])
            perm = johnson_rule(p1, p2)
            mk = makespan(perm)
            if mk < best_makespan:
                best_makespan = mk
                best_perm = perm
        return best_perm

    return cds_variant()

