        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]

    # Compute lower bound for early termination
    LB = 0
    for m in range(M):
        min_before = min(p[i][m] for i in range(N)) if m > 0 else 0
        min_after = min(p[i][m] for i in range(N)) if m < M-1 else 0
        sum_m = sum(p[i][m] for i in range(N))
        LB_m = min_before + sum_m + min_after
        if LB_m > LB:
            LB = LB_m

    # Makespan calculation with Taillard acceleration for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        e = [0] * M
        for idx in perm:
            job = p[idx]
            e[0] += job[0]
            for m in range(1, M):
                e[m] = max(e[m-1], e[m]) + job[m]
        return e[-1]

    # NEH construction with Taillard acceleration
    def construct_initial():
        # Sort by total processing time descending
        order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N == 0:
            return []
        perm = [order[0]]
        if N == 1:
            return perm
        # Try both orders for first two jobs
        seq1 = [order[0], order[1]]
        seq2 = [order[1], order[0]]
        if makespan(seq1) <= makespan(seq2):
            perm = seq1
        else:
            perm = seq2

        # Insert remaining jobs using Taillard's O(k*M) method
        for k in range(2, N):
            job_idx = order[k]
            job = p[job_idx]
            # Forward matrix e for current perm (length k)
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                idx_r = perm[r]
                job_r = p[idx_r]
                if r == 0:
                    e[0][0] = job_r[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_r[m]
                else:
                    e[r][0] = e[r-1][0] + job_r[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
            # Backward matrix q for current perm (length k)
            q = [[0] * M for _ in range(k+1)]
            # q[k][m] = 0 already
            for r in range(k-1, -1, -1):
                idx_r = perm[r]
                job_r = p[idx_r]
                q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
            # Evaluate all k+1 insertion positions
            best_pos = 0
            best_makespan = float('inf')
            for i in range(k+1):
                # Compute forward vector f for inserting job at position i
                f = [0] * M
                if i == 0:
                    prev_e = [0] * M
                else:
                    prev_e = e[i-1]
                f[0] = prev_e[0] + job[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + job[m]
                # Makespan if inserted at i: max_m (f[m] + q[i][m])
                curr_max = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > curr_max:
                        curr_max = val
                if curr_max < best_makespan:
                    best_makespan = curr_max
                    best_pos = i
            perm.insert(best_pos, job_idx)
        return perm

    # Iterated Greedy with destruction size 3
    def iterated_greedy(initial_perm, max_iter=60):
        current = initial_perm[:]
        best = current[:]
        best_makespan = makespan(best)
        total_processing = sum(total_p)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

        for _ in range(max_iter):
            # Destruction: remove d=3 random jobs
            if N <= 3:
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(N), 3)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(N) if i not in indices_set]

            # Reconstruction: reinsert destroyed jobs one by one using NEH insertion (Taillard accelerated)
            for job_idx in destroyed:
                job = p[job_idx]
                k = len(remaining)
                if k == 0:
                    remaining = [job_idx]
                    continue
                # Build forward matrix e for current remaining (length k)
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    idx_r = remaining[r]
                    job_r = p[idx_r]
                    if r == 0:
                        e[0][0] = job_r[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + job_r[m]
                    else:
                        e[r][0] = e[r-1][0] + job_r[0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
                # Build backward matrix q for current remaining (length k)
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    idx_r = remaining[r]
                    job_r = p[idx_r]
                    q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
                # Evaluate k+1 insertion positions
                best_pos = 0
                best_mk = float('inf')
                for i in range(k+1):
                    if i == 0:
                        prev_e = [0] * M
                    else:
                        prev_e = e[i-1]
                    f = [0] * M
                    f[0] = prev_e[0] + job[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev_e[m]) + job[m]
                    curr_max = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > curr_max:
                            curr_max = val
                    if curr_max < best_mk:
                        best_mk = curr_max
                        best_pos = i
                remaining.insert(best_pos, job_idx)

            # New candidate solution
            candidate = remaining
            candidate_makespan = makespan(candidate)

            # Acceptance criterion
            if candidate_makespan < makespan(current):
                current = candidate
                if candidate_makespan < best_makespan:
                    best = candidate[:]
                    best_makespan = candidate_makespan
            else:
                if makespan(current) > 0:
                    prob = math.exp(-(candidate_makespan - makespan(current)) / T)
                    if random.random() < prob:
                        current = candidate

        return best

    # Build initial solution
    initial_perm = construct_initial()
    if makespan(initial_perm) == LB:
        return initial_perm

    # Apply iterated greedy refinement
    refined_perm = iterated_greedy(initial_perm, max_iter=50)
    if makespan(refined_perm) == LB:
        return refined_perm

    return refined_perm

