def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    total_processing = 0
    for i in range(n):
        for j in range(m):
            total_processing += times[i][j]

    # Preprocess job data for fast access
    p = [row[:] for row in times]
    P = [sum(row) for row in p]
    S = [sum((2 * j - m + 1) * p[i][j] for j in range(m)) for i in range(n)]

    # Order by total processing time descending (NEH), with tie-breaking by slope
    order = sorted(range(n), key=lambda i: (-P[i], -S[i]))

    # Preallocate matrices for Taillard acceleration
    e = [[0] * m for _ in range(n)]
    q = [[0] * m for _ in range(n + 1)]
    f = [0] * m

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * m
        for idx in seq:
            job = p[idx]
            t[0] += job[0]
            for j in range(1, m):
                t[j] = max(t[j-1], t[j]) + job[j]
        return t[-1]

    def compute_forward(partial):
        k = len(partial)
        if k == 0:
            for j in range(m):
                e[0][j] = 0  # dummy, will be overridden
            return
        for j in range(m):
            e[0][j] = p[partial[0]][j]
        for i in range(1, k):
            job = p[partial[i]]
            e[i][0] = e[i-1][0] + job[0]
            for j in range(1, m):
                e[i][j] = max(e[i-1][j], e[i][j-1]) + job[j]

    def compute_backward(partial):
        k = len(partial)
        for j in range(m):
            q[k][j] = 0
        for i in range(k-1, -1, -1):
            job = p[partial[i]]
            q[i][m-1] = q[i+1][m-1] + job[m-1]
            for j in range(m-2, -1, -1):
                q[i][j] = max(q[i+1][j], q[i][j+1]) + job[j]

    def evaluate_insertion(partial, job_idx, pos):
        k = len(partial)
        if pos == 0:
            prev_e = [0] * m
        else:
            prev_e = e[pos-1]
        job = p[job_idx]
        f[0] = prev_e[0] + job[0]
        for j in range(1, m):
            f[j] = max(f[j-1], prev_e[j]) + job[j]
        makespan_val = 0
        for j in range(m):
            val = f[j] + q[pos][j]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def insert_job(partial, job_idx):
        k = len(partial)
        if k == 0:
            return [job_idx]
        compute_forward(partial)
        compute_backward(partial)
        best_pos = 0
        best_makespan = evaluate_insertion(partial, job_idx, 0)
        for pos in range(1, k+1):
            makespan_val = evaluate_insertion(partial, job_idx, pos)
            if makespan_val < best_makespan:
                best_makespan = makespan_val
                best_pos = pos
        return partial[:best_pos] + [job_idx] + partial[best_pos:]

    def construct_initial():
        if n < 2:
            return order[:n]
        seq = [order[0], order[1]]
        seq_rev = [order[1], order[0]]
        if makespan(seq_rev) < makespan(seq):
            seq = seq_rev
        for idx in range(2, n):
            job = order[idx]
            seq = insert_job(seq, job)
        return seq

    def destroy(sequence, d):
        indices = random.sample(range(len(sequence)), d)
        indices.sort(reverse=True)
        removed = []
        for idx in indices:
            removed.append(sequence.pop(idx))
        return sequence, removed

    def reconstruct(partial, removed):
        for job in removed:
            partial = insert_job(partial, job)
        return partial

    # Iterated Greedy
    current = construct_initial()
    best = current[:]
    best_makespan = makespan(best)
    T_param = 0.5
    T = T_param * total_processing / (10 * n * m) if n * m > 0 else 1e-6
    max_iter = 60
    for _ in range(max_iter):
        if best_makespan == 0:
            break
        destroyed, removed = destroy(current[:], 3)
        current = reconstruct(destroyed, removed)
        current_makespan = makespan(current)
        if current_makespan < best_makespan:
            best = current[:]
            best_makespan = current_makespan
        if current_makespan < makespan(current):
            current = current[:]
        else:
            if random.random() < math.exp(-(current_makespan - makespan(current)) / T):
                current = current[:]
    return best

