def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times and slope indices for priority orders
    total_times = [sum(job) for job in times]
    slope_index = [sum((2 * j - M + 1) * times[i][j] for j in range(M)) for i in range(N)]

    # Helper: makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Helper: compute forward completion matrix for a prefix
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = times[perm[0]][m] if m == 0 else (e[0][m-1] + times[perm[0]][m])
        for i in range(1, k):
            e[i][0] = e[i-1][0] + times[perm[i]][0]
            for m in range(1, M):
                e[i][m] = max(e[i-1][m], e[i][m-1]) + times[perm[i]][m]
        return e

    # Helper: compute backward tail matrix for a prefix
    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for i in range(k-1, -1, -1):
            job = perm[i]
            q[i][M-1] = q[i+1][M-1] + times[job][M-1]
            for m in range(M-2, -1, -1):
                q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job][m]
        return q

    # Helper: evaluate makespan of inserting job x at position i in current prefix perm (length k)
    def evaluate_insertion(perm, x, i):
        k = len(perm)
        e = compute_forward(perm)
        q = compute_backward(perm)
        # f[m]: completion of job x on machine m after inserting at position i
        f = [0] * M
        if i == 0:
            prev_e = [0] * M
        else:
            prev_e = e[i-1]
        f[0] = prev_e[0] + times[x][0]
        for m in range(1, M):
            f[m] = max(f[m-1], prev_e[m]) + times[x][m]
        # makespan = max_m (f[m] + q[i][m])
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Beam Search with width K=2
    K = 2
    # Initial jobs sorted by total time descending, then slope index descending for tie-breaking
    order = sorted(range(N), key=lambda i: (-total_times[i], -slope_index[i]))
    beams = [([order[0]], makespan([order[0]]))]  # (sequence, makespan)

    for idx in range(1, N):
        job = order[idx]
        new_beams = []
        for seq, _ in beams:
            for pos in range(len(seq) + 1):
                new_seq = seq[:pos] + [job] + seq[pos:]
                new_makespan = makespan(new_seq)
                new_beams.append((new_seq, new_makespan))
        # Prune to top K by makespan (ascending)
        new_beams.sort(key=lambda x: x[1])
        beams = new_beams[:K]

    # Return the best sequence from the beam
    best_seq = min(beams, key=lambda x: x[1])[0]
    return best_seq

