def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)

    # Precompute job data for fast access
    job_data = [list(job) for job in times]
    total_time = [sum(job) for job in job_data]

    # Makespan calculation for a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job_idx in perm:
            job = job_data[job_idx]
            t[0] += job[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job[m]
        return t[-1]

    # Taillard's accelerated makespan for inserting job x at position i in partial schedule of length k
    def insertion_makespan(partial, k, x, e, q):
        if k == 0:
            f = [job_data[x][m] for m in range(M)]
            return max(f[m] + q[0][m] for m in range(M))
        f = [0] * M
        jobx = job_data[x]
        # machine 0
        f[0] = (e[i-1][0] if i-1 >= 0 else 0) + jobx[0]
        for m in range(1, M):
            f[m] = max(f[m-1], e[i-1][m] if i-1 >= 0 else 0) + jobx[m]
        best = float('inf')
        for m in range(M):
            val = f[m] + q[i][m]
            if val < best:
                best = val
        return best

    # NEH construction with Taillard acceleration
    def construct_neh():
        order = sorted(range(N), key=lambda i: total_time[i], reverse=True)
        if N < 2:
            return order[:]
        # Initial two jobs
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        if makespan(seq0) <= makespan(seq1):
            perm = seq0
        else:
            perm = seq1
        # Iterative insertion
        for k in range(2, N):
            job = order[k]
            # Build forward matrix e for current perm (length k)
            e = [[0]*M for _ in range(k)]
            for r in range(k):
                job_r = job_data[perm[r]]
                if r == 0:
                    e[0][0] = job_r[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + job_r[m]
                else:
                    e[r][0] = e[r-1][0] + job_r[0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
            # Build backward matrix q for current perm (length k)
            q = [[0]*M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = job_data[perm[r]]
                q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                for m in range(M-2, -1, -1):
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
            # Try all insertion positions
            best_pos = 0
            best_makespan = float('inf')
            for i in range(k+1):
                # Compute makespan if job inserted at position i
                f = [0]*M
                jobx = job_data[job]
                if i == 0:
                    f[0] = jobx[0]
                    for m in range(1, M):
                        f[m] = f[m-1] + jobx[m]
                else:
                    f[0] = e[i-1][0] + jobx[0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[i-1][m]) + jobx[m]
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_makespan:
                    best_makespan = mk
                    best_pos = i
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy
    def iterated_greedy(initial_perm, max_iter=50):
        current = initial_perm[:]
        best = current[:]
        best_mk = makespan(best)
        d = 3 if N >= 3 else N
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build remaining sequence
            remaining = [current[i] for i in range(N) if i not in indices]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                # Build forward matrix e for current remaining
                k = len(remaining)
                if k == 0:
                    e = []
                else:
                    e = [[0]*M for _ in range(k)]
                    for r in range(k):
                        job_r = job_data[remaining[r]]
                        if r == 0:
                            e[0][0] = job_r[0]
                            for m in range(1, M):
                                e[0][m] = e[0][m-1] + job_r[m]
                        else:
                            e[r][0] = e[r-1][0] + job_r[0]
                            for m in range(1, M):
                                e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
                # Build backward matrix q for current remaining
                q = [[0]*M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = job_data[remaining[r]]
                    q[r][M-1] = q[r+1][M-1] + job_r[M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
                # Try all positions for job
                best_pos = 0
                best_mk_ins = float('inf')
                jobx = job_data[job]
                for i in range(k+1):
                    f = [0]*M
                    if i == 0:
                        f[0] = jobx[0]
                        for m in range(1, M):
                            f[m] = f[m-1] + jobx[m]
                    else:
                        f[0] = e[i-1][0] + jobx[0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + jobx[m]
                    mk_ins = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk_ins:
                            mk_ins = val
                    if mk_ins < best_mk_ins:
                        best_mk_ins = mk_ins
                        best_pos = i
                remaining.insert(best_pos, job)
            # Acceptance criterion
            new_mk = makespan(remaining)
            if new_mk < makespan(current):
                current = remaining[:]
                if new_mk < best_mk:
                    best = remaining[:]
                    best_mk = new_mk
            elif new_mk < best_mk:
                # Metropolis acceptance
                if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                    current = remaining[:]
        return best

    # Run algorithm
    initial = construct_neh()
    # Adjust iterations based on problem size to stay within time limit
    max_iter = 40 if N > 60 else 60
    improved = iterated_greedy(initial, max_iter)
    return improved

