def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * m
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for k in range(1, m):
                t[k] = max(t[k], t[k-1]) + job_t[k]
        return t[-1]

    def taillard_forward(partial):
        k = len(partial)
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job_t = times[partial[r]]
            if r == 0:
                e[0][0] = job_t[0]
                for c in range(1, m):
                    e[0][c] = e[0][c-1] + job_t[c]
            else:
                e[r][0] = e[r-1][0] + job_t[0]
                for c in range(1, m):
                    e[r][c] = max(e[r-1][c], e[r][c-1]) + job_t[c]
        return e

    def taillard_backward(partial):
        k = len(partial)
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_t = times[partial[r]]
            if r == k-1:
                q[r][m-1] = job_t[m-1]
                for c in range(m-2, -1, -1):
                    q[r][c] = q[r][c+1] + job_t[c]
            else:
                q[r][m-1] = q[r+1][m-1] + job_t[m-1]
                for c in range(m-2, -1, -1):
                    q[r][c] = max(q[r+1][c], q[r][c+1]) + job_t[c]
        return q

    def insertion_cost(partial, job, pos, e_prev, q_next):
        f = [0] * m
        job_t = times[job]
        if pos == 0:
            prev = [0] * m
        else:
            prev = e_prev[pos-1]
        f[0] = prev[0] + job_t[0]
        for c in range(1, m):
            f[c] = max(f[c-1], prev[c]) + job_t[c]
        best = 0
        for c in range(m):
            val = f[c] + q_next[c]
            if val > best:
                best = val
        return best

    def neh_taillard(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            seq1 = [order[0], order[1]]
            seq2 = [order[1], order[0]]
            seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, len(order)):
            job = order[idx]
            e = taillard_forward(seq)
            q = taillard_backward(seq)
            best_cost = float('inf')
            best_pos = 0
            for pos in range(len(seq)+1):
                cost = insertion_cost(seq, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    total_p = [sum(job) for job in times]
    order_ne = sorted(range(n), key=lambda i: total_p[i], reverse=True)
    pi = neh_taillard(order_ne)
    pi_best = pi[:]
    best_makespan = makespan(pi)

    T_param = 0.5
    T = T_param * total_processing / (10 * n * m)
    d = 3 if n > 20 else 2
    max_iter = 60

    for _ in range(max_iter):
        if len(pi) <= d:
            pi_new = pi[:]
            random.shuffle(pi_new)
        else:
            positions = random.sample(range(len(pi)), d)
            positions.sort(reverse=True)
            removed = [pi.pop(pos) for pos in positions]
            random.shuffle(removed)
            pi_D = pi[:]
            for job in removed:
                e = taillard_forward(pi_D)
                q = taillard_backward(pi_D)
                best_cost = float('inf')
                best_pos = 0
                for pos in range(len(pi_D)+1):
                    cost = insertion_cost(pi_D, job, pos, e, q)
                    if cost < best_cost:
                        best_cost = cost
                        best_pos = pos
                pi_D.insert(best_pos, job)
            pi_new = pi_D

        new_makespan = makespan(pi_new)
        if new_makespan < makespan(pi):
            pi = pi_new[:]
            if new_makespan < best_makespan:
                pi_best = pi_new[:]
                best_makespan = new_makespan
        elif new_makespan < best_makespan:
            if random.random() < math.exp(-(new_makespan - makespan(pi)) / T):
                pi = pi_new[:]
        else:
            if random.random() < math.exp(-(new_makespan - makespan(pi)) / T):
                pi = pi_new[:]

    return pi_best

