        t = [0] * M
        for job in perm:
            p = times[job]
            t[0] += p[0]
            for m in range(1, M):
                t[m] = max(t[m - 1], t[m]) + p[m]
        return t[-1]

    def taillard_evaluate(perm, x):
        k = len(perm)
        # Forward pass for current perm (0..k-1)
        for r in range(k):
            pj = times[perm[r]]
            if r == 0:
                e[r][0] = pj[0]
                for m in range(1, M):
                    e[r][m] = e[r][m - 1] + pj[m]
            else:
                e[r][0] = e[r - 1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r - 1][m], e[r][m - 1]) + pj[m]
        # Backward pass (q[k][*] = 0)
        for m in range(M):
            q[k][m] = 0
        for r in range(k - 1, -1, -1):
            pj = times[perm[r]]
            q[r][M - 1] = q[r + 1][M - 1] + pj[M - 1]
            for m in range(M - 2, -1, -1):
                q[r][m] = max(q[r + 1][m], q[r][m + 1]) + pj[m]
        # Evaluate insertion positions
        best_pos = 0
        best_ms = float('inf')
        px = times[x]
        for i in range(k + 1):
            # forward vector f for job x
            if i == 0:
                f[0] = px[0]
                for m in range(1, M):
                    f[m] = f[m - 1] + px[m]
            else:
                f[0] = e[i - 1][0] + px[0]
                for m in range(1, M):
                    f[m] = max(f[m - 1], e[i - 1][m]) + px[m]
            # makespan = max_m (f[m] + q[i][m])
            ms = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > ms:
                    ms = val
            if ms < best_ms:
                best_ms = ms
                best_pos = i
        return best_pos, best_ms

    # NEH construction with Taillard acceleration
    perm = [order[0]]
    for idx in range(1, N):
        job = order[idx]
        pos, _ = taillard_evaluate(perm, job)
        perm.insert(pos, job)

    # Iterated Greedy refinement
    random.seed(42)  # deterministic behavior
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    d = 3 if N > 20 else 2
