            pass
        elif curr_ms > makespan(best):
            delta = curr_ms - makespan(best)
            if random.random() < math.exp(-delta / T):
                current = current[:]
            else:
                current = best[:]
        else:
            # equal makespan, keep current
            pass

    return best

