            f.append(max(left, up) + times[job][m])
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
        return best

    def neh_construct(order):
        if not order:
            return []
        best_seq = [order[0], order[1]] if makespan([order[0], order[1]]) < makespan([order[1], order[0]]) else [order[1], order[0]]
        for idx in range(2, len(order)):
            job = order[idx]
            partial = best_seq[:]
            e = compute_forward(partial)
            q = compute_backward(partial)
            best_cost = float('inf')
            best_pos = 0
            for pos in range(len(partial) + 1):
                cost = insertion_cost(partial, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            best_seq = best_seq[:best_pos] + [job] + best_seq[best_pos:]
        return best_seq

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: (-P[i], i))
    current = neh_construct(order)
    best = current[:]
    best_makespan = makespan(best)
    if best_makespan == 0:
        return best

    S = [sum((2*m - M + 1) * times[i][m] for m in range(M)) for i in range(N)]
    order_slope = sorted(range(N), key=lambda i: (-S[i], i))
    current_slope = neh_construct(order_slope)
    if makespan(current_slope) < best_makespan:
        best = current_slope[:]
        best_makespan = makespan(best)

    for _ in range(60):
        d = 3 if N > 5 else max(1, N//2)
        indices = random.sample(range(N), d)
        extracted = [current[i] for i in indices]
        remaining = [current[i] for i in range(N) if i not in indices]
        e = compute_forward(remaining)
        q = compute_backward(remaining)
        for job in extracted:
            best_cost = float('inf')
            best_pos = 0
            for pos in range(len(remaining) + 1):
                cost = insertion_cost(remaining, job, pos, e, q)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            remaining = remaining[:best_pos] + [job] + remaining[best_pos:]
        current = remaining
        current_makespan = makespan(current)
        if current_makespan < best_makespan:
            best = current[:]
            best_makespan = current_makespan
        if current_makespan < makespan(best):
            current = current[:]
        else:
            if random.random() < math.exp(-(current_makespan - makespan(best)) / T):
                current = current[:]
    return best

