def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_times = [times[i][:] for i in range(N)]

    # Helper: compute makespan using DP
    def compute_makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            pt = job_times[job]
            t[0] += pt[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pt[m]
        return t[-1]

    # Helper: compute forward completion matrix e for a sequence
    def compute_forward(seq):
        k = len(seq)
        if k == 0:
            return [[0]*M]
        e = [[0]*M for _ in range(k)]
        for r in range(k):
            pt = job_times[seq[r]]
            if r == 0:
                e[0][0] = pt[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pt[m]
            else:
                e[r][0] = e[r-1][0] + pt[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pt[m]
        return e

    # Helper: compute backward tail matrix q for a sequence
    def compute_backward(seq):
        k = len(seq)
        if k == 0:
            return [[0]*M]
        q = [[0]*M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pt = job_times[seq[r]]
            q[r][M-1] = q[r+1][M-1] + pt[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pt[m]
        return q

    # Helper: evaluate makespan for inserting job x at position i using Taillard's O(M) method
    def evaluate_insertion(e_prev, q_next, x, i):
        pt = job_times[x]
        f = [0] * M
        if i == 0:
            f[0] = pt[0]
            for m in range(1, M):
                f[m] = f[m-1] + pt[m]
        else:
            e_row = e_prev[i-1]
            f[0] = e_row[0] + pt[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_row[m]) + pt[m]
        makespan = 0
        q_row = q_next[i]
        for m in range(M):
            val = f[m] + q_row[m]
            if val > makespan:
                makespan = val
        return makespan

    # NEH with Taillard acceleration
    total_times = [sum(job) for job in job_times]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    if N == 0:
        return []
    seq = [order[0]]
    if N > 1:
        # Try both orders for first two jobs
        makespan01 = compute_makespan([order[0], order[1]])
        makespan10 = compute_makespan([order[1], order[0]])
        if makespan01 <= makespan10:
            seq = [order[0], order[1]]
        else:
            seq = [order[1], order[0]]
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            e = compute_forward(seq)
            q = compute_backward(seq)
            best_pos = 0
            best_makespan = float('inf')
            for i in range(len(seq)+1):
                msp = evaluate_insertion(e, q, job, i)
                if msp < best_makespan:
                    best_makespan = msp
                    best_pos = i
            seq.insert(best_pos, job)

    # Iterated Greedy refinement
    makespan_star = compute_makespan(seq)
    seq_star = seq[:]

    # Calculate temperature parameter
    total_processing = sum(total_times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-9:
        T = 1e-9

    max_iter = 60  # Calibrated for <50ms
    d = 3  # Destruction size

    for _ in range(max_iter):
        # Destruction: remove d random jobs
        if d >= N:
            destroyed = []
            remaining = seq[:]
        else:
            indices = random.sample(range(N), d)
            indices.sort(reverse=True)
            destroyed = [seq.pop(i) for i in indices]
            remaining = seq

        # Reconstruction: reinsert using NEH with Taillard
        if destroyed:
            # Sort destroyed jobs by descending total processing time
            destroyed_sorted = sorted(destroyed, key=lambda i: total_times[i], reverse=True)
            for job in destroyed_sorted:
                if not remaining:
                    remaining.append(job)
                    continue
                e = compute_forward(remaining)
                q = compute_backward(remaining)
                best_pos = 0
                best_makespan = float('inf')
                for i in range(len(remaining)+1):
                    msp = evaluate_insertion(e, q, job, i)
                    if msp < best_makespan:
                        best_makespan = msp
                        best_pos = i
                remaining.insert(best_pos, job)
            seq = remaining
        else:
            seq = seq[:]  # No change

        # Acceptance criterion
        current_makespan = compute_makespan(seq)
        if current_makespan < makespan_star:
            makespan_star = current_makespan
            seq_star = seq[:]
        if current_makespan < makespan_star:  # This condition is redundant but kept for structure
            pass
        elif random.random() < math.exp(-(current_makespan - makespan_star) / T):
            seq = seq[:]  # Accept current solution
        else:
            seq = seq_star[:]  # Revert to best solution

    return seq_star

