def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Flatten processing times for faster access
    p = [times[i][:] for i in range(n)]

    # Precompute total processing times for NEH priority
    total_time = [sum(p[i]) for i in range(n)]
    order = sorted(range(n), key=lambda i: total_time[i], reverse=True)

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * m
        for job in perm:
            for k in range(m):
                if k == 0:
                    t[k] += p[job][k]
                else:
                    t[k] = max(t[k], t[k-1]) + p[job][k]
        return t[-1]

    # Taillard acceleration: compute forward completion matrix e for prefix perm[0:k]
    def compute_forward(perm, k):
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job = perm[r]
            for mc in range(m):
                if mc == 0:
                    prev = e[r-1][0] if r > 0 else 0
                    e[r][mc] = prev + p[job][mc]
                else:
                    left = e[r][mc-1]
                    up = e[r-1][mc] if r > 0 else 0
                    e[r][mc] = max(left, up) + p[job][mc]
        return e

    # Taillard acceleration: compute backward tail matrix q for suffix perm[k:]
    def compute_backward(perm, k):
        q = [[0] * m for _ in range(k+1)]
        # q[k][:] is already 0
        for r in range(k-1, -1, -1):
            job = perm[r]
            for mc in range(m-1, -1, -1):
                if mc == m-1:
                    down = q[r+1][mc]
                    q[r][mc] = down + p[job][mc]
                else:
                    right = q[r][mc+1]
                    down = q[r+1][mc]
                    q[r][mc] = max(right, down) + p[job][mc]
        return q

    # Evaluate makespan for inserting job x at each position in current perm (length k)
    # Returns list of makespans for positions 0..k
    def insertion_makespans(perm, k, x, e, q):
        f = [0] * m
        spans = [0] * (k+1)
        for i in range(k+1):
            # Compute forward vector f for job x after prefix perm[0:i-1]
            for mc in range(m):
                if mc == 0:
                    prev_e = e[i-1][0] if i > 0 else 0
                    f[mc] = prev_e + p[x][mc]
                else:
                    left = f[mc-1]
                    up = e[i-1][mc] if i > 0 else 0
                    f[mc] = max(left, up) + p[x][mc]
            # Makespan = max_m (f[m] + q[i][m])
            best = 0
            for mc in range(m):
                val = f[mc] + q[i][mc]
                if val > best:
                    best = val
            spans[i] = best
        return spans

    # NEH construction with Taillard acceleration
    def neh_construction():
        if n == 0:
            return []
        perm = [order[0]]
        if n == 1:
            return perm
        # Try both orders for first two jobs
        span1 = makespan([order[0], order[1]])
        span2 = makespan([order[1], order[0]])
        if span1 <= span2:
            perm = [order[0], order[1]]
        else:
            perm = [order[1], order[0]]
        # Insert remaining jobs
        for k in range(2, n):
            job = order[k]
            e = compute_forward(perm, k)
            q = compute_backward(perm, k)
            spans = insertion_makespans(perm, k, job, e, q)
            # Find best position (earliest in case of tie)
            best_pos = 0
            best_span = spans[0]
            for pos in range(1, k+1):
                if spans[pos] < best_span:
                    best_span = spans[pos]
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    # Iterated Greedy with Taillard-accelerated reconstruction
    def iterated_greedy(initial_perm, max_iter=50):
        current = initial_perm[:]
        best = current[:]
        best_span = makespan(best)
        total_processing = sum(total_time)
        T = 0.5 * total_processing / (10 * n * m)  # Temperature parameter
        d = 3  # Number of jobs to remove

        for _ in range(max_iter):
            # Destruction: remove d random jobs
            if n <= d:
                destroyed = []
                removed = current[:]
            else:
                indices = random.sample(range(n), d)
                indices.sort(reverse=True)
                removed = [current[i] for i in indices]
                destroyed = current[:]
                for idx in indices:
                    destroyed.pop(idx)
            # Reconstruction: reinsert removed jobs one by one using NEH insertion
            for job in removed:
                k = len(destroyed)
                if k == 0:
                    destroyed = [job]
                else:
                    e = compute_forward(destroyed, k)
                    q = compute_backward(destroyed, k)
                    spans = insertion_makespans(destroyed, k, job, e, q)
                    best_pos = 0
                    best_span_insert = spans[0]
                    for pos in range(1, k+1):
                        if spans[pos] < best_span_insert:
                            best_span_insert = spans[pos]
                            best_pos = pos
                    destroyed.insert(best_pos, job)
            current = destroyed
            current_span = makespan(current)
            # Acceptance criterion
            if current_span < makespan(best):
                best = current[:]
                best_span = current_span
            if current_span < makespan(current):  # Always improve if better
                current = current[:]
            else:
                # Metropolis acceptance
                delta = current_span - makespan(current)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    current = current[:]
                # else: keep current (no change)
        return best

    # Build initial solution
    init_perm = neh_construction()
    # Refine with Iterated Greedy
    result = iterated_greedy(initial_perm, max_iter=40)
    return result

