def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten times for faster access: job * M + machine
    flat = [0] * (N * M)
    for i in range(N):
        base = i * M
        for j in range(M):
            flat[base + j] = times[i][j]

    # Precompute total processing times for each job
    total = [0] * N
    for i in range(N):
        base = i * M
        s = 0
        for j in range(M):
            s += flat[base + j]
        total[i] = s

    # Sort jobs by total processing time descending
    order = list(range(N))
    order.sort(key=lambda i: total[i], reverse=True)

    # Preallocate matrices for Taillard's acceleration
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N + 1)]

    def makespan(perm):
        if not perm:
            return 0
        c_prev = [0] * M
        for job in perm:
            base = job * M
            c_curr = [0] * M
            c_curr[0] = c_prev[0] + flat[base]
            for m in range(1, M):
                c_curr[m] = max(c_prev[m], c_curr[m-1]) + flat[base + m]
            c_prev = c_curr
        return c_prev[M-1]

    def compute_forward(perm, length):
        if length == 0:
            for m in range(M):
                e[0][m] = 0
        else:
            for r in range(length):
                job = perm[r]
                base = job * M
                if r == 0:
                    e[0][0] = flat[base]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + flat[base + m]
                else:
                    e[r][0] = e[r-1][0] + flat[base]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + flat[base + m]

    def compute_backward(perm, length):
        for m in range(M):
            q[length][m] = 0
        for r in range(length-1, -1, -1):
            job = perm[r]
            base = job * M
            q[r][M-1] = q[r+1][M-1] + flat[base + M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + flat[base + m]

    def evaluate_insertion(perm, length, job, pos):
        base = job * M
        f = [0] * M
        if pos == 0:
            f[0] = flat[base]
            for m in range(1, M):
                f[m] = f[m-1] + flat[base + m]
        else:
            f[0] = e[pos-1][0] + flat[base]
            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + flat[base + m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Construct initial solution using accelerated NEH
    perm = [order[0], order[1]]
    if makespan([order[1], order[0]]) < makespan(perm):
        perm = [order[1], order[0]]

    for k in range(2, N):
        job = order[k]
