        # Evaluate first two jobs
        seq1 = [priority_order[0], priority_order[1]]
        seq2 = [priority_order[1], priority_order[0]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        # Preallocate matrices
        e = [[0] * M for _ in range(len(seq))]
        q = [[0] * M for _ in range(len(seq) + 1)]
        # Insert remaining jobs
        for idx in range(2, len(priority_order)):
