            job_t = times[job]
            k = len(seq)
            # Forward pass
            for r in range(k):
                if r == 0:
                    e[r][0] = job_t[seq[0]] if r == 0 else e[r-1][0] + job_t[seq[r]]
                else:
                    e[r][0] = e[r-1][0] + job_t[seq[r]]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_t[seq[r]]
            # Backward pass
            for m in range(M):
