    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_time = times[job]
            t[0] += job_time[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_time[m]
        return t[-1]

    def compute_forward(seq):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        job0 = times[seq[0]]
        e[0][0] = job0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0[m]
        for i in range(1, k):
            job = times[seq[i]]
            e[i][0] = e[i-1][0] + job[0]
            for m in range(1, M):
                e[i][m] = max(e[i-1][m], e[i][m-1]) + job[m]
        return e

    def compute_backward(seq):
        k = len(seq)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for i in range(k-1, -1, -1):
            job = times[seq[i]]
            q[i][M-1] = q[i+1][M-1] + job[M-1]
            for m in range(M-2, -1, -1):
                q[i][m] = max(q[i+1][m], q[i][m+1]) + job[m]
        return q

    def insertion_cost(e, q, job_idx, pos):
        job = times[job_idx]
        f = [0] * M
        if pos == 0:
            f[0] = job[0]
            for m in range(1, M):
                f[m] = f[m-1] + job[m]
        else:
            e_prev = e[pos-1]
            f[0] = e_prev[0] + job[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[m]) + job[m]
        q_pos = q[pos]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q_pos[m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_construct():
