        for job in removed:
            best_cost = float('inf')
            best_pos = 0
            for pos in range(len(current)+1):
                cost = insertion_cost(e, q, job, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            current.insert(best_pos, job)
            e = compute_forward(current)
            q = compute_backward(current)
        new_makespan = makespan(current)
        if new_makespan < current_makespan:
            current_makespan = new_makespan
            if new_makespan < best_makespan:
                best_makespan = new_makespan
                best_seq = list(current)
        elif new_makespan < best_makespan:
            best_makespan = new_makespan
            best_seq = list(current)
            current = list(best_seq)
            current_makespan = best_makespan
        else:
            if random.random() < math.exp(-(new_makespan - current_makespan) / T):
                current = list(current)
                current_makespan = new_makespan
            else:
                current = list(current)
                current_makespan = current_makespan
    return best_seq

