def schedule_flowshop(times: list[list[int]]) -> list[int]:
    n = len(times)
    if n == 0:
        return []
    if n == 1:
        return [0]
    m = len(times[0])
    if m == 0:
        return list(range(n))
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    total_processing = [sum(times[i]) for i in range(n)]
    jobs = sorted(range(n), key=lambda i: total_processing[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * m
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for k in range(1, m):
                t[k] = max(t[k-1], t[k]) + job_t[k]
        return t[-1]

    def makespan_taillard(seq):
        if not seq:
            return 0
        e = [0] * m
        for job in seq:
            job_t = times[job]
            e[0] += job_t[0]
            for k in range(1, m):
                e[k] = max(e[k-1], e[k]) + job_t[k]
        return e[-1]

    def taillard_insertion_cost(partial, job_x):
        k = len(partial)
        if k == 0:
            return times[job_x][-1] if m > 0 else 0
        e = [0] * m
        for idx in range(k):
            job_idx = partial[idx]
            job_t = times[job_idx]
            if idx == 0:
                e[0] = job_t[0]
                for mc in range(1, m):
                    e[mc] = e[mc-1] + job_t[mc]
            else:
                e[0] += job_t[0]
                for mc in range(1, m):
                    e[mc] = max(e[mc-1], e[mc]) + job_t[mc]
        q = [0] * m
        for idx in range(k-1, -1, -1):
            job_idx = partial[idx]
            job_t = times[job_idx]
            if idx == k-1:
                q[m-1] = job_t[m-1]
                for mc in range(m-2, -1, -1):
                    q[mc] = q[mc+1] + job_t[mc]
            else:
                q[m-1] += job_t[m-1]
                for mc in range(m-2, -1, -1):
                    q[mc] = max(q[mc], q[mc+1]) + job_t[mc]
        best_cost = float('inf')
        best_pos = 0
        for pos in range(k+1):
            if pos == 0:
                f = [0] * m
                f[0] = times[job_x][0]
                for mc in range(1, m):
                    f[mc] = f[mc-1] + times[job_x][mc]
            elif pos == k:
                f = e[:]
                f[0] += times[job_x][0]
                for mc in range(1, m):
                    f[mc] = max(f[mc-1], f[mc]) + times[job_x][mc]
            else:
                f = [0] * m
                f[0] = e[pos-1][0] + times[job_x][0]
                for mc in range(1, m):
                    f[mc] = max(f[mc-1], e[pos-1][mc]) + times[job_x][mc]
            cost = 0
            for mc in range(m):
                val = f[mc] + q[pos][mc]
                if val > cost:
                    cost = val
            if cost < best_cost:
                best_cost = cost
                best_pos = pos
        return best_cost, best_pos

    def neh_taillard(jobs_order):
        if not jobs_order:
            return []
        seq = [jobs_order[0]]
        if len(jobs_order) > 1:
            job1, job2 = jobs_order[0], jobs_order[1]
            seq1 = [job1, job2]
            seq2 = [job2, job1]
            if makespan_taillard(seq1) <= makespan_taillard(seq2):
                seq = seq1
            else:
                seq = seq2
        for idx in range(2, len(jobs_order)):
            job = jobs_order[idx]
            _, pos = taillard_insertion_cost(seq, job)
            seq.insert(pos, job)
        return seq

    current = neh_taillard(jobs)
    best = current[:]
    best_makespan = makespan_taillard(best)
    total_sum = sum(total_processing)
    T_param = 0.5
    T = T_param * total_sum / (10 * n * m) if n * m > 0 else 1e-6
    d = 3 if n > 20 else 2
    max_iter = 60 if n <= 60 else 40
    for _ in range(max_iter):
        if len(current) <= d:
            destroyed = []
            R = current[:]
        else:
            indices = random.sample(range(len(current)), d)
            indices.sort(reverse=True)
            R = [current[i] for i in indices]
            destroyed = current[:]
            for i in indices:
                del destroyed[i]
        pi_D = destroyed
        for job in R:
            _, pos = taillard_insertion_cost(pi_D, job)
            pi_D.insert(pos, job)
        current = pi_D
        curr_makespan = makespan_taillard(current)
        if curr_makespan < best_makespan:
            best_makespan = curr_makespan
            best = current[:]
        if curr_makespan < makespan_taillard(best):
            best = current[:]
            best_makespan = curr_makespan
        if curr_makespan < makespan_taillard(current):
            current = current[:]
        else:
            if random.random() < math.exp(-(curr_makespan - makespan_taillard(current)) / T):
                current = current[:]
    return best

