        if not perm:
            return [[0] * M]
        e = [[0] * M for _ in range(len(perm))]
        for r in range(len(perm)):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job][m]
        return e

    def compute_backward(perm):
        k = len(perm)
        q = [[0] * M for _ in range(k + 1)]
        for r in range(k - 1, -1, -1):
            job = perm[r]
            for m in range(M - 1, -1, -1):
                if m == M - 1:
                    q[r][m] = q[r + 1][m] + times[job][m]
                else:
                    q[r][m] = max(q[r + 1][m], q[r][m + 1]) + times[job][m]
        return q

    def makespan_insertion(e, q, job, pos):
        f = [0] * M
        for m in range(M):
            if m == 0:
                f[m] = (e[pos-1][m] if pos > 0 else 0) + times[job][m]
            else:
                f[m] = max(f[m-1], e[pos-1][m] if pos > 0 else 0) + times[job][m]
        max_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > max_val:
                max_val = val
        return max_val

    def makespan(perm):
        if not perm:
            return 0
        e = compute_forward(perm)
        return e[-1][-1]

    perm = [order[0]]
    for idx in range(1, N):
        job = order[idx]
        k = len(perm)
        e = compute_forward(perm)
        q = compute_backward(perm)
        best_pos = 0
        best_cmax = makespan_insertion(e, q, job, 0)
        for pos in range(1, k + 1):
            cmax = makespan_insertion(e, q, job, pos)
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = pos
        perm.insert(best_pos, job)

    best_perm = perm[:]
    best_cmax = makespan(best_perm)

    for _ in range(max_iter):
