        random.shuffle(indices)
        removed = []
        remaining = perm[:]
        for idx in indices[:d]:
            job = remaining.pop(indices.index(idx) if idx in remaining else remaining.index(indices[indices.index(idx)] if idx in indices else 0))
            removed.append(job)
        random.shuffle(removed)

        for job in removed:
            k = len(remaining)
            e = compute_forward(remaining)
