    total_processing = sum(sum(job) for job in times)
    job_sums = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m-1], t[m]) + times[job][m]
        return t[-1]

    def makespan_taillard(perm, forward=None, backward=None):
        k = len(perm)
        if k == 0:
            return 0
        if forward is None:
            forward = [[0] * M for _ in range(k)]
        if backward is None:
            backward = [[0] * M for _ in range(k + 1)]
        for r in range(k):
            job = perm[r]
            for m in range(M):
                if m == 0:
                    forward[r][m] = (forward[r-1][m] if r > 0 else 0) + times[job][m]
                else:
                    forward[r][m] = max(forward[r-1][m] if r > 0 else 0, forward[r][m-1]) + times[job][m]
        for r in range(k, -1, -1):
            for m in range(M):
                if r == k:
                    backward[r][m] = 0
                else:
                    if m == M-1:
                        backward[r][m] = backward[r+1][m] + times[perm[r]][m]
                    else:
                        backward[r][m] = max(backward[r+1][m], backward[r][m+1]) + times[perm[r]][m]
        return forward, backward

    def evaluate_insertion(forward, backward, job, pos, k):
        f = [0] * M
        for m in range(M):
            if m == 0:
                f[m] = (forward[pos-1][m] if pos > 0 else 0) + times[job][m]
            else:
                f[m] = max(f[m-1], forward[pos-1][m] if pos > 0 else 0) + times[job][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + backward[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def construct_neh():
        if N < 2:
            return order[:2] if N == 2 else order[:1]
        perm = [order[0], order[1]]
        if makespan([order[1], order[0]]) < makespan(perm):
            perm = [order[1], order[0]]
        forward = [[0] * M for _ in range(2)]
        backward = [[0] * M for _ in range(3)]
        forward, backward = makespan_taillard(perm, forward, backward)
        for idx in range(2, N):
            job = order[idx]
            best_pos = 0
            best_ms = float('inf')
            for pos in range(idx + 1):
                ms = evaluate_insertion(forward, backward, job, pos, idx)
                if ms < best_ms:
                    best_ms = ms
                    best_pos = pos
            perm.insert(best_pos, job)
            forward, backward = makespan_taillard(perm, forward, backward)
        return perm

    def destruction(perm, d):
        indices = random.sample(range(len(perm)), d)
        removed = [perm[i] for i in sorted(indices, reverse=True)]
        for i in sorted(indices, reverse=True):
            del perm[i]
        return perm, removed

    def reconstruction(perm_D, R):
        if not perm_D:
            return R[:]
        forward = [[0] * M for _ in range(len(perm_D))]
        backward = [[0] * M for _ in range(len(perm_D) + 1)]
        forward, backward = makespan_taillard(perm_D, forward, backward)
        for job in R:
            best_pos = 0
            best_ms = float('inf')
            for pos in range(len(perm_D) + 1):
                ms = evaluate_insertion(forward, backward, job, pos, len(perm_D))
                if ms < best_ms:
                    best_ms = ms
                    best_pos = pos
            perm_D.insert(best_pos, job)
            forward, backward = makespan_taillard(perm_D, forward, backward)
        return perm_D

    current = construct_neh()
    best = current[:]
    best_ms = makespan(current)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 60
    for _ in range(max_iter):
        if best_ms == 0:
            break
        perm_D, R = destruction(current[:], 3)
        current = reconstruction(perm_D, R)
        ms = makespan(current)
        if ms < best_ms:
            best_ms = ms
            best = current[:]
        if ms < makespan(current):
            current = current[:]
        else:
            if ms < makespan(current):
                current = current[:]
            else:
                delta = ms - makespan(current)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    current = current[:]
    return best

