def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]
    # Slope index for alternative ordering
    slope = [sum((2 * j - M + 1) * p[i][j] for j in range(M)) for i in range(N)]

    # Makespan calculation for a given permutation
    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += p[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + p[job][m]
        return t[-1]

    # Taillard's accelerated insertion evaluation
    def evaluate_insertion(partial, job_idx):
        k = len(partial)
        # Forward matrix e: completion times of partial schedule
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = partial[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][0] if r > 0 else 0) + p[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job][m]
        # Backward matrix q: tail times from position r
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = partial[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]
        # Evaluate each insertion position
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            # Forward pass for job_idx up to machine m
            f = [0] * M
            for m in range(M):
                if m == 0:
                    f[m] = (e[i-1][0] if i > 0 else 0) + p[job_idx][m]
                else:
                    f[m] = max(f[m-1], e[i-1][m] if i > 0 else 0) + p[job_idx][m]
            # Compute makespan if inserted at i
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_pos, best_cmax

    # NEH construction with Taillard acceleration
    def neh_construct(order):
        if not order:
            return []
        seq = [order[0]]
        if len(order) > 1:
            # Evaluate both orders of first two jobs
            c01 = makespan([order[0], order[1]])
            c10 = makespan([order[1], order[0]])
            seq = [order[0], order[1]] if c01 <= c10 else [order[1], order[0]]
            start = 2
        else:
            start = 1
        for idx in range(start, len(order)):
            job = order[idx]
            pos, _ = evaluate_insertion(seq, job)
            seq.insert(pos, job)
        return seq

    # Try multiple orderings: total processing time and slope
    order_tp = sorted(range(N), key=lambda i: total_p[i], reverse=True)
    order_slope = sorted(range(N), key=lambda i: slope[i], reverse=True)
    best_seq = None
    best_cmax = float('inf')
    for order in (order_tp, order_slope):
        seq = neh_construct(order)
        cmax = makespan(seq)
        if cmax < best_cmax:
            best_cmax = cmax
            best_seq = seq

    # Iterated Greedy refinement
    random.seed(42)  # for deterministic behavior
    T_param = 0.5
    avg_p = sum(total_p) / (N * M)
