    d = 3 if N > 20 else 2
    max_iters = 60
    current = best_seq[:]
    current_cmax = best_cmax
    for _ in range(max_iters):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current[i] for i in indices]
        # Build partial sequence without removed jobs
        partial = [current[i] for i in range(N) if i not in indices]
        # Reconstruction: reinsert removed jobs one by one
        for job in removed:
            pos, _ = evaluate_insertion(partial, job)
            partial.insert(pos, job)
        new_seq = partial
        new_cmax = makespan(new_seq)
        # Acceptance criterion
        if new_cmax < current_cmax:
            current = new_seq
            current_cmax = new_cmax
            if new_cmax < best_cmax:
                best_seq = new_seq
                best_cmax = new_cmax
        else:
            if random.random() < math.exp(-(new_cmax - current_cmax) / T):
                current = new_seq
                current_cmax = new_cmax
    return best_seq

