def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    job_times = [row[:] for row in times]
    total_time = [sum(row) for row in job_times]
    total_processing = sum(total_time)

    # ---------- Makespan evaluation ----------
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            pt = job_times[job]
            t[0] += pt[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + pt[m]
        return t[-1]

    # ---------- Taillard acceleration helpers ----------
    def compute_forward(partial_seq):
        k = len(partial_seq)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            pt = job_times[partial_seq[r]]
            if r == 0:
                e[0][0] = pt[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pt[m]
            else:
                e[r][0] = e[r-1][0] + pt[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pt[m]
        return e

    def compute_backward(partial_seq):
        k = len(partial_seq)
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            pt = job_times[partial_seq[r]]
            q[r][M-1] = q[r+1][M-1] + pt[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pt[m]
        return q

    def insertion_cost(partial_seq, job, e_prev, q_next):
        i = len(e_prev)  # insertion index
        pt = job_times[job]
        f = [0] * M
        if i == 0:
            f[0] = pt[0]
            for m in range(1, M):
                f[m] = f[m-1] + pt[m]
        else:
            f[0] = e_prev[0][0] + pt[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[0][m]) + pt[m]
        best = float('inf')
        for m in range(M):
            val = f[m] + q_next[m]
            if val < best:
                best = val
        return best

    def taillard_insert(partial_seq, job):
        k = len(partial_seq)
        if k == 0:
            return [job]
        e = compute_forward(partial_seq)
        q = compute_backward(partial_seq)
        best_cost = float('inf')
        best_pos = 0
        for i in range(k+1):
            e_prev = e[:i] if i > 0 else []
            q_next = q[i]
            cost = insertion_cost(partial_seq, job, e_prev, q_next)
            if cost < best_cost:
                best_cost = cost
                best_pos = i
        return partial_seq[:best_pos] + [job] + partial_seq[best_pos:]

    # ---------- NEH construction ----------
    order = sorted(range(N), key=lambda i: total_time[i], reverse=True)
    seq = [order[0]]
    for idx in order[1:]:
        seq = taillard_insert(seq, idx)
    best_seq = seq[:]
    best_makespan = makespan(seq)

    # ---------- Iterated Greedy ----------
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 60
    current_seq = best_seq[:]
    no_improve = 0
    max_no_improve = 20

    for it in range(max_iter):
        # Destruction
        if d >= N:
            destroyed = current_seq[:]
            remaining = []
        else:
            indices = random.sample(range(N), d)
            indices.sort()
            destroyed = [current_seq[i] for i in indices]
            remaining = [current_seq[i] for i in range(N) if i not in indices]
        # Reconstruction
        for job in destroyed:
            remaining = taillard_insert(remaining, job)
        new_seq = remaining
        new_makespan = makespan(new_seq)
        # Acceptance
        if new_makespan < makespan(current_seq):
            current_seq = new_seq[:]
            if new_makespan < best_makespan:
                best_seq = new_seq[:]
                best_makespan = new_makespan
                no_improve = 0
            else:
                no_improve += 1
        else:
            delta = new_makespan - makespan(current_seq)
            if random.random() < math.exp(-delta / T):
                current_seq = new_seq[:]
                no_improve += 1
            else:
                no_improve += 1
        if no_improve >= max_no_improve:
            break

    return best_seq

