        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = 0
    job_sums = [0] * N
    for i in range(N):
        s = 0
        row = times[i]
        for j in range(M):
            s += row[j]
        job_sums[i] = s
        total_processing += s

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            row = times[job]
            t[0] += row[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + row[m]
        return t[-1]

    def makespan_with_tails(perm, x, pos, e, q):
        if pos == 0:
            f0 = times[x][0]
        else:
            f0 = e[pos-1][0] + times[x][0]
        f = [f0]
        for m in range(1, M):
            val = f[m-1]
            if e[pos-1][m] > val:
                val = e[pos-1][m]
            f.append(val + times[x][m])
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    def neh_construction():
        order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
        if N == 0:
            return []
        if N == 1:
            return [order[0]]
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        if makespan(seq0) <= makespan(seq1):
            perm = seq0[:]
        else:
            perm = seq1[:]
        for k in range(2, N):
            job = order[k]
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = perm[r]
                row = times[job_r]
                if r == 0:
                    e[0][0] = row[0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + row[m]
                else:
                    e[r][0] = e[r-1][0] + row[0]
                    for m in range(1, M):
                        val = e[r-1][m]
                        if e[r][m-1] > val:
                            val = e[r][m-1]
                        e[r][m] = val + row[m]
            q = [[0] * M for _ in range(k+1)]
            for m in range(M):
                q[k][m] = 0
            for r in range(k-1, -1, -1):
                job_r = perm[r]
                row = times[job_r]
                q[r][M-1] = q[r+1][M-1] + row[M-1]
                for m in range(M-2, -1, -1):
                    val = q[r+1][m]
                    if q[r][m+1] > val:
                        val = q[r][m+1]
                    q[r][m] = val + row[m]
