                makespan_val = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > makespan_val:
                        makespan_val = val
                if makespan_val < best_makespan:
                    best_makespan = makespan_val
                    best_pos = pos
            perm.insert(best_pos, job)
        return perm

    def ig_improvement(initial_perm, max_iter=60):
        current = initial_perm[:]
        current_makespan = makespan(current)
        best = current[:]
        best_makespan = current_makespan
        d = 3 if N < 30 else 4
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M)
        if T < 1e-6:
            T = 1e-6
        for _ in range(max_iter):
            indices = list(range(N))
            random.shuffle(indices)
            removed_indices = indices[:d]
            removed_indices.sort()
            remaining = [current[i] for i in range(N) if i not in removed_indices]
            extracted = [current[i] for i in removed_indices]
            random.shuffle(extracted)
            for job in extracted:
                k = len(remaining)
                if k == 0:
                    remaining = [job]
                    continue
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    job_r = remaining[r]
                    row = times[job_r]
                    if r == 0:
                        e[0][0] = row[0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + row[m]
                    else:
                        e[r][0] = e[r-1][0] + row[0]
                        for m in range(1, M):
                            val = e[r-1][m]
                            if e[r][m-1] > val:
                                val = e[r][m-1]
                            e[r][m] = val + row[m]
                q = [[0] * M for _ in range(k+1)]
                for m in range(M):
                    q[k][m] = 0
                for r in range(k-1, -1, -1):
                    job_r = remaining[r]
                    row = times[job_r]
                    q[r][M-1] = q[r+1][M-1] + row[M-1]
                    for m in range(M-2, -1, -1):
                        val = q[r+1][m]
                        if q[r][m+1] > val:
                            val = q[r][m+1]
                        q[r][m] = val + row[m]
                best_pos = 0
                best_makespan_val = float('inf')
                for pos in range(k+1):
                    if pos == 0:
                        f0 = times[job][0]
                    else:
                        f0 = e[pos-1][0] + times[job][0]
                    f = [f0]
                    for m in range(1, M):
                        val = f[m-1]
                        if e[pos-1][m] > val:
                            val = e[pos-1][m]
                        f.append(val + times[job][m])
                    makespan_val = 0
                    for m in range(M):
                        val = f[m] + q[pos][m]
                        if val > makespan_val:
                            makespan_val = val
                    if makespan_val < best_makespan_val:
                        best_makespan_val = makespan_val
                        best_pos = pos
                remaining.insert(best_pos, job)
            new_perm = remaining
            new_makespan = makespan(new_perm)
            if new_makespan < current_makespan or random.random() < math.exp((current_makespan - new_makespan) / T):
                current = new_perm
                current_makespan = new_makespan
                if current_makespan < best_makespan:
                    best = current[:]
                    best_makespan = current_makespan
        return best

    initial_perm = neh_construction()
    if N <= 20:
        return initial_perm
    improved_perm = ig_improvement(initial_perm)
    return improved_perm

