def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    p = [row[:] for row in times]
    total_processing = sum(sum(row) for row in p)

    # Precompute total processing times per job
    P = [sum(row) for row in p]
    order = sorted(range(n), key=lambda i: P[i], reverse=True)

    # Makespan function for a given sequence
    def makespan(seq):
        t = [0] * m
        for job in seq:
            for k in range(m):
                if k == 0:
                    t[k] += p[job][k]
                else:
                    t[k] = max(t[k], t[k-1]) + p[job][k]
        return t[-1]

    # Taillard acceleration for insertion
    def insert_with_taillard(current_seq, job):
        k = len(current_seq)
        if k == 0:
            return [job]
        # Forward matrix e: k x m
        e = [[0] * m for _ in range(k)]
        for r in range(k):
            job_r = current_seq[r]
            for c in range(m):
                if r == 0 and c == 0:
                    e[r][c] = p[job_r][c]
                elif r == 0:
                    e[r][c] = e[r][c-1] + p[job_r][c]
                elif c == 0:
                    e[r][c] = e[r-1][c] + p[job_r][c]
                else:
                    e[r][c] = max(e[r-1][c], e[r][c-1]) + p[job_r][c]
        # Backward matrix q: (k+1) x m
        q = [[0] * m for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job_r = current_seq[r]
            for c in range(m-1, -1, -1):
                if c == m-1:
                    q[r][c] = q[r+1][c] + p[job_r][c]
                elif r == k-1:
                    q[r][c] = q[r][c+1] + p[job_r][c]
                else:
                    q[r][c] = max(q[r+1][c], q[r][c+1]) + p[job_r][c]
        best_pos = 0
        best_ms = float('inf')
        for i in range(k+1):
            # Compute forward vector f for job at position i
            f = [0] * m
            if i == 0:
                for c in range(m):
                    if c == 0:
                        f[c] = p[job][c]
                    else:
                        f[c] = f[c-1] + p[job][c]
            else:
                prev = e[i-1]
                for c in range(m):
                    if c == 0:
                        f[c] = prev[c] + p[job][c]
                    else:
                        f[c] = max(f[c-1], prev[c]) + p[job][c]
            # Compute makespan: max over c of f[c] + q[i][c]
            ms = 0
            for c in range(m):
                val = f[c] + q[i][c]
                if val > ms:
                    ms = val
            if ms < best_ms:
                best_ms = ms
                best_pos = i
        return current_seq[:best_pos] + [job] + current_seq[best_pos:]

    # Construct initial solution using NEH with Taillard
    seq = []
    for job in order:
        seq = insert_with_taillard(seq, job)

    # Iterated Greedy parameters
    d = 3 if n < 20 else 4
    T_param = 0.5
    T = T_param * total_processing / (10 * n * m)
    if T < 1e-6:
        T = 1e-6

    current_seq = seq[:]
    best_seq = seq[:]
    best_ms = makespan(best_seq)

    # Run IG for a fixed number of iterations to stay within time budget
    max_iter = 60
    for _ in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(n), d)
        removed = [current_seq[i] for i in indices]
        # Build destroyed sequence by keeping others in order
        destroyed = [current_seq[i] for i in range(n) if i not in indices]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job in removed:
            destroyed = insert_with_taillard(destroyed, job)
        new_seq = destroyed
        new_ms = makespan(new_seq)
        # Acceptance criterion
        if new_ms < makespan(current_seq):
            current_seq = new_seq
            if new_ms < best_ms:
                best_seq = new_seq[:]
                best_ms = new_ms
        else:
            if random.random() < math.exp(-(new_ms - makespan(current_seq)) / T):
                current_seq = new_seq
    return best_seq

