    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m], t[m-1]) + times[job][m]
        return t[-1]

    # Helper: Johnson's rule for two-machine flow shop
    def johnson_rule(times_sub):
        n = len(times_sub)
        left, right = 0, n - 1
        seq = [0] * n
        jobs = list(range(n))
        while jobs:
            best_job = None
            best_val = float('inf')
            best_side = None  # 'left' or 'right'
            for j in jobs:
                a, b = times_sub[j]
                if a <= b:
                    if a < best_val:
                        best_val = a
                        best_job = j
                        best_side = 'left'
                else:
                    if b < best_val:
                        best_val = b
                        best_job = j
                        best_side = 'right'
            if best_side == 'left':
                seq[left] = best_job
                left += 1
            else:
                seq[right] = best_job
                right -= 1
            jobs.remove(best_job)
        return seq

    # CDS: generate M-1 permutations via Johnson's rule on artificial 2-machine problems
    best_perm = None
    best_makespan = float('inf')
    for l in range(1, M):
        # Build artificial two-machine processing times
        times_sub = []
        for i in range(N):
            p1 = sum(times[i][:l])      # sum of first l machines
            p2 = sum(times[i][M-l:])    # sum of last l machines
            times_sub.append((p1, p2))
        perm_sub = johnson_rule(times_sub)
        # Map back to original job indices
        perm = [perm_sub[i] for i in range(N)]
        m = makespan(perm)
        if m < best_makespan:
            best_makespan = m
            best_perm = perm
    return best_perm

