    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job processing times as flat lists for faster access
    proc = [row[:] for row in times]

    # Gupta's heuristic: sign-weighted sum of (machine_index - (m-1)/2) * processing_time
    # Jobs with negative sum (early-loaded) come first, positive sum (late-loaded) come last
    gupta_scores = []
    mid = (m - 1) / 2.0
    for i in range(n):
        s = 0.0
        for j in range(m):
            s += (j - mid) * proc[i][j]
        gupta_scores.append(s)

    # Sort by Gupta score ascending (negative first)
    order = sorted(range(n), key=lambda i: gupta_scores[i])

    # Function to compute makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            t[0] += proc[job][0]
            for k in range(1, m):
                t[k] = max(t[k], t[k-1]) + proc[job][k]
        return t[-1]

    # NEH with Taillard acceleration for initial solution
    def neh_taillard(job_order):
        if not job_order:
            return []
        # Start with first job
        seq = [job_order[0]]
        # Preallocate matrices
        e = [[0] * m for _ in range(len(job_order))]
        q = [[0] * m for _ in range(len(job_order) + 1)]

        for idx in range(1, len(job_order)):
            job = job_order[idx]
            k = len(seq)  # current sequence length

            # Compute forward completion matrix e for current seq
            for r in range(k):
                for mc in range(m):
                    if mc == 0:
                        prev = e[r-1][0] if r > 0 else 0
                        e[r][0] = prev + proc[seq[r]][0]
                    else:
                        up = e[r-1][mc] if r > 0 else 0
                        left = e[r][mc-1]
                        e[r][mc] = max(up, left) + proc[seq[r]][mc]

            # Compute backward tail matrix q for current seq
            for mc in range(m):
                q[k][mc] = 0
            for r in range(k-1, -1, -1):
                for mc in range(m-1, -1, -1):
                    if mc == m-1:
                        q[r][mc] = q[r+1][mc] + proc[seq[r]][mc]
                    else:
                        down = q[r+1][mc]
                        right = q[r][mc+1]
                        q[r][mc] = max(down, right) + proc[seq[r]][mc]

            # Find best insertion position for job
            best_pos = 0
            best_mk = float('inf')
            for i in range(k+1):
                # Compute forward vector f for job at position i
                f = [0] * m
                if i == 0:
                    prev_e = [0] * m
                else:
                    prev_e = e[i-1]
                for mc in range(m):
                    if mc == 0:
                        f[0] = prev_e[0] + proc[job][0]
                    else:
                        f[mc] = max(f[mc-1], prev_e[mc]) + proc[job][mc]
                # Compute makespan if job inserted at i
                mk = 0
                for mc in range(m):
                    val = f[mc] + q[i][mc]
                    if val > mk:
