    # Compute a simple lower bound: max of machine total and job total
    total_proc = [0] * m
    for i in range(n):
        for j in range(m):
            total_proc[j] += proc[i][j]
    lb = max(max(total_proc), max(sum(proc[i]) for i in range(n)))
    if best_mk == lb:
