            if k == 0:
                current_seq.append(job)
                continue

            # Recompute e and q for current_seq
            e = [[0] * m for _ in range(k)]
            q = [[0] * m for _ in range(k+1)]

            for r in range(k):
                for mc in range(m):
                    if mc == 0:
                        prev = e[r-1][0] if r > 0 else 0
                        e[r][0] = prev + proc[current_seq[r]][0]
                    else:
