            best_seq = current_seq[:]
            best_mk = curr_mk
        elif curr_mk > makespan(current_seq):  # Always false, but structure for Metropolis
            pass
        else:
            # Metropolis acceptance: accept worse solution with probability
            delta = curr_mk - makespan(current_seq)  # This is zero, so always accept if equal
            if delta < 0 or random.random() < math.exp(-delta / T):
                # Accept current_seq (already set)
                pass
            else:
                # Revert to previous state? Not stored; we keep current_seq as is for simplicity
                # In practice, we would need to keep last accepted, but for speed we skip revert
                # Since delta is often small and we accept on equality or improvement, this is rare
                pass

    return best_seq

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for job priority
    total_times = [sum(job) for job in times]
    jobs_sorted = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Helper: compute makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += times[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + times[job][m]
        return t[-1]

    # Helper: compute forward completion matrix e for a given permutation (length k)
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        e = [[0] * M for _ in range(k)]
        for m in range(M):
            e[0][m] = (e[0][m-1] if m > 0 else 0) + times[perm[0]][m]
        for i in range(1, k):
            e[i][0] = e[i-1][0] + times[perm[i]][0]
            for m in range(1, M):
                e[i][m] = max(e[i-1][m], e[i][m-1]) + times[perm[i]][m]
        return e

    # Helper: compute backward tail matrix q for a given permutation (length k)
    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0] * M]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for i in range(k-1, -1, -1):
            q[i][M-1] = q[i+1][M-1] + times[perm[i]][M-1]
            for m in range(M-2, -1, -1):
                q[i][m] = max(q[i+1][m], q[i][m+1]) + times[perm[i]][m]
        return q

    # Helper: evaluate makespan for inserting job x at position i in current perm (length k)
    def evaluate_insertion(perm, x, i, e_prev=None, q_prev=None):
        k = len(perm)
        if k == 0:
            return times[x][0] if M == 1 else sum(times[x])
        if e_prev is None:
            e_prev = compute_forward(perm)
        if q_prev is None:
            q_prev = compute_backward(perm)
        # f[m]: completion of job x on machine m after inserting at position i
        f = [0] * M
        if i == 0:
            prev_e = [0] * M
        else:
            prev_e = e_prev[i-1]
        f[0] = prev_e[0] + times[x][0]
        for m in range(1, M):
            f[m] = max(f[m-1], prev_e[m]) + times[x][m]
        # makespan = max over m of (f[m] + q_prev[i][m])
        makespan_val = 0
        for m in range(M):
            val = f[m] + q_prev[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # NEH construction with Taillard acceleration and tie-breaking by last machine idle time
    def neh_construction():
        if N == 0:
            return []
        # Start with first two jobs
        best_seq = None
        best_mk = float('inf')
        # Try both orders of first two jobs
        for seq in ([jobs_sorted[0], jobs_sorted[1]], [jobs_sorted[1], jobs_sorted[0]]):
            mk = makespan(seq)
            if mk < best_mk:
                best_mk = mk
                best_seq = seq[:]
        current = best_seq
        # Insert remaining jobs
        for idx in range(2, N):
            job = jobs_sorted[idx]
            k = len(current)
            e_mat = compute_forward(current)
            q_mat = compute_backward(current)
            best_mk = float('inf')
            best_pos = 0
            best_last_idle = float('inf')
            # Evaluate all insertion positions
            for pos in range(k+1):
                mk = evaluate_insertion(current, job, pos, e_mat, q_mat)
                if mk < best_mk:
                    best_mk = mk
                    best_pos = pos
                    # Compute idle time on last machine for tie-breaking
                    if pos == 0:
                        prev_end = 0
                    else:
                        prev_end = e_mat[pos-1][M-1]
                    job_end = prev_end + times[job][M-1]
                    if pos < k:
                        next_start = e_mat[pos][M-1]
                    else:
                        next_start = float('inf')
                    idle = max(0, next_start - job_end)
                    best_last_idle = idle
                elif mk == best_mk:
                    # Tie-break: minimize idle time on last machine
                    if pos == 0:
                        prev_end = 0
                    else:
                        prev_end = e_mat[pos-1][M-1]
                    job_end = prev_end + times[job][M-1]
                    if pos < k:
                        next_start = e_mat[pos][M-1]
                    else:
                        next_start = float('inf')
                    idle = max(0, next_start - job_end)
                    if idle < best_last_idle:
                        best_mk = mk
                        best_pos = pos
                        best_last_idle = idle
            # Insert job at best_pos
            current.insert(best_pos, job)
        return current

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_sol, max_iter=60):
        current = initial_sol[:]
        best = initial_sol[:]
        best_mk = makespan(best)
        total_processing = sum(total_times)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N >= 3 else N
        for _ in range(max_iter):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in indices]
            # Build destroyed sequence by keeping non-removed jobs
            destroyed = [job for i, job in enumerate(current) if i not in indices]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            seq = destroyed[:]
            for job in removed:
                k = len(seq)
                if k == 0:
                    seq.append(job)
                    continue
                e_mat = compute_forward(seq)
                q_mat = compute_backward(seq)
                best_mk_pos = float('inf')
                best_pos = 0
                best_last_idle = float('inf')
                for pos in range(k+1):
                    mk = evaluate_insertion(seq, job, pos, e_mat, q_mat)
                    if mk < best_mk_pos:
                        best_mk_pos = mk
                        best_pos = pos
                        if pos == 0:
                            prev_end = 0
                        else:
                            prev_end = e_mat[pos-1][M-1]
                        job_end = prev_end + times[job][M-1]
                        if pos < k:
                            next_start = e_mat[pos][M-1]
                        else:
                            next_start = float('inf')
                        idle = max(0, next_start - job_end)
                        best_last_idle = idle
                    elif mk == best_mk_pos:
                        if pos == 0:
                            prev_end = 0
                        else:
                            prev_end = e_mat[pos-1][M-1]
                        job_end = prev_end + times[job][M-1]
                        if pos < k:
                            next_start = e_mat[pos][M-1]
                        else:
                            next_start = float('inf')
                        idle = max(0, next_start - job_end)
                        if idle < best_last_idle:
                            best_mk_pos = mk
                            best_pos = pos
                            best_last_idle = idle
                seq.insert(best_pos, job)
            # Acceptance criterion
            new_mk = makespan(seq)
            if new_mk < makespan(current):
                current = seq[:]
                if new_mk < best_mk:
                    best = seq[:]
                    best_mk = new_mk
            elif new_mk < best_mk:
                # Accept with probability even if worse than current but better than best
                if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                    current = seq[:]
                else:
                    # Reject
                    pass
            else:
                if random.random() < math.exp(-(new_mk - makespan(current)) / T):
                    current = seq[:]
        return best

    # Build initial solution using NEH
    initial = neh_construction()
    # Apply iterated greedy refinement
    refined = iterated_greedy(initial, max_iter=50)
    return refined

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0]) if N > 0 else 0
    if N == 1:
        return [0]
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [row[:] for row in times]
    total_p = [sum(row) for row in p]

    # Makespan evaluation
    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[-1]

    # NEH construction with Taillard acceleration
    def neh_construct():
        order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N < 2:
            return order[:]
        # Initial two jobs
        seq0 = [order[0], order[1]]
        seq1 = [order[1], order[0]]
        current_seq = seq0 if makespan(seq0) <= makespan(seq1) else seq1
        # Insert remaining jobs
        for k in range(2, N):
            job = order[k]
            best_pos = 0
            best_mk = float('inf')
            # Forward matrix e: completion times of current_seq[0..k-1]
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = current_seq[r]
                if r == 0:
                    e[0][0] = p[job_r][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + p[job_r][m]
                else:
                    e[r][0] = e[r-1][0] + p[job_r][0]
                    for m in range(1, M):
                        e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]
            # Backward tail matrix q: from job r to end
            q = [[0] * M for _ in range(k+1)]
            for r in range(k-1, -1, -1):
                job_r = current_seq[r]
                if r == k-1:
                    for m in range(M):
                        q[r][m] = p[job_r][m]
                else:
                    q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
                    for m in range(M-2, -1, -1):
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
            # Evaluate insertion positions
            for i in range(k+1):
                # Forward vector f for job
                f = [0] * M
                if i == 0:
                    f[0] = p[job][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + p[job][m]
                else:
                    prev = e[i-1]
                    f[0] = prev[0] + p[job][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], prev[m]) + p[job][m]
                # Compute makespan: max_m (f[m] + q[i][m])
                mk = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > mk:
                        mk = val
                if mk < best_mk:
                    best_mk = mk
                    best_pos = i
            current_seq = current_seq[:best_pos] + [job] + current_seq[best_pos:]
        return current_seq

    # Iterated Greedy with destruction size 3
    def iterated_greedy(initial_seq, max_iter=50):
        current = initial_seq[:]
        best = current[:]
        best_mk = makespan(best)
        total_processing = sum(total_p)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        for _ in range(max_iter):
            # Destruction: remove 3 random jobs
            if N <= 3:
                destroyed = []
                remaining = []
            else:
                indices = random.sample(range(N), 3)
                indices_set = set(indices)
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(N) if i not in indices_set]
            # Reconstruction: reinsert using NEH insertion (Taillard style)
            seq = remaining[:]
            for job in destroyed:
                best_pos = 0
                best_mk_ins = float('inf')
                k = len(seq)
                if k == 0:
                    seq = [job]
                    continue
                # Forward matrix e for current seq
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    job_r = seq[r]
                    if r == 0:
                        e[0][0] = p[job_r][0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + p[job_r][m]
                    else:
                        e[r][0] = e[r-1][0] + p[job_r][0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]
                # Backward tail matrix q
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job_r = seq[r]
                    if r == k-1:
                        for m in range(M):
                            q[r][m] = p[job_r][m]
                    else:
                        q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
                        for m in range(M-2, -1, -1):
                            q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]
                # Evaluate insertion positions
                for i in range(k+1):
                    f = [0] * M
                    if i == 0:
                        f[0] = p[job][0]
                        for m in range(1, M):
                            f[m] = f[m-1] + p[job][m]
                    else:
                        prev = e[i-1]
                        f[0] = prev[0] + p[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], prev[m]) + p[job][m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_ins:
                        best_mk_ins = mk
                        best_pos = i
                seq = seq[:best_pos] + [job] + seq[best_pos:]
            # Acceptance
            mk_new = makespan(seq)
            if mk_new < best_mk:
                best = seq[:]
                best_mk = mk_new
            if mk_new < makespan(current):
                current = seq[:]
            else:
                delta = mk_new - makespan(current)
                if delta < 0 or random.random() < math.exp(-delta / T):
                    current = seq[:]
        return best

    # Build initial solution and refine
    initial_seq = neh_construct()
    return iterated_greedy(initial_seq, max_iter=40)

