def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            for m in range(M):
                if m == 0:
                    t[m] += times[job][m]
                else:
                    t[m] = max(t[m-1], t[m]) + times[job][m]
        return t[-1]

    def makespan_with_tail(seq, e, q):
        if not seq:
            return 0
        k = len(seq)
        if k == 0:
            return 0
        f = [0] * M
        f[0] = (e[-1][0] if k > 0 else 0) + times[seq[0]][0]
        for m in range(1, M):
            f[m] = max(f[m-1], (e[-1][m] if k > 0 else 0)) + times[seq[0]][m]
        best = max(f[m] + q[0][m] for m in range(M))
        return best

    def taillard_neh(seq, job):
        k = len(seq)
        if k == 0:
            return [job]
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            pj = times[seq[r]]
            if r == 0:
                e[0][0] = pj[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + pj[m]
            else:
                e[r][0] = e[r-1][0] + pj[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + pj[m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            pj = times[seq[r]]
            q[r][M-1] = q[r+1][M-1] + pj[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + pj[m]
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            if i == 0:
                f0 = times[job][0]
                fm = [0] * M
                fm[0] = f0
                for m in range(1, M):
                    fm[m] = fm[m-1] + times[job][m]
            else:
                fm = [0] * M
                fm[0] = e[i-1][0] + times[job][0]
                for m in range(1, M):
                    fm[m] = max(fm[m-1], e[i-1][m]) + times[job][m]
            cmax = 0
            for m in range(M):
                val = fm[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return seq[:best_pos] + [job] + seq[best_pos:]

    def neh_construct():
        job_sums = [sum(job) for job in times]
        order = sorted(range(N), key=lambda i: job_sums[i], reverse=True)
        seq = [order[0]]
        for idx in range(1, N):
            seq = taillard_neh(seq, order[idx])
        return seq

    def ig_improve(initial_seq, max_iter=60):
        current = initial_seq[:]
        best = current[:]
        total_processing = sum(sum(job) for job in times)
        T = 0.5 * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 20 else 2
        for _ in range(max_iter):
            if len(current) <= d:
                destroyed = []
                R = current[:]
            else:
                indices = random.sample(range(len(current)), d)
                indices.sort(reverse=True)
                R = [current.pop(i) for i in indices]
                destroyed = current
            for job in R:
                destroyed = taillard_neh(destroyed, job)
            if makespan(destroyed) < makespan(current):
                current = destroyed[:]
                if makespan(current) < makespan(best):
                    best = current[:]
            else:
                if makespan(destroyed) < makespan(best):
                    best = destroyed[:]
                diff = makespan(destroyed) - makespan(current)
                if diff < 0 or random.random() < math.exp(-diff / T):
                    current = destroyed[:]
        return best

    initial = neh_construct()
    improved = ig_improve(initial, max_iter=50)
    return improved

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[M-1]

    def taillard_forward_backward(perm, job):
        k = len(perm)
        if k == 0:
            f = [0] * M
            for m in range(M):
                if m == 0:
                    f[m] = job[0]
                else:
                    f[m] = f[m-1] + job[m]
            return f, [0] * M
        e = [[0] * M for _ in range(k)]
        r0 = perm[0]
        job0 = times[r0]
        e[0][0] = job0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job0[m]
        for r in range(1, k):
            job_r = times[perm[r]]
            e[r][0] = e[r-1][0] + job_r[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job_r[m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_r = times[perm[r]]
            q[r][M-1] = q[r+1][M-1] + job_r[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_r[m]
        f = [0] * M
        for m in range(M):
            if m == 0:
                prev_e = e[-1][0] if k > 0 else 0
                f[m] = prev_e + job[0]
            else:
                prev_e = e[-1][m] if k > 0 else 0
                f[m] = max(f[m-1], prev_e) + job[m]
        return f, q

    def insert_job_taillard(perm, job):
        k = len(perm)
        if k == 0:
            return [0]
        f, q = taillard_forward_backward(perm, job)
        best_pos = 0
        best_cmax = float('inf')
        for i in range(k+1):
            cmax_i = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax_i:
                    cmax_i = val
            if cmax_i < best_cmax:
                best_cmax = cmax_i
                best_pos = i
        return best_pos

    def neh_construct(sorted_jobs):
        if not sorted_jobs:
            return []
        perm = [sorted_jobs[0]]
        if len(sorted_jobs) > 1:
            job1 = sorted_jobs[1]
            seq1 = [sorted_jobs[0], job1]
            seq2 = [job1, sorted_jobs[0]]
            if makespan(seq1) <= makespan(seq2):
                perm = seq1
            else:
                perm = seq2
        for idx in range(2, len(sorted_jobs)):
            job = sorted_jobs[idx]
            pos = insert_job_taillard(perm, times[job])
            perm.insert(pos, job)
        return perm

    total_times = [sum(job) for job in times]
    base_order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    best_perm = None
    best_cmax = float('inf')

    for _ in range(3):
        noisy_times = [[int(t * random.uniform(0.9, 1.1)) for t in job] for job in times]
        noisy_total = [sum(job) for job in noisy_times]
        order = sorted(range(N), key=lambda i: noisy_total[i], reverse=True)
        perm = neh_construct(order)
        cmax = makespan(perm)
        if cmax < best_cmax:
            best_cmax = cmax
            best_perm = perm

    if best_perm is None:
        best_perm = neh_construct(base_order)
