def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)

    # Compute priority using Lagrangian-inspired shadow prices
    machine_load = [0.0] * M
    for job in times:
        for m in range(M):
            machine_load[m] += job[m]
    shadow_price = [1.0 / (machine_load[m] + 1e-9) for m in range(M)]
    priority = [0.0] * N
    for i in range(N):
        for m in range(M):
            priority[i] += times[i][m] * shadow_price[m]
    order = sorted(range(N), key=lambda i: priority[i], reverse=True)

    # Preallocate buffers
    pi = [0] * N
    e = [0] * M
    q = [0] * M
    f = [0] * M

    def makespan(perm):
        t = [0] * M
        for job_idx in perm:
            job = times[job_idx]
            for m in range(M):
                if m == 0:
                    t[m] += job[m]
                else:
                    t[m] = max(t[m-1], t[m]) + job[m]
        return t[M-1]

    def compute_forward(perm, length):
        if length == 0:
            for m in range(M):
                e[m] = 0
        else:
            job0 = times[perm[0]]
            e[0] = job0[0]
            for m in range(1, M):
                e[m] = e[m-1] + job0[m]
            for r in range(1, length):
                job_r = times[perm[r]]
                e[0] += job_r[0]
                for m in range(1, M):
                    e[m] = max(e[m-1], e[m]) + job_r[m]

    def compute_backward(perm, length):
        if length == 0:
            for m in range(M):
                q[m] = 0
        else:
            job_last = times[perm[length-1]]
            q[M-1] = job_last[M-1]
            for m in range(M-2, -1, -1):
                q[m] = q[m+1] + job_last[m]
            for r in range(length-2, -1, -1):
                job_r = times[perm[r]]
                q[M-1] += job_r[M-1]
                for m in range(M-2, -1, -1):
                    q[m] = max(q[m], q[m+1]) + job_r[m]

    # Build initial solution with NEH + Taillard
    pi[0] = order[0]
    best_pi = pi[:1]
    best_cmax = makespan(best_pi)

    for k in range(1, N):
        job_k = order[k]
        compute_forward(pi, k)
        compute_backward(pi, k)

        best_pos = 0
        best_val = float('inf')

        for i in range(k+1):
            if i == 0:
                f[0] = times[job_k][0]
            else:
                f[0] = e[0] + times[job_k][0]
            for m in range(1, M):
                if i == 0:
                    f[m] = f[m-1] + times[job_k][m]
                else:
                    f[m] = max(f[m-1], e[m]) + times[job_k][m]

            val = 0
            for m in range(M):
                cand = f[m] + q[m]
                if cand > val:
                    val = cand
            if val < best_val:
                best_val = val
                best_pos = i

        for idx in range(k, best_pos, -1):
            pi[idx] = pi[idx-1]
        pi[best_pos] = job_k

        if best_val < best_cmax:
            best_cmax = best_val
            best_pi = pi[:k+1]

    pi = best_pi + [0] * (N - len(best_pi))
    current = pi[:]
    current_cmax = best_cmax
    best_overall = current[:]
    best_overall_cmax = current_cmax

    T_param = 0.5
    T = T_param * total_processing / (10 * N * M)
    if T < 1e-9:
        T = 1e-9

    destruction_size = 3 if N > 20 else 2
    max_iter = 60
    if N > 60:
        max_iter = 40
    elif N > 100:
        max_iter = 30

    for _ in range(max_iter):
        if random.random() < 0.3:
            d = destruction_size + 1
        else:
            d = destruction_size
        if d > N:
            d = N

        positions = random.sample(range(N), d)
        positions.sort(reverse=True)
        removed = []
        for pos in positions:
            removed.append(current.pop(pos))

        for job in removed:
            length = len(current)
            compute_forward(current, length)
            compute_backward(current, length)

            best_pos = 0
            best_val = float('inf')

            for i in range(length+1):
                if i == 0:
                    f[0] = times[job][0]
                else:
                    f[0] = e[0] + times[job][0]
                for m in range(1, M):
                    if i == 0:
                        f[m] = f[m-1] + times[job][m]
                    else:
                        f[m] = max(f[m-1], e[m]) + times[job][m]

                val = 0
                for m in range(M):
                    cand = f[m] + q[m]
                    if cand > val:
                        val = cand
                if val < best_val:
                    best_val = val
                    best_pos = i

            current.insert(best_pos, job)

        new_cmax = makespan(current)

        if new_cmax < current_cmax:
            current_cmax = new_cmax
            if new_cmax < best_overall_cmax:
                best_overall_cmax = new_cmax
                best_overall = current[:]
        elif new_cmax < best_overall_cmax:
            best_overall_cmax = new_cmax
            best_overall = current[:]

        if new_cmax < current_cmax or random.random() < math.exp(-(new_cmax - current_cmax) / T):
            current_cmax = new_cmax
        # else: keep current unchanged

    return best_overall

