                best_mk = float('inf')
                for i in range(k+1):
                    mk = evaluate_insertion(job, i, k)
                    if mk < best_mk:
                        best_mk = mk
                        best_pos = i
                pi_new.insert(best_pos, job)
                # Update e and q for the new schedule length k+1
                # Recompute e[0..k] and q[0..k+1]
                for r in range(k+1):
                    job_r = pi_new[r]
                    if r == 0:
                        e[0][0] = p[job_r][0]
                        for m in range(1, M):
                            e[0][m] = e[0][m-1] + p[job_r][m]
                    else:
                        e[r][0] = e[r-1][0] + p[job_r][0]
                        for m in range(1, M):
                            e[r][m] = max(e[r-1][m], e[r][m-1]) + p[job_r][m]
                for m in range(M):
                    q[k+1][m] = 0
                for r in range(k, -1, -1):
                    job_r = pi_new[r]
                    if r == k:
                        q[k][M-1] = q[k+1][M-1] + p[job_r][M-1]
                        for m in range(M-2, -1, -1):
                            q[k][m] = max(q[k+1][m], q[k][m+1]) + p[job_r][m]
                    else:
                        q[r][M-1] = q[r+1][M-1] + p[job_r][M-1]
                        for m in range(M-2, -1, -1):
                            q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job_r][m]

        # Evaluate new solution
        new_makespan = makespan(pi_new)
        # Acceptance criterion
        if new_makespan < makespan(current):
            current = pi_new[:]
            if new_makespan < best_makespan:
                best = pi_new[:]
                best_makespan = new_makespan
        else:
            if random.random() < math.exp(-(new_makespan - makespan(current)) / T):
                current = pi_new[:]

    return best

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    if not times:
        return []
    n = len(times)
    m = len(times[0])
    if n == 1:
        return [0]
    if m == 1:
        return sorted(range(n), key=lambda i: times[i][0])

    # Precompute job processing times for fast access
    proc = [row[:] for row in times]

    # Helper: makespan of a permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * m
        for job in perm:
            pj = proc[job]
            t[0] += pj[0]
            for j in range(1, m):
                t[j] = max(t[j], t[j-1]) + pj[j]
        return t[-1]

    # Helper: compute forward matrix e for a partial schedule
    def compute_forward(perm):
        k = len(perm)
        if k == 0:
            return [[0]*m]
        e = [[0]*m for _ in range(k)]
        for r in range(k):
            pj = proc[perm[r]]
            for j in range(m):
                if r == 0 and j == 0:
                    e[r][j] = pj[j]
                elif r == 0:
                    e[r][j] = e[r][j-1] + pj[j]
                elif j == 0:
                    e[r][j] = e[r-1][j] + pj[j]
                else:
                    e[r][j] = max(e[r-1][j], e[r][j-1]) + pj[j]
        return e

    # Helper: compute backward matrix q for a partial schedule
    def compute_backward(perm):
        k = len(perm)
        if k == 0:
            return [[0]*m]
        q = [[0]*m for _ in range(k+1)]
        # q[k] is already zeros
        for r in range(k-1, -1, -1):
            pj = proc[perm[r]]
            for j in range(m-1, -1, -1):
                if j == m-1:
                    q[r][j] = q[r+1][j] + pj[j]
                elif j == 0:
                    q[r][j] = max(q[r+1][j], q[r][j+1]) + pj[j]
                else:
                    q[r][j] = max(q[r+1][j], q[r][j+1]) + pj[j]
        return q

    # Helper: evaluate makespan of inserting job x at position i in perm using Taillard
    def evaluate_insertion(perm, x, i, e, q):
        k = len(perm)
        # forward vector f for job x
        f = [0] * m
        if i == 0:
            prev = [0] * m
        else:
            prev = e[i-1]
        for j in range(m):
            if j == 0:
                f[j] = prev[0] + proc[x][0]
            else:
                f[j] = max(f[j-1], prev[j]) + proc[x][j]
        # makespan = max over j of f[j] + q[i][j]
        makespan_val = 0
        for j in range(m):
            val = f[j] + q[i][j]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Beam search with width K=2
    K = 2
    # Initial job order: sort by total processing time descending
    total_proc = [sum(proc[i]) for i in range(n)]
    job_order = sorted(range(n), key=lambda i: total_proc[i], reverse=True)

    # Start beam with first job
    beam = [[job_order[0]]]

    # Iteratively build beam
    for idx in range(1, n):
        job = job_order[idx]
        new_beam = []
        for seq in beam:
            k = len(seq)
            # Compute e and q for this sequence once
            e_mat = compute_forward(seq)
            q_mat = compute_backward(seq)
            # Try all insertion positions
            for pos in range(k+1):
                makespan_val = evaluate_insertion(seq, job, pos, e_mat, q_mat)
                new_seq = seq[:pos] + [job] + seq[pos:]
                new_beam.append((makespan_val, new_seq))
        # Prune to top K by makespan
        new_beam.sort(key=lambda x: x[0])
        beam = [seq for _, seq in new_beam[:K]]

    # Return best sequence in beam
    best_seq = beam[0]
    best_makespan = makespan(best_seq)
    for seq in beam[1:]:
        mk = makespan(seq)
        if mk < best_makespan:
            best_makespan = mk
            best_seq = seq
    return best_seq
